comms.text:
@1 בְּקַדְמִין בְּרָא יְיָ יָת שְׁמַיָּא וְיָת אַרְעָא:
@2 וְאַרְעָא הֲוַת צָדְיָא וְרֵיקַנְיָא וַחֲשׁוֹכָא פָּרַשׂ עַל אַפֵּי תְהוֹמָא וְרוּחָא מִן קֳדָם יְיָ מְנַשְּׁבָא עַל אַפֵּי מַיָּא:
@3 וַאֲמַר יְיָ יְהֵי נְהוֹרָא וַהֲוָה נְהוֹרָא:
@4 וַחֲזָא יְיָ יָת נְהוֹרָא אֲרֵי טָב וְאַפְרֵשׁ יְיָ בֵּין נְהוֹרָא וּבֵין חֲשׁוֹכָא:
@5 וּקְרָא יְיָ לִנְהוֹרָא יְמָמָא וְלַחֲשׁוֹכָא קְרָא לֵילְיָא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹמָא חָד:
@6 וַאֲמַר יְיָ יְהִי רְקִיעָא בִּמְצִיעוּת מַיָּא וִיהִי מַפְרִישׁ בֵּין מַיָּא לְמַיָּא:
@7 וַעֲבַד יְיָ יָת רְקִיעָא וְאַפְרֵישׁ בֵּין מַיָּא דִּי מִלְרַע לִרְקִיעָא וּבֵין מַיָּא דִּי מֵעַל לִרְקִיעָא וַהֲוָה כֵן:
@8 וּקְרָא יְיָ לִרְקִיעָא שְׁמַיָּא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם תִּנְיָן:
@9 וַאֲמַר יְיָ יִתְכַּנְשׁוּן מַיָּא מִתְּחוֹת שְׁמַיָּא לַאֲתַר חָד וְתִתְחֲזֵי יַבֶּשְׁתָּא וַהֲוָה כֵן:
@10 וּקְרָא יְיָ לְיַבֶּשְׁתָּא אַרְעָא וּלְבֵית כְּנִישׁוּת מַיָּא קְרָא יַמְמֵי וַחֲזָא יְיָ אֲרֵי טָּב:
@11 וַאֲמַר יְיָ תַּדְאֵית אַרְעָא דִּיתְאָה עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע אִילַן פֵּירִין עָבַד פֵּירִין לִזְנֵהּ דִּי בַר זַרְעֵהּ בֵּהּ עַל אַרְעָא וַהֲוָה כֵן:
@12 וְאַפֵּקַת אַרְעָא דִּיתְאָה עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע לִזְנוֹהִי וְאִילַן עָבֵד פֵּירִין דְּבַר זַרְעֵהּ בֵּהּ לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@13 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם תְּלִיתָאִי:
@14 וַאֲמַר יְיָ יְהוֹן נְהוֹרִין בִּרְקִיעָא דִּשְׁמַיָּא לְאַפְרָשָׁא בֵּין יְמָמָא וּבֵין לֵילְיָא וִיהוֹן לְאָתִין וּלְזִמְנִין וּלְמִימְנֵי בְהוֹן יוֹמִין וּשְׁנִין:
@15 וִיהוֹן לִנְהוֹרִין בִּרְקִיעָא דִּשְׁמַיָּא לְאַנְהָרָא עַל אַרְעָא וַהֲוָה כֵן:
@16 וַעֲבַד יְיָ יָת תְּרֵין נְהוֹרַיָּא רַבְרְבַיָּא יָת נְהוֹרָא רַבָּא לְמִשְׁלַט בִּימָמָא וְיָת נְהוֹרָא זְעֵרָא לְמִשְׁלַט בְּלֵילְיָא וְיָת כּוֹכְבַיָּא:
@17 וִיהַב יָתְהוֹן יְיָ בִּרְקִיעָא דִּשְׁמַיָּא לְאַנְהָרָא עַל אַרְעָא:
@18 וּלְמִשְׁלַט בִּימָמָא וּבְלֵילְיָא וּלְאַפְרָשָׁא בֵּין נְהוֹרָא וּבֵין חֲשׁוֹכָא וַחֲזָא יְיָ אֲרֵי טָב:
@19 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם רְבִיעָאִי:
@20 וַאֲמַר יְיָ יִרְחֲשׁוּן מַיָּא רְחֵשׁ נַפְשָׁא חַיְתָא וְעוֹפָא יְפָרַח עַל אַרְעָא עַל אַפֵּי רְקִיעָא דִּשְׁמַיָּא:
@21 וּבְרָא יְיָ יָת תַּנִּינַיָּא רַבְרְבַיָּא וְיָת כָּל נַפְשָׁא חַיְתָא דִּרְחִשָׁא דִּי אַרְחִישׁוּ מַיָּא לִזְנֵיהוֹן וְיָת כָּל עוֹפָא דְפָרַח לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@22 וּבָרִיךְ יָתְהוֹן יְיָ לְמֵימָר פּוּשׁוּ וּסְגוּ וּמְלוּ יָת מַיָּא בְּיַמְמַיָּא וְעוֹפָא יִסְגֵּי בְּאַרְעָא:
@23 וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם חֲמִישָׁאִי:
@24 וַאֲמַר יְיָ תַּפֵּק אַרְעָא נַפְשָׁא חַיְתָא לִזְנַהּ בְּעִיר וּרְחֵשׁ וְחֵוַת אַרְעָא לִזְנַהּ וַהֲוָה כֵן:
@25 וַעֲבַד יְיָ יָת חֵוַת אַרְעָא לִזְנַהּ וְיָת בְּעִירָא לִזְנַהּ וְיָת כָּל רִחֲשָׁא דְאַרְעָא לִזְנוֹהִי וַחֲזָא יְיָ אֲרֵי טָב:
@26 וַאֲמַר יְיָ נַעֲבִיד אֶינָשָׁא בְּצַלְמֵנָא כִּדְמוּתָנָא וְיִשְׁלְטוּן בְּנוּנֵי יַמָּא וּבְעוֹפָא דִּשְׁמַיָּא וּבִבְעִירָא וּבְכָל אַרְעָא וּבְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא:
@27 וּבְרָא יְיָ יָת אָדָם בְּצַלְמֵהּ בְּצַלְמָא דַיְיָ בְּרָא יָתֵהּ דְּכַר וְנוּקְבָא בְּרָא יָתְהוֹן:
@28 וּבָרִיךְ יָתְהוֹן יְיָ וַאֲמַר לְהוֹן יְיָ פּוּשׁוּ וּסְגוּ וּמְלוּ יָת אַרְעָא וּתְקוּפוּ עֲלַהּ וּשְׁלוּטוּ בְּנוּנֵי יַמָּא וּבְעוֹפָא דִּשְׁמַיָּא וּבְכָל חַיְתָא דְּרָחֵשָׁא עַל אַרְעָא:
@29 וַאֲמַר יְיָ הָא יְהָבִית לְכוֹן יָת כָּל עִסְבָּא דְּבַר זַרְעֵהּ מִזְדְּרַע דִּי עַל אַפֵּי כָל אַרְעָא וְיָת כָּל אִילָנָא דִּי בֵהּ פֵּירֵי אִילָנָא דְּבַר זַרְעֵהּ מִזְדְּרָע לְכוֹן יְהֵא לְמֵיכָל:
@30 וּלְכָל חֵוַת אַרְעָא וּלְכָל עוֹפָא דִּשְׁמַיָּא וּלְכֹל דְּרָחֵשׁ עַל אַרְעָא דִּי בֵהּ נַפְשָׁא חַיְתָא יָת כָּל יְרוֹק עִסְבָּא לְמֵיכָל וַהֲוָה כֵן:
@31 וַחֲזָא יְיָ יָת כָּל דִּי עֲבַד וְהָא תַקִּין לַחֲדָא וַהֲוָה רְמַשׁ וַהֲוָה צְפַר יוֹם שְׁתִיתָאִי:
@32 וְאִשְׁתַּכְלָלוּ שְׁמַיָּא וְאַרְעָא וְכָל חֵילֵיהוֹן:
@33 וְשֵׁיצֵי יְיָ בְּיוֹמָא שְׁבִיעָאָה עֲבִדְתֵּהּ דִּי עֲבָד וְנַח בְּיוֹמָא שְׁבִיעָאָה מִכָּל עֲבִדְתֵּהּ דִּי עֲבָד:
@34 וּבָרִיךְ יְיָ יָת יוֹמָא שְׁבִיעָאָה וְקַדִּישׁ יָתֵהּ אֲרֵי בֵהּ נַח מִכָּל עֲבִדְתֵּהּ דִּי בְרָא יְיָ לְמֶעְבַּד:
@35 אִלֵּין תּוּלְדַת שְׁמַיָּא וְאַרְעָא כַּד אִתְבְּרִיאוּ בְּיוֹמָא דִּי עֲבַד יְיָ אֱלֹהִים אַרְעָא וּשְׁמַיָּא:
@36 וְכֹל אִילָנֵי חַקְלָא עַד לָא הֲווּ בְאַרְעָא וְכָל עִסְבָּא דְחַקְלָא עד לָא צְמָח אֲרֵי לָא אָחִית מִטְרָא יְיָ אֱלֹהִים עַל אַרְעָא וְאֱנַשׁ לֵית לְמִפְלַח יָת אַדְמְתָא:
@37 וַעֲנָנָא הֲוָה סָלֵיק מִן אַרְעָא וְאַשְׁקֵי יָת כָּל אַפֵּי אַדְמְתָא:
@38 וּבְרָא יְיָ אֱלֹהִים יָת אָדָם עַפְרָא מִן אַדְמְתָא וּנְפַח בְּאַפּוֹהִי נִשְׁמְתָא דְחַיֵּי וַהֲוַת בְּאָדָם לְרוּחַ מְמַלְלָא:
@39 וּנְצִיב יְיָ אֱלֹהִים גִּינְתָא בְעֵדֶן מִלְּקַדְמִין וְאַשְׁוֵי תַמָּן יָת אָדָם דִּי בְרָא:
@40 וְאַצְמַח יְיָ אֱלֹהִים מִן אַרְעָא כָּל אִילַן דִּמְרַגֵּג לְמֶחֱזֵי וְטַב לְמֵיכַל וְאִילַן חַיָּא בִּמְצִיעוּת גִּינְתָא וְאִילַן דְּאָכְלִין פֵּירוֹהִי חַכִּימִין בֵּין טַב לְבִישׁ:
@41 וְנַהֲרָא הֲוָה נָפִיק מֵעֵדֶן לְאַשְׁקָאָה יָת גִּינְתָא וּמִתַּמָּן יִתְפָּרִשׁ וַהֲוֵי לְאַרְבְּעָה רֵישֵׁי נַהֲרִין:
@42 שׁוּם חָד פִּישׁוֹן הוּא מַקִּיף יָת כָּל אֲרַע דַּחֲוִילָה דִּי תַמָּן דַּהֲבָא:
@43 וְדַהֲבָא דְאַרְעָא הַהִיא טָב תַּמָן בְּדָלְחָא וְאַבְנֵי בוּרְלָא:
@44 וְשׁוּם נַהֲרָא תִנְיָנָא גִּיחוֹן הוּא מַקִּיף יָת כָּל אַרְעָא דְכוּשׁ:
@45 וְשׁוּם נַהֲרָא תְּלִיתָאָה דִּיגְלַת הוּא מְהַלֵּךְ לְמַדִּינְחָא דְאַתּוּר וְנַהֲרָא רְבִיעָאָה הוּא פְרָת:
@46 וּדְבַר יְיָ אֱלֹהִים יָת אָדָם וְאַשְׁרֵיהּ בְּגִינְתָא דְעֵדֶן לְמִפְלְחַהּ וּלְמִטְרַהּ:
@47 וּפַקִּיד יְיָ אֱלֹהִים עַל אָדָם לְמֵימָר מִכֹּל אִילַן גִּינְתָא מֵיכַל תֵּיכוּל:
@48 וּמֵאִילָן דְּאָכְלִין פֵּירוֹהִי חַכִּימִין בֵּין טַב לְבִישׁ לָא תֵיכוּל מִנֵּהּ אֲרֵי בְּיוֹמָא דְתֵיכוּל מִנֵּהּ מֵימַת תְּמוּת:
@49 וַאֲמַר יְיָ אֱלֹהִים לָא תַקִּין לְמֶהֱוֵי אָדָם בִּלְחוֹדוֹהִי אַעֲבֵד לֵהּ סְמַךְ לְקִבְלֵהּ:
@50 וּבְרָא יְיָ אֱלֹהִים מִן אַרְעָא כָּל חֵוַת בְּרָא וְיָת כָּל עוֹפָא דִּשְׁמַיָּא וְאַיְתֵהּ לְוַת אָדָם לְמֶחֱזֵי מַה יִּקְרֵי לֵהּ וְכֹל דִּי הֲוָה קָרֵי לֵהּ אָדָם נַפְשָׁא חַיְתָא הוּא שְׁמֵהּ:
@51 וּקְרָא אָדָם שְׁמָהָן לְכָל בְּעִירָא וּלְעוֹפָא דִּשְׁמַיָּא וּלְכָל חֵוַת בְּרָא וּלְאָדָם לָא אַשְׁכַּח סָמֵךְ לְקִבְלֵהּ:
@52 וּרְמָא יְיָ אֱלֹהִים שִׁינְתָא עַל אָדָם וּדְמֵךְ וּנְסִיב חֲדָא מֵעִלְעוֹהִי וּמְלֵי בִשְׂרָא תְּחוֹתַהּ:
@53 וּבְנָא יְיָ אֱלֹהִים יָת עִלְעָא דִּנְסִיב מִן אָדָם לְאִתְּתָא וְאַיְתַהּ לְוַת אָדָם:
@54 וַאֲמַר הָאָדָם הֲדָא זִמְנָא גַּרְמָא מִגַּרְמַי וּבִסְרָא מִבִּסְרִי לְדָא יִתְקְרֵי אִתְּתָא אֲרֵי מִבַּעְלָא נְסִיבָא דָא:
@55 עַל כֵּן יִשְׁבּוֹק גְּבַר בֵּית מִשְׁכְּבֵי אַבוּהִי וְאִמֵּהּ וְיִדְבַּק בְּאִתְּתֵהּ וִיהוֹן לְבִסְרָא חָדּ:
@56 וַהֲווֹ תַרְוֵיהוֹן עַרְטִילָאִין אָדָם וְאִתְּתֵהּ וְלָא מִתְכַּלְמִין:
@57 וְחִוְיָא הֲוָה חַכִּים מִכֹּל חֵוַת בְּרָא דִּי עֲבַד יְיָ אֱלֹהִים וַאֲמַר לְאִתְּתָא בְּקוּשְׁטָא אֲרֵי אֲמַר יְיָ לָא תֵיכְלוּן מִכֹּל אִילַן גִּינְתָא:
@58 וַאֲמָרַת אִתְּתָא לְחִוְיָא מִפֵּירֵי אִילַן גִּינְתָא נֵיכוּל:
@59 וּמִפֵּירֵי אִילָנָא דִּי בִמְצִיעוּת גִּינְתָא אֲמַר יְיָ לָא תֵיכְלוּן מִנֵּהּ וְלָא תְקַרְבוּן בֵּהּ דִּילְמָא תְּמוּתוּן:
@60 וַאֲמַר חִוְיָא לְאִיתְּתָא לָא מוּת תְּמוּתוּן:
@61 אֲרֵי גַּלֵּי קֳדָם יְיָ אֲרֵי בְּיוֹמָא דְּתֵיכְלוּן מִנֵּהּ וְיִתְפַּתְּחַן עֵינֵיכוֹן וּתְהוֹן כְּרַבְרְבִין חַכִּימִין בֵּין טַב לְבִישׁ:
@62 וַחֲזַת אִתְּתָא אֲרֵי טַב אִילַן לְמֵיכָל וַאֲרֵי אַסֵּי הוּא לְעַיְנִין וּמְרַגֵּג אִילָנָא לְאִסְתַּכָּלָא בֵהּ וּנְסֵיבַת מֵאִבֵּהּ וַאֲכָלַת וִיהָבַת אַף לְבַעְלַהּ עִמַּהּ וַאֲכָל:
@63 וְאִתְפַּתָּחָא עֵינֵי תַרְוֵיהוֹן וִידָעוּ אֲרֵי עַרְטִילָאִין אִינוּן וְחַטִּיטוּ לְהוֹן טַרְפֵי תְאֵנִין וַעֲבָדוּ לְהוֹן זְרָזִין:
@64 וּשְׁמָעוּ יָת קַל מֵימְרָא דַּיְיָ אֱלֹהִים מְהַלֵּךְ בְּגִינְתָא לִמְנַח יוֹמָא וְאִיטַמַּר אָדָם וְאִתְּתֵהּ מִן קֳדָם יְיָ אֱלֹהִים בְּגוֹ אִילַן גִּינְתָא:
@65 וּקְרָא יְיָ אֱלֹהִים לְאָדָם וַאֲמַר לֵהּ אָן אָתְּ:
@66 וַאֲמַר יָת קַל מֵימְרָךְ שַׁמְעִית בְּגִינְתָא וּדְהֵילִית אֲרֵי עַרְטִילַאי אֲנָא וְאִיטַמָּרִית:
@67 וַאֲמַר מָן חַוֵי לָךְ אֲרֵי עַרְטִילַאי אָתְּ הֲמִן אִילָנָא דִּפַקֶּדְתָּךְ בְּדִיל דְּלָא לְמֵיכַל מִנֵּהּ אֲכָלְתְּ:
@68 וַאֲמַר הָאָדָם אִתְּתָא דִּיהַבְתָּ עִמִּי הִיא יַהֲבַת לִי מִן אִילָנָא וַאֲכָלִית:
@69 וַאֲמַר יְיָ אֱלֹהִים לְאִתְּתָא מַה דָּא עַבְדָת וַאֲמָרַת אִתְּתָא חִוְיָא אַטְעַיָנִי וַאֲכָלִית:
@70 וַאֲמַר יְיָ אֱלֹהִים לְחִוְיָא אֲרֵי עֲבַדְתָּ דָּא לִיט אַתְּ מִכָּל בְּעִירָא וּמִכֹּל חֵוַת בָּרָא עַל מְעָךְ תֵּיזִילּ וְעַפְרָא תֵיכוּל כָּל יוֹמֵי חַיָּיךְ:
@71 וּדְבָבוּ אֱשַׁוֵּי בֵּינָךְ וּבֵין אִתְּתָא וּבֵין בְּנָךְ וּבֵין בְּנָהַהּ הוּא יְהֵי דְּכִיר לָךְ מַה דִּעֲבַדְתָּ לֵהּ מִלְּקַדְמִין וְאַתְּ תְּהֵא נָטִיר לֵהּ לְסוֹפָא:
@72 לְאִתְּתָא אֲמַר אַסְגָּאָה אַסְגֵּי צַעֲרַיְכִי וְעִדּוּיַיְכִי בְּצְעַר תֵּלְדִי בְנִין וּלְוַת בַּעְלִךְ תְּהֵא תִּאוּבְתִּיךְ וְהוּא יִשְׁלַט בִּךְ:
@73 וּלְאָדָם אֲמַר אֲרֵי קַבֵּילְתָּ לְמֵימַר אִתְּתָךְ וַאֲכַלְתָּ מִן אִילָנָא דִּי פַקֵּידְתָּךְ לְמֵימַר לָא תֵיכוּל מִנֵּהּ לִיטָא אַרְעָא בְּדִילָךְ בַּעֲמַל תִּיכְלִינַהּ כָּל יוֹמֵי חַיָּיךְ:
@74 וְכוּבִין וְאַטְדִּין תַּצְמַח לָךְ וְתֵיכוּל יָת עִסְבָּא דְחַקְלָא:
@75 בְּזִעֲתָא דְאַפָּךְ תֵּיכוּל לַחְמָא עַד דְּתִיתוּב לְאַרְעָא דְּמִנַּהּ אִתְבְּרֵיתָא אֲרֵי עַפְרָא אַתְּ וּלְעַפְרָא תְּתוּב:
@76 וּקְרָא אָדָם שׁוּם אִתְּתֵהּ חַוָּה אֲרֵי הִיא הֲוַת אִמָּא דְכָל בְּנֵי אֱנָשָׁא:
@77 וַעֲבַד יְיָ אֱלֹהִים לְאָדָם וּלְאִתְּתֵהּ לְבוּשִׁין דִּיקָר עַל מְשַׁךְ בִּשְׂרֵיהוֹן וְאַלְבִּישִׁינוּן:
@78 וַאֲמַר יְיָ אֱלֹהִים הָא אָדָם הֲוָה יְחִידַי בְּעַלְמָא מִנֵּהּ לְמִידַע טַב וּבִישׁ וּכְעַן דִּילְמָא יוֹשִׁיט יְדֵהּ וְיִסַב אַף מֵאִילָן חַיָּיא וְיֵכוּל וִיחֵי לְעָלָם:
@79 וְשַׁלְּחֵהּ יְיָ אֱלֹהִים מִגִּינְתָא דְעֵדֶן לְמִפְלַח יַת אַדְמְתָא דְּאִתְבְּרִי מִתַּמָּן:
@80 וְתָרִךְ יָת אָדָם וְאַשְׁרֵי מִלְּקַדְמִין לְגִינְתָא דְעֵדֶן יָת כְּרוּבַיָּא וְיָת שְׁנַן חַרְבָּא דְּמִתְהַפְּכָא לְמִיטַר יָת אוֹרַח אִילַן חַיָּיא:
@81 וְאָדָם יְדַע יָת חַוָּה אִתְּתֵהּ וְעַדִּיאַת וִילִידַת יָת קַיִן וַאֲמֶרֶת קָנִיתִי גַּבְרָא (מִן) קֳדָם יְיָ:
@82 וְאוֹסִיפַת לְמֵילַד יָת אֲחוֹהִי יָת הָבֶל וַהֲוָה הֶבֶל רָעֵי עָנָא וְקַיִן הֲוָה פָלַח בְּאַרְעָא:
@83 וַהֲוָה מִסּוֹף יוֹמִין וְאַיְתִי קַיִן מֵאִבָּא דְאַרְעָא תִּקְרוּבְתָּא קֳדָם יְיָ:
@84 וְהֶבֶל אַיְתִי אַף הוּא מִבַּכִּירֵי עָנֵהּ וּמִשַׁמִּנְהוֹן וַהֲוַת רַעֲוָא מִן קֳדָם יְיָ בְּהֶבֶל וּבְּקוּרְבָּנֵהּ:
@85 וּבְּקַיִן וּבְּקוּרְבָּנֵהּ לָא הֲוַת רַעֲוָא וּתְקֵף לְקַיִן לַחֲדָא וְאִתְכְּבִישׁוּ אַפּוֹהִי:
@86 וַאֲמַר יְיָ לְקָיִן לְמָא תְּקִיף לָךְ וּלְמָא אִתְכְּבִישׁוּ אַפָּיךְ:
@87 הֲלָא אִם תּוֹטִיב עוֹבָדָךְ יִשְׁתְּבֵק לָךְ וְאִם לָא תּוֹטִיב עוֹבָדָךְ לְיוֹם דִּינָא חֶטְאָךְ נְטִיר דִיעֲתִיד לְאִתְפָּרְעָא מִנָּךְ אִם לָא תְתוּב וְאִם תְּתוּב יִשְׁתְּבֵק לָךְ:
@88 וַאֲמַר קַיִן לְהֶבֶל אַחוֹהִי וַהֲוָה בְּמֶהֱוֵיהוֹן בְּחַקְלָא וְקָם קַיִן עַל הֶבֶל אַחוֹהִי וְקַטְלֵהּ:
@89 וַאֲמַר יְיָ לְקַיִן אָן הֶבֶל אָחוּךְ וַאֲמַר לָא יָדַעֲנָא הֲנָטֵר אָחִי אֲנָא:
@90 וַאֲמַר מֶה עֲבַדְתָּא קַל דַם זַרְעִין דִעֲתִידִין לְמֵפַק מִן אָחוּךְ קַבְלִין קֳדָמַי מִן אַרְעָא:
@91 וּכְעַן לִיט אָתְּ מִן אַרְעָא דִּפְתָחַת יָת פּוּמַהּ וְקַבִּילַת יָת דְּמֵהּ דְּאָחוּךְ מִן יְדָךְ:
@92 אֲרֵי תִפְלַח בְאַרְעָא לָא תוֹסִיף לְמִתַּן חֵילַהּ לָךְ מִטַלְטֵּל וְגָלֵי תְּהֵא בְאַרְעָא:
@93 וַאֲמַר קַיִן קֳדָם יְיָ סַגִּי חוֹבִי מִלְּמִשְׁבָּק:
@94 הָא תָרִיכְתָּא יָתִי יוֹמָא דֵּין מֵעַל אַפֵּי אַרְעָא וּמִן קֳדָמָךְ לֵית אֶפְשָׁר לְאִטַּמָּרָא וָאֱהִי מְטַלְטֵל וְגָלֵי בְּאַרְעָא וִיהֵי כָל דְּיִשְׁכְּחִנַנִי יִקְטְּלִינַנִי:
@95 וַאֲמַר לֵהּ יְיָ בְּכֵן כָּלּ קָטִיל קַיִן לְשַׁבְעָא דָּרִין יִתְפְּרַע מִנֵּהּ וְשַׁוִּי יְיָ לְקַיִן אָתָא בְּדִיל דְּלָא לְמִקְטַל יָתֵהּ כָּל דִיִשְׁכְּחֻנֵהּ:
@96 וּנְפַק קַיִן מִן קֳדָם יְיָ וִיתֵיב בְּאַרְעָא גָּלֵי וּמִטַּלְטַל דַּהֲוָה עֲבִידָא עֲלוֹהִי מִלְּקַדְמִין דְּגִינְתָא דְעֵדֶן:
@97 וִידַע קַיִן יָת אִתְּתֵהּ וְעַדִּיאַת וִילֵידַת יָת חֲנוֹךְ וַהֲוָה בָּנֵי קַרְתָּא וּקְרָא שְׁמָא דְקַרְתָּא כְּשׁוּם בְּרֵהּ חֲנוֹךְ:
@98 וְאִתְיְלִיד לַחֲנוֹךְ יָת עִירָד וְעִירָד אוֹלִיד יָת מְחוּיָאֵל וּמְחִיָּיאֵל אוֹלִיד יָת מְתוּשָׁאֵל וּמְתוּשָׁאֵל אוֹלִיד יָת לָמֶךְ:
@99 וּנְסִיב לֵהּ לֶמֶךְ תַּרְתֵּין נְשִׁין שׁוּם חֲדָא עָדָה וְשׁוּם תִּנְיֵתָא צִלָּה:
@100 וִילֵידַת עָדָה יָת יָבָל הוּא הֲוָה רַבְּהוֹן דְּיָתְבֵי מַשְׁכְּנִין וּמָרֵי בְעִיר:
@101 וְשׁוּם אֲחוֹהִי יוּבָל הוּא הֲוָה רַבְּהוֹן דְּכָל דִּמְנַגֵּן עַל פּוּם נִבְלָא יָדְעֵי זְמַר כִּנּוֹרָא וְאַבּוּבָא:
@102 וְצִלָּה אַף הִיא יְלֵידַת יָת תּוּבַל קַיִן רַבְּהוֹן דְכָל דְּיָדְעֵי עִיבִידַת נְחָשָׁא וּפַרְזְלָא וַאֲחָתֵהּ דְתוּבַל קַיִן נַעֲמָה:
@103 וַאֲמַר לֶמֶךְ לִנְשׁוֹהִי עָדָה וְצִלָּה שִׁמְעַן קָלִי נְשֵׁי לֶמֶךְ אֲצֵיתָא לְמֵמְרִי לָא גַּבְרָא קְטָלִית דִּבְדִילֵהּ אֲנָא סָבִיל חוֹבִין וְאַף לָא עוּלֵימָא חַבָּלִית דִּבְדִילֵהּ יִשְׁתֵּיצֵי זַרְעִי:
@104 אֲרֵי שַׁבְעָא דָּרִין אִיתְלִאוּ לְקָיִן הֲלָא לְלֶמֶךְ בְּרֵהּ שַׁבְעִין וְשַׁבְעָא:
@105 וִידַע אָדָם עוֹד יָת אִתְּתֵהּ וִילֵידַת בַּר וּקְרַת יָת שְׁמֵהּ שֵׁת אֲרֵי אַמָרַת יְהַב לִי יְיָ בַּר אוֹחֲרָן חֲלַף הֶבֶל דִּקַטְלֵהּ קָיִן:
@106 וּלְשֵׁת אַף הוּא אִתְיְלִיד בַּר וּקְרָא יָת שְׁמֵהּ אֱנוֹשׁ בְּכֵן בְּיוֹמוֹהִי חָלוּ בְנֵי אֱנָשָׁא מִלְּצַלָּאָה בִּשְׁמָא דַּיְיָ:
@107 דֵּין סְפַר תּוּלְדַת אָדָם בְּיוֹמָא דִּבְרָא יְיָ אָדָם בִּדְמוּת אֱלֹהִים עָבַד יָתֵהּ:
@108 דְּכַר וְנוּקְבָא בְּרָאנוּן וּבָרִיךְ יָתְהוֹן וּקְרָא יָת שְׁמָהוֹן אָדָם בְּיוֹמָא דְאִתְבְּרִיאוּ:
@109 וַחֲיָא אָדָם מְאָה וּתְלָתִין שְׁנִין וְאוֹלִיד בִּדְמוּתֵהּ דְּדָמֵי לֵהּ וּקְרָא יָת שְׁמֵהּ שֵׁת:
@110 וַהֲווֹ יוֹמֵי אָדָם בָּתַר דְּאוֹלִיד יָת שֵׁת תַּמְנֵי מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@111 וַהֲווֹ כָּל יוֹמֵי אָדָם דַחֲיָא תְּשַׁע מְאָה וּתְלָתִין שְׁנִין וּמִית:
@112 וַחֲיָא שֵׁת מְאָה וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת אֱנוֹשׁ:
@113 וַחֲיָא שֵׁת בָּתַר דְּאוֹלִיד יָת אֱנוֹשׁ תַּמְנֵי מְאָה וּשְׁבַע שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@114 וַהֲווֹ כָּל יוֹמֵי שֵׁת תְּשַׁע מְאָה וְתַרְתֵּי עַשְׂרֵי שְׁנִין וּמִית:
@115 וַחֲיָא אֱנוֹשׁ תִּשְׁעִין שְׁנִין וְאוֹלִיד יָת קֵינָן:
@116 וַחֲיָא אֱנוֹשׁ בָּתַר דְאוֹלִיד יָת קֵינָן תַּמְנֵי מְאָה וַחֲמֵשׁ עַשְׂרֵי שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@117 וַהֲווֹ כָּל יוֹמֵי אֱנוֹשׁ תְּשַׁע מְאָה וַחֲמֵשׁ שְׁנִין וּמִית:
@118 וַחֲיָא קֵינָן שַׁבְעִין שְׁנִין וְאוֹלִיד יָת מַהֲלַלְאֵל:
@119 וַחֲיָא קֵינָן בָּתַר דְּאוֹלִיד יָת מַהֲלַלְאֵל תַּמְנֵי מְאָה וְאַרְבְּעִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@120 וַהֲווֹ כָּל יוֹמֵי קֵינָן תְּשַׁע מְאָה וַעֲשַׂר שְׁנִין וּמִית:
@121 וַחֲיָא מַהֲלַלְאֵל שִׁתִּין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת יָרֶד:
@122 וַחֲיָא מַהֲלַלְאֵל בָּתַר דְּאוֹלִיד יָת יֶרֶד תַּמְנֵי מְאָה וּתְלָתִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@123 וַהֲווֹ כָּל יוֹמֵי מַהֲלַלְאֵל תַּמְנֵי מְאָה וְתִשְׁעִין וַחֲמֵשׁ שְׁנִין וּמִית:
@124 וַחֲיָא יֶרֶד מְאָה וְשִׁתִּין וְתַרְתֵּין שְׁנִין וְאוֹלִיד יָת חֲנוֹךְ:
@125 וַחֲיָא יֶרֶד בָּתַר דְּאוֹלִיד יָת חֲנוֹךְ תַּמְנֵי מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@126 וַהֲווֹ כָּל יוֹמֵי יֶרֶד תְּשַׁע מְאָה וְשִׁתִּין וְתַרְתֵּין שְׁנִין וּמִית:
@127 וַחֲיָא חֲנוֹךְ שִׁתִּין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת מְתוּשָׁלַח:
@128 וְהַלִּיךְ חֲנוֹךְ בְּדַחַלְתָּא דַּיְיָ בָּתַר דְּאוֹלִיד יָת מְתוּשֶׁלַח תְּלַת מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@129 וַהֲוָה כָּל יוֹמֵי חֲנוֹךְ תְּלַת מְאָה וְשִׁתִּין וַחֲמֵשׁ שְׁנִין:
@130 וְהַלִּיךְ חֲנוֹךְ בְּדַחַלְתָּא דַּיְיָ וְלַיְתוֹהִי אֲרֵי (לָא) אֲמֵית יָתֵהּ יְיָ:
@131 וַחֲיָא מְתוּשֶׁלַח מְאָה וְתַמְנִין וּשְׁבַע שְׁנִין וְאוֹלִיד יָת לָמֶךְ:
@132 וַחֲיָא מְתוּשֶׁלַח בָּתַר דְּאוֹלִיד יָת לֶמֶךְ שְׁבַע מְאָה וְתַמְנִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@133 וַהֲווֹ כָּל יוֹמֵי מְתוּשֶׁלַח תְּשַׁע מְאָה וְשִׁתִּין וּתְשַׁע שְׁנִין וּמִית:
@134 וַחֲיָא לֶמֶךְ מְאָה וְתַמְנִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד בָּר:
@135 וּקְרָא יָת שְׁמֵהּ נֹחַ לְמֵימָר דֵּין יְנַחֲמִנָּנָא מֵעוֹבָדָנָא וּמִלֵּאוּת יְדָנָא מִן אַרְעָא דִּי לַטְטַהּ יְיָ:
@136 וַחֲיָא לֶמֶךְ בָּתַר דְּאוֹלִיד יָת נֹחַ חֲמֵשׁ מְאָה וְתִשְׁעִין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@137 וַהֲווֹ כָּל יוֹמֵי לֶמֶךְ שְׁבַע מְאָה וְשַׁבְעִין וּשְׁבַע שְׁנִין וּמִית:
@138 וַהֲוָה נֹחַ בַּר חֲמֵשׁ מְאָה שְׁנִין וְאוֹלִיד נֹחַ יָת שֵׁם יָת חָם וְיָת יָפֶת:
@139 וַהֲוָה כַּד שְׁרִיאוּ בְנֵי אֱנָשָׁא לְמִסְגֵּי עַל אַפֵּי אַרְעָא וּבְנָתָא אִתְיְלִידוּ לְהוֹן:
@140 וַחֲזוֹ בְנֵי רַבְרְבַיָּא יָת בְּנַת אֱנָשָׁא אֲרֵי שַׁפִּירָן אִנוּן וּנְסִיבוּ לְהוֹן נְשִׁין מִכֹּל דִּי אִתְרְעִיאוּ:
@141 וַאֲמַר יְיָ לָא יִתְקַיַם דָרָא בִישָׁא הָדֵין קֳדָמַי לְעַלָם בְּדִיל דְאִנוּן בִּשְׂרָא וְעוֹבָדֵיהוֹן בִּישַׁיָא אַרְכָא יְהִיבַת לְהוֹן מְאָה וְעַשְׂרִין שְׁנִין אִם יְתוּבוּן:
@142 גִּבָּרַיָּא הֲווֹ בְאַרְעָא בְּיוֹמַיָּא הָאִנּוּן וְאַף בָּתַר כֵּן דִּי יַעֲלוּן בְּנֵי רַבְרְבַיָּא לְוַת בְּנַת אֱנָשָׁא וִילִידָן לְהוֹן אִנוּן גִּבָּרַיָּא דִּמֵעָלְמָא אֱנָשִׁין דִּשְׁמָא:
@143 וַחֲזָא יְיָ אֲרֵי סְגִיאַת בִּישַׁת אֱנָשָׁא בְּאַרְעָא וְכָל יִצְרָא מַחְשְׁבַת לִבֵּהּ לְחוֹד בִּישׁ כָּל יוֹמָא:
@144 וְתַב יְיָ בְּמֵימְרֵהּ אֲרֵי עֲבַד יָת אֱנָשָׁא בְּאַרְעָא וַאֲמַר בְּמֵימְרֵהּ לְמִתְּבַר תָּקְפְּהוֹן כִּרְעוּתֵהּ:
@145 וַאֲמַר יְיָ אֶמְחֵי יָת אֲנָשָׁא דִּי בְרֵאתִי מֵעַל אַפֵּי אַרְעָא מֵאֱנָשָׁא עַד בְּעִירָא עַד רִיחֲשָׁא וְעַד עוֹפָא דִּשְׁמַיָּא אֲרֵי תָבִית בְּמֵימְרִי אֲרֵי עֲבַדְתִּנוּן:
@146 וְנֹחַ אַשְׁכַּח רַחֲמִין קֳדָם יְיָ: פפפ:
@147 אִלֵן תּוּלְדַת נֹחַ נֹחַ גְּבַר זַכַּאי שְׁלִים הֲוָה בְּדָרוֹהִי בְּדַחַלְתָּא דַּיְיָ הַלִּיךְ נֹחַ:
@148 וְאוֹלִיד נֹחַ תְּלָתָא בְנִין יָת שֵׁם יָת חָם וְיָת יָפֶת:
@149 וְאִתְחַבָּלַת אַרְעָא קֳדָם יְיָ וְאִתְמְלִיאַת אַרְעָא חֲטּוֹפִין:
@150 וַחֲזָא יְיָ יָת אַרְעָא וְהָא אִתְחַבָּלַת אֲרֵי חַבִּילוּ כָּל בִּסְרָא אֱנַשׁ יָת אָרְחֵהּ עַל אַרְעָא:
@151 וַאֲמַר יְיָ לְנֹחַ קִצָא דְכָל בִּסְרָא עַלַּת לִקֳדָמַי אֲרֵי אִתְמְלִיאַת אַרְעָא חֲטוֹפִין מִן קֳדָם עוֹבָדֵיהוֹן בִּישַׁיָּא וְהָא אֲנָא מְחַבֶּלְהוֹן עִם אַרְעָא:
@152 עִבֵד לָךְ תֵּבוֹתָא דְאָעִין דְּקַדְרוֹם מְדוֹרִין תַּעְבֵּד יָת תֵּבוֹתָא וְתֶחְפֵּי יָתַהּ מִגָּו וּמִבָּרָא בְּכּוּפְרָא:
@153 וְדֵין דְּתַעְבֵּד יָתַהּ תְּלַת מְאָה אַמִּין אֻרְכָּא דְתֵבוֹתָא חַמְשִׁין אַמִּין פְּתָיַהּ וּתְלָתִין אַמִּין רוּמַהּ:
@154 נֵהוֹר תַּעְבֵּיד לְתֵבוֹתָא וּלְאַמְתָא תְּשַׁכְלְלִינַהּ מִלְּעֵלָּא וְתַרְעָא דְתֵבוֹתָא בְּסִטְרַהּ תְּשַׁוִּי מְדוֹרִין אֲרָעִין תִּנְיָנִין וּתְלִיתָאִין תַּעְבְּדִנַּהּ:
@155 וַאֲנָא הָא אֲנָא מַיְתֵי יָת טוֹפָנָא מַיָּא עַל אַרְעָא לְחַבָּלָא כָּל בִּסְרָא דִּי בֵהּ רוּחָא דְחַיֵּי מִתְּחוֹת שְׁמַיָּא כֹּל דִּי בְאַרְעָא יְמוּת:
@156 וְאָקֵם יָת קְיָמִי עִמָּךְ וְתֵעוֹל לְתֵבוֹתָא אַתְּ וּבְנָךְ וְאִתְּתָךְ וּנְשֵׁי בְנָיךְ עִמָּךְ:
@157 וּמִכָּל דְּחַי מִכָּל בִּסְרָא תְּרֵין מִכֹּלָּא תָּעֵיל לְתֵבוֹתָא לְקַיָּמָא עִמָּךְ דְּכַר וְנוּקְבָא יְהוֹן:
@158 מֵעוֹפָא לִזְנוֹהִי וּמִן בְּעִירָא לִזְנַהּ וּמִכֹּל רִחֲשָׁא דְאַרְעָא לִזְנוֹהִי תְּרֵין מִכֹּלָּא יַעֲלוּן לְוָתָךְ לְקַיָּמָא:
@159 וְאַתְּ סַב לָךְ מִכָּל מֵיכַל דְּמִתְאֲכֵל וְתִכְנוֹשׁ לְוָתָךְ וִיהֵי לָךְ וּלְהוֹן לְמֵיכָל:
@160 וַעֲבַד נֹחַ כְּכֹל דִּי פַקֵּיד יָתֵהּ יְיָ כֵּן עֲבָד:
@161 וַאֲמַר יְיָ לְנֹחַ עוּל אַתְּ וְכָל אֱנַשׁ בֵּיתָךְ לְתֵבוֹתָא אֲרֵי יָתָךְ חֲזֵיתִי זַכַּאי קֳדָמַי בְּדָרָא הָדֵין:
@162 מִכֹּל בְּעִירָא דַכְיָא תִּסַּב לָךְ שַׁבְעָא שַׁבְעָא דְּכַר וְנוּקְבָא וּמִן בְּעִירָא דְּלָא אִיתָהָא דַכְיָא הִיא תְּרֵין דְּכַר וְנוּקְבָא:
@163 אַף מֵעוֹפָא דִשְׁמַיָּא שַׁבְעָא שַׁבְעָא דְּכַר וְנוּקְבָא לְקַיָּמָא זַרְעָא עַל אַפֵּי כָל אַרְעָא:
@164 אֲרֵי לִזְמַן יוֹמִין עוֹד שַׁבְעָא אֲנָא מָחֵת מִטְרָא עַל אַרְעָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן וְאֶמְחֵי יָת כָּל יְקוּמָא דִּי עַבְדֵת מֵעַל אַפֵּי אַרְעָא:
@165 וַעֲבַד נֹחַ כְּכֹל דִּי פַקְּדֵהּ יְיָ:
@166 וְנֹחַ בַּר שִׁתְּ מְאָה שְׁנִין וְטּוֹפָנָא הֲוָה מַיָּא עַל אַרְעָא:
@167 וְעָאל נֹחַ וּבְנוֹהִי וְאִתְּתֵהּ וּנְשֵׁי בְנוֹהִי עִמֵּהּ לְתֵבוֹתָא מִן קֳדָם מֵי טוֹפָנָא:
@168 מִן בְּעִירָא דַּכְיָא וּמִן בְּעִירָא דִּי לֵיתָהָא דַּכְיָא וּמִן עוֹפָא וְכֹל דִּי רָחֵשׁ עַל אַרְעָא:
@169 תְּרֵין תְּרֵין עַלּוּ לְוַת נֹחַ לְתֵבוֹתָא דְּכַר וְנוּקְבָא כְּמָא דִּי פַּקֵּיד יְיָ יָת נֹחַ:
@170 וַהֲוָה לִזְמַן שִׁבְעַת יוֹמִין וּמֵי טוֹפָנָא הֲווֹ עַל אַרְעָא:
@171 בִּשְׁנַת שִׁתְּ מְאָה שְׁנִין לְחַיֵּי נֹחַ בְּיַרְחָא תִּנְיָנָא בְּשִׁבְעַת עַשְׂרָא יוֹמָא לְיַרְחָא בְּיוֹמָא הָדֵין אִתְבְּזָעוּ כָּל מַבּוּעֵי תְּהוֹמָא רַבָּא וְכַוֵּי שְׁמַיָּא אִתְפַּתָּחוּ:
@172 וַהֲוָה מִטְרָא נָחֵת עַל אַרְעָא אַרְבְּעִין יְמָמִין וְאַרְבְּעִין לֵילָוָן:
@173 בִּכְרַן יוֹמָא הָדֵין עָאל נֹחַ וְשֵׁם וְחָם וָיֶפֶת בְּנֵי נֹחַ וְאִתַּת נֹחַ וּתְלָתָא נְשֵׁי בְנוֹהִי עִמְהוֹן לְתֵבוֹתָא:
@174 אִנּוּן וְכָל חַיְתָא לִזְנַהּ וְכָל בְּעִירָא לְזְנַהּ וְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא לִזְנוֹהִי וְכָל עוֹפָא לִזְנוֹהִי כֹּל צִפַּר כָּל דְּפָרָח:
@175 וְעַלּוּ עִם נֹחַ לְתֵבוֹתָא תְּרֵין תְּרֵין מִכָּל בִּשְׂרָא דִּי בֵהּ רוּחָא דְּחַיֵּי:
@176 וְעָלַיָּא דְּכַר וְנוּקְבָא מִכָּל בִּשְׂרָא עַלּוּ כְּמָא דִּי פַּקֵּיד יָתֵהּ יְיָ וַאֲגֵן יְיָ (בְּמֵימְרֵהּ) עֲלוֹהִי:
@177 וַהֲוָה טוֹפָנָא אַרְבְּעִין יְמָמִין עַל אַרְעָא וּסְגִיאוּ מַיָּא וּנְטָלוּ יָת תֵּבוֹתָא וְאִתָּרָמַת מֵעַל אַרְעָא:
@178 וּתְקִיפוּ מַיָּא וּסְגִיאוּ לַחֲדָא עַל אַרְעָא וּמְהַלְּכָא תֵבוֹתָא עַל אַפֵּי מַיָּא:
@179 וּמַיָּא תְּקִיפוּ לַחֲדָא לַחֲדָא עַל אַרְעָא וְאִתְחֲפִיאוּ כָּל טוּרַיָּא רָמַיָּא דִּי תְחוֹת כָּל שְׁמַיָּא:
@180 חֲמֵשׁ עַשְׂרֵי אַמִּין מִלְעֵלָּא תְּקִיפוּ מַיָּא וְאִתְחֲפִיאוּ טוּרַיָּא:
@181 וּמִית כָּל בִּשְׂרָא דְּרָחֵשׁ עַל אַרְעָא בְּעוֹפָא וּבִבְעִירָא וּבְחַיְתָא וּבְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא וְכֹל אֱנָשָׁא:
@182 כֹּל דִּי נִשְׁמְתָא רוּחָא דְּחַיִּין בְּאַפּוֹהִי מִכֹּל דִּי בְּיַבֶּשְׁתָּא מִיתוּ:
@183 וּמְחָא יָת כָּל יְקוּמָא דִּי עַל אַפֵּי אַרְעָא מֵאֱנָשָׁא עַד בְּעִירָא עַד רִחֲשָׁא וְעַד עוֹפָא דִּשְׁמַיָּא וְאִתְמְחִיאוּ מִן אַרְעָא וְאִשְׁתָּאַר בְּרַם נֹחַ וְדִי עִמֵּהּ בְּתֵבוֹתָא:
@184 וּתְקִיפוּ מַיָּא עַל אַרְעָא מְאָה וְחַמְשִׁין יוֹמִין:
@185 וּדְכִיר יְיָ יָת נֹחַ וְיָת כָּל חַיְתָא וְיָת כָּל בְּעִירָא דִּי עִמֵּהּ בְּתֵבוֹתָא וְאַעְבַּר יְיָ רוּחָא עַל אַרְעָא וְנָחוּ מַיָּא:
@186 וְאִסְתְּכָרוּ מַבּוּעֵי תְהוֹמָא וְכַוֵּי שְׁמַיָּא וְאִתְכְּלִי מִטְרָא מִן שְׁמַיָּא:
@187 וְתָבוּ מַיָּא מֵעַל אַרְעָא אָזְלִין וְתָיְבִין וַחֲסָרוּ מַיָּא מִסּוֹף מְאָה וְחַמְשִׁין יוֹמִין:
@188 וְנָחַת תֵּבוֹתָא בְּיַרְחָא שְׁבִיעָאָה בְּשִׁבְעַת עֲשַׂר יוֹמָא לְיַרְחָא עַל טוּרֵי קַרְדּוּ:
@189 וּמַיָּא הֲווֹ אָזְלִין וְחָסְרִין עַד יַרְחָא עֲשִׂירָאָה בַּעֲשִׂירָאָה בְּחַד לְיַרְחָא אִתְחֲזִיאוּ רֵישֵׁי טוּרַיָּא:
@190 וַהֲוָה מִסּוֹף אַרְבְּעִין יוֹמִין וּפְתַח נֹחַ יָת כַּוַּת תֵּבוֹתָא דִּי עֲבָד:
@191 וְשַׁלַּח יָת עוֹרְבָא וּנְפַק מִפַּק וְתַיִּב עַד דְּיַבִּישׁוּ מַיָּא מֵעַל אַרְעָא:
@192 וְשַׁלַּח יָת יוֹנָה מִלְּוָתֵהּ לְמֵחֲזֵי הֲקַלִּיאוּ מַיָּא מֵעַל אַפֵּי אַרְעָא:
@193 וְלָא אַשְׁכַּחַת יוֹנָה מְנַח לְפַרְסַת רַגְלַהּ וְתָבַת לְוָתֵהּ לְתֵבוֹתָא אֲרֵי מַיָּא עַל אַפֵּי כָל אַרְעָא וְאוֹשִׁיט יְדֵהּ וְנָסְבַהּ וְאָעֵיל יָתַהּ לְוָתֵהּ לְתֵבוֹתָא:
@194 וְאוֹרִיךְ עוֹד שַׁבְעָא יוֹמִין אָחֳרָנִין וְאוֹסֵיף שַׁלַּח יָת יוֹנָה מִן תֵּבוֹתָא:
@195 וַאֲתַת לְוָתֵהּ יוֹנָה לְעִדַּן רַמְשָׁא וְהָא טְּרַף זֵיתָא תְּבִיר נָחִית בְּפוּמַהּ וִידַע נֹחַ אֲרֵי קַלִּיאוּ מַיָּא מֵעַל אַרְעָא:
@196 וְאוֹרִיךְ עוֹד שַׁבְעָא יוֹמִין אָחֳרָנִין וְשַׁלַּח יָת יוֹנָה וְלָא אוֹסֵיפַת לְמִתּוּב לְוָתֵהּ עוֹד:
@197 וַהֲוָה בְּשִׁתְּ מְאָה וְחַד שְׁנִין בְּקַדְמָאָה בְּחַד לְיַרְחָא נְגוּבוּ מַיָּא מֵעַל אַרְעָא וְאַעְדִּי נֹחַ יָת חוֹפָאָה דְּתֵבוֹתָא וַחֲזָא וְהָא נְגוּבוּ אַפֵּי אַרְעָא:
@198 וּבְיַרְחָא תִּנְיָנָא בְּעַשְׂרִין וְשַׁבְעָא יוֹמָא לְיַרְחָא יַבִּישַׁת אַרְעָא:
@199 וּמַלִּיל יְיָ עִם נֹחַ לְמֵימָר:
@200 פּוּק מִן תֵּבוֹתָא אַתְּ וְאִתְּתָךְ וּבְנָךְ וּנְשֵׁי בְנָיךְ עִמָךְ:
@201 כָּל חַיְתָא דְּעִמָּךְ מִכָּל בִּשְׂרָא בְּעוֹפָא וּבִבְעִירָא וּבְכָל רִחֲשָׁא דְּרָחֵשׁ עַל אַרְעָא אַפֵּיק עִמָּךְ וְיִתְיַלְּדוּן בְּאַרְעָא וְיִפְּשׁוּן וְיִסְגּוּן עַל אַרְעָא:
@202 וּנְפַק נֹחַ וּבְנוֹהִי וְאִתְּתֵהּ וּנְשֵׁי בְנוֹהִי עִמֵּהּ:
@203 כָּל חַיְתָא כָּל רִחֲשָׁא וְכָל עוֹפָא כֹּל דְּרָחֵשׁ עַל אַרְעָא לְזַרְעֲיָתְהוֹן נְפָקוּ מִן תֵּבוֹתָא:
@204 וּבְנָא נֹחַ מַדְבְּחָא קֳדָם יְיָ וּנְסִיב מִכֹּל בְּעִירָא דַּכְיָא וּמִכֹּל עוֹפָא דְכֵי וְאַסֵּיק עֲלָוָן בְּמִדְבְּחָא:
@205 וְקַבִּיל יְיָ בְּרַעֲוָא יָת קוּרְבָּנֵהּ וַאֲמַר יְיָ בְּמֵימְרֵהּ לָא אוֹסֵף לְמֵילַט עוֹד יָת אַרְעָא בְּדִיל חוֹבֵי אֱנָשָׁא אֲרֵי יִצְרָא לִבָּא דֶּאֱנָשָׁא בִּישׁ מִזְעִירֵהּ וְלָא אוֹסֵף עוֹד לְמִמְחֵי יָת כָּל דְּחַי כְּמָא דִעַבָדִית:
@206 עוֹד כָּל יוֹמֵי אַרְעָא זְרוֹעָא וַחֲצָדָא וְקוֹרָא וְחוֹמָא וְקַיְטָא וְסִתְוָא וִימָם וְלֵילְיָא לָא יִבְטְּלוּן:
@207 וּבָרִיךְ יְיָ יָת נֹחַ וְיָת בְּנוֹהִי וַאֲמַר לְהוֹן פּוּשׁוּ וּסְגוּ וּמְלוּ יָת אַרְעָא:
@208 וְדַחֲלַתְכוֹן וְאֵימַתְכוֹן תְּהֵי עַל כָּל חֵוַת אַרְעָא וְעַל כָּל עוֹפָא דִּשְׁמַיָּא בְּכֹל דִּי תַרְחֵישׁ אַרְעָא וּבְכָל נוּנֵי יַמָּא בְּיֶדְכוֹן יְהוֹן מְסִירִין:
@209 כָּל רִחֲשָׁא דְּהוּא חַי לְכוֹן יְהֵי לְמֵיכָל כִּירוֹק עִשְׂבָּא יְהָבִית לְכוֹן יָת כֹּלָּא:
@210 בְּרַם בִּשְׂרָא בְּנַפְשֵׁהּ דְּמֵהּ לָא תֵכְלוּן:
@211 וּבְרַם יָת דִּמְכוֹן לְנַפְשָׁתֵיכוֹן אֶתְבַּע מִיַּד כָּל חַיְתָא אֶתְבְּעִנֵהּ וּמִיַד אֱנָשָׁא מִיַד גְבַר דְיֵשׁוֹד יָת דְמָא דַאֲחוֹהִי אֶתְבַּע יָת נַפְשָׁא דֶאֱנָשָׁא:
@212 דְיֵשׁוֹד דְמָא דֶאֱנָשָׁא בְּסַעֲדִין עַל מֵימַר דַיָנַיָא דְמֵהּ יִתְּשָׁד אֲרֵי בְּצַלְמָא דַיְיָ עֲבַד יָת אֱנָשָׁא:
@213 וְאַתּוּן פּוּשׁוּ וּסְגוּ אִתְיְלִידוּ בְאַרְעָא וּסְגוּ בַהּ:
@214 וַאֲמַר יְיָ לְנֹחַ וְלִבְנוֹהִי עִמֵּהּ לְמֵימָר:
@215 וַאֲנָא הָא אֲנָא מֵקִים יָת קְיָמִי עִמְּכוֹן וְעִם בְּנֵיכוֹן בַּתְרֵיכוֹן:
@216 וְעִם כָּל נַפְשָׁא חַיְתָא דְּעִמְּכוֹן בְּעוֹפָא בִבְעִירָא וּבְכָל חַיַת אַרְעָא דְּעִמְּכוֹן מִכֹּל נַפְקֵי תֵבוֹתָא לְכֹל חַיַת אַרְעָא:
@217 וְאָקֵם יָת קְיָמִי עִמְּכוֹן וְלָא יִשְׁתֵּיצֵי כָל בִּשְׂרָא עוֹד מִמֵּי טוֹפָנָא וְלָא יְהֵי עוֹד טוֹפָנָא לְחַבָּלָא אַרְעָא:
@218 וַאֲמַר יְיָ דָּא אָת קְיָם דִּי אֲנָא יָהֵב בֵּין מֵימְרִי וּבֵינֵכוֹן וּבֵין כָּל נַפְשָׁא חַיְתָא דִּי עִמְּכוֹן לְדָרֵי עַלְמָא:
@219 יָת קַשְׁתִּי יְהָבִית בַּעֲנָנָא וּתְהִי לְאָת קְיָם בֵּין מֵימְרִי וּבֵין אַרְעָא:
@220 וִיהִי בַּעֲנָנוּתִי עֲנָנָא עַל אַרְעָא וְתִתְחֲזֵי קַשְׁתָּא בַּעֲנָנָא:
@221 וְדָכִירְנָא יָת קְיָמִי דִּי בֵין מֵימְרִי וּבֵינֵיכוֹן וּבֵין כָּל נַפְשָׁא חַיְתָא בְּכָל בִּשְׂרָא וְלָא יְהֵי עוֹד מַיָּא לְטוֹפָנָא לְחַבָּלָא כָל בִּשְׂרָא:
@222 וּתְהֵי קַשְׁתָּא בַּעֲנָנָא וְאֵחֲזִנַּהּ לְמִדְכַּר קְיַם עָלָם בֵּין מֵימְרָא דַּיְיָ וּבֵין כָּל נַפְשָׁא חַיְתָא בְּכָל בִּשְׂרָא דִּי עַל אַרְעָא:
@223 וַאֲמַר יְיָ לְנֹחַ דָּא אָת קְיָם דִּי אֲקֵמִית בֵּין מֵימְרִי וּבֵין כָּל בִּשְׂרָא דִּי עַל אַרְעָא:
@224 וַהֲווֹ בְנֵי נֹחַ דִּי נְפָקוּ מִן תֵּבוֹתָא שֵׁם וְחָם וָיָפֶת וְחָם הוּא אֲבוּהִי דִכְנָעַן:
@225 תְּלָתָא אִלֵּין בְּנֵי נֹחַ וּמֵאִלֵּין אִתְבַּדָּרוּ כָּל אַרְעָא:
@226 וְשָׁרִי נֹחַ גְּבַר פָּלַח בְּאַרְעָא וּנְצִיב כַּרְמָא:
@227 וּשְׁתִי מִן חַמְרָא וּרְוִי וְאִתְגְּלִי בְּגוֹ מַשְׁכְּנֵהּ:
@228 וַחֲזָא חָם אֲבוּהִי דִּכְנַעַן יָת עֶרְיְתָא דַּאֲבוּהִי וְחַוֵּי לִתְרֵין אֲחוֹהִי בְּשׁוּקָא:
@229 וּנְסֵיב שֵׁם וָיֶפֶת יָת כְּסוּתָא וְשַׁוִּיוּ עַל כְּתַף תַּרְוֵיהוֹן וַאֲזָלוּ מְחַזְרִין וַחֲפִיאוּ יָת עֶרְיְתָא דַּאֲבוּהוֹן וְאַפֵּיהוֹן מְחַזְרִין וְעֶרְיְתָא דַּאֲבוּהוֹן לָא חֲזוֹ:
@230 וְאִתְּעַר נֹחַ מֵחַמְרֵהּ וִידַע יָת דִּי עֲבַד לֵהּ בְּרֵהּ זְעֵירָא:
@231 וַאֲמַר לִיט כְּנַעַן עֲבַד פְּלַח עַבְדִין יְהֵי לַאֲחוֹהִי:
@232 וַאֲמַר בְּרִיךְ יְיָ אֱלָהֵהּ דְּשֵׁם וִיהֵי כְנַעַן עַבְדָא לְהוֹן:
@233 יַפְתֵּי יְיָ לְיֶפֶת וְיִשְׁרֵי שְׁכִינְתֵּהּ בְּמַשְׁכְּנֵהּ דְּשֵׁם וִיהֵי כְנַעַן עַבְדָא לְהוֹן:
@234 וַחֲיָא נֹחַ בָּתַר טוֹפָנָא תְּלַת מְאָה וְחַמְשִׁין שְׁנִין:
@235 וַהֲווֹ כָל יוֹמֵי נֹחַ תְּשַׁע מְאָה וְחַמְשִׁין שְׁנִין וּמִית:
@236 וְאִלֵּין תּוּלְדַת בְּנֵי נֹחַ שֵׁם חָם וָיָפֶת וְאִתְיְלִידוּ לְהוֹן בְּנִין בָּתַר טוֹפָנָא:
@237 בְּנֵי יֶפֶת גּוֹמֶר וּמָגוֹג וּמָדַי וְיָוָן וְתוּבָל וּמֶשֶׁךְ וְתִירָס:
@238 וּבְנֵי גּוֹמֶר אַשְׁכְּנַז וְרִיפַת וְתוֹגַרְמָה:
@239 וּבְנֵי יָוָן אֱלִישָׁה וְתַרְשִׁישׁ כִּתִּים וְדֹדָנִים:
@240 מֵאִלֵּין אִתַּפְרָשׁוּ נַגְוַת עַמְמַיָּא בְּאַרְעֲהוֹן גְּבַר לְלִישָׁנֵהּ לְזַרְעֲיָתְהוֹן בְּעַמְמֵיהוֹן:
@241 וּבְנֵי חָם כּוּשׁ וּמִצְרַיִם וּפוּט וּכְנָעַן:
@242 וּבְנֵי כוּשׁ סְבָא וַחֲוִילָה וְסַבְתָּה וְרַעְמָה וְסַבְתְּכָא וּבְנֵי רַעְמָה שְׁבָא וּדְדָן:
@243 וְכוּשׁ אוֹלִיד יָת נִמְרֹד הוּא שָׁרֵי לְמֵהֲוֵי גִבַּר תַּקִּיף בְּאַרְעָא:
@244 הוּא הֲוָה גִבַּר תַּקִּיף קֳדָם יְיָ עַל כֵּן יִתְאֲמַר כְּנִמְרֹד גִּבַּר תַּקִּיף קֳדָם יְיָ:
@245 וַהֲוָה רֵישׁ מַלְכוּתֵהּ בָּבֶל וְאֶרֶךְ וְאַכַּד וְכַלְנֵה בְּאַרְעָא דְּבָבֶל:
@246 מִן אַרְעָא (ס''א עֵיצָה) הַהִיא נְפַק אֲתוּרָאָה וּבְנָא יָת נִינְוֵה וְיָת רְחֹבֹת (נ''א רְחוֹבֵי) קַרְתָּא וְיָת כָּלַח:
@247 וְיָת רֶסֶן בֵּין נִינְוֵה וּבֵין כָּלַח הִיא קַרְתָּא רַבְּתָא:
@248 וּמִצרָאֵי (בכל הס':וּמִצְרַיִם) אוֹלִיד יָת לוּדָאֵי וְיָת עֲנָמָאֵי וְיָת לְהָבָאֵי וְיָת נַפְתּוּחָאֵי:
@249 וְיָת פַּתְרוּסָאֵי וְיָת כַּסְלוּחָאֵי דִּי נְפָקוּ מִתַּמָּן פְּלִשְׁתָּאֵי וְיָת קַפּוּטְקָאֵי:
@250 וּכְנַעַן אוֹלִיד יָת צִידוֹן בָּכְרֵהּ וְיָת חֵת:
@251 וְיָת יְבוּסָאֵי וְיָת אֱמוֹרָאֵי וְיָת גִּרְגָּשָׁאֵי:
@252 וְיָת חִוָּאֵי וְיָת עַרְקָאֵי וְיָת אַנְתּוֹסָאֵי:
@253 וְיָת אַרְוָדָאֵי וְיָת צְמָרָאֵי וְיָת חֲמָתָאֵי וּבָתַר כֵּן אִתְבַּדָּרוּ זַרְעֲיַת כְּנַעֲנָאֵי:
@254 וַהֲוָה תְּחוּם כְּנַעֲנָאֵי מִצִידוֹן מָטֵי לִגְרָר עַד עַזָּה מָטֵי לִסְדוֹם וַעֲמוֹרָה וְאַדְמָה וּצְבוֹיִם עַד לָשַׁע:
@255 אִלֵּין בְּנֵי חָם לְזַרְעֲיָתְהוֹן לְלִישָׁנְהוֹן בְּאַרְעָתְהוֹן בְּעַמְמֵיהוֹן:
@256 וּלְשֵׁם אִתְיְלִיד אַף הוּא אֲבוּהוֹן דְּכָל בְּנֵי עֵבֶר אָחוּהִי דְּיֶפֶת רַבָּא:
@257 בְּנֵי שֵׁם עֵילָם וְאַשּׁוּר וְאַרְפַּכְשַׁד וְלוּד וַאֲרָם:
@258 וּבְנֵי אֲרָם עוּץ וְחוּל וְגֶתֶר וָמַשׁ:
@259 וְאַרְפַּכְשַׁד אוֹלִיד יָת שָׁלַח וְשֶׁלַח אוֹלִיד יָת עֵבֶר:
@260 וּלְעֵבֶר אִתְיְלִידוּ תְּרֵין בְּנִין שׁוּם חַד פֶּלֶג אֲרֵי בְּיוֹמוֹהִי אִתְפְּלִיגַת אַרְעָא וְשׁוּם אֲחוּהִי יָקְטָן:
@261 וְיָקְטָן אוֹלִיד יָת אַלְמוֹדָד וְיָת שָׁלֶף וְיָת חֲצַרְמָוֶת וְיָת יָרַח:
@262 וְיָת הֲדוֹרָם וְיָת אוּזָל וְיָת דִּקְלָה:
@263 וְיָת עוֹבָל וְיָת אֲבִימָאֵל וְיָת שְׁבָא:
@264 וְיָת אוֹפִר וְיָת חֲוִילָה וְיָת יוֹבָב כָּל אִלֵּין בְּנֵי יָקְטָן:
@265 וַהֲוָה מוֹתְבָנֵהוֹן מִמֵּשָׁא מָטֵי לִסְפַר טּוּר מָדִינְחָא:
@266 אִלֵּין בְּנֵי שֵׁם לְזַרְעֲיָתְהוֹן לְלִישָׁנְהוֹן לְאַרְעָתְהוֹן בְּעַמְמֵיהוֹן:
@267 אִלֵּין זַרְעֲיַת בְּנֵי נֹחַ לְתוּלְדָתְהוֹן בְּעַמְמֵיהוֹן וּמֵאִלֵּין אִתַּפְרָשׁוּ עַמְמַיָּא בְּאַרְעָא בָּתַר טוֹפָנָא:
@268 וַהֲוָה כָל אַרְעָא לִישָׁן חָד וּמַמְלָל חָד:
@269 וַהֲוָה בְּמִטַּלְהוֹן בְּקַדְמֵיתָא וְאַשְׁכָּחוּ בִקְעֲתָא בְּאַרְעָא דְבָבֶל וִיתִיבוּ תַמָּן:
@270 וַאֲמָרוּ גְּבַר לְחַבְרֵהּ הָבוּ נִרְמֵי לִבְנִין וְנוֹקְדִינוּן בְּנוּרָא יוֹקַדְתָּא (נ''י בְּנוּרָא) וַהֲוַת לְהוֹן לְבִנְתָּא לְאַבְנָא וְחֵימָרָא הֲוָה לְהוֹן לְשִׁיעַ:
@271 וַאֲמָרוּ הָבוּ נִבְנֵי לָנָא קַרְתָּא וּמַגְדְּלָא וְרֵישֵׁהּ מָטֵי עַד צֵית שְׁמַיָּא וְנַעְבֵּיד לָנָא שׁוּם דִּילְמָא נִתְבַּדַּר עַל אַפֵּי כָל אַרְעָא:
@272 וְאִתְגְּלֵי יְיָ לְאִתְפְּרָעָא עַל עוֹבָדֵי קַרְתָּא וּמַגְדְּלָא דִּי בְנוֹ בְּנֵי אֱנָשָׁא:
@273 וַאֲמַר יְיָ הָא עַמָּא חַד וְלִישָׁן חַד לְכֻלְּהוֹן וְדֵין דְּשָׁרִיוּ לְמֶעְבָּד וּכְעַן לָא יִתִּמְנַע מִנְּהוֹן כֹּל דִחַשִּׁיבוּ לְמֶעְבָּד:
@274 הָבוּ נִתְגְּלִי וּנְבַלְבֵּל תַּמָּן לִישָׁנְהוֹן דְּלָא יִשְׁמְעוּן (גְּבַר) אֱנַשׁ לִישָׁן חַבְרֵהּ:
@275 וּבַדַּר יְיָ יָתְהוֹן מִתַּמָּן עַל אַפֵּי כָל אַרְעָא וּמְנָעוּ לְמִבְנֵי (נ''י וְאִתְמְנָע מִלְּמִבְנֵי) קַרְתָּא:
@276 עַל כֵּן קְרָא שְׁמַהּ בָּבֶל אֲרֵי תַמָּן בַּלְבֵּל יְיָ לִישַׁן כָּל אַרְעָא וּמִתַּמָּן בַּדָּרִנּוּן יְיָ עַל אַפֵּי כָּל אַרְעָא:
@277 אִלֵּין תּוּלְדַת שֵׁם שֵׁם בַּר מְאָה שְׁנִין וְאוֹלִיד יָת אַרְפַּכְשָׁד תַּרְתֵּין שְׁנִין בָּתַר טּוֹפָנָא:
@278 וַחֲיָא שֵׁם בָּתַר דְּאוֹלִיד יָת אַרְפַּכְשָׁד חֲמֵשׁ מְאָה שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@279 וְאַרְפַּכְשַׁד חֲיָא תְּלָתִין וַחֲמֵשׁ שְׁנִין וְאוֹלִיד יָת שָׁלַח:
@280 וַחֲיָא אַרְפַּכְשַׁד בָּתַר דְּאוֹלִיד יָת שֶׁלַח אַרְבַּע מְאָה וּתְלָת שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@281 וְשֶׁלַח חֲיָא תְּלָתִין שְׁנִין וְאוֹלִיד יָת עֵבֶר:
@282 וַחֲיָא שֶׁלַח בָּתַר דְּאוֹלִיד יָת עֵבֶר אַרְבַּע מְאָה וּתְלָת שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@283 וַחֲיָא עֵבֶר תְּלָתִין וְאַרְבַּע שְׁנִין וְאוֹלִיד יָת פָּלֶג:
@284 וַחֲיָא עֵבֶר בָּתַר דְּאוֹלִיד יָת פֶּלֶג אַרְבַּע מְאָה וּתְּלָתִין שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@285 וַחֲיָא פֶלֶג תְּלָתִין שְׁנִין וְאוֹלִיד יָת רְעוּ:
@286 וַחֲיָא פֶלֶג בָּתַר דְּאוֹלִיד יָת רְעוּ מָאתָן וּתְשַׁע שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@287 וַחֲיָא רְעוּ תְּלָתִין וְתַרְתֵּין שְׁנִין וְאוֹלִיד יָת שְׂרוּג:
@288 וַחֲיָא רְעוּ בָּתַר דְּאוֹלִיד יָת שְׂרוּג מָאתָן וּשְׁבַע שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@289 וַחֲיָא שְׂרוּג תְּלָתִין שְׁנִין וְאוֹלִיד יָת נָחוֹר:
@290 וַחֲיָא שְׂרוּג בָּתַר דְּאוֹלִיד יָת נָחוֹר מָאתָן שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@291 וַחֲיָא נָחוֹר עֶשְׂרִין וּתְשַׁע שְׁנִין וְאוֹלִיד יָת תָּרַח:
@292 וַחֲיָא נָחוֹר בָּתַר דְּאוֹלִיד יָת תֶּרַח מְאָה וּתְשַׁע עֲשַׂר שְׁנִין וְאוֹלִיד בְּנִין וּבְנָן:
@293 וַחֲיָא תֶרַח שִׁבְעִין שְׁנִין וְאוֹלִיד יָת אַבְרָם יָת נָחוֹר וְיָת הָרָן:
@294 וְאִלֵּין תּוּלְדַת תֶּרַח תֶּרַח אוֹלִיד יָת אַבְרָם יָת נָחוֹר וְיָת הָרָן וְהָרָן אוֹלִיד יָת לוֹטּ:
@295 וּמִית הָרָן עַל אַפֵּי תֶּרַח אֲבוּהִי בְּאַרְעָא דְּיַלָּדוּתֵהּ בְּאוּרָא דְכַסְדָּאֵי:
@296 וּנְסִיב אַבְרָם וְנָחוֹר לְהוֹן נְשִׁין שׁוּם אִתַּת אַבְרָם שָׂרָי וְשׁוּם אִתַּת נָחוֹר מִלְכָּה בַּת הָרָן אֲבוּהָא דְּמִלְכָּה וַאֲבוּהָא דְּיִסְכָּה:
@297 וַהֲוַת שָׂרַי עֲקָרָה לֵית לָהּ וְלָד:
@298 וּדְבַר תֶּרַח יָת אַבְרָם בְּרֵהּ וְיָת לוֹט בַּר הָרָן בַּר בְּרֵהּ וְיָת שָׂרַי כַּלָּתֵהּ אִתַּת אַבְרָם בְּרֵהּ וּנְפָקוּ עִמְּהוֹן מֵאוּרָא דְּכַסְדָּאֵי לְמֵיזַל לְאַרְעָא דִּכְנָעַן וַאֲתוֹ עַד חָרָן וִיתִיבוּ תַמָּן:
@299 וַהֲווֹ יוֹמֵי תֶרַח מָאָתן וַחֲמֵשׁ שְׁנִין וּמִית תֶּרַח בְּחָרָן: פפפ:
@300 וַאֲמַר יְיָ לְאַבְרָם אִיזֵל לָךְ מֵאַרְעָךְ וּמִיַּלָּדוּתָךְ וּמִבֵּית אֲבוּךְ לְאַרְעָא דִּי אַחֲזִנָּךְ:
@301 וְאֶעְבְּדִנָּךְ לְעַם סַגִּי וֶאֱבָרֵכִנָּךְ וַאֲרַבֵּי שְׁמָךְ וּתְהֵא מְבָרֵךְ:
@302 וֶאֱבָרֵךְ מְבָרְכָךְ וּמְלַטְטָךְ אֵילוּט וְיִתְבָּרֲכוּן בְּדִילָךְ כֹּל זַרְעֲיַת אַרְעָא:
@303 וַאֲזַל אַבְרָם כְּמָא דְּמַלֵּיל עִמֵּהּ יְיָ וַאֲזַל עִמֵּהּ לוֹטּ וְאַבְרָם בַּר שִׁבְעִין וַחֲמֵשׁ שְׁנִין בְּמִפְקֵהּ מֵחָרָן:
@304 וּדְבַר אַבְרָם יָת שָׂרַי אִתְּתֵהּ וְיָת לוֹט בַר אֲחוּהִי וְיָת כָּל קִנְיָנְהוֹן דִּי קְנוֹ וְיָת נַפְשָׁתָא דְּשַׁעֲבִּידוּ לְאוֹרַיְתָא בְחָרָן וּנְפָקוּ לְמֵיזַל לְאַרְעָא דִּכְנַעַן וַאֲתוֹ לְאַרְעָא דִּכְנָעַן:
@305 וַעֲבַר אַבְרָם בְּאַרְעָא עַד אֲתַר שְׁכֶם עַד מֵישַׁר מוֹרֶה וּכְנַעֲנָאָה בְּכֵן בְּאַרְעָא:
@306 וְאִתְגְּלִי יְיָ לְאַבְרָם וַאֲמַר לִבְנָךְ אֶתֵּן יָת אַרְעָא הָדָא וּבְנָא תַמָּן מַדְבְּחָא קֳדָם יְיָ דְּאִתְגְּלִי לֵהּ:
@307 וְאִסְתַּלַּק מִתַּמָּן לְטוּרָא מִמַדְנַח לְבֵית אֵל וּפְרַס מַשְׁכְּנֵהּ בֵּית אֵל מִמַּעַרְבָא וְעַי מִמָּדִינְחָא וּבְנָא תַמָּן מִדְבְּחָא קֳדָם יְיָ וְצַלִּי בִּשְׁמָא דַּיְיָ:
@308 וּנְטַּל אַבְרָם אָזֵל וְנָטֵל לְדָרוֹמָא:
@309 וַהֲוָה כַפְנָא בְּאַרְעָא וּנְחַת אַבְרָם לְמִצְרַיִם לְאִתּוֹתָבָא תַמָּן אֲרֵי תַקִּיף כַּפְנָא בְּאַרְעָא:
@310 וַהֲוָה כַּד קְרֵיב לְמֵיעַל לְמִצְרָיִם וַאֲמַר לְשָׂרַי אִתְּתֵה הָא כְעַן יְדָעִית אֲרֵי אִתְּתָא שַׁפִּירַת חֵיזוּ אָתְּ:
@311 וִיהֵי כַּד (נ''י אֲרֵי) יֶחֱזוּן יָתִיךְ מִצְרָאֵי וְיֵימְרוּן אִתְּתֵהּ דָּא וְיִקְטְלוּן יָתִי וְיָתִיךְ יְקַיְמוּן:
@312 אִמְרִי כְעַן אֲחָתִי אָתְּ בְּדִיל דְּיֵיטַב לִי בְּדִילָךְ וְתִתְקַיֵּם נַפְשִׁי בְּפִתְגָּמָיְכִי:
@313 וַהֲוָה כַּד עַל אַבְרָם לְמִצְרָיִם וַחֲזוֹ מִצְרָאֵי יָת אִתְּתָא אֲרֵי שַׁפִּירָא הִיא לַחֲדָא:
@314 וַחֲזוֹ יָתַהּ רַבְרְבֵי פַרְעֹה וְשַׁבָּחוּ יָתַהּ לְפַרְעֹה וְאִדַּבָּרַת אִתְּתָא לְבֵית פַּרְעֹה:
@315 וּלְאַבְרָם אוֹטִיב בְּדִילַהּ וַהֲווֹ לֵהּ עָאן וְתוֹרִין וַחֲמָרִין וְעַבְדִין וְאַמְהָן וְאַתְנָן וְגַמְלִין:
@316 וְאַיְתִי יְיָ עַל פַּרְעֹה מַכְתָּשִׁין רַבְרְבִין וְעַל אֱנַשׁ בֵּיתֵהּ עַל עֵיסַק שָׂרַי אִתַּת אַבְרָם:
@317 וּקְרָא פַרְעֹה לְאַבְרָם וַאֲמַר מָה דָּא עֲבַדְתְּ לִי לְמָא לָא חַוֵּיתָא לִי אֲרֵי אִתְּתָךְ הִיא:
@318 לְמָא אֲמַרְתְּ אֲחָתִי הִיא וּדְבָרִית יָתַהּ לִי לְאִתּוּ וּכְעַן הָא אִתְּתָךְ דְּבַר וְאִיזֵל:
@319 וּפַקִּיד עֲלוֹהִי פַּרְעֹה גּוּבְרִין וְאַלְוִיאוּ יָתֵהּ וְיָת אִתְּתֵהּ וְיָת כָּל דִילֵהּ:
@320 וּסְלֵיק אַבְרָם מִמִּצְרַיִם הוּא וְאִתְּתֵהּ וְכָל דִּילֵהּ וְלוֹט עִמֵּהּ לְדָרוֹמָא:
@321 וְאַבְרָם תַּקִּיף לַחֲדָא בִּבְעִירָא בְּכַסְפָּא וּבְדַהֲבָא:
@322 וַאֲזַל לְמַטְלָנוֹהִי מִדָּרוֹמָא וְעַד בֵּית אֵל עַד אַתְרָא דִּי פְּרַס תַּמָּן מַשְׁכְּנֵהּ בְּקַדְמֵיתָא בֵּין בֵּית אֵל וּבֵין עָי:
@323 לַאֲתַר מַדְבְּחָא דִּי עֲבַד תַּמָּן בְּקַדְמֵיתָא וְצַלֵּי תַמָּן אַבְרָם בִּשְׁמָא דַּיְיָ:
@324 וְאַף לְלוֹט דְּאָזִיל עִם אַבְרָם הֲוָה עָאן וְתוֹרִין וּמַשְׁכְּנִין:
@325 וְלָא סוֹבָרַת יָתְהוֹן אַרְעָא לְמִיתַב כַּחֲדָא אֲרֵי הֲוָה קִנְיָנְהוֹן סַגִּי וְלָא יְכִילוּ לְמִיתַּב כַּחֲדָא:
@326 וַהַוַת מַצוּתָא בֵּין רָעֵי בְּעִירֵה דְאַבְרָם וּבֵין רָעֵי בְּעִירֵה דְלוֹט וּכְנַעֲנָאָה וּפְרִזָאָה בְּכֵן יָתִיב בְּאַרְעָא:
@327 וַאֲמַר אַבְרָם לְלוֹט לָא כְעַן תְּהֵי מַצוּתָא בֵּינָא וּבֵינָךְ וּבֵין רַעֲוָתִי וּבֵין רַעֲוָתָךְ אֲרֵי גוּבְרִין אַחִין אֲנָחְנָא:
@328 הֲלָא כָל אַרְעָא קֳדָמָךְ אִתְפָּרַשׁ כְּעַן מִלְוָתִי אִם אַתְּ לְצִפּוּנָא וַאֲנָא לְדָרוֹמָא וְאִם אַתְּ לְדָרוֹמָא וַאֲנָא לְצִפּוּנָא:
@329 וּזְקַף לוֹט יָת עֵינוֹהִי וַחֲזָא יָת כָּל מֵישַׁר יַרְדְנָא אֲרֵי כֻלַהּ בֵּית שַׁקְיָא קֳדָם חַבָּלוּת יְיָ יָת סְדוֹם וְיָת עֲמֹרָא כְּגִנְתָא דַיְיָ כְּאַרְעָא דְמִצְרַיִם מָטֵּי לְצוֹעַר:
@330 וּבְחַר לֵיהּ לוֹט יַת כָּל מֵישַׁר יַרְדְנָא וּנְטַל לוֹט מִלְקַדְמִין וְאִתַּפְרָשׁוּ גְבַר מִלְוַת אָחוּהִי:
@331 אַבְרָם יָתֵיב בְּאַרְעָא דִכְנָעַן וְלוֹט יָתֵיב בְּקִרְוֵי מֵישְׁרָא וּפְרַס עַד סְדוֹם:
@332 וֶאֱנָשִׁין דִסְדוֹם בִּישִׁין בְּמָמוֹנְהוֹן וְחַיָבִין בִּגְוִיָתְהוֹן קֳדָם יְיָ לַחֲדָא:
@333 וַיְיָ אֲמַר לְאַבְרָם בָּתַר דְאִתְפָּרֶשׁ לוֹט מֵעִמֵהּ זְקוֹף כְּעַן עֵינָךְ וַחֲזֵי מִן אַתְרָא דְאַתְּ תַּמָן לְצִפּוּנָא וּלְדָרוֹמָא וּלְמַדִינְחָא וּלְמַעֲרָבָא:
@334 אֲרֵי יָת כָּל אַרְעָא דִי אַתְּ חָזֵי לָךְ אֶתְּנִנַהּ וְלִבְנָיךְ עַד עָלָם:
@335 וֶאֱשַׁוֵּי יָת בְּנָיךְ סַגִיאִין כְּעַפְרָא דְאַרְעָא כְּמָא דִי לָא אֶפְשַׁר לִגְבַר לְּמִמְנֵי יָת עַפְרָא דְאַרְעָא אַף בְּנָיךְ לָא יִתִּמְנוּן:
@336 קוּם הֲלִיךְ בְּאַרְעָא לְאָרְכַּהּ וְלִפְתָיַהּ אֲרֵי לָךְ אֶתְּנִינַהּ:
@337 וּפְרַס אַבְרָם וַאֲתָא וִיתֵב בְּמֵישְׁרֵי מַמְרֵא דִי בְחֶבְרוֹן וּבְנָא תַמָן מַדְבְּחָא קֳדָם יְיָ:
@338 וַהֲוָה בְיוֹמֵי אַמְרָפֶל מַלְכָּא דְבָבֶל אַרְיוֹךְ מַלְכָּא דְאֶלָסָר כְּדָרְלָעוֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמֵי:
@339 סְדָרוּ (נ''א עֲבָדוּ) קְרָבָא עִם בֶּרַע מַלְכָּא דִסְדוֹם וְעִם בִּרְשַׁע מַלְכָּא דַעֲמֹרָה שִׁנְאָב מַלְכָּא דְאַדְמָה וְשֶׁמְאֵבֶר מַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַּע הִיא צוֹעַר:
@340 כָּל אִלֵין אִתְכְּנָשׁוּ לְמֵישַׁר חַקְלַיָא הוּא אֲתַר יַמָא דְמִלְחָא:
@341 תַּרְתֵּי עַשְׂרֵי שְׁנִין פְּלָחוּ יָת כְּדָרְלָעוֹמֶר וּתְלָת עֶשְׂרֵי שְׁנִין מְרָדוּ:
@342 וּבְאַרְבַּע עֶשְׂרֵי שְׁנִין אֲתָא כְּדָרְלָעֹמֶר וּמַלְכַיָא דְעִמֵהּ וּמְחוֹ יָת גִבָּרַיָא דִי בְעַשְׁתְּרוֹת קַרְנַיִם וְיָת תַּקִיפַיָא דִבְהֶמְתָּא וְיָת אֵמְתָנֵי דִבְשָׁוֵה קִרְיָתָיִם:
@343 וְיָת חוֹרָאֵי דִי בְּטוּרְהוֹן דְשֵׂעִיר עַד מֵישַׁר פָּארָן דִסְמִיךְ עַל מַדְבְּרָא:
@344 וְתָבוּ וַאֲתוּ לְמֵישַׁר פִּלּוּג דִינָא הִיא רְקָם וּמְחוֹ יָת כָּל חֲקַל עֲמַלְקָאָה וְאַף יָת אֱמוֹרָאָה דְיָתֵיב בְּעֵין גֶּדִי:
@345 וּנְפַק מַלְכָּא דִסְדוֹם וּמַלְכָּא דַעֲמוֹרָה וּמַלְכָּא דְאַדְמָה וּמַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַע הִיא צוֹעַר וְסַדָרוּ עִמְהוֹן קְרָבָא בְּמֵישַׁר חַקְלַיָא:
@346 עִם כְּדָרְלָעֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמִין וְאַמְרָפֶל מַלְכָּא דְבָבֶל וְאַרְיוֹךְ מַלְכָּא דְאֶלָסָר אַרְבְּעָה מַלְכִין לָקֳבֵיל חַמְשָׁא:
@347 וּמֵישַׁר חַקְלַיָא בֵּירִין בֵּירִין מַסְקַן חֵימָרָא וַעֲרָקוּ מַלְכָּא דִסְדוֹם וַעֲמוֹרָה וּנְפָלוּ תַמָן וּדְאִשְׁתָּאֲרוּ לְטוּרָא עֲרָקוּ:
@348 וּשְׁבוֹ יָת כָּל קִנְיָנָא דִסְדוֹם וַעֲמוֹרָה וְיָת כָּל מֵיכָלְהוֹן וַאֲזָלוּ:
@349 וּשְׁבוֹ יָת לוֹט וְיָת קִנְיָנֵהּ בַּר אַחוּהִי דְאַבְרָם וַאֲזָלוּ וְהוּא יָתֵיב בִּסְדוֹם:
@350 וַאֲתָא מְשֵׁיזָבָא וְחַוִּי לְאַבְרָם עִבְרָאָה וְהוּא שָׁרֵי בְּמֵישְׁרֵי מַמְרֵא אֱמוֹרָאָה אֲחוּהִי דְאֶשְׁכּוֹל וַאֲחוּהִי דְעָנֵר וְאִינוּן אֱנָשֵׁי קְיָמֵהּ דְאַבְרָם:
@351 וּשְׁמַע אַבְרָם אֲרֵי אִשְׁתְּבִי אֲחוּהִי וְזָרֵיז יָת עוּלֵמוֹהִי יְלִידֵי בֵיתֵהּ תְּלַת מְאָה וְתַמְנֵי עֲסַר וּרְדַף עַד דָן:
@352 וְאִתְפְּלֵג עֲלֵיהוֹן לֵילְיָא הוּא וְעַבְדוֹהִי וּמְחוֹנוּן וּרְדָפִנוּן עַד חוֹבָא דִי מִצִפּוּנָא לְדַמָשֶׂק:
@353 וַאֲתֵיב יָת כָּל קִנְיָנָא וְאַף יָת לוֹט בַּר אֲחוּהִי וְקִנְיָנֵהּ אֲתֵיב וְאַף יָת נְשַׁיָא וְיָת עַמָא:
@354 וּנְפַק מַלְכָּא דִסְדוֹם לְקַדָמוּתֵה בָּתַר דְתָב מִלְמִמְחֵי יָת כְּדָרְלָעוֹמֶר וְיָת מַלְכַיָא דִי עִמֵהּ לְמֵישַׁר מַפְנָא הוּא אֲתַר בֵּית רֵיסָא דְמַלְכָּא:
@355 וּמַלְכִּי צֶדֶק מַלְכָּא דִירוּשְׁלֶם אַפֵּיק לְחֵם וַחֲמָר וְהוּא מְשַׁמֵשׁ קֳדָם אֵל עִלָאָה:
@356 וּבָרְכֵיהּ וַאֲמָר בְּרִיךְ אַבְרָם לְאֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@357 וּבְרִיךְ אֵל עִלָאָה דִמְסַר סָנְאָיךְ בִּידָךְ וִיהַב לֵיהּ חַד מִן עַשְׂרָא מִכֹּלָא:
@358 וַאֲמַר מַלְכָּא דִסְדוֹם לְאַבְרָם הַב לִי נַפְשָׁתָא וְקִנְיָנָא (סַב) דְבַר לָךְ:
@359 וַאֲמַר אַבְרָם לְמַלְכָּא דִסְדוֹם אֲרֵמִית יְדַי בִּצְלוֹ קֳדָם יְיָ אֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@360 אִם מִחוּטָא וְעַד עַרְקַת מְסָנָא וְאִם אֶסַב מִכָּל דִי לָךְ וְלָא תֵימַר אֲנָא אַעְתָּרִית יָת אַבְרָם:
@361 לְחוֹד (בַּר) מִדִאֲכָלוּ עוּלֵמַיָא וְחָלָק גֻבְרַיָא דִי אֲזָלוּ עִמִי עָנֵר אֶשְׁכּוֹל וּמַמְרֵא אִינוּן יְקַבְּלוּן חַלָקְהוֹן:
@362 בָּתַר פִּתְגָמַיָא הָאִלֵין הֲוָה פִּתְגָמָא דַיְיָ עִם אַבְרָם בִּנְבוּאָה לְמֵימָר לָא תִדְחַל אַבְרָם מֵימְרִי תְּקוֹף לָךְ אַגְרָךְ סַגִי לַחֲדָא:
@363 וַאֲמַר אַבְרָם יְיָ אֱלֹהִים מַה תִּתֶּן לִי וַאֲנָא אָזֵיל בְּלָא וְלָד וּבַר פַּרְנָסָא הָדֵין דִבְּבֵיתִי הוּא דַמַשְׂקָאָה אֱלִיעֶזֶר:
@364 וַאֲמַר אַבְרָם הָא לִי לָא יְהַבְתְּ וְלָד וְהָא בַר בֵיתִי יָרִיתּ יָתִי:
@365 וְהָא פִּתְגָמָא דַיְיָ עִמֵהּ לְמֵימַר לָא יִרְתִינָךְ דֵין אֱלָהֵין בַּר דְתוֹלִיד הוּא יִרְתִינָךְ:
@366 וְאַפֵּיק יָתֵהּ לְבָרָא וַאֲמַר אִסְתְּכִי כְעַן לִשְׁמַיָא וּמְנֵי כּוֹכְבַיָא אִם תִּכּוֹל לְמִמְנֵי יָתְהוֹן וַאֲמַר לֵיהּ כְּדֵין יְהוֹן בְּנָךְ:
@367 וְהֵימִין בְּמֵימְרָא דַיְיָ וְחָשְׁבַהּ לֵיהּ לְזָכוּ:
@368 וַאֲמַר לֵהּ אֲנָא יְיָ דְאַפֵּקְתָּךְ מֵאוּרָא דְכַשְׂדָאֵי לְמִתַּן לָךְ יָת אַרְעָא הָדָא לְמֵירְתַהּ:
@369 וַאֲמָר יְיָ אֱלֹהִים בְּמָה אִידַע אֲרֵי אֵרְתִנַהּ:
@370 וַאֲמַר לֵהּ קָרֵב קֳדָמַי עֶגְלִין תְּלָתָא וְעִזִין תְּלָתָא וְדִכְרִין תְּלָת וְשַׁפְנִינָא וּבַר יוֹנָה:
@371 וְקָרֵב קֳדָמוֹהִי יָת כָּל אִלֵין וּפַלִיג יָתְהוֹן בְּשָׁוֶה וִיהַב פַּלְגַיָא פִּלוּג לָקֳבֵיל חַבְרֵיהּ וְיָת עוֹפָא לָא פַּלִיג:
@372 וּנְחַת עוֹפָא עַל פַּגְלַיָא וְאַפְרַח יָתְהוֹן אַבְרָם:
@373 וַהֲוָה שִׁמְשָׁא לְמֵיעַל וְשִׁינְתָא נְפָלַת עַל אַבְרָם וְהָא אֵימָתָא קְבֵל סַגִי נְפָלַת עֲלוֹהִי:
@374 וַאֲמַר לְאַבְרָם מִדַע תִּדַע אֲרֵי דַיָרִין יְהוֹן בְּנָיךְ בְּאַרְעָא דְלָא דִילְהוֹן וְיִפְלְחוּן בְּהוֹן וִיעַנוּן יָתְהוֹן אַרְבַּע מְאָה שְׁנִין:
@375 וְאַף יָת עַמָא דְיִפְלְחוּן בְּהוֹן דָיִין אֲנָא וּבָתַר כֵּן יִפְקוּן בְּקִנְיָנָא סַגִי:
@376 וְאַתְּ תֵעוֹל לְוָת אַבָהָתָךְ בִּשְׁלָם תִּתְקְבַר בְּסֵיבוּ טָבָא:
@377 וְדָרָא רְבִיעָאָה יְתוּבוּן הָכָא אֲרֵי לָא שְׁלִים חוֹבָא דֶאֱמוֹרָאָה עַד כְּעָן:
@378 וַהֲוָה שִׁמְשָׁא עַלַת וְקִבְלָא הֲוָה וְהָא תַּנוּר דִתְנַן וּבָעוּר דְאֶשָׁתָא דִעֲדָא בֵּין פַּלְגַיָא הָאִלֵין:
@379 בְּיוֹמָא הַהוּא גְזַר יְיָ עִם אַבְרָם קְיָם לְמֵימָר לִבְנָךְ יְהָבִית יָת אַרְעָא הָדָא מִן נַהֲרָא דְמִצְרַיִם וְעַד נַהֲרָא רַבָּא נַהֲרָא פְרָת:
@380 יָת שַׁלְמָאֵי וְיָת קְנִזָאֵי וְיָת קַדְמוֹנָאֵי:
@381 וְיָת חִתָּאֵי וְיָת פְּרִזָאֵי וְיָת גִבָּרָאֵי:
@382 וְיָת אֱמוֹרָאֵי וְיָת כְנַעֲנָאֵי וְיָת גִרְגָשָׁאֵי וְיָת יְבוּסָאֵי:
@383 וְשָׂרַי אִתַּת אַבְרָם לָא יְלִידַת לֵהּ וְלַהּ אַמְתָא מִצְרֵיתָא וּשְׁמַהּ הָגָר:
@384 וַאֲמַרַת שָׂרַי לְאַבְרָם הָא כְעַן מַנְעֲנִי יְיָ מִלְמֵילַד עוּל כְּעַן לְוַת אַמְתִי מָאִים אִתְבְּנֵי מִנַהּ וְקַבִּיל אַבְרָם לְמֵימַר שָׂרָי:
@385 וּדְבָרַת שָׂרַי אִתַּת אַבְרָם יָת הָגָר מִצְרֵיתָא אַמְתַהּ מִסוֹף עֲשַׂר שְׁנִין לְמִיתַּב אַבְרָם בְּאַרְעָא דִכְנָעַן וִיהָבַת יָתַהּ לְאַבְרָם בַּעֲלַהּ לֵהּ לְאִנְתּוּ:
@386 וְעַל לְוַת הָגָר וְעַדִיאַת וַחֲזַת אֲרֵי עֲדִיאַת וּקְלַת רִבָּנְתַּהּ בְּעֵינָהַהּ:
@387 וַאֲמַרַת שָׂרַי לְאַבְרָם דִין לִי עֲלָךְ אֲנָא יְהָבִית אַמְתִי לָךְ וַחֲזַת אֲרֵי עֲדִיאַת וּקְלֵית בְּעֵינָהַהּ יְדִין יְיָ בֵּינִי וּבֵינָךְ:
@388 וַאֲמַר אַבְרָם לְשָׂרַי הָא אַמְתִיךְ בִּידִךְ עִבִידִי לַהּ כִּדְתַקִין בְעֵינָיְכִי וְעֲנִיתַהּ שָׂרַי וְעָרְקַת מִקֳדָמָהַהּ:
@389 וְאַשְׁכְּחַהּ מַלְאָכָא דַיְיָ עַל עֵינָא דְמַיָא בְּמַדְבְּרָא עַל עֵינָא בְּאָרְחָא דְחַגְרָא:
@390 וַאֲמַר הָגָר אַמְתָא דְשָׂרַי מְנָן אַתְּ אָתְיָא וּלְאָן אַתְּ אָזְלָא וַאֲמַרַת מִן קֳדָם שָׂרַי רִבָּנְתִּי אֲנָא עֲרָקָא (עֲרָקַת):
@391 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ תּוּבִי לְוַת רִבּוֹנְתִּיךְ וְאִשְׁתַּעְבְּדִי תְּחוֹת יְדָהָא:
@392 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ אַסְגָאָה אַסְגֵי יָת בְּנָיְכִי וְלָא יִתִּמְנוּן מִסְגֵי:
@393 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ הָא אַתְּ מְעַדְיָא וְתֵלְדִין בַּר וְתִקְרִין שְׁמֵהּ יִשְׁמָעֵאל אֲרֵי קַבִּיל יְיָ צְלוֹתִיךְ:
@394 וְהוּא יְהֵא מָרוֹד בֶּאֱנָשָׁא הוּא יְהֵא צְרִיךְ לְכֹלָא וְאַף כָּל בְנֵי אֲנָשָׁא יְהוֹן צְרִיכִין לֵהּ וְעַל אַפֵּי כָל אֲחוֹהִי יִשְׁרֵי:
@395 וְצַלִיאַת בִּשְׁמָא דַיְיָ דְמִתְמַלֵל עִמַהּ אֲמַרַת אַתְּ הוּא אֱלָהָא דְחָזֵי כֹלָא אֲרֵי אֲמַרַת הַבְרַם הָכָא (נ''א הַאַף אֲנָא) שָּׁרֵיתִי חַזְיָא בָּתַר דְאִתְגְלִי לִי:
@396 עַל כֵּן קְרָא לִבְאֵרָא בְּאֵרָא דְמַלְאַךְ קַיָימָא אִתַּחֲזִי עֲלַהּ הָא הִיא בֵּין רְקָם וּבֵין חַגְרָא:
@397 וִילִידַת הָגָר לְאַבְרָם בָּר וקְרָא אַבְרָם שׁוּם בְּרֵיהּ דִילִידַת הָגָר יִשְׁמָעֵאל:
@398 וְאַבְרָם בַּר תְּמָנָן וְשִׁית שְׁנִין כַּד יְלִידַת הָגָר יָת יִשְׁמָעֵאל לְאַבְרָם:
@399 וַהֲוָה אַבְרָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין וְאִתְגְלִי יְיָ לְאַבְרָם וַאֲמַר לֵיהּ אֲנָא אֵל שַׁדַי פְּלַח קֳדָמַי וֶהֱוֵי שְׁלִים:
@400 וְאֶתֵּן קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וְאַסְגֵי יָתָךְ לַחֲדָא לַחֲדָא:
@401 וּנְפַל אַבְרָם עַל אַפּוֹהִי וּמַלֵיל עִמֵהּ יְיָ לְמֵימָר:
@402 אֲנָא הָא (גְזַר) קְיָמִי עִמָךְ וּתְהֵי לְאַב סַגִי עַמְמִין:
@403 וְלָא יִתְקְרֵי עוֹד יָת שְׁמָּךְ אַבְרָם וִיהֵי שְׁמָךְ אַבְרָהָם אֲרֵי אַב סַגִי עַמְמִין יְהָבִתָךְ:
@404 וְאַפִּישׁ יָתָךְ לַחֲדָא לַחֲדָא וְאֶתְּנִנָךְ לְכִנְשִׁין וּמַלְכִין דְשַׁלִיטִין בְּעַמְמַיָא מִנָךְ יִפְקוּן:
@405 וַאַקֵים יָת קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וּבֵין בְּנָךְ בַּתְרָךְ לְדָרֵיהוֹן לִקְיָם עָלָם לְמֵהֲוֵי לָךְ לֵאלָהָא וְלִבְנָיךְ בַּתְרָךְ:
@406 וְאֶתֵּן לָךְ וְלִבְנָיךְ בַּתְרָךְ יָת אַרְעָא תּוֹתָבוּתָךְ יָת כָּל אַרְעָא דִכְנַעַן לְאַחֲסָנַת עָלָם וְאֱהֶוֵי לְהוֹן לֵאלָהָא:
@407 וַאֲמַר יְיָ לְאַבְרָהָם וְאַתְּ יָת קְיָמִי תִטָר אַתְּ וּבְנָךְ בַּתְרָךְ לְדָרֵיהוֹן:
@408 דָא קְיָמִי דִי תִטְרוּן בֵּין מֵימְרִי וּבֵינֵיכוֹן וּבֵין בְּנָיךְ בַּתְרָךְ מִגְזַר לְכוֹן כָּל דְכוּרָא:
@409 וְתִגְזְרוּן יָת בִּשְׂרָא דְעָרְלָתְכוֹן וּתְהֵי (נ''י וּתְהֵא) לְאָת קְיָם בֵּין מֵימְרִי וּבֵינֵיכוֹן:
@410 וּבַר תְּמַנְיָא יוֹמִין יִתְגְזַר (יִגְזַר) לְכוֹן כָּל דְכוּרָא לְדָרָתֵיכוֹן יְלִידֵי בֵּיתָא וּזְבִינֵי כַּסְפָּא מִכֹּל בַּר עַמְמִין דְלָא מִבְּנָךְ הוּא:
@411 אִתְגַזָרָא יִתְגַזְרוּן (נ''י מִגְזַר יִגְזַר) יְלִיד בֵּיתָךְ וּזְבִין כַּסְפָּךְ וּתְהֵי קְיָמִי בְּבִשְׂרֵיכוֹן לִקְיָם עָלָם:
@412 וְעָרֵל דְכוּרָא דִי לָא יִגְזַר יָת בְּשַׂר עָרְלָתֵהּ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמֵּיהּ יָת קְיָמִי אַשְׁנִי:
@413 וַאֲמַר יְיָ לְאַבְרָהָם שָׂרַי אִתְּתָךְ לָא תִקְרֵי יָת שְׁמַהּ שָׂרָי אֲרֵי שָׂרָה שְׁמַהּ:
@414 וֶאֱבָרֵךְ יָתַהּ וְאַף אֶתֵּן מִנַהּ לָךְ בָּר וֶאֱבָרֲכִנַהּ וּתְהֵי לְכִנְשִׁין מַלְכִין דְשַׁלִּיטִין בְעַמְמַיָּא מִנַהּ יְהוֹן:
@415 וּנְפַל אַבְרָהָם עַל אַפּוֹהִי וַחֲדִי וַאֲמַר בְּלִבֵּהּ הַלְּבַר מְאָה שְׁנִין יְהֵי וְלַד וְאִם שָׂרָה הֲבַת תִּשְׁעִין שְׁנִין תְּלִיד:
@416 וַאֲמַר אַבְרָהָם קֳדָם יְיָ לְוַי יִשְׁמָעֵאל יִתְקַיָּם קֳדָמָךְ:
@417 וַאֲמַר יְיָ בְּקוּשְׁטָא שָׂרָה אִתְּתָךְ תְּלִיד לָךְ בָּר וְתִקְרֵי יָת שְׁמֵהּ יִצְחָק וַאֲקִים יָת קְיָמִי עִמֵּהּ לִקְיָם עָלָם לִבְנוֹהִי בַּתְרוֹהִי:
@418 וְעַל יִשְׁמָעֵאל קַבֵּלִית צְלוֹתָךְ הָא בָּרֵכִית יָתֵהּ וְאַפֵּישּׁ יָתֵהּ וְאַסְגֵּי יָתֵהּ לַחֲדָא לַחֲדָא תְּרֵין עֲשַׂר רַבְרְבַיָּא יְלִיד וְאֶתְּנִנֵּיהּ לְעַם סַגִּי:
@419 וְיָת קְיָמִי אָקִים עִם יִצְחָק דִי תְלִיד לָךְ שָׂרָה לְזִמְנָא הָדֵין בְּשַׁתָּא אָחֳרַנְתָּא:
@420 וְשֵׁיצֵי לְמַלָּלָא עִמֵהּ וְאִסְתַּלַּק יְקָרָא דַיְיָ מֵעִלָּווֹהִי דְּאַבְרָהָם:
@421 וּדְבַר אַבְרָהָם יָת יִשְׁמָעֵאל בְּרֵהּ וְיָת כָּל יְלִידֵי בֵיתֵהּ וְיָת כָּל זְבִינֵי כַסְפֵּה כָּל דְּכוּרָא בַּאֲנָשֵׁי בֵּית אַבְרָהָם וּגְזַר יָת בִּשְׂרָא דְעָרְלָתְהוֹן בִּכְרַן יוֹמָא הָדֵין כְּמָא דִי מַלֵיל עִמֵּהּ יְיָ:
@422 וְאַבְרָהָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין כַּד גְזַר בִּשְׂרָא דְעָרְלְתֵהּ:
@423 וְיִשְׁמָעֵאל בְּרֵהּ בַּר תְּלַת עַשְׂרֵי שְׁנִין כַּד גְּזַר יַת בִּשְׂרָא דְעָרְלְתֵהּ:
@424 בִּכְרַן יוֹמָא הָדֵין (גְּזַר) אִתְגְּזַר אַבְרָהָם וְיִשְׁמָעֵאל בְּרֵהּ:
@425 וְכָל אֱנָשֵׁי בֵיתֵהּ יְלִידֵי בֵיתָא וּזְבִינֵי כַסְפָּא מִן בַּר עַמְמִין אִתְגְּזָרוּ (גְזָרוּ) עִמֵּהּ: פפפ:
@426 וְאִתְגְּלִי לֵהּ יְיָ בְּמֵישְׁרֵי מַמְרֵא וְהוּא יָתֵב בִּתְרַע מַשְׁכְּנָא כְּמֵיחַם יוֹמָא:
@427 וּזְקַף עֵינוֹהִי וַחֲזָא וְהָא תְּלָתָא גֻּבְרִין (נ''י גַּבְרִין) קָיְמִין עִלָּווֹהִי וַחֲזָא וּרְהַט לְקַדָּמוּתְהוֹן מִתְּרַע מַשְׁכְּנָא וּסְגִיד עַל אַרְעָא:
@428 וַאֲמָר יְיָ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ (נ''י בְּעֵינָיךְ) לָא כְעַן תְּעִבַּר מֵעַל עַבְדָּךְ:
@429 יִסְּבוּן כְּעַן זְעֵיר מַיָּא וְאַסְחוּ רַגְלֵיכוֹן וְאִסְתְּמִיכוּ תְּחוֹת אִילָנָא:
@430 וְאֶסַּב פִּתָּא דְלַחְמָא וּסְעִידוּ לִבְּכוֹן בָּתַר כֵּן תְּעִבְּרוּן אֲרֵי עַל כֵּן עֲבַרְתּוּן עַל עַבְדְּכוֹן וַאֲמָרוּ כֵּן תַּעְבֵּיד כְּמָא דִּי מַלֵּלְתָּא:
@431 וְאוֹחִי אַבְרָהָם לְמַשְׁכְּנָא לְוַת שָׂרָה וַאֲמַר אוֹחָא תְּלָת סְאִין קִמְחָא דְּסָלְתָּא לוּשִׁי וְעִבִידִי גְּרִיצָן:
@432 וּלְוַת תּוֹרֵי רְהַט אַבְרָהָם וּדְבַר בַּר תּוֹרֵי רַכִּיךְ וְטַב וִיהַב לְעוּלֵמָא וְאוֹחִי לְמֶעְבַּד יָתֵהּ:
@433 וּנְסִיב שְׁמַן וַחֲלָב וּבַר תּוֹרֵי דִּי עֲבַד וִיהַב קֳדָמֵיהוֹן וְהוּא מְשַׁמֵּשׁ עִלָּוֵיהוֹן תְּחוֹת אִילָנָא וַאֲכָלוּ:
@434 וַאֲמָרוּ לֵהּ אָן שָׂרָה אִתְּתָךְ וַאֲמַר הָא בְמַשְׁכְּנָא:
@435 וַאֲמַר מִתַּב אִתּוּב לְוָתָךְ כְּעִדָּן דְּאַתּוּן קַיָּמִין וְהָא בַר לְשָׂרָה אִתְּתָךְ וְשָׂרָה שְמַעַת בִּתְרַע מַשְׁכְנָא וְהוּא אֲחוֹרוֹהִי:
@436 וְאַבְרָהָם וְשָׂרָה סִיבוּ עַלּוּ בְיוֹמִין פְּטַק מִלְּמֶהֱוֵי לְשָׂרָה אוֹרַח כִּנְשַׁיָּא:
@437 וְחַיְכַת שָׂרָה בִּטְעָהַהּ לְמֵימָר בָּתַר דְּסֵיבִית הֲוַת לִי עוּלֵימוּ וְרִבּוֹנִי םִיב:
@438 וַאֲמַר יְיָ לְאַבְרָהָם לְמָּא דְנָן חַיְכַת שָׂרָה לְמֵימַר הַבְרַם בְּקוּשְׁטָא אוֹלִיד וַאֲנָא סֵיבִית:
@439 הַיִתְכַּסֵּי מִן קֳדָם יְיָ פִּתְגָּמָא לִזְמַן אִתּוּב לְוָתָךְ כְּעִדָּן דְּאַתּוּן קַיָּמִין וּלְשָׂרָה בָר:
@440 וְכַדִּיבַת שָׂרָה לְמֵימָר לָא חַיֵּכִית אֲרֵי דְחֵלַת וַאֲמַר לָא בְּרַם חַיָּכְתְּ:
@441 וְקָמוּ מִתַּמָּן גֻּבְרַיָּא וְאִסְתְּכִיאוּ עַל אַפֵּי סְדוֹם וְאַבְרָהָם אָזַל עִמְּהוֹן לְאַלְווֹאֵיהוֹן:
@442 וַיְיָ אֲמָר הַמְכַסֵּי אֲנָא מֵאַבְרָהָם דִּי אֲנָא עָבֵד:
@443 וְאַבְרָהָם מֵהֲוָה יֶהֱוֵי לְעַם סַגִּי וְתַקִּיף וְיִתְבָּרְכוּן בְּדִילֵהּ כֹּל עַמְמֵי אַרְעָא:
@444 אֲרֵי גְּלִי קֳדָמַי (גי' רמב''ן יְדַעְתִּנֵּהּ) בְּדִיל דִּי יְפַקֵּד יָת בְּנוֹהִי וְיָת אֱנַשׁ בֵּיתֵהּ בַּתְרוֹהִי וְיִטְּרוּן אָרְחָן דְּתַקְּנָן קֳדָם יְיָ לְמֶעֱבַּד צְדַקְתָּא וְדִינָא בְּדִיל אַיְיתִי יְיָ עַל אַבְרָהָם יָת דְּמַלֵּל עֲלוֹהִי:
@445 וַאֲמַר יְיָ קְבֵלַת סְדוֹם וַעֲמוֹרָה אֲרֵי סְגִיאַת וְחוֹבָתְהוֹן אֲרֵי תְקִיפַת לַחֲדָא:
@446 אִתְגְּלֵי כְעַן וְאֶדּוּן הֲכִי קְבִלְתְּהוֹן דְּעַלַּת לָקֳדָמַי עֲבָדוּ אֶעְבֵּד עִמְּהוֹן גְּמִירָא אִם לָא תָיְבִין וְאִם תָּיְבִין לָא אֶתְפְּרָע:
@447 וְאִתְפְּנִיאוּ מִתַּמָּן גֻּבְרַיָּא וַאֲזָלוּ לִסְדוֹם וְאַבְרָהָם עַד כְּעַן מְשַׁמֵּשׁ בִּצְלוֹ קֳדָם יְיָ:
@448 וּקְרֵב אַבְרָהָם וַאֲמָר הֲבִרְגַז תְּשֵׁיצֵי זַכָּאָה עִם חַיָּבָא:
@449 מָאִים אִית חַמְּשִׁין זַכָּאִין בְּגוֹ קַרְתָּא הֲבִרְגַז תְּשֵׁיצֵי וְלָא תִשְׁבּוֹק לְאַתְרָא בְּדִיל חַמְשִׁין זַכָּאִין דִּי בְגַוָּהּ:
@450 קוּשְׁטָא אִנּוּן דִּינָךְ מִלְּמֶעְבַּד כְּפִתְגָּמָא הָדֵין לְקַטָּלָא זַכָּאָה עִם חַיָּבָא וִיהֵי זַכָּאָה כְּחַיָּבָא קוּשְׁטָא אִנּוּן דִּינָךְ דְּדָיִן כָּל אַרְעָא לָא יַעְבֵד דִּינָא:
@451 וַאֲמַר יְיָ אִם אַשְׁכַּח בִּסְדוֹם חַמְשִׁין זַכָּאִין בְּגוֹ קַרְתָּא וְאֶשְׁבּוֹק לְכָל אַתְרָא בְּדִילְהוֹן:
@452 וַאֲתֵב אַבְרָהָם וַאֲמַר הָא כְעַן שָׁרֵיתִי לְמַלָּלָא קֳדָם יְיָ וַאֲנָא עָפָר וּקְטָם:
@453 מָאִים יַחְסְרוּן חַמְשִׁין זַכָּאִין חַמְשָׁא הַתְחַבֵּל בְּחַמְשָׁא יָת כָּל קַרְתָּא וַאֲמַר לָא אֲחַבֵּל אִם אַשְׁכַּח תַּמָּן אַרְבְּעִין וְחַמְשָׁא:
@454 וְאוֹסִף עוֹד לְמַלָּלָא קֳדָמוֹהִי וַאֲמַר מָאִים יִשְׁתַּכְחוּן תַּמָּן אַרְבְּעִין וַאֲמַר לָא אֶעְבְּד גְּמֵרָא בְּדִיל אַרְבְּעִין:
@455 וַאֲמַר לָא כְעַן יִתְקֵף קֳדָם יְיָ (נ''י רוּגְזָא דַּיְיָ) וַאֲמַלֵּל מָאִים יִשְׁתַּכְּחוּן תַּמָּן תְּלָתִין וַאֲמַר לָא אֶעְבֵּד גְּמֵרָא אִם אַשְׁכַּח תַּמָּן תְּלָתִין:
@456 וַאֲמַר הָא כְעַן שָׁרֵיתִי לְמַלָּלָא קֳדָם יְיָ מָאִים יִשְׁתַּכְּחוּן תַּמָּן עֶשְרִין וַאֲמַר לָא אֲחַבֵּל בְּדִיל עֶשְׁרִין:
@457 וַאֲמַר לָא כְעַן יִתְקֵף קֳדָם יְיָ (נ''י רוּגְזָא דַּיְיָ) וֶאֱמַלֵּל בְּרַם זִמְנָא הָדָא מָאִים יִשְׁתַּכְּחוּן תַּמָּן עַשְׂרָא וַאֲמַר לָא אֲחַבֵּל בְּדִיל עַשְׂרָא:
@458 וְאִסְתַּלַּק יְקָרָא דַּיְיָ כַּד שֵׁצִי לְמַלָּלָא עִם אַבְרָהָם וְאַבְרָהָם תָּב לְאַתְרֵהּ:
@459 וְעַלּוּ תְּרֵין מַלְאָכַיָּא לִסְדוֹם בְּרַמְשָׁא וְלוֹט יָתֵב בְּתַרְעָא (נ''י בִּתְרַע) דִּסְדוֹם וַחֲזָא לוֹט וְקָם לְקַדָּמוּתְהוֹן וּסְגִיד עַל אַפּוֹהִי עַל אַרְעָא:
@460 וַאֲמַר בְּבָעוּ כְעַן רִבּוֹנַי זוּרוּ כְעַן לְבֵית עַבְדְּכוֹן וּבִיתוּ וְאַסְחוּ רַגְלֵיכוֹן וּתְקַדְּמוּן וּתְהָכוּן לְאָרְחֲכוֹן וְאֲמָרוּ לָא אֶלָּהֵן בִּרְחוֹבָא נְבִית:
@461 וְאַתְקַף בְּהוֹן לַחֲדָא וְזָרוּ לְוָתֵהּ וְעַלּוּ לְבֵיתֵהּ וַעֲבַד לְהוֹן מִשְׁתְּיָא וּפַטִּיר אֲפָא לְהוֹן וְאֲכָלוּ:
@462 עַד לָא שְׁכִיבוּ וְאֲנָשֵׁי קַרְתָּא אֲנָשֵׁי סְדוֹם אַקִּיפוּ עַל בֵּיתָא מֵעוּלֵימָא וְעַד סָבָא כָּל עַמָּא מִסּוֹפֵהּ:
@463 וּקְרוֹ לְלוֹט וַאֲמָרוּ לֵהּ אָן גֻּבְרַיָא דִּי אֲתוֹ לְוָתָךְ לֵילְיָא אַפֵּקִנּוּן לְוָתָנָא וְנִדַּע יָתְהוֹן:
@464 וּנְפַק לְוָתְהוֹן לוֹט לְתַרְעָא וְדָשָׁא אֲחַד בַּתְרוֹהִי:
@465 וַאֲמַר בְּבָעוּ כְעַן אַחַי לָא תַבְאִישוּן:
@466 הָא כְעַן לִי תַּרְתֵּין בְּנָן דִּי לָא יְדָעִנּוּן גְּבַר אַפֵּק כְּעַן יַתְהוֹן לְוָתְכוֹן וְעִיבִידוּ לְהֵן כִּדְתַקֵּן בְּעֵינֵיכוֹן לְחוֹד לְגֻבְרַיָּא הָאִלֵּין לָא תַעְבְּדוּן מִדַּעַם אֲרֵי עַל כֵּן עַלּוּ בִּטְלַל שֵׁרוּתִי:
@467 וַאֲמָרוּ קְרֵב לְהַלָּא וַאֲמָרוּ חַד אֲתָא לְאִתּוֹתָבָא והָא דָיִין דִּינָא כְּעַן נַבְאֵשׁ לָךְ מִדִּילְהוֹן וּתְקִיפוּ בְגַבְרָא בְלוֹט לַחֲדָא וּקְרִיבוּ לְמִתְּבַר דָּשָׁא:
@468 וְאוֹשִׁיטוּ גֻּבְרַיָּא יָת יְדֵיהוֹן וְאַיְתִיאוּ יָת לוֹט לְוָתְהוֹן לְבֵיתָא וְיָת דָּשָׁא אֲחָדוּ:
@469 וְיָת גֻּבְרַיָּא דִּי בִתְרַע בֵּיתָא מְחוֹ בְּשַׁבְרִירַיָּא מִזְּעֵירָא וְעַד רַבָּא וּלְאִיוּ לְאַשְׁכָּחָא תַרְעָא:
@470 וַאֲמָרוּ גֻּבְרַיָּא לְלוֹט עוֹד מָן לָךְ הָכָא חַתְנָא וּבְנָךְ וּבְנָתָךְ וְכֹל דִּי לָךְ בְּקַרְתָּא אַפֵּיק מִן אַתְרָא:
@471 אֲרֵי מְחַבְּלִין אֲנַחְנָא יָת אַתְרָא הָדֵין אֲרֵי סְגִיאַת קְבִלְתְּהוֹן קֳדָם יְיָ וְשַׁלְּחָנָא יְיָ לְחַבָּלוּתַהּ:
@472 וּנְפַק לוֹט וּמַלֵּיל עִם חַתְנוֹהִי נָסְבֵי בְנָתֵהּ וְאֲמַר קוּמוּ פּוּקוּ מִן אַתְרָא הָדֵין אֲרֵי מְחַבֵּל יְיָ יָת קַרְתָּא וַהֲוָה כִּמְחָיִךְ בְּעֵינֵי חַתְנוֹהִי:
@473 וּכְמִסַּק צַפְרָא הֲוָה וּדְחִיקוּ מַלְאָכַיָּא בְּלוֹט לְמֵימָר קוּם דְּבַר יָת אִתְּתָךְ וְיָת תַּרְתֵּין בְּנָתָךְ דְּאִשְׁתְּכַחַן מְהֵימְנָא עִמָּךְ דִּילְמָא תִלְקֵי בְּחוֹבֵי קַרְתָּא:
@474 וְאִתְעַכַּב וְאַתְקִיפוּ גֻּבְרַיָּא בִּידֵהּ וּבִידָא דְּאִתְּתֵהּ וּבִידָא דְתַּרְתֵּין בְּנָתֵהּ כִּרְחַם (נ''י כַּד חָס) יְיָ עֲלוֹהִי וְאַפְּקוּהִי וְאַשְׁרוּהי מִבָּרָא לְקַרְתָּא:
@475 וַהֲוָה כַּד אַפִּיקוּ יָתְהוֹן לְבָרָא וַאֲמַר חוּס עַל נַפְשָׁךְ לָא תִּסְתְּכִי לַאֲחוֹרָךְ וְלָא תְקוּם בְּכָל מֵישְׁרָא לְטוּרָא אִשְׁתְּזֵב דִּלְמָא תִלְקֵי:
@476 וַאֲמַר לוֹט לְהוֹן בְּבָעוּ כְעַן רִבּוֹנָי (נ''י יְיָ):
@477 הָא כְעַן אַשְׁכַּח עַבְדָךְ רַחֲמִין קֳדָמָךְ וְאַסְגֵּיתָא טֵיבוּתָךְ דִּי עֲבַדְתָּ עִמִּי לְקַיָּמָא יָת נַפְשִׁי וַאֲנָא לֵית אֲנָא יָכִיל לְאִשְׁתֵּזָבָא לְטּוּרָא דִּילְמָא תְעַרְעִנַּנִי בִשְׁתָּא וְאֵימוּת:
@478 הָא כְעַן קַרְתָּא הָדָא קְרִיבָא לְמֵעִירוֹק לְתַמָּן וְהִיא זְעֵירָא אִשְׁתְּזֵב כְּעַן תַּמָּן הֲלָא זְעֵירָא הִיא וְתִתְקַיַּם נַפְשִׁי:
@479 וַאֲמַר לֵהּ הָא נְסֵיבִית אַפָּךְ אַף לְפִתְגָּמָא הָדֵין בְּדִיל דְּלָא לְמֵהְפַּךְ יָת קַרְתָּא דִּבְעִיתָא עֲלַהּ:
@480 אוֹחִי לְאִשְׁתֵּזֵב תַּמָּן אֲרֵי לָא אִכּוּל לְמֶעְבַּד פִּתְגָּמָא עַד מֵיתָךְ לְתַמָּן עַל כֵּן קְרָא שְׁמָא דְּקַרְתָּא צוֹעַר:
@481 שִׁמְשָׁא נְפַק עַל אַרְעָא וְלוֹט עַל לְצוֹעַר:
@482 וַיְיָ אַמְטַר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרֵיתָא וְאֶשָּׁתָא מִן קֳדָם יְיָ מִן שְׁמַיָּא:
@483 וַהֲפַךְ יָת קִרְוַיָּא הָאִלֵּין וְיָת כָּל מֵישְׁרָא וְיָת כָּל יָתְבֵי קִרְוַיָּא וְצִמְחָא דְּאַרְעָא:
@484 וְאִסְתְּכִיאַת אִתְּתֵהּ מִבַּתְרוֹהִי וַהֲוַת קָמָא דְּמִלְחָא:
@485 וְאַקְדֵּים אַבְרָהָם בְּצַפְרָא לְאַתְרָא דִּשַׁמֵשׁ תַּמָּן בִּצְלוֹ קֳדָם יְיָ:
@486 וְאִסְתְּכִי עַל אַפֵּי סְדוֹם וַעֲמוֹרָה וְעַל כָּל אַפֵּי אַרְעָא דְּמֵישְׁרָא וַחֲזָא וְהָא סְלִיק תְּנָנָא דְּאַרְעָא כִּתְנָנָא דְּאַתּוּנָא:
@487 וַהֲוָה בְּחַבָּלוּת (נ''י כַּד חֲבַל) יְיָ יָת קִרְוֵי מֵישְׁרָא וּדְכִיר יְיָ יָת אַבְרָהָם וְשַׁלַּח יָת לוֹט מִגּוֹ הֲפֶכְתָּא כַּד הֲפַךְ יָת קִרְוַיָּא דִּי הֲוָה יָתֵב בְּהֵן לוֹט:
@488 וּסְלֵק לוֹט מִצּוֹעַר וִיתֵב בְּטוּרָא וְתַרְתֵּין בְּנָתֵהּ עִמֵּהּ אֲרֵי דָּחִיל לְמִתַּב בְּצוֹעַר וִיתֵב בִּמְעַרְתָּא הוּא וְתַרְתֵּין בְּנָתֵהּ:
@489 וַאֲמֶרֶת רַבְּתָא לִזְעֶרְתָּא אֲבוּנָא סִיב וּגְבַר לֵית בְּאַרְעָא לְמֵיעַל עֲלָנָא כְּאוֹרַח כָּל אַרְעָא:
@490 אִיתָא נַשְׁקֵי יָת אֲבוּנָא חַמְרָא וְנִשְׁכּוּב עִמֵּהּ וּנְקַיֵּם מֵאֲבוּנָא בְּנִין:
@491 וְאַשְׁקִיאָה יָת אֲבוּהֶן חַמְרָא בְּלֵילְיָא הוּא וְעַלַּת רַבְּתָא וּשְׁכִיבָא עִם אֲבוּהָא וְלָא יְדַע בְּמִשְׁכְּבַהּ וּבְקִימַהּ:
@492 וַהֲוָה בְּיוֹמָא דְבַתְרוֹהִי וַאֲמֶרֶת רַבְּתָא לִזְעֶרְתָּא הָא שְׁכֵיבִית רַמְשָׁא עִם אַבָּא נַשְׁקִנֵּהּ חַמְרָא אַף בְּלֵילְיָא וְעוּלִי שְׁכִיבִי עִמֵּהּ וּנְקַיֵּם מֵאֲבוּנָא בְּנִין:
@493 וְאַשְׁקִיאָה אַף בְּלֵילְיָא הַהוּא יָת אֲבוּהֶן חַמְרָא וְקָמַת זְעֶרְתָּא וּשְׁכִיבַת עִמֵּהּ וְלָא יְדַע בְּמִשְׁכְּבַהּ וּבְקִימַהּ:
@494 וְעַדִּיאַן תַּרְתֵּין בְּנַת לוֹט מֵאֲבוּהֶן:
@495 וִילִידַת רַבְּתָא בַּר וּקְרַת שְׁמֵהּ מוֹאָב הוּא אֲבוּהוֹן דְמוֹאָבָא עַד יוֹמָא דֵין:
@496 וּזְעֶרְתָּא אַף הִיא יְלִידַת בַּר וּקְרַת שְׁמֵהּ בַּר עַמִּי הוּא אֲבוּהוֹן דִּבְנֵי עַמּוֹן עַד יוֹמָא דֵין:
@497 וּנְטַל מִתַּמָּן אַבְרָהָם לְאַרְעָא דָּרוֹמָא וִיתֵב בֵּין רְקָם וּבֵין חַגְרָא וְאִתּוֹתַב בִּגְרָר:
@498 וַאֲמַר אַבְרָהָם עַל שָׂרָה אִתְּתֵהּ אֲחָתִי הִיא וּשְׁלַח אֲבִימֶלֶךְ מַלְכָּא דִּגְרָר וּדְבַר יָת שָׂרָה:
@499 וַאֲתָא מֵימַר מִן קָדָם יְיָ לְוַת אֲבִימֶלֶךְ בְּחֶלְמָא דְלֵילְיָא וַאֲמַר לֵהּ הָא אַתְּ מִית עַל עֵיסַק אִתְּתָא דִּדְבַרְתָּא וְהִיא אִתַּת גְּבָר:
@500 וַאֲבִימֶלֶךְ לָא קְרֵב לְוָתַהּ וַאֲמַר יְיָ הָעָם אַף זַכַּאי תִּקְטוֹל:
@501 הֲלָא הוּא אֲמַר לִי אֲחָתִי הִיא וְהִיא אַף הִיא אֲמָרַת אָחִי הוּא בְּקַשִּׁיטוּת לִבִּי וּבְזַכָּאוּת יָדַי עֲבָדִית דָּא:
@502 וַאֲמַר לֵהּ מֵימַר מִן קֳדָם יְיָ בְּחֶלְמָא אַף קֳדָמַי גְּלִי אֲרֵי בְּקַשִּׁיטוּת לִבָּךְ עֲבַדְתָּ דָּא וּמְנָעִית אַף אֲנָא יָתָךְ מִלְּמֶחְטֵי קֳדָמָי עַל כֵּן לָא שְׁבָקְתָּךְ לְמִקְרַב לְוָתַהּ:
@503 וּכְעַן אֲתֵיב אִתַּת גַּבְרָא אֲרֵי נְבִיָּא הוּא וִיצַלֵּי עֲלָךְ וּתְחֵי וְאִם לֵיתָךְ מֵתֵיב דַּע אֲרֵי מֵימַת תְּמוּת אַתְּ וְכָל דִּי לָךְ:
@504 וְאַקְדֵּים אֲבִימֶלֶךְ בְּצַפְרָא וּקְרָא לְכָל עַבְדּוֹהִי וּמַלִּיל יַת כָּל פִּתְגָּמַיָּא הָאִלֵּין קֳדָמֵיהוֹן וּדְחִילוּ גּוּבְרַיָּא לַחֲדָא:
@505 וּקְרָא אֲבִימֶלֶךְ לְאַבְרָהָם וַאֲמַר לֵהּ מָה עֲבַדְתָּ לָנָא וּמָה חָבִית (נ''י חָטֵית) לָךְ אֲרֵי אַיְתֵיתָא עֲלַי וְעַל מַלְכוּתִי חוֹבָא רַבָּא עוֹבָדִין דִּי לָא כָשְׁרִין לְאִתְעֲבָדָא עֲבַדְתָּ עִמִּי:
@506 וַאֲמַר אֲבִימֶלֶךְ לְאַבְרָהָם מָה חָזֵיתָ אֲרֵי עֲבַדְתָּ יָת פִתְגָּמָא הָדֵין:
@507 וַאֲמַר אַבְרָהָם אֲרֵי אֲמָרִית לְחוֹד לֵית דַּחַלְתָּא דַּיְיָ בְּאַתְרָא הָדֵין וְיִקְטְלֻנַּנִי עַל עֵיסַק אִתְּתִי:
@508 וּבְרַם בְּקוּשְׁטָא אֲחָתִי בַּת אַבָּא הִיא בְּרַם לָא בַת אִמִּי וַהֲוַת לִי לְאִנְתּוּ:
@509 וַהֲוָה כַּד טָעוּ עַמְמַיָּא בָּתַר עוֹבָדֵי יְדֵיהוֹן יָתִי קָרִיב יְיָ לְדַחַלְתֵּהּ מִבֵּית אַבָּא וַאֲמָרִית לַהּ דֵּין (נ''י דָּא) טֵיבוּתִיךְ דִּי תַעְבְּדִי עִמִּי לְכָל אַתְרָא דִּי נְהַךְ לְתַמָּן אֱמָרִי עֲלַי אָחִי הוּא:
@510 וּדְבַר אֲבִימֶלֶךְ עָאן וְתוֹרִין וְעַבְדִין וְאַמְהָן וִיהַב לְאַבְרָהָם וַאֲתֵיב לֵהּ יָת שָׂרָה אִתְּתֵהּ:
@511 וַאֲמַר אֲבִימֶלֶךְ הָא אַרְעִי קֳדָמָךְ בִּדְתַקִּין בְּעֵינָיךְ תִּיב:
@512 וּלְשָׂרָה אֲמַר הָא יְהָבִית אֶלֶף סַלְעִין דִּכְסַף לְאָחִיךְ הָא הוּא לִיךְ כְּסוּת דִּיקָר עַיְנִין חֳלַף דִּשְׁלָחִית וּדְּבַרְתִּיךְ וַחֲזֵית יָתִיךְ וְיָת כָּל דְּעִמָּךְ וְעַל כָּל מָה דַּאֲמָרַת אִתּוֹכָחַת:
@513 וְצַלִּי אַבְרָהָם קֳדָם יְיָ וְאַסִּי יְיָ יָת אֲבִימֶלֶךְ וְיָת אִתְּתֵהּ וְאַמְהָתֵהּ וְאִתְרְוָחוּ:
@514 אֲרֵי מֵיחַד אֲחַד יְיָ בְּאַפֵּי כָל פָּתַח וַלְדָא לְבֵית אֲבִימֶלֶךְ עַל עֵיסַק שָׂרָה אִתַּת אַבְרָהָם:
@515 וַיְיָ דְּכִיר יָת שָׂרָה כְּמָא דִּי אֲמַר וַעֲבַד יְיָ לְשָׂרָה כְּמָא דִּי מַלִּיל:
@516 וְעַדִּיאַת וִילִידַת שָׂרָה לְאַבְרָהָם בַּר לְסִיבְתוֹהִי לִזְמַן דִּי מַלִּיל יָתֵהּ יְיָ:
@517 וּקְרָא אַבְרָהָם יָת שׁוּם בְּרֵהּ דְאִתְיְלִיד לֵהּ דִּילִידַת לֵהּ שָׂרָה יִצְחָק:
@518 וּגְזַר אַבְרָהָם יָת יִצְחָק בְּרֵהּ בַּר תְּמַנְיָא יוֹמִין כְּמָא דִּי פַקִּיד יָתֵהּ יְיָ:
@519 וְאַבְרָהָם בַּר מְאָה שְׁנִין כַּד אִתְיְלִיד לֵהּ יָת יִצְחָק בְּרֵהּ:
@520 וַאֲמֶרֶת שָׂרָה חֶדְוָא עֲבַד לִי יְיָ כָּל דִּשְׁמַע יֶחֱדֵּי לִי:
@521 וַאֲמֶרֶת מָאן מְהֵימָן דַּאֲמַר לְאַבְרָהָם קַיָּם דְּתוֹנִיק בְּנִין שָׂרָה אֲרֵי יְלֵידִית בַּר לְסִיבְתוֹהִי:
@522 וּרְבָא רַבְיָא וְאִתְחֲסִיל וַעֲבַד אַבְרָהָם מִשְׁתְּיָא רַבָּא בְּיוֹמָא דְּאִתְחֲסִיל יָת יִצְחָק:
@523 וַחֲזַת שָׂרָה יָת בַּר הָגָר מִצְרֵיתָא דִּילִידַת לְאַבְרָהָם מְחָיִיךְ:
@524 וַאֲמֶרֶת לְאַבְרָהָם תָּרֵךְ אַמְתָא הָדָא וְיָת בְּרַהּ אֲרֵי לָא יֵרַת בַּר אַמְתָא הָדָא עִם בְּרִי עִם יִצְחָק:
@525 וּבְאֵישׁ פִּתְגָּמָא לַחֲדָא בְּעֵינֵי אַבְרָהָם עַל עֵיסַק בְּרֵהּ:
@526 וַאֲמַר יְיָ לְאַבְרָהָם לָא יַבְאֵשׁ בְּעֵינָיךְ עַל עוּלֵימָא וְעַל אַמְתָךְ כֹּל דִּי תֵימַר לָךְ שָׂרָה קַבֵּל מִנַּהּ אֲרֵי בְיִצְחָק יִתְקְרוּן לָךְ בְּנִין:
@527 וְאַף יָת בַּר אַמְתָא לְעַם אֲשַׁוִּנֵּהּ אֲרֵי בְנָךְ הוּא:
@528 וְאַקְדֵּים אַבְרָהָם בְּצַפְרָא וּנְסִיב לַחֲמָא וְרָקְבָּא דְמַיָּא וִיהַב לְהָּגָר שַׁוֵי עַל כַּתְפַּהּ וְיָת רַבְיָא וְשַׁלְחַהּ וַאֲזָלַת וְתָעַת בְּמַדְבְּרָא (נ''א בְּמַדְבֵּר) בְּאֵר שָׁבַע:
@529 וּשְׁלִימוּ מַיָּא מִן רָקְבָּא וּרְמַת יָת רַבְיָא תְּחוֹת חַד מִן אִילָנַיָּא:
@530 וַאֲזָלַת וִיתִיבַת לַהּ מִקֳּבֵל אַרְחֵיקַת (נ''י אַרְחִיק) כְּמֵיגַד קַשְׁתָּא אֲרֵי אֲמֶרֶת לָא אֶחֱזֵי בְּמוֹתָא דְרַבְיָא וִיתִיבַת מִקֳּבֵל וַאֲרֵימַת יָת קָלַהּ וּבְכָת:
@531 וּשְׁמִיעַ קֳדָם יְיָ יָת קָלֵהּ דְּרַבְיָא וּקְרָא מַלְאֲכָא דַּיְיָ לְהָגָר מִן שְׁמַיָּא וַאֲמַר לַהּ מָה לָיךְ הָגָר לָא תִדְחֲלִי אֲרֵי שְׁמִיעַ קֳדָם יְיָ יָת קָלֵהּ דְּרַבְיָא בַּאֲתַר דְּהוּא תַמָּן:
@532 קוּמִי טוּלִי יָת רַבְיָא וְאַתְקִיפִי יָת יְדֵךְ בֵּהּ אֲרֵי לְעַם סַגִּי אֲשַׁוִּנֵּהּ:
@533 וּגְלָא יְיָ יָת עֵינָהַהּ וַחֲזַת בֵּירָא דְמַיָּא וַאֲזָלַת וּמְלַת יָת רָקְבָּא מַיָּא וְאַשְׁקִיאַת יָת רַבְיָא:
@534 וַהֲוָה מֵימְרָא דַּיְיָ בְּסַעְדֵהּ דְּרַבְיָא וּרְבָא וִיתֵב בְּמַדְבְּרָא וַהֲוָה רָבֵי קַשְׁתָּא:
@535 וִיתֵב בְּמַדְבְּרָא דְפָארָן וּנְסִיבַת לֵהּ אִמֵּהּ אִתְּתָא מֵאַרְעָא דְמִצְרָיִם:
@536 וַהֲוָה בְּעִדָּנָא הַהִיא וַאֲמַר אֲבִימֶלֶךְ וּפִיכֹל רַב חֵילֵהּ לְאַבְרָהָם לְמֵימָר מֵימְרָא דַּיְיָ בְּסַעְדָּךְ בְּכֹל דִּי אַתְּ עָבֵד:
@537 וּכְעַן קַיֵּם לִי בְּמֵימְרָא דַּיְיָ הָכָא דְּלָא תְשַׁקַּר בִּי וּבִבְרִי וּבְבַר בְּרִי כְּטִיבוֹתָא דִּי עֲבָדִית עִמָּךְ תַּעְבֵּד עִמִּי וְעִם אַרְעָא דְאִתּוֹתַבְתָּא בַהּ:
@538 וַאֲמַר אַבְרָהָם אֲנָא אֲקַיֵּם:
@539 וְאוֹכַח אַבְרָהָם יָת אֲבִימֶלֶךְ עַל עֵיסַק בֵּירָא דְמַיָּא דִּי אֲנִּיסוּ עַבְדֵי אֲבִימֶלֶךְ:
@540 וַאֲמַר אֲבִימֶלֶךְ לָא יְדָעִית מָאן עֲבַד יָת פִּתְגָּמָא הָדֵין וְאַף אַתְּ לָא חַוֵּיתָ לִּי וְאַף אֲנָא לָא שְׁמָעִית אֱלָּהֵין יוֹמָא דֵין:
@541 וּדְבַר אַבְרָהָם עָאן וְתוֹרִין וִיהַב לַאֲבִימֶלֶךְ וּגְזָרוּ תַרְוֵיהוֹן קְיָם:
@542 וַאֲקִים אַבְרָהָם יָת שְׁבַע חוּרְפַן דְּעָאן בִּלְחוֹדֵיהֶן:
@543 וַאֲמַר אֲבִימֶלֶךְ לְאַבְרָהָם מָה אִנּוּן שְׁבַע חוּרְפַן אִלֵּין דַּאֲקֵמְתָּא בִּלְחוֹדֵיהֶן:
@544 וַאֲמַר אֲרֵי יָת שְׁבַע חוּרְפַן תְּקַבֵּל מִן יְדִי בְּדִיל דִּתְהֵי לִי לְסַהֲדוּ אֲרֵי חֲפָרִית יָת בֵּירָא הָדָא:
@545 עַל כֵּן קְרָא לְאַתְרָא הַהוּא בְּאֵר שָׁבַע אֲרֵי תַמָּן קַיָּמוּ תַּרְוֵיהוֹן:
@546 וּגְזָרוּ קְיָם בִּבְאֵר שָׁבַע וְקָם אֲבִימֶלֶךְ וּפִיכֹל רַב חֵילֵהּ וְתָבוּ לְאַרַע פְּלִשְׁתָּאֵי:
@547 וּנְצִיב נִצְבָּא (נ''י אִילָנָא) בִּבְאֵר שָׁבַע וְצַלִּי תַמָּן בִּשְׁמָא דַּיְיָ אֱלָהָא דְעַלְמָא:
@548 וְאִתּוֹתָב אַבְרָהָם בְּאַרַע פְּלִשְׁתָּאֵי יוֹמִין סַגִּיאִין:
@549 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וַיְיָ נַסִּי יָת אַבְרָהָם וַאֲמַר לֵהּ אַבְרָהָם וַאֲמַר הָא אֲנָא:
@550 וַאֲמַר דְּבַר כְּעַן יָת בְּרָךְ יָת יְחִידָךְ דִּי רְחַמְתָּ יָת יִצְחָק וְאִיזֵל לָךְ לְאַרְעָא פּוּלְחָנָא וְאַסְקֵהּ קֳדָמַי תַּמָּן לַעֲלָתָא עַל חַד מִן טוּרַיָּא דִּי אֵימַר לָךְ:
@551 וְאַקְדֵּים אַבְרָהָם בְּצַפְרָא וְזָרֵז יָת חֲמָרֵהּ וּדְבַר יָת תְּרֵין עוּלֵימוֹהִי עִמֵּהּ וְיָת יִצְחָק בְּרֵהּ וְצַלַּח אָעֵי לַעֲלָתָא וְקָם וַאֲזַל לְאַתְרָא דִּי אֲמַר לֵהּ יְיָ:
@552 בְּיוֹמָא תְלִיתָאָה וּזְקַף אַבְרָהָם יָת עֵינוֹהִי וַחֲזָא יָת אַתְרָא מֵרָחִיק:
@553 וַאֲמַר אַבְרָהָם לְעוּלֵימוֹהִי אוֹרִיכוּ לְכוֹן הָכָא עִם חֲמָרָא וַאֲנָא וְעוּלֵימָא נִתְמְטֵי עַד כָּא וְנִסְגּוּד וּנְתוּב לְוַתְכוֹן:
@554 וּנְסֵיב אַבְרָהָם יָת אָעֵי דַּעֲלָתָא וְשַׁוִּי עַל יִצְחָק בְּרֵהּ וּנְסֵיב בִּידֵהּ יָת אֶשָּׁתָא וְיָת סַכִּינָא וַאֲזָלוּ תַרְוֵיהוֹן כַּחֲדָא:
@555 וַאֲמַר יִצְחָק לְאַבְרָהָם אֲבוּהִי וַאֲמַר אַבָּא וַאֲמַר הָא אֲנָא בְרִי וַאֲמַר הָא אֶשָּׁתָא וְאָעַיָּא וְאָן אִימְרָא לַעֲלָתָא:
@556 וַאֲמַר אַבְרָהָם קֳדָם יְיָ גְּלֵי לֵהּ אִימְרָא לַעֲלָתָא בְּרִי וַאֲזָלוּ תַרְוֵיהוֹן כַּחֲדָא:
@557 וְאָתוּ לְאַתְרָא דִּי אֲמַר לֵהּ יְיָ וּבְנָא תַמָּן אַבְרָהָם יָת מַדְבְּחָא וְסַדַּר יָת אָעַיָּא וַעֲקַד יָת יִצְחָק בְּרֵהּ וְשַׁוֵּי יָתֵהּ עַל מַדְבְּחָא עֵיל מִן אָעַיָּא:
@558 וְאוֹשִׁיט אַבְרָהָם יָת יְדֵהּ וּנְסֵיב יָת סַכִּינָא לְמֵיכַס יַת בְּרֵהּ:
@559 וּקְרָא לֵהּ מַלְאָכָא דַּיְיָ מִן שְׁמַיָּא וַאֲמַר אַבְרָהָם אַבְרָהָם וַאֲמַר הָא אֲנָא:
@560 וַאֲמַר לָא תוֹשִׁיט יְדָךְ לְעוּלֵימָא וְלָא תַעְבֵּד לֵהּ מִדָּעָם אֲרֵי כְּעַן יְדַעְנָא (נ''י יְדָעִית) אֲרֵי דַּחֲלָא דַּיְיָ אַתְּ וְלָא מְנַעְתָּ יָת בְּרָךְ יָת יְחִידָךְ מִנִּי:
@561 וּזְקַף אַבְרָהָם יָת עֵינוֹהִי בָּתַר אִלֵּין וַחֲזָא וְהָא דִּכְרָא בָּתַר אֲחִיד בְּאִילָנָא בְּקַרְנוֹהִי וַאֲזַל אַבְרָהָם וּנְסֵיב יָת דִּכְרָא וְאַסְקֵהּ לַעֲלָתָא חֲלַף בְּרֵהּ:
@562 וּפְלַח וְצַלִּי אַבְרָהָם תַּמָּן בְּאַתְרָא הַהוּא וַאֲמַר קֳדָם יְיָ הָכָא יְהוֹן פַּלְחַן דָּרַיָּא בְּכֵן יִתְאֲמַר בְּיוֹמָא הָדֵין בְּטוּרָא הָדֵין אַבְרָהָם קֳדָם יְיָ פְּלָח:
@563 וּקְרָא מַלְאָכָא דַּיְיָ לְאַבְרָהָם תִּנְיָנוּת מִן שְׁמַיָּא:
@564 וַאֲמַר בְּמֵימְרִי קַיֵּמִית אֲמַר יְיָ אֲרֵי חֲלַף דִּי עֲבַדְתָּא יָת פִּתְגָּמָא הָדֵין וְלָא מְנַעְתָּא יָת בְּרָךְ יָת יְחִידָךְ:
@565 אֲרֵי בָרָכָא אֲבָרְכִנָּךְ וְאַסְגָּאָה אַסְגֵּי יָת בְּנָיךְ כְּכוֹכְבֵי שְׁמַיָּא וּכְחָלָא דִּי עַל כֵּיף יַמָּא וְיִרְתוּן בְּנָיךְ יָת קִרְוֵי סַנְאֵיהוֹן:
@566 וְיִתְבָּרְכוּן בְּדִיל בְּנָיךְ כֹּל עַמְמַיָּא דְאַרְעָא חֲלַף דִּי קַבֵּלְתָּא לְמֵימְרִי:
@567 וְתַב אַבְרָהָם לְוָת עוּלֵימוֹהִי וְקָמוּ וַאֲזָלוּ כַחֲדָא לִבְאֵר שָׁבַע וִיתֵיב אַבְרָהָם בִּבְאֵר שָׁבַע:
@568 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וְאִתְחֲוָא לְאַבְרָהָם לְמֵימָר הָא יְלֵידַת מִלְכָּה אַף הִיא בְּנִין לְנָחוֹר אָחוּךְ:
@569 יָת עוּץ בּוּכְרֵהּ וְיָת בּוּז אָחוּהִי וְיָת קְמוּאֵל אֲבוּהִי דַּאֲרָם:
@570 וְיָת כֶּשֶׂד וְיָת חֲזוֹ וְיָת פִּלְדָּשׁ וְיָת יִדְלָף ויָת בְּתוּאֵל:
@571 וּבְתוּאֵל:אוֹלִיד יָת רִבְקָה תְּמַנְיָא אִלֵּין יְלֵידַת מִלְכָּה לְנָחוֹר אֲחוּהִי דְאַבְרָהָם:
@572 וּלְחֵנָתֵהּ וּשְׁמַהּ רְאוּמָה וִילֵידַת אַף הִיא יָת טֶבַח וְיָת גַּחַם וְיָת תַּחַשׁ וְיָת מַעֲכָה: פפפ:
@573 וַהֲווֹ חַיֵּי שָׂרָה מְאָה וְעֶשְׂרִין וּשְׁבַע שְׁנִין שְׁנֵי חַיֵּי שָׂרָה:
@574 וּמִיתַת שָׂרָה בְּקִרְיַת אַרְבַּע הִיא חֶבְרוֹן בְּאַרְעָא דִּכְנָעַן וַאֲתָא אַבְרָהָם לְמִסְפְּדָה לְשָׂרָה וּלְמִבְכַּהּ:
@575 וְקָם אַבְרָהָם מֵעַל אַפֵּי מִיתֵהּ וּמַלֵּל עִם בְּנֵי חִתָּאָה לְמֵימָר:
@576 דַּיָּר וְתוֹתַב אֲנָא עִמְּכוֹן הָבוּ לִי אַחֲסָנַת קְבוּרָא עִמְּכוֹן וְאִקְבַּר מִיתִי מִן קֳדָמָי:
@577 וַאֲתִיבוּ בְנֵי חִתָּאָה יָת אַבְרָהָם לְמֵימָר לֵהּ:
@578 קַבֵּל מִנָּנָא רִבּוֹנָנָא רַב קֳדָם יְיָ אַתְּ בֵּינָנָא בִּשְׁפַר קִבְרָנָא קְבַר יָת מִיתָךְ אֱנַשׁ מִנָּנָא יָת קִבְרֵהּ לָא יִמְנַע מִנָּךְ מִלְמִקְבַּר מִיתָךְ:
@579 וְקָם אַבְרָהָם וּסְגִיד לְעַמָּא דְאַרְעָא לִבְנֵי חִתָּאָה:
@580 וּמַלֵּל עִמְּהוֹן לְמֵימָר אִם אִית רַעֲוָא בְנַפְשְׁכוֹן לְמִקְבַּר יָת מִיתִי מִן קֳדָמַי קַבִּילוּ מִנִּי וּבְעוּ לִי מִן עֶפְרוֹן בַּר צוֹחַר:
@581 וְיִתֶּן לִי יָת מְעָרַת כָּפֶלְתָּא דִּי לֵהּ דִּי בִּסְטַר חַקְלֵהּ בְּכַסְפָּא שְׁלִים יִתְּנִינַהּ לִי בֵּינֵיכוֹן לְאַחֲסָנַת קְבוּרָא:
@582 וְעֶפְרוֹן יָתֵב בְּגוֹ בְּנֵי חִתָּאָה וְאָתֵיב עֶפְרוֹן חִתָּאָה יָת אַבְרָהָם קֳדָם בְּנֵי חִתָּאָה לְכֹל עָלֵי תְּרַע קַרְתֵּהּ לְמֵימָר:
@583 לָא רִבּוֹנִי קַבֵּיל מִנִּי חַקְלָא יְהָבִית לָךְ וּמְעַרְתָּא דִּי בֵהּ לָךְ יְהָבִיתַהּ לְעֵינֵי בְנֵי עַמִּי יְהָבִיתַהּ לָךְ קְבַר מִיתָךְ:
@584 וּסְגִיד אַבְרָהָם קֳדָם עַמָּא דְאַרְעָא:
@585 וּמַלֵּיל עִם עֶפְרוֹן קֳדָם עַמָּא דְאַרְעָא לְמֵימָר בְּרַם אִם אַתְּ עָבֵד לִי טִיבוּ קַבֵּל מִנִּי אֶתֵּן כַּסְפָּא דְמֵי חַקְלָא סַב מִנִּי וְאֶקְבַּר יָת מִיתִי תַּמָּן:
@586 וְאָתֵיב עֶפְרוֹן יָת אַבְרָהָם לְמֵימָר לֵהּ:
@587 רִבּוֹנִי קַבֵּל מִנִּי אַרְעָא שַׁוְיָא אַרְבַּע מְאָה סִלְעִין דִּכְסַף בֵּינָא וּבֵינָךְ מַה הִיא וְיָת מִיתָךְ קְבַר:
@588 וְקַבֵּל אַבְרָהָם מִן עֶפְרוֹן וּתְקַל אַבְרָהָם לְעֶפְרוֹן יָת כַּסְפָּא דְּמַלֵּיל קֳדָם בְּנֵי חִתָּאָה אַרְבַּע מְאָה סִלְעִין דִּכְסַף מִתְקַבֵּל סְחוֹרָא (נ''י דְּמִתְקַבֵּל סְחוֹרָתָא) בְּכָל מְדִינְתָּא:
@589 וְקָם חֲקַל עֶפְרוֹן דִּי בְּכָפֶלְתָּא דִּי קֳדָם מַמְרֵא חַקְלָא וּמְעַרְתָּא דִּי בֵהּ וְכָל אִילָנֵי דִּי בְחַקְלָא דִּי בְכָל תְּחוּמֵהּ סְחוֹר סְחוֹר:
@590 לְאַבְרָהָם לִזְבִינוֹהִי לְעֵינֵי בְּנֵי חִתָּאָה בְּכֹל עָלֵי תְּרַע קַרְתֵּהּ:
@591 וּבָתַר כֵּן קְבַר אַבְרָהָם יָת שָׂרָה אִתְּתֵהּ בִּמְעָרַת חֲקַל כָּפֶלְתָּא עַל אַפֵּי מַמְרֵא הִיא חֶבְרוֹן בְּאַרְעָא דִּכְנָעַן:
@592 וְקָם חַקְלָא וּמְעַרְתָּא דִּי בֵהּ לְאַבְרָהָם לְאַחֲסָנַת קְבוּרָא מִן בְּנֵי חִתָּאָה:
@593 וְאַבְרָהָם סִיב עָל בְּיוֹמִין וַיְיָ בְּרִיךְ יָת אַבְרָהָם בְּכֹלָא:
@594 וַאֲמַר אַבְרָהָם לְעַבְדֵהּ סָבָא דְבֵיתֵהּ דְּשַׁלִּיט בְּכָל דִי לֵהּ שַׁוִּי כְעַן יְדָךְ תְּחוֹת יַרְכִּי:
@595 וַאֲקַיֵּם עֲלָךְ בְּמֵימְרָא דַּיְיָ אֱלָהָא דִּשְׁמַיָּא וֵאלָהָא דְאַרְעָא דְּלָא תִסַּב אִתְּתָא לִבְרִי מִבְּנַת כְּנַעֲנָאֵי דִּי אֲנָא יָתֵב בֵּינֵיהוֹן:
@596 אֱלָהֵין לְאַרְעִי וּלְיַלָּדוּתִי תֵּיזִיל וְתִסַּב אִתְּתָא לִבְרִי לְיִצְחָק:
@597 וַאֲמַר לֵהּ עַבְדָא מָאִים לָא תֵיבֵי אִתְּתָא לְמֵיתֵי בַתְרַי לְאַרְעָא הָדָא הַאֲתָבָא אָתֵיב יָת בְּרָךְ לְאַרְעָא דִּי נְפַקְתָּא מִתַּמָּן:
@598 וַאֲמַר לֵהּ אַבְרָהָם אִסְתַּמַּר לָךְ דִּילְמָא תָתֵיב יָת בְּרִי לְתַמָּן:
@599 יְיָ אֱלָהָא דִּשְׁמַיָּא דִּי דַּבְּרַנִי מִבֵּית אַבָּא וּמֵאֲרַע יַלְדוּתִי וְדִי מַלֵּל לִי וְדִי קַיֵּם לִי לְמֵימַר לִבְרָךְ אֶתֵּן יָת אַרְעָא הָדָא הוּא יִשְׁלַח מַלְאָכֵהּ קֳדָמָךְ וְתִסַּב אִתְּתָא לִבְרִי מִתַּמָּן:
@600 וְאִם לָא תֵיבֵי אִתְּתָא לְמֵיתֵי בַתְרָךְ וּתְהֵי זַכָּאָה מִמּוֹמָתִי דָּא לְחוֹד יָת בְּרִי לָא תָתֵב לְתַמָּן:
@601 וְשַׁוִּי עַבְדָא יָת יְדֵהּ תְּחוֹת יַרְכָא דְאַבְרָהָם רִבּוֹנֵהּ וְקַיֵּם לֵהּ עַל פִּתְגָּמָא הָדֵין:
@602 וּדְבַר עַבְדָא עַשְׂרָא גַּמְלִין מִגַּמְלֵי רִבּוֹנֵהּ וַאֲזַל וְכָל שְׁפַר רִבּוֹנֵהּ בִּידֵהּ וְקָם וַאֲזַל לַאֲרָם דִּי עַל פְּרַת לְקַרְתָּא דְנָחוֹר:
@603 וְאַשְׁרֵי גַּמְלַיָּא מִבָּרָא לְקַרְתָּא לִבְאֵרָא דְמַיָּא לְעִדַּן רַמְשָׁא לְעִדַּן דְּנַפְקַן מַלְיָתָא:
@604 וַאֲמַר יְיָ אֱלָהֵהּ דְּרִבּוֹנִי אַבְרָהָם זַמִּין כְּעַן קֳדָמַי יוֹמָא דֵּין וְעִבַד טִיבוּ עִם רִבּוֹנִי אַבְרָהָם:
@605 הָא אֲנָא קָאֵם עַל עֵינָא דְמַיָּא וּבְנַת אֱנָשֵׁי קַרְתָּא נַפְקַן לְמִמְלֵי מַיָּא:
@606 וּתְהֵי עוּלֶמְתָּא דְּאֵימַר לַהּ אַרְכִינִי כְעַן קוּלְתִיךְ וְאֶשְׁתִּי וְתֵימַר אֵשְׁתְּ וְאַף גַּמְלָךְ אַשְׁקֵי יָתַהּ זַמִּנְתָּא לְעבְדָּךְ לְיִצְחָק וּבַהּ אִידַע אֲרֵי עֲבַדְתָּ טִיבוּ עִם רִבּוֹנִי:
@607 וַהֲוָה הוּא עַד לָא שֵׁיצֵי לְמַלָּלָא וְהָא רִבְקָה נְפָקַת דְּאִתְיְלִידַת לִבְתוּאֵל בַּר מִלְכָּה אִתַּת נָחוֹר אֲחוּהִי דְאַבְרָהָם וְקוּלְתַהּ עַל כַּתְפַּהּ:
@608 וְעוּלֶמְתָּא שַׁפִּירַת חֵיזוּ (נ''י שַׁפִּירָא לְמֶחֱזֵי) לַחֲדָא בְּתֻלְתָּא וּגְבַר לָא יַדְעָהּ וּנְחָתַת לְעֵינָא וּמְלַת קוּלְתַהּ וּסְלֵקָת:
@609 וּרְהַט עַבְדָּא לִקְדָמוּתַהּ וַאֲמַר אַשְׁקִינִי (נ''י אַטְעֵמְנִי) כְעַן זְעֵיר מַיָּא מִקּוּלְתִיךְ:
@610 וַאֲמֶרֶת אֵשְׁתְּ רִבּוֹנִי וְאוֹחִיאַת וַאֲחֵיתַת קוּלְתַהּ עַל יְדַהּ וְאַשְׁקְתֵהּ:
@611 וְשֵׁיצִיאַת לְאַשְׁקָיוּתֵהּ וַאֲמֶרֶת אַף לְגַמְלָךְ אַמְלֵי עַד דִּי סַפְקוּן לְמִשְׁתֵּי:
@612 וְאוֹחִיאַת וּנְפָצַת קוּלְתַהּ לְבֵית שַׁקְיָא וּרְהָטַת עוֹד לְבֵירָא לְמִמְלֵי וּמְלַת לְכָל גַּמְלוֹהִי:
@613 וְגַבְרָא שָׁהֵי בַהּ מִסְתַּכֵּל שָׁתִיק לְמֵידַע הַאַצְלַח יְיָ אָרְחֵהּ אִם לָא:
@614 וַהֲוָה כַּד סַפִּיקוּ גַּמְלַיָּא לְמִשְׁתֵּי וּנְסֵיב גַּבְרָא קָדָשָׁא דְדַהֲבָא תִּקְלָא מַתְקְלֵהּ וּתְרֵין שֵׁירִין עַל יְדָהָא מַתְקַל עֲשַׂר סִלְעִין דְּדַהֲבָא מַתְקַלְהוֹן:
@615 וַאֲמַר בַּת מָן אַתְּ חַוִּי כְעַן לִי הַאִית בֵּית אָבוּךְ אָתַר כָּשַׁר לָנָא לִמְבָת:
@616 וַאֲמֶרֶת לֵהּ בַּת בְּתוּאֵל אֲנָא בַּר מִלְכָּה דִּילֵידַת לְנָחוֹר:
@617 וַאֲמֶרֶת לֵהּ אַף תִּבְנָא אַף כִּסָּתָא סַגִּי עִמָּנָא אַף אָתַר כָּשַׁר לִמְבָת:
@618 וּכְרַע גַּבְרָא וּסְגִיד קֳדָם יְיָ:
@619 וַאֲמַר בְּרִיךְ יְיָ אֱלָהָא דְרִבּוֹנִי אַבְרָהָם דִּי לָא מְנַע טִיבוּתֵהּ וְקוּשְׁטֵהּ מִן רִבּוֹנִי אֲנָא בְּאוֹרַח תַּקְנָא דַּבְּרַנִּי יְיָ בֵּית אֲחוֹהִי דְרִבּוֹנִי:
@620 וּרְהָטַת עוּלֶמְתָּא וְחַוִּיאַת לְבֵית אִמַּהּ כְּפִתְגָּמַיָּא הָאִלֵּין:
@621 וּלְרִבְקָה אָחָא וּשְׁמֵהּ לָבָן וּרְהַט לָבָן לְוַת גַּבְרָא לְבָרָא לְוַת עֵינָא:
@622 וַהֲוָה כַּד חָזָא יָת קָדָשָׁא וְיָת שֵׁירַיָּא עַל יְדֵי אֲחָתֵהּ וְכַד שְׁמַע יָת פִּתְגָּמֵי רִבְקָה אֲחָתֵהּ לְמֵימַר כְּדֵין מַלֵּיל עִמִּי גַּבְרָא וַאֲתָא לְוַת גַּבְרָא וְהָא קָאֵם עִלַּוֵּי גַּמְלַיָּא עַל עֵינָא:
@623 וַאֲמַר עוּל בְּרִיכָא דַּיְיָ לְמָא אַתְּ קָאֵם בְּבָרָא וַאֲנָא פַּנֵּיתִי בֵיתָא וַאֲתַר כָּשַׁר לְגַמְלַיָּא:
@624 וְעַל גַּבְרָא לְבֵיתָא וּשְׁרָא גַּמְלַיָּא וִיהַב תִּבְנָא וְכִסָּתָא לְגַמְלַיָּא וּמַיָּא לְאַסְחָאָה רַגְלוֹהִי וְרַגְלֵי גֻּבְרַיָּא דְּעִמֵּהּ:
@625 וְשַׁוִּיאוּ קֳדָמוֹהִי לְמֵיכָל וַאֲמַר לָא אֵיכוּל עַד דַּאֲמַלֵּל פִּתְגָּמָי וַאֲמַר מַלֵּיל:
@626 וַאֲמַר עַבְדָּא דְאַבְרָהָם אֲנָא:
@627 וַיְיָ בְּרִיךְ יָת רִבּוֹנִי לַחֲדָא וּרְבָא וִיהַב לֵהּ עָאן וְתוֹרִין וּכְסַף וּדְהַב וְעַבְדִּין וְאַמְהָן וְגַמְלִין וְחַמָרִין:
@628 וִילֵידַת שָׂרָה אִתַּת רִבּוֹנִי בַר לְרִבּוֹנִי בָּתַר דְּסֵיבָת וִיהַב לֵהּ יָת כָּל דִּילֵהּ:
@629 וְקַיֵּם עָלַי רִבּוֹנִי לְמֵימָר לָא תִסַבּ אִתְּתָא לִבְרִי מִבְּנַת כְּנַעֲנָאֵי דִי אֲנָא יָתֵב בְּאַרְעֵהּ:
@630 אֶלָהֵן לְבֵית אַבָּא תֵּזִיל וּלְזַרְעִיתִי וְתִסַּב אִתְּתָא לִבְרִי:
@631 וַאֲמָרִית לְרִבּוֹנִי מָאִים לָא תֵיתֵי אִתְּתָא בַּתְרָי:
@632 וַאֲמַר לִי יְיָ דִּי פְלָחִית קֳדָמוֹהִי יִשְׁלַח מַלְאָכֵהּ עִמָּךְ וְיַצְלַח אָרְחָךְ וְתִסַּב אִתְּתָא לִבְרִי מִזְּרְעִיתִי וּמִבֵּית אַבָּא:
@633 בְּכֵן תְּהֵי זַכַּי (נ''י זַכָּא) מִמּוּמָתִי אֲרֵי תְהַךְ לְזַרְעִיתִי וְאִם לָא יִתְּנוּן לָךְ וּתְהֵי זַכַּי מִמּוּמָתִי:
@634 וְאָתִית (נ''י וַאֲתֵיתִי) יוֹמָא דֵּין לְעֵינָא וַאֲמָרִית יְיָ אֱלָהָא דְּרִבּוֹנִי אַבְרָהָם אִם אִית כְּעַן רַעֲוָא קֳדָמָךְ לְאַצְלָחָא אָרְחִי דִּי אֲנָא אָזֵיל עֲלַהּ:
@635 הָא אֲנָא קָאֵם עַל עֵינָא דְמַיָּא וִיהֵי עוּלֶמְתָּא דְּתִפּוֹק לְמִמְלֵי וְאֵימַר לַהּ אַשְׁקִינִי כְעַן זְעֵיר מַיָּא מִקּוּלְתִיךְ:
@636 וְתֵימַר לִי אַף אַתְּ אֵשְׁתְּ וְאַף לְגַמְלָיךְ אַמְלִי הִיא אִתְּתָא דְּזַמִּין יְיָ לְבַר רִבּוֹנִי:
@637 אֲנָא עַד לָא שֵׁיצִיתִי לְמַלָּלָא בְלִבִּי וְהָא רִבְקָה נְפָקַת וְקוּלְתַהּ עַל כַּתְפַּהּ וּנְחָתַת לְעֵינָא וּמְלָת וַאֲמָרִית לַהּ אַשְׁקִינִי כְעָן:
@638 וְאוֹחִיאַת וַאֲחִיתַת קוּלְתַהּ מִנַּהּ וַאֲמֶרֶת אֵשְׁתְּ וְאַף גַּמְלָךְ אַשְׁקִי וּשְׁתֵיתִי וְאַף גַּמְלַיָּא אַשְׁקִיאַת:
@639 וּשְׁאֵילִית יָתַהּ וַאֲמָרִית בַּת מָן אַתְּ וַאֲמֶרֶת בַּת בְּתוּאֵל בַּר נָחוֹר דִּילֵידַת לֵהּ מִלְכָּה וְשַׁוֵּיתִי קָדָשָׁא עַל אַפַּהּ וְשִׁירַיָּא עַל יְדָהָא:
@640 וּכְרָעִית וּסְגָדִית קֳדָם יְיָ וּבָרֵכִית יָת יְיָ אֱלָהֵהּ דְּרִבּוֹנִי אַבְרָהָם דְּדַבְּרַנִּי בְּאוֹרַח קְשׁוֹט לְמִיסַב יָת בַּת אֲחוּהִי דְּרִבּוֹנִי לִבְרֵהּ:
@641 וּכְעַן אִם אִיתֵיכוֹן עָבְדִין טִיבוּ וּקְשׁוֹט עִם רִבּוֹנִי חַוּוֹ לִי וְאִם לָא חַוּוֹ לִי וְאִתְפְּנֵי עַל יַמִּינָא אוֹ עַל שְׂמָאלָא:
@642 וְאָתֵיב לָבָן וּבְתוּאֵל וַאֲמָרוּ מִן קֳדָם יְיָ נְפַק פִּתְגָּמָא לֵית אֲנַחְנָא יָכְלִין לְמַלָּלָא עִמָּךְ בִּישׁ אוֹ טָב:
@643 הָא רִבְקָה קֳדָמָךְ דְּבַר וְאֵיזִיל וּתְהֵי אִתְּתָא לְבַר רִבּוֹנָךְ כְּמָא דִּי מַלֵּל יְיָ:
@644 וַהֲוָה כַּד שְׁמַע עַבְדָּא דְאַבְרָהָם יָת פִּתְגָּמֵיהוֹן וּסְגֵד עַל אַרְעָא קֳדָם יְיָ:
@645 וְאַפֵּק עַבְדָּא מָנִין דִּכְסַף וּמָנִין דִּדְהַב וּלְבוּשִׁין וִיהַב לְרִבְקָה וּמִגְדָּנִין יְהַב לַאֲחוּהָא וּלְאִמַּהּ:
@646 וַאֲכָלוּ וּשְׁתִיאוּ הוּא וְגוּבְרַיָּא דִּי עִמֵּהּ וּבָתוּ וְקָמוּ בְצַפְרָא וַאֲמַר שַׁלְּחוּנִי לְוַת רִבּוֹנִי:
@647 וַאֲמַר אֲחוּהָ וְאִמַּהּ תָּתֵיב עוּלֶמְתָּא עִמָּנָא עִדַּן בְּעִדַּן אוֹ עַשְׂרָא יַרְחִין בָּתַר כֵּן תֵּיזִיל:
@648 וַאֲמַר לְהוֹן לָא תְאַחֲרוּן יָתִי וַיְיָ אַצְלַח אָרְחִי שַׁלְּחוּנִי וְאֵיהַךְ לְוַת רִבּוֹנִי:
@649 וַאֲמַרוּ נִקְרֵי לְעוּלֶמְתָּא וְנִשְׁמָע מַה דְּהִיא אָמְרָה:
@650 וּקְרוֹ לְרִבְקָה וַאֲמַרוּ לַהּ הֲתֵיזְלִי עִם גַּבְרָא הָדֵין וַאֲמֶרֶת אֵיזִיל:
@651 וְשַׁלָּחוּ יָת רִבְקָה אֲחַתְהוֹן וְיָת מֵנִקְתַּהּ וְיָת עַבְדָּא דְאַבְרָהָם וְיָת גַּבְרוֹהִי:
@652 וּבָרִיכוּ יָת רִבְקָה וַאֲמַרוּ לַהּ אֲחָתָנָא אַתְּ הֲוֵי לְאַלְפִין וּלְרִבְוָן וְיִרְתוּן בְּנַיְכִי יָת קִרְוֵי סַנְאֵיהוֹן:
@653 וְקָמַת רִבְקָה וְעוּלֶמְתָּהָא וּרְכִיבָא עַל גַּמְלַיָּא וְאָזְלָּא בָּתַר גַּבְרָא וּדְבַר עַבְדָּא יָת רִבְקָה וַאֲזָל:
@654 וְיִצְחָק אָתָא מִמֵּתוֹהִי (נ''י עַל בְּמֵיתוֹהִי) מִבֵּירָא דְמַלְאָךְ קַיָּמָא אִתְחֲזֵי עֲלַהּ וְהוּא יָתֵב בַּאֲרַע דָּרוֹמָא:
@655 וּנְפַק יִצְחָק לְצַלָּאָה בְחַקְלָא לְמִפְנֵי רַמְשָׁא וּזְקַף עֵינוֹהִי וַחֲזָא וְהָא גַּמְלַיָּא אָתָן:
@656 וּזְקָפַת רִבְקָה יָת עֵינָהָא וַחֲזַת יָת יִצְחָק וְאִתְרְכִינַת מֵעַל גַּמְלָא:
@657 וַאֲמֶרֶת לְעַבְדָּא מָן גַּבְרָא דֵיכִי דִּמְהַלֵּךְ בְּחַקְלָא לְקַדָּמוּתָנָא וַאֲמַר עַבְדָּא הוּא רִבּוֹנִי וּנְסֵיבַת עֵיפָא וְאִתְכַּסִּיאַת:
@658 וְאִשְׁתָּעֵי עַבְדָּא לְיִצְחָק יָת כָּל פִּתְגָּמַיָּא דִּי עֲבָד:
@659 וְאַעֲלַהּ יִצְחָק לְמַשְׁכְּנָא וַחֲזָא וְהָא תַקְּנִין עוֹבָדָהָא כְּעוֹבָדֵי שָׂרָה אִמֵּהּ וּנְסֵיב יָת רִבְקָה וַהֲוַת לֵהּ לְאִנְּתּוּ וּרְחִימַהּ וְאִתְנְחֵם יִצְחָק בָּתַר דְּמִיתַת אִמֵּהּ:
@660 וְאוֹסֵיף אַבְרָהָם וּנְסֵיב אִתְּתָא וּשְׁמַהּ קְטּוּרָה:
@661 וִילֵידַת לֵהּ יָת זִמְרָן וְיָת יָקְשָׁן וְיָת מְדָן וְיָת מִדְיָן וְיָת יִשְׁבָּק וְיָת שׁוּחַ:
@662 וְיָקְשָׁן אוֹלִיד יָת שְׁבָא וְיָת דְּדָן וּבְנֵי דְדָן הֲווֹ לְמַשִּׁירְיָן וְלִשְׁכוּנִין וּלְּנַגְוָן:
@663 וּבְנֵי מִדְיָן עֵיפָה וָעֵפֶר וַחֲנוֹךְ וַאֲבִידָע וְאֶלְדָּעָה כָּל אִלֵּין בְּנֵי קְטוּרָה:
@664 וִיהַב אַבְרָהָם יָת כָּל דִּילֵהּ לְיִצְחָק:
@665 וְלִבְנֵי לְחֵינָתָא דִּי לְאַבְרָהָם יְהַב אַבְרָהָם מַתְּנָן וְשַׁלְחִנּוּן מֵעַל יִצְחָק בְּרֵהּ בְּעוֹד דְּהוּא קַיָּם קִידוּמָא לַאֲרַע מַדִינְחָא:
@666 וְאִלֵּין יוֹמֵי שְׁנֵי חַיֵּי אַבְרָהָם דַּחֲיָא מְאָה וְשַׁבְעִין וְחָמֵשׁ שְׁנִין:
@667 וְאִתְנְגִיד וּמִית אַבְרָהָם בְּסִיבוּ טָבָא סִיב וּשְׂבַע יוֹמִין וְאִתְכְּנִישׁ לְעַמֵּהּ:
@668 וּקְבָרוּ יָתֵהּ יִצְחָק וְיִשְׁמָעֵאל בְּנוֹהִי בִּמְעָרַת כָּפֶלְתָּא בַּחֲקַל עֶפְרוֹן בַּר צֹחַר חִתָּאָה דִּי עַל אַפֵּי מַמְרֵא:
@669 חַקְלָא דִּי זְבַן אַבְרָהָם מִן בְּנֵי חִתָּאָה תַּמָּן אִתְקְבַר אַבְרָהָם וְשָׂרָה אִתְּתֵהּ:
@670 וַהֲוָה בָּתַר דְּמִית אַבְרָהָם וּבָרֵךְ יְיָ יָת יִצְחָק בְּרֵהּ וִיתֵב יִצְחָק עִם בֵּירָא דְמַלְאָךְ קַיָּמָא אִתְחֲזֵי עֲלַהּ:
@671 וְאִלֵּין תּוּלְדַת יִשְׁמָעֵאל בַּר אַבְרָהָם דִּי יְלֵידַת הָגָר מִצְרֵתָא אַמְתָא דְשָׂרָה לְאַבְרָהָם:
@672 וְאִלֵּין שְׁמָהַת בְּנֵי יִשְׁמָעֵאל בִּשְׁמָהַתְהוֹן לְתוּלְדַתְהוֹן בּוּכְרָא דְיִשְׁמָעֵאל נְבָיוֹת וְקֵדָר וְאַדְבְּאֵל וּמִבְשָׂם:
@673 וּמִשְׁמָע וְדוּמָה וּמַשָּׂא:
@674 חֲדַד וְתֵימָא יְטוּר נָפִישׁ וָקֵדְמָה:
@675 אִלֵּין אִנּוּן בְּנֵי יִשְׁמָעֵאל וְאִלֵּין שְׁמָהַתְהוֹן בְּפַצְחֵיהוֹן וּבִכְרַכֵּיהוֹן תְּרֵין עֲסַר רַבְרְבִין לְאֻמֵּיהוֹן:
@676 וְאִלֵּין שְׁנֵי חַיֵּי יִשְׁמָעֵאל מְאָה וּתְלָתִין וּשְׁבַע שְׁנִין וְאִתְנְגִיד וּמִית וְאִתְכְּנִישׁ לְעַמֵּהּ:
@677 וּשְׁרוֹ מֵחֲוִילָה עַד חַגְרָא דִּי עַל אַפֵּי מִצְרַיִם מָטֵי לְאָתוּר עַל אַפֵּי כָל אֲחוֹהִי שְׁרָא: פפפ:
@678 וְאִלֵּין תּוּלְדַת יִצְחָק בַּר אַבְרָהָם אַבְרָהָם אוֹלִיד יָת יִצְחָק:
@679 וַהֲוָה יִצְחָק בַּר אַרְבְּעִין שְׁנִין כַּד נְסֵיב יָת רִבְקָה בַּת בְּתוּאֵל אֲרַמָּאָה מִפַּדַּן אֲרָם אֲחָתֵהּ דְלָבָן אֲרַמָּאָה לֵהּ לְאִנְתּוּ:
@680 וְצַלִּי יִצְחָק קֳדָם יְיָ לָקֳבֵל אִתְּתֵהּ אֲרֵי עֲקָרָה הִיא וְקַבֵּל צְלוֹתֵהּ יְיָ וְעַדִּיאַת רִבְקָה אִתְּתֵהּ:
@681 וְדַחֲקִין בְּנַיָּא בִּמְעָהָא וַאֲמֶרֶת אִם כֵּן לְמָה דְּנַן אֲנָא וַאֲזָלַת לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ:
@682 וַאֲמַר יְיָ לַהּ תְּרֵין עַמְמִין בִּמְעַיְכִי וְתַרְתֵּין מַלְכְּוָן מִמֵעַיְכִי יִתְפָּרְשָׁן וּמַלְכוּ מִמַלְכוּ יִתְקַף וְרַבָּא יִשְׁתַּעֲבֵּיד לִזְעֵירָא:
@683 וּשְׁלִימוּ יוֹמָהָא לְמֵילָד וְהָא תְיוּמִין בִּמְעָהָא:
@684 וּנְפַק קַדְמָאָה סִמוֹק כֻּלֵּהּ כִּגְלִים (נ''י כִּכְלָן) דִּשְׂעָר וּקְרוֹ שְׁמֵהּ עֵשָׂו:
@685 וּבָתַר כֵּן נְפַק אֲחוּהִי וִידֵהּ אֲחִידָא בְּעִקְבָא דְעֵשָׂו וּקְרָא שְׁמֵהּ יַעֲקֹב וְיִצְחָק בַּר שִׁתִּין שְׁנִין כַּד יְלִידַת יָתְהוֹן:
@686 וּרְבִיוּ עוּלֵמַיָּא וַהֲוָה עֵשָׂו גְבַר נַחְשִׁירְכָן גְבַר נָפֵק לְחַקְלָא וְיַעֲקֹב גְבַר שְׁלִים מְשַׁמֵשׁ בֵּית אוּלְפָנָא:
@687 וּרְחֵם יִצְחָק יָת עֵשָׂו אֲרֵי מִצֵידֵהּ הֲוָה אָכִיל וְרִבְקָה רְחִימַת יָת יַעֲקֹב:
@688 וּבַשִּׁיל יַעֲקֹב תַּבְשִׁילָא וַאֲתָא (נ'''י וְעַל) עֵשָׂו מִן חַקְלָא וְהוּא מְשַׁלְהֵי:
@689 וַאֲמַר עֵשָׂו לְיַעֲקֹב אַטְעֵמְנִי כְעַן מִן סִמּוֹקָא סִמּוֹקָא הָדֵין אֲרֵי מְשַׁלְהֵי אֲנָא עַל כֵּן קְרָא שְׁמֵהּ אֱדוֹם:
@690 וַאֲמַר יַעֲקֹב זַבִּין כְּיוֹם דִּלְהֵן יָת בְּכֵרוּתָךְ לִי:
@691 וַאֲמַר עֵשָׂו הָא אֲנָא אָזֵל לִמְמָת וּלְמָה דְּנָן לִי בְּכֵרוּתָא:
@692 וַאֲמַר יַעֲקֹב קַיֵּם לִי כְּיוֹם דִּלְהֵן וְקַיִּים לֵהּ וְזַבִּין יָת בְּכֵרוּתֵהּ לְיַעֲקֹב:
@693 וְיַעֲקֹב יְהַב לְעֵשָׂו לְחֵם וְתַבְשִׁיל דִּטְלוֹפְחִין וַאֲכַל וּשְׁתִי וְקָם וַאֲזָל וְשָׁט עֵשָׂו יָת בְּכֵרוּתָא:
@694 וַהֲוָה כַפְנָא בְּאַרְעָא בַּר מִכַּפְנָא קַדְמָאָה דִּי הֲוָה בְּיוֹמֵי אַבְרָהָם וַאֲזַל יִצְחָק לְוַת אֲבִימֶלֶךְ מַלְכָּא דִּפְלִשְׁתָּאֵי לִגְרָר:
@695 וְאִתְגְּלִי לֵהּ יְיָ וַאֲמַר לָא תֵחוֹת לְמִצְרָיִם שְׁרֵי בְאַרְעָא דִּי אֵימַר לָךְ:
@696 דּוּר בְּאַרְעָא הָדָא וִיהֵי מֵימְרִי בְסַעְדָךְ וְאֵבָרְכִנָךְ אֲרֵי לָךְ וְלִבְנָיךְ אֶתֵּן יָת כָּל אַרְעָתָא הָאִלֵּין וְאָקֵם יָת קְיָמָא דִּי קַיֵּמִית לְאַבְרָהָם אֲבוּךְ:
@697 וְאַסְגֵּי יָת בְּנָיךְ סַגִּיאִין כְּכוֹכְבֵי שְׁמַיָּא וְאֶתֵּן לִבְנָיךְ יָת כָּל אַרְעָתָא הָאִלֵּין וְיִתְבָּרְכוּן בְּדִיל בְּנָךְ כֹּל עַמְמֵי אַרְעָא:
@698 חֳלַף דִּי קַבִּיל אַבְרָהָם בְּמֵימְרִי וּנְטַר מַטְּרַת מֵימְרִי פִּקּוֹדַי קְיָמַי וְאוֹרָיָתָי:
@699 וִיתֵב יִצְחָק בִּגְרָר:
@700 וּשְׁאִילוּ אֲנָשֵׁי אַתְרָא (עַל עֵיסַק אִתְּתֵהּ) לְאִתְּתֵהּ וַאֲמַר אֲחָתִי הִיא אֲרֵי דְחִיל לְמֵימַר אִתְּתִי דִּלְמָא יִקְטְּלֻנַּנִי אֲנָשֵׁי אַתְרָא עַל רִבְקָה אֲרֵי שַׁפִּירַת חֵיזוּ הִיא:
@701 וַהֲוָה כַּד סְגִיאוּ לֵהּ תַּמָּן יוֹמַיָּא וְאִסְתְּכִי אֲבִימֶלֶךְ מַלְכָּא דִּפְלִשְׁתָּאֵי מִן חֲרַכָּא וַחֲזָא וְהָא יִצְחָק מְחַיִּיךְ עִם רִבְקָה אִתְּתֵהּ:
@702 וּקְרָא אֲבִימֶלֶךְ לְיִצְחָק וַאֲמַר בְּרַם הָא אִתְּתָךְ הִיא וְאֶכְדֵּין אֲמַרְתָּ אֲחָתִי הִיא וַאֲמַר לֵהּ יִצְחָק אֲרֵי אֲמָרִית דִּלְמָא אֵימוּת עֲלַהּ:
@703 וַאֲמַר אֲבִימֶלֶךְ מָה דָא עֲבַדְתָּ לָנָא כִּזְעֵיר פּוֹן שָׁכִיב דִּמְיָחֵד בְּעַמָּא עִם אִתְּתָךְ וְאַיְתֵיתָא עֲלָנָא חוֹבָא:
@704 וּפַקִּיד אֲבִימֶלֶךְ יָת כָּל עַמָּא לְמֵימָר דְּיַנְזֵק לְגַבְרָא הָדֵין וּבְאִתְּתֵהּ אִתְקְטָלָא יִתְקְטֵּל:
@705 וּזְרַע יִצְחָק בְּאַרְעָא הַהִיא וְאַשְׁכַּח בְּשַׁתָּא הַהִיא עַל חַד מְאָה בִדְשַׁעֲרוֹהִי וּבָרְכֵהּ יְיָ:
@706 וּרְבָא גַּבְרָא וַאֲזַל אֲזִיל (נ''י סָגֵי) וְרָבֵי עַד דִּי רְבָא לַחֲדָא:
@707 וַהֲוָה לֵהּ גֵּיתֵי עָנָא וְגֵיתֵי תוֹרִין וּפָלְחָנָא (נ''י וַעֲבוּדָה) סַגְיָא וְקַנִּיאוּ בֵהּ פְּלִשְׁתָּאֵי:
@708 וְכָל בֵּירִין דִּי חֲפָרוּ עַבְדֵי אֲבוּהִי בְּיוֹמֵי אַבְרָהָם אֲבוּהִי טַמּוֹנוּן פְּלִשְׁתָּאֵי וּמְלוֹנוּן עַפְרָא:
@709 וַאֲמַר אֲבִימֶלֶךְ לְיִצְחָק אִזְּל מֵעִמָּנָא אֲרֵי תְקֵפְתָּא מִנָּנָא לַחֲדָא:
@710 וַאֲזַל מִתַּמָּן יִצְחָק וּשְׁרָא בְנַחֲלָא דִּגְרָר וִיתֵב תַּמָּן:
@711 וְתָב יִצְחָק וְחָפַר יָת בֵּירֵי דְמַיָּא דִּי חֲפָרוּ בְּיוֹמֵי אַבְרָהָם אֲבוּהִי וְטַּמּוֹנוּן פְּלִשְׁתָּאֵי בָּתַר דְּמִית אַבְרָהָם וּקְרָא לְהֵן שְׁמָהָן כִּשְׁמָהָן דִּי הֲוָה קָרֵי לְהֵן אֲבוּהִי:
@712 וַחֲפָרוּ עַבְדֵי יִצְחָק בְּנַחֲלָא וְאַשְׁכָּחוּ תַמָּן בֵּירָא דְּמַיִּין נָבְעִין:
@713 וּנְצוֹ רַעֲוָתָא דִּגְרָר עִם רַעֲוָתָא דְיִצְחָק לְמֵימַר דִּי לָנָא מַיָּא וּקְרָא שְׁמָא דְבֵירָא עִסְקָא אֲרֵי אִתְעַסִּיקוּ עִמֵּהּ:
@714 וַחֲפָרוּ בֵּירָא אָחֳרִי וּנְצוֹ אַף עֲלַהּ וּקְרָא שְׁמַהּ שִׂטְנָא:
@715 וְאִסְתַּלַּק מִתַּמָּן וַחֲפַר בֵּירָא אָחֳרִי וְלָא נְצוֹ עֲלַהּ וּקְרָא שְׁמַהּ רְחֹבוֹת וַאֲמַר אֲרֵי כְעַן אַפְתֵּי יְיָ לָנָא וְנִיפוּשׁ בְּאַרְעָא:
@716 וְאִסְתַּלַּק מִתַּמָּן לִבְּאֵר שָׁבַע:
@717 וְאִתְגְּלִי לֵהּ יְיָ בְּלֵילְיָא הַהוּא וַאֲמַר אֲנָא אֱלָהֵהּ דְּאַבְרָהָם אֲבוּךְ לָא תִדְחַל אֲרֵי בְסַעְדָּךְ מֵימְרִי וֶאֱבָרֵכִנָּךְ וְאַסְגֵּי יָת בְּנָיךְ בְּדִיל אַבְרָהָם עַבְדִּי:
@718 וּבְנָא תַמָּן מַדְבְּחָא וְצַלִּי בִּשְׁמָא דַּיְיָ וּפְרַס תַּמָּן מַשְׁכְּנֵהּ וּכְרוֹ תַמָּן עַבְדֵי יִצְחָק בֵּירָא:
@719 וַאֲבִימֶלֶךְ אֲזַל לְוָתֵהּ מִגְּרָר וְסִיעַת מֵרַחֲמוֹהִי וּפִיכֹל רַב חֵילֵהּ:
@720 וַאֲמַר לְהוֹן יִצְחָק מָה דֵּין אֲתֵיתוּן לְוָתִי וְאַתּוּן סְנֵיתוּן יָתִי וְשַׁלַּחְתּוּנִי מִלְּוָתְכוֹן:
@721 וַאֲמָרוּ מֶחֱזָא חֲזֵינָא אֲרֵי הֲוָה מֵימְרָא דַּיְיָ בִּסַעְדָּךְ וַאֲמַרְנָא תִּתְקַיַּם כְּעַן מוֹמָתָא דִּהֲוָה בֵין אֲבָהָתָנָא בֵּינָנָא וּבֵינָךְ וְנִגְזַר קְיָם עִמָּךְ:
@722 אִם תַּעְבֵּד עִמָּנָא בִּישָׁא כְּמָא דִּי לָא אַנְזִיקְנָךְ וּכְמָא דִּי עֲבַדְנָא עִמָךְ לְחוֹד טָב וַנְשַׁלְּחִנָּךְ בִּשְׁלָם אַתְּ כְּעַן בְּרִיכָא דַּיְיָ:
@723 וַעֲבַד לְהוֹן מִשְׁתְּיָא וַאֲכָלוּ וּשְׁתִיאוּ:
@724 וְאַקְדִימוּ בְצַפְרָא וְקַיִּימוּ גְּבַר לְאָחוּהִי וְשַׁלָּחִנוּן יִצְחָק וַאֲזָלוּ מִלְוָתֵהּ בִּשְׁלָם:
@725 וַהֲוָה בְּיוֹמָא הַהוּא וַאֲתוֹ עַבְדֵי יִצְחָק וְחַוִּיאוּ לֵהּ עַל עֵיסַק בֵּירָא דִּי חֲפָרוּ וַאֲמָרוּ לֵהּ אַשְׁכַּחְנָא מַיָּא:
@726 וּקְרָא יָתַהּ שִׁבְעָה עַל כֵּן שְׁמָא דְקַרְתָּא בְּאֵרָא דְשֶׁבַע (נ''י בְּאֵר שֶׁבַע) עַד יוֹמָא הָדֵין:
@727 וַהֲוָה עֵשָׂו בַּר אַרְבְּעִין שְׁנִין וּנְסִיב אִתְּתָא יָת יְהוּדִית בַּת בְּאֵרִי חִתָּאָה וְיָת בָּשְׂמַת בַּת אֵילוֹן חִתָּאָה:
@728 וַהֲוָאָה מְסָרְבָן וּמְרַגְּזָן עַל מֵימַר יִצְחָק וְרִבְקָה:
@729 וַהֲוָה כַּד סִיב יִצְחָק וְכָהֲיָּא עֵינוֹהִי מִלְּמֶחֱזֵי וּקְרָא יַת עֵשָׂו בְּרֵהּ רַבָּה וַאֲמַר לֵהּ בְּרִי וַאֲמַר לֵהּ הָא אָנָא:
@730 וַאֲמַר הָא כְעַן סֵיבִית לֵית אֲנָא יְדַע יוֹמָא דְאֵימוּת:
@731 וּכְעַן סַב כְּעַן זֵינָךְ סַיְפָךְ וְקַשְׁתָּךְ וּפוּק לְחַקְלָא וְצוּד לִי צֵידָא:
@732 וְעִבֵיד לִי תַבְשִׁילִין כְּמָא דִרְחֵימִית וְאָעֵל לִי וְאֵיכוּל בְּדִיל דִּי תְבָרֵכִנָּךְ נַפְשִׁי עַד לָא אֵימוּת:
@733 וְרִבְקָה שְׁמַעַת כַּד מַלִּיל יִצְחָק לְוַת עֵשָׂו בְּרֵהּ וַאֲזַל עֵשָׂו לְחַקְלָא לְמֵיצַד צֵידָא לְאַיְתָאָה:
@734 וְרִבְקָה אֲמָרַת לְוַת יַעֲקֹב בְּרַהּ לְמֵימָר הָא שְׁמָעִית יַת אֲבוּךְ מְמַלֵּל עִם עֵשָׂו:אַחוּךְ לְמֵימָר:
@735 אַיְתִי לִי צֵידָא וְעִבֵּיד לִי תַבְשִׁילִין וְאֵיכוּל וֶאֱבָרֵכִנָּךְ קֳדָם יְיָ קֳדָם מוֹתִי:
@736 וּכְעַן בְּרִי קַבֵּל מִנִי לְמָא דִי אֲנָא:מפַקֵד יָתָךְ:
@737 אִזֵיל כְּעַן לְוַת עָנָא וְסַב לִי מִתַּמָּן תְּרֵין גַדְיֵי (בַר) עִזְּין טָבָן וְאֶעְבֵּד יָתְהוֹן תַּבְשִׁילִין לְאָבוּךְ כְּמָא דִי רְחֵם:
@738 וְתַיְתִי (נ''י וְתָעֵל) לְאָבוּךְ וְיֵכוּל בְּדִיל דִּיְבָרְכִנָּךְ קֳדָם מוֹתֵהּ:
@739 וַאֲמַר יַעֲקֹב לְרִבְקָה אִמֵּהּ הָא עֵשָׂו אָחִי גְּבַר שַׂעֲרָן וַאֲנָא גְּבַר שְׁעִיעַ:
@740 מָאִים יְמֻשִּׁנַּנִי אַבָּא וְאֵהֵי בְעֵינוֹהִי כְּמִתְלָעָב וְאֵהֵי מַיְתֵי (נ''י וָאֱהִי מַיְתֵי) עֲלַי לְוָטִין וְלָא בִרְכָן:
@741 וַאֲמֶרֶת לֵהּ אִמֵּהּ עֲלַי אִתְאַמַּר בִּנְבוּאָה דְּלָא יֵיתוּן לְוָטַּיָּא עֲלָךְ בְּרִי בְּרַם קַבֵּל מִנִּי וְאִזְּיל סַב לִי:
@742 וַאֲזַל וּנְסִיב וְאַיְתִי לְאִמֵּהּ וַעֲבָדַת אִמֵּהּ תַּבְשִׁילִין כְּמָא דִּרְחֵם אֲבוּהִי:
@743 וּנְסִיבַת רִבְקָה יָת לְבוּשֵׁי עֵשָׂו בְּרַהּ רַבָּא דָּכְיָתָא דִּי עִמַּהּ בְּבֵיתָא וְאַלְבִּישַׁת יָת יַעֲקֹב בְּרַהּ זְעֵירָא:
@744 וְיָת מַשְׁכֵי גַּדְיֵי בַּר עִזֵּי אַלְבִּישַׁת עַל יְדוֹהִי וְעַל שְׁעִיעוּת צַוְרֵהּ:
@745 וִיהָבַת יָת תַּבְשִׁילַיָּא וְיָת לַחְמָא דִּי עֲבָדַת בִּידָא דְיַעֲקֹב בְּרַהּ:
@746 וְעַל לְוַת אֲבוּהִי וַאֲמַר אַבָּא וַאֲמַר הָא אֲנָא מָן אַתְּ בְּרִי:
@747 וַאֲמַר יַעֲקֹב לַאֲבוּהִי אֲנָא עֵשָׂו בּוּכְרָךְ עֲבָדִית כּמָא דִי מַלֵּילְתָּא עִמִּי (נ''י:לִי) קוּם כְּעַן אִסְתַּחַר וֶאֱכוּל מִצֵידִי בְּדִיל דִּי תבָרכִנַּנִּי נַפְשָׁךְ:
@748 וַאֲמַר יִצְחָק לִבְרֵהּ מָה דֵּין אוֹחֵיתָא לְאַשְׁכָּחָא בְּרִי וַאֲמַר אֲרֵי זַמִּין יְיָ אֱלָהָךְ קֳדָמַי:
@749 וַאֲמַר יִצְחָק לְיַעֲקֹב קְרֵיב כְּעַן וֶאֱמֻשִּׁנָּךְ בְּרִי הַאַתְּ דֵּין בְּרִי עֵשָׂו אִם לָא:
@750 וּקְרֵיב יַעֲקֹב לְוַת יִצְחָק אֲבוּהִי וּמָשְׁיֵהּ וַאֲמַר קָלָא קָלָא דְיַעֲקֹב וִידַיָּא יְדוֹהִי דְעֵשָׂו:
@751 וְלָא אִשְׁתְּמוֹדְעֵהּ אֲרֵי הֲוָאָה יְדוֹהִי כִּידֵי עֵשָׂו אֲחוּהִי שְׂעִירָן (נ''י שַׂעֲרַנְיָן) וּבָרְכֵהּ:
@752 וַאֲמַר אַתְּ דֵּין בְּרִי עֵשָׂו וַאֲמַר הָא אֲנָא:
@753 וַאֲמַר קָרֵיב קֳדָמַי וְאֵיכוּל מִצֵידָא דִּבְרִי בְּדִיל דִּי תְבָרְכִנָּךְ נַפְשִׁי וְקָרֵיב לֵהּ וַאֲכַל וְאַיְתִי (נ''י וְאָעֵל) לֵהּ חַמְרָא וּשְׁתִי:
@754 וַאֲמַר לֵהּ יִצְחָק אֲבוּהִי קְרֵיב כְּעַן וּנְשַׁק לִי (נ''י וְשַׁק לִי) בְּרִי:
@755 וּקְרֵב וּנְשַׁק לֵהּ וַאֲרַח יָת רֵיחָא דִּלְבוּשׁוֹהִי וּבָרְכֵהּ וַאֲמַר חֲזֵי רֵיחָא דִּבְרִי כְּרֵיחָא דְחַקְלָא דִּי בָרֲכֵהּ יְיָ:
@756 וְיִתֶּן לָךְ יְיָ מִטַּלָּא דִּשְׁמַיָּא וּמִטּוּבָא דְאַרְעָא וּסְגִיאוּת (נ''י וְסַגְיוּת) עִיבוּר וַחֲמָר:
@757 יִפְלְחֻנָּךְ עַמְמִין וְיִשְׁתַּעְבְּדוּן לָךְ מַלְכְּוָן הֱוֵי רַב לְאַחָיךְ וְיִסְגְּדוּן לָךְ בְּנֵי אִמָּךְ מְלַטְטָיךְ יְהוֹן לִיטִין וּמְבָרֲכָיךְ יְהוֹן בְּרִיכִין:
@758 וַהֲוָה כַּד שֵׁיצֵי יִצְחָק לְבָרָכָא יָת יַעֲקֹב וַהֲוָה בְּרַם מִפַּק נְפַק יַעֲקֹב מִלְּוַת אַפֵּי יִצְחָק אֲבוּהִי וְעֵשָׂו אֲחוּהִי אָתָא (נ''י עַל) מִצֵידֵהּ:
@759 וַעֲבַד אַף הוּא תַּבְשִׁילִין וְאָעֵיל לְוַת אֲבוּהִי וַאֲמַר לַאֲבוּהִי יָקוּם אַבָּא וְיֵכוּל מִצֵידָא דִּבְרֵהּ בְּדִיל דִּי תְבָרְכִנַּנִּי נַפְשָׁךְ:
@760 וַאֲמַר לֵהּ יִצְחָק אֲבוּהִי מָן אָתְּ וַאֲמַר אֲנָא בְּרָךְ בּוּכְרָךְ עֵשָׂו:
@761 וּתְוָה יִצְחָק תִּוְהָא רַבָּא עַד לַחֲדָא וַאֲמַר מָן הוּא דֵּיכִי דְצָד צֵידָא וְאָעֵיל לִי וַאֲכָלִית מִכֹּלָּא עַד לָא תֵיעוֹל וּבָרֵכִתֵּהּ אַף בְּרִיךְ יְהֵי:
@762 כַּד שְׁמַע עֵשָׂו יָת פִּתְגָּמֵי אֲבוּהִי וּצְוַח צִוְחָא רַבָּא וּמְרִירָא עַד לַחֲדָא וַאֲמַר לַאֲבוּהִי בָּרֵכְנִי אַף אֲנָא (נ''י לִי) אַבָּא:
@763 וַאֲמַר עַל אָחוּךְ בְּחָכְמְתָא וְקַבִּיל בִּרְכְּתָךְ:
@764 וַאֲמַר יָאוּת קְרָא שְׁמֵהּ יַעֲקֹב וְכָמַנִי דְּנָן תַּרְתֵּין זִמְנִין יָת בְּכֵירוּתִי נְסִיב וְהָא כְּעַן קַבִּיל בִּרְכְּתִי וַאֲמַר הֲלָא שְׁבַקְתָּ לִי בִּרְכְּתָא:
@765 וַאֲתֵיב יִצְחָק וַאֲמַר לְעֵשָׂו הָא רַב שַׁוִּתֵּהּ לָךְ (נ''י עִלַּוָּךְ) וְיָת כָּל אֲחוֹהִי יְהָבִית לֵהּ לְעַבְדִּין וְעִיבוּר וַחֲמָר סְעִדְתֵּהּ וְלָךְ הָכָא מָה אֶעְבֵּיד בְּרִי:
@766 וַאֲמַר עֵשָׂו לַאֲבוּהִי הֲבִרְכְּתָא חֲדָא הִיא לָךְ אַבָּא בָּרֵךְ לִי אַף אֲנָא אַבָּא וַאֲרֵים עֵשָׂו קָלֵהּ וּבְכָא:
@767 וַאֲתֵיב יִצְחָק אֲבוּהִי וַאֲמַר לֵהּ הָא מִטּוּבָא דְאַרְעָא יְהֵא מוֹתְבָךְ וּמִטַּלָּא דִּשְׁמַיָּא מִלְּעֵלָא:
@768 וְעַל חַרְבָּךְ תֵּיחֵי וְיָת אָחוּךְ תִּפְלָח וִיהֵי כַּד יַעְבְּרוּן בְּנוֹהִי עַל פִּתְגָּמֵי אוֹרַיְתָא וְתַעְדִּי נִירֵהּ מֵעַל צַוְרָךְ:
@769 וּנְטַר עֵשָׂו דְּבָבוּ לְיַעֲקֹב עַל בִּרְכְּתָא דִּי בָרְכֵהּ אֲבוּהִי וַאֲמַר עֵשָׂו בְּלִבֵּהּ יִקְרְבוּן יוֹמֵי אֶבְלֵי דְאַבָּא וְאֶקְטוֹל יָת יַעֲקֹב אָחִי:
@770 וְאִתְחַוָּה לְרִבְקָה יָת פִּתְגָּמֵי עֵשָׂו בְּרַהּ רַבָּא וּשְׁלָחַת וּקְרַת לְיַעֲקֹב בְּרַהּ זְעֵירָא וַאֲמֶרֶת לֵהּ הָא עֵשָׂו אָחוּךְ כָּמִן לָךְ לְמִקְטְלָךְ:
@771 וּכְעַן בְּרִי קַבֵּל מִנִּי וְקוּם אִזֵּיל לָךְ לְוַת לָבָן אָחִי לְחָרָן:
@772 וְתֵתֵיב עִמֵּהּ יוֹמִין זְעֵירִין עַד דִּיתוּב רוּגְזָא דְאָחוּךְ:
@773 עַד דִּיתוּב רוּגְזָא דְאָחוּךְ מִנָּךְ וְיִתְנְשֵׁי יָת דִּי עֲבַדְתָּ לֵהּ וְאֶשְׁלַח וְאֶדְבְּרִנָּךְ מִתַּמָּן לְמָה אֶתְכַּל אַף תַּרְוֵיכוֹן יוֹמָא חָד:
@774 וַאֲמֶרֶת רִבְקָה לְיִצְחָק עָקִית בְּחַיַּי מִן קֳדָם בְּנַת חִתָּאָה אִם נְסִיב יַעֲקֹב אִתְּתָא מִבְּנַת חִתָּאָה כְאִלֵּין מִבְּנַת אַרְעָא לְמָה לִי חַיִּים:
@775 וּקְרָא יִצְחָק לְיַעֲקֹב וּבָרִיךְ יָתֵהּ וּפַקְדֵהּ וַאֲמַר לֵהּ לָא תִסַּב אִתְּתָא מִבְּנַת כְּנָעַן:
@776 קוּם אִזֵּיל לְפַדַּן אֲרָם לְבֵית בְּתוּאֵל אֲבוּהָא דְאִמָּךְ וְסַב לָךְ מִתַּמָּן אִתְּתָא מִבְּנַת לָבָן אֲחוּהָא דְאִמָּךְ:
@777 וְאֵל שַׁדַּי יְבָרֵךְ יָתָךְ וְיַפְּשָׁךְ וְיַסְגִּנָּךְ וּתְהֵי לְכִנְשַׁת שִׁבְטִין:
@778 וְיִתֶּן לָךְ יָת בִּרְכְּתָא דְאַבְרָהָם לָךְ וְלִבְנָיךְ עִמָּךְ לְמֵירְתָךְ יָת אֲרַע תּוֹתָבוּתָךְ דִּי יְהַב יְיָ לְאַבְרָהָם:
@779 וּשְׁלַח יִצְחָק יָת יַעֲקֹב וַאֲזַל לְפַדַּן אֲרָם לְוַת לָבָן בַּר בְּתוּאֵל אֲרַמָּאָה אֲחוּהָא דְרִבְקָה אִמֵּהּ דְּיַעֲקֹב וְעֵשָׂו:
@780 וַחֲזָא עֵשָׂו אֲרֵי בָרִיךְ יִצְחָק יָת יַעֲקֹב וְשַׁלַּח יָתֵהּ לְפַדַּן אֲרָם לְמִסַּב לֵהּ מִתַּמָּן אִתְּתָא כַּד בָּרִיךְ יָתֵהּ וּפַקֵּיד עֲלוֹהִי לְמֵימַר לָא תִסַּב אִתְּתָא מִבְּנַת כְּנָעַן:
@781 וְקַבִּיל יַעֲקֹב מִן אֲבוּהִי וּמִן אִמֵּהּ וַאֲזַל לְפַדַּן אֲרָם:
@782 וַחֲזָא עֵשָׂו אֲרֵי בִישָׁא בְּנַת כְּנָעַן בְּעֵינֵי יִצְחָק אֲבוּהִי:
@783 וַאֲזַל עֵשָׂו לְוַת יִשְׁמָעֵאל וּנְסִיב יָת מַחֲלַת בַּת יִשְׁמָעֵאל בַּר אַבְרָהָם אֲחָתֵהּ דִּנְבָיוֹת עַל נְשׁוֹהִי לֵהּ לְאִנְתּוּ: ססס:
@784 וּנְפַק יַעֲקֹב מִבְּאֵרָא דְשָׁבַע וַאֲזַל לְחָרָן:
@785 וַעֲרַע בְּאַתְרָא וּבָת תַּמָּן אֲרֵי עָל שִׁמְשָׁא וּנְסִיב מֵאַבְנֵי אַתְרָא וְשַׁוִּי אִסָדוֹהִי וּשְׁכִיב בְּאַתְרָא הַהוּא:
@786 וַחֲלַם וְהָא סֻלְמָא נָעִיץ בְּאַרְעָא וְרֵישֵׁהּ מָטֵי עַד צֵית שְׁמַיָּא וְהָא מַלְאָכַיָּא דַּיְיָ סָלְקִין וְנָחֲתִין בֵּהּ:
@787 וְהָא יְקָרָא דַיְיָ מְעַתַּד עִלָווֹהִי וַאֲמַר אֲנָא יְיָ אֱלָהֵהּ דְּאַבְרָהָם אָבוּךְ וֵאלָהֵהּ דְּיִצְחָק אַרְעָא דִּי אַתְּ שְׁכִיב עֲלַהּ לָךְ אֶתְּנִנַּהּ וְלִבְנָיךְ:
@788 וִיהוֹן בְּנָיךְ סַגִּיאִין כְּעַפְרָא דְאַרְעָא וְתִתְקֵף לְמַעַרְבָא וּלְמַדִינְחָא וּלְצִפּוּנָא וּלְדָרוֹמָא וְיִתְבָּרְכוּן בְּדִילָךְ כָּל זַרְעֲיַת אַרְעָא וּבְדִיל בְּנָיךְ:
@789 וְהָא מֵימְרִי בְּסַעְדָךְ וְאֶטְרִנָךְ בְּכָל אֲתַר דִּי תְהַךְ וַאֲתֵיבִנָּךְ לְאַרְעָא הָדָא אֲרֵי לָא אֶשְׁבְּקִנָּךְ עַד דִּי אֶעְבֵּיד יָת דִּי מַלֵּלִית לָךְ:
@790 וְאִתְּעַר יַעֲקֹב מִשִּׁנְתֵּהּ וַאֲמַר בְּקוּשְׁטָּא (אִית) יְקָרָא דַיְיָ שָׁרֵי בְּאַתְרָא הָדֵין וַאֲנָא לָא הֲוֵיתִי יְדָע:
@791 וּדְחִיל וַאֲמַר מָה דְחִילוּ אַתְרָא הָדֵין לֵית דֵּין אֲתַר הֶדְיוֹט אֶלָהֵין אֲתַר דְּרַעֲוָא בֵהּ מִן קֳדָם יְיָ וְדֵין תְּרַע קֳבֵל שְׁמַיָּא:
@792 וְאַקְדֵים יַעֲקֹב בְּצַפְרָא וּנְסִיב יָת אַבְנָא דִי שַׁוִּי אִסָדוֹהִי וְשַׁוִּי יָתַהּ קָמָא וַאֲרִיק מִשְׁחָא עַל רֵישֵׁהּ:
@793 וּקְרָא יָת שְׁמָא דְאַתְרָא הַהוּא בֵּית אֵל וּבְרַם לוּז שְׁמָא דְקַרְתָּא בְּקַדְמֵיתָא:
@794 וְקַיִּים יַעֲקֹב קְיָם לְמֵימָר אִם יְהֵא מֵימְרָא דַּיְיָ בְּסַעְדִי וְיִטְרִינַנִּי בְּאָרְחָא הָדֵין דִּי אֲנָא אָזֵל וְיִתֶּן לִי לַחֲמָא (נ''י לְחֵם) לְמֵיכַל וּכְסוּ לְמִלְבָּשׁ:
@795 וְאֵתוּב בִּשְׁלַם לְבֵית אַבָּא וִיהֵא מֵימְרָא דַיְיָ לִי לֵאלָהָא:
@796 וְאַבְנָא הָדָא דִי שַׁוֵּיתִי קָמָא תְּהֵי דִי אֵהֵי פָלַח עֲלַהּ קֳדָם יְיָ וְכֹל דִּי תִתֶּן לִי חַד מִן עַשְׂרָא אַפְרְשִׁנֵּהּ קֳדָמָךְ:
@797 וּנְטַל יַעֲקֹב רַגְלוֹהִי (נ''י רִיגְלוֹהִי) וַאֲזַל לַאֲרַע בְּנֵי מַדִינְחָא:
@798 וַחֲזָא וְהָא בֵירָא בְחַקְלָא וְהָא תַמָּן תְּלָתָא עֶדְרִין דְּעָן רְבֵעִין עֲלַהּ אֲרֵי מִן בֵּירָא הַהִיא מַשְׁקָן עֲדָרַיָּא וְאַבְנָא רַבְּתָא עַל פּוּמָא דְבֵירָא:
@799 וּמִתְכַּנְשִׁין לְתַמָּן כָּל עֲדָרַיָּא וּמְגַנְדְּרִין יָת אַבְנָא מֵעַל פּוּמָא דְבֵירָא וּמַשְׁקָן יָת עָנָא וּמְתִיבִין יָת אַבְנָא עַל פּוּמָא דְבֵירָא לְאַתְרַהּ:
@800 וַאֲמַר לְהוֹן יַעֲקֹב אַחַי מְנָן אַתּוּן וַאֲמָרוּ מֵחָרָן אֲנָחְנָא:
@801 וַאֲמַר לְהוֹן הַיְדַעְתּוּן יָת לָבָן בַּר נָחוֹר וַאֲמָרוּ יְדַעְנָן:
@802 וַאֲמַר לְהוֹן הַשְׁלַם לֵהּ וַאֲמָרוּ שְׁלַם וְהָא רָחֵל בְּרַתֵּהּ אַתְיָא עִם עָנָא:
@803 וַאֲמַר הָא עוֹד יוֹמָא סַגִי לָא עִדַן לְמִכְנַשׁ בְּעִיר אַשְׁקוּ עָנָא וְאִזִילוּ רְעוּ:
@804 וַאֲמָרוּ לָא נִכּוּל עַד דִי יִתְכַּנְשִׁין כָּל עֲדָרַיָּא וִיגַנְדְרוּן יָת אַבְנָא מֵעַל פוּמָא דְבֵירָא וְנַשְׁקֵי עָנָא:
@805 עַד דְהוּא מְמַלֵל עִמְהוֹן וְרָחֵל אָתַת עִם עָנָא דִי לַאֲבוּהָ אֲרֵי רָעִיתָא הִיא:
@806 וַהֲוָה כַּד חֲזָא יַעֲקֹב יָת רָחֵל בַּת לָבָן אֲחוּהָא דְאִמֵהּ וְיָת עָנָא דְלָבָן אֲחוּהָא דְאִמֵהּ וּקְרֵב יַעֲקֹב וּגַנְדַר יָת אַבְנָא מֵעַל פּוּמָא דְבֵירָא וְאַשְׁקֵי יָת עָנָא דְלָבָן אֲחוּהָא דְאִמֵהּ:
@807 וּנְשַׁק יַעֲקֹב לְרָחֵל וַאֲרֵם יָת קָלֵהּ וּבְכָא:
@808 וְחַוִּי יַעֲקֹב לְרָחֵל אֲרֵי בַר אֲחַת אָבוּהָא הוּא וַאֲרֵי בַר רִבְקָה הוּא וּרְהָטַת וְחַוִּיאַת לְאָבוּהָא:
@809 וַהֲוָה כַּד שְׁמַע לָבָן יָת שֵׁמַע יַעֲקֹב בַּר אֲחָתֵהּ וּרְהַט לְקַדָמוּתֵהּ וְגַפֵּף לֵהּ וְנַשִׁיק לֵהּ וְאַעֲלֵהּ לְבֵיתֵהּ וְאִשְׁתָּעִי לְלָבָן יָת כָּל פִּתְגָמַיָּא הָאִלֵּין:
@810 וַאֲמַר לֵהּ לָבָן בְּרַם קָרִיבִי וּבִשְׂרִי אָתְּ וִיתֵיב עִמֵּהּ יְרַח יוֹמִין:
@811 וַאֲמַר לָבָן לְיַעֲקֹב הֲמִדְּאָחִי אַתְּ וְתִפְלְחִנַּנִּי מַגָּן חַוִּי לִי מָה אַגְרָךְ:
@812 וּלְלָבָן תַּרְתֵּין בְּנָן שׁוּם רַבְּתָא לֵאָה וְשׁוּם זְעֶרְתָּא רָחֵל:
@813 וְעֵינֵי לֵאָה יָאֲיָן וְרָחֵל הֲוַת שַׁפִּירָא בְרֵיוָא וְיָאֲיָא בְחֶזְוָא:
@814 וּרְחֵם יַעֲקֹב יָת רָחֵל וַאֲמַר אֶפְלְחִנָּךְ שְׁבַע שְׁנִין בְּרָחֵל בְּרַתָּךְ זְעֶרְתָּא:
@815 וַאֲמַר לָבָן טַב דְּאֶתֵּן יָתַהּ לָךְ מִדְּאֶתֵּן יָתַהּ לִגְבַר אָחֳרָן תִּיב עִמִּי:
@816 וּפְלַח יַעֲקֹב בְּרָחֵל שְׁבַע שְׁנִין וַהֲווֹ בְעֵינוֹהִי כְּיוֹמִין זְעִירִין כַּד רְחֵים יָתַהּ:
@817 וַאֲמַר יַעֲקֹב לְלָבָן הַב יָת אִתְּתִי אֲרֵי אַשְׁלֵמִית יוֹמֵי פָלְחָנִי וְאֵעוֹל לְוָתַהּ:
@818 וּכְנַשׁ לָבָן יָת כָּל אֲנָשֵׁי אַתְרָא וַעֲבַד מִשְׁתְּיָא:
@819 וַהֲוָה בְרַמְשָׁא וּדְבַר יָת לֵאָה בְרַתֵּהּ וְאָעֵיל יָתַהּ לְוָתֵהּ וְעַל לְוָתַהּ:
@820 וִיהַב לָבָן לַהּ יָת זִלְפָּה אַמְתֵהּ לְלֵאָה בְרַתֵּהּ לְאַמְהוּ:
@821 וַהֲוָה בְצַפְרָא וְהָא הִיא לֵאָה וַאֲמַר לְלָבָן מָה דָּא עֲבַדְתָּ לִּי הֲלָא בְרָחֵל פְּלָחִית עִמָּךְ וּלְמָא שַׁקַּרְתָּ בִּי:
@822 וַאֲמַר לָבָן לָא יִתְעֲבֵד כְּדֵין בְּאַתְרָנָא לְמִתַּן זְעֶרְתָּא קֳדָם רַבְּתָא:
@823 אַשְׁלִים שְׁבוּעֲתָא דְדָא וְנִתֵּן לָךְ אַף יָת דָּא בְּפָלְחָנָא דִּי תִפְלַח עִמִּי עוֹד שְׁבַע שְׁנִין אָחֳרָנִין:
@824 וַעֲבַד יַעֲקֹב כֵּן וְאַשְׁלֵים שְׁבוּעֲתָא דְדָא וִיהַב לֵהּ יָת רָחֵל בְּרַתֵּהּ לֵהּ לְאִנְתּוּ:
@825 וִיהַב לָבָן לְרָחֵל בְּרַתֵּהּ יָת בִּלְהָה אַמְתֵהּ לַהּ לְאַמְהוּ:
@826 וְעַל אַף לְּוַת רָחֵל וּרְחֵים אַף יָת רָחֵל מִלֵּאָה וּפְלַח עִמֵּהּ עוֹד שְׁבַע שְׁנִין אָחֳרָנִין:
@827 וַחֲזָא יְיָ אֲרֵי שְׂנִיאֲתָא לֵאָה וִיהַב לַהּ עִדּוּי וְרָחֵל עַקְרָא:
@828 וְעַדִּיאַת לֵּאָה וִילִידַת בָּר וּקְרַת שְׁמֵהּ רְאוּבֵן אֲרֵי אֲמֶרֶת אֲרֵי גְלִי קֳדָם יְיָ עֻלְבּוֹנִי אֲרֵי כְעַן יְרַחֲמִנַנִי בַעֲלִי:
@829 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת אֲרֵי שְׁמִיעַ קֳדָם יְיָ אֲרֵי שְׂנִיאֲתָא אֲנָא וִיהַב לִי אַף יָת דֵּין וּקְרַת שְׁמֵהּ שִׁמְעוֹן:
@830 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת הָדָא זִמְנָא יִתְחַבַּר לִי בַעֲלִי אֲרֵי יְלֵידִית לֵהּ תְּלָתָא בְנִין עַל כֵּן קְרָא שְׁמֵהּ לֵוִי:
@831 וְעַדִּיאַת עוֹד וִילִידַת בָּר וַאֲמֶרֶת הָדָא זִמְנָא אוֹדֶה קֳדָם יְיָ עַל כֵּן קְרַת שְׁמֵהּ יְהוּדָה וְקָמַת מִלְּמֵילַד:
@832 וַחֲזַת רָחֵל אֲרֵי לָא יְלִידַת לְיַעֲקֹב וְקַנִּיאַת רָחֵל בַּאֲחָתַהּ וַאֲמֶרֶת לְיַעֲקֹב הַב לִי בְנִין וְאִם לָא מֵיתָא אֲנָא:
@833 וּתְקֵיף רוּגְזָא דְיַעֲקֹב בְּרָחֵל וַאֲמַר הָא מִנִּי אַתְּ בַּעְיָא הֲלָא מִן קֳדָם יְיָ תִּבְעִין דִּי מְנַע מִנִּיךְ וַלְדָא דִּמְעִין:
@834 וַאֲמֶרֶת הָא אַמְתִי בִלְהָה עוּל לְוָתַהּ וּתְלִיד וַאֲנָא אֱרַבֵּי וְאִתְבְּנֵי אַף אֲנָא מִנַּהּ:
@835 וִיהָבַת לֵהּ יָת בִּלְהָה אַמְתַהּ לְאִנְתּוּ וְעַל לְוָתַהּ יַעֲקֹב:
@836 וְעַדִּיאַת בִּלְהָה וִילִידַת לְיַעֲקֹב בַּר:
@837 וַאֲמֶרֶת רָחֵל דְּנַנִּי יְיָ וְאַף קַבִּיל צְלוֹתִי וִיהַב לִי בַּר עַל כֵּן קְרַת שְׁמֵהּ דָּן:
@838 וְעַדִּיאַת עוֹד וִילִידַת בִּלְהָה אַמְתָא דְרָחֵל בָּר תִּנְיָן לְיַעֲקֹב:
@839 וַאֲמֶרֶת רָחֵל קַבִּיל יְיָ בָּעוּתִי בְּאִתְחַנָּנוּתִי בִּצְלוֹתִי חֲמֵידַת דִּיהֵי לִי וְלַד כַּאֲחָתִי אַף אִתְיְהִיב לִי וּקְרַת שְׁמֵהּ נַפְתָּלִי:
@840 וַחֲזַת לֵּאָה אֲרֵי קָמַת מִלְּמֵילַד וּדְבָרַת יָת זִלְפָּה אַמְתַהּ וִיהָבַת יָתַהּ לְיַעֲקֹב לְאִנְתּוּ:
@841 וִילִידַת זִלְפָּה אַמְתָא דְלֵאָה לְיַעֲקֹב בָּר:
@842 וַאֲמֶרֶת לֵאָה אֲתָא גָד וּקְרַת יָת שְׁמֵהּ גָּד:
@843 וִילִידַת זִלְפָּה אַמְתָא דְלֵאָה בָּר תִּנְיָן לְיַעֲקֹב:
@844 וַאֲמֶרֶת לֵאָה תֻּשְׁבַּחְתָּא הֲוַת לִי אֲרֵי בְכֵן יְשַׁבְּחֻנַּנִּי נְשַׁיָּא וּקְרַת יָת שְׁמֵהּ אָשֵׁר:
@845 וַאֲזַל רְאוּבֵן בְּיוֹמֵי חֲצַד חִטִּין וְאַשְׁכַּח יַבְרוּחִין בְּחַקְלָא וְאַיְתִי יָתְהוֹן לְלֵאָה אִמֵּהּ וַאֲמֶרֶת רָחֵל לְלֵאָה הָבִי כְעַן לִי מִיַּבְרוּחֵי דִּבְרִיךְ:
@846 וַאֲמֶרֶת לַהּ הַזְעֵיר דִּדְבַרְתְּ יָת בַּעְלִי וְתִסְּבִין אַף יָת יַבְרוּחֵי דִּבְרִי וַאֲמֶרֶת רָחֵל בְּכֵן יִשְׁכּוּב עִמָּךְ בְּלֵילְיָא חֳלַף יַבְרוּחֵי דִּבְרִיךְ:
@847 וַאֲתָא (נ''י וְעַל) יַעֲקֹב מִן חַקְלָא בְּרַמְשָׁא וּנְפָקַת לֵאָה לְקַדָּמוּתֵהּ וַאֲמֶרֶת לְוָתִי תֵיעוֹל אֲרֵי מֵיגַר אֲגַרְתִּיךְ בְּיַבְרוּחֵי דִּבְרִי וּשְׁכִיב עִמַּהּ בְּלֵילְיָא הוּא:
@848 וְקַבִּיל יְיָ צְלוֹתַהּ דְּלֵאָה וְעַדִּיאַת וִילִידַת לְיַעֲקֹב בַּר חֲמִישָׁאֵי:
@849 וַאֲמֶרֶת לֵאָה יְהַב יְיָ אַגְרִי דִּי יְהָבִית אַמְתִי לְבַעְלִי וּקְרַת שְׁמֵהּ יִשָּׂשׂכָר:
@850 וְעַדִּיאַת עוֹד לֵאָה וִילִידַת בַּר שְׁתִיתָאֵי לְיַעֲקֹב:
@851 וַאֲמֶרֶת לֵאָה יְהַב יְיָ יָתֵהּ לִי חָלַק טַב הָדָא זִמְנָא יְהֵי מְדוֹרֵהּ דְּבַעְלִי לְוָתִי אֲרֵי יְלֵידִית לֵהּ שִׁתָּא בְנִין וּקְרַת יָת שְׁמֵהּ זְבֻלוּן:
@852 וּבָתַר כֵּן יְלִידַת בְּרַתָּא וּקְרַת יָת שְׁמַהּ דִּינָה:
@853 וְעַל דּוּכְרָנָא דְרָחֵל קֳדָם יְיָ וְקַבִּיל צְלוֹתַהּ יְיָ וִיהַב לַהּ עִדּוּי:
@854 וְעַדִּיאַת וִילִידַת בָּר וַאֲמֶרֶת כְּנַשׁ יְיָ יָת חִסּוּדִי:
@855 וּקְרַת יָת שְׁמֵהּ יוֹסֵף לְמֵימָר יוֹסֵף יְיָ לִי בַּר אָחֳרָן:
@856 וַהֲוָה כַּד יְלִידַת רָחֵל יָת יוֹסֵף וַאֲמַר יַעֲקֹב לְלָבָן שַׁלְּחַנִּי וְאֵיהַךְ לְאַתְרִי וּלְאַרְעִי:
@857 הַב יָת נְשַׁי וְיָת בְּנַי דִּי פְלָחִית יָתָךְ בְּהֵן וְאֵזִיל אֲרֵי אַתְּ יְדַעְתָּ יָת פָּלְחָנִי דִּי פְלָחִתָּךְ:
@858 וַאֲמַר לֵהּ לָבָן אִם כְּעַן אַשְׁכָּחִית רַחֲמִין קֳדָמָךְ נַסֵּיתִי וּבָרְכַנִי יְיָ בְּדִילָךְ:
@859 וַאֲמָר פָּרֵישׁ אַגְרָךְ עֲלַי וְאֶתֵּן:
@860 וַאֲמַר לֵהּ אַתְּ יְדַעְתָּ יָת דִּי פְלָחִתָּךְ וְיָת דַּהֲוָה בְעִירָךְ עִמִּי:
@861 אֲרֵי זְעֵיר דִּי הֲוָה לָךְ קֳדָמַי וּתְקֵיף לְמִסְגֵּי וּבְרִיךְ יְיָ יָתָךְ בְּדִילִי וּכְעַן אֵימָתַי אֶעְבֵּיד אַף אֲנָא לְבֵיתִי:
@862 וַאֲמַר מָה אֶתֵּן לָךְ וַאֲמַר יַעֲקֹב לָא תִתֶּן לִי מִדַּעַם אִם תַּעְבֶּד לִי פִּתְגָּמָא הָדֵין אֱתוּב אֶרְעֵי עָנָךְ אֶטָּר:
@863 אֶעְבַּר בְּכָל עָנָךְ יוֹמָא דֵּין הַעֲדֵי (נ''י אַעְדִּי) מִתַּמָּן כָּל אִמָּר נְמוֹר וּרְקוֹעַ וְכָל אִמָּר שְׁחוּם בְּאִמְרַיָא וּרְקוֹעַ וּנְמוֹר בְּעִזַיָא וִיהֵי אַגְרִי:
@864 וְתַסְהֵד בִּי זָכוּתִי בְּיוֹם דִּמְחָר אֲרֵי תֵיעוֹל עַל אַגְרִי קֳדָמָךְ כֹּל דִּי לֵיתוֹהִי נְמוֹר וּרְקוֹעַ בְּעִזַּיָּא וּשְׁחוּם בְּאִמְרַיָא גְּנוּבָא הוּא עִמִּי:
@865 וַאֲמַר לָבָן בְּרַם לְוַי יְהֵי כְפִתְגָּמָךְ:
@866 וְאַעְדִּי בְיוֹמָא הַהוּא יָת תְּיָשַׁיָא רְגוֹלַיָא וּרְקוֹעַיָא וְיָת כָּל עִזַּיָא נְמוֹרְתָא וּרְקוֹעֲתָא כֹּל דִּי חִוָּר בֵּהּ וְכָל דִּשְׁחוּם בְּאִמְּרַיָּא וִיהַב בְּיַד בְּנוֹהִי:
@867 וְשַׁוִּי מַהֲלַךְ תְּלָתָא יוֹמִין בֵּינוֹהִי וּבֵין יַעֲקֹב וְיַעֲקֹב רָעֵי יָת עָנָא דְלָבָן דְּאִשְׁתָּאֳרָן:
@868 וּנְסִיב לֵהּ יַעֲקֹב חוּטְרִין דִּלְבָן רַטִּיבִין וִּדְלוּז וְדִדְלוּף וְקַלִּיף בְּהוֹן קִלְפִין חִוָּרִין קִלּוּף חִוָּר דִּי עַל חוּטְרַיָּא:
@869 וְדָעִיץ יָת חוּטְרַיָּא דִּי קַלִּיף בִּרְהָטַיָּא אֲתַר בֵּית שַׁקְיָא דְמַיָּא אֲתַר דְּאָתָן (נ''י דְּאָתְיָן) עָנָא לְמִשְׁתֵּי לְקִבְלֵיהוֹן דְּעָנָא וּמִתְיַחֲמָן בְּמֵיתֵיהוֹן לְמִשְׁתֵּי:
@870 וְאִתְיַחֲמָא עָנָא בְּחוּטְרַיָּא וִילִידָא עָנָא רְגוֹלִין נְמוֹרִין וּרְקוֹעִין:
@871 וְאִמְּרַיָּא אַפְרֵשׁ יַעֲקֹב וִיהַב בְּרֵישׁ עָנָא כָּל דִּרְגוֹל וְכָל דִּשְׁחוּם בְּעָנָא דְלָבָן וְשַׁוִּי לֵהּ עֶדְרִין בִּלְחוֹדוֹהִי וְלָא עֲרֵבִנּוּן עִם עָנָא דְלָבָן:
@872 וַהֲוֵי בְּכָל עִדַּן דְּמִתְיַחֲמָן עָנָא מְבַכַּרְתָּא וּמְשַׁוִּי יַעֲקֹב יָת חוּטְרַיָּא לְעֵינֵי עָנָא בִּרְהָטַיָּא לְיַחָמוּתְהוֹן בְּחוּטְרַיָּא:
@873 וּבְלַקִּישׁוּת עָנָא לָא מְשַׁוֵּי וַהֲווֹ לַקִּישָׁא לְלָבָן וּבַכִּירַיָּא לְיַעֲקֹב:
@874 וּתְקֵיף גַּבְרָא לַחֲדָא לַחֲדָא וַהֲווֹ לֵהּ עָן סַגִּיאָן וְאַמְהָן וְעַבְדִּין וְגַמְלִין וַחֲמָרִין:
@875 וּשְׁמַע יָת פִתְגָּמֵי בְנֵי לָבָן דְּאָמְרִין נְסִיב יַעֲקֹב יָת כָּל דִּי לְאָבוּנָא וּמִדִּי לְאָבוּנָא קְנָא יָת כָּל נִכְסַיָּא הָדֵין:
@876 וַחֲזָא יַעֲקֹב יָת סְבַר אַפֵּי לָבָן וְהָא לֵיתוֹהִי עִמֵּהּ כְּמֵאִתְמַלִּי וּמִדְּקַמּוֹהִי:
@877 וַאֲמַר יְיָ לְיַעֲקֹב תּוּב לְאַרְעָא דַּאֲבָהָתָךְ וּלְיַלָּדֻתָךְ וִיהֵי מֵימְרִי בְּסַעְדָּךְ:
@878 וּשְׁלַח יַעֲקֹב וּקְרָא לְרָחֵל וּלְלֵאָה לְחַקְלָא לְוַת עָנֵהּ:
@879 וַאֲמַר לְהֵן חָזֵי אֲנָא יָת סְבַר אַפֵּי אֲבוּכֶן אֲרֵי לֵיתוֹהִי עִמִּי כְּמֵאִתְמַלִּי וּמִדְּקַמֹּהִי וֵאלָהֵהּ דְּאַבָּא הֲוָה בְּסַעְדִּי:
@880 וְאַתִּין יְדַעְתִּין אֲרֵי בְּכָל חֵילִי פְּלָחִית יָת אֲבוּכֶן:
@881 וַאֲבוּכֶן שְׁקַּר בִּי וְאַשְׁנִי יָת אַגְרִי עֲשַׂר זִמְנִין וְלָא שָׁבְקֵהּ יְיָ לְאַבְאָשָׁא עִמִּי:
@882 אִם כְּדֵין הֲוָה אֲמַר נְמוֹרִין יְהֵא אַגְרָךְ וִילִידָן כָּל עָנָא נְמוֹרִין וְאִם כְּדֵין הֲוָה אֲמַר רְגוֹלִין יְהֵא אַגְרָךְ וִילִידָן כָּל עָנָא רְגוֹלִין:
@883 וְאַפְרֵשׁ יְיָ יָת גֵּיתֵי דַּאֲבוּכוֹן וִיהַב לִי:
@884 וַהֲוָה בְּעִדַּן דְּאִתְיַחֲמָא עָנָא וּזְקָפִית עַיְנַי וַחֲזֵית בְּחֶלְמָא וְהָא תְיָשַׁיָּא דְּסָלְקִין עַל עָנָא רְגוֹלִין נְמוֹרִין וּפַצִיחִין:
@885 וַאֲמַר לִי מַלְאָכָא דַּיְיָ בְּחֶלְמָא יַעֲקֹב וַאֲמָרִית הָא אֲנָא:
@886 וַאֲמַר זְקוֹף כְּעַן עַינָיךְ וַחֲזֵי כָּל תְּיָשַׁיָּא דְּסָלְקִין עַל עָנָא רְגוֹלִין נְמוֹרִין וּפַצִיחִין אֲרֵי גְלֵי קֳדָמַי יָת כָּל דִּי לָבָן עָבֵד לָךְ:
@887 אֲנָא אֱלָהָא דְּאִתְגְּלֵיתִי עֲלָךְ בְּבֵית אֵל דִּי מְשַׁחְתָּא תַמָּן קָמָא דִּי קַיִּמְתָּא קֳדָמַי תַּמָּן קְיָם כְּעַן קוּם פּוּק מִן אַרְעָא הָדָא וְתוּב לְאַרְעָא יַלָּדוּתָךְ:
@888 וַאֲתִיבַת רָחֵל וְלֵאָה וַאֲמָרַן לֵהּ הַעוֹד (כְּעַן) לָנָא חֳלָק וְאַחֲסָנָא בְּבֵית אֲבוּנָא:
@889 הֲלָא נוּכְרָאָן אִתְחֲשַׁבְנָא לֵהּ אֲרֵי זַבְּנָנָא וַאֲכַל אַף מֵיכַל יָת כַּסְפָּנָא:
@890 אֲרֵי כָל עוּתְרָא דִּי אַפְרֵשׁ יְיָ מֵאֲבוּנָא דִּילָנָא הוּא וְדִבְּנָנָא וּכְעַן כֹּל דִּי אֲמַר יְיָ לָךְ עִבֵד:
@891 וְקָם יַעֲקֹב וּנְטַל יָת בְּנוֹהִי וְיָת נְשׁוֹהִי עַל גַּמְלַיָּא:
@892 וּדְבַר יָת כָּל גֵּיתוֹהִי וְיָת כָּל קִנְיָנֵהּ דִּקְנָא גֵּיתֵי קִנְיָנֵהּ דִּי קְנָא בְּפַדַּן אֲרָם לְמֵיתֵי לְוַת יִצְחָק אֲבוּהִי לְאַרְעָא כְנָעַן:
@893 וְלָבָן אֲזַל לְמִגַּז יָת עָנֵהּ וּנְסִּבַת רָחֵל יָת צַלְמָנַיָּא דִּי לַאֲבוּהָא:
@894 וְכַסִּי יַעֲקֹב מִן לִבָּא דְלָבָן אֲרַמָּאָה עַל דְּלָא חַוִּי לֵהּ אֲרֵי אָזֵל הוּא:
@895 וַאֲזַלּ הוּא וְכָל דִּי לֵהּ וְקָם וַעֲבַר יָת פְּרָת וְשַׁוִּי יָת אַפּוֹהִי לְטוּרָא דְגִלְעָד:
@896 וְאִתְחַוָא לְלָבָן בְּיוֹמָא תְלִיתָאָה אֲרֵי אֲזַל יַעֲקֹב:
@897 וּדְבַר יָת אַחוּהִי עִמֵּהּ וּרְדַף בַּתְרוֹהִי מַהֲלַךְ שִׁבְעַת יוֹמִין וְאַדְבֵּק יָתֵהּ בְּטוּרָא דְגִלְעָד:
@898 וַאֲתָא מֵימָר מִן קֳדָם יְיָ לְוַת לָבָן אֲרַמָּאָה בְּחֵילְמָא דְּלֵילְיָא וַאֲמַר לֵהּ אִסְתַּמַּר לָךְ דִּילְמָא תְמַלֵּיל עִם יַעֲקֹב מִטַּב עַד בִּישׁ:
@899 וְאַדְבֵּיק לָבָן יָת יַעֲקֹב וְיַעֲקֹב פְּרַס יָת מַשְׁכְּנֵהּ בְּטוּרָא וְלָבָן אַשְׁרֵי יָת אֲחוֹהִי בְּטוּרָא דְגִלְעָד:
@900 וַאֲמַר לָבָן לְיַעֲקֹב מָה עֲבַדְתָּ וְכַסֵּיתָא מִנִּי וּדְבַרְתָּא יָת בְּנָתַי כְּשַׁבְיוֹת חַרְבָּא:
@901 לְמָה אִטְמַרְתָּ לְמֵיזַל וְכַסֵּיתָא מִנִּי וְלָא חַוֵּיתָא לִי וְשַׁלָּחִתָּךְ פּוֹן בְּחֶדְוָא וּבְתוּשְׁבְּחָן בְּתוּפִּין וּבְכִנָּרִין:
@902 וְלָא שְׁבַקְתַּנִּי לְנַשָּׁקָא לִבְנַי וְלִבְנָתָי כְּעַן אַסְכֶּלְתָּא לְמֶעְבָּד:
@903 אִית חֵילָא בִידִי לְמֶעְבַּד עִמְּכוֹן בִּישׁ וֵאלָהָא דַּאֲבוּכוֹן בְּרַמְשָׁא אֲמַר לִי לְמֵימַר אִסְתַּמַּר לָּךְ מִלְּמַלָּלָא עִם יַעֲקֹב מִטַּב עַד בִּישׁ:
@904 וּכְעַן מֵיזַל אֲזַלְתָּ אֲרֵי חַמָּדָא חַמֵדְתָּא לְבֵית אָבוּךְ לְמָה נְסִבְתָּא יָת דַּחַלְתִּי:
@905 וַאֲתֵיב יַעֲקֹב וַאֲמַר לְלָבָן אֲרֵי דְחֵילִית אֲרֵי אֲמָרִית דִּילְמָא תָנֵיס יָת בְּנָתָךְ מִנִּי:
@906 עִם (נ''י אֲתַר) דִּי תַשְׁכַּח יָת דַּחַלְתָּךְ לָא יִתְקַיַּם קֳדָם אֲחָנָא אִשְׁתְּמוֹדַע לָךְ מָה דְעִמִּי וְסַב לָךְ וְלָא יְדַע יַעֲקֹב אֲרֵי רָחֵל נְסִיבָתְהוֹן:
@907 וְעַל לָבָן בְּמַשְׁכְּנָא דְיַעֲקֹב וּבְמַשְׁכְּנָא דְלֵאָה וּבְמַשְׁכְּנָא דְּתַרְתֵּין לְחֵינָתָא וְלָא אַשְׁכַּח וּנְפַק מִמַּשְׁכְּנָא דְלֵאָה וְעַל בְּמַשְׁכְּנָא דְרָחֵל:
@908 וְרָחֵל נְסִיבַת יָת צַלְמָנַיָּא וְשַׁוִּתִּנּוּן בַּעֲבִיטָא דְגַמְלָא וִיתִיבַת עֲלֵיהוֹן וּמַשִּׁישׁ לָבָן יָת כָּל מַשְׁכְּנָא וְלָא אַשְׁכָּח:
@909 וַאֲמֶרֶת לַאֲבוּהָא לָא יִתְקֵף בְּעֵינֵי רִבּוֹנִי אֲרֵי לָא אִכּוּל לְמֵיקַם מִן קֳדָמָךְ אֲרֵי אֹרַח נְשִׁין לִי וּבְלַשׁ וְלָא אַשְׁכַּח יָת צַלְמָנַיָּא:
@910 וּתְקֵיף לְיַעֲקֹב וּנְצָא עִם לָבָן וַאֲתֵיב יַעֲקֹב וַאֲמַר לְלָבָן מַה חוֹבִי מַה סוּרְחָנִי אֲרֵי רְדַפְתָּא בַּתְרָי:
@911 אֲרֵי מַשִּׁשְׁתָּא יָת כָּל מָנַי מָה אַשְׁכַּחְתָּא מִכֹּל מָנֵי בֵיתָךְ שַׁוִּי הָכָא קֳדָם אַחַי וְאַחָיךְ וְיוֹכִיחוּן בֵּין תַּרְוָנָא:
@912 דְּנַן עֶסְרִין שְׁנִין אֲנָא עִמָּךְ רְחֵלָיךְ וְעִזָּיךְ לָא אַתְכִּילוּ וְדִכְרֵי עָנָךְ לָא אֲכָלִית:
@913 דִּתְבִירָא לָא אַיְתֵיתִי לְוָתָךְ דַּהֲוַת שָׁגְיָא מִמִּנְיָנָא מִנִּי אַתְּ בָּעֵי לַהּ נְטָרִית בִּימָמָא וּנְטָּרִית בְּלֵילְיָא:
@914 הֲוֵיתִי בִימָמָא אֲכַלְנִי שַׁרְבָא וּגְלִידָא (הֲוָה) נָחֵית עֲלַי בְּלֵילְיָא וּנְדַד שִׁנְתִּי מֵעֵינָי:
@915 דְּנַן לִי עֶשְׂרִין שְׁנִין בְּבֵיתָךְ פְּלָחִתָּךְ אַרְבַּע עֶשְׂרֵי שְׁנִין בְּתַרְתֵּין בְּנָתָךְ וְשִׁתְּ שְׁנִין בְּעָנָךְ וְאַשְׁנֵיתָא יָת אַגְרִי עֲשַׂר זִמְנִין:
@916 אִילוּלָא פוֹן אֱלָהֵהּ דְּאַבָּא אֱלָהֵהּ דְּאַבְרָהָם וּדְדָחִיל לֵהּ יִצְחָק הֲוָה בְּסַעְדִּי אֲרֵי כְעַן רֵיקָן שִׁלַּחְתָּנִי יָת עַמְלִי וְיָת לֵיאוּת יְדַי גְלֵי קֳדָם יְיָ וְאוֹכַח בְּרַמְשָׁא:
@917 וַאֲתֵיב לָבָן וַאֲמַר לְיַעֲקֹב בְּנָתָא בְּנָתַי וּבְנַיָּא בְנַי וְעָנָא עָנִי וְכֹל דִּי אַתְּ חָזֵי דִּילִי הוּא וְלִבְנָתַי מָה אֶעְבֵּיד לְאִלֵּין יוֹמָא דֵין אוֹ לִבְנֵיהֶן דִּילִידָן:
@918 וּכְעַן אֱתָא נִגְזַר קְיָם אֲנָא וְאָתְּ וִיהֵי לְסָהִיד בֵּינִי וּבֵינָךְ:
@919 וּנְסִיב יַעֲקֹב אַבְנָא וּזְקָפַהּ קָמָא:
@920 וַאֲמַר יַעֲקֹב לַאֲחוֹהִי לְקוּטוּ אַבְנִין וּנְסִיבוּ אַבְנִין וַעֲבָדוּ דְּגוֹרָא וַאֲכָלוּ תַמָּן עַל דְּגוֹרָא:
@921 וּקְרָא לֵהּ לָבָן יְגַר שָׂהֲדוּתָא וְיַעֲקֹב קְרָא לֵהּ גַּלְעֵד:
@922 וַאֲמַר לָבָן דְּגוֹרָא הָדֵין סָהִיד בֵּינִי וּבֵינָךְ יוֹמָא דֵּין עַל כֵּן קְרָא שְׁמֵהּ גַּלְעֵד:
@923 וְסָכוּתָא דִּי אֲמַר יִסֶּךְ מֵימְרָא דַּיְיָ בֵּינִי וּבֵינָךְ אֲרֵי נִתכַּסִּי גּבַר מֵחַבְרֵהּ:
@924 אִם תְּעַנֵּי יָת בְּנָתַי וְאִם תִּסַּב נְשִׁין עַל בְּנָתַי לֵית אֱנַשׁ עִמָּנָא חָזֵי מֵימְרָא דַּיְיָ סָהִיד בֵּינִי וּבֵינָךְ:
@925 וַאֲמַר לָבָן לְיַעֲקֹב הָא דְּגוֹרָא הָדֵין וְהָא קַמְתָא דִּי אֲקֵימִית בֵּינִי וּבֵינָךְ:
@926 סָהִיד דְּגוֹרָא הָדֵין וְסָהֲדָא קָמָא אִם אֲנָא לָא אֶעְבַּר לְוָתָךְ יָת דְּגוֹרָא הָדֵין וְאִם אַתְּ לָא תֵעִבַּר לְוָתִי יָת דְּגוֹרָא הָדֵין וְיָת קַמְתָא הָדָא לְבִישׁוּ:
@927 אֱלָהֵהּ דְּאַבְרָהָם וֵאֱלָהֵהּ דְּנָחוֹר יְדוּנוּן בֵּינָנָא אֱלָהֵהּ דַּאֲבוּהוֹן וְקַיֵּים יַעֲקֹב בִּדְדָחִיל לֵהּ אֲבוּהִי יִצְחָק:
@928 וּנְכֵס יַעֲקֹב נִכְסָתָא בְּטּוּרָא וּקְרָא לַאֲחוֹהִי לְמֵיכַל לַחְמָא וַאֲכָלוּ לַחְמָא וּבִיתוּ בְּטוּרָא:
@929 וְאַקְדֵּם לָבָן בְּצַפְרָא וּנְשַׁק לִבְנוֹהִי וְלִבְנָתֵהּ וּבָרִיךְ יָתְהֵן וַאֲזַל וְתַב לָבָן לְאַתְרֵהּ:
@930 וְיַעֲקֹב אֲזָל לְאָרְחֵהּ וַעֲרָעוּ בֵהּ מַלְאָכַיָּא דַּיְיָ:
@931 וַאֲמַר יַעֲקֹב כַּד חֲזָנוּן מַשְׁרִיתָא מִן קֳדָם יְיָ דֵּין וּקְרָא שְׁמָא דְאַתְרָא הַהוּא מַחֲנָיִם: פפפ:
@932 וּשְׁלַח יַעֲקֹב אִזְגַּדִּין קֳדָמוֹהִי לְוַת עֵשָׂו אֲחוּהִי לְאַרְעָא דְשֵׂעִיר לַחֲקַל דְאֱדוֹם:
@933 וּפַקִּיד יָתְהוֹן לְמֵימָר כְּדֵין תֵּימְרוּן לְרִבּוֹנִי לְעֵשָׂו כִּדְנַן אֲמַר עַבְדָּךְ יַעֲקֹב עִם לָבָן דָּרִית וְאוֹחָרִית עַד כְּעָן:
@934 וַהֲוָה לִי תּוֹרִין וַחֲמָרִין עָאן וְעַבְדִּין וְאַמְהָן וּשְׁלָחִית לְחַוָּאָה לְרִבּוֹנִי לְאַשְׁכָּחָא רַחֲמִין בְּעֵינָךְ:
@935 וְתָבוּ אִזְגַּדַּיָּא לְוַת יַעֲקֹב לְמֵימָר אֲתֵינָא לְוַת אָחוּךְ לְוַת עֵשָׂו וְאַף אָתֵי לְקַדָּמוּתָךְ וְאַרְבַּע מְאָה גַּבְרָא עִמֵּהּ:
@936 וּדְחִיל יַעֲקֹב לַחֲדָא וַעֲקַת לֵהּ וּפַלִּיג יָת עַמָּא דִּי עִמֵּהּ וְיָת עָנָא וְיָת תּוֹרֵי וְגַמְלַיָּא לִ:תרֵין מַשִּׁירְיָן:
@937 וַאֲמַר אִם יֵיתֵי עֵשָׂו לְמַשְׁרִיתָא חֲדָא וְיִמְחִנֵּהּ וִיהֵי (נ''י וְיִמְחֵנַּהּ וּתְהִי) מַשְׁרִיתָא דְאִשְׁתָּאַר לְשֵׁיזָבָא:
@938 וַאֲמַר יַעֲקֹב אֱלָהֵהּ דְּאַבָּא אַבְרָהָם וֵאֱלָהֵהּ דְּאַבָּא יִצְחָק יְיָ דִּי אֲמַר לִי תּוּב לְאַרְעָךְ וּלְיַלָּדוּתָךְ וְאוֹטֵיב עִמָּךְ:
@939 זְעִירָן זָכוּתַי מִכֹּל חִסְדִּן וּמִכָּל טַבְוָן דִּי עֲבַדְתָּ עִם עַבְדָּךְ אֲרֵי יְחִידִי עֲבָרִית יָת יַרְדְּנָא הָדֵין וּכְעַן הֲוֵיתִי לִתְרֵין (נ''י לְתַרְתֵּין) מַשִּׁרְיָן:
@940 שֵׁזַבְנִי כְעַן מִידָא דְאָחִי מִידָא דְעֵשָׁו אֲרֵי דַחֵל אֲנָא מִנֵּהּ דִּילְמָא יֵיתֵי וְיִמְחִנַּנִי אִמָּא עַל בְּנַיָּא:
@941 וְאַתְּ אֲמַרְתָּ אוֹטָבָא אוֹטִיב עִמָּךְ וֶאֱשַׁוֵּי יָת בְּנָיךְ סַגִּיאִין כְּחַלָּא דְיַמָּא דִּי לָא יִתִּמְנוּן מִסַּגִּי:
@942 וּבָת תַּמָּן בְּלֵילְיָא הַהוּא וּנְסִיב מִן דְּאַיְתִי בִּידֵהּ תִּקְרֻבְתָּא לְעֵשָׂו אֲחוּהִי:
@943 עִזֵּי מָאתָן וּתְיָשַׁיָא עֶסְרִין רְחֵלִין מָאתָן וְדִכְרִין עֶסְרִין:
@944 גַּמְלֵי מֶנְקָתָא וּבְנֵיהוֹן תְּלָתִין תּוֹרְתָא אַרְבְּעִין וְתוֹרֵי עַסְרָא אַתְנָן עֶסְרִין וְעִירֵי עַסְרָא:
@945 וִיהַב בְּיַד עַבְדּוֹהִי עֶדְרָא עֶדְרָא בִּלְחוֹדוֹהִי וַאֲמַר לְעַבְדּוֹהִי עִבָּרוּ קֳדָמַי וּרְוָחָא תְּשַׁווּן בֵּין עֶדְרָא וּבֵין עֶדְרָא:
@946 וּפַקִד יָת קַדְמָאָה לְמֵימָר אֲרֵי יְעַרְעִנָּךְ עֵשָׂו אָחִי וּשְׁאֵלִנָּךְ לְמֵימָר לְמָן אַתְּ וּלְאָן אַתְּ אָזֵל וּלְמָן אִלֵּין דִּקֳדָמָךְ:
@947 וְתֵימַר לְעַבְדָךְ לְיַעֲקֹב תִּקְרֻבְתָּא הִיא דִמְשַׁלְּחָא לְרִבּוֹנִי לְעֵשָׂו וְהָא אַף הוּא אָתֵי בַתְרָנָא:
@948 וּפַקִּיד אַף יָת תִּנְיָנָא אַף יָת תְּלִיתָאָה אַף יָת כָּל דְּאָזְלִין בָּתַר עֲדָרַיָּא לְמֵימָר כְּפִתְגָּמָא הָדֵין תְּמַלְּלוּן עִם עֵשָׂו כַּד תַּשְׁכְּחוּן יָתֵהּ:
@949 וְתֵימְרוּן אַף הָא עַבְדָּךְ יַעֲקֹב אָתֵי בַתְרָנָא אֲרֵי אֲמַר אַנְחִנֵּהּ לְרוּגְזֵהּ בְּתִקְרֻבְתָּא דְּאָזְלַת קֳדָמַי וּבָתַר כֵּן אֶחֱזֵי אַפּוֹהִי מָאִים יִסַּב אַפָּי:
@950 וַעֲבָרַת תִּקְרֻבְתָּא עַל אַפּוֹהִי וְהוּא בָת בְּלֵילְיָא הַהוּא בְּמַשְׁרִיתָא:
@951 וְקָם בְּלֵילְיָא הוּא וּדְבַר יָת תַּרְתֵּין נְשׁוֹהִי וְיָת תַּרְתֵּין לְחֵינָתֵהּ וְיָת חַד עֲסַר בְּנוֹהִי וַעֲבַר יָת מַעֲבַר יוּבְקָא:
@952 וּדְבָרִנּוּן וְעַבָּרִנּוּן יָת נַחְלָא וְאַעְבַּר יָת דִּילֵהּ:
@953 וְאִשְׁתָּאַר יַעֲקֹב בִּלְחוֹדוֹהִי וְאִשְׁתַּדֵּל גַּבְרָא עִמֵּהּ עַד דִּסְלֵק צַפְרָא:
@954 וַחֲזָא אֲרֵי לָא יָכִיל לֵהּ וּקְרֵב בִּפְתֵי יַרְכֵּהּ וְזָע פְּתֵי יַרְכָּא דְיַעֲקֹב בְּאִשְׁתַּדָּלוּתֵהּ עִמֵּהּ:
@955 וַאֲמַר שַׁלְּחַנִּי אֲרֵי סְלִיק צַפְרָא וַאֲמַר לָא אֲשַׁלְחִנָךְ אֶלָּהֵין בֵּרַכְתָּנִי:
@956 וַאֲמַר לֵהּ מָה שְׁמָךְ וַאֲמַר יַעֲקֹב:
@957 וַאֲמַר לָא יַעֲקֹב יִתְאֲמַר עוֹד שְׁמָךְ אֶלָּהֵין יִשְׂרָאֵל אֲרֵי רַבְרְבַת קֳדָם יְיָ וְעִם גּוּבְרַיָּא וִיכָלְתָּא:
@958 וּשְׁאֵל יַעֲקֹב וַאֲמַר חַוִּי כְעַן שְׁמָךְ וַאֲמַר לְמָה דְנַן אַתְּ שָׁאֵל לִשְׁמִי וּבָרִיךְ יָתֵהּ תַּמָּן:
@959 וּקְרָא יַעֲקֹב שְׁמָא דְאַתְרָא פְּנִיאֵל אֲרֵי חֲזֵיתִי מַלְאָכַיָּא דַּיְיָ אַפִּין בְּאַפִּין וְאִשְׁתְּזָבַת נַפְשִׁי:
@960 וּדְנַח לֵהּ שִׁמְשָׁא כְּמָא דִּי עֲבַר יָת פְּנוּאֵל וְהוּא מַטְלַע עַל יַרְכֵּהּ:
@961 עַל כֵן לָא יֵיכְלוּן בְּנֵי יִשְׂרָאֵל יָת גִּידָא דְנַשְׁיָא דִּי עַל פְּתֵי יַרְכָּא עַד יוֹמָא הָדֵין אֲרֵי קְרֵיב בִּפְתֵי יַרְכָּא דְיַעֲקֹב בְּגִידָא דְנַשְׁיָא:
@962 וּזְקַף יַעֲקֹב עֵינוֹהִי וַחֲזָא וְהָא עֵשָׂו אֲתָא וְעִמֵּהּ אַרְבַּע מְאָה גֻּבְרִין וּפַלִּיג יָת בְּנַיָּא עַל לֵאָה וְעַל רָחֵל וְעַל תַּרְתֵּין לְחֵינָתָא:
@963 וְשַׁוִּי יָת לְחֵינָתָא וְיָת בְּנֵיהֶן קַדְמָאִין וְיָת לֵאָה וּבְנָהָא בַּתְרָאִין וְיָת רָחֵל וְיָת יוֹסֵף בַּתְרָאִין:
@964 וְהוּא עֲבַר קֳדָמֵיהוֹן וּסְגִיד עַל אַרְעָא שְׁבַע זִמְנִין עַד מִקְרְבֵהּ עַד (נ''י לְוַת) אֲחוּהִי:
@965 וּרְהַט עֵשָׂו לְקַדָּמוּתֵהּ וְגַפְּפֵהּ וּנְפַל עַל צַוְּארֵהּ וְנַשְׁקֵהּ וּבְכוֹ:
@966 וּזְקַף יָת עֵינוֹהִי וַחֲזָא יָת נְשַׁיָּא וְיָת בְּנַיָּא וַאֲמַר מָן אִלֵּין לָךְ וַאֲמַר בְּנַיָּא דִּי חַן יְיָ יָת עַבְדָּךְ:
@967 וּקְרִיבָן לְחֵינָתָא אִנוּן וּבְנֵיהֶן וּסְגִידוּ:
@968 וּקְרִיבָא אַף לֵאָה וּבְנָהָא וּסְגִידוּ וּבָתַר כֵּן קְרֵיב יוֹסֵף וְרָחֵל וּסְגִידוּ:
@969 וַאֲמַר מָן לָךְ כָּל מַשְׁרִיתָא הָדֵין דִּי עֲרָעִית וַאֲמַר לְאַשְׁכָּחָא רַחֲמִין בְּעֵינֵי רִבּוֹנִי:
@970 וַאֲמַר עֵשָׂו אִית לִי סַגִּי אָחִי אַצְלַח בְּדִילָךְ:
@971 וַאֲמַר יַעֲקֹב בְּבָעוּ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינָיךְ וּתְקַבֵּל תִּקְרֻבְתִּי מִן יְדִי אֲרֵי עַל כֵּן חֲזִתִּנּוּן לְאַפָּיךְ כְּחֵיזוּ אַפֵּי רַבְרְבַיָּא וְאִתְרְעֵית לִי:
@972 קַבֵּל כְּעַן יָת תִּקְרֻבְתִּי דְּאִתּוֹתִיאַת לָךְ אֲרֵי רַחִים עֲלַי (קֳדָם) יְיָ וַאֲרֵי אִית לִי כֹלָּא וְאַתְקֵף בֵּהּ וְקַבִּיל:
@973 וַאֲמַר נִטַל וְנֵהָךְ וְאֵיהַךְ לְקָבְלָךְ:
@974 וַאֲמַר לֵהּ רִבּוֹנִי יְדַע אֲרֵי יָנְקַיָּא רַכִּיכִין וְעָנָא וְתוֹרֵי מֵינִקְתָּא עָלָי וּדְחוֹקִנּוּן יוֹמָא חַד וִימוּתוּן כָּל עָנָא:
@975 יְעִבַּר כְּעַן רִבּוֹנִי קֳדָם עַבְדֵּהּ וַאֲנָא אֱדַבֵּר בְּנִיחַ לְרֶגֶל עוֹבַדְתָּא דִּי קֳדָמַי וּלְרֶגֶל יָנְקַיָּא עַד דִּי אֵעוֹל לְוַת רִבּוֹנִי לְשֵׂעִיר:
@976 וַאֲמַר עֵשָׂו אֶשְׁבּוֹק כְּעַן עִמָּךְ מִן עַמָּא דְּעִמִּי וַאֲמַר לְמָא דְנַן אַשְׁכַּח רַחֲמִין בְּעֵינֵי רִבּוֹנִי:
@977 וְתַב בְּיוֹמָא הַהוּא עֵשָׂו לְאָרְחֵהּ לְשֵׂעִיר:
@978 וְיַעֲקֹב נְטַל לְסֻכּוֹת וּבְנָא לֵהּ בֵּיתָא וְלִבְעִירֵהּ עֲבַד מְטַלָּן עַל כֵּן קְרָא שְׁמָא דְאַתְרָא סֻכּוֹת:
@979 וַאֲתָא יַעֲקֹב שְׁלִים קַרְתָּא דִּשְׁכֶם דִּי בְּאַרְעָא דִּכְנָעַן בְּמֵיתֵהּ מִפַּדַּן דַּאֲרָם וּשְׁרָא לָקֳבֵל (אַפֵּי) קַרְתָּא:
@980 וּזְבַן יָת אַחֲסָנַת חַקְלָא דִּי פְרַס תַּמָּן מַשְׁכְּנֵהּ מִידָא דִּבְנֵי חֲמוֹר אֲבוּהִי דִּשְׁכֶם בְּמֵאָה חוּרְפָן:
@981 וַאֲקֵם תַּמָּן מַדְבְּחָא וּפְלַח עֲלוֹהִי קֳדָם אֵל אֱלָהָא דְיִשְׂרָאֵל:
@982 וּנְפָקַת דִּינָה בַּת לֵאָה דִּי יְלִידַת לְיַעֲקֹב לְמֶחֱזֵי בִּבְנַת אַרְעָא:
@983 וַחֲזָא יָתַהּ שְׁכֶם בַּר חֲמוֹר חִוָאָה רַבָּא דְאַרְעָא וּדְבַר יָתַהּ וּשְׁכִיב יָתַהּ וְעַנְיַהּ:
@984 וְאִתְרְעִיאַת נַפְשֵׁהּ בְּדִינָה בַּת יַעֲקֹב וּרְחֵים יָת עוּלֶמְתָּא וּמַלִּיל עַל לִבָּא דְעוּלֶמְתָּא:
@985 וַאֲמַר שְׁכֶם לַחֲמוֹר אֲבוּהִי לְמֵימָר סַב לִי יָת עוּלֶמְתָּא הָדָא לְאִנְתּוּ:
@986 וְיַעֲקֹב שְׁמַע אֲרֵי סָאֵיב יָת דִּינָה בְרַתֵּהּ וּבְנוֹהִי הֲווֹ עִם גֵּיתוֹהִי בְּחַקְלָא וְשָׁתִיק יַעֲקֹב עַד מֵיתֵיהוֹן:
@987 וּנְפַק חֲמוֹר אֲבוּהִי דִּשְׁכֶם לְוַת יַעֲקֹב לְמַלָּלָא עִמֵּהּ:
@988 וּבְנֵי יַעֲקֹב עַלּוּ מִן חַקְלָא כַּד שְׁמָעוּ וְאִתְנְסִיסוּ גֻּבְרַיָּא וּתְקֵיף לְהוֹן לַחֲדָא אֲרֵי קְלָנָא עֲבַד בְּיִשְׂרָאֵל לְמִשְׁכַּב עִם בַּת יַעֲקֹב וְכֵן לָא כָשַׁר לְאִתְעֲבָדָא:
@989 וּמַלִּיל חֲמוֹר עִמְּהוֹן לְמֵימָר שְׁכֶם בְּרִי אִתְרְעִיאַת נַפְשֵׁהּ בִּבְרַתְּכוֹן הָבוּ כְעַן יָתַהּ לֵהּ לְאִנְתּוּ:
@990 וְתִתְחַתְּנוּן בָּנָא בְּנָתֵיכוֹן תִּתְּנוּן לָנָא וְיָת בְּנָתָנָא תִּסְבוּן לְכוֹן:
@991 וְעִמָּנָא תֵּתְבוּן וְאַרְעָא תְּהֵי קֳדָמֵיכוֹן תִּיבוּ וְעֲבִידוּ בַהּ סְחוֹרְתָּא וְאַחֲסִינוּ בַּהּ:
@992 וַאֲמַר שְׁכֶם לַאֲבוּהָא וּלְאַחָהָא אַשְׁכַּח רַחֲמִין בְּעֵינֵיכוֹן וְדִי תֵימְרוּן לִי אֶתֵּן:
@993 אַסְגוּ עָלַי לַחֲדָא מוֹהֲרִין וּמַתְּנָן וְאֶתֵּן כְּמָא דִּי תֵימְרוּן לִי וְהָבוּ לִי יָת עוּלֶמְתָּא:לאִנְתּוּ:
@994 וַאֲתִיבוּ בְנֵי יַעֲקֹב יָת שְׁכֶם וְיָת חֲמוֹר אֲבוּהִי בְּחָכְמְתָא וּמַלִּילוּ דִּי סָאֵב יָת דִּינָה אֲחָתְהוֹן:
@995 וַאֲמָרוּ לְהוֹן לָא נִכּוּל לְמֶעְבַּד פִּתְגָּמָא הָדֵין לְמִתַּן יָת אֲחָתָנָא לִגְבַר דִּי לֵיהּ עָרְלְתָא אֲרֵי חִסּוּדָא הִיא לָנָא:
@996 בְּרַם בְּדָא נִתְפֵּס לְכוֹן אִם תֶּהֱווֹן כְּוָתָנָא לְמִגְזַר לְכוֹן כָּל דְּכוּרָא:
@997 וְנִתַּן יָת בְּנָתָנָא לְכוֹן וְיָת בְּנָתֵיכוֹן נִסַּב לָנָא וְנִתּוּב עִמְּכוֹן וְנֵיהֵי לְעַמָּא חָד:
@998 וְאִם לָא תְקַבְּלוּן מִנָּנָא לְמִגְזָר וּנְדַבֵּר יָת בְּרַתָּנָא וְנֵזֵיל:
@999 וּשְׁפָרוּ פִּתְגָּמֵיהוֹן בְּעֵינֵי חֲמוֹר וּבְעֵינֵי שְׁכֶם בַּר חֲמוֹר:
@1000 וְלָא אוֹחַר עוּלֵימָא לְמֶעְבַּד פִּתְגָּמָא אֲרֵי אִתְרְעִי בְּבַת יַעֲקֹב וְהוּא יַקִּיר מִכֹּל בֵּית אֲבוּהִי:
@1001 וַאֲתָא חֲמוֹר וּשְׁכֶם בְּרֵהּ לִתְרַע קַרְתְּהוֹן וּמַלִּילוּ עִם אֲנָשֵׁי קַרְתְּהוֹן לְמֵימָר:
@1002 גֻּבְרַיָּא הָאִלֵּין שָׁלְמִין אִנּוּן עִמָּנָא וִיתִיבוּן בְּאַרְעָא וְיַעְבְּדוּן בַּהּ סְחוֹרְתָא וְאַרְעָא הָא פְתָיוּת יְדִין קֳדָמֵיהוֹן יָת בְּנָתֵיהוֹן נִסַּב לָנָא לִנְשִׁין וְיָת בְּנָתָנָא נִתֵּן לְהוֹן:
@1003 בְּרַם בְּדָא יִתָּפְסוּן לָנָא גּוּבְרַיָּא לְמִתַּב עִמָּנָא לְמֶהֱוֵי לְעַמָּא חָד בְּמִגְזַר לָנָא כָּל דְּכוּרָא כְּמָא דִּי אִנּוּן גְּזִירִין:
@1004 גֵּיתֵיהוֹן וְקִנְיָנְהוֹן וְכָל בְּעִירְהוֹן הֲלָא דִּילָנָא אִנּוּן בְּרַם נִתְפֵּס לְהוֹן וִיתִיבוּן עִמָּנָא:
@1005 וְקַבִּילוּ מִן חֲמוֹר וּמִן שְׁכֶם בְּרֵהּ כָּל נָפְקֵי תְּרַע קַרְתֵּהּ וּגְזָרוּ כָּל דְּכוּרָא כָּל נָפְקֵי תְּרַע קַרְתֵּהּ:
@1006 וַהֲוָה בְיוֹמָא תְלִיתָאָה כַּד תְּקִיפוּ עֲלֵיהוֹן כֵּאבֵיהוֹן וּנְסִיבוּ תְרֵין בְּנֵי יַעֲקֹב שִׁמְעוֹן וְלֵוִי אֲחֵי דִּינָה גְּבַר חַרְבֵּהּ וְעַלּוּ עַל קַרְתָּא דְּיָתְבוּן לְרָחֲצָן וּקְטָלוּ כָּל דְּכוּרָא:
@1007 וְיָת חֲמוֹר וְיָת שְׁכֶם בְּרֵהּ קְטָלוּ לְפִתְגַּם דְּחָרֶב וּדְבָרוּ יָת דִּינָה מִבֵּית שְׁכֶם וּנְפָקוּ:
@1008 בְּנֵי יַעֲקֹב עַלּוּ לְחַלָּצָא קָטִילַיָּא וּבְזוֹ קַרְתָּא דִּי סָאִיבוּ אֲחָתְהוֹן:
@1009 יָת עָנְהוֹן וְיָת תּוֹרְהוֹן וְיָת חֲמָרֵיהוֹן וְיָת דִּי בְקַרְתָּא וְיָת דִּי בְחַקְלָא בְּזוֹ:
@1010 וְיָת כָּל נִכְסֵיהוֹן וְיָת כָּל טַפְלְהוֹן וְיָת נְשֵׁיהוֹן שְׁבוֹ וּבְזוֹ וְיָת כָּל דִּי בְבֵיתָא:
@1011 וַאֲמַר יַעֲקֹב לְשִׁמְעוֹן וּלְלֵוִי עֲכַרְתּוּן יָתִי לְמִתַּן דְּבָבוּ בֵּינָנָא וּבֵין יָתְבֵי אַרְעָא בִּכְנַעֲנָאָה וּבַפְּרִזָּאָה וַאֲנָא עַם דְּמִנְיַן וְיִתְכַּנְשׁוּן עֲלַי וְיִמְחִנּוּנִי וְאֶשְׁתֵּצֵי אֲנָא וְאֱנַשׁ בֵּיתִי:
@1012 וַאֲמָרוּ הַכְנָפְקַת בָּרָא יִתְעֲבֵד (נ''א יַעְבֵּד יָת אַחָתָנָא) לַאֲחָתָנָא:
@1013 וַאֲמַר יְיָ לְיַעֲקֹב קוּם סַק לְבֵית אֵל וְתִיב תַּמָן וְעִבֵּד תַּמָן מַדְבְּחָא לֵאלָהָא דְאִתְגְלִי לָךְ בְּמֵעִרְקָךְ מִן קֳדָם עֵשָׂו אָחוּךְ:
@1014 וַאֲמַר יַעֲקֹב לֶאֱנַשׁ בֵּיתֵהּ וּלְכֹל דִּי עִמֵּהּ אַעְדוּ יָת טַעֲוַת עַמְמַיָּא דִי בֵינֵיכוֹן וְאִדַכּוּ וְשַׁנּוּ כְּסוּתְכוֹן:
@1015 וְנֵקוֹם וְנִסַּק לְבֵית אֵל וְאֶעְבֵּד תַּמָּן מַדְבְּחָא לֵאלָהָא דְקַבִּיל צְלוֹתִי בְּיוֹמָא דְעַקְתִי וַהֲוָה מֵימְרֵהּ בְּסַעְדִי בְּאָרְחָא דִי אֲזָלִית:
@1016 וִיהָבוּ לְיַעֲקֹב יָת כָּל טַעֲוַת עַמְמַיָּא דִי בִידֵיהוֹן וְיָת קָדָשַׁיָּא דִי בְאֻדְנֵיהוֹן וְטַּמַּר יָתְהוֹן יַעֲקֹב תְּחוֹת בָּטְמָא דִי עִם שְׁכֶם:
@1017 וּנְטָלוּ וַהֲוַת דַּחֲלָא דַיְיָ עַל עַמְמַיָא דִי בְּקִרְוֵי סַחֲרָנֵיהוֹן וְלָא רְדָפוּ בָּתַר בְּנֵי יַעֲקֹב:
@1018 וַאֲתָא יַעֲקֹב לְלוּז דִּי בְאַרְעָא דִכְנַעַן הִיא בֵּית אֵל הוּא וְכָל עַמָּא דִי עִמֵּהּ:
@1019 וּבְנָא תַמָּן מַדְבְּחָא וּקְרָא לְאַתְרָא אֵל בֵּית אֵל אֲרֵי תַמָּן אִתְגְלֵי לֵהּ יְיָ בְּמֵעִרְקֵהּ מִן קֳדָם אָחוּהִי:
@1020 וּמִיתַת דְּבוֹרָה מֵנִקְתָּא דְרִבְקָה וְאִתְקְבָרַת מִלְרַע לְבֵית אֵל בְּשִׁפּוֹלֵי מֵישְׁרָא וּקְרָא שְׁמֵּהּ מֵישַׁר בָּכִיתָא:
@1021 וְאִתְגְלִי יְיָ לְיַעֲקֹב עוֹד בְּמֵיתוֹהִי מִפַּדַן אֲרָם וּבָרִיךְ יָתֵהּ:
@1022 וַאֲמַר לֵהּ יְיָ שְׁמָךְ יַעֲקֹב לָא יִתְקְרֵי שְׁמָךְ עוֹד יַעֲקֹב אֶלָהֵין יִשְׂרָאֵל יְהֵא שְׁמָךְ וּקְרָא יָת שְׁמֵהּ יִשְׂרָאֵל:
@1023 וַאֲמַר לֵהּ יְיָ אֲנָא אֵל שַׁדַּי פּוּשׁ וּסְגֵי עַם וְכִנְשַׁת שִׁבְטִּין יְהֵא מִנָּךְ וּמַלְכִין דְשַׁלִּיטִין בְּעַמְמַיָּא מִנָּךְ יִפְקוּן:
@1024 וְיָת אַרְעָא דִי יְהָבִית לְאַבְרָהָם וּלְיִצְחָק לָךְ אֶתְּנִנַּהּ וְלִבְנָיךְ בַּתְרָךְ אֶתֵּן יָת אַרְעָא:
@1025 וְאִסְתַּלַּק מֵעִלָּוֹהִי יְקָרָא דַיְיָ בְּאַתְרָא דִי מַלֵּיל עִמֵּהּ:
@1026 וַאֲקֵם יַעֲקֹב קַמְתָא בְּאַתְרָא דִי מַלִּיל עִמֵּהּ קָמַת אַבְנָא וְאַסִּיךְ עֲלַהּ נִסּוּכִין וַאֲרִיק עֲלַהּ מִשְׁחָא:
@1027 וּקְרָא יַעֲקֹב יָת שְׁמָא דְאַתְרָא דִי מַלִּיל עִמֵּהּ תַּמָּן יְיָ בֵּית אֵל:
@1028 וּנְטָלוּ מִבֵּית אֵל וַהֲוָה עוֹד כְּרוּבַת אַרְעָא לְמֵיעַל לְאֶפְרָת וִילִידַת רָחֵל וְקַשִׁיאַת בְּמֵילְדַהּ:
@1029 וַהֲוָה בְקַשְׁיוּתַהּ בְּמֵילְדַהּ וַאֲמֶרֶת לַהּ חָיְתָא לָא תִדְחֲלִי אֲרֵי אַף דֵּין לִיךְ בָּר:
@1030 וַהֲוָה בְּמִפַּק נַפְשַׁהּ אֲרֵי מִיתַת (נ''י מַיְתָא) וּקְרַת שְׁמֵהּ בַּר דְוָי וַאֲבוּהִי קְרָא לֵהּ בִּנְיָמִין:
@1031 וּמִיתַת רָחֵל וְאִתְקְבָרַת בְּאֹרַח אֶפְרָת הִיא בֵּית לָחֶם:
@1032 וַאֲקֵים יַעֲקֹב קַמְתָא עַל קְבֻרְתַּהּ הִיא קָמַת קְבֻרְתָּא דְרָחֵל עַד יוֹמָא דֵין:
@1033 וּנְטַל יִשְׂרָאֵל וּפְרַס מַשְׁכְּנֵהּ מִלְהַלָא לְמִגְדְלָא דְעֵדֶר:
@1034 וַהֲוָה כַּד שְׁרָא יִשְׂרָאֵל בְּאַרְעָא הַהִיא וַאֲזַל רְאוּבֵן וּשְׁכִיב עִם בִּלְהָה לְחֵינָתָא דַאֲבוּהִי וּשְׁמַע יִשְׂרָאֵל וַהֲווֹ בְנֵי יַעֲקֹב תְּרֵי עֲסַר:
@1035 בְּנֵי לֵאָה בּוּכְרָא דְיַעֲקֹב רְאוּבֵן וְשִׁמְעוֹן וְלֵוִי וִיהוּדָה וְיִשָׂשׂכָר וּזְבֻלוּן:
@1036 בְּנֵי רָחֵל יוֹסֵף וּבִנְיָמִן:
@1037 וּבְנֵי בִלְהָה אַמְתָא דְרָחֵל דָּן וְנַפְתָּלִי:
@1038 וּבְנֵי זִלְפָּה אַמְתָא דְלֵאָה גָּד וְאָשֵׁר אִלֵּין בְּנֵי יַעֲקֹב דִּי אִתְיְלִידוּ לֵהּ בְּפַדַן אֲרָם:
@1039 וַאֲתָא יַעֲקֹב לְוַת יִצְחָק אֲבוּהִי מַמְרֵא קִרְיַת אַרְבַּע הִיא חֶבְרוֹן דִּי דָר תַּמָּן אַבְרָהָם וְיִצְחָק:
@1040 וַהֲווֹ יוֹמֵי יִצְחָק מְאָה וּתְמָנָן שְׁנִין:
@1041 וְאִתְנְגִיד יִצְחָק וּמִית וְאִתְכְּנִישׁ לְעַמֵהּ סִיב וּשְׂבַע יוֹמִין וּקְבָרוּ יָתֵהּ עֵשָׂו וְיַעֲקֹב בְּנוֹהִי:
@1042 וְאִלֵּין תּוּלְדַת עֵשָׂו הוּא אֱדוֹם:
@1043 עֵשָׂו נְסִיב יָת נְשׁוֹהִי מִבְּנַת כְּנָעַן יָת עָדָה בַּת אֵילוֹן חִתָּאָה וְיָת אָהֳלִיבָמָה בַּת עֲנָה בַּת צִבְעוֹן חִוָאָה:
@1044 וְיָת בָּשְׂמַת בַּת יִשְׁמָעֵאל אֲחָתֵהּ דִנְבָיוֹת:
@1045 וִילִידַת עָדָה לְעֵשָׂו יָת אֱלִיפָז וּבָשְׂמַת יְלִידַת יָת רְעוּאֵל:
@1046 וְאָהֳלִיבָמָה יְלִידַת יָת יְעוּשׁ וְיָת יַעְלָם וְיָת קֹרַח אִלֵּין בְּנֵי עֵשָׂו דִי אִתְיְלִידוּ לֵהּ בְּאַרְעָא דִכְנָעַן:
@1047 וּדְבַר עֵשָׂו יָת נְשׁוֹהִי וְיָת בְּנוֹהִי וְיָת בְּנָתֵהּ וְיָת כָּל נַפְשַׁת בֵּיתֵהּ וְיָת גֵּיתוֹהִי וְיָת כָּל בְּעִירֵהּ וְיָת כָּל קִנְיָנֵהּ דִי קְנָא בְּאַרְעָא דִכְנָעַן וַאֲזַל לְאַרְעָא אוֹחֲרִי מִן קֳדָם יַעֲקֹב אָחוּהִי:
@1048 אֲרֵי הֲוָה קִנְיָנְהוֹן סַגִּי מִלְמִתַּב כַּחֲדָא וְלָא יְכִילַת אֲרַע תּוֹתָבוּתְהוֹן לְסוֹבָרָא יָתְהוֹן מִן קֳדָם גֵּיתֵיהוֹן:
@1049 וִיתֵיב עֵשָׂו בְּטוּרָא דְשֵׂעִיר עֵשָׂו הוּא אֱדוֹם:
@1050 וְאִלֵּין תּוּלְדַת עֵשָׂו אֲבוּהוֹן דֶאֱדוֹמָאֵי בְּטוּרָא דְשֵׂעִיר:
@1051 אִלֵּין שְׁמָהַת בְּנֵי עֵשָׂו אֱלִיפַז בַּר עָדָה אִתַּת עֵשָׂו רְעוּאֵל בַּר בָּשְׂמַת אִתַּת עֵשָׂו:
@1052 וַהֲווֹ בְּנֵי אֱלִיפָז תֵּימָן אוֹמָר צְפוֹ וְגַעְתָּם וּקְנַז:
@1053 וְתִמְנַע הֲוַת לְחֵינָתָא לֶאֱלִיפַז בַּר עֵשָׂו וִילִידַת לֶאֱלִיפַז יָת עֲמָלֵק אִלֵּין בְּנֵי עָדָה אִתַּת עֵשָׂו:
@1054 וְאִלֵּין בְּנֵי רְעוּאֵל נַחַת וָזֶרַח שַׁמָּה וּמִזָה אִלֵּין הֲווֹ בְּנֵי בָשְׂמַת אִתַּת עֵשָׂו:
@1055 וְאִלֵּין הֲווֹ בְּנֵי אָהֳלִיבָמָה בַת עֲנָה בַּת צִבְעוֹן אִתַּת עֵשָׂו וִילִידַת לְעֵשָׂו יָת יְעוּשׁ וְיָת יַעְלָם וְיָת קֹרַח:
@1056 אִלֵּין רַבְרְבֵי בְנֵי עֵשָׂו בְּנֵי אֱלִיפַז בּוּכְרָא דְעֵשָׂו רַבָּא תֵּימָן רַבָּא אוֹמָר רַבָּא צְפוֹ רַבָּא קְנַז:
@1057 רַבָּא קֹרַח רַבָּא גַעְתָּם רַבָּא עֲמָלֵק אִלֵּין רַבְרְבֵי אֱלִיפַז בְּאַרְעָא דֶאֱדוֹם אִלֵּין בְּנֵי עָדָה:
@1058 וְאִלֵּין בְּנֵי רְעוּאֵל בַּר עֵשָׂו רַבָּא נַחַת רַבָּא זֶרַח רַבָּא שַׁמָה רַבָּא מִזָּה אִלֵּין רַבְרְבֵי רְעוּאֵל בְּאַרְעָא דֶאֱדוֹם אִלֵין בְּנֵי בָשְׂמַת אִתַּת עֵשָׂו:
@1059 וְאִלֵּין בְּנֵי אָהֳלִיבָמָה אִתַּת עֵשָׂו רַבָּא יְעוּשׁ רַבָּא יַעְלָם רַבָּא קֹרַח אִלֵּין רַבְרְבֵי אָהֳלִיבָמָה בַּת עֲנָה אִתַּת עֵשָׂו:
@1060 אִלֵּין בְּנֵי עֵשָׂו וְאִלֵּין רַבְרְבָנֵיהוֹן הוּא אֱדוֹם:
@1061 אִלֵּין בְּנֵי שֵׂעִיר חוֹרָאָה יָתְבֵי דְּאַרְעָא לוֹטָן וְשׁוֹבָל וְצִבְעוֹן וַעֲנָה:
@1062 וְדִישׁוֹן וְאֵצֶר וְדִישָׁן אִלֵּין רַבְרְבֵי חוֹרָאֵי בְּנֵי שֵׂעִיר בְּאַרְעָא דֶאֱדוֹם:
@1063 וַהֲווֹ בְנֵי לוֹטָן חוֹרִי וְהֵימָם וַאֲחָתֵהּ דְלוֹטָן תִּמְנָע:
@1064 וְאִלֵּין בְּנֵי שׁוֹבָל עַלְוָן וּמָנַחַת וְעֵיבָל שְׁפוֹ וְאוֹנָם:
@1065 וְאִלֵּין בְּנֵי צִבְעוֹן וְאַיָּה וַעֲנָה הוּא עֲנָה דִּי אַשְׁכַּח יָתּ גִּבָּרַיָּא בְּמַדְבְּרָא כַּד הֲוָה רָעֵי יָת חֲמָרַיָּא לְצִבְעוֹן אֲבוּהִי:
@1066 וְאִלֵּין בְּנֵי עֲנָה דִּשֹׁן וְאָהֳלִיבָמָה בַּת עֲנָה:
@1067 וְאִלֵּין בְּנֵי דִישָׁן חֶמְדָן וְאֶשְׁבָּן וְיִתְּרָן וּכְרָן:
@1068 אִלֵּין בְּנֵי אֵצֶר בִּלְהָן וְזַעֲוָן וַעֲקָן:
@1069 אִלֵּין בְּנֵי דִישָׁן עוּץ וַאֲרָן:
@1070 אִלֵּין רַבְרְבֵי חוֹרָאָה רַבָּא לוֹטָן רַבָּא שׁוֹבָל רַבָּא צִבְעוֹן רַבָּא עֲנָה:
@1071 רַבָּא דִּשֹׁן רַבָּא אֵצֶר רַבָּא דִישָׁן אִלֵּין רַבְרְבֵי חוֹרָאָה לְרַבְרְבָנֵיהוֹן בְּאַרְעָא דְשֵׂעִיר:
@1072 וְאִלֵּין מַלְכַיָּא דִי מְלִיכוּ בְּאַרְעָא דֶאֱדוֹם קֳדָם דִּי מְלַךְ מַלְכָּא לִבְנֵי יִשְׂרָאֵל:
@1073 וּמְלַךְ בֶּאֱדוֹם בֶּלַע בַּר בְּעוֹר וְשׁוּם קַרְתֵּהּ דִּנְהָבָה:
@1074 וּמִית בָּלַע וּמְלַךְ תְּחוֹתוֹהִי יוֹבָב בַּר זֶרַח מִבָּצְרָה:
@1075 וּמִית יוֹבָב וּמְלַךְ תְּחוֹתוֹהִי חֻשָׁם מֵאַרְעָא דָרוֹמָא:
@1076 וּמִית חֻשָׁם וּמְלַךְ תְּחוֹתוֹהִי הֲדַד בַּר בְּדַד דִקְטִיל יָת מִדְיָנָאֵי בְּחַקְלָא דְמוֹאָב וְשׁוּם קַרְתֵּהּ עֲוִית:
@1077 וּמִית הֲדָד וּמְלַךְ תְּחוֹתוֹהִי שַׂמְלָה מִמַשְׂרֵקָה:
@1078 וּמִית שַׂמְלָה וּמְלַךְ תְּחוֹתוֹהִי שָׁאוּל מֵרְחוֹבוֹת דְעַל פְּרָת:
@1079 וּמִית שָׁאוּל וּמְלַךְ תְּחוֹתוֹהִי בַּעַל חָנָן בַּר עַכְבּוֹר:
@1080 וּמִית בַּעַל חָנָן בַּר עַכְבּוֹר וּמְלַךְ תְּחוֹתוֹהִי הֲדַר וְשׁוּם קַרְתֵּהּ פָּעוּ וְשׁוּם אִתְּתֵהּ מְהֵיטַבְאֵל בַּת מַטְּרֵד בַת מְצָרֵף דַּהֲבָא:
@1081 וְאִלֵּין שְׁמָהַת רַבְרְבֵי עֵשָׂו לְזַרְעֲיָתְהוֹן לְאַתְרֵיהוֹן בִּשְׁמָהַתְהוֹן רַבָּא תִמְנָע רַבָּא עַלְוָה רַבָּא יְתֵת:
@1082 רַבָּא אָהֳלִיבָמָה רַבָּא אֵלָה רַבָּא פִּינֹן:
@1083 רַבָּא קְנַז רַבָּא תֵימָן רַבָּא מִבְצָר:
@1084 רַבָּא מַגְדִיאֵל רַבָּא עִירָם אִלֵּין רַבְרְבֵי אֱדוֹם לְמוֹתְבָנְהוֹן בְּאַרְעָא אַחֲסַנְתְּהוֹן הוּא עֵשָׂו אֲבוּהוֹן דֶאֱדוֹמָאֵי: פפפ:
@1085 וִיתֵיב יַעֲקֹב בְּאַרְעָא תּוֹתָבוּת אֲבוּהִי בְּאַרְעָא דִכְנָעַן:
@1086 אִלֵּין תּוּלְדַת יַעֲקֹב יוֹסֵף בַּר שְׁבַע עַסְרֵי שְׁנִין (כַּד) הֲוָה רָעֵי עִם אֲחוֹהִי בַּעֲנָא וְהוּא מְרַבֵּי עִם בְנֵי בִלְהָה וְעִם בְּנֵי זִלְפָּה נְשֵׁי אֲבוּהִי וְאַיְתִי יוֹסֵף יָת דִּבְּהוֹן בִּישָׁא לְוַת אֲבוּהוֹן:
@1087 וְיִשְׂרָאֵל רְחֵם יָת יוֹסֵף מִכָּל בְּנוֹהִי אֲרֵי בַר חַכִּים הוּא לֵהּ וַעֲבַד לֵהּ כִּתּוּנָא דְפַסֵי:
@1088 וַחֲזוֹ אֲחוֹהִי אֲרֵי יָתֵהּ רְחֵם אֲבוּהוֹן מִכָּל אֲחוֹהִי וּסְנוֹ יָתֵהּ וְלָא צָבָן לְמַלָּלָא עִמֵּהּ לִשְׁלָם:
@1089 וַחֲלַם יוֹסֵף חֶלְמָא וְחַוִי לַאֲחוֹהִי וְאוֹסִיפוּ עוֹד סְנוֹ יָתֵהּ:
@1090 וַאֲמַר לְהוֹן שְׁמָעוּ כְעַן חֶלְמָא הָדֵין דִּי חֲלֵימִית:
@1091 וְהָא אֲנַחְנָא מְאַסְרִין אֱסָרָן בְּגוֹ חַקְלָא וְהָא קָמַת אֱסַרְתִּי וְאַף אִזְדְקָפַת וְהָא מִסְתַּחֲרָן אֱסָרָתְכוֹן וְסָגְדָן לֶאֱסַרְתִּי:
@1092 וַאֲמָרוּ לֵהּ אֲחוֹהִי הֲמַלְכוּ אַתְּ מְדַמֵּי לְמִמְלַךְ עָלָנָא אוֹ שׁוּלְטָּן אַתְּ סְבִיר לְמִשְׁלַט בָּנָא וְאוֹסִיפוּ עוֹד סְנוֹ יָתֵהּ עַל חֶלְמוֹהִי וְעַל פִּתְגָמוֹהִי:
@1093 וַחֲלַם עוֹד חֶלְמָא אָחֲרָנָא וְאִשְׁתָּעֵי יָתֵהּ לַאֲחוֹהִי וַאֲמַר הָא חֲלֵמִית חֶלְמָא עוֹד וְהָא שִׁמְשָׁא וְסִהֲרָא וְחַד עֲשַׂר כּוֹכְבַיָּא סָגְדָן לִי:
@1094 וְאִשְׁתָּעֵי לַאֲבוּהִי וְלַאֲחוֹהִי וּנְזַף בֵּהּ אֲבוּהִי וַאֲמַר לֵהּ מָה חֶלְמָא הָדֵין דִּי חֲלֵמְתָּא הֲמֵיתָא נֵיתֵי אֲנָא וְאִמָּךְ וְאַחָיךְ לְמִסְגֻד לָךְ עַל אַרְעָא:
@1095 וְקַנִּיאוּ בֵהּ אֲחוֹהִי וַאֲבוּהִי נְטַר יָת פִּתְגָמָא:
@1096 וַאֲזָלוּ אֲחוֹהִי לְמִרְעֵי יָת עָנָא דַאֲבוּהוֹן בִּשְׁכֶם:
@1097 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף הֲלָא אַחָיךְ רָעָן בִּשְׁכֶם אֱתָא וְאֶשְׁלְחִנָּךְ לְוָתְהוֹן וַאֲמַר לֵהּ הָא אֲנָא:
@1098 וַאֲמַר לֵהּ אִיזֵל כְּעַן חֲזֵי יָת שְׁלָמָא דְאָחוּךְ וְיָת שְׁלָמָא דְעָנָא וַאֲתֶבְנִי פִּתְגָמָא וְשַׁלְחֵהּ מִמֵישַׁר חֶבְרוֹן וַאֲתָא לִשְׁכֶם:
@1099 וְאַשְׁכְּחֵהּ גַבְרָא וְהָא תָעֵי בְּחַקְלָא וּשְׁאָלִנֵּהּ גַבְרָא לְמֵימָר מָה אַתְּ בָּעֵי:
@1100 וַאֲמַר יָת אַחַי אֲנָא בָעֵי חַוִי כְעַן לִי הֵיכָא אִנּוּן רָעָן:
@1101 וַאֲמַר גַּבְרָא נְטָלוּ מִכָּא אֲרֵי שְׁמָעִית דְּאָמְרִין נֵיזֵל לְדֹתָן וַאֲזַל יוֹסֵף בָּתַר אֲחוֹהִי וְאַשְׁכְּחִנּוּן בְּדֹתָן:
@1102 וַחֲזוֹ יָתֵהּ מֵרָחִיק וְעַד לָא קְרֵיב לְוָתְהוֹן וְחַשִּׁיבוּ עֲלוֹהִי לְמִקְטְלֵהּ:
@1103 וַאֲמָרוּ גְבַר לַאֲחוּהִי הָא מָרֵי חֶלְמַיָּא דֵיכִי אֲתָא:
@1104 וכְעַן אֱתוֹ וְנִקְטְלִנֵּהּ וְנִרְמִנֵּהּ בַּחֲדָא מִן גֻּבַּיָּא וְנֵימַר חַיְתָא בִישְׁתָא אֲכַלְתֵּהּ וְנֶחֱזֵי מָה יְהוֹן בְּסוֹף חֶלְמוֹהִי:
@1105 וּשְׁמַע רְאוּבֵן וְשֵׁזְבֵהּ מִידֵיהוֹן וַאֲמַר לָא נִקְטְלִנֵּהּ נְפָשׁ:
@1106 וַאֲמַר לְהוֹן רְאוּבֵן לָא תוֹשְׁדוּן דְּמָא רְמוֹ יָתֵהּ לְגֻבָּא הָדֵין דִּי בְּמַדְבְּרָא וִידָא לָא תוֹשְׁטוּן בֵּהּ בְּדִיל לְשֵׁיזָבָא יָתֵהּ מִידֵיהוֹן לַאֲתָבוּתֵהּ לְוַת אֲבוּהִי:
@1107 וַהֲוָה כַּד אָתָא יוֹסֵף לְוַת אֲחוֹהִי וְאַשְׁלָחוּ יָת יוֹסֵף יָת כִּתּוּנֵהּ יָת כִּתּוּנָא דְפַסֵּי דִי עֲלוֹהִי:
@1108 וְנָסְבוּהִי וּרְמוֹ יָתֵהּ לְגֻבָּא וְגֻבָּא רֵיקָא לֵית בֵּהּ מַיָּא:
@1109 וְאַסְחָרוּ לְמֵיכַל לַחֲמָא וּזְקָפוּ עֵינֵיהוֹן וַחֲזוֹ וְהָא שְׁיָרַת עֲרָבָאֵי אָתְיָא מִגִּלְעָד וְגַמְלֵיהוֹן טְעִינִין שְׁעַף וּקְטַף וּלְטוֹם אָזְלִין לַאֲחָתָא לְמִצְרָיִם:
@1110 וַאֲמַר יְהוּדָה לַאֲחוֹהִי מָה מָמוֹן נִתְהֲנֵי לָנָא אֲרֵי נִקְטּוֹל יָתּ אָחוּנָא וּנְכַסֵי עַל דְּמֵהּ:
@1111 אֱתוּ וּנְזַבְּנִנֵּהּ לַעֲרָבָאֵי וִידָנָא לָא תְהֵי בֵהּ אֲרֵי אֲחוּנָא בִסְרָנָא הוּא וְקַבִּילוּ מִנֵּהּ אֲחוֹהִי:
@1112 וַעֲבָרוּ גַבְרֵי מִדְיָנָאֵי תַּגָּרֵי וּנְגִידוּ וְאַסִּיקוּ יָת יוֹסֵף מִן גֻּבָּא וְזַבִּינוּ יָת יוֹסֵף לַעֲרָבָאֵי בְּעֶסְרִין כְּסָף וְאַיְתִיוּ יָת יוֹסֵף לְמִצְרָיִם:
@1113 וְתָב רְאוּבֵן לְגֻבָּא וְהָא לֵית יוֹסֵף בְּגֻבָּא וּבְזַע יָת לְבוּשׁוֹהִי:
@1114 וְתָב לְוַת אֲחוֹהִי וַאֲמַר עוּלֵימָא לֵיתוֹהִי וַאֲנָא לְאָן אֲנָא אָתֵי:
@1115 וּנְסִיבוּ יָת כִּתּוּנָא דְיוֹסֵף וּנְכִיסוּ צְפִיר בַּר עִזֵּי וּטְבָלוּ יָת כִּתּוּנָא בִּדְמָא:
@1116 וְשַׁלָּחוּ יָת כִּתּוּנָא דְפַסֵּי וְאַיְתִיוּ לְוַת אֲבוּהוֹן וַאֲמָרוּ דָא אַשְׁכַּחְנָא אִשְׁתְּמוֹדַע כְּעַן הֲכִתּוּנָא דִבְרָךְ הִיא אִם לָא:
@1117 וְאִשְׁתְּמוֹדְעַהּ וַאֲמַר כִּתּוּנָא דִבְרִי חַיְתָא בִישְׁתָא אֲכָלְתֵּהּ מִקְטַל קְטִיל יוֹסֵף:
@1118 וּבְזַע יַעֲקֹב לְבוּשׁוֹהִי וַאֲסַר שַׂקָא בְּחַרְצֵהּ וְאִתְאַבַּל עַל בְּרֵהּ יוֹמִין סַגִיאִין:
@1119 וְקָמוּ כָל בְּנוֹהִי וְכָל בְּנָתֵהּ לְנַחֲמוּתֵהּ וְסָרֵיב לְקַבָּלָא תַנְחוּמִין וַאֲמַר אֲרֵי אֵחוֹת לְוַת (עַל) בְּרִי כַּד אֲבֵילָא לִשְׁאוֹל וּבְכָא יָתֵהּ אֲבוּהִי:
@1120 וּמִדְיָנָאֵי זַבִּינוּ יָתֵהּ לְמִצְרָיִם לְפוֹטִיפַר רַבָּא דְפַרְעֹה רַב קָטוֹלַיָּא:
@1121 וַהֲוָה בְּעִדָּנָא הַהִיא וּנְחַת יְהוּדָה מִלְּוַת אֲחוֹהִי וּסְטָא עַד גַּבְרָא עֲדֻלָּמָאָה וּשׁמֵהּ חִירָה:
@1122 וַחֲזָא תַמָּן:יְהוּדָה בַּת גְּבַר תַּגָּרָא וּשְׁמֵהּ שׁוּעַ וְנָסְבַהּ וְעַל לְוָתַהּ:
@1123 וְעַדִּיאַת וִילִידַת בָּר וּקְרָא יָת שְׁמֵהּ עֵר:
@1124 וְעַדִּיאַת עוֹד וִילִידַת בָּר וּקְרַת יָת שְׁמֵהּ אוֹנָן:
@1125 וְאוֹסִיפַת עוֹד וִילִידַת בָּר וּקְרַת יָת שְׁמֵהּ שֵׁלָה וַהֲוָה בִכְזִיב כַּד יְלִידַת יָתֵהּ:
@1126 וּנְסִיב יְהוּדָה אִתְּתָא לְעֵר בּוּכְרֵהּ וּשְׁמַהּ תָּמָר:
@1127 וַהֲוָה עֵר בּוּכְרָא דִיהוּדָה בִּישׁ קֳדָם יְיָ וַאֲמִיתֵהּ יְיָ:
@1128 וַאֲמַר יְהוּדָה לְאוֹנָן עוּל לְוַת אִתַּת אָחוּךְ וְיַבֵּם יָתַהּ וַאֲקֵים זַרְעָא לְאָחוּךְ:
@1129 וִידַע אוֹנָן אֲרֵי לָא עַל שְׁמֵהּ מִתְקְרֵי זַרְעָא וַהֲוָה כַּד עָלֵיל לְוַת אִתַּת אֲחוּהִי וּמְחַבֵּל אָרְחֵהּ עַל אַרְעָא בְּדִיל דְּלָא לְקַיָּמָא זַרְעָא לַאֲחוּהִי:
@1130 וּבְאֵישׁ קֳדָם יְיָ דִּי עֲבָד וַאֲמִית אַף יָתֵהּ:
@1131 וַאֲמַר יְהוּדָה לְתָמָר כַּלְּתֵהּ תִּיבִי אַרְמְלָא בֵית אָבִיךְ עַד דְיִרְבֵּי שֵׁלָה בְרִי אֲרֵי אֲמַר דִּלְמָא יְמוּת אַף הוּא כְּאָחוֹהִי וַאֲזָלַת תָּמָר וִיתִיבַת בֵּית אָבוּהָא:
@1132 וּסְגִיאוּ יוֹמַיָּא וּמִיתַת בַּת שׁוּעַ אִתַּת יְהוּדָה וְאִתְנַחֵם יְהוּדָה וּסְלִיק עַל גּוֹזְזֵי עָנֵהּ הוּא וְחִירָה רַחֲמֵהּ עֲדֻלָּמָאָה לְתִמְנָת:
@1133 וְאִתְחַוָּא לְתָמָר לְמֵימָר הָא חֲמוּיִךְ סָלֵק לְתִמְנָת לְמֵיגַז עָנֵהּ:
@1134 וְאַעְדִּיאַת לְבוּשֵׁי אַרְמְלוּתַהּ מִנַּהּ וְאִתְכַּסִּיאַת בְּעֵיפָא וְאִתַּקָּנַת וִיתִיבַת בְּפָרָשׁוּת עַיְנִין דִּי עַל אֹרַח תִּמְנָת אֲרֵי חָזַת אֲרֵי רְבָא שֵׁלָה וְהִיא לָא אִתְיְהִיבַת לֵהּ לְאִנְתּוּ:
@1135 וַחֲזָאַהּ יְהוּדָה וְחַשְּׁבַהּ כְּנָפְקַת בָּרָא אֲרֵי כַסִּיאַת אַפָּאָה:
@1136 וּסְטָא לְוָתַהּ לְאָרְחָא וַאֲמַר הָבִי כְעַן אֵיעוֹל לְוָתִיךְ אֲרֵי לָא יְדַע אֲרֵי כַלְּתֵהּ הִיא וַאֲמֶרֶת מַה תִּתֵּן לִי אֲרֵי תֵיעוֹל לְוָתִי:
@1137 וַאֲמַר אֲנָא אֲשַׁלַּח גַּדְיָא בַר עִזֵּי מִן עָנָא וַאֲמֶרֶת אִם תִּתֵּן מַשְׁכּוֹנָא עַד דְּתִשְׁלָח:
@1138 וַאֲמַר מָה מַשְׁכּוֹנָא דִּי אֶתֵּן לָךְ וַאֲמֶרֶת עִזְקְתָךְ וְשׁוֹשִׁפָּךְ וְחוּטְרָךְ דִּי בִידָךְ וִיהַב לַהּ וְעַל לְוָתַהּ וְעַדִּיאַת לֵהּ:
@1139 וְקָמַת וַאֲזָלַת וְאַעְדִּיאַת עֵיפַהּ מִנַּהּ וּלְבִישַׁת לְבוּשֵׁי אַרְמְלוּתַהּ:
@1140 וְשַׁדַּר יְהוּדָה יָת גַּדְיָא בַר עִזֵּי בִּידָא דְרַחֲמֵהּ עֲדֻלָּמָאָה לְמִסַּב מַשְׁכּוֹנָא מִידָא דְאִתְּתָא וְלָא אַשְׁכְּחַהּ:
@1141 וּשְׁאִיל יָת אֲנָשֵׁי אַתְרַהּ לְמֵימַר אָן מְקַדִּשְׁתָּא הִיא בְעַיְנִין עַל אָרְחָא וַאֲמָרוּ לֵית הָכָא מְקַדִּשְׁתָּא:
@1142 וְתָב לְוַת יְהוּדָה וַאֲמַר לָא אַשְׁכְּחִיתַהּ וְאַף אֲנָשֵׁי אַתְרָא אֲמָרוּ לֵית הָכָא מְקַדִּשְׁתָּא:
@1143 וַאֲמַר יְהוּדָה תִּסַּב לַהּ דִילְמָא נְהֵי לְחוֹךְ הָא שַׁדָּרִית גַּדְיָא הָדֵין וְאַתְּ לָא אַשְׁכְּחִתַּהּ:
@1144 וַהֲוָה כִּתְלָתוּת יַרְחַיָּא וְאִתְחַוָּא לִיהוּדָה לְמֵימַר זַנִּיאַת תָּמָר כַּלְּתָךְ וְאַף הָא מַעַדְּיָא לִזְנוּתָא וַאֲמַר יְהוּדָה אַפְּקוּהַ וְתִתּוֹקָד:
@1145 הִיא מִתַּפְּקָא וְהִיא שְׁלָחַת לַחֲמוּהָא לְמֵימַר לִגְבַר דִּי אִלֵּין דִּילֵהּ מִנֵּהּ אֲנָא מְעַדְּיָא וַאֲמֶרֶת אִשְׁתְּמוֹדַע כְּעַן לְמָן עִזְקְתָא וְשׁוֹשִׁפָּא וְחוּטְרָא הָאִלֵּין:
@1146 וְאִשְׁתְּמוֹדַע יְהוּדָה וַאֲמַר זַכָּאָה מִנִּי מְעַדְּיָא אֲרֵי עַל כֵּן לָא יְהָבִתַּהּ לְשֵׁלָה בְרִי וְלָא אוֹסִיף עוֹד לְמִידְעַהּ:
@1147 וַהֲוָה בְּעִדַּן דְּמֵילְדַהּ וְהָא תְיוֹמִין בִּמְעָהָא:
@1148 וַהֲוָה בְּמֵילְדַהּ וִיהַב יְדָא וּנְסִיבַת חַיְתָא וּקְטָרַת עַל יְדֵהּ זְהוֹרִיתָא לְמֵימַר דֵּין נְפַק קַדְמָאָה:
@1149 וַהֲוָה כַּד אֲתֵיב יְדֵהּ וְהָא נְפַק אֲחוּהִי וַאֲמֶרֶת מָה תְקוֹף סַגִּי עֲלָךְ לְמִתְקָף וּקְרָא שְׁמֵהּ פָּרֶץ:
@1150 וּבָתַר כֵּן נְפַק אֲחוּהִי דִּי עַל יְדֵהּ זְהוֹרִיתָא וּקְרָא שְׁמֵהּ זָרַח:
@1151 וְיוֹסֵף אִתָּחַת לְמִצְרָיִם וּזְבָנֵהּ פּוֹטִיפַר רַבָּא דְפַרְעֹה רַב קָטוֹלַיָּא גְּבַר מִצְרָאָה מִידָא דַּעֲרָבָאֵי דִּי אֲחִתוֹהִי לְתַמָּן:
@1152 וַהֲוָה מֵימְרָא דַּיְיָ בְּסַעְדֵּהּ דְּיוֹסֵף וַהֲוָה גְּבַר מַצְלָח וַהֲוָה בְּבֵית רִבּוֹנֵהּ מִצְרָאָה:
@1153 וַחֲזָא רִבּוֹנֵהּ אֲרֵי מֵימְרָא דַּיְיָ בְּסַעְדֵּהּ וְכֹל דִּי הוּא עָבֵד יְיָ מַצְלַח בִּידֵהּ:
@1154 וְאַשְׁכַּח יוֹסֵף רַחֲמִין בְּעֵינוֹהִי וְשַׁמֵּשׁ יָתֵהּ וּמַנְיֵהּ עַל בֵּיתֵהּ וְכָל דִּי אִית לֵהּ מְסַר בִּידֵהּ:
@1155 וַהֲוָה מֵעִדַּן דְּמַנִּי יָתֵהּ בְּבֵיתֵהּ וְעַל כָּל דִּי אִית לֵהּ וּבָרִיךְ יְיָ יָת בֵּית מִצְרָאָה בְּדִיל יוֹסֵף וַהֲוָה בִּרְכְּתָא דַּיְיָ בְּכָל דִּי אִית לֵהּ בְּבֵיתָא וּבְחַקְלָא:
@1156 וּשְׁבַק כָּל דִּי לֵהּ בִּידָא דְיוֹסֵף וְלָא יְדַע עִמֵּהּ מִדַּעַם אֶלָּהֵן לַחְמָא דִּי הוּא אָכֵל וַהֲוָה יוֹסֵף שַׁפִּיר בְּרֵיוָא וְיָאֵי בְחֶזְוָא:
@1157 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וּזְקָפַת אִתַּת רִבּוֹנֵהּ יָת עֵינָהָא לְיוֹסֵף וַאֲמֶרֶת שְׁכוּב עִמִּי:
@1158 וְסָרֵיב וַאֲמַר לְוַת אִתַּת רִבּוֹנֵהּ הָא רִבּוֹנִי לָא יְדַע עִמִּי מָה דִּבְבֵיתָא וְכֹל דִּי אִית לֵהּ מְסַר בִּידִי:
@1159 לֵיתוֹהִי רַב בְּבֵיתָא הָדֵין מִנִּי וְלָא מְנַע מִנִּי מִדַּעַם אֶלָּהֵן יָתִיךְ בְּדִיל דְאַתְּ אִתְּתֵהּ וְאֶכְדֵּין אֶעְבֵּיד בִּישְׁתָא רַבְּתָא הָדָא וְאֵחוֹב קֳדָם יְיָ:
@1160 וַהֲוָה כַּד מַלֵּילַת עִם יוֹסֵף יוֹם יוֹם וְלָא קַבִּיל מִנַּהּ לְמִשְׁכַּב לְוָתַהּ לְמֶהֱוֵי עִמַּהּ:
@1161 וַהֲוָה כְּיוֹמָא הָדֵין וְעַל לְבֵיתָא לְמִבְדַּק בְּכִתְבֵי חָשְׁבְּנֵהּ וְלֵית אֱנַשׁ מֵאֲנָשֵׁי בֵיתָא תַּמָּן בְּבֵיתָא:
@1162 וַאֲחִדְתֵּהּ בִּלְבוּשֵׁהּ לְמֵימַר שְׁכוּב עִמִּי וְשָׁבְקֵהּ לִלְבוּשֵׁהּ בִּידַהּ וַעֲרַק וּנְפַק לְשׁוּקָא:
@1163 וַהֲוָה כַּד חֲזַת אֲרֵי שָׁבְקֵהּ לִלְבוּשֵׁהּ בִּידַהּ וַעֲרַק לְשׁוּקָא:
@1164 וּקְרַת לַאֲנָשֵׁי בֵיתַהּ וַאֲמֶרֶת לְהוֹן לְמֵימָר חֲזוֹ אַיְתִי לָנָא גַּבְרָא עִבְרָאָה לְחַיָּכָא בָנָא עַל לְוָתִי לְמִשְׁכַּב עִמִּי וּקְרֵית בְּקָלָא רַבָּא:
@1165 וַהֲוָה כַד שְׁמַע אֲרֵי אֲרֵימִית קָלִי וּקְרֵית וְשָׁבְקֵהּ לִלְבוּשֵׁהּ לְוָתִי וַעֲרַק וּנְפַק לְשׁוּקָא:
@1166 וַאֲחִתְּתֵהּ לִלְבוּשֵׁהּ לְוָתַהּ עַד דְּעַל רִבּוֹנֵהּ לְבֵיתֵהּ:
@1167 וּמַלֵּילַת עִמֵּהּ כְּפִתְגָּמַיָּא הָאִלֵּין לְמֵימָר עַל לְוָתִי עַבְדָּא עִבְרָאָה דִּי אַיְתֵיתָא לָנָא לְחַיָּכָא בִי:
@1168 וַהֲוָה כַּד אֲרֵימִית קָלִי וּקְרֵית וְשָׁבְקֵהּ לִלְבוּשֵׁהּ לְוָתִי וַעֲרַק לְשׁוּקָא:
@1169 וַהֲוָה כַד שְׁמַע רִבּוֹנֵהּ יָת פִּתְגָּמֵי אִתְּתֵהּ דִּי מַלֵּילַת עִמֵּהּ לְמֵימַר כְּפִתְגָּמַיָּא הָאִלֵּין עֲבַד לִי עַבְדָּךְ וּתְקֵף רָגְזֵהּ:
@1170 וּנְסִיב רִבּוֹנֵהּ דְּיוֹסֵף יָתֵהּ וִיהָבֵיה לְבֵית אֲסִירֵי אֲתַר דִּי אֲסִירֵי מַלְכָּא אֲסִירִין וַהֲוָה תַמָּן בְּבֵית אֲסִירֵי:
@1171 וַהֲוָה מֵימְרָא דַּיְיָ בְּסַעְדֵּהּ דְּיוֹסֵף וּנְגַד לֵהּ חִסְדָּא וִיהָבֵהּ לְרַחֲמִין בְּעֵינֵי רַב בֵּית אֲסִירֵי:
@1172 וִיהַב רַב בֵּית אֲסִירֵי בִּידָא דְיוֹסֵף יָת כָּל אֲסִירַיָּא דִּי בְּבֵית אֲסִירֵי וְיָת כָּל דִּי עָבְדִין תַּמָּן עַל מֵימְרֵהּ הֲוָה מִתְעֲבֵד:
@1173 לֵית רַב בֵּית אֲסִירֵי חָזֵי יָת כָּל סָרְחָן בִּידֵהּ בְּדִי מֵימְרָא דַּיְיָ בְּסַעְדֵּהּ וְדִי הוּא עָבֵד יְיָ מַצְלָח:
@1174 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין סְרָחוּ שָׁקְיָא מַלְכָּא דְמִצְרַיִם וְנַחְתּוֹמָא לְרִבּוֹנֵיהוֹן לְמַלְכָּא דְמִצְרָיִם:
@1175 וּרְגַז פַּרְעֹה עַל תְּרֵין רַבְרְבָנוֹהִי עַל רַב שָׁקֵי וְעַל רַב נַחְתּוֹמֵי:
@1176 וִיהַב יָתְהוֹן בְּמַטְּרָא בֵּית רַב קָטּוֹלַיָּא לְבֵית אֲסִירֵי אֲתַר דִּי יוֹסֵף אָסִיר תַּמָּן:
@1177 וּמַנִּי רַב קָטוֹלַיָּא יָת יוֹסֵף עִמְּהוֹן וְשַׁמֵּשׁ יָתְהוֹן וַהֲווֹ יוֹמִין בְּמַטְּרָא:
@1178 וַחֲלָמוּ חֶלְמָא תַּרְוֵיהוֹן גְּבַר חֶלְמֵהּ בְּלֵילְיָא חַד גְּבַר כְּפוּשְׁרַן חֶלְמֵהּ שָׁקְיָא וְנַחְתּוֹמָא דִּי לְמַלְכָּא דְמִצְרַיִם דִּי אֲסִירִין בְּבֵית אֲסִירֵי:
@1179 וַאֲתָא לְוָתְהוֹן יוֹסֵף בְּצַפְרָא וַחֲזָא יָתְהוֹן:והָא אִנּוּן נְסִיסִין:
@1180 וּשְׁאֵל יָת רַבְרְבֵי פַרְעֹה דִּי עִמֵּהּ בְּמַטְּרָא בֵּית רִבּוֹנֵהּ לְמֵימָר מָה דֵין אַפֵּיכוֹן בִּישִׁין יוֹמָא דֵּין:
@1181 וַאֲמָרוּ לֵהּ חֶלְמָא חֲלֵמְנָא וּפָשַׁר לֵית לֵהּ וַאֲמַר לְהוֹן יוֹסֵף הֲלָא מִן קֳדָם יְיָ פּוּשְׁרַן חֶלְמַיָּא אִשְׁתָּעוּ כְעַן לִי:
@1182 וְאִשְׁתָּעִי רַב שָׁקֵי יָת חֶלְמֵהּ לְיוֹסֵף וַאֲמַר לֵה בְּחֶלְמִי וְהָא גּוּפְנָא קֳדָמָי:
@1183 וּבְגוּפְנָא תְּלָתָא שִׁבְשִׁין וְהִיא כַד אַפְרַחַת אַפֵּקַת לַבְלְבִין וַאֲנִיצַת נֵץ בַּשִּׁילוּ אִתְכְּלָתָהָא עִנְּבִין:
@1184 וְכַסָּא דְפַרְעֹה בִּידִי וּנְסִיבַת יָת עִנְּבַיָּא וְעַצָרִית יָתְהוֹן לְכַסָּא דְפַרְעֹה וִיהָבִית יָת כַּסָּא עַל יְדָא דְפַרְעֹה:
@1185 וַאֲמַר לֵהּ יוֹסֵף דֵּין פִּשְׁרָנֵהּ תְּלָתָא שִׁבְשִׁין:תּלָתָא יוֹמִין אִנּוּן:
@1186 בְּסוֹף תְּלָתָא יוֹמִין יִדְכַּר פַּרְעֹה יָת רֵישָׁךְ וִיתֵיבִנָּךְ עַל שִׁמּוּשָׁךְ וְתִתֵּן כַּסָּא דְפַרְעֹה בִּידֵהּ כְּהִלְכְתָא קַדְמָאָה דִּי הֲוֵיתָא מַשְׁקֵי לֵהּ:
@1187 אֶלָּהֵן תִּדְכְּרִנַּנִי עִמָּךְ כַּד יֵיטַב לָךְ וְתַעְבֵּד כְּעַן עִמִּי טִיבוּ וְתִדְכַּר עָלַי קֳדָם פַּרְעֹה וְתַפְּקִנַּנִי מִן בֵּית אֲסִירָא הָדֵין:
@1188 אֲרֵי מִגְנַב גְּנֵבְנָא מֵאַרְעָא דְעִבְרָאֵי וְאַף הָכָא לָא עֲבָדִית מִדַּעַם אֲרֵי שַׁוִּיאוּ יָתִי בְּבֵית אֲסִירֵי:
@1189 וַחֲזָא רַב נַחְתּוֹמֵי אֲרֵי יָאוּת פָּשַׁר וַאֲמַר לְיוֹסֵף אַף אֲנָא בְּחֶלְמִי וְהָא תְּלָתָא סַלִּין דְּחֵירוּ עַל רֵישִׁי:
@1190 וּבְסַלָּא עִלָּאָה מִכֹּל מֵיכַל פַּרְעֹה עוֹבַד נַחְתּוֹם וְעוֹפָא אָכֵל יָתְהוֹן מִן סַלָּא מֵעִלָּוֵי רֵישִׁי:
@1191 וַאֲתֵב יוֹסֵף וַאֲמַר דֵּין פִּשְׁרָנֵהּ תְּלָתָא סַלִּין תְּלָתָא יוֹמִין אִנּוּן:
@1192 בְּסוֹף תְּלָתָא יוֹמִין יַעְדִּי פַרְעֹה יָת רֵישָׁךְ מִנָּךְ וְיִצְלוֹב יָתָךְ עַל צְלִיבָא וְיֵכוּל עוֹפָא יָת בִּשְׂרָךְ מִנָּךְ:
@1193 וַהֲוָה בְּיוֹמָא תְלִיתָאָה יוֹמָא בֵּית וַלְדָא דְפַרְעֹה וַעֲבַד מִשְׁתְּיָא לְכָל עַבְדּוֹהִי וְאִדְכַּר יָת רֵישׁ רַב שָׁקֵי וְיָת רֵישׁ רַב נַחְתּוֹמֵי בְּגוֹ עַבְדּוֹהִי:
@1194 וַאֲתֵיב יָת רַב שָׁקֵי עַל שַׁקְיוּתֵהּ וִיהַב יָת כַּסָּא עַל יְדָא דְפַרְעֹה:
@1195 וְיָת רַב נַחְתּוֹמֵי צְלָב כְּמָא דִּי פָשַׁר לְהוֹן יוֹסֵף:
@1196 וְלָא דְכִיר רַב שָׁקֵי יָת יוֹסֵף וְאַנְשְׁיֵהּ: פפפ:
@1197 וַהֲוָה מִסּוֹף תַּרְתֵּין שְׁנִין וּפַרְעֹה חָלֵם וְהָא קָאֵם עַל נַהֲרָא:
@1198 וְהָא מִן נַהֲרָא סָלְקָן שְׁבַע תּוֹרָן שַׁפִּירָן לְמֶחֱזֵי וּפַטִּימָן בְּשָׂר וְרָעְיָן בְּאַחְוָה:
@1199 וְהָא שְׁבַע תּוֹרָן אָחֳרָנְיָן סָלְקָן בַּתְרֵיהוֹן מִן נַהֲרָא בִּישָׁן לְמֶחֱזֵי וַחֲסִירַן בְּשָׂר וְקָמָן לְקִבְלֵיהוֹן דְּתוֹרָן עַל כֵּיף נַהֲרָא:
@1200 וַאֲכָלַן תּוֹרְתָּא בִּישָׁן לְמֶחֱזֵי וַחֲסִירַן בְּשַׂר יָת שְׁבַע תּוֹרְתָּא שַׁפִּירָן לְמֶחֱזֵי וּפַטִּימָתָא וְאִתְּעַר פַּרְעֹה:
@1201 וּדְמוּךְ וַחֲלַם תִּנְיָנוּת וְהָא שְׁבַע שֻׁבְּלַיָּא סָלְקָן בְּקַנְיָא חַד פַּטִּימָן וְטָבָן:
@1202 וְהָא שְׁבַע שֻׁבְּלַיָּא לָקְיָן וּשְׁקִיפָן קִדּוּם צָמְחָן בַּ:תרֵיהוֹן:
@1203 וּבְלָעָא שֻׁבְּלַיָּא לָקְיָתָא יָת שְׁבַע שֻׁבְּלַיָּא פַּטִּימָתָא וּמָלְיָתָא וְאִתְּעַר פַּרְעֹה וְהָא חֶלְמָא:
@1204 וַהֲוָה בְצַפְרָא וּמִטַּרְפָּא רוּחֵהּ וּשְׁלַח וּקְרָא יָת כָּל חֳרָשֵׁי מִצְרַיִם וְיָת כָּל חַכִּימָהָא וְאִשְׁתָּעִי פַרְעֹה לְהוֹן יָת חֶלְמֵהּ וְלֵית דְּפָשַׁר יָתְהוֹן לְפַרְעֹה:
@1205 וּמַלִּיל רַב שָׁקֵי (עִם פַּרְעֹה) לְפַרְעֹה לְמֵימָר יָת סָרְחָנִי אֲנָא מַדְכַּר יוֹמָא דֵּין:
@1206 פַּרְעֹה רְגֵז עַל עַבְדוֹהִי וִיהַב יָתִי בְּמַטְּרָא בֵּית רַב קָטוֹלַיָּא יָתִי וְיָת רַב נַחְתּוֹמֵי:
@1207 וַחֲלֵמְנָא חֶלְמָא בְּלֵילְיָא חַד אֲנָא וָהוּא גְּבַר כְּפִשְׁרַן חֶלְמֵהּ חֲלֵמְנָא:
@1208 וְתַמָּן עִמָּנָא עוּלֵם עִבְרָאָה עַבְדָא לְרַב קָטוֹלַיָּא וְאִשְׁתָּעֵינָא לֵהּ וּפָשַׁר לָנָא יָת חֶלְמָנָא גְּבַר כְּחֶלְמֵהּ פָּשָׁר:
@1209 וַהֲוָה כְּמָא דִּי פָשַׁר לָנָא כֵּן הֲוָה יָתִי אֲתֵיב עַל שִׁמּוּשִׁי וְיָתֵהּ צְלָב:
@1210 וּשְׁלַח פַּרְעֹה וּקְרָא יָת יוֹסֵף וְאַרְהָטוּהִי מִן בֵּית אֲסִירֵי וְסַפַּר וְשַׁנִּי כְסוּתֵהּ וְעַל לְוַת פַּרְעֹה:
@1211 וַאֲמַר פַּרְעֹה לְיוֹסֵף חֶלְמָא חֲלֵמִית וּפָשַׁר לֵית לֵהּ וַאֲנָא שִׁמְעֵית עֲלָךְ לְמֵימַר דְּאַתְּ שָׁמַע חֶלְמָא לְמִפְשַׁר יָתֵהּ:
@1212 וַאֲתֵיב יוֹסֵף יָת פַּרְעֹה לְמֵימַר בַּר מִן חָכְמְתִי אֶלָּהֵן מִן קֳדָם יְיָ יִתֹּתַב יָת שְׁלָמָא דְפַרְעֹה:
@1213 וּמַלֵּיל פַּרְעֹה עִם יוֹסֵף בְּחֶלְמִי הָא אֲנָא קָאֵם עַל כֵּיף נַהֲרָא:
@1214 וְהָא מִן נַהֲרָא סָלְקָן שְׁבַע תּוֹרָן פַּטִּימָן בְּשַׂר וְשַׁפִּירָן לְמֶחֱזֵי וְרַעְיָן בְּאַחֲוָה:
@1215 וְהָא שְׁבַע תּוֹרָן אָחֳרָנְיָן סָלְקָן בַּתְרֵיהוֹן חֲסִיכָן וּבִישָׁן לְמֶחֱזֵי לַחֲדָא וַחֲסִירָן בְּשָׂר לָא חֲזֵתִי כְוָתְהֵן בְּכָל אַרְעָא דְמִצְרַיִם לְבִישׁוּ:
@1216 וַאֲכָלָן תּוֹרְתָּא חֲסִיכָתָא וּבִישָׁתָא יָת שְׁבַע תּוֹרְתָּא קַדְמָיָתָּא פַּטִּימָתָא:
@1217 וַעֲלָא לִמְעֵיהֶן וְלָא אִתְיְדַע אֲרֵי עַלּוּ לִמְעֵיהֶן וּמֶחֱזֵיהֶן בִּישׁ כַּד בְּקַדְמֵיתָא וְאִתְּעָרִית:
@1218 וַחֲזֵית בְּחֶלְמִי וְהָא שְׁבַע שֻׁבְּלַיָּא סָלְקָן בְּקַנְיָא חַד מָלְיָן וְטָבָן:
@1219 וְהָא שְׁבַע שֻׁבְּלַיָּא נָצָן לָקְיָן שְׁקִיפָן קִדּוּם צָמְחָן בַּתְרֵיהוֹן:
@1220 וּבְלָעָן שֻׁבְּלַיָּא לָקְיָתָא יָת שְׁבַע שֻׁבְּלַיָּא טָּבָתָא וַאֲמָרִית לַחֲרָשַׁיָּא וְלֵית דִּי מְחַוֵּי לִי:
@1221 וַאֲמַר יוֹסֵף לְפַרְעֹה חֶלְמָא דְפַּרְעֹה חַד הוּא יָת דִּי יְיָ עָתִיד לְמֶעְבַּד חַוִּי לְפַרְעֹה:
@1222 שְׁבַע תּוֹרְתָּא טָבָתָא שְׁבַע שְׁנִין אִנּוּן וּשְׁבַע שֻׁבְּלַיָּא טָבָתָא שְׁבַע שְׁנִין אִנּוּן חֶלְמָא חַד הוּא:
@1223 וּשְׁבַע תּוֹרְתָּא חֲסִיכָתָא וּבִישָׁתָא דְסָלְקָן בַּתְרֵיהוֹן שְׁבַע שְׁנִין אִנּוּן וּשְׁבַע שֻׁבְּלַיָּא לָקְיָתָא דִּשְׁקִיפָן קִדּוּם יְהֶוְיָן שְׁבַע שְׁנֵי כַפְנָא:
@1224 הוּא פִתְגָּמָא דִּי מַלֵּילִית עִם פַּרְעֹה דִּי יְיָ עָתִיד לְמֶעְבַּד אַחֲזֵי לְפַרְעֹה:
@1225 הָא שְׁבַע שְׁנִין אָתְיָן שׂוֹבְעָא רַבָּא בְּכָל אַרְעָא דְמִצְרָיִם:
@1226 וִיקוּמוּן שְׁבַע שְׁנֵי כַפְנָא בַּתְרֵיהֶן וְיִתִנְשֵׁי כָּל שׂוֹבְעָא בְּאַרְעָא דְמִצְרָיִם וִישֵׁיצֵי כַפְנָא יָת (עַמָּא דְ) אַרְעָא:
@1227 וְלָא יִתְיְדַע שׂוֹבְעָא בְּאַרְעָא מִן קֳדָם כַּפְנָא הַהוּא דִּיהֵי בָתַר כֵּן אֲרֵי תַקִּיף הוּא לַחֲדָא:
@1228 וְעַל דְּאִתַּנֵּית חֶלְמָא לְפַרְעֹה תַּרְתֵּין זִמְנִין אֲרֵי תַקִּין פִּתְגָּמָא מִן קֳדָם יְיָ וְאוֹחִי יְיָ לְמֶעְבְּדֵהּ:
@1229 וּכְעַן יֶחֱזֵי פַרְעֹה גְּבַר סוּכְלְתָן וְחַכִּים וִימַנִינֵיהּ עַל אַרְעָא דְמִצְרָיִם:
@1230 יַעְבֵּד פַרְעֹה וִימַנֵּי מְהֵימְנִין עַל אַרְעָא וִיזָרֵז יָת אַרְעָא דְמִצְרַיִם בְּשֶׁבַע שְׁנֵי שׂוֹבְעָא:
@1231 וְיִכְנְשׁוּן יָת כָּל עִיבוּר שְׁנַיָּא טָבָן דְּאָתְיָן הָאִלֵּין וְיִצְבְּרוּן עִיבוּרָא תְּחוֹת יְדָא מְהֵימְנֵי דְפַרְעֹה עִיבוּרָא בְּקִירְוַיָּא וְיִטְּרוּן:
@1232 וִיהֵי עִיבוּרָא גְּנִיז (לְעַמָּא דְ) לְאַרְעָא לִשְׁבַע שְׁנֵי כַפְנָא דִּי תְהֶוְיָן בְּאַרְעָא דְמִצְרָיִם וְלָא תִשְׁתֵּיצֵי עַמָּא דְאַרְעָא בְּכַפְנָא:
@1233 וּשְׁפַר פִּתְגָּמָא בְּעֵינֵי פַרְעֹה וּבְעֵינֵי כָּל עַבְדּוֹהִי:
@1234 וַאֲמַר פַּרְעֹה לְעַבְדוֹהִי הֲנִשְׁכַּח כְּדֵין גְּבַר דִּי רוּחַ נְבוּאָה מִן קֳדָם יְיָ בֵּהּ:
@1235 וַאֲמַר פַּרְעֹה לְיוֹסֵף בָּתַר דְּאוֹדַע יְיָ יָתָךְ יָת כָּל דָּא לֵית סָכְלְתָן וְחַכִּים כְּוָתָךְ:
@1236 אַתְּ תְּהֵי מְמַנָּא עַל בֵּיתִי וְעַל מֵימְרָךְ יִתְּזַן כָּל עַמִּי לְחוֹד כָּרְסֵי מַלְכוּתָא הָדֵין אֵיהֵי יַקִּיר מִנָּךְ:
@1237 וַאֲמַר פַּרְעֹה לְיוֹסֵף חֲזֵי מַנֵּיתִי יָתָךְ עַל כָּל אַרְעָא:דמִצְרָיִם:
@1238 וְאַעְדִּי פַרְעֹה יָת עִזְקְתֵהּ מֵעַל יְדֵהּ וִיהַב יָתַהּ עַל יְדָא דְיוֹסֵף וְאַלְבִּישׁ יָתֵהּ לְבוּשִׁין דְּבוּץ וְשַׁוִּי מָנִיכָא דְדַהֲבָא עַל צַוְּארֵהּ:
@1239 וְאַרְכֵּיב יָתֵהּ בִּרְתִכָּא תִנְיֵתָא (נ''י תִנְיָנָא) דִּי לֵהּ וְאַכְרִיזוּ קֳדָמוֹהִי דֵּין אַבָּא לְמַלְכָּא וּמַנִּי יָתֵהּ עַל כָּל אַרְעָא דְמִצְרָיִם:
@1240 וַאֲמַר פַּרְעֹה לְיוֹסֵף אֲנָא פַרְעֹה וּבַר מֵימְרָךְ לָא יְרִים גְּבַר יָת יְדֵהּ לְמֵיחַד זֵין וְיָת רִגְלֵהּ לְמִרְכַּב עַל סוּסְיָא בְּכָל אַרְעָא דְמִצְרָיִם:
@1241 וּקְרָא פַּרְעֹה שׁוּם יוֹסֵף גַּבְרָא דְמִטַּמְרָן גָּלְיָן לֵהּ וִיהַב לֵהּ יָת אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן לְאִתְּתָא וּנְפַק יוֹסֵף (שַׁלִּיט) עַל אַרְעָא דְמִצְרָיִם:
@1242 וְיוֹסֵף בַּר תְּלָתִין שְׁנִין כַּד קָם קֳדָם פַּרְעֹה מַלְכָּא דְמִצְרָיִם וּנְפַק יוֹסֵף מִן קֳדָם פַּרְעֹה וַעֲבַר (שַׁלִּיט) בְּכָל אַרְעָא דְמִצְרָיִם:
@1243 וּכְנָשׁוּ דָיְרֵי אַרְעָא בִּשְׁבַע שְׁנֵי שׂוֹבְעָא עִיבוּרָא לְאוֹצָרִין:
@1244 וּכְנַשׁ יָת כָּל עִיבוּר שְׁבַע שְׁנִין דִּי הֲווֹ בְּאַרְעָא דְמִצְרַיִם וִיהַב עִיבוּר בְּקִרְוַיָּא עִיבוּר חֲקַל קַרְתָּא דִּי בְסַחְרָנָהָא יְהַב בְּגַוָּהּ:
@1245 וּכְנַשׁ יוֹסֵף עִיבוּרָא כְּחַלָּא דְיַמָּא סַגִּי לַחֲדָא עַד דִּי פְסַק לְמִמְנֵי אֲרֵי לֵית מִנְיָן:
@1246 וּלְיוֹסֵף אִתְיְלִיד תַּרְתֵּין בְּנִין עַד לָא עַלַּת שַׁתָּא דְכַפְנָא דִּילִידַת לֵהּ אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן:
@1247 וּקְרָא יוֹסֵף יָת שׁוּם בּוּכְרָא מְנַשֶּׁה אֲרֵי אַנְשְׁיַנִי יְיָ יָת כָּל עַמְלִי וְיָת כָּל בֵּית אַבָּא:
@1248 וְיָת שׁוּם תִּנְיָנָא קְרָא אֶפְרָיִם אֲרֵי אַפְשַׁנִּי יְיָ בְּאַרַע שִׁעְבּוּדִי:
@1249 וּשְׁלִימַת שְׁבַע שְׁנֵי שׂוֹבְעָא דִּי הֲוָה בְּאַרְעָא דְמִצְרָיִם:
@1250 וּשְׁרִיאַת שְׁבַע שְׁנֵי כַפְנָא לְמֵיעַל כְּמָא דִּי אֲמַר יוֹסֵף וַהֲוָה כַפְנָא בְּכָל אַרְעֲתָא וּבְכָל אַרְעָא דְמִצְרַיִם הֲוָה לַחְמָא:
@1251 וּכְפָנַת כָּל אַרְעָא דְמִצְרַיִם וּצְוַח עַמָּא קֳדָם לְפַרְעֹה עַל לַחְמָא וַאֲמַר פַּרְעֹה לְכָל מִצְרָאֵי אִיזִילוּ לְוַת יוֹסֵף דִּי יֵימַר לְכוֹן תַּעְבְּדוּן:
@1252 וְכַפְנָא הֲוָה עַל כָּל אַפֵּי אַרְעָא וּפְתַח יוֹסֵף יָת כָּל דִּי בְהוֹן עִיבוּרָא וְזַבִּין לְמִצְרַיִם וּתְקֵיף כַּפְנָא בְּאַרְעָא דְמִצְרָיִם:
@1253 וְכָל דָּיְרֵי אַרְעָא עַלּוּ לְמִצְרַיִם לְמִזְבַּן עִיבוּרָא מִן יוֹסֵף אֲרֵי תְקֵיף כַּפְנָא בְּכָל אַרְעָא:
@1254 וַחֲזָא יַעֲקֹב אֲרֵי אִית עִיבוּרָא מִזְדַּבַּן בְּמִצְרָיִם וַאֲמַר יַעֲקֹב לִבְנוֹהִי לְמָא תִּתְחֲזוּן:
@1255 וַאֲמַר הָא שְׁמָעִית אָמְרִין אֲרֵי אִית עִיבוּרָא מִזְדַּבַּן בְּמִצְרָיִם חוּתוּ תַמָּן וּזְבוּנוּ לָנָא מִּתַּמָּן וְנֵחֵי וְלָא נְמוּת:
@1256 וּנְחָתוּ אֲחֵי יוֹסֵף עַסְרָא לְמִזְבַּן עִיבוּרָא מִמִּצְרָיִם:
@1257 וְיָת בִּנְיָמִין אֲחוּהִי דְיוֹסֵף לָא שְׁלַח יַעֲקֹב עִם אֲחוֹהִי אֲרֵי אֲמַר דִּלְמָא יְעַרְעִנֵּהּ מוֹתָא:
@1258 וַאֲתוֹ בְּנֵי יִשְׂרָאֵל לְמִזְבַּן עִיבוּרָא בְּגוֹ עָלַיָּא אֲרֵי הֲוָה כַפְנָא בְּאַרְעָא דִּכְנָעַן:
@1259 וְיוֹסֵף הוּא דְּשַׁלִּיט עַל אַרְעָא הוּא דְזַבִּין עִיבוּרָא לְכָל עַמָּא דְאַרְעָא וַאֲתוֹ אֲחֵי יוֹסֵף וּסְגִידוּ לֵהּ עַל אַפֵּיהוֹן עַל אַרְעָא:
@1260 וַחֲזָא יוֹסֵף יָת אֲחוֹהִי וְאִשְׁתְּמוֹדְעִנּוּן וְחַשִּׁיב מָה דְמַלֵּיל לְהוֹן וּמַלִּיל עִמְּהוֹן קַשְׁיָן וַאֲמַר לְהוֹן מְנָן אֲתֵיתוּן וַאֲמָרוּ מֵאַרְעָא דִּכְנַעַן לְמִזְבַּן עִיבוּרָא:
@1261 וְאִשְׁתְּמוֹדַע יוֹסֵף יָת אֲחוֹהִי וְאִנּוּן לָא אִשְׁתְּמוֹדְעוֹהִי:
@1262 וּדְכִיר יוֹסֵף יָת חֶלְמַיָּא דִּי חֲלִים לְהוֹן וַאֲמַר לְהוֹן מְאַלְלִין אַתּוּן לְמֶחֱזֵי יָת בִּדְקָא דְאַרְעָא אֲתֵיתוּן:
@1263 וַאֲמָרוּ לֵהּ לָא רִבּוֹנִי וְעַבְדָּיךְ עַלּוּ לְמִזְבַּן עִיבוּרָא:
@1264 כֻּלָּנָא בְּנֵי גַּבְרָא חַד נָחְנָא כֵּיוָנֵי אֲנַחְנָא לָא הֲווֹ עַבְדָיךְ אַלִּילֵי:
@1265 וַאֲמַר לְהוֹן לָא אֲרֵי בִדְקָא דְאַרְעָא אֲתֵיתוּן לְמֶחֱזֵי:
@1266 וַאֲמָרוּ תְּרֵין עֲשַׂר עַבְדָיךְ אַחִין אֲנַחְנָא בְּנֵי גַּבְרָא חַד בְּאַרְעָא דִּכְנָעַן וְהָא זְעֵירָא עִם אָבוּנָא יוֹמָא דֵּין וְחַד לֵיתוֹהִי:
@1267 וַאֲמַר לְהוֹן יוֹסֵף הוּא דִּי מַלֵּילִית עִמְּכוֹן לְמֵימַר אַלִּילֵי אַתּוּן:
@1268 בְּדָא תִּתְבַּחֲרוּן חֵי פַרְעֹה אִם תִּפְקוּן מִכָּא אֶלָּהֵין בְּמֵתֵי אֲחוּכוֹן זְעֵירָא הָכָא:
@1269 שְׁלָחוּ מִנְּכוֹן חַד וְיִדְבַּר יָת אֲחוּכוֹן וְאַתּוּן תִּתְאַסְרוּן וְיִתְבַּחֲרוּן פִּתְגָּמֵיכוֹן הַקְּשׁוֹטּ אַתּוּן אָמְרִין וְאִם לָא חֵי פַרְעֹה אֲרֵי אַלִּילֵי אַתּוּן:
@1270 וּכְנַשׁ יָתְהוֹן לְבֵית מַטְרָא תְּלָתָא יוֹמִין:
@1271 וַאֲמַר לְהוֹן יוֹסֵף בְּיוֹמָא תְלִיתָאָה דָּא עִבִידוּ וְאִתְקַיָּמוּ מִן קֳדָם יְיָ אֲנָא דָּחֵל:
@1272 אִם כֵּיוָנֵי אַתּוּן אֲחוּכוֹן חַד יִתְאַסַּר בְּבֵית מַטַּרְתְּכוֹן וְאַתּוּן אִיזִילוּ אוֹבִילוּ עִיבוּרָא דְּחַסִּיר בְּבָתֵּיכוֹן:
@1273 וְיָת אֲחוּכוֹן זְעֵירָא תַּיְתוּן לְוָתִי וְיִתְהֵמְנוּן פִּתְגָּמֵיכוֹן וְלָא תְמוּתוּן וַעֲבָדוּ כֵן:
@1274 וַאֲמָרוּ גְּבַר לַאֲחוּהִי בְּקוּשְׁטָּא חַיָּבִין אֲנַחְנָא עַל אָחוּנָא דִּי חֲזֵינָא עָקַת נַפְשֵׁהּ כַּד הֲוָה מִתְחַנֶּן לָנָא וְלָא קַבֵּלְנָא מִנֵּהּ עַל כֵּן אָתַת לְוָתָנָא עַקְתָא הָדָא:
@1275 וַאֲתֵיב רְאוּבֵן יָתְהוֹן לְמֵימָר הֲלָא אֲמָרִית לְוָתְכוֹן לְמֵימַר לָא תְחוֹבוּן בְּעוּלֵימָא וְלָא קַבֶּלְתּוּן וְאַף דְּמֵהּ הָא מִתְבְּעֵי:
@1276 וְאִנּוּן לָא יָדְעוּן אֲרֵי שְׁמִיעַ יוֹסֵף אֲרֵי מְתֻרְגְּמָן הֲוָה בֵינֵיהוֹן:
@1277 וְאִסְתַּחַר מֵעִלָּוֵיהוֹן וּבְכָא וְתָב לְוָתְהוֹן וּמַלֵּיל עִמְּהוֹן וּדְבַר מִלְּוַתְהוֹן יָת שִׁמְעוֹן וַאֲסַר יָתֵהּ לְעֵינֵיהוֹן:
@1278 וּפַקֵּיד יוֹסֵף וּמְלוֹ יָת מָנֵיהוֹן עִיבוּרָא וְלַאֲתָבָא כַסְפֵּיהוֹן גְּבַר לְסַקֵּהּ וּלְמִתַּן לְהוֹן זְוָדִין לְאָרְחָא וַעֲבַד לְהוֹן כֵּן:
@1279 וּנְטָלוּ יָת עִיבוּרְהוֹן עַל חֲמָרֵיהוֹן וַאֲזָלוּ מִתַּמָּן:
@1280 וּפְתַח חַד יָת סַקֵּהּ לְמִתַּן כִּסְתָא לַחֲמָרֵהּ בְּבֵית מְבָתָא וַחֲזָא יָת כַּסְפֵּהּ וְהָא הוּא בְּפוּם טוֹעֲנֵהּ:
@1281 וַאֲמַר לַאֲחוֹהִי אִתּוֹתַב כַּסְפִּי וְאַף הָא בְטּוֹעֲנִי וּנְפַק מַדַּע לִבְּהוֹן וּתְוָהוּ גְּבַר לַאֲחוּהִי לְמֵימַר מָה דָּא עֲבַד יְיָ לָנָא:
@1282 וַאֲתוֹ לְוַת יַעֲקֹב אֲבוּהוֹן אַרְעָא דִּכְנָעַן וְחַוִּיוּ לֵהּ יָת כָּל דְעַרְעָא יָתְהוֹן לְמֵימָר:
@1283 מַלֵּיל גַּבְרָא רִבּוֹנָא דְאַרְעָא עִמָּנָא קַשְׁיָן וִיהַב יָתָנָא כִּמְאַלִּילֵי יָת אַרְעָא:
@1284 וַאֲמַרְנָא לֵהּ כֵּיוָנֵי אֲנָחְנָא לָא הֲוֵינָא אַלִּילֵי:
@1285 תְּרֵין עֲסַר אֲנַחְנָא אַחִין בְּנֵי אָבוּנָא חַד לֵיתוֹהִי וּזְעֵירָא יוֹמָא דֵּין עִם אָבוּנָא בְּאַרְעָא דִּכְנָעַן:
@1286 וַאֲמַר לָנָא גַּבְרָא רִבּוֹנָא דְּאַרְעָא בְּדָא אִדַּע אֲרֵי כֵיוָנֵי אַתּוּן אֲחוּכוֹן חַד שְׁבוּקוּ לְוָתִי וְיָת עִיבוּרָא דְחַסִּיר בְּבָתֵּיכוֹן סִיבוּ וֶאֱזִילוּ:
@1287 וְאַיְתִיאוּ יָת אֲחוּכוֹן זְעֵירָא לְוָתִי וְאִדַּע אֲרֵי לָא אַלִּילֵי אַתּוּן אֲרֵי כֵיוָנֵי אַתּוּן יָת אֲחוּכוֹן אֶתֵּן לְכוֹן וְיָת אַרְעָא תַּעְבְּדוּן בַּהּ סְחוֹרְתָּא:
@1288 וַהֲוָה אִנּוּן מְרִיקִין סַקֵּיהוֹן וְהָא גְּבַר צְרִיר כַּסְפֵּהּ בְּסַקֵּהּ וַחֲזוֹ יָת צְרָרֵי כַסְפֵּיהוֹן אִנּוּן וַאֲבוּהוֹן וּדְחִילוּ:
@1289 וַאֲמַר לְהוֹן יַעֲקֹב אֲבוּהוֹן יָתִי אַתְכֶּלְתּוּן יוֹסֵף לֵיתוֹהִי וְשִׁמְעוֹן לָא הֲוָה הָכָא (לֵיתוֹהִי) וְיָת בִּנְיָמִן תִּדְבְּרוּן עֲלַי הֲווֹ כָלְּהוֹן:
@1290 וַאֲמַר רְאוּבֵן לְוַת אֲבוּהִי לְמֵימַר יָת תְּרֵין בְּנַי תְּמִית אִם לָא אַיְתִנֵּהּ לְוָתָךְ הַב יָתֵהּ עַל יְדִי וַאֲנָא אֲתֵבִנֵּהּ לָךְ:
@1291 וַאֲמַר לָא יֵחוּת בְּרִי עִמְּכוֹן אֲרֵי אָחוּהִי מִית וְהוּא בִּלְחוֹדוֹהִי אִשְׁתָּאַר וִיעַרְעִנֵּהּ מוֹתָא בְּאָרְחָא דִּי תְהָכוּן בַּהּ וְתַחֲתוּן יָת שִׂיבְתִי בְּדָווֹנָא לִשְׁאוֹל:
@1292 וְכַפְנָא תַּקִּיף בְּאַרְעָא:
@1293 וַהֲוָה כַּד שֵׁיצִיאוּ לְמֵיכַל יָת עִיבוּרָא דְּאַיְתִיאוּ מִמִּצְרָיִם וַאֲמַר לְהוֹן אֲבוּהוֹן תּוּבוּ זְבוּנוּ לָנָא זעֵיר עִיבוּרָא:
@1294 וַאֲמַר לֵהּ:יְהוּדָה לְמֵימָר אַסְהָדָא אַסְהֵד בָּנָא גַּבְרָא לְמֵימָר לָא תֶחֱזוּן אַפַּי אֶלָּהֵין כַּד אָחוּכוֹן עִמְּכוֹן:
@1295 אִם אִיתָךְ מְשַׁלַּח יָת אָחוּנָא עִמָּנָא נֵיחוֹת וְנִזְבֵּן לָךְ עִיבוּרָא:
@1296 וְאִם לֵיתָךְ מְשַׁלַּח לָא נֵיחוֹת אֲרֵי גַּבְרָא אֲמַר לָנָא לָא תֶחֱזוּן אַפַּי אֶלָּהֵין כַּד אֲחוּכוֹן עִמְּכוֹן:
@1297 וַאֲמַר יִשְׂרָאֵל לְמָה אַבְאֶשְׁתּוּן לִי לְחַוָּאָה לְגַבְרָא הַעַד כְּעַן לְכוֹן אָחָא:
@1298 וַאֲמָרוּ מִשְׁאַל שָׁאֵל גַּבְרָא לָנָא וּלְיַלָּדוּתָנָא לְמֵימַר הַעַד כְּעַן אֲבוּכוֹן קַיָּם הַאִית לְכוֹן אָחָא וְחַוֵּינָא לֵהּ עַל מֵימַר פִּתְגָּמַיָּא הָאִלֵּין הֲמִדַּע הֲוֵינָא יָדְעִין אֲרֵי יֵימַר אוֹחִיתוּ יָת אֲחוּכוֹן:
@1299 וַאֲמַר יְהוּדָה לְיִשְׂרָאֵל אֲבוּהִי שְׁלַח עוּלֵימָא עִמִּי וְנֵקוּם וְנֵזֵיל וְנֵיחֵי וְלָא נְמוּת אַף אֲנַחְנָא אַף אַתְּ אַף טַפְלָנָא:
@1300 אֲנָא מְעָרַבְנָא בֵהּ מִן יְדִי תִּבְעִנֵּהּ אִם לָא אַיְתִנֵּהּ לָךְ וַאֲקֵימִנֵּהּ קֳדָמָךְ וְאֵהֵי חָטֵי לָךְ כָּל יוֹמַיָּא:
@1301 אֲרֵי אִלּוּלָפוֹן בְּדָא אִתְעַכָּבְנָא אֲרֵי כְעַן תַּבְנָא דְּנַן תַּרְתֵּין זִמְנִין:
@1302 וַאֲמַר לְהוֹן יִשְׂרָאֵל אֲבוּהוֹן אִם כֵּן הָכָא דָּא עִיבִידוּ סִיבוּ מִדִּמְשַׁבַּח בְּאַרְעָא בְּמָנֵיכוֹן וְאוֹחִיתוּ לְגַבְרָא תִּקְרֻבְתָּא זְעֵיר קְטַף וּזְעֵיר דְּבַשׁ שְׁעַף וּלְטוֹם בָּטְנִין וְשִׁגְדִּין:
@1303 וְכַסְפָּא עַל חַד תְּרֵין סִיבוּ בְיֶדְכוֹן וְיָת כַּסְפָּא דְּאִתּוֹתַב בְּפוּם טוֹעֲנֵיכוֹן תְּתִיבוּן בְּיֶדְכוֹן מָאִים שָׁלוּ הוּא:
@1304 וְיָת אֲחוּכוֹן דְּבָרוּ וְקוּמוּ תּוּבוּ לְוַת גַּבְרָא:
@1305 וְאֵל שַׁדַּי יִתֵּן לְכוֹן רַחֲמִין קֳדָם גַּבְרָא וְיִפְטַר לְכוֹן יָת אֲחוּכוֹן אָחֳרָנָא וְיָת בִּנְיָמִין וַאֲנָא כְּמָא דְּאִתְכֵּלִית תְּכֵלִית:
@1306 וּנְסִיבוּ גֻּבְרַיָּא יָת תִּקְרֻבְתָּא הָדָא וְעַל חַד תְּרֵין כַּסְפָּא נְסִיבוּ בִידֵיהוֹן וּדְבָרוּ יָת בִּנְיָמִן וְקָמוּ וּנְחָתוּ לְמִצְרַיִם וְקָמוּ קֳדָם יוֹסֵף:
@1307 וַחֲזָא יוֹסֵף עִמְּהוֹן יָת בִּנְיָמִין וַאֲמַר לְדִי מְמַנָּא עַל בֵּיתֵהּ אָעֵיל יָת גֻּבְרַיָּא לְבֵיתָא וּנְכוֹס נִכְסָתָא וְאַתְקֵין אֲרֵי עִמִּי יֵיכְלוּן גֻּבְרַיָּא בְּשֵׁירוּתָא:
@1308 וַעֲבַד גַּבְרָא כְּמָא דִּי אֲמַר יוֹסֵף וְאָעֵיל גַּבְרָא יָת גֻּבְרַיָּא לְבֵית יוֹסֵף:
@1309 וּדְחִילוּ גֻּבְרַיָּא אֲרֵי אִתַּעֲלוּ לְבֵית יוֹסֵף וַאֲמָרוּ עַל עֵסַק כַּסְפָּא דְּאִתּוֹתַב בְּטוֹעֲנָנָא בְּקַדְמֵיתָא אֲנַחְנָא מִתַּעֲלִין לְאִתְרַבְרָבָא עֲלָנָא וּלְאִסְתַּקָּפָא עֲלָנָא וּלְמִקְנֵי יָתָנָא לְעַבְדִּין וּלְמִדְבַּר יָת חֲמָרָנָא:
@1310 וּקְרִיבוּ לְוַת גַּבְרָא דִּי מְמַנָּא עַל בֵּית יוֹסֵף וּמַלִּילוּ עִמֵּהּ בִּתְרַע בֵּיתָא:
@1311 וַאֲמָרוּ בְּבָעוּ רִבּוֹנִי מֵיחַת נִחֵתְנָא בְּקַדְמֵיתָא לְמִזְבַּן עִיבוּרָא:
@1312 וַהֲוָה כַּד אָתֵינָא לְבֵית מְבָתָא וּפְתַחְנָא יָת טוֹעֲנָנָא וְהָא כְסַף גְּבַר בְּפוּם טוֹעֲנֵהּ כַּסְפָּנָא בְּמַתְקְלֵהּ וַאֲתֵיבְנָא יָתֵהּ בִּידָנָא:
@1313 וְכַסְפָּא אָחֳרָנָא אוֹחִיתְנָא בִידָנָא לְמִזְבַּן עִיבוּרָא לָא יְדַעְנָא מָן שַׁוִּי כַסְפָּנָא בְּטוֹעֲנָנָא:
@1314 וַאֲמַר שְׁלַם לְכוֹן לָא תִדְחֲלוּן אֱלָהֲכוֹן וֵאֱלָהָא דַּאֲבוּכוֹן יְהַב לְכוֹן סִימָּא בְּטוֹעֲנֵיכוֹן כַּסְפְּכוֹן אֲתָא לְוָתִי וְאַפֵּיק לְוָתְהוֹן יָת שִׁמְעוֹן:
@1315 וְאָעֵיל גַּבְרָא יָת גֻּבְרַיָּא לְבֵית יוֹסֵף וִיהַב מַיָּא וְאַסְחוֹ רִגְלֵיהוֹן וִיהַב כִּסְּתָא לַחֲמָרֵיהוֹן:
@1316 וְאַתְקִינוּ יָת תִּקְרֻבְתָּא עַד דְּעַל יוֹסֵף בְּשֵׁירוּתָא אֲרֵי שְׁמָעוּ אֲרֵי תַמָּן יֵיכְלוּן לַחֲמָא:
@1317 וְעַל יוֹסֵף לְבֵיתָא וְאַיְתִיאוּ לֵהּ יָת תִּקְרֻבְתָּא דִּי בִידֵיהוֹן לְבֵיתָא וּסְגִידוּ לֵהּ לְאַרְעָא:
@1318 וּשְׁאֵיל לְהוֹן לִשְׁלַם וַאֲמַר הַשְׁלַם אֲבוּכוֹן סָבָא דִּי אֲמַרְתּוּן הַעַד כְּעַן קַיָּם:
@1319 וַאֲמָרוּ שְׁלַם לְעַבְדָךְ לְאָבוּנָא עַד כְּעַן קַיָּם וּכְרָעוּ וּסְגִידוּ:
@1320 וּזְקַף עֵינוֹהִי וַחֲזָא יָת בִּנְיָמִין אֲחוּהִי בַּר אִמֵּהּ וַאֲמַר הָדֵין אֲחוּכוֹן זְעֵירָא דִּי אֲמַרְתּוּן לִי וַאֲמַר מִן קֳדָם יְיָ יִתְרַחַם עֲלָךְ בְּרִי:
@1321 וְאוֹחִי יוֹסֵף אֲרֵי אִתְגּוֹלְלוּ רַחֲמוֹהִי עַל אֲחוּהִי וּבְעָא לְמִבְכֵּי וְעַל לְאִדְרוֹן בֵּית מִשְׁכְּבָא וּבְכָא תַמָּן:
@1322 וְאַסְחֵי אַפּוֹהִי וּנְפָק וְאִתְחַסִּין וַאֲמַר שַׁווּ לַחֲמָא:
@1323 וְשַׁוִּיאוּ לֵהּ בִּלְחוֹדוֹהִי וּלְהוֹן בִּלְחוֹדֵיהוֹן וּלְמִצְרָאֵי דְּאָכְלִין עִמֵּהּ בִּלְחוֹדֵיהוֹן אֲרֵי לָא יָכְלִין מִצְרָאֵי לְמֵיכַל עִם עִבְרָאֵי לַחְמָא אֲרֵי בְעִירָא דְּמִצְרָאֵי דָחֲלִין לֵהּ עִבְרָאֵי אָכְלִין:
@1324 וְאַסְחָרוּ קֳדָמוֹהִי רַבָּא כְּרַבְיוּתֵהּ וּזְעִירָא כִּזְעֵרוּתֵהּ וּתְמָהוּ גֻּבְרַיָּא גְּבַר לְחַבְרֵהּ:
@1325 וּנְטַלּ חֳלָקִין מִן קֳדָמוֹהִי לָקֳדָמֵיהוֹן וּסְגִי חֲלָקָא דְבִנְיָמִן מֵחֳלָקֵי דְכָלְּהוֹן חַמְשָׁא חֳלָקִין וּשְׁתִיאוּ וּרְוִיאוּ עִמֵּהּ:
@1326 וּפַקֵּיד יָת דִּי מְמַנָּא עַל בֵּיתֵהּ לְמֵימַר מְלֵי יָת טוֹעֲנֵי גֻּבְרַיָּא עִיבוּרָא כְּמָא דִּי יָכְלִין לְמִטְּעַן וְשַׁוִּי כְסַף גְּבַר בְּפוּם טוֹעֲנֵהּ:
@1327 וְיָת כַּלִּידִי כַּלִּידָא דְכַסְפָּא תְּשַׁוֵּי בְּפוּם טוֹעֲנָא דִּזְעֵירָא וְיָת כְּסַף זְבִינוֹהִי וַעֲבַּד כְּפִתְגָּמָא דְּיוֹסֵף דִּי מַלִּיל:
@1328 צַפְרָא נְהָר וְגֻבְרַיָּא אִתְפַּטָּרוּ אִנּוּן וַחֲמָרֵיהוֹן:
@1329 אִנּוּן נְפָקוּ מִן קַרְתָּא לָא אַרְחִיקוּ וְיוֹסֵף אֲמַר לְדִי מְמַנָּא עַל בֵּיתֵהּ קוּם רְדַף בָּתַר גֻּבְרַיָּא וְתַדְבְּקִנּוּן וְתֵימַר לְהוֹן לְמָה שַׁלֶמְתּוּן בִּישָׁא חֳלָף טַבְתָא:
@1330 הֲלָא דֵּין דְּשָׁתֵי רִבּוֹנִי בֵּהּ וְהוּא בָּדָקָא מְבָדֵק בֵּהּ אַבְאֶשְׁתּוּן דִּי עֲבַדְתּוּן:
@1331 וְאַדְבֵּיקִנּוּן וּמַלֵּיל עִמְּהוֹן יָת פִּתְגָּמַיָּא הָאִלֵּין:
@1332 וַאֲמָרוּ לֵהּ לְמָה יְמַלֵּל רִבּוֹנִי כְּפִתְגָּמַיָּא הָאִלֵּין חַס לְעַבְדָּיךְ מִלְּמֶעְבַּד כְּפִתְגָּמָא הָדֵין:
@1333 הָא כַסְפָּא דִּי אַשְׁכַּחְנָא בְּפוּם טּוֹעֲנָנָא אֲתֵיבְנוֹהִי לָךְ מֵאַרְעָא דִּכְנָעַן וְאֶכְדֵּין נִגְנוּב מִבֵּית רִבּוֹנָךְ כַּסְפָּא אוֹ דַּהֲבָא (מָנִין דִּכְסַף אוֹ מָנִין דִּדְהָב):
@1334 דִּי יִשְׁתְּכַח עִמֵּהּ מֵעַבְדָיךְ וּמִית וְאַף אַנַחְנָא נְהֵי לְרִבּוֹנִי לְעַבְדִין:
@1335 וַאֲמַר אַף כְּעַן כְּפִתְגָּמֵיכוֹן כֶּן הוּא דִּי יִשְׁתְּכַח עִמֵּהּ יְהֵי לִי עַבְדָּא וְאַתּוּן תְּהוֹן זַכָּאִין:
@1336 וְאוֹחִיאוּ וְאוֹחִיתוּ גְּבַר יָת טּוֹעֲנֵהּ לְאַרְעָא וּפְתָחוּ גְּבַר טוֹעֲנֵהּ:
@1337 וּבְלַשׁ בְּרַבָּא שָׁרֵי וּבִזְעֵירָא שֵׁצִי וְאִשְׁתְּכַח כַּלִּידָא בְּטוֹעֲנָא דְבִנְיָמִן:
@1338 וּבְזָעוּ לְבוּשֵׁיהוֹן וּרְמוֹ גְּבַר עַל חֲמָרֵהּ וְתָבוּ לְקַרְתָּא:
@1339 וְעַל יְהוּדָּה וַאֲחוֹהִי לְבֵית יוֹסֵף וְהוּא עַד כְּעַן תַּמָּן וּנְפָלוּ קֳדָמוֹהִי לְאַרְעָא:
@1340 וַאֲמַר לְהוֹן יוֹסֵף מָה עוֹבָדָא הָדֵין דִּי עֲבַדְתּוּן הֲלָא יְדַּעְתּוּן אֲרֵי בָדָקָא מְבָדֵק גַּבְרָא דִּי כְוָתִי:
@1341 וַאֲמַר יְהוּדָה מַה נֵּימַר לְרִבּוֹנִי מַה נְּמַלֵּל וּמַה נִזְכֵּי מִן קֳדָם יְיָ אִשְׁתְּכַח יָת חוֹבָא דְעַבְדָּיךְ הָא אֲנַחְנָא עַבְדִּין לְרִבּוֹנִי אַף אֲנַחְנָא אַף דְּאִשְׁתְּכַח כַּלִּידָא בִּידֵהּ:
@1342 וַאֲמַר חַס לִי מִלְּמֶעְבַּד דָּא גַּבְרָא דִּי אִשְׁתְּכַח כַּלִּידָא בִּידֵהּ הוּא יְהֵי לִי עַבְדָּא וְאַתּוּן סָקוֹ לִשְׁלַם לְוַת אֲבוּכוֹן: ססס:
@1343 וּקְרֵב לְוָתֵהּ יְהוּדָה וַאֲמַר בְּבָעוּ רִבּוֹנִי יְמַלֵּל כְּעַן עַבְדָּךְ פִּתְגָּמָא קֳדָם רִבּוֹנִי וְלָא יִתְקֵף רוּגְזָךְ בְּעַבְדָּךְ אֲרֵי כְפַרְעֹה כֵּן אָתְּ:
@1344 רִבּוֹנִי שְׁאִיל יָת עַבְדּוֹהִי לְמֵימָר הַאִית לְכוֹן אַבָּא אוֹ אָחָא:
@1345 וַאֲמַרְנָא לְרִבּוֹנִי אִית לָנָא אַבָּא סָבָא וּבַר סִיבְתִין זְעֵיר וְאָחוּהִי מִית וְאִשְׁתָּאַר הוּא בִלְחוֹדוֹהִי לְאִמֵּהּ וַאֲבוּהִי רְחִים לֵהּ:
@1346 וַאֲמַרְתָּ לְעַבְדָּיךְ אֲחִיתוֹהִי לְוָתִי וֶאֱשַׁוֵּי עֵינִי עֲלוֹהִי:
@1347 וַאֲמַרְנָא לְרִבּוֹנִי לָא יִכּוּל עוּלֵימָא לְמִשְׁבַּק יָת אֲבוּהִי וְאִם יִשְׁבּוֹק יָת אֲבוּהִי וּמִית:
@1348 וַאֲמַרְתָּ לְעַבְדָּיךְ אִם לָא יֵחוֹת אֲחוּכוֹן זְעֵירָא עִמְּכוֹן לָא תוֹסְפוּן לְמֶחֱזֵי אַפָּי:
@1349 וַהֲוָה כַּד סְלֵיקְנָא לְעַבְדָּךְ אַבָּא וְחַוֵּינָא לֵהּ יָת פִּתְגָּמֵי רִבּוֹנִי:
@1350 וַאֲמַר אָבוּנָא תּוּבוּ זְבוּנוּ לָנָא זְעֵיר עִיבוּרָא:
@1351 וַאֲמַרְנָא לָא נִכּוּל לְמֵיחָת אִם אִית אָחוּנָא זְעֵירָא עִמָּנָא וְנֵחוֹת אֲרֵי לָא נִכּוּל לְמֶחֱזֵי אַפֵּי גַּבְרָא וְאָחוּנָא זְעֵירָא לֵיתוֹהִי עִמָּנָא:
@1352 וַאֲמַר עַבְדָּךְ אַבָּא לָנָא אַתּוּן יְדַעְתּוּן אֲרֵי תְרֵין יְלִידַת לִי אִתְּתִי:
@1353 וּנְפַק חַד מִלְוָתִי וַאֲמָרִית בְּרַם מִקְטַל קְטִיל וְלָא חֲזִתֵּהּ עַד כְּעָן:
@1354 וְתַדְבְּרוּן אַף יָת דֵּין מִן קֳדָמַי וִיעַרְעִנֵּהּ מוֹתָא וְתַחֲתוּן יָת שִׂבְתִי בְּבִישְׁתָא לִשְׁאוֹל:
@1355 וּכְעַן כְּמֵיתִי לְוַת עַבְדָּךְ אַבָּא וְעוּלֵימָא לֵיתוֹהִי עִמָּנָא וְנַפְשֵׁהּ חֲבִיבָא לֵהּ כְּנַפְשֵׁהּ:
@1356 וִיהֵי כַּד יֶחֱזֵי אֲרֵי לֵית עוּלֵימָא וּמִית וְיַחֲתוּן עַבְדָּיךְ יָת שִׂיבַת עַבְדָּךְ אָבוּנָא בְּדָווֹנָא לִשְׁאוֹל:
@1357 אֲרֵי עַבְדָּךְ מְעָרַב בְּעוּלֵימָא מִן אַבָּא לְמֵימָר אִם לָא אַיְתִנֵּהּ לְוָתָךְ וָאֱהִי חָטֵי לְאַבָּא כָּל יוֹמַיָּא:
@1358 וּכְעַן יֵתֶב כְּעַן עַבְדָּךְ תְּחוֹת עוּלֵימָא עַבְדָּא לְרִבּוֹנִי וְעוּלֵימָא יִסַּק עִם אֲחוֹהִי:
@1359 אֲרֵי אֶכְדֵּין אֶסַּק לְוַת אַבָּא וְעוּלֵימָא לֵיתוֹהִי עִמִּי דִּלְמָא אֶחֱזֵי בְּבִישׁוּ דִּי יִשְׁכַּח יָת אַבָּא:
@1360 וְלָא יְכִיל יוֹסֵף לְאִתְחַסָּנָא לְכֹל דְּקָיְמִין עִלָּוֹהִי וּקְרָא אַפִּיקוּ כָל אֱנַשׁ מֵעִלָּוָי וְלָא קָם אֱנַשׁ עִמֵּהּ כַּד אִתְיְדַע יוֹסֵף לְוַת אֲחוֹהִי:
@1361 וִיהַב יָת קָלֵהּ בִּבְכִיתָא וּשְׁמָעוּ מִצְרַיִם וּשְׁמַע אֱנַשׁ בֵּית פַּרְעֹה:
@1362 וַאֲמַר יוֹסֵף לַאֲחוֹהִי אֲנָא יוֹסֵף הַעַד כְּעַן אַבָּא קַיָּם וְלָא יָכִילוּ אֲחוֹהִי לַאֲתָבָא יָתֵהּ פִּתְגָּם ארֵי אִתְבְּהִילוּ מִן קֳדָמוֹהִי:
@1363 וַאֲמַר יוֹסֵף לַאֲחוֹהִי קְרִיבוּ כְעַן לְוָתִי וּקְרִיבוּ וַאֲמַר אֲנָא יוֹסֵף אֲחוּכוֹן דִּי זַבִּנְתּוּן יָתִי לְמִצְרָיִם:
@1364 וּכְעַן לָא תִתְנַסְסוּן וְלָא יִתְקָף בְּעֵינֵיכוֹן אֲרֵי זַבִּנְתּוּן יָתִי הַלְכָא אֲרֵי לְקַיָּמָא שַׁלְחַנִּי יְיָ קֳדָמֵיכוֹן:
@1365 אֲרֵי דְנַן תַּרְתֵּין שְׁנִין כַּפְנָא בְּגוֹ אַרְעָא וְעוֹד חָמֵשׁ שְׁנִין דִּי לֵית זְרוֹעָא וַחֲצָדָא:
@1366 וְשַׁלְחַנִּי יְיָ קֳדָמֵיכוֹן לְשַׁוָּאָה לְכוֹן שְׁאָרָא בְּאַרְעָא וּלְקַיָּמָא לְכוֹן לְשֵׁיזָבָא רַבָּא:
@1367 וּכְעַן לָא אַתּוּן שְׁלַחְתּוּן יָתִי הַלְכָא אֶלָּהֵן מִן קֳדָם יְיָ וְשַׁוְּיַנִי לְאַבָּא לְפַרְעֹה וּלְרִבּוֹן לְכָל אֱנַשׁ בֵּיתֵהּ וְשַׁלִּיט בְּכָל אַרְעָא דְמִצְרָיִם:
@1368 אוֹחוּ וּסְקוֹ לְוַת אַבָּא וְתֵימְרוּן לֵהּ כִּדְנַן אֲמַר בְּרָךְ יוֹסֵף שַׁוְּיַנִי יְיָ לְרִבּוֹן לְכָל מִצְרָיִם חוּת לְוָתִי לָא תִתְעַכָּב:
@1369 וְתֵתֵב בְּאַרְעָא דְגשֶׁן וּתְהֵי קָרִיב לִי אַתְּ וּבְנָיךְ וּבְנֵי בְנָיךְ וְעָנָךְ וְתוֹרָךְ וְכָל דִּי לָךְ:
@1370 וְאֵזוּן יָתָךְ תַּמָּן אֲרֵי עוֹד חֲמֵשׁ שְׁנִין כַּפְנָא דִּלְמָא תִתְמַסְכַּן אַתְּ וֶאֱנַשׁ בֵּיתָךְ וְכָל דִּי לָךְ:
@1371 וְהָא עֵינֵיכוֹן חֲזָן וְעֵינֵי אָחִי בִנְיָמִין אֲרֵי בְלִישַׁנְכוֹן אֲנָא מְמַלֵּל עִמְּכוֹן:
@1372 וּתְחַווּן לְאַבָּא יָת כָּל יְקָרִי בְּמִצְרַיִם וְיָת כָּל דִּי חֲזֵיתוּן וְתוֹחוּן וְתַחֲתוּן יָת אַבָּא הָכָא:
@1373 וּנְפַל עַל צַוְּארֵי בִנְיָמִן אֲחוּהִי וּבְכָא וּבִנְיָמִן בְּכָא עַל צַוְּארֵהּ:
@1374 וּנְשַׁק לְכָל אֲחוֹהִי וּבְכָא עֲלֵיהוֹן וּבָתַר כֵּן מַלִּילוּ אֲחוֹהִי עִמֵּהּ:
@1375 וְקָלָא אִשְׁתְּמַע בֵית פַּרְעֹה לְמֵימַר עַלּוּ אֲחֵי יוֹסֵף וּשְׁפַר בְּעֵינֵי פַרְעֹה וּבְעֵינֵי עַבְדּוֹהִי:
@1376 וַאֲמַר פַּרְעֹה לְיוֹסֵף אֱמַר לְאַחָיךְ דָּא עִיבִידוּ טְעוּנוּ יָת בְּעִירְכוֹן וֶאֱזִילוּ אוֹבִילוּ לְאַרְעָא דִּכְנָעַן:
@1377 וּדְבָרוּ יָת אֲבוּכוֹן וְיָת אֱנַשׁ בָּתֵּיכוֹן וְעוּלוּ לְוָתִי וְאֶתֵּן לְכוֹן יָת טוּב אַרְעָא דְמִצְרַיִם וְתֵיכְלוּן יָת טוּבָא דְאַרְעָא:
@1378 וְאַתְּ מְפַקָּדָא דָּא עִיבִידוּ סִיבוּ לְכוֹן מֵאַרְעָא דְמִצְרַיִם עֶגְלָן לְטַפְלֵּיכוֹן וְלִנְשֵׁיכוֹן וְתִטְּלוּן יָת אֲבוּכוֹן וְתֵיתוּן:
@1379 וְעֵינְכוֹן לָא תְחוּס עַל מָנֵיכוֹן אֲרֵי טַב כָּל אַרְעָא דְמִצְרַיִם דִּלְכוֹן הוּא:
@1380 וַעֲבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וִיהַב לְהוֹן יוֹסֵף עֶגְלָן עַל מֵימַר פַּרְעֹה וִיהַב לְהוֹן זְוָדִין לְאָרְחָא:
@1381 לְכָלְהוֹן יְהַב לִגְבַר אִצְטְלַּוָּן דִּלְבוּשִׁין וּלְבִנְיָמִן יְהַב תְּלַת מְאָה סִלְעִין דִּכְסַף וַחֲמֵשׁ אִצְטְלַוָּן דִּלְבוּשִׁין:
@1382 וְלַאֲבוּהִי שְׁלַח כְּדָא עַסְרָא חֲמָרִין טְעִינִין מִטּוּבָא דְמִצְרָיִם וַעֲסַר אַתְנָן טְעִינָן עִיבוּר וּלְחֵם וּזְוָדִין לַאֲבוּהִי לְאָרְחָא:
@1383 וְשַׁלַּח יָת אֲחוֹהִי וַאֲזָלוּ וַאֲמַר לְהוֹן לָא תִתְנַצוּן:בּאָ:רחָא:
@1384 וּסְלִיקוּ מִמִּצְרָיִם וַאֲתוֹ לְאַרְעָא דִּכְנַעַן לְוַת יַעֲקֹב אֲבוּהוֹן:
@1385 וְחַוִּיאוּ לֵהּ לְמֵימַר עַד כְּעַן יוֹסֵף קַיָּם וַאֲרֵי הוּא שַׁלִּיט בְּכָל אַרְעָא דְמִצְרָיִם וַהֲווֹ מִלַּיָּא פָּיְגָן עַל לִבֵּהּ אֲרֵי לָא הֵימִין לְהוֹן:
@1386 וּמַלִּילוּ עִמֵּהּ יָת כָּל פִּתְגָּמֵי יוֹסֵף דִּי מַלִּיל עִמְּהוֹן וַחֲזָא יָת עֲגַלָּתָא דִּשְׁלַח יוֹסֵף לְמִטַּל יָתֵהּ וּשְׁרַת רוּחַ נְבוּאָה עַל יַעֲקֹב אֲבוּהוֹן:
@1387 וַאֲמַר יִשְׂרָאֵל סַגִּי לִי חֶדְוָא עַד כְּעַן יוֹסֵף בְּרִי קַיָּם אֱזֵיל וְאֶחֱזִנֵּהּ עַד לָא אֵמוּת:
@1388 וּנְטַל יִשְׂרָאֵל וְכָל דִּי לֵהּ וַאֲתָא לִבְאֵר שָׁבַע וּדְבַח דִּבְחִין לֵאלָהָא דְאֲבוּהִי יִצְחָק:
@1389 וַאֲמַר יְיָ לְיִשְׂרָאֵל בְּחֶזְוֵי דְלֵילְיָא וַאֲמַר יַעֲקֹב יַעֲקֹב וַאֲמַר הָא אֲנָא:
@1390 וַאֲמַר אֲנָא אֵל אֱלָהָא דְאָבוּךְ לָא תִדְחַל מִלְּמֵיחַת לְמִצְרַיִם אֲרֵי לְעַם סַגִּי אֲשֵׁוִּנָּךְ תַּמָּן:
@1391 אֲנָא אֵחוֹת עִמָּךְ לְמִצְרַיִם וַאֲנָא אַסֵּקִנָּךְ אַף אַסָּקָא וְיוֹסֵף יְשַׁוֵּי יְדוֹהִי עַל עֵינָיךְ:
@1392 וְקָם יַעֲקֹב מִבְּאֵרָא דְשָׁבַע וּנְטָלוּ בְנֵי יִשְׂרָאֵל יָת יַעֲקֹב אֲבוּהוֹן וְיָת טַפְלְהוֹן וְיָת נְשֵׁיהוֹן בַּעֲגַלְתָּא דִּי שְׁלַח פַּרְעֹה לְמִטַּל יָתֵהּ:
@1393 וּדְבָרוּ יָת גֵּיתֵיהוֹן וְיָת קִנְיָנְהוֹן דִּי קְנוֹ בְּאַרְעָא דִּכְנַעַן וַאֲתוֹ לְמִצְרָיִם יַעֲקֹב וְכָל בְּנוֹהִי עִמֵּהּ:
@1394 בְּנוֹהִי וּבְנֵי בְנוֹהִי עִמֵּהּ בְּנָתֵהּ וּבְנַת בְּנוֹהִי וְכָל זַרְעֵהּ אַיְתִי עִמֵּהּ לְמִצְרָיִם:
@1395 וְאִלֵּין שְׁמָהַת בְּנֵי יִשְׂרָאֵל דְּעַלּוּ לְמִצְרַיִם יַעֲקֹב וּבְנוֹהִי בּוּכְרָא דְיַעֲקֹב רְאוּבֵן:
@1396 וּבְנֵי רְאוּבֵן חֲנוֹךְ וּפַלּוּא וְחֶצְרֹן וְכַרְמִי:
@1397 וּבְנֵי שִׁמְעוֹן יְמוּאֵל וְיָמִין וְאֹהַד וְיָכִין וְצֹחַר וְשָׁאוּל בַּר כְּנַעֲנֵיתָא:
@1398 וּבְנֵי לֵוִי גֵּרְשׁוֹן קְהָת וּמְרָרִי:
@1399 וּבְנֵי יְהוּדָה עֵר וְאוֹנָן וְשֵׁלָה וָפֶרֶץ וָזָרַח וּמִית עֵר וְאוֹנָן בְּאַרְעָא דִּכְנַעַן וַהֲווֹ בְנֵי פֶרֶץ חֶצְרֹן וְחָמוּל:
@1400 וּבְנֵי יִשָּׂשכָר תּוֹלָע וּפֻוָּה וְיוֹב וְשִׁמְרוֹן:
@1401 וּבְנֵי זְבֻלוּן סֶרֶד וְאֵלוֹן וְיַחְלְאֵל:
@1402 אִלֵּין בְּנֵי לֵאָה דִּילִידַת לְיַעֲקֹב בְּפַדַּן אֲרָם וְיָת דִּינָה בְרַתֵּהּ כָּל נֶפֶשׁ בְּנוֹהִי וּבְנָתֵהּ תְּלָתִין וּתְלָת:
@1403 וּבְנֵי גָד צִפְיוֹן וְחַגִּי שׁוּנִי וְאֶצְבּוֹן עֵרִי וַאֲרוֹדִי וְאַרְאֵלִי:
@1404 וּבְנֵי אָשֵׁר יִמְנָה וְיִשְׁוָה וְיִשְׁוִי וּבְרִיעָה וְשֶׂרַח אֲחַתְהוֹן וּבְנֵי בְרִיעָה חֶבֶר וּמַלְכִּיאֵל:
@1405 אִלֵּין בְּנֵי זִלְפָּה דִי יְהַב לָבָן לְלֵאָה בְרַתֵּהּ וִילִידַת יָת אִלֵּין לְיַעֲקֹב שִׁית עֶשְׂרֵי נַפְשָׁא:
@1406 בְּנֵי רָחֵל אִתַּת יַעֲקֹב יוֹסֵף וּבִנְיָמִן:
@1407 וְאִתְיְלִידוּ לְיוֹסֵף בְּאַרְעָא דְמִצְרַיִם דִּילִידַת לֵהּ אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן יָת מְנַשֶּׁה וְיָת אֶפְרָיִם:
@1408 וּבְנֵי בִנְיָמִן בֶּלַע וָבֶכֶר וְאַשְׁבֵּל גֵּרָא וְנַעֲמָן אֵחִי וָרֹאשׁ מֻפִּים וְחֻפִּים וָאָרְדְּ:
@1409 אִלֵּין בְּנֵי רָחֵל דְּאִתְיְלִידוּ לְיַעֲקֹב כָּל נַפְשָׁא אַרְבָּעָה עֲשָׂר:
@1410 וּבְנֵי דָן חֻשִׁים:
@1411 וּבְנֵי נַפְתָּלִי יַחְצְאֵל וְגוּנִי וְיֵצֶר וְשִׁלֵּם:
@1412 אִלֵּין בְּנֵי בִלְהָה דִּיהַב לָבָן לְרָחֵל בְּרַתֵּהּ וִילִידַת יָת אִלֵּין לְיַעֲקֹב כָּל נַפְשָׁא שִׁבְעָא:
@1413 כָּל נַפְשָׁא דְּעַלָּא לְיַעֲקֹב לְמִצְרַיִם נָפְקֵי יַרְכֵּהּ בַּר מִנְּשֵׁי בְנֵי יַעֲקֹב כָּל נַפְשָׁתָא שִׁתִּין וְשִׁית:
@1414 וּבְנֵי יוֹסֵף דִּי אִתְיְלִידוּ לֵהּ בְּמִצְרַיִם נַפְשָׁתָא תְרֵין כָּל נַפְשָׁתָא לְבֵית יַעֲקֹב דְּעַלּוּ לְמִצְרַיִם שִׁבְעִין:
@1415 וְיָת יְהוּדָה שְׁלַח קֳדָמוֹהִי לְוַת יוֹסֵף לְפַנָּאָה קֳדָמוֹהִי לְגשֶׁן וַאֲתוֹ לְאַרְעָא דְגשֶׁן:
@1416 וְטַקֵּיס יוֹסֵף רְתִכּוֹהִי וּסְלֵיק לְקַדָּמוּת יִשְׂרָאֵל אֲבוּהִי לְגשֶׁן וְאִתְגְּלִי לֵהּ וּנְפַל עַל צַוְארֵהּ וּבְכָא עַל צַוְארֵהּ עוֹד:
@1417 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף אִלּוּ אֲנָא מָאִית זִמְנָא הָדָא מְנַחֵם אֲנָא בָּתַר דַּחֲזֵיתִי יָת אַפָיךְ אֲרֵי עַד כְּעַן אַתְּ קַיָּם:
@1418 וַאֲמַר יוֹסֵף לַאֲחוֹהִי וּלְבֵית אֲבוּהִי אֶסַּק וְאֵחַוֵּי לְפַרְעֹה וְאֵימַר לֵהּ אַחַי וּבֵית אַבָּא דִּי בְאַרְעָא דִּכְנַעַן עַלּוּ לְוָתִי:
@1419 וְגֻּבְרַיָּא רָעֵי עָנָא אֲרֵי גֻּבְרֵי מָרֵי גֵּיתֵי הֲווֹ וְעָנְהוֹן וְתוֹרְהוֹן וְכָל דִּי לְהוֹן אַיְתִיאוּ:
@1420 וִיהֵי אֲרֵי יִקְרֵי לְכוֹן פַּרְעֹה וְיֵימַר מָה עוֹבָדֵיכוֹן:
@1421 וְתֵימְרוּן גֻּבְרֵי מָרֵי גֵּיתֵי הֲווֹ עַבְדָּיךְ מֵעוּלֵמָנָא וְעַד כְּעַן אַף אֲנַחְנָא אַף אַבְהָתָנָא בְּדִיל דִּי תֵיתְבוּן בְּאַרְעָא דְגשֶׁן אֲרֵי מְרַחֲקִין מִצְרָאֵי כָּל רָעֵי עָנָא:
@1422 וַאֲתָא יוֹסֵף וְחַוִּי לְפַרְעֹה וַאֲמַר אַבָּא וְאַחַי וְעָנְהוֹן וְתוֹרְהוֹן וְכָל דִּי לְהוֹן אֲתוֹ מֵאַרְעָא דִּכְנָעַן וְהָא אִנּוּן בְּאַרְעָא דְגשֶׁן:
@1423 וּמִקְצַת מִן אֲחוֹהִי דְּבַר חַמְשָׁא גֻּבְרִין וַאֲקֵימִנּוּן קֳדָם פַּרְעֹה:
@1424 וַאֲמַר פַּרְעֹה לַאֲחוֹהִי מָה עוֹבָדֵיכוֹן וַאֲמָרוּ לְפַרְעֹה רָעֵי עָנָא עַבְדָּיךְ אַף אֲנַחְנָא אַף אֲבָהָתָנָא:
@1425 וַאֲמָרוּ לְוַת פַּרְעֹה לְאִתּוֹתָבָא בְאַרְעָא אֲתֵינָא אֲרֵי לֵית רַעֲיָא לְעָנָא דִּי לְעַבְדָּיךְ אֲרֵי תַקִּיף כַּפְנָא בְּאַרְעָא דִּכְנָעַן וּכְעַן יֵתְבוּן כְּעַן עַבְדָּיךְ בְּאַרְעָא דְגשֶׁן:
@1426 וַאֲמַר פַּרְעֹה לְיוֹסֵף לְמֵימָר אֲבוּךְ וְאַחָיךְ אֲתוֹ לְוָתָךְ:
@1427 אַרְעָא דְמִצְרַיִם קֳדָמָךְ הִיא בִּדְשַׁפִּיר בְּאַרְעָא אוֹתֵיב יָת אֲבוּךְ וְיָת אַחָיךְ יֵתְבוּן בְּאַרְעָא דְגשֶׁן וְאִם יָדַעְתְּ וְאִית בְּהוֹן גֻּבְרִין דְּחֵילָא וּתְמַנִּנוּן רַבָּנֵי גֵיתֵי עַל דִּי לִי:
@1428 וְאַיְתִי יוֹסֵף יָת יַעֲקֹב אֲבוּהִי וַאֲקִימִנֵּהּ קֳדָם פַּרְעֹה וּבְרִיךְ יַעֲקֹב יָת פַּרְעֹה:
@1429 וַאֲמַר פַּרְעֹה לְּיַעֲקֹב כַּמָּה יוֹמֵי שְׁנֵי חַיָּיךְ:
@1430 וַאֲמַר יַעֲקֹב לְפַרְעֹה יוֹמֵי שְׁנֵי תוֹתָבוּתַי מְאָה וּתְלָתִין שְׁנִין זְעֵירִין וּבִישִׁין הֲווֹ יוֹמֵי שְׁנֵי חַיַּי וְלָא אַדְבִּיקוּ יָת יוֹמֵי שְׁנֵי חַיֵּי אֲבָהָתַי בְּיוֹמֵי תּוֹתָבוּתְהוֹן:
@1431 וּבָרִיךְ יַעֲקֹב יָת פַּרְעֹה וּנְפַק מִן קֳדָם פַּרְעֹה:
@1432 וְאוֹתֵיב יוֹסֵף יָת אֲבוּהִי וְיָת אֲחוֹהִי וִיהַב לְהוֹן אַחֲסָנָא בְּאַרְעָא דְמִצְרַיִם בִּדְשַׁפִּיר בְּאַרְעָא בְּאַרְעָא דְרַעְמְסֵס כְּמָא דִי פַקֵּיד פַרְעֹה:
@1433 וְזָן יוֹסֵף יָת אֲבוּהִי וְיָת אֲחוֹהִי וְיָת כָּל בֵּית אֲבוּהִי לַחְמָא לְפוּם טַפְלָא:
@1434 וְלַחֲמָא לֵית בְּכָל אַרְעָא אֲרֵי תַקִּיף כַּפְנָא לַחֲדָא וְאִשְׁתַּלְהֵי עַמָּא דְאַרְעָא דְמִצְרַיִם וְעַמָּא דְאַרְעָא דִּכְנַעַן מִן קֳדָם כַּפְנָא:
@1435 וְלַקִּיט יוֹסֵף יָת כָּל כַּסְפָּא דְּאִשְׁתְּכַח בְּאַרְעָא דְמִצְרַיִם וּבְאַרְעָא דִּכְנַעַן בְּעִיבוּרָא דִּי אִנּוּן זָבְנִין וְאַיְתִי יוֹסֵף יָת כַּסְפָּא לְבֵית פַּרְעֹה:
@1436 וּשְׁלִים כַּסְפָא מֵאַרְעָא דְמִצְרַיִם וּמֵאַרְעָא דִּכְנַעַן וַאֲתוֹ כָּל מִצְרָאֵי לְוַת יוֹםֵף לְמֵימַר הַב לָנָא לַחֲמָא וּלְמָה נְמוּת לְקִבְלָךְ אֲרֵי שְׁלִים כַּסְפָּא:
@1437 וַאֲמַר יוֹסֵף הָבוּ גֵּיתֵיכוֹן וְאֶתֵּן לְכוֹן בְּגֵּיתֵיכוֹן אִם שְׁלִים כַּסְפָּא:
@1438 וְאַיְתִיּוּ יָת גֵּיתֵיהוֹן לְוַת יוֹסֵף וִיהַב לְהוֹן יוֹסֵף לַחְמָא בְּסוּסְוָתָא וּבְגֵיתֵי עָנָא וּבְגֵיתֵי תוֹרִין וּבַחֲמָרִין וְזָנִנּוּן בְּלַחֲמָא בְּכָל גֵּיתֵיהוֹן בְּשַׁתָּא הַהִיא:
@1439 וּשְׁלִימַת שַׁתָּא הַהִיא וַאֲתוֹ לְוָתֵהּ בְּשַׁתָּא תִנְיֵתָא וַאֲמָרוּ לֵהּ לָא נְכַסֵּי מִן רִבּוֹנִי אֶלָּהֵין שְׁלִים כַּסְפָּא וְגֵּיתֵי בְעִירָא לְוַת רִבּוֹנִי לָא אִשְׁתָּאַר קֳדָם רִבּוֹנִי אֶלָּהֵין גְּוִיָתָנָא וְאַרְעָנָא:
@1440 לְמָה נְמוּת לְעֵינָיךְ אַף אֲנַחְנָא אַף אַרְעָתָנָא קְנֵי יָתָנָא וְיָת אַרְעָתָנָא בְּלַחְמָא וּנְהֵי אֲנַחְנָא וְאַרְעָתָנָא עַבְדִּין לְפַרְעֹה וְהַב בַּר זַרְעָא וְנֵיחֵי וְלָא נְמוּת וְאַרְעָא לָא תְבוּר:
@1441 וּקְנָא יוֹסֵף יָת כָּל אַרְעָא דְמִצְרַיִם לְפַרְעֹה אֲרֵי זַבִּינוּ מִצְרַיִם גְּבַר חַקְלֵהּ אֲרֵי תְקֵיף עֲלֵיהוֹן כַּפְנָא וַהֲוַת אַרְעָא לְפַרְעֹה:
@1442 וְיָת עַמָּא אַעְבֵּר יָתֵהּ מִקְּרֵי לִקְרֵי מִסְּיָפֵי תְּחוּם מִצְרַיִם וְעַד סוֹפֵהּ:
@1443 לְחוֹד אַרְעָא דְכֻמָּרַיָּא לָא זַבִּין אֲרֵי חֳלָקָא לְכֻמָּרַיָּא מִלְּוַת פַּרְעֹה וְאָכְלִין יָת חֳלָקְהוֹן דִּי יְהַב לְהוֹן פַּרְעֹה עַל כֵּן לָא זַבִּינוּ יָת אַרְעֲהוֹן:
@1444 וַאֲמַר יוֹסֵף לְעַמָּא הָא זְבֵנִית יָתְכוֹן יוֹמָא דֵּין וְיָת אַרְעֲכוֹן לְפַרְעֹה הֵא לְכוֹן בַּר זַרְעָא וְתִזְרְעוּן יָת אַרְעָא:
@1445 וִיהֵי בְּאָעוֹלֵי עֲלַלְתָּא וְתִתְּנוּן חַד מִן חַמְשָׁא לְפַרְעֹה וְאַרְבַּע חֳלָקִין יְהֵא לְכוֹן לְבַר זְרַע חַקְלָא וּלְמֵיכַלְכוֹן וְלֶאֱנַשׁ בָתֵּיכוֹן וּלְמֵיכַל לְטַפְלְכוֹן:
@1446 וַאֲמָרוּ קַיִּמְתָּנָא נִשְׁכַּח רַחֲמִין בְּעֵינֵי רִבּוֹנִי וּנְהֵי עַבְדִּין לְפַרְעֹה:
@1447 וְשַׁוִּי יָתַהּ יוֹסֵף לִגְזֵרָא עַד יוֹמָא הָדֵין עַל אַרְעָא דְמִצְרַיִם דִּיהוֹן יָהֲבִין חַד מִן חַמְשָׁא לְפַרְעֹה לְחוֹד אַרְעָא דְכֻמָּרַיָּא בִּלְחוֹדֵיהוֹן לָא הֲוַת לְפַרְעֹה:
@1448 וִיתֵיב יִשְׂרָאֵל בְּאַרְעָא דְמִצְרַיִם בְּאַרְעָא דְגשֶׁן וְאַחֲסִינוּ בַהּ וּנְפִישׁוּ וּסְגִיאוּ לַחֲדָא:
@1449 וַחֲיָא יַעֲקֹב בְּאַרְעָא דְמִצְרַיִם שְׁבַע עֶשְׂרֵי שְׁנִין וַהֲווֹ יוֹמֵי יַעֲקֹב שְׁנֵי חַיוֹהִי מְאָה וְאַרְבְּעִין וּשְׁבַע שְׁנִין:
@1450 וּקְרִיבוּ יוֹמֵי יִשְׂרָאֵל לִמְמַת וּקְרָא לִבְרֵהּ לְיוֹסֵף וַאֲמַר לֵהּ אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינָיךְ שַׁוִּי כְעַן יְדָךְ תְּחוֹת יַרְכִּי וְתַעְבֵּד עִמִּי טִיבוּ וּקְשׁוֹט לָא כְעַן תִּקְבְּרִנַּנִי בְּמִצְרַיִם:
@1451 וְאִשְׁכּוּב עִם אֲבָהָתַי וְתִטְּלִנַנִּי מִמִּצְרַיִם וְתִקְבְּרִנַנִּי בִּקְבֻרְתְּהוֹן וַאֲמַר אֲנָא אֶעְבַּד כְּפִתְגָּמָךְ:
@1452 וַאֲמַר קַיֵּם לִי וְקַיִים לֵהּ וּסְגִיד יִשְׂרָאֵל עַל רֵישׁ עַרְסָא:
@1453 וַהֲוָה בָּתַר פִּתְגָּמַיָּא הָאִלֵּין וַאֲמַר לְיוֹסֵף הָא אֲבוּךְ שְׁכִיב מְרָע וּדְבַר יָת תְּרֵין בְּנוֹהִי עִמֵּהּ יָת מְנַשֶּׁה וְיָת אֶפְרָיִם:
@1454 וְחַוִּי לְיַעֲקֹב וַאֲמַר הָא בְּרָךְ יוֹסֵף אֲתָא לְוָתָךְ וְאִתַּקַף יִשְׂרָאֵל וִיתֵיב עַל עַרְסָא:
@1455 וַאֲמַר יַעֲקֹב לְיוֹסֵף אֵל שַׁדַּי אִתְגְּלִי לִי בְלוּז בְּאַרְעָא דִכְנָעַן וּבָרִיךְ יָתִי:
@1456 וַאֲמַר לִי הָא אֲנָא מַפְשִׁינָךְ וְאַסְגִּנָּךְ וְאֶתְּנִנָּךְ לְכִנְשַׁת שִׁבְטִין וְאֶתֵּן יָת אַרְעָא הָדָא לִבְנָיךְ בַּתְרָךְ אַחֲסָנַת עֲלָם:
@1457 וּכְעַן תְּרֵין בְּנָיךְ דְּאִתְיְלִידוּ לָךְ בְּאַרְעָא דְמִצְרַיִם עַד מֵיתִי לְוָתָךְ לְמִצְרַיִם דִּילִי אִנּוּן אֶפְרַיִם וּמְנַשֶּׁה כִּרְאוּבֵן וְשִׁמְעוֹן יְהוֹן קֳדָמָי:
@1458 וּבְנָיךְ דִּי תוֹלִיד בַּתְרֵיהוֹן דִּילָךְ יְהוֹן עַל שׁוּם אֲחוּהוֹן יִתְקְרוּן בְּאַחֲסַנְתְּהוֹן:
@1459 וַאֲנָא בְּמֵיתִי מִפַּדָן מִיתַת עָלַי רָחֵל בְּאַרְעָא דִּכְנַעַן בְּאָרְחָא בְּעוֹד כְּרוּבָא דְאַרְעָא לְמֵיעַל לְאֶפְרָת וּקְבָרִתַּהּ תַּמָּן בְּאֹרַח אֶפְרָת הִיא בֵּית לָחֶם:
@1460 וַחֲזָא יִשְׂרָאֵל יָת בְּנֵי יוֹסֵף וַאֲמַר מַן אִלֵּין:
@1461 וַאֲמַר יוֹסֵף לַאֲבוּהִי בְּנַי אִנּוּן דִּי יְהַב לִי יְיָ הָכָא וַאֲמַר קָרֵבִנּוּן כְּעַן לְוָתִי וְאֵבָרֵכִנּוּן:
@1462 וְעֵינֵי יִשְׂרָאֵל יְקָרָן מִסֵּיבוּ לָא יִכּוּל לְמֶחֱזֵי וְקָרִיב יָתְהוֹן לְוָתֵהּ וְנַשִּׁיק לְהוֹן וְגַפִּיף לְהוֹן:
@1463 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף לְמֶחֱזֵי אַפָיךְ לָא סְבָרִית וְהָא אַחֲזִי יָתִי יְיָ אַף יָת בְּנָיךְ:
@1464 וְאַפֵּיק יוֹסֵף יָתְהוֹן מִן קֳדָמוֹהִי וּסְגִיד עַל אַפּוֹהִי עַל אַרְעָא:
@1465 וּדְבַר יוֹסֵף יָת תַּרְוֵיהוֹן יָת אֶפְרַיִם בִּימִינֵהּ מִשְׂמָאלָא דְיִשְׂרָאֵל וְיָת מְנַשֶּׁה בִשְׂמָאלֵהּ מִימִינָא דְיִשְׂרָאֵל וְקָרֵיב לְוָתֵהּ:
@1466 וְאוֹשִׁיט יִשְׂרָאֵל יָת יְמִינֵהּ וְשַׁוִּי עַל רֵישָׁא דְאֶפְרַיִם וְהוּא זְעֵירָא וְיָת שְׂמָאלֵהּ עַל רֵישָׁא דִּמְנַשֶּׁה אַחְכִּמִינּוּן לִידוֹהִי אֲרֵי מְנַשֶּׁה בּוּכְרָא:
@1467 וּבְרִיךְ יָת יוֹסֵף וַאֲמָר יְיָ דִי פְלָחוּ אֲבָהָתַי קֳדָמוֹהִי אַבְרָהָם וְיִצְחָק יְיָ דְזַן יָתִי מִדְאִיתָנִי עַד יוֹמָא הָדֵין:
@1468 מַלְאָכָא דִי פְרַק יָתִי מִכָּל בִּישָׁא יְבָרֵךְ יָת עוּלֵמַיָּא וְיִתְקְרֵי בְהוֹן שְׁמִי וְשׁוּם אֲבָהָתַי אַבְרָהָם וְיִצְחָק וּכְנוּנֵי יַמָּא יִסְגוּן בְּגוֹ בְנֵי אֱנָשָׁא עַל אַרְעָא:
@1469 וַחֲזָא יוֹסֵף אֲרֵי שַׁוִּי אָבוּהִי יַד יְמִינֵהּ עַל רֵישָׁא דְאֶפְרַיִם וּבְאֵישׁ בְּעֵינוֹהִי וְסָעֵד יְדָא דְאָבוּהִי לְאַעֲדָאָה יָתַהּ מֵעַל רֵישָׁא דְאֶפְרַיִם לְאַנָחוּתַהּ עַל רֵישָׁא דִמְנַשֶּׁה:
@1470 וַאֲמַר יוֹסֵף לְאָבוּהִי לָא כֵן אַבָּא אֲרֵי דֵין בּוּכְרָא שַׁו יְמִינָךְ עַל רֵישֵׁהּ:
@1471 וְסָרֵיב אָבוּהִי וַאֲמַר יְדַעְנָא בְרִי יְדַעְנָא אַף הוּא יְהֵי לְעַמָּא וְאַף הוּא יִסְגֵּי וּבְרַם אָחוּהִי זְעִירָא יִסְגֵּי מִנֵּהּ וּבְנוֹהִי יְהוֹן שַׁלִּיטִין בְּעַמְמַיָּא:
@1472 וּבְרֵיכִנּוּן בְּיוֹמָא הַהוּא לְמֵימַר בָּךְ יְבָרֵךְ יִשְׂרָאֵל לְמֵימַר יְשַׁוִּינָךְ יְיָ כְּאֶפְרַיִם וְכִמְנַשֶּׁה וְשַׁוִּי יָת אֶפְרַיִם קֳדָם מְנַשֶּׁה:
@1473 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף הָא אֲנָא מָאִית וִיהֵי מֵימְרָא דַיְיָ בְּסַעְדְכוֹן וְיָתֵיב יָתְכוֹן לְאַרְעָא דַאֲבָהַתְכוֹן:
@1474 וַאֲנָא יְהָבִית לָךְ חוּלַק חַד יַתִּיר עַל אַחָיךְ דִּי נְסֵיבִית מִידָא דֶאֱמוֹרָאָה בִּצְלוֹתִי וּבְבָעוּתִי:
@1475 וּקְרָא יַעֲקֹב לִבְנוֹהִי וַאֲמַר אִתְכַּנָשׁוּ וַאֲחַוֵּי לְכוֹן יָת דִּי יְעָרַע יָתְכוֹן בְּסוֹף יוֹמַיָּא:
@1476 אִתְכַּנָּשׁוּ וּשְׁמָעוּ בְּנֵי יַעֲקֹב וְקַבִּילוּ אוּלְפַן מִן יִשְׂרָאֵל אֲבוּכוֹן:
@1477 רְאוּבֵן בּוּכְרִי אַתְּ חֵילִי וְרֵישׁ תָּקְפִּי לָךְ הֲוָה חָזֵי לְמִסַּב תְּלָתָא חוּלָקִין בְּכֵירוּתָא כְּהֻנְתָּא וּמַלְכוּתָא:
@1478 עַל דַאֲזַלְתָּא לָקֳבֵל אַפָּיךְ הָא כְמַיָּא בְּרַם לָא אַהֲנֵיתָא חוֹלָק יַתִּיר לָא תִסַּב אֲרֵי סְלֶקְתָּא בֵּית מִשְׁכָּבֵי אָבוּךְ בְּכֵן אֲחֶלְתָּא לְשִׁוּוּיִי בְּרִי סְלֶקְתָּא:
@1479 שִׁמְעוֹן וְלֵוִי אַחִין גַּבְרִין גִּבָּרִין בְּאַרַע תּוֹתָבוּתְהוֹן עֲבָדוּ גְּבוּרָא:
@1480 בְּרָזְהוֹן לָא הֲוַת נַפְשִׁי בְּאִתְכַּנְשֵׁהוֹן לִמְהַךְ לָא נְחָתִית מִן יְקָרִי אֲרֵי בְרָגְזְהוֹן קְטָלוּ קְטוֹל וּבִרְעוּתְהוֹן תַּרָעוּ שׁוּר סַנְּאָה:
@1481 לִיט רָגְזְהוֹן אֲרֵי תַקִיף וְחֵמַתְהוֹן אֲרֵי קַשְׁיָא אֲפַלְגִנוּן בְּיַעֲקֹב וְאֵבַדָרִנוּן בְּיִשְׂרָאֵל:
@1482 יְהוּדָה אַתְּ אוֹדֵיתָא וְלָא בְהֵיתְתָא בָּךְ יוֹדוּן אַחָיךְ יְדָךְ תִּתְקֵף עַל בַּעֲלֵי דְבָבָךְ יִתְבַּדְרוּן סַנְאָךְ יְהוֹן מְחַזְרִין קְדַּל קֳדָמָךְ וִיְהוֹן מְקַדְמִין לְמִשְׁאַל בִּשְׁלָמָךְ בְּנֵי אָבוּךְ:
@1483 שִׁלְטוֹן יְהֵי בְשֵׁרוּיָא וּבְסוֹפָא יִתְרַבָּא מַלְכָּא מִדְבֵית יְהוּדָה אֲרֵי מִדִין קַטְלָא בְּרִי נַפְשָׁךְ סְלֶקְתָּא יְנוּחַ יִשְׁרֵי בִתְקוֹף כְּאַרְיָא וּכְלֵיתָא וְלֵית מַלְכוּ דִתְזַעְזְעִנֵהּ:
@1484 לָא יַעֲדֵי עָבֵד שָׁלְטַן מִדְבֵית יְהוּדָה וְסַפְרָא מִבְּנֵי בְנוֹהִי עַד עָלְמָא עַד דְיֵיתֵי מְשִׁיחָא דְדִילֵהּ הִיא מַלְכוּתָא וְלֵהּ יִשְׁתַּמְעוּן עַמְמַיָּא:
@1485 יַסְחַר יִשְׂרָאֵל לְקַרְתֵּהּ עַמָּא יִבְנוּן הֵיכְלֵהּ יְהוֹן צַדִּיקַיָּא סְחוֹר סְחוֹר לֵהּ וְעָבְדֵי אוֹרַיְתָא בְּאוּלְפַן עִמֵּהּ יְהֵי אַרְגְוָן טַב לְבוּשׁוֹהִי כְּסוּתֵהּ מֵילָא מֵילָא צְבַע זְהוֹרִי:וצִבְעוֹנִין:
@1486 ??? יְסַמְקוּן טּוּרוֹהִי בְּכַרְמוֹהִי יְטוּפוּן נַעֲווֹהִי בַּחֲמָר יְחַוְרָן בִּקְעֲתֵהּ בְּעִיבוּר וּבְעֶדְרֵי עָנָא:
@1487 זְבוּלֻן עַל סְפַר יַמְמַיָּא יִשְׁרֵי וְהוּא יְכַבֵּשׁ מְחוֹזִין בִּסְפִינַן וְטוּב יַמָּא יֵיכוּל וּתְחוּמֵהּ יְהֵי מָטֵי עַל צִידוֹן:
@1488 יִשָּׂשׂכָר עַתִּיר בְּנִכְסִין וְאַחֲסַנְתֵּהּ בֵּין תְּחוּמַיָּא:
@1489 וַחֲזָא חוּלָקָא אֲרֵי טַב וְיָת אַרְעָא אֲרֵי מְעַבְּדָא פֵירִין וִיכַבֵּשׁ מָחוֹזֵי עַמְמַיָּא וִישֵׁיצֵי יָת דַּיָרֵיהוֹן וּדְאִשְׁתַּאֲרוּן בְּהוֹן יְהוֹן לֵהּ פַּלְחִין וּמַסְּקֵי מַסִּין:
@1490 מִדְּבֵית דָּן יִתְבְּחַר וִיקוּם גַּבְרָא בְּיוֹמוֹהִי יִתְפְּרֵק עַמֵּהּ וּבִשְׁנוֹהִי יְנוּחוּן כַּחֲדָא שִׁבְטַּיָּא דְיִשְׂרָאֵל:
@1491 יְהֵי גַבְרָא דְיִתְבְּחַר וִיקוּם מִדְּבֵית דָּן אֵימְתֵהּ תִּתְרְמֵי עַל עַמְמַיָּא וּמְחָתֵהּ תִּתְקֵף בִּפְלִשְׁתָּאֵי כְּחִיוֵי חוּרְמָן יִשְׁרֵי עַל אָרְחָא וּכְפִתְנָא יִכְמוֹן עַל שְׁבִילָא יְקַטֵּיל גִּבָּרֵי מַשִׁרְיַת פְּלִשְׁתָּאֵי פָּרָשִׁין עִם רַגְלָאִין יְעַקֵר סוּסָוָן וּרְתִכִּין וִימַגֵּר רוֹכְבֵיהוֹן לַאֲחוֹרָא:
@1492 לְפוּרְקָנָךְ סַבָּרִית יְיָ:
@1493 מִדְבֵית גָד מַשִׁרְיַת מְזַיְנִין כַּד יַעַבְרוּן יָת יַרְדְנָא קֳדָם אֲחֵיהוֹן לִקְרָבָא וּבְנִכְסִין סַגִּיאִין יְתוּבוּן לְאַרְעֲהוֹן:
@1494 דְאָשֵׁר טָבָא אַרְעֵהּ וְהוּא מְרַבְיָא בְּתַפְנוּקֵי מַלְכִין:
@1495 נַפְתָּלִי בְּאַרַע טָבָא יִתְרְמֵי עַדְבֵהּ וְאַחְסַנְתֵּהּ תְּהֵי מְעַבְּדָא פֵירִין יְהוֹן מוֹדַן וּמְבָרְכִין עֲלֵיהוֹן:
@1496 בְּרִי דְיִסְגֵּי יוֹסֵף בְּרִי דְיִתְבָּרַךְ כְּגֹפֶן דִּנְצִב עַל עֵינָא דְמַיָּא תְּרֵין שִׁבְטִין יִפְּקוּן מִבְּנוֹהִי יְקַבְּלוּן חוּלָקָא וְאַחֲסַנְתָּא:
@1497 וְאִתְמַרְרוּ יָתֵהּ וְנַקְמוֹהִי וְאָעִיקוּ לֵהּ גֻבְרִין גִּבָּרִין בַּעֲלֵי פַלְגוּתָא:
@1498 וְתָבַת בְּהוֹן נְבִיאוּתֵהּ עַל דְּקַיֵּם אוֹרַיְתָא בְּסִתְרָא וְשַׁוִּי בְתוּקְפָא רוֹחֲצָנֵהּ בְּכֵן יִתְרְמָא דְהַב עַל דְּרָעוֹהִי וְאַחֲסִין מַלְכוּתָא וּתְקֵיף דָּא הֲוַת לֵהּ מִן קֳדָם אֵל תַּקִיפָא דְיַעֲקֹב דִּי בְמֵימְרֵהּ זַן אֲבָהָן וּבְנִין זַרְעָא דְיִשְׂרָאֵל:
@1499 מֵימַר אֱלָהָא דְאָבוּךְ יְהֵי בְסַעְדָךְ וְיָת שַׁדַּי וִיבָרְכִנָּךְ בִּרְכַן דְּנַחֲתָן מִטַּלָּא דִשְׁמַיָּא מִלְעֵלָא בִּרְכַן דְנַגְדַן מִמַעֲמַקֵי אַרְעָא מִלְרָע בִּרְכְּתָא דְאָבוּךְ וּדְאִמָּךְ:
@1500 בִּרְכְּתָא דְאָבוּךְ יִתּוֹסְפָן עַל בִּרְכְּתָא דִילִי בָּרִיכוּ אֲבָהָתַי דַחֲמִידוּ לְהֶן רַבְרְבַיָּא דְמִן עָלְמָא יֶהֶוְיַן כָּל אִלֵּין לְרֵישָׁא דְיוֹסֵף וּלְגַבְרָא פָּרִישָׁא דַאֲחוֹהִי:
@1501 בִּנְיָמִין בְּאַרְעֵהּ תִּשְׁרֵי שְׁכִנְתָּא וּבְאַחֲסַנְתֵּהּ יִתְבְּנֵי מַקְדְשָׁא בְּצַפְרָא וּבְפַנְיָא יְהוֹן מְקָרְבִין כַּהֲנַיָּא קָרְבָּנָא וּבְעִדַּן רַמְשָׁא יְהוֹן מְפַלְגִין מוֹתַר חוּלְקְהוֹן מִשְׁאַר קָדְשַׁיָּא:
@1502 כָּל אִלֵּין שִׁבְטַיָּא דְיִשְׂרָאֵל תְּרֵין עֲסַר וְדָא דְמַלֵּיל לְהוֹן אֲבוּהוֹן וּבָרִיךְ יָתְהוֹן גְבַר דִּי כְבִרְכְּתֵהּ בָּרֵךְ יָתְהוֹן:
@1503 וּפַקֵד יָתְהוֹן וַאֲמַר לְהוֹן אֲנָא מִתְכְּנֵשׁ לְעַמִּי קְבָרוּ יָתִי לְוַת אֲבָהָתִי בִּמְעַרְתָּא דִי בַחֲקַל עֶפְרוֹן חִתָּאָה:
@1504 בִּמְעַרְתָּא דִי בַחֲקַל כָּפֶלְתָּא דִי עַל אַפֵּי מַמְרֵא בְּאַרְעָא דִכְנָעַן דִי זְבַן אַבְרָהָם יָת חַקְלָא מִן עֶפְרֹן חִתָּאָה לְאַחֲסָנַת קְבוּרָא:
@1505 תַּמָּן קְבָרוּ יָת אַבְרָהָם וְיָת שָׂרָה אִתְּתֵהּ תַּמָּן קְבָרוּ יָת יִצְחָק וְיָת רִבְקָה אִתְּתֵהּ וְתַמָּן קְבָרִית יָת לֵאָה:
@1506 זְבִינֵי חַקְלָא וּמְעַרְתָּא דִי בֵהּ מִן בְּנֵי חִתָּאָהּ:
@1507 וְשֵׁיצֵי יַעֲקֹב לְפַקָּדָא יָת בְּנוֹהִי וּכְנַשׁ רַגְלוֹהִי לְעַרְסָא וְאִתְנְגִיד וְאִתְכְּנִישׁ לְעַמֵּהּ:
@1508 וּנְפַל יוֹסֵף עַל אַפֵּי אָבוּהִי וּבְכָא עֲלוֹהִי וּנְשַׁק לֵהּ:
@1509 וּפַקֵּיד יוֹסֵף יָת עַבְדוֹהִי יָת אַסְוָתָא לְמֶחְנַט יָת אָבוּהִי וְחָנְטוּ אַסְוָתָא יָת יִשְׂרָאֵל:
@1510 וּשְׁלִימוּ לֵהּ אַרְבְּעִין יוֹמִין אֲרֵי כֵּן שְׁלִימוּ יוֹמֵי חֲנִיטַיָּא וּבְכוֹ יָתֵהּ מִצְרָאֵי שַׁבְעִין יוֹמִין:
@1511 וַעֲבָרוּ יוֹמֵי בְכִיתֵהּ וּמַלִיל יוֹסֵף עִם בֵּית פַּרְעֹה לְמֵימָר אִם כְּעַן אַשְׁכָּחִית רַחֲמִין בְּעֵינֵיכוֹן מַלִּילוּ כְעַן קֳדָם פַּרְעֹה לְמֵימָר:
@1512 אַבָּא קַיֵּים עָלַי לְמֵימָר הָא אֲנָא מָאִית בְּקִבְרִי דְאַתְקֵנִית לִי בְּאַרְעָא דִכְנָעַן תַּמָּן תִּקְבְּרִנָנִי וּכְעַן אֶסַּק כְּעַן וְאֶקְבַּר יָת אַבָּא וְאֵ יתוּב:
@1513 וַאֲמַר פַּרְעֹה סַק וּקְבוֹר יָת אֲבוּךְ כְּמָא דְקַיֵּים עֲלָךְ:
@1514 וּסְלֵיק יוֹסֵף לְמִקְבַּר יָת אָבוּהִי וּסְלִיקוּ עִמֵּהּ כָּל עַבְדֵי פַרְעֹה סָבֵי בֵיתֵהּ וְכֹל סָבֵי אַרְעָא דְמִצְרָיִם:
@1515 וְכֹל בֵּית יוֹסֵף וַאֲחוֹהִי וּבֵית אָבוּהִי לְחוֹד טַפְלְהוֹן וְעָנְהוֹן וְתוֹרֵיהוֹן שְׁבָקוּ בְּאַרְעָא דְגשֶׁן:
@1516 וּסְלִיקוּ עִמֵּהּ אַף רְתִכִּין אַף פָּרָשִׁין וַהֲוָה מַשְׁרִיתָא סַגִּיאָה לַחֲדָא:
@1517 וַאֲתוֹ עַד בֵּית אִדְרֵי דְאָטָד דִּי בְּעִבְרָא דְיַרְדְנָא וּסְפָדוּ תַמָּן מִסְפֵּד רַב וְתַקִּיף לַחֲדָא וְעָבַד לַאֲבוּהִי אֶבְלָא שַׁבְעָא יוֹמִין:
@1518 וַחֲזָא יָתֵב אַרְעָא כְנַעֲנָאָה יָת אֶבְלָא בְּבֵית אִדְרֵי דְאָטָד וַאֲמָרוּ אָבֵל תַּקִּיף דֵּין לְמִצְרָאֵי עַל כֵּן קְרָא שְׁמַהּ אָבֵל מִצְרַיִם דִּי בְּעִבְרָא דְיַרְדְנָא:
@1519 וַעֲבָדוּ בְּנוֹהִי לֵהּ כֵּן כְּמָא דִי פַּקֵדִנּוּן:
@1520 וּנְטָלוּ יָתֵהּ בְּנוֹהִי לְאַרְעָא דִכְנַעַן וּקְבָרוּ יָתֵהּ בִּמְעָרַת חֲקַל כָּפֶלְתָּא דִי זְבַן אַבְרָהָם יָת חַקְלָא לְאַחֲסָנַת קְבוּרָא מִן עֶפְרֹן חִתָּאָה עַל אַפֵּי מַמְרֵא:
@1521 וְתַב יוֹסֵף לְמִצְרַיִם הוּא וַאֲחוֹהִי וְכָל דִּסְלִיקוּ עִמֵּהּ לְמִקְבַּר יָת אָבוּהִי בָּתַר דִּקְבַר יָת אָבוּהִי:
@1522 וַחֲזוֹ אֲחֵי יוֹסֵף אֲרֵי מִית אֲבוּהוֹן וַאֲמָרוּ דִּלְמָא יִטַּר לָנָא דְבָבוּ יוֹסֵף וְאֲתָבָא יָתֵיב לָנָא יָת כָּל בִּישְׁתָא דִי גְמַלְנָא יָתֵהּ:
@1523 וּפַקִידוּ לְוַת יוֹסֵף לְמֵימָר אָבוּךְ פַּקֵּד קֳדָם מוֹתֵהּ לְמֵימָר:
@1524 כְּדֵין תֵּימְרוּן לְיוֹסֵף בְּבָעוּ שְׁבוֹק כְּעַן לְחוֹבָא אַחָיךְ וְלַחֲטָאֵהוֹן אֲרֵי בִישְׁתָא גְמָלוּךְ וּכְעַן שְׁבוֹק כְּעַן לְחוֹבָא עַבְדֵי אֱלָהָא דְאָבוּךְ וּבְכָא יוֹסֵף בְּמַלָלוּתְהוֹן עִמֵּהּ:
@1525 וַאֲזָלוּ אַף אֲחוֹהִי וּנְפָלוּ קֳדָמוֹהִי וַאֲמָרוּ הָא אֲנַחְנָא לָךְ לְעַבְדִין:
@1526 וַאֲמַר לְהוֹן יוֹסֵף לָא תִדַחֲלוּן אֲרֵי דַחֲלָא דַּיְיָ אֲנָא:
@1527 וְאַתּוּן חֲשַׁבְתּוּן עֲלַי בִּישָׁא מִן קֳדָם יְיָ אִתְחַשְׁבַת לְטָבָא בְּדִיל לְמֶעְבַּד כְּיוֹמָא הָדֵין לְקַיָּמָא עַם סַגִּי:
@1528 וּכְעַן לָא תִדַחֲלוּן אֲנָא אֵזוּן יָתְכוֹן וְיָת טַפְלְכוֹן וְנַחֵם יָתְהוֹן וּמַלֵּיל תַּנְחוּמִין עַל לִבְּהוֹן:
@1529 וִיתֵיב יוֹסֵף בְּמִצְרַיִם הוּא וּבֵית אָבוּהִי וַחֲיָא יוֹסֵף מְאָה וַעֲסַר שְׁנִין:
@1530 וַחֲזָא יוֹסֵף לְאֶפְרַיִם בְּנִין תְּלִיתָאִין אַף בְּנֵי מָכִיר בַּר מְנַשֶּׁה אִתְיְלִידוּ וְרַבִּי יוֹסֵף:
@1531 וַאֲמַר יוֹסֵף לַאֲחוֹהִי אֲנָא מָאִית וַיְיָ מִדְכַּר דְּכִיר יָתְכוֹן וְיִסַק יָתְכוֹן מִן אַרְעָא הָדָא לְאַרְעָא דִי קַיִים לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@1532 וְאוֹמֵי יוֹסֵף יָת בְּנֵי יִשְׂרָאֵל לְמֵימָר מִדְכַּר דְּכִיר יְיָ יָתְכוֹן וְתַסְקוּן יָת גַּרְמַי מִכָּא:
@1533 וּמִית יוֹסֵף בַּר מְאָה וַעֲסַר שְׁנִין וַחֲנָטוּ יָתֵהּ וְשָׂמוּהִי בָאֳרוֹנָא בְּמִצְרָיִם: חזק:

@1 **בראשית.** אמר רבי יצחק לא היה צריך להתחיל [את] התורה אלא (שמות יב ב) מהחודש הזה לכם, שהיא מצוה ראשונה שנצטוו [בה] ישראל, ומה טעם פתח בבראשית, משום כח מעשיו הגיד לעמו לתת להם נחלת גוים (תהלים קיא ו) , שאם יאמרו אמות העולם לישראל לסטים אתם, שכבשתם ארצות שבעה גוים, הם אומרים להם כל הארץ של הקדוש ברוך הוא היא, הוא בראה ונתנה לאשר ישר בעיניו, ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו: **בראשית ברא.** אין המקרא הזה אומר אלא דרשני, כמו שדרשוהו רבותינו זכרונם לברכה בשביל התורה שנקראת (משלי ח כב) ראשית דרכו, ובשביל ישראל שנקראו (ירמיה ב ג) ראשית תבואתו. ואם באת לפרשו כפשוטו כך פרשהו בראשית בריאת שמים וארץ והארץ היתה תהו ובהו וחשך ויאמר אלהים יהי אור. ולא בא המקרא להורות סדר הבריאה לומר שאלו קדמו, שאם בא להורות כך, היה לו לכתוב בראשונה ברא את השמים וגו' , שאין לך ראשית במקרא שאינו דבוק לתבה של אחריו, כמו (שם כו א) בראשית ממלכות יהויקים, (בראשית י י) ראשית ממלכתו, (דברים יח ד) ראשית דגנך, אף כאן אתה אומר בראשית ברא אלהים וגו' , כמו בראשית ברא. ודומה לו (הושע א ב) תחלת דבר ה' בהושע, כלומר תחלת דבורו של הקדוש ברוך הוא בהושע, ויאמר ה' אל הושע וגו' . ואם תאמר להורות בא שאלו תחלה נבראו, ופירושו בראשית הכל ברא אלו, ויש לך מקראות שמקצרים לשונם וממעטים תבה אחת, כמו (איוב ג י) כי לא סגר דלתי בטני, ולא פירש מי הסוגר, וכמו (ישעיה ח ד) ישא את חיל דמשק, ולא פירש מי ישאנו, וכמו (עמוס ו יב) אם יחרוש בבקרים, ולא פרש אם יחרוש אדם בבקרים, וכמו (ישעיה מו י) מגיד מראשית אחרית, ולא פרש מגיד מראשית דבר אחרית דבר. אם כן תמה על עצמך, שהרי המים קדמו, שהרי כתיב ורוח אלהים מרחפת על פני המים, ועדיין לא גלה המקרא בריאת המים מתי היתה, הא למדת שקדמו המים לארץ. ועוד שהשמים מאש ומים נבראו, על כרחך לא למד המקרא סדר המוקדמים והמאוחרים כלום: **ברא אלהים.** ולא אמר ברא ה', שבתחלה עלה במחשבה לבראתו במדת הדין, ראה שאין העולם מתקים, הקדים מדת רחמים ושתפה למדת הדין, היינו דכתיב (להלן ב ד) ביום עשות ה' אלהים ארץ ושמים:
@2 **תהו ובהו.** תהו לשון תמה ושממון שאדם תוהא ומשתומם על בהו שבה: **תהו.** אישטורדישו''ן בלע''ז [מבוכה]: **בהו.** לשון רקות וצדו: **על פני תהום.** על פני המים שעל הארץ. **ורוח אלהים מרחפת.** כסא הכבוד עומד באויר ומרחף על פני המים ברוח פיו של הקדוש ברוך הוא ובמאמרו, כיונה המרחפת על הקן אקוביטי''ר בלע''ז [לכסות]:
@4 **וירא אלהים את האור כי טוב ויבדל.** אף בזה אנו צריכים לדברי אגדה ראהו שאינו כדאי להשתמש בו רשעים והבדילו לצדיקים לעתיד לבא. ולפי פשוטו כך פרשהו ראהו כי טוב ואין נאה לו ולחשך שיהיו משתמשין בערבוביא, וקבע לזה תחומו ביום ולזה תחומו בלילה:
@5 **יום אחד.** לפי סדר [לשון] הפרשה היה לו לכתוב יום ראשון, כמו שכתב בשאר הימים שני, שלישי, רביעי. למה כתב אחד, לפי שהיה הקדוש ברוך הוא יחיד בעולמו שלא נבראו המלאכים עד יום שני, כך מפורש בבראשית רבה (ג ח) :
@6 **יהי רקיע.** יחזק הרקיע. שאף על פי שנבראו שמים ביום ראשון, עדיין לחים היו, וקרשו בשני מגערת הקדוש ברוך הוא באמרו יהי רקיע, וזהו שכתוב (איוב כו יא) עמודי שמים ירופפו כל יום ראשון. ובשני יתמהו מגערתו, כאדם שמשתומם ועומד מגערת המאיים עליו: **בתוך המים.** באמצע המים, שיש הפרש בין מים העליונים לרקיע כמו בין הרקיע למים שעל הארץ, הא למדת שהם תלוים במאמרו של מלך:
@7 **ויעש אלהים את הרקיע.** תקנו על עמדו והיא עשיתו, כמו (דברים כא יב) ועשתה את צפרניה: מעל לרקיע. על הרקיע לא נאמר אלא **מעל לרקיע.** לפי שהן תלויים באויר. ומפני מה לא נאמר כי טוב ביום שני, לפי שלא נגמרה מלאכת המים עד יום שלישי, והרי התחיל בה בשני, ודבר שלא נגמר אינו במלואו ובטובו, ובשלישי שנגמרה מלאכת המים והתחיל מלאכה אחרת וגמרה, כפל בו כי טוב שני פעמים, אחד לגמר מלאכת השני ואחד לגמר מלאכת היום:
@8 **ויקרא אלהים לרקיע שמים.** שא מים, שם מים, אש ומים, שערבן זה בזה ועשה מהם שמים:
@9 **יקוו המים.** [שהיו] שטוחין על פני כל הארץ והקום באוקינוס, הוא הים הגדול שבכל הימים:
@10 **קרא ימים.** והלא ים אחד הוא, אלא אינו דומה טעם דג העולה [מן הים] בעכו לטעם דג העולה [מן הים] באספמיא:
@11 **תדשא הארץ דשא עשב.** לא דשא לשון עשב ולא עשב לשון דשא, ולא היה לשון המקרא לומר תעשיב הארץ, שמיני דשאים מחלקין, כל אחד לעצמו נקרא עשב פלוני, ואין לשון למדבר לומר דשא פלוני, שלשון דשא הוא לבישת הארץ כשהיא מתמלאת בדשאים: **תדשא הארץ.** תתמלא ותתכסה לבוש עשבים. בלשון לעז נקרא דשא אירבידי''ץ [מכלול העשבים] כלן בערבוביא, וכל שורש לעצמו נקרא עשב: **מזריע זרע.** שיגדל בו זרעו לזרוע ממנו במקום אחר: **עץ פרי.** שיהא טעם העץ כטעם הפרי, והיא לא עשתה כן, אלא (פסוק יב) ותוצא הארץ עץ עשה פרי, ולא העץ פרי, לפיכך כשנתקלל אדם על עונו נפקדה גם היא על עונה ונתקללה: **אשר זרעו בו.** הן גרעני כל פרי, שמהן האילן צומח כשנוטעין אותן:
@12 **ותוצא הארץ** וגו' **.** אף על פי שלא נאמר למינהו בדשאין בציווייהן, שמעו שנצטוו האילנות על כך, ונשאו קל וחמר בעצמן, כמפורש באגדה בשחיטת חלין (חולין ס.) :
@14 **יהי מארת** וגו' **.** מיום ראשון נבראו, וברביעי צוה עליהם להתלות ברקיע, וכן כל תולדות שמים וארץ נבראו מיום ראשון, וכל אחד ואחד נקבע ביום שנגזר עליו, הוא שכתוב (פסוק א) את השמים, לרבות תולדותיהם, ואת הארץ, לרבות תולדותיה: **יהי מארת.** חסר וי''ו כתיב, על שהוא יום מארה ליפול אסכרה בתינוקות, הוא ששנינו ברביעי היו מתענים על אסכרה שלא תפל בתינוקות: **להבדיל בין היום ובין הלילה.** משנגנז האור הראשון, אבל בשבעת ימי בראשית שמשו האור והחשך הראשונים יחד בין ביום ובין בלילה: **והיו לאתת.** כשהמאורות לוקין סימן רע הוא לעולם, שנאמר (ירמיה י ב) מאותות השמים אל תחתו, בעשותכם רצון הקדוש ברוך הוא אין אתם צריכין לדאג מן הפרענות: **ולמועדים.** על שם העתיד, שעתידים ישראל להצטוות על המועדות, והם נמנים למולד הלבנה: **ולימים.** שמוש החמה חצי יום ושמוש הלבנה חציו, הרי יום שלם: **ושנים.** לסוף שלש מאות ששים וחמשה ימים יגמרו מהלכם בשנים עשר מזלות המשרתים אותם והיא שנה. (וחוזרים ומתחילים פעם שניה לסבב בגלגל כמהלכן הראשון) :
@15 **והיו למאורות.** עוד זאת ישמשו שיאירו לעולם:
@16 **המארת הגדלים** וגו' **.** שוים נבראו, ונתמעטה הלבנה על שקטרגה ואמרה אי אפשר לשני מלכים שישתמשו בכתר אחד: **ואת הכוכבים.** על ידי שמיעט את הלבנה, הרבה צבאיה להפיס דעתה:
@20 **נפש חיה.** שיש בה חיות: **שרץ.** כל דבר חי שאינו גבוה מן הארץ קרוי שרץ, בעוף כגון זבובים, בשקצים כגון נמלים וחפושין ותולעים, ובבריות כגון חולד ועכבר וחומט וכיוצא בהם, וכל הדגים:
@21 **התנינם.** דגים גדולים שבים. ובדברי אגדה הוא לויתן ובן זוגו שבראם זכר ונקבה והרג את הנקבה ומלחה לצדיקים לעתיד לבא, שאם יפרו וירבו לא יתקים העולם בפניהם: **נפש החיה.** שיש בה חיות:
@22 **ויברך אתם.** לפי שמחסרים אותן וצדין מהם ואוכלין אותם הצרכו לברכה. ואף החיות הוצרכו לברכה, אלא מפני הנחש שעתיד לקללה, לכך לא ברכן, שלא יהא הוא בכלל: **פרו.** לשון פרי, כלומר עשו פירות: **ורבו.** אם לא אמר אלא פרו היה אחד מוליד אחד ולא יותר, ובא ורבו שאחד מוליד הרבה:
@24 **תוצא הארץ.** הוא שפרשתי (פסוק יד) שהכל נברא מיום ראשון ולא הצרכו אלא להוציאם: **נפש חיה.** שיש בה חיות: **ורמש.** הם שרצים שהם נמוכים ורומשים על הארץ, נראים כאלו נגררים, שאין הלוכן נכר. כל לשון רמש ושרץ בלשוננו קונמובר''יש בלע''ז [רוחשים]:
@25 **ויעש.** תקנם בצביונם ובקומתן:
@26 **נעשה אדם.** ענותנותו של הקדוש ברוך הוא למדנו מכאן, לפי שהאדם בדמות המלאכים ויתקנאו בו לפיכך נמלך בהם, וכשהוא דן את המלכים הוא נמלך בפמליא שלו, שכן מצינו באחאב שאמר לו מיכה (מלכים א' כב יט) ראיתי את ה' ישב על כסאו וכל צבא השמים עמד עליו מימינו ומשמאלו, וכי יש ימין ושמאל לפניו, אלא אלו מימינים לזכות ואלו משמאילין לחובה. וכן (דניאל ד יד) בגזרת עירין פתגמא ומאמר קדישין שאלתא, אף כאן בפמליא שלו נמלך ונטל רשות, אמר להם יש בעליונים כדמותי, אם אין בתחתונים כדמותי, הרי יש קנאה במעשה בראשית: **נעשה אדם.** אף על פי שלא סייעוהו ביצירתו ויש מקום למינים לרדות, לא נמנע הכתוב מללמד דרך ארץ ומדת ענוה שיהא הגדול נמלך ונוטל רשות מן הקטן. ואם כתב אעשה אדם לא למדנו שיהא מדבר עם בית דינו אלא עם עצמו, ותשובת המינים כתב בצדו ויברא אלהים את האדם, ולא כתב ויבראו: **בצלמנו.** בדפוס שלנו: **כדמותנו.** להבין ולהשכיל: **וירדו בדגת הים.** יש בלשון הזה לשון רדוי ולשון ירידה, זכה רודה בחיות ובבהמות, לא זכה נעשה ירוד לפניהם והחיה מושלת בו:
@27 **ויברא אלהים את האדם בצלמו.** בדפוס העשוי לו, שהכל נברא במאמר והוא נברא בידים, שנאמר (תהלים קלט ה) ותשת עלי כפכה, נעשה בחותם כמטבע העשויה על ידי רושם שקורין קוי''ן בלע''ז [מטבע] וכן הוא אומר (איוב לח יד) תתהפך כחמר חותם: **בצלם אלהים ברא אתו.** פרש לך שאותו צלם המתקן לו צלם דיוקן יוצרו הוא: **זכר ונקבה ברא אתם.** ולהלן הוא אומר (בראשית ב כא) ויקח אחת מצלעתיו וגו' , מדרש אגדה שבראו שני פרצופין בבריאה ראשונה ואחר כך חלקו. ופשוטו של מקרא, כאן הודיעך שנבראו שניהם בששי ולא פרש לך כיצד בריתן ופרש לך במקום אחר:
@28 **וכבשה.** חסר וי''ו, ללמדך שהזכר כובש את הנקבה שלא תהא יצאנית, ועוד ללמדך שהאיש שדרכו לכבוש מצוה על פריה ורביה ולא האשה:
@29 **לכם יהיה לאכלה. ולכל חית הארץ.** השוה להם הכתוב בהמות וחיות למאכל, ולא הרשה לאדם ולאשתו להמית בריה ולאכל בשר, אך כל ירק עשב יאכלו יחד כלם, וכשבאו בני נח התיר להם בשר, שנאמר (להלן ט ג) כל רמש אשר הוא חי וגו' כירק עשב שהתרתי לאדם הראשון, נתתי לכם את כל:
@31 **יום הששי.** הוסיף ה' בששי בגמר מעשה בראשית, לומר שהתנה עמהם על מנת שיקבלו עליהם ישראל חמשה חומשי תורה. דבר אחר יום הששי כלם תלוים ועומדים עד יום הששי, הוא ששי בסיון המוכן למתן תורה:
@33 **ויכל אלהים ביום השביעי.** רבי שמעון אומר בשר ודם שאינו יודע עתיו ורגעיו צריך להוסיף מחול על הקדש, הקדוש ברוך הוא שיודע עתיו ורגעיו נכנס בו כחוט השערה ונראה כאלו כלה בו ביום. דבר אחר מה היה העולם חסר, מנוחה, באת שבת באת מנוחה, כלתה ונגמרה המלאכה:
@34 **ויברך ויקדש.** ברכו במן שכל ימות השבת היה יורד להם עמר לגלגלת ובששי לחם משנה, וקדשו במן שלא ירד בו מן כלל והמקרא כתוב על שם העתיד: **אשר ברא אלהים לעשות.** המלאכה שהיתה ראויה לעשות בשבת כפל ועשאה בששי, כמו שמפורש בבראשית רבה (יא י) :
@35 **אלה.** האמורים למעלה: **תולדות השמים והארץ בהבראם ביום עשות ה'.** למדך שכלם נבראו ביום ראשון. דבר אחר בהבראם, בה' בראם שנאמר (ישעיה כו ד) ביה ה' צור עולמים בשתי אותיות הללו של שם יצר שני עולמים, ולמדך כאן שהעולם הזה נברא בה''א (רמז כמו שה''א פתוחה למטה, כך העולם פתוח לשבים בתשובה. ועולם הבא נברא ביו''ד לומר שצדיקים שבאותו זמן מועטים כמו י' שהיא קטנה באותיות) . רמז שירדו הרשעים למטה לראות שחת כה''א זאת שסתומה מכל צדדים ופתוחה למטה לרדת דרך שם:
@36 **טרם יהיה בארץ.** כל טרם שבמקרא לשון עד לא הוא, ואינו לשון קודם, ואינו נפעל לומר הטרים כאשר יאמר הקדים, וזה מוכיח, ועוד אחר (שמות ט ל) כי טרם תיראון, עדין לא תיראון. ואף זה תפרש עדיין לא היה בארץ כשנגמרה בריאת העולם בששי קודם שנברא אדם: **וכל עשב השדה טרם יצמח.** עדיין לא צמח, ובשלישי שכתוב ותוצא הארץ, על פתח הקרקע עמדו עד יום ששי: **כי לא המטיר.** ומה טעם לא המטיר, לפי שאדם אין לעבוד את האדמה ואין מכיר בטובתם של גשמים, וכשבא אדם וידע שהם צרך לעולם התפלל עליהם וירדו, וצמחו האילנות והדשאים: **ה' אלהים.** ה' הוא שמו, אלהים שהוא שופט ושליט על כל, וכן פרוש זה בכל מקום לפי פשוטו, ה' שהוא אלהים:
@37 **ואד יעלה.** לענין בריאתו של אדם, העלה את התהום והשקה העננים לשרות העפר ונברא אדם, כגבל זה שנותן מים ואחר כך לש את העיסה, אף כאן והשקה ואחר כך וייצר:
@38 **וייצר.** שתי יצירות, יצירה לעולם הזה ויצירה לתחית המתים, אבל בבהמה שאינה עומדת לדין לא נכתב ביצירה שני יודי''ן: **עפר מן האדמה.** צבר עפרו מכל האדמה מארבע רוחות, שכל מקום שימות שם תהא קולטתו לקבורה. דבר אחר נטל עפרו ממקום שנאמר בו (שמות כ כא) מזבח אדמה תעשה לי, אמר הלואי תהיה לו כפרה ויוכל לעמוד: **ויפח באפיו.** עשאו מן התחתונים ומן העליונים, גוף מן התחתונים ונשמה מן העליונים, לפי שביום ראשון נבראו שמים וארץ. בשני ברא רקיע לעליונים. בשלישי תראה היבשה לתחתונים. ברביעי ברא מאורות לעליונים. בחמישי ישרצו המים לתחתונים, הוזקק הששי לבראות בו בעליונים ובתחתונים, ואם לאו יש קנאה במעשה בראשית, שיהיו אלו רבים על אלו בבריאת יום אחד: **לנפש חיה.** אף בהמה וחיה נקראו נפש חיה, אך זו של אדם חיה שבכלן, שנתוסף בו דעה ודבור:
@39 **מקדם.** במזרחו של עדן נטע את הגן. ואם תאמר הרי כבר כתב (לעיל א כז) ויברא אלהים את האדם וגו' . ראיתי בברייתא של ר' אלעזר בנו של ר' יוסי הגלילי משלושים ושתים מדות שהתורה נדרשת, וזו אחת מהן כלל שלאחריו מעשה הוא פרטו של ראשון. ויברא את האדם זהו כלל, סתם בריאתו מהיכן וסתם מעשיו, חזר ופירש וייצר ה' אלהים וגו' , ויצמח לו גן עדן, ויניחהו בגן עדן, ויפל עליו תרדמה, השומע סבור שהוא מעשה אחר, ואינו אלא פרטו של ראשון. וכן אצל הבהמה חזר וכתב ויצר ה' אלהים מן האדמה כל חית השדה (ב יט) , כדי לפרש ויבא אל האדם לקרות שם, וללמד על העופות שנבראו מן הרקק:
@40 **ויצמח.** לענין הגן הכתוב מדבר: **בתוך הגן.** באמצע:
@42 **פישון.** הוא נילוס נהר מצרים ועל שם שמימיו מתברכין ועולין ומשקין את הארץ נקרא פישון, כמו ופשו פרשיו. דבר אחר פישון שהוא מגדל פשתן שנאמר על מצרים (ישעיה יט ט) ובשו עובדי פשתים:
@44 **גיחון.** שהיה הולך והומה והמייתו גדולה מאד, כמו (שמות כא כח) כי יגח, שמנגח והולך והומה:
@45 **חדקל.** שמימיו חדין וקלין: **פרת.** שמימיו פרין ורבין ומברין את האדם. כוש ואשור. עדיין לא היו, וכתב המקרא על שם העתיד: **קדמת אשור.** למזרחה של אשור: **הוא פרת.** החשוב על כלם, הנזכר על שם ארץ ישראל:
@46 **ויקח.** לקחו בדברים נאים ופתהו ליכנס:
@49 **לא טוב היות** וגו' **.** שלא יאמרו שתי רשויות הן הקדוש ברוך הוא יחיד בעליונים ואין לו זוג, וזה יחיד בתחתונים ואין לו זוג: **עזר כנגדו.** זכה עזר, לא זכה כנגדו להלחם:
@50 **ויצר** וגו' **מן האדמה.** היא יצירה היא עשייה האמורה למעלה (לעיל א כה) ויעש אלהים את חית הארץ וגו' , אלא בא ופירש שהעופות מן הרקק נבראו, לפי שאמר למעלה מן המים נבראו וכאן אמר מן הארץ נבראו. ועוד למדך כאן שבשעת יצירתן מיד בו ביום הביאם אל האדם לקרות להם שם. ובדברי אגדה יצירה זו לשון רידוי וכבוש, כמו (דברים כ יט) כי תצור אל עיר, שכבשן תחת ידו של אדם: **וכל אשר יקרא לו האדם נפש חיה** וגו' **.** סרסהו ופרשהו כל נפש חיה אשר יקרא לו האדם שם הוא שמו לעולם:
@51 , כא **ולאדם לא מצא עזר ויפל ה' אלהים תרדמה.** כשהביאן הביאן לפניו כל מין ומין זכר ונקבה, אמר לכלם יש בן זוג ולי אין בן זוג, מיד ויפל: **מצלעותיו.** מסטריו, כמו (שמות כו כ) ולצלע המשכן, זהו שאמרו שני פרצופים נבראו: **ויסגר.** מקום החתך: **וישן ויקח.** שלא יראה חתיכת הבשר שממנו נבראת ותתבזה עליו:
@53 **ויבן.** כבנין, רחבה מלמטה וקצרה מלמעלה לקבל הולד, כאוצר של חטים שהוא רחב מלמטה וקצר מלמעלה, שלא יכביד משאו על קירותיו: **ויבן** וגו' **את הצלע** וגו' **לאשה.** להיות אשה, כמו (שופטים ח כז) ויעש אותו גדעון לאפוד, להיות אפוד:
@54 **זאת הפעם.** מלמד שבא אדם על כל בהמה וחיה ולא נתקררה דעתו בהם עד שבא על חוה: **לזאת יקרא אשה כי מאיש** וגו' **.** לשון נופל על לשון, מכאן שנברא העולם בלשון הקדש:
@55 **על כן יעזב איש.** רוח הקדש אומרת כן, לאסור על בני נח את העריות: **לבשר אחד.** הולד נוצר על ידי שניהם, ושם נעשה בשרם אחד:
@56 **ולא יתבוששו.** שלא היו יודעים דרך צניעות להבחין בין טוב לרע, ואף על פי שנתנה בו דעה לקרות שמות, לא נתן בו יצר הרע עד אכלו מן העץ ונכנס בו יצר הרע וידע מה בין טוב לרע:
@57 **והנחש היה ערום.** מה ענין זה לכאן היה לו לסמוך (פסוק כא) ויעש לאדם ולאשתו כתנות עור וילבישם. אלא למדך מאיזו עלה קפץ הנחש עליהם, ראה אותם ערומים ועוסקים בתשמיש לעין כל ונתאוה לה: **ערום מכל.** לפי ערמתו וגדלתו היתה מפלתו, ערום מכל, ארור מכל: **אף כי אמר** וגו' **.** שמא אמר לכם לא תאכלו מכל וגו' . ואף על פי שראה אותם אוכלים משאר פרות, הרבה עליה דברים כדי שתשיבנו ויבא לדבר באותו העץ:
@59 **ולא תגעו בו.** הוסיפה על הצווי, לפיכך באה לידי גרעון, הוא שנאמר (משלי ל ו) אל תוסף על דבריו:
@60 **לא מות תמתון.** דחפה עד שנגעה בו, אמר לה כשם שאין מיתה בנגיעה כך אין מיתה באכילה:
@61 **כי יודע.** כל אמן שונא את בני אמנותו, מן העץ אכל וברא את העולם: **והייתם כאלהים.** יוצרי עולמות:
@62 **ותרא האשה.** ראתה דבריו של נחש והנאו לה והאמינתו: **כי טוב העץ.** להיות כאלהים: **וכי תאוה הוא לעינים.** כמו שאמר לה ונפקחו עיניכם: **ונחמד להשכיל.** כמו שאמר לה יודעי טוב ורע: **ותתן גם לאישה עמה.** שלא תמות היא ויחיה הוא, וישא אשה אחרת: **גם.** לרבות כל בהמה וחיה:
@63 **ותפקחנה עיני שניהם.** לענין החכמה דבר הכתוב ולא לענין ראיה ממש, וסוף המקרא מוכיח: **וידעו כי עירמם הם.** אף הסומא יודע כשהוא ערום, אלא מהו וידעו כי עירומים הם, מצוה אחת היתה בידם ונתערטלו המנה: **עלה תאנה.** הוא העץ שאכלו ממנו, בדבר שנתקלקלו בו נתקנו, אבל שאר העצים מנעום מלטול עליהם. ומפני מה לא נתפרסם העץ, שאין הקדוש ברוך הוא חפץ להונות בריה, שלא יכלימוהו ויאמרו זהו שלקה העולם על ידו. מדרש רבי תנחומא (וירא יד) :
@64 **וישמעו.** יש מדרשי אגדה רבים וכבר סדרום רבותינו על מכונם בבראשית רבה (יט ו) ובשאר מדרשות ואני לא באתי אלא לפשוטו של מקרא ולאגדה המישבת דברי המקרא דבר דבור על אפניו. ומשמעו, שמעו את קול הקדוש ברוך הוא שהיה מתהלך בגן: **לרוח היום.** לאותו רוח שהשמש באה משם וזו היא מערבית, שלפנות ערב חמה במערב, והם סרחו בעשירית:
@65 **איכה.** יודע היה היכן הוא, אלא לכנס עמו בדברים, שלא יהא נבהל להשיב אם יענישהו פתאום. וכן בקין (בראשית ד ט) אמר לו אי הבל אחיך, וכן בבלעם (במדבר כב ט) מי האנשים האלה עמך, לכנס עמהם בדברים, וכן בחזקיה בשלוחי (אויל) מרודך בלאדן (ישעיה לט א) :
@67 **מי הגיד לך.** מאין לך לדעת מה בשת יש בעומד ערום: **המן העץ.** בתמיהה:
@68 **אשר נתת עמדי.** כאן כפר בטובה:
@69 **השיאני.** הטעני כמו (דה''י ב' לב טו) אל ישיא אתכם חזקיהו:
@70 **כי עשית זאת.** מכאן שאין מהפכים בזכותו של מסית, שאלו שאלו למה עשית זאת, היה לו להשיב דברי הרב ודברי התלמיד דברי מי שומעין: **מכל הבהמה ומכל חית השדה.** אם מבהמה נתקלל מחיה לא כל שכן, העמידו רבותינו מדרש זה במסכת בכורות (דף ח א) ללמד שימי עבורו של נחש שבע שנים: **על גחונך תלך.** רגלים היו לו ונקצצו טו **ואיבה אשית.** אתה לא נתכונת אלא שימות אדם כשיאכל הוא תחלה ותשא את חוה, ולא באת לדבר אל חוה תחלה אלא לפי שהנשים קלות להתפתות ויודעות לפתות את בעליהן, לפיכך ואיבה אשית: **ישופך.** יכתתך, כמו (דברים ט כא) ואכת אתו, ותרגומו ושפית יתיה: **ואתה תשופנו עקב.** לא יהא לך קומה ותשכנו בעקבו, ואף משם תמיתנו. ולשון תשופנו כמו (ישעיה מ כד) נשף בהם, כשהנחש בא לנשוך הוא נושף כמין שריקה, ולפי שהלשון נופל על הלשון כתב לשון נשיפה בשניהם:
@72 **עצבונך.** זה צער גדול בנים: **והרנך.** זה צער העבור: **בעצב תלדי בנים.** זה צער הלידה: **ואל אישך תשוקתך.** לתשמיש ואף על פי כן אין לך מצח לתבעו בפה אלא הוא ימשול בך, הכל ממנו ולא ממך: **תשוקתך.** תאותך, כמו (ישעיה כט ח) ונפשו שוקקה:
@73 **ארורה האדמה בעבורך.** מעלה לך דברים ארורים כגון זבובים ופרעושים ונמלים, משל ליוצא לתרבות רעה והבריות מקללות שדים שינק מהם:
@74 **וקוץ ודרדר תצמיח לך.** הארץ כשתזרענה מיני זרעים תצמיח קוץ ודרדר קונדס ועכביות, והן נאכלים על ידי תקון: **ואכלת את עשב השדה.** ומה קללה היא זו, והלא בברכה נאמר לו (לעיל א כט) הנה נתתי לכם את כל עשב זורע זרע וגו' . אלא מה אמור כאן בראש הענין (פסוק יז) ארורה האדמה בעבורך בעצבון תאכלנה, ואחר העצבון וקוץ ודרדר תצמיח לך, כשתזרענה קטניות או ירקות גנה היא תצמיח לך קוצים ודרדרים ושאר עשבי שדה, ועל כרחך תאכלם:
@75 **בזעת אפיך.** לאחר שתטרח בו הרבה:
@76 **ויקרא האדם.** חזר הכתוב לענינו הראשון ויקרא האדם שמות, ולא הפסיק אלא ללמדך שעל ידי קריאת שמות נזדוגה לו חוה, כמו שכתוב (לעיל ב כ) ולאדם לא מצא עזר כנגדו, לפיכך ויפל תרדמה, ועל ידי שכתב (שם פסוק כה) ויהיו שניהם ערומים, סמך לו פרשת הנחש, להודיעך שמתוך שראה ערותה וראה אותם עסוקים בתשמיש נתאוה לה ובא עליהם במחשבה ובמרמה: **חוה.** נופל על לשון חיה, שמחיה את ולדותיה, כאשר תאמר מה הוה לאדם, (קהלת ב כב) בלשון היה:
@77 **כתנות עור.** יש דברי אגדה אומרים חלקים כצפורן היו מדובקים על עורן. ויש אומרים דבר הבא מן העור, כגון צמר הארנבים שהוא רך וחם ועשה להם כתנות ממנו:
@78 **היה כאחד ממנו.** הרי הוא יחיד בתחתונים כמו שאני יחיד בעליונים, ומה היא יחידותו, לדעת טוב ורע ומה שאין כן בבהמה ובחיה: **ועתה פן ישלח ידו.** ומשיחיה לעולם הרי הוא קרוב להטעות הבריות אחריו ולומר אף הוא אלוה. ויש מדרשי אגדה, אבל אין מישבין על פשוטו:
@80 **מקדם לגן עדן.** במזרחו של גן עדן, חוץ לגן: **את הכרובים.** מלאכי חבלה: **החרב המתהפכת.** ולה להט לאים עליו מלכנס עוד לגן. תרגום של להט שנן, והוא כמו שלף שננא, [להב]. ומדרש אגדה יש, ואני איני בא אלא לפשוטו:
@81 **והאדם ידע.** כבר קודם הענין של מעלה, קודם שחטא ונטרד מגן עדן, וכן ההריון והלידה, שאם כתב וידע אדם נשמע שלאחר שנטרד היו לו בנים: **קין.** על שם קניתי איש: **את ה'.** כמו עם ה', כשברא אותי ואת אישי הוא לבדו בראנו, אבל בזה שותפים אנו עמו: **את קין' את אחיו את הבל.** שלש אתים ריבוים הם, מלמד שתאומה נלדה עם קין, ועם הבל נלדו שתים, לכך נאמר ותוסף:
@82 **רעה צאן.** לפי שנתקללה האדמה, פרש לו מעבודתה:
@83 **מפרי האדמה.** מן הגרוע, ויש אגדה שאומרת זרע פשתן היה:
@84 **וישע.** ויפן, וכן (פסוק ה) לא שעה אל מנחתו, לא פנה, וכן (שמות ה ט) ואל ישעו, אל יפנו. וכן (איוב יד ו) שעה מעליו, פנה מעליו: **וישע.** ירדה אש וליחכה מנחתו:
@87 **הלא אם תיטיב.** כתרגומו פרושו: **לפתח חטאת רבץ.** לפתח קברך חטאך שמור: **ואליך תשוקתו.** של חטאת, הוא יצר הרע, תמיד שוקק ומתאוה להכשילך: **ואתה תמשל בו.** אם תרצה תתגבר עליו:
@88 **ויאמר קין אל הבל.** נכנס עמו בדברי ריב ומצה להתגולל עליו להרגו, ויש בזה מדרשי אגדה אך זה ישובו של מקרא:
@89 **אי הבל אחיך.** להכנס עמו בדברי נחת, אולי ישוב ויאמר אני הרגתיו וחטאתי לך: **לא ידעתי.** נעשה כגונב דעת העליונה: **השומר אחי.** לשון תמה הוא, וכן כל ה, א הנקודה בחטף פתח:
@90 **דמי אחיך.** דמו ודם זרעיותיו. דבר אחר שעשה בו פצעים הרבה שלא היה יודע מהיכן נפשו יוצאה:
@91 **ארור אתה מן האדמה.** יותר ממה שנתקללה היא כבר בעונה, וגם בזו הוסיפה לחטוא: **אשר פצתה את פיה לקחת את דמי אחיך** וגו' **.** והנני מוסיף לה קללה לא תסף תת כחה:
@92 **נע ונד.** אין לך רשות לדור במקום אחד:
@93 **גדול עוני מנשא.** בתמיהה, אתה טוען עליונים ותחתונים, ועוני אי אפשר לטעון:
@95 **לכן כל הרג קין.** זה אחד מן המקראות שקצרו דבריהם ורמזו ולא פרשו. לכן כל הרג קין, לשון גערה, כה יעשה לו, כך וכך ענשו, ולא פרש ענשו: **שבעתים יקם.** איני רוצה להנקם מקין עכשיו, לסוף שבעה דורות אני נוקם נקמתי ממנו שיעמוד למך מבני בניו ויהרגהו. וסוף המקרא שאמר שבעתים יוקם, והיא נקמת הבל מקין, הא למדנו שתחלת מקרא לשון גערה היא, שלא תהא בריה מזיקתו. וכיוצא בו (שמואל ב' ה ח) ויאמר דוד כל מכה יבוסי ויגע בצנור ולא פרש מה יעשה לו, אבל דבר הכתוב ברמז כל מכה יבוסי ויגע בצנור, ויקרב אל השער ויכבשנו, ואת העורים וגו' , וגם אותם יכה על אשר אמרו העור והפסח לא יבא דוד אל תוך הבית, המכה את אלו אני אעשנו ראש ושר, כאן קצר דבריו ובדברי הימים (א יא ו) פרש יהיה לראש ולשר: **וישם ה' לקין אות.** חקק לו אות משמו במצחו (כל מוצאי יהרגני הבהמות והחיות, אבל בני אדם עדיין לא היו שיירא מהם רק אביו ואמו, ומהם לא היה ירא שיהרגוהו. אלא אמר עד עכשיו היה פחדתי על כל החיות כמו שנאמר ומוראכם וגו', ועכשיו בשביל עון זה לא ייראו ממני החיות ויהרגוני, מיד וישם ה' לקין אות, החזיר מוראו על הכל) :
@96 **ויצא קין.** יצא בהכנעה כגונב דעת העליונה: **בארץ נוד.** בארץ שכל הגולים נדים שם: **קדמת עדן.** שם גלה אביו כשגורש מגן עדן, שנאמר (לעיל ג כד) וישכן מקדם לגן עדן, את שמירת דרך מבוא הגן, שיש ללמוד שהיה אדם שם. ומצינו רוח מזרחית קולטת בכל מקום את הרוצחים, שנאמר (דברים ד מא) אז יבדיל משה וגו' מזרחה שמש. דבר אחר בארץ נוד, כל מקום [שהיה הולך] היתה הארץ מזדעזעה תחתיו והבריות אומרות סורו מעליו, זהו שהרג את אחיו:
@97 **ויהי.** קין בנה עיר ויקרא שם העיר לזכר בנו חנוך:
@98 **ועירד ילד.** יש מקום שהוא אומר בזכר הוליד ויש מקום שהוא אומר ילד, שהלידה משמשת שתי לשונות, לידת האשה ניישטר''א בלע''ז [ללדת], וזריעת תולדות האיש איניינדרי''ר בלע''ז [להוליד] כשהוא אומר הוליד בלשון הפעיל מדבר בלידת האשה, פלוני הוליד את אשתו בן או בת, וכשהוא אומר ילד מדבר בזריעת האיש:
@99 **ויקח לו למך.** לא היה לו לפרש כל זה, אלא ללמדנו מסוף הענין שקים הקדוש ברוך הוא הבטחתו שאמר שבעתים יקם קין, עמד למך לאחר שהוליד בנים ועשה דור שביעי והרג את קין, זהו שאמר (פסוק כג) כי איש הרגתי לפצעי וגו' : **שתי נשים.** כך היה דרכן של דור המבול, אחת לפריה ורביה ואחת לתשמיש, זו שהיא לתשמיש משקה כוס של עקרין כדי שתעקר ומקשטת ככלה ומאכילה מעדנים, וחברתה נזופה ואבלה כאלמנה, וזהו שפרש איוב (איוב כד כא) רעה עקרה לא תלד ואלמנה לא ייטיב, כמו שמפורש באגדת חלק: **עדה.** היא של פריה ורביה, ועל שם שמגונה עליו ומוסרת מאצלו. עדה תרגום של סורה: **צלה.** היא של תשמיש על שם שיושבת תמיד בצלו, דברי אגדה הם בבראשית רבה (כג ב) :
@100 **אבי ישב אהל ומקנה.** הוא היה הראשון לרועי בהמות במדברות, ויושב אהלים חדש כאן וחדש כאן בשביל מרעה צאנו, וכשכלה המרעה במקום הזה הולך ותוקע אהלו במקום אחר. ומדרש אגדה בונה בתים לעבודה זרה, כמה דאת אמר (יחזקאל ח ג) סמל הקנאה המקנה, וכן (פסוק כא) אחיו תופש כנור ועוגב לזמר לעבודה זרה:
@102 **תובל קין.** תבל אמנתו של קין. תובל לשון תבלין, תבל והתקין אמנתו של קין לעשות כלי זין לרוצחים: **לטש כל חרש נחשת וברזל.** מחדד אמנות נחשת וברזל, כמו (איוב טז ט) ילטוש עיניו לי. חרש אינו לשון פעל אלא לשון פועל שהרי נקוד קמץ קטן. וטעמו למטה, כלומר מחדד ומצחצח כל כלי אמנות נחשת וברזל: **נעמה.** היא אשתו של נח:
@103 **שמען קולי.** שהיו פורשות ממנו מתשמיש לפי שהרג את קין ואת תובל קין בנו, שהיה למך סומא ותובל קין מושכו, וראה את קין ונדמה לו כחיה ואמר לאביו למשוך בקשת, והרגו. וכיון שידע שהוא קין זקנו, הכה כף אל כף וספק את בנו ביניהם והרגו, והיו נשיו פורשות ממנו והוא מפיסן: **שמען קולי.** להשמע לי (לתשמיש) , וכי איש אשר הרגתיו לפצעי הוא נהרג, וכי אני פצעתיו מזיד שיהא הפצע קרוי על שמי, וילד אשר הרגתי לחבורתי נהרג, כלומר על ידי חבורתי, בתמיהה, והלא שוגג אני ולא מזיד, לא זהו פצעי ולא זהו חבורתי: פצע, מכת חרב או חץ נברידור''א בלע''ז [פצע]:
@104 **כי שבעתים יוקם קין.** קין שהרג מזיד נתלה לו עד שבעה דורות, אני שהרגתי שוגג לא כל שכן שיתלה לי שביעיות הרבה: **שבעים ושבעה.** לשון רבוי שביעיות אחז לו. כך דרש רבי תנחומא (אות יא) . ומדרש בראשית רבה (כג ד) לא הרג למך כלום ונשיו פורשות ממנו משקימו פריה ורביה, לפי שנגזרה גזרה לכלות זרעו של קין לאחר שבעה דורות, אמרו מה אנו יולדות לבהלה, למחר המבול בא ושוטף את הכל. והוא אומר להן וכי איש הרגתי לפצעי, וכי אני הרגתי את הבל שהיה איש בקומה וילד בשנים, שיהא זרעי כלה באותו עון, ומה קין שהרג נתלה לו שבעה דורות, אני שלא הרגתי לא כל שכן שיתלו לי שביעיות הרבה. וזהו קל וחומר של שטות, אם כן אין הקדוש ברוך הוא גובה את חובו ומקים את דברו:
@105 **וידע אדם** וגו' **.** בא לו למך אצל אדם הראשון וקבל על נשיו, אמר להן וכי עליכם לדקדק על גזרתו של מקום, אתם עשו מצותכם והוא יעשה את שלו. אמרו לו קשוט עצמך תחלה, והלא פרשת מאשתך זה מאה ושלשים שנה משנקנסה מיתה על ידך, מיד וידע אדם עוד וגו' . מהו עוד, ללמדך שנתוספה לו תאוה על תאותו:
@106 **אז הוחל.** (לשון חלין) לקרא את שמות האדם ואת שמות העצבים בשמו של הקדוש ברוך הוא לעשותן עבודה זרה ולקרותן אלהות:
@107 **זה ספר תולדת אדם.** זו היא ספירת תולדות אדם, ומדרשי אגדה יש רבים: **ביום ברא** וגו' **.** מגיד שביום שנברא הוליד:
@109 **שלשים ומאת שנה.** עד כאן פרש מן האשה:
@130 **ויתהלך חנוך.** צדיק היה וקל בדעתו לשוב להרשיע, לפיכך מיהר הקדוש ברוך הוא וסלקו והמיתו קודם זמנו [וזהו ששנה הכתוב במיתתו לכתוב ואיננו בעולם למלאות שנותיו: **כי לקח אתו.** לפני זמנו] כמו (יחזקאל כד טז) הנני לקח ממך את מחמד עיניך:
@134 **ויולד בן.** שממנו נבנה העולם:
@135 **זה ינחמנו.** ינח ממנו את עצבון ידינו, עד שלא בא נח לא היה להם כלי מחרשה והוא הכין להם, והיתה הארץ מוציאה קוצים ודרדרים כשזורעים חטים, מקללתו של אדם הראשון, ובימי נח נחה, וזהו ינחמנו, ינח ממנו. ואם לא תפרשהו כך, אין טעם הלשון נופל על השם, ואתה צריך לקרות שמו מנחם:
@138 **בן חמש מאות שנה.** אמר רבי יודן מה טעם כל הדורות הולידו למאה שנה וזה לחמש מאות, אמר הקדוש ברוך הוא אם רשעים הם יאבדו במים ורע לצדיק זה, ואם צדיקים הם אטריח עליו לעשות תבות הרבה, כבש את מעינו ולא הוליד עד שהיה בן חמש מאות שנה, כדי שלא יהא יפת הגדול שבבניו ראוי לעונשין לפני המבול דכתיב (ישעיה סה כ) כי הנער בן מאה שנה ימות, וראוי לענש לעתיד, וכן לפני מתן תורה: **את שם את חם ואת יפת.** והלא יפת הוא הגדול, אלא בתחלה אתה דורש את שם שהוא צדיק, ונלד כשהוא מהול, ושאברהם יצא ממנו וכו' :
@140 **בני האלהים.** בני השרים והשופטים. (דבר אחר בני האלהים הם השרים ההולכים בשליחותו של מקום, אף הם היו מתערבים בהם) . כל אלהים שבמקרא לשון מרות, וזה יוכיח (שמות ד טז) ואתה תהיה לו לאלהים, (שם ז א) ראה נתתיך אלהים: **כי טבת הנה.** אמר רבי יודן טבת כתיב, כשהיו מטיבין אותה מקשטת לכנס לחפה, היה גדול נכנס ובועלה תחלה: **מכל אשר בחרו.** אף בעולת בעל, אף הזכר והבהמה:
@141 **לא ידון רוחי באדם.** לא יתרעם ויריב רוחי עלי בשביל האדם: **לעלם.** לאורך ימים, הנה רוחי נדון בקרבי אם להשחית ואם לרחם, לא יהיה מדון זה ברוחי לעולם, כלומר לאורך ימים: **בשגם הוא בשר.** כמו בשגם, כלומר בשביל שגם זאת בו שהוא בשר, ואף על פי כן אינו נכנע לפני, ומה אם יהיה אש או דבר קשה, כיוצא בו (שופטים ה ז) עד שקמתי דבורה, כמו שקמתי. וכן (שם ו יז) שאתה מדבר עמי, כמו שאתה, אף בשגם כמו בשגם: **והיו ימיו** וגו' **.** עד מאה ועשרים שנה אאריך להם אפי ואם לא ישובו אביא עליהם מבול. ואם תאמר משנלד יפת עד המבול אינו אלא מאה שנה, אין מקדם ומאחר בתורה, כבר היתה הגזרה גזורה עשרים שנה קודם שהוליד נח תולדות, וכן מצינו בסדר עולם (פרק כח) . יש מדרשי אגדה רבים בלא ידון, אבל זה הוא צחצוח פשוטו:
@142 **הנפלים.** על שם שנפלו והפילו את העולם, ובלשון עברית לשון ענקים הוא: **בימים ההם.** בימי דור אנוש ובני קין: **וגם אחרי כן.** אף על פי שראו באבדן של דור אנוש שעלה אוקיינוס והציף שליש העולם, לא נכנע דור המבול ללמוד מהם: **אשר יבאו.** היו יולדות ענקים כמותם: **הגבורים.** למרוד במקום: **אנשי השם.** אותן שנקבו בשמות עירד, מחויאל, מתושאל, שנקראו על שם אבדן שנמוחו והותשו. דבר אחר אנשי שממון, ששממו את העולם:
@144 **וינחם ה' כי עשה.** נחמה היתה לפניו שבראו בתחתונים, שאלו היה מן העליונים היה ממרידן: **ויתעצב.** האדם: **אל לבו.** של מקום, עלה במחשבתו של מקום להעציבו, זהו תרגום אנקלוס. דבר אחר וינחם, נהפכה מחשבתו של מקום ממדת רחמים למדת הדין, עלה במחשבה לפניו מה לעשות באדם שעשה בארץ, וכן כל לשון נחום שבמקרא לשון נמלך מה לעשות (במדבר כג ט) ובן אדם ויתנחם, (דברים לב לו) ועל עבדיו יתנחם, (שמות לב יד) וינחם ה' על הרעה, (שמואל א' טו יא) נחמתי כי המלכתי, כלם לשון מחשבה אחרת הם: **ויתעצב אל לבו.** נתאבל על אבדן מעשה ידיו, כמו (ש''ב יט ג) נעצב המלך על בנו. וזו כתבתי לתשובת המינים, גוי אחד שאל את רבי יהושע בן קרחה, אמר לו אין אתם מודים שהקדוש ברוך הוא רואה את הנלד, אמר לו הן. אמר לו והא כתיב ויתעצב אל לבו, אמר לו נלד לך בן זכר מימיך, אמר לו הן. אמר לו ומה עשית, אמר לו שמחתי ושמחתי את הכל. אמר לו ולא היית יודע שסופו למות, אמר לו בשעת חדותא חדותא, בשעת אבלא אבלא. אמר לו כך מעשה הקדוש ברוך הוא, אף על פי שגלוי לפניו שסופן לחטוא ולאבדן לא נמנע מלבראן בשביל הצדיקים העתידים לעמוד מהם:
@145 **ויאמר ה' אמחה את האדם.** הוא עפר ואביא עליו מים ואמחה אותו, לכך נאמר לשון מחוי: **מאדם עד בהמה.** אף הם השחיתו דרכם. דבר אחר הכל נברא בשביל אדם, וכיון שהוא כלה מה צורך באלו: **כי נחמתי כי עשיתם.** חשבתי מה לעשות להם על אשר עש י ת י ם:
@147 **אלה תולדת נח נח איש צדיק.** הואיל והזכירו ספר בשבחו, שנאמר (משלי י ז) זכר צדיק לברכה. דבר אחר ללמדך, שעיקר תולדותיהם של צדיקים מעשים טובים: **בדרתיו.** יש מרבותינו דורשים אותו לשבח, כל שכן שאלו היה בדור צדיקים היה צדיק יותר, ויש שדורשים אותו לגנאי, לפי דורו היה צדיק, ואלו היה בדורו של אברהם לא היה נחשב לכלום: **את האלהים התהלך נח.** ובאברהם הוא אומר (יז א) התהלך לפני, (כד מ) אשר התהלכתי לפניו, נח היה צריך סעד לתמכו, אבל אברהם היה מתחזק ומהלך בצדקו מאליו: **התהלך.** לשון עבר, וזהו שמושו של למד בלשון כבד, משמשת להבא ולשעבר בלשון אחד, (שם יג יז) קום התהלך, להבא, התהלך נח, לשעבר, (ש''א יב יט) התפלל בעד עבדיך להבא, (מלכים א ח מב) ובא והתפלל אל הבית הזה, לשון עבר, אלא שהוי''ו שבראשו הופכו להבא:
@149 **ותשחת.** לשון ערוה ועבודה זרה, כמו (דברים ד טז) פן תשחתון, כי השחית כל בשר וגו' : **ותמלא הארץ חמס.** גזל:
@150 **כי השחית כל בשר.** אפילו בהמה חיה ועוף נזקקין לשאינן מינן:
@151 **קץ כל בשר.** כל מקום שאתה מוצא זנות ועבודה זרה, אנדרלמוסיא באה לעולם והורגת טובים ורעים: **כי מלאה הארץ חמס.** לא נחתם גזר דינם אלא על הגזל: **את הארץ.** כמו מן הארץ, ודומה לו (שמות ט כט) כצאתי את העיר, מן העיר, (מ''א טו כג) חלה את רגליו, מן רגליו. דבר אחר את הארץ עם הארץ, שאף שלשה טפחים של עומק המחרשה נמוחו ונטשטשו:
@152 **עשה לך תבת.** הרבה ריוח והצלה לפניו, ולמה הטריחו בבנין זה, כדי שיראוהו אנשי דור המבול עוסק בה מאה ועשרים שנה ושואלין אותו מה זאת לך, והוא אומר להם עתיד הקדוש ברוך הוא להביא מבול לעולם, אולי ישובו: **עצי גפר.** כך שמו. ולמה ממין זה על שם גפרית, שנגזר עליהם להמחות בו: **קנים.** מדורים מדורים לכל בהמה וחיה: **בכפר.** זפת בלשון ארמי. ומצינו בתלמוד כופרא. בתיבתו של משה, על ידי שהיו המים תשים, דיה בחומר מבפנים וזפת מבחוץ, ועוד כדי שלא יריח אותו צדיק ריח רע של זפת, אבל כאן מפני חזק המים זפתה מבית ומבחוץ:
@154 **צהר.** יש אומרים חלון, ויש אומרים אבן טובה המאירה להם: **ואל אמה תכלנה מלמעלה.** כסויה משפע ועולה עד שהוא קצר מלמעלה ועומד על אמה, כדי שיזובו המים למטה: **בצדה תשים.** שלא יפלו הגשמים בה: **תחתים שנים ושלשים.** שלש עליות זו על גב זו, עליונים לאדם, אמצעים למדור לבהמה תחתיים לזבל:
@155 **ואני הנני מביא.** הנני מוכן להסכים עם אותם שזרזוני ואמרו לפני כבר (תהלים ח ה) מה אנוש כי תזכרנו: **מבול.** שבלה את הכל, שבלבל את הכל, שהוביל את הכל מן הגבוה לנמוך, וזהו לשון אנקלוס שתרגם טופנא, שהציף את הכל והביאם לבבל שהיא עמוקה, לכך נקראת שנער שננערו שם כל מתי מבול:
@156 **והקמתי את בריתי.** ברית היה צריך על הפרות שלא ירקבו ויעפשו, ושלא יהרגוהו רשעים שבדור: **אתה ובניך ואשתך.** האנשים לבד והנשים לבד, מכאן שנאסרו בתשמיש המטה:
@157 **ומכל החי.** אפילו שדים: **שנים מכל.** מן הפחות שבהם לא פחתו משנים, אחד זכר ואחד נקבה:
@158 **מהעוף למינהו.** אותן שדבקו במיניהם ולא השחיתו דרכם, ומאליהם באו, וכל שהתיבה קולטתו הכניס בה:
@160 **ויעש נח.** זה בנין התבה:
@161 **כי אותך ראיתי צדיק.** ולא נאמר צדיק תמים. מכאן שאומרים מקצת שבחו של אדם בפניו וכלו שלא בפניו:
@162 **הטהורה.** העתידה להיות טהורה לישראל, למדנו שלמד נח תורה: **שבעה שבעה.** כדי שיקריב מהם קרבן בצאתו:
@163 **גם מעוף השמים** וגו' **.** בטהורים הכתוב מדבר. וילמד סתום מן המפורש:
@164 **כי לימים עוד שבעה.** אלו שבעת ימי אבלו של מתושלח הצדיק שחס הקדוש ברוך הוא על כבודו ועכב את הפרענות. צא וחשוב שנותיו של מתושלח ותמצא שהם כלים בשנת שש מאות שנה לחיי נח: **כי לימים עוד.** מהו עוד, זמן אחר זמן, זה נוסף על מאה ועשרים שנה: **ארבעים יום.** כנגד יצירת הולד שקלקלו להטריח ליוצרם לצור צורת ממזרים:
@165 **ויעש נח.** זה ביאתו לתבה:
@167 **נח ובניו.** האנשים לבד והנשים לבד, לפי שנאסרו בתשמיש המטה, מפני שהעולם היה שרוי בצער: **מפני מי המבול.** אף נח מקטני אמנה היה, מאמין ואינו מאמין שיבא המבול ולא נכנס לתבה עד שדחקוהו המים:
@169 **שנים שנים.** כלם השוו במנין זה, מן הפחות היו שנים: **באו אל נח.** מאליהן:
@171 **בחדש השני.** רבי אליעזר אומר זה מרחשון, רבי יהושע אומר זה איר: **נבקעו.** להוציא מימיהן: **תהום רבה.** מדה כנגד מדה, הם חטאו ברבה רעת האדם (בראש' ו ה) ולקו בתהום רבה:
@172 **ויהי הגשם על הארץ.** ולהלן הוא אומר (פסוק יז) ויהי המבול, אלא כשהורידן, הורידן ברחמים שאם יחזרו יהיו גשמי ברכה, וכשלא חזרו היו למבול: **ארבעים יום** וגו' **.** אין יום ראשון מן המנין לפי שאין לילו עמו, שהרי כתיב ביום הזה נבקעו כל מעינות, נמצאו ארבעים יום כלים בעשרים ושמונה בכסלו, לרבי אליעזר שהחדשים נמנין כסדרן אחד מלא ואחד חסר, הרי שנים עשר ממרחשון ועשרים ושמונה מכסלו:
@173 **בעצם היום הזה.** למדך הכתוב שהיו בני דורו אומרים אלו אנו רואים אותו נכנס לתבה אנו שוברין אותה והורגין אותו, אמר הקדוש ברוך הוא אני מכניסו לעיני כלם (בר''ר) ונראה דבר מי יקום:
@174 **צפור כל כנף.** דבוק הוא, צפור של כל מין כנף, לרבות חגבים (כנף לשון נוצה כמו (ויקרא א יז) ושסע אותו בכנפיו שאפלו נוצתה עולה, אף כאן צפור כל מין מראית נוצה) :
@176 **ויסגור ה' בעדו.** הגין עליו שלא ישברוה, הקיף התבה דבים ואריות והיו הורגים בהם. ופשוטו של מקרא סגר כנגדו מן המים וכן כל בעד שבמקרא לשון כנגד הוא (בראש' כ יח) בעד כל רחם, (מ''ב ד ד) בעדך ובעד בניך, (איוב ב ד) עור בעד עור, (תהלים ג ד) מגן בעדי, (ש''א יב יט) התפלל בעד עבדיך, כנגד עבדיך:
@177 **ותרם מעל הארץ.** משקעת היתה במים אחת עשרה אמה כספינה טעונה המשקעת מקצתה במים ומקראות שלפנינו יוכיחו:
@178 **ויגברו.** מאליהן:
@180 **חמש עשרה אמה מלמעלה.** למעלה של גובה כל ההרים לאחר שהשוו המים לראשי ההרים:
@182 **נשמת רוח חיים.** נשימה של רוח חיים: **אשר בחרבה.** ולא דגים שבים:
@183 **וימח.** לשון ויפעל הוא ואינו לשון ויפעל והוא מגזרת ויפן ויבן. כל תבה שסופה ה''א כגון בנה, מחה, קנה, כשהוא נותן וי''ו יו''ד בראשה נקוד בחירק תחת היו''ד: **אך נח.** לבד נח, זהו פשוטו. ומדרש אגדה היה גונח וכוהה דם מטורח הבהמות והחיות. ויש אומרים שאיחר מזונות לארי והכישו, ועליו נאמר (משלי יא לא) הן צדיק בארץ ישלם:
@185 **ויזכר אלהים.** זה השם מדת הדין הוא, ונהפכה למדת רחמים על ידי תפלת הצדיקים, ורשעתן של רשעים הופכת מדת רחמים למדת הדין, שנאמר (בראשית ו ה) וירא ה' כי רבה רעת האדם וגו' ויאמר ה' אמחה, והוא שם מדת רחמים: **ויזכור אלהים את נח** וגו' **.** מה זכר להם לבהמות, זכות שלא השחיתו דרכם קודם לכן ושלא שמשו בתבה: **ויעבר אלהים רוח.** רוח תנחומין והנחה עברה לפניו: **על הארץ.** על עסקי הארץ: **וישכו.** כמו (אסתר ב א) כשוך חמת המלך לשון הנחת חמה:
@186 **ויסכרו מעינות.** כשנפתחו כתיב (ז יא) כל מעינות, וכאן אין כתיב כל, לפי שנשתירו מהם אותן שיש בהם צורך לעולם, כגון חמי טבריא וכיוצא בהם: **ויכלא.** וימנע, כמו (תהלים מ יב) לא תכלא רחמיך, (בראשית כג ו) לא יכלה ממך:
@187 **מקצה חמשים ומאת יום.** התחילו לחסור, והוא אחד בסיון. כיצד בעשרים ושבעה בכסלו פסקו הגשמים הרי שלשה מכסלו ועשרים ותשעה מטבת הרי שלשים ושנים, ושבט ואדר וניסן ואייר מאה ושמונה עשר הרי מאה וחמשים:
@188 **בחדש השביעי.** סיון והוא שביעי לכסלו שבו פסקו הגשמים: **בשבעה עשר יום.** מכאן אתה למד שהיתה התבה משקעת במים אחת עשרה אמה, שהרי כתיב (פסוק ה) בעשירי באחד לחדש נראו ראשי ההרים, זה אב שהוא עשירי (למרחשון) לירידת גשמים והם היו גבוהים על ההרים חמש עשרה אמה וחסרו מיום אחד בסיון עד אחד באב חמש עשרה אמה לששים יום, הרי אמה לארבעה ימים, נמצא שבששה עשר בסיון לא חסרו אלא ארבע אמות, ונחה התבה ליום המחרת, למדת שהיתה משקעת אחת עשרה אמה במים שעל ראשי ההרים:
@189 **בעשירי** וכו' **נראו ראשי ההרים.** זה אב, שהוא עשירי למרחשון שהתחיל הגשם. ואם תאמר הוא אלול ועשירי לכסלו שפסק הגשם, כשם שאתה אומר בחדש השביעי סיון והוא שביעי להפסקה. אי אפשר לומר כן, על כרחך שביעי אי אתה מונה אלא להפסקה, שהרי לא כלו ארבעים יום של ירידת גשמים ומאה וחמשים של תגברת המים עד אחד בסיון, ואם אתה אומר שביעי לירידה אין זה סיון והעשירי אי אפשר למנות אלא לירידה, שאם אתה אומר להפסקה והוא אלול, אי אתה מוצא בראשון באחד לחדש חרבו המים מעל הארץ, שהרי מקץ ארבעים משנראו ראשי ההרים שלח את העורב, ועשרים ואחד יום הוחיל בשליחות היונה, הרי ששים יום משנראו ראשי ההרים עד שחרבו פני האדמה, ואם תאמר באלול נראו, נמצא שחרבו במרחשון, והוא קורא אותו ראשון ואין זה אלא תשרי, שהוא ראשון לבריאת עולם, ולרבי יהושע הוא ניסן:
@190 **מקץ ארבעים יום.** משנראו ראשי ההרים: **את חלון התבה אשר עשה.** לצהר, ולא זה פתח התבה העשוי לביאה ויציאה:
@191 **יצוא ושוב.** הולך ומקיף סביבות התבה ולא הלך בשליחותו שהיה חושדו על בת זוגו, כמו ששנינו באגדת חלק (סנהדרין קח:) : **עד יבשת המים.** פשוטו כמשמעו. אבל מדרש אגדה מוכן היה העורב לשליחות אחרת בעצירת גשמים בימי אליהו, שנאמר (מלכים א' יז ו) והערבים מביאים לו לחם ובשר:
@192 **וישלח את היונה.** לסוף שבעה ימים שהרי כתיב ויחל עוד שבעת ימים אחרים, מכלל זה אתה למד שאף בראשונה הוחיל שבעה ימים: **וישלח.** אין זה לשון שליחות אלא לשון שלוח, שלחה ללכת לדרכה, ובזו יראה אם קלו המים שאם תמצא מנוח לא תשוב אליו:
@194 **ויחל.** לשון המתנה, וכן (איוב כט כא) לי שמעו ויחלו, והרבה יש במקרא:
@195 **טרף בפיה.** אומר אני שזכר היה לכן קוראו פעמים לשון זכר ופעמים לשון נקבה, לפי שכל יונה שבמקרא לשון נקבה, כמו (שה''ש ה יב) כיונים על אפיקי מים רוחצות, (יחזקאל ז טז) כיוני הגאיות כלם המות וכמו (הושע ז יא) כיונה פותה: **טרף.** חטף, ומדרש אגדה לשון מזון, ודרשו בפיה, לשון מאמר, אמרה יהיו מזונותי מרורין כזית בידו של הקדוש ברוך הוא ולא מתוקין כדבש בידי בשר ודם:
@196 **וייחל.** הוא לשון ויחל, אלא שזה לשון ויפעל וזה לשון ויתפעל. ויחל וימתין, וייחל ויתמתן:
@197 **בראשון.** לרבי אליעזר הוא תשרי, ולרבי יהושע הוא ניסן: **חרבו.** נעשה כמין טיט, שקרמו פניה של מעלה:
@198 **בשבעה ועשרים.** וירידתן בחדש השני בשבעה עשר, אלו אחד עשר ימים שהחמה יתרה על הלבנה, שמשפט דור המבול שנה תמימה היה: **יבשה.** נעשה גריד כהלכתה:
@200 **אתה ואשתך** וגו' **.** איש ואשתו, כאן התיר להם תשמיש המטה:
@201 **היצא.** הוצא כתיב היצא קרי. היצא, אמור להם שיצאו. הוצא, אם אינם רוצים לצאת הוציאם אתה: **ושרצו בארץ.** ולא בתיבה, מגיד שאף הבהמה והעוף נאסרו בתשמיש:
@203 **למשפחתיהם.** קבלו עליהם על מנת לדבק במינן:
@204 **מכל הבהמה הטהורה.** אמר לא צוה לי הקדוש ברוך הוא להכניס מאלו שבעה שבעה אלא כדי להקריב קרבן מהם:
@205 **מנעריו.** מנעריו כתיב משננער לצאת ממעי אמו נתן בו יצר הרע: **לא אסף. ולא אסף.** כפל הדבר לשבועה, הוא שכתוב (ישעיהו נד ט) אשר נשבעתי מעבר מי נח, ולא מצינו בה שבועה אלא זו שכפל דבריו והיא שבועה, וכן דרשו חכמים במסכת שבועות (לו א) :
@206 **עוד כל ימי הארץ** וגו' **לא ישבתו.** שש עתים הללו שני חדשים לכל אחד ואחד, כמו ששנינו חצי תשרי ומרחשון וחצי כסלו זרע, חצי כסלו וטבת וחצי שבט קור וכו' : **קור.** קשה מחורף: **חורף.** עת זרע שעורים וקטניות החריפין להתבשל מהר. הוא חצי שבט ואדר וחצי ניסן: **קציר.** חצי ניסן ואייר וחצי סיון: **קיץ.** חצי סיון תמוז וחצי אב, הוא זמן לקיטת תאנים וזמן שמיבשים אותן בשדות, ושמו קיץ כמו (שמואל ב טז ב) והלחם והקיץ לאכול הנערים: **חום.** הוא סוף ימות החמה חצי אב ואלול וחצי תשרי, שהעולם חם ביותר, כמו ששנינו במסכת יומא (כט א) שלהי קייטא קשי מקייטא: **ויום ולילה לא ישבתו.** מכלל ששבתו כל ימות המבול, שלא שמשו המזלות ולא נכר בין יום ובין לילה: **לא ישבתו.** לא יפסקו כל אלה מלהתנהג כסדרן:
@208 **וחתכם.** ואימתכם כמו (איוב ו כא) תראו חתת. ואגדה לשון חיות שכל זמן שהתינוק בן יומו חי אין אתה צריך לשמרו מן העכברים, עוג מלך הבשן מת, צריך לשמרו מן העכברים, שנאמר ומוראכם וחתכם יהיה, אימתי יהיה מוראכם על החיות, כל זמן שאתם חיים:
@209 **לכם יהיה לאכלה.** שלא הרשיתי לאדם הראשון לאכול בשר אלא ירק עשב, ולכם כירק עשב שהפקרתי לאדם הראשון, נתתי לכם את כל:
@210 **בשר בנפשו.** אסר להם אבר מן החי, כלומר כל זמן שנפשו בו לא תאכלו הבשר: **בנפשו דמו.** בעוד נפשו בו: **בשר בנפשו לא תאכלו.** הרי אבר מן החי ואף בנפשו דמו לא תאכלו, הרי דם מן החי:
@211 **ואך את דמכם.** אף על פי שהתרתי לכם נטילת נשמה בבהמה, את דמכם אדרוש מהשופך דם עצמו: **לנפשותיכם.** אף החונק עצמו אף על פי שלא יצא ממנו דם: **מיד כל חיה.** לפי שחטאו דור המבול והפקרו למאכל חיות רעות לשלוט בהן, שנאמר (תהלים מט יג) נמשל כבהמות נדמו, לפיכך הצרך להזהיר עליהן את החיות: **ומיד האדם.** מיד ההורג במזיד ואין עדים אני אדרוש: **מיד איש אחיו.** מיד שהוא אוהב לו כאח והרגו שוגג, אני אדרוש, אם לא יגלה ויבקש על עונו למחל, שאף השוגג צריך כפרה, ואם אין עדים לחייבו גלות והוא אינו נכנע, הקדוש ברוך הוא דורש ממנו. כמו שדרשו רבותינו זכרונם לברכה והאלהים אנה לידו במסכת מכות (י ב) הקדוש ברוך הוא מזמנן לפנדק אחד וכו' :
@212 **באדם דמו ישפך.** אם יש עדים המיתוהו אתם, למה, כי בצלם אלהים וגו' : **עשה את האדם.** זה מקרא חסר, וצריך להיות עשה העושה את האדם, וכן הרבה במקרא:
@213 **ואתם פרו ורבו.** לפי פשוטו הראשונה לברכה, וכאן לצווי. ולפי מדרשו להקיש מי שאינו עוסק בפריה ורביה לשופך דמים:
@215 **ואני הנני.** מסכים אני עמך, שהיה נח דואג לעסוק בפריה ורביה עד שהבטיחו הקדוש ברוך הוא שלא לשחת את העולם עוד, וכן עשה. ובאחרונה אמר לו הנני מסכים לעשות קיום וחזוק ברית להבטחתי, ואתן לך אות:
@216 **חית הארץ אתכם.** הם המתהלכים עם הבריות: **מכל יוצאי התבה.** להביא שקצים ורמשים: **לכל חית הארץ.** להביא המזיקין שאינן בכלל החיה אשר אתכם, שאין הלוכן עם הבריות:
@217 **והקימותי.** אעשה קיום לבריתי, ומהו קיומו, את הקשת כמו שמסים והולך:
@218 **לדרת עולם.** נכתב חסר, שיש דורות שלא הצרכו לאות לפי שצדיקים גמורים היו, כמו דורו של חזקיהו מלך יהודה, ודורו של רבי שמעון בן יוחאי:
@220 **בענני ענן.** כשתעלה במחשבה לפני להביא חשך ואבדון לעולם:
@222 **בין אלהים ובין כל נפש חיה.** בין מדת הדין של מעלה וביניכם שהיה לו לכתוב ביני ובין כל נפש חיה. אלא זהו מדרשו כשתבא מדת הדין לקטרג עליכם (לחיב אתכם) אני רואה את האות ונזכר:
@223 **זאת אות הברית.** הראהו הקשת ואמר לו הרי האות שאמרתי:
@224 **וחם הוא אבי כנען.** למה הצרך לומר כאן, לפי שהפרשה עסוקה ובאה בשכרותו של נח שקלקל בה חם, ועל ידו נתקלל כנען, ועדיין לא כתב תולדות חם, ולא ידענו שכנען בנו, לפיכך הצרך לומר כאן וחם הוא אבי כנען:
@226 **ויחל.** עשה עצמו חלין, שהיה לו לעסוק תחלה בנטיעה אחרת: **איש האדמה.** אדוני האדמה, כמו (רות א ג) איש נעמי: **ויטע כרם.** כשנכנס לתבה הכניס עמו זמורות ויחורי תאנים:
@227 **ויתגל.** לשון ויתפעל: **אהלו.** אהלה כתיב רמז לעשרת שבטים שנקראו על שם שומרון שנקראת אהלה, שגלו על עסקי היין, שנאמר השתים במזרקי יין (עמוס ו ו) :
@228 **וירא חם אבי כנען.** יש מרבותינו אומרים כנען ראה והגיד לאביו לכך הזכר על הדבר ונתקלל: **וירא את ערות אביו.** יש אומרים סרסו ויש אומרים רבעו:
@229 **ויקח שם ויפת.** אין כתיב כאן ויקחו אלא ויקח, למד על שם שנתאמץ במצוה יותר מיפת, לכך זכו בניו לטלית של ציצית, ויפת זכה לקבורה לבניו, שנאמר (יחזקאל לט יא) אתן לגוג מקום שם קבר. וחם שבזה את אביו נאמר בזרעו (ישעיה כ ד) כן ינהג מלך אשור את שבי מצרים ואת גלות כוש נערים וזקנים ערום ויחף וחשופי שת וגו' : **ופניהם אחורנית.** למה נאמר פעם שניה, מלמד שכשקרבו אצלו והצרכו להפך עצמם לכסותו, הפכו פניהם אחורנית:
@230 **בנו הקטן.** הפסול והבזוי, כמו (ירמיה מט טו) הנה קטן נתתיך בגוים בזוי באדם:
@231 **ארור כנען.** אתה גרמת לי שלא אוליד בן רביעי אחר לשמשני, ארור בנך רביעי להיות משמש את זרעם של אלו הגדולים, שהטל עליהם טורח עבודתי מעתה. ומה ראה חם שסרסו, אמר להם לאחיו אדם הראשון שני בנים היו לו, והרג זה את זה בשביל ירשת העולם ואבינו יש לו שלשה בנים ועודנו מבקש בן רביעי:
@232 **ברוך ה' אלהי שם.** שעתיד לשמור הבטחתו לזרעו לתת להם את ארץ כנען: **ויהי כנען עבד למו.** למס עובד:
@233 **יפת אלהים ליפת.** מתורגם יפתי, ירחיב: **וישכון באהלי שם.** ישרה שכינתו בישראל. ומדרש חכמים אף על פי שיפת אלהים ליפת, שבנה כרש שהיה מבני יפת בית שני, לא שרתה בו שכינה. והיכן שרתה, במקדש ראשון שבנה שלמה שהיה מבני שם: **ויהי כנען עבד למו.** אף משיגלו בני שם, ימכרו להם עבדים מבני כנען:
@237 **ותירס.** זו פרס:
@243 **להיות גבר.** להמריד כל העולם על הקדוש ברוך הוא בעצת דור הפלגה:
@244 **גבר ציד.** צד דעתן של בריות בפיו ומטען למרוד במקום: **לפני ה'.** מתכון להקניטו על פניו: **על כן יאמר כנמרד.** על כל אדם מרשיע בעזות פנים, יודע רבונו ומתכון למרוד בו, יאמר זה כנמרוד גבור ציד:
@246 **מן הארץ** וגו' **.** כיון שראה אשור את בניו שומעין לנמרוד ומורדין במקום לבנות המגדל, יצא מתוכם:
@247 **העיר הגדולה.** היא נינוה שנאמר (יונה ג ג) ונינוה היתה עיר גדולה לאלהים:
@248 **להבים.** שפניהם דומים ללהב:
@249 **ואת פתרוסים ואת כסלוחים אשר יצאו משם פלשתים.** משניהם יצאו, שהיו פתרוסים וכסלוחים מחליפין משכב נשותיהם אלו לאלו, ויצאו מהם פלשתים:
@253 **ואחר נפצו.** מאלו נפוצו משפחות הרבה:
@254 **גבול הכנעני.** סוף ארצו. כל גבול שבמקרא לשון סוף וקצה: **באכה.** שם דבר. ולי נראה כאדם האומר לחברו גבול זה מגיע עד אשר תבא לגבול פלוני:
@255 **ללשונותם בארצותם.** אף על פי שנחלקו ללשונות וארצות, כלם בני חם הם:
@256 **אבי כל בני עבר.** הנהר היה שם: **אחי יפת הגדול.** איני יודע אם יפת הגדול אם שם, כשהוא אומר (להלן יא י) שם בן מאת שנה וגו' שנתים אחר המבול, הוי אומר יפת הגדול, שהרי בן חמש מאות שנה היה נח כשהתחיל להוליד, והמבול היה בשנת שש מאות שנה לנח, נמצא שהגדול בבניו היה בן מאה שנה, ושם לא הגיע למאה שנה עד שנתים אחר המבול: **אחי יפת.** ולא אחי חם, שאלו שניהם כבדו את אביהם, וזה בזהו:
@260 **נפלגה.** נתבלבלו הלשונות, ונפוצו מן הבקעה, ונתפלגו בכל העולם. למדנו שהיה עבר נביא שקרא שם בנו על שם העתיד. ושנינו בסדר עולם (פרק א) שבסוף ימיו נתפלגו, שאם תאמר בתחלת ימיו, הרי יקטן אחיו צעיר ממנו והוליד כמה משפחות קודם לכן, שנאמר (פסוק כו) ויקטן ילד וגו' ואחר כך ויהי כל הארץ וגו' . ואם תאמר באמצע ימיו, לא בא הכתוב לסתום אלא לפרש, הא למדת שבשנת מות פלג נתפלגו:
@261 **ויקטן.** שהיה ענו ומקטין עצמו, לכך זכה להעמיד כל המשפחות הללו: **חצרמות.** על שם מקומו, דברי אגדה:
@268 **שפה אחת.** לשון הקודש: **ודברים אחדים.** באו בעצה אחת ואמרו לא כל המנו שיבור לו את העליונים, נעלה לרקיע ונעשה עמו מלחמה. דבר אחר על יחידו של עולם. דבר אחר ודברים אחדים, אמרו אחת לאלף ושש מאות חמשים ושש שנים הרקיע מתמוטט כשם שעשה בימי המבול, בואו ונעשה לו סמוכות:
@269 **ויהי בנסעם מקדם.** שהיו יושבים שם, כדכתיב למעלה (י ל) ויהי מושבם וגו' הר הקדם, ונסעו משם לתור להם מקום להחזיק את כלם, ולא מצאו אלא שנער:
@270 **איש אל רעהו.** אמה לאמה, מצרים לכוש [וכוש לפוט] ופוט לכנען: **הבה.** הזמינו עצמכם. כל הבה לשון הזמנה הוא, שמכינים עצמן ומתחברים למלאכה, או לעצה, או למשא. הבה, הזמינו אפרייליי''ר בלע''ז : **לבנים.** שאין אבנים בבבל, שהיא בקעה: **ונשרפה לשרפה.** כך עושין הלבנים שקורין טיולי''ש בלע''ז , שורפים אותן בכבשן: **לחמר.** לטוח הקיר:
@271 **פן נפוץ.** שלא יביא עלינו שום מכה להפיצנו מכאן:
@272 **וירד ה' לראות.** לא הצרך לכך, אלא בא ללמד לדינים שלא ירשיעו הנדון עד שיראו ויבינו. במדרש רבי תנחומא (אות יח) : **בני האדם.** אלא בני מי, שמא בני חמורים וגמלים, אלא בני אדם הראשון שכפר את הטובה ואמר (ג יב) האשה אשר נתתה עמדי, אף אלו כפרו בטובה למרוד במי שהשפיעם טובה ומלטם מן המבול:
@273 **הן עם אחד ושפה אחת.** כל טובה זו יש עמהן, שעם אחד הם ושפה אחת לכלם, ודבר זה החלו לעשות: **החלם.** כמו אמרם, עשותם, התחילו הם לעשות: **לא יבצר מהם** וגו' **לעשות.** בתמיהה. יבצר לשון מניעה, כתרגומו, ודומה לו (תהלים עו יג) יבצר רוח נגידים:
@274 **הבה נרדה.** בבית דינו נמלך, מענותנותו היתרה: **הבה.** מדה כנגד מדה, הם אמרו הבה נבנה, והוא כנגדם מדד ואמר הבה נרדה: **ונבלה.** ונבלבל. נו''ן משמש בלשון רבים, וה''א אחרונה יתרה כה''א של נרדה: **לא ישמעו.** זה שואל לבנה וזה מביא טיט, וזה עומד עליו ופוצע את מוחו:
@275 **ויפץ ה' אותם משם.** בעולם הזה. מה שאמרו פן נפוץ, נתקים עליהם, הוא שאמר שלמה (משלי י כד) מגורת רשע היא תבואנו:
@276 **ומשם הפיצם.** למד שאין להם חלק לעולם הבא. וכי אי זו קשה, של דור המבול או של דור הפלגה, אלו לא פשטו יד בעקר, ואלו פשטו יד בעקר כביכול להלחם בו, ואלו נשטפו, ואלו לא נאבדו מן העולם. אלא שדור המבול היו גזלנים והיתה מריבה ביניהם לכך נאבדו, ואלו היו נוהגים אהבה ורעות ביניהם, שנאמר שפה אחת ודברים אחדים. למדת ששנאוי המחלוקת וגדול השלום:
@277 **שם בן מאת שנה.** כשהוליד את ארפכשד שנתים אחר המבול:
@295 **על פני תרח אביו.** בחיי אביו. ומדרש אגדה יש אומרים שעל ידי אביו מת, שקבל תרח על אברם בנו לפני נמרוד על שכתת את צלמיו והשליכו לכבשן האש, והרן יושב ואומר בלבו אם אברם נוצח, אני משלו, ואם נמרוד נוצח, אני משלו. וכשנצל אברם אמרו לו להרן משל מי אתה, אמר להם הרן משל אברם אני. השליכוהו לכבשן האש ונשרף, וזהו אור כשדים. ומנחם בן סרוק פרש אור בקעה, וכן (ישעיה כד טו) בארים כבדו ה', וכן (שם יא ח) מאורת צפעוני. כל חור ובקע עמוק קרוי אור:
@296 **יסכה.** זו שרה, על שם שסוכה ברוח הקודש, ושהכל סוכין ביפיה. ועוד יסכה לשון נסיכות, כמו שרה לשון שררה:
@298 **ויצאו אתם.** ויצאו תרח ואברם עם לוט ושרי:
@299 **וימת תרח בחרן.** לאחר שיצא אברם מחרן ובא לארץ כנען והיה שם יותר מששים שנה, שהרי כתוב (יב ד) ואברם בן חמש שנים ושבעים שנה בצאתו מחרן, (פסוק כו) ותרח בן שבעים שנה היה כשנלד אברם, הרי מאה ארבעים וחמש לתרח כשיצא אברם מחרן, עדיין נשארו משנותיו הרבה. ולמה הקדים הכתוב מיתתו של תרח ליציאתו של אברם, שלא יהא הדבר מפורסם לכל ויאמרו לא קים אברם את כבוד אביו שהניחו זקן והלך לו, לפיכך קראו הכתוב מת, שהרשעים אף בחייהם קרויים מתים, והצדיקים אף במיתתן קרויים חיים, שנאמר (שמואל ב' כג כ) ובניהו בן יהוידע בן איש חי: **בחרן.** הנו''ן הפוכה, לומר לך עד אברם היה חרון אף של מקום בעולם:
@300 **לך לך.** להנאתך ולטובתך, ושם אעשך לגוי גדול, וכאן אי אתה זוכה לבנים. ועוד שאודיע טבעך בעולם:
@301 **ואעשך לגוי גדול.** לפי שהדרך גורמת לשלשה דברים ממעטת פריה ורביה, וממעטת את הממון, וממעטת את השם, לכך הזקק לשלש ברכות הללו שהבטיחו על הבנים, ועל הממון, ועל השם. (וזהו ואגדלה שמך, הריני מוסיף אות על שמך, שעד עכשיו שמך אברם מכאן ואלך אברהם, ואברהם עולה רמ''ח כנגד איבריו של אדם) : **ואברכך.** בממון: **והיה ברכה.** הברכות נתנות בידך, עד עכשיו היו בידי, ברכתי את אדם ואת נח ואותך, ומעכשיו אתה תברך את אשר תחפוץ. דבר אחר ואעשך לגוי גדול זהו שאומרים אלהי אברהם, ואברכך זהו שאומרים אלהי יצחק, ואגדלה שמך זהו שאומרים אלהי יעקב. יכול יהיו חותמין בכלן, תלמוד לומר והיה ברכה, בך חותמין ולא בהם: **מארצך.** והלא כבר יצא משם עם אביו ובא עד לחרן, אלא כך אמר לו התרחק עוד משם וצא מבית אביך: **אל הארץ אשר אראך.** לא גלה לו הארץ מיד, כדי לחבבה בעיניו, ולתת לו שכר על כל דבור ודבור. כיוצא בו (בראשית כב ב) את בנך את יחידך אשר אהבת את יצחק, כיוצא בו (כב ב) על אחד ההרים אשר אמר אליך, כיוצא בו (יונה ג ב) וקרא עליה את הקריאה אשר אנכי דובר אליך:
@302 **ונברכו בך כל משפחת האדמה.** יש אגדות רבות, וזהו פשוטו אדם אומר לבנו תהא כאברהם, וכן כל ונברכו בך שבמקרא, וזה מוכיח (בראשית מח כ) בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה:
@304 **אשר עשו בחרן.** שהכניסן תחת כנפי השכינה, אברהם מגיר את האנשים, ושרה מגירת הנשים, ומעלה עליהם הכתוב כאלו עשאום. ופשוטו של מקרא עבדים ושפחות שקנו להם, כמו (שם לא א) עשה את כל הכבוד הזה, (במד' כד יח) וישראל עשה חיל, לשון קונה וכונס:
@305 **ויעבר אברם בארץ.** נכנס לתוכה: **עד מקום שכם.** להתפלל על בני יעקב כשיבאו להלחם בשכם: **אלון מורה.** הוא שכם, הראהו הר גריזים והר עיבל ששם קבלו ישראל שבועת התורה: **והכנעני אז בארץ.** היה הולך וכובש את ארץ ישראל מזרעו של שם, שבחלקו של שם נפלה כשחלק נח את הארץ לבניו, שנאמר (בראשית יד יח) ומלכי צדק מלך שלם, לפיכך (פסוק ז) ויאמר ה' אל אברם לזרעך אתן את הארץ הזאת, עתיד אני להחזירה לבניך שהם מזרעו של שם:
@306 **ויבן שם מזבח.** על בשורת הזרע ועל בשורת ארץ ישראל:
@307 **ויעתק משם.** אהלו: **מקדם לבית אל.** במזרחה של בית אל. נמצאת בית אל במערבו, והוא שנאמר בית אל מים: **אהלו.** אהלה כתיב, בתחלה נטה את אהל אשתו ואחר כך את שלו: **ויבן שם מזבח.** נתנבא שעתידין בניו להכשל שם על עון עכן והתפלל שם עליהם:
@308 **הלוך ונסוע.** לפרקים, יושב כאן חדש או יותר ונוסע משם ונוטה אהלו במקום אחר, וכל מסעיו הנגבה ללכת לדרומה של ארץ ישראל והוא לצד ירושלים שהיא בחלקו של יהודה, שנטלו בדרומה של ארץ ישראל הר המוריה שהיא נחלתו:
@309 **רעב בארץ.** באותה ארץ לבדה, לנסותו אם יהרהר אחר דבריו של הקדוש ברוך הוא שאמר לו ללכת אל ארץ כנען, ועכשיו משיאו לצאת ממנה:
@310 **הנה נא ידעתי.** מדרש אגדה עד עכשיו לא הכיר בה מתוך צניעות שבשניהם, ועכשיו על ידי מעשה הכיר בה. דבר אחר מנהג העולם שעל ידי טורח הדרך אדם מתבזה, וזאת עמדה ביפיה. ופשוטו של מקרא הנה נא הגיע השעה שיש לדאוג על יפיך, ידעתי זה ימים רבים כי יפת מראה את, ועכשיו אנו באים בין אנשים שחורים ומכוערים, אחיהם של כושים, ולא הרגלו באשה יפה. ודומה לו (בראשית יט ב) הנה נא אדני סורו נא:
@312 **למען ייטב לי בעבורך.** יתנו לי מתנות:
@313 **ויהי כבוא אברם מצרימה.** היה לו לומר כבואם מצרימה, אלא למד שהטמין אותה בתבה ועל ידי שתבעו את המכס פתחו וראו אותה:
@314 **ויהללו אותה אל פרעה.** הללוה ביניהם לומר הגונה זו למלך:
@315 **ולאברם היטיב.** פרעה **בעבורה.** [נתן לו מתנות]:
@316 **וינגע ה'** וגו' **.** במכת ראתן לקה, שהתשמיש קשה לו: **ואת ביתו.** כתרגומו ועל אנש ביתיה (ומדרשו לרבות כותליו ועמודיו וכליו) : **על דבר שרי.** על פי דבורה, אומרת למלאך הך והוא מכה:
@318 **קח ולך.** לא כאבימלך שאמר לו (כ טו) הנה ארצי לפניך, אלא אמר לו לך ואל תעמד, שהמצרים שטופי זמה הם, שנאמר (יחזקאל כג כ) וזרמת סוסים זרמתם:
@319 **ויצו עליו.** על אודותיו לשלחו ולשמרו: **וישלחו.** כתרגומו ואלויאו:
@320 **ויעל אברם** וגו' **הנגבה.** לבא לדרומה של ארץ ישראל כמו שאמור למעלה (פסוק ט) הלוך ונסוע הנגבה, להר המוריה, ומכל מקום כשהוא הולך ממצרים לארץ כנען מדרום לצפון הוא מהלך, שארץ מצרים בדרומה של ארץ ישראל, כמו שמוכיח במסעות ובגבולי הארץ:
@321 **כבד מאד.** טעון משאות:
@322 **וילך למסעיו.** כשחזר ממצרים לארץ כנען היה הולך ולן באכסניות שלן בהם בהליכתו למצרים. למדך דרך ארץ שלא ישנה אדם מאכסניא שלו. דבר אחר בחזרתו פרע הקפותיו: **מנגב.** ארץ מצרים בדרומה של ארץ כנען:
@323 **אשר עשה שם בראשנה ויקרא שם.** ואשר קרא שם אברם בשם ה'. וגם יש לומר ויקרא שם עכשיו בשם ה':
@324 **ההולך את אברם.** מי גרם שהיתה לו זאת, הליכתו עם אברם:
@325 **ולא נשא אתם.** לא היתה יכולה להספיק מרעה למקניהם, ולשון קצר הוא, וצריך להוסיף עליו, כמו ולא נשא אותם מרעה הארץ, לפיכך כתוב ולא נשא בלשון זכר:
@326 **ויהי ריב.** לפי שהיו רועים של לוט רשעים ומרעים בהמתם בשדות אחרים, ורועי אברם מוכיחים אותם על הגזל, והם אומרים נתנה הארץ לאברם, ולו אין יורש, ולוט יורשו, ואין זה גזל, והכתוב אומר והכנעני והפרזי אז ישב בארץ ולא זכה בה אברם עדיין:
@327 **אנשים אחים.** קרובים. ומדרש אגדה דומין בקלסתר פנים:
@328 **אם השמאל ואימנה.** בכל אשר תשב, לא אתרחק ממך ואעמוד לך למגן ולעזר. וסוף דבר הצרך לו שנאמר (יד יד) וישמע אברם כי נשבה אחיו וגו' : **ואימנה.** אימין את עצמי, כמו ואשמאילה אשמאיל את עצמי. ואם תאמר היה לו לנקד ואימינה, כך מצינו במקום אחר (ש''ב יד יט) אם אש להמין ואין נקוד להימין:
@329 **כי כלה משקה.** ארץ נחלי מים: **לפני שחת ה' את סדום ואת עמורה.** היה אותו מישור: **כגן ה'.** לאילנות: **כארץ מצרים.** לזרעים: **באכה צער.** עד צער. ומדרש אגדה דורשה לגנאי, על שהיו שטופי זמה בחר לו לוט בשכונתם במסכת הוריות (י ב) :
@330 **ככר.** מישור, כתרגומו: **מקדם.** נסע מאצל אברם והלך לו למערבו של אברם, נמצא נוסע ממזרח למערב. ומדרש אגדה הסיע עצמו מקדמונו של עולם אמר אי אפשי לא באברם ולא באלהיו:
@331 **ויאהל.** נטה אהלים לרועיו ולמקנהו עד סדום:
@332 **ואנשי סדום רעים.** ואף על פי כן לא נמנע לוט מלשכון עמהם. ורבותינו למדו מכאן (משלי י ז) שם רשעים ירקב: **רעים.** בגופם: **וחטאים.** בממונם: **לה' מאד.** יודעים רבונם ומתכונים למרוד בו:
@333 **אחרי הפרד לוט.** כל זמן שהרשע עמו היה הדבור פורש ממנו:
@335 **אשר אם יוכל איש.** כשם שאי אפשר לעפר להמנות, כך זרעך לא ימנה:
@337 **ממרא.** שם אדם:
@338 **אמרפל.** הוא נמרוד שאמר לאברהם פול לתוך כבשן האש: **מלך גוים.** מקום יש ששמו גוים, על שם שנתקבצו שמה מכמה אמות ומקומות והמליכו איש עליהם ושמו תדעל:
@339 **ברע.** רע לשמים ורע לבריות: **ברשע.** שנתעלה ברשעו: **שנאב.** שונא אביו שבשמים: **שמאבר.** שם אבר לעוף ולקפוץ ולמרוד בהקדוש ברוך הוא: **בלע.** שם העיר:
@340 **עמק השדים.** כך שמו, על שם שהיו בו שדות הרבה: **הוא ים המלח.** לאחר זמן נמשך הים לתוכו ונעשה ים המלח. ומדרש אגדה אומר שנתבקעו הצורים סביבותיו ונמשכו יאורים לתוכו:
@341 **שתים עשרה שנה עבדו.** חמשה מלכים הללו את כדרלעומר:
@342 **ובארבע עשרה שנה.** למרדן, **בא כדרלעומר' לפי שהוא היה בעל המעשה נכנס בעבי הקורה: והמלכים.** אלה שלשה מלכים: **הזוזים.** הם זמזמים:
@343 **בהררם.** בהר שלהם: **איל פארן.** כתרגומו מישור. ואומר אני שאין איל לשון מישור, אלא מישור של פארן איל שמו, ושל ממרא אלוני שמו, ושל ירדן ככר שמו, ושל שטים אבל שמו אבל השטים, וכן בעל גד בעל שמו, וכלם מתורגמין מישור, וכל אחד שמו עליו: **על המדבר.** אצל המדבר, כמו (במדבר ב כ) ועליו מטה מנשה:
@344 **עין משפט הוא קדש.** על שם העתיד, שעתידין משה ואהרן להשפט שם על עסקי אותו העין, והם מי מריבה. ואונקלוס תרגמו כפשוטו, מקום שהיו בני המדינה מתקבצים שם לכל משפט: **שדה העמלקי.** עדיין לא נלד עמלק ונקרא על שם העתיד: **בחצצון תמר.** הוא עין גדי, מקרא מלא (דה''י ב' כ ב) ביהושפט:
@346 **ארבעה מלכים את החמשה.** ואף על פי כן נצחו המועטים, להודיעך שגבורים היו, ואף על פי כן לא נמנע אברהם מלרדוף אחריהם:
@347 **בארת בארת חמר.** בארות הרבה היו שם שנוטלין משם אדמה לטיט של בנין. ומדרש אגדה שהיה הטיט מגבל בהם, ונעשה נס למלך סדום שיצא משם, לפי שהיו באמות מקצתן שלא היו מאמינין שנצל אברהם מאור כשדים מכבשן האש, וכיון שיצא זה מן החמר האמינו באברהם למפרע: **הרה נסו.** להר נסו. הרה כמו להר, כל תבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה. ויש חלוק בין הרה לההרה שה''א שבסוף התבה עומדת במקום למ''ד שבראשה, אבל אינה עומדת במקום למ''ד ונקודה פת''ח תחתיה, והרי הרה כמו להר, או כמו אל הר, ואינו מפרש לאיזה הר, אלא שכל אחד נס כאשר מצא הר תחלה, וכשהוא נותן ה''א בראשה לכתוב ההרה או המדברה, פתרונו כמו אל ההר או כמו לההר, ומשמע לאותו הר הידוע ומפורש בפרשה:
@349 **והוא ישב בסדום.** מי גרם לו זאת, ישיבתו בסדום:
@350 **ויבא הפליט.** [מדרשו] לפי פשוטו זה עוג שפלט מן המלחמה, והוא שכתוב (דברים ג יא) כי רק עוג נשאר מיתר הרפאים, וזהו נשאר שלא הרגוהו אמרפל וחבריו כשהכו את הרפאים בעשתרות קרנים, תנחומא (חוקת כה) . ומדרש בראשית רבה (מב ח) זה עוג שפלט מדור המבול, וזהו מיתר הרפאים שנאמר (ו ד) הנפלים היו בארץ וגו' ומתכון שיהרג אברהם וישא את שרה: **העברי.** שבא מעבר הנהר: **בעלי ברית אברם.** שכרתו עמו ברית (דבר אחר שהשיאו לו עצה על המילה כמו שמפורש במקום אחר) :
@351 **וירק.** כתרגומו וזרז, וכן (ויקרא כו לג) והריקתי אחריכם חרב, אזדיין בחרבי עליכם, וכן (שמות טו ט) אריק חרבי, וכן (תהלים לה ג) והרק חנית וסגר: **חניכיו.** חנכו כתיב זה אליעזר שחנכו למצוות והוא לשון התחלת כניסת האדם או כלי לאמנות שהוא עתיד לעמוד בה, וכן (משלי כב ו) חנך לנער, (במדבר ז יא) חנכת המזבח, (תהלים ל א) חנכת הבית ובלע''ז קורין לו איניציי''ר : **שמנה עשר ושלש מאות.** רבותינו אמרו אליעזר לבדו היה, והוא מנין גימטריא של שמו: **עד דן.** שם תשש כחו, שראה שעתידין בניו להעמיד שם עגל:
@352 **ויחלק עליהם.** לפי פשוטו, סרס המקרא, ויחלק הוא ועבדיו עליהם לילה כדרך הרודפים שמתפלגים אחר הנרדפים כשבורחים זה לכאן וזה לכאן: **לילה.** כלומר אחר שחשכה לא נמנעו מלרדפם. ומדרש אגדה שנחלק הלילה ובחציו הראשון נעשה לו נס, וחציו השני נשמר ובא לו לחצות לילה של מצרים: **עד חובה.** אין מקום ששמו חובה, אלא דן קורא חובה על שם עבודה זרה שעתידה להיות שם:
@354 **עמק שוה.** כך שמו כתרגומו למישר מפנא, פנוי מאילנות ומכל מכשול: **עמק המלך.** בית ריסא דמלכא, בית ריס אחד שהוא שלשים קנים, שהיה מיוחד למלך לשחק שם. ומדרש אגדה עמק שהשוו שם כל האמות והמליכו את אברהם עליהם לנשיא אלהים ולקצין:
@355 **ומלכי צדק.** מדרש אגדה הוא שם בן נח: **לחם ויין.** כך עושים ליגיעי מלחמה, והראה לו שאין בלבו עליו על שהרג את בניו. ומדרש אגדה רמז לו על המנחות ועל הנסכים שיקריבו שם בניו:
@356 **קנה שמים וארץ.** כמו (תהלים קלד ג) עשה שמים וארץ, על ידי עשיתן קנאן להיות שלו:
@357 **אשר מגן.** אשר הסגיר, וכן (הושע יא ח) אמגנך ישראל: **ויתן לו.** אברם, מעשר מכל אשר לו לפי שהיה כהן:
@358 **תן לי הנפש.** מן השבי שלי שהצלת, החזר לי הגופים לבדם:
@359 **הרימתי ידי.** לשון שבועה, מרים אני את ידי לאל עליון וכן (בראשית כב טז) בי נשבעתי, נשבע אני, וכן (שם כג יג) נתתי כסף השדה קח ממני, נותן אני לך כסף השדה וקחהו ממני:
@360 **אם מחוט ועד שרוך נעל.** אעכב לעצמי מן השבי: **ואם אקח מכל אשר לך.** ואם תאמר לתת לי שכר מבית גנזיך, לא אקח: **ולא תאמר אני העשרתי את אברם.** שהקדוש ברוך הוא הבטיחני לעשרני, שנאמר לעיל (יב ב) ואברכך וגו' :
@361 **הנערים.** עבדי אשר הלכו אתי, ועוד ענר אשכל וממרא וגו' . ואף על פי שעבדי נכנסו למלחמה, שנאמר לעיל (פסוק טו) הוא ועבדיו ויכם, וענר וחבריו ישבו על הכלים לשמר, אפלו הכי הם יקחו חלקם. וממנו למד דוד שאמר (ש''א ל כד) כחלק הירד למלחמה וכחלק הישב על הכלים יחדו יחלקו. לכך נאמר (שם פסוק כה) ויהי מהיום ההוא ומעלה וישמה לחק ולמשפט, ולא נאמר והלאה לפי שכבר נתן החוק בימי אברהם:
@362 **אחר הדברים האלה.** כל מקום שנאמר אחר סמוך, אחרי מפלג. אחר שנעשה לו נס זה שהרג את המלכים והיה דואג ואומר שמא קבלתי שכר על כל צדקתי, לכך אמר לו המקום אל תירא אברם אנכי מגן לך מן הענש שלא תענש על כל אותן נפשות שהרגת, ומה שאתה דואג על קבול שכרך, שכרך הרבה מאד:
@363 **הולך ערירי.** מנחם בן סרוק פרשו לשון יורש, וחבר לו (מלאכי ב יב) ער וענה, ערירי בלא יורש, כאשר תאמר (איוב לא יב) ובכל תבואתי תשרש, תעקר שרשיה, כך לשון ערירי חסר בנים, ובלע''ז דישאנפנטי''ף . ולי נראה ער וענה מגזרת (שיר השירים ה ב) ולבי ער, וערירי לשון חרבן, וכן (תהל' קלז ז) ערו ערו, וכן (חבק' ג יג) ערות יסוד, וכן (ירמיה נא נח) ערער תתערער, וכן (צפניה ב יד) כי ארזה ערה: **ובן משק ביתי.** כתרגומו, שכל ביתי נזון על פיו, כמו (בראשית מא מ) ועל פיך ישק, אפטורפס שלי, ואלו היה לי בן היה בני ממנה על שלי: **דמשק.** לפי התרגום מדמשק היה, ולפי מדרש אגדה שרדף המלכים עד דמשק. ובתלמוד דרשו נוטריקון דולה ומשקה מתורת רבו לאחרים:
@364 **הן לי לא נתת זרע.** ומה תועלת בכל אשר תתן לי:
@366 **ויוצא אתו החוצה.** לפי פשוטו הוציאו מאהלו לחוץ לראות הכוכבים, ולפי מדרשו אמר לו צא מאצטגנינות שלך שראית במזלות שאינך עתיד להעמיד בן, אברם אין לו בן, אבל אברהם יש לו בן. וכן שרי לא תלד, אבל שרה תלד, אני קורא לכם שם אחר וישתנה המזל. דבר אחר הוציאו מחללו של עולם והגביהו למעלה מן הכוכבים, וזהו לשון הבטה מלמעלה למטה:
@367 **והאמין בה'.** לא שאל לו אות על זאת, אבל על ירשת הארץ שאל לו אות ואמר לו במה אדע: **ויחשבה לו צדקה.** הקדוש ברוך הוא חשבה לאברם לזכות ולצדקה על האמונה שהאמין בו. דבר אחר במה אדע, לא שאל לו אות אלא אמר לפניו הודיעני באיזה זכות יתקימו בה, אמר לו הקדוש ברוך הוא בזכות הקרבנות:
@370 **עגלה משלשת.** שלשה עגלים, רמז לשלשה פרים פר יום הכפורים, ופר העלם דבר של צבור, ועגלה ערופה: **ועז משלשת.** רמז לשעיר הנעשה בפנים, ושעירי מוספין של מועד, ושעיר חטאת יחיד: **ואיל משלש.** אשם ודאי, ואשם תלוי, וכבשה של חטאת יחיד: **ותור וגוזל.** תור ובן יונה:
@371 **ויבתר אתם.** חלק כל אחד לשני חלקים, ואין המקרא יוצא מידי פשוטו לפי שהיה כורת עמו ברית לשמור הבטחתו להוריש לבניו את הארץ, כדכתיב (פסוק יח) ביום ההוא כרת ה' את אברם ברית לאמר וגו' , ודרך כורתי ברית לחלק בהמה ולעבר בין בתריה, כמה שנאמר להלן (ירמיה לד יט) העוברים בין בתרי העגל, אף כאן תנור עשן ולפיד אש אשר עבר בין הגזרים הוא שלוחו של שכינה שהוא אש: **ואת הצפור לא בתר.** לפי שהאמות נמשלו לפרים ואילים ושעירים, שנאמר (תהלים כב יג) סבבוני פרים רבים וגו' , ואומר (דניאל ח כ) והאיל אשר ראית בעל הקרנים מלכי מדי ופרס. ואומר (שם כא) והצפיר השעיר מלך יון, וישראל נמשלו לבני יונה שנאמר (שה''ש ב יד) יונתי בחגוי הסלע, לפיכך בתר הבהמות רמז על האמות שיהיו כלין והולכין, ואת הצפור לא בתר רמז שיהיו ישראל קימין לעולם:
@372 **העיט.** הוא עוף, ועל שם שהוא עט ושואף הנבלות (איוב ט כו) לטוש עלי אכל, כמו (שמואל א' טו יט) ותעט אל השלל: **על הפגרים.** על הבתרים (הפגרים מתרגמינן פגליא, אלא מתוך שהרגלו לתרגם (פסוק י) איש בתרו, ויהב פלגיא, נתחלף להם תבת פגליא לפלגיא, ותרגמו הפגרים פלגיא, וכל המתרגם כן טועה, לפי שאין להקיש בתרים לפגרים, שבתרים תרגומו פלגיא, ופגרים תרגומו פגליא לשון פגול, כמו (ויקרא יט ז) פגול הוא לשון פגר) : **וישב.** לשון נשיבה והפרחה, כמו (תהל' קמז יח) ישב רוחו, רמז שיבא דוד בן ישי לכלותם, ואין מניחין אותו מן השמים עד שיבא מלך המשיח:
@373 **והנה אימה** וגו' **.** רמז לצרות וחשך של גליות:
@374 **כי גר יהיה זרעך.** משנלד יצחק עד שיצאו ישראל ממצרים ארבע מאות שנה. כיצד, יצחק בן ששים שנה כשנלד יעקב. ויעקב כשירד למצרים אמר (להלן מז ט) ימי שני מגורי שלשים ומאת שנה, הרי מאה ותשעים, ובמצרים היו מאתים ועשר כמנין רדו, הרי ארבע מאות שנה. ואם תאמר במצרים היו ארבע מאות, הרי קהת מיורדי מצרים היה, צא וחשוב שנותיו של קהת, ושל עמרם, ושמונים של משה שהיה כשיצאו ישראל ממצרים, אין אתה מוצא אלא שלש מאות וחמשים, ואתה צריך להוציא מהן כל השנים שחי קהת אחר לידת עמרם, ושחי עמרם אחר לידת משה: **בארץ לא להם.** לא נאמר בארץ מצרים אלא בארץ לא להם, ומשנלד יצחק (להלן כא לד) ויגר אברהם וגו' , וביצחק (שם כו ג) גור בארץ הזאת, (תהלים קה כג) ויעקב גר בארץ חם, (בראשית מז ד) לגור בארץ באנו:
@375 **וגם את הגוי.** וגם לרבות ארבע מלכיות, שאף הם כלים על ששעבדו את ישראל: **דן אנכי.** בעשר מכות: **ברכוש גדול.** בממון גדול, כמו שנאמר (שמות יב לו) וינצלו את מצרים:
@376 **ואתה תבוא.** ולא תראה כל אלה: **אל אבתיך.** אביו עובד עבודה זרה והוא מבשרו שיבא אליו, אלא למדך שעשה תרח תשובה: **תקבר בשיבה טובה.** בשרו שיעשה ישמעאל תשובה בימיו ולא יצא עשו לתרבות רעה בימיו, ולפיכך מת חמש שנים קודם זמנו ובו ביום מרד עשו:
@377 **ודור רביעי.** לאחר שיגלו למצרים יהיו שם שלשה דורות, והרביעי ישובו לארץ הזאת, לפי שבארץ כנען היה מדבר עמו וכרת ברית זו, כדכתיב (פסוק ז) לתת לך את הארץ הזאת לרשתה, וכן היה. יעקב ירד למצרים. צא וחשוב דורותיו יהודה, פרץ, חצרון, וכלב בן חצרון מבאי הארץ היה: **כי לא שלם עון האמורי.** להיות משתלח מארצו עד אותו זמן, שאין הקדוש ברוך הוא נפרע מאמה עד שתתמלא סאתה, שנאמר (ישעיה כז ח) בסאסאה בשלחה תריבנה:
@378 **ויהי השמש באה.** כמו ויהי הם מריקים שקיהם (בראשית מב לה) , ויהי הם קוברים איש, כלומר ויהי דבר זה (מ''ב יג כא) : **השמש באה.** שקעה: **ועלטה היה.** חשך היום: **והנה תנור עשן** וגו' **.** רמז לו שיפלו המלכיות בגיהנם. באה טעמו למעלה, לכך הוא מבואר שבאה כבר, ואם היה טעמו למטה באל''ף היה מבואר כשהיא שוקעת. ואי אפשר לומר כן, שהרי כבר כתיב ויהי השמש לבא, והעברת תנור עשן לאחר מכאן היתה נמצא שכבר שקעה. וזה חלוק בכל תבה לשון נקבה שיסודה שתי אותיות, כמו בא, קם, שב, כשהטעם למעלה, לשון עבר הוא, כגון זה, וכגון (להלן כט ט) ורחל באה, (שם לז ז) קמה אלמתי, (רות א טו) הנה שבה יבמתך, וכשהטעם למטה הוא לשון הוה, דבר שנעשה עכשיו והולך, כמו (להלן כט ו) באה עם הצאן, (אסתר ב יד) בערב היא באה ובבקר היא שבה:
@379 **לזרעך נתתי.** אמירתו של הקדוש ברוך הוא כאלו היא עשויה: **הנהר הגדול נהר פרת.** לפי שהוא דבוק לארץ ישראל קראהו גדול אף על פי שהוא מאוחר בארבעה נהרות היוצאים מעדן, שנאמר והנהר הרביעי הוא פרת. משל הדיוט עבד מלך מלך, הדבק לשחור וישתחוו לך:
@380 **את הקיני.** עשר אמות יש כאן ולא נתן להם אלא שבעה גוים, והשלשה אדום ומואב ועמון, והם קיני קניזי וקדמוני עתידים להיות ירשה לעתיד, שנאמר (ישעיה יא יד) אדום ומואב משלוח ידם ובני עמון משמעתם:
@381 **ואת הרפאים.** ארץ עוג, שנאמר בה (דברים ג יג) ההוא יקרא ארץ רפאים:
@383 **שפחה מצרית.** בת פרעה היתה, כשראה נסים שנעשו לשרה אמר מוטב שתהא בתי שפחה בבית זה ולא גבירה בבית אחר:
@384 **אולי אבנה ממנה.** למד על מי שאין לו בנים שאינו בנוי אלא הרוס: **אבנה ממנה.** בזכות שאכניס צרתי לתוך ביתי: **לקול שרי.** לרוח הקודש שבה:
@385 **ותקח שרי.** לקחתה בדברים אשריך שזכית לדבק בגוף קדוש כזה: **מקץ עשר שנים.** מועד הקבוע לאשה ששהתה עשר שנים ולא ילדה לבעלה חיב לשא אחרת: **לשבת אברם** וגו' **.** מגיד שאין ישיבת חוצה לארץ עולה לו מן המנין, לפי שלא נאמר לו (לעיל יב ב) ואעשך לגוי גדול, עד שיבא לארץ ישראל:
@386 **ויבא אל הגר ותהר.** מביאה ראשונה: **ותקל גברתה בעיניה.** אמרה שרי זו אין סתרה כגלויה, מראה עצמה כאלו היא צדקת ואינה צדקת, שלא זכתה להריון כל השנים הללו, ואני נתעברתי מביאה ראשונה:
@387 **חמסי עליך.** חמס העשוי לי, עליך אני מטילה הענש, כשהתפללת להקדוש ברוך הוא מה תתן לי ואנכי הולך ערירי, לא התפללת אלא עליך, והיה לך להתפלל על שנינו והייתי אני נפקדת עמך. ועוד, דבריך אתה חומס ממני שאתה שומע בזיוני ושותק: **אנכי נתתי שפחתי** וגו' **ביני וביניך.** כל ביני ובינך שבמקרא חסר, וזה מלא, קרי ביה וביניך שהכניסה עין הרע בעבורה של הגר והפילה עברה, הוא שהמלאך אומר להגר הנך הרה, והלא כבר הרתה והוא מבשר לה שתהר, אלא מלמד שהפילה הריון הראשון:
@388 **ותענה שרי.** היתה משעבדת בה בקושי:
@390 **אי מזה באת.** מהיכן באת. יודע היה, אלא לתן לה פתח לכנס עמה בדברים. ולשון אי מזה, איה המקום שתאמר עליו מזה אני באה:
@391 **ויאמר לה מלאך ה'** וגו' **.** על כל אמירה היה שלוח לה מלאך אחר, לכך נאמר מלאך בכל אמירה ואמירה:
@393 **הנך הרה.** כשתשובי תהרי, כמו (שופטים יג ז) הנך הרה, דאשת מנוח: **וילדת בן.** כמו ויולדת, ודומה לו (ירמיה כב כג) ישבת בלבנון מקננת בארזים: **וקראת שמו.** צווי הוא, כמו שאומר לזכר (יז יט) וקראת את שמו יצחק:
@394 **פרא אדם.** אוהב מדברות לצוד חיות, כמו שכתוב (כא כ. כא) ויהי רבה קשת וישב במדבר פארן: **ידו בכל.** לסטים: **ויד כל בו.** הכל שונאין אותו ומתגרין בו: **ועל פני כל אחיו ישכן.** שיהיה זרעו גדול:
@395 **אתה אל ראי.** נקוד חטף קמ''ץ מפני שהוא שם דבר, אלוה הראיה, שרואה בעלבון של עלובין: **הגם הלם.** לשון תימה, וכי סבורה הייתי שאף הלום במדברות ראיתי שלוחו של מקום אחרי רואי אותם בביתו של אברהם, ששם הייתי רגילה לראות מלאכים. ותדע שהיתה רגילה לראותם שהרי מנוח ראה את המלאך פעם אחת ואמר (שופטים יג כב) מות נמות, וזו ראתה ארבעה פעמים זה אחר זה ולא חרדה:
@396 **באר לחי ראי.** כתרגומו בירא דמלאך קיימאאתחזי עלה:
@397 **ויקרא אברם שם** וגו' **.** אף על פי שלא שמע אברם דברי המלאך שאמר (פסוק יא) וקראת שמו ישמעאל, שרתה רוח הקדש עליו וקראו ישמעאל:
@398 **ואברם בן שמנים שנה** וגו' **.** לשבחו של ישמעאל נכתב, להודיע שהיה בן שלש עשרה שנה כשנמול ולא עכב:
@399 **אני אל שדי.** אני הוא שיש די באלהותי לכל בריה, לפיכך התהלך לפני ואהיה לך לאלוה ולפטרון, וכן כל מקום שהוא במקרא פרושו די יש לו, והכל לפי הענין: **התהלך לפני.** כתרגומו פלח קדמי, הדבק בעבודתי: **והיה תמים.** אף זה צווי אחר צווי, היה שלם בכל נסיונותי. ולפי מדרשו התהלך לפני במצות מילה, ובדבר הזה תהיה תמים, שכל זמן שהערלה בך אתה בעל מום לפני. דבר אחר והיה תמים, עכשיו אתה חסר חמשה אברים שתי עינים, שתי אזנים, וראש הגויה שאוסיף לך אות על שמך ויהיו מנין אותיותיך מאתים ארבעים ושמונה כמנין אבריך:
@400 **ואתנה בריתי.** ברית של אהבה וברית הארץ להורישה לך על ידי מצוה זו:
@401 **ויפל אברם על פניו.** ממורא השכינה, שעד שלא מל לא היה בו כח לעמוד ורוח הקדש נצבת עליו, וזהו שנאמר בבלעם (במדבר כד ד) נפל וגלוי עינים. בברייתא דרבי אליעזר מצאתי כן:
@403 **כי אב המון גוים.** לשון נוטריקון של שמו. ורי''ש שהיתה בו בתחלה, שלא היה אב אלא לארם שהוא מקומו ועכשיו אב לכל העולם, לא זזה ממקומה, שאף יו''ד של שרי נתרעמה על השכינה עד שנתוספה ליהושע, שנאמר (במדבר יג טז) ויקרא משה להושע בן נון יהושע:
@404 **ונתתיך לגוים.** ישראל ואדום, שהרי ישמעאל כבר היה לו ולא היה מבשרו עליו:
@405 **והקמתי את בריתי.** ומה היא הברית, להיות לך לאלהים:
@406 **לאחזת עולם.** ושם אהיה להם לאלהים, אבל הדר בחוצה לארץ דומה כמי שאין לו אלוה:
@407 **ואתה.** וא''ו זו מוסיף על ענין ראשון אני הנה בריתי אתך, ואתה הוי זהיר לשמרו, ומה היא שמירתו, (פסוק י) זאת בריתי אשר תשמרו המול לכם וגו' :
@408 **ביני וביניכם** וגו' **.** אותם של עכשיו: **ובין זרעך אחריך.** העתידין להולד: **המול.** כמו להמול כמו שאתה אומר עשות, כמו לעשות:
@409 **ונמלתם.** כמו ומלתם והנו''ן בו יתרה ליסוד הנופל בו לפרקים, כגון נ' של נושך ונ' של נושא. ונמלתם, כמו ונשאתם, אבל ימול לשון יפעל כמו יעשה, יאכל:
@410 **יליד בית.** שילדתו השפחה בבית: **ומקנת כסף.** שקנאו משנלד:
@411 **המול ימול יליד ביתך.** כאן כפל עליו ולא אמר לשמונה ימים, ללמדך שיש יליד בית נמול לאחר שמנה ימים, כמו שמפורש במסכת שבת (דף קלח ב) :
@412 **וערל זכר.** כאן למד שהמילה באותו מקום שהוא נכר בין זכר לנקבה: **אשר לא ימול.** משיגיע לכלל ענשין ונכרתה, אבל אביו אין ענוש עליו כרת אבל עובר בעשה: **ונכרתה הנפש.** הולך ערירי ומת קודם זמנו:
@413 **לא תקרא את שמה שרי.** דמשמע שרי לי ולא לאחרים כי שרה סתם שמה, שתהא שרה על כל:
@414 **וברכתי אתה.** ומה היא הברכה, שחזרה לנערותה, שנאמר (לקמן יח יב) אחרי בלתי היתה לי עדנה: **וברכתיה.** בהנקת שדים, כשנצרכה לכך ביום משתה של יצחק, שהיו מרננים עליהם שהביאו אסופי מן השוק ואומרים בננו הוא, והביאה כל אחת בנה עמה ומניקתה לא הביאה, והיא היניקה את כלם, הוא שנאמר (כא ז) היניקה בנים שרה. בראשית רבה (נג ט) רמזו במקצת:
@415 **ויפל אברהם על פניו ויצחק.** זה תירגם אנקלוס וחדי, לשון שמחה, ושל שרה לשון מחוך. למדת שאברהם האמין ושמח, ושרה לא האמינה ולגלגה. וזהו שהקפיד הקדוש ברוך הוא על שרה ולא הקפיד על אברהם: **הלבן.** יש תמיהות שהן קימות כמו (ש''א ב כז) הנגלה נגליתי, (ש''ב טו כז) הראה אתה, אף זו היא קימת, וכך אמר בלבו הנעשה חסד זה לאחר מה שהקדוש ברוך הוא עושה לי: **ואם שרה הבת תשעים שנה.** היתה כדאי לילד. ואף על פי שדורות הראשונים היו מולידין בני חמש מאות שנה, בימי אברהם נתמעטו השנים כבר ובא תשות כח לעולם, וצא ולמד מעשרה דורות שמנח ועד אברהם שמיהרו תולדותיהן בני ששים ובני שבעים:
@416 **לו ישמעאל יחיה.** הלואי שיחיה ישמעאל, איני כדאי לקבל מתן שכר כזה: **יחיה לפניך.** יחיה ביראתך, כמו (פסוק א) התהלך לפני, פלח קדמי:
@417 **אבל.** לשון אמתת דברים, וכן (לקמן מב כא) אבל אשמים אנחנו, (מ''ב ד יד) אבל בן אין לה: **וקראת את שמו יצחק.** על שם הצחוק. ויש אומרים על שם י' נסיונות, וצ' שנה של שרה, וח' ימים שנמול, וק' שנה של אברהם. והקימתי את בריתי למה נאמר, והרי כבר כתיב (פסוק ט) ואתה את בריתי תשמור אתה וזרעך וגו' אלא לפי שאומר (פסוק ז) והקמתי וגו' , יכול בני ישמעאל ובני קטורה בכלל הקיום, תלמוד לומר והקמותי את בריתי אתו, ולא עם אחרים. ואת בריתי אקים את יצחק, למה נאמר, [אלא למד שהיה קדוש מבטן]. דבר אחר אמר ר' אבא מכאן למד קל וחומר בן הגבירה מבן האמה, כתיב (פסוק כ) כי הנה ברכתי אותו והפריתי אותו והרביתי אותו, זה ישמעאל וקל וחמר ואת בריתי אקים את יצחק: **את בריתי.** ברית המילה תהא מסורה לזרעו של יצחק:
@418 **שנים עשר נשיאם.** כעננים יכלו, כמו (משלי כה יד) נשיאים ורוח:
@420 **מעל אברהם.** לשון נקיה הוא כלפי שכינה, ולמדנו שהצדיקים מרכבתו של מקום:
@421 **בעצם היום.** בו ביום שנצטוה, ביום ולא בלילה, לא נתיירא לא מן הגוים ולא מן הלצנים, ושלא יהיו אויביו ובני דורו אומרים אלו ראינוהו לא הנחנוהו למול ולקים מצותו של מקום: **וימל.** לשון ויפעל:
@422 **בהמלו.** בהפעלו, כמו (ב ד) בהבראם:
@423 **בהמלו את בשר ערלתו.** באברהם לא נאמר את, לפי שלא היה חסר אלא חתוך בשר, שכבר נתמעך על ידי תשמיש, אבל ישמעאל שהיה ילד הוזקק לחתוך ערלה ולפרוע המילה, לכך נאמר בו את:
@424 **בעצם היום הזה.** שמלאו לאברהם תשעים ותשע שנה ולישמעאל שלש עשרה שנים נמול אברהם וישמעאל בנו:
@426 **וירא אליו.** לבקר את החולה. אמר רבי חמא בר חנינא יום שלישי למילתו היה, ובא הקדוש ברוך הוא ושאל בשלומו: **באלוני ממרא.** הוא שנתן לו עצה על המילה, לפיכך נגלה עליו בחלקו: **ישב.** ישב כתיב, בקש לעמוד, אמר לו הקדוש ברוך הוא שב ואני אעמד, ואתה סימן לבניך, שעתיד אני להתיצב בעדת הדינין והן יושבין, שנאמר (תהלים פב א) אלהים נצב בעדת אל: **פתח האהל.** לראות אם יש עובר ושב ויכניסם בביתו: **כחם היום.** הוציא הקדוש ברוך הוא חמה מנרתיקה שלא להטריחו באורחים, ולפי שראהו מצטער שלא היו אורחים באים, הביא המלאכים עליו בדמות אנשים:
@427 **והנה שלשה אנשים.** אחד לבשר את שרה ואחד להפוך את סדום ואחד לרפאות את אברהם, שאין מלאך אחד עושה שתי שליחיות. תדע לך שכן כל הפרשה הוא מזכירן בלשון רבים (פסוק ח) ויאכלו (פסוק ט) ויאמרו אליו, ובבשורה נאמר (שם י) ויאמר שוב אשוב אליך, ובהפיכת סדום הוא אומר (יט כב) כי לא אוכל לעשות דבר, (שם כא) , לבלתי הפכי. ורפאל שרפא את אברהם הלך משם להציל את לוט, הוא שנאמר (שם יז) ויהי כהוציאם אותם החוצה ויאמר המלט על נפשך, למדת שהאחד היה מציל: **נצבים עליו.** לפניו, כמו (במדבר ב כ) ועליו מטה מנשה. אבל לשון נקיה היא כלפי המלאכים: **וירא.** מהו וירא וירא שני פעמים, הראשון כמשמעו והשני לשון הבנה, נסתכל שהיו נצבים במקום אחד והבין שלא היו רוצים להטריחו ואף על פי שיודעים היו שיצא לקראתם, עמדו במקומם לכבודו ולהראותו שלא רצו להטריחו, וקדם הוא ורץ לקראתם. בבבא מציעא (פו ב) כתיב נצבים עליו, וכתיב וירץ לקראתם, כד חזיוה דהוה שרי ואסר פרשו המנו, מיד וירץ לקראתם:
@428 **ויאמר אדני אם נא** וגו' **.** לגדול שבהם אמר, וקראם כלם אדונים ולגדול אמר אל נא תעבר, וכיון שלא יעבר הוא, יעמדו חבריו עמו, ובלשון זה הוא חול. דבר אחר קודש הוא, והיה אומר להקדוש ברוך הוא להמתין לו עד שירוץ ויכניס את האורחים. ואף על פי שכתוב אחר (פסוק ב) וירץ לקראתם, האמירה קודם לכן היתה, ודרך המקראות לדבר כן, כמו שפרשתי אצל (ו ג) לא ידון רוחי באדם, שנכתב אחר ויולד נח (ה לב) , ואי אפשר לומר אלא אם כן קודם הגזרה עשרים שנה, ושתי הלשונות בבראשית רבה (מח י) :
@429 **יקח נא.** על ידי שליח, והקדוש ברוך הוא שלם לבניו על ידי שליח שנאמר (במדבר כ יא) וירם משה את ידו ויך את הסלע: **ורחצו רגליכם.** כסבור שהם ערביים שמשתחוים לאבק רגליהם והקפיד שלא להכניס עבודה זרה לביתו. אבל לוט שלא הקפיד, הקדים לינה לרחיצה, שנאמר (יט ב) ולינו ורחצו רגליכם: **תחת העץ.** תחת האילן:
@430 **וסעדו לבכם.** בתורה בנביאים ובכתובים מצינו דפתא סעדתא דלבא. בתורה סעדו לבכם. בנביאים (שופטים יט ה) סעד לבך פת לחם. בכתובים (תהלים קד טו) ולחם לבב אנוש יסעד. אמר רבי חמא לבבכם אין כתיב כאן אלא לבכם, מגיד שאין יצר הרע שולט במלאכים: **אחר תעבורו.** אחר כן תלכו: **כי על כן עברתם.** כי הדבר הזה אני מבקש מכם מאחר שעברתם עלי לכבודי: **כי על כן.** כמו על אשר, וכן כל כי על כן שבמקרא (לקמן יט ח) כי על כן באו בצל קורתי, (לקמן לג י) כי על כן ראיתי פניך, (שם לח כו) כי על כן לא נתתיה, (במדבר י לא) כי על כן ידעת חנותנו:
@431 **קמח סלת.** סלת לעוגות, קמח לעמילן של טבחים, לכסות את הקדרה, ולשאוב את הזהמא:
@432 **בן בקר רך וטוב.** שלשה פרים היו כדי להאכילן שלש לשונות בחרדל: **אל הנער.** זה ישמעאל לחנכו במצות:
@433 **ויקח חמאה** וגו' **.** ולחם לא הביא לפי שפרסה שרה נדה, שחזר לה אורח כנשים אותו היום, ונטמאת העיסה: **חמאה.** שומן החלב שקולטין מעל פניו: **ובן הבקר אשר עשה.** אשר תקן, קמא קמא שתקן, אמטי ואייתי קמייהו: **ויאכלו.** נראו כמו שאכלו, מכאן שלא ישנה אדם מן המנהג:
@434 **ויאמרו אליו.** נקוד על אי''ו שבאליו, ותניא רבי שמעון בן אלעזר אומר כל מקום שהכתב רבה על הנקדה אתה דורש הכתב וכו' , וכאן הנקדה רבה על הכתב אתה דורש הנקודה, שאף לשרה שאלו איו אברהם, למדנו שישאל אדם באכסניא שלו לאיש על האשה ולאשה על האיש **.** בבבא מציעא (פז א) אומרים יודעים היו מלאכי השרת שרה אמנו היכן היתה, אלא להודיע שצנועה היתה כדי לחבבה על בעלה. אמר רבי יוסי בר חנינא כדי לשגר לה כוס של ברכה: **הנה באהל.** צנועה היא:
@435 **שוב אשוב.** לא בשרו המלאך שישוב אליו אלא בשליחותו של מקום אמר לו, כמו (טז י) ויאמר לה מלאך ה' הרבה ארבה, והוא אין בידו להרבות, אלא בשליחותו של מקום, אף כאן בשליחותו של מקום אמר לו כן. אלישע אמר לשונמית (מלכים ב' ד טז) למועד הזה כעת חיה את חובקת בן ותאמר אל אדוני איש האלהים אל תכזב בשפחתך, אותן המלאכים שבשרו את שרה אמרו למועד אשוב. אמר לה אלישע אותם המלאכים שהם חיים וקיימים לעולם אמרו למועד אשוב, אבל אני בשר ודם שהיום חי ומחר מת, בין חי ובין מת למועד הזה וגו' : **כעת חיה.** כעת הזאת לשנה הבאה, ופסח היה, ולפסח הבא נלד יצחק, מדלא קרינן כעת אלא כעת. **כעת חיה.** כעת הזאת שתהא חיה לכם שתהיו כלכם שלמים וקימים: **והוא אחריו.** הפתח היה אחר המלאך:
@436 **חדל להיות.** פסק ממנה: **ארח כנשים.** אורח נדות:
@437 **בקרבה.** מסתכלת במעיה ואמרה אפשר הקרבים הללו טעונין ולד, השדים הללו שצמקו מושכין חלב, תנחומא (שופטים יח) : **עדנה.** צחצוח בשר, ולשון משנה (מנחות פו א) משיר את השער ומעדן את הבשר. דבר אחר לשון עדן, זמן וסת נדות:
@438 **האף אמנם.** הגם אמת אלד: **ואני זקנתי.** שנה הכתוב מפני השלום, שהרי היא אמרה ואדוני זקן:
@439 **היפלא.** כתרגומו היתכסי, וכי שום דבר מפלא ומפרד ומכסה ממני מלעשות כרצוני: **למועד.** לאותו מועד המיחד שקבעתי לך אתמול למועד הזה בשנה האחרת:
@440 **כי יראה** וגו' **כי צחקת.** הראשון משמש לשון דהא שנותן טעם לדבר ותכחש שרה לפי שיראה, והשני משמש בלשון אלא, ויאמר לא כדבריך הוא אלא צחקת, שאמרו רבותינו כי משמש בארבע לשונות אי, דילמא, אלא, דהא:
@441 **וישקיפו על פני סדום.** כל השקפה שבמקרא לרעה חוץ מהשקיפה ממעון קדשך (דברים כו טו) , שגדול כח מתנות עניים שהופך מדת רגז לרחמים: **לשלחם.** ללוותם, כסבור אורחים הם:
@442 **המכסה אני.** בתמיהה: **אשר אני עושה.** בסדום, לא יפה לי לעשות דבר זה שלא מדעתו, אני נתתי לו את הארץ הזאת, וחמשה כרכין הללו שלו הן, שנאמר (י יט) גבול הכנעני מצידן וגו' באכה סדמה ועמרה וגו' . קראתי אותו אברהם, אב המון גוים, ואשמיד את הבנים ולא אודיע לאב שהוא אוהבי:
@443 **ואברהם היו יהיה.** מדרש אגדה (משלי י ז) זכר צדיק לברכה, הואיל והזכירו ברכו. ופשוטו וכי ממנו אני מעלים, והרי הוא חביב לפני להיות לגוי גדול ולהתברך בו כל גויי הארץ:
@444 **כי ידעתיו.** לשון חבה, כמו (רות ב א) מודע לאישה, (שם ג ב) הלא בעז מדעתנו, (שמות לג יז) ואדעך בשם, ואמנם עיקר לשון כלם אינו אלא לשון ידיעה, שהמחבב את האדם מקרבו אצלו ויודעו ומכירו. ולמה ידעתיו, למען אשר יצוה לפי שהוא מצוה את בניו עלי לשמור דרכי. ואם תפרשהו כתרגומו יודע אני בו שיצוה את בניו וגו' , אין למען נופל על הלשון: **יצוה.** לשון הוה, כמו (איוב א ה) ככה יעשה איוב: **למען הביא.** כך הוא מצוה לבניו שמרו דרך ה' כדי שיביא ה' על אברהם וגו' . על בית אברהם לא נאמר, אלא על אברהם, למדנו כל המעמיד בן צדיק כאלו אינו מת:
@445 **ויאמר ה'.** אל אברהם, שעשה כאשר אמר שלא יכסה ממנו: **כי רבה.** כל רבה שבמקרא הטעם למטה בבי''ת, לפי שהן מתורגמין גדולה, או גדלה והולכת, אבל זה טעמו למעלה ברי''ש, לפי שמתורגם גדלה כבר, כמו שפירשתי לעיל (טו יז) ויהי השמש באה, (רות א טו) הנה שבה יבמתך:
@446 **ארדה נא ואראה.** למד לדינים שלא יפסקו דיני נפשות אלא בראיה, הכל כמו שפרשתי בפרשת הפלגה (לעיל יא ז) . דבר אחר ארדה נא לסוף מעשיהם: **הכצעקתה.** של מדינה: **הבאה אלי עשו.** ואם עומדים במרדם כלה אני עושה בהם. ואם לא יעמדו במרדן, אדעה מה אעשה להפרע מהן ביסורין ולא אכלה אותן. וכיוצא בו מצינו במקום אחר (שמות לג ה) ועתה הורד עדיך מעליך ואדעה מה אעשה לך, ולפיכך יש הפסק נקדת פסק בין עשו לכלה, כדי להפריד תיבה מחברתה. ורבותינו דרשו הכצעקתה, צעקת ריבה אחת שהרגוה מיתה משנה על שנתנה מזון לעני, כמפורש בחלק (סנהדרין קט ב) :
@447 **ויפנו משם.** ממקום שאברהם לום שם: **ואברהם עודנו עומד לפני ה'.** והלא לא הלך לעמוד לפניו אלא הקדוש ברוך הוא בא אצלו ואמר לו (פסוק כ) זעקת סדום ועמורה כי רבה, והיה לו לכתוב וה' עודנו עומד לפני אברהם, אלא תקון סופרים הוא זה (אשר הפכוהו זכרונם לברכה לכתוב כן) :
@448 **ויגש אברהם.** מצינו הגשה למלחמה (ש''ב י יג) ויגש יואב וגו' , הגשה לפיוס (להלן מד יח) ויגש אליו יהודה, והגשה לתפלה (מלכים א' יח לו) ויגש אליהו הנביא, ולכל אלה נכנס אברהם, לדבר קשות, ולפיוס ולתפלה: **האף תספה.** הגם תספה. ולתרגום של אנקלוס שתרגמו לשון רוגז, כך פרושו האף ישיאך שתספה צדיק עם רשע:
@449 **אולי יש חמשים צדיקים.** עשרה צדיקים לכל כרך וכרך, כי חמשה מקומות יש:
@450 **חלילה לך.** ואם תאמר לא יצילו הצדיקים את הרשעים, למה תמית הצדיקים: **חלילה לך.** חלין הוא לך, יאמרו כך הוא אמנתו, שוטף הכל, צדיקים ורשעים, כך עשית לדור המבול ולדור הפלגה: **כדבר הזה.** לא הוא ולא כיוצא בו: **חלילה לך.** לעולם הבא: **השופט כל הארץ.** נקוד בחטף פת''ח ה''א של השופט לשון תמה, וכי מי שהוא שופט לא יעשה משפט אמת:
@451 **אם אמצא בסדום** וגו' **לכל המקום.** לכל הכרכים, לפי שסדום היתה מטרופולין וחשובה מכלם תלה בה הכתוב:
@452 **ואנכי עפר ואפר.** וכבר הייתי ראוי להיות עפר על ידי המלכים, ואפר על ידי נמרוד, לולי רחמיך אשר עמדו לי:
@453 **התשחית בחמשה.** והלא הן תשעה לכל כרך, ואתה צדיקו של עולם תצטרף עמהם:
@454 **אולי ימצאון שם ארבעים.** וימלטו ארבעה הכרכים, וכן שלשים יצילו שלשה מהם או עשרים יצילו שנים מהם או עשרה יצילו אחד מהם:
@456 **הואלתי.** רציתי כמו (שמות ב כא) ויואל משה:
@457 **אולי ימצאון שם עשרה.** על פחות לא בקש. אמר, דור המבול היו שמונה, נח ובניו ונשיהם ולא הצילו על דורם, ועל תשעה על ידי צרוף כבר בקש ולא מצא:
@458 **וילך ה'** וגו' **.** כיון שנשתתק הסניגור הלך לו הדין: **ואברהם שב למקומו.** נסתלק הדין נסתלק הסניגור והקטיגור מקטרג, ולפיכך (יט א) ויבאו שני המלאכים סדומה [בערב] להשחית. אחד להשחית את סדום ואחד להציל את לוט, והוא אותו שבא לרפאות את אברהם. והשלישי שבא לבשר את שרה, כיון שעשה שליחותו נסתלק לו:
@459 **המלאכים.** ולהלן קראם אנשים, כשהיתה שכינה עמהם קראם אנשים. דבר אחר אצל אברהם שכחו גדול והיו המלאכים תדירין אצלו כאנשים קראם אנשים, ואצל לוט קראם מלאכים: **בערב.** וכי כל כך שהו המלאכים מחברון לסדום, אלא מלאכי רחמים היו, וממתינים שמא יוכל אברהם ללמד עליהם סניגוריא: **ולוט ישב בשער סדום.** ישב כתיב, אותו היום מנוהו שופט עליהם: **וירא לוט** וגו' **.** מבית אברהם למד לחזר על האורחים:
@460 **הנה נא אדני.** הנה נא אתם אדונים לי אחר שעברתם עלי. דבר אחר הנה נא צריכים אתם לתת לב על הרשעים הללו שלא יכירו בכם. וזו היא עצה נכונה: **סורו נא.** עקמו את הדרך לביתי דרך עקלתון, שלא יכירו שאתם נכנסין שם לכך נאמר סורו (בב''ר נ ז) : **ולינו ורחצו רגליכם.** וכי דרכן של בני אדם ללון תחלה ואחר כך לרחוץ, ועוד שהרי אברהם אמר להם תחלה (יח ד) ורחצו רגליכם. אלא כך אמר לוט אם כשיבאו אנשי סדום ויראו שכבר רחצו רגליהם, יעלילו עלי ויאמרו כבר עברו שני ימים או שלשה שבאו לביתך ולא הודעתנו, לפיכך אמר מוטב שיתעכבו כאן באבק רגליהם שיהיו נראין כמו שבאו עכשיו, לפיכך אמר לינו תחלה ואחר כך רחצו: **ויאמרו לא.** לאברהם אמרו (יח ה) כן תעשה, מכאן שמסרבין לקטן ואין מסרבין לגדול **כי ברחוב נלין.** הרי כי משמש בלשון אלא, שאמרו לא נסור אל ביתך אלא ברחובה של עיר נלין:
@461 **ויסרו אליו.** עקמו את הדרך לצד ביתו: **ומצות אפה.** פסח היה:
@462 **טרם ישכבו ואנשי העיר אנשי סדום.** כך נדרש בבראשית רבה (נ ה) טרם ישכבו ואנשי העיר היו בפיהם של מלאכים, שהיו שואלים ללוט מה טיבם ומעשיהם, והוא אומר להם רבם רשעים. עודם מדברים בהם ואנשי סדום וגו' . ופשוטו של מקרא ואנשי העיר, אנשי רשע, נסבו על הבית. על שהיו רשעים נקראים אנשי סדום, כמו שאמר הכתוב (יג יג) ואנשי סדום רעים וחטאים: **כל העם מקצה.** מקצה העיר עד הקצה, שאין אחד מהם מוחה בידם, שאפלו צדיק אחד אין בהם:
@463 **ונדעה אתם.** במשכב זכר, כמו (פס' ח) אשר לא ידעו איש:
@466 **האל.** כמו האלה: **כי על כן באו.** כי הטובה הזאת תעשו לכבודי על אשר באו בצל קורתי, תרגום בטלל שרותי, תרגום של קורה שרותא:
@467 **ויאמרו גש הלאה.** קרב להלאה, כלומר התקרב לצדדין והתרחק ממנו, וכן כל הלאה שבמקרא לשון רחוק, כמו (במדבר יז ב) זרה הלאה, (ש''א כ כב) הנה החצים ממך והלאה. גש הלאה המשך להלן, בלשון לע''ז טרי''י טי''י ד''י נו''ש [משוך את עצמך ממנו], ודבר נזיפה הוא לומר אין אנו חוששין לך, ודומה לו (ישעיה סה ה) קרב אליך אל תגש בי, וכן (ישעיה מט כ) גשה לי ואשבה, המשך לצדדין בעבורי ואשב אצלך. אתה מליץ על האורחין, איך מלאך לבך. על שאמר להם על הבנות, אמרו לו גש הלאה, לשון נחת, ועל שהיה מליץ על האורחים אמרו האחד בא לגור, אדם נכרי יחידי אתה בינינו שבאת לגור, וישפוט שפוט ונעשית מוכיח אותנו: **הדלת.** דלת הסובבת לנעול ולפתוח:
@469 **פתח.** הוא החלל שבו נכנסין ויוצאין: **בסנורים.** מכת עורון: **מקטן ועד גדול.** הקטנים התחילו בעברה תחלה, שנאמר (פסוק ד) מנער ועד זקן, לפיכך התחילה הפרענות מהם:
@470 **עוד מי לך פה.** פשוטו של מקרא מי לך עוד בעיר הזאת חוץ מאשתך ובנותיך שבבית: **חתן ובניך ובנותיך.** אם יש לך חתן או בנים ובנות הוצא מן המקום: **ובניך.** בני בנותיך הנשואות. ומדרש אגדה עוד מאחר שעושין נבלה כזאת מי לך פתחון פה ללמד סניגוריא עליהם, שכל הלילה היה מליץ עליהם טובות, קרי ביה מי לך פה:
@472 **חתניו.** שתי בנות נשואות היו לו בעיר: **לוקחי בנותיו.** שאותן שבבית היו ארוסות להם:
@473 **ויאיצו.** כתרגומו ודחיקו, מהרוהו: **הנמצאות.** המזמנות לך בבית להצילם. ומדרש אגדה יש, וזה ישובו של מקרא: **תספה.** תהיה כלה. (דברים ב יד) עד תם כל הדור, מתרגם עד דסף כל דרא:
@474 **ויתמהמה.** כדי להציל את ממונו: **ויחזיקו.** אחד מהם היה שליח להצילו, וחברו להפוך את סדום, לכך נאמר (פסוק יז) ויאמר המלט, ולא נאמר ויאמרו:
@475 **המלט על נפשך.** דיך להציל נפשות, אל תחוס על הממון: **אל תביט אחריך.** אתה הרשעת עמהם, ובזכות אברהם אתה נצול, אינך כדאי לראות בפרענותם ואתה נצול: **בכל הככר.** ככר הירדן: **ההרה המלט.** אצל אברהם ברח, שהוא יושב בהר, שנאמר לעיל (יב ח) ויעתק משם ההרה. ואף עכשיו היה יושב שם, שנאמר (יג ג) אל המקום אשר היה שם אהלה בתחלה, ואף על פי שכתוב (שם יח) ויאהל אברם וגו' , אהלים הרבה היו לו ונמשכו עד חברון: **המלט.** לשון השמטה, וכן כל המלטה שבמקרא אישמוציי''ר [להנצל] בלע''ז וכן (ישעיה סו ז) והמליטה זכר, שנשמט העבר מן הרחם, (תהלים קכד ז) כצפור נמלטה, (ישעיה מו ב) לא יכלו מלט משא, להשמיט משא הרעי שבנקביהם:
@476 **אל נא אדני.** רבותינו אמרו שם זה קדש, שנאמר בו להחיות את נפשי, מי שיש בידו להמית ולהחיות. ותרגומו בבעו כען ה': **אל נא.** אל נא תאמר אלי להמלט ההרה: **נא.** לשון בקשה יט **פן תדבקני הרעה.** כשהייתי אצל אנשי סדום היה הקדוש ברוך הוא רואה מעשי ומעשי בני העיר, והייתי נראה צדיק וכדאי להנצל, וכשאבא אצל צדיק אני כרשע. וכן אמרה הצרפית לאליהו (מ''א יז יח) כי באת אלי להזכיר את עוני, עד שלא באת אצלי היה הקדוש ברוך הוא רואה מעשי ומעשי עמי ואני צדקת ביניהם, ומשבאת אצלי לפי מעשיך אני רשעה:
@478 **העיר הזאת קרובה.** קרובה ישיבתה נתישבה מקרוב, לפיכך לא נתמלאה סאתה עדיין. ומה היא קריבתה, מדור הפלגה שנתפלגו האנשים והתחילו להתישב איש איש במקומו, והיא היתה בשנת מות פלג, ומשם ועד כאן חמשים ושתים שנה, שפלג מת בשנת ארבעים ושמונה לאברהם. כיצד, פלג חי (לעיל יא יט) אחרי הולידו את רעו מאתים ותשע שנה, צא מהם שלשים ושתים כשנלד שרוג, ומשרוג עד שנלד נחור שלשים, הרי ששים ושתים, ומנחור עד שנלד תרח עשרים ותשע, הרי תשעים ואחת, ומשם עד שנלד אברהם שבעים, הרי מאה ששים ואחת, תן להם ארבעים ושמונה הרי מאתים ותשע, ואותה שנה היתה שנת הפלגה, וכשנחרבה סדום היה אברהם בן תשעים ותשע שנה, הרי מדור הפלגה עד כאן חמשים ושתים שנה, וצוער אחרה ישיבתה אחרי ישיבת סדום וחברותיה שנה אחת, הוא שנאמר אמלטה נא, נא בגימטריא חמשים ואחת: **הלא מצער היא.** והלא עונותיה מועטין, ויכול אתה להניחה: **ותחי נפשי.** בה, זה מדרשו. ופשוטו של מקרא הלא עיר קטנה היא, ואנשים בה מעט, אין לך להקפיד אם תניחנה ותחי נפשי בה:
@479 **גם לדבר הזה.** לא דיך שאתה נצול, אלא אף כל העיר אציל בגללך: **הפכי.** הופך אני, כמו (מח ה) עד בואי, (טז יג) אחרי רואי, (ירמיה לא יט) מדי דברי בו:
@480 **כי לא אוכל לעשות.** זהו ענשן של מלאכים, על שאמרו (פסוק יג) כי משחיתים אנחנו, ותלו הדבר בעצמן, לפיכך לא זזו משם עד שהזקקו לומר שאין הדבר ברשותן: **כי לא אוכל.** לשון יחיד, מכאן אתה למד שהאחד הופך והאחד מציל, שאין שני מלאכים נשלחים לדבר אחד: **על כן קרא שם העיר צוער.** על שם (פסוק כ) והיא מצער:
@482 **וה' המטיר.** כל מקום שנאמר וה' הוא ובית דינו: **המטיר על סדום.** בעלות השחר, כמו שנאמר לעיל (פסוק טו) וכמו השחר עלה, שעה שהלבנה עומדת ברקיע עם החמה, לפי שהיו מהם עובדין לחמה ומהם ללבנה, אמר הקדוש ברוך הוא אם אפרע מהם ביום יהיו עובדי לבנה אומרים אלו היה בלילה כשהלבנה מושלת לא היינו חרבין, ואם אפרע מהם בלילה יהיו עובדי החמה אומרים אלו היה ביום כשהחמה מושלת לא היינו חרבים, לכך כתיב וכמו השחר עלה ונפרע מהם בשעה שהחמה והלבנה מושלים: **המטיר** וגו' **גפרית ואש.** בתחלה מטר ונעשה גפרית ואש: **מאת ה'.** דרך המקראות לדבר כן, כמו (ד כג) נשי למך, ולא אמר נשי. וכן אמר דוד (מ''א א לג) קחו עמכם את עבדי אדוניכם, ולא אמר עבדי, וכן אחשורוש אמר (אסתר ח ח) בשם המלך, ולא אמר בשמי. אף כאן אמר מאת ה' ולא אמר מאתו: **מן השמים.** והוא שאמר הכתוב (איוב לו לא) כי בם ידין עמים וגו' , כשבא ליסר הבריות מביא עליהם אש מן השמים כמו שעשה לסדום, וכשבא להוריד המן מן השמים לישראל (שמות טז ד) הנני ממטיר לכם לחם מן השמים:
@483 **ויהפוך את הערים** וגו' **.** ארבעתן יושבות בסלע אחד והפכן מלמעלה למטה, שנאמר (איוב כח ט) בחלמיש שלח ידו וגו' :
@484 **ותבט אשתו מאחריו.** מאחריו של לוט: **ותהי נציב מלח.** במלח חטאה ובמלח לקתה. אמר לה תני מעט מלח לאורחים הללו, אמרה לו אף המנהג הרע הזה אתה בא להנהיג במקום הזה:
@486 **קיטור.** תמור של עשן טורק''א [לפיד] בלע''ז : **כבשן.** חפירה ששורפין בה את האבנים לסיד, וכן כל כבשן שבתורה:
@487 **ויזכור אלהים את אברהם.** מהו זכירתו של אברהם על לוט, נזכר שהיה לוט יודע ששרה אשתו של אברהם, ושמע שאמר אברהם במצרים על שרה (יב יט) אחותי היא, ולא גלה הדבר, שהיה חס עליו, לפיכך חס הקדוש ברוך הוא עליו:
@488 **כי ירא לשבת בצוער.** לפי שהיתה קרובה לסדום:
@489 **אבינו זקן.** ואם לא עכשיו אימתי, שמא ימות או יפסוק מלהוליד: **ואיש אין בארץ.** סבורות היו שכל העולם נחרב כמו בדור המבול:
@491 **ותשקין** וגו' **.** יין נזדמן להן במערה להוציא מהן שני אמות: **ותשכב את אביה.** ובצעירה כתיב (פסוק לה) ותשכב עמו, צעירה לפי שלא פתחה בזנות אלא אחותה למדתה, חסך עליה הכתוב ולא פירש גנותה. אבל בכירה שפתחה בזנות פרסמה הכתוב במפורש: **ובקומה.** של בכירה נקוד, לומר הרי הוא כאלו לא נכתב, לומר שבקומה ידע ואף על פי כן לא נשמר ליל שני מלשתות (אמר רבי לוי כל מי שהוא להוט אחר בלמוס של עריות לסוף מאכילים אותו מבשרו) :
@494 **ותהרין** וגו' **.** אף על פי שאין האשה מתעברת מביאה ראשונה, אלו שלטו בעצמן והוציאו ערותן לחוץ ונתעברו מביאה ראשונה:
@495 **מואב.** זו שלא היתה צנועה פרשה שמאביה הוא, אבל צעירה קראתו בלשון נקיה, וקבלה שכר בימי משה, שנאמר בבני עמון (דבר' ב יט) אל תתגר בם כלל, ובמואב לא הזהיר אלא שלא ילחם בם, אבל לצערן התיר לו:
@497 **ויסע משם אברהם.** כשראה שחרבו הכרכים ופסקו העוברים והשבים נסע לו משם. דבר אחר להתרחק מלוט שיצא עליו שם רע שבא על בנותיו:
@498 **ויאמר אברהם.** כאן לא נטל רשות אלא על כרחה שלא בטובתה לפי שכבר לקחה לבית פרעה על ידי כן: **אל שרה אשתו.** על שרה אשתו. וכיוצא בו (ש''א ד יט) אל הלקח ארון וגו' ואל מות חמיה, שניהם בלשון על:
@500 **לא קרב אליה.** המלאך מנעו, כמו שנאמר (פסוק ו) לא נתתיך לנגע אליה: **הגוי גם צדיק תהרג.** אף אם הוא צדיק תהרגנו. שמא כך דרכך לאבד האמות חנם, כך עשית לדור המבול ולדור הפלגה, אף אני אומר שהרגתם על לא דבר, כשם שאתה אומר להרגני:
@501 **גם הוא.** לרבות עבדים וגמלים וחמרים שלה, את כלם שאלתי ואמרו לי אחיה הוא: **בתם לבבי.** שלא דמיתי לחטוא: **ובנקיון כפי.** נקי אני מן החטא שלא נגעתי בה:
@502 **ידעתי כי בתם לבבך** וגו' **.** אמת שלא דמית מתחלה לחטוא אבל נקיון כפים אין כאן: **לא נתתיך.** לא ממך היה שלא נגעת בה אלא חשכתי אני אותך מחטוא, ולא נתתי לך כח, וכן (לקמן לא ז) ולא נתנו אלהים, וכן (שופט' טו א) ולא נתנו אביה לבוא:
@503 **השב אשת האיש.** ואל תהא סבור שמא תתגנה בעיניו ולא יקבלנה או ישנאך ולא יתפלל עליך: **כי נביא הוא.** ויודע שלא נגעת בה, לפיכך ויתפלל בעדך:
@505 **מעשים אשר לא יעשו.** מכה אשר לא הרגלה לבא על בריה באה לנו על ידך, עצירת כל נקבים, של זרע ושל קטנים ורעי ואזנים וחוטם:
@507 **רק אין יראת אלהים.** אכסנאי שבא לעיר, על עסקי אכילה ושתיה שואלין אותו או על עסקי אשתו שואלין אותו אשתך היא או אחותך היא:
@508 **אחותי בת אבי היא.** ובת אב מתרת לבן נח, שאין אבות לגוי. וכדי לאמת דבריו השיבם כן. ואם תאמר והלא בת אחיו היתה, בני בנים הרי הן כבנים והרי היא בתו של תרח, וכן הוא אומר ללוט (יג ח) כי אנשים אחים אנחנו: **אך לא בת אמי.** הרן מאם אחרת היה:
@509 **ויהי כאשר התעו אותי** וגו' **.** אנקלוס תרגם מה שתרגם. ויש לישבו עוד, דבר דבור על אפניו, כשהוציאני הקדוש ברוך הוא מבית אבי להיות משוטט ונד ממקום למקום, וידעתי שאעבור במקום רשעים ואומר לה זה חסדך אשר תעשי עמדי: **כאשר התעו.** לשון רבים, ואל תתמה, כי בהרבה מקומות לשון אלהות ולשון מרות קרוי לשון רבים. (שמואל ב' ז כג) אשר הלכו אלהים, (דברים ה כג) אלהים חיים, (יהושע כד יט) אלהים קדושים הוא, וכל לשון אלהים לשון רבים. וכן (לט כ) ויקח אדוני יוסף, (דברים י יז) אדוני האדונים, (להלן מב לג) אדוני הארץ, וכן (שמות כב יד) בעליו עמו, (שםכא כט) והועד בבעליו. ואם תאמר מהו לשון התעו, כל הגולה ממקומו ואינו מישב קרוי תועה, כמו (לקמן כא יד) ותלך ותתע, (תהלים קיט קעו) תעיתי כשה אובד, (איוב לח מא) יתעו לבלי אכל, יצאו ויתעו לבקש אכלם: **אמרי לי.** עלי, וכן (לקמן כו ז) וישאלו אנשי המקום לאשתו, על אשתו. וכן (שמות יד ג) ואמר פרעה לבני ישראל, כמו על בני ישראל, (שופטים ט נד) פן יאמרו לי אשה הרגתהו:
@510 **ויתן לאברהם.** כדי שיתפייס ויתפלל עליו:
@511 **הנה ארצי לפניך.** אבל פרעה אמר לו (לעיל יב יט) הנה אשתך קח ולך, לפי שנתירא שהמצריים שטופי זמה:
@512 **ולשרה אמר.** אבימלך, לכבודה כדי לפיסה הנה עשיתי לך כבוד זה, נתתי ממון לאחיך שאמרת עליו אחי הוא, הנה הממון והכבוד הזה לך כסות עינים: **לכל אשר אתך.** יכסו עיניהם שלא יקלוך, שאלו השיבותיך ריקנית יש להם לומר לאחר שנתעלל בה החזירה, עכשיו שהצרכתי לבזבז ממון ולפייסך, יודעים יהיו שעל כרחי השיבותיך ועל ידי נס: **ואת כל.** ועם כל באי העולם: **ונכחת.** יהא לך פתחון פה להתוכח ולהראות דברים נכרים הללו. ולשון תוכחת בכל מקום ברור דברים, ובלע''ז אישפרובי''ר [לבחן] ואונקלוס תרגם בפנים אחרים, ולשון המקרא כך הוא נופל על התרגום הנה הוא לך כסות של כבוד על העינים שלי ששלטו בך ובכל אשר אתך, ועל כן תרגומו וחזית יתיך וית כל דעמיך. ויש מדרש אגדה אבל ישוב לשון המקרא פרשתי:
@513 **וילדו.** כתרגומו ואתרוחו, נפתחו נקביהם והוציאו מה שצריך לצאת והיא לידה שלהם:
@514 **בעד כל רחם.** כנגד כל פתח: **על דבר שרה.** על פי דבורה של שרה:
@515 **וה' פקד את שרה** וגו' **.** סמך פרשה זו לכאן ללמדך שכל המבקש רחמים על חברו והוא צריך לאותו דבר הוא נענה תחלה, שנאמר (לעיל כ יז) ויתפלל וגו' וסמיך ליה וה' פקד את שרה שפקד כבר קודם שרפא את אבימלך: **פקד את שרה כאשר אמר.** בהריון: **כאשר דבר.** בלידה. והיכן היא אמירה והיכן הוא דבור, אמירה (לעיל יז יט) ויאמר אלהים אבל שרה אשתך וגו' . דבור (שם טו א) היה דבר ה' אל אברם, בברית בין הבתרים, ושם נאמר (שם ד) לא יירשך זה וגו' , והביא היורש משרה: **ויעש ה' לשרה כאשר דבר.** לאברהם:
@516 **למועד אשר דבר אתו.** דמליל יתיה. את המועד אשר דבר וקבע כשאמר לו (לעיל יח יד) למועד אשוב אליך, שרט לו שריטה בכותל ואמר לו, כשתגיע חמה לשריטה זו בשנה אחרת, תלד: ( **לזקניו.** שהיה זיו אקונין שלו דומה לו:) ו **יצחק לי.** ישמח עלי. ומדרש אגדה הרבה עקרות נפקדו עמה, הרבה חולים נתרפאו בו ביום, הרבה תפלות נענו עמה, ורב שחוק היה בעולם:
@521 **מי מלל לאברהם.** לשון שבח וחשיבות, ראו מי הוא ומה הוא, שומר הבטחתו, הקדוש ברוך הוא מבטיח ועושה: **מלל.** שנה הכתוב ולא אמר דבר, גימטריה שלו מאה, כלומר לסוף מאה לאברהם: **היניקה בנים שרה.** ומהו בנים לשון רבים, ביום המשתה הביאו השרות את בניהן עמהן והיניקה אותם שהיו אומרות לא ילדה שרה אלא אסופי הביאה מן השוק:
@522 **ויגמל.** לסוף עשרים וארבעה חדש: **משתה גדול.** שהיו שם גדולי הדור, שם ועבר ואבימלך:
@523 **מצחק.** לשון עבודה זרה, כמו שנאמר (שמות לב ו) ויקומו לצחק. דבר אחר לשון גלוי עריות, כמה דתימא (להלן לט יז) לצחק בי. דבר אחר לשון רציחה כמו (ש''ב ב יד) יקומו נא הנערים וישחקו לפנינו וגו' :
@524 **עם בני** וגו' **.** מתשובת שרה כי לא יירש בן האמה הזאת עם בני אתה למד שהיה מריב עם יצחק על הירשה ואמר אני בכור ונוטל פי שנים, ויוצאים בשדה ונוטל קשתו ויורה בו חצים, כמה דתימא (משלי כו יח. יט) כמתלהלה היורה זקים וגו' ואמר הלא משחק אני: **עם בני עם יצחק.** מכיון שהוא בני אפלו אם אינו הגון כיצחק, או הגון כיצחק אפלו אם אינו בני, אין זה כדאי לירש עמו, קל וחמר עם בני עם יצחק ששתיהן בו:
@525 **על אודת בנו.** ששמע שיצא לתרבות רעה. ופשוטו על שאמרה לו לשלחו:
@526 **שמע בקולה.** למדנו שהיה אברהם טפל לשרה בנביאות:
@528 **לחם וחמת מים.** ולא כסף וזהב, לפי שהיה שונאו על שיצא לתרבות רעה: **ואת הילד.** אף הילד שם על שכמה, שהכניסה בו שרה עין רעה ואחזתו חמה ולא יכול לילך ברגליו: **ותלך ותתע.** חזרה לגלולי בית אביה:
@529 **ויכלו המים.** לפי שדרך חולים לשתות הרבה:
@530 **מנגד.** מרחוק: **כמטחוי קשת.** כשתי טיחות והוא לשון ירית חץ, בלשון משנה שהטיח באשתו, על שם שהזרע יורה כחץ. ואם תאמר היה לו לכתוב כמטחי קשת, משפט הוי''ו ליכנס לכאן, כמו (שה''ש ב) בחגוי הסלע, מגזרת (ישעיה יט יז) והיתה אדמת יהודה למצרים לחגא, ומגזרת (תהלים קז כז) יחגו וינועו כשכור, וכן (שם סה ו) קצוי ארץ, מגזרת קצה: **ותשב מנגד.** כיון שקרב למות הוסיפה להתרחק:
@531 **את קול הנער.** מכאן שיפה תפלת החולה מתפלת אחרים עליו, והיא קודמת להתקבל: **באשר הוא שם.** לפי מעשים שהוא עושה עכשיו הוא נדון ולא לפי מה שהוא עתיד לעשות, לפי שהיו מלאכי השרת מקטרגים ואומרים רבונו של עולם, מי שעתיד זרעו להמית בניך בצמא אתה מעלה לו באר. והוא משיבם עכשיו מה הוא, צדיק או רשע, אמרו לו צדיק, אמר להם לפי מעשיו של עכשיו אני דנו וזהו באשר הוא שם. והיכן המית את ישראל בצמא, כשהגלם נבוכדנצר, שנאמר (ישעיה כא יג. יד) משא בערב וגו' לקראת צמא התיו מים וגו' כשהיו מוליכין אותם אצל ערביים היו ישראל אומרים לשוביהם בבקשה מכם, הוליכונו אצל בני דודנו ישמעאל וירחמו עלינו, שנאמר (שם שם) ארחות דדנים [אל תקרי דדנים אלא דודים] ואלו יוצאים לקראתם ומביאין להם בשר ודג מלוח ונודות נפוחים, כסבורים ישראל שמלאים מים, וכשמכניסו לתוך פיו ופותחו, הרוח נכנס בגופו ומת:
@534 **רבה קשת.** יורה חצים בקשת: **קשת.** על שם האמנות כמו חמר, גמל, ציד לפיכך השי''ן מדגשת. היה יושב במדבר ומלסטם את העוברים, הוא שנאמר (לעיל טז יב) ידו בכל וגו' :
@535 **מארץ מצרים.** ממקום גדוליה, שנאמר (שם א) ולה שפחה מצרית וגו' . היינו דאמרי אנשי זרוק חוטרא לאוירא, אעיקריה קאי:
@536 **אלהים עמך.** לפי שראו שיצא משכונת סדום לשלום, ועם המלכים נלחם ונפלו בידו, ונפקדה אשתו לזקוניו:
@537 **ולניני ולנכדי.** עד כאן רחמי האב על הבן: **כחסד אשר עשיתי עמך תעשה עמדי.** שאמרתי לך (לעיל כ טו) הנה ארצי לפניך:
@539 **והוכח.** נתוכח עמו על כך:
@544 **בעבור תהיה לי.** זאת: **לעדה.** לשון עדות של נקבה, כמו (להלן לא נב) ועדה המצבה: **כי חפרתי את הבאר.** מריבים היו עליה רועי אבימלך ואומרים אנחנו חפרנוה, אמרו ביניהם כל מי שיתראה על הבאר ויעלו המים לקראתו שלו היא, ועלו לקראת אברהם:
@547 **אשל.** רב ושמואל, חד אמר פרדס להביא ממנו פרות לאורחים בסעודה, וחד אמר פנדק לאכסניא ובו כל מיני פרות. ומצינו לשון נטיעה באהלים, שנאמר (דניאל יא מה) ויטע אהלי אפדנו: **ויקרא שם** וגו' **.** על ידי אותו אשל נקרא שמו של הקדוש ברוך הוא אלוה לכל העולם. לאחר שאוכלים ושותים אומר להם ברכו למי שאכלתם משלו, סבורים אתם שמשלי אכלתם, משל מי שאמר והיה העולם אכלתם:
@548 **ימים רבים.** מרבים על של חברון, בחברון עשה עשרים וחמש שנה וכאן עשרים ושש. שהרי בן שבעים וחמש שנה היה בצאתו מחרן, אותה שנה (לעיל יג יח) ויבא וישב באלוני ממרא, שלא מצינו קודם לכן שנתישב אלא שם, שבכל מקומותיו היה כאורח חונה ונוסע והולך, שנאמר (שם יב ו) ויעבור אברם, (שם ח) ויעתק משם, (שם י) ויהי רעב בארץ, וירד אברם מצרימה, ובמצרים לא עשה אלא שלשה חדשים שהרי שלחו פרעה, מיד (שם יג ג) וילך למסעיו, עד (לעיל יג יח) ויבא וישב באלוני ממרא אשר בחברון, שם ישב עד שנהפכה סדום, מיד (שם כ א) ויסע משם אברהם מפני בושה של לוט ובא לארץ פלשתים, ובן תשעים ותשע שנה היה, שהרי בשלישי למילתו באו אצלו המלאכים, הרי עשרים וחמש שנה וכאן כתיב ימים רבים, מרבים על הראשונים, ולא בא הכתוב לסתום אלא לפרש, ואם היו מרבים עליהם שתי שנים או יותר היה מפרשם, ועל כרחך אינם יתרים יותר משנה הרי עשרים ושש שנה, מיד יצא משם וחזר לחברון, ואותה שנה קדמה לפני עקידתו של יצחק שתים עשרה שנים, כך שנויה בסדר עולם (פרק א) :
@549 **אחר הדברים האלה.** יש מרבותינו אומרים אחר דבריו של שטן, שהיה מקטרג ואומר מכל סעודה שעשה אברהם לא הקריב לפניך פר אחד או איל אחד, אמר לו כלום עשה אלא בשביל בנו, אלו הייתי אומר לו זבח אותו לפני לא היה מעכב. ויש אומרים אחר דבריו של ישמעאל שהיה מתפאר על יצחק שמל בן שלש עשרה שנה ולא מחה, אמר לו יצחק באבר אחד אתה מיראני, אלו אמר לי הקדוש ברוך הוא זבח עצמך לפני לא הייתי מעכב: **הנני.** כך היא עניתם של חסידים, לשון ענוה הוא ולשון זמון:
@550 **קח נא.** אין נא אלא לשון בקשה, אמר לו בבקשה ממך עמוד לי בזה הנסיון, שלא יאמרו הראשונות לא היה בהן ממש: **את בנך.** אמר לו שני בנים יש לי, אמר לו את יחידך, אמר לו זה יחיד לאמו וזה יחיד לאמו, אמר לו אשר אהבת, אמר לו שניהם אני אוהב, אמר לו את יצחק. ולמה לא גלה לו מתחלה, שלא לערבבו פתאום, ותזוח דעתו עליו ותטרף, וכדי לחבב עליו את המצוה ולתן לו שכר על כל דבור ודבור: **ארץ המוריה.** ירושלים, וכן בדברי הימים (ב' ג א) לבנות את בית ה' בירושלים בהר המוריה. ורבותינו פרשו על שם שמשם הוראה יוצאה לישראל. ואונקלוס תרגמו על שם עבודת הקטורת שיש בה מור נרד ושאר בשמים: **והעלהו.** לא אמר לו שחטהו, לפי שלא היה חפץ הקדוש ברוך הוא לשחטו אלא שיעלהו להר לעשותו עולה, ומשהעלהו אמר לו הורידהו: **אחד ההרים.** הקדוש ברוך הוא מתהא הצדיקים ואחר כך מגלה להם, וכל זה כדי להרבות שכרן, וכן (לעיל יב א) אל הארץ אשר אראך, וכן ביונה (ג ב) וקרא אליה את הקריאה:
@551 **וישכם.** נזדרז למצוה: **ויחבש.** הוא בעצמו ולא צוה לאחד מעבדיו, שהאהבה מקלקלת השורה: **את שני נעריו.** ישמעאל ואליעזר, שאין אדם חשוב רשאי לצאת לדרך בלא שני אנשים, שאם יצטרך האחד לנקביו ויתרחק יהיה השני עמו: **ויבקע.** תרגומו וצלח, כמו (ש''ב יט יח) וצלחו הירדן, לשון בקוע (י''ג בקוע) פינדר''א בלע''ז [לחטוב]:
@552 **ביום השלישי.** למה אחר מלהראותו מיד, כדי שלא יאמרו הממו וערבבו פתאום וטרד דעתו, ואלו היה לו שהות להמלך אל לבו לא היה עושה: **וירא את המקום.** ראה ענן קשור על ההר:
@553 **עד כה.** כלומר דרך מועט למקום אשר לפנינו. ומדרש אגדה אראה היכן הוא מה שאמר לי המקום (לעיל טו ה) כה יהיה זרעך: **ונשובה.** נתנבא שישובו שניהם:
@554 **המאכלת.** סכין, על שם שאוכלת את הבשר, כמה דתימא (דברים לב מב) וחרבי תאכל בשר, ושמכשרת בשר לאכילה. דבר אחר זאת נקראת מאכלת, על שם שישראל אוכלים מתן שכרה: **וילכו שניהם יחדו.** אברהם שהיה יודע שהולך לשחוט את בנו היה הולך ברצון ושמחה כיצחק שלא היה מרגיש בדבר:
@556 **יראה לו השה.** כלומר יראה ויבחר לו השה, ואם אין שה, לעולה בני. ואף על פי שהבין יצחק שהוא הולך לשחט, וילכו שניהם יחדו בלב שוה:
@557 **ויעקד.** ידיו ורגליו מאחוריו, הידים והרגלים ביחד היא עקידה, והוא לשון (להלן ל לט) עקדים, שהיו קרסליהם לבנים, מקום שעוקדין אותן בו היה נכר:
@559 **אברהם אברהם.** לשון חבה הוא שכופל את שמו:
@560 **אל תשלח.** לשחוט, אמר לו אם כן לחנם באתי לכאן, אעשה בו חבלה ואוציא ממנו מעט דם, אמר לו אל תעש לו מאומה, אל תעש בו מום: **כי עתה ידעתי.** אמר רבי אבא אמר לו אברהם אפרש לפניך את שיחתי, אתמול אמרת לי (לעיל כא יב) כי ביצחק יקרא לך זרע, וחזרת ואמרת (שם כב ב) קח נא את בנך, עכשיו אתה אומר לי אל תשלח ידך אל הנער. אמר לו הקדוש ברוך הוא (תהלים פט לה) לא אחלל בריתי ומוצא שפתי לא אשנה, כשאמרתי לך קח, מוצא שפתי לא אשנה, לא אמרתי לך שחטהו אלא העלהו, אסקתיה, אחתיה: **כי עתה ידעתי.** מעתה יש לי מה להשיב לשטן ולאומות התמהים מה היא חבתי אצלך, יש לי פתחון פה עכשיו שרואים כי ירא אלהים אתה:
@561 **והנה איל.** מוכן היה לכך מששת ימי בראשית: **אחר.** אחרי שאמר לו המלאך (לעיל פסוק יב) אל תשלח ידך, ראהו כשהוא נאחז, והוא שמתרגמינן וזקף אברהם עינוהי בתר אלין: **בסבך.** אילן: **בקרניו.** שהיה רץ אצל אברהם והשטן סובכו ומערבבו באילנות כדי לעכבו: **תחת בנו.** מאחר שכתוב ויעלהו לעולה, לא חסר המקרא כלום, מהו תחת בנו, על כל עבודה שעשה ממנו היה מתפלל ואומר יהי רצון שתהא זו כאלו היא עשויה בבני, כאלו בני שחוט, כאלו דמו זרוק, כאלו הוא מפשט, כאלו הוא נקטר ונעשה דשן:
@562 **ה' יראה.** פשוטו כתרגומו, ה' יבחר ויראה לו את המקום הזה להשרות בו שכינתו ולהקריב כאן קרבנות: **אשר יאמר היום.** שיאמרו לימי הדורות עליו בהר זה יראה הקדוש ברוך הוא לעמו: **היום.** הימים העתידין, כמו עד היום הזה שבכל המקרא, שכל הדורות הבאים הקוראים את המקרא הזה אומרים עד היום הזה על היום שעומדים בו. ומדרש אגדה ה' יראה עקידה זו לסלוח לישראל בכל שנה ולהצילם מן הפרענות, כדי שיאמר היום הזה בכל הדורות הבאים בהר ה' יראה, אפרו של יצחק צבור ועומד לכפרה:
@565 **ברך אברכך.** אחת לאב ואחת לבן: **והרבה ארבה.** אחת לאב ואחת לבן:
@567 **וישב אברהם בבאר שבע.** לא ישיבה ממש, שהרי בחברון היה יושב שתים עשרה שנים לפני עקידתו של יצחק, יצא מבאר שבע והלך לו לחברון, כמו שנאמר (לעיל כא לד) ויגר אברהם בארץ פלשתים ימים רבים, מרבים משל חברון הראשונים, והם עשרים ושש שנה כמו שפרשנו למעלה (כא לד) :
@568 **אחרי הדברים האלה ויגד** וגו' **.** בשובו מהר המוריה היה אברהם מהרהר ואומר אלו היה בני שחוט כבר היה הולך בלא בנים, היה לי להשיאו אשה מבנות ענר אשכול וממרא, בשרו הקדוש ברוך הוא שנלדה רבקה בת זוגו, וזהו אחרי הדברים האלה הרהורי דברים שהיו על ידי עקידה: **גם היא.** אף היא השותה משפחותיה למשפחות אברהם שתים עשרה, מה אברהם שנים עשר שבטים שיצאו מיעקב, שמונה בני הגבירות וארבעה בני שפחות, אף אלו שמונה בני גבירות וארבעה בני פלגש:
@571 **ובתואל ילד את רבקה.** כל היחוסין הללו לא נכתבו אלא בשביל פסוק זה:
@573 **ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים.** לכך נכתב שנה בכל כלל וכלל, לומר לך שכל אחד נדרש לעצמו, בת מאה כבת עשרים לחטא, מה בת עשרים לא חטאה, שהרי אינה בת ענשין, אף בת מאה בלא חטא, ובת עשרים כבת שבע ליופי: **שני חיי שרה.** כלן שוין לטובה:
@574 **בקרית ארבע.** על שם ארבע ענקים שהיו שם אחימן ששי ותלמי ואביהם. דבר אחר על שם ארבעה זוגות שנקברו שם איש ואשתו אדם וחוה, אברהם ושרה, יצחק ורבקה, יעקב ולאה: **ויבא אברהם.** מבאר שבע: **לספוד לשרה ולבכתה.** ונסמכה מיתת שרה לעקידת יצחק, לפי שעל ידי בשורת העקידה שנזדמן בנה לשחיטה וכמעט שלא נשחט, פרחה נשמתה ממנה ומתה:
@576 **גר ותושב אנכי עמכם.** גר מארץ אחרת ונתישבתי עמכם. ומדרש אגדה אם תרצו הריני גר, ואם לאו אהיה תושב ואטלנה מן הדין שאמר לי הקדוש ברוך הוא (לעיל יב ז) לזרעך אתן את הארץ הזאת: **אחזת קבר.** אחוזת קרקע לבית הקברות:
@578 **לא יכלה.** לא ימנע, כמו (תהלים מ יב) לא תכלא רחמיך, וכמו (לעיל ח ב) ויכלא הגשם:
@580 **נפשכם.** רצונכם: **ופגעו לי.** לשון בקשה, כמו (רות א טז) אל תפגעי בי:
@581 **המכפלה.** בית ועליה על גביו. דבר אחר שכפולה בזוגות: **בכסף מלא.** אשלם כל שויה, וכן דוד אמר לארונה (דברי הימים א' כא כד) בכסף מלא:
@582 **ועפרון ישב.** כתיב חסר, אותו היום מנוהו שוטר עליהם, מפני חשיבותו של אברהם שהיה צריך לו עלה לגדלה: **לכל באי שער עירו.** שכלן בטלו ממלאכתן ובאו לגמול חסד לשרה:
@583 **לא אדני.** לא תקנה אותה בדמים: **נתתי לך.** הרי הוא כמו שנתתיה לך:
@585 **אך אם אתה לו שמעני.** אתה אומר לי לשמוע לך ולקח בחנם, אני אי אפשי בכך, אך אם אתה לו שמעני הלואי ותשמעני: **נתתי.** דונא''י בלע''ז [נתתי] מוכן הוא אצלי והלואי נתתי לך כבר:
@587 **ביני ובינך.** בין שני אוהבים כמונו מה היא חשובה לכלום, אלא הנח את המכר ואת מתך קבור:
@588 **וישקל אברהם לעפרן.** חסר וי''ו, לפי שאמר הרבה ואפלו מעט לא עשה, שנטל ממנו שקלים גדולים שהן קנטרין, שנאמר (פסוק טז) עבר לסוחר, שמתקבלים בשקל בכל מקום ויש מקום ששקליהן גדולים שהן קנטרין, צינטינייר''ש [מטבעות של מאה] בלע''ז :
@589 **ויקם שדה עפרון.** תקומה היתה לה שיצאה מיד הדיוט ליד מלך. ופשוטו של מקרא ויקם השדה והמערה אשר בו וכל העץ לאברהם למקנה וגו':
@590 **בכל באי שער עירו.** בקרב כלם ובמעמד כלם הקנהו לו:
@593 **ברך את אברהם בכל.** בכל עולה בגימטריא בן, ומאחר שהיה לו בן היה צריך להשיאו אשה:
@594 **זקן ביתו.** לפי שהוא דבוק נקוד זקן: **תחת ירכי.** לפי שהנשבע צריך שיטול בידו חפץ של מצוה, כגון ספר תורה או תפלין, והמילה היתה מצוה ראשונה לו ובאה לו על ידי צער והיתה חביבה עליו ונטלה:
@599 **ה' אלהי השמים אשר לקחני מבית אבי.** ולא אמר ואלהי הארץ, ולמעלה אמר (פסוק ג) ואשביעך בה' אלהי השמים ואלהי הארץ. אמר לו עכשיו הוא אלהי השמים ואלהי הארץ, שהרגלתיו בפי הבריות, אבל כשלקחני מבית אבי היה אלהי השמים ולא אלהי הארץ, שלא היו באי עולם מכירים בו, ושמו לא היה רגיל בארץ: **מבית אבי.** מחרן: **ומארץ מולדתי.** מאור כשדים: **ואשר דבר לי.** לצרכי, כמו (מל''א ב ד) אשר דבר עלי, וכן כל לי ולו ולהם הסמוכים אצל דבור מפורשים בלשון על, ותרגום שלהם עלי עלוהי עליהון, שאין נופל אצל דבור לשון לי ולו ולהם, אלא אלי אליו אליהם ותרגום שלהם עמי עמיה עמהון, אבל אצל אמירה נופל לשון לי ולו ולהם: **ואשר נשבע לי.** בין הבתרים:
@600 **ונקית משבועתי** וגו' **.** וקח לו אשה מבנות ענר אשכול וממרא: **רק את בני** וגו' **.** רק, מעוט הוא. בני אינו חוזר, אבל יעקב בן בני, סופו לחזור:
@602 **מגמלי אדניו.** נכרין היו משאר גמלים, שהיו יוצאין זמומין מפני הגזל שלא ירעו בשדות אחרים: **וכל טוב אדניו בידו.** שטר מתנה כתב ליצחק על כל אשר לו, כדי שיקפצו לשלוח לו בתם: **ארם נהרים.** בין שתי נהרות יושבת:
@603 **ויברך הגמלים.** הרביצם:
@606 **אתה הכחת.** ראויה היא לו שתהא גומלת חסדים וכדאי לכנס בביתו של אברהם. ולשון הוכחת בררת, אפרוביש''ט בלע''ז : **ובה אדע.** לשון תחנה, הודע לי בה: **כי עשית חסד.** אם תהיה ממשפחתו והוגנת לו, אדע כי עשית חסד:
@608 **בתולה.** ממקום בתולים: **ואיש לא ידעה.** שלא כדרכה, לפי שבנות הגוים היו משמרות מקום בתוליהן ומפקירות עצמן ממקום אחר, העיד על זו שנקיה מכל:
@609 **וירץ העבד לקראתה.** לפי שראה שעלו המים לקראתה: **הגמיאיני נא.** לשון גמיעה, הומיי''ר בלע''ז :
@610 **ותרד כדה.** מעל שכמה:
@611 **עד אם כלו.** הרי אם משמש בלשון אשר, אם כלו, דיספקון, שזו היא גמר שתיתן כששתו די ספוקן:
@612 **ותער.** לשון נפיצה, והרבה יש בלשון משנה (עבודה זרה ה ז) המערה מכלי אל כלי, ובמקרא יש לו דומה (תהלים קמא ח) אל תער נפשי, (ישעיה נג יב) אשר הערה למות נפשו: **השקת.** אבן חלולה ששותים בה הגמלים:
@613 **משתאה.** לשון שאיה, כמו (ישעיה ו יא) שאו ערים, תשאה שממה: **משתאה.** משתומם ומתבהל על שראה דברו קרוב להצליח. אבל אינו יודע אם ממשפחת אברהם היא אם לאו. ואל תתמה בתי''ו של משתאה שאין לך תיבה שתחלת יסודה שי''ן ומדברת בלשון מתפעל שאין תי''ו מפרידה בין שתי אותיות של עיקר היסוד כגון משתאה מגזרת שאה, (ישעיה נט טו) משתולל מגזרת שולל, (שם נט טו) וישתומם מגזרת שממה, (מיכה ו טז) וישתמר חקות עמרי מגזרת וישמר, אף כאן משתאה מגזרת תשאה, וכשם שאתה מוצא לשון משומם באדם נבהל ונאלם ובעל מחשבות, כמו (איוב יח כ) על יומו נשמו אחרונים, (ירמיה ב יב) שמו שמים, (דניאל ד טז) אשתומם כשעה חדא, כך תפרש לשון שאיה באדם בהול ובעל מחשבות. ואונקלוס תרגם לשון שהיה וגוברא שהי, שוהא ועומד במקום אחד לראות ההצליח ה' דרכו. ואין לתרגם שתי, שהרי אינו לשון שתיה, שאין אל''ף נופלת בלשון שתיה: **משתאה לה.** משתומם עליה כמו (לעיל כ יג) אמרי לי אחי הוא, וכמו (לקמן כו ז) וישאלו אנשי המקום לאשתו:
@614 **בקע.** רמז לשקלי ישראל בקע לגלגלת: **ושני צמידים.** רמז לשני לוחות מצמדות: **עשרה זהב משקלם.** רמז לעשרת הדברות שבהן:
@615 **ויאמר בת מי את.** לאחר שנתן לה שאלה, לפי שהיה בטוח בזכותו של אברהם שהצליח הקדוש ברוך הוא דרכו: **ללין.** לינה אחת. לין שם דבר והיא אמרה ללון כמה לינות:
@616 **בת בתואל.** השיבתו על ראשון ראשון ועל אחרון אחרון:
@617 **מספוא.** כל מאכל הגמלים קרוי מספוא כגון תבן ושעורים:
@619 **בדרך.** דרך המימן, דרך הישר, באותו דרך שהייתי צריך. וכן כל בי''ת ולמ''ד וה''א המשמשים בראש התבה ונקודים בפת''ח מדברים בדבר הפשוט שנזכר כבר במקום אחר או שהוא מבורר וניכר באיזו הוא מדבר:
@620 **לבית אמה.** דרך הנשים היתה להיות להן בית לישב בו למלאכתן, ואין הבת מגדת אלא לאמה:
@621 **וירץ.** למה וירץ ועל מה רץ, ויהי כראות את הנזם, אמר עשיר הוא זה, ונתן עיניו בממון:
@622 **על הגמלים.** לשמרן, כמו (לעיל יח ח) והוא עומד עליהם, לשמשם:
@623 **פניתי הבית.** מעבודה זרה:
@624 **ויפתח.** התיר זמם שלהם, שהיה סותם את פיהם שלא ירעו בדרך בשדות אחרים:
@625 **עד אם דברתי.** הרי אם משמש בלשון אשר ובלשון כי, כמו (לקמן מט י) עד כי יבא שילה, וזה שאמרו חכמינו זכרונם לברכה כי משמש בארבע לשונות, והאחת אי, והוא אם:
@628 **ויתן לו את כל אשר לו.** שטר מתנה הראה להם:
@629 **לא תקח אשה לבני מבנות הכנעני.** אם לא תלך תחלה אל בית אבי ולא תאבה ללכת אחריך:
@631 **אלי לא תלך האשה.** אלי כתיב, בת היתה לו לאליעזר והיה מחזר למצוא עלה שיאמר לו אברהם לפנות אליו להשיאו בתו, אמר לו אברהם בני ברוך ואתה ארור, ואין ארור מדבק בברוך:
@634 **ואבא היום.** היום יצאתי והיום באתי, מכאן שקפצה לו הארץ. אמר רבי אחא יפה שיחתן של עבדי אבות לפני המקום מתורתן של בנים, שהרי פרשה של אליעזר כפולה בתורה, והרבה גופי תורה לא נתנו אלא ברמיזה:
@636 **גם אתה.** גם לרבות אנשים שעמו: **הכיח.** ברר והודיע, וכן כל הוכחה שבמקרא ברור דבר:
@637 **טרם אכלה.** טרם שאני מכלה, וכן כל לשון הוה פעמים שהוא מדבר בלשון עבר ויכול לכתוב כמו טרם כליתי, ופעמים שמדבר בלשון עתיד, כמו (איוב א ה) כי אמר איוב, הרי לשון עבר, (שם) ככה יעשה איוב הרי לשון עתיד. ופירוש שניהם לשון הווה, כי אומר היה איוב (שם) אולי חטאו בני וגו' והיה עושה כך:
@639 **ואשאל ואשים.** שנה הסדר, שהרי הוא תחלה נתן ואחר כך שאל, אלא שלא יתפשוהו בדבריו ויאמרו היאך נתת לה, ועדיין אינך יודע מי היא:
@641 **על ימין.** מבנות ישמעאל: **על שמאל.** מבנות לוט שהיה יושב לשמאלו של אברהם:
@642 **ויען לבן ובתואל.** רשע היה וקפץ להשיב לפני אביו: **לא נוכל דבר אליך.** למאן בדבר הזה, לא על ידי תשובת דבר רע ולא על ידי תשובת דבר הגון לפי שנכר שמה' יצא הדבר, לפי דבריך שזמנה לך:
@644 **וישתחו ארצה.** מכאן שמודים על בשורה טובה:
@645 **ומגדנות.** לשון מגדים, שהביא עמו מיני פירות של ארץ ישראל:
@646 **וילינו.** כל לינה שבמקרא לינת לילה אחד:
@647 **ויאמר אחיה ואמה.** ובתואל היכן היה, הוא היה רוצה לעכב ובא מלאך והמיתו: **ימים.** שנה, כמו (ויקרא כה כט) ימים תהיה גאלתו, שכך נותנין לבתולה זמן שנים עשר חדש לפרנס את עצמה בתכשיטים: **או עשור.** עשרה חדשים. ואם תאמר ימים ממש, אין דרך המבקשים לבקש דבר מועט ואם לא תרצה תן לנו מרבה מזה:
@649 **ונשאלה את פיה.** מכאן שאין משיאין את האשה אלא מדעתה:
@650 **ותאמר אלך.** מעצמי, ואף אם אינכם רוצים:
@652 **את היי לאלפי רבבה.** את וזרעך תקבלו אותה ברכה שנאמר לאברהם בהר המוריה (לעיל כב יז) הרבה ארבה את זרעך וגו' . יהי רצון שיהא אותו הזרע ממך ולא מאשה אחרת:
@654 **מבוא באר לחי ראי.** שהלך להביא הגר לאברהם אביו שישאנה: **יושב בארץ הנגב.** קרוב לאותו באר, שנאמר (לעיל כ א) ויסע משם אברהם ארצה הנגב וישב בין קדש ובין שור, ושם היה הבאר, שנאמר (שם טז יד) הנה בין קדש ובין ברד:
@655 **לשוח.** לשון תפלה, כמו (תהלים קב א) ישפוך שיחו:
@656 **ותרא את יצחק.** ראתה אותו הדור ותוהא מפניו: **ותפל.** השמיטה עצמה לארץ, כתרגומו ואתרכינת הטתה עצמה לארץ ולא הגיעה עד הקרקע, כמו (פסוק יד) הטי נא כדך, ארכיני, (ש''ב כב י) ויט שמים, וארכין, לשון מטה לארץ, ודומה לו (תהלים לז כד) כי יפל לא יוטל, כלומר אם יטה לארץ לא יגיע עד הקרקע:
@657 **ותתכס.** לשון ותתפעל, כמו ותקבר, ותשבר:
@658 **ויספר העבד.** גלה לו נסים שנעשו לו שקפצה לו הארץ ושנזדמנה לו רבקה בתפלתו:
@659 **האהלה שרה אמו.** ויביאה האהלה ונעשית דגמת שרה אמו, כלומר והרי היא שרה אמו, שכל זמן ששרה קימת היה נר דלוק מערב שבת לערב שבת, וברכה מצויה בעיסה, וענן קשור על האהל, ומשמתה פסקו, וכשבאת רבקה חזרו: **אחרי אמו.** דרך ארץ כל זמן שאמו של אדם קימת כרוך הוא אצלה, ומשמתה הוא מתנחם באשתו:
@660 **קטורה.** זו הגר, ונקראת קטורה על שם שנאים מעשיה כקטרת ושקשרה פתחה שלא נזדוגה לאדם מיום שפרשה מאברהם:
@662 **אשורם ולטושם.** שם ראשי אומות. ותרגום של אנקלוס אין לי לישבו על לשון המקרא. שפרש למשרין, לשון מחנה. ואם תאמר שאינו כן מפני האל''ף שאינה יסודית, הרי לנו תבות שאין בראשם אל''ף ונתוספה אל''ף בראשם, כמו (עמוס ז ז) חומת אנך, שהוא מן (שמואל ב' ד ד) נכה רגלים, וכמו (מלכים ב' ד ב) אסוך שמן שהוא מן (רות ג ג) ורחצת וסכת: **ולטושם.** הם בעלי אהלים המתפזרים אנה ואנה ונוסעים איש באהלי אפדנו, וכן הוא אומר (ש''א ל טז) והנה נטושים על פני כל הארץ, שכן למ''ד ונו''ן מתחלפות זו בזו:
@664 **ויתן אברהם** וגו' **.** אמר ר' נחמיה ברכה דיאתיקי, שאמר לו הקדוש ברוך הוא לאברהם (לעיל יב ב) והיה ברכה, הברכות מסורות בידך לברך את מי שתרצה, ואברהם מסרם ליצחק:
@665 **הפילגשים.** חסר כתיב, שלא היתה אלא פלגש אחת, היא הגר היא קטורה. נשים בכתבה, פילגשים בלא כתבה, כדאמרינן בסנהדרין (כא א) בנשים ופילגשים דדוד: **נתן אברהם מתנת.** פרשו רבותינו שם טמאה מסר להם. דבר אחר מה שנתן לו על אודות שרה ושאר מתנות שנתנו לו, הכל נתן להם שלא רצה להנות מהם:
@666 **מאת שנה ושבעים שנה וחמש שנים.** בן מאה כבן שבעים, ובן שבעים כבן חמש בלא חטא:
@668 **יצחק וישמעאל.** מכאן שעשה ישמעאל תשובה והוליך את יצחק לפניו, והיא שיבה טובה שנאמר באברהם:
@670 **ויהי אחרי מות אברהם ויברך** וגו' **.** נחמו תנחומי אבלים. דבר אחר אף על פי שמסר הקדוש ברוך הוא את הברכות לאברהם, נתיירא לברך את יצחק מפני שצפה את עשו יוצא ממנו, אמר יבא בעל הברכות ויברך את אשר ייטב בעיניו ובא הקדוש ברוך הוא וברכו:
@672 **בשמתם לתולדתם.** סדר לידתן זה אחר זה:
@675 **בחצריהם.** כרכים שאין להם חומה, ותרגומו בפצחיהון, שהם מפוצחים לשון פתיחה, כמו (תהלים צח ד) פצחו ורננו:
@676 **ואלה שני חיי ישמעאל** וגו' **.** אמר רבי חייא בר אבא למה נמנו שנותיו של ישמעאל, כדי ליחס בהם שנותיו של יעקב. מן שנותיו של ישמעאל למדנו ששמש יעקב בבית עבר ארבע עשרה שנה כשפרש מאביו קודם שבא אצל לבן, שהרי כשפרש יעקב מאביו מת ישמעאל, שנאמר (להלן כח ט) וילך עשו אל ישמעאל וגו' , כמו שמפורש בסוף מגלה נקראת (מגילה יז א) : **ויגוע.** לא נאמרה גויעה אלא בצדיקים:
@677 **נפל.** שכן, כמו (שופטים ז יב) מדין ועמלק וכל בני קדם נופלים בעמק. כאן הוא אומר לשון נפילה, ולהלן הוא אומר על פני כל אחיו ישכן (לעיל טז יב) , עד שלא מת אברהם ישכן, משמת אברהם נפל:
@678 **ואלה תולדות יצחק.** יעקב ועשו האמורים בפרשה: **אברהם הוליד את יצחק.** על ידי שכתב הכתוב יצחק בן אברהם הזקק לומר אברהם הוליד את יצחק, לפי שהיו ליצני הדור אומרים מאבימלך נתעברה שרה, שהרי כמה שנים שהתה עם אברהם ולא נתעברה המנו, מה עשה הקדוש ברוך הוא, צר קלסתר פניו של יצחק דומה לאברהם, והעידו הכל אברהם הוליד את יצחק, וזהו שכתב כאן יצחק בן אברהם היה, שהרי עדות יש שאברהם הוליד את יצחק:
@679 **בן ארבעים שנה.** שהרי כשבא אברהם מהר המוריה נתבשר שנלדה רבקה, ויצחק היה בן שלשים ושבע שנה, שהרי בו בפרק מתה שרה, ומשנלד יצחק עד העקידה שמתה שרה שלשים ושבע שנה, ובת תשעים היתה כשנלד יצחק, ובת מאה עשרים ושבע כשמתה, שנאמר (כג א) ויהיו חיי שרה וגו' , הרי ליצחק שלשים ושבע שנים ובו בפרק נלדה רבקה, המתין לה עד שתהא ראויה לביאה שלש שנים ונשאה: **בת בתואל מפדן ארם אחות לבן.** וכי עדיין לא נכתב שהיא בת בתואל ואחות לבן ומפדן ארם, אלא להגיד שבחה שהיתה בת רשע ואחות רשע ומקומה אנשי רשע, ולא למדה ממעשיהם: **מפדן ארם.** על שם ששני ארם היו, ארם נהרים וארם צובה, קורא אותו פדן, לשון (שמואל א' יא ז) צמד בקר, תרגום פדן תורין. ויש פותרין פדן ארם כמו (הושע יב יג) שדה ארם, שבלשון ישמעאל קורין לשדה פדן:
@680 **ויעתר.** הרבה והפציר בתפלה: **ויעתר לו.** נתפצר ונתפייס ונתפתה לו, ואומר אני כל לשון עתר לשון הפצרה ורבוי הוא וכן (יחזקאל ח יא) ועתר ענן הקטרת, מרבית עלית העשן, וכן (שם לה יג) והעתרתם עלי דבריכם, וכן (משלי כז ו) נעתרות נשיקות שונא, דומות למרבות והנם למשא. אינקריישימינ''ט בלע''ז : **לנכח אשתו.** זה עומד בזוית זו ומתפלל, וזו עומדת בזוית זו ומתפללת: **ויעתר לו.** לו ולא לה, שאין דומה תפלת צדיק בן צדיק לתפלת צדיק בן רשע לפיכך לו ולא לה:
@681 **ויתרוצצו.** על כרחך המקרא הזה אומר דרשני, שסתם מה היא רציצה זו וכתב אם כן למה זה אנכי. רבותינו דרשוהו לשון ריצה, כשהיתה עוברת על פתחי תורה של שם ועבר יעקב רץ ומפרכס לצאת, עוברת על פתחי עבודה זרה עשו מפרכס לצאת. דבר אחר מתרוצצים זה עם זה ומריבים בנחלת שני עולמות: **ותאמר אם כן.** גדול צער העבור: **למה זה אנכי.** מתאוה ומתפללת על הריון: **ותלך לדרש.** לבית מדרשו של שם: **לדרש את ה'.** שיגיד לה מה תהא בסופה:
@682 **ויאמר ה' לה.** על ידי שליח, לשם נאמר ברוח הקודש והוא אמר לה: **שני גוים בבטנך.** גיים כתיב, אלו אנטונינוס ורבי, שלא פסקו מעל שלחנם לא צנון ולא חזרת לא בימות החמה ולא בימות הגשמים: **ושני לאמים.** אין לאום אלא מלכות: **ממעיך יפרדו.** מן המעים הם נפרדים, זה לרשעו וזה לתמו: **מלאם יאמץ.** לא ישוו בגדולה, כשזה קם זה נופל, וכן הוא אומר (יחזקאל כו ב) אמלאה החרבה, לא נתמלאה צור אלא מחרבנה של ירושלים:
@683 **וימלאו ימיה.** אבל בתמר כתיב (להלן לח כז) ויהי בעת לדתה. שלא מלאו ימיה כי לשבעה חדשים ילדתם: **והנה תומם.** חסר, ובתמר תאומים מלא לפי ששניהם צדיקים, אבל כאן אחד צדיק ואחד רשע:
@684 **אדמוני.** סימן הוא שיהא שופך דמים: **כלו כאדרת שער.** מלא שער כטלית של צמר המלאה שער פלוקייד''א בלע''ז : **ויקראו שמו עשו.** הכל קראו לו כן, לפי שהיה נעשה ונגמר בשערו כבן שנים הרבה:
@685 **ואחרי כן יצא אחיו** וגו' **.** שמעתי מדרש אגדה הדורשו לפי פשוטו, בדין היה אוחז בו לעכבו, יעקב נצר מטפה ראשונה ועשו מן השניה, צא ולמד משפופרת שפיה קצרה, תן לה שתי אבנים זו תחת זו, הנכנסת ראשונה תצא אחרונה, והנכנסת אחרונה תצא ראשונה, נמצא עשו הנצר באחרונה יצא ראשון, ויעקב שנצר ראשונה יצא אחרון, ויעקב בא לעכבו שיהא ראשון ללידה כראשון ליצירה, ויפטור את רחמה, ויטול את הבכורה מן הדין: **בעקב עשו.** סימן שאין זה מספיק לגמור מלכותו עד שזה עומד ונוטלה המנו: **ויקרא שמו יעקב.** הקדוש ברוך הוא. דבר אחר אביו קרא לו יעקב על שם אחיזת העקב: **בן ששים שנה.** עשר שנים משנשאה עד שנעשית בת שלש עשרה שנה וראויה להריון ועשר שנים הללו צפה והמתין לה כמו שעשה אביו לשרה, כיון שלא נתעברה ידע שהיא עקרה והתפלל עליה. ושפחה לא רצה לשא, לפי שנתקדש בהר המוריה להיות עולה תמימה:
@686 **ויגדלו הנערים ויהי עשו.** כל זמן שהיו קטנים לא היו נכרים במעשיהם ואין אדם מדקדק בהם מה טיבם, כיון שנעשו בני שלש עשרה שנה זה פרש לבתי מדרשות וזה פרש לעבודה זרה: **ידע ציד.** לצוד ולרמות את אביו בפיו, ושואלו אבא היאך מעשרין את המלח ואת התבן, כסבור אביו שהוא מדקדק במצות: **איש שדה.** כמשמעו אדם בטל וצודה בקשתו חיות ועופות: **תם.** אינו בקי בכל אלה, אלא כלבו כן פיו. מי שאינו חריף לרמות קרוי תם: **ישב אהלים.** אהלו של שם ואהלו של עבר:
@687 **בפיו.** כתרגומו בפיו של יצחק. ומדרשו בפיו של עשו שהיה צד אותו ומרמהו בדבריו:
@688 **ויזד.** לשון בשול, כתרגומו: **והוא עיף.** ברציחה, כמה דתימא (ירמיה ד לא) כי עיפה נפשי להורגים:
@689 **הלעיטני.** אפתח פי ושפוך הרבה לתוכו, כמו ששנינו: אין אובסין את הגמל אבל מלעיטין אותו (שבת קנה:) : **מן האדם האדם.** עדשים אדמות, ואותו היום מת אברהם שלא יראה את עשו בן בנו יוצא לתרבות רעה, ואין זו שיבה טובה שהבטיחו הקדוש ברוך הוא, לפיכך קצר הקדוש ברוך הוא חמש שנים משנותיו, שיצחק חי מאה ושמונים שנה וזה מאה שבעים וחמש שנה, ובשל יעקב עדשים להברות את האבל. ולמה עדשים, שדומות לגלגל שהאבלות גלגל החוזר בעולם (ועוד מה עדשים אין להם פה כך האבל אין לו פה שאסור לדבר. לפיכך המנהג להברות את האבל בתחלת מאכלו ביצים שהם עגלים ואין להם פה, כך אבל אין לו פה כדאמרינן במועד קטן (כא ב) אבל כל שלשה ימים הראשונים אינו משיב שלום לכל אדם וכל שכן שאינו שואל בתחלה, משלשה ועד שבעה משיב ואינו שואל וכו' ) :
@690 **מכרה כיום.** כתרגומו, כיום דילהן, כיום שהוא ברור, כך מכור לי מכירה ברורה: **בכרתך.** לפי שהעבודה בבכורות, אמר יעקב אין רשע זה כדאי שיקריב להקדוש ברוך הוא:
@691 **הנה אנכי הולך למות.** (מתנודדת והולכת היא הבכורה שלא תהא כל עת העבודה בבכורות כי שבט לוי יטל אותה ועוד) אמר עשו מה טיבה של עבודה זו, אמר לו כמה אזהרות וענשין ומיתות תלוין בה, כאותה ששנינו אלו הן שבמיתה שתויי יין, ופרועי ראש. אמר אני הולך למות על ידה, אם כן מה חפץ לי בה:
@693 **ויבז עשו.** העיד הכתוב על רשעו שבזה עבודתו של מקום:
@695 **אל תרד מצרימה.** שהיה דעתו לרדת מצרימה כמו שירד אביו בימי הרעב, אמר לו אל תרד מצרימה שאתה עולה תמימה, ואין חוצה לארץ כדאי לך:
@696 **האל.** כמו האלה:
@697 **והתברכו בזרעך.** אדם אומר לבנו יהא זרעך כזרעו של יצחק, וכן בכל המקרא. וזה אב לכלן (להלן מח כ) בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה, ואף לענין הקללה מצינו כן (במדבר ה כז) והיתה האשה לאלה, שהמקלל שונאו אומר תהא כפלונית, וכן (ישעיה סה טו) והנחתם שמכם לשבועה לבחירי, שהנשבע אומר אהא כפלוני אם עשיתי כך וכך:
@698 **שמע אברהם בקלי.** כשנסיתי אותו: **וישמר משמרתי.** גזרות להרחקה על אזהרות שבתורה, כגון שניות לעריות ושבות לשבת: **מצותי.** דברים שאלו לא נכתבו ראויין הם להצטוות כגון גזל ושפיכות דמים: **חקותי.** דברים שיצר הרע ואמות העולם משיבין עליהן כגון אכילת חזיר ולבישת שעטנז שאין טעם בדבר אלא גזרת המלך וחקותיו על עבדיו: **ותורתי.** להביא תורה שבעל פה, הלכה למשה מסיני:
@700 **לאשתו.** על אשתו, כמו (לעיל כ יג) אמרי לי אחי הוא:
@701 **כי ארכו.** אמר מעתה אין לי לדאוג מאחר שלא אנסוה עד עכשיו, ולא נזהר להיות נשמר: **וישקף אבימלך** וגו' **.** שראהו משמש מטתו:
@703 **אחד העם.** המיחד בעם זה המלך: **והבאת עלינו אשם.** אם שכב, כבר הבאת עלינו אשם:
@705 **בארץ ההיא.** אף על פי שאינה חשובה כארץ ישראל עצמה, כארץ שבעה גוים: **בשנה ההיא.** אף על פי שאינה כתקנה, שהיתה שנת רעבון: **בארץ ההיא בשנה ההיא.** שניהם למה, לומר שהארץ קשה והשנה קשה: **מאה שערים.** שאמדוה כמה ראויה לעשות ועשתה על אחת מאה ממה שאמדוה. ורבותינו אמרו אומד זה למעשרות היה:
@706 **כי גדל מאד.** שהיו אומרים זבל פרדותיו של יצחק ולא כספו וזהבו של אבימלך:
@707 **ועבדה רבה.** פעלה רבה, בלשון לע''ז אובריינ''א [מכלול העבודות] עבודה משמע עבודה אחת, עבדה משמע פעלה רבה:
@708 **סתמום פלשתים.** מפני שאמרו תקלה הם לנו מפני הגיסות הבאות עלינו. טמונין פלשתאי לשון סתימה, ובלשון משנה (פסחים מב א) מטמטם את הלב:
@710 **בנחל גרר.** רחוק מן העיר:
@711 **וישב ויחפר.** הבארות אשר חפרו בימי אברהם אביו. ופלשתים סתמום, מקדם שנסע יצחק מגרר חזר וחפרן:
@713 **עשק.** ערעור: **כי התעשקו עמו.** נתעשקו עמו עליה במריבה וערעור:
@714 **שטנה.** נוישימונ''ט [נזק]:
@715 **ופרינו בארץ.** כתרגומו ונפוש בארעא:
@719 **ואחזת מרעהו.** כתרגומו וסיעת מרחמוהי, סיעת מאוהביו. ויש פותרין מרעהו מ' מיסוד התבה, כמו (שופטים יד יא) שלשים מרעים דשמשון, כדי שתהיה תבת ואחזת דבוקה, אבל אין דרך ארץ לדבר על המלכות כן סיעת אוהביו, שאם כן כל סיעת אוהביו הוליך עמו ולא היה לו אלא סיעה אחת של אוהבים, לכן יש לפתרו כלשון הראשון. ואל תתמה על תי''ו של ואחזת ואף על פי שאין התבה סמוכה, יש דגמתה במקרא (תהלים ס יג) עזרת מצר, (ישעיה נא כא) ושכורת ולא מיין: **אחזת.** לשון קבוצה ואגודה שנאחזין יחד:
@721 **ראו ראינו.** ראה באביך ראינו בך: **תהי נא אלה בינותינו** וגו' **.** האלה אשר בינותינו מימי אביך, תהי גם עתה בינינו וביניך:
@722 **לא נגענוך.** כשאמרנו (לעיל פסוק טז) לך מעמנו: **אתה.** גם אתה עשה עמנו כמו כן:
@726 **שבעה.** על שם הברית:
@727 **בן ארבעים שנה.** עשו היה נמשל לחזיר, שנאמר (תהלים פ יד) יכרסמנה חזיר מיער, החזיר הזה כשהוא שוכב פושט טלפיו לומר ראו שאני טהור, כך אלו [אלופי עשו] גוזלים וחומסים ומראים עצמם כשרים. כל ארבעים שנה היה עשו צד נשים מתחת בעליהן ומענה אותם, כשהיה בן ארבעים אמר אבא בן ארבעים שנה נשא אשה, אף אני כן:
@728 **מרת רוח.** לשון המראות רוח, כמו (דברים ט כד) ממרים הייתם כל מעשיהן היו לעצבון: **ליצחק ולרבקה.** שהיו עובדות עבודה זרה:
@729 **ותכהין.** בעשנן של אלו. דבר אחר כשנעקד על גבי המזבח והיה אביו רוצה לשחטו, באותה שעה נפתחו השמים וראו מלאכי השרת והיו בוכים וירדו דמעותיהם ונפלו על עיניו, לפיכך כהו עיניו. דבר אחר כדי שיטול יעקב את הברכות:
@730 **לא ידעתי יום מותי.** אמר רבי יהושע בן קרחה, אם מגיע אדם לפרק אבותיו ידאג חמש שנים לפניהם וחמש לאחר כן, ויצחק היה בן מאה עשרים ושלש, אמר שמא לפרק אמי אני מגיע, והיא מתה בת מאה עשרים ושבע והריני בן חמש שנים סמוך לפרקה, לפיכך לא ידעתי יום מותי, שמא לפרק אמי, שמא לפרק אבא:
@731 **תליך.** חרבך שדרך לתלותה: **שא נא.** לשון השחזה כאותה ששנינו (ביצה כח א) אין משחיזין את הסכין אבל משיאה על גבי חברתה, חדד סכינך ושחוט יפה, שלא תאכילני נבלה: **וצודה לי.** מן ההפקר ולא מן הגזל:
@733 **לצוד ציד להביא.** מהו להביא, אם לא ימצא ציד יביא מן הגזל:
@735 **לפני ה'.** ברשותו שיסכים על ידי:
@737 **וקח לי.** משלי הם ואינם גזל, שכך כתב לה יצחק בכתבתה לטול שני גדיי עזים בכל יום: **שני גדיי עזים.** וכי שני גדיי עזים היה מאכלו של יצחק, אלא האחד הקריב לפסחו והאחד עשה מטעמים. בפרקי דרבי אליעזר (פרק לב) : **כאשר אהב.** כי טעם הגדי כטעם הצבי:
@739 **איש שער.** בעל שער:
@740 **ימשני.** כמו (דברים כח כט) ממשש בצהרים:
@743 **החמודות.** הנקיות, כתרגומו דכייתא. דבר אחר שחמד אותן מן נמרוד: **אשר אתה בבית.** והלא כמה נשים היו לו והוא מפקיד אצל אמו, אלא שהיה בקי במעשיהן וחושדן:
@747 **אנכי עשו בכרך.** אנכי המביא לך, ועשו הוא בכרך: **עשיתי.** כמה דברים כאשר דברת אלי: **שבה.** לשון מיסב על השלחן, לכך מתורגם אסתחר:
@749 **גשה נא ואמשך.** אמר יצחק בלבו אין דרך עשו להיות שם שמים שגור בפיו, וזה אמר (פסוק כ) כי הקרה ה' אלהיך:
@750 **קול יעקב.** שמדבר בלשון תחנונים (פסוק יט) קום נא, אבל עשו בלשון קנטוריא דבר (פסוק לא) יקום אבי:
@752 **ויאמר אני.** לא אמר אני עשו אלא אני:
@755 **וירח** וגו' **.** והלא אין ריח רע יותר משטף העזים, אלא מלמד שנכנסה עמו ריח גן עדן: **כריח שדה אשר ברכו ה'.** שנתן בו ריח טוב, וזה שדה תפוחים, כן דרשו רבותינו זכרונם לברכה:
@756 **ויתן לך.** יתן ויחזור ויתן. ולפי פשוטו מוסב לענין הראשון ראה ריח בני, שנתן לו הקדוש ברוך הוא, כריח שדה וגו' ועוד יתן לך מטל השמים וגו' : **האלהים.** מהו האלהים, בדין, אם ראוי לך יתן לך, ואם לאו לא יתן לך, אבל לעשו אמר משמני הארץ יהיה מושבך, בין צדיק בין רשע יתן לך, וממנו למד שלמה כשעשה הבית וסדר תפלתו, ישראל שהוא בעל אמונה ומצדיק עליו את הדין לא יקרא עליך תגר, לפיכך, (מ''א ח לט) ונתת לאיש ככל דרכיו אשר תדע את לבבו, אבל נכרי מחסר אמנה, לפיכך אמר (שם שם מג) אתה תשמע השמים וגו' ועשית ככל אשר יקרא אליך הנכרי, בין ראוי בין שאינו ראוי תן לו, כדי שלא יקרא עליך תגר: **מטל השמים.** כמשמעו, ומדרש אגדה יש להרבה פנים:
@757 **בני אמך.** ויעקב אמר ליהודה (להלן מט ח) בני אביך, לפי שהיו לו בנים מכמה אמהות, וכאן שלא נשא אלא אשה אחת אמר בני אמך: **ארריך ארור ומברכיך ברוך.** ובבלעם הוא אומר (במדבר כד ט) מברכיך ברוך ואורריך ארור. הצדיקים תחלתם יסורים וסופן שלוה, ואורריהם ומצעריהם קודמים למברכיהם, לפיכך יצחק הקדים קללת אוררים לברכת מברכים. והרשעים תחלתן שלוה וסופן, יסורין לפיכך בלעם הקדים ברכה לקללה:
@758 **יצא יצא.** זה יוצא וזה בא:
@761 **ויחרד.** כתרגומו ותוה לשון תימה. ומדרשו ראה גיהנם פתוחה מתחתיו: **מי אפוא.** לשון לעצמו, משמש עם כמה דברים. איפוא, איה פה, מי הוא ואיפוא הוא הצד ציד: **ואכל מכל.** מכל טעמים שבקשתי לטעום טעמתי בו: **גם ברוך יהיה.** שלא תאמר אלולי שרמה יעקב לאביו לא נטל את הברכות, לכך הסכים וברכו מדעתו:
@763 **במרמה.** בחכמה:
@764 **הכי קרא שמו.** לשון תימה הוא, כמו (לקמן כט טו) הכי אחי אתה, שמא לכך נקרא שמו יעקב על שם סופו שהוא עתיד לעקבני. תנחומא (תנחומא ישן כג) למה חרד יצחק, אמר שמא עון יש בי שברכתי הקטן לפני הגדול, ושניתי סדר היחס. התחיל עשו מצעק ויעקבני זה פעמים, אמר לו אביו מה עשה לך, אמר לו את בכורתי לקח, אמר בכך הייתי מצר וחרד שמא עברתי על שורת הדין, עכשיו לבכור ברכתי, גם ברוך יהיה: **ויעקבני.** כתרגומו וכמני, ארבני. וארב, וכמן. ויש מתרגמין וחכמני נתחכם לי: **אצלת.** לשון הפרשה, כמו (במדבר יא כה) ויאצל:
@765 **הן גביר.** ברכה זו שביעית היא והוא עושה אותה ראשונה, אלא אמר לו מה תועלת לך בברכה, אם תקנה נכסים שלו הם, שהרי גביר שמתיו לך ומה שקנה עבד קנה רבו: **ולכה אפוא מה אעשה.** איה פה אבקש מה לעשות לך:
@766 **הברכה אחת.** ה''א זו משמשת לשון תימה, כמו (במדבר יג יט) הבמחנים, (במדבר יג כ) השמנה היא, (ש''ב ג לג) הכמות נבל:
@767 **משמני הארץ** וגו' **.** זו איטליה של יון:
@768 **ועל חרבך.** כמו בחרבך, יש על שהוא במקום אות ב', כמו (יחזקאל לג כו) עמדתם על חרבכם בחרבכם, (שמות ו כו) על צבאותם בצבאותם: **והיה כאשר תריד.** לשון צער, כמו (תהלים נה ג) אריד בשיחי, כלומר כשיעברו ישראל את התורה, ויהיה לך פתחון פה להצטער על הברכות שנטל, ופרקת עלו וגו' :
@769 **יקרבו ימי אבל אבי.** כמשמעו, שלא אצער את אבא. ומדרש אגדה לכמה פנים יש:
@770 **ויגד לרבקה.** ברוח הקודש הגד לה מה שעשו מהרהר בלבו: **מתנחם לך.** נחם על האחוה לחשוב מחשבה אחרת להתנכר לך ולהרגך. ומדרש אגדה כבר אתה מת בעיניו ושתה עליך כוס של תנחומים. ולפי פשוטו לשון תנחומים, מתנחם הוא על הברכות בהריגתך:
@772 **אחדים.** מועטים:
@773 **למה אשכל.** אהיה שכולה משניכם. הקובר את בניו קרוי שכול. וכן ביעקב אמר (להלן מג יד) כאשר שכלתי שכלתי: **גם שניכם.** אם יקום עליך ואתה תהרגנו יעמדו בניו ויהרגוך, ורוח הקדש נזרקה בה ונתנבאה שביום אחד ימותו, כמו שמפורש בפרק המקנא לאשתו (סוטה יג א) :
@774 **קצתי בחיי.** מאסתי בחיי:
@776 **פדנה.** כמו לפדן: **ביתה בתואל.** לבית בתואל. כל תבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה:
@777 **ואל שדי.** מי שדי בברכותיו למתברכין מפיו יברך אותך:
@778 **את ברכת אברהם.** שאמר לו (לעיל יב ב) ואעשך לגוי גדול, (שם כב יח) והתברכו בזרעך. יהיו אותן ברכות האמורות בשבילך, ממך יצא אותו הגוי ואותו הזרע המבורך:
@779 **אם יעקב ועשו.** איני יודע מה מלמדנו:
@781 **וישמע יעקב.** מחבר לענין של מעלה וירא עשו כי ברך יצחק וגו' וכי שלח אותו פדנה ארם, וכי שמע יעקב אל אביו והלך פדנה ארם וכי רעות בנות כנען, והלך גם הוא אל ישמעאל:
@783 **אחות נביות.** ממשמע שנאמר (לעיל כה יג) בת ישמעאל איני יודע שהיא אחות נביות, אלא למדנו שמת ישמעאל משיעדה לעשו קודם נשואיה והשיאה נביות אחיה. ולמדנו שהיה יעקב באותו הפרק בן ששים ושלש שנים, שהרי ישמעאל בן שבעים וארבע שנים היה כשנלד יעקב, ארבע עשרה שנה היה גדול ישמעאל מיצחק, ויצחק בן ששים שנה בלדת אותם הרי שבעים וארבע, ושנותיו היו מאה שלשים ושבע, שנאמר (שם יז) ואלה שני חיי ישמעאל וגו' , נמצא יעקב כשמת ישמעאל בן ששים ושלש שנים היה, ולמדנו מכאן שנטמן בבית עבר ארבע עשרה שנה ואחר כך הלך לחרן, שהרי לא שהה בבית לבן שלפני לידתו של יוסף אלא ארבע עשרה שנה, שנאמר (שם לא מא) עבדתיך ארבע עשרה שנה בשתי בנותיך ושש שנים בצאנך ושכר הצאן משנלד יוסף היה, שנאמר (שם ל כה) ויהי כאשר ילדה רחל את יוסף וגו' , ויוסף בן שלשים שנה היה כשמלך, ומשם עד שירד יעקב למצרים תשע שנים, שבע של שבע ושתים של רעב, ויעקב אמר לפרעה (שם מז ט) ימי שני מגורי שלשים ומאת שנה. צא וחשוב ארבע עשרה שלפני לידת יוסף, ושלשים של יוסף, ותשע משמלך עד שבא יעקב הרי חמשים ושלש, וכשפרש מאביו היה בן ששים ושלש הרי מאה ושש עשרה, והוא אומר שלשים ומאת שנה, הרי חסרים ארבע עשרה שנים הא למדת שאחר שקבל הברכות נטמן בבית עבר ארבע עשרה שנים. (אבל לא נענש עליהם בזכות התורה, שהרי לא פרש יוסף מאביו אלא עשרים ושתים שנה דהינו משבע עשרה עד שלשים ותשע כנגד עשרים ושתים שפרש יעקב מאביו ולא כבדו, והם עשרים שנים בבית לבן, ושתי שנים ששהה בדרך, כדכתיב (להלן לג יז) ויבן לו בית ולמקנהו עשה סכת, ופירשו רבותינו זכרונם לברכה מזה הפסוק ששהה שמונה עשר חדשים בדרך, דבית הוה בימות הגשמים וסכות הוו בימות החמה, ולחשבון הפסוקים שחשבנו לעיל משפרש מאביו עד שירד למצרים שהיה בן מאה שלשים שנים, שם אנו מוצאים עוד ארבע עשרה שנים, אלא ודאי נטמן בבית עבר בהליכתו לבית לבן ללמוד תורה ממנו, ובשביל זכות התורה לא נענש עליהם ולא פרש יוסף ממנו אלא עשרים ושתים שנה, מדה כנגד מדה) : **על נשיו.** הוסיף רשעה על, רשעתו שלא גרש את הראשונות:
@784 **ויצא יעקב.** על ידי שבשביל שרעות בנות כנען בעיני יצחק אביו הלך עשו אל ישמעאל, הפסיק הענין בפרשתו של יעקב וכתב (לעיל כח ו) וירא עשו כי ברך וגו' , ומשגמר חזר לענין הראשון: **ויצא יעקב מבאר שבע.** לא היה צריך לכתוב אלא וילך יעקב חרנה, ולמה הזכיר יציאתו, אלא מגיד שיציאת צדיק מן המקום עושה רושם, שבזמן שהצדיק בעיר הוא הודה הוא זיוה הוא הדרה, יצא משם פנה הודה פנה זיוה פנה הדרה וכן (רות א ז) ותצא מן המקום, האמור בנעמי ורות: **וילך חרנה.** יצא ללכת לחרן:
@785 **ויפגע במקום.** לא הזכיר הכתוב באיזה מקום אלא במקום הנזכר במקום אחר, הוא הר המוריה שנאמר בו (לעיל כב ד) וירא את המקום מרחוק: **ויפגע.** כמו (יהושע טז ז) ופגע ביריחו, (שם יט יא) ופגע בדבשת. ורבותינו פרשו לשון תפלה כמו (ירמיה ז טז) ואל תפגע בי, ולמדנו שתקן תפלת ערבית. ושנה הכתוב ולא כתב ויתפלל, ללמדך שקפצה לו הארץ, כמו שמפורש בפרק גיד הנשה (חלין צא ב) : **כי בא השמש.** היה לו לכתוב ויבא השמש. כי בא השמש, משמע ששקעה לו חמה פתאם שלא בעונתה כדי שילין שם: **וישם מראשותיו.** עשאן כמין מרזב סביב לראשו שהיה ירא מפני חיות רעות. התחילו מריבות זו עם זו, זאת אומרת עלי יניח צדיק את ראשו, וזאת אומרת עלי יניח, מיד עשאן הקדוש ברוך הוא אבן אחת, וזהו שנאמר (פסוק יח) ויקח את האבן אשר שם מראשותיו: **וישכב במקום ההוא.** לשון מעוט באותו מקום שכב, אבל ארבע עשרה שנים ששמש בבית עבר לא שכב בלילה, שהיה עוסק בתורה:
@786 **עולים ויורדים.** עולים תחלה ואחר כך יורדים, מלאכים שלווהו בארץ אין יוצאים חוצה לארץ ועלו לרקיע, וירדו מלאכי חוצה לארץ ללוותו:
@787 **נצב עליו.** לשמרו: **ואלהי יצחק.** אף על פי שלא מצינו במקרא שיחד הקדוש ברוך הוא שמו על הצדיקים בחייהם לכתוב אלהי פלוני, משום שנאמר (איוב טו טו) הן בקדושיו לא יאמין, כאן ייחד שמו על יצחק לפי שכהו עיניו וכלוא היה בבית, והרי הוא כמת, ויצר הרע פסק ממנו: **שכב עליה.** קפל הקדוש ברוך הוא כל ארץ ישראל תחתיו, רמז לו שתהא נחה לכבש לבניו:
@788 **ופרצת.** וחזקת, כמו (שמות א יב) וכן יפרוץ:
@789 **אנכי עמך.** לפי שהיה ירא מעשו ומלבן: **עד אשר אם עשיתי.** אם משמש בלשון כי: **דברתי לך.** לצרכך ועליך, מה שהבטחתי לאברהם על זרעו, לך הבטחתיו ולא לעשו, שלא אמרתי לו כי יצחק יקרא לך זרע, אלא כי ביצחק, ולא כל. יצחק וכן כל לי ולך ולו ולהם הסמוכים אצל דבור, משמשים לשון על, וזה, יוכיח שהרי עם יעקב לא דבר קדם לכן:
@790 **ואנכי לא ידעתי.** שאלו ידעתי לא ישנתי במקום קדוש כזה:
@791 **כי אם בית אלהים.** אמר רבי אלעזר בשם רבי יוסי בן זמרא הסלם הזה עומד בבאר שבע ואמצע שפועו מגיע כנגד בית המקדש, שבאר שבע עומד בדרומה של יהודה, וירושלים בצפונה בגבול שבין יהודה ובנימין, ובית אל היה בצפון של נחלת בנימין בגבול שבין בנימין ובין בני יוסף, נמצא סלם שרגליו בבאר שבע וראשו בבית אל מגיע אמצע שפועו נגד ירושלים. וכלפי שאמרו רבותינו שאמר הקדוש ברוך הוא צדיק זה בא לבית מלוני ויפטר בלא לינה, ועוד אמרו יעקב קראה לירושלים בית אל וזו לוז היא ולא ירושלים ומהיכן למדו לומר כן. אומר אני שנעקר הר המוריה ובא לכאן, וזהו היא קפיצת הארץ האמורה בשחיטת חלין (חולין צא ב) , שבא בית המקדש לקראתו עד בית אל, וזהו ויפגע במקום. [ואם תאמר וכשעבר יעקב על בית המקדש מדוע לא עכבו שם, איהו לא יהב לביה להתפלל במקום שהתפללו אבותיו, ומן השמים יעכבוהו, איהו עד חרן אזל כדאמרינן בפרק גיד הנשה (חולין צא ב) , וקרא מוכיח וילך חרנה, כי מטא לחרן אמר אפשר שעברתי על מקום שהתפללו אבותי ולא התפללתי בו, יהב דעתיה למהדר וחזר עד בית אל וקפצה לו הארץ]: **מה נורא.** תרגום מה דחילו אתרא הדין. דחילו שם דבר הוא, כמו סוכלתנו, וכסו למלבש: **וזה שער השמים.** מקום תפלה לעלות תפלתם השמימה. ומדרשו שבית המקדש של מעלה מכון כנגד בית המקדש של מטה כ **אם יהיה אלהים עמדי.** אם ישמור לי הבטחות הללו שהבטיחני להיות עמדי, כמו שאמר לי (פסוק טו) והנה אנכי עמך: **ושמרני.** כמו שאמר לי (פסוק טו) ושמרתיך בכל אשר תלך: **ונתן לי לחם לאכול.** כמו שאמר (פסוק טו) כי לא אעזבך, והמבקש לחם הוא קרוי נעזב, שנאמר (תהלים לז כה) ולא ראיתי צדיק נעזב וזרעו מבקש לחם:
@795 **ושבתי.** כמו שאמר לי (פסוק טו) והשיבותיך אל האדמה: **בשלום.** שלם מן החטא, שלא אלמד מדרכי לבן: **והיה ה' לי לאלהים.** שיחול שמו עלי מתחלה ועד סוף, שלא ימצא פסול בזרעי, כמו שנאמר (פסוק טו) אשר דברתי לך, והבטחה זו הבטיח לאברהם, שנאמר (שם יז ז) להיות לך לאלהים ולזרעך אחריך:
@796 **והאבן הזאת.** כך תפרש וי''ו זו של והאבן, אם תעשה לי את אלה, אף אני אעשה זאת: **והאבן הזאת אשר שמתי מצבה** וגו' **.** כתרגומו אהי פלח עלה קדם ה' וכן עשה בשובו מפדן ארם, כשאמר לו (לקמן לה א) קום עלה בית אל, מה נאמר שם (שם יד) ויצב יעקב מצבה וגו' ויסך עליה נסך:
@797 **וישא יעקב רגליו.** משנתבשר בשורה טובה שהובטח בשמירה, נשא לבו את רגליו ונעשה קל ללכת. כך מפרש בבראשית רבה (ע ח) :
@798 **ישקו העדרים.** משקים הרועים את העדרים, והמקרא דבר בלשון קצרה:
@799 **ונאספו.** רגילים היו להאסף לפי שהיתה האבן גדולה: **וגללו.** וגוללין ותרגומו ומגנדרין, כל לשון הוה משתנה לדבר בלשון עתיד ובלשון עבר לפי שכל דבר ההוה תמיד כבר היה ועתיד להיות: **והשיבו.** תרגומו ומתיבין:
@802 **באה עם הצאן.** הטעם באל''ף, ותרגומו אתיא. (פסוק ט) ורחל באה, הטעם למעלה בבי''ת ותרגומו אתת. הראשון לשון עושה, והשני לשון עשתה:
@803 **הן עוד היום גדול.** לפי שראה אותם רובצים, כסבור שרוצים לאסוף המקנה הביתה ולא ירעו עוד, אמר להם הן עוד היום גדול, כלומר אם שכירים אתם לא שלמתם פעלת היום, ואם הבהמות שלכם אף על פי כן לא עת האסף המקנה וגו' :
@804 **לא נוכל.** להשקות, לפי שהאבן גדולה: **וגללו.** זה מתורגם ויגנדרון, לפי שהוא לשון עתיד:
@806 **ויגש יעקב ויגל.** כזה שמעביר את הפקק מעל פי צלוחית, להודיעך שכחו גדול:
@807 **ויבך.** לפי שצפה ברוח הקודש שאינה נכנסת עמו לקבורה. דבר אחר לפי שבא בידים ריקניות, אמר אליעזר עבד אבי אבא היו בידיו נזמים וצמידים ומגדנות, ואני אין בידי כלום. לפי שרדף אליפז בן עשו במצות אביו אחריו להרגו והשיגו, ולפי שגדל אליפז בחיקו של יצחק משך ידו. אמר לו מה אעשה לצווי של אבא, אמר לו יעקב טול מה שבידי, והעני חשוב כמת:
@808 **כי אחי אביה הוא.** קרוב לאביה, כמו (לעיל יג ח) אנשים אחים אנחנו. ומדרשו אם לרמאות הוא בא גם אני אחיו ברמאות, ואם אדם כשר הוא, גם אני בן רבקה אחותו הכשרה: **ותגד לאביה.** לפי שאמה מתה לא היה לה להגיד אלא לו:
@809 **וירץ לקראתו.** כסבור ממון הוא טעון, שהרי עבד הבית בא לכאן בעשרה גמלים טעונים: **ויחבק.** כשלא ראה עמו כלום אמר שמא זהובים הביא והנם בחיקו: **וינשק לו.** אמר שמא מרגליות הביא והם בפיו: **ויספר ללבן.** שלא בא אלא מתוך אונס אחיו, ושנטלו ממונו ממנו:
@810 **אך עצמי ובשרי.** מעתה אין לי לאספך הביתה הואיל ואין בידך כלום, אלא מפני קורבה אטפל בך חדש ימים, וכן עשה ואף זו לא לחנם שהיה רועה צאנו:
@811 **הכי אחי אתה.** לשון תמה, וכי בשביל שאחי אתה תעבדני חנם: **ועבדתני.** כמו ותעבדני, וכן כל תבה שהיא לשון עבר הוסיף וי''ו בראשה היא הופכת התבה להבא:
@813 **ועיני לאה רכות.** שהיתה סבורה לעלות בגורלו של עשו ובוכה שהיו הכל אומרים שני בנים לרבקה ושתי בנות ללבן, הגדולה לגדול והקטנה לקטן: **תאר.** הוא צורת הפרצוף לשון (ישעיה מד יג) יתארהו בשרד, קונפ''ס בלע''ז : **מראה.** הוא זיו קלסתר:
@814 **אעבדך שבע שנים.** הם ימים אחדים שאמרה לו אמו (לעיל כז מד) וישבת עמו ימים אחדים. ותדע שכן הוא, שהרי כתיב (להלן פסוק כ) ויהיו בעיניו כימים אחדים: **ברחל בתך הקטנה.** כל הסימנים הללו למה, לפי שיודע בו שהוא רמאי אמר לו אעבדך ברחל, ושמא תאמר רחל אחרת מן השוק, תלמוד לומר בתך, ושמא תאמר אחליף ללאה שמה ואקרא שמה רחל, תלמוד לומר הקטנה ואף על פי כן לא הועיל לו שהרי רמהו:
@817 **מלאו ימי.** שאמרה לי אמי. ועוד מלאו ימי, שהרי אני בן שמונים וארבע שנה ואימתי אעמיד שנים עשר שבטים, וזהו שאמר ואבואה אליה, והלא קל שבקלים אינו אומר כן, אלא להוליד תולדות אמר כן:
@821 **ויהי בבקר והנה היא לאה.** אבל בלילה לא היתה לאה, לפי שמסר יעקב לרחל סימנים, וכשראתה רחל שמכניסין לו לאה אמרה עכשיו תכלם אחותי, עמדה ומסרה לה אותן סימנים:
@823 **מלא שבוע זאת.** דבוק הוא שהרי נקוד בחטף שבוע של זאת, והן שבעת ימי המשתה בתלמוד ירושלמי במועד קטן (א ז) . ואי אפשר לומר שבוע ממש, שאם כן היה צריך לנקד בפתח השין. ועוד ששבוע לשון זכר, כדכתיב (דברים טז ט) שבעה שבעת תספר לך, לפיכך אין משמע שבוע אלא שבעה שייטיינ''א בלע''ז : **ונתנה לך.** לשון רבים, כמו (לעיל יא ז) נרדה ונבלה, (שם ג) ונשרפה, אף זה לשון ונתן **גם את זאת.** [מיד לאחר שבעת ימי המשתה] ותעבוד לאחר נשואיה:
@826 **ויעבוד עמו עוד שבע שנים אחרות.** הקישן לראשונות, מה ראשונות באמונה אף האחרונות באמונה, ואף על פי שברמאות בא עליו:
@828 **ותקרא שמו ראובן.** רבותינו פרשו, אמרה ראו מה בין בני לבן חמי שמכר הבכורה ליעקב, וזה לא מכרה ליוסף ולא ערער עליו, ולא עוד שלא ערער עליו אלא שבקש להוציאו מן הבור:
@830 **הפעם ילוה אישי.** לפי שהאמהות נביאות היו ויודעות ששנים עשר שבטים יוצאים מיעקב וארבע נשים ישא, אמרה מעתה אין לו פתחון פה עלי, שהרי נטלתי כל חלקי בבנים: **על כן.** כל מי שנאמר בו על כן מרבה באוכלוסין, חוץ מלוי שהארון היה מכלה בהם: **קרא שמו לוי.** תמהתי שבכלם כתיב ותקרא, וזה כתב בו קרא, ויש מדרש אגדה באלה הדברים רבה ששלח הקדוש ברוך הוא גבריאל והביאו לפניו וקרא לו שם זה ונתן לו עשרים וארבע מתנות כהנה, ועל שם שלוהו במתנות קראו לוי:
@831 **הפעם אודה.** שנטלתי יותר מחלקי, מעתה יש לי להודות:
@832 **ותקנא רחל באחותה.** קנאה במעשיה הטובים, אמרה אלולי שצדקה ממני לא זכתה לבנים: **הבה לי.** וכי כך עשה אביך לאמך, והלא התפלל עליה: **מתה אנכי.** מכאן למי שאין לו בנים שחשוב כמת:
@833 **התחת אלהים אנכי.** וכי במקומו אני: **אשר מנע ממך.** את אמרת שאעשה כאבא, אני איני כאבא, אבא לא היו לו בנים אני יש לי בנים, ממך מנע ולא ממני:
@834 **על ברכי.** כתרגומו ואנא ארבי: **ואבנה גם אנכי.** מהו גם, אמרה לו זקנך אברהם היו לו בנים מהגר, וחגר מתניו כנגד שרה, אמר לה זקנתי הכניסה צרתה לביתה, אמרה לו אם הדבר הזה מעכב, הנה אמתי בלהה, ואבנה גם אנכי ממנה כשרה:
@837 **דנני אלהים.** דנני וחיבני וזכני:
@839 **נפתולי אלהים.** מנחם בן סרוק פרשו במחברת (במדבר יט טו) צמיד פתיל, חבורים, מאת המקום נתחברתי עם אחותי לזכות לבנים. ואני מפרשו לשון (דברים לב ה) עקש ופתלתול, נתעקשתי והפצרתי פצירות ונפתולים הרבה למקום להיות שוה לאחותי: **גם יכלתי.** הסכים על ידי. ואונקלוס תרגם לשון תפלה, כמו נפתולי אלהים, נתפללתי בקשות החביבות לפניו, נתקבלתי ונעתרתי כאחותי: **נפתלתי.** נתקבלה תפלתי. ומדרש אגדה יש רבים בלשון נוטריקון:
@841 **ותלד זלפה.** בכלן נאמר הריון חוץ מזלפה לפי שהיתה בחורה מכולן ותינוקת בשנים ואין הריון נכר בה, וכדי לרמות ליעקב נתנה לבן ללאה שלא יבין שמכניסין לו את לאה, שכך מנהג לתן שפחה גדולה לגדולה וקטנה לקטנה:
@842 **בא גד.** בא מזל טוב, כמו (שבת סז ב) גד גדי וסנוק לא, ודומה לו (ישעיה סה יא) העורכים לגד שלחן. ומדרש אגדה שנלד מהול, כמו (דניאל ד כ) גדו אילנא, ולא ידעתי על מה נכתבה תבה אחת. דבר אחר למה נקראת תיבה אחת בגד, כמו בגדת בי כשבאת אל שפחתי, כאיש שבגד באשת נעורים:
@845 **בימי קציר חטים.** להגיד שבחן של שבטים, שעת הקציר היה ולא פשט ידו בגזל להביא חטים ושעורים אלא דבר ההפקר שאין אדם מקפיד בו: **דודאים.** סיגלי, עשב הוא ובלשון ישמעאל יסמי''ן:
@846 **ולקחת גם את דודאי בני.** בתמיהה, ולעשות עוד זאת לקח גם את דודאי בני ותרגומו ולמסב: **לכן ישכב עמך הלילה.** שלי היתה שכיבת לילה זו ואני נותנה לך תחת דודאי בנך. ולפי שזלזלה במשכב הצדיק לא זכתה להקבר עמו:
@847 **שכר שכרתיך.** נתתי לרחל שכרה: **בלילה הוא.** הקדוש ברוך הוא סיע שיצא משם יששכר:
@848 **וישמע אלהים אל לאה.** שהיתה מתאוה ומחזרת להרבות שבטים:
@851 **זבד טוב.** כתרגומו: **יזבלני.** לשון (מלכים א' ח יג) בית זבול הירבירייריא''ה בלע''ז בית מדור. מעתה לא תהא עיקר דירתו אלא עמי שיש לי בנים כנגד כל נשיו:
@852 **דינה.** פרשו רבותינו שדנה לאה דין בעצמה אם זה זכר לא תהא רחל אחותי כאחת השפחות, והתפללה עליו ונהפך לנקבה:
@853 **ויזכר אלהים את רחל.** זכר לה שמסרה סימניה לאחותה, ושהיתה מצרה שלא תעלה בגורלו של עשו שמא יגרשנה יעקב לפי שאין לה בנים, ואף עשו הרשע כך עלה בלבו כששמע שאין לה בנים. הוא שיסד הפיט (קרובות דר''ה שחרית) האדמון כבט שלא חלה, צבה לקחתה לו ונתבהלה:
@854 **אסף.** הכניסה במקום שלא תראה וכן (ישעיה ד א) אסף חרפתנו, (שמות ט יט) ולא יאסף הביתה, (יואל ד טו) אספו נגהם, (ישעיה ס כ) וירחך לא יאסף, לא יטמן: **חרפתי.** שהייתי לחרפה שאני עקרה, והיו אומרים עלי שאעלה לחלקו של עשו הרשע. ומדרש אגדה כל זמן שאין לאשה בן אין לה במי לתלות סרחונה, משיש לה בן תולה בו. מי שבר כלי זה, בנך, מי אכל תאנים אלו, בנך:
@855 **יוסף ה' לי בן אחר.** יודעת היתה בנבואה שאין יעקב עתיד להעמיד אלא שנים עשר שבטים, אמרה יהי רצון שאותו שהוא עתיד להעמיד יהא ממני, לכך לא נתפללה אלא על בן אחר:
@856 **כאשר ילדה רחל את יוסף.** משנלד שטנו של עשו, שנאמר (עובדיה א יח) והיה בית יעקב אש ובית יוסף להבה ובית עשו לקש, אש בלא להבה אינו שולט למרחוק, משנלד יוסף בטח יעקב בהקדוש ברוך הוא ורצה לשוב:
@857 **תנה את נשי** וגו' **.** איני רוצה לצאת כי אם ברשות:
@858 **נחשתי.** מנחש היה, נסיתי בנחוש שלי שעל ידך באה לי ברכה, כשבאת לכאן לא היו לי בנים, שנאמר (לעיל כט ו) והנה רחל בתו באה עם הצאן, אפשר יש לו בנים והוא שולח בתו אצל הרועים, ועכשיו היו לו בנים שנאמר (להלן לא א) וישמע את דברי בני לבן:
@859 **נקבה שכרך.** כתרגומו פריש אגרך:
@860 **ואת אשר היה מקנך אתי.** את חשבון מעוט מקנך שבא לידי מתחלה כמה היו:
@861 **לרגלי.** עם רגלי, בשביל ביאת רגלי באת אצלך הברכה, כמו (שמות יא ח) העם אשר ברגלך, (שופטים ח ה) לעם אשר ברגלי, הבאים עמי: **גם אנכי לביתי.** לצורך ביתי, עכשיו אין עושין לצרכי אלא בני וצריך אני להיות עושה גם אני עמהם לסמכן, וזהו גם:
@863 **נקד.** מנמר בחברבורות דקות, כמו נקדות, פוינטור''א בלע''ז : **טלוא.** לשון טלאים חברבורות רחבות: **חום.** שחום דומה לאדום, רו''ש בלע''ז [אדום] לשון משנה שחמתית ונמצאת לבנה, לענין התבואה: **והיה שכרי.** אותן שיולדו מכאן ולהבא נקדים וטלואים בעזים ושחומים בכשבים יהיו שלי ואותן שישנן עכשיו הפרש מהם והפקידם ביד בניך, שלא תאמר לי על הנלדים מעתה אלו היו שם מתחלה, ועוד שלא תאמר לי על ידי הזכרים שהן נקדים וטלואים תלדנה הנקבות דוגמתן מכאן ואלך:
@864 **וענתה בי** וגו' **.** אם תחשדני שאני נוטל משלך כלום, תענה בי צדקתי, כי תבא צדקתי ותעיד על שכרי לפניך, שלא תמצא בעדרי כי אם נקדים וטלואים, וכל שתמצא בהן שאינו נקוד או טלוא או חום בידוע שגנבתיו לך, ובגנבה הוא שרוי אצלי:
@865 **הן.** לשון הן, קבלת דברים: **לו יהי כדברך.** הלואי שתחפץ בכך:
@866 **ויסר.** לבן ביום ההוא וגו' : **התישים.** עזים זכרים: **כל אשר לבן בו.** כל אשר היתה בו חברבורית לבנה: **ויתן.** לבן ביד בניו:
@867 **הנותרת.** הרעועות שבהן החולות והעקרות, שאינן אלא שירים, אותן מסר לו:
@868 **מקל לבנה.** עץ הוא ושמו לבנה, כמה דתימא (הושע ד יג) תחת אלון ולבנה, ואומר אני הוא שקורין טרינבל''א בלע''ז שהוא לבן [צפצפה עצנית]: **לח.** כשהוא רטוב: **ולוז.** ועוד לקח מקל לוז, עץ שגדלין בו אגוזים דקים קולדר''א בלע''ז [אלסר]: **וערמון.** קשטיניי''ר בלע''ז [עץ ערמון]: **פצלות.** קלופים קלופים, שהיה עושהו מנמר: **מחשף הלבן.** גלוי לובן של מקל. כשהיה קולפו היה נראה ונגלה לובן שלו במקום הקלוף:
@869 **ויצג.** תרגומו ודעיץ, לשון תחיבה ונעיצה הוא בלשון ארמי, והרבה יש בתלמוד (שבת נ ב) דצה ושלפה, (חולין צג ב) דץ ביה מידי. דצה כמו דעצה, אלא שמקצר את לשונו: **ברהטים.** במרוצת המים, בבריכות העשויות בארץ, להשקות שם הצאן: **אשר תבאן** וגו' **ברהטים.** אשר תבאנה הצאן לשתות, שם הציג המקלות לנכח הצאן: **ויחמנה.** הבהמה רואה את המקלות והיא נרתעת לאחוריה, והזכר רובעה ויולדת כיוצא בו. ר' הושעיא אומר המים נעשין זרע במעיהן ולא היו צריכות לזכר, וזהו ויחמנה וגו' :
@870 **אל המקלות.** אל מראות המקלות: **עקדים.** משנים במקום עקידתן, הם קרסלי ידיהן ורגליהן:
@871 **והכשבים הפריד יעקב.** הנלדים עקדים נקדים הבדיל והפריד לעצמן ועשה אותן עדר עדר לבדו, והוליך אותו העדר העקוד לפני הצאן, ופני הצאן ההולכות אחריהם צופות אליהם, וזהו שנאמר ויתן פני הצאן אל עקוד, שהיו פני הצאן אל העקדים, ואל כל חום שמצא בצאן לבן: **וישת לו עדרים.** כמו שפרשתי:
@872 **המקשרות.** כתרגומו הבכירות ואין לו עד במקרא להוכיח עליו. ומנחם חברו עם (שמואל ב' טו לא) אחיתפל בקשרים, (שם טו י) ויהי הקשר אמיץ, אותן המתקשרות יחד למהר עבורן:
@873 **ובהעטיף.** לשון אחור, כתרגומו ובלקישות. ומנחם חברו עם (ישעיה ג כג) המחלצות והמעטפות, לשון עטיפת כסות, כלומר מתעטפות בעורן וצמרן ואינן מתאוות להתיחם על ידי הזכרים:
@874 **צאן רבות.** פרות ורבות יותר משאר צאן: **ושפחות ועבדים.** מוכר צאנו בדמים יקרים ולוקח לו כל אלה:
@875 **עשה.** כנס, כמו (ש''א יד מח) ויעש חיל ויך את עמלק:
@877 **שוב אל ארץ אבותיך.** ושם אהיה עמך, אבל בעודך מחבר לטמא אי אפשר להשרות שכינתי עליך:
@878 **ויקרא לרחל וללאה.** לרחל תחלה ואחר כך ללאה שהיא היתה עקרת הבית, שבשבילה נזדוג יעקב עם לבן, ואף בניה של לאה מודים בדבר, שהרי בעז ובית דינו משבט יהודה אומרים (רות ד יא) כרחל וכלאה אשר בנו שתיהם וגו' , הקדימו רחל ללאה:
@881 **עשרת מנים.** אין מונים פחות מעשרה: **מנים.** לשון סכום כלל החשבון, והן עשיריות, למדנו שהחליף תנאו מאה פעמים:
@884 **והנה העתודים.** אף על פי שהבדילם לבן כלם שלא יתעברו הצאן דוגמתן, היו המלאכים מביאין אותן מעדר המסור ביד בני לבן לעדר שביד יעקב: **וברדים.** כתרגומו ופציחין פיישי''ד בלע''ז [מנומש], חוט של לבן מקיף את גופו סביב, חברבורית שלו פתוחה ומפולשת מזן אל זן, ואין לי להביא עד מן המקרא:
@887 **האל בית אל.** כמו אל בית אל, הה''א יתרה, ודרך מקראות לדבר כן, כמו (במדבר לד ב) כי אתם באים אל הארץ כנען: **משחת שם.** לשון רבוי וגדלה כשנמשח למלכות, כך (לעיל כח יח) ויצק שמן על ראשה, להיות משוחה למזבח: **אשר נדרת לי.** וצריך אתה לשלמו, שאמרת (שם כב) יהיה בית אלהים, שתקריב שם קרבנות:
@888 **העוד לנו חלק.** למה נעכב על ידך מלשוב, כלום אנו מיחלות לירש בנכסי אבינו כלום בין הזכרים:
@889 **הלוא נכריות נחשבנו לו.** אפלו בשעה שדרך בני אדם לתת נדוניא לבנותיו בשעת נשואין, נהג עמנו כנכריות, כי מכרנו לך בשכר הפעלה: **את כספנו.** שעכב דמי שכר פעלתך:
@890 **כי כל העשר.** כי זה משמש בלשון אלא, כלומר משל אבינו אין לנו כלום אלא מה שהציל הקדוש ברוך הוא מאבינו שלנו הוא: **הציל.** לשון הפריש, וכן כל לשון הצלה שבמקרא לשון הפרשה, שמפרישו מן הרעה ומן האויב:
@891 **את בניו ואת נשיו.** הקדים זכרים לנקבות, ועשו הקדים נקבות לזכרים, שנאמר (לקמן לו ו) ויקח עשו את נשיו ואת בניו וגו' :
@892 **מקנה קנינו.** מה שקנה מצאנו עבדים ושפחות וגמלים וחמורים:
@893 **לגזז את צאנו.** שנתן ביד בניו דרך שלשת ימים בינו ובין יעקב: **ותגנב רחל את התרפים.** להפריש את אביה מעבודה זרה נתכונה:
@896 **ביום השלישי.** שהרי דרך שלשת ימים היה ביניהם:
@897 **את אחיו.** קרוביו: **דרך שבעת ימים.** כל אותן שלשה ימים שהלך המגיד להגיד ללבן הלך יעקב לדרכו. נמצא יעקב רחוק מלבן ששה ימים, ובשביעי השיגו לבן, למדנו שכל מה שהלך יעקב בשבעה ימים הלך לבן ביום אחד (שנאמר וירדוף אחריו דרך שבעת ימים, ולא נאמר וירדוף אחריו שבעת ימים) :
@898 **מטוב עד רע.** כל טובתן של רשעים רעה היא אצל הצדיקים:
@900 **כשביות חרב.** כל חיל הבא למלחמה קרוי חרב:
@901 **ותגנב אתי.** גנבת את דעתי:
@903 **יש לאל ידי.** יש כח וחיל בידי לעשות עמכם רע. וכל אל שהוא לשון קדש על שם עזוז ורוב אונים הוא:
@904 **נכספתה.** חמדת, והרבה יש במקרא (תהלים פד ג) נכספה וגם כלתה נפשי, (איוב יד טו) למעשה ידיך תכסף:
@905 **כי יראתי** וגו' **.** השיבו על ראשון ראשון, שאמר לו (פסוק כו) ותנהג את בנותי וגו' :
@906 **לא יחיה.** ומאותה קללה מתה רחל בדרך: **מה עמדי.** משלך:
@907 **באהל יעקב.** הוא אהל רחל, שהיה יעקב תדיר אצלה, וכן הוא אומר (להלן מו יט) בני רחל אשת יעקב, ובכלן לא נאמר אשת יעקב: **ויבא באהל רחל.** כשיצא מאהל לאה חזר לו לאהל רחל קודם שחפש באהל האמהות. וכל כך למה, לפי שהיה מכיר בה שהיא משמשנית:
@908 **בכר הגמל.** לשון כרים וכסתות כתרגומו בעביטא דגמלא, והיא מרדעת העשויה כמין כר ובעירובין (דף טז א) הקיפוה בעביטין, והן עביטי גמלים, בשטי''ל בלע''ז :
@910 **דלקת.** רדפת, כמו (איכה ד יט) על ההרים דלקנו, וכמו (ש''א יז נג) מדלק אחרי פלשתים:
@911 **ויוכיחו.** ויבררו עם מי הדין, אפרובי''ר בלע''ז :
@912 **לא שכלו.** לא הפילו עבורם, כמו (הושע ט יד) רחם משכיל, (איוב כא י) תפלט פרתו ולא תשכל: **ואילי צאנך.** מכאן אמרו איל בן יומו קרוי איל, שאם לא כן מה שבחו, אילים לא אכל אבל כבשים אכל, אם כן גזלן הוא:
@913 **טרפה.** על ידי ארי או זאב: **אנכי אחטנה.** לשון (שופטים כ טז) קולע באבן אל השערה ולא יחטא, (מ''א א כא) אני ובני שלמה חטאים, חסרים, אנכי אחסרנה, אם חסרה חסרה לי, שמידי תבקשנה: **אנכי אחטנה.** תרגומו דהות שגיא ממנינא שהיתה נפקדת ומחסרת, כמו (במדבר לא מט) ולא נפקד ממנו איש, תרגומו ולא שגא: **גנבתי יום וגנבתי לילה.** גנובת יום או גנובת לילה הכל שלמתי: **גנבתי.** כמו (איכה א א) רבתי בגוים שרתי במדינות, (ישעיה א כא) מלאתי משפט, (הושע י יא) אהבתי לדוש:
@914 **אכלני חרב.** לשון (דברים ד כד) אש אכלה: **וקרח.** כמו (תהלים קמז יז) משליך קרחו, תרגומו גלידא: **שנתי.** לשון שינה:
@915 **ותחלף את משכרתי.** היית משנה תנאי שבינינו מנקוד לטלוא ומעקדים לברדים:
@916 **ופחד יצחק.** לא רצה לומר אלהי יצחק, שאין הקדוש ברוך הוא מיחד שמו על הצדיקים בחייהם, ואף על פי שאמר לו בצאתו מבאר שבע (לעיל כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק, בשביל שכהו עיניו והרי הוא כמת, יעקב נתירא לומר אלהי ואמר ופחד: **ויוכח.** לשון תוכחה הוא ולא לשון הוכחה:
@917 **מה אעשה לאלה.** איך תעלה על לבי להרע להן:
@918 **והיה לעד.** הקדוש ברוך הוא:
@920 **לאחיו.** הם בניו, שהיו לו אחים נגשים אליו לצרה ולמלחמה:
@921 **יגר שהדותא.** תרגומו של גלעד: **גלעד.** כמו גלעד:
@923 **והמצפה אשר אמר** וגו' **.** והמצפה אשר בהר הגלעד, כמו שכתוב (שופטים יא כט) ויעבר את מצפה גלעד. ולמה נקרא שמה מצפה, לפי שאמר כל אחד מהם לחברו יצף ה' ביני ובינך אם תעבור את הברית: **כי נסתר.** ולא נראה איש את רעהו:
@924 **בנתי בנתי.** שתי פעמים, אף בלהה וזלפה בנותיו היו מפלגש: **אם תענה את בנתי.** למנוע מהם עונת תשמיש:
@925 **יריתי.** כמו (שמות טו ד) ירה בים, כזה שהוא יורה חנית:
@926 **אם אני.** הרי אם משמש בלשון אשר, כמו (לעיל כד לג) עד אם דברתי דברי: **לרעה.** לרעה אי אתה עובר, אבל אתה עובר לפרקמטיא:
@927 **אלהי אברהם.** קדש: **ואלהי נחור.** חול: **אלהי אביהם.** חול:
@928 **ויזבח יעקב זבח.** שחט בהמות למשתה: **לאחיו.** לאוהביו שעם לבן: **לאכל לחם.** כל דבר מאכל קרוי לחם, כמו (דניאל ה א) עבד לחם רב, (ירמיה יא יט) נשחיתה עץ בלחמו:
@930 **ויפגעו בו מלאכי אלהים.** מלאכים של ארץ ישראל באו לקראתו ללוותו לארץ:
@931 **מחנים.** שתי מחנות, של חוצה לארץ שבאו עמו עד כאן, ושל ארץ ישראל שבאו לקראתו:
@932 **וישלח יעקב מלאכים.** מלאכים ממש: **ארצה שעיר.** לארץ שעיר, כל תיבה שצריכה למ''ד בתחלתה הטיל לה הכתוב ה''א בסופה:
@933 **גרתי.** לא נעשיתי שר וחשוב אלא גר, אינך כדאי לשנוא אותי על ברכות אביך שברכני (לעיל כז כט) הוה גביר לאחיך, שהרי לא נתקימה בי. דבר אחר גרתי בגימטריא תרי''ג, כלומר עם לבן הרשע גרתי ותרי''ג מצות שמרתי ולא למדתי ממעשיו הרעים:
@934 **ויהי לי שור וחמור.** אבא אמר לי (כז כח) מטל השמים ומשמני הארץ, זו אינה לא מן השמים ולא מן הארץ: **שור וחמור.** דרך ארץ לומר על שורים הרבה שור. אדם אומר לחברו בלילה קרא התרנגול, ואינו אומר קראו התרנגולים: **ואשלחה להגיד לאדוני.** להודיע שאני בא אליך: **למצא חן בעיניך.** שאני שלם עמך ומבקש אהבתך:
@935 **באנו אל אחיך אל עשו.** שהיית אומר אחי הוא, אבל הוא נוהג עמך כעשו הרשע, עודנו בשנאתו:
@936 **ויירא ויצר.** ויירא שמא יהרג, ויצר לו אם יהרוג הוא את אחרים:
@937 **המחנה האחת והכהו.** מחנה משמש לשון זכר ולשון נקבה. (תהלים כז ג) אם תחנה עלי מחנה, הרי לשון נקבה, (לג ח) המחנה הזה, לשון זכר. וכן יש שאר דברים משמשים לשון זכר ולשון נקבה, (לעיל יט כג) השמש יצא על הארץ, (תהלים יט ז) מקצה השמים מוצאו, הרי לשון זכר. (מ''ב ג כב) והשמש זרחה על המים, הרי לשון נקבה. וכן רוח (איוב א יט) והנה רוח גדולה באה, הרי לשון נקבה, (שם) ויגע בארבע פנות הבית, הרי לשון זכר, (מ''א יט יא) ורוח גדולה וחזק מפרק הרים, הרי לשון זכר ולשון נקבה. וכן אש (במדבר טז לה) ואש יצאה מאת ה', לשון נקבה. (תהלים קד ד) אש לוהט, לשון זכר: **והיה המחנה הנשאר לפלטה.** על כרחו כי אלחם עמו. התקין עצמו לשלשה דברים לדורון, לתפלה ולמלחמה. לדורון להלן (פסוק כא) ותעבור המנחה על פניו. לתפלה (פסוק ט) אלהי אבי אברהם. למלחמה והיה המחנה הנשאר לפלטה:
@938 **ואלהי אבי יצחק.** ולהלן הוא אומר (לא מב) ופחד יצחק, ועוד מהו שחזר והזכיר שם המיחד, היה לו לכתוב האומר אלי שוב לארצך וגו' . אלא כך אמר יעקב לפני הקדוש ברוך הוא שתי הבטחות הבטחתני אחת בצאתי מבית אבי מבאר שבע, שאמרת לי (כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק, ושם אמרת לי (שם טו) ושמרתיך בכל אשר תלך. ובבית לבן אמרת לי (לא ג) שוב אל ארץ אבותיך ולמולדתך ואהיה עמך, ושם נגלית אלי בשם המיחד לבדו, שנאמר (לא ג) ויאמר ה' אל יעקב שוב אל ארץ אבותיך וגו' , בשתי הבטחות האלו אני בא לפניך:
@939 **קטנתי מכל החסדים.** נתמעטו זכיותי על ידי החסדים והאמת שעשית עמי, לכך אני ירא, שמא משהבטחתני נתלכלכתי בחטא ויגרום לי להמסר ביד עשו: **ומכל האמת.** אמתת דבריך, ששמרת לי כל ההבטחות שהבטחתני: **כי במקלי.** לא היה עמי לא כסף ולא זהב ולא מקנה אלא מקלי לבדו. ומדרש אגדה נתן מקלו בירדן ונבקע הירדן:
@940 **מיד אחי מיד עשו.** מיד אחי שאין נוהג עמי כאח אלא כעשו הרשע:
@941 **היטב איטיב.** היטב בזכותך, איטיב בזכות אבותיך: **ושמתי את זרעך כחול הים.** והיכן אמר לו כן, והלא לא אמר לו אלא (שם כח יד) והיה זרעך כעפר הארץ. אלא שאמר לו (כח טו) כי לא אעזבך עד אשר אם עשיתי את אשר דברתי לך, ולאברהם אמר (כב יז) הרבה ארבה את זרעך ככוכבי השמים וכחול אשר על שפת הים:
@942 **הבא בידו.** ברשותו, וכן (במדבר כא כו) ויקח את כל ארצו מידו. ומדרש אגדה מן הבא בידו אבנים טובות ומרגליות, שאדם צר בצרור ונושאם בידו. דבר אחר מן הבא בידו מן החלין, שנטל מעשר, כמה דאת אמר (כח כב) עשר אעשרנו לך, והדר לקח מנחה:
@943 **עזים מאתים ותישים עשרים.** מאתים עזים צריכות עשרים תישים, וכן כלם, הזכרים כדי צורך הנקבות. ובבראשית רבה (עו ז) דורש מכאן לעונה האמורה בתורה, הטילים בכל יום, הפועלים שתים בשבת, החמרים אחת בשבת, הגמלים אחת לשלשים יום, הספנים אחת לששה חדשים. ואיני יודע לכון המדרש הזה בכוון. אך נראה בעיני שלמדנו מכאן שאין העונה שוה בכל אדם אלא לפי טורח המטל עליו, שמצינו כאן שמסר לכל תיש עשרה עזים, וכן לכל איל, לפי שהם פנוים ממלאכה, דרכן להרבות בתשמיש לעבר עשר נקבות, ובהמה משנתעברה אינה מקבלת זכר, ופרים שעוסקין במלאכה לא מסר לזכר אלא ארבע נקבות, ולחמור שהולך בדרך רחוקה שתי נקבות לזכר, ולגמלים שהולכים דרך יותר רחוקה נקבה אחת לזכר:
@944 **גמלים מיניקות** וט' **שלשים.** ובניהם עמהם. ומדרש אגדה ובניהם בנאיהם, זכר כנגד נקבה, ולפי שצנוע בתשמיש לא פרסמו הכתוב: **ועירים.** חמורים זכרים:
@945 **עדר עדר לבדו.** כל מין ומין לעצמו: **עברו לפני.** דרך יום או פחות, ואני אבא אחריכם: **ורוח תשימו.** עדר לפני חברו מלא עין, כדי להשביע עינו של רשע ולתוהו על רבוי הדורון:
@946 **למי אתה.** שלמי אתה, מי שולחך, ותרגומו דמן את: **ולמי אלה לפניך.** ואלה שלפניך שלמי הם, למי המנחה הזאת שלוחה. למ''ד משמשת בראש התבה במקום של, כמו (לעיל לא מג) וכל אשר אתה רואה לי הוא, שלי הוא, (תהלים כד א) לה' הארץ ומלואה, של ה':
@947 **ואמרת לעבדך ליעקב.** על ראשון ראשון ועל אחרון אחרון, ששאלת (פסוק יז. יח) למי אתה, לעבדך ליעקב אני, ותרגומו דעבדך דיעקב, וששאלת (פסוק יז. יח) ולמי אלה לפניך, מנחה היא שלוחה וגו' : **והנה גם הוא.** יעקב:
@949 **אכפרה פניו.** אבטל רגזו וכן (ישעיה כח יח) וכפר בריתכם את מות, (שם מז יא) לא תוכלי כפרה. ונראה בעיני שכל כפרה שאצל עוון וחטא ואצל פנים כלן לשון קנוח והעברה הן, ולשון ארמי הוא הרבה בתלמוד (ב''מ כד א) וכפר ידה, (גיטין נו א) בעי לכפורי ידה בההוא גברא, וגם בלשון המקראנקראים המזרקים של קדש (עזרא א י) כפורי זהב, על שם שהכהן מקנח ידיו בהן בשפת המזרק:
@950 **על פניו.** כמו לפניו, וכן (ירמיה ו ז) חמס ושד ישמע בה על פני תמיד, וכן (ישעיה סה ג) המכעסים אתי על פני. ומדרש אגדה על פניו אף הוא שרוי בכעס, שהיה צריך לכל זה:
@951 **ואת אחד עשר ילדיו.** ודינה היכן היתה, נתנה בתבה ונעל בפניה שלא יתן בה עשו עיניו, ולכך נענש יעקב שמנעה מאחיו שמא תחזירנו למוטב, ונפלה ביד שכם: **יבק.** שם הנהר:
@952 **את אשר לו.** הבהמות והמטלטלין, עשה עצמו כגשר, נוטל מכאן מניח כאן:
@953 **ויותר יעקב.** שכח פכים קטנים וחזר עליהם: **ויאבק איש.** מנחם פרש ויתעפר איש, לשון אבק, שהיו מעלים עפר ברגליהם על ידי נענועם. ולי נראה שהוא לשון ויתקשר, ולשון ארמי הוא, בתר דאביקו בה, ואבק לה מיבק, לשון עניבה, שכן דרך שנים שמתעצמים להפיל איש את רעהו שחובקו ואובקו בזרועותיו. ופירשו רבותינו זכרונם לברכה שהוא שרו של עשו:
@954 **ויגע בכף ירכו.** קלית הירך התקוע בקלבוסית קרוי כף, על שם שהבשר שעליה כמין כף של קדרה: **ותקע.** נתקעקעה ממקום מחברתה, ודומה לו (ירמיה ו ח) פן תקע נפשי ממך, לשון הסרה. ובמשנה לקעקע ביצתן, לשרש שרשיהן:
@955 **כי עלה השחר.** וצריך אני לומר שירה ביום: **ברכתני.** הודה לי על הברכות שברכני אבי, שעשו מערער עליהן:
@957 **לא יעקב.** לא יאמר עוד שהברכות באו לך בעקבה וברמיה כי אם בשררה ובגלוי פנים, וסופך שהקדוש ברוך הוא נגלה עליך בבית אל ומחליף את שמך, ושם הוא מברכך, ואני שם אהיה ואודה לך עליהן, וזהו שכתוב (הושע יב ה) וישר אל מלאך ויכל בכה ויתחנן לו, בכה המלאך ויתחנן לו, ומה נתחנן לו (שם) בית אל ימצאנו ושם ידבר עמנו, המתן לי עד שידבר עמנו שם, ולא רצה יעקב, ועל כרחו הודה לו עליהן, וזהו (פסוק ל) ויברך אותו שם, שהיה מתחנן להמתין לו ולא רצה: **ועם אנשים.** עשו ולבן: **ותוכל.** להם:
@958 **למה זה תשאל.** אין לנו שם קבוע, משתנין שמותינו, הכל לפי מצות עבודת השליחות שאנו משתלחים:
@960 **ויזרח לו השמש.** לשון בני אדם הוא, כשהגענו למקום פלוני האיר לנו השחר, זהו פשוטו. ומדרש אגדה ויזרח לו לצרכו, לרפאות את צלעתו, כמה דתימא (מלאכי ג כ) שמש צדקה ומרפא בכנפיה, ואותן שעות שמיהרה לשקוע בשבילו כשיצא מבאר שבע, מהרה לזרוח בשבילו: **והוא צלע.** והוא היה צולע כשזרחה השמש:
@961 **גיד הנשה.** ולמה נקרא שמו גיד הנשה, לפי שנשה ממקומו ועלה, והוא לשון קפיצה, וכן (ירמיה נא ל) נשתה גבורתם, וכן (לקמן מא נא) כי נשני אלהים את כל עמלי:
@963 **ואת לאה וילדיה אחרנים.** אחרון אחרון חביב:
@964 **עבר לפניהם.** אמר אם יבא אותו רשע להלחם, ילחם בי תחלה:
@965 **ויחבקהו.** נתגלגלו רחמיו כשראהו משתחוה כל השתחואות הללו: **וישקהו.** נקוד עליו, ויש חולקין בדבר הזה בברייתא דספרי (בהעלותך סט) , יש שדרשו נקדה זו לומר שלא נשקו בכל לבו. אמר ר' שמעון בן יוחאי הלכה היא בידוע שעשו שונא ליעקב, אלא שנכמרו רחמיו באותה שעה ונשקו בכל לבו:
@966 **מי אלה לך.** מי אלה להיות שלך:
@968 **נגש יוסף ורחל.** בכלן האמהות נגשות לפני הבנים, אבל ברחל יוסף נגש לפניה, אמר אמי יפת תאר, שמא יתלה בה עיניו אותו רשע, אעמד כנגדה ואעכבנו מלהסתכל בה, מכאן זכה יוסף לברכת (מט כב) עלי עין:
@969 **מי לך כל המחנה.** מי כל המחנה אשר פגשתי שהוא שלך, כלומר למה הוא לך. ופשוטו של מקרא [נאמר] על מוליכי המנחה. ומדרשו כתות של מלאכים פגע, שהיו דוחפין אותו ואת אנשיו, ואומרים להם של מי אתם, והם אומרים להם של עשו, והן אומרים הכו הכו, ואלו אומרים הניחו בנו של יצחק הוא, ולא היו משגיחים עליו, בן בנו של אברהם הוא, ולא היו משגיחים, אחיו של יעקב הוא, אומרים להם אם כן משלנו אתם:
@970 **יהי לך אשר לך.** כאן הודה לו על הברכות:
@971 **אל נא.** אל נא תאמר לי כן: **אם נא מצאתי חן בעיניך ולקחת מנחתי מידי כי על כן ראיתי פניך** וגו' **.** כי כדאי והגון לך שתקבל מנחתי על אשר ראיתי פניך, והן חשובין לי כראית פני המלאך שראיתי שר שלך, ועוד על שנתרצית למחול סרחני. ולמה הזכיר לו ראית המלאך, כדי שיתירא המנו ויאמר ראה מלאכים ונצול, איני יכול לו מעתה: **ותרצני.** נתפיסת לי, וכן כל רצון שבמקרא לשון פיוס, אפיימינ''ט בלע''ז (ויקרא כב כ) כי לא לרצון יהיה לכם, הקרבנות באות לפיס ולרצון, וכן (משלי י לב) שפתי צדיק ידעון רצון, יודעים לפיס ולרצות:
@972 **ברכתי.** מנחתי, מנחה זו הבאה על ראית פנים ולפרקים אינה באה אלא לשאילת שלום, וכל ברכה שהיא לראית פנים, כגון להלן (מז י) ויברך יעקב את פרעה, (מ''ב יח לא) עשו אתי ברכה, דסנחריב. וכן (ש''ב ח י) לשאל לו לשלום ולברכו, דתועי מלך חמת, כלם לשון ברכת שלום הן שקורין בלע''ז שלוצי''ר [לשאול בשלום], אף זו ברכתי מו''ן שלו''ד : **אשר הבאת לך.** לא טרחת בה, ואני יגעתי להגיעה עד שבאה לידך: **חנני.** נו''ן ראשונה מדגשת לפי שהיא משמשת במקום שתי נוני''ן, שהיה לו לומר חננני, שאין חנן בלא שתי נונין, והשלישית לשמוש כמו עשני, זבדני: **יש לי כל.** כל ספוקי, ועשו דבר בלשון גאוה (פסוק ט) יש לי רב, יותר ויותר מכדי צרכי:
@973 **נסעה.** כמו (תהלים קל ב) שמעה, שהוא כמו שמע, אף כאן נסעה כמו נסע, והנו''ן יסוד בתבה. ותרגומו טול ונהך, עשו אמר ליעקב נסע מכאן ונלך: **ואלכה לנגדך.** בשוה לך, טובה זו אעשה לך שאאריך ימי מהלכתי ללכת לאט כאשר אתה צריך, וזהו לנגדך, בשוה לך:
@974 **עלות עלי.** הצאן והבקר שהן עלות מטלות עלי לנהלן לאט: **עלות.** מגדלות עולליהן, לשון (איכה ב יא) עולל ויונק, (ישעיה סה כ) עול ימים, (שמואל א' ו י) ושתי פרות עלות, ובלע''ז אינפנטיי''ש **ודפקום יום אחד.** ליגעם בדרך במרוצה, ומתו כל הצאן: **ודפקום.** כמו (שה''ש ה ב) קול דודי דופק, נוקש בדלת:
@975 **יעבר נא אדני.** אל תאריך ימי הליכתך, עבור כפי דרכך ואף אם תתרחק: **אתנהלה.** אתנהל, ה''א יתרה כמו (לעיל יח כא) ארדה, (במדבר ט ח) אשמעה: **לאטי.** לאט שלי, לשון נחת (ישעיה ח ו) ההולכים לאט, (ש''ב יח ה) לאט לי לנער. לאטי הלמ''ד מן היסוד ואינה משמשת, אתנהל נחת שלי: **לרגל המלאכה.** לפי צורך הליכת רגלי המלאכה המטלת עלי להוליך: **ולרגל הילדים.** לפי רגליהם שהם יכולים לילך: **עד אשר אבא אל אדני שעירה.** הרחיב לו הדרך, שלא היה דעתו ללכת אלא עד סכות. אמר אם דעתו לעשות לי רעה ימתין עד בואי אצלו, והוא לא הלך. ואימתי ילך, בימי המשיח, שנאמר (עובדיה א כא) ועלו מושעים בהר ציון לשפט את הר עשו. ומדרשי אגדה יש לפרשה זו רבים:
@976 **ויאמר למה זה.** תעשה לי טובה זו שאיני צריך לה: **אמצא חן בעיני אדני.** ולא תשלם לי עתה שום גמול:
@977 **וישב ביום ההוא עשו לדרכו.** עשו לבדו וארבע מאות איש שהלכו עמו נשמטו מאצלו אחד אחד. והיכן פרע להם הקדוש ברוך הוא, בימי דוד, שנאמר (ש''א ל יז) כי אם ארבע מאות איש נער אשר רכבו על הגמלים:
@978 **ויבן לו בית.** שהה שם שמונה עשר חדש, קיץ וחרף וקיץ. סכות קיץ, בית חורף, סכות קיץ:
@979 **שלם.** שלם בגופו, שנתרפא מצליעתו. שלם בממונו, שלא חסר כלום מכל אותו דורון. שלם בתורתו, שלא שכח תלמודו בבית לבן: **עיר שכם.** כמו לעיר, וכמוהו (רות א יט) עד בואנה בית לחם: **בבאו מפדן ארם.** כאדם האומר לחברו יצא פלוני מבין שני אריות ובא שלם, אף כאן ויבא שלם מפדן ארם, מלבן ומעשו שנזדוגו לו בדרך:
@980 **קשיטה.** מעה. אמר רבי עקיבא כשהלכתי לכרכי הים היו קורין למעה קשיטה (ותרגומו חרפן, טובים, חריפים בכל מקום, כגון עובר לסוחר) :
@981 **ויקרא לו אל אלהי ישראל.** לא שהמזבח קרוי אלהי ישראל, אלא על שם שהיה הקדוש ברוך הוא עמו והצילו קרא שם המזבח על שם הנס, להיות שבחו של מקום נזכר בקריאת השם, כלומר מי שהוא אל הוא הקדוש ברוך הוא הוא לאלהים לי ששמי ישראל, וכן מצינו במשה (שמות יז טו) ויקרא שמו ה' נסי, לא שהמזבח קרוי ה', אלא על שם הנס קרא שם המזבח, להזכיר שבחו של הקדוש ברוך הוא, ה' הוא נסי. ורבותינו דרשוהו שהקדוש ברוך הוא קראו ליעקב אל. ודברי תורה (ירמיה כג כט) כפטיש יפצץ סלע, מתחלקים לכמה טעמים, ואני לישב פשוטו ושמועו של מקרא באתי:
@982 **בת לאה.** ולא בת יעקב, אלא על שם יציאתה נקראת בת לאה, שאף היא יצאנית היתה, שנאמר (ל טז) ותצא לאה לקראתו (ועליה משלו המשל (יחזקאל טז מד) כאמה בתה) :
@983 **וישכב אתה.** כדרכה: **ויענה.** שלא כדרכה:
@984 **על לב הנערה.** דברים המתישבין על הלב, ראי אביך בחלקת שדה קטנה כמה ממון בזבז, אני אשאך ותקני העיר וכל שדותיה:
@988 **וכן לא יעשה.** לענות את הבתולות, שהאמות גדרו עצמן מן העריות על ידי המבול:
@989 **חשקה.** חפצה:
@993 **מהר.** כתבה:
@994 **במרמה.** בחכמה: **אשר טמא.** הכתוב אומר שלא היתה רמיה, שהרי טמא את דינה אחותם:
@995 **חרפה הוא.** שמץ פסול הוא אצלנו, הבא לחרף חברו הוא אומר לו ערל אתה, או בן ערל. חרפה בכל מקום גדוף:
@996 **נאות לכם.** נתרצה לכם, לשון (מ''ב יב ט) ויאותו: **להמל.** להיות נמול, אינו לשון לפעול אלא לשון להפעל:
@997 **ונתנו.** נו''ן שניה מדגשת, לפי שהיא משמשת במקום שתי נוני''ן ונתננו: **ואת בנתיכם נקח לנו.** אתה מוצא בתנאי שאמר חמור ליעקב ובתשובת בני יעקב לחמור שתלו החשיבות בבני יעקב, לקח בנות שכם את שיבחרו להם ובנותיהם יתנו להם לפי דעתם, דכתיב ונתנו את בנותינו, לפי דעתנו, ואת בנותיכם נקח לנו, ככל אשר נחפוץ. וכשדברו חמור ושכם בנו אל יושבי עירם הפכו הדברים (פסוק כא) את בנתם נקח לנו לנשים ואת בנתינו נתן להם, כדי לרצותם שיאותו להמול:
@1002 **שלמים.** בשלום ובלב שלם: **והארץ הנה רחבת ידים.** כאדם שידו רחבה וותרנית, כלומר לא תפסידו כלום, פרקמטיא הרבה באה לכאן ואין לה קונים:
@1003 **בהמול.** בהיות נמול:
@1004 **אך נאותה להם.** לדבר זה, ועל ידי כן ישבו אתנו:
@1006 **שני בני יעקב.** בניו היו, ואף על פי כן נהגו עצמן שמעון ולוי, כשאר אנשים שאינם בניו, שלא נטלו עצה המנו: **אחי דינה.** לפי שמסרו עצמן עליה נקראו אחיה: **בטח.** שהיו כואבים. ומדרש אגדה בטוחים היו על כחו של זקן:
@1008 **על החללים.** לפשט את החללים:
@1010 **חילם.** ממונם וכן (דברים ח יז) עשה לי את החיל הזה, (במדבר כד יח) וישראל עשה חיל, (תהלים מט יא) ועזבו לאחרים חילם: **שבו.** לשון שביה לפיכך טעמו מלרע:
@1011 **עכרתם.** לשון מים עכורים, אין דעתי צלולה עכשיו. ואגדה, צלולה היתה החבית ועכרתם אותה, מסורת היתה ביד כנענים שיפלו ביד בני יעקב, אלא שהיו אומרים (שמות כג ל) עד אשר תפרה ונחלת את הארץ, לפיכך היו שותקין: **מתי מספר.** אנשים מועטים:
@1012 **הכזונה.** הפקר: **את אחותנו.** ית אחתנא:
@1013 **קום עלה.** לפי שאחרת בדרך נענשת ובא לך זאת מבתך:
@1014 **הנכר.** שיש בידכם משלל שלשכם: **והטהרו.** מעבודה זרה: **והחליפו שמלתיכם.** שמא יש בידכם כסות של עבודה זרה:
@1016 **האלה.** מין אילן סרק: **עם שכם.** אצל שכם:
@1017 **חתת.** פחד:
@1019 **אל בית אל.** הקדוש ברוך הוא בבית אל גלוי שכינתו בבית אל. יש תבה חסרה בי''ת המשמשת בראשה, כמו (ש''ב ט ד) הנה הוא בית מכיר בן עמיאל, כמו בבית מכיר, (להלן לח יא) בית אביך כמו בבית אביך: **נגלו אליו האלהים.** במקומות הרבה יש שם אלהות ואדנות בלשון רבים, כמו (להלן לט כ) אדני יוסף, (שמות כב יד) אם בעליו עמו, ולא נאמר בעלו, וכן אלהות שהוא לשון שופט ומרות נזכר בלשון רבים, אבל אחד מכל שאר השמות לא תמצא בלשון רבים:
@1020 **ותמת דברה.** מה ענין דבורה בבית יעקב, אלא לפי שאמרה רבקה ליעקב (כז מה) ושלחתי ולקחתיך משם, שלחה דבורה אצלו לפדן ארם לצאת משם, ומתה בדרך. מדברי רבי משה הדרשן למדתיה: **מתחת לבית אל.** העיר יושבת בהר ונקברה ברגלי ההר: **תחת האלון.** בשפולי מישרא, שהיה מישור מלמעלה בשפוע ההר והקבורה מלמטה, ומישור של בית אל היו קורין לו אלון. ואגדה נתבשר שם באבל שני, שהגד לו על אמו שמתה. ואלון בלשון יוני אחר. ולפי שהעלימו את יום מותה, שלא יקללו הבריות הכרס שיצא ממנו עשו, אף הכתוב לא פרסמו:
@1021 **עוד.** פעם שני במקום הזה, אחד בלכתו ואחד בשובו: **ויברך אתו.** ברכת אבלים:
@1022 **לא יקרא שמך עוד יעקב.** לשון אדם הבא במארב ועקבה אלא לשון שר ונגיד:
@1023 **אני אל שדי.** שאני כדאי לברך, שהברכות שלי: **פרה ורבה.** על שם שעדין לא נלד בנימין ואף על פי שכבר נתעברה ממנו: **גוי.** בנימין: **גוים.** מנשה ואפרים שעתידים לצאת מיוסף, והם במנין השבטים: **ומלכים.** שאול ואיש בשת שהיו משבט בנימין, שעדין לא נלד. (ופסוק זה דרשו אבנר כשהמליך איש בשת, ואף השבטים דרשוהו וקרבו בנימין, דכתיב (שופטים כא א) איש ממנו לא יתן את בתו לבנימן לאשה, וחזרו ואמרו אלמלא היה עולה מן השבטים לא היה הקדוש ברוך הוא אומר ליעקב ומלכים מחלציך יצאו) : **גוי וקהל גוים.** שגוים עתידים בניו להעשות כמנין הגוים שהם שבעים אמות, וכן כל הסנהדרין שבעים. דבר אחר שעתידים בניו להקריב אסור במות כגוים בימי אליהו:
@1026 **במקום אשר דבר אתו.** איני יודע מה מלמדנו:
@1028 **כברת הארץ.** מנחם פרש לשון כביר, רבוי, מהלך רב. ואגדה בזמן שהארץ חלולה ומנקבת ככברה שהניר מצוי, הסתו עבר, והשרב עדין לא בא. ואין זה פשוטו של מקרא, שהרי בנעמן מצינו (מ''ב ה יט) וילך מאתו כברת ארץ. ואומר אני שהוא שם מדת קרקע כמו מהלך פרסה או יותר, כמו שאתה אומר (ישעיה ה י) צמדי כרם, (לעיל לג יט) חלקת השדה, כך במהלך אדם נותן שם מדה כברת ארץ:
@1029 **כי גם זה.** נוסף לך על יוסף. ורבותינו דרשו עם כל שבט נלדה תאומה, ועם בנימין נלדה תאומה יתרה:
@1030 **בן אוני.** בן צערי: **בנימין.** נראה בעיני לפי שהוא לבדו נלד בארץ כנען, שהיא בנגב כשאדם בא מארם נהרים, כמו שנאמר (במדבר לג מ) בנגב בארץ כנען, (לעיל יב ט) הלוך ונסוע הנגבה: **בנימין.** בן ימין, לשון (תהלים פט יג) צפון וימין אתה בראתם, לפיכך הוא מלא:
@1034 **בשכן ישראל בארץ ההוא.** עד שלא בא לחברון אצל יצחק ארעוהו כל אלה: **וישכב.** מתוך שבלבל משכבו מעלה עליו הכתוב כאלו שכבה. ולמה בלבל וחלל יצועו, שכשמתה רחל נטל יעקב מטתו שהיתה נתונה תדיר באהל רחל ולא בשאר אהלים ונתנה באהל בלהה, בא ראובן ותבע עלבון אמו, אמר אם אחות אמי היתה צרה לאמי, שפחת אחות אמי תהא צרה לאמי, לכן בלבל: **ויהיו בני יעקב שנים עשר.** מתחיל לענין ראשון משנלד בנימין נשלמה המטה, ומעתה ראוים להמנות, ומנאן. ורבותינו דרשו ללמדנו בא שכלן שוין, וכלן צדיקים, שלא חטא ראובן:
@1035 **בכור יעקב.** אפלו בשעת הקלקלה קראו בכור: **בכור יעקב.** בכור לנחלה, בכור לעבודה, בכור למנין, ולא נתנה בכורה ליוסף אלא לענין השבטים שנעשה לשני שבטים:
@1039 **ממרא.** שם המישור: **קרית הארבע.** שם העיר ממרא קרית הארבע אל מישור של קרית ארבע. ואם תאמר היה לו לכתוב ממרא הקרית ארבע, כן דרך המקרא בכל דבר ששמו כפול, כגון זה, וכגון בית לחם, אבי עזר, בית אל, אם הוצרך להטיל בו ה''א נותנה בראש התבה השניה (ש''א טז א) בית הלחמי, (שופטים ו כד) בעפרת אבי העזרי, (מ''א טז לד) בנה חיאל בית האלי:
@1041 **ויגוע יצחק.** אין מקדם ומאחר בתורה, מכירתו של יוסף קדמה למיתתו של יצחק שתים עשרה שנה, שהרי כשנלד יעקב היה יצחק בן ששים שנה, שנאמר (לעיל כה כו) ויצחק בן ששים שנה וגו' , ויצחק מת בשנת מאה ועשרים ליעקב, אם תוציא ששים ממאה ושמונים שנה, נשארו מאה ועשרים, ויוסף נמכר בן שבע עשרה שנה, ואותה שנה שנת מאה ושמונה ליעקב. כיצד, בן ששים ושלש נתברך, וארבע עשרה שנה נטמן בבית עבר, הרי שבעים ושבע, וארבע עשרה עבד באשה, ובסוף ארבע עשרה נלד יוסף, שנאמר (לעיל ל כה) ויהי כאשר ילדה רחל את יוסף וגו' , הרי תשעים ואחת, ושבע עשרה עד שלא נמכר יוסף הרי מאה ושמנה. (עוד מפורש מן המקרא משנמכר יוסף עד שבא יעקב מצרימה עשרים ושתים שנה, שנאמר (להלן מא מו) ויוסף בן שלשים שנה וגו' , ושבע שנים שובע ושנתים רעב הרי עשרים ושתים, וכתיב ימי שני מגורי שלשים ומאת שנה נמצא יעקב במכירתו מאה ושמונה) :
@1043 **עדה בת אילון.** היא (לעיל כו לד) בשמת בת אילון, ונקראת בשמת על שם שהיתה מקטרת בשמים לעבודה זרה: **אהליבמה.** היא יהודית, והוא כנה שמה יהודית לומר שהיא כופרת בעבודה זרה כדי להטעות את אביו: **בת ענה בת צבעון.** אם בת ענה לא בת צבעון, ענה בנו של צבעון, שנאמר (פסוק כד) ואלה בני צבעון ואיה וענה, מלמד שבא צבעון על כלתו אשת ענה ויצאת אהליבמה מבין שניהם והודיעך הכתוב שכלן בני ממזרות היו:
@1044 **בשמת בת ישמעאל.** ולהלן קורא לה (כח ט) מחלת. מצינו באגדת מדרש ספר שמואל (פרק יז) שלשה מוחלין להן עונותיהם גר שנתגיר, והעולה לגדלה, והנושא אשה, ולמד הטעם מכאן, לכך נקראת מחלת שנמחלו עונותיה: **אחות נביות.** על שם שהוא השיאה לו משמת ישמעאל נקראת על שמו:
@1046 **ואהליבמה ילדה** וגו' **.** קרח זה ממזר היה ובן אליפז היה, שבא על אשת אביו אל אהליבמה אשת עשו שהרי הוא מנוי עם (פסוק טז) אלופי אליפז בסוף הענין:
@1047 **וילך אל ארץ.** לגור באשר ימצא:
@1048 **ולא יכלה ארץ מגוריהם.** להספיק מרעה לבהמות שלהם. ומדרש אגדה (פסוק ו) מפני יעקב אחיו, מפני שטר חוב של גזרת (טו יג) כי גר יהיה זרעך, המטל על זרעו של יצחק, אמר אלך לי מכאן, אין לי חלק לא במתנה שנתנה לו הארץ הזאת, ולא בפרעון השטר. ומפני הבושה, שמכר בכורתו:
@1050 **ואלה.** התולדות שהולידו בניו עכשיו משהלך לשעיר:
@1053 **ותמנע היתה פילגש.** להודיע גדלתו של אברהם כמה היו תאבים לדבק בזרעו. תמנע זו בת אלופים היתה, שנאמר (פסוק כב) ואחות לוטן תמנע, ולוטן מאלופי יושבי שעיר היה, מן החורים שישבו בה לפנים, אמרה איני זוכה להנשא לך, הלואי ואהיה פילגש. ובדברי הימים מונה אותה (דברי הימים א' א לו) בבניו של אליפז, מלמד שבא על אשתו של שעיר ויצאה תמנע מביניהם, וכשגדלה נעשית פילגשו, וזהו ואחות לוטן תמנע, ולא מנאה עם בני שעיר שהיתה אחותו מן האם ולא מן האב:
@1056 **אלה אלופי בני עשו.** ראשי משפחות:
@1061 **ישבי הארץ.** שהיו יושביה קודם שבא עשו לשם. ורבותינו דרשו שהיו בקיאין בישובה של ארץ, מלא קנה זה לזיתים מלא קנה זה לגפנים, שהיו טועמין העפר ויודעים אי זו נטיעה ראויה לה:
@1065 **ואיה וענה.** וי''ו יתרה, והוא כמו איה וענה, והרבה יש במקרא (דניאל ח יג) תת וקדש וצבא מרמס, (תהלים עו ז) נרדם ורכב וסוס: **הוא ענה.** האמור למעלה (פסוק כ) שהוא אחיו של צבעון וכאן הוא קורא אותו בנו, מלמד שבא צבעון על אמו והוליד את ענה: **את הימם.** פרדים, הרביע חמור על סוס נקבה וילדה פרד, והוא היה ממזר והביא פסולין לעולם. ולמה נקרא שמם ימים, שאימתן מטלת על הבריות, דאמר רבי חנינא מימי לא שאלני אדם על מכת פרדה לבנה וחיה (והלא קא חזינן דחיה, אל תקרי וחיה אלא וחיתה, כי המכה לא תרפא לעולם) . ולא הזקק לכתוב לנו משפחות החורי אלא מפני תמנע, ולהודיע גדלת זרע אברהם, כמו שפרשתי למעלה (פסוק יב) :
@1072 **ואלה המלכים** וגו' **.** שמנה היו וכנגדן העמיד יעקב ובטל מלכות עשו בימיהם, ואלו הן שאול, ואיש בשת, דוד, ושלמה, רחבעם, אביה, אסא, יהושפט. ובימי יורם בנו כתיב (מ''ב ח כ) בימיו פשע אדום מתחת יד יהודה וימלכו עליהם מלך, ובימי שאול כתיב (מ''א כב מח) ומלך אין באדום נצב מלך:
@1074 **יובב בן זרח מבצרה.** בצרה מערי מואב היא, שנאמר (ירמיה מח כד) ועל קריות ועל בצרה וגו' , ולפי שהעמידה מלך לאדום, עתידה ללקות עמהם, שנאמר (ישעיה לד ו) כי זבח לה' בבצרה:
@1076 **המכה את מדין בשדה מואב.** שבא מדין על מואב למלחמה, והלך מלך אדום לעזור את מואב. ומכאן אנו למדים שהיו מדין ומואב מריבים זה עם זה, ובימי בלעם עשו שלום להתקשר על ישראל:
@1080 **בת מי זהב.** שהיה אומר מהו זהב, עשיר היה ואין זהב חשוב בעיניו לכלום:
@1081 **ואלה שמות אלופי עשו.** שנקרא על שם מדינותיהם לאחר שמת הדר ופסקה מהם מלכות. והראשונים הנזכרים למעלה, הם שמות תולדותם, וכן מפורש בדברי הימים (דברי הימים א' א נא) וימת הדד ויהיו אלופי אדום אלוף תמנע וגו' :
@1084 **מגדיאל.** היא רומי:
@1085 **וישב יעקב** וגו' **.** אחר שכתב לך ישובי עשו ותולדותיו בדרך קצרה, שלא היו ספונים וחשובים לפרש היאך נתישבו וסדר מלחמותיהם איך הורישו את החורים, פרש לך ישובי יעקב ותולדותיו בדרך ארכה כל גלגולי סבתם, לפי שהם חשובים לפני המקום להאריך בהם. וכן אתה מוצא בעשרה דורות שמאדם ועד נח, פלוני הוליד פלוני, וכשבא לנח האריך בו. וכן בעשרה דורות שמנח ועד אברהם קצר בהם, ומשהגיע אצל אברהם האריך בו. משל למרגלית שנפלה בין החול, אדם ממשמש בחול וכוברו בכברה עד שמוצא את המרגלית, ומשמצאה הוא משליך את הצרורות מידו ונוטל המרגלית. (דבר אחר וישב יעקב הפשתני הזה נכנסו גמליו טעונים פשתן, הפחמי תמה אנה יכנס כל הפשתן הזה, היה פקח אחד משיב לו ניצוץ אחד יוצא ממפוח שלך ששורף את כלו, כך יעקב ראה כל האלופים הכתובים למעלה, תמה ואמר מי יכול לכבוש את כלן, מה כתיב למטה (פסוק ב) אלה תולדות יעקב יוסף, דכתיב (עובדיה א יח) והיה בית יעקב אש ובית יוסף להבה ובית עשו לקש, ניצוץ יוצא מיוסף שמכלה ושורף את כלם) :
@1086 **אלה תולדות יעקב.** ואלה של תולדות יעקב, אלה ישוביהם וגלגוליהם עד שבאו לכלל ישוב. סבה ראשונה יוסף בן שבע עשרה וגו' על ידי זה נתגלגלו וירדו למצרים. זהו אחר פשוטו של מקרא להיות דבר דבור על אפניו. ומדרש אגדה דורש, תלה הכתוב תולדות יעקב ביוסף מפני כמה דברים, אחת שכל עצמו של יעקב לא עבד אצל לבן אלא ברחל, ושהיה זיו אקונין של יוסף דומה לו, וכל מה שארע ליעקב ארע ליוסף, זה נשטם וזה נשטם, זה אחיו מבקש להרגו וזה אחיו מבקשים להרגו, וכן הרבה בבראשית רבה (סד ו) . ועוד נדרש בו וישב בקש יעקב ישב בשלוה, קפץ עליו רגזו של יוסף. צדיקים מבקשים לישב בשלוה אמר הקדוש ברוך הוא לא דין לצדיקים מה שמתקן להם לעולם הבא, אלא שמבקשים לישב בשלוה בעולם הזה: **והוא נער.** שהיה עושה מעשה נערות, מתקן בשערו ממשמש בעיניו, כדי שיהיה נראה יפה: **את בני בלהה.** כלומר ורגיל אצל בני בלהה, לפי שהיו אחיו מבזין אותן והוא מקרבן: **את דבתם רעה.** כל רעה שהיה רואה באחיו בני לאה היה מגיד לאביו, שהיו אוכלין אבר מן החי, ומזלזלין בבני השפחות לקרותן עבדים, וחשודים על העריות. ובשלשתן לקה. על אבר מן החי (לעיל פסוק לא) וישחטו שעיר עזים במכירתו, ולא אכלוהו חי. ועל דבה שספר עליהם שקורין לאחיהם עבדים, (תהלים קה יז) לעבד נמכר יוסף. ועל העריות שספר עליהם, (להלן לט ז) ותשא אשת אדניו וגו' : **דבתם.** כל לשון דבה פרלידי''ץ בלע''ז [רכילות] כל מה שהיה יכול לדבר בהם רעה היה מספר: **דבה.** לשון (שיה''ש ז י) דובב שפתי ישנים:
@1087 **בן זקונים.** שנלד לו לעת זקנתו. ואונקלוס תרגם בר חכים הוא ליה כל מה שלמד משם ועבר מסר לו. דבר אחר שהיה זיו אקונין שלו דומה לו: **פסים.** לשון כלי מלת, כמו (אסתר א ו) כרפס ותכלת, וכמו (שמואל ב' יג יח) כתנת הפסים, דתמר ואמנון. ומדרש אגדה על שם צרותיו שנמכר לפוטיפר ולסוחרים ולישמעאלים ולמדינים:
@1088 **ולא יכלו דברו לשלום.** מתוך גנותם למדנו שבחם, שלא דברו אחת בפה ואחת בלב: **דברו.** לדבר עמו:
@1091 **מאלמים אלמים.** כתרגומו מאסרין אסרן, עמרין, וכן (תהלים קכו ו) נשא אלמתיו, וכמוהו בלשון משנה (בבא מציעא כב ב) והאלמות נוטל ומכריז: **קמה אלמתי.** נזקפה: **וגם נצבה.** לעמוד על עמדה בזקיפה:
@1092 **ועל דבריו.** על דבתם רעה שהיה מביא לאביהם:
@1094 **ויספר אל אביו ואל אחיו.** לאחר שספר אותו לאחיו חזר וספרו לאביו בפניהם: **ויגער בו.** לפי שהיה מטיל שנאה עליו: **הבוא נבוא.** והלא אמך כבר מתה. והוא לא היה יודע שהדברים מגיעין לבלהה, שגדלתו כאמו. ורבותינו למדו מכאן שאין חלום בלא דברים בטלים. ויעקב נתכון להוציא הדבר מלב בניו שלא יקנאוהו, לכך אמר לו הבוא נבוא וגו' , כשם שאי אפשר באמך כך השאר הוא בטל:
@1095 **שמר את הדבר.** היה ממתין ומצפה מתי יבא, וכן (ישעיה כו ב) שומר אמונים וכן (איוב יד טז) לא תשמר על חטאתי, לא תמתין:
@1096 **לרעות את צאן.** נקוד על את, שלא הלכו אלא לרעות את עצמן:
@1097 **הנני.** לשון ענוה וזריזות, נזדרז למצות אביו, ואף על פי שהיה יודע באחיו ששונאין אותו:
@1098 **מעמק חברון.** והלא חברון בהר, שנאמר (במדבר יג כב) ויעלו בנגב ויבא עד חברון, אלא מעצה עמוקה של אותו צדיק הקבור בחברון, לקים מה שנאמר לאברהם בין הבתרים (לעיל טו יג) כי גר יהיה זרעך: **ויבא שכמה.** מקום מוכן לפרענות, שם קלקלו השבטים, שם ענו את דינה, שם נחלקה מלכות בית דוד, שנאמר (מ''א י''ב א) וילך רחבעם שכמה וגו' :
@1099 **וימצאהו איש.** זה גבריאל שנאמר (דניאל ט כא) והאיש גבריאל:
@1101 **נסעו מזה.** הסיעו עצמן מן האחוה: **נלכה דתינה.** לבקש לך נכלי דתות שימיתוך בהם. ולפי פשוטו שם מקום הוא, ואין מקרא יוצא מידי פשוטו:
@1102 **ויתנכלו.** נתמלאו נכלים וערמומיות: **אתו.** כמו אתו, עמו, כלומר אליו:
@1104 **ונראה מה יהיו חלומותיו.** אמר ר' יצחק מקרא זה אומר דרשני, רוח הקדש אומרת כן. הם אומרים נהרגהו, והכתוב מסים ונראה מה יהיו חלומותיו, נראה דבר מי יקום או שלכם או שלי. ואי אפשר שיאמרו הם ונראה מה יהיו חלומותיו מכיון שיהרגוהו בטלו חלומותיו:
@1105 **לא נכנו נפש.** מכת נפש זו היא מיתה:
@1106 **למען הציל אותו.** רוח הקודש מעיד על ראובן שלא אמר זאת אלא להציל אותו, שיבא הוא ויעלנו משם, אמר אני בכור וגדול שבכלן, לא יתלה הסרחון אלא בי:
@1107 **את כתנתו.** זה חלוק: **את כתנת הפסים.** היא שהוסיף לו אביו יותר על אחיו:
@1108 **והבור רק אין בו מים.** ממשמע שנאמר והבור רק, איני יודע שאין בו מים, מה תלמוד לומר אין בו מים, מים אין בו אבל נחשים ועקרבים יש בו:
@1109 **ארחת.** כתרגומו שירת, על שם הולכי ארח: **וגמליהם נשאים** וגו' **.** למה פרסם הכתוב את משאם, להודיע מתן שכרן של צדיקים, שאין דרכן של ערביים לשאת אלא נפט ועטרן שריחן רע, ולזה נזדמנו בשמים שלא יזק מריח רע: **נכאת.** כל כנוסי בשמים הרבה קרוי נכאת וכן (מ''ב כ יג) ויראם את כל בית נכתה, מרקחת בשמיו, ואונקלוס תרגמו לשון שעוה: **וצרי.** שרף הנוטף מעצי הקטף, והוא (שמות ל לד) נטף, הנמנה עם סמני הקטורת: **ולט.** לוטס שמו בלשון משנה (שביעית ז ו) . ורבותינו פירשוהו לשון שרש עשב ושמו אשטורוזי''א (במסכת נדה ח א) :
@1110 **מה בצע.** מה ממון, כתרגומו: **וכסינו את דמו.** ונעלים את מיתתו:
@1111 **וישמעו.** וקבילו מניה. וכל שמיעה שהיא קבלת דברים כגון זה וכגון (לעיל כח ז) וישמע יעקב אל אביו, (שמות כד ז) נעשה ונשמע, מתרגם נקבל, וכל שהוא שמיעת האזן, כגון (בראשית ג ח) וישמעו את קול ה' אלהים מתהלך בגן, (שם כז ה) ורבקה שומעת, (שם לה כב) וישמע ישראל, (שמות טז יב) שמעתי את תלונת, כלן מתרגם ושמעו, ושמעת, ושמע, שמיע קדמי:
@1112 **ויעברו אנשים מדינים.** זו היא שירה אחרת, והודיעך הכתוב שנמכר פעמים הרבה: **וימשכו.** בני יעקב את יוסף מן הבור וימכרוהו לישמעאלים, והישמעאלים למדינים, והמדינים למצרים:
@1113 **וישב ראובן.** במכירתו לא היה שם, שהגיע יומו לילך ולשמש את אביו. דבר אחר עסוק היה בשקו ובתעניתו על שבלבל יצועי אביו:
@1114 **אנה אני בא.** אנה אברח מצערו של אבא:
@1115 **שעיר עזים.** דמו דומה לשל אדם: **הכתנת.** זה שמה, וכשהיא דבוקה לתבה אחרת כגון (פסוק לא) כתנת יוסף, (פסוק ג) כתנת פסים, (ויקרא טז ד) כתנת בד, נקוד כתנת:
@1117 **ויאמר כתנת בני.** היא זו: **חיה רעה אכלתהו.** נצנצה בו רוח הקדש, סופו שתתגרה בו אשת פוטיפר. ולמה לא גלה לו הקדוש ברוך הוא, לפי שהחרימו וקללו את כל מי שיגלה, ושתפו להקדוש ברוך הוא עמהם, אבל יצחק היה יודע שהוא חי, אמר היאך אגלה והקדוש ברוך הוא אינו רוצה לגלות לו:
@1118 **ימים רבים.** עשרים ושתים שנה משפרש ממנו עד שירד יעקב למצרים, שנאמר (פס' ב) יוסף בן שבע עשרה שנה וגו' ובן שלשים שנה היה בעמדו לפני פרעה, ושבע שני השובע ושנתים הרעב כשבא יעקב למצרים הרי עשרים ושתים שנה, כנגד עשרים ושתים שנה שלא קים יעקב כבוד אב ואם. עשרים שנה שהיה בבית לבן, ושתי שנים בדרך בשובו מבית לבן, שנה וחצי בסכות וששה חדשים בבית אל וזהו שאמר ללבן לעיל (לא מא) זה לי עשרים שנה בביתך, לי הן, עלי הן, וסופי ללקות כנגדן:
@1119 **וכל בנתיו.** רבי יהודה אומר אחיות תאומות נלדו עם כל שבט ושבט ונשאום. רבי נחמיה אומר כנעניות היו, אלא מהו וכל בנותיו, כלותיו, שאין אדם נמנע מלקרוא לחתנו בנו ולכלתו בתו: **וימאן להתנחם.** אין אדם יכול לקבל תנחומין על החי וסבור שמת, שעל המת נגזרה גזרה שישתכח מן הלב ולא על החי: **ארד אל בני.** כמו על בני, והרבה אל משמשין בלשון על, (ש''ב כא א) אל שאול ואל בית הדמים, (ש''א ד כא) אל הלקח ארון האלהים ואל מות חמיה ואישה: **אבל שאלה.** כפשוטו לשון קבר הוא, באבלי אקבר, ולא אתנחם כל ימי. ומדרשו גיהנם, סימן זה היה מסור בידי מפי הגבורה אם לא ימות אחד מבני בחיי מבטח אני שאיני רואה גיהנם: **ויבך אתו אביו.** יצחק היה בוכה מפני צרתו של יעקב, אבל לא היה מתאבל, שהיה יודע שהוא חי:
@1120 **הטבחים.** שוחטי בהמות המלך:
@1121 **ויהי בעת ההוא.** למה נסמכה פרשה זו לכאן, והפסיק בפרשתו של יוסף, ללמד שהורידוהו אחיו מגדלתו כשראו בצרת אביהם, אמרו אתה אמרת למכרו, אלו אמרת להשיבו היינו שומעים לך: **ויט.** מאת אחיו: **עד איש עדלמי.** נשתתף עמו:
@1122 **כנעני.** תגרא:
@1125 **והיה בכזיב.** שם המקום. ואומר אני על שם שפסקה מלדת נקרא כזיב, לשון (ירמיה טו יח) היו תהיה לי כמו אכזב, (ישעיה נח יא) אשר לא יכזבו מימיו, דאם לא כן מה בא להודיענו. ובבראשית רבה (פה ד) ראיתי ותקרא שמו שלה, פסקת:
@1127 **רע בעיני ה'.** כרעתו של אונן משחית זרעו, שנאמר באונן (פסוק י) וימת גם אותו, כמיתתו של ער מיתתו של אונן, ולמה היה ער משחית זרעו, כדי שלא תתעבר ויכחיש יפיה:
@1128 **והקם זרע.** הבן יקרא על שם המת:
@1129 **ושחת ארצה.** דש מבפנים וזורה מבחוץ:
@1131 **כי אמר** וגו' **.** כלומר דוחה היה אותה בקש, שלא היה בדעתו להשיאה לו: **כי אמר פן ימות.** מחזקת היא זו שימותו אנשיה:
@1132 **ויעל על גזזי צאנו.** ויעל תמנתה לעמוד על גוזזי צאנו:
@1133 **עלה תמנתה.** ובשמשון הוא אומר (שופטים יד א) וירד שמשון תמנתה, בשפוע ההר היתה יושבת, עולין לה מכאן ויורדין לה מכאן:
@1134 **ותתעלף.** כסתה פניה שלא יכיר בה: **ותשב בפתח עינים.** בפתיחת עינים, בפרשת דרכים שעל דרך תמנתה. ורבותינו דרשו בפתחו של אברהם אבינו שכל עינים מצפות לראותו: **כי ראתה כי גדל שלה** וגו' **.** לפיכך הפקירה עצמה אצל יהודה, שהיתה מתאוה להעמיד ממנו בנים:
@1135 **ויחשבה לזונה.** לפי שיושבת בפרשת דרכים: **כי כסתה פניה.** ולא יכול לראותה ולהכירה. ומדרש רבותינו כי כסתה פניה כשהיתה בבית חמיה היתה צנועה, לפיכך לא חשדה:
@1136 **ויט אליה אל הדרך.** מדרך שהיה בה נטה אל הדרך אשר היא בה, ובלשון לע''ז דשטולי''ר : **הבה נא.** הכיני עצמך ודעתך לכך. כל לשון הבה לשון הזמנה הוא, חוץ ממקום שיש לתרגמו בלשון נתינה, ואף אותן של הזמנה קרובים ללשון נתינה הם:
@1137 **ערבון.** משכון:
@1138 **חתמך ופתילך.** עזקתך ושושיפך, טבעת שאתה חותם בה, ושמלתך שאתה מתכסה בה: **ותהר לו.** גבורים כיוצא בו, צדיקים כיוצא בו:
@1141 **הקדשה.** מקדשת ומזמנת לזנות:
@1143 **תקח לה.** יהיה שלה מה שבידה: **פן נהיה לבוז.** אם תבקשנה עוד יתפרסם הדבר ויהיה גנאי, כי מה עלי לעשות עוד לאמת דברי: **הנה שלחתי הגדי הזה.** לפי שרמה יהודה את אביו בגדי עזים, שהטביל כתנת יוסף בדמו, רמוהו גם אותו בגדי עזים:
@1144 **כמשלש חדשים.** רבו של ראשון ורבו של אחרון ואמצעי שלם, ולשון כמשלש חדשים, כהשתלש החדשים, כמו (אסתר ט כב) ומשלוח מנות, (ישעיה יא יד) משלוח ידם, וכן תרגם אנקלוס כתלתות ירחיא: **הרה לזנונים.** שם דבר, מעברת כמו (שמות כא כב) אשה הרה, וכמו (שה''ש ו י) ברה כחמה: **ותשרף.** אמר אפרים מקשאה משום רבי מאיר בתו שלשם היתה, שהוא כהן, לפיכך דנוה בשרפה:
@1145 **הוא מוצאת.** להשרף: **והיא שלחה אל חמיה.** לא רצתה להלבין פניו ולומר ממך אני מעברת, אלא לאיש אשר אלה לו, אמרה אם יודה מעצמו, יודה, ואם לאו ישרפוני, ואל אלבין פניו. מכאן אמרו נוח לו לאדם שיפילוהו לכבשן האש ואל ילבין פני חברו ברבים: **הכר נא.** אין נא אלא לשון בקשה, הכר נא בוראך ואל תאבד שלש נפשות:
@1146 **צדקה.** בדבריה **ממני.** היא מעברת. ורבותינו זכרונם לברכה דרשו שיצאה בת קול ואמרה ממני ומאתי יצאו הדברים, לפי שהיתה צנועה בבית חמיה גזרתי שיצאו ממנה מלכים, ומשבט יהודה גזרתי להעמיד מלכים בישראל: **כי על כן לא נתתיה.** כי בדין עשתה, על אשר לא נתתיה לשלה בני: **ולא יסף עוד.** יש אומרים לא הוסיף. ויש אומרים לא פסק וחברו גבי אלדד ומידד (במדבר יא כה) ולא יספו, ומתרגמנן ולא פסקו:
@1147 **בעת לדתה.** וברבקה הוא אומר (כב כד) וימלאו ימיה ללדת, להלן למלאים וכאן לחסרים: **והנה תאומים.** מלא, ולהלן (כה כד) תומם, חסר, לפי שהאחד רשע, אבל אלו שניהם צדיקים:
@1148 **ויתן יד.** הוציא האחד ידו לחוץ, ולאחר שקשרה על ידו השני החזירה:
@1149 **פרצת.** חזקת עליך חזק:
@1150 **אשר על ידו השני.** ארבע ידות כתובות כאן כנגד ארבעה חרמים שמעל עכן שיצא ממנו. ויש אומרים כנגד ארבעה דברים שלקח, (יהושע ז כא) אדרת שנער, ושני חתכות כסף של מאתים שקלים, ולשון זהב אחד: **ויקרא שמו זרח.** על שם זריחת מראית השני:
@1151 **ויוסף הורד.** חוזר לענין ראשון, אלא שהפסיק בו כדי לסמוך ירידתו של יהודה למכירתו של יוסף לומר לך שבשבילו הורידוהו מגדלתו. ועוד, כדי לסמוך מעשה אשתו של פוטיפר למעשה תמר, לומר לך מה זו לשם שמים אף זו לשם שמים, שראתה באצטרולוגין שלה שעתידה להעמיד בנים ממנו ואינה יודעת אם ממנה אם מבתה:
@1153 **כי ה' אתו.** שם שמים שגור בפיו:
@1154 **וכל יש לו.** הרי לשון קצר, חסר אשר:
@1156 **ולא ידע אתו מאומה.** לא היה נותן לבו לכלום: **כי אם הלחם.** היא אשתו, אלא שדבר בלשון נקיה: **ויהי יוסף יפה תאר.** כיון שראה עצמו מושל, התחיל אוכל ושותה ומסלסל בשערו, אמר הקדוש ברוך הוא אביך מתאבל ואתה מסלסל בשערך, אני מגרה בך את הדב, מיד
@1157 **ותשא אשת אדניו** וגו' **.** כל מקום שנאמר אחר סמוך:
@1159 **וחטאתי לאלהים.** בני נח נצטוו על העריות:
@1160 **לשכב אצלה.** אפלו בלא תשמיש: **להיות עמה.** לעולם הבא:
@1161 **ויהי כהיום הזה.** כלומר ויהי כאשר הגיע יום מיוחד, יום צחוק, יום איד שלהם שהלכו כלם לבית עבודה זרה, אמרה אין לי יום הגון להזקק ליוסף כהיום הזה. אמרה להם חולה אני ואיני יכולה לילך: **לעשות מלאכתו.** רב ושמואל, חד אמר מלאכתו ממש, וחד אמר לעשות צרכיו עמה, אלא שנראית לו דמות דיוקנו של אביו וכו' , כדאיתא במסכת סוטה (דף לו ב) :
@1164 **ראו הביא לנו.** הרי זה לשון קצרה, הביא לנו ולא פרש מי הביאו, ועל בעלה אומרת כן: **עברי.** מעבר הנהר, מבני עבר:
@1166 **אדניו.** של יוסף:
@1167 **בא אלי.** לצחק בי העבד העברי אשר הבאת לנו:
@1169 **ויהי כשמע אדניו** וגו' **.** בשעת תשמיש אמרה לו כן, וזהו שאמרה כדברים האלה עשה לי עבדך, עניני תשמיש כ אל ה:
@1171 **ויט אליו חסד.** שיהא מקבל לכל רואיו, לשון כלה נאה וחסודה שבמשנה (כתובות יז א) :
@1172 **הוא היה עשה.** כתרגומו במימריה הוה מתעביד:
@1173 **באשר ה' אתו.** בשביל שה' אתו:
@1174 **אחר הדברים האלה.** לפי שהרגילה אותה ארורה את הצדיק בפי כלם לדבר בו ולגנותו, הביא להם הקדוש ברוך הוא סרחנם של אלו שיפנו אליהם ולא אליו, ועוד שתבוא הרוחה לצדיק על ידיהם: **חטאו.** זה נמצא זבוב בפיילי פוטירין שלו, וזה נמצא צרור בגלוסקין שלו: **והאפה.** את פת המלך ואין לשון אפייה אלא בפת, ובלע''ז פיסטו''ר [אופה]:
@1177 **ויפקד שר הטבחים את יוסף.** להיות אתם: **ויהיו ימים במשמר.** שנים עשר חדש:
@1178 **ויחלמו חלום שניהם.** ויחלמו שניהם חלום, זה פשוטו, ומדרשו כל אחד חלם חלום שניהם, שחלם את חלומו ופתרון חברו, וזהו שנאמר (פסוק טז) וירא שר האופים כי טוב פתר: **איש כפתרון חלמו.** כל אחד חלם חלום הדומה לפתרון העתיד לבא עליהם:
@1179 **זעפים.** עצבים כמו (מ''א כ מג) סר וזעף, (מיכה ז ט) זעף ה' אשא:
@1183 **שריגם.** זמורות ארכות שקורין וידי''ץ בלע''ז : **והיא כפרחת.** דומה לפורחת. והיא כפורחת נדמה לי בחלומי כאלו היא פורחת, ואחר הפרח עלתה נצה ונעשה סמדר, אישפני''ר בלע''ז . ואחר כך הבשילו, והיא כד אפרחת אפיקת לבלבין, עד כאן תרגום של פורחת. נץ גדול מפרח, כדכתיב (ישעיה יח ה) ובוסר גומל יהיה נצה, וכתיב (במדבר יז כג) ויוצא פרח, והדר ויצץ ציץ:
@1184 **ואשחט.** כתרגומו ועצרית, והרבה יש בלשון משנה:
@1185 **שלשת ימים הם.** סימן הם לך לשלשת ימים, ויש מדרשי אגדה הרבה:
@1186 **ישא פרעה את ראשך.** לשון חשבון, כשיפקוד שאר עבדיו לשרת לפניו בסעודה ימנה אתך עמהם: **כנך.** בסיס שלך ומושבך:
@1187 **כי אם זכרתני אתך.** אשר אם זכרתני אתך מאחר שייטב לך כפתרוני: **ועשית נא עמדי חסד.** אין נא אלא לשון בקשה:
@1189 **סלי חרי.** סלים של נצרים קלופים עשוים חורין חורין, ובמקומנו יש הרבה, ודרך מוכרי פת כסנין שקורין אובלידי''ש לתתם באותן סלים:
@1193 **יום הלדת את פרעה.** יום לידתו, וקורין לו יום גינוסיא. ולשון הלדת, לפי שאין הולד נלד אלא על ידי אחרים שהחיה מילדת את האשה, ועל כן החיה נקראת מילדת, וכן (יחזקאל טז ד) ומולדותיך ביום הלדת אותך, וכן (ויקרא יג נה) אחרי הכבס את הנגע, שכבוסו על ידי אחרים: **וישא את ראש** וגו' **.** מנאם עם שאר עבדיו, שהיה מונה המשרתים שישרתו לו בסעודתו, וזכר את אלו בתוכם, כמו (במדבר א ב) שאו את ראש, לשון מנין:
@1196 **ולא זכר שר המשקים.** בו ביום: **וישכחהו.** לאחר מכן. מפני שתלה בו יוסף בטחונו לזכרו, הזקק להיות אסור עוד שתי שנים, שנאמר (תהלים מ ה) אשרי הגבר אשר שם ה' מבטחו ולא פנה אל רהבים, ולא בטח על מצרים הקרוים (ישעיה ל ז) רהב:
@1197 **ויהי מקץ.** כתרגומו מסוף, וכל לשון קץ סוף הוא: **על היאר.** כל שאר נהרות אינם קרויין יאורים חוץ מנילוס, מפני שכל הארץ עשוים יאורים יאורים בידי אדם ונילוס עולה בתוכם ומשקה אותם, לפי שאין גשמים יורדין במצרים תדיר כשאר ארצות:
@1198 **יפות מראה.** סימן הוא לימי שובע, שהבריות נראות יפות זו לזו, שאין עין בריה צרה בחברתה: **באחו.** באגם, מריש''ק בלע''ז , כמו (איוב ח יא) ישגא אחו:
@1199 **ודקות בשר.** טינבי''ש בלע''ז , לשון דק:
@1200 **ותאכלנה.** סימן שתהא כל שמחת השובע נשכחת בימי הרעב:
@1201 **בקנה אחד.** טודי''ל בלע''ז : **בריאות.** שייני''ש בלע''ז :
@1202 **ושדופת.** השלידי''ש בלע''ז ושקיפן קדום, חבוטות לשון משקוף החבוט תמיד על ידי הדלת המכה עליו: **קדים.** רוח מזרחית שקורין ביש''א :
@1203 **הבריאות.** שייני ''ש בלע''ז : **והנה חלום.** והנה נשלם חלום שלם לפניו והצרך לפותרים:
@1204 **ותפעם רוחו.** ומטרפא רוחה מקשקשת בתוכו כפעמון. ובנבוכדנצר הוא אומר (דניאל ב א) ותתפעם רוחו, לפי שהיו שם שתי פעימות שכחת החלום והעלמת פתרונו: **חרטמי.** הנחרים בטימי מתים, ששואלים בעצמות. טימי, הן עצמות בלשון ארמי, ובמשנה בית שהוא מלא טמיא, מלא עצמות: **ואין פותר אותם לפרעה.** פותרים היו אותם, אבל לא לפרעה, שלא היה קולן נכנס באזניו, ולא היה לו קורת רוח בפתרונם, שהיו אומרים שבע בנות אתה מוליד, שבע בנות אתה קובר:
@1207 **איש כפתרון חלומו.** חלום הראוי לפתרון שנפתר לו ודומה לו:
@1208 **נער עברי עבד.** ארורים הרשעים שאין טובתם שלמה. מזכירו בלשון בזיון: **נער.** שוטה ואין ראוי לגדלה: **עברי.** אפילו לשוננו אינו מכיר: **עבד.** וכתוב בנמוסי מצרים שאין עבד מולך ולא לובש בגדי שרים: **איש כחלומו.** לפי החלום וקרוב לענינו:
@1209 **השיב על כני.** מי שבידו להשיב, והוא פרעה הנזכר למעלה, כמו שאמר (לעיל י) פרעה קצף על עבדיו, הרי מקרא קצר ולא פרש מי השיב, לפי שאין צריך לפרש מי השיב, וכן דרך כל מקראות קצרים על מי שעליו לעשות הם סותמים את הדבר:
@1210 **מן הבור.** מן בית הסוהר שהוא עשוי כמין גמא, וכן כל בור שבמקרא לשון גמא הוא, ואף אם אין בו מים קרוי בור פוש''א בלע''ז : **ויגלח.** מפני כבוד המלכות:
@1211 **תשמע חלום לפתר אתו.** תאזין ותבין חלום לפתר אתו: **תשמע.** לשון הבנה והאזנה, כמו (להלן מב כג) שומע יוסף, (דברים כח מט) אשר לא תשמע לשונו, אינטינדר''א בלע''ז :
@1212 **בלעדי.** אין החכמה משלי אלא אלהים יענה, יתן עניה בפי לשלום פרעה:
@1215 **דלות.** כחושות, כמו (ש''ב יג ד) מדוע אתה ככה דל, דאמנון: **ורקות בשר.** כל לשון רקות שבמקרא חסרי בשר, ובלע''ז בלושי''ש :
@1219 **צנמות.** צונמא בלשון ארמי סלע, הרי הן כעץ בלי לחלוח, וקשות כסלע, ותרגומו נצן לקין, נצן אין בהן אלא הנץ לפי שנתרוקנו מן הזרע:
@1222 **שבע שנים' שבע שנים.** כלן אינן אלא שבע, ואשר נשנה החלום פעמים לפי שהדבר מזמן, כמו שפרש לו בסוף (פסוק לב) ועל השנות החלום וגו' . בשבע שנים הטובות נאמר (פסוק כה) הגיד לפרעה, לפי שהיה סמוך, ובשבע שני רעב נאמר (פסוק כח) הראה את פרעה, לפי שהיה הדבר מפלג ורחוק, נופל בו לשון מראה:
@1226 **ונשכח כל השבע.** הוא פתרון הבליעה:
@1227 **ולא יודע השבע.** הוא פתרון (פסוק כא) ולא נודע כי באו אל קרבנה:
@1228 **נכון.** מזמן:
@1230 **וחמש.** כתרגומו ויזרזון וכן (שמות יג יח) וחמושים:
@1231 **את כל אכל.** שם דבר הוא, לפיכך טעמו באל''ף ונקוד בפתח קטן, ואוכל שהוא פועל, כגון (ויקרא ז כה) כי כל אכל חלב, טעמו למטה בכף ונקוד קמץ קטן: **תחת יד פרעה.** ברשותו ובאוצרותיו:
@1232 **והיה האכל.** הצבור כשאר פקדון הגנוז לקיום הארץ:
@1234 **הנמצא כזה.** הנשכח כדין, אם נלך ונבקשנו הנמצא כמוהו. הנמצא לשון תמיהה, וכן כל ה''א המשמשת בראש תבה ונקודה בחטף פתח:
@1235 **אין נבון וחכם כמוך.** לבקש איש נבון וחכם שאמרת, לא נמצא כמוך:
@1236 **ישק.** יתזן, יתפרנס. כל צרכי עמי יהיו נעשים על ידך, כמו (לעיל טו ב) ובן משק ביתי, וכמו (תהלים ב יב) נשקו בר, גרנישו''ן בלע''ז : **רק הכסא.** שיהיו קורין לי מלך: **כסא.** לשון שם המלוכה כמו (מלכים א א לז) ויגדל את כסאו מכסא אדני המלך:
@1237 **נתתי אתך.** מניתי יתך, ואף על פי כן לשון נתינה הוא, כמו (דברים כו יט) ולתתך עליון, בין לגדלה בין לשפלות נופל לשון נתינה עליו, כמו (מלאכי ב ט) נתתי אתכם נבזים ושפלים:
@1238 **ויסר פרעה את טבעתו.** נתינת טבעת המלך הוא אות למי שנותנה לו להיות שני לו לגדלה: **בגדי שש.** דבר חשיבות הוא במצרים: **רבד.** ענק, ועל שהוא רצוף בטבעות קרוי רביד. וכן (משלי ז טז) רבדתי ערשי, רצפתי ערשי מרצפות. בלשון משנה (מדות א ח) מקף רבדין של אבן, (יומא מג ב) על הרובד שבעזרה, והיא רצפה:
@1239 **במרכבת המשנה.** השניה למרכבתו, המהלכת אצל שלו: **אברך.** כתרגומו דין אבא למלכא. רך בלשון ארמי מלך. בהשותפין (בבא בתרא ד א) לא ריכא ולא בר ריכא. ובדברי אגדה דרש ר' יהודה אברך זה יוסף שהוא אב בחכמה ורך בשנים, אמר לו רבי יוסי בן דורמסקית עד מתי אתה מעות עלינו את הכתובים, אין אברך אלא לשון ברכים, שהכל היו נכנסין ויוצאין תחת ידו, כענין שנאמר ונתון אותו וגו' :
@1240 **אני פרעה.** שיש יכולת בידי לגזור גזרות על מלכותי, ואני גוזר שלא ירים איש את ידו: **ובלעדיך.** שלא ברשותך. דבר אחר אני פרעה אני אהיה מלך ובלעדיך וגו' וזהו דגמת (פסוק מ) רק הכסא: **את ידו ואת רגלו.** כתרגומו:
@1241 **צפנת פענח.** מפרש הצפונות, ואין לפענח דמיון במקרא: **פוטי פרע.** הוא פוטיפר, ונקרא פוטיפרע על שנסתרס מאליו, לפי שלקח את יוסף למשכב זכר:
@1243 **ותעש הארץ.** כתרגומו, ואין הלשון נעקר מלשון עשייה: **לקמצים.** קומץ על קומץ, יד על יד היו אוצרים:
@1244 **אכל שדה העיר אשר סביבתיה נתן בתוכה.** שכל ארץ וארץ מעמדת פירותיה ונותנין בתבואה מעפר המקום ומעמיד את התבואה מלירקב:
@1245 **עד כי חדל לספר.** עד כי חדל לו הסופר לספר, והרי זה מקרא קצר: **כי אין מספר.** לפי שאין מספר, והרי כי משמש בלשון דהא:
@1246 **בטרם תבוא שנת הרעב.** מכאן שאסור לאדם לשמש מטתו בשני רעבון:
@1251 **ותרעב כל ארץ מצרים.** שהרקיבה תבואתם שאצרו חוץ משל יוסף: **אשר יאמר לכם תעשו.** לפי שהיה יוסף אומר להם שימולו, וכשבאו אצל פרעה ואומרים כך הוא אומר לנו, אמר להם למה לא צברתם בר, והלא הכריז לכם ששני הרעב באים, אמרו לו אספנו הרבה והרקיבה, אמר להם אם כן כל אשר יאמר לכם תעשו, הרי גזר על התבואה והרקיבה, מה אם יגזור עלינו ונמות:
@1252 **על כל פני הארץ.** מי הם פני הארץ, אלו העשירים: **את כל אשר בהם.** כתרגומו די בהון עבורא: **וישבר למצרים.** שבר לשון מכר ולשון קנין הוא, כאן משמש לשון מכר, (להלן מג ב) שברו לנו מעט אכל, לשון קנין. ואל תאמר אינו כי אם בתבואה, שאף ביין וחלב מצינו (ישעיה נה א) ולכו שברו בלא כסף ובלא מחיר יין וחלב:
@1253 **וכל הארץ באו מצרימה לשבר אל יוסף.** (סרסהו ופרשהו וכל הארץ באו מצרים אל יוסף) . אם תפרשהו כסדרו היה צריך לכתוב לשבור מן יוסף:
@1254 **וירא יעקב כי יש שבר במצרים.** ומהיכן ראה, והלא לא ראה אלא שמע, שנאמר (להלן מב ב) הנה שמעתי וגו' , ומהו וירא, ראה באספקלריא של קדש שעדין יש לו שבר סבר במצרים. ולא היתה נבואה ממש להודיעו בפרוש שזה יוסף: **למה תתראו.** למה תראו עצמכם בפני בני ישמעאל ובני עשו כאלו אתם שבעים, שבאותה שעה עדין היה להם תבואה. [ולי נראה כפשוטו למה תתראו, למה יהיו הכל מסתכלין בכם ומתמיהים בכם שאין אתם מבקשים לכם אכל בטרם שיכלה מה שבידכם]. ומפי אחרים שמעתי שהוא לשון כחישה, למה תהיו כחושים ברעב. ודומה לו (משלי יא כה) ומרוה גם הוא יורא:
@1255 **רדו שמה.** ולא אמר לכו, רמז למאתים ועשר שנים שנשתעבדו למצרים, כמנין רד''ו:
@1256 **וירדו אחי יוסף.** ולא כתב בני יעקב, מלמד שהיו מתחרטים במכירתו ונתנו לבם להתנהג עמו באחוה ולפדותו בכל ממון שיפסקו עליהם: **עשרה.** מה תלמוד לומר, והלא כתיב (פסוק ד) ואת בנימין אחי יוסף לא שלח, אלא לענין האחוה היו חלוקין לעשרה, שלא היתה אהבת כלם ושנאת כלם שוה לו, אבל לענין לשבור בר כלם לב אחד להם:
@1257 **פן יקראנו אסון.** ובבית לא יקראנו אסון, אמר רבי אלעזר בן יעקב מכאן שהשטן מקטרג בשעת הסכנה:
@1258 **בתוך הבאים.** מטמינין עצמן שלא יכירום, לפי שצוה להם אביהם שלא יתראו כלם בפתח אחד אלא שיכנס כל אחד בפתחו, כדי שלא תשלט בהם עין הרע שכלם נאים וכלם גבורים: [ כי היה הרעב . מוסב על הבאים , כי היה הרעב בארץ כנען והיו באים הרבה שירות משם]:
@1259 **וישתחוו לו אפים.** נשתטחו לו על פניהם, וכן כל השתחואה פשוט ידים ורגלים היא:
@1260 **ויתנכר אליהם.** נעשה להם כנכרי בדברים, לדבר קשות:
@1261 **ויכר יוסף** וגו' **.** לפי שהניחם חתומי זקן: **והם לא הכרהו.** שיצא מאצלם בלא חתימת זקן, ועכשיו בא בחתימת זקן. ומדרש אגדה ויכר יוסף את אחיו כשנמסרו בידו הכיר שהם אחיו ורחם עליהם, והם לא הכירוהו כשנפל בידם לנהוג בו אחוה:
@1262 **אשר חלם להם.** עליהם, וידע שנתקימו, שהרי השתחוו לו: **ערות הארץ.** גלוי הארץ, מהיכן היא נוחה לכבש, כמו (ויקרא כ יח) את מקורה הערה, וכמו (יחזקאל טז ז) ערום ועריה. וכן כל ערוה שבמקרא לשון גלוי. ותרגום אנקלוס בדקא דארעא, כמו (מלכים ב' יב ו) בדק הבית, רעוע הבית, אבל לא דקדק לפרשו אחר לשון המקרא:
@1263 **לא אדני.** לא תאמר כן, שהרי עבדיך באו לשבר אכל:
@1264 **כלנו בני איש אחד נחנו.** נצנצה בהם רוח הקדש וכללוהו עמהם שאף הוא בן אביהם: **כנים.** אמתיים, כמו (שמות י כט) כן דברת, (במדבר כז ז) כן בנות צלפחד דוברות, (ישעיה טז ו) ועברתו לא כן בדיו:
@1265 **כי ערות הארץ באתם לראות.** שהרי נכנסתם בעשרה שערי העיר, למה לא נכנסתם בשער אחד:
@1266 **ויאמרו שנים עשר עבדיך** וגו' **.** ובשביל אותו אחד שאיננו נתפזרנו בעיר לבקשו:
@1267 **הוא אשר דברתי.** הדבר אשר דברתי שאתם מרגלים הוא האמת והנכון, זהו לפי פשוטו. ומדרשו אמר להם ואלו מצאתם אותו ויפסקו עליכם ממון הרבה תפדוהו. אמרו לו הן. אמר להם ואם יאמרו לכם שלא יחזירוהו בשום ממון מה תעשו. אמרו לו לכך באנו, להרוג או להרג, אמר להם הוא אשר דברתי אליכם להרוג בני העיר באתם, מנחש אני בגביע שלי ששנים מכם החריבו כרך גדול של שכם:
@1268 **חי פרעה.** אם יחיה פרעה. שהיה נשבע לשקר, היה נשבע בחיי פרעה: **אם תצאו מזה.** מן המקום הזה:
@1269 **האמת אתכם.** אם אמת אתכם. לפיכך ה''א נקוד פתח שהוא כמו בלשון תמה. ואם לא תביאוהו, חי פרעה כי מרגלים אתם:
@1270 **משמר.** בית האסורים:
@1272 **בבית משמרכם.** שאתם אסורים בו עכשיו: **ואתם לכו הביאו.** לבית אביכם: **שבר רעבון בתיכם.** מה שקניתם לרעבון אנשי בתיכם:
@1273 **ויאמנו דבריכם.** יתאמתו ויתקימו, כמו (במדבר ה כב) אמן אמן, וכמו (מ''א ח כו) יאמן נא דברך:
@1274 **אבל.** כתרגומו בקושטא. וראיתי בבראשית רבה (צא ח) לישנא דרומאה היא אבל, ברם: **באה אלינו.** טעמו בבי''ת, לפי שהוא בלשון עבר שכבר באה, ותרגומו אתת לנא:
@1275 **וגם דמו.** אתין וגמין רבויין, דמו וגם דם הזקן:
@1276 **והם לא ידעו כי שומע יוסף.** מבין לשונם ובפניו היו מדברים כן: **כי המליץ בינתם.** כי כשהיו מדברים עמו היה המליץ ביניהם, היודע לשון עברי ולשון מצרי, והיה מליץ דבריהם ליוסף ודברי יוסף להם, לכך היו סבורים שאין יוסף מכיר בלשון עברי: **המליץ.** זה מנשה:
@1277 **ויסב מעליהם.** נתרחק מעליהם שלא יראוהו בוכה: **ויבך.** לפי ששמע שהיו מתחרטין: **את שמעון.** הוא השליכו לבור, הוא שאמר ללוי (לעיל לז יט) הנה בעל החלומות הלזה בא. דבר אחר נתכון יוסף להפרידו מלוי שמא יתיעצו שניהם להרוג אותו: **ויאסור אותו לעיניהם.** לא אסרו אלא לעיניהם, וכיון שיצאו הוציאו והאכילו והשקהו:
@1280 **ויפתח האחד.** הוא לוי שנשאר יחיד משמעון בן זוגו: **במלון.** במקום שלנו בלילה: **אמתחתו.** הוא שק:
@1281 **וגם הנה באמתחתי.** גם הכסף בו עם התבואה: **מה זאת עשה אלהים לנו.** להביאנו לידי עלילה זו שלא הושב אלא להתעולל עלינו:
@1287 **ואת הארץ תסחרו.** תסובבו. וכל לשון סוחרים וסחורה על שם שמחזרים וסובבים אחר פרקמטיא:
@1288 **צרור כספו.** קשר כספו:
@1289 **אתי שכלתם.** מלמד שחשדן שמא הרגוהו או מכרוהו כיוסף: **שכלתם.** כל מי שבניו אבודים קרוי שכול:
@1291 **לא ירד בני עמכם.** לא קבל דבריו של ראובן. אמר בכור שוטה הוא זה, הוא אומר להמית בניו, וכי בניו הם ולא בני:
@1293 **כאשר כלו לאכל.** יהודה אמר להם המתינו לזקן עד שתכלה פת מן הבית: **כאשר כלו.** כד שציאו. והמתרגם כד ספיקו, טועה כאשר כלו הגמלים לשתות מתרגם כד ספיקו כששתו די ספוקם הוא גמר שתיתם. אבל זה כאשר כלו לאכול, כאשר תם האכל הוא, ומתרגמינן כד שציאו:
@1294 **העד העד.** לשון התראה, שסתם התראה מתרה בו בפני עדים, וכן (ירמיהו יא ז) העדתי באבותיכם, (שמות יט כא) רד העד בעם: **לא תראו פני בלתי אחיכם אתכם.** לא תראוני בלא אחיכם אתכם. ואנקלוס תרגם אלהין כד אחוכון עמכון, ישב באור הדבר על אפנו ולא דקדק לתרגם אחר לשון המקרא:
@1298 **לנו ולמולדתנו.** למשפחותינו, ומדרשו אפילו עצי עריסותינו גלה לנו: **ונגד לו.** שיש לנו אב ואח: **על פי הדברים האלה.** על פי שאלותיו אשר שאל הזקקנו להגיד: **כי יאמר.** אשר יאמר, כי משמש בלשון אם, ואם משמש בלשון אשר. הרי זה שמוש אחד מארבע לשונותיו שמשמש כי, והוא אם, שהרי כי זה כמו אם, כמו עד אם דברתי דברי (כד לג) :
@1299 **ונחיה.** נצנצה בו רוח הקדש, על ידי הליכה זו תחי רוחך שנאמר (מה כז) ותחי רוח יעקב אביהם: **ולא נמות.** ברעב. בנימין ספק יתפש ספק לא יתפש, ואנו כלנו מתים ברעב אם לא נלך, מוטב שתניח את הספק ותתפוש את הודאי:
@1300 **והצגתיו לפניך.** שלא אביאנו אליך מת כי אם חי: **וחטאתי לך כל הימים.** לעולם הבא:
@1301 **לולא התמהמהנו.** על ידך, כבר היינו שבים עם שמעון ולא נצטערת כל הימים הללו:
@1302 **אפוא.** כל לשון אפוא לשון יתר הוא לתקון מלה בלשון עברי, אם כן אזדקק לעשות שאשלחנו עמכם, צריך אני לחזור ולבקש איה פה תקנה ועצה להשיאכם, ואומר אני זאת עשו: **מזמרת הארץ.** מתרגם מדמשבח בארעא שהכל מזמרים עליו כשהוא בא לעולם: **נכאת.** שעוה: **בטנים.** לא ידעתי מה הם ובפרושי א' ב' של רבי מכיר ראיתי פישיטצי''ש [פיסטוקים] ודומה לי שהם אפרסקין:
@1303 **וכסף משנה.** פי שנים כראשון: **קחו בידכם.** לשבור אוכל, שמא הוקר השער: **אולי משגה הוא.** שמא הממנה על הבית שכחו שוגג:
@1305 **ואל שדי.** מעתה אינכם חסרים כלום אלא תפלה, הריני מתפלל עליכם: **ואל שדי.** שדי בנתינת רחמיו, וכדי היכולת בידו לתן, יתן לכם רחמים, זהו פשוטו. ומדרשו מי שאמר לעולם די יאמר די לצרותי, שלא שקטתי מנעורי, צרת לבן, צרת עשו, צרת רחל, צרת דינה, צרת יוסף, צרת שמעון, צרת בנימין: **ושלח לכם.** ויפטר לכון, תרגומו, יפטרנו מאסוריו, לשון (שמות כא כו) לחפשי ישלחנו, ואינו נופל בתרגום לשון וישלח, שהרי לשם הם הולכים אצלו: **את אחיכם.** זה שמעון: **אחר.** רוח הקדש נזרקה בו, לרבות יוסף: **ואני.** עד שובכם אהיה שכול מספק: **כאשר שכלתי.** מיוסף ומשמעון: **שכלתי.** מבנימין:
@1306 **ואת בנימין.** מתרגמינן ודברו ית בנימין, לפי שאין לקיחת הכסף ולקיחת האדם שוה בלשון ארמי, בדבר הנקח ביד מתורגם ונסיב, ודבר הנקח בהנהגת דברים מתרגמינן ודבר:
@1307 **וטבוח טבח והכן.** כמו ולטבוח טבח ולהכין, ואין טבוח לשון צווי שהיה לו לומר וטבח: **בצהרים.** זה מתורגם בשירותא, שהוא לשון סעודה ראשונה בלשון ארמי, ובלע''ז דישני''ר [ארוחת צהרים], ויש הרבה בתלמוד (תענית יא ב) שדא לכלבא שירותיה, (ברכות לט ב) בצע אכולא שירותיה. אבל כל תרגום של צהרים טיהרא:
@1309 **וייראו האנשים.** כתוב בשני יודי''ן ותרגומו ודחילו: **כי הובאו בית יוסף.** ואין דרך שאר הבאים לשבור בר ללון בבית יוסף, כי אם בפנדקאות שבעיר. וייראו שאין זה אלא לאספם אל משמר: **אנחנו מובאים.** אל תוך הבית הזה: **להתגולל.** להיות מתגלגלת עלינו עלילת הכסף ולהיותה נופלת עלינו. ואונקלוס שתרגם ולאסתקפא עלנא, הוא לשון להתעולל, כדמתרגמינן (דברים כב יד) עלילת דברים תסקופי מלין, ולא תרגמו אחר לשון המקרא, ולהתגלל שתרגם לאתרברבא הוא לשון (קהלת יב ו) גלת הזהב, (נחום ב ח) והצב גלתה העלתה, שהוא לשון מלכות:
@1311 **בי אדני.** לשון בעיא ותחנונים הוא, ובלשון ארמי בייא בייא: **ירד ירדנו.** ירידה היא לנו, רגילים היינו לפרנס אחרים, עכשיו אנו צריכים לך:
@1314 **אלהיכם.** בזכותכם, ואם אין זכותכם כדאי, ואלהי אביכם, בזכות אביכם נתן לכם מטמון:
@1315 **ויבא האיש.** הבאה אחר הבאה, לפי שהיו דוחפים אותו לחוץ עד שדברו אליו פתח הבית, ומשאמר להם (פסוק כג) שלום לכם, נמשכו ובאו אחריו:
@1316 **ויכינו.** הזמינו, עטרוה בכלים נאים:
@1317 **הביתה.** מפרזדור לטרקלין:
@1319 **ויקדו וישתחוו.** על שאילת שלום. קידה כפיפת קדקד, השתחואה משתטח לארץ:
@1320 **אלהים יחנך בני.** בשאר שבטים שמענו חנינה (לעיל לג ה) אשר חנן אלהים את עבדך, ובנימין עדיין לא נלד, לכך ברכו יוסף בחנינה:
@1321 **כי נכמרו רחמיו.** שאלו יש לך אח מאם, אמר לו אח היה לי ואיני יודע היכן הוא. יש לך בנים, אמר לו יש לי עשרה, אמר לו ומה שמם, אמר לו (להלן מו כא) בלע ובכר וגו' , אמר לו מה טיבן של שמות הללו, אמר לו כלם על שם אחי והצרות אשר מצאוהו, בלע שנבלע בין האמות. בכר שהיה בכור לאמי. אשבל ששבאו אל. גרא שנתגייר באכסניא. ונעמן, שהיה נעים ביותר. אחי וראש אחי היה וראשי היה. מפים מפי אביו למד. וחפים שלא ראה חפתי ולא ראיתי אני חפתו. וארד שירד לבין האמות, כדאיתא במסכת סוטה (לו ב) מיד נכמרו רחמיו: **נכמרו.** נתחממו, ובלשון משנה (ב''מ עד א) על הכמר של זיתים, ובלשון ארמי מכמר בשרא, ובמקרא (איכה ה י) עורנו כתנור נכמרו, נתחממו ונקמטו קמטים קמטים מפני זלעפות רעב. כן דרך כל עור כשמחממין אותו נקמט וכווץ:
@1322 **ויתאפק.** נתאמץ. והוא לשון (איוב יב כא) ומזיח אפיקים רפה, וכן (איוב מא ז) אפיקי מגנים, חוזק:
@1323 **כי תועבה הוא.** דבר שנאוי הוא למצרים לאכול את העברים, ואונקלוס נתן טעם לדבר:
@1324 **הבכור כבכורתו.** מכה בגביע וקורא ראובן שמעון לוי ויהודה יששכר וזבולון, בני אם אחת, הסבו כסדר הזה שהוא סדר תולדותיכם וכן כלם, כיון שהגיע לבנימין אמר זה אין לו אם ואני אין לי אם ישב אצלי:
@1325 **משאת.** מנות: **חמש ידות.** חלקו עם אחיו ומשאת יוסף ואסנת ומנשה ואפרים: **וישכרו עמו.** ומיום שמכרוהו לא שתו יין, ולא הוא שתה יין, ואותו היום שתו
@1327 **גביע.** כוס ארוך, וקורין לו מדירנ''א בלע''ז :
@1332 **חלילה לעבדיך.** חלין הוא לנו, לשון גנאי. ותרגום חס לעבדיך, חס מאת הקדוש ברוך הוא יהי עלינו מעשות זאת והרבה חס ושלום יש בתלמוד בלשון הזה:
@1333 **הן כסף אשר מצאנו.** זה אחד מעשרה קל וחמר האמורים בתורה. וכלן מנויין בבר' רבה:
@1335 **גם עתה כדבריכם.** אף זו מן הדין, אמת כדבריכם כן הוא שכלכם חיבים בדבר, עשרה שנמצאת גנבה ביד אחד מהם כלם נתפשים, אבל אני אעשה לכם לפנים משורת הדין, אשר ימצא אתו יהיה לי עבד:
@1337 **בגדול החל.** שלא ירגישו בו שהיה יודע היכן הוא:
@1338 **ויעמס איש על חמרו.** בעלי זרוע היו ולא הצרכו לסיע זה את זה לטעון: **וישבו העירה.** מטרפולין היתה והוא אומר העירה, עיר כל שהיא, אלא שלא היתה חשובה בעיניהם אלא כעיר בינונית של עשרה בני אדם לענין המלחמה:
@1339 **עודנו שם.** שהיה ממתין להם:
@1340 **הלוא ידעתם כי נחש ינחש** וגו' **.** הלא ידעתם כי איש חשוב כמוני יודע לנחש ולדעת מדעת ומסברא ובינה כי אתם גנבתם הגביע:
@1341 **האלהים מצא.** יודעים אנו שלא סרחנו, אבל מאת הקדוש ברוך הוא נהיתה להביא לנו זאת. מצא בעל חוב מקום לגבות שטר חובו: **ומה נצטדק.** לשון צדק, וכן כל תבה שתחלת יסודה צד''י והיא באה לדבר בלשון מתפעל או נתפעל נותן טי''ת במקום תי''ו, ואינה נתנת לפני אות ראשונה של יסוד התבה אלא באמצע אותיות העקר, כגון נצטדק מגזרת צדק, (דניאל ד ל) ויצטבע מגזרת צבע, (יהושע ט ד) ויצטירו מגזרת (משלי יג יז) ציר אמונים, (יהושע ט יב) הצטידנו מגזרת (לעיל מב כה) צדה לדרך. ותיבה שתחלתה סמ''ך או שי''ן כשהיא מתפעלת התי''ו מפרדת את אותיות העקר, כגון (קהלת יב ה) ויסתבל החגב, מגזרת סבל, (דניאל ז ח) משתכל הוית בקרניא, (מיכה ו טז) וישתמר חקות עמרי, מגזרת שמר, (ישעיה נט טו) וסר מרע משתולל, מגזרת (איוב יב יז) מוליך יועצים שולל, (שמות ט יז) מסתולל בעמי, מגזרת (ירמיה יח טו) דרך לא סלולה:
@1343 **ויגש אליו. דבר באזני אדני.** (בראשית רבה) יכנסו דברי באזניך: **ואל יחר אפך.** מכאן אתה למד שדבר אליו קשות: **כי כמוך כפרעה.** חשוב אתה בעיני כמלך, זהו פשוטו. ומדרשו - סופך ללקות עליו בצרעת כמו שלקה פרעה ע"י זקנתי שרה על לילה אחת שעכבה (בראשית רבה). דבר אחר מה פרעה גוזר ואינו מקיים מבטיח ואינו עושה אף אתה כן. וכי זוהי שימת עין שאמרה לשים עיניך עליו, דבר אחר: כי כמוך כפרעה - אם תקניטני אהרוג אותך ואת אדוניך (בראשית רבה):
@1344 **אדני שאל את עבדיו.** (בראשית רבה) בתחילה בעלילה באת עלינו, למה היה לך לשאול כל אלה, ביתך היינו מבקשים, או אחותינו אתה מבקש, ואף על פי כן ונאמר אל אדוני לא כחדנו ממך דבר:
@1345 **ואחיו מת.** מפני היראה היה מוציא דבר שקר מפיו, אמר - אם אומר לו שהוא קיים - ימר הביאוהו אצלי: **לבדו לאמו.** מאותו האם אין לו עוד אח:
@1347 **ועזב את אביו ומת.** אם יעזוב את אביו דואגים אנו שמא ימות בדרך שהרי אמו בדרך מתה:
@1354 **וקראו אסון.** (בראשית רבה) שהשטן מקטרג בשעת הסכנה: **והורדתם את שיבתי וגו'.** עכשיו כשהוא אצלי אני מתנחם בו על אמו ועל אחיו, ואם ימות זה דומה עלי ששלשתן מתו ביום:
@1356 **והיה כראותו כי אין הנער ומת.** אביו מצרתו:
@1357 **כי עבדך ערב את הנער.** אם תאמר למה אני נכנס לתגר יותר משאר אחי - הם כולם מבחוץ ואני נתקשרתי בקשר חזק להיות מנודה בשני עולמות:
@1358 **ישב נא עבדך וגו'.** (בראשית רבה) לכל דבר אני מעולה ממנו, לגבורה, ולמלחמה, ולשמש:
@1360 **ולא יכול יוסף להתאפק לכל הנצבים.** לא היה יכול לסבול שיהיו מצרים נצבים עליו ושומעים שאחיו מתביישים בהודעו להם:
@1361 **וישמע בית פרעה.** ביתו של פרעה כלומר עבדיו ובני ביתו ואין זה לשון בית ממש אלא כמו בית ישראל. בית יהודה [מישנד"ה בלעז]:
@1362 **נבהלו מפניו.** וכמוהו הבושה:
@1363 **גשו נא אלי.** ראה אותם נסוגים לאחור, אמר עכשיו אחי נכלמים, קרא להם בלשון רכה ותחנונים והראה להם שהוא מהול (בראשית רבה):
@1364 **למחיה.** להיות לכם למחיה:
@1365 **כי זה שנתיים הרעב.** עברו משני הרעב:
@1367 **לאב.** לחבר ולפטרון [צום בשיטצער. פאטראן בלעז ???]: **ועלו אל אבי.** ארץ ישראל גבוה מכל הארצות:
@1370 **פן תורש.** דלמא תתמסכן, לשון מוריש ומעשיר:
@1371 **והנה עיניכם רואות.** בכבודי ושאני אחיכם ושאני מהול ככם. ועוד כי פי המדבר אליכם בלשון הקודש (בבראשית רבה): **ועיני אחי בנימין.** (מגילה יז) השוה את כולם יחד לומר שכשם שאין לי שנאה על בנימין אחי שהרי לא היה במכירתי, כך אין בלבי שנאה עליכם:
@1373 **ויפל על צוארי בנימין אחיו ויבך.** על שני מקדשות שעתידים להיות בחלקו של בנימין וסופן להיחרב:
@1374 **ואחרי כן.** מאחר שראוהו בוכה ולבו שלם עמהם: דברו אחיו אתו. שמתחילה היו בושים ממנו:
@1375 **והקול נשמע בית פרעה.** כמו בבית פרעה וזהו לשון בית ממש:
@1376 **טענו את בעירכם.** תבואה:
@1377 **ואת טוב ארץ מצרים.** ארץ גושן. ניבא ואינו יודע מה ניבא, סופה לעשותה כמצולה שאין בה דגים: **חלב הארץ.** כל חלב לשון מיטב הוא:
@1378 **ואתה צויתה.** מפי לומר להם: **זאת עשו.** כך אמור להם שברשותי הוא:
@1382 **שלח כזאת.** כחשבון הזה ומהו החשבון י' חמורים וגו'. (רצונו שמלת כזאת המיותרת ובכ''ף הדמיון מורה על כי מעולם לא שלח לו י' חמורים וי' אתונות, רק הכי קאמר קרא. בשם הגאון מהרש"ל): **מטוב מצרים.** מצינו בגמרא ששלח לו יין ישן שדעת זקנים נוחה הימנו. ומדרש אגדה גריסין של פול: **בר ולחם.** כתרגומו: **ומזון.** לפתן (כך גירסאת רא"ם):
@1383 **אל תרגזו בדרך.** אל תתעסקו בדבר הלכה שלא תרגז עליכם הדרך. דבר אחר - אל תפסעו פסיעה גסה ותכנסו בחימה לעיר, ולפי פשוטו של מקרא יש לומר - לפי שהיו נכלמים - היה דואג שמא יריבו בדרך על דבר מכירתו להתווכח זה עם זה ולומר על ידך נמכר, אתה ספרת לשון הרע עליו וגרמת לנו לשנאתו:
@1385 **וכי הוא מושל.** ואשר הוא מושל: **ויפג לבו.** נחלף לבו והלך מלהאמין, לא היה לבו פונה אל הדברים, לשון מפיגין טעמן בלשון משנה וכמו (איכה ג) מאין הפוגות (ירמיה מח ???) וריחו לא נמר מתרגמינן וריחיא לא פג:
@1386 **את כל דברי יוסף.** סימן מסר להם במה שהיה עוסק כשפירש ממנו בפרשת עגלה ערופה, זהו שנאמר וירא את העגלות אשר שלח יוסף ולא נאמר אשר שלח פרעה: **ותחי רוח יעקב.** שרתה עליו שכינה שפירשה ממנו:
@1387 **רב עוד.** רב לי עוד שמחה וחדוה הואיל ועוד יוסף בני חי:
@1388 **בארה שבע.** כמו לבאר שבע, ה"א בסוף תיבה במקום למ"ד בתחילתה: **לאלוהי אביו יצחק.** חייב אדם בכבוד אביו יותר מבכבוד זקנו לפיכך תלה ביצחק ולא באברהם:
@1389 **יעקב יעקב.** לשון חיבה:
@1390 **אל תירא מרדה מצרימה.** לפי שהיה מיצר על שנזקק לצאת לחוצה לארץ:
@1391 **ואנכי אעלך.** הבטיחו להיות נקבר בארץ:
@1393 **אשר רכשו בארץ כנען.** אבל מה שרכש בפדן ארם נתן הכל לעשו בשביל חלקו במערת המכפלה, אמר נכסי חוצה לארץ אינן כדאי לי וזהו אשר כריתי לי, העמיד לו צבורין של זהב וכסף כמין כרי ואמר לו טול את אלו:
@1394 **ובנות בניו.** סרח בת אשר, ויוכבד בת לוי:
@1395 **הבאים מצרימה.** על שם השעה קורא להם הכתוב באים. ואין לתמוה על אשר לא כתב אשר באו:
@1397 **בן הכנענית.** בן דינה שנבעלה לכנעני ,כשהרגו את שכם לא הייתה דינה רוצה לצאת עד שנשבע לה שמעון שישאנה (בראשית רבה):
@1402 **אלה בני לאה ואת דינה בתו.** הזכרים תלה בלאה והנקבות תלה ביעקב ללמדך אשה מזרעת תחלה יולדת זכר, איש מזריע תחלה יולדת נקבה: **שלשים ושלש.** ובפרטן אי אתה מוצא אלא שלשים ושנים, אלא זו יוכבד שנולדה בין החומות בכניסתן לעיר שנאמר אשר ילדה אותה ללוי במצרים, לידתה במצרים ואין הורתה במצרים:
@1406 **בני רחל אשת יעקב.** ובכולן לא נאמר בהן אשת אלא שהיתה עיקרו של בית:
@1413 **כל הנפש הבאה ליעקב.** שיצאו מארץ כנען לבוא למצרים. ואין הבאה זו לשון עבר, אלא לשון הווה, כמו (אסתר ב) בערב היא באה וכמו והנה רחל בתו באה עם הצאן, לפיכך טעמו למטה באל"ף, לפי שכשיצאו לבוא מארץ כנען לא היו אלא שישים ושש. והשני כל הנפש לבית יעקב הבאה מצרימה שבעים הוא לשון עבר לפיכך טעמו למעלה בבי"ת לפי שמשבאו שם היו שבעים שמצאו שם יוסף ושני בניו ונתוספה להם יוכבד בין החומות. (ועיין בביאור לת"י ומשם תמצא להרוות צמאונך ברש"י) ולדברי האומר תאומות נולדו עם השבטים צריכים אנו לומר שמתו לפני ירידתן למצרים שהרי לא נמנו כאן. מצאתי בויקרא רבה עשו שש נפשות היו לו והכתוב קורא אותן נפשות ביתו לשון רבים, לפי שהיו עובדין לאלהות הרבה, יעקב שבעים היו לו והכתוב קורא אותן נפש, לפי שהיו עובדים לאל אחד:
@1415 **להורות לפניו.** כתרגומו לפנות לו מקום ולהורות האיך יתיישב בה: **לפניו.** קודם שיגיע לשם.ומדרש אגדה: להורות לפניו לתקן לו בית תלמוד שמשם תצא הוראה:
@1416 **ויאסור יוסף מרכבתו.** הוא עצמו אסר את הסוסים למרכבה להזדרז לכבוד אביו: **וירא אליו.** יוסף נראה אל אביו: **ויבך על צואריו עוד.** לשון הרבות בכיה. וכן (איוב לד) כי לא על איש ישים, עוד לשון רבוי הוא, אינו שם עליו עלילות נוספות על חטאיו, אף כאן הרבה והוסיף בבכי יותר על הרגיל אבל יעקב לא נפל על צוארי יוסף ולא נשקו. ואמרו רבותינו שהיה קורא את שמע:
@1417 **אמותה הפעם.** פשוטו כתרגומו ומדרשו - סבור הייתי למות שתי מיתות בעולם הזה ובעולם הבא, שנסתלקה שכינה ממני, והייתי אומר שיתבעני הקב"ה מיתתך, עכשיו שעודך חי לא אמות אלא פעם אחת:
@1418 **ואמרה אליו אחי וגו'.** ועוד אומר לו (פסוק לב) והאנשים רועי צאן וגו':
@1421 **בעבור תשבו בארץ גשן.** והיא צריכה לכם שהיא ארץ מרעה, וכשתאמרו לו שאין אתם בקיאין במלאכה אחרת ירחיקכם מעליו ויושיבכם שם: **כי תועבת מצרים וגו'.** לפי שהם להם אלהות.
@1423 **ומקצה אחיו.** מן הפחותים שבהם לגבורה שאין נראים גיבורים, שאם יראה אותם גיבורים יעשה אותם אנשי מלחמתו. ואלה הם ראובן שמעון לוי יששכר ובנימין, אותם שלא כפל משה שמותם כשברכם, אבל שמות הגיבורים כפל, וזאת ליהודה שמע ה' קול יהודה, ולגד אמר ברוך מרחיב גד. ולנפתלי אמר נפתלי. ולדן אמר דן. וכן לזבולן, וכן לאשר זה לשון בראשית רבה שהיא אגדת ארץ ישראל אבל בגמרא בבלית שלנו (בבא קמא צ''ב) מצינו שאותם שכפל משה שמותם הם החלשים ואותן הביא לפני פרעה, ויהודה שהוכפל שמו לא הוכפל משום חלשות, אלא טעם יש בדבר כדאיתא בבבא קמא ובברייתא דספרי שנינו בה בוזאת הברכה כמו בגמרא שלנו:
@1427 **אנשי חיל.** בקיאין באומנותן לרעות צאן: **על אשר לי.** על צאן שלי:
@1428 **ויברך יעקב.** היא שאילת שלום כדרך כל הנראים לפני המלכים לפרקים, שלידי"ר בלע"ז [גריסען]:
@1430 **שני מגורי.** ימי גרותי כל ימי הייתי גר בארץ: **ולא השיגו.** בטובה:
@1431 **ויברך יעקב.** כדרך כל הנפטרים מלפני שרים מברכים אותם ונוטלים רשות ומה ברכה ברכו שיעלה נילוס לרגליו לפי שאין מצרים שותה מי גשמים אלא נילוס עולה ומשקה ומברכתו של יעקב ואילך היה פרעה בא אל נילוס והוא עולה לקראתו ומשקה את הארץ [תנחומא]:
@1432 **רעמסס.** מארץ גושן היא:
@1433 **לפי הטף.** לפי הצריך לכל בני ביתם:
@1434 **ולחם אין בכל הארץ.** חוזר לענין הראשון לתחלת שני הרעב: **ותלה.** כמו ותלאה לשון עייפות כתרגומו ודומה לו (משלי כו) כמתלהלה היורה זיקים:
@1436 **אפס.** כתרגומו שלים:
@1439 **בשנה השנית.** שנית לשני הרעב: **כי אם תם הכסף וגו'.** כי אשר תם הכסף והמקנה ובא הכל אל יד אדוני: **בלתי אם גויתנו.** כמו אם לא גויתנו:
@1440 **ותן זרע.** לזרוע האדמה ואע"פ שאמר יוסף ועוד חמש שנים אשר אין חריש וקציר מכיון שבא יעקב למצרים באה ברכה לרגליו והתחילו לזרוע וכלה הרעב וכן שנינו בתוספתא דסוטה: **לא תשם - לא תהא שממה.** לא תבור לשון שדה בור שאינו חרוש:
@1441 **ותהי הארץ לפרעה.** קנויה לו:
@1442 **ואת העם העביר.** יוסף מעיר לעיר לזכרון שאין להם עוד חלק בארץ והושיב של עיר זו בחברתה, ולא הוצרך הכתוב לכתוב זאת אלא להודיעך שבחו של יוסף שנתכוין להסיר חרפה מעל אחיו שלא יהיו קורין אותם גולים (חולין ס): **מקצה גבול מצרים וגו'.** כן עשה לכל הערים אשר במלכות מצרים מקצה גבולה ועד קצה גבולה:
@1443 **הכהנים.** הכומרים כל לשון כהן משרת לאלהות הוא חוץ מאותן שהם לשון גדולה כמו כהן מדין כהן און: **חוק לכהנים.** חק כך וכך לחם ליום:
@1444 **הא.** כמו הנה כמו (יחזקאל טז) וגם אני הא דרכך בראש נתתי:
@1446 **נמצא חן.** לעשות לנו זאת כמו שאמרת: **והיינו עבדים לפרעה.** להעלות לו המס הזה בכל שנה לחק שלא יעבור:
@1448 **וישב ישראל בארץ מצרים.** והיכן בארץ גושן שהיא מארץ מצרים: **ויאחזו בה.** לשון אחוזה:
@1449 **ויחי יעקב.** למה פרשה זו סתומה, לפי שכיון שנפטר יעקב אבינו נסתמו עיניהם ולבם של ישראל מצרת השעבוד שהתחילו לשעבדם. דבר אחר שבקש לגלות את הקץ לבניו ונסתם ממנו:
@1450 **ויקרבו ימי ישראל למות.** כל מי שנאמר בו קריבה למות לא הגיע לימי אבותיו. [יצחק חי מאה ושמונים ויעקב מאה ארבעים ושבע. בדוד נאמר קריבה, אביו חי ארבע מאות שנים והוא חי שבעים]: **ויקרא לבנו ליוסף.** למי שהיה יכולת בידו לעשות: **שים נא ידך.** והשבע: **חסד ואמת.** חסד שעושין עם המתים הוא חסד של אמת, שאינו מצפה לתשלום גמול: **אל נא תקברני במצרים.** סופה להיות עפרה כנים ומרחשין תחת גופי ושאין מתי חוצה לארץ חיים אלא בצער גלגול מחלות, ושלא יעשוני מצרים עבודה זרה:
@1451 **ושכבתי עם אבתי.** וי''ו זו מחבר למעלה לתחלת המקרא (פסוק כט) שים נא ידך תחת ירכי והשבע לי, ואני סופי לשכב עם אבותי, ואתה תשאני ממצרים. ואין לומר ושכבתי עם אבותי, השכיבני עם אבותי במערה, שהרי כתיב אחריו ונשאתני ממצרים וקברתני בקברתם. ועוד, מצינו בכמה מקומות לשון שכיבה עם אבותיו היא הגויעה, ולא הקבורה, כמו (מ''א ב י) וישכב דוד עם אבותיו, ואחר כך ויקבר בעיר דוד:
@1452 **וישתחו ישראל.** תעלא בעדניה סגיד ליה: **על ראש המטה.** הפך עצמו לצד השכינה, מכאן אמרו שהשכינה למעלה מראשותיו של חולה. דבר אחר על ראש המטה, על שהיתה מטתו שלמה שאין בה רשע, שהרי יוסף מלך הוא, ועוד שנשבה לבין הגוים, והרי הוא עומד בצדקו:
@1453 **ויאמר ליוסף.** אחד מן המגידים, והרי זה מקרא קצר. ויש אומרים אפרים היה רגיל לפני יעקב בתלמוד, וכשחלה יעקב בארץ גושן, הלך אפרים אצל אביו למצרים והגיד לו: **ויקח את שני בניו עמו.** כדי שיברכם יעקב לפני מותו:
@1454 **ויגד.** המגיד ליעקב, ולא פרש מי, והרבה מקראות קצרי לשון: **ויתחזק ישראל.** אמר אף על פי שהוא בני, מלך הוא ואחלוק לו כבוד. מכאן שחולקין כבוד למלכות, וכן משה חלק כבוד למלכות (שמות יא ח) וירדו כל עבדיך אלה אלי, וכן אליהו (מ''א יח מו) וישנס מתניו וגו' :
@1456 **ונתתיך לקהל עמים.** בשרני שעתידים לצאת ממני עוד קהל ועמים ואף על פי שאמר לי (לעיל לה יא) גוי וקהל גוים, גוי אמר לי על בנימין, קהל גוים הרי שנים לבד מבנימין, ושוב לא נלד לי בן, למדני שעתיד אחד משבטי לחלק, ועתה אותה מתנה אני נותן לך:
@1457 **הנולדים לך' עד באי אליך.** לפני בואי אליך, כלומר שנלדו משפרשת ממני עד שבאתי אצלך: **לי הם.** בחשבון שאר בני הם לטול חלק בארץ איש כנגדו:
@1458 **ומולדתך** וגו' **.** אם תוליד עוד לא יהיו במנין בני אלא בתוך שבטי אפרים ומנשה יהיו נכללים, ולא יהא להם שם בשבטים לענין הנחלה, ואף על פי שנתחלקה הארץ למנין גלגלתם כדכתיב (במדבר כו נד) לרב תרבו נחלתו, וכל איש ואיש נטל בשוה חוץ מן הבכורות, מכל מקום לא נקראו שבטים אלא אלו [להטיל גורל הארץ למנין שמות השבטים, ונשיא לכל שבט ושבט. ודגלים לזה ולזה]:
@1459 **ואני בבאי מפדן** וגו' **.** ואף על פי שאני מטריח עליך להוליכני להקבר בארץ כנען, ולא כך עשיתי לאמך, שהרי סמוך לבית לחם מתה: **כברת ארץ.** מדת ארץ, והם אלפים אמה כמדת תחום שבת, כדברי רבי משה הדרשן. ולא תאמר שעכבו עלי גשמים מלהוליכה ולקברה בחברון, עת הגריד היה, שהארץ חלולה ומנקבת ככברה: **ואקברה שם.** ולא הולכתיה אפלו לבית לחם להכניסה לארץ, וידעתי שיש בלבך עלי [תרעומת], אבל דע לך שעל פי הדבור קברתיה שם שתהא לעזרה לבניה כשיגלה אותם נבוזראדן, והיו עוברים דרך שם, יצאת רחל על קברה ובוכה ומבקשת עליהם רחמים, שנאמר (ירמיה לא יד) קול ברמה נשמע רחל מבכה על בניה וגו' , והקדוש ברוך הוא משיבה (ירמיה לא טו) יש שכר לפעלתך נאם ה' ושבו בנים לגבולם. ואונקלוס תרגם כרוב ארעא, כדי שעור חרישת יום [הארץ]. ואומר אני שהיה להם קצב שהיו קורין אותו כדי מחרשה אחת, קרואיד''א בלע''ז [מלוא מחרשה], כדאמרנן (בבא מציעא קז א) כרוב ותני, (יומא מג ב) כמה דמסיק תעלא מבי כרבא:
@1460 **וירא ישראל את בני יוסף.** בקש לברכם ונסתלקה שכינה ממנו, לפי שעתיד ירבעם ואחאב לצאת מאפרים, ויהוא ובניו ממנשה: **ויאמר מי אלה.** מהיכן יצאו אלו שאינן ראויין לברכה:
@1461 **בזה.** [הראה לו] שטר ארוסין ושטר כתבה, ובקש יוסף רחמים על הדבר ונחה עליו רוח הקדש: **ויאמר קחם נא אלי ואברכם.** זהו שאמר הכתוב (הושע יא ג) ואנכי תרגלתי לאפרים קחם על זרועתיו, תרגלתי רוחי ביעקב בשביל אפרים, עד שלקחן על זרועותיו:
@1463 **לא פללתי.** לא מלאני לבי לחשב מחשבה שאראה פניך עוד. פללתי לשון מחשבה, כמו (ישעיה טז ג) הביאי עצה עשו פלילה:
@1464 **ויוצא יוסף אתם.** לאחר שנשקם הוציאם יוסף מעם ברכיו כדי לישבם, זה לימין וזה לשמאל לסמוך ידיו עליהם ולברכם: **וישתחו לאפיו.** כשחזר לאחוריו מלפני אביו:
@1465 **את אפרים בימינו משמאל ישראל.** הבא לקראת חברו ימינו כנגד שמאל חברו, וכיון שהוא הבכור מימן לברכה:
@1466 **שכל את ידיו.** כתרגומו אחכמנון, בהשכל וחכמה השכיל את ידיו (לכך, ומדעת) , כי יודע היה כי מנשה הבכור, ואף על פי כן לא שת ימינו עליו:
@1468 **המלאך הגאל אתי.** מלאך הרגיל להשתלח אלי בצרתי, כענין שנאמר (בראשית לא יא. יג) ויאמר אלי מלאך האלהים בחלום יעקב וגו' אנכי האל בית אל: **יברך את הנערים.** מנשה ואפרים: **וידגו.** כדגים הללו שפרים ורבים ואין עין הרע שולטת בהם:
@1469 **ויתמך יד אביו.** הרימה מעל ראש בנו ותמכה בידו:
@1471 **ידעתי בני ידעתי.** שהוא הבכור: **גם הוא יהיה לעם וגם הוא יגדל.** שעתיד גדעון לצאת ממנו שהקדוש ברוך הוא עושה נס על ידו: **ואולם אחיו הקטן יגדל ממנו.** שעתיד יהושע לצאת ממנו שינחיל את הארץ וילמד תורה לישראל: **וזרעו יהיה מלא הגוים.** כל העולם יתמלא בצאת שמעו כשיעמיד חמה בגבעון וירח בעמק אילון:
@1472 **בך יברך ישראל.** הבא לברך את בניו, יברכם בברכתם ויאמר איש לבנו ישימך אלהים כאפרים וכמנשה: **וישם את אפרים.** בברכתו לפני מנשה, להקדימו בדגלים ובחנכת הנשיאים:
@1474 **ואני נתתי לך.** לפי שאתה טורח להתעסק בקבורתי, וגם אני נתתי לך נחלה שתקבר בה, ואי זו, זו שכם, שנאמר (יהושע כד לב) ואת עצמות יוסף אשר העלו בני ישראל ממצרים קברו בשכם: **שכם אחד על אחיך.** שכם ממש, היא תהיה לך חלק אחד יתרה על אחיך: **בחרבי ובקשתי.** כשהרגו שמעון ולוי את אנשי שכם נתכנסו כל סביבותיהם להזדוג להם וחגר יעקב כלי מלחמה כנגדן. דבר אחר שכם אחד היא הבכורה שיטלו בניו שני חלקים, ושכם לשון חלק הוא, והרבה יש לו דומים במקרא (תהלים כא יג) כי תשיתמו שכם, תשית שונאי לפני לחלקים, (שם ס ח) אחלקה שכם, (הושע ו ט) דרך ירצחו שכמה, איש חלקו, (צפניה ג ט) לעבדו שכם אחד: **אשר לקחתי מיד האמרי.** מיד עשו שעשה מעשה אמורי. דבר אחר שהיה צד אביו באמרי פיו: **בחרבי ובקשתי.** היא חכמתו ותפלתו:
@1475 **ואגידה לכם.** בקש לגלות את הקץ ונסתלקה שכינה ממנו והתחיל אומר דברים אחרים:
@1477 **וראשית אוני.** היא טפה ראשונה שלו, שלא ראה קרי מימיו: **אוני.** כוחי, כמו (הושע יב ט) מצאתי און לי, (ישעיה מ כו) מרוב אונים, (שם כט) ולאין אונים: **יתר שאת.** ראוי היית להיות יתר על אחיך בכהנה, לשון נשיאות כפים: **ויתר עז.** במלכות, כמו (ש''א ב י) ויתן עז למלכו. ומי גרם לך להפסיד כל אלה:
@1478 **פחז כמים.** הפחז והבהלה אשר מהרת להראות כעסך, כמים הללו הממהרים למרוצתם, לכך **אל תותר.** אל תרבה לטל כל היתרות הללו שהיו ראויות לך. ומהו הפחז אשר פחזת. **כי עלית משכבי אביך אז חללת.** אותו שעלה על יצועי, שם שכינה שהיה דרכה להיות עולה על יצועי: **פחז.** שם דבר הוא לפיכך טעמו למעלה וכלו נקוד פת''ח, ואלו היה לשון עבר היה נקוד חציו קמ''ץ וחציו פת''ח וטעמו למטה: **יצועי.** לשון משכב על שם שמציעים אותו על ידי לבדין וסדינין, והרבה דומים לו (תהלים קלב ג) אם אעלה על ערש יצועי, (תהלים סג ז) אם זכרתיך על יצועי:
@1479 **שמעון ולוי אחים.** בעצה אחת על שכם ועל יוסף. (לעיל לז יט. כ) ויאמרו איש אל אחיו ועתה לכו ונהרגהו, מי הם, אם תאמר ראובן או יהודה, הרי לא הסכימו בהריגתו, אם תאמר בני השפחות, הרי לא היתה שנאתן שלמה, שנאמר (שם ב) והוא נער את בני בלהה ואת בני זלפה וגו' , יששכר וזבולן לא היו מדברים בפני אחיהם הגדולים מהם, על כרחך שמעון ולוי הם, שקראם אביהם אחים: **כלי חמס.** אמנות זו של רציחה, חמס הוא בידיהם, מברכת עשו היא, זו אמנות שלו היא, ואתם חמסתם אותה המנו: **מכרתיהם.** לשון כלי זין, הסיף בלשון יוני מכי''ר. דבר אחר מכרתיהם. בארץ מגורתם נהגו עצמן בכלי חמס, כמו (יחזקאל טז ג) מכרתיך ומלדתיך, וזה תרגום של אונקלוס:
@1480 **בסדם אל תבא נפשי.** זה מעשה זמרי, כשנתקבצו שבטו של שמעון להביא את המדינית לפני משה, ואמרו לו זו אסורה או מתרת, אם תאמר אסורה, בת יתרו מי התירה לך, אל יזכר שמי בדבר, שנאמר (במדבר כה יד) זמרי בן סלוא נשיא בית אב לשמעוני, ולא כתב בן יעקב: **בקהלם.** כשיקהיל קרח שהוא משבטו של לוי את כל העדה על משה ועל אהרן: **אל תחד כבדי.** שם, אל יתיחד עמהם שמי, שנאמר (במדבר טז א) קרח בן יצהר בן קהת בן לוי, ולא נאמר בן יעקב אבל בדברי הימים כשנתיחסו בני קרח על הדוכן, נאמר (דה''א ו כב) בן קרח בן יצהר בן קהת בן לוי בן ישראל: **אל תחד כבדי.** כבוד לשון זכר הוא, ועל כרחך אתה צריך לפרש כמדבר אל הכבוד ואומר אתה כבודי אל תתיחד עמם, כמו (ישעיה יד כ) לא תחד אתם בקבורה: **כי באפם הרגו איש.** אלו חמור ואנשי שכם, ואינם חשובין כלם אלא כאיש אחד וכן הוא אומר בגדעון (שופטים ו טז) והכית את מדין כאיש אחד, וכן במצרים (שמות טו א) סוס ורוכבו רמה בים, זהו מדרשו. ופשוטו אנשים הרבה קורא איש, כל אחד לעצמו, באפם הרגו כל איש שכעסו עליו, וכן (יחזקאל יט ג) וילמד לטרף טרף אדם אכל: **וברצנם עקרו שור.** רצו לעקר את יוסף שנקרא שור, שנאמר (דברים לג יז) בכור שורו הדר לו. עקרו אישירוטו''ר בלע''ז [לכרות גידי השוק], לשון (יהושע יא ו) את סוסיהם תעקר:
@1481 **ארור אפם כי עז.** אפלו בשעת תוכחה לא קלל אלא אפם, וזהו שאמר בלעם (במדבר כג ח) מה אקוב לא קבה אל: **אחלקם ביעקב.** אפרידם זה מזה שלא יהא לוי במנין השבטים, והרי הם חלוקים. דבר אחר אין לך עניים וסופרים ומלמדי תינוקות אלא משמעון, כדי שיהיו נפוצים, ושבטו של לוי עשאו מחזר על הגרנות לתרומות ולמעשרות, נתן לו תפוצתו דרך כבוד:
@1482 **יהודה אתה יודוך אחיך.** לפי שהוכיח את הראשונים בקנטורים התחיל יהודה לסוג לאחוריו (שלא יוכיחנו על מעשה תמר) וקראו יעקב בדברי רצוי יהודה לא אתה כמותם: **ידך בערף איביך.** בימי דוד, שנאמר (ש''ב כב מא) ואויבי תתה לי ערף: **בני אביך.** על שם שהיו מנשים הרבה לא אמר בני אמך, כדרך שאמר יצחק (לעיל כז כט) :
@1483 **גור אריה.** על דוד נתנבא, בתחלה גור (שמואל ב' ה ב) בהיות שאול מלך עלינו אתה היית המוציא והמביא את ישראל, ולבסוף אריה כשהמליכוהו עליהם, וזהו שתרגם אונקלוס שלטון יהא בשרויא, בתחלתו: **מטרף.** ממה שחשדתיך (לעיל לז לג) בטרף טרף יוסף חיה רעה אכלתהו, וזהו יהודה שנמשל לאריה: **בני עלית.** סלקת את עצמך, ואמרת (שם כו) מה בצע וגו' . וכן מהריגת תמר שהודה (לעיל לח כו) צדקה ממני, לפיכך כרע רבץ וגו' בימי שלמה (מ''א ה ה) איש תחת גפנו וגו' :
@1484 **לא יסור שבט מיהודה.** מדוד ואלך, אלו ראשי גליות שבבבל שרודים את העם בשבט שממנים על פי המלכות: **ומחקק מבין רגליו.** תלמידים, אלו נשיאי ארץ ישראל: **עד כי יבא שילה.** מלך המשיח שהמלוכה שלו, וכן תרגם אנקלוס. ומדרש אגדה שילו, שי לו, שנאמר (תהלים עו יב) יובילו שי למורא: **ולו יקהת עמים.** אסיפת עמים, שהיו''ד עיקר היא ביסוד, כמו (יחזקאל כח יז) יפעתך, ופעמים שנופלת ממנו, וכמה אותיות משמשות בלשון זה והם נקראים עיקר נופל, כגון נו''ן של נוגף ושל נושך ואל''ף (איוב יג יז) שבאחותי באזניכם, (יחזקאל כא כ) ושבאבחת חרב (מ''ב ד ב) ואסוך שמן. אף זה יקהת עמים, אסיפת עמים, שנאמר (ישעיהו יא י) אליו גוים ידרשו, ודומה לו (משלי ל יז) עין תלעג לאב ותבז ליקהת אם, לקבוץ קמטים שבפנים מפני זקנתה. ובתלמוד (יבמות קו ב) דיתבי ומקהו אקהתא בשוקי דנהרדעא, ויכול היה לומר קהית עמים:
@1485 **אסרי לגפן עירה.** נתנבא על ארץ יהודה שתהא מושכת יין כמעין, איש יהודה יאסר לגפן עיר אחד ויטעננו מגפן אחת, ומשורק אחד בן אתון אחד: **שרקה.** זמורה ארכה, קורייד''א בלע''ז [עריס]: **כבס ביין.** כל זה לשון רבוי יין: **סותה.** לשון מין בגד הוא, ואין לו דמיון במקרא: **אסרי.** כמו אוסר, דוגמתו (תהלים קיג ז) מקימי מעפר דל, (שם קכג א) היושבי בשמים, וכן בני אתנו כענין זה. ואונקלוס תרגם במלך המשיח. גפן הם ישראל, עירה זו ירושלים. שורקה אלו ישראל (ירמיה ב כא) ואנכי נטעתיך שורק: **בני אתונו.** יבנון היכליה, לשון שער האיתון בספר יחזקאל (מ טו) . ועוד תרגמו בפנים אחרים גפן אלו צדיקים. בני אתונו עבדי אוריתא באלפן, על שם (שופטים ה י) רוכבי אתונות צחורות. **כבס ביין.** יהא ארגוון טב לבושוהי, דומה ליין, וצבעונין הוא לשון סותה שהאשה לובשתן ומסיתה בהן את הזכר לתן עיניו בה. ואף רבותינו פרשו בתלמוד לשון הסתת שכרות במסכת כתבות (דף קיא ב) ועל היין, שמא תאמר אינו מרוה, תלמוד לומר סותה:
@1486 **חכלילי.** לשון אודם כתרגומו וכן (משלי כג כט) למי חכלילות עינים, שכן דרך שותי יין עיניהם מאדימין: **מחלב.** מרוב חלב [שיהא בארצו מרעה טוב לעדרי צאן, וכן פרוש המקרא אדם עינים יהא מרוב יין, ולבן שנים יהא מרוב חלב]. ולפי תרגומו עינים לשון הרים, שמשם צופים למרחוק. ועוד תרגמו בפנים אחרות לשון מעינות וקלוח היקבים. נעווהי, יקבים שלו, ולשון ארמי הוא במסכת עבודה זרה (דף עד ב) נעוא ארתחו. יחורן בקעתיה, תרגם שנים לשון (ש''א יד ד) שני הסלעים:
@1487 **זבלון לחוף ימים.** על חוף ימים תהיה ארצו. חוף כתרגומו ספר, מרק''א בלע''ז [גבול], והוא יהיה מצוי תדיר על חוף אניות, במקום הנמל, שאניות מביאות שם פרקמטיא, שהיה זבולן עוסק בפרקמטיא, וממציא מזון לשבט יששכר והם עוסקים בתורה, הוא שאמר משה (דברים לג יח) שמח זבולן בצאתך ויששכר באהליך, זבולן יוצא בפרקמטיא ויששכר עוסק בתורה באהלים: **וירכתו על צידן.** סוף גבולו יהיה סמוך לצידון. ירכתו, סופו, כמו (שמות כו כב) ולירכתי המשכן:
@1488 **יששכר חמור גרם.** חמור בעל עצמות, סובל עול תורה כחמור חזק שמטעינין אותו משאוי כבד: **רבץ בין המשפתים.** כחמור המהלך ביום ובלילה ואין לו לינה בבית וכשהוא רוצה לנוח רובץ לו בין התחומין בתחומי העירות שמוליך שם פרקמטיא:
@1489 **וירא מנוחה כי טוב.** ראה לחלקו ארץ מבורכת וטובה להוציא פירות: **ויט שכמו לסבל.** עול תורה: **ויהי.** לכל אחיו ישראל: **למס עבד.** לפסוק להם הוראות של תורה וסדרי עבורין, שנאמר (דה''א יב לג) ומבני יששכר יודעי בינה לעתים לדעת מה יעשה ישראל ראשיהם מאתים, מאתים ראשי סנהדראות העמיד, וכל אחיהם על פיהם: **ויט שכמו.** השפיל שכמו כמו (שמואל ב' כב י) ויט שמים (תהלים עח א) הטו אזנכם. ואונקלוס תרגמו בפנים אחרים ויט שכמו לסבל מלחמות ולכבוש מחוזות שהם יושבים על הספר, ויהי האויב כבוש תחתיו למס עובד:
@1490 **דן ידין עמו.** ינקם נקמת עמו מפלשתים, כמו (דברים לב לו) כי ידין ה' עמו: **כאחד שבטי ישראל.** כל ישראל יהיו כאחד עמו ואת כלם ידין, ועל שמשון נבא נבואה זו. ועוד יש לפרש כאחד שבטי ישראל כמיוחד שבשבטים הוא דוד שבא מיהודה:
@1491 **שפיפן.** הוא נחש. ואומר אני שקרוי כן על שם שהוא נושף, כמו (בראשית ג טו) ואתה תשופנו עקב: **הנשך עקבי סוס.** כך דרכו של נחש, ודמהו לנחש הנושך עקבי סוס, ונופל רכבו אחור שלא נגע בו. ודוגמתו מצינו בשמשון (שופטים טז כט) וילפת שמשון את שני עמודי התוך וגו' ושעל הגג מתו. ואונקלוס תרגם כחיוי חורמן, שם מין נחש, שאין רפואה לנשיכתו, והוא צפעוני, וקרוי חורמן על שם שעושה הכל חרם. וכפתנא, כמו פתן. יכמון, יארוב:
@1492 **לישועתך קויתי ה'.** נתנבא שינקרו פלשתים את עיניו, וסופו לומר (שופטים טז כח) זכרני נא וחזקני נא אך הפעם וגו' :
@1493 **גד גדוד יגודנו.** כלם לשון גדוד הם, וכך חברו מנחם. ואם תאמר אין גדוד בלא שני דלתי''ן, יש לומר גדוד שם דבר צריך שני דלתי''ן, שכן דרך תבה בת שתי אותיות לכפול בסופה, ואין יסודה אלא שתי אותיות, וכן אמר (משלי כו ב) כצפור לנוד, מגזרת (איוב ז ד) ושבעתי נדודים, (שופטים ה כז) שם נפל שדוד, מגזרת (תהלים צא ו) ישוד צהרים, אף יגוד, יגודנו, וגדוד, מגזרה אחת הם. וכשהוא מדבר בלשון יפעל אינו כפול, כמו יגוד, ינוד, ירום, ישוד, ישוב, וכשהוא מתפעל או מפעיל אחרים הוא כפול, כמו יתגודד, יתרומם, יתבולל, יתעודד. ובלשון מפעיל (תלים קמו ט) יתום ואלמנה יעודד, (ישע' מט ה) לשובב יעקב אליו, (שם נח יב) משובב נתיבות. יגודנו האמור כאן אינו לשון שיפעילוהו אחרים, אלא כמו יגוד המנו, כמו (ירמיה י כ) בני יצאוני, יצאו ממני. גד גדוד יגודנו. גדודים יגודו המנו, שיעברו הירדן עם אחיהם למלחמה כל חלוץ עד שנכבשה הארץ: **והוא יגוד עקב.** כל גדודיו ישובו על עקבם לנחלתם שלקחו בעבר הירדן, ולא יפקד מהם איש: **עקב.** בדרכן ובמסלותם שהלכו ישובו, כמו (תהלים עז כ) ועקבותיך לא נודעו, וכן (שה''ש א ח) בעקבי הצאן, בלשון לע''ז תרצי''ש [עקבות]:
@1494 **מאשר שמנה לחמו.** מאכל הבא מחלקו של אשר יהא שמן, שיהיו זיתים מרבים בחלקו, והוא מושך שמן כמעין. וכן ברכו משה (דברים לג כד) וטבל בשמן רגלו, כמו ששנינו במנחות (דף פה ב) פעם אחת הצרכו אנשי לודקיא לשמן וכו' :
@1495 **אילה שלחה.** זו בקעת גנוסר שהיא קלה לבשל פירותיה כאילה זו שהיא קלה לרוץ. אילה שלוחה. אילה משלחת לרוץ: **הנתן אמרי שפר.** כתרגומו. דבר אחר על מלחמת סיסרא נתנבא (שופטים ד ו) ולקחת עמך עשרת אלפים איש מבני נפתלי וגו' , והלכו שם בזריזות, וכן נאמר שם לשון שלוח (שופטים ה טו) בעמק שלח ברגליו: **הנתן אמרי שפר.** על ידם שרו דבורה וברק שירה. ורבותינו דרשוהו על יום קבורת יעקב כשערער עשו על המערה, במסכת סוטה (דף יג א) . ותרגומו יתרמי עדביה יפול חבלו, והוא יודה על חלקו אמרים נאים ושבח:
@1496 **בן פרת.** בן חן, והוא לשון ארמי אפריון נמטייה לרבי שמעון בסוף בבא מציעא (קיט א) : **בן פרת עלי עין.** חנו נטוי על העין הרואה אותו: **בנות צעדה עלי שור.** בנות מצרים היו צועדות על החומה להסתכל ביפיו. ובנות הרבה צעדה, כל אחת ואחת במקום שתוכל לראותו משם. עלי שור. על ראיתו, כמו (במדבר כד יז) אשורנו ולא קרוב. ומדרשי אגדה יש רבים, וזה נוטה לישוב המקרא: **פרת.** תי''ו שבו הוא תקון הלשון, כמו (קהלת ג יח) על דברת בני האדם: **שור.** כמו לשור: **עלי שור.** בשביל לשור. ותרגום של אנקלוס בנות צעדה עלי שור תרין שבטין יפקון מבנוהי וכו' . וכתב בנות על שם בנות מנשה בנות צלפחד שנטלו חלק בשני עברי הירדן. ברי דיסגי יוסף פורת לשון פריה ורביה. ויש מדרשי אגדה המתישבים על הלשון בשעה שבא עשו לקראת יעקב, בכלן קדמו האמהות ללכת לפני בניהם להשתחוות, וברחל כתיב (לעיל לג ז) נגש יוסף ורחל וישתחוו. אמר יוסף רשע הזה עינו רמה, שמא יתן עיניו באמי, יצא לפניה ושרבב קומתו לכסותה, והוא שברכו אביו בן פורת, הגדלת עצמך יוסף עלי עין של עשו, לפיכך זכית לגדלה: **בנות צעדה עלי שור.** להסתכל בך בצאתך על מצרים. ועוד דרשוהו לענין שלא תשלט בזרעו עין רעה, ואף כשברך מנשה ואפרים ברכם כדגים שאין עין רעה שולטת בהם:
@1497 **וימררהו ורבו.** וימררוהו אחיו, וימררוהו פוטיפר ואשתו לאסרו, לשון (שמות א יד) וימררו את חייהם: **ורבו.** נעשו לו אחיו אנשי ריב. ואין הלשון הזה לשון פעלו, שאם כן היה לו לנקד ורבו, כמו (במדבר כ יג) המה מי מריבה אשר רבו וגו' . ואף אם לשון רבית חצים הוא, כך היה לו להנקד. ואינו אלא לשון פעלו, כמו שמו שמים (ירמיה ב יב) , שהוא לשון הושמו, וכן (איוב כד כד) רומו מעט, שהוא לשון הורמו. אלא שלשון הורמו והושמו על ידי אחרים, ולשון שמו, רמו, רבו, מאליהם הוא, משוממים את עצמם, נתרוממו מעצמם, נעשו אנשי ריב. וכן (ישעיה כג ב) דמו יושבי אי, כמו נדמו. וכן תרגם אנקלוס ונקמוהי: **בעלי חצים.** שלשונם כחץ. ותרגומו לשון (במדבר לא לו) ותהי המחצה, אותן שהיו ראוים לחלוק עמו נחלה:
@1498 **ותשב באיתן קשתו.** נתישבה בחזק. קשתו, חזקו: **ויפזו זרעי ידיו.** זו היא נתינת טבעת על ידו, לשון (מלכים א' י יח) זהב מופז, זאת היתה לו מידי הקדוש ברוך הוא שהוא אביר יעקב, ומשם עלה להיות רעה אבן ישראל, עיקרן של ישראל לשון (זכריה ד ז) האבן הראשה לשון מלכות. ואונקלוס אף הוא כך תרגמו. ותשב. ותבת בהון נביאותיה, החלומות אשר חלם להם, על דקים אוריתא בסתרא, תוספת הוא ולא מלשון עברי שבמקרא, ושוי תוקפא רוחצניה, תרגום של באיתן קשתו, וכך לשון התרגום על העברי ותשב נבואתו, בשביל שאיתנו של הקדוש ברוך הוא היתה לו לקשת ולמבטח. בכן יתרמא דהב על דרעוהי, לכך ויפזו זרעי ידיו, לשון פז: **אבן ישראל.** לשון נוטריקון אב ובן, אבהן ובנין, יעקב ובניו. ורבותינו דרשו ותשב באיתן קשתו על כבישת יצרו באשת אדוניו, וקוראו קשת על שם שהזרע יורה כחץ. ויפזו זרעי ידיו, כמו ויפוצו. שיצא הזרע מבין אצבעות ידיו: **מידי אביר יעקב.** שנראתה לו דמות דיוקנו של אביו וכו' כדאיתא בסוטה (דף לו ב) :
@1499 **מאל אביך.** היתה לך זאת והוא יעזרך: **ואת שדי.** ועם הקדוש ברוך הוא היה לבך, כשלא שמעת לדברי אדונתך והוא יברכך: **ברכת שדים ורחם.** ברכתא דאבא ודאמא, כלומר יתברכו המולידים והיולדות, שיהיו הזכרים מזריעין טפה הראויה להריון, והנקבות לא ישכלו את רחם שלהן להפיל עבריהן: **שדים.** כמו (שמות יט יג) ירה יירה, דמתרגמינן אישתדאה ישתדי, אף שדים כאן על שם שהזרע יורה כחץ:
@1500 **ברכת אביך גברו** וגו' **.** הברכות שברכני הקדוש ברוך הוא גברו והלכו על הברכות שברך את הורי: **עד תאות גבעות עולם.** לפי שהברכות שלי גברו עד סוף גבולי גבעות עולם, שנתן לי ברכה פרוצה בלי מצרים, מגעת עד ארבע קצות העולם שנאמר (לעיל כח יד) ופרצת ימה וקדמה וגו' , מה שלא אמר לאברהם אבינו וליצחק. לאברהם אמר (שם יג יד. טו) שא נא עיניך וראה צפנה וגו' , כי את כל הארץ אשר אתה רואה לך אתננה, ולא הראהו אלא ארץ ישראל בלבד, ליצחק אמר (שם כו ג) כי לך ולזרעך אתן את כל הארצות האל והקימותי את השבועה וגו' , זהו שאמר ישעיה (נח יד) והאכלתיך נחלת יעקב אביך, ולא אמר נחלת אברהם: **תאות.** אשמול''ץ בלע''ז [גבול], כך חברו מנחם בן סרוק: **הורי.** לשון הריון, שהורוני במעי אמי, כמו (איוב ג ג) הורה גבר: **עד תאות.** עד קצות, כמו (במדבר לד י) והתאויתם לכם לגבול קדמה (שם לד ח) תתאו לבא חמת: **תהיין.** כלם לראש יוסף: **נזיר אחיו.** פרישא דאחוהי, שנבדל מאחיו, כמו (ויקרא כב ב) וינזרו מקדשי בני ישראל, (ישעיה א ד) נזרו אחור. ואונקלוס תרגם תאות גבעת עולם, לשון תאוה וחמדה, וגבעות לשון (שמואל א' ב ח) מצוקי ארץ, שחמדתן אמו והזקיקתו לקבלם:
@1501 **בנימין זאב יטרף.** זאב הוא אשר יטרף, נבא על שיהיו עתידין להיות חטפנין (שופטים כא כא) וחטפתם לכם איש אשתו, בפילגש בגבעה, ונבא על שאול שיהיה נוצח באויביו סביב, שנאמר (ש''א יד מז) ושאול לכד המלוכה וילחם וגו' במואב ובאדום ובכל אשר יפנה ירשיע: **בבקר יאכל עד.** לשון בזה ושלל, המתורגם (במדבר לא יב) עדאה. ועוד יש לו דומה בלשון עברית (ישעיה לג כג) אז חלק עד שלל מרבה, ועל שאול הוא אומר שעמד בתחלת פריחתן וזריחתן של ישראל: **ולערב יחלק שלל.** אף משתשקע שמשן של ישראל על ידי נבוכדנצר שיגלם לבבל, יחלק שלל. מרדכי ואסתר שהם מבנימין יחלקו את שלל המן, שנאמר (אסתר ח ז) הנה בית המן נתתי לאסתר. ואונקלוס תרגם על שלל הכהנים בקדשי המקדש:
@1502 **וזאת אשר דבר להם אביהם ויברך אותם.** והלא יש מהם שלא ברכם אלא קנטרן. אלא כך פרושו וזאת אשר דבר להם אביהם מה שנאמר בענין. יכול שלא ברך לראובן שמעון ולוי, תלמוד לומר ויברך אותם, כלם במשמע: **איש אשר כברכתו.** ברכה העתידה לבא על כל אחד ואחד: **ברך אתם.** לא היה לו לומר אלא איש אשר כברכתו ברך אותו, מה תלמוד לומר ברך אותם, לפי שנתן ליהודה גבורתו של אריה, ולבנימין חטיפתו של זאב, ולנפתלי קלותו של איל, יכול שלא כללן בכל הברכות, תלמוד לומר ברך אותם:
@1503 **נאסף אל עמי.** על שם שמכניסין הנפשות אל מקום גניזתן, שיש אסיפה בלשון עברי שהיא לשון הכנסה, כגון (שופטים יט טו) ואין איש מאסף אותם הביתה, (דברים כב ב) ואספתו אל תוך ביתך, (ויק' כג לט) באספכם את תבואת הארץ, הכנסתם לבית מפני הגשמים, (שמות כג טז) באספך את מעשיך. וכל אסיפה האמורה במיתה אף היא לשון הכנסה: **אל אבותי.** עם אבותי:
@1507 **ויאסף רגליו.** הכניס רגליו: **ויגוע ויאסף.** ומיתה לא נאמרה בו, ואמרו רבותינו זכרונם לברכה יעקב אבינו לא מת:
@1509 **לחנט את אביו.** ענין מרקחת בשמים הוא:
@1510 **וימלאו לו.** השלימו לו ימי חניטתו עד שמלאו לו ארבעים יום: **ויבכו אתו מצרים שבעים יום.** ארבעים לחניטה, ושלשים לבכיה, לפי שבאה להם ברכה לרגלו, שכלה הרעב, והיו מי נילוס מתברכין:
@1512 **אשר כריתי לי.** כפשוטו כמו (שמות כא לג) כי יכרה איש. ומדרשו עוד מתישב על הלשון, כמו אשר קניתי. אמר רבי עקיבא כשהלכתי לכרכי הים היו קורין למכירה כירה, ועוד מדרשו לשון כרי, דגור, שנטל יעקב כל כסף וזהב שהביא מבית לבן ועשה אותו כרי, ואמר לעשו טול זה בשביל חלקך במערה:
@1513 **כאשר השביעך.** ואם לא בשביל השבועה לא הייתי מניחך, אבל ירא לומר עבור על השבועה, שלא יאמר אם כן אעבר על השבועה שנשבעתי לך שלא אגלה על לשון הקדש שאני מכיר עודף על שבעים לשון ואתה אינך מכיר בו, כדאיתא במסכת סוטה (דף לו ב) :
@1517 **גרן האטד.** מקף אטדין היה. ורבותינו דרשו על שם המאורע שבאו כל מלכי כנען ונשיאי ישמעאל למלחמה, וכיון שראו כתרו של יוסף תלוי בארונו של יעקב, עמדו כלן ותלו בו כתריהם, והקיפוהו כתרים כגרן המקף סיג של קוצים:
@1519 **כאשר צום.** מהו אשר צום:
@1520 **וישאו אתו בניו.** ולא בני בניו, שכך צום אל ישאו מטתי, לא איש מצרי, ולא אחד מבניכם שהם מבנות כנען, אלא אתם, וקבע להם מקום, שלשה למזרח וכן לארבע רוחות, וכסדרן למסע מחנה של דגלים נקבעו כאן. לוי לא ישא שהוא עתיד לשאת את הארון, ויוסף לא ישא שהוא מלך, מנשה ואפרים יהיו תחתיהם, וזהו (במדבר ב ב) איש על דגלו באתת, באות שמסר להם אביהם לשא מטתו:
@1521 **הוא ואחיו וכל העלים אתו.** בחזרתן כאן הקדים אחיו למצרים העולים אתו, ובהליכתן הקדים מצרים לאחיו, שנאמר (לעיל פסוק ז) ויעלו אתו כל עבדי פרעה וגו' ואחר כך (שם ח) כל בית יוסף ואחיו, אלא לפי שראו הכבוד שעשו מלכי כנען שתלו כתריהם בארונו של יעקב נהגו בהם כבוד:
@1522 **ויראו אחי יוסף כי מת אביהם.** מהו ויראו, הכירו במיתתו אצל יוסף, שהיו רגילים לסעוד עמו על שלחנו של יוסף והיה מקרבן בשביל כבוד אביו, ומשמת יעקב לא קרבן: **לו ישטמנו.** שמא ישטמנו. לו מתחלק לענינים הרבה, יש לו משמש בלשון בקשה ולשון הלואי, כגון (לעיל ל לד) לו יהי כדברך, (שם כג יג) לו שמעני, (יהושע ז ז) ולו הואלנו, (במדבר יד ב) לו מתנו. ויש לו משמש בלשון אם ואולי, כגון (דברים לב כט) לו חכמו, (ישעיה מח יח) לוא הקשבת למצותי, (שמואל ב' יח יב) ולו אנכי שקל על כפי. ויש לו משמש בלשון שמא לו ישטמנו, ואין לו עוד דומה במקרא, והוא לשון אולי, כמו (לעיל כד לט) אולי לא תלך האשה אחרי לשון שמא הוא, ויש אולי לשון בקשה כגון (שמו''ב טז יב) אולי יראה ה' בעיני, (יהושע יד יב) אולי ישיב ה' אותי, הרי הוא כמו, (לעיל ל לד) לו יהי כדברך, ויש אולי לשון אם, (לעיל יח כד) אולי יש חמשים צדיקם:
@1523 **ויצוו אל יוסף.** כמו (שמות ו יג) ויצום אל בני ישראל, צוה למשה ולאהרן להיות שלוחים אל בני ישראל, אף זה ויצוו אל שלוחם להיות שליח אל יוסף לומר לו כן. ואת מי צוו, את בני בלהה שהיו רגילין אצלו, שנאמר (לעיל לז ב) והוא נער את בני בלהה: **אביך צוה.** שנו בדבר מפני השלום, כי לא צוה יעקב כן שלא נחשד יוסף בעיניו:
@1524 **שא נא לפשע עבדי אלהי אביך.** אם אביך מת אלהיו קים, והם עבדיו:
@1525 **וילכו גם אחיו.** מוסף על השליחות:
@1526 **כי התחת אלהים אני.** שמא במקומו אני, בתמיהה, אם הייתי רוצה להרע לכם, כלום אני יכול, והלא אתם כלכם חשבתם עלי רעה והקדוש ברוך הוא חשבה לטובה, והיאך אני לבדי יכול להרע לכם:
@1528 **וידבר על לבם.** דברים המתקבלים על הלב, עד שלא ירדתם לכאן היו מרננים עלי שאני עבד, ועל ידיכם נודע שאני בן חורין, ואם אני הורג אתכם מה הבריות אומרות כת של בחורים ראה ונשתבח בהן, ואמר אחי הם, ולבסוף הרג אותם, יש לך אח שהורג את אחיו. דבר אחר עשרה נרות לא יכלו לכבות נר אחד וכו' :
@1530 **על ברכי יוסף.** כתרגומו, גדלן בין ברכיו:

@1 **בְּרֵאשִׁית בָּרָא אֱלֹהִים** . אמר רבי יצחק: לא היה צריך להתחיל התורה אלא מ"הַחֹדֶשׁ הַזֶּה לָכֶם" (שמות יב ב), שהיא מצווה ראשונה שנצטוו בה ישראל. ומה טעם פתח בבראשית? שאם יאמרו אומות העולם: "ליסטים אתם, שכבשתם לכם ארצות שבעה גוים", הם אומרים להם: "כל הארץ של הקב"ה היא, ונתנה לאשר ישר בעיניו; וברצונו נתנה להם, וברצונו נטלה מהם ונתנה לנו". וזו אגדה בלשון שכתבה רבינו שלמה בפירושיו.
@1 ויש לשאול בה, כי צורך גדול הוא להתחיל התורה ב"בְּרֵאשִׁית בָּרָא אֱלֹהִים", כי הוא שורש האמונה; ושאינו מאמין בזה וחושב שהעולם קדמון, הוא כופר בעיקר ואין לו תורה כלל.
@1 והתשובה, מפני שמעשה בראשית – סוד עמוק, אינו מובן מן המקראות, ולא יוודע על בוריו אלא מפי הקבלה עד משה רבינו מפי הגבורה, ויודעיו חייבין להסתיר אותו. לכך אמר רבי יצחק שאין להתחלת התורה צורך ב"בְּרֵאשִׁית בָּרָא", והסיפור במה שנברא ביום ראשון ומה נעשה ביום שני ושאר הימים, והאריכות ביצירת אדם וחוה, וחטאם ועונשם, וסיפור גן עדן וגירוש אדם ממנו, כי כל זה לא יובן בינה שלימה מן הכתובים. וכל שכן ספור דור המבול והפלגה, שאין הצורך בהם גדול. ויספיק לאנשי התורה בלעדי הכתובים האלה, ויאמינו בכלל בנזכר להם בעשרת הדברות (שמות כ י): "כִּי שֵׁשֶׁת יָמִים עָשָׂה ה' אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ אֶת הַיָּם וְאֶת כָּל אֲשֶׁר בָּם וַיָּנַח בַּיּוֹם הַשְּׁבִיעִי", ותישאר הידיעה ליחידים שבהם הלכה למשה מסיני, עם התורה שבעל פה.
@1 ונתן רבי יצחק טעם לזה, כי התחילה התורה ב"בְּרֵאשִׁית בָּרָא אֱלֹהִים" וסיפור כל עניין היצירה עד בריאת אדם, ושהמשילו במעשה ידיו וכל שת תחת רגליו, וגן עדן – שהוא מבחר המקומות הנבראים בעולם הזה – נעשה מכון לשבתו, עד שגירש אותו חטאו משם. ואנשי דור המבול, בחטאם גורשו מן העולם כולו, והצדיק בהם לבדו נמלט, הוא ובניו. וזרעם, חטאם גרם להם להפיצם במקומות ולזרותם בארצות, ותפשו להם המקומות למשפחותם בגוייהם כפי שנזדמן להם. אם כן ראוי הוא, כאשר יוסיף הגוי לחטוא, שיאבד ממקומו ויבוא גוי אחר לרשת את ארצו, כי כן הוא משפט האלהים בארץ מעולם.
@1 וכל שכן עם המסופר בכתוב כי כנען מקולל ונמכר לעבד עולם, ואינו ראוי שיירש מבחר מקומות היישוב, אבל יירשוה עבדי ה' זרע אוהבו, כעניין שכתוב (תהלים קה מד): "וַיִּתֵּן לָהֶם אַרְצוֹת גּוֹיִם וַעֲמַל לְאֻמִּים יִירָשׁוּ בַּעֲבוּר יִשְׁמְרוּ חֻקָּיו וְתוֹרֹתָיו יִנְצֹרוּ". כלומר, שגירש משם מורדיו, והשכין בו עובדיו, שיידעו כי בעבודתו ינחלוה, ואם יחטאו לו – תקיא אותם הארץ כאשר קאה את הגוי אשר לפניהם.
@1 ואשר יבאר הפירוש שכתבתי, לשונם בבראשית רבה (פרשה א) שאמרוה שם בלשון הזה: רבי יהושע דסכנין בשם רבי לוי פתח, "כֹּחַ מַעֲשָׂיו הִגִּיד לְעַמּוֹ" (תהלים קיא ו). מה טעם גילה להם הקב"ה לישראל מה שנברא ביום ראשון ומה שנברא ביום שני? מפני ז' אומות, שלא יהיו מונין את ישראל ואומרים להם: הלא אומה של בזיזות אתם. וישראל משיבין להם: ואתם הלא בזוזה היא בידכם, הלא "כַּפְתֹּרִים הַיֹּצְאִים מִכַּפְתּוֹר הִשְׁמִידֻם וַיֵּשְׁבוּ תַחְתָּם" (דברים ב כג). העולם ומלואו של הקב"ה הוא, כשרצה – נתנו לכם; כשרצה – נטלו מכם ונתנו לנו. הדא הוא דכתיב (תהלים קיא ו), "לָתֵת לָהֶם נַחֲלַת גּוֹיִם" – "כֹּחַ מַעֲשָׂיו הִגִּיד לְעַמּוֹ": בשביל לתת להם נחלת גוים, הגיד להם את בְּרֵאשִׁית.
@1 וכבר בא להם ממקום אחר עוד העניין שהזכרתי. בתעלומות מעשה בראשית, אמרו רבותינו ז"ל: "כֹּחַ מַעֲשָׂיו הִגִּיד לְעַמּוֹ", להגיד כוח מעשה בראשית לבשר ודם אי אפשר; לפיכך סתם לך הכתוב בְּרֵאשִׁית בָּרָא אֱלֹהִים. אם כן נתבאר מה שאמרנו בזה.
@1 בְּרֵאשִׁית בָּרָא אֱלֹהִים – כתב רש"י: אין המקרא הזה אומר אלא "דרשני", כמו שדרשוהו רבותינו: בשביל התורה שנקראת ראשית, שנאמר (משלי ח כח) "ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ", ובשביל ישראל שנקראו ראשית, שנאמר (ירמיהו ב ג) "קֹדֶשׁ יִשְׂרָאֵל לה' רֵאשִׁית תְּבוּאָתו". והמדרש הזה לרבותינו סתום וחתום מאד, כי דברים רבים מצאו שנקראו ראשית, ובכולם להם מדרשים, וקטני אמנה יספרו להם לרובם. אמרו (ברשית רבה פרשה א): בזכות שלושה דברים נברא העולם: בזכות חלה, בזכות מעשרות, ובזכות ביכורים. בְּרֵאשִׁית בָּרָא אֱלֹהִים – אין ראשית אלא חלה, שנאמר (במדבר טו כ): "רֵאשִׁית עֲרִסֹתֵכֶם". ואין רֵאשִׁית אלא מעשרות, שנאמר (דברים יח ד): "רֵאשִׁית דְּגָנְךָ". ואין ראשית אלא ביכורים, שנאמר (שמות כג יט): "רֵאשִׁית בִּכּוּרֵי אַדְמָתְךָ". ועוד אמרו (שם): בזכות משה, שנאמר (דברים לג כא): "וַיַּרְא רֵאשִׁית לוֹ".
@1 וכוונתם זו, שמילת בְּרֵאשִׁית תרמוז כי בעשר ספירות נברא העולם. ורמז לספירה הנקראת חכמה שבה יסוד כל, כעניין שנאמר (משלי ג יט): "ה' בְּחָכְמָה יָסַד אָרֶץ", היא התרומה. והיא קודש, אין לה שיעור למיעוט התבוננות הנבראים בה. וכאשר ימנה אדם עשר מדות ויפריש אחת מעשר, רמז לעשר ספירות, יתבוננו החכמים בעשירית וידברו בה. וְהַחַלָה – מצווה יחידה בעיסה – תרמוז לזה. וישראל שנקראו "ראשית", היא כנסת ישראל המשולה בשיר השירים לכלה, שקראה הכתוב "בת" ו"אחות" ו"אם", וכבר בא להם זה במדרש (שיר השירים רבה פרשה ג): "בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ" (שיר השירים ג יא), ובמקומות רבים. וכן "וַיַּרְא רֵאשִׁית לוֹ" דמשה, יסברו כי משה רבינו נסתכל באיספקלריא המאירה וַיַּרְא רֵאשִׁית לוֹ, ולכן זכה לתורה. הכל כוונה אחת להם.
@1 ואי אפשר להאריך בפירוש זה העניין במכתב, והרמז רב הנזק, כי יסברו בו סברות אין בהם אמת. אבל הזכרתי זה לבלום פי קטני אמנה מעוטי חכמה, המלעיגים על דברי רבותינו.
@1 בְּרֵאשִׁית – כתב רש"י: ואם באת לפרשו כפשוטו כך פרשהו: בְּרֵאשִׁית בריית שמים וארץ, והארץ היתה תהו ובהו וחושך, ויאמר הקב"ה יהי אור. אם כן, הכל נמשך לבריאת האור.
@1 ורבי אברהם פירש כעניין זה בעצמו, אבל תיקן כי הו"ו במילת "והארץ" אינה משמשת, ורבות כן במקראות. והטעם, כי בראשית בריאת הרקיע והיבשה לא היה בארץ ישוב, אבל היתה תהו ובהו מכוסה במים, ויאמר אלהים יהי אור. ולפי דעתו, לא נברא ביום ראשון, רק האור.
@1 והקושיא לרבינו שלמה בפירוש הזה, כי אמר, שאם בא להורות סדר הבריאה באלו לומר שהם קדמו – היה לו לכתוב "בראשונה", שאין "רֵאשִׁית" במקרא שאינו סמוך. והנה "מַגִּיד מֵרֵאשִׁית אַחֲרִית" (ישעיהו מו י). ואם יסמוך אותו ל"דבר", גם זה תסמוך אותו. ועוד, "וַיַּרְא רֵאשִׁית לוֹ" (דברים לג כא). וטען בזה עוד טענות.
@1 ועתה שמע פירוש המקרא על פשוטו נכון וברור. הקב"ה ברא כל הנבראים מאפיסה מוחלטת. ואין אצלנו בלשון הקדש בהוצאת היש מאין אלא לשון "ברא"; ואין כל ה"נעשה" – תחת השמש או למעלה – הווה מן האין התחלה ראשונה. אבל הוציא מן האפס הגמור המוחלט יסוד דק מאד, אין בו ממש, אבל הוא כוח ממציא, מוכן לקבל הצורה ולצאת מן הכוח אל הפועל. והוא החומר הראשון, נקרא ליוונים "היולי". ואחר ההיולי לא ברא דבר, אבל יצר ועשה, כי ממנו המציא הכל והלביש הצורות ותיקן אותן.
@1 ודע, כי השמים וכל אשר בהם – חומר אחד, והארץ וכל אשר בה – חומר אחד. והקב"ה ברא אלו שניהם מאין, ושניהם לבדם נבראים, והכל נעשים מהם.
@1 והחומר הזה, שקראו היולי, נקרא בלשון הקדש "תֹּהוּ", והמלה נגזרה מלשונם (קידושין מ ב): "בתוהא על הראשונות". מפני שאם בא אדם לגזור בו שֵם, תוהא ונמלך לקוראו בשם אחר, כי לא לבש צורה שיתפש בה השם כלל. והצורה הנלבשת לחומר הזה נקראת בלשון הקדש "בֹּהוּ", והמלה מורכבת, כלומר "בּוֹ הוּא", כמלת "לֹא תוּכַל עֲשֹׂהוּ" (שמות יח יח), שמחוסר הו"ו והאל"ף, עֲשׂוֹ הוּא.
@1 וזהו שאמר הכתוב (ישעיהו לד יא): "וְנָטָה עָלֶיהָ קַו תֹהוּ וְאַבְנֵי בֹהוּ", כי הוא הקו אשר בו יתחם האומן מחשבת בניינו ומה שיקוה לעשות, נגזר מן "קַוֵּה אֶל ה'" (תהלים כז יד), והאבנים הם צורות בבניין. וכן כתוב: "מֵאֶפֶס וָתֹהוּ נֶחְשְׁבוּ לוֹ" (ישעיהו מ יז), כי התוהו אחר האפס, ואיננו דבר. וכך אמרו בספר יצירה: "יצר מתהו ממש ועשה אינו ישנו".
@1 ועוד אמרו במדרש רבי נחוניא בן הקנה (ספר הבהיר): אמר רבי ברכיה, מאי דכתיב: "והארץ היתה תהו ובהו"? מאי משמע "היתה"? שכבר היתה תהו. ומאי "בֹהוּ"? אלא תהו היתה, ומאי "תֹהוּ"? דבר המתהא בני אדם, וחזרה לבהו. ומאי "בֹהוּ"? דבר שיש בו ממש, דכתיב "בּוֹ הוּא".
@1 ואמר "אֱלֹהִים", בעל הכחות כלם, כי המלה עיקרה "אל", שהוא כח, והיא מלה מורכבת, "אל הם", כאלו "אל" סמוך, "והם" ירמוז לכל שאר הכוחות; כלומר, כוח הכוחות כולם. ועוד יתבאר סוד בזה.
@1 אם כן יהיה פשט הכתובים על נכון, משמעותו, בתחילה "בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם", כי הוציא חומר שלהם מאין, "וְאֵת הָאָרֶץ", שהוציא החומר שלה מאין. "וְהָאָרֶץ" תכלול ארבע היסודות כולם, כמו "וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם" (להלן ב א), שתכלול כל הכדור התחתון. וכן "הַלְלוּ אֶת ה' מִן הָאָרֶץ תַּנִּינִים וְכָל תְּהֹמוֹת" (תהלים קמח ז), וזולתם רבים. והנה בבריאה הזאת, שהיא כנקודה קטנה דקה ואין בה ממש, נבראו כל הנבראים בשמים ובארץ.
@1 ומלת "אֵת", כמו עצם הדבר. ודרשו בה שהיא לעולם לרבות, כי היא נגזרה מן "אָתָה בֹקֶר וְגַם לָיְלָה" (ישעיהו כא יב). וכן אמרו רבותינו (ברשית רבה פרשה א): "אֵת הַשָּׁמַיִם", לרבות חמה ולבנה כוכבים ומזלות; "וְאֵת הָאָרֶץ", לרבות האילנות ודשאים וגן עדן. ואלו כלל כל הנבראים בעל הגוף.
@1 ואחר שאמר כי בתחילה – במאמר אחד ברא אלהים השמים והארץ וכל צבאם, חזר ופירש, כי הארץ אחר הבריאה הזו היתה "תהו", כלומר, חומר אין בו ממש; והיתה "בֹהוּ", כי הלביש אותה צורה. ופירש שבצורה הזו צורת ד' יסודות, שהם האש והמים והעפר והאויר, ומלת "הָאָרֶץ" תכלול ארבעת אלה. והאש נקראת "חֹשֶׁךְ", מפני שהאש היסודית חשוכה; ואלו היתה אדומה, היתה מאדימה לנו הלילה. והמים שנגבל בהם העפר יקרא "תְהוֹם", ולכן יקראו מי הים "תְּהֹמוֹת", כדכתיב (שמות טו ה): "תְּהֹמֹת יְכַסְיֻמוּ"; "קָפְאוּ תְהֹמֹת" (שם ח); "תְּהוֹם יְסֹבְבֵנִי" (יונה ב ו). ויקרא קרקע הים "תְּהוֹם": "וַיִּגְעַר בְּיַם סוּף וַיֶּחֱרָב וַיּוֹלִיכֵם בַּתְּהֹמוֹת כַּמִּדְבָּר" (תהלים קו ט); "מוֹלִיכָם בַּתְּהֹמוֹת כַּסּוּס בַּמִּדְבָּר" (ישעיהו סג יג). והאוויר יקרא "רוּחַ".
@1 וכבר נודע כי היסודות הארבעה – מקשה אחת, והעמוד שלה הוא עיגול הארץ. והמים מקיפין על הארץ, והאוויר מקיף על המים, והאש מקיף על האוויר. ואמר הכתוב כי הארץ לבשה צורה, והיה האש מקיף למעלה על המים והעפר המעורבים, והרוח מנשבת ותיכנס בחושך ותרחף על המים.
@1 ויראה לי שהנקודה הזאת, בלובשה הצורה והיתה בהו, היא שהחכמים קורין אותה "אבן שתיה" (יומא נד ב) שממנה נשתת העולם.
@1 והנה שיעור הכתובים: בתחילה ברא אלהים מאין את השמים, וברא מאין את הארץ, והארץ בהבראה היתה תהו והיתה בהו, ובהם חשך ומים ועפר, ורוח נושבת על המים. והנה הכל נברא ונעשה.
@1 וסמך "הרוח" ל"אלהים", בעבור שהיא דקה מכולם, ולמעלה מהם, רק שהיא מרחפת על פני המים במאמרו של הקב"ה.
@1 ואם תבקש בריאה למלאכים שאינם גוף, לא נתפרש זה בתורה. ודרשו בהם שנבראו ביום שני, שלא תאמר שסייעו בבריאת העולם. אבל אם תזכה ותבין סוד מלת בְּרֵאשִׁית, ולמה לא הקדים לומר "אֱלֹהִים בָּרָא בְּרֵאשִׁית", תדע כי על דרך האמת – הכתוב יגיד בתחתונים וירמוז בעליונים. ומילת בְּרֵאשִׁית תרמוז בחכמה, שהיא ראשית הראשים, כאשר הזכרתי. ולכך תרגמו בתרגום ירושלמי "בחכמתא", והמילה מוכתרת בכתר בי"ת.
@3 **וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר** . מילת אמירה בכאן להורות על החפץ, כדרך "מַה תֹּאמַר נַפְשְׁךָ וְאֶעֱשֶׂה לָּךְ" (שמואל א כ ד), מה תרצה ותחפוץ, וכן "וּתְהִי אִשָּׁה לְבֶן אֲדֹנֶיךָ כַּאֲשֶׁר דִּבֶּר ה'" (להלן כד נא), כאשר רצה; כי כן הוא הרצון לפניו. או הוא כגון מחשבה, כמו "הָאֹמְרָה בִּלְבָבָהּ" (ישעיהו מז ח); "וְאָמְרוּ אַלֻּפֵי יְהוּדָה בְּלִבָּם" (זכריה יב ה). והעניין, לומר שלא היה בעמל. וכך קראו רבותינו לזה "מחשבה"; אמרו: מחשבה – ביום; המעשה – עם דמדומי חמה. והוא להורות על דבר מחושב שיש בו טעם, לא חפץ פשוט בלבד. ומילת הויה – מורה על מעשה הזמן העומד, כמו "וְאַתָּה הֹוֶה לָהֶם לְמֶלֶךְ" (נחמיה ו ו). ולכן אמר הכתוב, כי כשברא חומר השמים – אמר שיהיה מן החומר ההוא דבר מזהיר, קראו אור.
@3 "וַיְהִי אוֹר" – לא אמר "וַיְהִי-כֵן", כאמור בשאר הימים, לפי שלא עמד האור בתכונה הזאת כל הימים כשאר מעשה בראשית. ויש לרבותינו בזה מדרש בסוד נעלם.
@3 ודע, כי הימים הנזכרים במעשה בראשית היו בבריאת השמים והארץ ימים ממש, מחוברים משעות ורגעים, והיו שישה כששת ימי המעשה, כפשוטו של מקרא. ובפנימיות הענין יקראו "ימים" הספירות האצולות מעליון, כי כל מאמר פועל הויה תיקרא "יוֹם". והיו שישה, כי לה' הגדולה והגבורה. והמאמרים עשרה, כי הראשונות אין שם "יוֹם" נתפס בהם. והפירוש בסידור הכתובים בזה נשגב ונעלם, ודעתנו בו פחות מטיפה מן הים הגדול.
@4 **וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב** . כתב רבינו שלמה: אף בזה אנו צריכין לדברי אגדה: ראה שאינו ראוי להשתמש בו רשעים, והבדילו לצדיקים לעתיד לבוא. ולפי פשוטו כך פרשהו: ראהו כִּי טוֹב, ואין נאה לו ולחשך להשתמש בערבוביא, וקבע לזה תחומו ביום ולזה תחומו בלילה.
@4 ורבי אברהם אמר: וַיַּרְא – כמו "וְרָאִיתִי אָנִי" (קהלת ב יג), והיא במחשבת הלב. וטעם וַיַּבְדֵּל – בקריאת השמות.
@4 ואין דברי שניהם נכונים: שאם כן, ייראה כענין הַמְלָכָה ועצה חדשה, שיאמר, כי אחרי שאמר אלהים: "יְהִי אוֹר", והיה אור, ראה אותו כי טוב הוא, ולכן הבדיל בינו ובין החשך, כעניין באדם שלא ידע טיבו של דבר עד היותו.
@4 אבל הסדר במעשה בראשית, כי הוצאת הדברים אל הפועל יקרא "אמירה": "וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר" (כאן); "וַיֹּאמֶר... יְהִי רָקִיעַ" (פסוק ו); "וַיֹּאמֶר... תַּדְשֵׁא הָאָרֶץ" (פסוק יא).. וקיומם יקרא "ראיה", כעניין "וְרָאִיתִי אָנִי" דקהלת (ב יג); וכן "וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל" (להלן ג ו). והוא כעניין שאמרו (כתובות קט א): "רואה אני את דברי אדמון", וכמוהו (שמואל ב טו כז): "וַיֹּאמֶר הַמֶּלֶךְ אֶל צָדוֹק הַכֹּהֵן הֲרוֹאֶה אַתָּה שֻׁבָה הָעִיר בְּשָׁלוֹם". והעניין, להורות כי עמידתם בחפצו, ואם החפץ2 יתפרד רגע מהם – יהיו לאין. וכאשר אמר בכל מעשה יום ויום: "וַיַּרְא אֱלֹהִים כִּי טוֹב", ובשישי כאשר נשלם הכל: "וַיַּרְא אֱלֹהִים אֶת כָּל אֲשֶׁר עָשָׂה וְהִנֵּה טוֹב מְאֹד" (פסוק לא), כן אמר ביום הראשון בהיות האור: וַיַּרְא אֱלֹהִים כִּי טוֹב, שרצה בקיומו לעד.
@4 והוסיף בכאן אֶת הָאוֹר. שאילו אמר סתם: וַיַּרְא אֱלֹהִים כִּי טוֹב, היה חוזר על בריאת השמים והארץ; ולא גזר בהן עדיין הקיום, כי לא עמדו ככה, אבל מן החומר הנברא בראשון – נעשה בשני רקיע, ובשלישי נפרדו הַמַּיִם והעפר ונעשית הַיַּבָּשָׁה שקראה "אֶרֶץ", ואז גזר בהם הקיום ואמר בהם: "וַיַּרְא אֱלֹהִים כִּי טוֹב".
@4 וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ – איננו החשך הנזכר בפסוק הראשון, שהוא האש, אבל הוא אפיסת האור; כי נתן אלהים מידה לאור, ושיהיה נעדר אחר כן עד שובו.
@4 ואמרו קצת המפרשים, כי האור הזה נברא לפניו של הקב"ה, כלומר במערב, ושיקעו מיד כדי מידת לילה, ואחרי כן האיר כמידת יום. וזה טעם "וַיְהִי עֶרֶב וַיְהִי בֹקֶר" (פסוק ה), שקודם היה לילה, ואחר כך יום, ושניהם אחרי הויית האור. ואיננו נכון כלל, כי יוסיפו על ששת ימי בראשית יום קצר.
@4 אבל ייתכן שנאמר, כי האור נברא לפניו יתברך, ולא נתפשט ביסודות הנזכרים. והבדיל בינו ובין החשך, שנתן לשניהם מידה. ועמד לפניו כמידת לילה, ואחר כך הזריח אותו על היסודות. והנה קדם הערב לבוקר.
@4 ועוד ייתכן שנאמר, כי משיצאו השמים והארץ מן האפס אל היש הנזכר בפסוק הראשון, נהיה זמן. כי אף על פי שזמנינו ברגעים ושעות, שהם באור ובחשך, משיהיה יש – ייתפש בו זמן. ואם כן, נבראו שמים וארץ, ועמדו כן כמידת לילה מבלי אוֹר, ואמר "יְהִי אוֹר", וַיְהִי אוֹר, וגזר עליו שיעמוד כמידת הראשון, ואחר כך ייעדר מן היסודות; "וַיְהִי עֶרֶב וַיְהִי בֹקֶר".
@5 **וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם** . יאמר כי נברא הזמן ועשה מדת יום ומדת לילה וענין "וַיִּקְרָא" מפני שהאדם קרא השמות אמר באלו שנעשו קודם היותו כי האלהים קרא להם שמות וזה דעת רבי אברהם והנכון שענין "קריאה" באלו בכאן היא ההבדלה המוגבלת בהם כשלבשו צורתם וכך אמרו (ב"ר ג ו) יום יהא תחומך ולילה יהא תחומך
@5 "וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד" - היה ערב והיה בקר של יום אחד ויקרא תחילת הלילה "עֶרֶב" בעבור שיתערבו בו הצורות ותחלת היום "בֹקֶר" שיבקר אדם בינותם כך פירש רבי אברהם ועל דרך הפשט לא יתכן לומר "יום ראשון" בעבור שעדיין לא נעשה השני כי הראשון קודם לשני במנין או במעלה אבל שניהם נמצאים וה"אֶחָד" לא יורה על שני ויש מפרשים (מורה נבוכים ב ל) כי זה רמז לתנועת הגלגל על פני כל הארץ בעשרים וארבע שעות שכל רגע מהם בקר במקומות משתנים וערב במקומות שכנגדם ואם כן ירמוז לאשר יהיה ברקיע אחרי הנתן המאורות ברקיע השמים
@6 **יְהִי רָקִיעַ** . החומר ההווה בתחלה שבראו מאין אמר שיהיה רקיע מתוח כאהל בתוך המים ויהיה מבדיל בין מים למים ושמא לזה כוונו באמרם (אב"ר ד א) רב אמר לחים היו שמים ביום הראשון וביום השני קרשו רב אמר יְהִי רָקִיעַ יחזק הרקיע רבי יהודה ברבי סימון אמר יעשה מטלית הרקיע כמה דאת אמר (שמות לט ג) וַיְרַקְּעוּ אֶת פַּחֵי הַזָּהָב וגו'
@6 "בְּתוֹךְ הַמָּיִם" - באמצע המים בין מים העליונים למים התחתונים כמו שיש הפרש בין הרקיע למים שעל הארץ כך יש הפרש בין מים העליונים לרקיע הא למדת שהן תלויים במאמר בראשית רבה (ד ג) וכתבה רש"י וזה מענין מעשה בראשית הוא ואל תקוה ממני שאכתוב בו דבר שהענין הוא מסתרי התורה ואין הפסוקים צריכים לביאור הזה כי לא יאריך הכתוב בענינו והפירוש אסור ליודעיו וכל שכן אלינו
@7 **וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ** . לשון עשייה בכל מקום תקון הדבר על מתכונתו
@7 "וַיְהִי-כֵן" - הכתיב בראשון "וַיְהִי אוֹר" אחר "וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר" אחר האמירה פירש שיצא אל הפועל והיה כאשר נגזר אבל בכאן אחר אמירת "יְהִי רָקִיעַ" כתוב וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ וַיַּבְדֵּל ולמה הוסיף "וַיְהִי-כֵן" אבל הוא לומר שהיה כן תמיד כל ימי עולם ורבי אברהם פירש כי הוא דבק עם הבא אחריו כאשר היה כן קרא לָרָקִיעַ שָׁמָיִם ואינו נכון ובבראשית רבה (ד ו) אמרו וַיַּעַשׂ אֱלֹהִים אֶת-הָרָקִיעַ זו אחד מן המקראות שהרעיש בן זומא את העולם וַיַּעַשׂ אֱלֹהִים וכו' והלא במאמר בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ (תהלים לג ו) ואין ההרעשה הזו מלשון "וַיַּעַשׂ" לבדו שהרי ברביעי ובששי כתוב "וַיַּעַשׂ" אבל היה מזה שאמרתי בעבור כי בשאר הימים כתוב אחר האמירה "וַיְהִי-כֵן" לומר שנהיה כן מיד תיכף אחר האמירה אבל כאן אחר "וַיֹּאמֶר אֱלֹהִים" כתוב "וַיַּעַשׂ" זו היא קושיתו ואולי היה לו פירוש נסתר לא רצה לגלות סודו וזה ענין הרעש
@8 **וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם** . ביום השני קראם בשם הזה כאשר הלביש אותם צורת רקיע כי בראשון היו שמים בבריאה אבל אין השם נתפש בהם עד שלבשו הצורה הזו ופירוש השם הזה כאלו הוא נקוד בסגול תחת השי"ן כמלת (שיר השירים א ז) "שַׁלָּמָה" אֶהְיֶה כְּעֹטְיָה כאלו אמר שמים הם שנרקעו ונמתחו כאהל בתוך המים העליונים והתחתונים הודיע בשם הזה סוד יצירתם ובגמרא במסכת חגיגה (יב) אמרו מאי שמים שם מים ואם כן הוא יחסר מ"ם אחד להתחברות שתי אותיות שוות כמלת "יְרֻבַּעַל" (שופטים ו לב ועוד) ויאמר שם מים כלומר שם שקרא למים בלבשם צורה אחרת וזה פשט הכתובים על הדרך הזה שכתב רש"י והוא דעת רב שהזכרנו (בפסוק ו) ויהי שם "הַשָּׁמַיִם" ו"הָאָרֶץ" בפסוק הראשון על העתיד לקרא להם כי לא יתכן להודיעם רק בלשון הזה אבל יותר נכון לפי פשט הכתובים שנאמר כי הַשָּׁמַיִם הנזכרים בפסוק הראשון הם הַשָּׁמַיִם העליונים אינם מכלל הגלגלים אבל הם למעלה מן המרכבה כענין וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא נָטוּי עַל רָאשֵׁיהֶם מִלְמָעְלָה (יחזקאל א כב) ומהם נקרא הקב"ה "רוֹכֵב שָׁמַיִם" (דברים לג כו) ולא סיפר הכתוב בבריאתם דבר כאשר לא הזכיר המלאכים וחיות המרכבה וכל דבר נפרד שאינו בעל גוף רק הזכיר בשמים שהם נבראים כלומר שקדמותם אפס ואמר בשני שיהיה רקיע בתוך המים כלומר שיתהוה מן המים הנזכרים שהזכיר בריאתם דבר מרוקע מבדיל ביניהם וקרא גם לאלו הכדורים שמים כשם השמים העליונים הראשונים ולכן יקראם בפרשה (בפסוק יז) "רְקִיעַ שָׁמַיִם" ויתן אותם אלהים ברקיע הַשָּׁמַיִם לבאר שאינם הנזכרים בשם הַשָּׁמַיִם רק הרקיעים שקראם שָׁמַיִם וגם זה דעת רבותינו הזכירוהו בבראשית רבה (ד ב) אמרו כל רבנין אמרין לה בשם רבי חנניה ברבי פנחס ורבי יעקב ברבי אבין בשם רבי שמואל ברבי נחמן בשעה שאמר הקב"ה "יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם" גלדה טיפה האמצעית ונעשו שמים התחתונים ושמי הַשָּׁמַיִם העליונים ומאמר זה יתפשט לכדורי הגלגלים שבהם תחתונים ועליונים נקראים "שְׁמֵי הַשָּׁמַיִם" כדכתיב (תהלים קמח ג-ד) הַלְלוּהוּ שֶׁמֶשׁ וְיָרֵחַ הַלְלוּהוּ כָּל כּוֹכְבֵי אוֹר הַלְלוּהוּ שְׁמֵי הַשָּׁמָיִם וְהַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמָיִם אבל השמים הנזכרים בראשון ששם כסאו של הקב"ה דכתיב (ישעיהו סו א) הַשָּׁמַיִם כִּסְאִי הם הנזכרים בתחלת זה המזמור (תהלים קמח א-ב) הַלְלוּ אֶת ה' מִן הַשָּׁמַיִם הַלְלוּהוּ בַּמְּרוֹמִים הַלְלוּהוּ כָל מַלְאָכָיו וזה הלשון נכון בפשט הכתוב עם מה שיש עוד בשם השמים ובשם הכסא סוד נשגב ונעלם כי יש שמים לשמים וכסא לכסא ומזה אומרים החכמים (ברכות יג) כדי לקבל עליו עול מלכות שמים ואמרו (שם ז) יראת שמים והכתוב אמר דִּי שַׁלִּטִן שְׁמַיָּא (דניאל ד כג) ויש להם מדרש נפלא (ספר הבהיר אות ק) במה שכתוב דאתה תִּשְׁמַע הַשָּׁמַיִם (מלכים א ח לב) וכל זה יראנו נרמז בפסוק הראשון הזוכה לו והנה בארו הכתובים כי הנבראים הראשונים הם מאין והשאר מוצאם מן החומר הראשון הנברא ואל יקשה עליך מאמר רבי אליעזר הגדול (פרקי דר"א ג) שאמר שמים מהיכן נבראו מאור לבושו של הקב"ה וכן הוא בבראשית רבה עוד כי בעבור שירצו החכמים עוד להעלות החומר הראשון עד תכלית ולעשותו דק מן הדקים לא יראו שהשמים שהם גוף מתנועע בעל חומר וצורה הם הנבראים מן האין אבל אור הלבוש הוא הנברא הראשון וממנו יצא חומר הממש בשמים ונתן לארץ חומר אחר ואיננו כדקות הראשון והוא שלג שתחת כסא הכבוד כי כסא הכבוד נברא וממנו היה השלג שתחתיו וממנו נעשה חומר הארץ והנה הוא שלישי בבריאה
@9 **יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם** . היה הַתְּהוֹם שהוא מים ועפר כעין הַמַּיִם העכורים וגזר על הַמַּיִם שיקוו במקום אֶחָד מסובב כל הפאות וגזר על העפר שיעלה עד שיראה על הַמַּיִם וייבש ותהיה יבשה שטוחה ראויה לישוב וכן כתוב לְרֹקַע הָאָרֶץ עַל הַמָּיִם(תהלים קלו ו) או שמא שתהיה כדורית מקצתה מגולה ורובה משוקעת אשר ידמו היונים במופתיהם הנראים או המפתים והנה הן שתי גזרות כלומר שני ענינים נעשים בחפץ אלהים הפך מן הנאות בטבעם כי הראוי לכבדות העפר ולקלות הַמַּיִם כנגדה להיות עמוד הארץ אמצעי והמים מכסים עליה מקיפים אותה מכל צד ועל כן אמר יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם כלומר אֶל מָקוֹם שפלות ואמר וְתֵרָאֶה הַיַּבָּשָׁה וקרא להם שמות בהיותם לובשים הצורות האלו כי מתחילה היה שמם "תְּהוֹם"
@10 **וַיִּקְרָא אֱלֹהִים לַיַּבָּשָׁה אֶרֶץ** . יאמר כי שמה הראוי לה "יַבָּשָׁה" כי בהפרד המים מן העפר היא יבשה אבל יקרא אותה "אֶרֶץ" כשם כלל היסודות הנברא בראשון והטעם כי בעבורה נבראו שתהיה ישוב לאדם שאין בתחתונים מכיר בוראו זולתו וקרא למקוה הַמַּיִם "יַמִּים" כאילו הוא "ים מים" לפי שקרקע המקוה נקרא "ים" כדכתיב (ישעיהו יא ט) כַּמַּיִם לַיָּם מְכַסִּים וכן וְאֶת הַיָּם הוֹרִד מֵעַל הַבָּקָר (מלכים ב טז יז) כי מפני שהוא מקוה מים גדול יקרא כן
@10 "וַיַּרְא אֱלֹהִים כִּי טוֹב" - הוא קיומם בחפצו והענין כי כאשר הלבישם הצורה הזו חפץ בהם והיה הקיום כמו שפירשתי (בפסוק ד) וזה מה שאמרו רבותינו (ב"ר ד ו) מפני מה לא נאמר כי טוב בשני לפי שלא נגמרה מלאכת המים לפיכך כתוב בשלישי שני פעמים אחד למלאכת המים ואחד למלאכת היום
@11 **וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא** . גזר שיהיה בתולדות הארץ כח הצומח ומוליד זרע כדי שיהיה המין קיים לעד ויתכן שירמוז בארץ הנזכרת בפסוק הראשון שימשך ממנה כח מצמיח והנה נאצלו מכחה היסודות למיניהם ומהם צמחו בגן עדן דשאים ואילנות ומהם בעולם וזהו שאמרו (ב"ר יא ט) בשלישי ברא שלש בריות אילנות ודשאים וגן עדן ועוד אמרו (שם י ו) אין לך כל עֵשֶׂב ועשב מלמטה שאין לו מזל ברקיע ומכה אותו ואומר לו גדל הדא הוא דכתיב (איוב לח לג) הֲיָדַעְתָּ חֻקּוֹת שָׁמָיִם אִם תָּשִׂים מִשְׁטָרוֹ בָאָרֶץ שוטר ואמר שיהיה כל זה למינהו והוא אסור הַכִּלְאַיִם כי הזורע אותם מכחיש בכח מעשה בראשית ועוד אבאר בו בעזרת השם (בויקרא יט יט) וכתב רבינו שלמה דֶּשֶׁא עֵשֶׂב לא דֶּשֶׁא לשון עֵשֶׂב ולא עֵשֶׂב לשון דֶּשֶׁא שלשון דֶּשֶׁא לבישת הארץ בעשבים ואין לומר דֶּשֶׁא פלוני וכל שרש לעצמו נקרא עֵשֶׂב ואין דברו זה נכון שאם כן לשון "דֶּשֶׁא" לא יתרבה וחכמים אומרים הרכיב שני מיני דשאים מהו (חולין ס) והרב עצמו מזכיר דשאים אבל דֶּשֶׁא הוא הקטן הצומח וְעֵשֶׂב הוא הגדול המזריע ולכן יאמר "תַּדְשֵׁא הָאָרֶץ" ולא יתכן לומר "תעשיב" וכל קטן הצומח מן הארץ יקרא "דֶּשֶׁא" אף באילנות ולכן ימשך תדשא הארץ עץ פרי כי לא אמר "תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב ותוציא עֵץ פְּרִי" והנה הוא כטעם צמיחה וכן כִּי דָשְׁאוּ נְאוֹת מִדְבָּר כִּי עֵץ נָשָׂא פִרְיוֹ (יואל ב כב) ואני תמה איך לא הזכיר הכתוב אילני הסרק ואיך צוה בעץ פרי לבדו ואולי בזה נתעוררו רבותינו שאמרו (ב"ר ה ט) אף אילני סרק עשו פירות ואם כן נאמר כי מקללת "אֲרוּרָה הָאֲדָמָה" (להלן ג יז) היו סרק ויתכן שיהיה פירוש הכתוב תצמיח הארץ צמח ועשב מזריע זרע ועץ עושה פרי והנה בתחילה גזר בעשבי הסרק ובאילני הסרק וממה שאמר "עֹשֶׂה פְּרִי אֲשֶׁר זַרְעוֹ בוֹ" (פסוק יב) נלמוד כי כל האילנות יצמחו מזרעם אף על פי שהמנהג במקצתם ליטע מהם הענף
@12 **וַיַּרְא אֱלֹהִים כִּי טוֹב** . קיום המינין לעד והנה לא נתיחד יום למאמר הזה לבדו מפני שאיננו מעשה מיוחד כי הארץ כאשר תצמיח או שתהיה ארץ מליחה אחת היא
@14 **יְהִי מְאוֹרוֹת** . הנה האור נברא ביום ראשון ומאיר ביסודות וכאשר נעשה הרקיע בשני הפסיק באור ומנע אותו מהאיר ביסודות התחתונים והנה כאשר נבראת הארץ בשלישי היה בה חשך ולא אור ועתה ברביעי רצה הקב"ה שיהיו ברקיע מאורות מגיעים אור לארץ וזה טעם "בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ" כי האור היה למעלה מן הרקיע ולא האיר על הארץ וענין "יְהִי מְאוֹרוֹת" כי מחומר השמים גזר בראשון שיהיה אור במדת היום ועתה גזר שיתגשם ויתהוה ממנו גוף מאיר ביום גדול האורה וגוף אחר קטן האורה מאיר בלילה ויתלו שניהם ברקיע השמים שיאירו גם למטה ויתכן כי כמו ששם בארץ כח הצמיחה במקומות ממנה כן שם ברקיע מקומות מוכנים ומזומנים לקבל האורה והגופים האלה מקבלי אור מזהירים כגון האספקלריאות ואבני השהם ולכן יקראם מְאוֹרוֹת לא אוֹרִים אף על פי שקראם המזמור כן (תהלים קלו ז)
@14 "לְהַבְדִּיל בֵּין הַיּוֹם וּבֵין הַלָּיְלָה" - כתב רש"י משנגנז האור הראשון אבל בששת ימי בראשית שמשו האור והחשך זה ביום וזה בלילה ואיני רואה שיהיה זה דעת רבותינו המזכירים "גניזה" על האור הראשון אבל לדעתם האור הראשון שמש שלשה ימים וברביעי נאצל ממנו ונעשו בו אז ממנו שני המאורות האלה כמו שאמרו (ב"ר יז ה) נובלת אורה של מעלה גלגל חמה כי לפי שלא היה העולם הזה ראוי להשתמש באור ההוא בלי אמצעות גנזו לצדיקים לעולם הבא ושמשו בנובלת הזו מיום רביעי ואילך כך אמרו בבראשית רבה (ג ו) תני אורה שנבראת בששת ימי בראשית להאיר ביום אינה יכולה מפני שהיא מכהה גלגל חמה בלילה אינה יכולה שלא נבראת להאיר אלא ביום והיכן היא נגנזה והיכן היא מתוקנת לצדיקים לעתיד לבא שנאמר (ישעיהו ל כו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים שבעה אתמהה לא שלשה הן כאינש דאמר "כן אנא מפקיד לשבעה יומי דמשתותי" כלומר לשון בני אדם הוא שיאמר "אני מפקיד ושומר זה הבשר לשבעת ימי המשתה שלי" לא שיספיק לו לשבעה כולם אלא שיוציא אותו בתוכם וכך אמרו "שִׁבְעַת הַיָּמִים" כְּאוֹר שהיה בימים ההם במקצתם ושם אמרו עוד (ב"ר ג ו) ויבדל רבי יהודה ברבי סימון אמר הבדילו לו ורבנן אמרין הבדילו לצדיקים לעתיד לבא ואם תוכל לדעת כוונתם באמרם בברכת הלבנה "עטרת תפארת לעמוסי בטן" תדע סוד האור הראשון והגניזה וההבדלה שאמר הבדילו לו וסוד שני המלכים המשתמשים בכתר אחד כאשר בסוף שיהיה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה אחר שיהיה אוֹר הַחַמָּה שִׁבְעָתַיִם
@14 "וְהָיוּ לְאוֹתוֹת" - השנוי שיולידו ויעשו ממנו אותות וּמוֹפְתִים בַּשָּׁמַיִם וּבָאָרֶץ דָּם וָאֵשׁ וְתִימֲרוֹת עָשָׁן (יואל ג ג) כלשון וּמֵאֹתוֹת הַשָּׁמַיִם אַל תֵּחָתּוּ (ירמיהו י ב) ולמועדים זֶרַע וְקָצִיר וְקוֹר וָחוֹם וְקַיִץ וָחוֹרֶף (להלן ח כב) וּלְיָמִים מדת יום ומדת לילה ושנים ישלימו מהלכם ויוסיפו שנית לשוב בדרך אשר הלכו בה ושנת החמה בשס"ה יום ושנת הלבנה בשלשים יום
@15 **וְהָיוּ לִמְאוֹרֹת בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ** . הוסיף שיהיה אורם מגיע לארץ, כי אפשר שיראה להם אור בשמים ויעשו כל המעשים הנזכרים מבלי שיאירו בארץ. ולכך אמר שיהיו למאורות ברקיע השמים ומביט בארץ ויאירו עליה.
@16 **וַיַּעַשׂ אֱלֹהִים וַיִּתֵּן אֹתָם אֱלֹהִים** . מלמד שלא נהיו אלו המאורות מגוף הרקיע אבל גופים (נטבעים) נקבעים בו
@18 **וְלִמְשֹׁל בַּיּוֹם וּבַלַּיְלָה** . ענין הממשלה דבר אחר מבלי האורה שהזכיר כי יכלול מה שאמר תחלה "וְהָיוּ לְאֹתֹת וּלְמוֹעֲדִים" כי יש להם ממשלה בארץ בשנוייה אשר יולידו בה וממשלה בהוייה ובהפסד בכל השפלים כי השמש בממשלתו ביום יצמיח ויוליד ויגדל בכל החמים והיבשים והירח בממשלתו יפרה במעינות ובימים וכל הלחים והקרים ועל כן אמר סתם
@18 "וְלִמְשֹׁל בַּיּוֹם וּבַלַּיְלָה" - כי ממשלת השפלים להם ויתכן שהממשלה עוד כח אצילות שהם מנהיגי התחתונים ובכחם ימשול כל מושל והמזל הצומח ביום ימשול בו והמזל הצומח בלילה ימשול בה כענין שכתוב (דברים ד יט) אֲשֶׁר חָלַק ה' אֱלֹהֶיךָ אֹתָם לְכֹל הָעַמִּים והוא מה שאמר הכתוב (תהלים קמז ד) מוֹנֶה מִסְפָּר לַכּוֹכָבִים לְכֻלָּם שֵׁמוֹת יִקְרָא וכן לְכֻלָּם בְּשֵׁם יִקְרָא (ישעיהו מ כו) כי קריאת השמות היא ההבדלה בכחותם לזה כח הצדק והיושר ולזה כח הדם והחרב וכן בכל הכחות כידוע באצטגנינות והכל בכח עליון ולרצונו ולכך אמר גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ (תהלים קמז ה) כי הוא גָּדוֹל על כולם וְרַב כֹּחַ עליהם וכן אמר מֵרֹב אוֹנִים וְאַמִּיץ כֹּחַ (ישעיהו מ כו) ועל דרך הסוד שרמזתי לך תהיה ממשלה גמורה באמת
@18 "וּלֲהַבְדִּיל בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ" - אמר רבי אברהם כי בצאת השמש ביום ואור הלבנה בלילה יבדילו בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ ולפי דעתי כי ה"אוֹר" הנזכר בכאן הוא היום וה"חֹשֶׁךְ" הוא הלילה כי כן שמם כמו שאמר (לעיל פסוק ה) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם וְלַחֹשֶׁךְ קָרָא לָיְלָה והנה בכל מעשה בראשית יזכיר הכתוב הצוואה ויספר המעשה ובכאן צוה "וְהָיוּ לִמְאוֹרֹת" (לעיל טו) וספר "וַיִּתֵּן אֹתָם אֱלֹהִים" (לעיל יז) ואמר "וְלִמְשֹׁל בַּיּוֹם וּבַלַּיְלָה" שיהיה זה מושל ביום וזה מושל בלילה והממשלה הוא מה שצוה "וְהָיוּ לְאֹתֹת וּלְמוֹעֲדִים" (לעיל יד) וספר שאין ממשלת שניהם שוה אבל "לֲהַבְדִּיל בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ" כי הגדול ימשול ביום ויהיה כולו אור גם במקום שאין השמש מגיע והקטן ימשול בלילה ויהיה חשך זולתי הירח שיגיה חשכו והיא הצוואה שאמר "לְהַבְדִּיל בֵּין הַיּוֹם וּבֵין הַלָּיְלָה" (שם) כמו "וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחֹשֶׁךְ" (לעיל ד)
@20 **יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ** . כתב רש"י כל דבר חי שאינו גבוה מן הארץ קרוי שרץ בעוף כגון זבובים בשקצים כגון נמלים ותולעים בבריות כגון חולד ועכבר וכיוצא בהם וכל הדגים ומה יאמר הרב בפסוק וְאַתֶּם פְּרוּ וּרְבוּ שִׁרְצוּ בָאָרֶץ וּרְבוּ בָהּ שנאמר בנח ובניו (להלן ט ז) וכן "אֲשֶׁר שָׁרְצוּ הַמַּיִם" ראוי לפי הדעת הזו שיאמר "אשר שרצו במים" ועופות רבים שאינם גבוהים מן הארץ כגובה החולד העכבר והעטלף קטן הרגלים מאד ולמה לא יקרא "שֶׁרֶץ הָעוֹף" ודעת אונקלוס שענין שריצה כטעם תנועה אמר בשרץ וברמש ריחשא דרחיש ויפה פירש ויקראו השרצים כן בעבור שתנועתם תמידית ויתכן שהוא לשון מורכב יקרא שרץ "שהוא רץ" ורמש שהוא רומש הארץ לא ישקוט ולא ינוח ודע כי כל העוף אשר לו ארבע רגלים יקרא "שֶׁרֶץ הָעוֹף" (ויקרא יא כ-כג) מפני שברגליו יסמוך וינוע כשרצים ואשר איננו כן יקרא "עוֹף כָּנָף" שעיקר תנועתו לעופף ויהיה טעם "וְשָׁרְצוּ בָאָרֶץ וּפָרוּ וְרָבוּ עַל הָאָרֶץ" (להלן ח יז) שיהיו מתהלכים בכולה ויפרו וירבו עליה "שִׁרְצוּ בָאָרֶץ וּרְבוּ בָהּ" (להלן ט ז) התנועעו בכולה ותרבו בה והוא טעם הכפל "וּרְבוּ" שני פעמים בפסוק ואם כן נפרש "אֲשֶׁר שָׁרְצוּ הַמַּיִם" ((להלן פסוק כא) אֲשֶׁר הניעו והוליכו הַמַּיִם וכן וְשָׁרַץ הַיְאֹר צְפַרְדְּעִים (שמות ז כח) וכן פָּרוּ וַיִּשְׁרְצוּ (שם א ז) שפרו ורבו וינועו לרובם עד שתמלא הארץ מהם אבל אונקלוס פתר ב"שִׁרְצוּ בָאָרֶץ" (להלן ט ז) ענין תולדה "איתילידו בארעא" כי הוא עשה הלשון מושאל מן השרצים ואתם פרו ורבו כשרצים בארץ ורבו בה וכן "פָּרוּ וַיִּשְׁרְצוּ" (שמות א ז) שהיו בתולדותם כשרצים לרוב
@20 "וְעוֹף יְעוֹפֵף עַל הָאָרֶץ" - ביום הזה היה מאמר הבריאה במים והיה ביום הששי בארץ אם כן פירוש "וְעוֹף יְעוֹפֵף עַל הָאָרֶץ" נמשך יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה וְעוֹף שיעופף והכתוב שאמר ויצר ה' אלהים מן האדמה כל חית השדה ואת כל עוף השמים (להלן ב יט) כאלו אמר "וַיִּצֶר ה' אֱלֹהִים מִן הָאֲדָמָה כָּל חַיַּת הַשָּׂדֶה וְאֵת כָּל עוֹף הַשָּׁמַיִם" ורבים כמוהו וכן דעת רבי אליעזר הגדול בפרקיו (ריש פרק ט) שאמר בחמישי השריץ מן המים כל עוף כנף אבל בגמרא (חולין כז) נחלקו בו יש אומרין כן שמן המים נבראו ויש אומרין שהעוף משניהם נברא אמרו מהרקק נבראו ואם כן בעבור שתולדותם היתה במים והרקק בקרקע הים הוא מפני זה היה המאמר בהם ביום החמישי וכן אמר "יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה" כי הדגים גופם ונפשם מן המים בדבר האלהים שהביא להם רוח מן היסודות לא כאדם שהפריד גופו מנפשו כמו שאמר וַיִּיצֶר ה' אלהים אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים (להלן ב ז) ולא הזכיר בשלישי בצומח נפש כלל כי אין כח הגדול נפש רק בבעלי התנועה בלבד היא ועל דעת היונים שאומרים כשם שאין הגדול במתנועע רק בנפש כך בצומח בנפש יגדל יהיה הפרש כי זאת נפש חיה כלומר נפש שיש בו חיות כי יש נפש אין בה חיות והיא נפש הצומחת והזכירו רבותינו (ב"ר מא א) באילני התמרים תאוה ואולי הוא כח בצמיחה לא יקרא נפש
@21 **וַיִּבְרָא אֱלֹהִים אֶת הַתַּנִּינִם הַגְּדֹלִים** . בעבור גודל הנבראים האלה שיש מהם אורכם פרסאות רבות הגידו היונים בספריהם שידעו מהם ארוכים חמש מאות פרסה ורבותינו גם כן הפליגו בהם (עיין ב"ב עג) בעבור זה ייחס בהם הבריאה לאלהים כי הוא שהמציאם מאין מבראשית כאשר פירשתי לשון בריאה (לעיל פסוק א) וכן יעשה באדם למעלתו להודיע כי הוא מוצא מאין עם דעתו ושכלו ואני תמה למה לא אמר ביום הזה "וַיְהִי-כֵן" ואולי לא יתכן להזכיר "וַיִּבְרָא" אחרי "וַיְהִי-כֵן" כי מבראשונה ידבר ורבותינו אמרו (בבא בתרא עד) כי התנינים הגדולים הוא לויתן ובת זוגו שבראם זכר ונקבה והרג הנקבה ומלחה לצדיקים לעתיד לבא ואפשר כי מפני זה לא היה ראוי שיאמר בהם "וַיְהִי-כֵן" כי לא עמדו עוד
@22 **וַיְבָרֶךְ אֹתָם אֱלֹהִים לֵאמֹר** . גזר בהם הברכה ואמר בהם שיפרו וירבו כלומר שיעשו פירות רבים שיוציא האחד רבים כמותו וענין הברכה בילידה כענין שאמר וברכתיה והיתה לגוים (להלן יז טז) וגם בצמחים תבא לשון ברכה (ויקרא כה כא) וְצִוִּיתִי אֶת בִּרְכָתִי לָכֶם בַּשָּׁנָה הַשִּׁשִּׁית אבל לא נאמר כן בשלישי לפי שהנבראים בכל בעלי הנפש היו שנים בלבד זכר ונקבה למיניהם כענין באדם והוצרכו לברכה שירבו מאד אבל בצמחים צמחו על פני כל האדמה רבים מאד כאשר הם היום ולא אמר בבהמות ובחיות ברכה שמזאת הגזירה שגזר בבעלי הנפש התנועה שבמים הרבוי נתרבו בעלי נפש התנועה שבארץ כי בעלי נפש חיה שאינה מדברת כולם ענין אחד בבריאתם ורבותינו אמרו (ב"ר יא ג) כי בעבור היות בני אדם צדים מהם ואוכלים הוצרכו לברכה
@22 "וּמִלְאוּ אֶת הַמַּיִם בַּיַּמִּים" - בירך אותם שימלאו לרובם הימים אף הנחלים והאגמים או שמלואם בימים הוא כי בנחלים מעטים הם וְהָעוֹף יִרֶב בָּאָרֶץ אף על פי שבריאתו מן המים ברכתו תהיה בארץ שיפרו וירבו עליה כי אין בעוף שיטיל ביציו במים ויגדלו שם רק השוכנים תמיד במים וניזונים מהם עושין ביציהם בארץ ונולדים בה
@24 **בְּהֵמָה** . הם המינים האוכלים עֵשֶׂב בין ישובי בין מדברי וְחַיְתוֹ אֶרֶץ אוכלי הבשר יקרא חיות וכלם יטרופו
@24 "וָרֶמֶשׂ" - כתב רש"י הם שרצים נמוכים ורומשים עַל הָאָרֶץ נראין כאילו נגררין והנה בפרשה הזאת (להלן פסוק כח) וּבְכָל חַיָּה הָרֹמֶשֶׂת עַל הָאָרֶץ וכתיב (להלן ז כא) וַיִּגְוַע כָּל בָּשָׂר הָרֹמֵשׂ עַל הָאָרֶץ בָּעוֹף וּבַבְּהֵמָה וּבַחַיָּה וּבְכָל הַשֶּׁרֶץ הַשֹּׁרֵץ עַל הָאָרֶץ וכתיב (תהלים קד כ) בּוֹ תִרְמֹשׂ כָּל חַיְתוֹ יָעַר אבל פירוש "רמישה" כענין בסמ"ך מן תִּרְמְסֶנָּה רָגֶל (ישעיהו כו ו) וחביריו ואמר בחיה ובבהמה "רֹמֵשׂ עַל הָאָרֶץ" ובשרצים הנגררים "רֶמֶשׂ הָאֲדָמָה" (פסוק כה) בעבור שדריכתם באדמה בכל גופם
@26 **וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם** . נתייחד בעשיית האדם מאמר בעבור גודל מעלתו כי אין טבעו כטבע החיה והבהמה אשר ברא במאמר הקודם לו והפשט הנכון במלת "נַעֲשֶׂה" הוא מפני שכבר הראית לדעת (לעיל פסוק א) כי האלהים בָּרָא יש מאין ביום הראשון לבדו ואחר כך מן היסודות ההם הנבראים יצר ועשה וכאשר נתן במים כח השרוץ לשרוץ נפש חיה והיה המאמר בהם "יִשְׁרְצוּ הַמַּיִם" (פסוק כ) והיה המאמר בבהמה "תּוֹצֵא הָאָרֶץ" (פסוק כד) אמר באדם "נַעֲשֶׂה" כלומר אני והארץ הנזכרת נַעֲשֶׂה אָדָם שתוציא הארץ הגוף מיסודיה כאשר עשתה בבהמה ובחיה כדכתיב (להלן ב ז) וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה ויתן הוא יתברך הרוח מפי עליון כדכתיב (שם) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים ואמר "בְּצַלְמֵנוּ כִּדְמוּתֵנוּ" כי ידמה לשניהם במתכונת גופו לארץ אשר לוקח ממנה וידמה ברוח לעליונים שאינה גוף ולא תמות ואמר בכתוב השני בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ (פסוק כז) לספר הפלא אשר נפלא בו משאר הנבראים וזה פשט המקרא הזה מצאתיו לרבי יוסף הקמחי והוא הנראה מכל מה שחשבו בו ופירוש "צֶלֶם" כמו תאר וּצְלֵם אַנְפּוֹהִי אֶשְׁתַּנִּי (דניאל ג יט) וכן אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ (תהלים לט ז) בָּעִיר צַלְמָם תִּבְזֶה (([תהלים עג כ|שם עג כ]]) תאר מראיתו ו"דמות" הוא דמיון בצורה ובמעשה כי הקרובים בענין יקראו דומים זה לזה והנה האדם דומה לתחתונים ולעליונים בתאר והדר כדכתיב (תהלים ח ו) וְכָבוֹד וְהָדָר תְּעַטְּרֵהוּ והוא מגמת פניו בחכמה ובדעת וכשרון המעשה ובדמות ממש שידמה גופו לעפר ונפשו לעליונים
@26 "וְיִרְדּוּ בִדְגַת הַיָּם" - בעבור היותו זָכָר וּנְקֵבָה אמר "וְיִרְדּוּ" בִדְגַת הַיָּם לשון רבים ובבראשית רבה (ז ה) אמרו תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ אמר רבי אלעזר נֶפֶשׁ חַיָּה זו רוחו של אדם הראשון ולא יתכן שיאמר רבי אלעזר כי "תּוֹצֵא הָאָרֶץ" יתפרש בנפשו של אדם הראשון כלל אלא שיתכוין למה שהזכרתי לומר כי יצירת האדם ברוחו הוא הנפש אשר בדם נעשה מן הארץ כמאמר החיה והבהמה כי כל נפשות התנועה נעשו יחד ואחר כן ברא להם גופות עשה תחילה גופי הבהמה והחיה ואחר כך גוף האדם ונתן בו הנפש הזו ואחר כן נפח בו נשמה עליונית כי הנפש הנפרדת אשר בו היא שנתיחד בה מאמר אחר אל האלהים אשר נתנה כדכתיב (להלן ב ז) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים ודרך האמת בפסוק הזה יודע למשכיל בפסוק השני ואפשר שנתכוין לו רבי אלעזר ודרש ב"תּוֹצֵא הָאָרֶץ" ארץ החיים שתוצא נפש חיה למינה לעולם עומדת וכן מה שאמר זָכָר וּנְקֵבָה בָּרָא אֹתָם (להלן א כז, להלן ה ב) כי היתה הבריאה מתחלה מזכר ונקבה ונשמתו כלולה בהם אבל היצירה היתה יצירה לאדם ובנין צלע לאשה כאשר יספר בסוף ולכן הזכיר כאן "בריאה" ובפרשה של מטה הזכיר "יצירה" והמשכיל יבין וטעם וְיִרְדּוּ שימשלו בחזקה בדגים ובעוף ובבהמה ובכל הרמש וה"בְּהֵמָה" תכלול החיה ואמר ובכל הארץ שימשלו בארץ עצמה לעקור ולנתוץ ולחפור ולחצוב נחשת וברזל ולשון "רדייה" ממשלת האדון בעבדו
@28 **וַיְבָרֶךְ אֹתָם אֱלֹהִים** . זו ברכה ממש לפיכך כתוב בה וַיֹּאמֶר לָהֶם אֱלֹהִים אבל למעלה (כב) כתוב וַיְבָרֶךְ אֹתָם אֱלֹהִים לֵאמֹר יפרש שהברכה היא המאמר שנתן בהם כח התולדה לא דבור אחד שיהיו בו מבורכים וּמִלְאוּ אֶת הָאָרֶץ ברכה שימלא העולם לרובם ולפי דעתי יברך אותם שימלאו כל הארץ ויפרדו הגוים למשפחותם בקצוי תבל לרובם ולא יהיו במקום אחד כמחשבת אנשי דור הפלגה וכבשוה נתן להם כח וממשלה בארץ לעשות כרצונם בבהמות ובשרצים וכל זוחלי עפר ולבנות ולעקור נטוע ומהרריה לחצוב נחשת וכיוצא בזה וזה יכלול מה שאמר "וּבְכָל הָאָרֶץ" (לעיל פסוק כו)
@28 "וּרְדוּ בִּדְגַת הַיָּם" - אמר שיהיו רודים גם בדגי הים הנכסים מהם וּבְעוֹף הַשָּׁמַיִם שאינם עמהם באדמה גם בכל חיה רעה וסדר אותם כבריאתם הדגים והעוף תחלה והחיה אחר כן וכך אמר הכתוב (תהלים ח ז-ט) תַּמְשִׁילֵהוּ בְּמַעֲשֵׂי יָדֶיךָ כֹּל שַׁתָּה תַחַת רַגְלָיו צֹנֶה וַאֲלָפִים כֻּלָּם וְגַם בַּהֲמוֹת שָׂדָי צִפּוֹר שָׁמַיִם וּדְגֵי הַיָּם וגו' ורבותינו שמו הפרש בין כבישה ורדייה
@29 **הִנֵּה נָתַתִּי לָכֶם אֶת כָּל עֵשֶׂב זֹרֵעַ זֶרַע** . לא הרשה לאדם ולאשתו להמית בריה ולאכול בשר, אך כל ירק עשב יאכלו יחדיו כלם. וכשבאו בני נח התיר להם בשר שנאמר (להלן ט ג) "כָּל רֶמֶשׂ אֲשֶׁר הוּא חַי לָכֶם יִהְיֶה לְאָכְלָה, כְּיֶרֶק עֵשֶׂב נָתַתִּי לָכֶם אֶת כֹּל" - את כל כירק עשב שהתרתי לאדם הראשון התרתי לכם את כל. לשון רש"י. וכן פירש הרב במסכת סנהדרין (נט ד"ה לא הותר) "ולכל חית הארץ" לכם ולחיות נתתי העשבים ואת האילנות "אֶת כָּל יֶרֶק עֵשֶׂב לְאָכְלָה".
@29 ואם כך יהיה פירוש "אֶת כָּל יֶרֶק עֵשֶׂב לְאָכְלָה" "וְאֶת כָּל יֶרֶק עֵשֶׂב לְאָכְלָה" ואינו כן, אבל נתן לאדם ולאשתו "כָּל עֵשֶׂב זֹרֵעַ זֶרַע" וכל פרי עץ, ולחית הארץ ולעוף השמים נתן "כל ירק עשב" לא פרי העץ ולא הזרעים, ואין מאכלם יחד כלם בשוה, אך הבשר לא הורשו בו עד בני נח כדעת רבותינו, והוא פשוטו של מקרא.
@29 והיה זה מפני שבעלי נפש התנועה יש להם קצת מעלה בנפשם, נדמו בה לבעלי הנפש המשכלת, ויש להם בחירה בטובתם ומזוניהם ויברחו מן הצער והמיתה, והכתוב אומר "מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ" (קהלת ג כא). וכאשר חטאו והשחית כל בשר את דרכו על הארץ, ונגזר שימותו במבול ובעבור נח הציל מהם לקיום המין נתן להם רשות לשחוט ולאכול כי קיומם בעבורו. ועם כל זה לא נתן להם הרשות בנפש ואסר להם אבר מן החי. והוסיף לנו במצות לאסור כל דם מפני שהוא מעמד לנפש כדכתיב (ויקרא יז יד) "כִּי נֶפֶשׁ כָּל בָּשָׂר דָּמוֹ בְנַפְשׁוֹ הוּא, וָאֹמַר לִבְנֵי יִשְׂרָאֵל: דַּם כָּל בָּשָׂר לֹא תֹאכֵלוּ כִּי נֶפֶשׁ כָּל בָּשָׂר דָּמוֹ הִוא", כי התיר הגוף בחי שאינו מדבר אחר המיתה, לא הנפש עצמה. וזה טעם השחיטה. ומה שאמרו (ב"מ לב) "צער בעלי חיים דאורייתא", וזו ברכתנו שמברך "אשר קדשנו במצותיו וצונו על השחיטה", ועוד אדבר בענין המצוה בדם בהגיעי שם (ויקרא יז יא-יד) אם גומר השם עלי.
@29 וטעם "אֶת כָּל עֵשֶׂב זֹרֵעַ זֶרַע" ואת כל העץ אשר בו פרי עץ זורע זרע לכם יהיה לאכלה, שיאכלו זרועי העשב כגרגרי החטה והשעורה והקטניות וזולתם, ויאכלו כל פרי העץ, אבל העץ עצמו אינו להם לאכלה, וגם לא העשב, עד שנתקלל אדם ונאמר לו: "וְאָכַלְתָּ אֶת עֵשֶׂב הַשָּׂדֶה" (להלן ג יח).
@31 **וְהִנֵּה טוֹב מְאֹד** . הוא הקיום כאשר פירשתי (לעיל פסוקים ד י יב) וטעם "מְאֹד" כטעם רבוי והוסיף ביום הזה לאמר כן בעבור שידבר בכלל וימצא רע בקצתו ואמר כי טוֹב מְאֹד מאדו טוב וזהו מאמרם בבראשית רבה (ט ה) וְהִנֵּה טוֹב מְאֹד והנה טוב זה מות וכן הזכירו (שם יא) זה יצר הרע וזו מדת פורענות ולזה גם נתכוין אונקלוס שאמר בכאן "והא תקין לחדא" יאמר שהוא מתוקן הסדר מאד כי הרע צריך בקיום הטוב כענין שנאמר (קהלת ג א) לַכֹּל זְמָן וְעֵת לְכָל חֵפֶץ תַּחַת הַשָּׁמָיִם ויש מפרשים כי מפני מעלת האדם הוסיף בשבח היצירה בו כי הוא טוֹב מְאֹד
@32 **וְכָל צְבָאָם** . "צבא הארץ" הם הנזכרים חיה ורמש ודגים וכל הצומח גם האדם ו"צבא השמים" שני המאורות והכוכבים הנזכרים כענין וּפֶן תִּשָּׂא עֵינֶיךָ הַשָּׁמַיְמָה וְרָאִיתָ אֶת הַשֶּׁמֶשׁ וְאֶת הַיָּרֵחַ וְאֶת הַכּוֹכָבִים כֹּל צְבָא הַשָּׁמַיִם (דברים ד יט) גם יכלול השכלים הנבדלים כענין רָאִיתִי אֶת ה' יֹשֵׁב עַל כִּסְאוֹ וְכָל צְבָא הַשָּׁמַיִם עֹמֵד עָלָיו וגו' (מלכים א כב יט) וכן יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם (ישעיהו כד כא) והנה בכאן רמז על יצירת המלאכים במעשה בראשית וכן נפשות האדם צבא השמים הנה
@34 **וַיְבָרֶךְ וַיְקַדֵּשׁ** . ברכו במן וקדשו במן והמקרא כתוב על העתיד לשון רבינו שלמה מבראשית רבה (יא ב) ובשם הגאון רב סעדיה אמרו שהברכה והקידוש על השומרים שיהיו מבורכים ומקודשים ואין משמע הכתוב שידבר על העתיד ורבי אברהם אמר כי הברכה תוספת טוב שיתחדש הגופות יתרון כח בתולדות ובנשמה יתרון השכל וַיְקַדֵּשׁ אותו שלא עשה בו מלאכה כשאר הימים ודברו בזה נכון למאמינים בו כי אין זה מושג בהרגש לאנשים והאמת כי הברכה ביום השבת היא מעין הברכות והוא יסוד עולם וַיְקַדֵּשׁ אֹתוֹ כי ימשוך מן הקדש ואם תבין דברי זה תדע מה שאמרו בבראשית רבה (יא ח) לפי שאין לו בן זוג ומה שאמרו עוד כנסת ישראל תהא בן זוגך ותשכיל כי בשבת נפש יתירה באמת
@34 "אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת" - מלאכה שהיתה ראויה לעשות בשבת כפל ועשה בששי כמו שמפורש בבראשית רבה (יא ט) לשון רש"י אבל רבי אברהם אמר כפשוטו כי מְלַאכְתּוֹ "השרשים בכל המינים שנתן בהם כח לעשות כמותן" ולי נראה פירושו ששָׁבַת מִכָּל מְלַאכְתּוֹ אֲשֶׁר בָּרָא יש מאין לעשות ממנו כל המעשים הנזכרים בששת הימים והנה אמר כִּי שָׁבַת מבריאה וממעשה מן הבריאה שברא ביום הראשון ומן המעשה שעשה בשאר הימים ויתכן שיהיה "לַעֲשׂוֹת" נמשך למעלה כִּי בוֹ שָׁבַת מִכָּל מְלַאכְתּוֹ אֲשֶׁר בָּרָא מלעשות וכמהו כִּי חָדַל לִסְפֹּר (להלן מא מט) וַיַּחְדְּלוּ לִבְנֹת הָעִיר (שם יא ח) הִשָּׁמְרוּ לָכֶם עֲלוֹת בָּהָר (שמות יט יב) וְלֹא סָרוּ מִצְוַת הַמֶּלֶךְ (דהי"ב ח טו) וכן רבים ודע כי נכלל עוד במלת "לַעֲשׂוֹת" כי ששת ימי בראשית הם כל ימות עולם כי קיומו יהיה ששת אלפים שנה (ר"ה לא) שלכך אמרו (ב"ר יט ח) יומו של הקב"ה אלף שנים והנה בשני הימים הראשונים היה העולם כולו מים ולא נשלם בהם דבר והם רמז לשני אלפים הראשונים שלא היה בהם קורא בשם ה' וכך אמרו (ע"ז ט) שני אלפים תהו אבל היתה הבריאה ביום הראשון האור כנגד האלף של ימות אדם שהיה אורו של עולם מכיר את בוראו ואולי לא עבד אנוש עבודה זרה עד שמת אדם הראשון ביום השני יְהִי רָקִיעַ וִיהִי מַבְדִּיל שבו היו מובדלין נח ובניו הצדיקים מן הרשעים שנדונו במים ביום השלישי נראית היבשה והצמיחה ועשתה פירות הוא האלף השלישי המתחיל בהיות אברהם בן מ"ח שנה (ב"ר סד ד) ואָז הוּחַל לִקְרֹא בְּשֵׁם ה' (להלן ד כו) וצמח צמח צדיק כי משך רבים לדעת את ה' כמו שדרשו וְאֶת הַנֶּפֶשׁ אֲשֶׁר עָשׂוּ בְחָרָן (שם יב ה) וצוה את ביתו ואת בניו אַחֲרָיו וְשָׁמְרוּ דֶּרֶךְ ה' לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט (יח יט) ועלה הענין עד שקבלו זרעו את התורה בסיני ונבנה הבית ביום ההוא ואז נתקיימו כל המצות שהם פירות העולם ודע כי מעת היות בין השמשות יחשב כיום מחר ועל כן יתחיל ענין כל יום קודם לו מעט כאשר נולד אברהם באלף השני וכן תראה בכל יום ויום והיום הרביעי נבראו בו המאורות הגדול והקטן והכוכבים יומו ירמוז באלף הד' הוא החל כאשר נבנה בית ראשון ע"ב שנה אחרי בניינו עד אחרי הבית השני קע"ב שנה והנה ביום הזה לכל בני ישראל היה אור כי מלא כבוד ה' את בית ה' והיה אור ישראל לאש על גבי המזבח רבוץ שם כארי אוכל הקרבנות ואחרי כן הקטין אורם וגלו כאשר יעדר במולד הלבנה וזרחה להם כל ימי בית שני והאש על גבי המזבח רבוץ ככלב ושקעו שני המאורים בערב היום וחרב הבית ביום החמישי שרצו המים נפש חיה ועוף יעופף על הארץ רמז לאלף החמישי המתחיל קע"ב שנה אחר חרבן הבית כי בו ימשלו האומות ויעשה אדם כדגי הים כרמש לא מושל בו כלו בחכה העלה יגורהו בחרמו ויאספהו במכמרתו ואין דורש את ה' ביום הששי בבקר "תוצא הארץ נפש חיה למינה בהמה ורמש וחיתו ארץ למינה" והיתה בריאתה קודם זרוח השמש כענין שכתוב (תהלים קד כב) תִּזְרַח הַשֶּׁמֶשׁ יֵאָסֵפוּן וְאֶל מְעוֹנֹתָם יִרְבָּצוּן ואז נברא האדם בצלם אלהים והוא זמן ממשלתו שנאמר (שם כג) יֵצֵא אָדָם לְפָעֳלוֹ וְלַעֲבֹדָתוֹ עֲדֵי עָרֶב והוא האלף הששי כי בתחלתו ימשלו בו החיות הם המלכיות אשר לא ידעו את ה' ואחרי עשיריתו כשעור הנץ החמה ליום (עיין פסחים צד) יבא הגואל שנאמר בו (תהלים פט לז) וְכִסְאוֹ כַשֶּׁמֶשׁ נֶגְדִּי זהו בן דוד הנעשה בצלם אלהים כדכתיב (דניאל ז יגיד) וַאֲרוּ עִם עֲנָנֵי שְׁמַיָּא כְּבַר אֱנָשׁ אָתֵה הֲוָה וְעַד עַתִּיק יוֹמַיָּא מְטָה וּקְדָמוֹהִי הַקְרְבוּהִי וְלֵהּ יְהִיב שָׁלְטָן וִיקָר וּמַלְכוּ ויהיה זה קי"ח אחר חמשת אלפים לכלות דבר ה' מפי דניאל (שם יב יא) וּמֵעֵת הוּסַר הַתָּמִיד וְלָתֵת שִׁקּוּץ שֹׁמֵם יָמִים אֶלֶף מָאתַיִם וְתִשְׁעִים ונראה משנוי הימים משרץ המים והעוף לחית הארץ כי בתחלת האלף הששי תתחדש מלכות אומה שלטת ואימתני ותקיפא יתירא ומתקרבת אל האמת יותר מן הראשונות היום השביעי שבת רמז לעולם הבא שכולו שבת ומנוחה לחיי העולמים והאל ישמרנו בכל הימים וישים חלקינו עם עבדיו התמימים
@35 **אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם** . יספר תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ במטר ובצמיחה כאשר נבראו ונעשו כתקונם כי השמים יתנו טלם ומטרם והארץ תתן יבולה והם קיום כל חי ורמז בְּ"הִבָּרְאָם" מה שאמרו בה"א בראם ומפני זה לא הזכיר עד הנה רק מלת אלהים ומפורש בכתוב (ישעיהו סו ב) וְאֶת כָּל אֵלֶּה יָדִי עָשָׂתָה וכן אמר איוב מִי לֹא יָדַע בְּכָל אֵלֶּה כִּי יַד ה' עָשְׂתָה זֹּאת (איוב יב ט) אם כן תרמוז "בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים" למלת בראשית כמו שאמרנו
@36 **וְכֹל שִׂיחַ הַשָּׂדֶה** . על דעת רבותינו (בבראשית רבה) עיין חולין ס בשלישי עמדו על פתח קרקע הארץ ובששי צמחו לאחר שהמטיר עליהם ועל דעתי כפי הפשט כי בשלישי הוציאה הארץ העשב ועץ הפרי בקומותם וצביונם כאשר צותה בהם ועכשיו יספר הכתוב כי אין נוטע וזורע מהם והיא לא תצמח עד אשר עלה אד ממנה והשקה אותה ונוצר האדם העובד אותה לזרוע ולנטוע ולשמור וזהו טעם "שִׂיחַ הַשָּׂדֶה טֶרֶם יִצְמָח" שלא אמר "שיח האדמה" כי המקום הנעבד יקרא "שדה" אֲשֶׁר תִּזְרַע בַּשָּׂדֶה (שמות כג טז) לֹא נַעֲבֹר בְּשָׂדֶה וּבְכֶרֶם (במדבר כ יז) וזהו תשמישו של עולם שנהיה מאחרי ששת ימי בראשית והלאה כל ימי עולם כי בסיבת האד ימטירו השמים ובסבתם הארץ זירועיה תצמיח
@38 **וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים** . ירמוז לנו הכתוב הזה מעלת הנפש יסודה וסודה כי הזכיר בה שם מלא ואמר כי הוא נפח בְּאַפָּיו נִשְׁמַת חַיִּים להודיע כי לא באה בו מן היסודות כאשר רמז בנֶפֶשׁ התנועה (לעיל א כ) גם לא בהשתלשלות מן השכלים הנבדלים אבל היא רוח השם הגדול מפיו דעת ותבונה כי הנופח באפי אחר מנשמתו יתן בו וזהו שנאמר (איוב לב ח) וְנִשְׁמַת שַׁדַּי תְּבִינֵם כי היא מיסוד הבינה בדרך אמת ואמונה והוא מאמרם בספרי (ריש פרשת מטות) נדרים כנשבע בחיי המלך שבועות כנשבע במלך עצמו אף על פי שאין ראיה לדבר זכר לדבר חַי ה' וְחֵי נַפְשְׁךָ וגומר (מלכים ב ד ל) ובמדרשו של רבי נחוניא בן הקנה (ספר הבהיר אות נז) מאי וינפש מלמד שיום השבת מקיים כל הנפשות שנאמר וינפש ומכאן תבין דברת שבועת אלהים והמשכיל יבין ודע כי המתחכמים במחקר חלקו באדם מהם יאמרו (ראב"ח הנשיא ראב"ע שמות כג כה) כי באדם שלש נפשות נפש הגדול כצומח או תאמר בזו כח הגדול ובו עוד נפש התנועה שהזכירה הכתוב (לעיל א כ-כד) בדגים ובחיה ובכל רומש על הארץ והשלישית הנפש המשכלת ומהם יאמרו (שמונה פרקים להרמב"ם ח"א) כי זאת הנפש אשר באדם מפי עליון בה ימצאו שלש הכחות האלה ורק היא יחידה והכתוב הזה כפי משמעו ירמוז כן כי יאמר שיצר השם אֶת הָאָדָם עָפָר מִן הָאֲדָמָה והיה מוטל גולם כאבן דומם והקב"ה נפח בְּאַפָּיו נִשְׁמַת חַיִּים ואז חזר הָאָדָם להיות "נֶפֶשׁ חַיָּה" שיתנועע בה כמו החיות והדגים שאמר בהם (לעיל א כ כד) "יִשְׁרְצוּ הַמַּיִם שֶׁרֶץ נֶפֶשׁ חַיָּה" ו"תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה" וזה טעם "לְנֶפֶשׁ חַיָּה" כלומר ששב האדם להיות נפש בה חיים אחרי שהיה חרש את חרשי אדמה כי הלמ"ד תבא בהפוכים כמו וְהָיוּ לְדָם בַּיַּבָּשֶׁת (שמות ד ט) וַיְהִי לְנָחָשׁ (שם ד ג) וַיָּשֶׂם אֶת הַיָּם לֶחָרָבָה (שם יד כא) אבל אונקלוס אמר והות באדם לרוח ממללא נראה שדעתו כדברי האומרים שהם נפשות שונות וזאת הנפש המשכלת אשר נפחה השם באפיו היתה בו לנפש מדברת וכן נראה לי מדעת רבותינו ממה שאמרו (סנהדרין סה) רבא ברא גברא שדריה לקמיה דרבי זירא הוה מישתעיה ליה ולא אישתעי אמר דמן דחבריא את תוב לעפרך ובויקרא רבה (לב ב) אמר רבי אבין בשעה שאדם ישן הגוף אומר לנשמה והנשמה אומרת לנפש והנפש אומרת למלאך וכן רוּחוֹ וְנִשְׁמָתוֹ אֵלָיו יֶאֱסֹף(איוב לד יד) יורה כפי משמעו שהן שתים ואם כן יאמר הכתוב וייצר ה' אלהים את האדם יצירת תנועה שהיה האדם נוצר כלומר בעל תנועה כי היצירה היא החיות וההרגש שבהם הוא אדם לא גבול העפר וכמו שאמר וַיִּצֶר ה' אֱלֹהִים מִן הָאֲדָמָה כָּל חַיַּת הַשָּׂדֶה וְאֵת כָּל עוֹף הַשָּׁמַיִם וַיָּבֵא אֶל הָאָדָם (להלן ב יט) ואחרי שיצרו בהרגשה נפח בְּאַפָּיו נִשְׁמַת חַיִּים מפי עליון להוסיף הנפש הזאת על היצירה הנזכרת ויהי הָאָדָם כולו לְנֶפֶשׁ חַיָּה כי בנשמה הזאת ישכיל וידבר ובה יעשה כל מעשה וכל הנפשות וכחותן לה תהיינה והלמ"ד הזו למ"ד הקנין כמו אֲדֹנִי הַמֶּלֶךְ לְךָ אֲנִי וְכָל אֲשֶׁר לִי (מלכים א כ ד) לַקֹּנֶה אֹתוֹ לְדֹרֹתָיו (ויקרא כה ל) לְךָ אֲנִי הוֹשִׁיעֵנִי (תהלים קיט צד) או יאמר שחזר כולו נֶפֶשׁ חַיָּה ונהפך לאיש אחר כי כל יצירותיו היו עתה לְנֶפֶשׁ הזאת
@39 **וַיִּטַּע ה' אֱלֹהִים גַּן בְעֵדֶן מִקֶּדֶם** . פירש רש"י במזרחו של עדן נטע הגן ואונקלוס תרגם מלקדמין וכך אמרו בבראשית רבה (טו ג) והוא הנכון ואין טעם "וַיִּטַּע" שהביא האילנות ממקום אחר ונטען שם כי מן המקום ההוא הצמיחם כמו שנאמר ויצמח ה' אלהים וגו' אבל ענין "וַיִּטַּע ה' אֱלֹהִים" להגיד שהיו מטע ה' כי טרם שגזר על הארץ "תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא" גזר במקום ההוא שיהיה שם גַּן ואמר "בכאן יהיה אילן פלוני ובכאן אילן פלוני" כערוגת המטעים ולא היה כדרך שאר מקומות הארץ שאמר "תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא וְעֵץ פְּרִי" והצמיחה בלא סדר והנה אילני גַּן עֵדֶן גזר בהם לעשות ענף ולשאת פרי לעד לעולם לא יזקין בארץ שרשם ובעפר לא ימות גזעם אין צריכין לעובד וזומר שאילו היו צריכין עבודה אחרי שגורש האדם משם מי עבד אותם גם זה טעם "וַיִּטַּע ה' אֱלֹהִים" שהיו מטעיו מעשה ידיו וקיימים לעולמים כענין שנאמר (יחזקאל מז יב) לֹא יִבּוֹל עָלֵהוּ וְלֹא יִתֹּם פִּרְיוֹ וכו' כִּי מֵימָיו מִן הַמִּקְדָּשׁ הֵמָּה יוֹצְאִים אם כן מה טעם "וַיַּנִּחֵהוּ בְגַן עֵדֶן לְעָבְדָהּ וּלְשָׁמְרָהּ" (להלן פסוק טו) שהניחו שם להיות זורע לו חטים ומיני תבואות וכל עשב זורע זרע וערוגות הבשמים וקוצר ותולש ואוכל כרצונו וזה טעם "לְעָבְדָהּ וּלְשָׁמְרָהּ" לעבוד אדמת הגן הערוגות שיעשה שם כי הגן שהם האילנות לא יעבדו ויתכן שכנה הגן בלשון נקבה כמו וּכְגַנָּה זֵרוּעֶיהָ תַצְמִיחַ (ישעיהו סא יא) וְנִטְעוּ גַנּוֹת (ירמיהו כט ה) ורבותינו נתעוררו בזה אמרו בבראשית רבה (טז ה) לְעָבְדָהּ וּלְשָׁמְרָהּ אלו הקרבנות שנאמר (שמות ג יב) תַּעַבְדוּן אֶת הָאֱלֹהִים הדא הוא דכתיב (במדבר כח ב) תִּשְׁמְרוּ לְהַקְרִיב לִי בְּמוֹעֲדוֹ והכונה להם בזה לומר כי הצמחים וכל בעלי חיים צריכים לכוחות הראשונות ס"א העליונות ומהם יבא להם הגידול ובקרבנות יהיה משך הברכה לעליונים ומהם לצמחי גַּן עֵדֶן ומהם יהיו ויחיו לעולם בגשמי רצון וברכה שיגדלו בה כמו שאמרו (ב"ר טו א) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע (תהלים קד טז) אמר רבי חנינא יִשְׂבְּעוּ חייהן יִשְׂבְּעוּ מימיהן יִשְׂבְּעוּ מטעתן כי "חייהן" יסודותם העליונים ו"מימיהם" אוצרו הטוב המוריד הגשם ו"מטעתן" כחם בשמים כמו שאמרו (ב"ר י ו) אין לך כל עשב ועשב מלמטה שאין לו מזל ברקיע והוא מכה אותו ואומר לו גדל שנאמר (איוב לח לג) הֲיָדַעְתָּ חֻקּוֹת שָׁמָיִם אִם תָּשִׂים מִשְׁטָרוֹ בָאָרֶץ שוטר
@40 **וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן וְעֵץ הַדַּעַת טוֹב וָרָע** . בעבור שאמר הכתוב וְעֵץ הַחַיִּים "בְּתוֹךְ" הַגָּן ולא אמר "בגן" ועוד שאמר (להלן ג ג) וּמִפְּרִי הָעֵץ אֲשֶׁר בְּתוֹךְ הַגָּן אָמַר אֱלֹהִים לֹא תֹאכְלוּ שלא הזכירו ולא הודיעו בשם אחר נאמר לפי פשוטו שהוא מקום ידוע בגן שהוא בתוך ולכך תרגם אונקלוס "במציעות גנתא" והנה לדבריו עֵץ הַחַיִּים וְעֵץ הַדַּעַת שניהם היו באמצע ואם כן נאמר שהוא כאלו תעשה באמצע הגן ערוגה אחת סוגה ובה שני האילנות האלה ויהיה האמצע הזה אמצע רחב כי אמצע הדק כבר אמרו שאין יודע בו אמתת הנקודה בלתי השם לבדו וְעֵץ הַחַיִּים אילן פריו נותן באוכליו חיים ארוכים
@40 "וְעֵץ הַדַּעַת טוֹב וָרָע" - אמרו המפרשים כי היה פריו מוליד תאות המשגל ולכן כסו מערומיהם אחרי אכלם ממנו והביאו לו דומה בלשון זה מאמר ברזילי הגלעדי הַאֵדַע בֵּין טוֹב לְרָע (שמואל ב יט לו) כי בטלה ממנו התאוה ההיא ואיננו נכון אצלי בעבור שאמר וִהְיִיתֶם כֵּאלֹהִים יֹדְעֵי טוֹב וָרָע (להלן ג ה) ואם תאמר כחש לה הנה וַיֹּאמֶר ה' אֱלֹהִים הֵן הָאָדָם הָיָה כְּאַחַד מִמֶּנּוּ לָדַעַת טוֹב וָרָע (להלן ג כב) וכבר אמרו (פירקא דרבינו הקדוש בבא דשלשה טז) שלשה אמרו אמת ואבדו מן העולם ואלו הן נחש ומרגלים ודואג האדומי הבארותי והיפה בעיני כי האדם היה עושה בטבעו מה שראוי לעשות כפי התולדת כאשר יעשו השמים וכל צבאם פועלי אמת שפעולתם אמת ולא ישנו את תפקידם ואין להם במעשיהם אהבה או שנאה ופרי האילן הזה היה מוליד הרצון והחפץ שיבחרו אוכליו בדבר או בהפכו לטוב או לרע ולכן נקרא "עֵץ הַדַּעַת טוֹב וָרָע" כי הַ"דַּעַת" יאמר בלשוננו על הרצון כלשונם (פסחים ו) לא שנו אלא שדעתו לחזור ושדעתו לפנותו ובלשון הכתוב (תהלים קמד ג) מָה אָדָם וַתֵּדָעֵהוּ תחפוץ ותרצה בו יְדַעְתִּיךָ בְשֵׁם (שמות לג יב) בחרתיך מכל האדם וכן מאמר ברזילי האדע בין טוב לרע שאבד ממנו כח הרעיון לא היה בוחר בדבר ולא קץ בו והיה אוכל מבלי שיטעם ושומע מבלי שיתענג בשיר והנה בעת הזאת לא היה בין אדם ואשתו המשגל לתאוה אבל בעת ההולדה יתחברו ויולידו ולכן היו האיברים כלם בעיניהם כפנים והידים ולא יתבוששו בהם והנה אחרי אכלו מן העץ היתה בידו הבחירה וברצונו להרע או להטיב בין לו בין לאחרים וזו מדה אלהית מצד אחד ורעה לאדם בהיות לו בה יצר ותאוה ואפשר שנתכוון הכתוב לענין הזה כשאמר אֲשֶׁר עָשָׂה הָאֱלֹהִים אֶת הָאָדָם יָשָׁר וְהֵמָּה בִקְשׁוּ חִשְּׁבֹנוֹת רַבִּים (קהלת ז כט) ה"יושר" שיאחוז דרך אחת ישרה וה"בִקְשׁוּ חִשְּׁבֹנוֹת רַבִּים" שיבקש לו מעשים משתנים בבחירה ממנו וכאשר צוהו הקב"ה על העץ שלא יאכל ממנו לא הודיעו כי בו המדה הזאת רק אמר לו סתם "ומפרי העץ אשר בתוך הגן" כלומר הידוע באמצעותו לא תאכל ממנו והוא מאמר האשה אל הנחש והכתוב שאמר וּמֵעֵץ הַדַּעַת טוֹב וָרָע לֹא תֹאכַל מִמֶּנּוּ (להלן פסוק יז) הזכירו הכתוב אלינו בשמו
@42 **ארץ החוילה אשר שם הזהב** . לבאר שאינה חוילה של מצרים שאמר בה וישכנו מחוילה עד שור (להלן כה יח) כי זו מזרח המזרח והזכיר עוד שם הבדולח לשבח הנהר כי בחול אשר בו ועל שפתו ימצא הזהב ההוא הטוב והבדולח והשוהם כי כן ימצא בנהרות מהם שימצא שם הזהב ומהם אשר ימצא בהם הכסף וכן הבדולח והאבנים הטובות בנהרות ימצאו רובם ועל דעת הראשונים (רש"י ורס"ג וכן הוא בזוה"ק חיי שרה קכה) "פישון" הוא נילוס מצרים יסובב כל ארץ החוילה הזאת ויבא משם על פני כל ארץ מצרים עד נפלו בים הגדול באלכסנדריא של מצרים
@48 **לא תאכל ממנו** . מן הפרי יזהירנו כי העץ אינו נאכל וכן אמר למטה (להלן ג ג) מפרי העץ אשר בתוך הגן וכמהו ואכלו איש גפנו ואיש תאנתו (מלכים ב יח לא) וכן בעצבון תאכלנה (להלן ג יז) תאכל פריה
@48 "ביום אכלך ממנו מות תמות" - בעת שתאכל ממנו תהיה בן מות וכמוהו ביום צאתך והלכת אנה ואנה ידוע תדע כי מות תמות (מלכים א ב מב) שאין הכוונה שימות מיד בו ביום ואין הכוונה לידיעה בלבד שידע שימות כי החיים יודעים שימותו כלם אבל הכוונה כי בעת שיצא יהיה חייב מיתה למלך והוא ימית אותו כאשר ירצה ולא יבאו לראות כבלע את הקדש ומתו (במדבר ד כ) ולא ישאו עליו חטא ומתו בו כי יחללוהו (ויקרא כב ט) אין ענינם אלא שיהיו חייבים מיתה וימותו בחטאם זה ועל דעת אנשי הטבע היה האדם מעותד למיתה מתחלת היצירה מפני היותו מורכב אבל גזר עתה שאם יחטא ימות בחטאו כדרך חייבי מיתה בידי שמים בעבירות כגון זר האוכל תרומה (ויקרא כט ט) ושתוי יין (שם י ט) ומחוסר בגדים ששמשו (שמות כח מג) וזולתם שהכונה בהם שימותו בחטאם טרם בא יומם ולכך אמר בעונש עד שובך אל האדמה כי ממנה לוקחת כי עפר אתה ואל עפר תשוב בטבעך (להלן ג יט) וגם מתחילה היה אוכל מפרי העץ ומזרע הארץ אם כן היתה בו התכה וסבת הויה והפסד ועל דעת רבותינו (עיין שבת נה) אלמלא שחטא לא מת לעולם כי הנשמה העליונית נותנת לו חיים לעד והחפץ האלהי אשר בו בעת היצירה יהיה דבק בו תמיד והוא יקיים אותו לעד כמו שפירשתי במלת וירא אלהים כי טוב (לעיל אחד) ודע כי אין ההרכבה מורה על ההפסד אלא לדעת קטני אמנה כי הבריאה היא בחיוב אבל לדעת אנשי האמונה האומרים כי העולם מחודש בחפץ אלוהי פשוט גם הקיום יהיה בו לעד כל ימי החפץ וזה אמת ברור אם כן ביום אכלך ממנו מות תמות שאז תהיה בן מות לא תתקיים לעד בחפצי והאכילה היתה לו מתחילה לענג ויתכן שפירות גן עדן נבלעים באיברים כמן ומקיימים את אוכליהם וכאשר גזר עליו ואכלת את עשב השדה ובזעת אפיו יאכל לחם האדמה היה זה סבה להפסד כי עפר הוא ועפר יאכל ואל עפר ישוב
@49 **לא טוב היות האדם לבדו** . איננו נראה שנברא האדם להיות יחיד בעולם ולא יוליד שכל הנבראים זכר ונקבה מכל בשר נבראו להקים זרע וגם העשב והעץ זרעם בהם אבל יתכן לומר כי היה כדברי האומר (ברכות סא) דו פרצופים נבראו ונעשו שיהיו בהם טבע מביא באיברי ההולדה מן הזכר לנקבה כח מוליד או תאמר זרע כפי המחלוקת הידוע בעיבור והיה הפרצוף השני עזר לראשון בתולדתו וראה הקב"ה כי טוב שיהיה העזר עומד לנגדו והוא יראנו ויפרד ממנו ויתחבר אליו כפי רצונו וזהו שאמר אעשה לו עזר כנגדו וטעם "לא טוב" שלא יאמר בו כי טוב בהיותו לבדו שלא יתקיים כן במעשה בראשית ה"טוב" הוא הקיום כאשר פירשתי במאמר "וירא אלהים כי טוב" (לעיל א ד)
@50 **אשר יקרא לו האדם נפש חיה** . לשון רש"י סרסהו ופרשהו וכל נפש חיה אשר יקרא לו האדם שם הוא שמו לעולם ורבי אברהם אמר כי למ"ד "אשר יקרא לו" נמשך וכל אשר יקרא לו האדם לנפש חיה הוא שמו לעולם ויתכן שיהיה פירושו בענין העזר והכוונה לומר כי האדם נפש חיה כמו שאמר ויהי האדם לנפש חיה (לעיל ב ז) וכמו שפירשתי והביא לפניו המינין כולן וכל מין מהם שיקראנו האדם בשמו ויאמר בו שהוא נפש חיה כמותו הוא יהיה שמו ויהיה לו לעזר כנגדו והוא קרא לכולן ולא מצא לעצמו עזר שיקרא לו "נפש חיה" כשמו
@51 **ולאדם לא מצא עזר כנגדו** . לשון רש"י כשהביאן הביאן לפניו זכר ונקבה אמר לכל יש בן זוג ולי אין בן זוג מיד ויפל ה' אלהים עליו תרדמה ויפה פירש כי כאשר הכניס פסוקי קריאת השמות בתוך דבר העזר יכריח זה וקריאת השמות על דעת המפרשים (רש"י ורד"ק) כפשוטו שיהא לכל אחד שם לעצמו כדי שיהיו ידועים וניכרים לתולדותיו בשמות אשר יקרא להם כי יהיה שמו לעולם והנה הקב"ה כשרצה לעשות לו העזר אז הביאם לפניו כי היה צריך להביאם לו זוגות לקרוא שם גם לנקבותיהם כי מהם שקראם בשם אחד ומהם חלוקים כשור ופרה ותיש ועז וכבש ורחל וזולתם וכשראה אותם מזווגים זה עם זה נתאוה להם וכאשר לא מצא בתוכם עזר לעצמו נעצב ויישן והאלהים הפיל עליו תרדמה שלא ירגיש בהסרת צלע מגופו (פרד"א יב) ולפי דעתי שקריאת השם הוא העזר והענין כי הקב"ה הביא כל חית השדה וכל עוף השמים לפני אדם והוא הכיר טבעם וקרא להם שמות כלומר השם הראוי להם כפי טבעיהם ובשמות נתבאר הראוי להיות עזר לחבירו כלומר הראוים להוליד זה מזה ואפילו אם נאמין בשמות שהם בהסכמה לא טבעיות (מו"נ ב ל) נאמר שקריאת השמות היא הבדלת המינים כי עברו לפניו זכר ונקבה והתבונן בטבעם איזה מהם עזר לחבירו כלומר המוליד ממנו והודיע זה בשמות כי הבהמה הדקה קרא בשם אחר שכולן עזר זה לזה בתולדה שיולידו זה מזה והגסה בשם אחר והחיה בשם אחר שלא יולידו מין זה מזה וכן כולן ולא מצא בכולן שתהיה בטבעה עזר לו ותקרא בשמו כי קריאת השמות היא הבדלת המינים והפרד כחותם זה מזה כאשר פירשתי למעלה ואין הענין שיהיה ביד האדם למצא בהם עזר לו כי בטבעם נבראו אבל שאם יראה טבעו נאות באחד המינים ויבחר בו היה הקב"ה מתקן טבעו אליו כאשר עשה בצלע ולא יצטרך לבנותו בנין חדש וזה טעם "כל אשר יקרא לו האדם נפש חיה הוא שמו" כלומר הוא יהיה שמו שהקב"ה יקיים בו השם ההוא על ענין שפירשתי והנכון בעיני כי לא היה החפץ לפניו יתברך לקחת צלעו ממנו עד שידע אדם שאין בנבראים עזר לו ושיתאוה שיהיה לו עזר כמותם ומפני זה היה צריך לקחת ממנו אחת מצלעותיו וזה טעם "ולאדם לא מצא עזר כנגדו" כלומר ולשם האדם לא מצא עזר שיהיה ראוי כנגדו ותקרא בשמו שיוליד ממנו ואין צורך בכאן לדברי המפרשים (ראב"ע בפסוק יח והרד"ק) שאמרו כי יבא בכאן שם במקום הכנוי ולו לא מצא עזר כנגדו כדרך נשי למך (להלן ד כג) ואת יפתח ואת שמואל (שמואל א יב יא) וזהו שאמר "זאת הפעם" כלומר הפעם הזאת מצאתי עזר לי שלא מצאתי עד הנה בשאר המינים כי היא עצם מעצמי ובשר מבשרי וראוי שתקרא בשמי ממש כי נוליד זה מזה ובמלת "זאת" סוד יודע מדברינו בפרשת וזאת הברכה אם יברכני צורי להגיע שם ולכך החזיר "כי מאיש לקחה זאת" והבן
@55 **על כן יעזב איש את אביו ואת אמו ודבק באשתו וגו'** . רוח הקדש אומרת כן לאסור העריות לבני נח והיו לבשר אחד הולד נוצר על ידי שניהם ושם נעשה בשרם אחד לשון רש"י ואין בזה טעם כי גם הבהמה והחיה יהיו לבשר אחד בולדותיהם והנכון בעיני כי הבהמה והחיה אין להם דבקות בנקבותיהן אבל יבא הזכר על איזה נקבה שימצא וילכו להם ומפני זה אמר הכתוב בעבור שנקבת האדם היתה עצם מעצמיו ובשר מבשרו ודבק בה והיתה בחיקו כבשרו ויחפוץ בה להיותה תמיד עמו וכאשר היה זה באדם הושם טבעו בתולדותיו להיות הזכרים מהם דבקים בנשותיהם עוזבים את אביהם ואת אמם ורואים את נשותיהן כאלו הן עמם לבשר אחד וכן כי אחינו בשרנו הוא (להלן לז כז) אל כל שאר בשרו (ויקרא יח ו) הקרובים במשפחה יקראו "שאר בשר" והנה יעזוב שאר אביו ואמו וקורבתם ויראה שאשתו קרובה לו מהם
@62 **כי טוב העץ למאכל** . היתה סבורה כי הוא מר וסם המות ולכן יזהירנו ממנו ועתה ראתה כי הוא מאכל טוב ומתוק וכי תאוה הוא לעינים שבו יתאוה ויתור אחרי עיניו ונחמד העץ להשכיל כי בו ישכיל לחמוד ונתנה התאוה לעינים והחמדה בשכל והכלל כי בו ירצה ויחפוץ בדבר או בהפכו
@63 **ותפקחנה עיני שניהם** . לענין החכמה דבר הכתוב ולא לענין ראיה ממש וסופו מוכיח וידעו כי ערומים הם כלשון רש"י וכן גל עיני ואביטה נפלאות מתורתך (תהלים קיט יח)
@64 **וישמעו את קול ה' אלהים מתהלך בגן לרוח היום** . אמרו בבראשית רבה (יט יב) אמר רבי חילפי שמענו שיש הלוך לקול שנאמר וישמעו את קול ה' אלהים מתהלך בגן וכן כתב הרב במורה הנבוכים (א כד) וכן דעת רבי אברהם כי "מתהלך" כנוי לקול כענין קולה כנחש ילך (ירמיהו מו כב) והוא אמר כי טעם "לרוח היום" ששמעו הקול לפנות ערב והזכיר בשם רבי יונה כי הטעם והאדם מתהלך בגן לרוח היום ולפי דעתי כי טעם מתהלך בגן עדן כטעם והתהלכתי בתוככם (ויקרא כו יב) וילך ה' כאשר כלה לדבר אל אברהם (להלן יח לג) אלך אשובה אל מקומי (הושע ה טו) והוא ענין גלוי שכינה במקום ההוא או הסתלקותו מן המקום שנגלה בו וטעם לרוח היום כי בהגלות השכינה תבא רוח גדולה וחזק כענין שנאמר (מלכים א יט יא) והנה ה' עובר ורוח גדולה וחזק מפרק הרים ומשבר סלעים לפני ה' וכן וידא על כנפי רוח (תהלים יח יא) וכתוב באיוב (איוב לח א) ויען ה' את איוב מן הסערה ולפיכך אמר בכאן כי שמעו קול ה' שנתגלה השכינה בגן כמתקרב אליהם לרוח היום כי רוח ה' נשבה בו בגן כרוח הימים לא רוח גדולה וחזק במחזה בשאר הנבואות שלא יפחדו ויבהלו ואמר כי אף על פי כן נתחבאו מפני מערומיהם ובבראשית רבה (יט ז) נמי אמרו אמר רבי אבא בר כהנא מהלך אין כתוב כאן אלא מתהלך מקפץ ועולה הנה רבי אבא עשאו כלשון "וילך ה'" (להלן יח לג) כמו שפירשנו בלשון ההליכה אלא שהוא פתר הכתוב להסתלקות השכינה שהיתה שורה בגן עדן ונסתלקה ממנו בחטאו של אדם כענין אלך אשובה אל מקומי (הושע ה טו) ואנו מפרשים אותו לגלוי השכינה במקום ההוא והוא הנכון והנאות בכתוב
@68 **וטעם האשה אשר נתת עמדי** . כלומר האשה אשר אתה בכבודך נתת אותה לי לעזר היא נתנה לי מן העץ והייתי חושב שכל אשר תאמר אלי יהיה לי לעזר ולהועיל וזהו מה שאמר בענשו "כי שמעת לקול אשתך" שלא היית ראוי לעבור על מצותי בעבור עצתה ורבותינו (במסכת ע"ז ה) קורין אותו בזה כפוי טובה ירצו לפרש שענה אותו אתה גרמת לי המכשול הזה שנתת לי אשה לעזר והיא יעצתני להרשיע
@69 **וטעם מה זאת עשית** . לעבור על מצותי כי האשה בכלל אזהרת אדם כי היתה עצם מעצמיו בעת ההיא וכן היא בכלל העונש שלו ולא אמר באשה "ותאכלי מן העץ" כי היא נענשה על אכילתה ועל עצתה כאשר נענש הנחש ועל כן אמרה הנחש השיאני ואוכל כי העונש הגדול על האכילה והנה מכאן נוכל ללמוד עונש למחטיאי אדם בדבר כאשר למדונו רבותינו (פסחים כב ע"ז ו) בפסוק ולפני עור לא תתן מכשול (ויקרא יט יד)
@70 **מכל הבהמה ומכל חית השדה** . התבונן רבי יהושע מן המקרא הזה כי הנחש מוליד לשבע שנים (בכורות ח) ובדקו ומצאו כי כן הדבר (ב"ר שם) כי מדרשי הכתוב ורמזיהם מקובלים ובהם להם סודות עמוקים בתולדות ובכל דבר כאשר הזכרתי בפתיחתי
@71 **וטעם תשופנו עקב** . שיהיה לאדם יתרון עליך באיבה כי הוא ישופך ראש ואתה לא תשופנו רק בעקבו וירצץ מוחך שם
@72 **ואל אישך תשוקתך** . לתשמיש ואף על פי כן אין לך מצח לתבעו בפה אלא הוא ימשול בך הכל ממנו ולא ממך לשון רש"י ואיננו נכון כי זה שבח באשה כמו שאמרו (עירובין ק) וזו מדה יפה בנשים ורבי אברהם אמר ואל אישך תשוקתך משמעתך והטעם שתשמעי אל כל אשר יצוה עליך כי את ברשותו לעשות חפצו ולא מצאתי לשון תשוקה רק בחשק ותאוה והנכון בעיני שהעניש אותה שתהיה נכספת מאד אל בעלה ולא תחוש לצער ההריון והלידה והוא יחזיק בה כשפחה ואין המנהג להיות העבד משתוקק לקנות אדון לעצמו אבל יברח ממנו ברצונו והנה זו מדה כנגד מדה כי היא נתנה גם לאישה ויאכל במצותה וענשה שלא תהיה היא מצוה עליו עוד והוא יצוה עליה כל רצונו
@78 **ועתה פן ישלח ידו** . רצה הקב"ה שתתקיים גזירתו במיתת האדם ואם יאכל מעץ החיים שנברא לתת לאוכליו חיי עולם תבטל הגזרה או שלא ימות כלל או שלא יבא יומו בעת הנגזר עליו ועל תולדותיו והנה עתה שהיתה לו בחירה שמר העץ הזה ממנו כי מתחילה לא היה עושה אלא מה שיצווה ולא אכל ממנו כי לא היה צריך ודע והאמן כי גן עדן בארץ ובו עץ החיים ועץ הדעת ומשם יצא הנהר ויפרד לארבעה ראשים הנראים לנו כי פרת בארצנו ובגבולנו ופישון הוא נילוס מצרים כדברי הראשונים אבל כאשר הם בארץ כן יש בשמים דברים יקראו כן והם לאלה יסוד כמו שאמרו (מדרש שה"ש זוטא א ד) הביאני המלך חדריו מלמד שעתיד הקב"ה להראות את ישראל גנזי מרום החדרים שבשמים דבר אחר הביאני המלך חדריו אלו חדרי גן עדן מכאן אמרו כמעשה הרקיע מעשה גן עדן והנהרות כנגד ארבע מחנות שבמרום ומשם ימשך כח המלכיות שבארץ כמו שכתוב (ישעיהו כד כא) ועל צבא המרום במרום ועל מלכי האדמה באדמה כך אמרו בבראשית רבה (טז ד) ארבעה ראשים אלו ד' מלכיות שם האחד פישון זה בבל וכו' והדברים הנקראים עץ החיים ועץ הדעת למעלה סודם נעלה ונשגב והאדם חטא בפרי עץ הדעת תחתון ועליון במעשה ובמחשבה ואם היה העץ טוב לאדם למאכל ונחמד אליו להשכיל למה מנעו ממנו והאלהים הוא הטוב והמטיב לא ימנע טוב להולכים בתמים והנחש אין בו היום נפש מדברת ואם היתה בו מתחילה היה מזכיר בקללתו שיאלם פיו כי היא היתה לו קללה נמרצת מכולן אבל כל אלה דברים כפולים הגלוי והחתום בהם אמת ובבראשית רבה (טז ה) דבר אחר לעבדה ולשמרה אלו הקרבנות שנאמר (שמות ג יב) תעבדון את האלהים על ההר הזה הדא הוא דכתיב (במדבר כח ב) תשמרו להקריב לי במועדו רמזו כי הקרבנות יצמיחו ויגדלו בעץ החיים ועץ הדעת וכל עצי גן עדן והם העבודה והשמירה בהם ורבי אברהם מכחיש מה שאמרו כי פישון הוא נילוס בעבור שימצאהו יוצא מהר הלבונה ולכן יגדל בימי הקיץ וכבר נודעו נהרות רבים יצאו מן המקור וימשכו הרבה ואחר כן יכנסו בתחתיות ארץ מהלך ימים ויבקעו ויהיו נובעים תחת אחד ההרים במקום רחוק
@81 **ותהר ותלד את קין** . ענינו ותלד בן ותקרא את שמו קין כי אמרה קניתי איש את ה' וכן ותלד את חנוך (להלן ד יז) ורבים בפרשה ובמקומות אחרים את ה' עם ה' כשברא אותי ואת אישי הוא לבדו בראנו אבל בזה אנו שותפין עמו לשון רש"י והנכון לי שאמרה הבן הזה יהיה לי קנין לה' כי כאשר נמות יהיה במקומנו לעבוד את בוראו וכן דעת אונקלוס שאמר קדם ה' וכמהו (ונראה) והראה את הכהן (ויקרא יג מט) לכהן ויגש דוד את העם (שמואל א ל כא) אל העם או יהיה "את ה'" כמו ויתהלך חנוך את האלהים (להלן ה כב) את האלהים התהלך נח (להלן ו ט) וקראה האחד בשם קנין והשני הבל כי קנין האדם להבל דמה ולא רצתה לפרש זה על כן לא נכתב טעם בשם השני והסוד המקובל בענין הבל גדול מאד
@83 **ויבא קין מפרי האדמה מנחה לה' והבל הביא גם הוא** . הבינו האנשים האלה סוד גדול מהקרבנות והמנחות וכן נח ורבותינו אמרו (ע"ז ח) שגם אדם הראשון הקריב שור פר וזה יחסום פי המבהילים בטעם הקרבנות ועוד ארמוז בו עיקר גדול ברצון הקב"ה (עיין ויקרא א ט)
@87 **הלא אם תיטיב שאת** . על דעת המפרשים (אונקלוס רש"י ורד"ק) שאת עונך ועל דעת רבי אברהם שאת פניך כנגד למה נפלו פניך כי המתבייש כובש פנים למטה וכן ואור פני לא יפילון (איוב כט כד) והמכבדו כאלו נושא פניו למעלה וזה טעם אולי ישא פני (להלן לב כא) לא תשא פני דל (ויקרא יט טו) ועל דעתי אם תיטיב יהיה לך יתר שאת על אחיך כי אתה הבכור וזה טעם למה חרה לך כי בבשתו מאחיו נפלו פניו ובקנאתו ממנו הרגו והנה אמר לו למה חרה לך על אחיך ולמה נפלו פניך ממנו הלא אם תיטיב יהיה לך יתר שאת על אחיך ואם לא תיטיב לא עמו בלבד תבואך רעה כי לפתח ביתך חטאתך רובץ להכשילך בכל דרכיך ואליך תשוקתו שהוא ישתוקק להיות דבק בך כל הימים אבל אתה תמשול בו אם תחפוץ כי תיטיב דרכיך ותסירנו מעליך הורהו על התשובה שהיא נתונה בידו לשוב בכל עת שירצה ויסלח לו
@88 **וטעם ויאמר קין אל הבל אחיו** . שנכנס עמו בדברי ריב ומצה להתגולל עליו ולהרגו לשון רש"י ורבי אברהם אמר כי הקרוב אליו שאמר לו כל התוכחות שהוכיחו השם ועל דעתי שהוא דבק עם ויהי בהיותם בשדה כי אמר לו נצא השדה והרג אותו שם בסתר ויתכן שנתכוון בהריגהו שיבנה העולם ממנו כי חשב שלא יהיה לאביו זרע אחר עוד גם פחד שלא יהיה עיקר בנינו של עולם מאחיו שנתקבלה מנחתו
@91 **ארור אתה מן האדמה** . יותר ממה שנתקללה היא כבר בעונה וגם בזו הוסיפה לחטוא אשר פצתה את פיה והנני מוסיף לה קללה לא תוסף תת כחה לשון רש"י ואיננו נכון כי בכאן לא ארר האדמה בעבורו כאשר באביו אבל אמר שיהיה הוא ארור ממנה ופירש הקללה שלא תוסיף תת כחה אליו ושיהיה נע ונד בה ואמר כי תעבוד את האדמה כי בכל אשר תטרח בה לעבוד אותה כראוי בחרישה ועידור ובכל עבודה בשדה ותזרע אותה כהוגן לא תוסיף תת כחה לך אבל תזרע הרבה ותביא מעט וזו היא הארירה כטעם וארותי את ברכותיכם (מלאכי ב ב) ואמר כן כנגד אומנותו כי הוא היה עובד אדמה והנה ארר מעשיו וזה טעם לא תוסף תת כחה לך שלא תתן עוד כחה לך כאשר היתה עושה עד הנה בהיותך עובד אותה וכך פירש רבי אברהם ויתכן שאררו מן האדמה שלא תתן היא מעצמה כחה אליו תאנה וגפן לא יתנו חילם באחוזתו ועץ השדה לא יתן אליו פריו וחזר ואמר גם כן כי תעבוד אותה לחרוש ולזרוע לא תוסף תת כחה לך כאשר בתחלה והנה הן שתי קללות באומנתו והשלישית שיהיה נע ונד בה והטעם שלא ינוח לבו ולא ישקוט לעמוד במקום אחד ממנה אבל יהיה גולה לעולם כי עונש הרוצחים גלות וטעם אשר פצתה את פיה לאמר אתה הרגת את אחיך וכסית את דמו באדמה ואני אגזור עליה שתגלה את דמיה ולא תכסה עוד על הרוגיה כי תענש בה ובכל אשר תכסה בה כגון הזריעה והנטיעה וזה עונש כל שפיכות דם בארץ כענין שכתוב (במדבר לה לג) כי הדם הוא יחניף את הארץ וחנופת הארץ מארה בפירותיה כענין מהיותם בא אל ערימת עשרים והיתה עשרה בא אל היקב לחשוף חמשים פורה והיתה עשרים (חגי ב טז)
@93 **גדול עוני מנשוא** . בתמיה אתה טוען עליונים ותחתונים ועוני אי אפשר לטעון לשון רש"י מבראשית רבה (כב יא) והנכון בפשט שהוא וידוי אמר אמת כי עוני גדול מלסלוח וצדיק אתה ה' וישר משפטיך אף על פי שענשת אותי הרבה מאד והנה גרשת אותי היום מעל פני האדמה כי בהיותי נע ונד ולא אוכל לעמוד במקום אחד הנה אנכי מגורש מן האדמה ואין מקום למנוחתי ומפניך אסתר כי לא אוכל לעמוד לפניך להתפלל או להקריב קרבן ומנחה כי בושתי וגם נכלמתי כי נשאתי חרפת נעורי אבל מה אעשה כי כל מוצאי יהרגני ואתה בחסדך הרבים לא חייבת אותי מיתה והענין שאמר לפניו הנה חטאי גדול והרבית עלי עונש אבל שמרני שלא אענש יותר ממה שחייבת אותי כי בעבור שאהיה נע ונד ולא אבנה לי בית וגדרות בשום מקום יהרגוני החיות כי סר צלך מעלי הודה כי האדם איננו נשגב ונמלט בכחו רק בשמירת עליון עליו
@95 **וישם ה' לקין אות** . ולא אמר "ויתן" לו השם אות או "ויעש" יורה ששם לו האות קבוע שיהיה עמו תמיד אולי כשהיה נוסע ממקום למקום היה לו אות מאת השם מורה לו הדרך אשר ילך בה ובזה ידע שלא יקראנו אסון בדרך ההוא ובבראשית רבה (כב יב) אמרו כענין זה רבי אבא אמר כלב מסר לו כי מפני שהיה פחדו מן החיות מסר לו אחת מהן שתלך לפניו ולמקום שיפנה הכלב ללכת ידע כי שם צוה לו השם ולא יהרג בה הזכירו בו החכמים אות נבזה כראוי לו אבל הכוונה שהיה עמו האות תמיד להורות לפניו הדרך שילך בה כי כן לשון "וישם"
@96 **וטעם ויצא קין מלפני ה'** . כי עוד לא עמד לפניו לעולם כטעם שאמר ומפניך אסתר וטעם וישב בארץ נוד שלא הלך בכל העולם אבל באותה הארץ ישב נודד תמיד לא ינוח במקום ממנה כלל ונקראת "ארץ נוד" על שמו לעולם
@97 **וטעם ויהי בונה עיר ויקרא שם העיר כשם בנו חנוך** . כי מתחילה היה חושב להיות ערירי בעונו ואחרי שנולד לו זרע החל לבנות עיר להיות בנו יושב בה ובעבור כי הוא ארור ומעשיו לא יצליחו קראו "חנוך" להגיד כי לא בנאה לעצמו כי הוא אין לו עיר ומושב בארץ כי נע ונד הוא אבל יהיה הבנין לחנוך וכאלו חנוך בנאה לנפשו ומפני שלא אמר "ויבן עיר" כאשר יאמר ויבן את נינוה (להלן י יא) ויבנו בני גד את דיבון (במדבר לב לד) יורה כי היה כל ימיו בונה העיר כי מעשיו ארורים יבנה מעט בטורח ועמל וינוע וינוד מן המקום ההוא ויחזור שם ויבנה מעט ולא יצליח את דרכיו ונכתבו תולדות קין ומעשיו להודיע כי השם ארך אפים והאריך לו כי הוליד בנים ובני בנים והזכיר כי פקד עון אבות על בנים ונכרת זרעו ורבותינו אמרו (שמות רבה לא יז) שחיה שנים רבות ומת במבול ולא הוריד שיבתו בשלום שאול רק ראה בהכרת הוא וכל זרעו אתו והקרוב כי לא היו תולדותיו רק ששה דורות עד המבול והיו בתולדות שת שני דורות יותר או שלא היה צריך לספר בהם וספר באלה להודיע מי היו המתחילים בבנין הערים ובמרעה הצאן וחכמת הנגון ומלאכת המתכות וכתב תוכחת למך עם נשיו להגיד כי הוליד הוא אך בניו נכרתו טרם הולידם
@102 **לוטש כל חורש נחשת וברזל** . שיעורו הוא היה לוטש וחורש כל נחשת וברזל יאמר כי הוא היה מחדד וחורש כל מלאכת נחשת וברזל וכמהו כל תשא עון וקח טוב (הושע יד ג) ועל דעת אונקלוס דבק בכתובים הראשונים הוא היה אבי לוטש כל חורש נחשת וברזל
@102 "ואחות תובל קין נעמה" - כאומר ונולדה לו אחות ושמה נעמה וכן ואחות לוטן תמנע (להלן לו כב) ואת מרים אחותם (במדבר כו נט) ושם אחותו מעכה (דהי"א ז טו) ובבראשית רבה (כג ג) יש אומרים אשתו של נח היתה ולמה היו קורין אותה נעמה שהיו מעשיה נאים ונעימים נתכוונו לומר שהיה לה שם בדורות ההם כי היתה צדקת והולידה צדיקים ולכן יזכירנה הכתוב ואם כן נשאר לקין זכר מעט בעולם ואם נאמר שאינה האשה שהוליד נח ממנה שלשת בניו אם כן אין בזה טעם להזכירה ומדרש אחר לרבותינו שהיא האשה היפה היא מאד שממנה תעו בני האלהים והיא הנרמזת בפסוק ויראו בני האלהים את בנות האדם (להלן ו ב) כמו שמוזכר בפרקי רבי אליעזר (כב) ואחרים אמרו (זהר חדש א יט ב) כי היא היתה אשת שמדון אם אשמדאי וממנה נולדו השדים כי כן ימצא שמה בכתבי שמושי השדים והכתוב ירמוז ויקצר בתעלומות כאלה
@103 **ויאמר למך לנשיו** . סמכו המפרשים (רש"י והראב"ע) בענין הכתוב הזה על דעת אונקלוס שפירש לכן כל הורג קין שבעתים יוקם (לעיל ד טו) כי לשבעה דורות יוקם ממנו ולא עתה כי השם האריך אפו ממנו והנה נשי למך פחדו להוליד בנים בעבור שיהיו שבועיים לקין והוא נחם את נשיו שהשם יאריך לו עוד שבעים ושבעה כי יתפלל לפניו כי הוא ארך אפים וירחם עליו או שהיה קל וחומר של שטות כפי המדרש שהזכיר רש"י ואם כן יאמר לכן כל הורג קין לשבעתים יוקם ממנו ולא בימיו וזהו תרגומו של אונקלוס כל דיקטל קין לשבעה דרין יתפרע מיניה ואם כן היה ראוי שיהיה "ויאמר למך לנשיו" מוקדם ולפי דעתי אין טעם "שבעתים" לשבעה דורות כי לא תאמר המלה הזאת על השבעה הנפרדים רק על הכפל דבר אחד שבעה פעמים כמו מזוקק שבעתים (תהלים יב ז) ישלם שבעתים (משלי ו לא) ואור החמה יהיה שבעתים (ישעיהו ל כו) כפול ומכופל שבעה חלקים אבל פירוש "כל הורג קין" כפשוטו שאמר השם לכן כל אשר יהרוג את קין שבעתים יוקם ממנו כי אעניש ההורג אותו שבע על חטאתו כי אני הבטחתי את קין שלא יהרג בעבור יראתו אותי והתודותו לפני אבל ענין למך עם נשיו לא הזכירו הכתוב בביאור ונוכל לומר גם כן שהיו יראות מעונש שלא יהרג למך בעון אביו כי השם לא אמר לקין סלחתי לך רק שלא יהרג אבל יגבה חובו מזרעו ולא ידעו מתי וכן היה הדבר ולמך נחם אותן לאמר כי השם ירחם עליו כאשר רחם על קין כי הוא נקי כפים ממנו ויתפלל לפניו גם הוא וישמע תפלתו אבל הנראה בעיני כי היה למך איש חכם מאד בכל מלאכת מחשבת ולמד לבנו הבכור ענין המרעה כפי טבעי הבהמות ולמד את השני חכמת הנגון ולמד את השלישי ללטוש ולעשות חרבות ורמחים וחניתות וכל כלי המלחמה והיו נשיו מתפחדות שלא יענש כי הביא החרב והרציחה בעולם והנה הוא תופש מעשה אבותיו בידו כי הוא בן המרצח הראשון וברא משחית לחבל והוא אמר להן אני לא הרגתי איש לפצעים ולא ילד לחבורות כאשר עשה קין ולא יענישני השם אבל ישמרני מן ההריגה יותר ממנו והזכיר כן לומר כי לא בחרב וחנית יכול אדם להרוג בפצעים וחבורות שימית במיתה רעה יותר מן החרב ואין החרב גורם הרציחה ואין על העושו חטא
@107 **זה ספר תולדות אדם** . הבנים אשר יזכיר בפרשה ולפי דעתי ירמוז לכל התורה כי כל התורה כולה ספר תולדות אדם על כן אמר בכאן "ספר" ולא אמר "ואלה תולדות אדם" כאשר יאמר בשאר מקומות (להלן כה יב) ואלה תולדות ישמעאל ואלה תולדות יצחק (שם יט) וכן כולן וטעם ביום ברוא אלהים אדם נמשך לפניו כי יתחיל באדם עצמו יזכיר בו שנברא מאין ולכך אמר ביום ברוא אלהים מאין האדם הזה הנזכר בדמות אלהים עשאו יפרש שהוא מעשה אלהים ובדמות אלהים והזכיר כי כאשר ברא אותו מאין כן ברא את אשתו ואמר ויברך אותם שנתן בהם כח תולדה להתברך לעד בבנים ובנות רבים מאד והכוונה לומר כי התולדות מברכת אלהים כי הם לא נולדו אבל נבראו מאין ונתברכו לעשות כן וטעם ויקרא את שמם אדם מפני ששם אדם כלל לכל המין האנושי הזכיר כי האלהים קרא הזוג הראשון בשם זה מפני שכולם בהם בכח ועליהם הוא אומר "זה ספר תולדות אדם" וכתב רבינו שרירא הגאון שמסרו חכמים אחד לחברו הכרת פנים וסדרי שרטוטין מקצתן אמורים בסדר פסוק "זה ספר תולדות אדם" ומקצתן בסדר פסוק של אחריו "זכר ונקבה בראם" ואין מוסרים סתרי תורה ורזין אלא למי שרואין בו סימנין שראוי לכך אלו דברי הגאון ולא זכינו בהם
@109 **ויולד בדמותו כצלמו** . ידוע כי כל הנולדים מן החיים יהיו בדמות המולידים ובצלמם אבל בעבור שנתעלה האדם בדמותו וצלמו שאמר בו (לעיל ה א) בדמות אלהים עשה אותו פירש כאן שאף תולדותיו היו כן באותו הדמות המעולה ולא אמר זה בקין והבל כי לא רצה להאריך בהם אבל פירש כן בשת שהעולם הושתת ממנו או מפני שהאדם נברא בתכלית שלימות היצירה הגיד בשת כי היה כמוהו בכח וביופי
@110 **ויהיו ימי אדם אחר הולידו את שת** . בעבור ארך חיי אלה הראשונים יפרוט ימיהם קודם הולידם וגם אחר כך ויכלול כלם בסוף עד הדורות שאחר המבול והסבה באריכות ימיהם כי אדם הראשון מעשה ידיו של הקב"ה נעשה בתכלית השלימות בנוי בכח בקומה וגם אחרי שנקנס עליו שיהיה בן מות היה בטבעו לחיות זמן רב וכאשר בא המבול על הארץ נתקלקל עליהם האויר והלכו ימותם הלוך וחסור כי עד המבול היו ימיהם בארך ההוא ויש מהם שחיו יותר מאדם ושם שנולד קודם המבול חיה שש מאות הועיל לו החוזק שנולד בו והזיק לו האויר שנתקלקל ובניו הנולדים אחר המבול נתקצרו ימותם ושבו לארבע מאות ותראה שהיה זה בהם עד הפלגה וכאשר משל עליהם שנוי האוירות בהפלגה נתקצרו עוד ימיהם כי פלג אשר בימיו נפלגה הארץ שב לחצי ימיהם למאתים שנה ונראה כי בדורות אברהם יצחק ויעקב היו הימים בעם שבעים ושמנים שנה כאשר הזכיר משה רבינו בתפלתו (תהלים צ י) אבל הצדיקים בדורותם יראת ה' תוסיף בהם ימים כי פרעה תמה על יעקב והוא הפליג לו בימי אבותיו כמו שאמר ולא השיגו את ימי שני חיי אבותי בימי מגוריהם (להלן מז ט) ולא יכשר בעיני מאמר הרב שכתב במורה הנבוכים (ב מז) כי לא היה אורך השנים רק ביחידים האלה הנזכרים ושאר בני אדם בדורות ההם היו שנות חייהם השנים הטבעיים המורגלים ואמר כי היה החדוש הזה באיש ההוא בהנהגתו ומזונו או על דרך נס והנה אלה דברי רוח ולמה יהיה הנס הזה בהם והם אינם נביאים ולא צדיקים וטובים לעשות להם נס אף כי דור אחר דור ותיקון ההנהגה והמזון איך תאריך ימיהם כפלי כפלים מכל הדור ההוא ויתכן שיהיו אחרים גם כן מתנהגים בטוב ההנהגה ההיא ותאריך לכלם או לרובם ואיך לא תגיע החכמה בהנהגה הטובה ההיא לאחד מכל בני נח אחר המבול אבל היה בהם קצת מחכמת אבותם והיא מתמעטת והולכת דור אחר דור
@139 **ויהי כי החל האדם לרוב על פני האדמה** . כאשר הזכיר הכתוב נח ובניו ורצה להתחיל בענין המבול אמר כי מיד כאשר החלו בני האדם לרוב החלו לחטוא ועמדו בחטאם ימים רבים עד שהיה נח בן ד' מאות ושמנים שנה ואז גזר עליהם הקב"ה שלא ידון רוחו בהם לעולם אבל יאריך עוד להם שנים עד שתמלא סאתם כי כן משפט האלהים
@140 **בני האלהים** . בני השרים והשופטים לשון רש"י וכך הוא בבראשית רבה (כו ה) אם כן יספר הכתוב כי הדיינין אשר להם לעשות המשפט בניהם עושים החמס בגלוי ואין מונע אותם
@140 "כי טובות הנה" - כמו כי תראה חמור שונאך (שמות כג ה) כי יקרא קן צפור לפניך (דברים כב ו) כאשר הנה טובות יקחו אותן להם לנשים באונס וספר הכתוב החמס ואמר עוד "מכל אשר בחרו" להכניס הנשואות לאחרים אבל לא הזכיר הכתוב האיסור בהם בפירוש ולא נגזר עליהם העונש רק על החמס לפי שהוא ענין מושכל איננו צריך לתורה
@141 **בשגם הוא בשר** . כמו בשגם בסגול ופירש רש"י בשביל שגם זאת בו שהוא בשר ואף על פי כן איננו נכנע מלפני ומה אם יהיה אש או דבר קשה ואין בפירוש הזה טעם או ריח ורבי אברהם פירש כי יאמר לא יעמוד רוחי באדם לעולם בעבור החמס הזה ועוד בעבור שהאדם בשר ויגיע עד עת ויחסר והנה הוא כמו גם בשהוא בשר ומה צורך לטענה הזאת וידוע כי בשר המה ונגזר עליהם המיתה כי עפר אתה ואל עפר תשוב (לעיל ג יט) והנכון בעיני כי יאמר לא יעמוד רוחי באדם לעולם בעבור שגם האדם הוא בשר ככל בשר הרומש על הארץ בעוף ובבהמה ובחיה ואיננו ראוי להיות רוח אלהים בקרבו והענין לומר כי האלהים עשה את האדם ישר להיותו כמלאכי השרת בנפש שנתן בו והנה נמשך אחרי הבשר ובתאוות הגופניות נמשל כבהמות נדמו ולכן לא ידון עוד רוח אלהים בקרבו כי הוא גופני לא אלהי אבל יאריך להם אם ישובו והנה זה כטעם ויזכור כי בשר המה רוח הולך ולא ישוב (תהלים עח לט)
@142 **הנפלים** . לשון רש"י על שם שנפלו והפילו את העולם והוא בבראשית רבה (כו ז) ובעלי הלשון אמרו (הראב"ע והרד"ק) שנקראו כן בעבור שיפול לב אדם עליו מפחדם וכן האימים (להלן יד ה)
@142 "בימים ההם" - לשון רש"י בימי דור אנוש וגם אחרי כן שראו באבדן דור אנוש שעלה אוקינוס והציף שלישו של עולם ולא נכנעו ללמוד מהם ורבי אברהם פירש גם אחרי המבול כי בני ענק היו ממשפחת בני האלהים ואם כן או תהיינה נשי בני נח מזרעם וידמו להם או שיודה במאמר (נדה סא) הדורש בעוג שפלט מן המבול ויוסיף הוא שנמלטו גם אחרים עמו והנכון בעיני כי אדם ואשתו יקראו בני האלהים בעבור שהיו מעשה ידיו והוא אביהם אין להם אב זולתו והוא הוליד בנים רבים ככתוב (לעיל ה ד) ויולד בנים ובנות והיו האנשים האלה הנולדים ראשונים מאב ואם בשלמות גדולה מן הגובה והחוזק כי נולדו בדמות אביהם ככתוב בשת (לעיל ה ג) ויולד בדמותו כצלמו ויתכן שהיו כל בני הקדמונים אדם שת אנוש נקראים בני האלהים כי היו ג' האנשים האלה בדמות אלהים ואז הוחל לעבוד עבודה זרה והוחל לבא באנשים חולשה ורפיון וכך אמרו בבראשית רבה (כד ו) זה ספר תולדות אדם ואין הראשונים תולדות ומה הן אלוהות בעון קומי אבא כהן ברדלא אדם שת אנוש ושתק אמר לון עד כאן בצלם ובדמות מכאן ואילך קינן קנטרנין וכאשר החל האדם לרוב ונולדו להם הבנות היו אלה בני הראשונים בחזקם ולרוב תאותם היו בוחרים הנשים הטובות בעלות הקומה והבריאות וספר בתחלה (בפסוק ב) כי יקחו אותם לנשים דרך חמס ואחר כך ספר כי יבאו דרך זנות אל בנות האדם שאינן באותה המעלה ולא יודע הדבר עד שיולידו להם בנים ויכירו כי אינם מבני שאר האנשים רק לבני האלהים האלה נולדו שהם גדולים מאד אבל הם נופלים מאבותם בגובה וכח כלשון לא נופל אנכי מכם (איוב יב ג) והמה גבורים כנגד שאר בני האדם ואמר שהיה זה בדורות הראשונים אשר היו נקראים "בני האלהים" בהיותם בתכלית השלימות שיולידו מבנות האדם נפילים וגם אחרי כן כי הנפילים עצמם יולידו נפילים מהם ופירוש "אשר מעולם" כי האנשים אחרי המבול כאשר יראו גבורים יזכירו אלה ויאמרו כבר היו גבורים מאלה לעולמים אשר היו לפנינו והיו "אנשי השם" בכל הדורות אחרי כן וזה פשט הגון בפרשה הזאת אבל המדרש אשר לרבי אליעזר הגדול בפרקיו על המלאכים שנפלו ממקום קדושתן מן השמים והוזכר בגמרא במסכת יומא (סז) הוא הנאות בלשון הכתוב יותר מן הכל אלא שיש צורך להאריך בסוד הענין ההוא
@144 **וינחם ה' ויתעצב אל לבו** . דבר תורה כלשון בני אדם והענין כי מרו ועצבו את רוח קדשו בפשעיהם וענין "אל לבו" כי לא הגיד זה לנביא שלוח אליהם וכן הלשון במחושב כדרך לדבר אל לבי (להלן כד מה) וזולתו ובבראשית רבה (כז ד) אמרו בזה ענין נכבד במשל שהביאו מן הסרסור והאדריכל והוא סוד גדול לא ניתן ליכתב והיודעו יתבונן למה אמר בכאן שם המיוחד ובכל הפרשה וענין המבול שם אלהים
@146 **וטעם ונח מצא חן בעיני ה'** . שהיו כל מעשיו לפניו נאים ונעימים וכן כי מצאת חן בעיני ואדעך בשם (שמות לג יז) כדרך ויתן חנו בעיני שר בית הסוהר (להלן לט כא) ותהי אסתר נושאת חן בעיני כל רואיה (אסתר ב טו) והזכיר זה כנגד מה שאמר בדורו שהיו כל מעשיהם לעצבון לפניו יתברך ואמר בו שהיה לחן בעיניו ואחר כן סיפר מדוע היה טוב לפני האלהים כי היה צדיק תמים חסלת פרשת בראשית
@147 **אלה תולדות נח** . טעמו פירשו בו (הראב"ע והרד"ק) קורותיו כטעם מה ילד יום (משלי כז א) וירמוז אל כל הפרשה ואינו נכון בעיני כי אין קורות האדם תולדותיו והנכון שהוא כמשמעו כמו אלה תולדות בני נח (להלן י א) ואלה תולדות ישמעאל (להלן כה יב) יאמר אלה תולדות נח שם חם ויפת אבל החזיר "ויולד נח" בעבור שהפסיק ואמר נח איש צדיק תמים היה להודיע למה צוהו בתיבה ואף על פי שכבר אמר למעלה (ה לב) ויהי נח בן חמש מאות שנה ויולד נח את שם את חם ואת יפת חזר להזכירם פעם אחרת להגיד כי לא היה ככל אבותיו שיולידו בנות ובנים וזה טעם "שלשה בנים" כי יזכיר מספרם לאמר כי אלה שלשה לבדם היו תולדותיו ונצלו בזכותו ומאלה נפצה כל הארץ
@147 "איש צדיק תמים היה" - יזכיר הכתוב שהיה זכאי ושלם בצדקו להודיע שראוי להנצל מן המבול שאין לו עונש כלל כי הוא תמים בצדק כי הצדיק הוא הזכאי בדין הפך הרשע כמו שאמר והצדיקו את הצדיק והרשיעו את הרשע (דברים כה א) וכן ואתה צדיק על כל הבא עלינו כי אמת עשית (נחמיה ט לג) וכן בצדק תשפוט עמיתך (ויקרא יט טו) אבל באברהם שאמר (להלן יח יט) לעשות צדקה ומשפט שבח אותו בצדק שהוא המשפט וברחמים שהיא הצדקה ורבי אברהם אמר צדיק במעשיו תמים בלבו וכתיב (יחזקאל כח טו) תמים אתה בדרכיך ואחר שאמר שהוא איש צדיק כי איננו איש חמס ומשחית דרכו כבני דורו החייבים אמר שהיה מתהלך את השם הנכבד ליראה אותו לבדו איננו נפתה אחרי הוברי שמים ומנחש ועונן וכל שכן אחרי עבודה זרה ואיננו שומע להם כלל רק בשם לבדו הוא דבק תמיד והולך בדרך אשר בחר השם או אשר יורה אותו כי נביא היה וזה כטעם אחרי ה' אלהיכם תלכו ואותו תיראו (דברים יג ה) הנאמר בהרחקת המתנבא לעבוד עבודה זרה ונותן אות ומופת כאשר אפרש ועוד אזכיר זה בפסוק התהלך לפני והיה תמים (להלן יז א) אם יהיה תמים דעות עמי והנה אחר שהיה נח צדיק ואיננו ראוי ליענש גם בניו וביתו ראוים להנצל בזכותו כי היה עונש עליו אם יכרת זרעו או יאמר כי הוא צדיק שלם וגם בניו וביתו צדיקים כי הוא למדם כענין שכתוב (להלן יח יט) כי ידעתיו למען אשר יצוה את בניו ואת ביתו
@147 "בדורותיו" - יש מרבותינו שדרשוהו לטובה כל שכן אם היה בדור של צדיקים ויש שדורשין לגנאי לשון רש"י והנכון בעיני לפי הפשט כי טעמו לומר שהוא לבדו הצדיק בדורות ההם אין בדורותיו צדיק ולא תמים זולתו וכן כי אותך ראיתי צדיק לפני בדור הזה (להלן ז א) שאין אחר בדור ראוי להנצל ואמר "בדורותיו" כי דורות רבים עברו מעת שהשחיתו ואין צדיק בארץ בלתו ואל יקשה עליך דבר רבותינו במתושלח כי הכתוב לא יספר רק שאין צדיק ראוי להנצל מן המבול מכל הדורות ההם
@148 **את שם את חם ואת יפת** . הנראה אלי כי יפת הוא הגדול שנאמר (להלן י כא) אחי יפת הגדול וכן ימנם כתולדותם בני יפת תחילה (שם שם ב) וחם הוא הקטן בכולם כאשר אמר (שם ט כד) וידע את אשר עשה לו בנו הקטן אבל הקדים שם בעבור מעלתו והזכיר חם אחריו כי כן נולדו והנה נתאחר יפת ולא רצה הכתוב לומר "שם ויפת וחם" כי היו כולם נזכרים שלא כסדר תולדותם ואין ליפת מעלה שיבטל הסדר בעבורו אבל שם הקדים אותו בעבור מעלתו אף על פי שהוא מאוחר בספור התולדות (להלן י כא) וכן בני אברהם יצחק וישמעאל (דהי"א א כח) וכן ואתן ליצחק את יעקב ואת עשו (יהושע כד ד)
@150 **כי השחית כל בשר את דרכו** . אם נפרש כל בשר כמשמעו ונאמר שאפילו בהמה וחיה ועוף השחיתו דרכם להזקק לשאינן מינן כמו שפירש רש"י נאמר כי מלאה הארץ חמס מפניהם לא מפני כולם אלא מפני מקצתם וסיפר עונש האדם לבדו או שנאמר שלא שמרו גם בזה תולדתם והיתה כל הבהמה טורפת וכל העוף דורס והנה גם הם עושים חמס ועל דרך הפשט "כל בשר" זה כל האדם ולמטה יפרש כל בשר אשר בו רוח חיים (להלן ז טו) ומכל החי ומכל בשר (להלן פסוק יט) כל חי בגוף אבל בכאן "כל בשר" כל האדם וכן יבא כל בשר להשתחוות לפני (ישעיהו סו כג) וכן בשר כי יהיה בעורו (ויקרא יג כד)
@151 **חמס** . הוא הגזל והעושק ונתן לנח הטעם בחמס ולא הזכיר השחתת הדרך כי החמס הוא החטא הידוע והמפורסם ורבותינו אמרו (סנהדרין קח) שעליו נתחתם גזר דינם והטעם מפני שהוא מצוה מושכלת אין להם בה צורך לנביא מזהיר ועוד שהוא רע לשמים ולבריות והנה הודיע לנח החטא שעליו בא הקץ הגיע הצפירה
@151 "והנני משחיתם את הארץ" - כמו מן הארץ וכן כצאתי את העיר (שמות ט כט) חלה את רגליו (מלכים א טו כג) דבר אחר את הארץ עם הארץ שאף שלשה טפחים של מחרישה נימוחו לשון רש"י מבראשית רבה (לא ז) ורבי אברהם אמר שמלת "משחיתם" מושכת עצמה ואחרת עמה והנני משחיתם ומשחית את הארץ ועל דרך האמת הוא כמו את השמים ואת הארץ כי הארץ תהיה בהשחתה שבהשחתת הארץ ישחתו והנם נשחתים בעולם הבא כדרך ויתעצב אל לבו (לעיל פסוק ו) ולזה רמזו בבראשית רבה (לא ז) לבן אדון שהיתה לו מניקה כל זמן שהיה סורח היתה מניקתו נרדית וכו'
@155 **ואני הנני מביא את המבול** . הנני מסכים עם אותן שאמרו לפני מה אנוש כי תזכרנו (תהלים ח ה) לשון רש"י מבראשית רבה (לא יב) ואני תמה והאיך מסכים עמהם והוא משאיר להם שארית לפליטה גדולה בנח ובניו וכל חי להרבות זרעם כחול אולי היא הסכמה לדעתם כשלא יחמול עליהם ועל האמת ואני כמו ויסרתי אתכם אף אני (ויקרא כו כח) וכן אני הנה בריתי אתך (להלן יז ד) ואני זאת בריתי (ישעיהו נט כא) יאמר אף אני תהיה ידי בהם על שהשחיתו את הארץ ולכך אמר (להלן ט יב) זאת אות הברית אשר אני נותן ימחץ וידיו תרפינה (איוב ה יח) והמשכיל יבין
@156 **והקמתי את בריתי** . אמר רבי אברהם לאות כי השם נשבע לו שלא ימות במבול הוא ובניו ואם לא נכתב תחילה מפורש כאשר מצאנו במשנה תורה (דברים א כב) נשלחה אנשים לפנינו ומלת והקימותי שאקיים שבועתי והקרוב אלי שזאת הברית רמז לקשת וטעם ברית הסכמה ודבר שבחרו שנים מגזרת ברו לכם (שמואל א יז ח) והמלה בסמוך ובמוכרת וכן שבית יעקב (תהלים פה ב) ובנותיו בשבית (במדבר כא כט) ויש אומרים כי ברית גבול כרות כל אלו דבריו ויותר נכון בדרך הפשט כי ענין "והקימותי את בריתי" לאמר בעת שיבא המבול תהיה ברית קיימת אתך שתבא אל התיבה אתה וביתך ושנים מכל הבשר להחיות כלומר שתחיו שם ותתקיימו לצאת משם לחיים והברית הוא דבר השם כשיגזור אומר בלא תנאי ושיור ויקיים והזכיר הברית והזכיר שיהיה קיים והוא כלשון קיימו וקבלו היהודים עליהם ועל זרעם (אסתר ט כז) שקבלו עליהם דבר להיותו קיים ועל דרך האמת הברית מעולם היא והמלה נגזרת מן בראשית ברא אלהים והנה בריתי כמו ברייתי והמלה כמו סמוכה כי היא סמוכה לעולמים שהיו לפנינו יצוה שתקום ותהיה עם הצדיק וכן ואני הנני מקים את בריתי אתכם (להלן ט ט) בריתי היתה אתו (מלאכי ב ה) והמשכיל יבין
@157 **מכל בשר וגו'** . ידוע כי החיות רבות מאד ומהן גדולות מאד כפילים וכראמים וזולתם והרמש הרומש על הארץ רב מאד גם מעוף השמים מינים רבים אין להם מספר וכמו שאמרו רבותינו (חולין סג) מאה ועשרים מיני עופות טמאים יש במזרח וכלם מין איה הם ולעופות טהורים אין מספר והנה יצטרך להביא מכלם שיולידו כמותם וכאשר תאסוף לכלם מאכל אשר יאכל לשנה תמימה לא תכיל אותם התיבה הזאת ולא עשר כיוצא בה אבל הוא נס החזיק מועט את המרובה ואם תאמר יעשנה קטנה ויסמך על הנס הזה ראה השם יתברך לעשותה גדולה כדי שיראו אותה בני דורו ויתמהו בה ויספרו עליה וידברו בענין המבול וכנוס הבהמה והחיה והעוף לתוכה אולי יעשו תשובה ועוד עשו אותה גדולה למעט בנס כי כן הדרך בכל הניסים שבתורה או בנביאים לעשות מה שביד אדם לעשות והשאר יהיה בידי שמים ואל תתפתה לאמר (ראה ראב"ע להלן פסוק טז) כי היו שלש מאות אמות באמות איש נח והיה גדול שאם כן היו גם האנשים גדולים גם החיה והעופות בדורות ההם גדולים עד שלקה העולם במבול ועוד כי האמות אמות התורה הנה
@157 "תביא אל התיבה להחיות אתך" - צוהו שיתעסק ויעזור אותם הוא בכניסתם בתיבה וישתדל בהם שיחיו כאשר ישתדל בנפשו
@158 **שנים מכל יבאו אליך להחיות** . הודיעו כי מעצמם יבאו לפניו שנים שנים ולא יצטרך הוא לצוד אותם בהרים ובאיים והוא יביאם בתיבה אחרי כן ובמעשה פירש שבאו זכר ונקבה (להלן ז ט) וזה היה בכללם אחרי כן צוהו שיקח מכל הבהמה הטהורה שבעה שבעה ובאלה לא אמר שיבאו אליו אלא שהוא יקח אותם כי הבאים להנצל ולחיות להם זרע באים מאליהם אבל הבאים להקריב עולות לא גזר שיבאו מעצמם להשחט אבל לקחם נח כי הצואה של שבעה שבעה היתה כדי שיוכל נח להקריב מהן קרבן וטעם "הטהורה" הקב"ה פירש לו סימני הטהרה אבל הכתוב יקצר לומר הטהורה על פי התורה ורש"י כתב את שעתידה להיות טהורה לישראל מלמד שלמד נח תורה והנה מכאן שלא הוכשרו בקרבנות בני נח אלא בהמה טהורה ועוף טהור וכן אמר בהבל (לעיל ד ד) מבכורות צאנו ומחלביהן אבל כל המינין הטהורים כשרין בהם כדכתיב (להלן ח כ) ויקח מכל הבהמה הטהורה ומכל עוף הטהור ויעל עולות במזבח והוסיף לישראל במצוה שיהיו כל קרבנותם מן הבקר ומן הצאן מן התורים ומן בני היונה וטעם "גם מעוף השמים" הטהור כי הכתוב נמשך למעלה
@160 **ויעש נח ככל אשר צוה אותו אלהים** . שעשה את התיבה ואסף המאכל ודרך הכתוב לאמר "ויעש" "וכן עשה" לבאר כי לא הפיל דבר מכל אשר צוה
@161 **ויאמר ה' לנח** . הודיעו השם כי במדת רחמים ימלט אותו ואת ביתו ויחיה מהם זרע לדורות וזה טעם לחיות זרע על פני כל הארץ (להלן פסוק ג) כי מתחלה אמר להחיות אתך (לעיל ו יט) ורמז לו עתה במדת רחמים על הקרבן להודיע אותו שישעה אל קרבנו ובזכות קרבנו יקיים העולם ולא יכרת עוד מפני מי המבול ועל כן מזכיר בו השם המיוחד כי בכל ענין הקרבנות לא יזכיר "אלהים" כאשר אזכיר (ויקרא א ט) בהגיעי לשם בעזרת השם
@161 "בא אתה וכל ביתך אל התיבה" - עשה נח את התיבה ימים רבים קודם המבול וכאשר קרב עת המבול בחדש השני בעשור לחדש חזר וצוהו שיבא הוא וכל ביתו בתיבה הוא שאמר לו בראשונה (לעיל ו יח) אתה ובניך ואשתך ונשי בניך והודיעו כי בזכותו לבדו ינצלו שלא אמר "אתכם ראיתי צדיקים לפני" וצוה שיקח הוא ויביא מן הבהמה הטהורה ומן העוף הטהור שבעה שבעה והודיעו יום המבול שבו יבא אל התיבה וכן עשה שבעצם היום זה בא נח (להלן פסוק יג) וזהו טעם מפני מי המבול (להלן פסוק ז) ורש"י כתב אף נח מקטני אמנה היה ולא נכנס לתיבה עד שדחפוהו המים ולשון בראשית רבה (לב ו) מחוסר אמונה היה אלולי שהגיעו מים עד קרסוליו לא היה נכנס לתיבה אם כן יאמר שלא נכנס שם עד שגברו המים וכסו פני כל הארץ וראה כי יטבע
@168 **מן הבהמה הטהורה ומן הבהמה אשר איננה טהורה שנים שנים באו אל נח** . פירש רש"י כולן הושוו במנין זה מן הפחות היו שנים ואחרים אמרו (רד"ק) כי פירוש שנים זוגות לומר שהיו באים זכר ונקבה יחד ועל דעתי שכן היה שבאו מכלם שנים זכר ונקבה מעצמם ונח הוסיף להביא מן הטהורים ששה זוגות כי הבאים להנצל באו מעצמם ואשר לצורך קרבן טרח במצוה כי כן נאמר לו וטעם ויעש נח ככל אשר צוהו ה' (לעיל פסוק ה) אמרו בבראשית רבה (לב ה) זה שיכין לכנוס בהמה וחיה ועוף כלומר הטהורים שטרח הוא אחריהם ולקחם אל ביתו והכתוב שאמר פעם שלישית כאשר צוה אלהים את נח (פסוק ט) לומר שעשה כאשר צוהו בכניסת התיבה כי הוא נמשך למעלה עם ויבא נח לומר שבא נח ובניו ואשתו ונשי בניו אל התיבה ומן הבהמה והעוף והרמש שנים שנים שבאו אליו אל התיבה וכלם באו אתו שנכנסו בתיבה מפני מי המבול כאשר צוה אותו אלהים וחזר ופירש החדש והיום שבא המבול וכיצד בא ואמר כי בעצם אותו היום הוא שבא נח אל התיבה ועמו כל הבשר החי לא קודם לכן
@175 **וטעם ויבאו אל נח אל התיבה** . להודיע שלא נאספו אליו כלל ולא באו עד עצם היום ההוא שהיה הגשם ובא הוא בתיבה כי האל הוא צוה ורוחו הוא קבצן ברגע אחד
@176 **וטעם והבאים זכר ונקבה מכל בשר באו** . כי הבאים אל תוך התיבה היו זכר ונקבה שהכניסם נח בתוכה כן ולכך אמר כאשר צוה אותו אלהים כי הוא מצוה עליו שיכניסם לתוכה ודעת רבי אברהם כי ויבא נח ובניו ואשתו ונשי בניו אתו אל התיבה (לעיל פסוק ז) לא נכנסו בתוכה אלא שבאו אליו כלם בעשור לחדש השני כי ביתו קרוב אל התיבה היה וטעם מפני מי המבול מפחד מי המבול ולשבעת הימים היה מי המבול ונאספו כלם בתיבה וסגר הפתח והצהר ואין דבריו נכונים ויתכן כי ויעש נח ככל אשר צוהו ה' ונח בן שש מאות שנה והפסוקים עד בשנת שש מאות שנה (פסוקים ה ו) אינם מספרים מעשה אבל ויעש נח ככל אשר צוהו יכלול הענין כולו יאמר שעשה ככל אשר נצטווה לא הפיל מכל הענין דבר עשה התיבה ואסף המאכל ולקח מן הבהמה והעוף הטהורים שבעה שבעה ביום אשר צוה אותו וכאשר היה בן שש מאות שנה והמבול ירד על הארץ בא עם ביתו ועם הבהמות הטהורות וכל החי אל התיבה כאשר צוהו אלהים ואחר כן (מפסוק י והלאה) ספר במעשה ויהי לשבעת הימים בשנת שש מאות וגמר הענין (יח-יט) וטעם ויגברו המים והמים גברו שנתרבו מאד כי לרבוי הגדול יקרא הלשון גבורה וכן ופשעיהם כי יתגברו (איוב לו ט) רבו מאד גבר חסדו על יראיו (תהלים קג יא) גדל וכן ואם בגבורות שמונים שנה (שם צ י) ברבוי גדול ויתכן כי טעם "ויגברו" שהיו באים בשטף ועוקרים האילנות ומפילים הבנינים כי לכח יקראו גבורה בעבור כי הגבורה בכח וכן גם גברו חיל (איוב כא ז) והגביר ברית לרבים שבוע אחד (דניאל ט כז) יעמידנו בחוזק ולשון חכמים (תענית ב) גבורת גשמים מפני שיורדין בגבורה ואפשר שיהיה מזה ואם בגבורות שמונים שנה שאם היו עצמותיו וגופו חזקים והוא בעל כח יחיה שמונים ואם כן יהיה פירוש גברו על הארץ שהיו בגבורתם כלם אף על ההרים הגבוהים ושוטפים אותם
@183 **וימח את כל היקום אשר על פני האדמה** . אחר שאמר ויגוע כל בשר ואמר מכל אשר בחרבה מתו הוסיף לאמר וימח שנמחו הגופות ויהיו למים כענין ומחה אל מי המרים (במדבר ה כג) כי היו המים רותחין כדברי רבותינו (סנהדרין קח) אבל אם כן יהיו הדגים מתיםואולי היה כמו שאמרו בבראשית רבה (לב יא) מכל אשר בחרבה ולא דגים שבים ויש אומרים אף הן בכלל נאספין אלא שברחו לאוקינוס ומכל מקום ניצולו הדגים ושני הדעות האלו אפשריים כי יתכן שמימי המבול הרותחים יתערבו בימים ויחממו עליוני הים בלבד והדגים יבאו בעמקי המצולות ויחיו שם או כדברי יש אומרים שהיו דגי הימים שבתוך הארץ הקרובים מהם לאוקינוס בורחים שם בהרגישם רתיחת המים וניצולין מהם שם ואפילו אם ימותו כלם הנה מרבית הדגה באוקינוס היא ושם לא ירד מבול כמו שנאמר (לעיל פסוק יב) ויהי הגשם על הארץ ומשם יחזרו הדגים אחרי המבול כי מן הים היו יוצאים כל הימים ושם הם שבים ללכת ועל הכלל ניצולו הדגים שהרי לא נכנסו מהם בתיבה לחיות זרע ונאמר בברית (להלן ט ט י) הנני מקים את בריתי אתכם ואת כל נפש החיה אשר אתכם בעוף ובבהמה ובכל חית הארץ אתכם מכל יוצאי התיבה ולא הזכיר דגי הים
@183 "וימחו מן הארץ" - פירשו הכפל לומר כי נשכח זכרם שאין להם זרע ומה צורך לאמר כן אחר שמתו הכל אולי מפני העופות ומקצת השרץ לאמר שלא נשאר בהם ביצים בכל עץ או תחת הארץ כי הכל נמוחו ויתכן שיהא שיעור הכתוב וימח את כל היקום אשר על פני האדמה כי מאדם עד בהמה עד רמש ועד עוף השמים נמוחו מן הארץ לא נשאר רק נח ורבותינו דרשו (סנהדרין קח) וימח בעולם הזה וימחו מן הארץ מן העולם הבא עשו הארץ הנזכרת כאן ארץ החיים וכבר רמזתי סודה (לעיל א כו ו יג)
@185 **ויזכור אלהים את נח ואת כל החיה ואת כל הבהמה** . הזכירה בנח מפני שהיה צדיק תמים וכרת לו ברית להצילו ונח יכלול זרעו אשר אתו שם ולא הזכירם כי בזכותו ניצולו אבל הזכירה שאמר בחיה ובבהמה אינה בזכות שאין בבעלי נפש זכות או חובה זולתי באדם לבדו אבל הזכירה בהם כי זכר את דבר קדשו שאמר והיה העולם והרצון אשר לו בבריאת העולם עלה לפניו ורצה בקיום העולם במינין אשר ברא בו והנה ראה עתה להוציאם שלא יכלו בתיבה ולא הזכיר העוף והשרץ כי זכירת החיה שוה עמהם ויגיד עליו רעו
@188 **ותנח התבה בחדש השביעי בשבעה עשר יום לחדש** . כתב רש"י מכאן אתה למד שהיתה משוקעת במים י"א אמה כפי החשבון הכתוב בפירושיו והוא כן בבראשית רבה (לג ז) אבל כיון שרש"י מדקדק במקומות אחרי מדרשי ההגדות וטורח לבאר פשטי המקרא הרשה אותנו לעשות כן כי שבעים פנים לתורה ומדרשים רבים חלוקים בדברי החכמים ואומר אני שאין החשבון הזה שאמרו נאות בלשון הכתוב כי אם נסבול לפרש ותנח התיבה בחדש השביעי ליום הזה הנזכר שכלא בו הגשם ושבו המים מעל הארץ הלוך וחסור שלא כמנין החדש השני הנזכר בהתחלת הפרשה (ז יא) וכמנין האמור בסוף הפרשה (ח יד) איך יתכן שיחזור מיד בפסוק השני ויאמר עד החדש העשירי למנין אחר שיהיה העשירי לירידת הגשמים והראיה מן התיבה שהיתה משוקעת במים מפני שנותן חסרון שוה לכל הימים אמה לד' ימים אינה ראיה כי מן הידוע בחסרון המים כי הנחל הגדול כאשר יחסר בתחלתו אמה לד' ימים יחסר בסופו ד' אמות ליום אחד והרי לפי החשבון הזה באחד לחדש אב נראו ראשי ההרים ובאחד בתשרי חרבו המים והנה בששים יום חסרו כל גובה ההרים הגבוהים שהם כמה אלפים אמה ועוד כי שלח היונה בשבעה עשר יום לחדש אלול והמים על פני כל הארץ והאילנות מכוסים והנה חרבו כולם בשנים עשר ימים ועל דרך הסברא אם היתה משוקעת במים י"א אמה והוא יותר משליש קומתה תטבע בעבור היותה רחבה מלמטה וכלה אל אמה כי היא הפך הספינות ויש בה כבדות גדולה והנראה בדרך הפשט כי חמשים ומאת יום האמורים בתגברות המים (לעיל ז כד) יכללו ארבעים יום של ירידת הגשם כי בהם עיקר הרבוי והתגברות והנה החלו לחסור בשבעה עשר בניסן ותנח התיבה אחר שלשים יום על הרי אררט בשבעה עשר יום לחדש אייר הוא החדש השביעי לירידת הגשם ואחרי ע"ג ימים באחד לחדש אב הוא החדש העשירי לירידה נראו ראשי ההרים והנה תקננו תקון מועט בלשון הכתוב והנכון בעיני כי חמשים ומאת יום היו משבעה עשר יום לחדש השני הוא חדש מרחשון עד שבעה עשר יום לחדש השביעי הוא חדש ניסן והוא יום מנוח התיבה כי אז העביר השם רוח קדים עזה כל הלילה וישם את המים לחרבה שחסרו מאד ותנח התיבה והראיה כי לא אמר הכתוב בכאן "ויחסרו המים בחדש פלוני ביום פלוני והיו המים הלוך וחסור עד החדש השביעי ותנח התיבה וגו'" כאשר אמר בחסרון האחר שנראו בו ראשי ההרים כי ביום החסרון נחה התיבה והסדר בענין הזה כי ביום רדת הגשם נבקעו מעינות תהום ונפתחו ארובות השמים וירד הגשם ארבעים יום ובהם גברו המים חמש עשרה אמה מלמעלה ונפסק הגשם בסוף הארבעים ונשארו מעיינות תהום וארובות השמים פתוחות והיה האויר לח מאד וכל הארץ מלאה מים ואינם נגררים במורד ולא יבשו לעולם ועמדו כן בגבורתם עד מלאת ק"נ יום לירידת הגשם ואז העביר השם רוח חזק מאד בשמים ובארץ ויסכרו מעיינות תהום כי חזרו המים הנובעים מהם אל מקומם עד אשר נתמלא התהום כמו שהיה בתחלה ונסגרו פתחי מעיינותיו וארובות השמים נסגרו וייבש האויר מאד ברוח המייבש והמים אשר בארץ לחכה והנה חסרו המים הרבה ביום ההוא ותנח התיבה שהיתה משוקעת במים כשתים ושלש אמות ואחר שבעים ושלש יום באחד לחדש העשירי הוא חדש תמוז נראו ראשי ההרים ומקץ ארבעים יום בעשתי עשר חדש בעשרה לחדש פתח נח חלון התיבה ואחרי שלש שבועות הלכה היונה מאתו ואחר שלשים יום הסיר מכסה התיבה וטעם ויעבר אלהים רוח על הארץ שהיה רוח גדולה וחזק יוצאה מבטן הארץ על פני התהום ומרחפת במים ויסכרו בו מעיינות תהום כי לא אמר הכתוב "ויעבר אלהים רוח על המים" וישכו המים שהיו נובעין מן התהום וינוחו מלשון וחמת המלך שככה (אסתר ז י) שנחה או לשון הסתר הדבר והבלעו ללמד שנבלעו מי התהום במקומם וכך אמר זה בסדר עולם (ד) המים העולים למעלה נגבה אותם הרוח והיורדים למטה נבלעו במקומם וטעם ויכלא הגשם מן השמים שלא ירד עוד גשם עד צאתם מן התיבה כי היו השמים ברוח הזה כברזל ולא הורידו טל ומטר כלל וייבש האויר וחרבו המים כי גשם המבול כבר כלה מיום הארבעים וישובו המים מעל הארץ הלוך ושוב יאמר שהיו חסרים מעט מעט עד שחרבו פני האדמה ויחסרו המים מקצה חמשים ומאת יום דבק עם "ותנח התיבה" לומר שחסרו ביום ההוא חסרון גדול שנחה בו התיבה כאשר פירשתי
@189 **והמים היו הלוך וחסור עד החדש העשירי** . טעמו מסורס שהיו הלוך וחסור עד שנראו ראשי ההרים בחדש העשירי הוא חדש תמוז והודיענו הכתוב שחסרו בע"ג יום חמש עשרה אמה אבל החסרון אשר מתחלה למנוח התיבה לא ידענו כמה היה כי לא הוצרך הכתוב להודיע השקוע ולא החסרון והנראה לדעתי בשוט התיבה כי היתה מפני היות המים נובעים מן התהומות והיותם עוד רותחים כדברי רבותינו כי בעבור כן תלך על פני המים ואם לא מפני זה היתה נטבעת בכבדותה כי רבים אשר בתוכה והמאכל והמשקה היה הרבה מאד וכאשר שככו המים מנביעתם או מרתיחתם גם כן וחסרו ברוח מיד נכנסה התיבה אל תוך המים בכובד משאה ותנח על ההר ועל דעת המפרשים (הראב"ע והרד"ק) המספר בתגבורת המים חמשים ומאת יום ומנוח התיבה וראיית ראשי ההרים וארבעים יום אחרי כן הכל ידענו בדרך הנבואה כי הכתוב מודיע אותנו כן אבל נח לא ידע רק שהרגיש כי נחה התיבה והמתין לפי דעתו זמן שחשב כי קלו המים והנה גם לדברינו גם לדברי רבותינו וכל המפרשים יהיו הרי אררט מן "ההרים הגבוהים אשר תחת כל השמים" (לעיל ז יט) שהיו המים עליהם ט"ו אמה ולכן יקשה זה כי הידוע בהר היוני שגבוה מהם הרבה מאד וארץ אררט בשפל הכדור הקרוב לבבל ואולי נאמר כי היה החסרון בי"ז לחדש השביעי גדול מאד מט"ו אמה וקודם לכן נראו ראשי ההרים הגבוהים לא הרי אררט ויקר מקרה התיבה שהיתה בארץ אררט בחדש השביעי ותנח על ראשי ההרים ההם והנה נח מעת שכלה הגשם היה פותח החלון וסוגר אותו כרצונו ואחר ע"ג יום ממנוח התיבה השגיח מן החלון ונראו לו ראשי הרי אררט וחזר וסגר אותו והגיד הכתוב כי אחר ארבעים יום שלח העורב ולא אמר הכתוב "ויהי בחדש פלוני וביום פלוני ויפתח נח" ואמר "ויהי מקץ ארבעים יום" להגיד כי מעת שנראו לנח ראשי ההרים המתין ארבעים יום כי חשב בלבו שבזמן הזה נראו המגדלים ונגלו האילנות וימצאו העופות להם מנוח באשר תקנינה ופתח החלון לשלוח העורב ובחדש הראשון הוא חדש תשרי חרבו המים ובחדש השני הוא חדש מרחשון בשבעה ועשרים בו יבשה הארץ ובו ביום יצאו מן התיבה והנה כל מנין הפרשה כפשוטו ומשמעו ודע כי אחרי שהסכימו שבתשרי נברא העולם כאשר תקנו "זה היום תחלת מעשיך זכרון ליום ראשון" וכן הוא סדר הזמנים זרע וקציר וקור וחום יהיה ראש השנים מתשרי וכן החדשים ממנו הם נמנים עד שהגענו ליציאת מצרים ואז צוה הקב"ה למנות בחדשים מנין אחר שנאמר (שמות יב ב) החדש הזה לכם ראש חדשים ראשון הוא לכם לחדשי השנה ומשם ואילך בכל הכתוב ימנה תשרי החדש השביעי ועדיין נשאר בשנים החשבון ממנו דכתיב (שמות לד כב) וחג האסיף תקופת השנה וכך תרגם יונתן בן עוזיאל "בירח האיתנים בחג הוא החדש השביעי" (מלכים א ח ב) אמר בירחא דעתיקיא דקרן ליה ירחא קדמאה וכען הוא ירחא שביעאה ובמכילתא (בא א ח) החדש הזה לכם ולא מנה בו אדם הראשון
@193 **ולא מצאה היונה מנוח** . אין מנהג העופות לנוח בראשי ההרים הגבוהים על הארץ ואין אילן שם אף כי בהיות המים על פני כל הארץ ולכן לא מצאה היונה מנוח אשר ייטב לה ובעת הראות האילנות הלכה לנפשה כי בדליותיהם תקננה
@195 **והנה עלה זית טרף בפיה** . מפשוטו של פסוק זה יראה שלא נעקרו האילנות ולא נמחו במבול כי לא היה שם נחל שוטף בעבור כי נתמלא כל העולם מים אבל בבראשית רבה (לג ו) אמרו מהיכן הביאה אותו רבי לוי אמר מהר המשחה הביאה אותו דלא טפת ארעא דישראל במיא דמבולא הוא שהקדוש ברוך הוא אמר ליחזקאל בן אדם אמור לה את ארץ לא מטוהרה היא לא גושמה ביום זעם (יחזקאל כב כד) רבי ביריי אמר נפתחו לה שערי גן עדן והביאה אותו והנה כוונתם שנעקרו האילנות ונמחו במקומות המבול ואף כי יהיה העלה נבל וכן אמרו (ב"ר ל ח) אפילו איצטרובולין של ריחים נמוחו במבול ודרשו בו אבנים שחקו מים (איוב יד יט) ומאמרם "דלא טפת ארעא דישראל במיא דמבולא" שלא היה עליה גשם המבול כדכתיב לא גושמה ולא נפתחו בה מעינות תהום רבה אבל המים נתפשטו בכל העולם וכסו כל ההרים הגבוהים אשר תחת כל השמים כמו שכתוב מפורש (לעיל ז יט) ואין סביב ארץ ישראל גדר לעכב המים שלא יבאו בה וכך אמרו בפרקי רבי אליעזר (פרק כג) ארץ ישראל לא ירד עליה מי המבול מן השמים אלא נתגלגלו המים מן הארצות ונכנסו לתוכה שנאמר בן אדם אמור לה והנה לדעת רבי לוי מפני שלא ירד בארץ ההיא הגשם השוטף ולא נפתחו עליה ארובות השמים נשארו בה האילנות ובכל העולם נשברו ונעקרו במבול ומטרות עזו ואני תמה על מאמרם "מגן עדן" אם כן לא ידע נח שקלו המים מעל הארץ כי שם לא נכנסו מי המבול ואולי היו שעריו סגורים שלא יכנסו שם המים וכאשר קלו המים נפתחו ומדעתם זו אמרו שם (ב"ר לו ג) ויטע כרם (להלן ט כ) ומהיכן היה לו אמר רבי אבא בר כהנא בכניסתו לתיבה הכניס עמו זמורות לנטיעות יחורים לתאנים גרופיות לזתים
@195 "טרף בפיה" - כתב רש"י: "אומר אני שזכר היה ולכך קורא אותו פעמים לשון זכר ופעמים לשון נקבה לפי שכל יונה שבמקרא לשון נקבה הוא טרף חטף. ומדרש אגדה לשון "מזון" ודרשו "בפיה" לשון מאמר אמרה יהיו מזונותי מרורין כזית ובידו של הקב"ה ואל יהיו מתוקים כדבש ביד אדם". ואין כל זה נכון בעיני, כי חזרת זכר היונים מנקבה לזכר במקום אחד מן הפרשה אין בו טעם, ואם הלשון לקרוא כלם בשם הנקבות למה שינה בכאן? וכן מדרשם בהגדה לא שיעשו "בפיה" לשון מאמר כלל, אבל מדרשם מפני שהביאה העלה הזה, כי אם נאמר שאירע כן לא על חנם פירש אותו הכתוב, כי היה לו לומר והנה עלה טרף בפיה, והזית איננו בא מן האילנות הגבוהים מאד שישכנו בו העופות לארך דליותיו, ולכך אמרו כי היה בזה רמז, שהעופות נוח להם להיות מזונותם מרים כלענה ביד הקב"ה ולא שיהיו טובים בידי אדם, וכל שכן בני האדם שאין רצונם להתפרנס זה מזה.
@195 ולשון בראשית רבה (בראשית רבה לג ו): "אמר רבי אבהו אילו מגן עדן הביאה אותו לא היה לה להביא דבר מעולה או קנמון או פפולסמון אלא רמז רמזה לו נח מר מזה מתחת ידו של הקדוש ברוך הוא ולא מתוק מתחת ידך". אבל בגמרא הוסיפו (סנהדרין קח א): "מאי משמע דהאי טרף לישנא דמזוני הוא דכתיב (משלי ל ח) הטריפני לחם חקי". כי מפני הטעם שאמרנו, עשו לזה סמך מלשון "הטריפני", ירמוז כאילו אמר והנה עלה זית טרף בפיה.
@195 ופשוטו של מקרא, פרשו בו (אונקלוס הראב"ע והרד"ק) שהוא תאר לעלה: והנה עלה זית טרוף בפיה. וסמך לדבר, שהוא קמוץ, כי כן משפטו. אבל נמצא מהם בזרות, (הושע ו א): "כי הוא טרף וירפאנו", (ויקרא ה כג): "והשיב את הגזלה אשר גזל", (ויקרא ה יח): "על שגגתו אשר שגג", וזולתם רבים.
@205 **ויאמר ה' אל לבו** . לא גלה הדבר לנביא בזמן ההוא רק ביום צוותו את משה בכתיבת התורה גלה אליו כי כאשר הקריב נח קרבנו עלה לפניו לרצון וגזר שלא יוסיף להכות את כל חי וכבר כתבתי בזה (לעיל ו ו) סוד נרמז לרבותינו ז"ל וטעם בעבור האדם כי בעבורו נענשו ואם אדם לא חטא היו הם ניצולין אף על פי שהשחיתו גם הם דרכם
@205 "כי יצר לב האדם רע מנעוריו" - מלמד עליהם זכות שיצירתם בתולדת רעה בימי הנעורים ולא בימי הזקנה ואם כן אין להכות את כל חי מפני שני הטעמים האלה וטעם המ"ם כי מתחלת הנעורים הוא בהם כמו שאמרו (ב"ר לד יב) משננער לצאת ממעי אמו נתן בו יצר הרע או יאמר כי מן הנעורים כלומר מחמתם תהיה רעת היצר באדם שהם יחטיאו אותו ויש אומרים שהוא כמו בנעוריו וכמוהו מטרם שום אבן אל אבן בהיכל ה' (חגי ב טו) וכן זאת הארץ אשר תפילו מנחלה לשבטי ישראל (יחזקאל מח כט)
@209 **כל רמש אשר הוא חי** . ירמוז לבהמה ולחיה ולעוף וגם לדגי הים כי כלם נקראים רמש כדכתיב (לעיל א כא) כל נפש החיה הרומשת אשר שרצו המים
@210 **אך בשר בנפשו דמו** . כתב רש"י בעוד נפשו בו בשר בנפשו לא תאכלו הרי אבר מן החי ואף דם לא תאכלו הרי דם מן החי אם כן יאמר בשר בנפשו ודמו לא תאכלו וזה כפי הפשט איננו נכון ולפי המדרש איננו אמת שלא נצטוו בני נח אלא על אבר מן החי כדברי חכמים (סנהדרין נט) לא על דם מן החי כדברי רבי חנינא בן גמליאל (שם) אבל פירושו אך בשר בנפשו שהיא דמו לא תאכלו כי נפש כל בשר דמו הוא
@211 **דמכם לנפשתיכם** . דמכם נפשותיכם כלומר דמכם שהוא נפשותיכם כדרך לכל כלי המשכן (שמות כז יט) וכן השלישי לאבשלום (דהי"א ג ב) ויש לפרש את דמכם לנפשותיכם בנפשותיכם כי נפש כל בשר דמו בנפשו הוא (ויקרא יז יד) וכמוהו וכל דם לא תאכלו בכל מושבותיכם לעוף ולבהמה (שם ז כו) פתרונו בעוף או בבהמה והנכון שיאמר הדם שהוא לנפש בכם אדרוש הגיד כי הדם הוא הנפש ורמז כי על שופך הנפש הוא מחייב מיתה לא על דם האיברים שאין הנשמה תלויה בהם ורבותינו (ב"ק צא) דרשו בו הורג את עצמו את דמכם מנפשותיכם אדרוש
@211 "מיד כל חיה אדרשנו" - תמה אני אם הדרישה כמשמעה מיד החיה כמו מיד האדם להיות עונש בדבר ואין בחיה דעת שתענש או שתקבל שכר ואולי יהיה כן בענין דם האדם לבדו שכל החיה שתטרוף אותו תטרף כי גזרת מלך היא וזה טעם סקול יסקל השור ולא יאכל את בשרו (שמות כא כח) ואיננו להעניש את בעליו בממון כי אפילו שור המדבר חייב מיתה (ב"ק מד) וצוה כן בבני נח כבישראל ויהיה טעם " שופך דם האדם" כל שופך בין חיה בין אדם והנה דמו נדרש בבית דין ובידי שמים ויתכן שיהיה טעם "מיד כל חיה" שתהיה הנקמה בשופך הדם מיד כל חיה כמו כי לקחה מיד ה' כפלים בכל חטאתיה (ישעיהו מ ב) ואמר אך דמכם אדרוש ואנקום אותו ביד כל חיה כי אשלח ברוצח כל חית הארץ ואשלח בו גם האדם ולא ינצל מידם וכמוהו מכל צוררי הייתי חרפה (תהלים לא יב) מידם זה חלק אדם רשע מאלהים ונחלת אמרו מאל (איוב כ כט) ואולי הדרישה מיד החיה היא שלא תטרוף האדם כי כן שם בטבעם וסוד הענין כי בעת היצירה נתן לאדם את כל עשב זורע זרע ואת כל העץ אשר בו פרי עץ לאכלה ונתן לחיה את כל ירק עשב לאכלה ואמר הכתוב (לעיל א ל) ויהי כן כי הוא טבעם ומנהגם ועתה כאשר אמר באדם שישחוט הבעלי החיים והושם בטבע או במנהג שיהיו בעלי החיים זה לזה לאכלה הוצרך לצוות שיהיו שאר בעלי החיים לבני אדם טרף לשיניהם והם ייראו מהם ולא יטרופו בהם ואמר ואך את דמכם לנפשותיכם לרמוז כי לא ידרוש דם חיה מיד חברתה אם כן נשאר בהם לטרוף זו את זו וזה טעם הזכירו איסור שפיכת דמים בכאן מפני היתר השחיטה שהיה המנהג לשפוך דם כי על דעת רבותינו (סנהדרין נו) כבר הזהיר אדם הראשון בזה אבל מפני השחיטה הוצרך לומר התרתי לכם לשפוך דם כל חי זולתי דמכם שיהיה אסור לכם ולכל החיים שלא יהיה להם טבע לשפוך אותו
@213 **ואתם פרו ורבו** . פשוטו כמדרשו שהיא מצוה כי האמור באדם (לעיל א כח) גם בבני נח (שם ט א) עם "ויברך אותם אלהים" ברכה כענין שנאמר בדגים (שם א כב) ובעבור שדבר בשאר הנפש החיה ואמר "ושרצו בארץ ופרו ורבו על הארץ" (שם ח יז) אמר כאן ואתם האדם פרו ורבו ואמר שרצו בארץ ורבו בה כי יכפול המצוה לחזוק לומר שיתעסקו בה בכל יכולתם או שיצום ביישוב כל הארץ כאשר פירשתי בסדר בראשית (א כ) ורש"י כתב לפי פשוטו הראשונה לברכה וכאן לצווי ולפי מדרשו להקיש מי שאינו עוסק בפריה ורביה לשופך דמים והמדרש הזה לא הוציאו אותו אלא מן הסמוכים אבל המקרא למצוה נכתב והראשונה לברכה וכך אמרו והרי פריה ורביה שנאמרה לבני נח דכתיב ואתם פרו ורבו וכו' כדאיתא בסנהדרין (נט)
@214 **וטעם ויאמר אלהים אל נח ואל בניו אתו** . על ידי אביהם כי בניו לא היו נביאים ולא הגיע חם למעלת הנבואה וכן ויאמר ה' אל אחז (ישעיהו ז י) וכן ויאמר ה' אל משה ואל אהרן (שמות ז ח) כדברי רבותינו (ת"כ ויקרא א) אל משה אמר שיאמר לאהרן וכן פירש בסוף ויאמר אלהים אל נח (להלן פסוק יז)
@218 **זאת אות הברית אשר אני נותן** . המשמע מן האות הזה שלא היה קשת בענן ממעשה בראשית ועתה ברא ה' חדשה לעשות קשת בשמים ביום ענן ואמרו בטעם האות הזה כי הקשת לא עשאו שיהיו רגליו למעלה שיראה כאלו מן השמים מורים בו וישלח חציו ויפיצם בארץ (תהלים יח טו) אבל עשאו בהפך מזה להראות שלא יורו בו מן השמים וכן דרך הנלחמים להפוך אותו בידם ככה כאשר יקראו לשלום למי שכנגדם ועוד שאין לקשת יתר לכונן חצים עליו ואנחנו על כרחנו נאמין לדברי היונים שמלהט השמש באויר הלח יהיה הקשת בתולדה כי בכלי מים לפני השמש יראה כמראה הקשת וכאשר נסתכל עוד בלשון הכתוב נבין כן כי אמר את קשתי "נתתי" בענן ולא אמר "אני נותן" בענן כאשר אמר זאת אות הברית אשר "אני נותן" ומלת קשתי מורה שהיתה לו הקשת תחלה ולכן נפרש הכתוב הקשת אשר נתתי בענן מיום הבריאה תהיה מן היום הזה והלאה לאות ברית ביני וביניכם שכל זמן שאראנה אזכיר כי ברית שלום ביני וביניכם ואם תבקש מה טעם בקשת להיות אות הנה הוא כטעם עד הגל הזה ועדה המצבה (להלן לא נב) וכן כי את שבע כבשות תקח מידי בעבור תהיה לי לעדה (להלן כא ל) כי כל הדבר הנראה שיושם לפני שנים להזכירם ענין נדור ביניהם יקרא אות וכל הסכמה ברית וכן במילה אמר והיה לאות ברית ביני וביניכם (להלן יז יא) בעבור ההסכמה שימולו כל זרע אברהם לעבדו שכם אחד ועוד כי כאשר תראה בהפוך הנזכר יהיה זכר לשלום כאשר כתבנו ובין שתהיה הקשת עתה בין שהיתה מעולם בטבע הטעם באות שבה אחד הוא אבל יש לרבותינו בפרשה הזאת סוד נעלם אמרו בבראשית רבה (לה ג) את קשתי נתתי בענן קשותי דבר שהוא מוקש לי אפשר כן אלא קשין דפריא והיה בענני ענן רבי יודן בשם ר' יהודה בר' סימון אומר משל לאחד שבידו סולת רותח ובקש ליתנו על בנו ונתנו על עבדו ושם עוד והיתה הקשת בענן וראיתיה לזכור ברית עולם בין אלהים זו מדת הדין של מעלה ובין כל נפש חיה בכל בשר אשר על הארץ זו מדת הדין של מטה מדת הדין של מעלה קשה ומדת הדין של מטה רפה וכבר ידעת מאמרם (חגיגה טז) במסתכל בקשת כל שלא חס על כבוד קונו ראוי לו שלא בא לעולם ואם זכית להבין דבריהם תדע כי פירוש הכתוב כן את קשתי שהיא מדת הדין הנתונה בענן בעת הדין תהיה לאות ברית
@220 **והיה בענני ענן על הארץ** . שלא יאר ה' פניו אליה מחטאות יושביה ונראתה מדת הדין שלי בענן ואזכור את הברית בזכר הרחמים ואחמול על הטף אשר בארץ והנה האות הזה והברית הוא אות המילה והברית שבה ולשון המקראות נאות מאד לענין והנה פירשו בין אלהים מדת הדין של מעלה שהיא הגבורה ואשר על הארץ מדת הדין של מטה שהיא מדה נוחה מנהגת הארץ עם הרחמים כי לא אמר אשר בארץ רק אשר על הארץ וכבר רמזתי (לעיל ו יג) סודם בשם הארץ ורש"י כתב בין מדת הדין של מעלה וביניכם אבל רבותינו לא לכך נתכוונו
@224 **וחם הוא אבי כנען** . פירש רש"י לפי שהפרשה עסוקה ובאה בשכרותו של נח שקלקל בה חם ועל ידו נתקלל כנען ועדיין לא כתב תולדות חם הוצרך לומר שחם הוא אבי כנען ורבי אברהם אמר כי חם ראה והגיד לאחיו וכנען עשה לו רעה לא גלה אותה הכתוב וזה טעם את אשר עשה לו "בנו הקטן" כי כנען הוא הקטן לחם כאשר ימנה אותם ובני חם כוש ומצרים ופוט וכנען והנה עזב רבי אברהם דרכו בפשוטי המקרא והחל להנבא שקרים והנכון בעיני כי חם הוא הקטן לנח כאשר פירשתי בראש הסדר (לעיל ו י) וכנען הוא הבן הגדול לחם ואשר אמר ובני חם כוש ומצרים ופוט וכנען אחרי נמכר לעבד עבדים נתן לכל אחיו מעלה עליו וכאשר אירע המעשה הזה לנח לא היה לחם זרע זולתי כנען וזהו טעם וירא חם "אבי כנען" (להלן פסוק כב) כי אין לו בן אחר וכאשר חטא לאביו קלל זרעו ואם אמר "ארור חם עבד עבדים יהיה" לא יזיק רק לגופו כי הזרע שכבר נולד איננו בכללו ואולי לא יוליד ולא לקח ממנו נקמתו כי מי יודע מה יהיה אחריו על כן קלל הבן שהיה לו ואם יוליד מאה די שיקולל בנו הבכור וכל זרעו אתו והנה החטא שראה חם ערות אביו ולא נהג בו כבוד שהיה ראוי לו לכסות ערותו ולכסות קלונו שלא יגידנו גם לאחיו והוא הגיד הדבר לשני אחיו בפני רבים להלעיג עליו וזה טעם "בחוץ" וכן תרגם אונקלוס "בשוקא" וטעם וידע את אשר "עשה לו" שגלה חרפתו לרבים והיה בוש בדבר ורבותינו הוסיפו עליו חטא (עיין סנהדרין ע)
@226 **איש האדמה** . פירש רש"י אדוני האדמה כמו איש נעמי (רות א ג) ואינו כן כי איש נעמי לשון אישות כמו איש ואשתו (לעיל ז ב) ואחרים אמרו (הרד"ק בספר השרשים) גדול האדמה וראשה והביאו דומים לו גדעון בן יואש איש ישראל (שופטים ז יד) גם בני אדם גם בני איש (תהלים מט ג) הלא איש אתה ומי כמוך בישראל (שמואל א כו טו) ורבים לפי דעתם ועל דעתי גדעון בן יואש איש ישראל ייחוס איש ישראלי הלא איש אתה שאין כמוך בישראל וכן התחזקו והיו לאנשים (שמואל א ד ט) שלא יהיו כנשים גם בני אדם גם בני איש פלוני הידוע במעלתו אבל "איש האדמה" כמו אנשי העיר (להלן יט ד) בעבור היותו דר בכל האדמה לא בנה עיר ומדינה שיתייחס אליה וכן איש שדה (להלן כה כז) העומד שם כל היום תמיד ובמשנה (אבות א ד) יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים או שנתן לבו לעבוד את האדמה לזרוע ולנטוע בעבור מצאו הארץ שממה שכל נבדל לדבר יקרא כן אנשי העיר הם יושביה ואנשי דוד (שמואל א כג ג) עבדיו ואיש האלהים (דברים לג א) המיוחד בעבודתו וכך אמרו בבראשית רבה (לו ג) איש האדמה בורגר לשם בורגרות ואמרו (שם) שהיה להוט אחר האדמה והנה הוא ייחוס וטעם ויחל כי הוא החל לנטוע כרמים כי הראשונים נטעו גפן והוא החל לנטוע גפנים רבים שורות שורות הנקרא "כרם" כי ברצותו ביין לא נטע הגפן כשאר האילנות ועשה כרם
@232 **ויהי כנען עבד למו** . פירש רבי אברהם כי "למו" שיהיה כנען עבד לאלהים ולשם כי הוא יכריחנו לעבוד האל ובשני פירש שיהיה עבד ליפת ולשם ואם כן נח לקוב אויביו בא והנה ברכם ברך שיהיה כנען עבד לאלהים ורש"י כתב ברוך ה' אלהי שם שעתיד לשמור הבטחתו לזרעו של שם לתת להם ארץ כנען ויהי להם כנען למס עובד והחזיר כן פעם אחרת לומר אף משיגלו בני שם ימכרו להם עבדים מבני כנען והנכון בעיני כי מתחלה קלל אותו שיהיה עבד עבדים לכל העולם והיה כל מוצאו יעבוד בו כי טעם "לאחיו" לכל בני אדם כענין ואשלח את כל האדם איש ברעהו (זכריה ח י) כטעם איש באיש (ישעיהו ג ה) או "לאחיו" שם ויפת כי אחי אביו יקראו אחיו כטעם כי נשבה אחיו (להלן יד יד) ויש אומרים (הראב"ע והרד"ק) "לאחיו" בני אביו כי אחרי היותו עבד לבני אביו ולשם ויפת הנה הוא עבד לכל העולם וברך תחלה אלהי שם הודיעו כי יהיה שם עובד האלהים וכנען יהיה עובד לו ו"למו" ירמוז לזרעו של שם שהם רבים ויתכן שיהיה "למו" חוזר גם לאחיו הנזכרים וחזר וברך יפת בהרחבת הגבול ושם בשכון האלהים באהליו ושיהיה כנען עבד למו לשניהם והנה העביד כנען לשם שני פעמים רמז כי הוא ינחל ארצו וכל אשר לו כי מה שקנה עבד קנה רבו (פסחים פח) ונכתבה זאת הפרשה להודיע כי בחטאו היה כנען עבד עולם וזכה אברהם בארצו ונכתב ענין היין בנח כי יש בו אזהרה ממנו יותר מפרשת נזירות כי הצדיק תמים אשר צדקו הציל כל העולם גם אותו החטיא היין והביא אותו לידי בזיון וקללת זרעו
@236 **וטעם ויולדו להם בנים אחר המבול** . לרמוז כי אף על פי שהיו ראוים לבנים קודם המבול כי דרך הדורות ההם להוליד כבני ששים אלו לא נולדו להם גם למאה רק אחר המבול כי כבש השם את מעיינם שלא יולידו ויאבדו במבול או שיצטרך להציל רבים בתיבה וכן עשה לכל המשפחה הזאת כי למך נתאחר בתולדות נח יותר מכפלים באבותיו ונח הרבה מאד וכבר הוזכר זה בפירוש רש"י (לעיל ה לב) מבראשית רבה (כו ב)
@237 **בני יפת גומר** . החל ממנו כי הוא הבכור ונתן אחריו חם כי רצה לאחר תולדת שם לקרב שני הפרשיות בתולדותיו כי יש להאריך בתולדות אברהם
@240 **וטעם מאלה נפרדו איי הגויים בארצותם** . כי בני יפת יושבי איי הים והם נפרדים כל אחד מבניו באי אחר יושב לבדו וארצותם רחוקות זו מזו והיא ברכת אביהם שאמר יפת אלהים ליפת שיהיו רבים במרחבי ארץ אבל בני חם כלם קרובים יושבי הארצות ולכן אמר ויהי גבול הכנעני מצידון וגו' (להלן פסוק יט) ואמר בארצותם בגויהם (פסוק כ) וכן בבני שם וספר הכתוב כל אלה כי רצה להודיע יחוס אברהם משם ותולדות חם להודיע העמים שזכה אברהם בארצם בעון אבותם ולכן ספר גם ביפת והפלגה להודיע סבת שנוי הלשונות ופזורם בקצוי הארץ לזמן מועט אחרי אדם הראשון ועוד להודיע חסדי השם ושמרו הברית לנח כי לא כלה אותם והרב אמר במורה הנבוכים (ג נ) כי זה יאמת לשומעים חדוש העולם וגם זה אמת כי אברהם אבינו יצוה את בניו ואת ביתו אחריו ויעיד להם על נח ובניו שראו המבול והיו בתיבה והנה הוא עד מפי עד בענין כל המבול ועד רביעי על יצירה כי נח ראה אביו שראה אדם הראשון ויצחק ויעקב ראו שם העד במבול ויעקב מגיד כל זה ליורדי מצרים גם לפרעה ואנשי דורו והאנשים בכל דור יודעים מאבותם ארבעה וחמשה דורות מגידים מעשיהם ותולדותיהם
@242 **ובני כוש סבא וחוילה** . היו אלה ראשי אומות ובני רעמה היו שני לאומים אבל נמרוד לא היה לאום על כן כתב אחר כך וכוש ילד את נמרוד ולא אמר "ובני כוש נמרוד וסבא וחוילה" אבל פוט היה לגוי אחד ולא היו ממנו אומות שונות כמצרים וכנען על כן לא החזירו הכתוב ובבראשית רבה (לז ב) אמר ריש לקיש היינו סבורים שנבלעה משפחתו של פוט ובא יחזקאל ופירש פוט ולוד וכל הערב (יחזקאל ל ה) כי מפני שלא החזירו הכתוב היינו סבורים שנתערב זרעו בבני כנען ולא היו אומה ולא ירשו להם ארץ שתקרא על שמם אבל גם במגוג ומדי ותובל ומשך ותירס בני יפת לא הזכיר משפחות בתולדותם וכן בבני שם עילם ואשור וארפכשד ולוד ראשי אומות ולא הזכיר להם תולדות כי כל אחד היה לגוי אחד בארץ ולא הוליד אומות שונות
@243 **הוא החל להיות גבור בארץ** . כתב רש"י להמריד כל העולם על הקב"ה בעצת דור הפלגה ואם כן "הוא החל" אחר המבול כי בימי דור אנוש הוחל ואפשר שנאמר כי הוחל בדור הפלגה מרד ובימי אנוש לא היו במורדי אור אבל עבדו גם לאלהים אחרים
@244 **הוא היה גבור ציד לפני ה'** . צד דעתן של בריות בפיו ומטען למרוד במקום על כן יאמר על כל אדם מרשיע בעזות פנים ויודע רבונו ומתכוין למרוד בו יאמר זה כנמרוד לשון רש"י וכן דעת רבותינו (עירובין נג) ורבי אברהם פירש הפך הענין על דרך פשוטו כי הוא החל להיות גבור על החיות לצוד אותן ופירש "לפני ה'" שהיה בונה מזבחות ומעלה את החיות לעולה לפני השם ואין דבריו נראין והנה הוא מצדיק רשע כי רבותינו ידעו רשעו בקבלה והנכון בעיני כי הוא החל להיות מושל בגבורתו על האנשים והוא המולך תחלה כי עד ימיו לא היו מלחמות ולא מלך מלך וגבר תחלה על אנשי בבל עד שמלך עליהם ואחר כן יצא אל אשור ועשה כרצונו והגדיל ובנה שם ערים בצורות בתקפו ובגבורתו וזהו שאמר ותהי ראשית ממלכתו בבל וארך ואכד וכלנה
@246 **מן הארץ ההיא** . במלכו עליה יצא אשור פתרונו יצא אל אשור כי אשור מבני שם היה וזהו כלשון ויצא חצר אדר ועבר עצמונה (במדבר לד ד) ויצא עוג מלך הבשן לקראתנו אדרעי (דברים ג א) וישוב ארצו ברכוש גדול (דניאל יא כח) ורבים כן ולכך תקרא ארץ אשור "ארץ נמרוד" כמו שנאמר (מיכה ה ה) ורעו את אשור בחרב ואת ארץ נמרוד בפתחיה ו"ארץ נמרוד" ירמוז אל נינוה ואל רחובות עיר ואל כלח וסיפר עוד בגבורתו כי הוא גבור ציד להתגבר גם על החיות ולצוד אותן ואמר לפני ה' להפליג כי אין תחת כל השמים כמוהו בגבורה וכן ותשחת הארץ לפני האלהים (לעיל ו יא) כי כל אשר לפניו בארץ נשחתו כענין ונכרתה הנפש ההיא מלפני (ויקרא כב ג) כי בכל מקום הוא לפניו
@248 **ומצרים ילד** . יזכיר למצרים תולדותיו ולא הזכיר מושבם כמו שהזכיר באחרים כי בבני יפת הזכיר איים ובבני כוש ארץ שנער ואשור ובבני כנען הזכיר תחומי ארצם וכן בבני שם והיה זה כי מצרים ארץ מושבו ידוע כי היא נקראת על שמו והיו כל בניו יושבים סביבות מצרים ושם ארצם גם כן כשמם כי כן מצינו לפתרוסים ארץ פתרוס והיא מכלל ארץ מצרים כמו שכתוב (יחזקאל ל יג יד) ונתתי יראה בארץ מצרים והשמותי את פתרוס על ארץ מכורתם וכן לוד וכל הערב סביבות מצרים ושמם ושם ארצם שוה וכן פלשתים ארצם פלשת וכן כתוב (שמות טו יד) יושבי פלשת ואמר רבי אברהם כי אלה שמות מדינות ובכל מדינה ומדינה משפחה אחת ועל כן הם כלם לשון רבים והראיה הגמורה אשר יצאו משם כי זה רמז למקום וטעם אשר יצאו על דעת המפרשים שהולידם כלשון מחלציך יצאו (להלן לה יא) וכתב רש"י משניהם יצאו שהיו הפתרוסים וכסלוחים מחליפים נשותיהם זה לזה ויצאו פלשתים מביניהם בראשית רבה (לז ה) ועל דעתי בדרך הפשט היו כסלוחים יושבי עיר ששמה כן והיתה מכלל ארץ כפתור אשר שם כפתורים אחיהם ויצאו משם מן הכפתורים אשר הם מזרע כסלוחים והלכו לתור להם מנוחה והניחו הארץ לאחיהם וכבשו להם ארץ ששמה פלשת ונקראו אחר כך פלשתים על שם הארץ והוא מה שכתוב (דברים ב כב) כפתורים היוצאים מכפתור השמידום וישבו תחתם והם מבני כסלוחים יושבי ארץ כפתור
@250 **וכנען ילד את צדון בכורו** . אלה עשרה עממים בני כנען שנתנו לאברהם אבינו (להלן טו יט-כא) כי כל זרע כנען נמכר לעבד עולם והם שנתנו לו אבל נתחלף השם ברובם בימי אברהם כי בכאן נכתבו בשם שקראם אביהם ביום הולדם ואחרי שנפרדו בארצותם לגוייהם נקראו בשמות אחרים אולי העלו להם שם על שם הארץ כמו שפירשנו (בפסוק יג) וכן שעיר החורי (להלן לו כ) שם העיר שעיר וכן רבים או שהולידו הערקי והסיני משפחות ונכרתו מהם ובניהם היו קיני וקניזי על דרך משל והיו לראשי בתי אבות תקרא האומה בשמם כנהוג בשבטי ישראל והנה קראם בשם שהיה להם בימי אברהם במתנתו וראיה לדבר כי החוי הנזכר בכאן איננו נזכר במתנתו של אברהם והוא היה מהם שנאמר (דברים ז א) ונשל גוים רבים מפניך החתי והגרגשי והאמורי והכנעני והפריזי והחוי והיבוסי שבעה גוים וכן בכל מקום וימנה הכנעני עם בניו ולא ימנה בהן רק עשרה כי אחד מבניו לא גבר כאחיו ונקרא עם אחיו בשם אביו ויתכן שהיה צידון בכורו הנקרא "כנעני" עם אחד מאחיו שלא היה לגוי ואל יקשה עליך ארץ פלשתים שהיתה לאברהם כדכתיב (להלן כו ג) גור בארץ הזאת כי לך ולזרעך אתן את כל הארצות האל והם מבני מצרים כי הכתוב אמר לכנעני תחשב חמשת סרני פלשתים (יהושע יג ג) כי כבשו מקצת הארץ וישבו בה ובכאן תראה כי גבול הכנעני מצדון בואכה גררה עד עזה ואלה ערי פלשתים כי אבימלך מלך גרר ועזה לעזתי היא וכן לעזה אחד (שמואל א ו יז) וצידון לפלשתים דכתיב (יהושע יג ב ו) כל צידונים אנכי אורישם מפני בני ישראל רק הפילה בנחלה וכתוב (יואל ד ד) וגם מה אתם לי צור וצידון וכל גלילות פלשת ואולי שאר ארץ פלשתים לא היתה לישראל לבד אלו חמשת סרניהם ודע כי ארץ כנען לגבולותיה מאז היתה לגוי היא ראויה לישראל והיא חבל נחלתם כמו שנאמר (דברים לב ח) בהנחל עליון גוים בהפרידו בני אדם יצב גבולות עמים למספר בני ישראל אבל נתנה הקב"ה בעת הפלגה לכנען מפני היותו עבד לשמור אותה לישראל כאדם שמפקיד נכסי בן האדון לעבדו עד שיגדל ויזכה בנכסים וגם בעבד ועוד אבאר בעזרת האל יתעלה (דברים ב כג)
@256 **ולשם ילד גם הוא** . בעבור שאיחר תולדות שם וספר תולדות אחיו הקטן ממנו כאלו לא היה לו בנים אמר בכאן גם הוא וטעם אבי כל בני עבר שהוא אבי כל יושבי עבר הנהר שהוא מקום יחוס אברהם ולא יתכן שיהיה עבר במקום הזה שם האיש אבי פלג (כ"פ הרד"ק והראב"ע שמות כא ב) כי למה ייחס אותן אליו
@256 "אחי יפת הגדול" - דרך הכתוב ליחס הקטן אל הגדול באחיו ולא אל הנולד אחריו וכן מרים הנביאה אחות אהרן (שמות טו כ) וטעם להזכיר זה כלל לומר כי הוא אחי הנכבד שוה אליו בכבודו להגיד שלא איחר אותו מפני מעלת חם עליו והנראה אלי שיהיה "הגדול" תאר לשם לומר שהוא האח הגדול של יפת כי חם קטן מכלם ואם הקדים אותו וכן בכל מקום תאר למדובר בו כגון ישעיהו בן אמוץ הנביא (מלכים ב כ א) חנניה בן עזור הנביא (ירמיהו כח א) לחובב בן רעואל המדיני חותן משה (במדבר י כט) ורש"י כתב אחי יפת ולא אחי חם שאלו שניהם כבדו אביהם וזה בזהו גם זה לומר שהוא אחי הצדיק ולא אחי הרשע אף על פי שנמנה אחריו
@269 **בנסעם מקדם** . פירש רש"י שהיו יושבים שם ככתוב למעלה (י ל) ויהי מושבם ממשא באכה ספרה הר הקדם ונסעו משם לתור להם מקום המחזיק אותם ולא מצאו אלא שנער ואין זה נכון כי תולדות שם לבדן הם שנאמר עליהם כן ולמה ייחס הפלגה עליהם כי בני יפת ובני חם רבים מהם ועוד כי מושבם בארצותם היה ממשא עד הר הקדם והפלגה היתה טרם שהיה מושבם כי לא באו בני יפת מאיי הים אל הבקעה אשר בארץ שנער אבל בהפלגה הפיצם השם על פני כל הארץ ואז הושבו בארצותם לגוייהם ורבי אברהם פירש כי הרי אררט במזרח ויפה אמר כי הם במזרח קרובים לאשור שנאמר (מלכים ב יט לז) והמה נמלטו ארץ אררט ונח ברדתו מן ההר נתישב בארצות ההם הוא ותולדותיו וכאשר רבו נסעו משם אל הבקעה הזו ואנשי הפלגה על דברי רבותינו (סנהדרין קט) מורדים בבוראם ורודפי הפשט (הראב"ע והרד"ק) אומרים שלא היה דעתם אלא שיהיו יחד מחוברים כי הגיד הכתוב דעתם "פן נפוץ" ולא ספר עליהם ענין אחר ואם כדבריהם יהיו טפשים כי איך תהיה עיר אחת ומגדל אחד מספיק לכל בני העולם או שמא היו חושבים שלא יפרו ושלא ירבו וזרע רשעים יכרת אבל היודע פירוש שם יבין כוונתם ממה שאמרו ונעשה לנו שם וידע כמה השיעור שיזמו במגדל לעשותו ויבין כל הענין כי חשבו מחשבה רעה והעונש שבא עליהם להפרידם בלשונות ובארצות מדה כנגד מדה כי היו קוצצים בנטיעות והנה חטאם דומה לחטא אביהם ושמא בשביל זה דרשו (ב"ר לח ט) אשר בנו בני האדם אמר רבי ברכיה מה בני חמריא בני גמליא אלא בנוי דאדם קדמאה וכו' והסתכל כי בכל ענין המבול הזכיר "אלהים" ובכל ענין הפלגה הזכיר השם המיוחד כי המבול בעבור השחתת הארץ והפלגה בעבור שקצצו בנטיעות והנם ענושים בשמו הגדול וזה טעם הירידה וכן במדת סדום והמשכיל יבין "()" "סגירה"
@295 **על פני תרח אביו בארץ מולדתו** . כתב רש"י כדרך דברי רבותינו (בב"ר לח יג) תרח קבל על אברם בנו לפני נמרוד על שבירת צלמיו והשליכהו לכבשן והרן ישב ואמר אם אברם נוצח אני שלו ואם נמרוד נוצח אני שלו וכשניצל אברם אמרו לו משל מי אתה אמר להם משל אברם אני השליכוהו לכבשן ונשרף וזהו אור כשדים ומנחם פירש אור בקעה וכן על כן באורים כבדו ה' (ישעיהו כד טו) וכן מאורת צפעוני (שם יא ח) כל חור ובקע עמוק יקרא אור והענין שקבלו רבותינו בזה הוא האמת ואני מבאר אותו אברהם אבינו לא נולד בארץ כשדים כי אבותיו בני שם היו וכשדים וכל ארץ שנער ארצות בני חם והכתוב אמר ויגד לאברם העברי (להלן יד יג) לא הכשדי וכתיב (יהושע כד ב) בעבר הנהר ישבו אבותיכם מעולם תרח אבי אברהם ואבי נחור ומלת מעולם תורה כי משם תולדותיו מאז וכתיב (שם ג) ואקח את אביכם את אברהם מעבר הנהר וראיה לדבר כי נחור בחרן היה ואם היה מקום תרח אור כשדים בארץ שנער והכתוב ספר כי בצאתו מאור כשדים לא לקח אתו רק אברם בנו ולוט בן הרן בן בנו ושרי כלתו אם כן היה נחור נשאר בארץ כשדים אבל באמת ארץ מולדתם ארץ ארם היא בעבר הנהר והיא מנחלת אבותיו מעולם והכתוב אומר בבני שם (לעיל י ל) ויהי מושבם ממשא בואכה ספרה הר הקדם והוא שם כולל כדכתיב (שם לא) בארצותם לגוייהם וכתוב (במדבר כג ז) מן ארם ינחני בלק מלך מואב מהררי קדם והנה הוא ואבותיו מן הארץ ההיא מעולם ומצינו בתלמוד (ב"ב צא) כי אברהם נחבש בכותא וזאת העיר איננה בארץ כשדים דכתיב (מלכים ב יז כד) ויבא מלך אשור מבבל ומכותא ומעוה ומחמת וכתוב (שם ל) ואנשי בבל עשו את סכות בנות ואנשי כות עשו את נרגל אבל יראה כי היא עיר בעבר הנהר בארץ ארם נהרים כי חרן שם עיר בארץ ארם נהרים דכתיב (להלן כד י) וילך אל ארם נהרים אל עיר נחור שהיא חרן ועוד חקרנו וידענו על פי תלמידים רבים שהיו יושבי הארץ ההיא כי כותא עיר גדולה בין חרן ובין אשור רחוקה ממדינת בבל ובינה ובין חרן כמו ששה ימים אבל היא נכללת בעבר הנהר בעבור היותה בין ארם נהרים ובין נהר פרת גבול ארץ ישראל ובין חדקל ההולך קדמת אשור והנה תרח הוליד בניו הגדולים אברהם ונחור בעבר הנהר ארץ אבותיו והלך לו עם אברהם בנו אל ארץ כשדים ושם נולד לו בנו הקטן הרן ונשאר נחור בנו בעבר הנהר בעיר חרן או שנולד בעיר ההיא או שנתישב בה מכותא וזה טעם בארץ מולדתו באור כשדים כי שם מולדתו של הרן לבדו והענין המקובל הזה נמצא גם כן בספר קדמוני הגוים כמו שכתב הרב במורה הנבוכים (ג כט) כי הזכירו בספר "עבודת האכרים המצרים" כי אברם אשר נולד בכותא חלק על דעת ההמון שהיו עובדים השמש ונתן המלך אותו בבית הסוהר והיה עמהם בתוכחות ימים רבים שם אחר כך פחד המלך שישחית עליו ארצו ויסיר בני האדם מאמונתם וגרש אותו אל קצה ארץ כנען אחר שלקח כל הונו והנה על כל פנים במקום ההוא בארץ כשדים נעשה נס לאברהם אבינו או נס נסתר שנתן בלב אותו המלך להצילו ושלא ימיתנו והוציא אותו מבית הסוהר שילך לנפשו או נס מפורסם שהשליכו לכבשן האש וניצל כדברי רבותינו ואל יפתה אותך רבי אברהם בקושיותיו שאומר שלא ספר הכתוב זה הפלא כי עוד אתן לך טעם וראיה בזה ובכיוצא בו (להלן מו טו) אבל הגוים ההם לא הזכירו זה בספרם לפי שהם חולקים על דעתו והיו חושבים בנסו שהוא מעשה כשפים כענין משה רבינו עם המצרים בתחילת מעשיו ומפני זה לא הזכיר עוד הכתוב הנס הזה כי היה צריך להזכיר דברי החולקים עליו כאשר הזכיר דברי חרטומי מצרים ולא נתבארו דברי אברהם עמהם כאשר נתבארו דברי משה רבינו בסוף וזהו שאמר הכתוב (להלן טו ז) אני ה' אשר הוצאתיך מאור כשדים לתת לך את הארץ הזאת לרשתה כי מלת "הוצאתיך" תלמד על נס כי לא אמר "אשר לקחתיך מאור כשדים" אבל אמר "הוצאתיך" שהוציא ממסגר אסיר כמו אשר הוצאתיך מארץ מצרים (שמות כ ב) ואמר לתת לך את הארץ הזאת לרשתה כי מעת הוציאו אותו מאור כשדים היה הרצון לפניו יתעלה שיגדלנו ויתן לו את הארץ ההיא ותרח אביו ואברהם היה בלבם מן היום ההוא שנצל שילכו אל ארץ כנען להתרחק מארץ כשדים מפחד המלך כי חרן קרוב להם ועם אחד ושפה אחת לכלם כי לשון ארמית לשניהם ורצו ללכת אל עם אשר לא ישמע לשונו המלך ההוא ועמו וזהו טעם ויצאו אתם מאור כשדים ללכת ארצה כנען ויבאו עד חרן אשר שם משפחותיהם ואבותיהם מעולם וישבו ביניהם ונתעכבו שם ימים רבים ושם נצטוה אברהם לעשות מה שעלה בדעתו ללכת ארצה כנען ועזב את אביו ומת שם בחרן ארצו והוא הלך עם אשתו ולוט בן אחיו ארצה כנען וזהו שאמר הכתוב (יהושע כד ג) ואקח את אביכם את אברהם מעבר הנהר ואולך אותו בכל ארץ כנען כי בעבר הנהר נצטוה בזה ומשם לקחו והוליכו בכל ארץ כנען והנה על דעת רבותינו יהיה אור כשדים כפשוטו מלשון חמותי ראיתי אור (ישעיהו מד טז) ואמרו
@295 "ויצאו אתם מאור כשדים" - ותרח לא יצא מן הכבשן אבל אברם הוא עיקר או המקום נקרא כן בעבור הנס כמו ובתבערה ובמסה ובקברות התאוה (דברים ט כב) וזולתם וירמוז הכתוב כי בצאת אברם מן הכבשן ברחו להם כלם משם ופירוש באורים כבדו ה' (ישעיהו כד טו) על דעתי כדבריהם כי הם ההרים הגבוהים ששם עושים אורות ומשיאין משואות להודיע החדשות מהר במרחקים כאשר אמר (שם) באיי הים שם ה' אלהי ישראל והענין שיודיעו בכל העולם הנס והפלא הנעשה להם לכבוד השם וכן מאורת צפעוני (ישעיהו יא ח) החור שלו ששם אורו וחמימותו הגדול כמו שקורא אותו "שרף" וראיתי במדרש "קומי אורי" (פסקתא דר"כ פסקא כא) על כן באורים כבדו ה' במה מכבדין אותו ר' אבא בר כהנא אמר באילין פנסיא הן כגון העששיות שמדליקין בבתי כנסיות בכל מקום אפילו באיי הים לכבוד השם הרי שעושין "באורים" מלשון אש כפשוטו
@298 **ויצאו אתם מאור כשדים** . בעבור כי אברם נכבד מאביו וההולכים בעצתו ובעבורו ילכו אמר הכתוב ויצאו אתם ואף על פי שאמר "ויקח תרח" אבל לוט ושרי בעבור אברם הלכו אתם כי גם אחרי שנפרד אברם מאביו הלכו אתו
@299 **וימת תרח בחרן** . כשיצא אברם נשארו משנות תרח הרבה ולמה הקדים הכתוב מיתתו של תרח ליציאתו של אברם שלא יהא הדבר מפורסם לכל ויאמרו לא קיים אברם כבוד אב ואם שהניחו זקן והלך לו לפיכך קראו מת ועוד שאף הרשעים בחייהם קרואים מתים לשון רש"י ובבראשית רבה (לט ז) הוא ואני תמה על דבריהם שזה מנהג כל הכתוב לספר חיי האב והולידו הבן ומיתתו ואחר כך מתחיל בענין הבן בכל הדורות כך נהגו הכתובים ונח עצמו הנה בימיו של אברם עודנו חי ושם בנו כל ימי אברהם היה חי ויתכן שבאו למדרש הזה מפני ששינה הכתוב בתרח סדר הפרשה כולה כי בשם ותולדותיו כולם לא הזכיר הכתוב מיתה ולא חזר וכלל השנים ובכאן חזר ותפש הסדר הראשון שבבעלי השנים הרבים מאדם ועד נח וכלל ויהיו כל ימי תרח וימת והוסיף להזכיר עוד מקום המיתה שהיה בחרן המקום שהזכיר לאברהם ולכך דרשו שכל זה כדי שיראה מבלי עיון שהיה אברהם שם עמו ועוד כי מפני שכבר התחיל בענין אברהם וספר שיצא עם אביו מאור כשדים ללכת ארצה כנען יקשה בעיניהם כשלא סדר חייו ומיתתו על הסדר ויכתוב אותה בזמנה ואשר אמרו עוד (בב"ר שם) בתחילה אתה דורש שהרשעים בחייהם קרויין מתים גם כן תמה הוא בעיני שכבר דרשו (בב"ר לד ד) מפסוק ואתה תבוא אל אבותיך בשלום (להלן טו טו) בשרו שיש לאביו חלק לעולם הבא ואולי כוונתם שעשה תשובה בשעת מיתה אבל ימיו היו כלם ברשע והיה קרוי מת ולשון רש"י למדך שעשה תרח תשובה בשעת מיתה או שמא יש לו חלק לעולם הבא שאמרו חז"ל בזכות בנו והיא הבשורה שהוא לא היה יודע עד שנתבשר בכך בעת שאמר לו ואתה תבא אל אבותיך בשלום וכן מצאתי במדרש (לק"ט ויקרא ד ב) כל העצים כשרין חוץ -משל זית ושל גפן שהשמן והיין קרבין לגבי מזבח הצילו הפירות האילנות וכן מצינו באברהם שהציל את תרח שנאמר ואתה תבוא אל אבותיך בשלום חסלת פרשת נח
@300 **ויאמר ה' אל אברם לך לך** . להנאתך ולטובתך ושם אעשך לגוי גדול וכאן אי אתה זוכה לבנים לשון רש"י ואין צורך כי משפט הלשון כן הגשם חלף הלך לו (שיר השירים ב יא) אלכה לי אל הגדולים (ירמיהו ה ה) קומו ועברו לכם את נחל זרד (דברים ב יג) ורובם ככה אבל רבותינו (יומא ג עב) עשו מדרש במה שאמר הכתוב (דברים י א) ועשית לך ארון עץ ועשה לך שתי חצוצרות כסף (במדבר י ב) בעבור שאין המלאכה שלו והיה ראוי שיאמר כמו שאמר במשכן ואת המשכן תעשה (שמות כו א)
@300 "מארצך וממולדתך" - כתב רש"י והלא כבר יצא משם עם אביו ובא עד חרן אלא כך אמר לו הקב"ה התרחק עוד מבית אביך ורבי אברהם פירש וכבר אמר השם אל אברם לך לך מארצך כי הדבור הזה היה בעודנו באור כשדים ושם צוהו לעזוב ארצו ומולדתו ובית אביו אשר שם ואיננו נכון כי אם היה כן היה אברם עיקר הנסיעה מבית אביו במצות האלהים ותרח אביו ברצון נפשו הלך עמו והכתוב אמר (לעיל יא לא) ויקח תרח את אברם בנו יורה כי אברם אחרי אביו ובעצתו יצא מאור כשדים ללכת ארצה כנען ועוד כי הכתוב שאמר (יהושע כד ג) ואקח את אביכם את אברהם מעבר הנהר ואולך אותו בכל ארץ כנען היה ראוי שיאמר "ואקח את אביכם את אברהם מאור כשדים ואולך אותו בכל ארץ כנען" כי משם לוקח ושם נצטוה בזה ועוד יקשה עליהם כי אברהם בצוותו את אליעזר לקחת אשה לבנו אמר לו כי אל ארצי ואל מולדתי תלך (להלן כד ד) והוא הלך אל ארם נהרים אל עיר נחור (שם כד י) אם כן היא ארצו ומולדתו ושם נאמר (בפסוק לח) אם לא אל בית אבי תלך ואל משפחתי כי שם בית אביו ומשפחתו שהיא מולדתו לא כאשר השתבש רבי אברהם לומר אל ארצי חרן ומולדתי אור כשדים והנה הוא האומר כאן כי באור כשדים נאמר לו לך לך מארצך וממולדתך ומבית אביך והנה לו ארצות רבות אבל העיקר כבר ידעת אותו ממה שכתבנו בסדר שלפני זה (יא כח) כי חרן היא ארצו ושם מולדתו והיא ארץ אבותיו מעולם ושם נצטוה לעזוב אותם וכך אמרו בבראשית רבה (לט ח) לך לך אחת מארם נהרים ואחת מארם נחור וטעם להזכיר "ארצך ומולדתך ובית אביך" כי יקשה על האדם לעזוב ארצו אשר הוא יושב בה ושם אוהביו ורעיו וכל שכן כשהוא ארץ מולדתו ששם נולד וכל שכן כשיש שם כל בית אביו ולכך הוצרך לומר לו שיעזוב הכל לאהבתו של הקב"ה
@300 "אל הארץ אשר אראך" - היה נודד והולך מגוי אל גוי ומממלכה אל עם אחר עד שבא אל ארץ כנען ואמר לו לזרעך אתן את הארץ הזאת אז נתקיים "אל הארץ אשר אראך" ואז נתעכב וישב בה ומה שאמר ויצאו ללכת ארצה כנען לא להתישב בה כי עדיין לא ידע כי על הארץ ההיא נצטוה אלא שאחז צדיק דרכו דרך ארץ כנען כי כן היה בדעתו ובדעת אביו גם מתחלה בצאתם מאור כשדים ומפני זה אמר ויהי כאשר התעו אותי אלהים מבית אבי (להלן כ יג) כי היה תועה כשה אובד ויתכן לומר כי אברהם מבראשונה ידע כי ארץ כנען היא נחלת ה' ובה יתן ה' חלקו והאמין כי "אל הארץ אשר אראך" ירמוז לו על ארץ כנען או על כולה או על אחת מכל הארצות האל ושם פניו אל כלל ארץ כנען כי שם הארץ אשר יראנו באמת
@301 **והיה ברכה** . אתה תהיה הברכה אשר יתברכו בך לאמר "ישימך אלהים כאברהם" והוסיף עוד כי כל משפחות האדמה יתברכו בו לא אנשי ארצו בלבד או ונברכו בך שיהיו מבורכים בעבורו והנה זאת הפרשה לא בארה כל הענין כי מה טעם שיאמר לו הקב"ה עזוב ארצך ואיטיבה עמך טובה שלא היתה כמוהו בעולם מבלי שיקדים שהיה אברהם עובד אלהים או צדיק תמים או שיאמר טעם לעזיבת הארץ שיהיה בהליכתו אל ארץ אחרת קרבת אלהים ומנהג הכתוב לאמר התהלך לפני ותשמע בקולי ואיטיבה עמך כאשר בדוד ובשלמה וכענין התורה כולה אם בחוקותי תלכו (ויקרא כו ג) אם שמע תשמע בקול ה' אלהיך (דברים כח א) וביצחק אמר בעבור אברהם עבדי (להלן כו כד) אבל להבטיחו בעבור יציאת הארץ אין בו טעם אבל הטעם מפני שעשו אנשי אור כשדים עמו רעות רבות על אמונתו בהקב"ה והוא ברח מהם ללכת ארצה כנען ונתעכב בחרן אמר לו לעזוב גם אלו ולעשות כאשר חשב מתחלה שתהיה עבודתו לו וקריאת בני האדם לשם ה' בארץ הנבחרת ושם יגדל שמו ויתברכו בו הגוים ההם לא כאשר עשו עמו באור כשדים שהיו מבזין ומקללים אותו ושמו אותו בבור או בכבשן האש ואמר לו שיברך מברכיו ואם יחיד מקללו יואר וזה טעם הפרשה אבל התורה לא תרצה להאריך בדעות עובדי עבודה זרה ולפרש הענין שהיה בינו ובין הכשדים באמונה כאשר קצרה בענין דור אנוש וסברתם בעבודה זרה שחדשו
@305 **ויעבר אברם בארץ עד מקום שכם** . אומר לך כלל תבין אותו בכל הפרשיות הבאות בענין אברהם יצחק ויעקב והוא ענין גדול הזכירוהו רבותינו בדרך קצרה ואמרו (תנחומא ט) כל מה שאירע לאבות סימן לבנים ולכן יאריכו הכתובים בספור המסעות וחפירת הבארות ושאר המקרים ויחשוב החושב בהם כאלו הם דברים מיותרים אין בהם תועלת וכולם באים ללמד על העתיד כי כאשר יבוא המקרה לנביא משלשת האבות יתבונן ממנו הדבר הנגזר לבא לזרעו ודע כי כל גזירת עירין כאשר תצא מכח גזירה אל פועל דמיון תהיה הגזרה מתקיימת על כל פנים ולכן יעשו הנביאים מעשה בנבואות כמאמר ירמיהו שצוה לברוך והיה ככלותך לקרוא את דברי הספר הזה תקשור עליו אבן והשלכתו אל תוך פרת ואמרת ככה תשקע בבל וגו' (ירמיה נא סג סד) וכן ענין אלישע בהניחו זרועו על הקשת (מלכים ב יג טז-יז) ויאמר אלישע ירה ויור ויאמר חץ תשועה לה' וחץ תשועה בארם ונאמר שם (פסוק יט) ויקצוף עליו איש האלהים ויאמר להכות חמש או שש פעמים אז הכית את ארם עד כלה ועתה שלש פעמים תכה את ארם ולפיכך החזיק הקב"ה את אברהם בארץ ועשה לו דמיונות בכל העתיד להעשות בזרעו והבן זה ואני מתחיל לפרש הענינים בפרט בפסוקים בעזרת השם
@305 "ויעבור אברם בארץ עד מקום שכם" - היא עיר שכם כן זה שם המקום ההוא ושכם בן חמור על שם עירו נקרא וכתב רש"י נכנס לתוכה עד מקום שכם להתפלל על בני יעקב כשיבואו מן השדה עצבים ונכון הוא ואני מוסיף כי החזיק אברהם במקום ההוא תחלה וקודם שנתן לו את הארץ נרמז לו מזה כי בניו יכבשו המקום ההוא תחלה קודם היותם זוכים בו וקודם היות עון יושב הארץ שלם להגלותם משם ולכן אמר והכנעני אז בארץ וכאשר נתן לו הקב"ה הארץ במאמר אז נסע משם ונטע אהל בין בית אל ובין העי כי הוא המקום אשר כבש יהושע בתחלה ויתכן שהזכיר הכתוב והכנעני אז בארץ להורות על ענין הפרשה לומר כי אברם בא בארץ כנען ולא הראהו השם הארץ אשר יעדו ועבר עד מקום שכם והכנעני הגוי המר והנמהר אז בארץ ואברם ירא ממנו ולכן לא בנה מזבח לה' ובבואו במקום שכם באלון מורה נראה אליו השם ונתן לו הארץ וסרה יראתו כי כבר הובטח בארץ אשר אראך ואז בנה מזבח לה' לעבדו בפרהסיא
@305 "ואלון מורה" - זהו במקום שכם ונקרא גם כן "אלוני מורה" כמו שכתוב (דברים יא ל) מול הגלגל אצל אלוני מורה ושם הר גריזים והר עבל בשכם וקרוב לירדן שבאו שם בתחילת ביאתם בארץ אבל "אלוני ממרא" הוא מקום אשר הוא בארץ חברון רחוק מן הירדן ודע כי בכל מקום שיאמר הכתוב "אלוני ממרא" שם "ממרא" הוא על איש אמורי שהמקום ההוא שלו כמו שנאמר (להלן יד יג) והוא שוכן באלוני ממרא האמורי אחי אשכול ואחי ענר וכל "אלון מורה" ו"אלוני מורה" נקרא המקום ההוא על שם איש ששמו "מורה" אבל זה כנעני הוא מארץ הכנעני היושב בערבה וכשיזכיר הכתוב ממרא סתם הוא שם העיר כמו שנאמר (להלן לה כז) ויבא יעקב אל יצחק אביו ממרא קרית הארבע היא חברון על פני ממרא היא חברון (להלן כג יט) כי האיש אשר לו אלוני נקרא על שם העיר וכן שכם בן חמור כשם העיר שכם ובבראשית רבה (מב ח) על דעתיה דרבי יהודה אתרא הוא דשמיה ממרא ועל דעתיה דרבי נחמיה גברא הוא דשמיה ממרא
@306 **וטעם לה' הנראה אליו** . כי הודה לשם הנכבד וזבח לו זבח תודה על שנראה אליו כי עד הנה לא נראה אליו השם ולא נתודע אליו במראה ולא במחזה אבל נאמר לו "לך לך מארצך" בחלום הלילה או ברוח הקדש ויתכן שירמוז "הנראה אליו" על סוד הקרבן (עיין רקאנטי כא ב) והמשכיל יבין
@307 **ויקרא בשם ה'** . פירש אונקלוס שהתפלל שם כמו קראתי שמך ה' מבור תחתיות (איכה ג נה) והנכון שהיה קורא בקול גדול שם לפני המזבח את שם ה' מודיע אותו ואלהותו לבני אדם כי באור כשדים היה מלמדם ולא אבו שמוע ועתה כשבא בארץ הזאת שהובטח בה "ואברכה מברכיך" היה למוד ללמד ולפרסם האלהות וכן אמר הכתוב (להלן כו כד) ביצחק כאשר הלך אל נחל גרר והובטח אל תירא כי אתך אנכי שבנה מזבח "ויקרא בשם ה'" כי בא במקום חדש אשר לא שמעו את שמעו ולא ראו את כבודו והגיד כבודו בגוים ההם ולא נאמר ביעקב כן מפני שהוליד בנים רבים כלם עובדי ה' והיתה לו קהלה גדולה נקראת עדת ישראל ונתפרסמה האמונה בהם ונודעה לכל עם וגם כי מימי אבותיו נתפרסמה בכל ארץ כנען וכך אמרו בבראשית רבה (לט טז) מלמד שהקריא שמו של הקב"ה בפי כל בריה
@308 **הנגבה** . כתב רבינו שלמה ללכת לדרומה של ארץ ישראל והוא בחלק של בני יהודה שנטלו בדרומה של ארץ ישראל וכן לעתיד לבא בבניו שנאמר (שופטים א ב) יהודה יעלה בתחלה
@309 **ויהי רעב בארץ** . הנה אברהם ירד למצרים מפני הרעב לגור שם להחיות נפשו בימי הבצורת והמצרים עשקו אותו חנם לקחת את אשתו והקב"ה נקם נקמתם בנגעים גדולים והוציאו משם במקנה בכסף ובזהב וגם צוה עליו פרעה אנשים לשלחם ורמז אליו כי בניו ירדו מצרים מפני הרעב לגור שם בארץ והמצרים ירעו להם ויקחו מהם הנשים כאשר אמר (שמות א כב) וכל הבת תחיון והקב"ה ינקום נקמתם בנגעים גדולים עד שיוציאם בכסף וזהב וצאן ובקר מקנה כבד מאד והחזיקו בהם לשלחם מן הארץ לא נפל דבר מכל מאורע האב שלא יהיה בבנים והענין הזה פרשוהו בבראשית רבה (ח ו) רבי פנחס בשם רבי אושעיא אמר אמר הקב"ה לאברהם צא וכבוש את הדרך לפני בניך ואתה מוצא כל מה שכתוב באברהם כתוב בבניו באברהם כתוב ויהי רעב בארץ בישראל כתיב (להלן מה ו) כי זה שנתים הרעב בקרב הארץ ודע כי אברהם אבינו חטא חטא גדול בשגגה שהביא אשתו הצדקת במכשול עון מפני פחדו פן יהרגוהו והיה לו לבטוח בשם שיציל אותו ואת אשתו ואת כל אשר לו כי יש באלהים כח לעזור ולהציל גם יציאתו מן הארץ שנצטווה עליה בתחילה מפני הרעב עון אשר חטא כי האלהים ברעב יפדנו ממות ועל המעשה הזה נגזר על זרעו הגלות בארץ מצרים ביד פרעה במקום המשפט שמה הרשע והחטא
@310 **הנה נא ידעתי וגו' אמרי נא אחותי את** . לא ידעתי למה פחד ממנה עתה יותר מקודם לכן ואם נאמר שהיו המצרים שחורים ומכוערים כדברי רש"י הנה גם לאבימלך מלך פלשתים אמר כן גם הוא גם יצחק שהיה דר בארץ ההיא במצות ה' אולי היו הכנענים בדור ההוא שטופים בעבודה זרה וגדורים מן העריות יותר מאנשי מצרים והפלשתים ואיננו נכון ויתכן כי לא היה להם פחד רק בבואם בעיר מושב המלכים כי היה דרכם להביא למלך האשה היפה מאד ולהרוג את בעלה בעלילה שישימו עליו והנכון בעיני כי זה דרכם למו מעת צאתם מחרן בכל מקום היה אומר "אחותי היא" כי כן אמר (להלן כ יג) ויהי כאשר התעו אותי אלהים מבית אבי אבל הכתוב יזכיר זה במקומות אשר יתחדש להם ענין בדבר והנה זרז אותה עתה כאשר צוה לה מתחילה ויצחק לא פחד בארצו ובעירו רק בבואו אל ארץ פלשתים אחז דרך אביו ואמר למען יטב לי בעבורך וחיתה נפשי בגללך כל ימי היותנו גרים בארץ הזאת עד עבור הרעב כי אברהם מפני הרעב בא לגור בארץ וכעבור הרעב ישוב לארץ אשר נצטוה עליה ונתנה השם לו ולזרעו והיה חושב שיחיו נפשם ברעב ויבא להם ריוח והצלה מאת האלהים לשוב או שיתכן להם לברוח לארץ כנען בהתיאשם ממנה וכתב רש"י הנה נא ידעתי מדרש אגדה עד עכשיו לא הכיר בה מתוך צניעותה ועכשיו על ידי מעשה דבר אחר שעל ידי הדרך אדם מתבזה וזו עמדה ביופיה ולפי פשוטו הנה נא הגיע השעה שיש לדאוג על יופייך וידעתי זה כמה ימים כי יפת מראה את ועכשיו אנו באים בין בני אדם שחורים אחיהם של כושים ולא הורגלו באשה יפה ודומה לו הנה נא אדני סורו נא כל זה לשון הרב והמדרש קבלה בענוה שבהם ונסמך למקרא אבל אין צורך לכל הדברים האלה שאין מלת "נא" מורה על דבר שיתחדש בעת ההיא בלבד אבל על כל דבר הווה ועומד יאמרו כן כי הוא רומז על הענין לומר שהוא עתה ככה הנה נא ידעתי כי אשה יפת מראה את מאז ועד עתה וכן הנה נא עצרני ה' מלדת (להלן טז ב) מנעורי ועד היום הזה וכן הנה נא לי שתי בנות (להלן יט ח) כי לא נולדו עתה וכולם ככה ויראה מפשט הכתובים כי שרה לא קבלה עליה לאמר כן אבל המצרים היו רעים וחטאים מאד וכאשר ראו אותה ויהללו אותה אל פרעה לוקחה אל ביתו ולא שאלו בהם כלל אם אשתו היא או אם אחותו היא והיא שתקה ולא הגידה כי אשתו ואברהם ספר מעצמו כי אחותו היא ולכך הטיבו לו בעבורה וזהו שאמר הכתוב מה זאת עשית לי למה לא הגדת לי כי אשתך היא (להלן פסוק יח) האשים אותו כי בראותו שיקחו אותה היה לו להגיד לפרעה כי אשתו היא וחזר והאשים אותו על אמרו אחרי כן לשרים ולבית פרעה כי אחותו היא ולא האשים את האשה כלל כי אין ראוי שתכחיש היא את בעלה והראוי לה שתשתוק
@311 ראו רמב"ן על בראשית יב יא
@312 ראו רמב"ן על בראשית יב יא
@314 **וטעם ויראו אותה שרי פרעה** . כי כאשר ראו אותה המצרים אמרו ראויה זאת לשרים הגדולים והנה הביאוה אליהם וגם הם יראו לנפשם מנגוע בה כי מפני היופי הגדול ידעו כי המלך יחפוץ בה מאד ויהללו אותה ביניהם לומר ראויה היא למלך לשון רש"י וזה דעת אונקלוס שאמר ושבחו יתה לות פרעה או שהללוה אל המלך עצמו ושלח ולקחה
@316 **וטעם על דבר שרי אשת אברם** . כי בעבור החמס שעשה לשרה גם לאברהם ובזכות שניהם באו עליו הנגעים הגדולים ההם
@317 **ויקרא פרעה לאברם** . יתכן כי בבוא הנגעים פתאום עליו ועל ביתו בעת אשר לוקחה שרה אל ביתו הרהר בדעתו לאמר מה זאת עשה אלהים לנו ושאל אותה והגידה כי היא אשתו ולכן קרא לאברהם והאשים אותואו כאשר אמרו רבותינו (ב"ר מא ב) שלקה בראתן שהמשגל קשה לו וחשש כי שמא אשתו היא ואמר לו בספק מה זאת עשית לי להוציא מפיו האמת כי אם היתה אחותו היה אומר אמנם אחותי היא ואמר ועתה הנה אשתך קח ולך לראות מה ידבר ומה ישיב על תוכחתו ואברהם שתק ממנו ולא השיב אותו דבר מרוב פחדו אז הבין פרעה כי היא אשתו כאשר חשב וצוה עליו פרעה אנשים לשלחם
@318 **וטעם ואקח אותה לי לאשה** . שהיה רצונו שתהיה זאת אשתו המולכת לא תהיה פלגש לו והזכיר זה בעבור שיודה לו אם היא אחותו כאשר פירשתי
@320 **וטעם הוא ואשתו וכל אשר לו** . להודיע שלא גזלו ממנו דבר מכל המתנות הגדולות שנתנו לו בעבור שרה שתהיה למלך ולא אמרו רמיתנו ומתנה בטעות היא וזה מעשה נס
@326 **ויהי ריב** . כתב רש"י לפי שהיו רועיו של לוט מרעין בהמתם בשדות אחרים והיו רועיו של אברם מוכיחין אותם על הגזל והם אומרים נתנה הארץ לאברם ולו אין יורש ולוט יורשו ואין זה גזל והכתוב אמר והכנעני והפריזי אז יושב בארץ ולא זכה בה עדיין אברם ומדרש רבותינו הוא (ב"ר מא ה) ואני תמה כי המתנה שנאמרה לאברם לזרעו היתה שנאמר למעלה (יב ז) לזרעך אתן את הארץ הזאת והיאך יירשנו לוט אולי שמעו הרועים המתנה וטעו והכתוב אומר כי גם ללוט גם לאברם איננה עתה ולפי זה מה שאמר תחילה כי היה רכושם רב לאמר כי מפני הרכוש הרב לא ישא אותם הארץ והוצרכו רועי לוט להכניס מקניהם בשדות שיש להם בעלים וזאת סבת המריבה ועל דרך הפשט היתה המריבה על המרעה כי לא נשא אותם הארץ וכאשר היה מקנה אברם רועה באחו היו רועי לוט באים בגבולם ורועים שם והנה אברם ולוט היו גרים ותושבים בארץ ופחד אברם פן ישמע הכנעני והפריזי יושב הארץ כובד מקניהם ויגרשום או יכו אותם לפי חרב ויקחו להם מקניהם ורכושם כי ישיבת הארץ עתה להם לא לאברם וזה טעם והכנעני והפריזי כי הזכיר שהיו עמים רבים יושבים בארץ ההיא ולהם ולמקניהם אין מספר ולא ישא אותם הארץ ואת אברם ולוט וממלת אז יראה לי כי העמים היו בארץ בימים ההם יושבי אהל ומקנה נאספים מקצתם אל עיר אחת ורועים שם שנה או שנתים ונוסעים משם אל גבול אחר אשר לא רעו אותו וכן יעשו תמיד כמנהג בני קדר והכנעני והפריזי היו אז בארץ הנגב ובשנה האחרת יבואו שם היבוסי והאמורי
@329 **כגן ה' כארץ מצרים** . יאמר כי ארץ הככר כולה משקים אותה ברגל מן הירדן כדרך הנעשה בגן ה' שנאמר בו (לעיל ב י) ונהר יוצא מעדן להשקות את הגן וכדרך שהיא בארץ מצרים שנאמר בה (דברים יא י) והשקית ברגלך כגן הירק והזכיר שני המקומות אמר "כגן ה'" שהמקום הטוב בתחתונים כן הוא כולו משקה והזכיר "כארץ מצרים" מקום ידוע לרעיה ורבותינו אמרו (ספרי עקב לח) כגן ה' לאילנות כארץ מצרים לזרעים ירצו לפרש שיש בככר נהרות גדולים ישקו אילני הגנות כגן ה' ובו יאורים כארץ מצרים ישקו גן הירק ובחר לו לוט בזה כי הארץ שישקו אותה כן רחוקה מן הבצורת וטובה למרעה
@331 **וטעם אברם ישב בארץ כנען** . בשאר ארץ כנען כולה שלא יעמוד במקום אחד אבל בכל ארץ כנען יגור ולוט נתישב במקום אחד ממנה בערי הככר כי ערי הככר מכלל ארץ כנען וטעם בערי הככר פעם בזו ופעם בזו מפני כובד המקנה וזה טעם ויבחר לו לוט את כל ככר הירדן כי התנה עם אברם שלא יבא בכל הככר
@332 **וטעם ואנשי סדום רעים וחטאים** . יאשים הכתוב את לוט שלא נמנע מלשכון עמהם כדברי רש"י וידבר עוד בזכות הצדיק שלא נפל חבלו במקום אשר שמה הרשע כי לא ינוח שבט הרשע על גורל הצדיקים וכל ערי הככר רעים וחטאים לה' מאד כי על כן נהפכו אף על פי שכל בני כנען אנשי תועבות גדולות כי כן כתוב (ויקרא יח כז)
@336 **קום התהלך בארץ לארכה ולרחבה** . יתכן שזה רשות כרצונו אמר לו בכל אשר תרצה ללכת בארץ לך כי אהיה עמך ושמרתיך מרעת הגוים כי לך אתננה כלומר שלך תהיה ואם היא מצוה שילך בה כל ארכה ורחבה להחזיק במתנתו כאשר פירשתי (לעיל יב ו) לא נצטווה לעשות זה מיד והנה עשה כן כי עתה היה במזרח ואחר כן הלך אל ארץ פלשתים שהוא במערב והנה קיים המצוה בחייו וטעם לך ולזרעך שתחזיק במתנה מעכשיו להנחילה לזרעך כמו שאמרו רבותינו (ב"ב קיט) ירושה היא להם מאבותיהם ועל דרך הפשט יתכן שיהיה מושל עליה ונשיא אלהים בתוכה בכל מקום שילך בארץ ההיא
@338 **ויהי בימי אמרפל מלך שנער** . המעשה הזה אירע לאברהם להורות כי ארבע מלכיות תעמודנה למשול בעולם ובסוף יתגברו בניו עליהם ויפלו כלם בידם וישיבו כל שבותם ורכושם והיה הראשון מהם מלך בבל כי כן העתיד כדכתיב (דניאל ב לח) אנת הוא רישא די דהבא ואולי "אלסר" שם עיר במדי או בפרס ו "עילם" בעיר ההיא המלך מלך יון הוא המלך הראשון ומשם נתפשט מלכותו כשנצח דריוש וכבר הזכירו זה רבותינו (ע"ז י) רבי יוסי אומר שש שנים מלכו בעילם ואחר כך נתפשטה מלכותם בכל העולם כולו ו"מלך גוים" המלך על עמים שונים אשר שמוהו עליהם לראש ולקצין רמז למלך רומי אשר המלך על עיר מקובצת מעמים רבים כיתים ואדום ויתר גוים וכך אמרו בבראשית רבה (מב ב) אמר רבי אבין כשם שפתח בארבע מלכיות כך אינו חותם אלא בארבע מלכיות וכו' ושם עוד (מב ד בשינוי לשון) ויהי בימי אמרפל מלך שנער זו בבל אריוך מלך אלסר זו מדי כדרלעומר מלך עילם זו יון ותדעל מלך גוים זו מלכות אדום שהיא מכתבת טירוניא מכל אומות העולם
@339 **וטעם ומלך בלע** . מפני שמלך על עיר קטנה ואנשים בה מעט ולא שם לו על פני חוץ
@343 **איל פארן** . כתרגומו מישר פארן ואני אומר שאין איל לשון מישור אלא מישור של פארן איל שמו ושל ממרא אלוני שמו ושל ירדן ככר שמו ושל שטים אבל שמו וכולם מתורגמין מישרא וכל אחד שמו עליו לשון רש"י ואלו היה כן היה אונקלוס מתרגם בשמם "אילא דפארן" "אלוני דממרא" כמנהגו בשמות ומי הגיד לו במקומות הרבים ההם המישור הם כולם או הרים הגבוהים ו"ממרא" שם האיש האמורי אחי אשכול ואחי ענר בעלי ברית אברם והמקום ההוא שלו כמו שאמר (להלן פסוק יג) אלוני ממרא האמורי כאשר פרשתי (לעיל יב ו) אבל "איל פארן" מקום אילים כי יבשו מאילים אשר חמדתם (ישעיהו א כט) ו"אלוני" מקום אלונים כאלה וכאלון (שם ו יג) אלונים מבשן (יחזקאל כז ו) והנהוג בהם להיותם נטועים במישור לפני המדינות להיות לעיר כמו מגרש וכן תרגום "אלון בכות" (להלן לה ח) "מישור בכותא" ושם איננו שם העצם למקום רק הוא שם לאלון הנטוע שם כמו שמפורש (שם) תחת האלון אלא שהוא רודף הענין לא המלות והתרגום הירושלמי אמר ב"איל פארן" ו"אלוני ממרא" "מישרא" כדברי אונקלוס ואמר ב"אלון בכות" "בלוט בכותא" כי "אלון בכות" אצלו שם לאילן לא למקום ואונקלוס סבר שהוא שם למקום כי היו בו אלונים רבים כמו "אלוני ממרא" ולכך אמר "האלון" והנה כולם שמות תאר אבל "ככר הירדן" לשון מישור ממש הוא כי כן יקרא בלשון הקודש המקום שהנהרות מתפשטין בהם במרוצת המים הנגרים השוטפים שם ולכן אמר (להלן יט יז) ואל תעמוד בכל הככר ההרה המלט וכן כר נרחב (ישעיהו ל כג) לבשו כרים הצאן ועמקים יעטפו בר (תהלים סה יד) פעמים יכפלו המלה ופעמים יסירו הכפל כמו בת עין (שם יז ח) וזולתם רבים ויקראו גם כן השלוחים המהירים בשם הזה לכרי ולרצים (מלכים ב יא ד) שרי המאות ואת הכרי (שם יט) וכן בכרכרות (ישעיהו סו כ) שם לגמלים המריצין שהזכירום בתלמוד (מכות ה) "גמלא פרחא" וממנו "מכרכר" כפולים ואבל השטים (במדבר לג מט) וכן "אבל מחולה" (שופטים ז כב) תרגמו אותו "מישר" הוא המקום הנחרב אין בו נטע ולא בנין כי הלשון אצלם לשון חרבה ושממה כמו ויאבל חיל וחומה (איכה ב ח) אבל תירוש אומללה גפן (ישעיהו כד ז)
@344 **אל עין משפט** . על שם העתיד שעתידים משה ואהרן להשפט שם על עסקי אותו העין לשון רש"י מדברי אגדה (במד"ר יט יד) ולא הבינותי זה כי "קדש" זה הוא "קדש ברנע" כי הוא ב"איל פארן אשר על המדבר" וממנו נשתלחו מרגלים בשנה שניה שנאמר (במדבר יג כו) אל מדבר פארן קדשה וכתוב (דברים א יט כב) ונבא עד קדש ברנע ותאמרו נשלחה אנשים לפנינו ושם ישבו ישראל ימים רבים אבל "קדש" ששם משפט הצדיקים הוא במדבר צין שבאו שם בשנת הארבעים שנאמר (במדבר כ א) ויבאו בני ישראל כל העדה מדבר צין בחדש הראשון וישב העם בקדש וגמר הפרשה אולי המדרש על השם בלבד הוא רמז הכתוב כי השם הזה "קדש" הוא יהיה עין משפט ואונקלוס אמר "מישר פילוג דינא" ולא ידעתי מהו אולי הוא מלשון פלגים יבלי מים (ישעיהו ל כה) מי פלג לשטף תעלה (איוב לח כה) וכן בלשון חכמים (אסתר רבה ה) "פלגו של ים" יאמר כי במישור ההוא מעין המשפט ועומק הדין כי היה מישור נאה מעותד למלכים שם ישבו לשפוט את כל הגוים בארצות ההם
@344 "שדה העמלקי" - לשון רש"י עדיין לא נולד עמלק ונקרא על שם העתיד ולא ידעתי אם רצונו לומר כי משה רבינו קרא המקום בשם שהוא נקרא בימיו ואם כן אין בכאן דבר עתיד או מה העתיד הזאת שיתנבאו הגוים לקרוא המקום כן ולשון בראשית רבה (מב ז) עדיין לא נולד עמלק ואת אמרת את כל שדה העמלקי אלא מגיד מראשית אחרית וזה דרך הדרש להם במקומות רבים גם בנהרות גן עדן אמרו (ב"ר טז ב) כלשון הזה וכוונתם לומר כי מעת צאת הנהרות נאמר כי הנהר הולך קדמת ארץ העתידה להיות לאשור והנכון בעיני בשדה העמלקי כי היה בימים הקדמונים אדם נכבד מבני החורי יושב הארץ ומשל על המקום ההוא ושמו עמלק ואליפז בכור עשו קרא שם בנו על שם האיש ההוא ואולי ממשפחת תמנע אמו היה ומשל גם במקום ההוא והיה שם אלוף עליהם
@347 **בארת בארת חמר** . בארות הרבה היו שם שנוטלין משם אדמה לטיט הבנין ומדרש אגדה שהיה הטיט מוגבל בהן ונעשה נס למלך סדום שיצא משם לפי שהיו באומות מקצתן שלא היו מאמינים באברם שנצל מכבשן האש וכיון שיצא זה מן החמר האמינו באברם למפרע לשון רש"י ואין ספק כי פירוש בארות חמר בארות אשר בהם רפש וטיט כענין שכתוב (ירמיהו לח ו) ובבור אין מים כי אם טיט ויטבע ירמיהו בטיט וכתוב (תהלים מ ג) ויעלני מבור שאון מטיט היון ויתכן שיצא משם כראוי בלא נס ואני תמה במדרש ההגדה הזה כי האומות שלא היו מאמינים שעשה הקב"ה נס לאברהם בראותם נסו של מלך סדום לא יוסיפו אמונה בהקב"ה כי מלך סדום עובד עבודה זרה היה והנה נסו או יחזק ידי עובדי עבודה זרה או שיאמינו בכל הנסים שיהיו בכשפים או מקרה באפשרות רחוקה ונסו יתן ספק בלב המאמינים בנסו של אברהם ואולי יפרשו ויצא מלך סדום לקראתו שיצא מן הבור כשעבר אברהם עליו כי נעשה לו נס לכבוד אברהם שיצא לקראתו לכבודו ולברכו ואפשר כי אברהם בשובו הביט בבור ההוא כי חפץ להציל המלכים ולהשיב להם רכושם והנה נעשה הנס על ידו ואם נעשה למלך סדום נס לכבוד אברהם כל שכן שיש להאמין שיעשה נס לאברהם להציל ממות נפשו ונאמר כי מלך עמורה כבר מת כאשר עבר אברהם עליו או שנפל בבור אחר כי שמה רמז לעמק
@352 **ויחלק עליהם לילה** . כתב רש"י לפי פשוטו כדרך הרודפים שמתפלגים אחר בורחיהם כשבורחין זה לכאן וזה לכאן לילה כלומר לאחר שחשכה לא נמנע מלרדפם והנכון כי רדף אותם ביום עד דן עם כל מחנהו וכאשר חשך עליהם הלילה ולא היה רואה אי זה דרך אשר יברחו בה חלק עמו ועבדיו לשנים או שלשה ראשים ולקח החלק האחד עמו ורדפו אחריהם בכל הדרכים והכום עד חובה אשר משמאל לדמשק וחזר מלרדוף אחריהם ושיעורו ויחלק עליהם הוא ועבדיו לילה
@352 "וירדפם עד חובה אשר משמאל לדמשק" - ידוע כי מרחק רב מן אלוני ממרא אשר בחברון בארץ יהודה לדמשק אשר הוא חוצה לארץ אם כן רדף אחריהם ימים רבים עד הוציאו אותם מן הארץ כי הם אל בבל ארצם היו חוזרים או שהיה נס גדול כאשר דרשו רבותינו (ב"ר מג ג) בארח ברגליו לא יבא (ישעיהו מא ג)
@355 **ומלכי צדק מלך שלם** . היא ירושלים כענין שנאמר (תהלים עו ג) ויהי בשלם סוכו ומלכה יקרא גם בימי יהושע "אדני צדק" (יהושע י א) כי מאז ידעו הגוים כי המקום ההוא מבחר המקומות באמצע הישוב או שידעו מעלתו בקבלה שהוא מכוון כנגד בית המקדש של מעלה ששם שכינתו של הקב"ה שנקרא "צדק" ובבראשית רבה (מג ו) המקום הזה מצדיק את יושביו ומלכי צדק אדוני צדק נקראת ירושלם צדק שנאמר (ישעיהו א כא) צדק ילין בה והזכיר והוא כהן לאל עליון להודיע כי אברהם לא היה נותן מעשר לכהן לאלהים אחרים אבל מפני שידע בו שהוא כהן לאל עליון נתן לו המעשר לכבוד השם והרמז לאברהם מזה כי שם יהיה בית אלהים ושם יוציא זרעו המעשר והתרומה ושם יברכו את ה' ועל דעת רבותינו (נדרים לב) שאומרים כי מלכי צדק הוא שם בן נח הלך מארצו לירושלם לעבוד שם את ה' והיה להם לכהן לאל עליון כי הוא אחי אביהם הנכבד כי ירושלים מגבול הכנעני היא מעולם ורש"י כתב למעלה (יב ו) והכנעני אז בארץ היה הולך וכובש את ארץ ישראל מזרעו של שם זקנו של אברהם שבחלקו של שם נפלה כשחלק נח לבניו את הארץ (ספרא קכו) שנאמר ומלכי צדק מלך שלם ואין זה נכון כי "גבול הכנעני מצידון" (לעיל י יט) יכלול כל ארץ ישראל וגבול בני שם במזרח ממשא רחוק מארץ ישראל אבל אם חלק נח לבניו הארצות ונתן לשם ארץ ישראל היה זה כ"מחלק נכסיו על פיו" וישבו בה בני כנען עד אשר ינחיל אותה השם לזרע אוהבו כאשר הזכרתי כבר (לעיל י טו)
@355 "והוא כהן לאל עליון" - בעבור היות בכל העמים כהנים משרתים למלאכים הנקראים "אלים" כענין שנאמר (שמות טו יא) מי כמוכה באלים יקרא הקב"ה "אל עליון" וענינו התקיף הגבוה על כל גבוהים כמו יש לאל ידי (להלן לא כט) ומלכי צדק לא הזכיר השם אבל אברהם אמר ה' אל עליון (להלן פסוק כב)
@356 **קונה שמים וארץ** . כתב רש"י קונה כמו עושה על ידי עשייתו קנאן להיות לו ואלה שני פנים הם ואולי כן הדבר שיבא לשון קנין בענין העשייה וכן כי אתה קנית כליותי (תהלים קלט יג) שיכפול תסוכני בבטן אמי וכן הלא הוא אביך קנך הוא עשך ויכוננך (דברים לב ו) כי הלשון יאמר "קנין" בעשייה וההפך אשר עשו בחרן (לעיל יב ה) קנו ומאשר לאבינו עשה (להלן לא א) והנכון מה שאמר עוד קנאן להיות לו כי כל אשר לאדם יקרא קנינו ויקראו הצאן "מקנה" בעבור היותו עיקר רכוש האדם ולשון חכמים (ב"מ י) המגביה מציאה לחבירו קנה חבירו הבטה בהפקר קניא (שם קיח) חצרו של אדם קונה לו שלא מדעתו (שם יא) וכן בכל מקום תבוא להם במקום זכיה כלומר שהוא שלו ולזה נתכוין אונקלוס שתרגם דקניניה ולא אמר "קנה"
@357 **ויתן לו מעשר מכל** . אברהם לא רצה לקחת לעצמו מחוט ועד שרוך נעל אבל חלק הגבוה הפריש לתתו לכהן ומלך סדום יצא לקראת אברהם אל עמק שוה לכבדו והלך עמו עד שלם שהוציא מלכי צדק לחם ויין לעם אשר ברגליו ולא בקש מלך סדום ממנו דבר אבל כאשר ראה נדיבת לבו וצדקתו שנתן המעשר אז בקש גם הוא הנפש בדרך צדקה ואברהם בטח באלהיו שיתן לו עושר ונכסים וכבוד ולא רצה לקחת ממנו דבר והשיב לו כל רכוש סדום שהוא שלו וכל רכוש עמורה להשיב אותו לבעליו כי בכל בקש ממנו הנפש ובכל היתה טענתו שלא יאמרו הם העשירו את אברם ושאר המקומות הנזכרים לפי חרב הכו אותם ולא לקחו מערי המלכים רק רכוש סדום ועמורה כי בעבור שאבדו מלכיהם נשארו עזובות עריהם ויתכן שיהיה זה מה שאמר "אם מחוט ועד שרוך" ישאר בידי מכל הרכוש הבא אלי מכולכם "ואם אקח מכל אשר לך" ברכושך שנתת אתה לי
@359 **וטעם הרימותי ידי אל ה'** . לשון שבועה מרים אני ידי לאל עליון וכן בי נשבעתי (להלן כב טז) נשבע אני לשון רש"י וכן מצאתי בספרי (ואתחנן לג) מצינו בכל הצדיקים שמשביעין את יצרן שלא לעשות באברהם הוא אומר הרימותי ידי אל ה' והנה הוא כלשון וירם ימינו ושמאלו אל השמים וישבע בחי העולם (דניאל יב ז) ואונקלוס אמר ארימית ידי בצלו קדם ה' יאמר התפללתי אל ה' וכפי פרושות השמים אם אקח מכל אשר לך כלומר כה יעשה לי אלהים וכה יוסיף אם אקח והנכון בעיני כי אמר הרימותי ידי אל ה' להיות הקדש וחרם לפניו אם אקח מכל אשר לך כי ההקדשות יקראו כן "תרומת יד" כלשון כל מרים תרומת כסף ונחשת (שמות לה כד) וכל איש אשר הניף תנופת זהב לה' (שם כב) ואמר כן בעבור שנתן ממנו מעשר כי כל אשר יקח מכל אשר לו יהיה תרומה לה' לא יהנה ממנו דבר ובבראשית רבה (מג ט) עשאן תרומה כמה דאת אמר (במדבר יח כו) והרמותם ממנו תרומת ה'
@362 **היה דבר ה' אל אברם במחזה** . זכה עתה אברהם להיות לו דבר ה' במחזה ביום כי מתחילה היתה נבואתו במראות הלילה וטעם היה דבר ה' אל אברם במחזה כטעם וכל העם רואים את הקולות (שמות כ יח) וסודם ליודעי חן
@362 "אל תירא אברם" - היה מתירא משני דברים מן המלכים פן ירבו צבאותם עליו הם או העומדים תחתם ובמלחמה ירד ונספה או יומו יבא למות בלא זרע והבטיחו כי הוא יהיה מגן בעדו מהם ועוד יהיה שכר לכתו עם ה' הרבה מאד
@363 **ויאמר אברם ה' אלהים מה תתן לי** . הנה הצלתני מן המלכים אבל מן הכרת לא הבטחת אותי רק אמרת שתרבה לי שכר הרבה ומה יהיה שכרי בלא בנים והנה לא עלה בדעתו שיהיה השכר הגדול הזה עולם הבא כי זה אין צורך להבטחה כי כל עובד אלהים ימצא חיים לפניו אך בעולם הזה יש צדיקים שמגיע עליהם כמעשה הרשעים על כן צריכים בטחון ועוד כי הרבה מאד לאמר שיזכה לשתי שולחנות בכל הטוב הראוי לצדיקים הגמורים מאין עונש כלל ועוד כי ההבטחה למה שהיה מתירא ממנו וחזר ופירש לו הבטחתו שלא יפחד גם מזה כי ישים זרעו ככוכבי השמים לרוב ויש עליך לשאול שכבר נאמר לו לאברהם (לעיל יג טו) כי את כל הארץ אשר אתה רואה לך אתננה ולזרעך עד עולם ושמתי את זרעך כעפר הארץ ואיך יאמר עתה ואנכי הולך ערירי והנה בן ביתי יורש אותי ולמה לא האמין בנבואה הראשונה כאשר יאמין בזאת והתשובה כי הצדיקים לא יאמינו בעצמם בחטאם בשגגה וכתוב (ירמיהו יח ט) רגע אדבר על גוי ועל ממלכה לבנות ולנטוע ושב הגוי ההוא ועשה הרע לפני ונחמתי על הטובה והנה ראה עצמו בא בימים ולא נתקיימה נבואתו וחשב כי חטאיו מנעו הטוב ואולי חשש עתה פן יענש על הנפשות שהרג כדברי רבותינו (ב"ר מד ה) וכלשון הזה אמרו בבראשית רבה (עו ב) ויירא יעקב מאד ויצר לו (להלן לב ח) מכאן שאין הבטחה לצדיקים בעולם הזה וכו'
@363 "מה תתן לי ואנכי הולך ערירי" - פירשו בו (יב"ע) אני מת בלא בנים כטעם כי הולך האדם אל בית עולמו (קהלת יב ה) והנכון בעיני כי מתחלה יתאונן מה יהיה שכרי אחרי שאין לי בנים ואנכי הולך נע ונד בארץ נכריה יחידי כערער בערבה אין יוצא ואין בא בביתי זולתי אליעזר איש נכרי אשר לקחתי לי מדמשק לא מבית אבי ולא מארצי ואחר כך אמר הן לי לא נתתה זרע כאשר הבטחתני והנה בן ביתי הנזכר יורש אותי כי זקנתי ויבא עתי בלא זרע והנה אני ענוש ואבד שכרי אשר הבטחתני בו בראשונה
@365 **והנה דבר ה' אליו לאמר לא יירשך זה** . בעבור היות לו הבן היורש אחרי זקנתו לא הבטיחו רק על הירושה שלא ידאג כי זרעו יירשנו וטעם והנה דבר ה' אליו כי עוד בפיו והנה בן ביתי יורש אותי ובא אליו פתאום דבר השם לאמר לא יירשך זה
@366 **ויוצא אותו החוצה** . לפי פשוטו הוציאו מאהלו אל החוץ לראות הכוכבים ולפי מדרשו אמר לו צא מאצטגנינות שלך שראית במזלות שאינך עתיד להעמיד בן אברם אין לו בן אברהם יש לו בן שרי לא תלד שרה תלד לשון רש"י והנה אברם הוליד את ישמעאל אבל פירוש המדרש כי אברם מבקש בן יורש אותו כמו שאמר
@366 "והנה בן ביתי יורש אותי" - והקדוש ברוך הוא אמר לו לא יירשך זה כי אם אשר יצא ממעיך הוא יירשך וצא מן האצטגנינות שלך אברם אינו מוליד בן ליורשו אבל אברהם מוליד בן ליורשו ויתכן שהיה האצטגנינות על זיווגם שאברם ושרי לא יולידו זה מזה ואברהם ושרה יולידו אבל לפי דעתי שרה תוספת במדרש לומר שהיה כן גם בשרה אבל הקדוש ברוך הוא לא הבטיחו עתה בשרה וגם בעת נבואת המילה עדיין היה אברהם מסתפק בשרה שתלד
@367 **והאמן בה' ויחשבה לו צדקה** . פירש רש"י הקדוש ברוך הוא חשב לו צדקה וזכות על האמונה שהאמין בו ואיני מבין מה הזכות הזאת למה לא יאמין באלהי אמן והוא הנביא בעצמו ולא איש אל ויכזב ומי שהאמין לשחוט את בנו היחיד האהוב ושאר הנסיונות איך לא יאמין בבשורה טובה והנכון בעיני כי יאמר שהאמין בה' וחשב כי בצדקו של הקב"ה יתן לו זרע על כל פנים לא בצדקת אברם ובשכרו אף על פי שאמר לו "שכרך הרבה מאד" ומעתה לא יירא פן יגרום החטא ואף על פי שבנבואה הראשונה חשב שתהיה על תנאי כפי שכר מעשיו עתה כיון שהבטיחו שלא יירא מן החטא ויתן לו זרע האמין כי נכון הדבר מעם האלהים אמת לא ישוב ממנה כי צדקת ה' היא ואין לה הפסק כענין שכתוב (ישעיהו מה כג) בי נשבעתי נאם ה' יצא מפי צדקה דבר ולא ישוב או יאמר כי אברהם האמין שיהיה לו זרע יורש על כל פנים והקב"ה עוד חשב לו ההבטחה הזו שהבטיחו צדקה כי בצדקת ה' יעשה כן כמו אלהים חשבה לטובה (להלן נ כ) וכן ותחשב לו לצדקה (תהלים קו לא) דפנחס שחשב לו הבטחתו זו שבטח בשם במעשה ההוא לצדקה לדור ודור כי לעולם ישמור לו האל בעבורה צדקתו וחסדו כדרך לעולם אשמור לו חסדי (שם פט כט)
@368 **אני ה' אשר הוצאתיך מאור כשדים לתת לך את הארץ הזאת לרשתה** . כבר פירשתי זה (לעיל יא כח) כי יאמר מעת שהוצאתיך מאור כשדים ועשיתי לך נס היה הרצון לפני לתת לך הארץ הזאת והנה עתה לא גזר שיתננה לו אבל אמר שהוציאו מאור כשדים על דעת שיתננו לו ולכן חשש אברהם פן יהיה בירושת הארץ תנאי המעשים אף על פי שאמר לו פעמים (לעיל יב ז יג טו) לזרעך אתן את הארץ הזאת כי עתה לא יגזור המתנה כאשר גזר לו זרע ולכן אמר במה אדע כי אירשנה ואינו כשאלת "מה אות" (מלכים ב כ ח) וגם הקדוש ברוך הוא לא עשה עמו כשאר האותות להראות לו אות או מופת בדבר נפלא אבל בקש אברהם שידע ידיעה אמיתית שיירשנה ולא יגרום חטאו או חטא זרעו למנעה מהם או שמא יעשו הכנענים תשובה ויקיים בהם רגע אדבר על גוי ועל ממלכה לנתוש ולנתוץ להאביד ושב הגוי ההוא מרעתו ונחמתי על הרעה (ירמיהו יח ז) והקדוש ברוך הוא כרת עמו ברית שיירשנה על כל פנים
@370 **עגלה משולשת ועז משולשת** . פירש רבי אברהם בת שלש שנים אבל אונקלוס אמר שלש וכן הדבר כי בת שלש לא תקרא עגלה כמו ששנינו (פרה א א) וחכמים אומרים עגלה בת שתים פרה בת שלש ורמז כי שלשה קרבנות מהן יקריבו לפניו זרעו העולה והחטאת והשלמים כי האשם כחטאת הוא אין ביניהם לבד השם ויתכן שיהיה טעם "משולשת" שיביא אותן רצופות ויהיה כל מין לבד וכן כי משולשות הנה (יחזקאל מב ו) שהיו הלשכות העליונות והתיכונות והתחתונות
@371 **ויבתר אותם בתוך** . לכרות עמו ברית לעבור בין הבתרים האלה ונרמז לו גם כן כי מאלה יהיה כל קרבן בבהמה ובעוף כי הגוזל בן יונה ואמר בו גוזל שלא הוכשרו במין ההוא אלא הקטנים ואף על פי שכל קטני העופות יקראו גוזלים שנאמר (דברים לב יא) כנשר יעיר קנו על גוזליו ירחף הבין אברהם מעצמו המין הנבחר או הקריב בן יונה ברצונו והכתוב בחר לעולם במין אשר הקריב הזקן והנה ידע שאלה יהיו הקרבנות וכל הקרבנות יבתרו העולה לנתחים והשלמים לחזה ושוק וחלבים והחטאת והאשם לחלביהן
@371 "ואת הצפור לא בתר" - נתן התור והגוזל איש לקראת רעהו כי גם הם היו בברית אבל לא בתר אותם בתוך כי בכל העוף הקרב נאמר לא יבדיל (ויקרא א יז) ובבראשית רבה (מד יד) הראה לו הקב"ה שמבדילין בעולת העוף ואין מבדילין בחטאת העוף
@372 **וירד העיט על הפגרים** . לאכול אותם כמנהג העופות
@372 "וישב אותם" - נרמז לו כי יבאו העמים לבטל הקרבנות וזרע אברהם יבריחום
@373 **והנה אימה חשכה גדולה נופלת** . דרשו בו רמז לשעבוד ארבע גליות כי מצא הנביא בנפשו אימה ואחר כך בא בחשכה ואחר כך גדלה החשכה ואחר כך הרגיש כאלו היא נופלת עליו כמשא כבד תכבד ממנו אמרו (ב"ר מד יז) אימה זו בבל חשכה זו מדי שהחשיכה עיניהם של ישראל בצום ובתענית גדולה זו מלכות אנטיוכס נופלת עליו זו אדום והיה הענין הזה לאברהם כי כשהקב"ה כרת עמו ברית לתת הארץ לזרעו לאחזת עולם אמר לו כמשייר במתנתו שארבע גליות ישתעבדו בבניו וימשלו בארצם וזה בעל מנת אם יחטאו לפניו ואחרי כן הודיעו בבאור גלות אחרת שיגלו תחלה שהוא גלות מצרים שכבר נענש בו כאשר פירשתי (לעיל יב י)
@374 **כי גר יהיה זרעך** . זה מקרא מסורס ושיעורו כי גר יהיה זרעך בארץ לא להם ארבע מאות שנה ועבדום וענו אותם ולא פירש כמה ימי העבדות והעינוי והרבה מקראות מסורסות יש בכתוב וכן בא אלי העבד העברי אשר הבאת לנו לצחק בי (להלן לט יז) וכן וכל הארץ באו מצרימה לשבור אל יוסף (שם מא נז) וכן כי כל אוכל חמץ ונכרתה הנפש ההיא מישראל מיום הראשון עד יום השביעי (שמות יב טו) וכן ביום ההוא ישליך האדם את אלילי כספו ואת אלילי זהבו אשר עשו לו להשתחות לחפור פירות ולעטלפים (ישעיהו ב כ) וכן לכו שמעו ואספרה כל יראי אלהים אשר עשה לנפשי (תהלים סו טז) וכן לי יזעקו אלהי ידענוך ישראל (הושע ח ב) וכן והיו לי אמר ה' צבאות ליום אשר אני עושה סגלה וחמלתי עליהם (מלאכי ג יז) ורבים כן וענין הכתוב אף על פי שאני אומר לך לזרעך נתתי את הארץ הזאת ידוע תדע כי טרם תתי אותה להם יהיו גרים בארץ לא להם ארבע מאות שנה וגם יעבדום וענו אותם ורבי אברהם אמר ידוע תדע כי גר יהיה זרעך בעבדות וענוי עד קץ ארבע מאות שנה מן היום הזה ואם כן הודיעו קץ הגאולה ולא הודיעו כמה ימי הגלות גם נכון הוא "()" "סגירה"
@375 **וגם את הגוי אשר יעבודו** . וגם לרבות ד' גליות על ששעבדו את ישראל לשון רש"י ועל דרך הפשט יאמר כאשר דנתי את בניך בגלות וענוי על עון גם את הגוי אשר יעבודו אדין על החמס אשר יעשו להם והנכון בעיני כי טעם וגם אף על פי שאני גזרתי על זרעך להיות גרים בארץ לא להם ועבדום וענו אותם אף על פי כן אשפוט את הגוי אשר יעבודו על אשר יעשו להם ולא יפטרו בעבור שעשו גזרתי והטעם כמו שאמר הכתוב (זכריה א יד) וקנאתי לירושלם ולציון קנאה גדולה וקצף גדול אני קוצף על הגוים השאננים אשר אני קצפתי מעט והמה עזרו לרעה ואומר (ישעיהו מז ו) קצפתי על עמי חללתי נחלתי וגו' וכן היה במצרים שהוסיפו להרע כי השליכו בניהם ליאור וימררו את חייהם וחשבו למחות את שמם וזה טעם דן אנכי שאביא אותם במשפט אם עשו כנגזר עליהם או הוסיפו להרע להם וזהו מה שאמר יתרו כי בדבר אשר זדו עליהם (שמות יח יא) כי הזדון הוא שהביא עליהם העונש הגדול שאבדם מן העולם וכן כי ידעת כי הזידו עליהם (נחמיה ט י) והרב נתן טעם בספר המדע (הלכות תשובה ו ה) לפי שלא גזר על איש ידוע וכל אותם המריעים לישראל אלו לא רצה כל אחד מהם הרשות בידו לפי שלא נגזר על איש ידוע ולא נתכנו דבריו אצלי שאפילו גזר שאחד מכל האומות יריע להם בכך וכך וקדם זה ועשה גזרתו של הקב"ה זכה בדבר מצוה ומה טעם בדבריו כאשר יצוה המלך שיעשו בני מדינה פלונית מעשה מן המעשים המתרשל ומטיל הדבר על האחרים חומס וחוטא נפשו והעושה יפיק רצון ממנו וכל שכן שהכתוב אמר וגם את הגוי אשר יעבודו שיעבדו הגוי כולו והם הלכו מעצמם למצרים אבל הטעם כאשר כתבתי וכבר הזכירו רבותינו הענין הזה אמרו בואלה שמות רבה (ל טו) משל לאדון שאמר לבנו "יעשה עם פלוני ולא יצערנו" הלך ועשה אף על פי שעשה עמו חנם לא הניח שלא היה מצערו כשנתרצה האדון לבנו גזר על מצעריו הריגה כך גזר הקב"ה שיהיו ישראל משועבדין במצרים עמדו עליהם ושעבדום בחוזק אמר הקב"ה היה לכם לנהוג בם כעבדים ויעשו צרכיכם אני קצפתי מעט והמה עזרו לרעה (זכריה א טו) עד כאן לשונם ודבר ברור הוא כי השלכת בניהם ליאור אינה בכלל "ועבדום וענו אותם" אבל היא עקירתם לגמרי וכן מה שאמרו תחלה הבה נתחכמה לו פן ירבה (שמות א י) אינו בכלל עבדות וענוי מלבד מה שהוסיפו בענוי עצמו וימררו את חייהם בעבודה קשה וגו' והוא מה שאמר הכתוב (דברים כו ז) וירא את עניינו ואת עמלינו ואת לחצנו ודע והבן כי האיש שנכתב ונחתם בראש השנה להריגה לא ינקה הליסטים ההורג אותו בעבור שעשה מה שנגזר עליו הוא רשע בעונו ימות ודמו מיד הרוצח יבוקש אבל כאשר תצא הגזירה על פי נביא יש בעושה אותה דינים כי אם שמע אותה ורצה לעשות רצון בוראו כנגזר אין עליו חטא אבל יש לו זכות בו כאשר אמר ביהוא (מלכים ב י ל) יען אשר הטיבות לעשות הישר בעיני ככל אשר בלבבי עשית לבית אחאב בנים רבעים ישבו לך על כסא ישראל אבל אם שמע המצוה והרג אותו לשנאה או לשלול אותו יש עליו העונש כי הוא לחטא נתכוון ועבירה הוא לו וכן הכתוב אומר בסנחריב (ישעיהו י ה) הוי אשור שבט אפי וגו' בגוי חנף אשלחנו ועל עם עברתי אצונו ואמר הכתוב והוא לא כן ידמה ולבבו לא כן יחשוב כי להשמיד בלבבו ועל כן הענישו בסוף כמו שנאמר (שם י יב) והיה כי יבצע ה' את כל מעשהו אפקוד על פרי גודל לבב מלך אשור ועל תפארת רום עיניו וגו' ואמר בו שה פזורה ישראל אריות הדיחו הראשון אכלו מלך אשור וזה האחרון עצמו נבוכדראצר מלך בבל לכן כה אמר ה' וגו' הנני פוקד אל מלך בבל ואל ארצו כאשר פקדתי על מלך אשור (ירמיהו נ יז) והנה זו ראיה שנענש מלך אשור על הרעה שעשה לישראל והנה נבוכדראצר שמע כי הנביאים פה אחד קוראים אותו להחריב ירושלים והוא וכל עמו נצטוו על כך מפי הנביא כמו שכתוב (ירמיהו כה ט) הנני שולח לך ולקחתי את כל משפחות צפון נאם ה' ואל נבוכדראצר מלך בבל עבדי והביאותים על הארץ הזאת ועל יושביה והחרמתים וכתיב (שם לב כח) הנני נותן את העיר הזאת ביד הכשדים וביד נבוכדראצר מלך בבל והציתו את העיר באש ואף על בית המקדש עצמו אמר (שם כו ו) ונתתי את הבית הזה כשילה והם יודעים כי מצות השם היא כמו שאמר נבוזראדן לירמיהו (שם מ ב) ה' אלהיך דבר את הרעה הזאת אל המקום הזה ויבא ויעש ה' כאשר דבר כי חטאתם לה' ואף על פי כן נענשו הכשדים כולם בסוף והיה זה מפני שני טעמים האחד שגם הוא נתכון להשמיד כל הארץ להגדיל ממשלתו כמו שכתוב בו (ישעיהו יג יא) והשבתי גאון זדים וגאות עריצים אשפיל וכתיב (שם יד יג) ואתה אמרת בלבבך השמים אעלה וגו' וכתוב אעלה על במתי עב אדמה לעליון וכתיב באומתו (שם מז ח) האומרת בלבבה אני ואפסי עוד ואמר בו חבקוק (חבקוק ב ט) הוי בוצע בצע רע לביתו לשום במרום קנו וגו' והנה זה כענשו של סנחריב ולכך אמר הכתוב (ירמיהו נ יח) לכן כה אמר ה' הנני פוקד אל מלך בבל ואל ארצו כאשר פקדתי על מלך אשור אבל היה במלך בבל עונש אחר שהוסיף על הגזרה והרע לישראל יותר מאד כמו שאמר בו (ישעיהו מז ו) קצפתי על עמי חללתי נחלתי ואתנם בידך לא שמת להם רחמים על זקן הכבדת עולך מאד ועל כן בא עליהם עונש כפול ומכופל שנשמד זרעו לגמרי ולא יהיה לבבל שם ושאר נין ונכד (ישעיהו יד כב) ונשמדה עירו לעולמים שנאמר (שם יג יט) והיתה בבל צבי ממלכות תפארת גאון כשדים כמהפכת אלהים את סדום ואת עמורה לא תשב לנצח ולא תשכון עד דור ודור ורבצו שם ציים ושעירים ירקדו שם ואמר בו הכתוב (ירמיהו נא יא) כי נקמת ה' היא נקמת היכלו וכתיב (שם נא לה לו) חמסי ושארי על בבל תאמר יושבת ציון ודמי אל יושבי כשדים תאמר ירושלים לכן כה אמר ה' הנני רב את ריבך ונקמתי את נקמתך ופסוקים רבים כאלה
@376 **ואתה תבא אל אבותיך בשלום** . ולא תראה כל אלה לשון רש"י ואינו נכון כפי פירושו שאמר (בפסוק יג) "כי גר יהיה זרעך" משיהיה לך זרע ומשנולד יצחק נאמר בו ויגר אברהם בארץ פלשתים (להלן כא לד) ויגר יצחק בגרר אם כן גם הוא בכלל הגזירה אבל טעמו ואתה תבא אל אבותיך בשלום שלא יגיעך שום עונש דבר מאתי אף על פי שאני גוזר על בניך עונשים בעבדות וענוי
@377 **ודור רביעי ישובו הנה** . לאחר שיגלו למצרים יהיו שלשה דורות וכן היה יעקב גולה צא וחשוב דורותיו יהודה פרץ חצרון וכלב בן חצרון מבאי הארץ היה לשון רש"י ואיננו נכון כלל והנכון בעיני כי "דור רביעי" לאמורי המשלים עונו כי מיום הגזירה האריך לו כי הוא פוקד עון על שלשים ועל רבעים כי אם ישובו לא יחרימם אבל יהיו למס עובד או יפנו להם
@377 "עון האמורי" - הזכיר התקיף שבהם אשר כגבה ארזים גבהו ולא יוכלו לו עד שתתמלא סאתו ועונותיו ילכדונו ועוד כי הוא הנלכד להם אשר הורישו בתחלה
@378 **והנה תנור עשן ולפיד אש** . ראה כאלו תנור עשן כולו ובתוכו לפיד אש בוערה כענין עשן גדול ואש מתלקחת (יחזקאל א ד) והעשן הוא הענן והערפל הנזכר במתן תורה (דברים ד יא) ולפיד האש בתוכו הוא האש האמור שם (ד לו) ודבריו שמעת מתוך האש וכתוב (שמות כד יז) ומראה כבוד ה' כאש אוכלת וגו' והנה השכינה עברה בין הבתרים והוא הברית אשר היתה אתו מעולם וזה טעם כרת ה' את אברם ברית כי הקב"ה בעצמו העביר ברית בין הבתרים והמשכיל יבין
@379 **ביום ההוא כרת ה' את אברם ברית לאמר** . הנה הקב"ה הבטיח את אברהם במתנת הארץ פעמים רבים וכולם לצורך ענין בבואו בארץ מתחלה אמר לו לזרעך אתן את הארץ הזאת (לעיל יב ז) ולא באר מתנתו כי אין במשמע רק במה שהלך בארץ עד מקום שכם עד אילון מורה ואחרי כן כשרבו זכיותיו בארץ הוסיף לו שא נא עיניך וראה צפונה ונגבה וקדמה וימה (לעיל יג יד) כי יתן לו כל הארצות ההן בכללן ואין הטעם אשר אתה רואה בעיניך כי ראות האדם איננו למרחק רק שיתן לו לכל מראה עיניו הרוחות או שהראהו כל ארץ ישראל כאשר היה במשה רבינו והוסיף לו בברכה השנית הזאת עוד ולזרעך עד עולם ושירבה זרעו כעפר הארץ ובפעם השלישית באר לו תחומי הארץ והזכיר לו כל העמים עשרה אומות והוסיף לכרות לו ברית עליהן שלא יגרום החטא וכאשר צוהו על המילה אמר לו לאחזת עולם (להלן יז ח) לאמר שאם יגלו ממנה עוד ישובו וינחלוה והוסיף והייתי להם לאלהים שהוא בכבודו ינהיג אותם ולא יהיו בממשלת כוכב ומזל או שר משרי מעלה כאשר יתבאר עוד בתורה (ויקרא יח כה) ואמר הכתוב בפעם הראשונה לזרעך אתן בלשון עתיד וכן בשנית כי עד הנה לא נתנה אליו כולה ולפיכך אמר לו אתננה אבל בשלישית בשעת הברית אמר לזרעך נתתי לאמר שיכרות לו ברית על המתנה שכבר נתן לו וכן בעת המילה כשאמר "לאחזת עולם" אמר לו "ונתתי לך" בעתיד ורש"י כתב לזרעך נתתי אמירת הגבוה כמו שהיא עשויה ואין צורך במקום הזה
@384 **וישמע אברם לקול שרי** . לא אמר הכתוב "ויעש כן" אבל אמר כי שמע לקול שרי ירמוז כי אף על פי שאברם מתאוה מאד לבנים לא עשה כן בלא רשות שרי וגם עתה לא נתכוון שיבנה הוא מהגר ויהיה זרעו ממנה אבל כל כוונתו לעשות רצון שרה שתבנה ממנה שיהיה לה נחת רוח בבני שפחתה או זכות שתזכה היא לבנים בעבור כן כדברי רבותינו (ב"ר מב ב עא ז) ואמר עוד ותקח שרי להודיע שלא מהר אברם לדבר עד שלקחה שרי ונתנה בחיקו והזכיר הכתוב שרי אשת אברם לאברם אישה לרמוז כי שרה לא נתיאשה מאברם ולא הרחיקה עצמה מאצלו כי היא אשתו והוא אישה אבל רצתה שתהיה גם הגר אשתו ולכך אמר לו לאשה שלא תהיה כפלגש רק כאשה נשואה לו וכל זה מוסר שרה והכבוד שהיא נוהגת בבעלה
@385 **מקץ עשר שנים** . מועד הקבוע לאשה ששהתה עם בעלה י' שנים ולא ילדה חייב לישא אחרת לשבת אברם בארץ כנען מגיד שאין ישיבת חוצה לארץ עולה לו מן המנין לפי שלא נאמר לו ואעשך לגוי גדול עד שבא לארץ ישראל לשון רש"י והטעם הזה איננו יפה שישיבת חוצה לארץ הלכה פסוקה היא שאינה עולה לשום אדם בעולם ומשנה ששנינו בה (יבמות סד) בכל אדם היא ואם היה מפני ההבטחה הזו לאברם היתה עולה לשאר האנשים וכבר טעו בה גם כן מן המפרשים טעות אחרת שאמרו שאין דין היושב בחוצה לארץ להוציא האשה ששהתה עמו עשר שנים ולא ילדה ולא שישא אחרת ואין הענין כן אבל הכוונה לומר שאם היה אדם עם אשתו בחוצה לארץ חמש או עשר שנים ובאו לארץ ישראל שנותנין להם זמן עשר שנים מעת ביאתם לארץ אולי בזכות הארץ יבנו וכן עשו אברהם ושרה מנו מעת בואם שם
@388 **ותענה שרי ותברח מפניה** . חטאה אמנו בענוי הזה וגם אברהם בהניחו לעשות כן ושמע ה' אל עניה ונתן לה בן שיהא פרא אדם לענות זרע אברהם ושרה בכל מיני הענוי
@391 **שובי אל גברתך והתעני תחת ידיה** . צוה אותה לשוב ולקבל עליה ממשלת גברתה רמז כי לא תצא לחפשי ממנה כי בני שרה ימשלו בזרעה לעולם
@393 **וקראת שמו ישמעאל** . הודיע המלאך להגר שיהיה שמו ישמעאל כדרך הנה בן נולד לבית דוד יאשיהו שמו (מלכים א יג ב) ואמר לה שהיא תקראנו כן ותזכור כי שמע אלהים אל עניה ואברהם מעצמו קרא שמו כן שישמע אל ויעננו או ששרתה עליו רוח הקודש כדברי רש"י וקרא אותו ישמעאל כי שמע אלהים אל עני אמו כדבר המלאך והנכון בעיני כי המלאך צוה להגר שתקראנה כן והיא יראה בעבור היותה פלגש לקרוא שם לבן אדוניה וגלתה לו הענין ואברם קיים דבר ה' אבל לא הוצרך הכתוב להאריך בזה
@394 **פרא אדם** . לשון רש"י אוהב מדברות לצוד חיות כמו שכתוב (להלן כא כ) וישב במדבר ויהי רובה קשת ידו בכל ליסטים ויד כל בו הכל שונאין אותו ומתגרין בו והנכון כי פרא אדם סמוך שיהיה איש פרא למוד מדבר יצא בפעלו משחר לטרף ויטרוף הכל והכל יטרפוהו והענין על זרעו שיגדל ויהיו להם מלחמות עם כל העמים ורבי אברהם אמר ידו בכל שינצח מתחלה כל הגוים ואחר כן יד כל בו שינוצח בסוף ועל פני כל אחיו שהם בני קטורה ישכון שיגדל זרעו מהם
@399 **אל שדי** . שני שמות כל אחד תאר לעצמו ופירוש "אל" תקיף מלשון אלי מואב (שמות טו טו) ופירוש "שדי" אמר רש"י שיש די באלהותי לכל בריה ובספר מורה הנבוכים (א סג) פירש הרב כלומר שאינו צריך במציאות מה שנמצא ולא בקיום מציאותו לזולתו אבל מציאותו תספיק בעצמה ורבי אברהם פירשו בשם הנגיד ז"ל מגזרת שודד כלומר מנצח ומשודד מערכות השמים וזהו הנכון כי היא מדת הגבורה מנהגת העולם שיאמרו בה החכמים (ב"ר לה ד) "מדת הדין של מטה" וטעם להזכיר עתה זה השם כי בו יעשו הנסים הנסתרים לצדיקים להציל ממות נפשם ולחיותם ברעב ולפדותם במלחמה מיד חרב ככל הנסים הנעשים לאברהם ולאבות וככל הבאים בתורה בפרשת אם בחקותי (ויקרא כו ג-מו) ובפרשת והיה כי תבא (דברים כח א-סח) בברכות ובקללות שכולם נסים הם כי אין מן הטבע שיבואו הגשמים בעתם בעבדנו האלהים ולא שיהיו השמים כברזל כאשר נזרע בשנה השביעית וכן כל היעודים שבתורה אבל כולם נסים ובכולם תתנצח מערכת המזלות אלא שאין בהם שנוי ממנהגו של עולם כנסים הנעשים על ידי משה רבינו בעשר המכות ובקריעת הים והמן והבאר וזולתם שהם מופתים משנים הטבע בפירסום והם שיעשו בשם המיוחד אשר הגיד לו ולכן אמר עתה לאברהם אבינו כי הוא התקיף המנצח שיגבר על מזלו ויוליד ויהיה ברית בינו ובין זרעו לעולם שיהיה חלק ה' עמו וברצונו ינהיגם לא יהיו תחת ממשלת כוכב ומזל ודע וראה כי אברהם אבינו לא הזכיר בדבריו שם יו"ד ה' רק בצירוף השם הכתוב באל"ף דל"ת או בצירוף אל עליון עמו ויזכיר בעניניו "אלהים" וכן יאמר ה' אלהי השמים (להלן כד ז) ואמר ה' יראה (להלן כב יד) על מקום המקדש העתיד ויעקב הזכיר תמיד "אל שדי" (להלן מג יד מח ג) ומשה רבינו לא יזכיר כן לעולם ואם תזכה תבין זה כולו ממה שאמרו במסכת יבמות (מט) כל הנביאים נסתכלו באיספקלריא שאינה מאירה ולפיכך אמר ישעיה ואראה את ה' (ישעיהו ו א) ומשה נסתכל באיספקלריא המאירה ולפיכך אמר כי לא יראני האדם וחי (שמות לג כ) ואראה את ה' כתוב באל"ף דל"ת ועוד אזכיר זה בפרשת וארא (שמות ו ב) אם יראה אלהים בעניי
@399 "התהלך לפני" - ללכת בדרך אשר אורה אותך כטעם אחרי ה' אלהיכם תלכו ואותו תיראו (דברים יג ה) כי המצוה לאחוז דרכו קודם שיורנו יאמר "התהלך לפני" והבא אחרי הצואה יאמר "אחרי ה' תלכו" והענין בשניהם ללכת אחרי השם לירא ממנו לבדו ולעשות מה שיצוה
@399 "והיה תמים" - מצוה אחרת עוד בענין הזה כטעם תמים תהיה עם ה' אלהיך (דברים יח יג) אחרי אזהרת השם לא ימצא בך קוסם קסמים מעונן ומנחש ומכשף וגו' (שם יח י) והענין בשניהם שיאמין בלבו כי הקב"ה לבדו הוא בעל היכולת בתחילה ובסוף הוא היכול לעשות ולבטל ולא ישמעו אל מעוננים ואל קוסמים או למנחש ומכשף ולא יאמין שיבאו דבריהם על כל פנים אבל יגזור בלבו שהכל ביד עליון העליונים שהוא "אל" והוא "אל שדי" עושה טובה שלא היה במזל ומביא רעה בהיות המזל טוב ויפה כפי שיתהלך האדם לפניו מפר אותות בדים וקוסמים יהולל (ישעיהו מד כה) וזהו שאמרו (שבת קנו) צא מאצטגנינות שלך וכו' ורש"י פירש והיה תמים היה שלם בכל הנסיונות ורבי אברהם אמר שלא ישאל על המילה למה והוא כטעם יהי לבי תמים בחקיך למען לא אבוש (תהלים קיט פ) והנכון מה שפרשתי
@401 **וטעם ויפול אברם על פניו** . לכוין דעתו לנבואה וכאשר השלים לו נבואת המצוה במילה קם אברהם ועמד ובא אליו הדיבור שנית מן השמים ואמר לו שרי אשתך וגו' וחזר ונפל על פניו לכוין דעתו והתפלל על ישמעאל כדרך ויפלו על פניהם ויאמרו אל אלהי הרוחות וגו' (במדבר טז כב) וכן ואכלה אותם כרגע ויפלו על פניהם (שם יז י)
@402 **הנה בריתי אתך והיית לאב המון גוים** . הוא ברית המילה כאשר יפרש זאת אות הברית ואחרי הברית תהיה לאב המון גוים וברוך השם אשר לו לבדו נתכנו עלילות שהקדים וצוה את אברהם לבא בבריתו להמול קודם שתהר שרה להיות זרעו קדוש (ראב"ע פסוק ה)
@404 **ונתתיך לגוים** . לשון רש"י ישראל ואדום שהרי ישמעאל כבר היה לו ולא היה מבשר עליו ואיננו נכון בעיני שיבשרנו בעת ברית המילה על עשו והוא אינו מקיים המילה וגם לא נצטוה עליה כמו שדרשו בסנהדרין (נט) כי ביצחק ולא כל יצחק אבל ישראל לבדם יקראו גוים ועמים וכן אף חובב עמים (דברים לג ג) עמים הר יקראו (שם יט) אחריך בנימין בעממיך (שופטים ה יד) גם אחרי הולדת השבטים כולם אמר גוי וקהל גוים יהיה ממך (להלן לה יא) ונתתיך לקהל עמים (להלן מח ד)
@407 **ואתה את בריתי תשמור** . כתב רש"י ו' מוסיף על ענין ראשון אני הנה בריתי אתך ואתה הוי זהיר לשמרו ומה שמירתו זאת בריתי אשר תשמרו אתם של עכשיו ובין זרעך אחריך העתידים להולד וצדק הרב בפשוטו ואמרו (הרד"ק) בטעם המילה ששם זכרון באבר התאוה רב המהומה והחטא לבל ישתמשו בו רק במצוה ובמותר ועל דרך האמת טעם "הנה בריתי אתך" כטעם "הנה אנכי עמך" (להלן כח טו) "ויאמר כי אהיה עמך" (שמות ג יב) "יהי ה' אלהינו עמנו" (מלכים א ח נז) יאמר כי הברית יהיה עמו ולכן יפרה וירבה ואחר כך צוה שישמור אברהם הברית הזאת ותהיה המילה לאות ברית והנה האות הזה אות כשבת ולכן ידחה אותו והבן זה (עי' זהר לך לך פט)
@412 **וערל זכר** . כאן לימדך שהמילה היא באותו מקום שהוא ניכר בין זכר לנקבה לשון רש"י וכן הזכירו רבותינו (ב"ר מו ד) גם טעמים אחרים ורבי אברהם אמר (ויקרא יב ג) ערלתו ידועה כי הוא בערוה ואין כן ערלת לב (ירמיהו ט כה) ושפה (שמות ו יב) ואזן (ירמיהו ו י) כי כולם סמוכים ולפי דעתי הדבר מפורש בכתוב כי לא אמר "ונמלתם את ערלתכם" שיהיה הדבר בספק וכן לא אמר "ערלת בשרכם" כמו שיאמר ערלת לבבכם (דברים י טז) וערלת שפתכם (עיי' שמות ו יב) אבל אמר "בשר ערלתכם" שתכרתו הבשר שהוא ערלה בכם כלומר הבשר האוטם בכם ואין בגוף בשר אוטם וכוסה אבר שיכרת הבשר ההוא וישאר בלא ערלה זולתי בשר החופה את העטרה שהזכירו חכמים (שבת קלז) ו"ערל בשר" (יחזקאל מד ט) כנוי כמו גדלי בשר (שם טז כו) זב מבשרו (ויקרא טו ב)
@415 **ויצחק** . תרגם אונקלוס "וחדי" וכן הדבר כי הצחוק פעם יאמר ללעג ופעם לשמחה כמו משחקת בתבל ארצו (משלי ח לא) משחקים לפני ה' ( ו ה) ולפי דעתי שהכונה בלשון הזה כי כל רואה ענין נפלא באדם לטוב לו ישמח עד ימלא שחוק פיו והוא מה שאמרה שרה (להלן כא ו) צחוק עשה לי אלהים כל השומע יצחק לי כענין אז ימלא שחוק פינו ולשוננו רנה (תהלים קכו ב) וכן עשה אברהם כאשר נאמר לו זה שמח ומלא שחוק פיו ויאמר בלבו ראוי זה לשחוק כי הוא ענין נפלא מאד הלבן מאה שנה יולד ואם שרה בת תשעים תלד ולא יהיה זה לשחוק ולשמחה ויקצר הכתוב בתמיהה כי היא נקשרת במה שאמר ויצחק וכן הגם הלום ראיתי (לעיל טז יג) נקשר בראש הפסוק כי אמרה הגם הלום ראיתי השם שנגלה לי כי ראה בעניי ולא אקראנו אל ראי וכן הנגלה נגליתי אל בית אביך (שמואל א ב כז) קשור עם "למה תבעטו בזבחי ובמנחתי" יאמר האם בחרתי בכם שתבעטו בזבחי ומנחתי ולמה תעשו כן או שתהיה הלבן מאה שנה בשאלה לדבר פלא לא כדבר נמנע כמו התשפוט את עיר הדמים (יחזקאל כב ב) ענינו התרצה לשפוט אותה ולהודיעה את כל תועבותיה וכן התעיף עיניך בו ואיננו (משלי כג ה) וכן המן העץ אשר צויתיך לבלתי אכל ממנו אכלת (לעיל ג יא) כלומר האם עלה בדעתך על הלב לאכול מן העץ וכן זה האם יעלה על הלב שלבן מאה שנה יוליד שרה בת תשעים שנה תלד ואחר כן אמר לו שיהיה הנס הזה עם חיי ישמעאל
@415 "הלבן מאה שנה יולד" - אין הפלא בבן מאה שנה שיוליד כי האנשים יולידו כל ימי היות בהם הליחה בני תשעים ובני מאה גם בדורות האלה אף כי בימי אברהם שלא עברו מימיו פי השנים והנה אחרי זה ארבעים שנה הוליד בנים רבים מקטורה אבל אמר הלבן מאה שנה שלא הוליד בבחרותו מן האשה הזאת יוליד ממנה עתה אחרי מאה ואחרי תשעים שפסק ממנה ארח נשים כי ידע כן ולכך לא אמר כן מתחלה כשנאמר לו (לעיל יז ו) "ונתתיך לגוים" עד אמרו אליו כי משרה יוליד וצוה אותו וקראת את שמו יצחק בעבור הצחוק שעשה אברהם וזה לאות כי היה לאמונה ולשמחה ואחרי שקרא אותו אברהם כן כאשר צוה ה' אותו אמרה שרה הכי קרא שמו יצחק כי צחוק עשה לי אלהים
@416 **לו ישמעאל יחיה לפניך** . פירוש המלה הזאת בכל מקום כטעם "אם" והורכבה במלת "לולי" (להלן לא מב) וטעמה "אם לא" ונכתבה לפעמים באל"ף (להלן מג י) וכן ירכיבוה עוד ויאמרו "אלו" ואלו לעבדים ולשפחות (אסתר ז ד) ואלו חיה אלף שנים פעמים (קהלת ו ו) וענין המלה "אם לו" וטעמה כמו "אם אם" ובא הכפל לחזוק כמו הרק אך במשה (במדבר יב ב) המבלי אין קברים (שמות יד יא) ודומיהם ואמר אברהם אם ישמעאל יחיה לפניך ארצה בברכה הזאת אשר ברכתני בזרע שרה כי הבטיחו מתחלה אשר יצא ממעיך הוא יירשך (לעיל טו ד) והנה היורש אותו יחיד והיה חושב שהוא ישמעאל ועתה כאשר נאמר לו כי משרה יוליד והבין כי הוא היורש פחד פן ימות ישמעאל ולכן אמר זה
@416 "יחיה לפניך" - פירש רש"י יחיה ביראתך כמו התהלך לפני (לעיל יז א) פלח קדמי ואיננו נכון בעבור שאמר ולישמעאל שמעתיך אבל פירושו יחיה ויתקיים זרעו כל ימי עולם
@417 **אבל שרה אשתך** . כמו אבל בן אין לה (מלכים ב ד יד) כטעם רק אמר רק הבן אשר אני מבשרך עליו שרה אשתך תלד אותו ובו אני מקים בריתי לעולם ובזרעו אחריו וישמעאל אברך להרבות זרעו אך לא מבריתי
@420 **ויעל אלהים מעל אברהם** . לשון כבוד כלפי המקום ולמדנו שהצדיקים מרכבתו של הקב"ה לשון רש"י אבל לשונם בבראשית רבה (מז ו) האבות הן הן המרכבה ירמוז למה שכתוב (מיכה ז כ) תתן אמת ליעקב חסד לאברהם ופחד יצחק היה לי (להלן לא מב) והמשכיל יבין
@424 **בעצם היום הזה** . כתב רש"י בעצם היום הזה שמלאו לאברהם צ"ט שנה ולישמעאל י"ג נמולו ומה טעם להזכיר זה ועוד שכבר הסכימו (ר"ה י) לדברי רבי אליעזר שבתשרי נברא העולם ובתשרי נולדו אבות ובפסח נולד יצחק והכתוב אמר למועד הזה בשנה האחרת והוא כתב בסדר וירא (יח י) כי הבשורה היתה בפסח ולפסח הבא נולד יצחק אבל בעצם היום הזה שנצטוה במצוה הזאת נימול הוא וילידי ביתו שמנה עשר ושלש מאות וכל מקנת כספו סיפר הכתוב מעלתו ביראת ה' ומעלת כל בני ביתו שכולם זריזים מקדימין למצות ואין טעם נימול אברהם שנימול הוא בתחלה אבל ישמעאל בנו נימול מתחלה וכל בני ביתו כי כן כתוב (לעיל פסוק כג) ויקח אברהם את ישמעאל בנו ואת כל ילידי ביתו ואחרי כן ואברהם בן תשעים ותשע שנה בהמולו והטעם כי אברהם נזדרז במצות המילה שלהם תחילה ומל אותם הוא בעצמו או שזימן להם מוהלים הרבה והוא עומד עליהם ואחר כך מל את עצמו שאילו הקדים מילתו היה חולה או מסוכן בה מפני זקנתו ולא היה יכול להשתדל במילתם חסלת פרשת לך לך
@426 **וירא אליו** . לשון רש"י לבקר את החולה אמר רבי חמא בר חנינא יום שלישי למילתו היה ובא הקב"ה ושאל בו והנה שלשה אנשים המלאכים שבאו אליו בדמות אנשים שלשה אחד לבשר את שרה ואחד לרפאות את אברהם ואחד להפוך את סדום ורפאל שריפא את אברהם הלך משם להציל את לוט שאין זה שתי שליחות כי היה במקום אחר ונצטווה בו אחר כן או ששתיהן להצלה ויאכלו נראו כמי שאכלו ובספר מורה הנבוכים (ב מב) נאמר כי הפרשה כלל ופרט אמר הכתוב תחלה כי נראה אליו השם במראות הנבואה ואיך היתה המראה הזאת כי נשא עיניו במראה והנה ג' אנשים נצבים עליו ויאמר אם נא מצאתי חן בעיניך זה ספור מה שאמר במראה הנבואה לאחד מהם הגדול שבהם ואם במראה לא נראו אליו רק אנשים אוכלים בשר איך אמר "וירא אליו ה'" כי הנה לא נראה לו השם לא במראה ולא במחשבה וככה לא נמצא בכל הנבואות והנה לדבריו לא לשה שרה עוגות ולא עשה אברהם בן בקר וגם לא צחקה שרה רק הכל מראה ואם כן בא החלום הזה ברוב ענין כחלומות השקר כי מה תועלת להראות לו כל זה וכן אמר (שם) בענין "ויאבק איש עמו" (להלן לב כה) שהכל מראה הנבואה ולא ידעתי למה היה צולע על ירכו בהקיץ ולמה אמר (להלן לב לא) כי ראיתי אלהים פנים אל פנים ותנצל נפשי כי הנביאים לא יפחדו שימותו מפני מראות הנבואה וכבר ראה מראה גדולה ונכבדת מזאת כי גם את השם הנכבד ראה פעמים רבות במראה הנבואה (עיין להלן כח יג לא ג) והנה לפי דעתו זאת יצטרך לומר כן בענין לוט כי לא באו המלאכים אל ביתו ולא אפה להם מצות ויאכלו אבל הכל היה מראה ואם יעלה את לוט למעלת מראה הנבואה איך יהיו אנשי סדום הרעים והחטאים נביאים כי מי הגיד להם שבאו אנשים אל ביתו ואם הכל מראות נבואתו של לוט יהיה "ויאיצו המלאכים וגו' קום קח את אשתך" "ויאמר המלט על נפשך" (להלן יט טו יז) ו"הנה נשאתי פניך" (שם כא) וכל הפרשה כלה מראה וישאר לוט בסדום אבל יחשוב שהיו המעשים נעשים מאליהם והמאמרים בכל דבר ודבר מראה ואלה דברים סותרים הכתוב אסור לשומעם אף כי להאמין בהם ובאמת כי כל מקום שהוזכר בכתוב ראיית מלאך או דבור מלאך הוא במראה או בחלום כי ההרגשים לא ישיגו המלאכים אבל לא מראות הנבואה כי המשיג לראות מלאך או דיבורו איננו נביא שאין הדבר כמו שהרב גוזר (במו"נ ב לד ובהלכות יסוה"ת ז ו) כי כל נביא זולת משה רבינו נבואתו על ידי מלאך וכבר אמרו (מגילה ג) בדניאל אינהו עדיפי מיניה דאינהו נביאי ואיהו לאו נביא וכן לא נכתב ספרו עם ספר הנביאים מפני שהיה עניינו עם גבריאל אף על פי שהיה נראה אליו ומדבר עמו בהקיץ כמו שנאמר במראה של בית שני ועוד אני מדבר בתפלה והאיש גבריאל (דניאל ט כא) וכן המראה של קץ הגאולה (שם י ד) בהקיץ היתה בלכתו עם חביריו על יד הנהר ואין הגר המצרית מכלל הנביאות וברור הוא גם כן שלא היה ענינה בת קול כמו שאמר הרב (במו"נ שם) והכתוב חלק נבואת משה רבינו מנבואת האבות כמה שנאמר (שמות ו ג) וארא אל אברהם אל יצחק ואל יעקב באל שדי וזה שם משמות הקדש לבורא איננו כנוי למלאך ורבותינו עוד למדו על החילוק שביניהם ואמרו (ויק"ר א יד) מה בין משה לכל הנביאים רבנן אמרי כל הנביאים ראו מתוך אספקלריא שאינה מצוחצחת הדא הוא דכתיב (הושע יב יא) ואנכי חזון הרביתי וביד הנביאים אדמה ומשה ראה מתוך אספקלריא מצוחצחת הדא הוא דכתיב (במדבר יב ח) ותמונת ה' יביט כמו שהוא מפורש בויקרא רבה (שם) ומקומות אחרים (יבמות מט) ולא נתנו בשום מקום נבואתם למלאך ואל תשומם בעבור שכתוב (מלכים א יג יח) גם אני נביא כמוך ומלאך דבר אלי בדבר ה' לאמר כי פירושו גם אני נביא כמוך ויודע אני שהמלאך שדבר אלי בדבר ה' הוא וזו מדרגה ממדרגות הנבואה כאשר אמר איש האלהים כי כן צוה אותי בדבר ה' (שם יג ט) ואמר כי דבר אלי בדבר ה' (שם יג יז) וכבר אמרו רבותינו (במד"ר כ ג) בענין בלעם שאמר ועתה אם רע בעיניך אשובה לי (במדבר כב לד) אני לא הלכתי עד שאמר לי הקב"ה קום לך אתם (שם שם כ) ואתה אומר שאחזור כך הוא אומנותו לא כך אמר לאברהם להקריב את בנו ואחר כך ויקרא מלאך ה' אל אברהם ויאמר אל תשלח ידך אל הנער (להלן כב יב) למוד הוא לומר דבר ומלאך מחזירו וכו' הנה החכמים מתעוררים לומר שאין הנבואה בדבור הראשון שהזכיר בו השם שוה לדיבור השני שאמר בו שהוא על ידי מלאך אלא שהוא דרך בנביאים שיצוה בנבואה ויבטל הצואה במלאך כי הנביא יודע כי דבר ה' הוא ובתחלת ויקרא רבה (א ט) אמרו ויקרא אל משה לא כאברהם באברהם כתוב ויקרא מלאך ה' אל אברהם שנית מן השמים (להלן כב טו) המלאך קורא והדבור מדבר ברם הכא אמר הקב"ה אני הוא הקורא ואני הוא המדבר כלומר שלא היה אברהם משיג הנבואה עד הכינו נפשו בתחלה להשגת מלאך ויעלה מן המדרגה ההיא למעלת דבור הנבואה אבל משה מוכן לנבואה בכל עת הנה בכל מקום יתעוררו החכמים להודיענו כי ראיית המלאך איננה נבואה ואין הרואים מלאכים והמדברים עמם מכלל הנביאים כאשר הזכרתי בדניאל אבל היא מראה תקרא "גלוי עינים" כמו ויגל השם את עיני בלעם וירא את מלאך ה' (במדבר כב לא) וכן ויתפלל אלישע ויאמר ה' פקח נא את עיניו ויראה (מלכים ב ו יז) אבל במקום אשר יזכיר המלאכים בשם "אנשים" כענין הפרשה הזאת ופרשת לוט וכן ויאבק איש עמו (להלן לב כה) וכן וימצאהו איש (שם לז טו) על דעת רבותינו (תנחומא וישב ב) הוא כבוד נברא במלאכים יקרא אצל היודעים "מלבוש" יושג לעיני בשר בזכי הנפשות כחסידים ובני הנביאים ולא אוכל לפרש והמקום אשר תמצא בו ראיית ה' ודבור מלאך או ראיית מלאך ודבור ה' ככתוב בדברי משה בתחילת נבואתו (שמות ג ב-ד) ובדברי זכריה (ג א-ב) עוד אגלה בו דברי אלהים חיים ברמיזות (עיין שמות ג ב) וענין ויאכלו אמרו חכמים (ב"ר מח יד) ראשון ראשון מסתלק וענין ההסתלקות תבין אותו מדבר מנוח אם תזכה אליו והנה פירוש הפרשה הזאת אחרי שאמר כי בעצם היום הזה נמול אברהם (לעיל יז כו) אמר שנראה אליו השם בהיותו חולה במילתו יושב ומתקרר בפתח אהלו מפני חום היום אשר יחלישנו והזכיר זה להודיע שלא היה מתכוין לנבואה לא נופל על פניו ולא מתפלל ואף על פי כן באה אליו המראה הזאת
@426 "באלוני ממרא" - להודיע המקום אשר בו נימול וזה גילוי השכינה אליו למעלה וכבוד לו כענין שבא במשכן ויצאו ויברכו את העם וירא כבוד ה' אל כל העם (ויקרא ט כג) כי מפני השתדלותם במצות המשכן זכו לראיית השכינה ואין גלוי השכינה כאן וכאן לצוות להם מצוה או לדבור כלל אלא גמול המצוה הנעשית כבר ולהודיע כי רצה האלהים את מעשיהם כענין שנאמר (תהלים יז טו) אני בצדק אחזה פניך אשבעה בהקיץ תמונתך וכן ביעקב אמר (להלן לב ב) ויפגעו בו מלאכי אלהים ואין שם דבור ולא שחדשו בו דבר רק שזכה לראיית מלאכי עליון וידע כי מעשיו רצויים וכן היה לאברהם בראיית השכינה זכות והבטחה וכן אמרו (מכילתא שירתא ג) ביורדי הים שאמרו "זה אלי ואנוהו" ראתה שפחה על הים מה שלא ראה יחזקאל הנביא זכות להם בעת הנס הגדול שהאמינו בה' ובמשה עבדו ופעמים יבא בשעת הקצף ויאמרו כל העדה לרגום אותם באבנים וכבוד ה' נראה באהל מועד אל כל בני ישראל (במדבר יד י) ויהיה זה להגין על עבדיו הצדיקים ולכבודם ואל תחוש להפסק הפרשה כי הענין מחובר ולכן אמר "וירא אליו" ולא אמר "וירא ה' אל אברהם" אבל בפרשה רצה לסדר כבוד הנעשה לו בעת שעשה המילה ואמר כי נגלית עליו השכינה ושלח אליו מלאכיו לבשר את אשתו וגם להציל לוט אחיו בעבורו כי אברהם נתבשר בבן מפי השכינה כבר ושרה מפי המלאך שדבר עם אברהם כדי שתשמע שרה כמו שאמר ושרה שומעת וזו כוונתם שאמרו (סוטה יד) לבקר את החולה שלא היה לדבור אלא לכבוד לו ועוד אמרו (ב"ר מח ד) מזבח אדמה תעשה לי (שמות כ כד) ומה אם זה שבנה מזבח לשמי הריני נגלה עליו ומברכו אברהם שמל עצמו לשמי על אחת כמה וכמה ושמא כיוונו עוד בזה לומר שהיה לו במראה השכינה רפוי למחלת המילה כי כן ראוי להיות כדכתיב (משלי טז טו) באור פני מלך חיים וטעם נצבים עליו שהיו עומדים לנגדו מסתכלים כלשון הנצב על הקוצרים (רות ב ה) משרי הנצבים (מלכים א ה ל) ולפי שהוא יושב והם היו עומדים ורואים בו אמר "עליו" וזה טעם וירא וירץ לקראתם כי כאשר ראה אותם עומדים נגדו ולא היו הולכים לדרכם רץ לקראתם להביאם אל ביתו וטעם מפתח האהל להגיד שהיה עדיין יושב שם אחרי הסתלק ממנו מראה השכינה ויתכן שיהיה "עליו" על האהל שהיו קרובים אליו מן הצד האחר שלא כנגד הפתח והיו שם נצבים ולא היו מתקרבין אל אברהם כטעם חונים על הים (שמות יד ט)
@428 **אדני אם נא מצאתי חן בעיניך** . מצינו אותו בספרים קמוץ והנה קראם בשם רבם באל"ף דל"ת כי הכיר בהם שהם מלאכי עליון כאשר יקראו אלהים ואלים ולכן השתחוה להם ארצה
@428 "אל נא תעבור מעל עבדך" - עם כל אחד ידבר כדרך כל התורה ושמרתם את (כל) חקתי (ועשיתם אותם) ערות אביך וערות אמך לא תגלה (ויקרא יח ה ז) ובקצרכם את קציר ארצכם לא תכלה (שם יט ט) ובקשתם משם את ה' אלהיך ומצאת כי תדרשנו בכל לבבך ובכל נפשך (דברים ד כט) ורוב משנה התורה כן והפך מזה ראה אנכי נותן לפניכם היום (שם יא כו) ורבותינו אמרו (ב"ר מח ו) לגדול שבהם אמר וגם זה יתכן שאמר לגדול אל נא תעבור ואתה ורעיך אשר ישארו עמך תרחצו רגליכם והנכון בעיני שקרא את כולם אדונים ופנה אל כל אחד ואחד לראשון אמר אם נא מצאתי חן בעיניך אל נא תעבור וכן אמר לשני וכן אמר לשלישי לכל אחד בפני עצמו יתחנן אם נא מצאתי חן בעיניך אל נא תעבור מעל עבדך ויוקח נא מעט מים ורחצו רגליכם כלכם וזה דרך מוסר וכבוד מרוב חפצו להתנדב עמהם והנה הכיר בהם שהם עוברי דרך ואין חפצם ללון שם ולכן לא בקש מהם רק שיוקח מעט מים לרחוץ רגליהם מעט מפני החום לתת מים קרים על נפש עיפה וישענו תחת העץ לרוח היום לא יבואו באהל ובמשכן
@430 **כי על כן עברתם** . כי אחרי שדרככם עלי איננו נכון שלא תנוחו מעט אצלי כן תעשה כאשר דברת דרך מוסר שבפת לחם די לשון רבי אברהם או יאמר כן תעשה לנו להשען תחת העץ ולעבור מיד כי שלוחים אנחנו ואל תעכבנו לבא באהל או ללון עמך
@431 **קמח סלת** . סלת לעוגות קמח לעמילן של טבחים לכסות את הקדרה לשאוב את הזוהמא לשון רש"י וכך הוא בבראשית רבה (מח יב) ושם פירשו שהיו שלש סאים לכל אחד ולא ידענו למה הרבה בלחם כל כך לשלשה אנשים אולי ידע הסתלקות המאכל ראשון ראשון והוא כמרבה עולות למזבח או שסעדו גדולי ביתו עמהם לכבודם ועל דרך הפשט מהרי שלש סאים קמח לעשות מהן סלת והנה הוציאה מכל השלש סאין סלת נקיה מעט
@432 **וטעם ואל הבקר רץ אברהם** . להגיד רוב חשקו בנדיבות כי האדם הגדול אשר היו בביתו שמונה עשר ושלש מאות איש שולף חרב והוא זקן מאד וחלוש במילתו הלך הוא בעצמו אל אהל שרה לזרז אותה בעשיית הלחם ואחרי כן רץ אל מקום הבקר לבקר משם בן בקר רך וטוב לעשות לאורחיו ולא עשה כל זה על יד אחד ממשרתיו העומדים לפניו
@435 **שוב אשוב אליך כעת חיה** . לשון רש"י לא בשרו המלאך שישוב אליו אלא בשליחותו של מקום אמר לו כמו ויאמר לה מלאך ה' הרבה ארבה את זרעך (לעיל טז י) והוא אין בידו להרבות אלא בשליחותו של מקום אמר לו אף כאן בשליחותו של מקום אמר לו והוצרך הרב לאמר כן מפני שהקב"ה אמר לו בכאן למועד אשוב אליך ובין במלאך או בהקב"ה לא מצינו ששב אליו למועדו אולי נכלל בלשון וה' פקד את שרה כאשר אמר ויעש ה' לשרה כאשר דבר (להלן כא א) ורבי אברהם אמר (להלן כא ב) כי "ויאמר ה' אל אברהם" הוא דבר המלאך בשם שולחו ושב אליו למועד אשר דבר אתו ואם לא נכתב והנכון בעיני שהוא מן "לתשובת השנה" ( יא א) יאמר כי שוב אשוב אליך עת כעת הזאת שתהיו בו חיים ויהיה בן לשרה אשתך וזהו כאשר נאמר לאברהם (לעיל יז כא) למועד הזה בשנה האחרת ויהיה "אשוב" כמו ושב ה' אלהיך ושב וקבצך (דברים ל ג)
@436 **באים בימים** . האדם בימי בחורותיו יקרא "עומד בימים" ויקראו "ימיו" כי הם שלו כלשון את מספר ימיך אמלא (שמות כג כו) אבל כאשר יזקין ויחיה ימים רבים מרוב בני האדם בדורו יקרא "בא בימים" מפני שהוא כבא בארץ אחרת נוסע מעיר ובא אל עיר מיום אל יום חדל להיות לשרה אורח כנשים הוא הזמן להריון כי אחרי הפסק האורח מחמת זקנה לא תהרינה
@438 **ואני זקנתי** . הוא פירוש אחרי בלותי ודבריו אמת אך מפני השלום לא רצה לגלות מה שאמרה "ואדוני זקן" כי היה ראוי שיאמר "ואני ואדוני זקנים" כי שרה בשניהם תצחק
@439 **היפלא מה' דבר** . אם דבר נפלא ורחוק הוא שיהיה מאת ה' ככה כלשון כי ממך הכל ומידך נתנו לך (דהי"א כט יד) ודומה לזה מאשר שמנה לחמו (להלן מט כ) מאת אשר תבא לחם שמנה ואונקלוס תרגם היתכסי עשאו כלשון כי יפלא ממך דבר למשפט (דברים יז ח) ואם כן יש בו סוד נעלם ולשון רש"י היפלא היתכסי וכי שום דבר מופלא ומכוסה ממני מלעשות כרצוני הרכיב בו שני ענינים
@440 **ותכחש שרה לאמר** . אני תמה בנביאה הצדקת איך תכחש באשר אמר השם לנביא וגם למה לא האמינה לדברי מלאכי אלהים והנראה בעיני כי המלאכים האלה הנראים כאנשים באו אל אברהם והוא בחכמתו הכיר בהם ובשר אותו שוב אשוב אליך ולשרה בן ושרה שומעת ולא ידעה כי מלאכי עליון הם כענין באשת מנוח (שופטים יג ו) ואולי לא ראתה אותם כלל
@440 "ותצחק בקרבה" - ללעג כמו יושב בשמים ישחק ה' ילעג למו (תהלים ב ד) כי השחוק לשמחה הוא בפה אז ימלא שחוק פינו (שם קכו ב) אבל השחוק בלב לא יאמר בשמחה והקב"ה האשים אותה לאברהם למה היה הדבר נמנע בעיניה וראוי לה שתאמין או שתאמר "אמן כן יעשה ה'" והנה אברהם אמר אליה למה צחקת היפלא מה' דבר ולא פירש אליה כי השם גילה אליו סודה והיא מפני יראתו של אברהם תכחש כי חשבה שאברהם בהכרת פניה יאמר כן או מפני ששתקה ולא נתנה שבח והודאה בדבר ולא שמחה והוא אמר לא כי צחקת אז הבינה כי בנבואה נאמר לו כן ושתקה ולא ענתה אותו דבר וראוי שנאמר עוד כי אברהם לא גילה לה הנאמר לו מתחילה (לעיל יז יט) אבל שרה אשתך יולדת לך בן אולי המתין עד שלוח השם אליה הבשורה ביום מחר כי ידע כי לא יעשה ה' אלהים דבר כי אם גלה סודו אל עבדיו הנביאים (עמוס ג ז) או מרוב זריזותו במצות היה טרוד במילתו ומילת עם רב אשר בביתו ואחר כן בחולשתו ישב לו פתח האהל והמלאכים באו טרם שהגיד לה דבר
@442 **וה' אמר** . אל צבא השמים העומדים עליו או אל המלאכים השלוחים ויתכן שהוא המחשבה כי חשב שלא יתכסה ממנו מפני הטעמים הללו וכן ואני אמרתי בדמי ימי (ישעיהו לח י) וכן ויאמר להכות את דוד ( כא טז) וכן כל אמירה עם הלב מחשבה
@443 **ואברהם היו יהיה** . מדרש אגדה זכר צדיק לברכה הואיל והזכירו ברכו ופשוטו של מקרא וכי ממנו אני מעלים והלא חביב לפני להיות לגוי עצום לשון רש"י והנכון כי השם יתברך דבר בכבוד אברהם אמר הנה הוא עתיד להיות לגוי גדול ועצום ויהיה זכרו בזרעו ובכל גויי הארץ לברכה לכן לא אכסה ממנו כי יאמרו הדורות הבאים איך כיסה ממנו או איך נתאכזר הצדיק על שכיניו החונים עליו ולא ריחם ולא התפלל עליהם כלל והגלוי אליו טוב ויפה כי ידעתי בו שהוא מכיר ויודע שאני ה' אוהב צדקה ומשפט כלומר שאני עושה משפט רק בצדקה ולכך יצוה את בניו וביתו אחריו לאחוז דרכי והנה אם בדרך צדקה ומשפט יפטרו יתפלל לפני להניחם וטוב הדבר ואם חייבין הם לגמרי גם הוא יחפוץ במשפטם ולכן ראוי שיבא בסוד ה'
@444 **כי ידעתיו למען אשר יצוה** . לשון רש"י ארי ידעתיניה כתרגומו לשון חבה כמו מודע לאישה (רות ב א) ואדעך (שמות לג יז) אמנם עיקר כולם לשון ידיעה שהמחבב את האדם ומקרבו אצלו יודעו ומכירו ואם תפרשהו יודע אני בו שיצוה את בניו אין "למען" נופל על הלשון ויתכן שיהיה "ידעתיו" גדלתיו ורוממתיו בעבור אשר יצוה את בניו אחריו לעשות את הישר לפני ולכך אשימנו לגוי גדול ועצום שיעבדוני וכמוהו ידעתיך בשם (שמות לג יב) מה אדם ותדעהו (תהלים קמד ג) או יאמר "ידעתיו שיצוה" וכן למען ינוח שורך וחמורך (שמות כג יב) שינוח והנכון בעיני שהיא ידיעה בו ממש ירמוז כי ידיעת השם שהיא השגחתו בעולם השפל היא לשמור הכללים וגם בני האדם מונחים בו למקרים עד בא עת פקודתם אבל בחסידיו ישום אליו לבו לדעת אותו בפרט להיות שמירתו דבקה בו תמיד לא תפרד הידיעה והזכירה ממנו כלל כטעם לא יגרע מצדיק עיניו (איוב לו ז) ובאו מזה פסוקים רבים כדכתיב (תהלים לג יח) הנה עין ה' אל יראיו וזולת זה
@445 **ויאמר ה' זעקת סדום ועמורה** . לשון רש"י ויאמר ה' אל אברהם שעשה כאשר אמר שלא יכסה ממנו ואמר רבי אברהם כי נכנס פסוק "ויפנו משם האנשים" בנתים להודיע כי בעת שבאו לסדום אז אמר השם לאברהם "זעקת סדום ועמורה כי רבה" וכן דעת כל המפרשים כי עם אברהם ידבר ולפי זה הנכון בפסוק "ויפנו משם האנשים" לומר כי כאשר אמר השם לאברהם בנסוע האנשים ממנו "זעקת סדום ועמורה כי רבה" עמד אברהם בתפלה ותחנה לפניו למחול להם ולתת לו רשות לדבר והאריך בתפלתו עד שבאו האנשים סדומה ואז נגש אברהם ואמר "האף תספה" או יהיה פירושו ששב לבאר "עודנו עומד לפני ה'" כי נגש אברהם ואמר "האף תספה" והנה האריך בתחינה לפניו בכל פעם לאמר "אל יחר אף ה'" והיה עוד מכוין דעתו בכל פעם לנבואה עד ששמע תשובה לדבריו מפיו של הקדוש ברוך הוא והאריכו כל היום בזה וילך ה' בערב כאשר כלה לדבר אל אברהם ובאו שני המלאכים סדומה
@445 "זעקת סדום ועמורה" - היא זעקת עשוקים יזעקו וישועו מזרוע רשעתם והיה ראוי שיאמר הכתוב זעקת סדום ועמורה שמעתי כי רבה או שיאמר זעקת סדום ועמורה רבה וחטאתם כבדה מאד אבל ענין הכתוב זעקת סדום ועמורה וחטאתם שגדלו מאד ארד ואראה אם כלם חטאו בהם ואם לא אדעה מי החוטאים וענין הירידה והראיה אמר רש"י בדרך הדרש לימד שלא יפסקו דיני נפשות אלא בראיה ועל דרך הפשט מפני שרצה הקב"ה לגלות לאברהם עניין סדום ולהודיעו כי אין בהם עושה טוב אמר אליו זעקת סדום ועמורה כי רבה ארד לראות כלומר באתי לשפוט אם חטאו אעשה בהם כלה ואם לא אדעה מה אעשה בהם ופקדתי בשבט פשעם ובנגעים עונם הודיעו כי אין עוד נגמר דינם וכי עתה יפקוד עונם וישפוט אותם וזה כלשון ה' משמים השקיף על בני אדם לראות היש משכיל דורש את אלהים הכל סר יחדיו נאלחו (תהלים יד ב ג) ורבי אברהם אמר בו סוד מילדי נכרים יספיקו בו ואני ארמוז לך דעת מקבלי האמת דרשו רבותינו (ירושלמי תענית פ"ב) בפסוק כי הנה ה' יוצא ממקומו וירד ודרך על במתי ארץ (מיכה א ג) יוצא ובא לו ממדה למדה יוצא ממדת רחמים ובא לו למדת הדין וכן הענין הזה ויאמר ה' אל לבו זעקת סדום ועמורה כי רבה ארד ממדת רחמים אל מדת הדין (זהר קה) ואראה ברחמים אם כצעקתה הבאה אלי במדת הדין עשו כלה (שם קו) ואם לא אדעה וארחם כדרך וידע אלהים (שמות ב כה) ואחר שסיפר הכתוב דעת העליון חזר אל הענין הראשון וסיפר במעשה כי האנשים אשר השקיפו על פני סדום ללכת שמה ושלחם אברהם הגיעו שמה ואברהם מעת הפרדם ממנו ועד הגיעם שם עודנו עומד לפניו כי קראו והגיד לו כי המלאכים הם השלוחים האלה להשחית המקום כאשר אמר ולא הוצרך לפרש מתי עמד לפניו כי מעת שאמר "המכסה אני מאברהם" נודע שהגיד לו
@448 **ויגש אברהם ויאמר האף תספה צדיק עם רשע** . אפו של הקדוש ברוך הוא היא מדת דינו וחשב אברהם שהיא תספה צדיק עם רשע לא ידע מחשבות ה' אשר חשב עליהם ברחמיו כאשר פירשתי ולכן אמר כי הגון וטוב הוא שישא לכל המקום למען חמשים הצדיקים אבל לא יתכן גם במדת הדין להמית צדיק עם רשע שאם כן יהיה כצדיק כרשע ויאמרו שוא עבוד אלהים וכל שכן במדת רחמים שהוא שופט כל הארץ והוא העושה משפט כענין ויגבה ה' צבאות במשפט (ישעיהו ה טז) ואמרנו (ברכות יב) המלך המשפט וזהו ענין הכפל חלילה לך והקב"ה הודה שישא לכל המקום בעבורם כי במדת רחמים יתנהג עמהם ומה שיודיע אליך כל הענין היות ויאמר ה' כתוב יו"ד ה"א וכל אשר הזכיר אברהם אל"ף דל"ת והנה זה מבואר
@449 **חמשים צדיקים** . כתב רש"י עשרה לכל כרך וכרך התשחית בחמשה תשעה לכל כרך וכרך ואתה צדיקו של עולם תצטרף עמהם אולי ימצאון שם ארבעים וימלטו ארבעה כרכים וכן שלשים יצילו שלשה ועשרים יצילו שנים ועשרה יצילו אחד ולא בקש על פחות מעשרה שדור המבול היו שמנה צדיקים ולא הצילו על דורן ותשעה על ידי צירוף כבר ביקש ולא מצא כל אלו דברי הרב ז"ל ואני תמה אם כן מה התפלה והתחינה הזאת אשר היה מתחנן בכל פעם ופעם "אל נא יחר לאדני" ו "הנה נא הואלתי" והלא ראוי הוא שיהיו ארבעים מצילין ארבעה ושלשים והעשרים יצילו לפי חשבון כאשר החמשים יצילו חמש וכן מה שאמר כי תשעה על ידי צירוף כבר בקש ולא מצא והלא לארבעים וחמשה היה מבקש הצירוף ולא היו שם ארבעים וחמשה אבל תשעה אולי ימצאון שם והנה דעת הרב לומר שהרבים ראוין להצלה גדולה יותר מאשר יצילו המועטים אפילו הצלה מועטת כמו שאמרו (ת"כ בחקותי) אינו דומה מועטין העושין את התורה למרובים העושין את התורה והנה הודה הקב"ה שיצילו ארבעים וחמשה בצירוף צדיקו של עולם כל הכרכין כאילו היו חמשים שלמין ומעתה כשיהיו מ' צדיקים מצילין ארבעה אף בצירוף הצדיק יתעלה ינצלו וכן השלשים והעשרים והעשרה שכבר הודה בצירוף הזה ואם תאמר שהודה בו עם ארבעים וחמשה שהם רבים ושמא לא יודה בצירוף עם המועטין כמו שאמרנו צדקת ה' ראויה היא להצטרף ולהציל כיון שהודה שלא יבדיל בין רב למעט זה דעת הרב ודרך פשט הכתובים סלולה שאמר תחילה חמשים לתת חשבון שלם של עשרה לכל אחד ואחד וחזר ופחת כמו שיכול ולהציל הכל היה אומר ולא ידעתי מי הכניסו לרב במה שאמר
@451 **בתוך העיר** . פירש רבי אברהם שיהיו יראים את השם בפרהסיא וכן שוטטו בחוצות ירושלם (ירמיהו ה א) והנכון בעיני כי אברהם אמר "בתוך העיר" לאמר שאפילו יהיו נכרים בתוכה ראוי שיצילוה ואמר זה בעבור לוט וחשב אולי יש אחרים שם
@453 **לא אשחית אם אמצא שם** . יבטיח אותו שלא ישחית אם ימצאון שם כן ולא היה אומר לו "דע שאין שם כמספר הזה שאמרת" לפי שעדיין לא נגמר דינם כאשר אמר ארדה נא ואראה והנה אברהם לא ידע מה יעשה בהם ולכן השכים בבקר והשקיף על פני סדום ובראותו כי נשחתו ידע שלא היו שם כן
@460 **הנה נא אדוני** . לשון רש"י הנה נא אתם אדונים לי אחר שעברתם עלי והנכון שהוא לשון תחינה אדני הנה נא בית עבדכם סורו נא אלי ומלת "סורו" כמו סורה שבה פה (רות ד א) סורה אדני סורה אלי אל תירא (שופטים ד יח) וטעם והשכמתם והלכתם לדרככם להגיד להם שלא יתעכבו בעיר אחר הבקר כי ידע בענין אנשי העיר ורשעם אבל היה חושב כי באור הבקר יעשוה או שראה אותם כהולכי ארחות לא יתעכבו בעיר ואמר והשכמתם והלכתם לדרככם אם תרצו
@461 **ויפצר בם מאד** . היה ללוט זכות בהפצירו בהם והיה לו חפץ טוב בהכנסת אורחים והיו ממאנים כדי לזכותו ולכן שמעו לו בסוף כי מתחלה לא היו רוצים לבא לביתו כי אינו צדיק תמים ורבותינו אמרו (ב"מ פז) מסרבין לקטן ואין מסרבין לגדול ואם כן יהיה כדרך מוסר בני אדם
@463 **ונדעה אותם** . כוונתם לכלות את הרגל מביניהם כדברי רבותינו (סנהדרין קט) כי חשבו שבעבור טובת ארצם שהיא כגן ה' יבאו שם רבים והם היו מואסי הצדקה אבל לוט בעשרו וממונו בא אליהם או שבקש מהם רשות או שקבלוהו לכבוד אברהם והכתוב מעיד שזאת כוונתם שנאמר (יחזקאל טז מט) הנה זה היה עון סדום אחותך גאון שבעת לחם ושלות השקט היה לה ולבנותיה ויד עני ואביון לא החזיקה ומה שאמר (לעיל יג יג) רעים וחטאים לה' מאד שהיו מכעיסים ומורדים בשלותם ובענוי האביונים והוא שאמר (יחזקאל טז נ) ותגבהינה ותעשינה תועבה לפני ואסיר אתהן כאשר ראיתי ועל דעת רבותינו (עיין סנהדרין קט) היו בהם כל מדות רעות אבל נגמר דינם על אותו העון מפני שלא החזיקו יד עני ואביון כי היו תדירים באותו עון יותר מכולם וגם כי כל העמים עושים צדקות עם ריעיהם ועם ענייהם לא היה בכל הגוים כסדום לאכזריות ודע כי משפט סדום היה למעלת ארץ ישראל כי היא מכלל נחלת ה' ואינה סובלת אנשי תועבות וכאשר תקיא את הגוי כלו מפני תועבותם הקדימה וקאתה את העם הזה שהיו רעים מכולם לשמים ולבריות ושממו עליהם השמים והארץ והושחתה הארץ בלא רפואה לעולם מפני שבעבור טובה נתגאו וראה הקב"ה שיהיה לאות לבני מרי לישראל העתידים לירשה כאשר התרה בהן גפרית ומלח שרפה כל ארצה כמהפכת סדום ועמורה אדמה וצבויים אשר הפך ה' באפו ובחמתו (דברים כט כב) כי יש באומות רעים וחטאים מאד ולא עשה בהם ככה אבל למעלת הארץ הזאת היה הכל כי שם היכל ה' ועוד אני עתיד לבאר זה בסדר אחרי מות (ויקרא יח כד) אם יחייני הממית והמחיה
@466 **אוציאה נא אתהן אליכם** . מתוך שבחו של האיש הזה באנו לידי גנותו שהיה טורח מאד על אכסניא שלו להציל אותם מפני שבאו בצל קורתו אבל שיפייס אנשי העיר בהפקר בנותיו אין זה כי אם רוע לב שלא היה ענין הזמה בנשים מרוחק בעיניו ולא היה עושה לבנותיו חמס גדול כפי דעתו לכך אמרו רבותינו (תנחומא וירא יב) בנוהג שבעולם אדם מוסר עצמו על בנותיו ועל אשתו והורג או נהרג וזה מוסר בנותיו להתעולל בהן אמר לו הקב"ה לעצמך אתה משמרן והנה לוט היה מתירא עליהם כי היה חושב שהם אנשים אבל כאשר הכו בסנורים את אנשי העיר ואמרו לו כי משחיתים אנחנו את המקום הזה וישלחנו ה' לשחתה אז הכיר בהם והאמין לעשות כל אשר צוו ודע והבן כי ענין פילגש בגבעה (שופטים יט) אף על פי שהוא נדמה לענין הזה איננו כמוהו לרוע כי הרשעים ההם לא היה דעתם לכלות הרגל ממקומם אבל היו שטופי זמה ורצו גם במשכב האיש האורח וכאשר הוציאו אליהם פילגשו נתפייסו בה והאיש הזקן שאמר להם הנה בתי הבתולה ופילגשהו אוציאה נא אותם ועשו להם הטוב בעיניכם (שם יט כד) יודע היה שלא יחפצו בבתו ולא יעשו עמה רעה ועל כן לא אבו לשמוע לו וכאשר הוציא את פילגשו לבדה שתקו ממנו והאיש בעל הבית גם האורח כולם היו חפצים להציל את האיש בפילגשו כי פילגש היתה לא אשת איש וכבר זנתה עליו ובפרץ ההוא עוד לא היו בו כל אנשי העיר כאשר בסדום שנאמר בו "מנער ועד זקן כל העם מקצה" אבל בגבעה נאמר והנה אנשי העיר "אנשי בני בליעל" (שם יט כב) מקצתם שהיו שרים ותקיפים בעיר כמו שאמר האיש (שם כ ה) ויקומו עלי בעלי הגבעה ועל כן לא מיחו האחרים בידם והנה פנות כל העם מכל שבטי ישראל רצו לעשות גדר גדול בדבר להמית אותם שנאמר (שם כ יג) ועתה תנו את האנשים בני בליעל אשר בגבעה ונמיתם ודבר ברור הוא שלא היו חייבין מיתה בדין תורה שלא עשו מעשה זולתי ענוי הפילגש הזונה ולא נתכוונו למיתה שלה וגם לא מתה בידם וישלחוה מאתם כעלות השחר והלכה מאתם לבית אדוניה ואחר כך מתה אולי נחלשה מרוב הביאות ונתקררה בפתח עד האור ומתה שם אבל מפני שהיו חפצים ואומרים לעשות נבלה כאנשי סדום ראו השבטים לעשות סייג לתורה שלא יעשה ולא יאמר כן בישראל כמו שאמרו ונבערה רעה מישראל (שם) וזה הדין הוא ממה שאמרו רבותינו (סנהדרין מו) בית דין מכין ועונשין שלא מן התורה ולא לעבור על דברי תורה אלא לעשות סייג לתורה ושבט בנימין לא הסכימו בדבר זה שלא היה בהם חיוב מיתה בענוי הפלגש ואולי הקפידו עוד בני בנימין על אשר לא שלחו להם מתחילה ועשו ההסכמה שלא מדעתם ולפי דעתי שזה ענשם של ישראל להנגף בתחילה מפני שלא היתה המלחמה נעשית מן הדין והגדר עצמו על שבט בנימין היה מוטל לעשותו ולא עליהם שמצוה על השבט לדון את שבטו (ספרי קמד) והנה שתי הכתות ראויות להענש כי בנימין מרשיע שאינו חושש ליסר הרעים ולא לגעור בהם כלל וישראל עושין מלחמה שלא מן הדין וגם את פי ה' לא שאלו בזה אבל אמרו מי יעלה לנו בתחלה למלחמה על בני בנימין (שופטים כ יח) כי מעצמם הסכימו למלחמה על כל פנים וכן לא שאלו בענין הנצוח "אם תתנם בידי" כי בטחו בזרוע בשר שהיו רבים מאד כי עתה כמוהם עשרה פעמים ויותר ולא שאלו אלא "מי יעלה לנו בתחלה" והוא כמו גורל ביניהם אולי היה כל שבט אומר "לא אעלה אני תחלה" או אומר "אני ראשון" והקב"ה השיב כפי שאלתם יהודה בתחלה לאמור כי יהודה הוא בראש לעולם כי ביהודה בחר ה' לנגיד (דהי"א כח ד) ולכך לא אמר "יהודה יעלה" כשאר המקומות (עיין שופטים א ב) כי לא הרשה אותם אבל לא מנעם ולא אמר להם "לא תעלו ולא תלחמו" מפני ענשו של בנימין והנה הלך השם עם שניהם בקרי והניחם למקרים ובני בנימין היו גבורים ועריהם בצורות והשחיתו בישראל הבוטחים בזרוע בשר והוסיפו עונש על ענשם כי די היה להם להבריח ישראל מן הגבעה והם הכו בהם למשחית איבת עולם והפילו מהם עם רב ועצום כ"ב אלפים והנה ישראל כאשר הכו מכה רבה נודעה להם שגגתם כי עשו מלחמה עם אחיהם שלא ברשות גבוה ושלא כדין תורה ועל כן שאלו ביום השני האוסיף לגשת למלחמה עם בני בנימין אחי (שם כ כג) והזכירו עתה האחוה לשאול אם הוא אוסר עליהם המלחמה והשם הרשה אותם עתה ביום השני ואמר עלו אליו כי עתה מותר להם לדרוש דם אחיהם השפוך והם לא שאלו הנצוח כי עדיין היו בוטחים ברובם לנצח על כל פנים והשם לא באר להם רק כי המלחמה מותרת להם ומפני שעדיין לא נתכפר ענשם הראשון נפלו מהם גם ביום השני י"ח אלפים וביום השלישי גזרו תענית ויצומו ויבכו לפני ה' והקריבו עולות לכפר על הרהורי הלב אשר בטחו בזרועם והקריבו שלמים והם שלמי תודה כי ראו עצמם כאלו כלם פלטים מחרב בנימין וזה משפט כל הנמלטים להקריב תודה כענין שנאמר (תהלים קז כב) ויזבחו זבחי תודה ויספרו מעשיו ברנה וכתוב (שם כז ו) ועתה ירום ראשי על אויבי סביבותי ואזבחה באהלו זבחי תרועה אשירה ואזמרה לה' והנה היו בשני הימים המתים מישראל ארבעים אלף ומבנימן נפלו בסוף כ"ה אלפים אנשי חיל (שופטים כ לה) ומעיר מתום עד כל הנמצא (שם כ מח) רבים ויתכן שיהיו ט"ו אלפים בין אנשים ונשים והטף והיה עונש שתי הכתות בשוה ומה נכבדו דברי רבותינו (סנהדרין קג) שהיה הקצף בפסלו של מיכה אמר הקב"ה בכבודי לא מחיתם בכבוד בשר ודם מחיתם לומר בכבודי לא מחיתם במחוייבי מיתה ופושטים ידיהם בעיקר בכבוד בשר ודם מחיתם יותר משורת הדין ועל כן סכל עצת שתי הכתות ואמץ את לבבם ולא זכרו ברית אחים ואחר המעשה נתחרטו כמו שנאמר (שופטים כא ב) ויבא העם בית אל וישבו שם עד הערב לפני האלהים ויבכו בכי גדול ויאמרו למה ה' אלהי ישראל היתה זאת בישראל להפקד היום מישראל שבט אחד כי הכירו טעותם וענשם והנה בדרך גררא פירשנו ענין מהותם ואינו מבואר והזכרנו סיבותיו
@467 **ויפצרו באיש בלוט** . לא מצאתי המלה הזאת רק בדברי הפיוסים אם כן נפרש זה שפייסו ממנו הרבה שיפתח להם הדלת וכאשר לא רצה לעשות כן נגשו לשבור אותו או שהיה עומד בפני הדלת ולא היה מניחם לקרבה אליו והם פייסו ממנו לסור מפניהם כי לא היו רוצים לפגוע בו וזה טעם גש הלאה שיגש למקום אחר
@470 **חתן ובניך ובנותיך** . לשון רש"י מי משלך עוד בעיר חוץ מאשתך ובנותיך שבבית אם יש לך חתן או בנים ובנות הוצא מן המקום ואם כן יהיה דבורם כדרך בני אדם שהוא לא היה לו בנים כי אם בנות ורבי אברהם אמר חתן ובניך חתנים שהם כבניך ויתכן שהיו לו בנים גדולים נשואי נשים ודיבר עם חתניו תחילה כי היה סבור שבניו ישמעו לו וכאשר צחקו עליו חתניו וארכו הדברים ביניהם השחר עלה והמלאכים לא הניחוהו לקחת רק הנמצאים אתו בבית והנה זכותו של לוט היה מציל בנים ובנות וחתנים לא כאשר חשב אברהם שימית צדיק עם רשע וברור הוא שהיו המלאכים יודעים דעת עליון בזה כי גם צוער בתפלתו נמלטה ויתכן שהיה זה לכבוד האכסניא כי דרך מוסר לשלוחים להציל בעל ביתם וכל אשר לו כאשר עשו שלוחי יהושע (יהושע ו כג) שהצילו גם כל משפחת בעלת ביתם ובבראשית רבה (נ כא) לוט על ידי שכבד את המלאך נשא לו פנים
@474 **ויחזיקו האנשים** . אמר רבי אברהם כי ויחזיקו יבאר שפחד ואין בו כח לברוח והנכון שהוא כמו ותחזק מצרים על העם למהר לשלחם מן הארץ (שמות יב לג) אף כאן היו מושכים בהם בחזקה למהר לשלחם
@474 "בחמלת ה' עליו" - לא בזכותו רק בחמלת האל וברחמיו הרבים או יאמר שהחזיקו בו למהר להוציאם בעוד החמלה עליו פן יצא הקצף מלפני ה' ויספה
@475 **אל תביט אחריך ואל תעמוד בכל הככר** . שיעור הכתוב אל תעמוד בכל הככר ואל תביט אחריך אחר שתנצל כי עד היות לוט בהר לא תרד עליהם רעה ובעבור כן אמר
@475 "ואנכי לא אוכל להמלט ההרה פן תדבקני הרעה" - בהיותי בככר כי אתה לא תאריך לי רק מעט כאשר אמרת מהר המלט ואמר רבי אברהם אל תביט אחריך אתה וכל אשר לך וכן לא תאכל ממנו ומה צורך לזה ואין העונש בכאן מפני שיעברו על אזהרת המלאך אבל הוא הזהירם מדעתו שיגיע להם עונש בהבטה ההיא והוא הזהיר את לוט לזכותו וכל השומע ונזהר הוא את נפשו הציל וענין איסור ההבטה אמר רש"י אתה הרשעת עמהם ובזכות אברהם אתה ניצל אינך רשאי לראות בפורענותן ועוד בו ענין כי הראות באויר הדבר ובכל החליים הנדבקים יזיק מאד וידביקם וכן המחשבה בהם ולכן יסגר האיש המצורע וישב בדד (ויקרא יג מו) וכן נשוכי חיות השוטות ככלב השוטה וזולתו כאשר יראו המים וכל מראה יחזו בהם דמות המזיק וישתטו וימותו כמו שאמרו במסכת יומא (פד) והזכירוהו אנשי הטבע ולכן היתה אשתו של לוט נציב מלח כי באתה המכה במחשבתה כאשר ראתה גפרית ומלח היורד עליהן מן השמים ודבקה בה וקרוב אני לומר כי בהשחית ה' את הערים האלה היה המלאך המשחית עומד בין הארץ ובין השמים נראה בלהב האש כענין במלאך המשחית אשר ראה דוד (דהי"א כא טז) ולכן אסר להן ההבטה ובפרקי דרבי אליעזר (כה) כענין הזה אמרו להם אל תביטו לאחוריכם שהרי ירדה שכינתו של הקב"ה להמטיר על סדום ועל עמורה גפרית ואש עירית אשתו של לוט נכמרו רחמיה על בנותיה הנשואות בסדום והביטה לאחריה לראות אם הולכות הן אחריה וראתה אחורי השכינה ונעשית נציב מלח
@482 **וה' המטיר על סדום** . כתב רש"י בכל מקום שנאמר וה' הוא ובית דינו מאת ה' ולא כתב מאתו דרך מקראות לדבר כן נשי למך (לעיל ד ג) ולא אמר נשי ודוד אמר קחו עמכם מעבדי אדניכם (מלכים א א לג) ולא אמר מעבדי ואחשורוש כתבו בשם המלך (אסתר ח ח) ולא אמר בשמי ואני תמה על הרב ז"ל שכתב מן ההגדות דעות חלוקות ומשוה אותם שזה מחלוקת הוא בבראשית רבה (נא ב) ושם עוד דעת שלישית אבא חלפי ברבי סמקי בשם רבי יהודה ב"ר סימון וה' המטיר על סדום זה גבריאל מאת ה' מן השמים זה הקב"ה אמר רבי אלעזר כל מקום שנאמר וה' הוא ובית דינו אמר רבי יצחק בתורה בנביאים ובכתובים מצינו שההדיוט מזכיר שמו שני פעמים בתורה ויאמר למך לנשיו וגו' הנה אלו שלש מחלוקות בדבר שרבי יהודה ב"ר סימון ייחס השם הראשון לגבריאל שהוא השליח לשחת ונקרא השליח בשם השולח ורבי אלעזר אמר כי הוא ובית דינו הסכימו במשפט ומאתו בא ורבי יצחק אמר שהוא דרך הלשון ואם הבינות מה שכתבתי למעלה תדע כוונתם ב"הוא ובית דינו" ויהיה פשוטו של מקרא ברור לפניך וכן וה' אמר (לעיל יח יז) ושמרו דרך ה' למען הביא ה' שלא אמר שמרו דרכי למען אביא וכן אמר כי גדלה צעקתם את פני ה' וישלחנו ה' וכן ויהי בשחת אלהים וגו' (להלן פסוק כט)
@484 **מאחריו** . מאחרי לוט שהיה הולך אחריהם מאסף לכל ביתו ממהרם להמלט
@487 **ויזכור אלהים את אברהם וישלח את לוט** . ענין הכתוב הזה כי לוט נתחסד עם הצדיק ללכת עמו לשוט בארץ באשר ילך והוא שנאמר (לעיל יב ד) וילך אתו לוט כי לצוות שלו הלך ולכן היה לו זכות להצילו בזכות אברהם כי בעבורו הוא גר בסדום ולולי אברהם עודנו היה בחרן עם מולדתו ולא יתכן שתבא אליו רעה בעבור אברהם שיצא במצות קונו וגם זה היה הענין ששם אברהם נפשו בכפו לרדוף המלכים בעבורו
@488 **כי ירא לשבת בצוער** . כתב רש"י לפי שהיא קרובה לסדום ואינו כן אבל מפני שהיא מן המקומות שנגזרה עליהם ההשחתה ובתחנתו של לוט הניחה המלאך בעבור שלא יוכל להמלט ההרה בו ביום חשב בלבו כי לא יאריך לו עוד אחרי שיש לו זמן רב להמלט ההרה ולכך אמרה בתו ואיש אין בארץ שחשבה כי בצאת אביה משם נשחתה צוער
@489 **ותאמר הבכירה** . אמר רבי אברהם יתכן שהיתה לו אשה אחרת ומתה בתחילה ואין צורך כי "הבכירה" הפך "צעירה" כל גדול באחוה יקרא "בכור" וכל קטן ממנו צעיר לו והפרי הראשון בשנה יקרא "בכורים" וכן בכורי דלים (ישעיהו יד ל) המוקדמים בדלות שהם דלי הדלים וכן בבכורו ייסדנה ובצעירו יציב דלתיה (יהושע ו כו) וכן תרגם אונקלוס רבתא
@490 **וטעם ונחיה מאבינו זרע** . באולי כי אמרו נעשה אנחנו המעשה הראוי לנו כי ירחם האלהים ונוליד זכר ונקבה ויתקיים העולם מהם כי עולם חסד יבנה (תהלים פט ג) ולא לחנם הצילנו ה' והנה היו צנועות ולא רצו לאמר לאביהם שישא אותן כי בן נח מותר בבתו (סנהדרין נח) או שהיה הדבר מכוער מאד בעיני הדורות ההם ולא נעשה כן מעולם וכן רבותינו בהגדות מגנים את לוט מאד (נזיר כג)
@498 **ויאמר אברהם אל שרה אשתו אחותי היא** . לא היה זה כמו במצרים כי שם בבואם מצרימה ויראו המצרים את האשה כי יפה היא ויהללו אותה אל השרים ואל המלך כי אנשי זמה הם אבל המלך הזה תם וישר גם אנשיו טובים רק אברהם חשד אותם והיה אומר לכל אחותי היא
@498 "וישלח אבימלך ויקח וגו'" - הנה זה פלא שהיתה שרה אחרי בלותה יפה עד מאד יקחוה המלכים כי בהלקחה אל פרעה אם היתה בת ששים וחמש אפשר שהיה עליה תארה אבל אחרי בלותה וחדל ממנה האורח פלא הוא ואולי חזרה לנערותיה כאשר בישרה המלאך כדברי רבותינו (ב"מ פז)
@508 **וגם אמנה אחותי בת אבי** . לא ידעתי טעם להתנצלות הזה כי גם אם אמת הדבר שהיתה אחותו ואשתו וברצותם באשה אמר להם אחותי היא להטעותם בדבר כבר חטא בהם להביא עליהם חטאה גדולה ואין חילוק והפרש כלל בין שהדבר אמת או שקר ואולי מפני שאמר אבימלך מה ראית כי עשית את הדבר הזה לומר מה ראית בי חטא או רשע שפחדת ועשית כן כי אני לא נסיתי לקחת נשים מבעליהן אז ענה אברהם אני לא ידעתי אתכם אך חשבתי אולי אין יראת אלהים במקום הזה כי רוב מקומות העולם אין בהם יראת אלהים ולכן מעת צאתי מארצי ולכתי בעמים כאיש תועה ולא ידעתי אל איזה מקום נבוא התניתי עמה לאמר כן בכל מקום כי הדבר אמת וחשבתי לי בו הצלת נפש ולא החלותי בדבר בבואי בארצכם כי לא ראיתי בכם עון אשר חטא
@508 "וגם" - אמנה אחותי בת אבי טענה אחרת אמר אני לפי דרכי אמרתי כן שהוא אמת וחשבתי אם אולי יחפצו בה ישאלוני אם היא גם אשתי כיון שלקחוה עבדיך ולא שאלוני דבר אמרתי גם במקום הזה אין יראת אלהים והחרשתי ויתכן שהיה התנאי הזה דברו עמה בבואם במצרים אף על פי שאמר "כאשר התעו אותי אלהים מבית אבי" או שחזר וזרז אותה שם במצרים בשעת מעשה כאשר פירשתי (לעיל יב יא) ודעת רבי אברהם כי כל אלה דברים לדחות את אבימלך
@512 **הנה נתתי אלף כסף לאחיך** . היו הצאן והבקר והעבדים שנתן לו שוים אלף כסף ואמר לשרה הנה נתתי ממון רב לאחיך הנה הכסף לך כסות עיני כל המביטים ביפיך כי את עיניהם ואת ראשיהם החוזים יכסו מהביט בך ומהביט בכל אשר אתך אפילו בנערותיך ושפחותיך והנה לטובתך נתפשת בביתי כי ייראו ממך ויכסו עיניהם מראות בך באמרם המלך פדה נפשו על שלחו יד באשת הנביא והגיד הכתוב שפייס את אברהם בממון ואת שרה בדברים שלא יענש באחד מהם ואמר כי שרה לא נתפייסה לו אבל עם כל זה היתה מתוכחת עמו בטענות לאמר שלא תמחול לו ובשבחה דבר הכתוב ואברהם נתפייס ויתפלל עליו והוא כלשון ועם ישראל יתוכח (מיכה ו ב) אך דרכי אל פניו אוכיח (איוב יג טו) שם ישר נוכח עמו (שם כג ז) ויתכן שיהיה "אלף כסף" אלפי כסף ממון רב כיד המלך וכן הקטן יהיה לאלף (ישעיהו ס כב) לעם רב וכן השיבו נא להם כהיום שדותיהם כרמיהם זיתיהם ובתיהם ומאת הכסף והדגן והתירוש והיצהר אשר אתם נושים בהם (נחמיה ה יא) מאות רבות ממון גדול
@513 **וילדו** . אם הלשון כפשוטו ושב לאשתו ואמהותיו כי עצר ה' בעד רחמם תימה הוא כי נראה כי גם בלילה הראשון אשר לוקחה שרה לבית אבימלך ולא קרב אליה עדיין בא אליו האלהים בחלום ובבקר השכים וקרא לעבדיו גם לאברהם ומתי היה להם עצר רחם אולי היו על פרקן ואחזום חבלי יולדה ולא יכלו להמליט ואולי אברהם איחר תפלתו ימים רבים והנה רפואות אבימלך גם חליו לא נתפרשו ולשון רש"י וילדו ואתרוחו נתפתחו נקביהם והוציאו והוא לידה שלהן בעד כל רחם כנגד כל פתח ואין זה נכון כי אם נאמר ב"וילדו" שהוא יציאת החוץ שמצינו לידה בענינים רבים כגון הרה עמל וילד שקר (תהלים ז טו) לדת חק (צפניה ב ב) מה ילד יום (משלי כז א) מה יולידו ויחדשו הימים אבל מלת "רחם" לא תבא על פתח אחר ואין טענה מן בגיחו מרחם יצא (איוב לח ח) שהוא כנוי כמו בטן האדמה (שם א כא) ודעת אונקלוס איננה כדברי הרב כי הוא שתרגם "ואתרוחו" עשה "רחם" כפשוטו "פתח ולדא" אלא שרצה לכלול גם אבימלך במלת וילדו ולשון בראשית רבה (נב יג) כי עצור עצר ה' עצירה בפה עצירה בגרון עצירה בעין עצירה באוזן עצירה מלמעלה עצירה מלמטה והמדרש הזה להם מיתור לשון הכפל עצור עצר לא שיפרשו כל רחם כל נקב והנכון בעיני כי מיום אשר נלקחה שרה לקה אבימלך באברי התשמיש ולא יוכל לשמש וזהו לא נתתיך לנגוע אליה כי הנגיעה והקריבה בנשים הוא על התשמיש כענין אל תגשו אל אשה (שמות יט טו) ואקרב אל הנביאה (ישעיהו ח ג) ואשתו ואמהותיו שהן מעוברות עצר בעד רחמן ולא יכלו להמליט כי "עצירת רחם" הוא שלא תהר כדרך וה' סגר רחמה (שמואל א א ה) אבל "עצירה בעד הרחם" הוא שלא תלד כלשון גדר בעדי ולא אצא (איכה ג ז) ועמדה שרה בביתו ימים ולא שב אבימלך מדרכו הרעה כי לא הבין עד שבא אליו האלהים בחלום והודיעו ולא פירש הכתוב חולי אבימלך והזכירו ברמז דרך מוסר וכבוד לשרה ואחרי תפלת אברהם נרפא אבימלך ואשתו ואמהותיו וילדו הנשים
@515 **וה' פקד את שרה כאשר אמר** . בהריון כאשר דבר בלידה לשון רש"י ואין "פקידה" אלא לשון זכירה והשגחה על הנפקד כגון פקוד יפקוד אלהים אתכם (להלן נ כה) פקוד פקדתי אתכם ואת העשוי לכם (שמות ג טז) ויפקוד שמשון את אשתו בגדי עזים (שופטים טו א) אף כאן וה' פקד את שרה זכר את שרה ועשה לה כאשר דבר וכן הלשון בכל העקרות היולדות ברחל ויזכור אלהים את רחל (להלן ל כב) ובחנה ויזכרה (אלהים) ה' (שמואל א א יט) וכך אמרו פקדונות הרי הן כזכרונות (ר"ה לב)
@521 **מי מלל לאברהם** . לשון שבח וחשיבות הוא ראו מי הוא וכמה הוא גדול ושומר הבטחתו ומבטיח ועושה לשון רש"י ולא מצינו מלת "מי" בערך כזה למעלה וכבוד רק לבזיון מי אבימלך ומי שכם (שופטים ט כח) מי דוד ומי בן ישי (שמואל א כה י) והנכון בעיני כי אמרה צחוק עשה לי אלהים כל השומע יצחק לי למלאת פיו ברנה ושחוק בפלא הנעשה לי כי מי בכל השומעים שאמר לאברהם מתחלה תניק בנים שרה אין בעולם שיאמר אליו כן אפילו לנחמו כי לא עלה זה על לב איש מעולם ולשון אונקלוס קרוב לזה מאן מהימן דאמר לאברהם וקיים דתוניק בנין שרה כלומר כל השומע יצחק לי כי אין אדם שיהיה נאמן גם בעיני אברהם אם הגיד לו זה הפלא
@523 **מצחק** . לשון עבודה זרה לשון רציחה לשון גלוי עריות מריב עם יצחק על הירושה ואומר אני בכור ויורש פי שנים ויוצאין לשדה ונוטל קשתו ויורה בו חצים כמה דתימר כמתלהלה היורה זיקים חצים ומות כן איש רמה את רעהו ואמר הלא משחק אני (משלי כו יח) ומתשובת שרה אתה למד כי לא יירש בן האמה הזאת וגו' כל זה לשון רש"י ואף כאן הרב כותב המחלוקות כולם דתניא (תוספתא סוטה פ"ו ה"ג) אמר רבי שמעון בן אלעזר אצלנו הגירסא בן יוחאי ד' דברים היה רבי עקיבא דורש ואיני דורש כמותו ונראין דברי מדבריו דרש רבי עקיבא ותרא שרה את בן הגר המצרית אשר ילדה לאברהם מצחק אין צחוק אלא לשון עבודה זרה וכו' ואני אומר חס ושלום שיהא בביתו של צדיק כך איפשר מי שכתוב בו כי ידעתיו למען אשר יצוה את בניו ואת ביתו וגו' (לעיל יח יט) יהא בביתו עבודה זרה וגלוי עריות ושפיכת דמים אלא אין צחוק האמור כאן אלא לשון ירושה שמשעה שנולד יצחק היו הכל שמחין אמר להם ישמעאל שוטים אני בכור ואני נוטל פי שנים שמתשובה שאמרה שרה אמנו לאברהם אתה למד וכו' ונראין דברי מדבריו וכן הלשון שאמר הרב "מריב עם יצחק על הירושה" אינו נראה נכון שאם כן יהיה זה לאחר ימים רבים ויהיה ישמעאל גדול מאד משאת אותו אמו על שכמה וכן אמרו ז"ל (ילק"ש רמז צה) שהיה בן שבע עשרה שנה אם כן היה בשנה שנגמל יצחק ורבי אברהם אמר על דרך הפשט כי מצחק משתעשע כדרך כל נער ותקנא בו בעבור היותו גדול מבנה והנכון בעיני שהיה זה ביום הגמל את יצחק וראתה אותו מלעיג על יצחק או על המשתה הגדול ולכך אמר הכתוב "את בן הגר המצרית" ולא אמר "את ישמעאל" מצחק וכן אמרה
@523 "גרש את האמה הזאת ואת בנה" - כי אמרה העבד המלעיג על אדוניו חייב הוא למות או להלקותו ואיני רוצה רק שתגרש אותו מאתי ולא יירש בנכסיך כלל עם בני שהוא בן גבירה ואמרה שיגרש גם אמו כי לא יוכל הנער לעזוב את אמו ועזב את אמו ומת
@525 **על אודות בנו** . שיצא לתרבות רעה ופשוטו על שאומרת לו לשלחו זה לשון רש"י והנכון בעיני כי הכתוב סיפר בכבוד אברהם ואמר שלא היה הדבר רע מאד בעיניו מפני חשק פילגשו וחפצו בה ואלו אמרה לו שתגרש האמה בלבד היה עושה כרצון שרה אבל מפני בנו חרה לו מאד ולא רצה לשמוע אליה והקב"ה אמר לו שלא ירע בעיניו על הנער ולא על האמה כלל וישמע לקול שרה כי ביצחק לבדו יקרא לו שמו וישמעאל לא יקרא לו זרע ומפני שהיה אברהם מפחד עליו שלא יקראנו אסון בשלחו אותו ממנו אמר כי ישימנו לו לגוי ויברכנו מפני שהוא זרעו באמת
@528 **ואת הילד וישלחה** . נמשך למעלה ויתן אל הגר ואת הילד כי גם הילד נתן לה שילך עמה באשר תלך
@529 **ותשלך את הילד** . גברה עליו הצמאה ולא יכול ללכת והשכיבתו אמו תחת האילן מושלך ונעזב או כענין וישליכם אל ארץ אחרת (דברים כט כז) אל תשליכני מלפניך (תהלים נא יג) ענין שלוח ורבי אברהם אמר ותשלך כי לקחתו בחיקה בעת שנחלש בצמא ורבותינו אמרו (ב"ר נג יג) שהיה חולה בעת ששלחו ושם על שכמה את הילד וזה הטעם "ותשלך" והיה כל הענין הזה לאברהם מפני שצווה לעשות ככל אשר תאמר שרה והיא צותה להוציאו מיד ובמצותה לא נתן להם כסף וזהב ועבדים וגמלים נושאים אותם
@531 **באשר הוא שם** . לפי מעשים שהוא עושה עכשיו הוא נדון ולא לפי מעשים שהוא עתיד לעשות לפי שהיו מלאכי השרת מקטרגין וכו' לשון רבינו שלמה מדברי רבותינו והנכון בעיני בדרך הפשט שיאמר כי שמע אלהים אל קול הנער במקום אשר הוא שם הודיע אותה שלא תצטרך ללכת משם אל מעין ובור כי במקום ההוא ירוה צמאו מיד ואמר לה קומי שאי את הנער אחרי שתותו כי לגוי גדול אשימנו וכמוהו באשר כרע שם נפל שדוד (שופטים ה כז) ובאשר חללים שם הוא (איוב לט ל) ירמוז למקום
@534 **רובה קשת** . בעבור היות קשת תואר אמרו כי "רובה" הוא המורה החצים מלשון יסבו עלי רביו (איוב טז יג) וימררוהו ורבו (להלן מט כג) ו "קשת" הוא העושה הקשתות ויותר נכון ש "רובה" הוא המורה ויאמר על המורה החצים ועל משליך האבנים וזולתם כאשר יאמר אשר יריתי ביני וביניך (להלן לא נא) ולכן יתאר אותו פעם אחרת כי הוא קשת וכן וימצאוהו המורים אנשים בקשת (שמואל א לא ג)
@537 **השבעה לי באלהים הנה אם תשקור לי** . מלת "אם" בכל מקום מספקת אל תחשוב בה בלתי זה והיא באה ברוב מקומות השבועה אם תשקור לי לכן נשבעתי לבית עלי אם יתכפר עון בית עלי (שמואל א ג יד) אחת נשבעתי בקדשי אם לדוד אכזב (תהלים פט לו) אם יבואון אל מנוחתי (שם צה יא) ויקצוף וישבע לאמר אם יראה איש באנשים האלה (דברים א לד לה) והענין כי בעבור היות השבועות באלה יאמר השבעה לי לאמר כה יעשה לי אלהים וכה יוסיף אם תשקור לי וכן אמר (להלן כו כח) תהי נא אלה בינותינו ובענין הגבוה נשבעתי בקדשי אם לדוד אכזב (תהלים פט לו) ואם יתכפר עון בית עלי (שמואל א ג יד) כלומר אם יהיה כן אין דברי אמת וכיוצא בזה שלא ירצה לפרש התנאי והכתוב יכנה ויקצר בהן וכמותם בחסרון התנאי (דהי"א ד י) ויקרא יעבץ לאלהי ישראל לאמר אם ברך תברכני והרבית את גבולי וגו' ועשית מרעה לבלתי עצבי ויבא אלהים את אשר שאל יחסר התנאי כולו וכן אם יראו את הארץ (במדבר יד כג) יחזור לפסוק ראשון חי אני וימלא כבוד ה' את כל הארץ ויקצר השבועה ולשון תשקור לי בעבור היותו מלך והוא גר בארצו או שיהיה משקר באהבתו כי אוהב נאמן היה לו לכבדו ולעשות כרצונו הלא תראה שלא מצא בו דבר זולתי באר המים אשר גזלו עבדיו והוא אומר לו כחסד אשר עשיתי עמך
@546 **וישובו אל ארץ פלשתים** . ענינו וישובו אל עירם אשר בארץ פלשתים כי בארץ פלשתים היו אבל הם יושבים בגרר שהיא מדינת המלך והוא יושב בבאר שבע שהיא בארץ פלשתים בנחל גרר
@547 **ויקרא שם בשם ה' אל עולם** . פי' הכתוב שקרא בשם ה' המנהיג בכחו הזמן או שיקראו השמים והארץ "עולם" כלשון הבא תמיד בדברי רבותינו והודיע בזה שקרא אברהם והודיע לבריות סוד הנהגת העולם בכללו שהוא בשם ה' החסין בכח שיש לו אילות בכולם הרב אמר במורה הנבוכים (ב יג) שהוא רומז לקדמות האל כי הודיע היותו קודם לזמן אבל אונקלוס אמר ב "ויקרא" שהוא תפלה
@549 **והאלהים נסה את אברהם** . ענין הנסיון הוא לדעתי בעבור היות מעשה האדם רשות מוחלטת בידו אם ירצה יעשה ואם לא ירצה לא יעשה יקרא "נסיון" מצד המנוסה אבל המנסה יתברך יצוה בו להוציא הדבר מן הכח אל הפועל להיות לו שכר מעשה טוב לא שכר לב טוב בלבד דע כי השם צדיק יבחן (תהלים יא ה) כשהוא יודע בצדיק שיעשה רצונו וחפץ להצדיקו יצוה אותו בנסיון ולא יבחן את הרשעים אשר לא ישמעו והנה כל הנסיונות שבתורה לטובת המנוסה
@550 **קח נא את בנך את יחידך** . בעבור היותו בן הגבירה והוא לבדו אשר יקרא לו זרע קראו יחידו ובא הלשון להגדיל המצוה אמר קח נא את בנך היחיד האהוב יצחק והעלהו עולה לפני
@550 "המוריה" - לשון רש"י היא ירושלים וכן בדברי הימים (ב ג א) לבנות את בית ה' בירושלים בהר המוריה ורבותינו פירשו (תענית טז) שמשם יצאה הוראה לעולם ואונקלוס תרגמו על שם הקטורת שיש בו מור וסמים ואם כן יהיה פירושו אל הארץ אשר תהיה מוריה או שנקראת כן מעולם על שם העתיד ובבראשית רבה (נה ז) כך אמרו רבנין אמרין למקום שהקטורת קרבה כמה דתימר אלך לי אל הר המור (שיר השירים ד ו) אבל דעת אונקלוס שאמר "ארעא פולחנא" אינו נראה כן על המור שבקטורת שאין לשון "פולחנא" על סם אחד מסמי אחת העבודות ולמה לא אמר "לארעא דקטורת בוסמין" אבל דעתו לומר בארץ אשר יעבדו שם האלהים ויתכוין בזה למה שדרשו בפירקי רבי אליעזר (לא) אמרו באצבע הראה הקדוש ברוך הוא לאברהם אבינו את המזבח אמר לו זהו המזבח הוא המזבח שהיה אדם הראשון מקריב בו הוא המזבח שהקריבו בו קין והבל הוא המזבח שהקריבו בו נח ובניו שנאמר ויבן שם אברהם את המזבח מזבח אין כתוב כאן אלא "המזבח" הוא המזבח שהקריבו בו הראשונים עד כאן ושם "מוריה" עשאו מן מורא ששם יראו האלהים ועבדו לפניו והנכון על דרך הפשט שהוא כמו אל הר המור ואל גבעת הלבונה כי ימצאון שם בהר ההוא מור ואהלים וקנמון כענין שאמרו (ירושלמי פאה ז ג) קנמון היה גדל בארץ ישראל והיו עזים וצבאים אוכלים ממנו או שנקרא כן לשבח ישראל והנה בכאן קורא שם הארץ "ארץ מוריה" ושם (דהי"ב ג א) נראה כי הר הבית לבדו יקרא "הר המוריה" ואולי נקראת העיר על שם ההר ההוא אשר בתוכה הארץ אשר בה המוריה וההר לבדו הוא נקרא מוריה ואברהם ידע את הארץ ולא ידע את ההר ולכן אמר לו שילך אל ארץ המוריה והוא יראנו אחד ההרים ששם שנקרא ככה וצוהו להעלותו במקום ההוא כי הוא ההר חמד אלהים לשבתו ורצה שתהיה זכות העקידה בקרבנות לעולם כאשר אמר אברהם "ה' יראה" ועוד כי למען צדקו הגדיל טרחו ורצה שיעשה זה אחרי מהלך שלשה ימים כי אלו יעשה כן בפתע פתאום במקומו היתה פעולתו במהירות ובהלה אבל כשיהיה אחר מהלך ימים כבר נעשה בישוב דעת ועצה וכך אמרו בבראשית רבה (נה ו) רבי עקיבא אומר נסה אותו בוודאי שלא יהיו אומרין הממו וערבבו ולא היה יודע מה לעשות
@551 **ויבקע עצי עולה** . זריזותו במצוה אולי לא ימצא שם במקום ההוא עצים והוליכם שלשה ימים או שהיה אברהם פוסל לקרבן עץ שנמצא בו תולעת כדין התורה (מדות ב ה) ולקח מביתו עצים טובים לעולה וכן אמר ויבקע עצי עולה
@552 **וירא את המקום מרחוק** . ראה ענן קשור על ההר (ב"ר נו א) ונתקיים בזה אשר אומר אליך ויתכן על דרך הפשט וירא את המקום מרחוק שראה ארץ המוריה כי כל הארץ ההיא היה יודע ויבאו אל המקום אשר אמר לו האלהים עתה הוא הר המוריה שאמר לו "הנה זה ההר אשר אמרתי לך"
@560 **כי עתה ידעתי** . מתחילה היתה יראתו בכח לא יצא לפועל במעשה הגדול הזה ועתה נודעה במעשה והיה זכותו שלם ותהי משכורתו שלימה מעם ה' אלהי ישראל ודעת הפרשה ש"האלהים" הוא המנסה ומצוה בעקידה ו"מלאך ה'" הוא המונע והמבטיח יתברר בפסוק המלאך הגואל אותי (להלן מח טז)
@564 **יען אשר עשית את הדבר הזה** . גם מתחילה (לעיל יג טז טו ה) הבטיחו כי ירבה את זרעו ככוכבי השמים וכעפר הארץ אבל עתה הוסיף לו יען אשר עשית המעשה הגדול הזה שנשבע בשמו הגדול ושיירש זרעו את שער אויביו והנה הובטח שלא יגרום שום חטא שיכלה זרעו או שיפול ביד אויביו ולא יקום והנה זו הבטחה שלימה בגאולה העתידה לנו
@568 **מלכה גם היא** . בעבור היותה בת הרן אחיו היתה בשורה לאברהם שנפקד אחיו הגדול בבנים רבים מבת אחיו המת ומלשון הכתוב נראה שלא ידע באחד מהם בלתי היום ואם היתה פקודתם בימי בחורותם אי אפשר שלא שמעו עד היום כי אין המרחק רב בין ארם נהרים ובין ארץ כנען והנה אברהם בצאתו מחרן בן ע"ה שנה וגם נחור זקן ואשתו איננה בחורה אבל עשה ה' להם נס שנפקדו בימי הזקנה וזה טעם "מלכה גם היא" ובדברי רבותינו (ילק"ש רמז תשסו) יאמר שנפקדה כאחותה
@571 **ובתואל ילד את רבקה** . לא הזכיר הכתוב לבן ואם הוא גדול מרבקה כי לא בא להזכיר רק השמונה שילדה מלכה לנחור אבל הזכיר רבקה כי להודיע יחוסה באה הפרשה וטעם אבי ארם לא הזכיר ארם רק להודיע ולהכיר קמואל כי ארם היה נכבד מאביו ואולי קמואל אחר היה בדורם וזה אבי ארם
@572 **ופילגשו ושמה ראומה** . יספר הכתוב כל הבשורה שבשרו את אברהם בבני אחיו ויתכן שנכתב זה להודיע כל יחוס נחור כי כלם ראויים להדבק בזרעו של אברהם ועל כולם אמר אם לא אל בית אבי תלך ואל משפחתי (להלן כד לח) חסלת פרשת וירא
@573 **מאה שנה ועשרים שנה** . לשון רש"י לכך נכתב שנה בכל כלל וכלל לומר לך שכל אחד נדרש לעצמו בת מאה כבת עשרים לחטא ובת עשרים כבת שבע ליופי וכן כתב בשני חיי אברהם (להלן כה ז) ואין מדרשו זה נכון שהרי בשני חיי ישמעאל (שם פסוק יז) נאמר כשני חיי אברהם בשוה ולא היו שוים בטובה אבל היה מתחלה רשע ועשה תשובה בסוף ועוד כי שנה שנה לחלק משמע ואיננו נדרש להשוותן אבל "שנה שנה ושנים" דרך הלשון הוא ומה שאמרו בבראשית רבה (נח א) בת מאה כבת עשרים לחטא לא דרשו כן אלא מיתור הלשון שחזר ואמר "שני חיי שרה" שכללן והשוה אותן ולא ידרשו כן באברהם
@574 **ויבא אברהם** . לשון רש"י מבאר שבע ואין זה לומר שהיה עומד שם ממה שכתוב (לעיל כב יט) וישב אברהם בבאר שבע כי איך תהיה שרה בחברון אבל הכוונה לומר שהלך שם ביום לצרכו ושמע במיתת שרה ובא משם לספוד לה ולבכותה ולשון רבותינו (ב"ר נח ה) מהר המוריה בא וכן הוא לפי המדרש שכתבו הרב (רש"י כאן) כי שמעה בעקידה ופרחה נשמתה והנראה בעקידה שהיתה הצואה בה בבאר שבע כי שם היה דר ושם חזר כי כן כתוב בתחילה (לעיל כא לג) ויטע אשל בבאר שבע ויקרא שם בשם ה' אל עולם ואמר (שם) ויגר אברהם בארץ פלשתים ימים רבים והוא גרותו בבאר שבע שהוא בארץ פלשתים ושם נצטווה בעקידה ועל כן שהה בדרך שלשה ימים שארץ פלשתים רחוקה מירושלים שאילו חברון בהר יהודה הוא כי כן כתוב (יהושע כ ז) וקרוב לירושלים ובשובו מן העקידה לבאר שבע חזר כמו שנאמר (לעיל כב יט) וישב אברהם אל נעריו ויקומו וילכו יחדו אל באר שבע וישב אברהם בבאר שבע להורות שנתעכב שם וישב בו שנים ואם כן לא מתה שרה באותו זמן כי לא היה אברהם דר בבאר שבע ושרה דרה בחברון וכן נראה כי יצחק נולד בבאר שבע כי כתוב תחילה (לעיל כ א) ויסע משם אברהם ארצה הנגב וישב בין קדש ובין שור ויגר בגרר ואבימלך אמר אליו הנה ארצי לפניך כטוב בעיניך שב (שם טו) ונתישב שם בארץ ההיא בבאר שבע שכן כתוב (לעיל כא כב) ויהי בעת ההיא ויאמר אבימלך ופיכול שר צבאו אל אברהם לאמר ואין כתוב שהלכו אליו מגרר ויכרתו שם הברית בבאר שבע וכן תראה כי הגר כאשר הוציאו אותה מבית אברהם ביום הגמל את יצחק הלכה במדבר באר שבע (לעיל כא יד) ששם היו דרים אבל אחר ימים רבים נסע מארץ פלשתים ובא לחברון ונפטרה שם הצדקת אבל לפי המדרש צריכין אנו לומר כי אברהם ושרה בזמן העקידה היו דרים בחברון ושם נצטוה ומה שאמר ביום השלישי וישא אברהם את עיניו (לעיל כב ד) כי לא נגלה לו ההר חמד אלהים עד היום השלישי והיה בשני הימים הולך בסביבי ירושלים ולא היה הרצון להראות לו ואברהם אחר העקידה לא שב למקומו לחברון אבל הלך תחלה אל באר שבע מקום האשל שלו לתת הודאה על נסו ושם שמע במיתת שרה ובא ומי שאמר מהר המוריה בא ומי שאמר מבאר שבע בא הכל טעם אחד ולפי זה מה שאמר הכתוב וישב אברהם בבאר שבע (לעיל כב יט) יהיה ענינו כי בשובו מן העקידה שב אל באר שבע ומשם הלך לקבור את שרה ואחר הקבורה מיד חזר לבאר שבע ונתישב שם שנים והשלים הכתוב ענין באר שבע כאחד ואחרי כן ספר בקבורה ושם בבאר שבע נשא יצחק את רבקה כמו שאמר והוא יושב בארץ הנגב (להלן כד סב) וזה דעת כל המפרשים (רש"י והראב"ע והרד"ק) כי אברהם היה במקום אחר ובא משם ולפי דעתי כי היה לשרה אהל שם עומדת ואמהותיה לפניה וכן כתוב (להלן לא לג) באהל יעקב ובאהל לאה ובאהל שתי האמהות והנה שרה מתה באהל אשר לה ונכנס אברהם באהל עם אחזת מרעיו לספוד אותה או שיהיה לשון "ויבא" לאמר שנתעורר אברהם להספד הזה והתחיל לעשותו כי כל מתעורר ומתחיל במלאכה יקרא בא אליה וזה לשון מורגל בדברי חכמים כמו ששנינו בתמיד (פ"ד מ"ג) בא לו לגרה והניח בה שתי צלעות מכאן בא לו לדופן השמאלית בא לו לעוקץ ואמרם (בכורות כ) אני לא באתי לידי המדה הזו וכן בכתוב (שמות כב יד) בא בשכרו שבא למלאכה ההיא ועשה אותה בעבור שכרו ולא יתכן בעיני שבא מעיר אחרת אל חברון שאלו היה כן היה מזכיר אותו המקום והיה הכתוב מפרש "וישמע אברהם ויבא ממקום פלוני"
@576 **גר ותושב אנכי עמכם** . היה המנהג להיות להם בתי קברות איש לבית אבותיו ושדה קבורה אחד יקברו בו כל הגרים והנה אברהם אמר אל בני חת אני גר מארץ אחרת ולא הנחלתי מאבותי בית הקברות בארץ הזאת והנה עתה אני תושב עמכם כי חפצתי לשבת בארץ הזאת ולכן תנו קבר להיות לי לאחזת עולם כאחד מכם ומפני שאמר "תנו" חשבו שבקש אותה מהם במתנה וענו אותו אינך נחשב בעינינו כגר ותושב אבל אתה מלך המליכך האלהים עלינו ואנחנו ואדמתנו עבדים לך תקח כל בית הקברות שתחפוץ בו וקבור מתך שם ויהיה לך לאחזת קבר לעולם כי איש ממנו לא ימנעהו ממך
@580 **אם יש את נפשכם לקבור את מתי מלפני** . טעמו אני לא אקבור מתי בקבר אחר אבל אם רצונכם שאקבור מתי פגעו לי בעפרון שיש לו מערה בקצה שדהו ואיננה לו בית קברות אבותיו כי לשדה היא להם וטעם מלפני כי אם לא תעשו כן אקברנו בארון או יהיה טעמו מתי אשר הוא לפני ואני צריך למהר לקברו וטעם ופגעו לי כי היה עפרון עשיר ונכבד כאשר אמר ביני וביניך מה היא ולא יהיה לו לכבוד למכור נחלת אבותיו כענין נבות היזרעאלי (עיין מלכים א כא) על כן לא הלך אברהם אליו להרבות לו מחיר השדה ובקש מאנשי העיר שיפגעו בעבורו דרך כבוד
@581 **וטעם ויתן לי ויתננה לי** . שאחשוב אותה כמתנה אם בכסף מלא אקחנה ממנו ועל כן לא הזכיר לשון מכירה וכן אוכל בכסף תשברני ומים בכסף תתן לי (דברים ב כח) שהמים הנתנים במתנה אתן בהם כסף או שהוא דרך הלשון להזכיר כן במכירות
@581 "מערת המכפלה" - לשון רש"י בית ועליה על גביו דבר אחר שכפולה בזוגות (עירובין נג) ואיננו נכון כי הכתוב אמר שדה עפרון אשר במכפלה (להלן פסוק יז) והנה הוא שם המקום אשר בו השדה ואין צורך לבקש טעם לשם המקומות ובבראשית רבה (נח ח) אמרו שכפל הקב"ה קומתו של אדם הראשון וקברו בתוכה ועל דעתם היה כל המקום ההוא נקרא כן מעולם והם לא ידעו טעמו כי עפרון בדמי השדה מכר לו הכל על דעתו שאין שם קבר והנה אברהם לא היה מבקש רק למכור לו המערה כי היא בקצה השדה וישאר השדה לעפרון והוא אמר לו דרך מוסר או מרמה שיתן לו השדה והמערה אשר בו כי לא יתכן לאדם נכבד כמוהו שתהיה לו המערה לאחזת קבר והשדה יהיה לאחר ואברהם שמח בכך וקנה הכל בדמים שהזכיר לו
@583 **וטעם לעיני בני עמי** . לאמר הנה כל העם הנה והם היודעים ועדים ואל תחוש לכפירה או לחזרה וקבור מתך שם מעתה כי שלך היא ולא אוכל לשוב ואברהם לא עשה כן כי גם אחרי שפרע הכסף מלא החזיק תחלה בשדה ובמערה והקימם ברשותו לעיני בני העיר וכל באי שער העיר הסוחרים והגרים הנמצאים שם ואחר כן קבר אותה
@585 **אם אתה לו שמעני** . שעורו אם אתה אם תשמעני וענינו כמו אם אתה תשמעני ובא הכפל לנחץ הענין כמו סורה אדני סורה אלי (שופטים ד יח) הטוב טוב אתה (שם יא כה) וכן ולאמר עליו לאמר (דהי"ב לב יז) וכן ואני אנה אני בא (להלן לז ל) ופניתי אני וראיתי אני (קהלת ב יב יג)) כי כל העדה כלם קדושים (במדבר טז ג) כלם רידוף הענין וכן על דעתי אם מחוט ועד שרוך נעל ואם אקח (לעיל יד כג) שעורו אם מחוט ועד שרוך נעל אקח מכל אשר לך או יאמר אם אתה כאשר אמרת כלומר שפיך ולבך שוים בענין ואם תשמעני וכן ויאמרו להם אחיהם מה אתם (שופטים יח ח) ודומה ללשון הזה על דעתי למה זה אנכי (להלן כה כב) אולי זה דעת אונקלוס שאמר אם את עבד לי טיבו שתעשה רצוני כאשר אמרת
@587 **וטעם ארץ ארבע מאות שקל כסף** . על דעת אונקלוס שהיא שוה כן אולי רצה לומר שהיו דמיה קצובים כן במקום ההוא כי כן המנהג ברוב הארצות להיות מחיר שדה קצוב לפי מדתו וכדברי רבותינו (ב"מ פז) עפרון קצב דמים כרצונו ביוקר גדול ואברהם בנדבת לבו שמע ועשה כרצונו והגדיל ועל דרך הפשט "ארץ ארבע מאות שקל כסף" שקנה אותה בכך עפרון או אבותיו הקדמונים
@591 **וטעם ואחרי כן קבר אברהם את שרה אשתו אל מערת שדה המכפלה וגו' היא חברון בארץ כנען** . כי שב לבאר השדה והמקום והארץ בעבור כי כל הפרשה הזכירה בני חת ועפרון החתי לפיכך הזכיר בסוף כי הוא בארץ כנען אשר היא ארץ ישראל וכן אמר בתחילת הפרשה בקרית ארבע היא חברון בארץ כנען וכל זה לבאר כי הצדקת מתה בארץ ישראל ושם נקברה כי החתים ממשפחות כנען ולפי דעתי כי טעם הכתובים אינו אלא להזכיר כי היא ארץ כנען לא ארץ פלשתים כי מפני שאמר ויגר אברהם בארץ פלשתים ימים רבים (לעיל כא לד) וכל מגוריו בארץ ההיא בגרר ונחל גרר ובאר שבע ומשם לחברון ומחברון לשם על כן הזכיר כי חברון הוא בארץ הכנעני היושב בהר ההוא לא בארץ פלשתים הנזכרת לאברהם והוסיף בסוף להודיע המערה שהיא בשדה המכפלה על פני ממרא שזה השם הנודע אליה ונכתבה זאת הפרשה להודיע חסדי השם עם אברהם שהיה נשיא אלהים בארץ אשר בא לגור שם והיחיד וכל העם היו קוראין לו "אדוני" והוא לא אמר להם כן שהיה שר וגדול וגם בחייו קיים לו ואגדלה שמך והיה ברכה ואשתו מתה ונקברה בנחלת ה' ועוד כי רצה להודיענו מקום קבורת האבות באשר אנחנו חייבים לכבד מקום קבורת אבותינו הקדושים ורבותינו אמרו (ב"ב טז) שגם זה מן הנסיונות של אברהם שבקש מקום לקבור את שרה ולא מצא עד שקנה אותו ולא ידעתי טעם לדברי רבי אברהם שאומר להודיע מעלת ארץ ישראל לחיים ולמתים ועוד לקיים לו דבר השם להיות לו נחלה כי מה מעלה לארץ בזה כי לא יוליכנה אל ארץ אחרת לקברה ודבר השם לאברהם על כל הארץ היה ונתקיים רק בזרעו
@593 **ואברהם זקן בא בימים** . חזר הכתוב לאמר כן להודיע הסבה שבעבורה השביע את עבדו ואמר כי ראה עצמו זקן מאד וחשב בלבו שאם ישלח לארץ מולדתו אולי טרם יחזור השליח ילך לו אל בית עולמו ולכן השביע את עבדו אשר ילך יצחק אחרי עצתו כי הוא המושל בכל אשר לו שלא יקח לו אשה מבנות כנען ובבראשית רבה (נט ו) אמרו כאן זקנה שיש בה לכלוכית ולהלן זקנה שאין בה לכלוכית ירצו לפרש כי "באים בימים" מתחילים בימי הזקנה כי "באים" מורה על זמן עומד כמו הבאים בשערים האלה (ירמיהו ז ב) וכאן אמר שהיה זקן מאד שכבר בא בימים כמו בא אחיך במרמה (להלן כז לה)
@593 "ברך את אברהם בכל" - בעושר ונכסים וכבוד אורך ימים ובנים וזאת כל חמדת האדם (אבן עזרא) והזכיר הכתוב זה לאמר כי היה שלם בכל לא חסר דבר זולתי שיראה בנים לבנו שינחלו מעלתו וכבודו ולכן התאוה לזה ולרבותינו בזה ענין נפלא אמרו (ב"ב טז) וה' ברך את אברהם בכל רבי מאיר אומר שלא היתה לו בת רבי יהודה אומר בת היתה לו אחרים אומרים בת היתה לו ובכל שמה דרש רבי מאיר שלא היתה לו בת לאברהם וזו לו לברכה כי לא היה יכול להשיאה רק לבני כנען הארורים ואם ישלחנה לארצו גם כן תעבוד שם עבודה זרה כמותם כי האשה ברשות בעלה ואברהם לא יחפוץ שיצא זרעו הכשר משרה אשתו חוצה לארץ ואף כי יעבוד עבודה זרה ורבי יהודה דרש כי בת היתה לו דאפילו ברתא לא חסריה רחמנא (שם קמא) והיא הברכה בכל כי היה לו כל אשר יחמדו האנשים לא חסר דבר ובאו אחרים והזכירו שם הבת ובאמת שאין הכוונה לאחרים והמחלוקת להם עם רבי יהודה להודיע אותנו שם הבת הזאת בלבד וחלילה להם שיוציאו ברכתו של אברהם שהיא גדולה וכללית לענין זה שיאמר הכתוב כי ברך אתו השם בבת אחת ששמה כך אבל אחרים חדשו בפירוש הכתוב הזה ענין עמוק מאד ודרשו בזה סוד מסודות התורה ואמרו כי "בכל" תרמוז על ענין גדול והוא שיש להקב"ה מדה תקרא "כל" מפני שהיא יסוד הכל ובה נאמר (ישעיהו מד כד) אנכי ה' עושה כל והוא שנאמר (קהלת ה ח) ויתרון ארץ בכל הוא יאמר כי יתרון הארץ וטובה הגדולה השופע על כל באי עולם בעבור כי בכל היא והיא המדה השמינית מי"ג מדות ומדה אחרת תקרא בת נאצלת ממנה ובה הוא מנהיג את הכל והיא בית דינו של הקב"ה הנרמז במלת וה' בכל מקום (ב"ר נא ב) והיא שנקראת כלה בספר שיר השירים בעבור שהיא כלולה מן הכל והיא שחכמים מכנים שמה כנסת ישראל במקומות רבים בעבור שהיא כנוסת הכל והמדה הזאת היתה לאברהם כבת כי הוא איש החסד ויתנהג בזו ולכך אמרו אחרים כי אין הברכה הזאת שנתברך בכל רומזת על שהוליד בת משרה אשתו או שלא הוליד אבל היא רומזת ענין גדול שברך אותו במדה שהיא בתוך מדת הכל ולכן תקרא גם היא כל כלשון כי שמי בקרבו (שמות כג כא) והנה הוא מבורך בשמים ובארץ ולכך אמר בה' אלהי השמים ואלהי הארץ והענין הזה נמצא לרבותינו רמוז בהגדות במקומות רבים כענין שאמרו במדרש חזית (שיר השירים ג כא) שאל רבי שמעון בן יוחאי את רבי אליעזר ברבי יוסי אפשר ששמעת מאביך מהו בעטרה שעטרה לו אמו (שיר השירים ג יא) אמר לו הן אמר לו היאך אמר לו משל למלך שהיתה לו בת יחידה והיה מחבבה יותר מדאי והיה קורא אותה בתי לא זז מחבבה עד שקרא אותה אחותי ולא זז מחבבה עד שקרא אותה אמי כך בתחילה חבב הקב"ה את ישראל וקראן בתי הדא הוא דכתיב (תהלים מה יא) שמעי בת וראי ולא זז מחבבן עד שקראן אחותי שנאמר (שיר השירים ה ב) פתחי לי אחותי רעיתי ולא זז מחבבן עד שקראן אמי שנאמר (ישעיהו נא ד) הקשיבו אלי עמי ולאומי לאמי כתיב עמד רבי שמעון בן יוחאי ונשקו על ראשו אמר לו אילו לא באתי אלא לשמוע זה הדבר מפיך די ומבואר זה במדרשו של ר' נחוניא בן הקנה (ספר הבהיר כב) אמרו בפסוק אנכי ה' עושה כל נוטה שמים לבדי רוקע הארץ מאתי (ישעיהו מד כד) אני כשנטעתי אילן זה להשתעשע בו כל העולם ורקעתי בו הכל וקראתי שמו כל שהכל תלוי בו והכל ממנו יוצא והכל צריכין לו ובו צופין ולו מחכים ומשם פורחים נשמות לבדי הייתי כשעשיתי אותו ולא יגדל עליו מלאך לאמר אני קדמתי לך גם בעת שרקעתי ארצי שבה נטעתי ושרשתי אילן זה ושמחתים ביחד ושמחתי בהם מי אתי שגליתי לו סודי זה עד כאן ועוד שם מבואר מאי ברוגז רחם תזכור (חבקוק ג ב) אמר בעת שחטאו לך בניך ותכעס עליהם רחם תזכור ומאי רחם תזכור זכור אותו שאמר ארחמך ה' חזקי (תהלים יח ב) ונתת לו המדה הזאת שהיא שכינתן של ישראל וזכור בנו שירשה ונתת לו המדה הזאת שהיא שכינתו של ישראל דכתיב (מלכים א ה כו) וה' נתן חכמה לשלמה וזכור אביהם אברהם דכתיב זרע אברהם אוהבי (ישעיהו מא ח) ובקרב שנים תודיע (חבקוק ג ב) ומהיכן היתה בת לאברהם הן דכתיב וה' ברך את אברהם בכל וכתיב (ישעיהו מג ז) כל הנקרא בשמי ולכבודי בראתיו ההיא ברכה היתה בתו או לא היתה אלא אמו הן בתו היתה משל לאדון שהיה לו עבד שלם תמים לפניו ונסהו בכמה נסיונות ועמד בכולן אמר האדון מה אתן לעבד זה או מה אעשה לו אלא אצונו לאחי הגדול ליעצו ולשמרו ולכבדו חזר העבד עם אחיו הגדול ולמד מדותיו אהבו האח וקראו אוהבי דכתיב זרע אברהם אוהבי אמר מה אתן לו או מה אעשה לו הנה כלי נאה עשיתי ובו מרגליות נאות ואין כמותן והם סגולת מלכים אתננה לו ויזכה במקומי הדא הוא דכתיב וה' ברך את אברהם בכל עד כאן ואם תבין מה שכתבתי תדע מאמר הנשים הארורות שאמרו ומן אז חדלנו לקטר למלכת השמים חסרנו כל (ירמיהו מד יח) ולמה נכתבה המלה חסרת האל"ף ותשכיל דברים רבים סתומים בתורה ומקרא ואילו ידע זה המתהדר בסודותיו תאלמנה שפתיו מהלעיג על דברי רבותינו ולכן כתבתי זה לסכור פי הדוברים על הצדיקים עתק
@595 **ואשביעך בה'** . היה ראוי לאברהם שיצוה את יצחק בנו שלא יקח אשה מבנות כנען אבל היה רצונו לשלוח בחייו אל ארצו ומשפחתו והשביע העבד לעשות כן בחייו או במותו ולכן הוצרך על כל פנים להשביע לעבד ללכת שם והוצרך לאמר אני מצוך שלא תקח אשה לבני מבנות כנען ושתלך אל ארצי ותקח לו אשה מבית אביוכיון שהשביע את העבד על זה לא הוצרך לצוות את יצחק דבר כי יודע בו שלא יעבור על רצון אביו ועל השבועה שהשביע את עבדו כי היה הענין נודע ליצחק באמת גם יתכן שהיה העבד אפוטרופוס על נכסיו וצוה אותו שישיא יצחק לרצונו וינחיל אותו נכסיו על מנת כן וזה טעם המושל בכל אשר לו אלהי השמים ואלהי הארץ הקב"ה יקרא אלהי ארץ ישראל כדכתיב (מלכים ב יז כו) לא ידעו את משפט אלהי הארץ וכתוב (דהי"ב לב יט) וידברו אל אלהי ירושלים כעל אלהי עמי הארץ ויש בזה סוד עוד אכתבנו בעזרת השם (עיין ויקרא יח כה) אבל בפסוק (ז) לקחני מבית אבי לא נאמר בו אלהי הארץ כי היה בחרן או באור כשדים וכן אמרו (כתובות קי) הדר בחוצה לארץ דומה כמי שאין לו אלוה שנאמר (שמואל א כו יט) כי גרשוני היום מהסתפח בנחלת ה' לאמר לך עבוד אלהים אחרים
@597 **וטעם אולי לא תאבה האשה** . האשה אשר אדבר בה מכל הנשים אשר שם או הראויה ליצחק
@599 **מבית אבי ומארץ מולדתי** . לשון רש"י מבית אבי מחרן ומארץ מולדתי מאור כשדים אם כן "אל ארצי ואל מולדתי תלך" יהיה אור כשדים וחלילה חלילה שיתערב זרע הקדש בבני חם הפושע אולי יאמר שהיה לו משפחה שם מזרעו של שם אבל העבד לחרן הלך כאשר דבר אדניו ואולי יחשוב הרב כי ארץ מולדתו אור כשדים אבל "מולדתי" היא משפחתי ו"ארצי" ארץ אשר גר בה וכל אלה דברים בטלים כי בכאן אמר ולקחת אשה לבני משם ועוד כי ימים רבים עמד בארץ כנען יותר מחרן ולמה תקרא חרן ארצו בעבור שגר בה ימים אבל "אל ארצי ואל מולדתי" ארצי ששם מולדתי כי שם עמד ומשם היו אבותיו מעולם וכבר נתבאר (לעיל יא כח יב א) ובבראשית רבה (נט י) מבית אבי זו ביתו של אביו ומארץ מולדתי זו שכונתי ויתכן שיהיה טעם "אל ארצי ואל מולדתי" ארצי ומשפחתי כי גם באנשי ארצו לא יחפוץ רק במשפחתו וכן ולקחת אשה לבני משם רמז אל "מבית אבי" וכן יאמר העבד (להלן פסוק מ) ולקחת אשה לבני ממשפחתי ומבית אבי ואמר (שם מא) כי תבא אל משפחתי או שהיה העבד אומר כן לכבדם שישמעו לו
@599 "ואשר דבר לי" - לשון רש"י לצרכי כמו עלי וכן כל לי ולו ולהם הסמוכים אצל דבור מפורשים בלשון על שאין נופל בלשון דבור אלא אלי אליו אליהם ותרגומם עמי עמיה עמהון אבל אצל אמירה נופל לי ולו ולהם ובפרשת ויצא יעקב הביא ראיה ממה שכתוב שם (להלן כח טו) את אשר דברתי לך שהרי עם יעקב לא דבר קודם לכן ואין החילוק הזה אמת כי הנה מצאנו (שמות לב לד) ועתה לך נחה את העם אל אשר דברתי לך וידברו הכשדים למלך ארמית (דניאל ב ד) והורשתם והאבדתם מהר כאשר דבר ה' אלהיך לך (דברים ט ג) וכן האמירה בשניהם (שמות ג יג) ואמרו לי מה שמו מה אומר אליהם ו "את אשר דברתי לך" פירושו שאמרתי לך עתה שאתן לך את הארץ ולזרעך ואברך אותך
@600 **ונקית משבועתי זאת** . לא הרשה אותו לקחת לו אשה מבנות כנען אבל שיהיה הוא פטור וה' הטוב בעיניו יעשה ורש"י כתב וקח לו אשה מבנות ענר אשכול וממרא ואם כנענים הם חלילה לו ובאמת שהם מזרע כנען שהכתוב אומר (לעיל יד יג) ממרא האמורי אחי אשכול ואחי ענר ובבראשית רבה (נט ח) אמרו אשר לא תקח אשה וגו' הזהירו בבנות כנען ענר אשכול וממרא כי עליהם אמר "אשר אנכי יושב בקרבו" כי הוא לא היה יושב בכל הכנעני כי עמים רבים היו אבל הזהיר על אלה בעלי בריתו וכל שכן על האחרים אבל ונקית משבועתי שיהיה הוא פטור ואברהם הוא היודע ביצחק הצדיק שישמע לאביו ושיזהר בהם וילך לו אל ישמעאל או ללוט ויתר העמים ויתכן כי "משבועתי זאת" רמז למה שאמר ולקחת אשה לבני משם כי אולי היתה השבועה על הכל ולא ירמוז לאשר אמר לו לא תקח אשה לבני מבנות הכנעני וזה טעם "זאת" ולכך אמר העבד ואפנה על ימין או על שמאל (להלן פסוק מט) ולא אמר "אשובה לי"
@602 **וכל טוב אדוניו בידו** . לשון רש"י שטר מתנה שכתב לו כל אשר לו כדי שיקפצו לשלוח לו בתם וכן בבראשית רבה (נט יא) דייתיקי ולדעת זו מה שכתוב (להלן כה ה) ויתן אברהם את כל אשר לו ליצחק לומר שהחזיק אותו בנכסים בשעת פטירתו שלא יערערו בו כמו שאמר וישלחם מעל יצחק בנו בעודנו חי ואם כן תהיה מלת הלקיחה מושכת "וכל טוב אדוניו בידו" לקח בידו או ויקח העבד עשרה גמלים וכל טוב אדוניו בידו וילך ואחרים מפרשים כי העבד כאשר נשבע מיד הלך מעצמו ולקח עשרה גמלים מגמלי אדוניו כי כל טוב אדוניו היה בידו והוא פקיד ונגיד על הכל לקחת ממנו כאשר ירצה כמו שאמר (לעיל פסוק ב) המושל בכל אשר לו והנכון בעיני כי טעם הפסוק הזה כטעם הכתוב בחזאל (מלכים ב ח ט) וילך חזאל לקראתו ויקח מנחה בידו וכל טוב דמשק משא ארבעים גמל אף כאן אמר כי לקח כל טוב אדוניו בידו משא עשרה גמלים והענין כי כל הטוב והמעולה במינים ההם פירות ומגדנות מכל הנמצא בדמשק או בבית אדוניו לקחו משא הגמלים והוליכו מנחה בידם וכן (להלן מה כג) עשרה חמורים נושאים מטוב מצרים והמקראות יקצרו לשונם במובן
@606 **אותה הוכחת לעבדך ליצחק** . לשון רש"י ראויה היא לו שהיא גומלת חסדים וראויה ליכנס בביתו של אברהם ובה אדע לשון תחינה הודיעני בה שעשית חסד עם אדוני ואם כן יאמר ידעתי כי באמת אותה הוכחת לעבדך ליצחק ואינו נקשר יפה אבל פירושו הקרה נא לפני היום הזה המקרה שתהיה הנערה אשר אומר אליה אותה שהוכחת לעבדך ליצחק ועשה בזה חסד עם אדוני אברהם כי בה אדע כי עשית חסד עמו אם תהיה ממשפחתו וטובת שכל ויפת מראה וכן אמר (להלן פסוק מג) והיה העלמה היא האשה אשר הוכיח ה'
@607 **אשר ילדה לבתואל בן מלכה** . בעבור שהיה לנחור בנים מפלגשו ראומה ייחסו לעולם בתואל בן מלכה ובעבור שהנערה הזכירה אם אביה תחלה בת בתואל אנכי בן מלכה כי כן דרך הנערות כדרך ותגד לבית אמה (להלן פסוק כח) לכן יזכירנו הכתוב כי הוא בן מלכה אשת נחור אבל העבד אמר ותאמר בת בתואל בן נחור (שם מז) כי תיקן הדבר בדרך מוסר אבל אמר אשר ילדה לו מלכה לומר שהוא בן הגבירה
@609 **וירץ העבד לקראתה** . לשון רש"י לפי שראה שעלו המים לקראתה ובבראשית רבה (ס ה) ותמלא כדה ותעל כל הנשים יורדות וממלאות מן העין וזו כיון שראו אותה המים מיד עלו אמר לה הקב"ה את סימן ברכה לבניך נראה שדקדקו כן מלשון ותמלא כדה ותעל שלא אמר "ותשאב ותמלא" ונעשה לה הנס בפעם הראשונה כי אחרי כן כתוב "ותשאב" והעבד כשספר להם אמר (להלן פסוק מה) ותרד העינה ותשאב אולי לא יאמינו
@614 **ויקח האיש נזם זהב ושני צמידים על ידיה** . הכתוב הזה יחסר המעשה שהיה צריך שיאמר "ויקח האיש נזם זהב ויתן על אפה ושני צמידים על ידיה" ולכך אני אומר כי פירושו ויקח האיש נזם זהב ושני צמידים שיהיו על ידיה ויאמר לה בת מי את ואחרי שאמרה אליו "בת בתואל אנכי" שם הנזם על אפה והצמידים על ידיה כאשר אמר להם אבל חסר כאן הנתינה וכן במקומות רבים
@624 **ויבא האיש הביתה** . אליעזר הוא האיש הבא ויפתח הגמלים יחזור על לבן שעשה עם אורחיו דרך מוסר ויפתח גמליהם ויתן להם תבן ומספוא ונתן מים לרחוץ רגלי אליעזר ורגלי האנשים אשר אתו כי רחוק הוא שיהיה אליעזר הוא הנותן מים לרחוץ רגליו ורגלי אנשיו וכן ויעברו אנשים מדינים סוחרים וימשכו ויעלו את יוסף מן הבור (להלן לז כח) כי "וימשכו" חוזר אל אחיו הנזכרים בפסוק הראשון וכן ויאמר ציבא אל המלך ככל אשר יצוה אדוני המלך את עבדו כן יעשה עבדך ומפיבושת אוכל על שולחני כאחד מבני המלך ( ט יא) והם דברי דוד ורבים כן וענין ויפתח הגמלים שפתח מוסרי צוארם כי המנהג להוליכם קשורים או שהיו הולכים חגורים במושב המרכבה אשר עליהם כלשון אל יתהלל חוגר כמפתח (מלכים א כ יא) התפתחי מוסרי צוארך (ישעיהו נב ב) ורש"י כתב התיר זמם שלהם שהיה סותם פיהם שלא ירעו בשדות אחרים ולשון בראשית רבה (ס ח) התיר זממיהם רבי הונא ורבי ירמיה שאל לרבי חייא ברבי אבא לא היו גמליו של אברהם אבינו דומים לחמורו של רבי פנחס בן יאיר וכו' וזו שאלה לסתור פתוח הזמם כי אי אפשר שיהיה החסידות בביתו של רבי פנחס בן יאיר גדול יותר מביתו של אברהם אבינו וכאשר חמורו של רבי פנחס בן יאיר איננו צריך להשתמר מן הדברים האסורים לבעליו להאכילו כל שכן גמליו של אברהם אבינו ואין צריך לזממם כי לא יאונה לצדיק כל און
@637 **וטעם והנה רבקה יצאת וכדה על שכמה** . כי בהיותו בביתה שמע את שמה או מתחילה הגידה לו שמה אע"פ שלא נזכר
@653 **ותקם רבקה ונערותיה** . סיפר הכתוב כי אחר שנתנו רשות שתלך רבקה ומיניקתה ועבד אברהם ואנשיו קמה רבקה וקראה נערותיה ותרכבנה על הגמלים ותלכנה אחרי האיש כי הוא מורה הדרך לפניהם וטעם ויקח העבד את רבקה וילך לספר בזריזותו כי אחרי צאתו מן העיר ותלכנה כל הנשים אחריו לקח העבד את רבקה עמו לא יפרד ממנה לשומרה בדרך מכל מכשול ורבי אברהם אמר כי טעמו שהיה הולך עם רבקה ולא הרגיש עד שבא יצחק ופגע בו
@654 **בא מבוא באר לחי ראי** . יאמר כי יצחק בא עתה מבוא באר לחי ראי ששב מבאר לחי שבא שמה שאלו אמר "בא מבאר לחי ראי" היה נראה שהיה דר שם ולכך הוצרך לפרש כי הוא שב לעירו מביאתו שבא אל באר לחי רואי לפי שעה כי הוא יושב בארץ הנגב וחוזר לעירו ויתכן בעבור היות "מבוא" מקור שהיה יצחק הולך תמיד אל המקום ההוא כי הוא לו מקום תפלה בעבור הראות שם המלאך והוא יושב בארץ הנגב קרוב משם וכן תרגם אונקלוס אתא ממיתוהי ועל דעתו הוא באר שבע שתרגם "בין קדש ובין שור" (לעיל כ א) ו"בין קדש ובין ברד" (לעיל טז יד) "רקם וחגרא" ואם כן המקום ההוא מקום אשל אברהם ראוי לתפלה והנה יצחק בא מן הבאר ההיא אל עיר אחרת אשר היתה בדרך עירו ויצא לפנות ערב לשוח בשדה עם רעיו ואוהביו אשר שם ומצא את העבד ורבקה והלכו כלם יחדו אל עירו ויביאה האהלה שרה אמו
@656 **ותרא את יצחק** . לשון רש"י ראתה אותו הדור ונתביישה ממנו ורבי אברהם פירש כי הפסוק האחרון מוקדם כי "ותאמר אל העבד" וכבר אמרה אל העבד ורבים בתורה כן על דעתו ובאמת שימצאו מהם אבל בכאן איננו נכון שיצטרך לערב שתי המקראות ותשא רבקה את עיניה ותרא את יצחק ותאמר אל העבד מי האיש הלזה ההולך בשדה לקראתנו ויאמר העבד הוא אדוני ותפול מעל הגמל ותקח הצעיף ותתכס ולדעתי בראות רבקה איש הולך לקראתה בשדה שירט הדרך והלך בשדה לעומתם ידעה כי הוא בא לראותם ולקרוא לשלום או להכניסם אל ביתו ללון עשתה כדרך מוסר הנשים לעמוד בהצנע
@656 "ותפול מעל הגמל" - לשון רש"י השמיטה עצמה לארץ כתרגומו ואתרכינת כמו הטי נא כדך (לעיל פסוק יד) ארכיני ויט שמים וירד (תהלים יח י) וארכין ודומה לו כי יפול לא יוטל (שם לז כד) אם יטה לארץ לא יגיע לקרקע ואין דעת אונקלוס שהשמיטה עצמה מן הגמל לארץ שאם כן הנה היא נופלת מעל הגמל ממש לא מוטה מעליו וכן כל לשון "הרכנה" הטיה לצד אחד בלבד אבל כוונתו כי מעל הגמל אשר היא רוכבת עליו הטת עצמה לצד אחד להסב פניה ממנו וכמוהו לדעתי ויראה נעמן רץ אחריו ויפול מעל המרכבה לקראתו ויאמר השלום (מלכים ב ה כא) שאין ענינו רק שהשפיל עצמו במרכבה לקראת הרץ אשר היה בארץ לשאול לו בשלום וכן אמר (שם כו) כאשר הפך איש מעל מרכבתו לקראתך או יהיה אצל אונקלוס "מעל הגמל" כמו "על הגמל" וכן מעל שמים חסדך (תהלים קח ה) וכזו המ"ם לא יהיה משם עוד עול ימים וזקן (ישעיהו סה כ) וכן המים אשר מעל השמים (תהלים קמח ד) ועל דרך הפשט הוא כמו והנה עם רב הולכים מדרך אחריו ( יג לד) וכן רבים
@659 **ויביאה יצחק האהלה שרה אמו** . חסר הנסמך וכמוהו רבים וטעם הכתוב כי יספר בכבוד שנהג יצחק באמו כי מעת שמתה שרה לא נטו אהלה כי אמרו לא תבא אשה אחרת אל אהל הגבירה הנכבדת וכאשר ראה רבקה הביאה אל האהל ההוא לכבודה ושם לקחה וזה טעם ויאהבה וינחם ירמוז שהיה מצטער מאד על אמו ורחק ממנו מנחם עד שנחם באשתו באהבתו אותה כי מה טעם שיזכיר הכתוב אהבת האיש באשתו ואונקלוס פירש ויביאה יצחק האהלה והנה היא שרה אמו ולכן הזכיר האהבה כי מפני צדקתה וכשרון מעשיה אהבה ונחם בה וכך הזכירו בבראשית רבה (ס טז) עד שלא מתה שרה היתה ברכה מצויה בעיסה
@662 **אשורים ולטושים ולאומים** . לשון רש"י שהם ראשי אומות ותרגומו של אונקלוס אין לישבו עם לשון המקרא ולי נראה שסבר אונקלוס ב"אשורים" שהם המחנות שיירות הולכי דרך מעיר לעיר כמו שאמר אורחת ישמעאלים (להלן לז כה) עשאו מלשון באשורו אחזה רגלי (איוב כג יא) לא תמעד אשוריו (תהלים לז לא) וסבר ב"לטושים" שהם השוכנים באהלים שהם נטושים על פני האדמה היום ישכנו במקום ההוא ולמחר במקום אחר כי הלמ"ד והנו"ן יומרו במקומות רבים כמו לשכה ונשכה ויפקדו ביום ההוא אנשים על הנשכות (נחמיה יב מד) ומזה חרב נטושה (ישעיהו כא טו) כמו לטושה ואמר ב"לאומים" "ולנגון" בלשון איים ומלת "היו" עוררה אותו בזה שהיה ראוי שיאמר כמו שאמר (לעיל י יג) ומצרים ילד את לודים ואת ענמים ואת להבים ואת נפתוחים ובבראשית רבה (סא ה) רבי שמואל בר רב נחמן אמר אף על גב דאנן מתרגמינן ואמרין תגרין ולפדין וראשי אומים כלם ראשי אומות הן והענין כמו שפירשתי כי היו המתרגמין עושים אשורים תגרין הולכי דרך והיו עושין מן לטושים אנשי רשע פניהם פני להבים בוערים כלפידים מן ללטוש את מחרשתו ואת אתו (שמואל א יג כ) ילטוש עיניו לי (איוב טז ט) ואמר רבי שמואל בר רב נחמן שאף על פי שנהגו לתרגם כן אינם אלא ראשי אומות אין בהם שם תואר כלל וכך הדבר
@665 **ולבני הפילגשים אשר לאברהם** . על דרך הפשט בעבור שנאמר לו (לעיל כא יב) כי ביצחק יקרא לך זרע לא בזרע אחר היו כל נשיו אצלו פילגשים לא היו נחשבות לנשים שאין זרען ביורשיו כי הגר שפחת שרה פילגשו היתה אבל קטורה לאשה לקח לו ואם היתה שפחה בביתו ולקחה לפילגש לא היה אומר "ויקח אשה ושמה קטורה" רק תקרא פילגש בכתוב מפני הטעם שפירשתי ובדברי הימים (א א לב) כתוב ובני קטורה פילגש אברהם והנה אברהם לקח לו אשה מבנות כנען ואם תאמר שהיתה מצרית או מארץ פלשתים הנה לא שלח אל ארצו ואל מולדתו כאשר עשה בבנו כי איננו שומר רק זרע יצחק כי עליו נכרת הברית ועוד שלא אמר הכתוב "ויקח אשה קטורה בת פלוני החוי או הפלשתי והמצרי מארץ פלונית" כאשר אמר בנשי עשו (להלן כו לד) וזולתן אבל הזכיר שמה בלבד כי היא כנענית וקצר ביחוסה וכן יעשה במקומות רבים כשלא יקפיד בייחוס שלהן ואולי תקרא פילגש בעבור היותה שפחה ממשפחת העבדים ואם היתה שפחה בביתו ובא אליה לא יזכיר ייחוסה כי אין דרך הכתוב להזכיר באמהות רק שמן כענין בזלפה ובלהה ורש"י כתב נשים בכתובה פילגשים שלא בכתובה כדאמר בנשים ופילגשים דדוד בסנהדרין (כא) ואין הדבר כן כי לא תקרא פילגש אלא כשהיא בלא קדושין כי הכתובה מדברי סופרים והגירסא בסנהדרין פילגש בלא כתובה וקדושין אבל אפשר שגם בני נח כאשר ישאו להם נשים כמשפטן בבעילה היו נוהגים לכתוב להן מהר ומתן ואשר רצונה שתהיה להם פילגש וישלח אותה כאשר ירצה ולא יהיו בניה בנוחלים את שלו לא היה כותב לה כלום ועל דעת רבותינו (ב"ר סא ד) שהיא הגר הנה היא פילגש ודאי
@667 **זקן ושבע** . שראה כל משאלות לבו ושבע כל טובה וכן ושבע ימים (להלן לה כט) ששבעה נפשו בימים ולא יתאוה שיחדשו בו הימים דבר וכענין שנאמר בדוד וימת בשיבה טובה שבע ימים ועושר וכבוד (דהי"א כט כח) והוא ספור חסדי השם בצדיקים ומדה טובה בהם שלא יתאוו במותרות כענין שנאמר בהם תאות לבו נתת לו (תהלים כא ג) ולא כמו שנאמר בשאר האנשים אוהב כסף לא ישבע כסף (קהלת ה ט) ואמרו בו (קהלת רבה א יג) אין אדם יוצא מן העולם וחצי תאוותיו בידו יש בידו מנה מתאוה מאתים השיגה ידו למאתים מתאוה לעשות ארבע מאות שנאמר אוהב כסף לא ישבע כסף ובבראשית רבה (סב ב) אמרו הקב"ה מראה להם לצדיקים מתן שכרן שהוא עתיד ליתן להם לעולם הבא ונפשם שבעה והם ישנים נתעוררו החכמים בזה ופירשו הכתוב שאומר "ושבע" במראה הזו
@668 **ויקברו אותו יצחק וישמעאל בניו** . לשון בראשית רבה (סב ג) כאן בן האמה חולק כבוד לבן הגבירה
@670 **וישב יצחק עם באר לחי ראי** . קרוב אל המקום ההוא או בעבור שאיננו עיר אמר כי נטה אהלו אצל הבאר
@676 **ואלה שני חיי ישמעאל** . הקרוב בדרך הפשט כי הכתוב יספר בבני הצדיקים תולדותם ומספר חייהם להודיע כי זרע צדיקים יבורך ולא ספר ימי עשו כי חיה יותר מיעקב וכבר נשלם הספור במות יעקב ולא רצה לחזור אלה חיי עשו שכבר הזכיר תולדותיו במקום הראוי להם ובמדרש רבותינו בסיפור ימי ישמעאל טעמים רבים (עיין מגילה יז) והנכון שבהם שהיה צדיק בעל תשובה וסיפר בו כדרך הצדיקים
@676 "ויגוע" - לשון רש"י לא נאמרה גויעה אלא בצדיקים ובגמרא (ב"ב טז) הקשו והא דור המבול נאמר בהם גויעה ויגוע כל בשר הרומש על הארץ וגו' וכל האדם (לעיל ז כא) כל אשר בארץ יגוע (לעיל ו יז) ומתרץ גויעה ואסיפה קאמרינן כוונתם כי הגויעה מיתה בלא חולי מכאיב ובלא יסורין ואין זוכין לה אלא הצדיקים ואנשי דור המבול ההפוכים כמו רגע ולא חלו בהם ידים וכן מתי מדבר ועל כן אמר בהם גויעה בגוע אחינו (במדבר כ ג) וכן והוא איש אחד לא גוע בעונו (יהושע כב כ) שלא המית אותו עונו פתאום אבל כשיזכיר הכתוב כן עם זכרון המיתה כמלת ויאסף או וימת תרמוז למיתת הצדיקים ולשון בראשית רבה (סב ב) ויגוע וימת אברהם (לעיל פסוק ח) אמר רבי יהודה בר אילעי החסידים הראשונים היו מתיסרין בחולי מעים בעשרה ובעשרים יום לומר שהחולי ממרק רבי יהודה אומר כל מי שנאמרה בו גויעה מת בחולי מעים ושם (לעיל ו יז) אמרו וכל אשר בארץ יגוע יצמוק ויראה שמלת גויעה אצלם המק בשרו והוא עומד על רגליו (זכריה יד יב) וכן דעת אונקלוס שתרגם בכאן ואתנגיד והוא העלוף כלשון אתנגיד ואתפח (סנהדרין לט) יכול ישלם חמשה נגידים (ב"ק סז) ונאמר כן במבול כמו שאמר (לעיל ז כג) וימח את כל היקום ונאמר ויגוע וימת כגבר יחלש וימות והיא מיתה בצדיקים חסלת פרשת חיי שרה
@678 **ואלה תולדות יצחק בן אברהם** . על עשו ויעקב בניו האמורים למטה והזכיר הכתוב איך היתה ילידתם אברהם הוליד את יצחק לשון רש"י על ידי שכתוב יצחק בן אברהם הוזקק לומר אברהם הוליד את יצחק לפי שהיו ליצני הדור אומרים מאבימלך נתעברה שרה לכך צר הקב"ה קלסתר פניו דומה לאברהם שיאמרו הכל אברהם הוליד את יצחק ורבי אברהם אמר עוד שטעם הוליד גדל ורבה כמו יולדו על ברכי יוסף כמו שאמר וישלחם מעל יצחק בנו והנכון בעיני כי חזר עתה והחל באב היחס כמנהג הכתוב לחזור באנשי המעלה אל ראש היחס וכן בדברי הימים (א א יז יח) כתוב בני שם עילם ואשור וארפכשד ולוד וארם וארפכשד ילד את שלח וכאשר השלים חזר ואמר (שם כד) שם ארפכשד שלח עד אברם הוא אברהם וכן ביחוס בנימין חזר למפרע והחל ונר הוליד את קיש וקיש הוליד את שאול (שם ח לג ט לט) אף כאן אברהם הוליד את יצחק ויצחק הוליד את יעקב כאשר יזכיר וחזר לספר זה בעבור שאמר (לעיל כה יב) ואלה תולדות ישמעאל בן אברהם שאם אמר גם כן ואלה תולדות יצחק בן אברהם בלבד הנה השווה שניהם ביחוס ובמעלה ואף כי הקדים הבכור ועוד שהיה ראוי שיתחיל באברהם ויאמר "אלה תולדות אברהם" אבל לא רצה לעשות כן שלא ימנה ישמעאל ובני קטורה ולכך חזר והשלים אברהם הוליד את יצחק לומר כי הוא לבדו תולדותיו וכאלו לא הוליד אחר יחשב כמו שנאמר לו (לעיל כא יב) כי ביצחק יקרא לך זרע ולכך אמר למעלה (כה יב) גם כן אשר ילדה הגר המצרית שפחת שרה לאברהם לכבוד יצחק לומר שאין אלו תולדות היחס לאברהם רק הם בני האמה וכמו שאמר (לעיל כא יג) וגם את בן האמה לגוי אשימנו וכן עשה הכתוב אף בדברי הימים (א א כח) כי אמר מתחילה בני אברהם יצחק וישמעאל ואלה תולדותם בכור ישמעאל נביות והזכיר ובני קטורה פילגש אברהם ילדה את זמרן והיה ראוי שיאמר "בני יצחק" וחזר והחל ויולד אברהם את יצחק בני יצחק עשו וישראל
@681 **ותאמר אם כן למה זה אנכי** . אם כן גדול צער העבור למה זה אנכי מתפללת ומתאוה על ההריון לשון רש"י ואיננו נכון ורבי אברהם אמר כי שאלה את הנשים אם אירע להם ככה ותאמרנה לא ותאמר אם כן הדבר והמנהג למה זה אנכי בהריון משונה והנה הכתוב חסר ואיננו שלם בפירוש הזה והנכון בעיני כי אמרה אם כן יהיה לי למה זה אנכי בעולם הלואי אינני שאמות או שלא הייתי כטעם כאשר לא הייתי אהיה (איוב י יט)
@681 "ותלך לדרוש את ה'" - לשון רש"י להגיד מה יהא בסופה ולא מצאתי דרישה אצל ה' רק להתפלל כטעם דרשתי את ה' וענני (תהלים לד ה) דרשוני וחיו (עמוס ה ד) חי אני אם אדרש לכם (יחזקאל כ ג)
@682 **וטעם שני גוים בבטנך** . הודיע לה שלא תפחד כי בעבור שהיתה מעוברת תאומים הוא הריצוץ הזה בבטנה כי דרך נשים לה ויתכן שיאמר עוד כי בעבור היותם שני גוים שונאים ונלחמים זה בזה עשו בתחלת יצירתם מריבה רמז למה שיהיה ביניהם בסוף ועתה ינוחו ותמצא מנוח והשקט לנפשה
@687 **כי ציד בפיו** . אמרו המפרשים (הראב"ע והרד"ק) כי יתן ציד בפיו של יצחק או יביא ויחסר המעשה וכן למועד אשר שמואל (שמואל א יג ח) וה' אותי כגבור עריץ (ירמיהו כ יא) נתן או שם אותי ויתכן לפרש ויאהב יצחק את עשו בעבור כי בפיו של יצחק ציד תמיד כל היום יתאוה לאכול את הציד ותמיד הוא בפיו לא יאכל דבר אחר והוא המביא לו כאשר אמר איש יודע ציד והנכון בעיני כי היא מליצה כי עשו ציד בפי אביו יכנה האיש במעשה לתדירותו וכמוהו שבתך בתוך מרמה (ירמיהו ט ה) וכן ואני תפלה (תהלים קט ד) וכן אמרו בבראשית רבה (סג ו) קופרא טבא לפומיה כסא טבא לפומיה
@689 **מן האדום האדום הזה** . היה התבשיל מאודם מן העדשים שהיו אדומות או שרקחו בדברים אדומים ועשו לא ידע מה הוא וקרא שמו אדום על כן קרא שמו אדום כי לעגו עליו שמכר בכורה נכבדת בעבור תבשיל מעט כי סובא וזולל יורש (משלי כג כא)
@690 **מכרה כיום את בכורתך לי** . כיום דילהן כיום שהוא ברור כן מכור לי מכירה גמורה לשון רש"י ופשוטו כעת הזאת וכן ואתה עמוד כיום ואשמיעך את דבר אלהים (שמואל א ט כז) אותו כהיום תמצאון אותו (שם יג) קטר יקטירון כיום את החלב (שם ב טז) ולנו בשת הפנים כהיום הזה (דניאל ט ז) והנראה מדעת אונקלוס כי בעבור היות מכירת הבכורה לאחר מיתת אביהם אמר מכרה לי הבכורה לאיזה יום שתפול בו וזה שמוש "להן" בלשון ארמית להן את אזיל לאיזה מקום מן הן את מודע לי וכן בפרשת וישלח (ב"ר עח א) ולהן אינון אזלין מן הן דאתברון והוא לשון מורגל להם במקומות הרבה ובדניאל (ב יא) בפתחות הלמד כטעם אלהן להן אלהין די מדרהון עם בשרא לא איתוהי וכן להן מלכא מלכי ישפר עלך (שם ד כד) ואונקלוס תרגם זולתי "אלהין" אלא הן ובנוסחאות בדוקות ומדוקדקות מן התרגום כיום דלהי והוא כמו שפירשתי כי הי בלשונם איזה כמו שאומר בתלמוד (ב"ק צט) הי רבי מאיר הי רבי יהודה (ב"ב קמא) וזולתן ואפשר שעשה אונקלוס "כיום" כאלו הוא "ביום" מכרה ביום שתבא בו הבכורה כי כן מצאנו השמוש הזה לכ"ף כאשר ילכו אפרוש עליהם רשתי (הושע ז יב) משפטו באשר וכדמי בניך אשר נתתה להם (יחזקאל טז לו) כי כארבע רוחות השמים פרשתי אתכם (זכריה ב י) ויש אומרים (הרד"ק בשם אביו) כי אין מחיר הבכורה הנזיד רק הכתוב יספר כי בבקשו לאכול והוא עיף אמר לו יעקב מכור לי בכורתך בכסף ואחר כך אכול וענה לו בפחזותו על האכילה למה זה לי בכורה הרי היא מכורה לך ונשבע עליה וישבו לאכול ולשתות והכתוב לא פירש המחיר ואין זו דעתי
@692 **השבעה לי כיום** . כאשר אמר עשו למה זה לי בכורה אינני חפץ בה אמר לו יעקב השבעה לי כי לא תחפוץ בה ולא תירשנה לעולם ונשבע לו ואחר כן מכרה לו ונתן לו המחיר או הנזיד שבקש ויתכן שאמר עשו למה זה לי בכורה הנה היא מכורה לך ויאמר השבעה לי שלא תערער על המכירה לעולם ואמר הכתוב שנשבע לו ומכרה כאלו אמר מכרה ונשבע לו
@693 **ויבז עשו את הבכורה** . בז לדבר יחבל לו (משלי יג יג) אבל כבר אמר הטעם שבעבורו נאות למכירה מפני שהיה הולך למות בצודו החיות וקרוב הוא שימות בחיי אביו ואין לבכורה שום מעלה רק אחרי האב ומה תועיל לו הבכורה ואמר ויאכל וישת ויקם וילך ויבז כי אחר שאכל ושתה חזר השדה אל צידו וזו סיבת בזוי הבכורה כי אין חפץ בכסילים רק שיאכלו וישתו ויעשו חפצם בעתם ולא יחושו ליום מחר ורבי אברהם משתבש בכאן מאד שאמר כי בזה הבכורה בעבור שראה שאין ממון לאביו ורבים יתמהו כי עזב לו אברהם ממון רב וכאלו לא ראו בימיהם עשיר גדול בנעוריו בא לידי עוני בזקוניו והעד שהיה יצחק אוהב את עשו בעבור צידו ואלו היה לחם רב בבית אביו והוא נכבד בעיניו לא מכר את בכורתו בעבור נזיד ואם היה אביו בכל יום אוכל מטעמים מה טעם יאמר אליו הביאה לי ציד ולמה לא היו ליעקב בגדים חמודות ולא נתנה לו אמו כסף וזהב לדרך שאמר (להלן כח כ) ונתן לי לחם לאכול ובגד ללבוש למה לא שלחה לו הון והיא אוהבת אותו כי הוצרך לשמור הצאן והפסוק שאמר (להלן כו יג) ויגדל האיש קודם זקנתו ועורי לב יחשבו כי העושר מעלה גדולה לצדיקים והנה אליהו יוכיח ועוד ישאלו למה חסר השם ממון ליצחק אולי יודיעונו למה חסר מאור עיניו ואל ידחונו בקנה של דרש כי יש לו סוד ואין לנו לחפש כי עמקו מחשבות השם ואין כח באדם להבינם כל אלו דבריו ואני תמה מי עור עיני שכלו בזה כי הנה אברהם הניח לו הון רב ואבד העושר ההוא מיד קודם הענין הזה ומפני זה בזה את הבכורה כי הדבר הזה היה בנעוריהם קודם היות לעשו נשים כאשר יספר הכתוב ואחרי כן חזר והעשיר בארץ פלשתים עד כי גדל מאד ויקנאו בו שרי פלשתים ואחרי כן חזר לעניו והתאוה לציד בנו והמטעמים ואין אלו רק דברי שחוק ועוד כי הכתוב אמר (לעיל כה יא) ויהי אחרי מות אברהם ויברך אלהים את יצחק בנו והברכה תוספת בעושר ובנכסים וכבוד ואיה ברכתו שאבד הון אביו והעני ואחרי כן (להלן כו ג) ואהיה עמך ואברכך העשיר והעני אחרי כן ואם יש צדיקים שמגיע אליהם כמעשה הרשעים בענין העושר אין זה באותם שנתברכו מפי הקב"ה כי ברכת ה' היא תעשיר ולא יוסיף עצב עמה (משלי י כב) אבל היו האבות כלם כמלכים ומלכי גוים באים לפניהם וכורתים עמהם ברית וכתוב (להלן כו לא) וישבעו איש לאחיו ואם היה יצחק רע המזל מאבד נכסי אביו איכה אמרו ראו ראינו כי היה ה' עמך (שם כח) וכבר היה בעוכריו אבל בזוי הבכורה לעשו לאכזריות לבו ויתכן כי פי השנים בבכורה ממשפטי התורה לא היה כן לפנים רק לנחול מעלת האב ושררתו שיהיה לו כבוד ומעלה על צעירו ולכן היה אומר ליצחק אני בנך בכורך (להלן כז לב) לומר כי הוא הבכור הראוי להתברך וכן כי זה הבכור שים ימינך על ראשו (להלן מח יח) להקדימו בברכה ואולי היה נוטל גם בנחלה יותר מעט כי דין פי שנים מחדוש משפט התורה והציד אשר היה בפיו כן יעשו השרים והמלכים בוחרים בציד מכל מאכל וכל העמים יובילו מהם שי למורא והיה עשו מחניף את אביו להביא כל צידו אל פיו לאכול ממנו כרצונו תמיד ואהבת האב לבנו הבכור קלה להביא ומה שאמר לברך אותו אחר עשות לו המטעמים איננו שכר האכילה ושחד בהם אבל רצה ליהנות ממנו שתהיה נפשו קשורה בנפשו בעת ההנאה ויברך אותו בחפץ מלא ורצון שלם או שהיה יודע בנפשו כי אחר האכילה היתה מתענגת ושמחה ויחול עליה רוח הקודש כענין ועתה קחו לי מנגן והיה כנגן המנגן ותהי עליו יד ה' (מלכים ב ג טו) ולא נתנו ביד יעקב הון כי בורח היה ובלא ידיעת אחיו יצא מן הארץ לבדו ואלו נתנו לו הון ועבדים וגמלים היו מוסיפים בו קנאה לארוב לו ולהרגו ורבותינו אמרו (ב"ר סח ב) שגזלוהו ממנו ומי אמר לו שלא היו ליעקב בגדים חמודות שש ומשי ורקמה אבל הכתוב אמר כי עשו בלכתו השדה לצוד היה מחליפם בבגדי הציד ומפני שיצחק ממשש תמיד בבנו ובבגדיו הלבישה אותם את יעקב פן יכירנו בהם והלא אתה רואה שעשה כן וירח את ריח בגדיו (להלן כז כז) כי היה משים אותם בתוך נרד וכרכום כענין שכתוב (תהלים מה ט) מור ואהלות קציעות כל בגדותיך והיו הבשמים צומחים בארץ ישראל ועל כן אמר "כריח שדה" כי בעבור היותו איש שדה הריחו בגדיו מהם או ריח ציצי האילנות כמו שאמרו רבותינו (תענית כט) כריח השדה של תפוחים והשאלה על מאור עיניו שאלת עורי לב כי אם היתה סבה מאת השם הנה היא כדי שיברך את יעקב והוא ספור הכתוב (להלן כז א) ותכהין עיניו מראות ויקרא את עשו ועל דרך הפשט איננו רק ענין הזקנה וטעמו ויהי כי זקן יצחק ותכהינה עיניו בזקנתו קרא את עשו והנה ביעקב (להלן מח י) ועיני ישראל כבדו מזוקן לא יוכל לראות וכתוב באחיה השילוני (מלכים א יד ד) כי קמו עיניו משיבו ויספר במשה רבינו פלא (דברים לד ז) לא כהתה עינו
@694 **מלבד הרעב הראשון אשר היה בימי אברהם** . אולי לא היה רעב בעולם עד ימי אברהם (פרקי דר"א כו) ועל כן ימנה הכתוב ממנו כי מה צורך להזכיר זה והנכון בעיני כי זה להגיד כי היו זוכרים אותו הרעב הראשון ומספרים עליו שבעבורו ירד אברהם למצרים ושם עשה לו השם כבוד גדול ולכן היה יצחק חפץ ללכת בדרך אבותיו לירד שם עד שנאמר לו אל תרד מצרימה וטעם המניעה אמרו רבותינו (ב"ר סד ג) אתה עולה תמימה ואין חוצה לארץ כדי לך ולדעתי נכלל עוד בענין רמיזה בעתיד כי גלות אברהם אל מצרים מפני הרעב רמז שיגלו בניו שם ולכתו אל אבימלך לא היה גלות כי שם היה יושב ברצונו אבל ירידתו של יצחק שם מפני הרעב ירמוז לגלות כי גלה ממקומו בעל כרחו והלך אל ארץ אחרת והנה היה גלותו ממקומו אל ארץ פלשתים שהיא ארץ מגורי אביו וירמוז לגלות בבל שהוא מקום מגורי אבותם שהיו באור כשדים ודע כי הגלות הנזכר ירמוז למעשה יצחק כאשר לא לקחו אשתו ולא היה לו שם רק הגלות והפחד ומתחילה אמר הנוגע באיש הזה ובאשתו מות יומת ולימים חזר בו ואמר לך מעמנו ואחרי כן חזרו אליו בברית וכן גלות בבל גלו שם מפני זלעפות רעב ומעת היותם שם לא עבדום ולא ענו אותם אבל היו גדוליהם שרים במלכות ואחרי כן אמרו מי בכם מכל עמו יהי אלהיו עמו ויעל (עזרא א ג) והזהירו עליהם שרי עבר הנהר והפחות ואחרי כן בטלו הבנין והות בטלא עד זמן ועידן אחרי כן חזרו ונתנו רשות בבנין והזהירו ואמרו די להון מהקרבין ניחוחין לאלה שמיא ומצלין לחיי מלכא ובנוהי (שם ו י)
@694 "אל אבימלך מלך פלשתים" - לא נודע אם הוא אבימלך אשר היה בימי אברהם או שכל מלך פלשתים בעת ההיא יקרא כן כי גם בימי דוד יקרא אבימלך ודעת אונקלוס שהיה בנו וטעם וילך יצחק אל אבימלך כי היה בדעתו לרדת מצרימה והלך אל אבימלך בעל ברית אביו אולי ייטיב עמו בימי הבצורת ולא יצטרך לירד למצרים והנה אבימלך מפני בריתו של אברהם לא נגע בו ולא בביתו כלל אבל אנשי המקום המה בקשו ממנו דרך שאלה על אשתו והוא אמר אחותי היא ואף על פי כן לא נגע בה המלך ולא איש מאנשיו כי היו נזכרים בענין אברהם ולכך אמר כמעט שכב "אחד העם" יאמר אני לא נגעתי בה ונשמרתי ממנה אבל קרוב היה שיכשל בה אחד מאנשי הארץ והיית מביא עלינו אשם כאשר היה עלינו חטא בענין אביך
@695 **שכון בארץ אשר אומר אליך** . אין טעם שיאמר בבת אחת "שכון בארץ אשר אומר אליך גור בארץ הזאת" אבל פירושו אל תרד מצרימה ושכון כל ימיך בארץ שאומר אליך בכל פעם ופעם על פי ה' תסע ועל פי ה' תחנה וגור עתה בארץ הזאת בארץ פלשתים כי לך ולזרעך אתן אותה כדכתיב (יהושע יג ג) לכנעני תחשב חמשת סרני פלשתים ויתכן שיהיה "וירא אליו" מוקדם כי קודם צאתו ממקומו נאמר לו אל תרד מצרימה שכון בארץ אשר אומר אליך בהיותך שם וגור עתה בארץ הזאת בארץ כנען אשר תכלול עמים רבים וארצות רבות כי אני מצוך עתה שלא תצא ממנה לעולם כי כל הארצות האל אתן לזרעך והנה נסע ממקומו מפני הרעב ללכת בכל ארצות כנען לשכון בארץ אשר יאמר אליו ובבאו לגרר אמר לו כאן תשב ולא הוצרך לפרש כי ידוע הוא שלא עבר על מצות השם וכן על אחד ההרים אשר אומר אליך (לעיל כב ב) כאשר הזכרתי (שם פסוק ט)
@696 **והקמותי את השבועה** . אין צריך שיבטיח הקב"ה את יצחק שלא יעבור השבועה שנשבע לאביו כי לא אדם הוא להנחם (שמואל א טו כט) ואברהם אין לו זרע אחר בעל ברית לאלהים והשבועה איננה על תנאי כי ביעקב הוצרך מפני עשו אחיו לומר שבו יתקיים הברית ובזרעו (להלן לה יב) לא בעשו ונראה שזה המאמר "והקמותי את השבועה" יחשב שבועה ולכך תמיד יאמר בתורה (שמות לג א) הארץ אשר נשבעתי לאברהם ליצחק וליעקב אשר נשבעת להם בך (שם לב יג) כי לא מצאנו שבועה ליצחק בלתי זאת ורצה הקב"ה להשבע לכל אחד מן האבות להודיע שראוי כל אחד לכרות עמו ברית ושתהיה זכות כל אחד עומדת לפניו עם זרעם כי אף על פי שהראשונה תספיק תוספת זכות וכבוד הוא להם ולכן אמר (ויקרא כו מב) וזכרתי את בריתי יעקב ואף את בריתי יצחק ואף את בריתי אברהם אזכור והארץ אזכור כי כלם בעלי ברית לאלהים ויתכן שהוסיף לו ליצחק בשבועה הזאת שיקיים בו בעצמו השבועה אשר נשבע לאברהם אביו שיהיה הוא ברכה בעמים כאשר אמר לאברהם אביו והתברכו בזרעך כל גויי הארץ ויהיה פירוש הכתוב והקמותי בך את השבועה אשר נשבעתי לאברהם אביך כי אתה ברכה בעמים וכן אמר עוד ביעקב (להלן כח יד) ונברכו בך כל משפחות האדמה ובזרעך
@698 **וישמור משמרתי** . לשון רש"י בקולי כשנסיתי אותו משמרתי גזירות להרחקה כגון שניות לעריות שבות לשבת מצותי מצות שאלו לא נכתבו דין הוא שיכתבו כגון גזל ושפיכות דמים חקותי דברים שיצר הרע ועו"ג משיבין עליהם כגון אכילת חזיר ולבישת שעטנז שאין טעם בדבר אלא המלך גזר חקו על עבדיו ותורתי להביא תורה שבעל פה הלכה למשה מסיני ואם כן יהיה כל זה בנוי על דעת שהיה אברהם מקיים ומשמר את התורה עד שלא נתנה וכך אמרו (ב"ר צד ג) בפסוק ויתן להם יוסף עגלות (להלן מה כא) שפירש ממנו בפרשת עגלה ערופה שהיה עוסק בתורה כשם שהיו אבותיו ועד עכשו לא נתנה תורה והרי כתוב וישמור משמרתי מצותי חקותי ותורותי ושם אמרו שהיה משמר אפילו דקדוקי תורה והיה מלמד לבניו וכו' ויש לשאול אם כן איך הקים יעקב מצבה (להלן כח יח) ונשא שתי אחיות וכדעת רבותינו (ב"ר עד יא) ארבע ועמרם נשא דודתו (שמות ו כ) ומשה רבינו הקים שתים עשרה מצבה (שם כד ד) והאיך אפשר שיהיו נוהגים היתר בתורה במה שאסר אברהם אביהם על עצמו וקבע לו השם שכר על הדבר והוא יצוה את בניו ואת ביתו אחריו ללכת בדרכיו וביעקב דרשו (ב"ר עט ו) ששמר את השבת וקבע תחומין ואפשר שיהיה זה בשבת מפני שהיא שקולה ככל התורה כולה (ירושלמי ברכות פ"א ה"ה) שהיא מעידה על מעשה בראשית ואולי נאמר משמרתי שניות לעריות של בני נח ומצותי גזל ושפיכות דמים חקותי אבר מן החי וכלאים של הרבעת בהמה והרכבת אילן ותורותי דינין ואסורי עבודה זרה שאלו כולן נצטוו בהן בני נח והוא השומר והעושה רצון בוראו ומשמר אפילו דקדוקין וחומרות במצות שלהן וכמו שהזכירו ע"ז של אברהם אבינו ארבע מאה פרקי הוות (ע"ז יד) ודרשו ב"מאה שערים" שמדדוה למעשרות (ב"ר סד ו) כי היו האבות נדיבי עמים לתת מעשרות לעניים או לכהני ה' כגון שם ועבר ותלמידיהם כענין והוא כהן לאל עליון (לעיל יד יח) והנראה אלי מדעת רבותינו שלמד אברהם אבינו התורה כלה ברוח הקדש ועסק בה ובטעמי מצותיה וסודותיה ושמר אותה כולה כמי שאינו מצווה ועושה ושמירתו אותה היה בארץ בלבד ויעקב בחוצה לארץ נשא האחיות וכן עמרם כי המצות משפט אלהי הארץ הן אף על פי שהוזהרנו בחובת הגוף בכל מקום (קדושין לו) וכבר רמזו רבותינו הסוד הזה (בספרי דברים פסקא מג) ואני אעירך בו בעזרת השם (ויקרא יח כה דברים יא יח) והמצבה מצוה שנתחדשה בזמן ידוע היא כמו שדרשו (בספרי) באשר שנא ה' אלהיך (דברים טז כב) ששנאה אחר היותה אהובה בימי האבות וביוסף דרשו (ב"ר צב ד) שהיה משמר את השבת אפילו במצרים מפני שהיא שקולה כנגד כל המצות לפי שהיא עדות על חדוש העולם והיה עושה כן ללמד את בניו אמונת בריאת העולם להוציא מלבם כונת עבודה זרה ודעות המצרים וזאת כונתם ועל דרך הפשט נאמר שיהא משמרתי אמונת האלהות שהאמין בשם המיוחד ושמר משמרת זו בלבו וחלק בה על עובדי העבודה זרה וקרא בשם ה' להשיב רבים לעבודתו מצותי ככל אשר צוהו בלך לך מארצך ועולת בנו וגרישת האמה ואת בנה חקותי ללכת בדרכי השם להיות חנון ורחום ועושה צדקה ומשפט ולצות את בניו ואת ביתו בהם ותורותי המילה בעצמו ובניו ועבדיו ומצות בני נח כלן שהן תורה להם
@700 **ויאמר אחותי היא** . ועל הבנים לא שאלוהו כי יאמר בני אשה אחרת הם לו
@707 **ויהי לו מקנה צאן ומקנה בקר ועבודה רבה** . אתונות וגמלים וחמורים ועבדים ושפחות ויזכיר הכתוב זה ולא יזכיר כסף וזהב כאשר נאמר באברהם (לעיל יג ב) בעבור כי גדולתו אשר נתגדל בה בארץ פלשתים במקנה ובעבודה היתה ויקנאו אותו פלשתים בענין ההוא וזה טעם כי עצמת ממנו מאד אמר לו גם לי שאני המלך אין בביתי מקנה ועבודה כמוך וחרפה היא לנו להיות ביתך גדול מבית המלך
@710 **בנחל גרר** . רחוק מן העיר וישב ויחפור את בארות המים אשר חפרו בימי אברהם אביו ופלשתים סתמום קודם שנסע יצחק מגרר חזר וחפרן לשון רש"י ונראה מדבריו שהם הבארות הנזכרים כאן כמו שאמר (בפסוק טו) סתמום פלשתים וימלאום עפר וזה איננו כן כי היאך יתנו לו הם רשות והם אמרו "תקלה הם לנו מפני הגייסות" אבל הם אחרים במקום אחר כי נחל גרר שם מקום או שהנחל נמשך מגרר אל ארץ אחרת וכאשר קנאו בו פלשתים הם השרים אשר בגרר מדינת המלך סתמו הבארות אשר לו מירושת אביו בגבול עיר גרר והמלך שלחו מעיר מושב כסאו והלך לו לעיר אחרת ואולי איננה ממלכותו אף על פי שהיא בארץ פלשתים ושם בארות אחרים שחפר אברהם שגר במקום ההוא ימים רבים ופלשתים יושבי הארץ כאשר מת אברהם ויצחק לא ישב שם סתמום ולא לשנאתו רק בימי אברהם לא רצו לסתמם מפני כבודו כי אמרו אולי ישוב לשבת בארץ ולכן שב יצחק ויחפור אותם בנחל ורועי נחל גרר רבו עמו לאמר לנו המים והטעם "לאמר" הנה הבאר בנחל ומימי הנחל הם אשר ימצו שם ומתמציתם ימלא הבור והנחל יתמעט בהם והנה הם שלנו ועל כן הזכיר הכתוב וימצאו שם באר "מים חיים" לאמר כי היה מקור נובע מים חיים אין מימיו מן הנחל כאשר אמרו מריביו
@713 **ויקרא שם הבאר עשק** . יספר הכתוב ויאריך בענין הבארות ואין בפשוטי הספור תועלת ולא כבוד גדול ליצחק והוא ואביו עשו אותם בשוה אבל יש בדבר ענין נסתר בתוכו כי בא להודיע דבר עתיד כי "באר מים חיים" ירמוז לבית אלהים אשר יעשו בניו של יצחק ולכן הזכיר באר מים חיים כמו שאמר (ירמיהו יז יג) מקור מים חיים את ה' וקרא הראשון עשק ירמוז לבית הראשון אשר התעשקו עמנו ועשו אותנו כמה מחלוקות וכמה מלחמות עד שהחריבוהו והשני קרא שמה שטנה שם קשה מן הראשון והוא הבית השני שקרא אותו כשמו שכתוב בו (עזרא ד ו) ובמלכות אחשורוש בתחילת מלכותו כתבו שטנה על יושבי יהודה וירושלם וכל ימיו היו לנו לשטנה עד שהחריבוהו וגלו ממנו גלות רעה והשלישי קרא רחובות הוא הבית העתיד שיבנה במהרה בימינו והוא יעשה בלא ריב ומצה והאל ירחיב את גבולנו כמו שנאמר (דברים יט ח) ואם ירחיב ה' אלהיך את גבולך כאשר דבר וגו' שהוא לעתיד וכתיב בבית השלישי (יחזקאל מא ז) ורחבה ונסבה למעלה למעלה ופרינו בארץ שכל העמים יעבדוהו שכם אחד
@717 **אל תירא כי אתך אנכי** . בעבור שהבריחו אבימלך מעליו מקנאתם בו וגם רועי גרר רבו עמו היה מתירא פן יאספו עליו ויכוהו הוא וביתו והבטיחו הקב"ה שלא יירא מהם ויברך אותו ואז נתן בלבם שהלך לפניו המלך בכבוד גדול יותר מאשר עשה לאביו כי בא עם פיכול שר צבאו ועוד הוסיף להביא עמו רבים רעיו
@722 **אם תעשה עמנו רעה כאשר לא נגענוך** . יאמר אם תעשה עמנו רעה כמו שאנחנו לא נגענוך אתה עתה ברוך ה' ואין לאל ידינו לעשות עמך רע אבל ישתנה העת בעבור החמס שאתה עושה ותצטרך לשוב אל ארצנו ונשיב לך גמול וטעם לא נגענוך שלא נפתה לבנו על אשתך ליגע באחד מכם כלשון הנוגע באיש הזה ובאשתו ועשינו עמך רק טוב לשמור את כל אשר לך בצוותינו את העם להשמר מכם ונשלחך בשלום כי גם בקנאתנו בך לא לקחנו מכל העושר אשר עשית עמנו ונשלחך עם כל אשר לך בשלום וענין היראה הזאת אשר פחדו ממנו אינו נראה שירא מלך פלשתים שלא יבא עליו יצחק למלחמה אבל הבטיחם אברהם לו ולנינו ולנכדו (לעיל כא כג) ועתה אמרו בלבם בעבור שהפרנו אנחנו את בריתנו עם יצחק ושלחנוהו מעלינו גם הוא יפר את בריתו עמנו ויגרש זרעו את זרעינו מן הארץ ולכן עשו עמו ברית חדשה והתנצלו לאמר לו שלא הפרו הברית הראשונה שלא עשו עמו רק טוב וזה טעם תהי נא אלה בינותינו שנבא עתה עמך באלה להחרים על כל מי שיעבור על הברית כטעם לעברך בברית ה' אלהיך ובאלתו (דברים כט יא) ויתכן שהיה אברהם גדול מאד ורב כח שהיו בביתו שלש מאות איש שולף חרב ולו בעלי ברית רבים והוא גם בן חיל אשר לבו כלב האריה ורדף ארבעה מלכים גבורים מאד ונצחם וכאשר ראו הצלחתו כי היא מאת האלהים פחד ממנו מלך פלשתים פן יכבוש ממנו מלכותו ונקל זאת ממלחמת ארבעת המלכים אולי שמע עוד דבר השם שנתן לו הארץ ולכן בא עמו בברית והשביעו אם תשקור לי ולנכדי כי היה שקר אם ימרוד על המלך וחשב כי אפשר שיחיה אברהם עד מלוך נכדו וכמעשה אבות עשו בנים כי היה יצחק גדול כאביו ופחד המלך פן ילחם בו בגרשו אותו מארצו
@725 **ויבואו עבדי יצחק ויגידו לו על אודות הבאר אשר חפרו** . הוא האמור בו למעלה (בפסוק כה) ויכרו שם עבדי יצחק באר כי החלו לחפור אותו ובא אבימלך אליו בימים ההם וביום הברית בלכתם ממנו בשרוהו כי מצאו מים וקרוב לי שהוא הבאר שכרה אברהם ונתן לו שבע כבשות לעדה (לעיל כא ל) כי סתמוהו פלשתים עם האחרים וישב יצחק ויחפור אותו ויקרא לו גם הוא שם כשם אשר קרא לו אביו ועל כן שם העיר באר שבע על שם הבאר אשר קראוהו כן האב והבן כי שם נשבעו שניהם והבאר הזאת להם תרמז על משכן שילה ופלשתים סתמוהו בהלקח הארון (שמואל א ד יא) וחזר וחפרו בו כי כן השיבו הארון עם הדורון לאלהים (שם ו יא)
@732 **בעבור תברכך נפשי** . היה בדעתו לברך אותו שיזכה הוא בברכת אברהם לנחול את הארץ ולהיות הוא בעל הברית לאלהים כי הוא הבכור ונראה שלא הגידה לו רבקה מעולם הנבואה אשר אמר ה' לה ורב יעבוד צעיר כי איך היה יצחק עובר את פי ה' והיא לא תצלח והנה מתחלה לא הגידה לו דרך מוסר וצניעות כי ותלך לדרוש את ה' שהלכה בלא רשות יצחק או שאמרה "אין אנכי צריכה להגיד נבואה לנביא כי הוא גדול מן המגיד לי" ועתה לא רצתה לאמר לו "כך הוגד לי מאת ה' טרם לדתי" כי אמרה באהבתו אותו לא יברך יעקב ויניח הכל בידי שמים והיא ידעה כי בסבת זה יתברך יעקב מפיו בלב שלם ונפש חפצה או הם סבות מאת ה' כדי שיתברך יעקב וגם עשו בברכת החרב ולו לבדו נתכנו עלילות
@735 **ואברככה לפני ה' לפני מותי** . לא נזכר בכל הפרשה לפני ה' רק במקום הזה כי אמרה לו אמו הברכה לפני ה' תהיה ברוח הקדש ואם יתברך בה עשו אחיך תתקיים בו בזרעו לעולם ואין לך עמידה לפניו
@740 **אולי ימשני אבי** . אין הטעם שימושהו להכיר אותו אבל אמר אולי יקרב אותי אל עצמו לנשק לי או לשום ידו על פני כדרך חבת האב על בנו וימצא במשוש שאני חלק ואני תמה איך לא פחד מהיכר הקול וכל בני אדם נכרים בקולם כמו שאמרו רבותינו (גיטין כג) היאך סומא מותר באשתו והיאך בני אדם מותרין בנשותיהן בלילה אלא בטביעות עינא דקלא ואם סתם בני אדם מכירין כן מה יהיה ביצחק החכם והבקי להכיר בין בניו שתהיה לו באמת טביעות בקול אולי היו האחים האלה דומים בקולם ולכך אמרו (ב"ר סה יט) כי הקול קול יעקב דבריו שמדבר בלשון רכה ומזכיר שם שמים או שהיה משנה קולו לדבר כלשון אחיו כי יש בבני אדם יודעים לעשות כן
@743 **עשו בנה הגדול ויעקב בנה הקטן** . להפליג בענין הצדקת כי המנהג במולידים להכיר את הבכור בברכה ובכבוד ובמתן והיא מדעתה צדקת הקטן ורשעת הגדול תשתדל בכל הטורח הזה להעביר הברכה והכבוד מן הגדול אל הקטן וכן יאמר למטה (פסוק מב) ויגד לרבקה את דברי עשו בנה הגדול ותשלח ותקרא ליעקב בנה הקטן
@749 **גשה נא ואמשך בני** . לשון רש"י אמר בלבו אין דרך עשו להיות שם שמים שגור בפיו וכן בבראשית רבה ואני תמה כי לא היה עשו רשע בעיני אביו ואולי היה חושב בלבו כי בעבור היותו איש שדה ולבו על הציד איננו מזכיר שם שמים מפחדו שלא יזכירנו במקום שאינו טהור ומבלי כוונה ונחשב לו זה בעיני אביו ליראת שמים ועל דרך הפשט יהיה זה בעבור טביעות הקול
@756 **מטל השמים** . אין הברכה שיתן לו האלהים מטל השמים כי הטל ירד בכל מקום ואלו אמר שיתן רבוי טל או שירד בעתו כענין ונתתי גשמיכם בעתם (ויקרא כו ד) היתה ברכה אבל פירושו כי הזכיר בו ברכת ה' כריח שדה אשר ברכו ה' והטעם אשר ברכו ה' לבני כי השם ברך אותו בשדה לומר שיצליחנו שם בצידו ולא ימות ולא תבואהו בו רעה ואמר
@756 "ויתן לך האלהים מטל השמים ומשמני הארץ" - והברכה תוספת ורבוי או שיהיה ורב דגן ותירש בתוספת הוא"ו ושיעורו ויתן לך האלהים מטל השמים ומשמני הארץ רב דגן ותירוש והנכון בעיני כי מתת האלהים תמיד הוא ואין לו הפסק לעולם ולכן אמר ויתן לך האלהים כל ימיך על אדמתך מטל השמים ויתן לך משמני הארץ כלומר השמנה בכל הארצות כענין שכתוב (יחזקאל כ ו) צבי היא לכל הארצות ורבי אברהם אמר כי מ"ם מטל מושך עצמו ואחר עמו וממשמני הארץ ולעשו לא נתנו במתת אלהים ולא ברבוי אבל אמר גם לך אצלתי אחריו ומשמני הארץ ומטל השמים יהיה מושביך בעוד אשר תשב שם ירמוז כי יכלה ויאבד אך בעודו יהיה חלקו טוב
@757 **ארריך ארור ומברכיך ברוך** . ובבלעם הוא אומר (במדבר כד ט) מברכיך ברוך ואורריך ארור הצדיקים תחלתן יסורין וסופן שלוה ואורריהן קודמין למברכיהן והרשעים תחלתן שלוה וסופן יסורין לפיכך הקדים בלעם ברכה לקללה לשון רש"י מבראשית רבה (סו ד) ואם כן למה אמר הקב"ה לאברהם (לעיל יב ג) ואברכה מברכיך ומקללך אאור וזה איננו קשה כי חזר שם ונברכו בך והנה הברכה בראש ובסוף או בעבור מה שפירשנו שם דבר בלשון יחיד ורבים כי הכל יברכוהו והיחיד אשר יקלל אותו יואר
@760 **מי אתה** . כאשר אמר לו "יקום אבי" היה חושב שהוא יעקב וידע שאכל מציד עשו וברך אותו ועשה גם הוא מטעמים שיברך גם אותו ולכן שאלו מי אתה לדעת האמת
@761 **בטרם תבא ואברכהו גם ברוך יהיה** . אין דרך החרד חרדה גדולה עד מאד וצועק "מי הוא אשר רמני לברך אותו" שישלים צעקתו לאמר מיד "גם ברוך יהיה" אבל היה ראוי שיקללהו ועוד כי היה עשו צועק עליו לאמר "ולמה תברכהו עתה אבי" ואיך יאמין עשו כי במרמה היה מתחלה בראותו כי עתה יברך אותו ברצונו והנכון בעיני שהוא לשון הווה יאמר מי איפוא הוא הצד ציד אשר היה יכול לרמותי שאברכהו וגם שיהיה ברוך על כל פנים כי ידעתי כי ברוך הוא או טעמו וגם ברוך יהיה על כרחי שאי אפשר לי להעביר הברכה ממנו כי מאז שברך אותו ידע ברוח הקדש שחלה ברכתו עליו וזהו טעם החרדה הגדולה אשר חרד כי ידע שאבד בנו האהוב לו ברכתו לעולם וזה טעם בא אחיך במרמה כי אחר שאמר מי איפוא נתן דעתו שהבא אליו היה יעקב שאי אפשר שתחול הברכה רק בזרעו
@765 **ואת כל אחיו נתתי לו לעבדים** . איננו ברכת "הוה גביר לאחיך" שכבר אמר הן גביר שמתיו לך אבל יתכן שיהיה הוא הגביר ולא יהיו הם עבדים כענין כי יהודה גבר באחיו (דהי"א ה ב) אבל אמר "נתתי לו לעבדים" ממאמרו וישתחוו לך בני אמך כי הוא השתחואת העבד לאדוניו כמו שאמר "יעבדוך עמים" ויכפול וישתחוו לך לאומים וטעם ואת כל אחיו כטעם "אחיך" ו"בני אמך" יזכירם בלשון רבים לרמוז על כל זרעו של עשו ורבי אברהם אמר בני הפילגשים
@767 **הנה משמני הארץ יהיה מושבך** . טעם "הנה" לאמר הנה אוכל לתת לך משמני הארץ ומטל השמים כי לשניכם יספיק שיהיה משמני הארץ וטל השמים אבל בענין הממשלה שלו תהיה ולו תעבוד ולא נתן לו גם כן רב דגן ותירוש כאחיו כי רצה לכבד המבורך ראשונה עליו ואחרי כן אמר ליעקב ויתן לך את ברכת אברהם לרשתך את ארץ מגוריך (להלן כח ד) להיות לו רב הדגן והתירוש בארץ כנען מתנת אברהם ולעשו יהיה הטל ומשמני הארץ בארץ אחרת
@768 **וטעם ועל חרבך תחיה** . כמו בחרבך וכן כי לא על הלחם לבדו יחיה האדם (דברים ח ג) בלחם ואין הברכה שתהיה מחיתו משלל האויבים בחרבו כי הנה נתן לו משמני הארץ ומטל השמים ובה יחיה אבל הענין לומר שיחיה במלחמותיו כי ינצח ולא יפול בחרב אויב ועל כן אמר ואת אחיך תעבוד שלא תתגבר עליו והוא יגבר עליך והיה כאשר תריד בשיחך מתגרת ידו ופרקת עלו מעל צוארך ירמוז לישראל שלא יתגרו בם יותר מדאי לעשות עמם רעה והוא מה שצוה הכתוב (דברים ב ד-ה) ונשמרתם מאד אל תתגרו בם וגו' וכך הזכירו רבותינו (ירושלמי ר"ה א א) אמרו כי ששת חדשים ישב שם יואב וכל ישראל עד הכרית כל זכר באדום (מלכים א יא טז) אמר לו הקב"ה אני אמרתי אל תתגרו בם ואתה התגרית בהם חייך שאין ששה חדשים הללו נמנין לך ולמלכותך מדכתיב (שם ב יא) והימים אשר מלך דוד על ישראל ארבעים שנה והוא מלך ששה חדשים יותר דכתיב ( ה ה) בחברון מלך על (ישראל) יהודה שבע שנים וששה חדשים ועוד אמרו (דב"ר א טז) אמר לו הקב"ה דוד ידיך חדודות וחרוצות ואני מבקש לרדות בהם את עולמי וכו'
@769 **ויאמר עשו בלבו** . אמר רבי אברהם יתכן שגלה סודו לאחד מאוהביו ואין צורך כי ההסכמה בדבר אשר ימלך אדם עם לבו תקרא אמירה עם הלב אף על פי שיהיה בה דבור בשפתים וכן בלב ולב ידברו (תהלים יב ג) כי הרצון יקרא "לב" וכל ישראל לב אחד להמליך את דוד (דהי"א יב לח) שהיו כלם על אותה ההסכמה והיו מדברים בה וכן ויאמר ירבעם בלבו (מלכים א יב כו) וכן אמר אליעזר (לעיל כד מה) אני טרם אכלה לדבר אל לבי והיתה שם תפלה בשפתיו ויאמר ה' אלהי אדני אברהם (שם יב) אבל טרם אכלה לדבר אל לבי טרם השלימי מה שעלה בדעתי
@769 "ויאמר" - כאן כי כאשר באה משטמה גדולה בנפש עשו לשטום את יעקב על הברכה עלה בלבו שיהרוג את אחיו והיה מתנחם בזה מרוע לבו וזה טעם ויגד לרבקה את דברי עשו ולכך אמרה מתנחם לך ורש"י כתב ברוח הקודש הוגד לה מה עשו מהרהר בלבו וכן בבראשית רבה (סז ט) ואם כן יהיה "דברי עשו" מחשבתו עם הלב כמו דברתי אני עם לבי (קהלת א טז) והנה עשו היה אומר יקרבו ימי אבל אבי כי בחייו לא יצערנו או מפחדו שלא יקללנו ותהפך ברכתו לקללה ורבקה פחדה שמא ימות הזקן פתאום ויהרגנו או שמא יזדמן לו בחייו ויהרגנו
@770 **וטעם ותשלח ותקרא ליעקב** . כי היה יעקב במקום אחר איננו באהל אביו ואמו כי היה מתחבא מפני עשו אחיו שהיה צועק עליו והיה מתבייש ממנו או מתפחד
@770 "מתנחם לך להרגך" - מתנחם הוא על הברכות בהריגתך לשון רש"י ופשוטו מתנחם בך וכן כי בוחר אתה לבן ישי (שמואל א כ ל) והחזיק לו (שם ב טו ה) ורבים כן או פירושו מתנחם עליך כמו כי כן צוה לו המלך (אסתר ג ב) אבל אונקלוס אמר כמין לך אורב לך ונראה מדעתו כי טעם מתנחם לך שמראה עצמו לך מנוחם על ענין הברכות וכאלו אינו מקפיד בהן והוא מארב כדי שלא תשתמר ממנו ותרגם הענין לא הלשון
@779 **אחי רבקה אם יעקב ועשו** . בעבור שאמר שצוה יצחק את יעקב לקחת לו אשה מבנות לבן אחי אמו הזכיר הכתוב שהיה גם כן אחי אמו של עשו וראוי היה שיצוה גם כן לעשו אבל מדעתו שברכת אברהם תהיה ליעקב ולזרעו עשה כן והזכיר כי עשו שמע שצוה אותו שלא יקח אשה מבנות כנען ושילך אל לבן אחי אמו והוא שמע לעשות רצון אביו שלא לקחת אשה מבנות כנען אך לא עשה כראוי שיקח מבנות לבן אף על פי שהוא אחי אמו ועוד הזכיר שלקח אותה על נשיו ולא גרש את הרעות כי הלך על תאות נפשו יותר מרצון אביו חסלת פרשת תולדות
@786 **והנה סלם מצב ארצה וראשו מגיע השמימה והנה מלאכי אלהים עולים ויורדים בו** . הראהו בחלום הנבואה כי כל הנעשה בארץ נעשה על ידי המלאכים והכל בגזרת עליון עליהם כי מלאכי אלהים אשר שלח ה' להתהלך בארץ לא יעשו קטנה או גדולה עד שובם להתיצב על אדון כל הארץ לאמר לפניו התהלכנו בארץ והנה יושבת בשלוה או מלאה חרב ודם והוא יצוה עליהם לשוב לרדת בארץ ולעשות דברו והראהו כי הוא יתברך נצב על הסלם ומבטיחו ליעקב בהבטחה גדולה להודיע שהוא לא יהיה ביד המלאכים אבל יהיה חלק ה' ויהיה עמו תמיד כמו שאמר והנה אנכי עמך ושמרתיך בכל אשר תלך כי מעלתו גדולה משאר הצדיקים שנאמר בהם (תהלים צא יא) כי מלאכיו יצוה לך לשמרך בכל דרכיך ועל דעת רבי אליעזר הגדול (פרקי דר"א לה) היתה זאת המראה כענין בין הבתרים לאברם כי הראהו ממשלת ארבע מלכיות ומעלתם וירידתם וזה טעם "מלאכי אלהים" כמו שנאמר בדניאל (י כ יג) שר מלכות יון ושר מלכות פרס והבטיחו כי הוא יתעלה יהיה עמו בכל אשר ילך ביניהם וישמרנו ויצילנו מידם אמרו (שם בפדר"א) הראה לו הקב"ה ארבע מלכיות מושלן ואבדן הראהו שר מלכות בבל עולה שבעים עוקים ויורד והראהו שר מלכות מדי עולה חמישים ושנים עוקים ויורד והראהו שר מלכות יון עולה מאה ושמונים עוקים ויורד והראהו שר מלכות אדום עולה ואינו יורד אמר לו יעקב אך אל שאול תורד (ישעיהו יד טו) אמר לו הקב"ה אם תגביה כנשר וגו' (עובדיה א ד)
@791 **כי אם בית אלהים וזה שער השמים** . הוא בית המקדש שהוא שער לעלות משם התפלות והקרבנות לשמים וכתב רש"י אמר רבי אלעזר בשם ר' יוסי בן זמרא (ב"ר סט ה) הסולם הזה עומד בבאר שבע ושיפועו מגיע עד בית המקדש שבאר שבע עומד בדרומו של יהודה וירושלם בצפונו בגבול שבין יהודה ובנימין ובית אל היה בצפון של נחלת בנימין בגבול שבין בנימין ובין בני יוסף נמצא סולם רגליו בבאר שבע וראשו בבית אל מגיע שפועו כנגד ירושלם ושאמרו רבותינו (חולין צא) צדיק זה בא לבית מלוני ועוד אמרו (פסחים פח) יעקב קראו בית אל וזו לוז היא ולא ירושלם ומהיכן למדו לומר כן אני אומר שנעקר הר המוריה ובא לכאן וזו היא קפיצת הארץ האמורה בשחיטת חולין (חולין צא) שבא בית המקדש לקראתו עד בית אל וזהו ויפגע במקום ואם תאמר כשעבר יעקב אבינו על בית המקדש מדוע לא עכבוהו שם איהו לא יהב דעתיה להתפלל במקום שהתפללו אבותיו ומן השמים יעכבוהו איהו עד חרן אזל כדאמרינן בפרק גיד הנשה (שם) וקרא מסייע לן וילך חרנה כי מטא לחרן אמר אפשר עברתי על מקום שהתפללו בו אבותי ולא התפללתי בו יהב דעתיה למהדר וחזר עד בית אל קפצה ליה ארעא עד בית אל כל אלו דברי הרב ולא נראה לי כלל שאין קפיצת הארץ שהזכירו ביעקב אלא כאותה שאמרו באליעזר עבד אברהם שבא ביום אחד לחרן כמו שאמרו בסנהדרין (צה) שלשה קפצה להם הארץ אליעזר עבד אברהם ויעקב אבינו ואבישי בן צרויה ופירשו אליעזר עבד אברהם דכתיב (לעיל כד מב) ואבא היום אל העין למימרא דההוא יומא נפק יעקב דכתיב ויפגע במקום כי מטא לחרן אמר אפשר שעברתי על מקום שהתפללו אבותי ולא התפללתי בו כיון דהרהר בדעתיה למהדר קפצה ליה ארעא מיד ויפגע במקום הנה בפירוש אומרים שכיון שעלה בלבו בחרן לחזור קפצה לו הארץ ופגע במקום שהתפללו בו אבותיו לא שחזר לבית אל ולא שקפץ הר המוריה ובא לשם ובבראשית רבה (נט יא) עוד עשו שניהם שוים בקפיצה אמרו ויקם וילך אל ארם נהרים (לעיל כד י) בר יומו ואבא היום אל העין היום יצאתי והיום באתי וביעקב דרשו (ב"ר סח ח) כן וילך חרנה רבנין אמרין בר יומו ומה טעם שיקפוץ הר המוריה ויבא עד בית אל אחר שטרח יעקב לחזור מחרן ועד בית אל מהלך כמה ימים ועוד כי בית אל איננו סוף גבול ארץ ישראל מפאת חרן כי חרן ארץ קדם הוא ועוד שאין האמצעות נקרא שפוע הסולם ועוד מה טעם להיותו כנגד בית אל והאמצע איננו מורה על דבר יותר מכולו אבל מדרשים הללו ענין אחר להם אמרו שם בבראשית רבה (סח ה) אמר רבי הושעיה כבר כתיב (לעיל כח ז) וישמע יעקב אל אביו ואל אמו וילך פדנה ארם ומה תלמוד לומר ויצא יעקב מבאר שבע אלא אמר אבא בשעה שבקש לצאת לחוצה לארץ מהיכן הורשה לו לא מבאר שבע אף אני הריני הולך לבאר שבע אם נותן לי רשות הריני יוצא ואם לאו איני יוצא לפיכך הוצרך הכתוב לומר ויצא יעקב מבאר שבע וכוונת המדרש הזה כי הם סבורים שיעקב בחברון נתברך שהוא ארץ מגורי אביו ולשם חזר אליו שנאמר (להלן לה כז) ויבא יעקב אל יצחק אביו ממרא קרית הארבע היא חברון אשר גר שם אברהם ויצחק ואם כן הכתוב שאמר ויצא יעקב מבאר שבע כי כאשר צוהו אביו ללכת אל לבן הלך שם ליטול רשות והוא המקום שלן בו וראה מראות אלהים ונתן לו הרשות לצאת כמו שאמר ושמרתיך בכל אשר תלך והשיבותיך אל האדמה הזאת והסולם שראה לדעת רבי יוסי בן זימרא ראה שרגליו בבאר שבע במקום אשר הוא שוכב שם וסוף שיפועו שהוא ראש הסולם מגיע עד כנגד בית המקדש נסמך בשמים בפתח שהמלאכים נכנסים ויוצאים בו והשם הנכבד נצב עליו ולכן ידע שבאר שבע הוא שער השמים טוב לתפלה ובית המקדש בית אלהים ובבקר נשא יעקב רגליו מבאר שבע וילך חרנה בן יומו והיא קפיצת הדרך שלו זהו דעת רבי יוסי בן זימרא שאמר בבראשית רבה (סט ז) הסולם הזה עומד בבאר שבע ושיפועו מגיע עד בית המקדש שנאמר ויצא יעקב מבאר שבע ויירא ויאמר מה נורא המקום הזה
@791 "והאבן" - אשר שם מצבה לא במקום שכיבתו הקים אותם שהרי באר שבע איננו בית אל והוא בבית אל העמיד אותה ולשם חזר בשובו שנאמר (להלן לה א) קום עלה בית אל ועשה שם מזבח לאל הנראה אליך וגו' אבל הקים אותה כנגד השיפוע במקום שראש הסולם עומד שקרא אותו בית אלהים והיא עיר לוז ולדעתו של רבי יוסי בן זמרא לוז היא ירושלים שקראו בית אל ואפשר שיהיה כן לפי המקראות שבספר יהושע ובאמת שאיננו בית אל הסמוך לעי כי כן שם העיר ההיא לראשונה בימי אברהם וקודם לכן ורבי יהודה ברבי סימון חלק שם (בב"ר סט ז) על רבי יוסי בן זימרא ואמר הסולם הזה עומד בבית המקדש ושיפועו מגיע עד בית אל מאי טעמיה ויירא ויאמר מה נורא המקום הזה וגו' ויקרא שם המקום ההוא בית אל ודעת רבי יהודה ברבי סימון כי "ויפגע במקום" הוא הר המוריה וילן שם כי בא השמש לו בלא עתו שאמרו צדיק זה בא לבית מלוני ויפטר בלא לינה וראה הסולם רגליו במקום ההוא ושיפועו שהוא ראשו מגיע עד כנגד בית אל זה והיא עיר לוז ואמר כי זה המקום בית אלהים ושיפוע הסולם שער השמים והנה הר המוריה טוב לתפלה וגם בית אל מקום ראוי לעבוד שם האלהים והקים המצבה בבית אל כי לדעת כולם כנגד השיפוע הקים אותה ויסכים דעתו של רבי יהודה ברבי סימון עם המדרש שבגמרא בפרק גיד הנשה (חולין צא) ובפרק חלק (סנהדרין צה) שיעקב יצא מבאר שבע והלך לחרן וכשנמלך לחזור ולהתפלל במקום שהתפללו אבותיו בהר המוריה אז קפצה לו הארץ ויפגע מיד בהר המוריה ושמא דעתם שקפצה לו בהליכה ובחזרה כדברי האומר (בב"ר סח ח) וילך חרנה בן יומו ויפגע במקום מיד בפתע פתאום ומצאתי עוד מפורש בפרקי רבי אליעזר הגדול (פרק לה) אמר בן שבעים ושבע שנה היה יעקב בצאתו מבית אביו והיתה הבאר מהלכת לפניו מבאר שבע ועד הר המוריה מהלך שני ימים והגיע לשם בחצי היום וכו' אמר לו הקב"ה יעקב הלחם בצקלונך והבאר לפניך לאכול ולשתות ולשכב במקום הזה אמר לפניו רבון כל העולמים עד עכשיו יש לשמש ירידות מעלות חמשים ואני שוכב במקום הזה ובלא עתו בא השמש ממערב והביט יעקב וראה את השמש בא במערב וילן שם כי בא השמש לקח יעקב שתים עשרה אבנים מאבני המזבח שנעקד עליו יצחק אביו ושם אותם מראשותיו להודיעו שעתידין לעמוד ממנו שנים עשר שבטים ונעשו כלן אבן אחת להודיעו שכלן עתידים להיות גוי אחד בארץ שנאמר ( ז כג) ומי כעמך ישראל גוי אחד השכים יעקב בבקר בפחד גדול ואמר ביתו של הקב"ה במקום הזה שנאמר ויירא ויאמר מה נורא המקום מכאן אתה למד שכל המתפלל בירושלם כאלו מתפלל לפני כסא הכבוד ששער שמים הוא פתוח לשמוע תפלתן של ישראל שנאמר וזה שער השמים ושב יעקב ללקט האבנים ומצא אותן כלן אבן אחת ושם אותה מצבה בתוך המקום וירד לו שמן מן השמים ויצק עליה שנאמר ויצוק שמן על ראשה מה עשה הקב"ה נטל רגל ימינו וטבע את האבן עד עמקי תהומות ועשה אותה סניף לארץ כאדם שהוא נותן סניף לכיפה לפיכך נקראת אבן שתיה ששם הוא טבור הארץ ומשם נפתחה הארץ ועליה היכל ה' עומד שנאמר והאבן הזאת אשר שמתי מצבה יהיה בית אלהים ומשם נשא רגליו וכהרף עין בא לחרן עד כאן והנה המדרשים כולם אף על פי שיש ביניהם חלוף במקצת אבל כלם מודים שקפיצת הארץ היתה ליעקב שהלך מהלך כמה ימים כהרף עין ויתכן שכלם מודים זה לזה ובכל הליכותיו קפצה לו בלכתו מבאר שבע לחרן וברצותו לשוב להר המוריה ובצאתו משם לחרן ואין אחד מכל המדרשים שיאמר כדברי רש"י
@792 **וישם אותה מצבה** . כבר פירשו רבותינו (ע"ז נג) ההפרש שבין המצבה למזבח שהמצבה אבן אחת והמזבח אבנים הרבה ונראה עוד שהמצבה תעשה לנסך עליה נסך יין וליצוק עליה שמן לא לעולה ולא לזבח והמזבח להעלות עליו עולות ושלמים ובבאם לארץ נאסרה עליהם המצבה (דברים טז כב) מפני ששמו אותה הכנענים להם לחק יותר מן המזבחות אף על פי שכתוב בהם (שמות לד יג) את מזבחותם תתוצון או שלא רצה לאסור הכל והשאיר המזבח שראוי לנסך ולקרבנות
@794 **אם יהיה אלהים עמדי** . לשון רש"י אם ישמור לי הבטחות הללו שהבטיחני וטעם התנאי שלא יגרום החטא וכך אמרו בבראשית רבה (עו ב) רב הונא בשם ר' אחא הנה אנכי עמך וכתיב אם יהיה אלהים עמדי אלא מכאן שאין הבטחה לצדיקים בעולם הזה ויתכן עוד על דרך הפשט שאין הספק בדבר אבל בכל העתיד יאמר הכתוב כן כמו עד אשר אם עשיתי וכן ואם יהיה היובל לבני ישראל (במדבר לו ד) אם יבא העת שיהיה התנאי אז יתקיים המעשה כלומר בבואו
@795 **והיה ה' לי לאלהים** . איננו תנאי כדברי רש"י אבל הוא נדר וענינו אם אשוב אל בית אבי אעבוד השם המיוחד בארץ הנבחרת במקום האבן הזאת שתהיה לי לבית אלהים ושם אוציא את המעשר ויש בענין סוד ממה שאמרו (כתובות קי) כל הדר בחוצה לארץ דומה כמי שאין לו אלוה
@798 **וירא והנה באר בשדה והנה שם שלשה עדרי צאן רובצים עליה** . יאריך הכתוב בספור הזה להודיענו כי קווי ה' יחליפו כח ויראתו תתן עוז כי הנה יעקב אבינו בא מן הדרך והוא עיף ויגל לבדו האבן אשר היו צריכים אליה כל הרועים ושלשה עדרי צאן אשר להם רועים רבים ושומרים כלם רובצים עליה אינם יכולים להניעה כלל ולרבותינו בבראשית רבה (ע ח) גם בזה להם סוד רמז לעתיד כי נזדמן לו ככה שנכנס בדרך הבאר ולא נאספו כל העדרים רק שלשה מהם ובא בזמן שהאבן על פי הבאר והעדרים שומרים לה וכל הענין המסופר כאן להודיעו שיצליח בדרך הזה ויצא ממנו זרע זוכה לרמז הזה כי הבאר ירמוז לבית המקדש וג' עדרי צאן עולי שלשה רגלים כי מן הבאר ההוא ישקו העדרים שמשם היו שואבין רוח הקדש או שירמוז כי מציון תצא תורה (ישעיהו ב ג) שנמשלה למים (ב"ק יז) ודבר ה' מירושלם ונאספו שמה כל העדרים באים מלבא חמת עד נחל מצרים (מלכים א ח סה) וגללו את האבן והשקו שמשם היו שואבין רוח הקודש והשיבו את האבן מונח לרגל הבא
@801 **הידעתם את לבן בן נחור** . היה ניכר וידוע בשם אבי אביו כי הוא נכבד מאביו וראש בית אבותם כדכתיב (להלן לא נג) אלהי אברהם ואלהי נחור ויתכן שהיה בתואל אדם פחות מעלה ולא ירצה לבן שייחסו אותו האנשים רק לאבי אביו כי כן מצאנו (לעיל כד נ) ויען לבן ובתואל אולי היה כל זה למעלת אברהם כי היו כל המשפחה מתייחסים לנחור אחי אברהם
@805 **וטעם כי רועה היא** . להגיד כי אין לצאן לבן רועה אחר זולתה כי לה לבדה מסר אביה העדר והיא לבדה רועה אותם כל הימים לא תלך בהם לאה אחותה כלל ולא היה ענינה כבנות יתרו שהיו שבע בנותיו כולן רועות כאחת כמו שאמר ותבאנה ותדלנה (שמות ב טז) ואולי בעבור כי עיני לאה רכות היה השמש מזיק לה או בעבור שהיתה לאה גדולה ראויה לאיש וחשש לה אביה אבל יתרו נכבד במקומו וכהן הארץ ויראו מגשת אל בנותיו או שהיה לבן צנוע ממנו כי משפחת אברהם כשרה וצנועה ורחל היתה קטנה ואין לחוש לה וזה ענין וישק יעקב לרחל או הוא כדברי רבי אברהם (לעיל כז כה) כי נשיקה בלמ"ד איננה בפה רק נשק אותה על ראשה או על כתיפה
@808 **ותגד לאביה** . לשון רש"י אמה מתה וכך בבראשית רבה (ע יג) ולפי פשוטו לבשרו ביאת קרובו ושיצא אליו ויכבדהו כי אמה מה לה ומה תעשה לו אבל רבקה הראת את אמה התכשיטין אשר נתנו לה כמנהג הנערות
@811 **הכי אחי אתה ועבדתני חנם** . לא סיפר הכתוב שהיה יעקב עובד אותו ויתכן כי מעת שאמר וישק את צאן לבן אחי אמו לא יצא הצאן מידו כי בראותו את רחל כי רועה היא חמל עליה שלא תשוב לרעות צאן עוד והיה הוא רועה אותן באהבתו אותה ואפשר עוד לומר כי לבן דבר בערמה אמר לו מתחלה כי עצמו ובשרו הוא ויחמול עליו כאשר יחמול האדם על עצמו ועל בשרו וכאשר ראה שהיה יעקב מתעכב שם מתפרנס מאשר ללבן אמר לו הכי אחי אתה ותעבדני חנם כי ידעתי כי מעתה תעבוד אותי כי איש מוסר אתה ולא תתפרנס משל אחרים וגם אני איני רוצה שתהיה העבודה שתעבדני בחנם בלא משכורת שלימה והגידה לי מה תבקש אתה במשכורתך ואתן אז הכיר יעקב דעתו ואמר לו שיעבוד אותו ז' שנים ברחל והעבודה מן הסתם היא מרעה הצאן כי לה היו צריכים ובה היו מדברים
@817 **כי מלאו ימי** . שאמרה לי אמי ועוד כי מלאו ימי הריני בן פ"ד שנה ואימתי אעמיד י"ב שבטים לשון רש"י מלא שבוע זאת דבק הוא בחטף שבוע של זאת והן ז' ימי המשתה גם זה לשון רש"י ואם כן למה לא פירש הרב מלאו ימי על שני העבודה והתנאי ששלמו כדברי אונקלוס והוא משמעות הכתוב באמת ובשביל הימים שאמרה לו אמו גם מפני זקנתו לא יתן לו לבן בתו קודם זמנו אשר התנו שניהם ודי שיקיים תנאו וכדברי אונקלוס הוא שנצטרך לפרש מלא שבוע זאת על ימי המשתה כי ימי העבודה שלמים היו כאשר אמר לו יעקב וכן פירש רבי אברהם ואני לא ידעתי כי שבעת ימי המשתה תקנת משה רבינו לישראל (ירושלמי כתובות פ"א ה"א) ואולי נאמר שנהגו בהם מתחלה נכבדי האומות כענין באבילות דכתיב (להלן נ י) ויעש לאביו אבל שבעת ימים ומה שלמדו כאן בירושלמי (מו"ק פ"א ה"ז) ובבראשית רבה (ע יט) שאין מערבין שמחה בשמחה סמך בעלמא ממנהגי הקדמונים קודם התורה אבל בגמרא שלנו (מו"ק ט) לא למדוה מכאן ודרשוה מויעש שלמה את החג (מלכים א ח סה) ויתכן לומר כי היה זה מחלוף משכורתו עשרת מונים (להלן לא מא) כי יעקב אמר לו מתחלה כי מלאו הימים ולבן שתק ונתן לו לאה ואחר כן אמר לו לבן מלא שבוע זאת כי עדיין לא מלאו ימי עבודת לאה וקודם זמני נתתיה לך ויעקב שמע אליו וימלא אותם כדברי לבן כי מה יוכל לעשות והוא ברחל יחפוץ ולכן לא אמר הכתוב בתחילה "ויהי במלאת הימים ויאמר יעקב וגו'" ועוד יתכן לומר כי כאשר היה בשנה השביעית אמר יעקב ללבן הבה את אשתי כי מלאו ימי שזו שנת מלאת הימים וכן זקן עם מלא ימים (ירמיהו ו יא) הוא אשר הגיעו לשנת סופו וכן עד יום מלאת ימי מלואיכם (ויקרא ח לג) עד יום השביעי שבו ימלאו ימי המלואים או שאמר "מלאו" בעבור שהיו קרובים להמלא וחשובים כמלאים וכמוהו רבים וכן בסדר האחר (להלן לה יח) בצאת נפשה כי מתה בהיותה קרובה לכך וחשובה כאילו מתה וזה טעם ואבואה אליה כלומר לא שתתן אותה ואלכה אבל שאשאנה ואשלים מעט הימים אשר עלי כי מעתה לא תירא ממני שאעזבך ורבותינו עשו מדרש (ב"ר ע יח) בלשון "ואבואה אליה" בעבור שאיננו דרך מוסר להזכיר כן אף כי בצדיקים אבל הכוונה היא מה שאמרתי ואחרי כן אמר לו לבן מלא שבוע השנים של לאה זאת כי אולי בעבור שעברתי על דעתך לא תשלים אותן או כדי שיהיה ידוע מתי התחילו ימי עבודת רחל ואז אתן לך האחרת בעבודה אשר תעבוד עמדי לאחר הנישואין
@823 **ונתנה לך** . לשון רבים נרדה ונבלה שם (לעיל יא ז) ונשרפה (שם פסוק ג) אף זה לשון ונתן זה פירש"י ולא אמר למה יתפוס היחיד לשון הרבים אולי יחשוב שהוא דרך הנכבדים בלשון הקדש כמאמר אחרים (ראה ראב"ע לעיל א כו) ורבי אברהם אמר בכאן (שם) שהוא בנין נפעל והו"ו השיבו לעתיד ופירושו ותנתן לך והנכון בעיני כי דברי לבן בערמה אמר ליעקב לא יעשה כן במקומנו כי לא יניחוני אנשי המקום לעשות כן כי נבלה הוא אצלם אבל תמלא שבוע זאת ונתן לך אני וכל אנשי המקום גם את זאת שכלנו נסכים בדבר ונעשה לך כבוד ומשתה כאשר עשינו בראשונה
@826 **ויאהב גם את רחל** . הזכיר הכתוב שגם אהב רחל יותר מלאה והטעם בעבור כי הטבע לאהוב יותר האשה אשר ידע האדם בראשונה כענין שהזכירו חכמים בנשים (סנהדרין כב) ואינה כורתת ברית אלא למי שעשאה כלי והנה יעקב אהב רחל מלאה שלא כדרך הארץ וזה טעם "גם"
@827 **כי שנואה לאה** . הנה לאה רמתה באחותה גם ביעקב כי אם נאמר שנהגה כבוד באביה שאחז בה והכניסה אליו ואל תמר בו היה לה להגיד או לרמוז כי היא לאה אף כי היתה מתנכרת כל הלילה ולפיכך לא הכירה עד שראה אותה בבקר ולכן שנאה יעקב והאלהים יודע כי להנשא אל הצדיק עשתה כן ורחם עליה וכך אמרו בבראשית רבה (עא ב) כיון שראה יעקב מעשים שרמתה לאה באחותה נתן דעתו לגרשה וכיון שפקדה הקב"ה בבנים אמר לאמן של אלו אני מגרש וזה טעם "וירא אלהים" כי חמל עליה שלא יעזבנה ויש אומרים (הרד"ק) כי שתים נשים שהאחת אהובה מאד תקרא השניה שנואה כנגדה כמו שאמר ויאהב גם את רחל מלאה לא ששנאה והיתה בושה בדבר וראה אלהים את עניה
@832 **הבה לי בנים** . אמרו המפרשים (רש"י וראב"ע) שתתפלל עלי ואם אין מתה אנכי לשון רש"י שמי שאין לו בנים חשוב כמת והוא מדרש רבותינו (ב"ר עא ו) ואני תמה אם כן למה חרה אפו ולמה אמר התחת אלהים אנכי ושומע אל צדיקים ה' ומה שאמר אבא לא היו לו בנים אני יש לי בנים ממך מנע ממני לא מנע וכי הצדיקים אינן מתפללים בעד אחרים והנה אליהו ואלישע התפללו בעד נשים נכריות (מ"א יז כא ושם ב ד טז) ונראה שבשביל זה תפסוהו רבותינו אמרו בבראשית רבה (עא ז) אמר לו הקב"ה כך עונין את המעיקות חייך שבניך עתידין לעמוד לפני בנה ועל דרך הפשט אמרה רחל ליעקב שיתן לה בנים ובאמת דעתה לאמר שיתפלל עליה אבל שיתפלל עליה עד שיתן לה בנים על כל פנים ואם אין שתמית עצמה בצער דברה שלא כהוגן בקנאתה וחשבה כי באהבתו אותה יתענה יעקב וילבש שק ואפר ויתפלל עד שיהיו לה בנים שלא תמות בצערה ויחר אף יעקב שאין תפלת הצדיקים בידם שתשמע ותענה על כל פנים ובעבור שדברה דרך געגועי הנשים האהובות להפחידו במיתתה חרה אפו ולכך אמר לה שאינו במקום אלהים שיפקוד העקרות על כל פנים ואיננו חושש בדבר כי ממנה נמנע פרי הבטן ולא ממנו וזה ליסר אותה ולהכלימה והנה הצדקת בראותה שלא תוכל להסמך על תפלת יעקב שבה להתפלל על עצמה אל שומע צעקה וזהו וישמע אליה אלהים (להלן פסוק כב) ואולי נתקן על דעת רבותינו כי יעקב אי אפשר שלא נתפלל על אשתו האהובה כי עקרה היא אלא שלא נתקבלה תפלתו ובאה עתה רחל להתעולל עליו לאמר שיתן לה בנים על כל פנים בתפלתו כי לא נופל הוא מאביו שעשה כן ויחר אפו ואמר לה כי הדבר ביד אלהים ולא בידו ואביו נשמעה תפלתו שהוא צדיק ועתיד להיות לו זרע אבל היא נמנע ממנה פרי בטן ונכון הוא
@836 **ותלד ליעקב בן** . הזכיר בכל השפחות "ליעקב" להגיד כי הוא חפץ ומודה בהם ואיננו נקרא לו בן האמה רק בן ליעקב כבני הגבירות המתיחסים אליו ואמר בלאה בן חמישי ובן ששי ליעקב בעבור רבוי הבנים לומר כי בכולן יחפוץ ואת כולם יקרב ולא הזכיר בראשונים כן
@840 **ותרא לאה כי עמדה מלדת** . לא ידעתי מה המעשה הזה ללאה ולמה נתנה שפחתה לבעלה והיא לא היתה עקרה שתבנה ממנה ואין דרך הנשים להרבות נשים לבעליהן אבל נצטרך לומר כי היו נביאות (ב"ר עב ו) יודעות שעתיד יעקב להעמיד י"ב שבטים ורצתה שיהיו לו רוב הבנים ממנה או משפחתה שהיא ברשותה ולא תתגבר אחותה עליה בבנים ולכך אמרה נתן אלהים שכרי אשר נתתי שפחתי לאישי (ראה זוהר ויצא קנז) וכן יעקב בעבור זה שמע אליה שיעמיד בנים רבים כי ידע כן כדברי רבותינו (ב"ר סח יא) ויתכן כי מדעתם שנתנה הארץ לזרעם ואברהם ויצחק לא הרבו בנים היה חפץ יעקב בנשים רבות להרבות זרעו לנחול את הארץ כי דור רביעי ישובו הנה ולכן רצתה ליתן לו שפחתה שלא ישא נכרית
@845 **דודאים** . סיגלי (סנהדרין צט) ובלשון ישמעאל יאסמין כך מצאתי בפירוש רש"י ואינו כן כי יאסמין בלשון ערבי כך שמו בדברי רבותינו כדאמרינן בפרק במה טומנין (שבת נ) האי כוספא דיאסמין שרי וסיגלי אומרים שהם "כנפסגא" שאמרו בהן (ברכות מג) מברכין עליהם בורא עשבי בשמים אבל אין זמנם בימי קציר חטים אולי מצאם שם במקרה והראוי לקבל בדודאים דעת אונקלוס שתרגם בהן יברוחין ובבראשית רבה (עב ב) גם כן ר' חייא ב"ר אבא אמר יברוחין והן יברוח בלשון ערבי וכתב רבי אברהם דודאים אמר המתרגם יברוחין וכך יקראו בלשון ישמעאל ויש להן ריח טוב וכן כתוב (שיר השירים ז יד) הדודאים נתנו ריח והם על צורת בן אדם כי יש להן דמות ראש וידים ויש אומרים כי יועילו להריון ואנכי לא ידעתי בעבור שתולדתם קרה אלו דבריו והנכון כי רצתה בהן להשתעשע ולהתענג בריחן כי בתפלה נפקדה רחל לא בדרך הרפואות וראובן הביא ענפי הדודאים או הפרי והוא כדמות תפוחים ולהם ריח טוב אבל השרש והוא העשוי בצורת ראש וידים לא הביא והשרש הוא שאומרים עליו האנשים שיועיל להריון ואם הדבר אמת הוא בסגולה בהם לא בטבעם אבל לא ראיתי כן באחד מספרי הרפואות המדברים בהם
@846 **המעט קחתך את אישי** . הטעם המעט ממך שתקחי לך את אישי כאילו את אשתו ואני האמה אף כי תעשי עצמך גברת לקחת הדודאים אשר אני מתענגת בריחן ויתכן שרצתה בהן לכבוד יעקב לבשם בהם יצועיו כי דרך נשים לה כענין שכתוב (משלי ז יז) נפתי משכבי מר ואהלות וקנמון ולכן אמרה לאה המעט קחתך את אישי ממני אף כי תקחי דודאי בני לפתותו בהם ויש אומרים הדודאים עשבים יוסיפו התאוה לנשים נגזר מלשון עת דודים (יחזקאל טז ח) ולכן אמרה לאה המעט קחתך את אישי כאשר הזכרתי
@851 **זבדני אלהים אותי זבד טוב** . לא מצאו למלה הזאת מוצא בלשון הקדש ויתכן שנאמר שהיא מלה מורכבת "זה בד" כמלת מדוע ומלת בגד (לעיל פסוק יא) בכתיבה והסגול והפתח מומרים במקומות רבים וכל שכן במלות המורכבות וכן מלת צלמות ומלת בלעדי ויצאה מלשון בדים בדי עצי שטים (שמות כה יג) ותעש בדים ותשלח פארות (יחזקאל יז ו) כי ענפי האילן הגסים נקראים כן והשאילוה לבנים יאכל בדיו בכור מות (איוב יח יג) לא כן בדיו (ישעיהו טז ו) ולכן אמרה לאה כי עשה לה האלהים זה הבן בד טוב להיות בעלה מתלונן בצלה כי יזבלני בצלי וכן בנה בניתי בית זבול לך (מלכים א ח יג) להתלונן בצלו ולכבוד עליון יאמר כן כמו שאמר (שם בפסוק כז) הנה השמים ושמי השמים לא יכלכלוך אף כי הבית הזה אשר בניתי וכן שמש ירח עמד זבולה (חבקוק ג יא) עמד במקום שיתלונן בו כמו שאמר לשמש שם אהל בהם (תהלים יט ה) ואונקלוס תרגם זבד טוב "חולק טב" ולא הבינותי סברתו עד שראיתי (בתרגום הירושלמי) בתרגום יונתן זווד יתי מימרא דה' זוודין טבין ולמדתי שעשו המלה כאלו כתובה בו"ו וטפלו אותה אל לשון הארמית שמתרגמין צדה "זוודין" (להלן מב כה) אמרה שהבן הזה עשאו השם לה צדה טובה וחלק טוב כי בעלה יהיה עיקר דירתו עמה לרוב בניה תתפרנס עמו בטוב לו והו"ו והבי"ת ישתוו בלשוננו במקומות רבים כמו תאוה ותאבה (תהלים קיט כ) גוי נתתי למכים (ישעיהו נ ו) על גבי חרשו חורשים (תהלים קכט ג) וכן לקצבי הרים ירדתי (יונה ב ז) כמו לקצוי וכן לפרבר למערב ארבעה (דברי הימים א כו יח) יאמרו ממנו פרוור דכתיב (מלכים ב כג יא) אל לשכת נתן מלך הסריס אשר בפרוורים ופירוש שניהם מה שהוא מקיר החומה לחוצה ומגרש לערים (במדבר לה ב) תרגום ירושלמי ופרוור וכן תרגום יונתן מגרשות (יחזקאל כז כח) ובמשנה מלא תרווד תרבד (נזיר מט אהלות פ"ב מ"א) בטבלא שאין לה לבזביז (פסחים מח) במקומות שונין ממנו "לזביז" (כלים פ"ב מ"ג מקואות פ"ד מ"ב) ובמקומות שונין ממנו "לזויז" איצטבא (פסחים יא) "איצטוא" (עירובין עז ויומא מט לפי גירסת הערוך) וכן כיוצא בהן הרבה ונהגו בירושלמי (כלאים פ"ה הכ"ט יבמות פ"ז ה"ח ועוד) "אביר" בבי"ת במקום ו"ו שאינם מקפידים בכך
@854 **אסף אלהים את חרפתי** . הכניסה במקום שלא תראה וכן ולא יאסף הביתה (שמות ט יט) וכוכבים אספו נגהם (יואל ב י) וירחך לא יאסף (ישעיהו ס כ) לא יטמן לשון רש"י ורבי אברהם אמר כטעם כרת ונאספה שמחה וגיל והנכון דעת אונקלוס שעשאן כולן לשון קבוץ וכנוס כפשוטם מלשון ויאספו את השליו (במדבר יא לב) כי מאספיו יאכלוהו (ישעיהו סב ט) ונקראת המיתה אסיפה בהיותו נקבץ אל אבותיו המתים ולא יאסף הביתה להקבץ לאנשי ביתו ואספו נגהם שקבצו האור בתוכם ולא הוציאו אורם לחוץ או שנאספו אל האהל אשר להם ברקיע השמים ויאמרו אסיפה בחרפה שתתקבץ ולא תתפזר בין בני אדם להיות נדברים בה עוד בחוצות
@858 **נחשתי ויברכני ה' בגללך** . בעבורך ובזכותך כי איש צדיק אתה ולשון נחשתי נסיתי וכל נחש נסיון ויש אומרים (ראב"ע) שהיה מנחש בתרפים ויעקב אמר ויברך ה' אותך לרגלי לא רצה לומר "בגללי" דרך ענוה ואמר לרגלי כי מעת שבא רגלי בבית היית מתברך
@860 **ואת אשר היה מקנך אתי** . את חשבון מיעוט מקנך שבא לידי כמה היה לשון רש"י כלומר אתה ידעת כמה היה מקנך כשבאו אתי ויותר ראוי שיאמר ואת מקנך אשר היה אתי ידעת כי מעט אשר היה לך טרם בואי ויפרוץ לרוב או נפרש אתה ידעת את אשר עבדתיך כי בכל כחי עשיתי וידעת את אשר היה מקנך אתי כי ימים רבים הם וידעת כי מעט אשר היה לך לפני ויפרוץ לרוב שלא כדרך כל הארץ רק ברכת ה' היא אשר באה מעת בא רגלי בביתך והוא הנכון
@861 **אעשה גם אנכי לביתי** . עכשיו אין עושין לצרכי אלא בני וצריך אני להיות עושה עמהם לסומכן וזהו גם לשון רש"י ולא מצאנו שיהיה ליעקב צאן ולא שירעו אותן בניו הקטנים והגדול שבהם בן שש שנים או פחות כי לבן יתכן שהיו לו בנים קטנים מרחל בטרם בא יעקב ועתה הם ראויים לרעות הצאן ואולי על נשיו ועל עבדיו אמר שהיו עושים לו במלאכה ואין כל זה נכון אבל פירוש מתי אעשה גם אנכי לביתי מתי אעשה אנכי גם לביתי כאשר עשיתי גם לביתך וכן ויאהב גם את רחל מלאה (לעיל כט ל) וגם אהב את רחל מלאה וכן גם אותכה הרגתי (במדבר כב לג) גם הרגתי אותך ורבים כן
@863 **וטעם נקוד וטלוא** . נקוד או טלוא וכל שה חום פירשו בו (הראב"ע והרד"ק) שחור כי השחרות מפני החום ואיננו נכון בעיני כי רוב הכשבים שחורים אף כי בארץ קדם שהיא חמה ואם כן יהיו כולם ליעקב והנכון דעת אונקלוס "שחום" והוא קרוב לאדום וקורין אותו רו"ש וכן פרש"י ויהיה חום מגזרת ואור החמה (ישעיהו ל כו) שהוא דומה לשמש אשר יתאדם קצת
@863 "והיה שכרי" - לשון רש"י אותן שילדו מכאן ולהבא נקודים וטלואים בעזים ושחומים בכשבים יהיו שלי וכן דעת רבי אברהם (בפסוק לה) ופירוש כל שה נקוד וטלוא תיש וטלוא ונקוד בעזים הנקבות כמו שאמר (שם) ויסר ביום ההוא את התישים ואת כל העזים ופירוש כל אשר לבן בו בנזכרים וכל חום בכשבים ולפי דעתי כי כל נקוד וטלוא בכשבים וכל חום בהם היה שכרו שהרי לא עשה במקלות מראה חום והיה מפסיד שכרו מן הכשבים שהם מיטב הצאן וכן בחלומו הראוהו העולים על הצאן עקודים נקודים אין בהם חום ופירוש הכתוב הסר משם כל שה נקוד וטלוא וכל חום בכשבים והסר טלוא ונקוד בעזים והיה שכרי שלשת המראות בכשבים והשנים בעזים ואמר
@863 "וענתה בי צדקתי ביום מחר" - כי כל אשר איננו נקוד וטלוא בעזים וגם חום בכשבים גנוב הוא אתי
@866 **וטעם ויסר ביום ההוא את התישים** . סיפר הכתוב כי יעקב אמר סתם הסר משם טלוא ונקוד בעזים ולבן חשש לזרע האב והפריש הזכרים והנקבות והפריש אפילו העקודים אשר להם לובן מעט ברגליהם במקום העקידה והפריש בכשבים כל אשר לבן בו וכל חום ואם יהיה "כל אשר לבן בו" לומר שהפריש בתישים ובעזים כל אשר בו מראה לבן בין עקוד בין ברוד יהיה וכל חום מוסף על המראות הנזכרות וטעם הוסיפו בשכר הכשבים חום מפני שאין בתולדתם להיותם בעלי גוונין כתישים והעזים ואין בתולדת העזים להיות בהן חום
@868 **ויקח לו יעקב מקל לבנה** . כיון שהסכימו להיות שכרו באלה היה רשאי לעשות כל מה שיוכל להולידם כן ואולי התנה יעקב שיעשה בהן כל מה שירצה כי לבן לא היה יודע בתולדה הזו והרועים לא היו מרגישים בדבר בראותם המקלות ברהטים פעם אחת בשנה בימי ניסן כי בהעטיף הצאן בימי תשרי לא ישים שלא ישאר ללבן עד פרסה ויש אומרים (הרד"ק) כי השנה הראשונה נולדו ליעקב נקודים וטלואים רבים בברכת השם אשר הראה לו המלאך ושם המקלות בפני אלו שהיו שלו שיולידו בדמותם שלא יאמר לבן כאשר יולדו כי גנוב הוא אתו וזה פירוש בכל יחם הצאן המקושרות שהם הנולדים לו ובהעטיף הצאן של לבן לא ישים והיה העטופים ללבן אשר לא יולדו נקודים והקשורים כלם ליעקב כי יולדו נקודים
@871 **והכשבים הפריד יעקב** . פירש רש"י הנולדים עקודים נקודים הבדילם לעצמם ועשה אותן עדר לבד והוליך אותו העדר העקוד לפני הצאן ופני הצאן ההולכות אחריהן צופות באלו וזהו שאמר ויתן פני הצאן אל עקוד שהיו פני הצאן אל עקוד ואל כל חום שנמצא בצאן לבן וישת לו עדרים לבדו ולא שתם על צאן לבן כמו שפירשתי זה לשון הרב ואין דבריו בכאן נכונים כי למה הפריד הכשבים ולא נשאר בעדר לבן נקוד או חום לא בכשבים ולא בעזים ואם היו הנפרדים אותם אשר הולידו הצאן עקודים נקודים וטלואים שהיו שלו ומהם עשה העדר הזה העקוד למה הפריד הכשבים לבדם ולא לקח גם התישים והעזים שנולדו לו כן ויעשה מכלם העדר העקוד הזה אשר הוליך לפני הצאן ועוד שלא אמר שנולד שם חום ועוד כי לפי דעת הרב אין בכשבים עקוד וטלוא שאינם שכרו ולא עשה להם מקלות אבל פירוש הכתוב שהפריד הכשבים מן העזים ועשה מהן עדר מיוחד והנה היו לו עדר כשבים ועדר עזים ונתן פני כל הצאן עדר הכשבים ועדר העזים אל העקודים ואל כל חום אשר בכל צאן לבן ששם העקודים לפני העזים וכל חום לפני הכשבים על דעת הראשונים או העקודים וכל חום לפני הכשבים על דעתנו כי צורך ההפרדה מפני החום אשר היה שכרו בכשבים לבדן והנכון בעיני שיאמר כי הכשבים הפריד יעקב ונתן פני הצאן הנזכר שהם הכשבים אל עקוד ואל כל חום וישת לו עדרים לבדו מן העקוד והחום והוליכם לפני הכשבים ולא שתם על צאן לבן כי היו שכרו וטעם בצאן לבן שעשה כן בכל צאן לבן והנה העקוד בכשבים היו שלו ואל תשאל למה אמר "הכשבים" ואמר "פני הצאן" כי דרך מקראות לדבר כן ובפרשה הזאת בדומה לו בהר הגלעד (להלן לא כא) וטעם עשותו כן בכשבים מפני שלא היה במקלות חום או שידע בתולדת הכשבים שצריכים לסימנים רבים בכבדותם יותר מן התישים לקלותם
@872 **הצאן המקושרות** . הנכון בעיני בלשון הזה שהם הצאן אשר הזכרים מהם הולכים אחר הנקבות בכל עת לא יתפרדו מהם לרב תאותם מלשון ונפשו קשורה בנפשו (להלן מד ל) ולשון חכמים כן הוא (בכורות כד) חזיר כרוך אחר רחל בכרוכין אחריה (קדושין עט) ויקראו הנולדים בעת ההיא "הקשורים" על שם אביהם ורבים אמרו כי קשורים הם החזקים אשר איבריהם קשורים זה בזה קשר אמיץ כי זה סיבת הבריאות והעטופים הם החלושים אשר נפשם בהם תתעטף ואין להם תאוה מלשון העטופים ברעב (איכה ב יט) והתרגום אמר בכיריא ולקישיא כי כן הדבר
@880 **כי בכל כחי עבדתי את אביכן** . מתחילה ונתברך לרגלי ויתכן שהיה ללבן צאן רבות כי נתברכו גם העטופים לרגל יעקב כי לא צעקו בניו רק בקנאתם ליעקב שעשה כל הכבוד הזה
@881 **ואביכן התל בי והחליף את משכורתי** . זה היה אמת ואם לא ספרו הכתוב מתחלה וכן אמר לו ותחלף את משכורתי עשרת מונים (להלן פסוק מא) וכזה במקומות רבים בתורה ובפרשה הזאת למעלה לא ספר שנתנה לאה את הדודאים לרחל
@882 **וטעם אם כה יאמר נקודים יהיה שכרך** . כי מתחילה נתן לו שני המראות נקודים וטלואים גם החום בכשבים וחזר בו לתת מראה אחד והיה מחליף אותו בכל שנה והיו הצאן יולדות כן ולא היה זה במקלות כי הוא מספר להם מעשה השם הגדול שעשה עמו להפליא מדי שנה בשנה כאשר אמר ולא נתנו אלהים להרע עמדי גם יתכן שהיה מחליף את משכורתו אחרי שהיו הצאן מעוברות והיו יולדות כרצון יעקב כאשר ישר בעיני היוצר לעשות ובבראשית רבה (עד ג) צפה הקב"ה מה שלבן עתיד לעשות ליעקב אבינו והוא צר צורה כיוצא בה אם כה אמר אין כתוב כאן אלא אם כה יאמר
@884 **ויהי בעת יחם הצאן** . זה היה אחר שהחליף את משכורתו ולכך אמר כי ראיתי את כל אשר לבן עושה לך וטעם והנה העתודים העולים על הצאן הראה לו בחלום כי יעלו על הצאן העתודים וכולם עקודים ואחרי כן היו כולם נקודים ושוב היו כולם ברודים והגיד כי הוא רואה החמס שעושה לו לבן להחליף את משכורתו ויעשה הנולדים כמראה אשר יצטרך אליו יעקב ומכאן ואילך לא יעשה יעקב מקלות כי בוטח בה' ישוגב (משלי כט כה)
@884 "והנה העתודים העולים על הצאן" - התישים והאילים יקראו עתודים כי כל גדול בצאן יקרא כן אף בגדולי האנשים כל עתודי ארץ (ישעיהו יד ט) וכתב רש"י אף על פי שהבדילם לבן כולם שלא יתעברו הצאן דוגמתן היו המלאכים מביאים אותן מעדר המסור לבני לבן לעדר שביד יעקב ועל דרך הפשט היה זה מראה להבטיחו כי יולידו כהם והעד מלת "והנה" כי בכל החלום יאמר כן (לעיל כח יב יג להלן מ ט טז) בטעם כאילו הדבר לפניו ובבראשית רבה (עד ג) לא הזכירו המלאכים אלא ממדרש אמרו עולים אין כתוב כאן אלא העולים כי פשוטו של מקרא כמו שאמרנו
@887 **אנכי האל בית אל** . יספר יעקב לנשיו כל מה שאמר לו מלאך האלהים בחלום כי הכל פיוס להם שתלכנה עמו אבל מה שיספר לא חלום אחד הוא כי מאמר "שא נא עיניך וראה כל העתודים" היה בהיותו עובד את לבן בצאנו בעת יחם הצאן באחת מהשנים הראשונות ומאמר "אנכי האל בית אל" היה אחר כן בעת הנסיעה כי אחר שאמר לו קום צא מן הארץ הזאת לא נתעכב עוד בחרן לרעות עוד צאן לבן ויעלו התישים על הצאן ותלדנה נקודים וטלואים רק ממחרת החלום שלח לרחל וללאה ויספר להם חלומו והלכו להם וטעם אנכי האל בית אל פירש"י ה"א יתירה והוא כמו אנכי אל בית אל וכמהו (במדבר לד ב) אל הארץ כנען ובעלי הלשון (הראב"ע והרד"ק) תקנו אנכי האל אל בית אל וכן ומעץ הדעת טוב ורע (לעיל ב ט) העבותות הזהב (שמות לט יז) והמלאך ידבר בלשון שולחו ועל דרך האמת יאמר המלאך הזה אנכי האל בית אל וכן ויקרא למקום אל בית אל (להלן לה ז) כמו שאמר ציון קדוש ישראל (ישעיהו ס יד) ויונתן בן עוזיאל אמר (שם ו ג) קדיש בשמי מרומא עילאה בית שכינתיה והוא המלאך הגואל (להלן מח טז) וכן בכל ביתי נאמן הוא (במדבר יב ז) והמשכיל יבין וטעם אשר משחת שם מצבה אשר נדרת לי שם נדר כי אתה נדרת להיות עובד לשם המיוחד בארץ הנבחרת ולהיות לך האבן בית אלהים ולהוציא שם מעשרותיך ואם תאחר נדריך עוד יקצוף האלהים על קולך
@893 **ותגנוב רחל את התרפים** . לא נתכוונה אלא להפריש אביה מעבודה זרה לשון רש"י ואפשר כי היו ללבן לעבודה זרה כאשר אמר למה גנבת את אלהי אבל לא היו כל התרפים נעבדים כי איך תמצא עבודה זרה בבית אדונינו דוד (עיין שמואל א יט יג) והקרוב מה שאומרים שהם כלים לקבל השעות ויקסמו בהם לדעת עתידות והמלה נגזרת מלשון רפה ידים (שם ב יז ב) נרפים אתם נרפים (שמות ה יז) יקראו אותם "תרפים" לרמוז בשמם כי דבורם כמו נבואה רפה תבא ברב ותכזב לעתים רחוקות כמו שאמרו (זכריה י ב) כי התרפים דברו און והנה יעשו אותם קטני אמנה להם לאלהים לא ישאלו בשם הנכבד ולא יתפללו אליו רק כל מעשיהם בקסמים אשר יגידו להם התרפים וכתוב (שופטים יז ה) והאיש מיכה לו בית אלהים ויעש אפוד ותרפים ושם כתוב (יח ה) שאל נא באלהים ונדעה התצליח דרכינו כי בתרפים היו שואלים וכן היה הענין בישראל באפוד כי אחרי אשר הורגלו באפוד הקדש עשו כדמותו והיו שואלים בו ומאמינים בדבריו ותועים אחריו גם בחלים לא ידרשו את ה' כי אם בהם וזה טעם ויעש אותו גדעון לאפוד ויצג אותו בעירו בעפרה ויזנו כל ישראל אחריו שם ויהי לגדעון ולביתו למוקש (שופטים ח כז) כי סרו מאחרי ה' והנה לבן היה קוסם ומנחש כאשר אמר (לעיל ל כז) נחשתי וארצו ארץ קוסמים מעולם כדכתיב (ישעיהו ב ו) כי מלאו מקדם ועוננים כפלשתים ובלעם בן בעור הקוסם היה מעירו וזה טעם למה גנבת את אלהי
@896 **ביום השלישי** . שהרי דרך ג' ימים היה ביניהם דרך שבעת ימים כל אותן ג' ימים הלך המגיד להגיד את לבן שהלך יעקב לדרכו נמצא רחוק מלבן ששה ימים ובשביעי השיגו ולמדנו שכל מה שהלך יעקב בששה ימים הלך לבן ביום אחד לשון רש"י מבראשית רבה (עד ו) ונכון הוא שילך לבן כגבור לרוץ ארח כי כן דרך הרודפים אבל לבן דרך שלשה ימים שם בין צאנו ובין הצאן אשר ביד יעקב לא בין העיר ובין צאנו כאלו לבן רועה צאנו במזרח לעיר יעקב למערבה וביניהם דרך שלשת ימים והנה יעקב מן העיר נסע כי שם ביתו בניו ובנותיו וכל אשר לו מלבד הצאן והוגד ללבן ביום השלישי כי לא הרגישו ביום הראשון ושב לבן לעירו ולקח את אחיו משם ורדף אחריו מעירו שבעה ימים והשיגו ביום השביעי אבל נאמר על דעת בראשית רבה כי מן השדה אשר שם הצאן נסע יעקב ולבן לקח את אחיו עמו מגוזזי צאנו ובפרקי רבי אליעזר (פרק לו) נראה כי לבן שב לעירו ומשם לקח כל גבור וכל בן חיל ורדף אחריו משם
@897 **וידבק אותו בהר הגלעד** . כי ביום השביעי בערב הגיע לבן אל תחת ההר וראה את יעקב חונה עליו מרחוק ולן בלילה ההוא למטה ויבא אליו החלום
@898 **וטעם אל לבן הארמי** . להגיד כי אף על פי שהוא ארמי ואנשי מקומו אנשי תרפים ועוננים כפלשתים (ישעיהו ב ו) בא אליו חלום הנבואה לכבוד הצדיק וכן ויגנב יעקב את לב לבן הארמי אף על פי שהוא הארמי הקוסם בעל התרפים
@898 "מטוב עד רע" - כל טובתן של רשעים רעה היא אצל הצדיקים לשון רש"י ופשוטו השמר לך פן תדבר עמו לעשות לו טובה אם ישוב עמך מדרכו או פן תפחידנו לעשות לו רעה אם לא יבא עמך כי אני צויתיו לשוב אל ארצו
@907 **באהל יעקב ובאהל לאה** . כתב רש"י באהל יעקב הוא אהל רחל שהיה תדיר אצלה וכן הוא אומר בני רחל אשת יעקב ובכלן לא נאמר אשת יעקב ויבא באהל רחל כשיצא מאהל לאה חזר לו לאהל רחל קודם שיחפש באהל האמהות וכל כך למה שהיה מכיר בה שהיא ממשמשנית ועל דרך הפשט איננו נכון שיקראנו בפסוק אחד בשני שמות ורבי אברהם אמר שבא באהל יעקב ובאהל לאה ובאהל שתי האמהות כי אהל אחד לשתיהן ואחר כך שב שנית אל אהל לאה ואחרי כן אל אהל רחל וגם זה איננו נכון ועוד כתב והקרוב אלי שהכתוב אחז דרך קצרה ואיחר להזכיר אהל רחל להזכיר בכלן "ולא מצא" כי לא היו שם וחזר ופירש כי בעת צאתו מאהל לאה בא באהל רחל אשר שם התרפים והוא הנכון אבל כי אהלים היו לכולם כי היה זה מצניעות הצדיק כי לכל אחת מארבע הנשים היה אהל מיוחד בעבור שלא תדע האחרת בבאו אל רעותה גם אסור הוא בדין תורה כמו שהזכירו חכמים במסכת נדה (יז) וליעקב אהל מיוחד ושם תאכלנה על שולחנו עם בניו ועם בני ביתו וטעם "אשת יעקב" שהזכיר ברחל על דעתי כפשוטו בעבור שהיא מוזכרת בין הפילגשים בפרשה ההיא (להלן מו יט) ולכן לא אמר כן בסדר וישלח יעקב (לה כד) שימנה לאה ורחל ואחרי כן השפחות
@909 **אל יחר בעיני אדני כי לא אוכל לקום מפניך** . לא הבינותי מה התנצלות זה וכי הנשים אשר להם האורח לא יקומו ולא יעמודו אולי אמרה כי ראשה ואבריה כבדים עליה והיא חולה בבא הארח כי כן דרכן וכל שכן במעטות הלידה כרחל שדמיהן מועטין והארח יכבד עליהם מאד והנכון בעיני כי היו הנדות בימי הקדמונים מרוחקות מאד כי כן שמן מעולם "נדות" לריחוקן כי לא יתקרבו אל אדם ולא ידברו בו כי ידעו הקדמונים בחכמתם שהבלן מזיק גם מבטן מוליד גנאי ועושה רושם רע כאשר בארו הפילוסופים עוד אני עתיד להזכיר נסיונם בזה (ויקרא יח יט) והיו יושבות בדד באהל לא יכנס בו אדם וכמו שהזכירו רבותינו בברייתא של מסכת נדה תלמיד אסור לשאול בשלמה של נדה רבי נחמיה אומר אפילו הדבור היוצא מפיה הוא טמא אמר רבי יוחנן אסור לאדם להלך אחר הנדה ולדרוס את עפרה שהוא טמא כמת כך עפרה של נדה טמא ואסור ליהנות ממעשה ידיה ולכך אמרה רחל ראויה הייתי לקום מפני אדוני לנשק ידיו אבל דרך נשים לי ולא אוכל להתקרב אליך וגם לא ללכת באהל כלל שלא תדרוך אתה עפר רגלי והוא החריש ממנה ולא ענה אותה כי לא היו מספרים עמהן כלל מפני שדבורה טמא
@910 **ויחר ליעקב וירב בלבן** . מתחילה נתן לו רשות לחפש כי אמר עם אשר תמצא את אלהיך ואמר נגד אחינו הכר לך מה עמדי ואיך ימצא אם לא יחפש וימשש אבל מתחלה היה חושש אולי אחת הנשים או העבדים גנבו את אלהיו ועתה בראותו כי אינם עמהם חרה אפו כי אמר לא אבד את אלהיו רק תואנה הוא מבקש ממני אמר לו למה דלקת אחרי כאשר ירדוף האדם אחרי הגנב הנה לא מצאת עמי מכל כלי ביתך דבר והיה ראוי לי לקחת ממך כל מה שאוכל כי אתה החלפת את משכורתי עשרת מונים והיית תובע ממני הטרפות ושלמתי לך שלא כדין
@916 **ופחד יצחק היה לי** . לא רצה לומר אלהי יצחק לפי שאין הקב"ה מיחד שמו על הצדיקים בחייהם ואף על פי שאמר לו בצאתו (לעיל כח יג) אני ה' אלהי אברהם אביך ואלהי יצחק בשביל שכהו עיניו והרי הוא כמת נתיירא יעקב לומר לשון רש"י וכן דעת אונקלוס כי פחד יצחק אלהיו דדחיל ליה יצחק ורבי אברהם אמר יראת יצחק את השם הועילתני כי זכות האב תועיל לבן וישבע יעקב בפחד אביו יצחק (פסוק נג) במי שיצחק מתפחד ממנו והנה אין פירושו שוה עוד כתב (שם) ויש אומרים כי זה הפחד רמז ליום העקדה ואיננו רחוק ועל דרך האמת יבא הלשון כפשוטו ומשמעו והוא מדת הדין של מעלה וממנו אמר הכתוב (הושע ג ה) אחר ישובו בני ישראל ובקשו את ה' אלהיהם ואת דוד מלכם ופחדו אל ה' ואל טובו באחרית הימים יאמר כי יבקשו הרחמים ומדת הדין שלמטה ויביאו פחד יצחק אל השם ואל טובו הנזכרים
@916 "ויוכח אמש" - לשון תוכחה ולא לשון הוכחה לשון רש"י ויותר נכון לשון הוכחה כי אמר למעלה ויוכיחו בין שנינו ואמר עתה כי האלהים היודע הנסתרות הוא הוכיח בין שניהם ולכך לא אמר "ויוכח אותך אמש"
@917 **ולבנותי מה אעשה לאלה היום** . אמרו (הראב"ע והרד"ק) שהוא כמו ולבנותי מה אעשה להן היום והיא תוספת ביאור וכן אשר נשבענו שנינו אנחנו (שמואל א כ מב) בנינו ובנותינו אנחנו (נחמיה ה ב) ויותר נכון נראה שהוא דרך חמלה ולבנותי מה אעשה לאלה אשר לפני כי נכמרו רחמי עליהן או לבניהן הנולדים בביתי והם לי כבני וזה טעם אשר ילדו ואמר זה כמתנצל על דברי יעקב כי באתי אחריך לראות בנותי ומה אוכל לעשות להם טובה או לבניהם ועתה אטיב להן שתכרות לי ברית שלא תענה אותן ולא תקח עליהן נשים
@918 **והיה לעד** . הקב"ה לשון רש"י ואיננו כמשמעו אבל יאמר והיה הברית לעד בינותינו כי העובר עליו יקולל בכל אלות הברית כטעם והיו בך לאות ולמופת (דברים כח מו) או טעמו נכרתה ברית בדבר קיים שיהיה לעד בינותינו על כן הרים יעקב אבן והוא מה שאמר עד הגל הזה ועדה המצבה כטעם ויאמר יהושע הנה האבן הזאת תהיה בנו לעדה (יהושע כד כז)
@920 **ויאמר יעקב לאחיו** . לאחי לבן הנזכר אשר באו עמו כי לא רצה לאמר כן לחמיו שהיה נוהג בו כבוד וכן ויקרא לאחיו לאכל לחם לאחי לבן ולא קרא ללבן דרך כבוד כאלו הכל ברשותו והכל שלו ודומה להם ויאמר פרעה לאחיו מה מעשיכם (להלן מז ג) ורש"י פירש לאחיו של יעקב כי הבאים עם לבן אוהביו ורעיו הם ויתכן כי מה שאמר בלבן ויקח את אחיו עמו (לעיל פסוק כג) הם קרוביו בני משפחתו מזרע נחור אחי אברהם ועשה כן בעבור שלא ירצה להביא על יעקב אנשים נכרים שלא יריבו עמו בכח או יחמדו ויגזלו ויגנבו מאשר לו והנה אלה קרובים ליעקב כמו ללבן על כן יקראו אחים לשניהם ויש אומרים (פסיקתא זוטרתא לעיל כט ד) שאמר להם אחי דרך מוסר כמו שאמר לרועים (שם) אחי מאין אתם ובבראשית רבה (עד יג) אמרו ויאמר יעקב לאחיו אלו בניו שהיה קורא אותן בלשון כבוד אחיו אבל בויקרא לאחיו לאכל לחם לא פירש והנכון מה שכתבתי תחילה
@920 "ויאכלו שם על הגל" - אכלו שם מעט לזכרון או שהוא דרך הבאים בברית לאכול שניהם מלחם אחד לאהבה ולחברה ואחרי בואם בשבועה ובברית זבח להם זבח ועשה להם כרה גדולה ויתכן כי טעם ויאכלו שם על הגל הזבח הנזכר למטה כי אמר להם לקטו אבנים ונעשה גל לאכול עליו ויהיה עד בבואנו בברית ואחרי כן אכלו עליו זבח וטעם ויאכלו לחם שעשה להם סעודה גדולה ללון עמו לא משתה בלבד
@922 **ויאמר לבן הגל הזה עד** . אחרי שקראו יעקב גלעד דבר לבן בלשון יעקב הגל הזה עד ועל כן נקרא שמו גלעד כי בשם הזה הסכימו שניהם או שדברי לבן מתורגמין ללשון הקדש
@923 **וטעם והמצפה** . כתב רש"י והמצפה אשר בהר גלעד כמו שכתוב (שופטים יא כט) ויעבור את מצפה גלעד למה נקראת מצפה אשר אמר כל אחד מהם לחבירו יצף ה' ואם כן הוא שם מקום גבוה בראש ההר ולפי דעתי שהיא האבן שהקים יעקב מצבה והוא נמשך על כן קרא שמו גלעד והמצפה קרא כי אמר יצף ה' ואפשר שהוא מצפה גלעד (עיין שופטים יא כט) שהמקום יקרא על שם האבן הזאת לעולם
@930 **ויפגעו בו מלאכי אלהים** . לשון רש"י מלאכי ארץ ישראל יצאו לקראתו מחנים שתי מחנות של חוצה לארץ באו עמו עד כאן ושל ארץ ישראל יצאו לקראתו ואני תמה בזה שהרי עדיין לא הגיע יעקב לארץ ורחוק היה משם ושלח מלאכים אל עשו מרחוק ושם (להלן לב כג) נאמר ויעבור את מעבר יבק שהוא "יבק הנחל גבול בני עמון" (דברים ג טז) שהוא דרומית מזרחית לארץ ישראל ועדיין יש לו לעבור גבול בני עמון ומואב ואחרי כך ארץ אדום ותחלת ביאתו בארץ בשכם היה שנאמר (להלן לג יח) ויבא יעקב שלם עיר שכם אשר בארץ כנען אבל היתה המראה הזאת ליעקב כאשר בא בגבול אויביו להודיעו כי רבים אשר אתו מאשר אתם ונקרא שם המקום מחנים כי כן הדרך בשמות או מחנים מחנהו ומחנה העליונים לומר כי מחנהו בארץ כמחנה המלאכים כלם מחנות אלהים מברכים לו ומודים בייחודו יתברך שמו לעולמים חסלת פרשת ויצא נכתבה הפרשה הזאת להודיע כי הציל הקב"ה את עבדו וגאלו מיד חזק ממנו וישלח מלאך ויצילהו וללמדנו עוד שהוא לא בטח בצדקתו והשתדל בהצלה בכל יכלתו ויש בה עוד רמז לדורות כי כל אשר אירע לאבינו עם עשו אחיו יארע לנו תמיד עם בני עשו וראוי לנו לאחז בדרכו של צדיק שנזמין עצמנו לשלשת הדברים שהזמין הוא את עצמו לתפלה ולדורון ולהצלה בדרך מלחמה לברוח ולהנצל וכבר ראו רבותינו הרמז הזה מן הפרשה הזאת כאשר אזכיר (להלן לב ט לג טו)
@932 **אל עשו אחיו ארצה שעיר** . בעבור היות נגב ארץ ישראל על ידי אדום ואביו יושב בארץ הנגב יש לו לעבור דרך אדום או קרוב משם על כן פחד אולי ישמע עשו והקדים לשלוח אליו מלאכים לארצו וכבר תפסוהו החכמים על זה אמרו בבראשית רבה (עה ג) מחזיק באזני כלב וגו' (משלי כו יז) אמר לו הקב"ה לדרכו היה מהלך והיית משלח אצלו ואומר לו כה אמר עבדך יעקב ועל דעתי גם זה ירמוז כי אנחנו התחלנו נפילתנו ביד אדום כי מלכי בית שני באו בברית עם הרומיים (ספר החשמונאים א ח) ומהם שבאו ברומה (כך כותב רבינו בויקרא כו טז) והיא היתה סבת נפילתם בידם וזה מוזכר בדברי רבותינו ומפורסם בספרים (יוסיפון פרק סה)
@933 **כה תאמרון לאדני לעשו כה אמר עבדך יעקב** . צוה אותם שיאמרו לאדני לעשו אנחנו שלו או שלוחים אליו ולאמר לו כה אמר עבדך יעקב עם לבן גרתי ודומה לו בפרשה (להלן פסוק יח) למי אתה או שקראו יעקב בפניהם אדני עשו להזהירם שלא יזכירוהו אפילו שלא בפניו רק דרך כבוד בראותם כי אדונם קורא אותו אדני ודע כי הכבוד הזה שהיה יעקב עושה לאחיו בפחדתו לאמר אדני ועבדך בעבור כי המנהג בצעיר לתת מעלה וכבוד אל הבכור כאלו הוא אביו כאשר רמזה לנו גם התורה לרבות אחיך הגדול והנה יעקב לקח בכורתו ואת ברכתו ועשו שוטם אותו עליהם ועתה היה מראה לו כאלו אין המכירה ההיא אצלו כלום וכי הוא נוהג בו כבכור ואב להוציא את המשטמה מלבו
@934 **ואשלחה להגיד לאדני** . להודיע שאני בא אליך למצא חן בעיניך שאני שלם עמך ומבקש אהבתך לשון רש"י רצה לומר שאינו מוסב למעלה אבל יאמר ואשלחה להגיד לאדני כי אני בא למצוא חן בעיניך ולעשות ככל אשר יצוה אדני ויותר נכון שיוסב למעלה ואשלחה להגיד לאדני שיש לי עושר ונכסים וכבוד לעשות בו חפצך ורצונך ירמוז שישלח לו דורון מהם או שיקח הוא משלו מה שיחפוץ וכן אמר (להלן לג ח) מי לך כל המחנה הזה אשר פגשתי ויאמר למצא חן בעיני אדני
@935 **וישובו המלאכים אל יעקב לאמר** . השלוחים האלה עשו שליחותם אבל לא סיפר הכתוב זה כי אין צורך וטעם וגם הולך לקראתך לאמר כאשר אתה הולך לקראתו כן הוא הולך לקראתך ומהר תפגשו זה בזה
@936 **ויירא יעקב מאד** . בעבור שאמרו לו כי יצא עשו מעירו והוא בא לקראת יעקב ועוד שלקח עמו אנשים רבים ארבע מאות היה ירא לנפשו מאד כי אמר לא לקח כל אלה רק להלחם בי והנראה בעיני בענין הזה כי עשו לא קבל השלוחים כהוגן ולא השגיח עליהם ואולי לא היו לפניו כי לא נתן רשות שיבאו לפניו וידברו עמו כלל כי היה הכתוב מספר ששאל להם מה שלום אחי ומה ענינו ועניני ביתו ובניו וקראו לו בשלומו ואמרו לו כי אני הולך לקראתו לראותו והם היו מגידים כן ליעקב והכתוב לא סיפר שיאמרו השליחים דבר בשם עשו אבל עברתו שמורה בלבו ולעשות לו רעה היה הולך בחיל הזה והנה השלוחים חקרו במחנה וידעו כי הוא הולך לקראת יעקב וזה טעם "וגם" כי אמרו באנו אל אחיך אל עשו ולא ענה אותנו דבר ולא שלח לך דברי שלום וגם הולך לקראתך בזרוע וחיל ולכך הוסיף לו פחד על פחדו ויירא יעקב מאד ויצר לו וכך אמרו רבותינו (ב"ר עה ז) כי השלוחים הכירו בו שנאה אמרו באנו אל אחיך אל עשו אתה נוהג בו כאח והוא נוהג עמך כעשו אבל בסוף כאשר ראה הכבוד הגדול שעשה לו יעקב ואשר השפיל עצמו לפניו שהשתחוה ארצה שבע פעמים מרחוק עד גשתו אליו נכמרו רחמיו וחשב כי הוא מודה בבכורתו ובגדולתו עליו כאשר פירשתי (לעיל בפסוק ה) והתנחם בזה כי הלבבות לה' המה לכל אשר יחפוץ יטה אותם
@937 **והיה המחנה הנשאר לפליטה** . על דרך הפשט אמר זה באולי כי אמר אולי ינצל המחנה האחד כי בהכותו האחד יברחו האחרים או תשוב חמתו או תבא להם הצלה מאת השם וכן אמרו בבראשית רבה (עו ג) למדתך תורה דרך ארץ לא יניח אדם כל ממונו בזוית אחת ורש"י כתב והיה המחנה הנשאר לפליטה על כרחו כי אלחם עמו התקין עצמו לשלשה דברים לתפלה ולדורון ולמלחמה וראיתי במדרש (קה"ר ט יח) מה עשה זיינם מבפנים והלבישם בגדים לבנים מבחוץ והתקין עצמו לשלשה דברים וכן עיקר והכונה בזה כי יעקב יודע שאין זרעו כלו נופל ביד עשו אם כן ינצל המחנה האחד על כל פנים וגם זה ירמוז שלא יגזרו עלינו בני עשו למחות את שמנו אבל יעשו רעות עם קצתנו בקצת הארצות שלהם מלך אחד מהם גוזר בארצו על ממוננו או על גופנו ומלך אחר מרחם במקומו ומציל הפלטים וכך אמרו בבראשית רבה (עו ג) אם יבא עשו אל המחנה האחת והכהו אלו אחינו שבדרום והיה המחנה הנשאר לפלטה אלו אחינו שבגולה ראו כי גם לדורות תרמוז זאת הפרשה
@939 **קטנתי מכל החסדים ומכל האמת** . נתמעטו זכיותי על ידי חסדים ואמת שעשית עמי לכך אני ירא שמא משהבטחתני נתקלקלתי בחטא ויגרום לי להמסר ביד עשו לשון רש"י ואיננו נכון בלשון הכתוב ועוד כי אמר אחרי כן ואתה אמרת היטב איטיב עמך ושמתי את זרעך כחול הים ומה יועיל הבטחון ההוא אם גרם החטא אחר כך ועוד כי יעקב הזכיר שתי הבטחות שהבטיחו הקב"ה בבית אל ובחרן ואמר תחלה מה שנאמר לו בחרן ה' האומר אלי שוב לארצך ולמולדתך ואיטיבה עמך והוא שנאמר לו בצאתו מבית לבן (לעיל לא ג) שוב אל ארץ אבותיך ולמולדתך ואהיה עמך והנה אחרי כן לא היטיב לו בכל החסדים ובכל האמת האלה שיתמעטו זכיותיו על ידיהם אבל "קטונתי" לומר כי קטון הוא מהיותו ראוי לכל החסדים שעשה עמו וכן מי יקום יעקב כי קטון הוא (עמוס ז ב) מהיותו יכול לסבול כל הנגזר עליו וכן אמרו בבראשית רבה (עו ח) קטונתי רבי אבא אמר איני כדאי והחסדים הם הטובות שעשה עמו בלא נדר והאמת הטובה אשר הבטיחו ואימת לו הבטחתו יאמר שאיננו ראוי שיבטיחנו ויעשה לו אותן טובות שהבטיחו בהן ולא לטובות אחרות רבות שעשה עמו ולא הבינותי דעת אונקלוס שתרגם מכל חסדין ומכל טבון והוא רגיל לתרגם חסד ואמת "טיבו וקשוט" (לעיל כד מט להלן מז כט) ואולי עושה חסדים הצלתו אשר הצילו פעמים רבות מכל צרותיו ועשה אמת כל הטוב הזה שהיה לו כי נתן לו בנים ובנות ועושר ונכסים וכבוד והנכון בעיני כי החסדים הקיימים יקראו אמת כי היא מגזרת אמנה כטעם ונאמן ביתך וממלכתך עד עולם ( ז טז) ענין קיום לחמו נתן מימיו נאמנים (ישעיהו לג טז) כאשר אמר היו תהיה לי כמו אכזב מים לא נאמנו (ירמיהו טו יח)
@940 **והכני אם על בנים** . פירשו בו (הראב"ע) והכני והכה אם על בנים וכן רבים
@941 **ואתה אמרת היטב איטיב עמך** . אף על פי שהיתה פחדתו פן יגרום החטא אמר עשית עמדי חסדים גדולים שלא הייתי ראוי להם כל שכן שיש לעשות עמי חנם החסד הזה אשר הבטחתני עליו שתיטיב לי ותרבה את זרעי ואין חטאי ראוי למנוע ממני הטובה אשר הבטחתני בה כי גם מתחילה לא הייתי ראוי לה אם עונות תשמור לי ולא הבטחתני עליה בעבור מעשי רק בחסדיך הרבים ויש אומרים כי יעקב היה חומל על בניו ועל ביתו פן יכה אותם עשו כי לא היה יודע בהבטחת והיה זרעך כעפר הארץ אם על אלה או על אחרים כי יתכן שימלט הוא לבדו וירבה עוד זרעו ואיננו נכון בעיני כי אם היתה זאת מחשבתו איך אמר בתפלתו ואתה אמרת היטב איטיב עמך ושמתי את זרעך ועוד כי שם נאמר לו והנה אנכי עמך ושמרתיך בכל אשר תלך והשיבותיך אל האדמה הזאת כי לא אעזבך ואם יהיו בניו נופלים בחרב אחיו אין ההבטחה הזאת קיימת ולזה ירמוז באמרו היטב איטיב עמך וכן ואיטיבה עמך כי כל זה ממה שנאמר לו (לעיל לא ג) ואהיה עמך אבל הכל מיראת חטא כי דרך הצדיקים לירא תמיד והיה מתירא אולי אפילו משיצא משם חטא בבואו בברית עם לבן עובד עבודה זרה או בדבר אחר ושגיאות מי יבין
@942 **מן הבא בידו מנחה** . יאמר כי עשה מנחה מאשר עמו כי עשרו היה צאן ובקר ומהם שלח כי בדרך היה ואיננו מקום לשלוח לו כלי כסף וכלי זהב ומגדנות
@945 **ורוח תשימו בין עדר** . כדי להשביע עינו של אותו הרשע ולתווהו על הדורון וסברו בבראשית רבה (עה יג) שיש בזה רמז אמר יעקב לפני הקב"ה רבונו של עולם אם יהיו צרות באות על בני לא תביא אותן זו אחר זו אלא הרוח להם מצרותיהם עשה רמז שיהיו המסים והארנוניות שיגבו בני עשו מזרעו ברוח והפרש בין זו לזו
@949 **אכפרה פניו במנחה** . אבטל רוגזיה וכן וכפר בריתכם את מות (ישעיהו כח יח) לא תוכלי כפרה (שם מז יא) ונראה בעיני שכל כפרה שאצל חטא ועון ואצל פנים כלם לשון קנוח והעברה הן ולשון ארמית הוא בהרבה מקומות בעי לכפורי ידיה (גיטין נו) וגם בלשון מקרא נקראים המזרקים כפורי זהב (עזרא א י) על שם שבהם מקנח ידיו בשפת המזרק לשון רבינו שלמה וכן אמר אונקלוס אנחיניה לרוגזיה ואם כן יהיה פירושו כי חשב יעקב בלבו אכפרה פניו והכתוב מגיד לנו זה כי איננו ראוי שיאמרו השלוחים לעשות ככה וכך פירש רבי אברהם ואיננו ישר בעיני שיצטרך הכתוב להגיד לנו עתה מחשבתו זאת והיא ידועה בכל שולחי מנחה ועוד שאם כן היה ראוי שיזכיר הכתוב זה בתחלה והנה גם הוא אחרינו כי חשב אכפרה פניו כי עתה לא הוסיף על הצואה ההיא אבל הנכון כי עתה הוסיף לפרש להם שיאמרו הנה גם הוא אחרינו בלשון כבוד כלשון זה גם הנה עבדך יעקב אחרינו והקדים אותנו לפניו לתת כופר נפשו על ראותו פני כבודך במנחה הזאת כאשר יתנו העבדים כפרם בתת להם רשות לראות פני המלך ואחרי כן אראה פניו כי אולי ישא פני ויכבדני להיותי מרואי פני המלך וזה דרך מעלה מיראתו ממנו ובא אכפרה פניו כדרך ואיש חכם יכפרנה (משלי טז יד) יתן כפר על החמה ולשון קנוח בכפור איננו לשון קדש רק לשון ארמית וכן כפורי זהב שם המזרקים בבבל כי לעולם לא תבא כפרה בחטא אבל יאמר לכפר על נפשותיכם (שמות ל טו) לכפר עליו ונסלח לו (במדבר טו כח) על נפשו ויאמר אכפרה בעד חטאתכם (שמות לב ל) וכולן מלשון ונתנו איש כופר נפשו (שם ל יב) שהוא פדיון
@950 **והוא לן בלילה ההוא במחנה** . יאמר שלא בא באהלו בלילה ההוא אבל לן במחנה עם עבדיו ועם הרועים בצאן ערוך כאיש מלחמה פן יבא אחיו בלילה ויכה בו
@951 **ויקח את שתי נשיו ואת שתי שפחותיו** . אין מוקדם ומאוחר בפסוק הזה להצלה אבל אמר שאסף נשיו ושפחותיו וילדיו אל שפת הנחל ועבר הוא לבדו את מעבר יבוק לראות אם גבהו המים ושב ולקחם עמו כולם כאחד ויעבירם את הנחל ואחרי כן ויעבר את אשר לו מקנהו ורכושו
@951 "ויותר יעקב לבדו" - ששכח פכים קטנים וחזר עליהן לשון רש"י ועל דרך הפשט ויקחם ויעבירם את הנחל העבירם עמו ויעבר את אשר לו בצווי כי חזר וצוה שיעברו לפניו ונשאר הוא אחריהם
@951 "ויאבק איש עמו" - ויתעפר כך פירשו מנחם לשון אבק שמעלין אבק ברגליהם ולי נראה לשון ויתקשר ולשון ארמי הוא בתר דאביקו ביה (סנהדרין סג) ואביקו ליה מיבק (מנחות מב) זה לשון רש"י ואביקה בלשון חכמים חביקה שמשו בה הרבה אבקתא אית בה (מכות כג) דרגש עיולי ואפוקי באבקתא (נדרים נו) וכן אבוקה בלשונם בעבור היותה מעצים דקים חגורים וקשורים יחד כי החי"ת תכבד בלשונם והקלו אותה לאל"ף ופעמים רבים יבליעו החי"ת תותך (חולין ז) במקום תחותך (זבחים נד) מסותא (ב"מ ו) במקום מסחותא (קדושין לג) אסיתא חסיתא (שבת עז) ואפשר שיהיה ויאבק ויחבק כמו ויחבקהו (להלן לג ד) כי אולי כן הלשון ומצינו ברודים אמוצים (זכריה ו ג) כמו חמוצים מלשון חמוץ בגדים (ישעיהו סג א) ואמרו המפרשים (הרד"ק) כי וארוזים במרכולתך (יחזקאל כז כד) כמו וחרוזים מן צוארך בחרוזים (שיר השירים א י) וכן אמרו במלת ותאלצהו (שופטים טז טז) שהוא כמו ותחלצהו מהופך מן ותלחצהו ושמא הוא דעת אונקלוס שאמר ואשתדל וכך תרגם וכי יפתה (שמות כב טו) ארי ישדל יחבק וינשק שהוא דרך הפתוי או שלא נזדמן לו לשון ועשאו ענין תחבולה כי כל השתדלות תחבולה וצדוד ענין ובבראשית רבה (עז ג) מי נתמלא אבק האיש שהיה עמו כדברי מנחם והוא הנכון
@954 **וירא כי לא יכל לו** . מלאכיו גבורי כח עושי דברו ועל כן לא יכול לו המלאך להזיקו כי לא הורשה רק במה שעשה עמו להקע כף ירכו ואמרו בבראשית רבה (עז ג) נגע בכל הצדיקים שעתידין להיות ממנו זה דורו של שמד והענין כי המאורע כלו רמז לדורותיו שיהיה דור בזרעו של יעקב יתגבר עשו עליהם עד שיהיה קרוב לקעקע ביצתן והיה זה דור אחד בימי חכמי המשנה כדור של רבי יהודה בן בבא וחביריו כמו שאמרו (שיר השירים ב ז) אמר רבי חייא בר אבא אם יאמר לי אדם תן נפשך על קדושת שמו של הקב"ה אני נותן ובלבד שיהרגוני מיד אבל בדורו של שמד איני יכול לסבול ומה היו עושים בדורו של שמד היו מביאין כדוריות של ברזל ומלבנין אותן באור ונותנין אותן תחת שיחיהן ומשיאין נפשותיהן מהן ויש דורות אחרים שעשו עמנו כזה ויותר רע מזה והכל סבלנו ועבר עלינו כמו שרמז ויבא יעקב שלם
@958 **למה זה תשאל לשמי** . אמר אין לך בידיעת שמי תועלת כי אין הכח והיכולת בלתי לה' לבדו אם תקראני לא אענך וגם מצרתך לא אושיעך אבל עתה אברך אותך כי כן צוותי ולא פירש הכתוב הברכה והקרוב מה שאמרו רבותינו (במדרש אגדה ובזוה"ק תולדות קמד) שהודה לו על כל הברכות שם במקום ההוא על כרחו כי לא רצה יעקב להמתין לו עד בית אל
@966 **מי אלה לך** . שאל על הנשים ועל הילדים וענה הילדים אשר חנן אלהים את עבדך דרך מוסר כי לא רצה לומר שהם נשיו והבין עשו שהן אמות הילדים
@969 **מי לך כל המחנה הזה אשר פגשתי** . הנה עבדי יעקב עשו כאשר צוה אותם ולא רצה לקבל מהם או שהוא בגאותו ועברתו לא דבר עמם ולא שאלם למי אתה ואנה תלך והם יראו מגשת אליו ואמר עתה מי לך כל המחנה הזה כי חשב שהם ליעקב מדברי המלאכים הראשונים או שאלה השלוחים הגידו כן במחנה עשו או שאין אדם אחד בדרך ההוא להיות לו כן וטעם מי לך כל המחנה הזה כלומר מי זה לך שתשלח לו כל אלה כלומר מי הוא הגדול אצלך שתשלח לו כל אלה והוא ענהו למצוא חן בעיני אדוני כי אתה הגדול והאדון בעיני
@971 **כי על כן ראיתי פניך** . אמר לו תקח מנחתי מידי בעבור שראיתי פניך שהם לי כראות פני אלהים ותרצני בקבלת המנחה כאשר האלהים רוצה את יראיו בקבלת מנחתם וקרבנם כענין ונרצה לו (ויקרא א ד) עולותיכם וזבחיכם לרצון על מזבחי (ישעיהו נו ז) מלשון יהי רצוי אחיו (דברים לג כד) ואור פניך כי רציתם (תהלים מד ד) כי רצו עבדיך את אבניה (שם קב טו) כולם ענין חפץ וחשק בדבר ורש"י כתב על שנתרצית למחול לי על סורחני ותרצני נתפייסת לי וכבר אמרתי (לעיל לב כא) שאיננו טוב שיהיה לו מזכיר עון
@972 **קח נא את ברכתי** . המנחה וכן עשו אתי ברכה (מלכים ב יח לא) השיבו לי מנחה וכן קח נא ברכה מאת עבדך (שם ה טו) ויקראו המנחה שישלח האדם לרצונו ברכה כי הוא שולח מאשר ברך אותו השם כענין אשר ברכך ה' אלהיך תתן לו (דברים טו יד) כאשר אמר למעלה (לב יד) מן הבא בידו והמנחה אשר התנו בה למלך בדבר ידוע תקרא מס
@974 **ומתו כל הצאן** . דרך חמלה שהיה לו לומר "ומתו כלם" אבל לא יאמר כן על הילדים וגם לא רצה לומר "ומתו" סתם על הבקר ועל הצאן כי יחמול על הילדים שלא יהיו במשמע ולא רצה להאריך "ומתו כל הצאן והבקר" או יהיה פירושו כי הילדים רכים ויעפו נערים וייגעו ולא ירצו ללכת והצאן והבקר עלות ואם ידחקום ימותו הצאן שהם בהמה דקה כי הבקר לא ימות אבל יזיק להם
@975 **עד אשר אבא אל אדוני שעירה** . היה ליעקב בשובו אל ארצו דרך בארץ שעיר והנה אמר לו עשו ואלכה לנגדך שלא יפרד ממנו עד שובו אל אביו לעשות לו כבוד בבואו אל ארצו ויעקב אמר אני אלך לאטי ואדני ישוב אל עיר ממשלתו ואם אשוב דרך עירו יכבדני וילך עמי כאשר יחפוץ ולא היה זה נדר ממנו שיבא אליו שאין עשו צריך לו ורבותינו אמרו (ע"ז כה) עוד שלא היה בדעת יעקב לשוב דרך שעיר ורצונו היה להתרחק ממנו כאשר יוכל אבל הרחיב לו את הדרך וגם זו עצת חכמה ועוד להם מדרש אחר (ב"ר עח יד) שיקים דברו לימות המשיח שנאמר (עובדיה א כא) ועלו מושיעים בהר ציון לשפוט את הר עשו יאמר כי המושיעים אשר בהר ציון יעלו לשפוט את הר עשו
@976 **למה זה אמצא חן בעיני אדני** . למה זה תעשה לי טובה שאיני צריך לה אמצא חן בעיניך ולא תשלם עתה שום גמול לשון רש"י והכונה ביעקב כי לא היה חפץ בהם ובחבורתם כלל וכל שכן שהיה בדעתו ללכת דרך אחרת ורבותינו ראו עוד בזה עצה אמרו (ב"ר עח טו) רבי ינאי כד הוה סליק למלכותא הוה מסתכל בהדא פרשתא ולא הוה נסיב עמיה רומאין חד זמן לא איסתכל בה ונסיב עמיה רומאין ולא הגיעו לעכו עד שמכר פינס שלו מפני שהיתה קבלה בידם שזו פרשת גלות כשהיה בא ברומה בחצר מלכי אדום על עסקי הצבור היה מסתכל בפרשה זו ללכת אחרי עצת הזקן החכם כי ממנו יראו הדורות וכן יעשו ולא היה מקבל חברת אנשי רומי ללותו שאין מקרבין אלא להנאת עצמן ומפקירין ממונו של אדם
@978 **ויבן לו בית** . יתכן כי היה המקום מקום אין שם עיר והוצרך לבנות לו בית ולעשות סוכות או ויבן לו בית שבנה לו בית גדול ובו מגדל עז להשגב מפני עשו
@979 **ויבא יעקב שלם מפדן ארם** . כאומר לחברו יצא פלוני מבין שני אריות ובא שלם אף כאן ויבא יעקב שלם מלבן ומעשו זה לשון רש"י אבל רבי אברהם פירש שבא בשלום ולא אירע לו שום מאורע כי עתה יחל לספר מאורע דינה ולפי דעתי אמר הכתוב כן כי בסוכות היה מתפחד מעשו כי סכות בעבר הירדן מזרח במלכות סיחון אם הוא המוזכר בספר יהושע (יג כז) ואם הוא אחר הנה הוא יותר קרוב לשעיר ועד היותו בארץ כנען לא שקט לבו כי אז ידע שלא יגע בו כי אביו קרוב משם או שיעזרוהו אנשי הארץ כי אביו נשיא אלהים בתוכם או שזכות הארץ תצילהו ולכן אמר עתה שבא שלם אל ארץ מגורי אביו כי הצילו אלהים בדרך מכף כל אויביו ואמרו בבראשית רבה (עח טז) כל אותן החדשים שעשה יעקב אבינו בסוכות היה מכבד את עשו באותו הדורון כי היה מתירא ממנו שם ומשלח לו כאותו הדורון בכל חדש וחדש או פעם אחת בשנה
@979 "ויחן את פני העיר" - לא רצה להיות אכסנאי בעיר אבל רצה שתהיה תחילת ביאתו בארץ בתוך שלו ולכן חנה בשדה וקנה המקום וזה להחזיק בארץ והמעשה הזה היה רמז כי המקום ההוא יכבש לפניו תחילה טרם הורישו יושבי הארץ מפני זרעו כאשר פרשתי באברהם (לעיל יב ו) ורבותינו אמרו (ב"ר עט ו) נכנס עם דמדומי חמה וקבע לו תחומין ועל דעתם לא היה בכוונה ממנו אבל על כל פנים היה המאורע לרמוז על העתיד שאמרנו אבל רבי אברהם אמר כי הזכיר הכתוב זה להודיע כי מעלה גדולה לארץ ישראל ומי שיש לו חלק בה חשוב הוא כחלק העולם הבא
@981 **ויקרא לו אל אלהי ישראל** . לא שהמזבח קרוי אלהי ישראל אלא על שם שהיה הקב"ה עמו להצילו קרא שם המזבח על שם הנס להיות שבחו של הקב"ה נזכר בקריאת המזבח כלומר מי שהוא אל הוא אלהים לי ששמי ישראל וכן מצינו במשה ויקרא שמו ה' נסי (שמות יז טו) לא שהמזבח קרוי ה' אלא על שם הנס קרא שם המזבח להזכיר שבחו של הקב"ה ה' הוא נסי ורבותינו דרשו (מגילה יח) שהקב"ה קראו ליעקב אל ודברי תורה כפטיש יפוצץ סלע מתחלקין לכמה טעמים ואני לישב פשוטו באתי כל זה לשון רש"י והנה צדקו דברי הרב בפשוטו של מקרא ויהי טעם "לו" כטעם קרא לו בנימין (להלן לה יח) וקורא לך גודר פרץ (ישעיהו נח יב) ודע כי המנהג הזה בישראל כן שיקראו השמות בשבחי האל כמו צוריאל (במדבר ג לה) צורישדי (שם א ו) כי יגיד הקורא שהאל הוא צורו ושדי הוא צורו וכן עמנו אל (ישעיהו ז יד) וכן שם המשיח ה' צדקנו (ירמיהו לג טז) ושם ירושלים ה' שמה (יחזקאל מח לה) וכן יעשו בשמות מלאכים גבריאל (דניאל ח טז) מיכאל (שם ו כא) כי בעבור גדולת כחם יגידו בשמם כי הגבורה לאל ומי כמוהו אבל אונקלוס אמר ופלח עלוהי קדם אל אלהא דישראל ויהיה טעם "לו" כטעם בו כדרך כי בוחר אתה לבן ישי (שמואל א כ ל) והחזיק לו ( טו ה) למי מריבה (במדבר כ כד) או יאמר ויקרא אל אלהי ישראל וטעם "לו" כטעם אלכה לי אל הגדולים (ירמיהו ה ה) לך לך מארצך (לעיל יב א) ועל דרך האמת הוא כמדרש רבותינו שדרשו רבותינו במסכת מגלה (יח) מנין שקראו הקב"ה ליעקב אל שנאמר ויקרא לו אל אלהי ישראל ויש בענין הזה סוד גדול הזכירוהו עוד בבראשית רבה (עט ח) בלשון אחר אמר לו אתה אלוה בעליונים ואני אלוה בתחתונים ירמזו למה שהם אומרים תמיד שאיקונין של יעקב חקוקה בכסא הכבוד והכונה שהשכינה שורה בארץ ישראל והמשכיל יבין
@982 **וטעם בת לאה אשר ילדה ליעקב** . לומר שהיא אחות שמעון ולוי המקנאים ונוקמים נקמתה והזכיר אשר ילדה ליעקב כי כל האחים קנאו בה
@983 **וישכב אותה ויענה** . וישכב כדרכה ויענה שלא כדרכה (ב"ר פ ה) לשון רש"י אבל רבי אברהם אמר ויענה בעבור היותה בתולה ואין צורך כי כל ביאה באונסה תקרא ענוי וכן לא תתעמר בה תחת אשר עניתה (דברים כא יד) וכן ואת פלגשי ענו ותמת (שופטים כ ה) ויגיד הכתוב כי היתה אנוסה ולא נתרצית לנשיא הארץ לספר בשבחה
@988 **וכן לא יעשה** . לענות הבתולות שהאומות גדרו עצמן מן העריות מפני המבול לשון רש"י ולא ידעתי זה כי הכנענים שטופים בעריות ובבהמה ובזכור דכתיב (ויקרא יח כז) כי את כל התועבות האל עשו אנשי הארץ אשר לפניכם ולא התחילו בהן באותו הדור ובימי אברהם ויצחק היו יראים פן יהרגו אותן לקחת נשיהם אבל "וכן לא יעשה" נמשך עם בישראל כי נבלה עשה בישראל וכן לא יעשה בהם על כן אמר בישראל כי איננה נבלה בין הכנענים ואונקלוס אמר לא כשר לאיתעבדא לומר שהוא אסור ולכך היא נבלה בישראל
@993 **מהר** . פראנון מתן פרא פרנון והם כתובה ונכסי מלוג בלשון ירושלמי כלומר שיתן לה הוא משלו נכסים שיהיו שלה כנכסי בית אביה ויהיו אצלו כנכסי מלוג וטעם הפיוס הזה כדי שיתנו אותה לו לאשה ברצון כי הנערה לא היתה מתרצה אליו וצועקת ובוכה תמיד וזה טעם וידבר על לב הנערה ולכך אמר קח לי את הילדה הזאת לאשה שכבר היא בביתו ובידו ולא יירא מאחיה כי הוא נשיא הארץ ואיך יגזלוה ממנו להוציאה מביתו והחשק הגדול לשכם כי היתה הנערה יפת תאר מאד אבל לא סיפר הכתוב ביפיה כאשר עשה בשרה וברבקה וברחל כי לא ירצה להזכיר יפיה בהיותו אליה למכשול עון ובשבח הצדיקות דבר הכתוב ולא בזו וכן לא הזכיר מה נעשה בה אחרי כן ועל דרך הפשט עמדה עם אחיה צרורה באלמנות חיות כי היתה טמאה בעיניהם כדכתיב
@993 "אשר טמא את דינה אחותם" - ורבותינו נחלקו בה (ב"ר פ יא) והקרוב דברי האומר נטלה שמעון וקברה בארץ כנען והוא כמו שאמרנו כי היתה עמו בביתו כאלמנה וירדה עמהם למצרים ושם מתה ונקברה בארץ וקבורתה ידועה עד היום בקבלה והיא בעיר ארבאל עם קבר ניתאי הארבלי ויתכן כי העלה שמעון עצמותיה בחמלו עליה או שהעלו אותם ישראל עם עצמות אחיה כל השבטים כמו שהזכירו רבותינו (ב"ר ק יא)
@994 **ויענו בני יעקב את שכם ואת חמור אביו במרמה** . הנה חמור ושכם אל אביה ואל אחיה דברו אבל הזקן לא ענה אותם דבר כי בניו ידברו במקומו בענין הזה לכבודו כי בעבור היות הדבר להם לקלון לא ירצו שיפתח פיו לדבר בו כלל ויש כאן שאלה שהדבר נראה כי ברצון אביה ובעצתו ענו כי לפניו היו והוא היודע מענם כי במרמה ידברו ואם כן למה כעס ועוד שלא יתכן שיהיה רצונו להשיא בתו לכנעני אשר טמא אותה והנה כל האחים ענו המענה הזה במרמה ושמעון ולוי לבדם עשו המעשה והאב ארר אפם להם לבדם והתשובה כי המרמה היתה באמרם להמול להם כל זכר כי חשבו שלא יעשו כן בני העיר ואם אולי ישמעו לנשיאם ויהיו כלם נמולים יבואו ביום השלישי בהיותם כואבים ויקחו את בתם מבית שכם וזאת עצת כל האחים וברשות אביהם ושמעון ולוי רצו להנקם מהם והרגו כל אנשי העיר ויתכן שהיה הכעס ליעקב שארר אפם על שהרגו אנשי העיר אשר לא חטאו לו והראוי להם שיהרגו שכם לבדו וזהו מה שאמר הכתוב ויענו בני יעקב את שכם ואת חמור אביו במרמה וידברו אשר טמא את דינה אחותם כי כולם הסכימו לדבר לו במרמה בעבור הנבלה שעשה להם ורבים ישאלו ואיך עשו בני יעקב הצדיקים המעשה הזה לשפוך דם נקי והרב השיב בספר שופטים (רמב"ם הלכות מלכים פי"ד ה"ט) ואמר שבני נח מצווים על הדינים והוא להושיב דיינין בכל פלך ופלך לדון בשש מצות שלהן ובן נח שעבר על אחת מהן הוא נהרג בסייף ראה אחד שעבר על אחת מהן ולא דנוהו להרגו הרי זה הרואה יהרג בסייף ומפני זה נתחייבו כל בעלי שכם הריגה שהרי שכם גזל והם ראו וידעו ולא דנוהו ואין דברים הללו נכונים בעיני שאם כן היה יעקב אבינו חייב להיות קודם וזוכה במיתתם ואם פחד מהם למה כעס על בניו וארר אפם אחר כמה זמנים וענש אותם וחלקם והפיצם והלא הם זכו ועשו מצוה ובטחו באלהים והצילם ועל דעתי הדינין שמנו לבני נח בשבע מצות שלהם אינם להושיב דיינין בכל פלך ופלך בלבד אבל צוה אותם בדיני גנבה ואונאה ועושק ושכר שכיר ודיני השומרים ואונס ומפתה ואבות נזיקין וחובל בחבירו ודיני מלוה ולוה ודיני מקח וממכר וכיוצא בהן כענין הדינין שנצטוו ישראל ונהרג עליהן אם גנב ועשק או אנס ופתה בתו של חבירו או שהדליק גדישו וחבל בו וכיוצא בהן ומכלל המצוה הזאת שיושיבו דיינין גם בכל עיר ועיר כישראל ואם לא עשו כן אינן נהרגין שזו מצות עשה בהם ולא אמרו (סנהדרין נז) אלא אזהרה שלהן זו היא מיתתן ולא תיקרא אזהרה אלא המניעה בלאו וכן דרך הגמרא בסנהדרין (נט) ובירושלמי אמרו בדינין של נח הטה דינו נהרג לקח שחד נהרג בדיני ישראל כל דין שאתה יודע שאתה שלם ממנו אי אתה רשאי לברוח ממנו וכל שאתה יודע שאי אתה שלם ממנו אתה רשאי לברוח ממנו אבל בדיניהם אף על פי שאתה יודע שאתה שלם ממנו אתה רשאי לברוח ממנו נראה מכאן שרשאי הגוי לאמר לבעלי הדין איני נזקק לכם כי תוספת היא בישראל לא תגורו מפני איש (דברים א יז) אל תכניס דבריך מפני איש (סנהדרין ו) וכל שכן שלא יהרג כשלא יעשה עצמו קצין שוטר ומושל לשפוט את אדוניו ומה יבקש בהן הרב חיוב וכי אנשי שכם וכל שבעה עממין לא עובדי עבודה זרה ומגלה עריות ועושים כל תועבות השם היו והכתוב צווח עליהן בכמה מקומות (דברים יב ב) על ההרים הרמים ועל הגבעות ותחת כל עץ רענן וגו' לא תלמד לעשות וכו' (שם יח ט) ובגלוי עריות כי את כל התועבות האל עשו וכו' (ויקרא יח כז) אלא שאין הדבר מסור ליעקב ובניו לעשות בהם הדין אבל ענין שכם כי בני יעקב בעבור שהיו אנשי שכם רשעים ודמם חשוב להם כמים רצו להנקם מהם בחרב נוקמת והרגו המלך וכל אנשי עירו כי עבדיו הם וסרים אל משמעתו ואין הברית אשר נמולו נחשב בעיניהם למאומה כי היה להחניף לאדוניהם ויעקב אמר להם בכאן כי הביאוהו בסכנה שנאמר עכרתם אותי להבאישני ושם ארר אפם כי עשו חמס לאנשי העיר שאמרו להם במעמדו וישבנו אתכם והיינו לעם אחד והם היו בוחרים בהם ובעטו בדבורם ואולי ישובו אל ה' והרגו אותם חנם כי לא הרעו להם כלל וזהו שאמר כלי חמס מכרותיהם (להלן מט ה) ואם נאמין בספר "מלחמות בני יעקב" (הוא ספר הישר) בא להם פחד אביהם כי נאספו שכני שכם ועשו עמהם שלש מלחמות גדולות ולולי אביהם שחגר גם הוא כלי מלחמתו ונלחם בם היו בסכנה כאשר יספר בספר ההוא ורבותינו (ב"ר פ י) הזכירו מזה בפסוק אשר לקחתי מיד האמורי בחרבי ובקשתי (להלן מח כב) אמרו נתכנסו כל סביבותיהם להזדווג להם חגר יעקב כלי מלחמה כנגדן כמו שכתב רש"י שם אבל הכתוב יקצר בזה כי היה נס נסתר כי אנשים גבורים היו וכאלו זרועם הושיעה למו כאשר קצר הכתוב בענין אברהם באור כשדים ולא הזכיר מלחמת עשו עם החורי כלל אבל הזכיר בכאן כי היה חתת אלהים על הערים אשר סביבותיהם ולא נאספו כולם לרדוף אחרי בני יעקב כי היו נופלים עליהם כחול אשר על שפת הים לרוב וזה טעם "חתת אלהים" כי נפלה עליהם אימתה ופחד מן הגבורה אשר ראו במלחמה ולכך אמר (להלן לה ו) ויבא יעקב לוזה הוא וכל העם אשר עמו להודיע שלא נפקד מהם ולא מעבדיהם איש במלחמה
@1002 **שלמים הם אתנו** . היו אנשי העיר חושבים שהיו שונאים אותם כי ראו אותם עצבים ויחר להם מאד ואולי היו נשמרים מהם ונותנים בעירם בריח ודלתים כי גבורים המה ואנשי חיל למלחמה ועתה אמרו להם אל תפחדו ואל תתרחקו מהם כי בלב שלם הם אתנו
@1004 **וטעם מקניהם וקנינם וכל בהמתם** . כי הבהמות אשר בעדרים בשדה הם יקראו מקנה בעבור שהם עיקר קנין האדם בין טמאות בין טהורות כענין שכתוב (שמות ט ג) הנה יד ה' הויה במקנך אשר בשדה בסוסים בחמורים בגמלים בבקר ובצאן ואשר אינם עדר כגון בהמות יחידות בבית אין שמם מקנה ויכנסו בכלל "וכל בהמתם" או הוא כפל הלשון לחזוק כלומר וכל בהמתם אשר הנם רבות מאד
@1013 **ושב שם ועשה שם מזבח** . לא ידעתי מהו ושב שם ויתכן שצוהו לשבת שם תחלה ואחר כן יעשה המזבח להטהר מעבודה זרה או מן החללים שהרגו כענין ואתם חנו מחוץ למחנה שבעת ימים (במדבר לא יט) כי לא צוו עדיין במי חטאת ויעקב נזדרז במצוה להטהר טרם בואו שם או שיהיה ונקומה ונעלה בית אל מוקדם במעשה ואולי צוה ושב שם לפנות מחשבתו לדבקה באל
@1016 **ויטמון אותם יעקב** . עבודה זרה ומשמשיה אינן מן הנקברים אבל צריך שיהא מפרר וזורה לרוח או מטיל לים (ע"ז מג) והנראה אלי כי בני יעקב לא לקחו עבודה זרה ומשמשיה משכם עד שנתבטלה והותרה להם שהעכו"ם מבטל עבודה זרה בעל כרחו (שם מג) והנה היא מותרת להם אבל יעקב צוה להסיר אותה לטהרת הקדש שיהיו ראויים לעבוד את השם ולהקריב לפניו קרבן כאשר צוה להם בטבילה וחלוף הבגדים והיה די להם בקבורה ולכן טמן אותם תחת האלה במקום שלא יעבד בו ולא יזרע
@1020 **ותמת דבורה מינקת רבקה** . לא ידעתי למה נכנס הפסוק הזה בין "ויקרא למקום אל בית אל" ובין "וירא אלהים אל יעקב עוד" והפסיק בענין אחר שהיה בבת אחת ובמקום אחד כי יעקב בבאו לוזה היא בית אל בנה מזבח וקרא למקום אל בית אל ונראה לו האלהים שם ויברך אותו ולמה הושם הכתוב הזה בתוך ענין אחד והקרוב מה שאמרו רבותינו (ב"ר פא ה) שירמוז למיתת רבקה ולכן קרא שם המקום ההוא אלון בכות כי אין בכי ואנקה על המינקת הזקנה שיקרא שם המקום עליו אבל יעקב בכה והתאבל על אמו הצדקת אשר אהבתהו ושלחה אותו שם ולא זכתה לראותו בשובו ולכן נגלה אליו האלהים וברך אותו לנחמו כאשר עשה ליצחק אביו אחרי מות אברהם (לעיל כה יא) ובשניהם אמרו חכמים (סוטה יד) ברכת אבלים ברכו וסיוע לזה מה שאמור למטה (פסוק כז) ויבא יעקב אל יצחק אביו ממרא קרית הארבע ואלו היתה רבקה שם היה מזכיר "אל אביו ואל אמו" כי היא השולחת אותו שם והגורמת לו כל הטובה ויצחק בעצתה צוה אותו ללכת שם וכתב רש"י ולפי שהעלימו את יום מותה שלא יקללו אותה הבריות כרס שיצא ממנה עשו אף הכתוב לא פרסמה ומדרש חכמים הוא (פסדר"כ זכור ד) והנה גם מיתת לאה לא יזכיר אבל הכוונה להם מפני שהזכיר המיתה ברמז ותלה הדבר במניקתה וכיון שדבר בה למה הסתיר הענין ולא גלהו וטעם הקללה אינו מחוור שהרי הזכירו במיתת יצחק (להלן פסוק כט) ויקברו אותו עשו ויעקב בניו אבל יתכן לומר שלא היה לה כבוד במיתתה כי יעקב איננו שם ועשו שונא אותה ולא יבא שמה ויצחק כהו עיניו ואיננו יוצא מביתו ולכן לא רצה הכתוב להזכיר שיקברוה בני חת וכענין הזה מצאתי (באלה הדברים רבה בפרשה כי תצא למלחמה) תנחומא תצא ד אמרו אתה מוצא כשמתה רבקה אמרין מאן יפוק קמא אברהם מת יצחק יושב בבית ועיניו כהות יעקב הלך לו לפדן ארם יפוק עשו רשיעא קמא ויימרון ברייתא ליטין בזיא דהא כדין ינקין מה עשו הוציאו מטתה בלילה אמר רבי יוסי בר חנינה לפי שהוציאו מטתה בלילה לא פרשו הכתובים מיתתה אלא מן הצד הדא הוא דכתיב ויקרא שמו אלון בכות שתי בכיות הדא הוא דכתיב וירא אלהים אל יעקב ויברך אותו מה ברכו ברכת אבלים ברכו עד כאן והנה בעבור שהיה עשו יחידי בקבורתה פחדו מן הקללה ולא ראו שיהיה לה לכבוד וזה ענין הרמז והיתה דבורה עם יעקב כי אחרי שבאה עם רבקה שבה לארצה ועתה תבא עם יעקב לראות גברתה או נתעסקה בגדול בני יעקב לכבוד רבקה ולאהבתה והיתה בביתו ויתכן שאינה היא המינקת שנאמר בה (לעיל כד נט) וישלחו את רבקה אחותם ואת מניקתה אבל היתה מינקת אחרת שנשארה בבית לבן ובתואל ועתה יביא אותה יעקב עמו לכלכל את שיבתה לכבוד אמו כי כן דרך הנכבדים להיות להם מיניקות רבות כי רחוק הוא שתהיה הזקנה השליח שתשלח אמו ליעקב כדברי רבי משה הדרשן
@1022 **שמך יעקב** . יאמר כי עתה עודך אתה נקרא יעקב אף על פי שהחליף שמך שרו של עשו כי הוא לא נשתלח לך להחליף את שמך אבל מעתה לא יקרא שמך יעקב כי אם ישראל יהיה שמך וזה טעם ויקרא את שמו ישראל או ירמוז שקרא את שמו ישראל מוסף על יעקב לא שיאסר להקרא יעקב
@1024 **ואת הארץ אשר נתתי לאברהם וליצחק לך אתננה** . כאשר נתתיה להם כן אתננה לך ירמוז זה לשבועה כי להם נתנה בשבועה שלא יגרום החטא אבל לו נתנה מתחלה בלא שבועה וזהו שאומר בכל מקום (שמות לג א ועוד) אשר נשבעתי לאברהם ליצחק וליעקב או שיהיה הכפל הנבואה לו לשבועה כאשר פירשתי כבר
@1025 **ויעל מעליו אלהים** . כמו שאמר באברהם (לעיל יז כב) ויעל אלהים מעל אברהם ובשניהם להודיע כי לא היה זה מראה וחלום נבואה בלבד או כענין ותבא אותי ירושלימה במראות אלהים (יחזקאל ח ג) אבל ששרתה עליו שכינה במקום אשר הוא עומד ועל דרך האמת עלה מעליו אלהים במקום המדבר עמו כענין שנאמר ברוך כבוד ה' ממקומו (שם ג יב) ויאמר מה שהזכירו החכמים האבות הן הן המרכבה (ב"ר פב ו)
@1026 **ויצב יעקב מצבה** . פירש רבי אברהם וכבר הציב בפעם הראשונה מצבה ונסך עליה עתה נסך ויצק עליה שמן ונכון הוא
@1027 **ויקרא יעקב את שם המקום בית אל** . יקראנו כן פעם אחר פעם להודיע כי הדבר אמת ונכון כי הוא בית אלהים ושם השכינה תמיד וכן ענין שם באר שבע
@1028 **כברת ארץ** . מנחם פירש לשון "כביר" מהלך רב ואגדה (ב"ר פב ז) בזמן שהארץ חלולה ככברה שהניר מצוי והסתו עבר ועדיין השרב לא בא ואין זה פשוטו של מקרא שהרי בנעמן מצינו (מלכים ב ה יט) וילך מאתו כברת ארץ ואומר אני שהוא שם מדת קרקע לשון רש"י והנכון מה שחשב בו ר' דוד קמחי כי הכ"ף לדמיון ואיננה שרשית ומוצא המלה היו לברות למו (איכה ד י) ותברני לחם ( יג ה) ענין אכילה מועטת בבקר ופירושה שיעור מהלך ארץ מן הבקר עד לעת האוכל כי כן ישערו כל הולכי דרך זה כתבתי תחילה ועכשיו שזכיתי ובאתי אני לירושלם שבח לאל הטוב והמטיב ראיתי בעיני שאין מן קבורת רחל לבית לחם אפילו מיל והנה הוכחש הפירוש הזה וגם דברי מנחם אבל הוא שם מדת הארץ כדברי רש"י ואין בו תאר רק הסכמה כרוב השמות והכ"ף לשמוש שלא נמדד בכוון ואם יהיה השם הזה מתואר יתכן שיהיה ברת כמו בת מלשון מה ברי ומה בר בטני (משלי לא ב) והוא שם למדה הקטנה שימדדו הולכי ארחות כמו למיל היום ויאמר לה "בת ארץ" כי המדה כמו בת לפרסה או למדה אחרת ידועה בימים ההם וכן ראיתי שאין קבורה ברמה ולא קרוב לה אבל הרמה אשר לבנימן רחוק ממנה כארבע פרסאות והרמה אשר בהר אפרים (שמואל א א א) רחוק ממנה יותר משני ימים על כן אני אומר שהכתוב שאומר קול ברמה נשמע (ירמיהו לא יד) מליצה כדרך משל לאמר כי היתה רחל צועקת בקול גדול ומספד מר עד שנשמע הקול למרחוק ברמה שהיא בראש ההר לבנה בנימן כי איננו שם והיא חרבה מהם לא נאמר בכתוב "ברמה רחל מבכה על בניה" אבל אמר כי שם נשמע הקול ונראה בעיני כי קברה יעקב בדרך ולא הכניסה לעיר בית לחם יהודה הקרובה שם לפי שצפה ברוח הקודש שבית לחם אפרתה יהיה ליהודה ולא רצה לקברה רק בגבול בנה בנימן והדרך אשר המצבה בה קרובה לבית אל בגבול בנימין וכך אמרו בספרי (זאת הברכה לג יא) בחלקו של בנימין מתה כדאיתא בפרשת וזאת הברכה וראיתי ליונתן בן עוזיאל שהוא מרגיש בזה ואמר קל ברום עלמא אשתמע ותרגם כל הכתוב על כנסת ישראל
@1030 **בן אוני** . בן צערי בנימין נראה בעיני לפי שהוא לבדו נולד בארץ כנען שהוא בנגב כשאדם בא מארם נהרים כמו שאמר בנגב בארץ כנען (במדבר לג מ) הלוך ונסוע הנגבה (לעיל יב ט) בנימין בן ימין לשון צפון וימין אתה בראתם (תהלים פט יג) ולפיכך הוא מלא לשון רש"י ולא הבינותי זה שתהא ארץ ישראל דרומית לארם נהרים שהרי ארם מזרחית לארץ ישראל כדכתיב (לעיל כט א) וילך ארצה בני קדם וכתיב (במדבר כג ז) מן ארם ינחני בלק מלך מואב מהררי קדם ויעקב עבר הירדן שהוא למזרחה של ארץ ישראל והיה חוזר דרך אדום שהוא בדרום ארץ ישראל נמצא ארם מזרחית דרומית לארץ ישראל וארץ ישראל לצפונה אבל אם נולד בתחום בית לחם אפרתה שהוא בארץ יהודה כדכתיב (שופטים יט ב) בית לחם יהודה וכתיב (מיכה ה א) ואתה בית לחם אפרתה צעיר להיות באלפי יהודה הנה הוא בדרומה של ארץ ישראל והנה בין בית אל ובין בית לחם אפרת נולד ואם המקום בהר אפרים הרי הוא בצפונה של ארץ ישראל כדכתיב (יהושע יח ה) יהודה יעמוד על גבולו מנגב ובית יוסף יעמדו על גבולם מצפון ואם בחלקו של בנימין גם כן אינה בדרום דכתיב ויהי להם גבול לפאת צפונה ומכל מקום אין טעם לקרותו בן דרום והנכון בעיני כי אמו קראתו בן אוני ורצתה לומר בן אבלי מלחם אונים (הושע ט ד) לא אכלתי באוני (דברים כו יד) ואביו עשה מן אוני כחי מלשון ראשית אוני (להלן מט ג) ולאין אונים (ישעיהו מ כט) ולכן קרא אותו בנימין בן הכח או בן החוזק כי הימין בו הגבורה וההצלחה כענין שכתוב (קהלת י ב) לב חכם לימינו ימינך תמצא לכל שונאיך (תהלים כא ט) ימין ה' רוממה (שם קיח טז) רצה להיות קורא אותו בשם שקראתו אמו כי כן כל בניו בשם שקראו אותם אמותם יקראו והנה תרגם אותו לטובה ולגבורה וראיתי בבראשית רבה (פב ט) בן אוני בן צערי ואביו קרא לו בנימין בלשון הקדש ולא ידעתי מהו כי הכל לשון הקדש וכן שם כל בניו לשון קדש הוא אבל רמזו למה שאמרתי שתרגם הלשון לטובה
@1034 **וישמע ישראל** . סיפר הכתוב ענותנותו כי שמע בחלל בנו יצועיו ולא צוה שיוציאוהו מביתו מכלל בניו ולא ינחל עמהם אבל ימנה עמהם ויהיו שנים עשר והוא ימנה ראשון ולכך עשה משתי הפרשיות פסוק אחד כי אף על פי שהוא תחלת ענין שבא למנות השבטים משנולדו כולם רמז כי ראובן לא נדחה במעשהו ועל דרך הפשט יתכן שבלבל ראובן יצועי בלהה מפחדו שלא תלד ליעקב עוד כי הוא הבכור וחשב לקחת שני חלקים ויפסיד יותר מכל האחים ולא פחד מאמו כי זקנה היתה ואולי מתה זלפה או חשש לכבוד אמו בעבור היותה שפחתה ולכן נטלה ממנו הבכורה מדה כנגד מדה וזהו טעם ויהיו בני יעקב שנים עשר כי לא הוליד אחרי כן
@1040 **ויהיו ימי יצחק** . אין מוקדם ומאוחר בתורה מכירתו של יוסף קדמה למיתתו של יצחק לשון רש"י וכבר כתבתי (לעיל יא לב) שזה מנהג הכתוב בכל הדורות יספר ענין האדם ותולדותיו ומיתתו ויתחיל בתולדות הדור האחר וראוי היה להקדים מיתת יצחק לתולדות יעקב כאשר עשה באברהם ובכל דורות הראשונים אבל יתכון הכתוב להגיד כי יצחק מת בשיבה טובה זקן ושבע ימים אחרי ששב אליו בנו המבורך הנוחל מעלתו וקברוהו בכבוד עשו ויעקב בניו גדולי העולם ולא הוצרך להזכיר כי קברוהו במערת המכפלה בעבור שהזכיר כי היה בעיר ההיא ואנה יקברוהו רק בקבר אביו
@1043 **עדה בת אילון** . היא בשמת בת אילון ונקראת בשמת (לעיל כו לד) על שם שהיתה מקטרת בשמים לעבודה זרה ואהליבמה היא יהודית אותו רשע כינה שמה יהודית לומר שהיא כופרת בעבודה זרה כדי להטעות את אביו בשמת בת ישמעאל ולהלן הוא קורא לה מחלת (לעיל כח ט) מצאתי בהגדת מדרש ספר שמואל (פרק יז) שלשה מוחלין להם על כל עונותיהם גר שנתגייר והעולה לגדולה והנושא אשה ולמד הטעם מכאן לכך נקראת מחלת שנמחלו לו עונותיו כל זה לשון רש"י והנה לא נתן טעם באבי אהליבמה שנקרא שם בארי וכאן ענה ובשמת בת ישמעאל יהיה שם העצם והוא שם תואר לקטור הבשמים ובבראשית רבה (סז יג) אמרו נתן עשו דעתו להתגייר מחלת שמחל לו הקב"ה על עונותיו בשמת שנתבשמה דעתו עליו והנה שניהם תאר אין שם העצם נודע בם ולכך אמר רבי אברהם כי היו לה שני שמות וגם לאביה ויתכן לומר כי השתים נשים ההם מתו בלא בנים אולי נענשו בעבור שהיו מורת רוח ליצחק ולרבקה ונשא אחות אשתו בת אלון ואחרת אהליבמה בת ענה אבל בת ישמעאל אחות נביות בעבור שהיה לה שם כעור בלשון הקדש מחלת קרא את שמה בשם הנכבד אשר היה לאשתו הראשונה מלשון בשמים כי היתה חביבה עליו בעבור שהיתה ממשפחתו ואיננה רעה בעיני יצחק אביו
@1047 **ויקח עשו את נשיו ואת בניו ואת בנותיו** . זה המסע היה אחרי שוב אחיו מחרן והאחזו בארץ כנען כמו שאמר כאן ואפשר שהיה גם אחרי מות אביהם והנה בעוד אחיו בחרן היה עשו בשעיר ככתוב למעלה (לב ד) אבל הענין כי עשו הלך לשעיר בימי אלופי החרי יושבי הארץ ויהי לשר הולך עם ד' מאות איש ובניו וביתו היו בארץ כנען ויתכן שהיתה לו שם אחוזה במקום אחד במישור לא בהר שעיר על כן ייחס לו ארצה שעיר שדה אדום ואחרי שחזר אחיו לארץ כנען פנה לו מפניו כי ידע שארץ כנען נחלת אחיו אשר נתן לו אביו בברכתו ולקח בניו וכל נפשות ביתו עם רב והלך לשעיר להתיישב שם ואז נלחם בבני שעיר החרי יושבי הארץ כי אולי פחדו ממנו ולא היו נותנים אותו לבא בגבולם בהר שעיר שהיו שם המבצרים אלא שישב בשדה אדום במקומו הראשון וישמידם ה' מפניהם ויירשום וישבו תחתם כאמור במשנה תורה (דברים ב כא) ולכך יאמר שם (ב ה) כי ירושה לעשו נתתי את "הר" שעיר וטעם וילך אל ארץ אמר אונקלוס אל ארץ אחרת ורש"י פירש לגור באשר ימצא כי הלך אל ארץ אשר ימצא לו מקום לחנותו עד שבא אל הר שעיר וישב שם והנכון בעיני שיאמר וילך אל ארץ שעיר וחסרו הכינוי בעבור היותו מובן שכבר הזכיר (לעיל לב ד) שהיה עומד בארץ שעיר והידוע כי לשם יוליך ביתו ויזכיר בסמוך (פסוק ח) וישב עשו בהר שעיר ונמצא כזה (מלכים א טז יח) ויבא אל ארמון בית המלך וישרף עליו את בית מלך ושיעורו בית המלך הזה שהיה בו וכן וישרף את הבמה הדק לעפר ושרף אשרה (מלכים ב כג טו) כלומר אשר לירבעם הנזכרת במקום ההוא וכן ויאמר יואב לכושי לך הגד למלך וישתחו כושי ליואב ( יח כא) וחמור והאריה (מלכים א יג כח) וכן כי נשברו אניות בעציון גבר (שם כב מט) האניות וכן רבים אף כאן וילך אל ארץ כמו אל הארץ ארץ שעיר הנזכרת
@1048 **ולא יכלה ארץ מגוריהם** . טעמו עיר מגוריהם היא חברון אשר גר שם אברהם ויצחק כי ארץ כנען תשא כזה וכזה אלף פעמים אבל עשו בראותו כי לא יוכל לעמוד בעירו ובמקומו עזב את כל הארץ לאחיו והלך לו
@1050 **ואלה תולדות עשו אבי אדום** . בא להזכיר התולדות אשר הולידו בניו אחרי שהלכו עמו לשעיר כי הוא לא הוליד שם והנה החל ממנו לומר הוא הוליד את אליפז ורעואל והם הולידו בארץ שעיר תולדות הללו ויזכיר עמהם בני אהליבמה הנולדים בארץ כנען אף על פי שלא הזכיר להם תולדות בארץ שעיר כדי שימנו עם אחיהם בני עשו הנזכרים בתחילת הפרשה ועוד בעבור היותם בשעיר אלופים כי כל אלופיהם יזכיר
@1053 **ותמנע היתה פילגש** . מפני שלא הקפיד בכל האחרים להודיע שם האם דרשו רבותינו (ב"ר פב יד) כי זה להודיע גדולתו של אברהם אבינו כמה היו תאבים להדבק בזרעו שהרי תמנע זו בת אלופים היתה שנאמר ואחות לוטן תמנע אמרה איני זוכה להנשא לך הלואי ואהיה פילגש כמו שכתב רש"י ויתכן כי בני אליפז החמשה היו ידועים לו כי הולידם מנשיו ועמלק בעבור היותו בן פלגש לא היה לו שם באחיו והיה נכלל עם בני עשו בעבור היותו מזרעו והוצרך הכתוב לומר כי אמו פלונית אשר הוא נודע לה ילדתו לאליפז אבל איננו בכלל בני עשו ולא יושב עמהם בהר שעיר כי בבני הגבירות יקרא לו זרע ולא בבן הפילגש כי לא יירש בן אמה עם בניו כמו שעשה אביו והנה אנחנו נצטוינו בבני עשו שלא נתעב אותם (דברים כג ח) ולא נקח את ארצם (שם ב ה) והם כל בניו הידועים לו היושבים בשעיר כי הם הנקראים אדום על שמו אבל בן הפילגש אינו בכלל בני עשו ולא עמהם בארצם ונצטוינו בו בהפך לתעב אותו ולמחות את שמו וכתב רש"י עוד ובדברי הימים (א א לו) מונה תמנע בבניו של אליפז מלמד שבא על אשתו של שעיר החורי ויצאה תמנע מביניהם וכשגדלה היתה פילגשו וזהו ואחות לוטן תמנע (להלן פסוק כב) ולא מנאה מבני שעיר שהיתה אחותו מן האם ולא מן האב ואין דעתי סובלת זה כי היה ראוי לומר בדברי הימים "ותמנע בתו" ולמה ימנה האשה בבנים אולי לא יקפיד הכתוב בכך בדבר הידוע כי מצינו שם בדברי הימים (א ה כט) ובני עמרם אהרן ומשה ומרים ובני אהרן נדב ואביהוא וגומר ואם כן ראוי שנאמר כי תמנע זאת היא בת אליפז אשר ילדה לו אשת שעיר החורי אחרי מות אישה והיתה אחות לוטן מן האם ונשאה אליפז לפילגש שהעכו"ם מותר בבתו או נאמר על דעת רבותינו כי תמנע הנזכר בדברי הימים הוא תמנע האלוף הנזכר למטה (בפסוק מ) שנמנה שם מבני אליפז כאשר נמנה קרח והוא בן אהליבמה כי שניהם היו ממזרים נולדו מאחד ונמנים עם בני האחר כי רחוק שימנה האשה בין הבנים בתוכם ועל דרך הפשט יש לחשוב בו כי תמנע פילגש אליפז אחרי לידתה את עמלק ילדה בן ותקש בלדתה ותמת ותקרא את שמו תמנע בעבור הזכיר שמה ואביו אליפז קרא לו קרח ולא הזכיר הכתוב הבן הזה לתמנע אמו כדי שלא יאריך כי הכונה היתה למנות עמלק בפני עצמו אבל בני אליפז שבעה היו ומנה הכתוב האלופים דרך מעלתם על כן הקדים קנז וקרח לגעתם ואני עוד סובר בכתוב הזה מה שאמרו רבותינו בשלשים ושתים מדות (מדה יא) שהאגדה נדרשת אמרו סדור היה ראוי להיות אלא שנחלק שנאמר (דהי"ב ל יח) כי מרבית העם וכו' וגם רודפי הפשט יאמרו כן בפסוקים אחרים וכן זה יאמר בני אליפז תימן אומר צפו וגעתם וקנז ותמנע וחזר ואמר היתה פילגש לאליפז בן עשו ותלד לאליפז את עמלק ולא הזכיר שם הפילגש והאמת שהיא אחות לוטן תמנע והיא הסבה שלא הזכיר שמה כי לא רצה לאמר שני פעמים ותמנע לזכר ולנקבה והנה בני אליפז שבעה והם האלופים הנזכרים לו אבל החליפו שם זה הקטן בעבור היות שמו כשם הפילגש שלא יחשב כבנה וקראוהו קרח בעלותו למעלת אלוף ורבי אברהם אמר כי קרח בן אהליבמה אשת עשו הוא נמנה פעמים כי הוא הקטן מבני אהליבמה וגדלתו עדה וכן בני מיכל בת שאול כדברי רבותינו (סנהדרין יט) ועל דעת הזו יהיה פירוש הכתוב בדברי הימים כי תמנע ילדה עמלק שיהיה שיעורו ולתמנע עמלק וחסרו הלמ"ד כדרך ושני שרי גדודים היו בן שאול ( ד ב) לבן שאול והנכון מה שחשבתי בו וטעם אלה בני עדה על הרוב כי עמלק איננו בנה וכן אלה בני יעקב אשר ילד לו בפדן ארם (לעיל לה כו) אינו על בנימין
@1061 **אלה בני שעיר החרי** . החרי שם איש היה אבי אומה קדמונית תקרא על שמו כמו האמורי והפריזי כמו שנאמר (דברים ב כב) אשר השמיד את החורי מפניהם ונקרא שעיר על שם הארץ שנקראת שעיר והשם הזה היה לארץ מן עשו שהוא איש שעיר מיום שהלך שם ואילך וכן שם אדום ממנו היה אבל הכתוב הפריש ביניהם כי אלה הם בני שעיר החורי שהיו יושבי הארץ למבראשונה לא בני שעיר האדומי אשר בא שם ועוד אפרש יחוס החורי במשנה תורה (דברים ב י) בעזרת השם וכתב רבי אברהם הזכיר הכתוב זה להפריש יחוסי שעיר ועשו כי ישראל יצוו על בני עשו ורש"י כתב (בפסוק כד) לא הוזקק לכתוב משפחות החורי אלא מפני תמנע להודיע גדולת אברהם
@1063 **ואחות לוטן תמנע** . כמו ואחות תובל קין נעמה (לעיל ד כב) ואחיותיהם צרויה ואביגיל (דהי"א ב טז) ותמר אחותם (שם ג ט) וסרח אחותם (להלן מו יז) כי המנהג ליחס הבת אל האחים והיה ראוי שתמנה למעלה עם בני שעיר ודישון ואצר ודישן ותמנע אחותם אבל היתה אחות לוטן בת אביו ובת אמו לא אחות שאר האחים ולכן רצה ליחס אותה אליו או שהיתה אחותו מן האם ולא מן האב ואיננה בת שעיר החורי
@1065 **ואלה בני צבעון ואיה וענה** . הוי"ו יתירה וכן עבד אביך ואני מאז ועתה ואני עבדך ( טו לד) דין שניהם אני ואלה ראשי בית אבותם ועפר וישעי (דהי"א ה כד) וכמוהם רבים והנה צבעון זה הוא הבן השלישי לשעיר החורי והוליד שני בנים אלו איה וענה וסיפר הכתוב כי ענה זה בן צבעון הוא אותו ענה שמצא הימים במדבר ברעותו החמורים של צבעון אביו להבדיל בינו ובין ענה דודו אחי צבעון אביו וזה ענה בן צבעון הוא חמיו של עשו
@1065 "אשר מצא את הימים" - כדעת מקצת רבותינו בתלמוד (פסחים נד) הם הפרדים וזה האיש מצא כי יולידו מין שלא במינו ואין כן בשאר מיני הכלאים ואמר במדבר ברעותו החמורים כי היו לו שם במדבר חמורים רבים תובעים אתונות והרביעם עם הסוסיות והולידו ונראה שנחשב לו בדורו לחכמה כי הכיר במיניהם שהם קרובים בטבע ויולידו והיה נודע במעשה ההוא ועל כן יתארהו בו ואונקלוס תרגם גבריא והנראה מסברתו כי ענה זה באו עליו מן האומה הנקראת אימים לפנים עם גדול ורם כענקים (דברים ב י) ורצו לגזול ממנו החמורים של צבעון אביו והוא היה במדבר ואין עוזר לו ותמצא ידו להם והציל מידם והוא מלשון תמצא ידך לכל אויביך (תהלים כא ט) ולא המציתך ביד (שאול) דוד ( ג ח) או יאמר שמצא אותם ונצל והיה נודע בגבורה הזאת ונכון הוא
@1066 **ואלה בני ענה דישון ואהליבמה בת ענה** . דרך הכתוב לאמר בבנות כן כמו ואת דינה בתו (להלן מו טו) וזה ענה הוא הבן הרביעי לשעיר החורי אחי צבעון הנמנה אחריו למעלה (בפסוק כ) כי הפרשה תמנה שבעה בני שעיר החורי כתולדותם והיה לזה ענה בן אחד יקרא גם כן דישון כשם דודו ולו בת תקרא אהליבמה כשם קרובתה בת ענה בן צבעון ולכך יאמר הכתוב באשת עשו (לעיל פסוק ב) אהליבמה בת ענה בת צבעון להגיד כי היא בת ענה שמצא הימים נכדת צבעון לא אהליבמה בת ענה בן שעיר החורי אחי צבעון ועל דעת קצת רבותינו (פסחים נד) אין בפרשה רק איש אחד הנקרא ענה והוא בן צבעון שבא בזנות על אמו אשת שעיר החורי וימנה אותו הכתוב (בפסוק כ) בבני שעיר החורי כי יחשבוהו האנשים כבנו ויקראוהו ענה בן שעיר וגדלו בין בניו בחשבו שהוא בנו וימנה אותו הכתוב פעם אחרת (בפסוק כד) על פי האמת בן לצבעון וזה מדרשם של דורשי חומרות כמו שמוזכר במסכת פסחים (שם) ואיננו דברי הכל בגמרא ולא משמעו של מקרא כלל
@1067 **ואלה בני דישן חמדן ואשבן** . הוא דישון הבן החמישי לשעיר כי אין קפידא שיקראנו דישן או דישון רק כשהם בפסוק אחד להבדיל בין שניהם וכן ויעש חירום את הכיורות ויכל חירם (מלכים א ז מ) והוצרך הכתוב בכאן לקראו דישן שלא יחשב שהוא דישון בן ענה הנזכר בסמוך ליחס לו תולדות כי כן יהיה במשמע
@1072 **ואלה המלכים אשר מלכו בארץ אדום** . נכתב זה להגיד כי נתקימה בו ברכת יצחק שאמר לו ועל חרבך תחיה (לעיל כז מ) כי גברו על בני שעיר החורי ומלכו עליהם בארצם ואלה הערים מדינות בארץ אדום כי בצרה לאדום היא כמו שכתוב (ישעיהו לד ו) כי זבח לה' בבצרה וטבח גדול בארץ אדום וכן ארץ התימני מאדום כמו שנאמר בו (עובדיה א ט) וחתו גבוריך תימן למען יכרת איש מהר עשו וכולם כך המה אבל ספר הכתוב כי לא היו מלך בן מלך כאשר היו בישראל
@1072 "ולפני מלך מלך" - ימים רבים קודם ואין טעם "לפני מלך מלך" שנמשכה מלכות אלה עד מלכות ישראל (ראה רש"י ורד"ק) אבל לאמר כי אז לא תהיה להם מלכות לקיים "ואת אחיך תעבוד" (לעיל כז מ) ויתכן שאלו כולם בימי משה כבר עברו כי היו זקנים בעת שהמליכו אותם ולא האריכו ימים
@1076 **וטעם המכה את מדין בשדה מואב** . להגיד גבורתו שבאו המדינים בשדה מואב להשגב עמם ונצח את כלם
@1079 **ובעל חנן בן עכבור** . היה ממקום שאול על כן לא הזכיר לו עיר אחרת ויתכן שהיה חנן מקום והוא בעל עליו ואחרי כן מלך
@1081 **ואלה שמות אלופי עשו** . מתחלה (פסוקים טו-יט) מנה בני בניו שהיו אלופים בדור ההוא ואחר כן הצליחו מזרעו למלוכה ואחרי כן פסקה מלכותם וחזרו ונתנו את אלו אלופים לראש וכך נאמר בדברי הימים (א א נא) וימת הדד ויהיו אלופי אדום אלוף תמנע כך פירש רש"י ומה שאמר למשפחותם למקומותם בשמותם למושבותם בארץ אחוזתם (פסוק מג) כי הראשונים היו כל האחים אלופים יושבים כלם בעיר אחת מושלים בעם כאחד או כענין נשיאי שבט וראשי בתי אבות אבל אלו אחרונים היו אלופים למשפחותם כי כל אחד היה אלוף לכל משפחות בני עשו ובכל מקומות מושבותם והוא לבדו נקרא בדור אלוף אין אחר נקרא כן בכל ארץ אחוזתם כי היו כמלכים לארצם אבל לא ישבו לכסא להם ולא נתנו עליהם הוד מלכות ונכתבה הפרשה בדרך הנבואה לדעת רבים (רש"י וראב"ע והרד"ק) ואיננו נכון כי הנבואה למה תזכיר את אלה ועד איזה זמן תמנה ותפסיק בהם אבל הנכון שכל אלה לפני התורה ונאמר שמשלו כאחד ויהיה פירוש למקומותם שמשל כל אחד במקומו או שהיה ממשלתם זמן מועט ושנות רשעים תקצורנה (משלי י כז)
@1084 **מגדיאל** . זו רומי לשון רש"י ולא הבינותי זה כי אם נאמר שיהיה נבואה לימים רבים ולעתים רחוקות הנה מלכים רבים מלכו לאדום על מלכות רומי ואין רומי אלוף אבל היא מלכות גדולה ואמתני ותקיפא יתירה לא היה כמוה בממלכות אבל מה שאמרו בפרקי רבי אליעזר (לח) בשכר שפינה את כליו מפני יעקב אחיו נתן לו מאה מדינות משעיר ועד מגדיאל ומגדיאל זו רומי שנאמר אלוף מגדיאל אלוף עירם כוונתם בזה מה שהודעתיך כמה פעמים כי היו המקרים בראשונים רמז לזרעם והנה אלה האלופים האחרונים עשרה עם מגדיאל רמז שיהיו מלכי אדום בממשלתם במלכות הרביעית עשרה ימלכו על ארץ אדום והעשירי מהם ימלוך על רומי ומשם תתפשט אחרי כן מלכותם על כל העולם ולזה ירמוז שם מגדיאל שיתגדל על כל אל כמו שאמר בו (דניאל יא לו) ועשה כרצונו המלך ויתרומם ויתגדל על כל אל וזהו שנאמר (שם ז כד) וקרניא עשר מינה מלכותא עשרה מלכין יקומון ואחרן יקום אחריהון והוא ישנא מן קדמיא ואמרו בבראשית רבה (עו ו) כלם ביוצאי ירכו של עשו הכתוב מדבר ודרשו (שם פג ד) אלוף עירם שהוא עתיד לערום תיסוריות למלך המשיח במהרה יגלה חסלת פרשת וישלח
@1085 **וישב יעקב בארץ מגורי אביו** . כי אמר שאלופי עשו ישבו בארץ אחוזתם כלומר הארץ שלקחו להם לאחוזת עולם אבל יעקב ישב גר כאביו בארץ לא להם אלא לכנען והכונה להגיד כי הם בוחרים לגור בארץ הנבחרת ושנתקיים בהם כי גר יהיה זרעך בארץ לא להם (לעיל טו יג) ולא בעשו כי ביעקב לבדו יקרא להם זרע
@1086 **אלה תולדות יעקב** . ואלה של תולדות יעקב אלה ישוביהן וגלגוליהן עד שבאו לכלל ישוב סיבה ראשונה יוסף בן שבע עשרה שנה על ידי זה נתגלגלו וירדו זהו ישוב פשוטו של מקרא להיות דבר דבור על אופניו לשון רש"י ואין לשון "לתולדות" שיהיה על הישוב ורבי אברהם אמר אלה המאורעות שאירעו לו והקורות שבאו עליו כטעם מה ילד יום ואין אדם מוליד קורותיו רק לימים מיוחסים שיולידום ואולי יאמר אלה תולדות הימים של יעקב והנכון בעיני כי אלה תולדות יעקב יוסף ואחיו אשר יזכיר ואחז הכתוב דרך קצרה בשמותם שכבר הזכירם למעלה אבל אמר אלה תולדות יעקב יוסף ואחיו אשר אירע להם ככה ואפשר גם כן שירמוז "אלה" את כל הנזכרים בספר הזה שבעים נפש ירדו אבותיך מצרימה כי כאשר הזכיר ב"אלה תולדות עשו" בנים ובני בנים מלכים ואלופים כל אשר היו בהם עד זמן התורה כן ימנה בתולדות יעקב בניו ובני בניו וכל זרעו רק יזכיר בהם הפרטים בתולדותם
@1086 "והוא נער את בני בלהה" - שהיה עושה מעשה נערות ממשמש בעיניו ומתקן בשערו את בני בלהה כלומר ורגיל את בני בלהה לפי שהיו אחיו מבזין אותן והוא מקרבן את דבתם רעה כל רעה שהיה רואה באחיו בני לאה היה מגיד לאביו לשון רש"י ואם כן למה לא הצילוהו בני השפחות והוא אוהב אותם ומקרבן ומגיד לאביו על האחים בבזיונם ואם נאמר שייראו מן האחים והנה הם ד' וראובן עמהם ויוסף עצמו ותגבר ידם עליהם ואף כי לא יבאו עמהם במלחמה ועוד כי נראה בכתוב כי כולם הסכימו במכירתו אבל לדעת רבותינו בבראשית רבה (פד ז) על כולם היה מוציא הדבה והנכון בעיני כי זה הכתוב שב לבאר מה שהזכיר ושיעורו יוסף והוא נער בן שבע עשרה שנה היה רועה בצאן את אחיו את בני בלהה ואת בני זלפה נשי אביו ודומה לו בסדר הזה (להלן מ ה) ויחלמו חלום שניהם איש חלומו בלילה אחד איש כפתרון חלומו המשקה והאופה אשר למלך מצרים אשר אסורים בבית הסוהר שב לפרש מלת "שניהם" אשר הזכיר ושיעורו ויחלמו חלום שניהם המשקה והאופה אשר למלך מצרים אשר אסורים בבית הסוהר איש כפתרון חלומו וכן רבים או שיהיה "והוא" מושך אחר עמו ומשפטו והוא נער והוא את בני בלהה ואת בני זלפה נשי אביו יאמר כי הוא נער והוא עם בני בלהה ועם בני זלפה נשי אביו תמיד לא יפרד מהם בעבור נערותו כי להם צוה אביהם שישמרוהו וישרתוהו לא לבני הגבירות והוא מביא מהם דבה רעה אל אביהם ולכן ישנאוהו אלה הארבעה האחים ואחר כן אמר כי אביו אהבו ויראו אחיו האחרים כי אותו אהב אביהם יותר מכולם ויקנאו בו וישנאוהו נמצא שנוא מכולם בני הגבירות יקנאו בו למה יאהב אותו מהם והם בני גבירה כמוהו ובני השפחות אשר לא יקנאו בזה למעלתו עליהם ישנאו בו בעבור היותו מביא דבתם אל אביהם וטעם דבתם רעה להפליג כי כל דבה רעה היא ועל דעת רש"י (במדבר יד לו) יתכן שתהיה דבה טובה ו"מביא דבה" הוא אשר יראה יגיד אבל "מוציא דבה" הוא כסיל האומר שקר ועל דרך הפשט איננו קשה שיקראנו נער והוא בן שבע עשרה שנה כי בעבור היותו קטן מכולם יקראנו כן לומר כי לא היה מתחזק כאחיו ויצטרך להיותו עם בני בלהה וזלפה מפני נערותו וכתיב ברחבעם בן שלמה (דהי"ב יג ז) ורחבעם היה נער ורך לבב ולא התחזק לפניהם והוא בן ארבעים ואחת שנה במלכו וכן השלום לנער לאבשלום ( יח לב) ובנימן ברדתו למצרים גדול ממנו ויקראנו נער פעמים רבים ואונקלוס תרגם והוא נער והוא מרבי עם בני בלהה יאמר כי מיום היותו נער הוא עמהם הם גדלוהו כאב והם ישרתוהו גם נכון הוא ועל הדרך שפירשתי כי הכתוב יספר כי מאלה יביא הדבה ולבני הגבירות בקנאתם וטעם נשי אביו כי נשיו היו שלקחם לנשים ולא יקרא אותם הכתוב שפחות רק בהיותם עם רחל ולאה שהן גבירות להן וכן וישם את השפחות ואת ילדיהן (לעיל לג ב) לומר כי בעבור היותן שפחות לרחל וללאה שם אותן לפניהן וכן וישכב את בלהה פלגש אביו (לעיל לה כב) שאילו היתה גברת לא יעשה כן ויתכן כי בחיי רחל ולאה יקרא אותן שפחות ופילגשים ועתה מתו ולקחן לנשים
@1087 **כי בן זקונים הוא לו** . שנולד לו בעת זקנתו ואונקלוס תרגם ארי בר חכים הוא ליה שכל מה שלמד משם ועבר מסר לו דבר אחר שהיה זיו איקונין שלו דומה לו לשון רש"י וכן אמר רבי אברהם כי בן זקונים שהולידו לזקוניו והוא בן תשעים ואחת שנה וגם אחיו בנימין קראו ילד זקונים קטן ואיננו נכון בעיני כי הכתוב אמר שאהב את יוסף מכל בניו בעבור שהוא בן זקונים וגם כל בניו נולדו לו בזקוניו והנה יששכר וזבולון אינם גדולים מיוסף רק כשנה או שנתים והנראה בעיני כי מנהג הזקנים שיקחו אחד מבניהם הקטנים להיות עמו לשרתו והוא נשען על ידו תמיד לא יפרד ממנו והוא נקרא לו בן זקוניו בעבור שישרתו לזקוניו והנה לקח יעקב את יוסף לדבר הזה והיה עמו תמיד ועל כן לא ילך עם הצאן ברעותם במקום רחוק ואונקלוס שאמר "בר חכים" ירצה לומר שהיה בן דעת וחכם בעיני אביו וטעמו כטעם זקנים ותרגם בילד זקונים בר סבתין כי לא אמר הכתוב בכאן "כי בן זקונים היה" אבל אמר "הוא לו" שהיה כן בעיניו וזאת כונתם באמרם (ב"ר פד ח) כל מה שלמד משם ועבר מסר לו לומר שמסר לו חכמות וסתרי תורה ומצאו משכיל ובעל סוד בהם כאלו היה זקן ורב ימים
@1091 **קמה אלומתי וגם נצבה והנה תסובינה אלומותיכם** . ענין החלום באלומות כי הראוהו שעל ידי אלומות ותבואה ישתחוו לו וענין תסובינה כי יקיפו אותו כמלך עתיד לכידור אשר עבדיו יחנו סביב לו
@1092 **המלוך תמלוך עלינו אם משול תמשול בנו** . פירש רבי אברהם אנחנו נשימך מלך עלינו או אתה תמשול בנו בחזקה ויותר נכון דעת אונקלוס התהיה מלך עלינו או שלטון מושל בנו כי לשניהם אדם משתחוה לא תהיה עלינו לעולם לא מלך ולא מושל וטעם על חלומותיו ועל דבריו שהיו שונאים אותו על החלומות וגם על הסיפור שהוא מספר אותו להם כמתהלל כמו שאמר שמעו נא החלום הזה אשר חלמתי
@1094 **ויספר אל אביו** . סיפר החלום הזה לאביו ולא הראשון כי הוא עצמו המכיר בפתרונו כי השמש ירמוז לאביו והוא גער בו וטעם ואל אחיו פעם שנית כי יספר אותו לאביו בפני אחיו והוא גער אותו לשכך חמתם מעליו וטעם מה החלום הזה אשר חלמת כמו מה אדם ותדעהו (תהלים קמד ג) כלומר מה החלום הזה אינו כלום שתגידנו כי אינם אלא דברים בטלים או טעם הגערה לומר איך נשאך לבך לחלום החלום הזה אין זה כי אם גובה לב ונערות שיעלו דברים כאלו על לבבך כענין שנאמר בחלומות (דניאל ב כט) רעיונך על משכבך סליקו וכתוב (שם ד ב) והרהורין על משכבי
@1094 "הבוא נבוא אני ואמך" - והלא אמך כבר מתה והוא לא היה יודע שהדברים מגיעים לבלהה שגדלתו כאמו ורבותינו (ברכות נה) למדו מכאן שאין חלום בלא דברים בטלים ויעקב נתכוון להוציא הדבר מלב בניו שלא יקנאוהו בכך אמר לו כשם שאי אפשר באמך כך הכל בטל לשון רש"י ולפי דעתי כי בעת שירד יעקב למצרים כבר מתה בלהה גם זלפה כי הכתוב אמר בספור שבעים נפש (להלן מו כו) מלבד נשי בני יעקב ולא הזכיר "מלבד נשיו ונשי בניו" ואם תאמר כי בעבור היותם פילגשים לא רצה לומר "לבד מנשי בני יעקב ופילגשיו" הנה כתוב נשי אביו ורחוק הוא שיהיה הירח רמז לפילגשו אבל ענין החלום כי השמש רמז ליעקב והירח רמז לבני ביתו וכל נשיו שבהן היו תולדותיו וירמוז כי כל תולדותיו ישתחוו לו והם כל שבעים נפש יוצאי ירכו כי כולם השתחוו בבואם אליו ואחד עשר כוכבים אלו אחיו אשר השתחוו לו בפני עצמן טרם בא אביהם כדכתיב (להלן מג כו) ויבא יוסף הביתה ויביאו לו את המנחה אשר בידם הביתה וישתחוו לו אפים ארצה
@1098 **וישלחהו מעמק חברון** . יזכיר הכתוב המקום אשר שלחו משם לומר כי היה מרחק רב ביניהם ולכן עשו עמו רעה כי רחוקים היו מאביהם ולהגיד כי יוסף לכבוד אביו נתאמץ ללכת אחריהם אל מקום רחוק ולא אמר איך אלך והם שונאים אותי ולרבותינו עוד בזה מדרש (ב"ר פד יג) להשלים עצה עמוקה של חבר הנאה הקבור בחברון
@1099 **וימצאהו איש והנה תעה בשדה** . יאמר כי הוא תועה מן הדרך ולא היה יודע אנה ילך ונכנס בשדה כי במקום המרעה היה מבקש אותם ויאריך הכתוב בזה להגיד כי סיבות רבות באו אליו שהיה ראוי לחזור לו אבל הכל סבל לכבוד אביו ולהודיענו עוד כי הגזרה אמת והחריצות שקר כי זמן לו הקב"ה מורה דרך שלא מדעתו להביאו בידם ולזה נתכוונו רבותינו (ב"ר פד יד) באמרם כי האישים האלה הם מלאכים שלא על חנם היה כל הסיפור הזה להודיענו כי עצת ה' היא תקום
@1101 **נסעו מזה** . הסיעו עצמן מן האחוה נלכה דותינה לבקש לך נכלי דתות שימיתוך בהם ולפי פשוטו שם מקום הוא ואין מקרא יוצא מידי פשוטו לשון ר' שלמה ואין הכונה לרבותינו שיפרש לו האיש נסעו מזה מן האחוה והלכו לעורר עליך דינין ותרעומות שאם כן היה נמנע ללכת ולא היה מסכן בעצמו אבל הכונה להם כי האיש גבריאל אשר הגיד לו הגיד אמת ואמר לשון משמש לשני פנים ושניהם אמת והוא לא הבין הנסתר בו והלך אחר הנגלה ממנו וילך אחר אחיו וימצאם בדותן כאשר אמר לו ודרשו זה מפני שהאיש הזה הוא מלאך ואם כן יודע הוא אנה הם ולמה לא אמר הנם בדותן ואמר כמסתפק ששמע מהם שילכו שם ואינו יודע אנה הם עתה ולכן יעשו מדרש במאמרו
@1101 "כי שמעתי אומרים" - שמעתי אותם שהיו אומרים נלכה דותינה וכן רבקה שומעת (לעיל כז ה) היתה שומעת ויתכן שיאמר נסעו הרועים מזה כי שמעתי אנשים אומרים נלכה דותינה אולי הם אחיך דיבר עמו כמסתיר פנים מן הענין
@1102 **ויתנכלו אותו להמיתו** . היו חושבים להמית אותו בנכליהם אשר יתנכלו בטרם יקרב אליהם ולא יצטרכו לשפוך דמו בידיהם וכך אמרו בבראשית רבה (פד יד) נשסה בו את הכלבים ואולי עשו כן ולא עלתה בידם וכאשר ראו כי קרב אליהם ולא יכלו להמיתו בנכליהם אמרו איש אל אחיו הנה בא אלינו ועתה נהרגהו אנחנו
@1104 **ונראה מה יהיו חלמתיו** . מליצה דרך לעג נראה אחרי מותו אם נשתחוה לו והנכון בעיני כי אמרו עתה נראה מה יהיו חלומותיו כי אם יצילוהו מידינו מלוך ימלוך עלינו אבל רבותינו אמרו (שם) רוח הקדש אומרת נראה מה יהיו חלומותיו כלומר דבר מי יקום ממני ומהם
@1106 **אל תשפכו דם** . אמר להם הנה הייתי סובל לכם כאשר חשבתם להמית אותו בנכליכם כי גם אני שנאתיו ורציתי שיומת על ידי אחרים אבל אתם אל תהיו שופכים דם בידיכם חלילה לכם והכונה לראובן בכל זה היתה להצילו להשיבו אל אביו והכתוב סיפר מה שאמר להם ראובן ושמעו אליו אבל דברים אחרים אמר להם מתחילה שלא קבלו ממנו כמו שאמר להם (להלן מב כב) הלא דברתי אליכם לאמר אל תחטאו בילד ולא שמעתם וכאשר ראה שלא שמעו לעזבו אמר להם אם כן אל תשפכו דם בידיכם ולא אמר "דמו" כי הראה עצמו שלא יאמר כן לאהבתו רק שלא יהיו שופכים דם לימד אותם שאין עונש הגורם כעונש השופך דם בידיו וטעם אל הבור הזה אשר במדבר לאמר הנה הבור הזה עמוק ולא יוכל לצאת הימנו והוא במדבר ואם יצעק אין מושיע לו כי אין עובר עליו וסיפר הכתוב כי היה ריק ואין בו מים שאם היה בו מים לא יטביעו אותו שכבר נמנעו משפוך דמו וכתב רש"י ממשמע שנאמר והבור ריק אינני יודע שאין בו מים מה תלמוד לומר אין בו מים מים אין בו אבל נחשים ועקרבים יש בו לשון רש"י מדברי רבותינו (שבת כב) ואם כן היו נחשים ועקרבים בחורי הבור או שהיה עמוק ולא ידעו בהם שאילו היו רואים אותם ולא יזיקו ליוסף היה הדבר ברור להם שנעשה לו נס גדול ושהוא צדיק גמור וידעו כי זכותו תצילנו מכל רע ואיך יגעו במשיח השם אשר הוא חפץ בו ומצילו וכענין שנאמר (דניאל ו כג) אלהי שלח מלאכה וסגר פום אריותא ולא חבלוני כל קבל די קדמוהי זכו השתכחת לי אבל הם לא ידעו בדבר ועל דרך הפשט יאמר והבור ריק אין בו מים כלל שגם אם היו בו מים מעט יקרא רק וכן כי מת אתה ולא תחיה (מלכים ב כ א) כלל בשום פנים והכל ביאור וחיזוק
@1109 **והנה ארחת ישמעאלים באה מגלעד** . כאשר נשאו עיניהם וראו מרחוק אנשים באים מדרך גלעד הכירו כי ארחת ישמעאלים היא בגמלים וידעו כי למצרים ילכו כי מגלעד יובא הצרי והנכאת ולמצרים היה דרכם להוליך אותו ולכן אמר להם יהודה הנה האנשים האלה מארץ מרחק והולכים אל ארץ רחוקה נמכרנו להם כי לא יודע הדבר וכאשר קרבו להם מצאו כי היו בעלי סחורה אשר להם הנכאת והצרי אנשים מדינים סוחרים ששכרו הגמלים מהישמעאלים וימכרו את יוסף למדינים שקנו אותו לסחור בו לסחורה כי ארחת הישמעאלים משכירי הגמלים לא יקנו הם סחורה לעצמם ואמר (בפסוק כח) וימכרו את יוסף לישמעאלים כי להם מסרו אותו שהם מוליכים הסחורה למצרים וזה טעם מיד הישמעאלים אשר הורידוהו שמה (להלן לט א) כי היה בידם אבל המדינים היו בעליו והם סחרו בו והוא שאמר והמדנים מכרו אותו אל מצרים וכל מעשה בכתוב פעם יספר אותו במושל המצוה בו ופעם בשליח שיעשנו בידו כענין שנאמר (דברים יא ז) את כל מעשה ה' הגדול אשר עשה וכתוב אחר (שם לד יב) אשר עשה משה לעיני כל ישראל וכן אמר (מלכים א ז נא) ותשלם כל המלאכה אשר עשה המלך שלמה וחירם עשאה כדכתיב (שם ז יד) ויבא אל המלך שלמה ויעש את כל מלאכתו וביוסף עצמו אמר (להלן לט כב) את כל אשר עושים שם הוא היה עושה נותן המעשה למצוה בו ולעושה אותו ורבי אברהם אמר (בפסוק כח) כי המדינים יקראו ישמעאלים כאשר אמר הכתוב על מלכי מדין כי ישמעאלים הם (שופטים ח כד) ואיננו כאשר חשב כי הכתוב שאמר (שם) כי נזמי זהב להם כי ישמעאלים הם ירמוז על בני קדם שהמלחמה ההיא להם היתה דכתיב (שם ו לג) וכל מדין ועמלק ובני קדם נאספו יחדיו ובני קדם הם ישמעאלים כי על כל בני הפילגשים אשר לאברהם אמר (לעיל כה ו) וישלחם מעל יצחק בנו בעודנו חי קדמה אל ארץ קדם גם יתכן שהיו המלכים ישמעאלים והם מלכו על מדין כי למה יקראו מדין על שם ישמעאל אחיהם והנכון בפשט הכתוב ביוסף מה שאמרנו בו אבל רבותינו אמרו (ב"ר פד כ) שנמכר פעמים רבות
@1110 **וכסינו את דמו** . ונעלים את מיתתו לשון רש"י וכן אמר אונקלוס ונכסי על דמיה והנכון שהוא כפשוטו כי מנהג רוצחי מסתרים להרוג הנרצח ולקברו ולכסות דמו בעפר כענין שנאמר (שמות ב יב) ויטמנהו בחול ולכך אמר להם הנה אנחנו הורגים את אחינו ומכסים את דמו בעפר כי כן יחשב לנו והנה ראובן למד להם שלא ישפכו דם בידם אבל ישליכוהו בבור וימות שם שאין עונש הגורם כעונש השופך דם ובא יהודה עתה ואמר גם זה יחשב לנו לרציחה כאלו אנחנו הרגנוהו וכן הדבר באמת וכענין שאמר הכתוב ( יב ט) ואותו הרגת בחרב בני עמון ודינא רבא ודינא זוטא איכא ביניהו ושניהם אמרו אמת
@1116 **וישלחו את כתונת הפסים ויביאו אל אביהם** . בצווי או ויביאו השלוחים המביאים כי שלחו אותה ועודם בדותן ואמרו זאת מצאנו הכר נא או ששלחוה אל חברון לבית האחד מהן ובבואם הכניסוה לפני אביהם ואמרו לו זאת מצאנו וכל זה להתנכר בענין כי אם שתקו היה חושד אותם לאמר אתם הרגתם אותו כי ידע קנאתם בו ויש מפרשים וישלחו שתקעו בה השלח לקרעה במקומות רבים כדמות שני חיות מלשון בשלח יעבורו (איוב לו יב) וטעם הפסים כי שלחו אותה שיכירנה בפסים אשר עשה לו
@1119 **וכל בנותיו** . בתו ובת בנו ויתכן שיכנס בכלל הזה גם כלותיו עמהן כי בכלל הבנות יקראו גם הכלות כן או כמאמר חכמים (ב"ר פד יט) אין אדם נמנע מלקרוא לכלותיו בנותיו וכן אמרה נעמי לכלותיה לכנה שובנה בנותי אל בנותי (רות א יא יג) לכי בתי (שם ב ב) ואיננו רק דרך חיבה בלבד כמו הלא שמעת בתי (שם ב ח)
@1120 **שר הטבחים** . שוחטי בהמות המלך לשון רש"י וכן וירם הטבח (שמואל א ט כד) לרקחות ולטבחות (שם ח יג) אבל יותר קרוב דעת אונקלוס בעבור היות בית הסהר בביתו ומצינו טביחה להריגת האנשים (ישעיהו יד כא) הכינו לבניו מטבח טבחת ולא חמלת (איכה ב כא) וראיה לדבר הכתוב בדניאל (ב יד) לאריוך רב טבחיא די מלכא די נפק לקטלא לחכימי בבל
@1122 **בת איש כנעני** . אמר אונקלוס תגרא כלומר איש סוחר שבא לגור בארץ בסחורתו ודעתו לומר כי בני יעקב ישתמרו מלישא כנעניות כאשר צוה אביהם יצחק גם אברהם וכן הזכירו בגמרא במסכת פסחים (נ) והיו נשיהם מצריות עמוניות מואביות ומיוחסי בני ישמעאל ובני קטורה ולכך יחד הכתוב על שאול בן שמעון (להלן מו י) "ושאול בן הכנענית" כי הוא לבדו בהם וגם שם דרשו (ב"ר פ יא) שהיא דינה שנבעלה לכנעני ורבותינו (שם פד יט) נחלקו בדבר אמרו רבי יהודה אומר תאומות נולדו עם השבטים ונשאום רבי נחמיה אומר כנעניות היו ויתכן שלא הקפיד רבי נחמיה בייחוסן שלא נתכוון אלא לומר שנשאו מנשי ארץ כנען אבל היו מן הגרים והתושבים הבאים מכל הארצות או עמוניות ומואביות ומיתר העמים כי לא נתכוון רק לחלוק על רבי יהודה שלא נשאו אחיותיהם שאחותו מן האם אסורה לבני נח (סנהדרין נח) ולדעת רבי יהודה יצטרכו בני לאה לשאת תאומות ששה האחרים והם ישאו שלהם או שלא יודה ר' נחמיה בתאומות כלל ולא היתה לו בת זולתי דינה כמשמעות הכתוב ועל דרך סברא איננו נכון שישאו כלם כנעניות שיהיה בנוחלי הארץ מזרע כנען העבד הארור כמו מזרעו של אברהם והכתוב צוה להחרימו ולא תהיה לו שארית ופליטה ועל כל פנים זה האיש תגר כי למה יצטרך הכתוב לאמר כי הוא כנעני ביחוסו וכל אנשי הארץ ההיא כנענים הם מן הפריזי ומן היבוסי ואחיהם כי לכנען יתיחסו כלם ועדולם בארץ כנען היא והראוי היה שיאמר ויקח שם יהודה אשה ושמה כך כאשר הזכיר שמות הנשים בתמר ונשי עשו וזולתן (לעיל ד יט יא כט כה א) אבל פירש בו שהוא תגר שאיננו מן הארץ שהיתה לחוי או לאמורי וזה טעם וירא שם יהודה בת איש כנעני כי בעבור אביה נשאה והכתוב שאמר בני יהודה ער ואונן ושלה שלשה נולדו לו מבת שוע הכנענית (דהי"א ב ג) בעבור היותה בת איש הכנעני תקרא כן כי האיש ההוא יקרא להם הסוחר כי הוא ידוע ומובהק בסחורתו אשר בעבורה גר שם ורבי אברהם אמר (להלן מו י) כי בעבור היות האשה הזאת כנענית ועבר על דעת אבותיו היו בניה רעים ומתו ולכן הזכירו הכתוב ושאול לבדו הזכיר שהיה בן הכנענית כי לא הוצרך להזכיר כן בשלה ואם כן יהיה טעם וירא שם יהודה כלומר שראה אותה וחשק בה כענין וירא אשה בתמנתה דשמשון (שופטים יד א) ובפרשת ויחי יעקב (להלן נ יג) כתב רש"י ז"ל וישאו אותו בניו ולא בני בניו שכך צום אל יטענו במטתי אחד מבניכם לפי שהם מבנות כנען (במדב"ר ב ח) ויהיה זה לפי ששאול בן שמעון ושלה בן יהודה היו מבנות כנען ולכן יוציא את כלם אבל בנסחאות שלנו בבראשית רבה מצינו בכלן אחד מבני בניכם שיש בהם מבנות כנען וכן תמר היתה בת אחת מן הגרים בארץ לא בת איש כנעני ביחוסו כי חלילה שיהיה אדוננו דוד ומשיח צדקנו שיגלה לנו במהרה מזרע כנען העבד המקולל ורבותינו אמרו (ב"ר פה י) בתמר שהיתה בתו של שם והוא כהן לאל עליון
@1123 **ויקרא את שמו ער** . יהודה קרא לבנו ער מלשון עוררה את גבורתך (תהלים פ ג) ואשתו קראה שם השני אונן ולא סיפר הכתוב למה ויתכן שתקש בלדתה כי דרך נשים לקרא שם בניהם על זה כאם יעבץ (דהי"א ד ט) שקראה שמו יעבץ לאמר כי ילדתי בעצב וגם כן עשתה עטרה אם אונם (שם ב כו) והוא מלשון ויהי העם כמתאוננים (במדבר יא א) מה יתאונן אדם חי (איכה ג לט) כמו בן אוני דרחל (לעיל לה יח) ויהודה לא הקפיד לשנות שמו כיעקב אביו ובבראשית רבה (פה ד) אמרו ער שהוער מן העולם ולא שהיתה זו כוונת יהודה אבל דרשו כי השמות יורו על העתיד
@1125 **ותקרא את שמו שלה והיה בכזיב בלדתה אותו** . כתב רש"י אומר אני על שפסקה מלדת נקרא כזיב לשון היה תהיה לי כמו אכזב (ירמיהו טו יח) שאם כן מה בא ללמדנו ולא ידעתי למה יקרא שם המקום על זה ואין במאורע ההוא כל חדש כי די לה שתלד שלשה בנים ובעת לדתה לא נודע אם פסקה או תוליד אחרי כן רק בעת מותה נודע הדבר ויש אומרים (הרד"ק ומהר"ם מרוטנברג) כי היה דרכם שיקרא האב שם הבכור ותקרא האם שם השני על כן הראשון ויקרא את שמו והשני ותקרא ואמר בשלישי ותקרא כי יהודה היה בכזיב בלדתה אותו ואיננו שם שיקרא לו שם ואין בזה טעם או ריח ודעת רבי אברהם שסיפר הכתוב אנה נולדו ואמר בלדתה אותו כאילו אמר בלדתה אותם כי במקום אחד נולדו כולם ועל דעתי שלה לשון דבר הפוסק והכוזב וכן לא תשלה אותי (מלכים ב ד כח) אמר בו התרגום לא תכדב פתגמך באמתך ואולי יתיחס ללשון שגגה שלו כי השוגג כוזב במחשבתו ואמר הכתוב כי קראתו שלה על שם המקום כי היה בכזיב בלדתה אותו כדרך והיה הנערה (לעיל כד יד) וזה מאמרם בבראשית רבה פסקת
@1127 **ויהי ער בכור יהודה רע בעיני ה'** . לא הזכיר הכתוב פשעו כאשר עשה באחיו אבל אמר כי בחטאו מת להודיע שלא היה זה בענש יהודה על מכירת יוסף כי ההצלה עמדה על המכירה ולא היה בבית האבות שכול זולתי זה שהיה רע בעיני השם כי זרע צדיקים יבורך ועל כן היה יעקב מתאבל על בנו ימים רבים וימאן להתנחם שהיה הדבר בעיניו עונש גדול לו מלבד אהבתו אותו
@1128 **ויבם אותה והקם זרע לאחיך** . הבן יקרא על שם המת לשון רש"י ואין זה אמת כי במצות התורה נאמר גם כן (דברים כה ו) יקום על שם אחיו המת ולא ימחה שמו מישראל ואין היבם מצווה לקרא לבנו כשם אחיו המת ואמר בבועז וגם את רות המואביה אשת מחלון קניתי לי לאשה להקים שם המת על נחלתו ולא יכרת שם המת מעם אחיו ומשער מקומו ותקראנה אותו עובד לא מחלון (רות ד י) ועוד שאמר וידע אונן כי לא לו יהיה הזרע ומה הרעה אשר תבא עליו עד כי השחית זרעו מפניה אם יקרא שם בנו כשם אחיו המת ורוב בני האדם מתאוים לעשות כן ולא אמר הכתוב "ויאמר אונן" אבל אמר וידע אונן כי לא לו יהיה הזרע כי ידיעה ברורה היתה לו בזה שלא יהיה לו הזרע אבל הענין סוד גדול מסודות התורה בתולדת האדם ונכר הוא לעיני רואים אשר נתן להם השם עינים לראות ואזנים לשמוע והיו החכמים הקדמונים קודם התורה יודעים כי יש תועלת גדולה ביבום האח והוא הראוי להיות קודם בו ואחריו הקרוב במשפחה כי כל שארו הקרוב אליו ממשפחתו אשר הוא יורש נחלה יגיע ממנו תועלת והיו נוהגים לישא אשת המת האח או האב או הקרוב מן המשפחה ולא ידענו אם היה המנהג קדמון לפני יהודה ובבראשית רבה (פה ה) אמרו כי יהודה התחיל במצות יבום תחלה כי כאשר קבל הסוד מאבותיו נזדרז להקים אותו וכאשר באתה התורה ואסרה אשת קצת הקרובים רצה הקב"ה להתיר איסור אשת האח מפני היבום ולא רצה שידחה מפניו איסור אשת אחי האב והבן וזולתם כי באח הורגל הדבר ותועלת קרובה ולא בהם כמו שהזכרתי והנה נחשב לאכזריות גדולה באח כאשר לא יחפוץ ליבם וקוראים אותו בית חלוץ הנעל (דברים כה י) כי עתה חלץ מהם וראוי הוא שתעשה המצוה זאת בחליצת הנעל וחכמי ישראל הקדמונים מדעתם הענין הנכבד הזה הנהיגו לפנים בישראל לעשות המעשה הזה בכל יורשי הנחלה באותם שלא יהיה בהם איסור השאר וקראו אותו גאולה וזהו ענין בועז וטעם נעמי והשכנות והמשכיל יבין
@1131 **וטעם שבי אלמנה בית אביך** . שתנהגי אלמנותיך שם עד יגדל שלה רמז לה התאבלי ולבשי בגדי אבל ואל תסוכי שמן כאשה חגורת שק על בעל נעוריה עד שיגדל שלה וייבם אותך כי כן המנהג במתיבמת כי היוצאת וחפצה להנשא לאיש זר לובשת בגדי אבל ימים מעט כפי המנהג ומתנחמת ולובשת שנים ותכס בצעיף ותתעלף עד שתנשא לאיש
@1131 "כי אמר" - כלומר היה דוחה אותה בקש שלא היה בדעתו להשיאה לו כי אמר פן ימות גם הוא כאחיו כי מוחזקת היא זו שימותו אנשיה לשון רש"י ולא ידעתי למה יתבייש יהודה המושל בדורו מן האשה הזאת ולא יאמר אליה לכי לשלום מביתי ולמה יטעה אותה והיא אסורה לשלה כמו שאמרו (יבמות סד) בנשואים בתרי זמני הויא חזקה ועוד כי בהיותו מקפיד על זנוניה לחייב אותה שריפה נראה שהיה חפץ בה להיותה בביתו ורחוק הוא שלא שמע יהודה כי בניו חטאו וישלחם ביד פשעם ואין לתמר בהם חטא והנכון בעיני שהיה שלה ראוי ליבם אבל לא רצה אביו שייבם אותה ועודנו נער פן יחטא בה כאחיו אשר מתו בנעוריהם כי נערים היו אין לאחד מהם שתים עשרה שנה וכאשר יגדל וישמע למוסר אביו אז יתננה לו לאשה וכאשר המתינה ימים רבים וראתה כי גדל שלה בעיניה והוא עודנו נער לאביו כי אין לו עשר שנים והיה ממתין לו עוד אז מהרה תמר ברוב תאותה להוליד מזרע הקדש ועשתה המעשה הזה
@1132 **ויעל על גוזזי צאנו** . היה עולה שם תמיד להתנחם שישים לבו בצאן וישכח רישו והוגד לתמר כי הוא עולה שם בכל יום תמיד וארבה לו באחד הימים או שהיה יהודה גדול בארץ והיו מתקבצים לו שם לעשות משתה בעת הגיזה כמשתה המלך והיו העניים הולכים שם והוגד לה טרם עלותו
@1135 **ויחשבה לזונה** . לפי שיושבת בפרשת דרכים כי כסתה פניה ולא יכול לראותה ומדרש רבותינו כי כסתה פניה כשהיתה בביתו היתה צנועה לפיכך לא חשדה לשון רש"י ופשוטו של הרב יתכן כי דרך הזונה לישב בפתח עינים כדכתיב (משלי ט יד טו) וישבה לפתח ביתה על כסא מרומי קרת לקרוא לעוברי דרך וגו' ואמר כי כסתה פניה ולא הכירה אבל מדרש רבותינו "שכסתה פניה בבית חמיה" לומר שהצניעה עצמה ממנו בביתו ולא ראה פניה מעולם ואיך יכירנה והנכון בעיני עוד לפי הפשט שיאמר שחשבה לזונה בעבור שתכסה הפנים כי אחרי כן אמר כי לא ידע כי כלתו היא והטעם כי דרך הזונה לשבת בפתח עינים מעולפת הצעיף מכסה קצת השער וקצת הפנים ומשקרת בעינים ושפתים ומגלה הגרון והצואר כי בעבור שתעיז פניה ותאמר לו ותחזק בו ונשקה לו תכסה קצת הפנים ועוד כי הקדשות היושבות על דרך בעבור שתזננה גם עם הקרובים יכסו פניהן וכן יעשו הקדשים גם היום בארצותם ובשובם לעיר לא נודעו ושנינו (כלים כד טז) שלש שבכות הן של ילדה טמאה מדרס ושל זקנה טמאה טמא מת ושל יוצאת חוץ טהורה מכלום "יוצאת חוץ" היא הזונה נפקת ברא ונותנת שבכה על קצת הראש לא שתשכב עליה ותהיה טמאה מדרס ולא לכסות בה ראשה ותטמא טמא מת אבל לקשוט קווצותיה ולהיותן מתחת השבכה נראין ואינן נראין ולכך טהורה מכלום
@1138 **חותמך ופתילך** . עזקתך ושושיפך טבעת שאתה חותם בה ושמלתך שאתה מתכסה בה לשון רש"י ואיננו נכון שיתן שמלתו וילך ערום ממנה ואיך תקרא השמלה פתיל ואיך יאמר הכתוב (בפסוק כה) "והפתילים" בלשון רבים ואם תאמר כי על שם פתילי הציצית תקרא השמלה פתיל חלילה שיקיים יהודה מצות ציצית ויזלזל בו לתת אותו בזמה ואולי היה בידו סודר קטן אשר יעטוף בו קצת הראש לפעמים ויקרא פתיל בעבור שהוא קצר כפתיל והוא תרגום שושיפא ולא תמצא לאונקלוס בכל שמלה שבתורה שיתרגם אותה שושיפא אבל לשון כסות ומלבוש תרגום בכלם מלבד ופרשו השמלה (דברים כב יז) שאומר בו ויפרשון שושיפא לפי שהוא הסודר הידוע בתלמוד (כתובות י) שיודעו בו הבתולים וכן תרגם יונתן בן עוזיאל (ישעיהו ג כב) המעטפות "שושיפא" שהם סודרים קטנים יעטפו בהם הראש ויפרשו אותם הנכבדים על המגבעות והפארים אשר על ראשם וזה המנהג עודנו היום בארצות המזרח ויתכן עוד כי היה ליהודה חותם כצורת אריה או צורה אחרת ידועה כמושלים והיו בידו פתילים שבהם כצורה ההיא לצייר בה והמטה היה בידו כמשפט שליט ונוגש כענין שכתוב (יחזקאל יט יד) מטה עוז שבט למשול וכתיב (להלן מט י) לא יסור שבט מיהודה ואלה נתן בידה
@1144 **ויאמר יהודה הוציאוה ותשרף** . אמר אפרים מקשאה תלמידו של רבי מאיר משום רבי מאיר תמר בתו של שם היתה שהוא כהן לפיכך דנוה בשריפה (ב"ר פה י) זה כתב רש"י ולא פירשו ואני לא ידעתי הדין הזה שבת כהן אינה חייבת שריפה אלא בזנות עם זיקת הבעל ארוסה או נשואה כמו שמפורש בגמרא בסנהדרין (נא) אבל בת כהן שומרת יבם שזינתה אינה במיתה כלל ובין בת ישראל ובין בת כהן אינה אלא בלאו גרידא ואם תאמר שהיה היבום נוהג בבני נח והיא להם בכלל אשת איש ואזהרה שלהם זו היא מיתתם (שם נח) והלא הם אומרים (ב"ר פה ה) שיהודה התחיל במצות יבום תחלה וכן בגמרא סנהדרין (נז) מוכיח שאין יבמה בבני נח חייבת כלל ונראה לי שהיה יהודה קצין שוטר ומושל בארץ והכלה אשר תזנה עליו איננה נדונת כמשפט שאר האנשים אך כמבזה את המלכות ועל כן כתוב ויאמר יהודה הוציאוה ותשרף כי באו לפניו לעשות בה ככל אשר יצוה והוא חייב אותה מיתה למעלת המלכות ושפט אותה כמחללת את אביה לכבוד כהונתו לא שיהיה דין הדיוטות כן ועל דרך הפשט יתכן שהיה משפטם כנהוג היום במקצת ארצות ספרד שהאשה אשר תזנה תחת אישה מוסרין אותה לבעלה והוא דן אותה למיתה או לחיים כרצונו והנה היתה מיועדת לשלה בנו והיא להם כאשת איש בנימוסיהם
@1146 **צדקה ממני** . צדקה בדבריה ממני היא מעוברת ורבותינו דרשו (סוטה י) שיצאה בת קול ואמרה ממני ומאתי יצאו הדברים לשון רש"י והנכון שהוא כמו צדיקים וטובים ממנו (מלכים א ב לב) ויאמר אל דוד צדיק אתה ממני כי אתה גמלתני הטובה ואני גמלתיך הרעה (שמואל א כד יז) צדקה במעשיה יותר ממני כי היא הצדקת ואני החוטא אליה שלא נתתיה לשלה בני והטעם כי שלה הוא היבם ואם לא יחפוץ לקחת את יבמתו אביו הוא הגואל אחריו כאשר פירשתי למעלה (בפסוק ח) בדין היבום
@1146 "ולא יסף עוד לדעתה" - אחרי שהקים זרע לבניו לא רצה להיות עמה עוד אף על פי שהיה ברצונו כי איננה אסורה עליו והיתה אשתו כמשפט היבמים וזה טעם האומר (סוטה י) לא פסק כתיב הכא ולא יסף וכתיב התם (דברים ה יט) קול גדול ולא יסף
@1149 **מה פרצת עליך פרץ** . חזקת עליך חוזק לשון רש"י וענין פרץ בכל מקום נתיצת הגדר ועברו מן פרוץ גדרו (ישעיהו ה ה) למה פרצת גדריה (תהלים פ יג) ובלשונם (סוכה כו) פרצה קוראה לגנב אבל יאמר בלשון הקדש על כל עובר גבול הדבר ופרצת ימה וקדמה (לעיל כח יד) ויפרוץ האיש מאד מאד (לעיל ל מג) ולכן אמר בכאן בהיות הראשון כמשיב ידו והוא מהר לצאת מה פרצת פרץ גדול בגדר למהר לצאת קודם ממנו ואמר עליך כי היה הגדר עליו והוא כלוא בתוכו כלומר מה פרצת עליך פרץ גדול בגדר ויצאת ממנו ורבי אברהם אמר מה פרצת כאדם הפורץ גדר ויצא ממנו והנה יש עליך משפט זה הפרץ ואין בזה טעם ובמדרשו של רבי נחוניא בן הקנה (ספר הבהיר קצו) יזכיר סוד בשם אלה הילודים אמרו איקרי זרח על שם החמה שהיא זורחת תמיד ופרץ על שם הלבנה הנפרצת לעתים ונבנית לעתים והרי פרץ הוא הבכור וחמה גדולה מן הלבנה לא קשיא דהא כתיב ויתן יד וכתיב ואחר יצא אחיו והנה לדעתם היה שם הלבנה לפרץ מפני מלכות בית דוד והיו תאומים כי הלבנה מותאמת בחמה והנה פרץ תאום לזרח הנותן יד והוא בכור בכח עליון כמו שאמר (תהלים פט כח) אף אני בכור אתנהו וזהו מאמרם (ר"ה כה) בקדוש החודש דוד מלך ישראל חי וקיים והמשכיל יבין
@1153 **כי ה' אתו** . שם שמים שגור בפיו לשון רש"י ואינו נראה אבל וירא אדוניו כי ה' אתו כי יצליחו מעשיו בכל עת יותר מכל אדם וידע כי מאת אלהים הוא לו וכן (לעיל כו כח) ראה ראינו כי היה ה' עמך וימצא חן בעיניו ושמו משרת לעצמו ופקיד על ביתו וכל יש לו נתן בידו להיות פקיד ונגיד על כל אשר לו בבית ובשדה ולרבותינו בו מדרש (ב"ר פו ה) אמרו מלחש ונכנס מלחש ויוצא אמר לו מזוג רותחין והא רותחין מזוג פושרין והא פושרין מה יוסף תבן בעפריים חרשין במצרים עד היכן עד שראה שכינה עומדת על גביו הדא הוא דכתיב וירא אדוניו כי ה' אתו והענין כי בעבור היות אדניו מצרי לא ידע את ה' אמרו כי בראותו הצלחתו הגדולה היה חושש כי דרך כשפים הוא כאשר בבני ארצו עד שראה שהיה מאת עליון במראה שנראית לו בחלום או בהקיץ בעמוד ענן וכיוצא בו לכבוד הצדיק
@1156 **כי אם הלחם אשר הוא אוכל** . לשון נקיה כדברי רבותינו (ב"ר פו ו) ורבי אברהם אמר כי כל אשר לו היה ביד יוסף חוץ מן הלחם אשר הוא אוכל שלא היה אפילו נוגע בו בעבור היותו עברי כי כן היה משפט המצרים את העברים שלא יגעו במאכלם כי תועבה היא למצרים ואפשר שהוא כן או יהיה פירוש הכתוב כי לא ידע אדוניו את יוסף מאומה שיקח מכל אשר לו רק את הלחם לבדו אשר יאכל יוסף לא לשאר הנאות כאשר יעשו הבחורים ולא לאסוף לו עושר ונכסים כענין שנאמר (שמואל א כט ג) ולא מצאתי בו מאומה מיום נפלו עד היום הזה ו"לא ידע אתי מה בבית" (פסוק ח) ענין אחר שלא ישגיח לדעת מה אתו בבית כי "לא ידע אתו מאומה" לשון שולל ו"מה בבית" יקיים
@1156 "ויהי יוסף יפה תאר ויפה מראה" - הזכיר זה בכאן לומר כי בעבור יפיו נשאה אשת אדוניו אליו את עיניה ורש"י כתב כי בעבור שראה עצמו מושל התחיל אוכל ושותה ומסלסל בשערו וכו'
@1158 **וימאן ויאמר אל אשת אדניו** . סיפר הכתוב כי מאן לעשות כרצונה אף על פי שהיא גברתו אשת אדוניו והוא ירא ממנה כי היה ירא את השם יותר וזה טעם אל אשת אדניו
@1159 **וחטאתי לאלהים** . בני נח נצטוו על העריות לשון רש"י ונכון הוא רק בעבור חסרון דעת הנשים הקדים אליה כי הדבר בגידה באדוניו אשר בוטח בו ואחרי כן אמר כי יש בענין עוד חטא לאלהים ויתכן לפרש עוד וחטאתי לאלהים בבגידה הזאת כי רעה גדולה היא שיהיה בה לי חטא לפני האלהים כי עיניו בנאמני ארץ (תהלים קא ו) ולא לפניו בוגד יבא ודברו אמת רק לא הזכיר אסור הערוה כי דבר עמה כדרך הנשים
@1160 **וטעם לשכב אצלה** . כדברי רבי אברהם אפילו שישכב אצלה בסמוך היא בבגדה והוא בבגדו או להיות עמה לדבר שיחות כי לא מצאנו "אצלה" על המשגל רק עמה או אותה שכבה עמי אם שכוב ישכב איש אותה (ויקרא טו כד) והנשים תשכבנה (זכריה יד ב)
@1162 **ויעזוב בגדו בידה** . לכבוד גברתו לא רצה להוציאו מידה בכחו הגדול ממנה והסיר אותו מעליו כי היה בגד שיתעטף בו כמעיל וצניף והיא בראותה כי הניח בגדו בידה פחדה פן יגלה עליה לבני הבית או לאדניו והקדימתו אליהם לאמר כי הפשיט בגדו לשכב עמה ובראותו כי הרימותי קולי נבהל לברוח וזה טעם ויהי בראותה כי עזב בגדו ולכן לא הגידה היא ויעזוב בגדו בידי רק אמרה לאנשי ביתה ולבעלה ויעזב בגדו אצלי
@1164 **וטעם ראו הביא לנו איש עברי** . כי העברים שנואי המצרים המה ולא יוכלו לאכל אתם לחם כי תועבה היא להם (להלן מג לב) ולא יקנו מהם רק לכורמים וליוגבים ולא יבאו בביתם ולכן אמרה הנה עשה עמנו רעה להביא בביתנו עברי ועשאו פקיד ונגיד וראוי לו שיצחק בנו כענין שנאמר (משלי כט כא) מפנק מנוער עבדו וגו' וזה טעם אשר הבאת לנו כי הבאתו בביתם היתה קשה בעיניהם ואמרה הביא לנו על בעלה לא הזכירתו לכבודו או בדרך מוסר לנשים או בעבור שהמביא ידוע וכן בספר איוב במקומות רבים ידבר על השם הנכבד בסתם בעבור דעתם שעליו ידברו וכן ויאמר אל אבנר מדוע באת אל פילגש אבי ( ג ז) לא יזכיר האומר ולא דבר בו כלל בעבור היותו ידוע שהוא איש בשת
@1169 **ויהי כשמוע אדוניו** . בשעת תשמיש אמרה לו כדברים האלה עשה לי עבדך עניני תשמיש כאלה רש"י וכך אמרו בבראשית רבה (פז י) רבי אבהו אמר בשעת תשמיש ואני תמה כי אדוני יוסף סריס היה ואשתו בנעוריו נשאה והם דרשו (שם פו ג) סריס פרעה מלמד שלא לקחו אלא לתשמיש וסרסו הקב"ה בגופו ועוד כי איך תפגום את עצמה ותמאס בעיני בעלה לאמר לו כי זנתה באונס או ברצון וראוי היה שיהרגנה כי למה לא צעקה מתחילה ויברח כאשר עשתה בסוף והנה לאנשי ביתה אמרה בא אלי לשכב עמי לא ששכב אלא שבא לעשות כן וצעקתי וברח וכל שכן שתסתיר הדבר מבעלה ואם תאמר כדי שיחר אפו ויהרגהו ודי חיוב מיתה לעבד שיבוא לאנוס אשת השר אדוניו ואפשר שרצו לפרש כדברים האלה עניני תשמיש בגלוי ערוה ומשמוש ידים לא תשמיש ממש שהיה אדוניו סריס בגופו שבא אליו חולי שלא יתאוה כענין השחוף ועל דרך הפשט אין צורך כי אין הכ"ף לדמיון בדבר אחר ופתרונו הדברים האלה וכמוהו (לעיל כד כח) ותגד לבית אמה כדברים האלה וכן ובדברו עמי כדברים האלה נתתי פני ארצה (דניאל י טו) וכן רבים או יאמר כי בשמוע אדוניו את דברי אשתו שאמרה לו עשה לי עבדך כדברים האלה שהגדתי מיד לאנשי הבית חרה אפו ויתכן ששמוש הכ"ף בזה להפלגה וכן (להלן מד ז) למה ידבר אדוני כדברים האלה ותקראנה אותי כאלה (ויקרא י יט) והנה מאהבת אדוניו את יוסף לא הרגו או שהיה נס מאת השם או שנסתפק בדבריה מדעתו צדקת יוסף וכן אמרו בבראשית רבה (פז י) אמר לו ידע אנא דלית הוא מינך אלא שלא לערב פסולת בבני
@1170 **ויתנהו אל בית הסוהר מקום אשר אסירי המלך אסורים שם** . אמר רבי אברהם כי הכתוב יפרש שבית הסוהר הוא מקום אשר אסירי המלך אסורים שם ולכך אמר כי הוא שם מצרי כי דרך הכתוב לפרש לשון נכריה כמו הפיל פור הוא הגורל ולא אמר כלום אבל ויתנהו אל בית הסהר הידוע למלך שהוא מקום אשר יאסרו שם אסירי המלך לומר כי היה זה סיבה שיכנסו עמו המשקה והאופה ויתכן כי טעם אסירי המלך עבדיו ומשרתיו החוטאים לו במשפט המלוכה כי שאר האסורים לעם ביד השופטים והשוטרים בבית סהר אחר ינתנו וסיפר הכתוב ששמו שם יוסף מאהבת אדוניו אתו והכל סיבה מאת ה' ובעלי הלשון (רד"ק בספר השרשים שורש סהר) יפרשו "סהר" כיפה עגולה מלשון אגן הסהר (שיר השירים ז ג) ולפי דעתי שהוא הבור (להלן מ ב) בית בנוי תחת הקרקע ולו פתח קטן מלמעלה יכניסו בו האסורים וממנו להם אורה והוא מלשון סיהרא בארמית כאשר אמר (לעיל ו טז) צהר תעשה לתבה מלשון צהרים ושנו בהם זה לרוב אורו וזה למיעוט
@1175 **על שני סריסיו** . היו אלה השרים שניהם סריסים כי היו שרי המשקים והאופים גם בבית הנשים אשר למלך והמלכים יסרסו אותם ודעת אונקלוס כי סריסים שרים וגדולים אמר בפוטיפר (לעיל לז לו) רבא דפרעה ועל תרין רברבנוהי וכן תרגם יונתן (מלכים ב כ יח) והיו סריסים בהיכל מלך בבל
@1178 **איש כפתרון חלומו** . לשון "פתרון חלומות" הוא המקרה אשר יקרנו לעתיד ויקרא המודיע אותו העתיד פותר ועל דעת רבים (הראב"ע והרד"ק) כי פתרון הוא פירוש וטעם איש כפתרון חלומו כל אחד ואחד חלם חלום שדומה לפתרון העתיד לבא אליו זה לשון רש"י ומה טעם שיאמר שר המשקים לפרעה (להלן מא יא) חלמנו חלום הדומה לפתרון שימעט בזה חכמת הפותר ואולי לא יהיה כן חלום פרעה ולא ידענו יוסף ורבי אברהם אמר שראה כל אחד בחלומו מה שהיה פתרון חלומו כל מה שאירע לו בעתיד לומר שהיה חלום אמת לא בא ברוב ענין שלא יתקיים רק המקצת והוא הנכון
@1180 **וישאל את סריסי פרעה אשר אתו במשמר בית אדוניו** . היה ראוי שיאמר הכתוב וישאל אותם לאמר אבל האריך כי רצה לספר בשבח יוסף שהיה נער עבד ושאל לשני שרים גדולים והם בבית אדוניו אשר שנא אותו והיה כל אחד יכול לצוות לשאת את ראשו מעליו ולא פחד מהם מלשאול אותם ולאמר להם דעתו בפתרון כי בטח בחכמתו שאילו נמלט שר האופים היה תולה אותו
@1181 **וטעם ופותר אין אותו** . אין מודיע העתיד ממנו ויתכן ששלחו לקצת החרטומים בבקר או שהיו אנשים עמהם בבית הסוהר ואין פותר אותו או שאמרו ואין בעולם פותר אותו כפי דעתנו כי נעלם הוא מאד
@1181 "הלוא לאלהים פתרונים" - פירש רבי אברהם כי יאמר כי המקרים העתידים לבא בחלומות לאלהים הם כי הוא לבדו המחלים והמודיע העתיד והוא העושה שלום ובורא רע ואין בדבורי לכם תועלת או הפסד וזה אמר שלא יענישוהו אם תבא להם רעה או כדי שיספרו אותם אליו ולא יבזוהו ואם כן אין למלת "הלא" בזה טעם ואולי יהיה פירושו כמו "הנה" יאמר הנה לאלהים לבדו הפתרונים ולא לאדם הפותר והנכון בעיני כי אמר הלא לאלהים פתרונים בכל החלומות הנעלמים והסתומים והוא יכול להודיע פתרון חלומכם ואם הוא נעלם בעיניכם ספרו נא לי אולי יישר בעיניו לגלות סודו אלי
@1183 **והוא כפורחת עלתה נצה** . דומה לפורחת והיא כפורחת נדמה לי בחלומי כאילו היא פורחת ואחר הפרח עלתה נצה נעשו סמדר ואחר כך הבשילו והיא כד אפרחת אפיקת לבלבין עד כאן תרגום של פורחת לשון רש"י ואינו נכון שאם היה מדבר כמדמה מפני שהם דברי חלום היה אומר והנה כגפן לפני ובגפן כשלשה שריגים והכ"ף הזו אינה בחלום שר האופים ולא בחלום פרעה ולמה ידמה בזה יותר מכל האחרים אבל יאמר בכולם והנה והוא הדמיון שטעמו "כאילו" אבל פירוש והיא כפורחת עלתה נצה שראה בחלומו הגפן כי מיד שפורחת עלתה נצה והבשילו אשכלותיה ענבים וזה להורות כי ממהר האלהים לעשותו ובזה הכיר יוסף כי שלשת השריגים שלשת ימים הם ולא חדשים או שנים וחשב בדעתו כי ביום אחד ישא ראש שניהם או בעבור כי בלילה אחד חלמו ואין צריך לדברי רבי אברהם שאמר שהיה יוסף יודע יום הולדת את פרעה וכזאת הכ"ף במקומות רבים ויהי כמשיב ידו (לעיל לח כט) כבא אברם (לעיל יב יד) וכעת מותה ותדברנה הנצבות (שמואל א ד כ) וכן רבים ואונקלוס שאמר והיא כד אפרחת אפיקת לבלבין תרגם עלתה שהעלתה לולבי גפנים הוציאה פרח והעלתה לולבין גדולים והנצו והבשילו אשכלותיה ענבים כי לא יבוא לשון עלתה בנץ כי איננו עולה
@1187 **כי אם זכרתני אתך** . אם תזכרני כאשר ייטב לך תעשה עתה עמדי חסד ואמת ותזכרני אל פרעה ואם יהיה נא לשון בקשה כי אם זכרתני ועשית כחסדך חסד עמדי תזכרני אל פרעה וטעם אתך שתזכרני לעשות עמי בטוב אשר ייטב לך שיצאת מבית הסוהר או יהיה פירוש שתזכרני בלבך כאילו אני עמך והזכירה אל פרעה שיהלל אותו אליו לאמר הנה בבית שר הטבחים עבד יפה לפני מלכים יתיצב והנכון עוד בעיני שיאמר אם תזכרני להיות אתך כאשר ייטב לך ותשוב למעלתך ותחפוץ לעשות עמי החסד הזה תזכרני אל פרעה לאמר בפניו זכרתי נער שהיה משרת לי בבית הסהר תנהו אלי להיות לי משרת והוצאתני מן הבית הזה כי חטא גדול הוא על המעמידים אותי בכאן או יהיה טעם והזכרתני אל פרעה כי ראה אותי פרעה בהיותי עבד לשר שלו ופקיד על כל אשר לו משרת לפניו ואם תזכרני לפניו תוציאני מכאן כי אין בי עון אשר חטא וראוי למלך שיוציאני ויצילני מיד עושקי כי כל דבר לא יכחד מן המלך אם יחפוץ
@1188 **וטעם מארץ העברים** . מארץ חברון אשר גרו שם אברהם יצחק ויעקב כי אברהם שהיה ראש היחס נקרא אברהם העברי (לעיל יד יג) כי היה מעבר הנהר וגדול שמו בגוים כי נתקיים בו ואגדלה שמך (לעיל יב ב) ועל כן נקראו כל זרעו העברים והם עצמם יחזיקו את שמם כן שלא יתערבו בעמי הארצות הכנענים והוחזק השם הזה בכל זרע ישראל לעולם וזה טעם הביא לנו איש עברי (לעיל לט יד) כי יוסף אמר להם עברי אנכי ולא רצה שיחזיקוהו בכנעני והנה ארץ מגוריהם קראה ארץ העברים כלומר הארץ אשר העברים שם או שנקרא שמה כן כי הם גדולי הארץ ואציליה כמו שנאמר (לעיל כג ו) נשיא אלהים אתה בתוכנו וכתיב (תהלים קה טו) אל תגעו במשיחי
@1189 **כי טוב פתר** . אמר אונקלוס כי יפה פתר וכן טוב טעם ודעת למדני (תהלים קיט סו) וכן כי טובות הנה (לעיל ו ב) יפות והטעם לאמר כן כי האיש הזה מבזה על יוסף חושב בו שלא ידע לפתור אותו לעולם ולא יגיד לו החלום אם לא בראותו כי פתר לחברו יפה וכהוגן או יאמר וירא שר האופים כי לטובה פתר לו ושמח והגיד חלומו שהיה מצטער בו יותר מחברו
@1189 "סלי חרי" - סלים של נצרים קלופים עשויים חורים חורים זה לשון רש"י והגאון רב סעדיה פירש סלי לחם לבן כלחם המלך מלשון ולא עתה פניו יחורו (ישעיהו כט כב) מן הארמית שתאמר ללבן חיור והוא הנכון כי היה בכל הסלים מלחם המלך ובסל העליון מכל מיני מאכל פרעה שהיה מעשה אופה ולשון רבותינו במשנה (ביצה ב ו) פתין גריצים וחיורי ואמרו בירושלמי (שם) רבנין שמעין לה מן הדא והנה שלשה סלי חורי על ראשי חסלת פרשת וישב
@1197 **על היאור** . כל שאר נהרות אינם קרוים יאורים חוץ מנילוס מפני שכל הארץ עשויה יאורים יאורים בידי אדם ונילוס עולה בתוכם לשון רש"י אבל אונקלוס תרגם יאור "נהרא" רק תרגם על יאוריהם (שמות ז יט) על "אריתיהון" כי הוצרך שם להבדיל ביניהם מפני שהזכיר על נהרותם ועל יאוריהם והנה כלם יקראו לדעתו יאורים הגדולים נקראים נהרות ויאורים ואלו העשויים חפירות ארוכות בידי אדם גם הם יקראו יאורים ומצינו כי חדקל נקרא יאור כמו שכתוב (דניאל י ד) ואני הייתי על יד הנהר הגדול הוא חדקל והנה איש אחד לבוש הבדים וכתיב (שם יב ה) והנה שנים אחרים עומדים אחד הנה לשפת היאור ואחד הנה לשפת היאור ויאמר לאיש לבוש הבדים אשר ממעל למימי היאור ולדעתי כדברי אונקלוס כן הוא כי יאור ונהר לשון אחד ושניהם לשון אורה וכן הגשם נקרא אור שנאמר (איוב לו ל) הן פרש עליו אורו יפיץ ענן אורו (שם לז יא) וכמו שאמר רבי יוחנן (ב"ר כו ז) כל אורה האמורה באליהוא בירידת גשמים הכתוב מדבר ואולי בעבור שהגשמים בסבת המאורות והנהרות יעשו מהם יתיחסו אל האבות
@1198 **והנה מן היאור עולות** . בעבור כי ארץ מצרים תשתה מן היאור וממנו בא להם השובע והרעב ראה אותן עולות מן היאור והפרות סימן לחרישה והשבלים סימן לקציר כמו שאמר (להלן מה ו) אשר אין חריש וקציר ראה כי היאור לא עלה רק מעט ואין חריש ואשר יזרעו מעט במקומות הלחים יבא קדים רוח ה' וישרוף אותם כאשר ראה אותם שדופות קדים והנראה ממשמע הכתובים כי היה השובע בארץ מצרים לבדה כאשר נאמר (להלן פסוק כט) שבע גדול בכל ארץ מצרים וכן (להלן פסוק מח) אשר היו בארץ מצרים אבל הרעב היה בכל הארצות (להלן מב נד) וכן פתר יוסף וקמו שבע שני רעב ולא הזכיר בארץ מצרים ועל כן לא יכלו בשאר הארצות לקבוץ אוכל ואפילו אם שמעו הענין כי היה מפורסם מאד ואולי היה בחלום רמז מזה במה שהזכיר ותרענה באחו כי שם היה מרעיהן ומעמדן אבל הרעות אחרי אכלן את הטובות תתהלכנה בארץ ולא ידע פרעה עד אנה הלכו
@1198 "באחו" - אגם כמו ישגא אחו (איוב ח יא) לשון רש"י ואיננו נכון כי אחו שם העשב הגדל כמו היגאה גומא בלא ביצה ישגא אחו בלי מים עודנו באבו לא יקטף (איוב ח יא-יב) והנה איננו האגם ואולי ירצה לומר שיקרא העשב הנעשה באגמים על שם האגם והנכון שיהיה אחו שם כולל הדשא והעשב הנעשה על שפת הנהרות והאגמים ויהיה בי"ת באחו כמו בי"ת לחמו בלחמי ושתו ביין מסכתי (משלי ט ה) כי על שפת היאור היו רועות כמו שאמר (בפסוק הבא) אצל הפרות על שפת היאור ואולי הוא מלשון אחוה בעבור היות מיני העשבים רבים גדלים יחד
@1199 **ותעמדנה אצל הפרות** . בצדן וקרוב להן והוא סימן שלא יהא הפסק בין שני השבע ושני הרעב ואף על פי שלא סיפר זה ליוסף ואולי המראה והסיפור היו שוים והכתוב לא יחוש כאשר הוסיף בסיפור ולא נודע כי באו אל קרבנה וכן עולות בקנה אחד סימן שתהיינה שבע שנים רצופות
@1200 **ותאכלנה הפרות** . על דעתי הוא סימן שיאכלו שני הרעב את שנות השבע ומזה למד יוסף לאמר לפרעה ויקבצו את כל אוכל השנים הטובות והיה האוכל לפקדון לארץ לשבע שני הרעב כי ראה שהפרות והשבלים הטובות תבואנה אל קרב הרעות ואיננה עצה כי הליועץ למלך נתנוהו רק בפתרון החלום אמר כן ונשכח כל השבע ולא יודע השבע פתרון ולא נודע כי באו אל קרבנה ומראיהן רע כי ראה שלא היו באכילתן בריאות וטובות רק היו להן למחיה אילו לא אכלו אותן היו מתות בכחשיהן ולא כדברי רש"י שאמר ונשכח כל השבע הוא פתרון הבליעה
@1202 **צמחות אחריהן** . לא שראה אותן צומחות שלא ראה אלא שבלים עשויות אבל הוא כאילו אמר צמחו אחריהן ואחז זה הלשון להודיע שמיד שראה הטובות ראה הרעות שעלו אחריהן כי סימן התכיפה ראה בכולן
@1203 **וטעם ויקץ פרעה וגו'** . הנה חלום שלם לשון רש"י ולפי דעתי ירמוז כי עמד על מטתו מקיץ מחשב בחלומו אולי יראה עוד דבר פעם שלישית וכאשר עמד בבקר ולא חלם עוד נפעם רוחו וזה טעם ויהי בבקר ותפעם רוחו אבל בנבוכדנצר אמר ותתפעם רוחו ושנתו נהיתה עליו (דניאל ב א) כי גם בלילה לא שכב לבו והזכיר ויקץ פרעה מן הענין הנזכר בספר השינה כי חלום שיחלום אחריו חלום אחר מענין אחר בשנתו איננו מתקיים על כן אמר כי כאשר הקיץ נהיה החלום וחשב בו עד הבקר אולי ישתלש חלומו כאשר נשנה והנה פרעה עצמו הכיר כי ענין אחד הוא ולכך הזכיר והנה חלום וכך אמר חלום חלמתי ופותר אין אותו ולא הזכיר חלומות וזה טעם וארא בחלומי אבל הכתוב הזכיר ואין פותר אותם לפרעה לומר שאין פותר אפילו האחד מהם
@1208 **איש כחלומו** . לפי החלום וקרוב לענינו לשון רש"י ויותר נכון שיאמר כי לכל אחד ממנו פתר כאשר היה אמתת חלומו העתיד לבא לו כי כאשר פתר כן היה לנו וכן (להלן מט כח) איש אשר כברכתו ברך אותם כברכה הבאה אליו ועל דעתי אין צורך אבל אמר איש את חלומו פתר לנו ויהי כאשר פתר לכל אחד כן בא והגיע אלינו הגיד כי היו חלומות שונים ולהם פתרונים שונים כאשר יפרש שלא יחשוב שחלום אחד חלמו שניהם ופתרון אחד להם וכן לדעתי איש כברכתו ברך שלא ברך אותם ברכה שוה לכולם אלא ברכה מיוחדת לכל אחד כאשר פירש ואמר לו
@1219 **צנומות דקות** . צונמא בלשון ארמי סלע הרי הן כעץ בלא לחלוח וקשות כסלע ותרגומו נצן לקיין נצן אין בהן אלא הנץ לפי שנתרוקנו מן הזרע לשון רש"י והשבלים בעת שנתרוקנו מן הזרע אין בהן נץ וכן פרעה לא ראה אותן בעת הנצן כי מלאות וטובות ודקות ושדופות קדים ראה אותן וכן צנומות שיהיה כמו סלועות מלשון צונמא אינו נכון והשבלים הדקות אינם קשות כסלע אבל פירוש צנומות פרודות לחתיכות הרבה והוא לשון רבותינו (ברכות לט) פת הצנומה בקערה מברכין עליה המוציא פת החתוכה והוא הפת שאדם עושה ממנו חתיכות ונותן המרק עליו בקערה ואוכלו חתיכה חתיכה בלא בציעה אחרת והוא לשון התרגום גם כן שאמר נצן לשון חתוך וחסרון ממה שאמרו הם ז"ל (ב"ב נד) מליא במליא נצא בנצא לא הויא חזקה שקל מוליא ושדא בנצא הויא חזקה המקום שהוא גבוה שלם העפר נקרא מליא ושהוא חסר העפר ובו חסרון נקרא נצא אף כאן הפך מלאות צנומות ונצן הפך מליאן והענין כי לא היו השבלים מלאות הגרגרים אבל היה בהם מקומות חסרים אין בהם גרגרים ומקום אחר גבוה שבו הגרגרים שלקו והם רקות ולכך אמר יוסף במקום צנומות רקות כי היו בהן מקומות רקים אין בהם גרגרים כלל
@1223 **יהיו שבע שני רעב** . בעבור שהשבע בארץ מצרים איננו חדוש גדול כי הוא כגן ה' (לעיל יג י) הזכיר תחילה פתרון הרעות כי הוא החדוש ותועלת החלום כי האלהים ברחמים הראה לפרעה הרעב להחיות לפליטה גדולה וזה טעם ותחילנה שבע שני הרעב לבוא כאשר אמר יוסף (להלן מא נד) כי לא נודע דברו רק בשנות הרעב
@1228 **ועל השנות החלום אל פרעה פעמים** . טעם השנות החלום שנשנה שני פעמים בלילה אחד כי היה אפשר שיראה בחלום אחד הפרות והשבלים להודיעו כי אין חריש וקציר ועשה ממנו שני חלומות באים זה אחר זה בלילה אחד ואין דרך החולמים כן להודיעו כי הדבר מזומן וממהר האלהים לעשותו וזה טעם פעמים כי לא נשנה בפעם אחת ורבי אברהם מפרש כי השנות החלום בפרות ובשבלים לעד כי הדבר נכון וקיים אבל בעבור כי היה פעמים בלילה אחד לעד כי ממהר האלהים לעשותו ואם כן נאמר שהיה די בשבלים כי הוא המודיע הרעב
@1229 **ירא פרעה איש נבון וחכם** . אמר לו שיצטרך לאיש נבון וחכם שיהיה ממונה על כל הארץ ויפקד עוד פקידים תחתיו שילכו בארץ ויקבצו את כל אוכל כי לא יוכל השליט ללכת בכל הארץ ואמר לו שיהיה נבון וחכם נבון שידע לנהל עם ארץ מצרים בלחם לפי הטף מידו ולתת להם כדי חיותם וימכור המותר לארצות האחרות לאסוף עושר וממון לפרעה וחכם שידע לקיים התבואה שלא תרקב שיערב עם כל מין דבר המקיים אותו בטבעו כגון חומטין שהזכירו רבותינו (שבת לא) והכסף החי הממית הכנימה וכיוצא בהן ואמרו בבראשית רבה (צ ה) ערב בהן עפר וקיסומיות דברים שמקיימין את התבואה ואמר יוסף כל זה בעבור שיבחרו אותו כי החכם עיניו בראשו
@1232 **והיה האוכל לפקדון לארץ** . אמר שיהיה האוכל פקדון ביד פקידי פרעה לצורך הארץ לשבע שני הרעב ולא יוציאו ממנו לדבר אחר שלא תכרת הארץ ברעב כאשר לא מתו הפרות בכחשיהן
@1234 **וטעם הנמצא כזה** . בעבור שהיה עברי והם שנואי נפש המצריים לא יאכלו מגעם ולא יתחברו עמהם כי טמאים הם אצלם על כן לא רצה למנותו משנה בלא רשותם ולכך אמר להם שלא ימצאו מצרי כמוהו כי רוח אלהים בו ואחרי שהודו אמר ליוסף אחרי הודיע אלהים אותך את כל זאת כי מאשר היה הפתרון טוב ונכון בעיני פרעה ובעיני עבדיו היה בעיניהם כאלו כבר בא הכל כמו שפתר להם ויתכן שירמוז "את כל זאת" גם למה שספר לו שר המשקים וכמוהו (לעיל כט יג) ויספר ללבן את כל הדברים האלה הברכות הנזכרות קודם לכן אמר אחרי שהודיע אלהים אותך החכמה הגדולה הזאת לפתור כל החלומות הנעלמים והסתומים ולא יפול דבר מכל דבריך אין נבון וחכם בכל ענין כמוך וראוי אתה לנהוג שררה ומלכות ולהיות לי למשנה
@1238 **ויסר פרעה את טבעתו מעל ידו** . נתינת טבעת המלך היא אות למי שנותנה להיות שני לו לגדולה לשון רש"י והנכון שטבעת המלך היא חותמו כענין וחתמו בטבעת המלך (אסתר ח ח) והנה נתן לו החותם להיות נגיד ומצוה בכל המלכות ויחתום בטבעת המלך כל אשר יחפוץ
@1239 **במרכבת המשנה** . השניה למרכבתו המהלכת אצל שלו לשון רש"י והנה הוא שם וכן כהני המשנה (מלכים ב כג ד) את משנה התורה הזאת (דברים יז יח) והנכון כי משנה תאר כמו ואנכי אהיה לך למשנה (שמואל א כג יז) כי מרדכי היהודי משנה למלך אחשורוש (אסתר י ג) וכן כסף משנה (להלן מג יב) תאר כמו כסף שני וכבר הביאו המדקדקים (רד"ק בספר השרשים שורש שנה) ראיה בהיות אלה כולם בסגול ומשנה התורה וכל השמות בצרי כמשפט הסמיכות והענין כי יש למלך מרכבת ידועה לו כמו שנאמר (אסתר ו ח) וסוס אשר רכב עליו המלך ואחרת ידועה למשנהו ואחריו לשליש
@1241 **צפנת פענח** . אמר ר' אברהם אם היא מלה מצרית לא ידענו פירושה ואם מתורגמת לא ידענו שם יוסף ועל דעת הראשונים שאומרים "המפענח נעלמים" יתכן שקרא לו שם נכבד כלשון ארצו כי שאל לו או שהיה המלך יודע שפת ארץ כנען הקרובה אליו וענינו צפונה מגלה וכן בתו קראה שם משה רבינו כלשון עמו מן המים משיתיהו (שמות ב י) ואל תשתומם בעבור שקראוהו סופרי המצריים מוניוס כי ישנו השמות ללשון מובן או מורגל להם כאשר יעשה התרגום בקצתם כגון בין קדש ובין שור (לעיל כ א) בין רקם ובין חגרא וכן בהרבה מן השמות ובקצתם לא ישנה דבר כאשר עשה בסיחון מלך חשבון ובעוג מלך הבשן וזולתם הרבה וזה לפי מה שהיו נקראים בלשון ארמית בדורו וכן עשו הנוצרים המעתיקים
@1241 "בת פוטיפרע כהן און" - הוא פוטיפר ונקרא פוטיפרע על שם שנסתרס מאליו לפי שלקח יוסף למשכב לשון רש"י והוא מדרש רבותינו (סוטה יג) והוצרך ממנו רש"י (להלן מז כב) לומר כי כל "כהן" משרת לאלהות חוץ מזה שהוא לשון גדולה שהרי שר הטבחים היה וכן כהן מדין (שמות ב טז) ואני אומר כי לדברי רבותינו היה פוטיפר שר לפרעה וכאשר נסתרס בגופו והכירו בו וקראוהו פוטיפרע נתבייש בדבר ופירש משררתו והכניס עצמו בבית עבודה זרה ונעשה כומר לעבודה זרה כי כן מנהג הנכבדים ואפשר שהיה און שם עבודה זרה שלו וכן כהן מדין כומר כמו שאמרו (סנהדרין פב) ביתרו שהיה מפטם עגלים לעבודה זרה והאמת כי לשון כהונה שרות אבל לא לאלהות בלבד כי הנה ובני דוד כהנים היו ( ח יח) ובמקומו בדברי הימים (א יח יז) ובני דוד הראשונים ליד המלך וכן מוליך כהנים שולל (איוב יב יט) שהם משרתי המלך וכן יכהן פאר (ישעיהו סא י) יתלבש פאר ככהן העובד שיעשו לו בגדים שלא כשאר העם לכבוד ולתפארת וכן ומיודעיו וכהניו (מלכים ב י יא) ראשי משרתיו
@1243 **לקמצים** . קומץ על קומץ יד על יד היו אוצרים לשון רש"י ותרגום אונקלוס לאוצרים כי החפירות העשויות בארץ לאוצרים או לדברים אחרים יקראו קמצים באחת הפחתים ( יז ט) תרגם יונתן בחדא מן קומציא וכן כל פחת (ישעיה כד יז יח) תרגם קמצא והוא קרוב מן חופר גומץ (קהלת י ח) כי הגימ"ל תשמש בכאן כמו קו"ף כאשר תשמש כמו כ"ף באל יחסר המזג (שיר השירים ז ג) מן מסכה יינה (משלי ט ב) וכנה אשר נטעה ימינך (תהלים פ טז) שהוא כמו גנה (ישעיהו א ל) ויסכרו מעינות תהום (לעיל ח ב) כטעם ויסגרו על ארץ מכורתם (יחזקאל כט יד) מכורותיך ומולדותיך (שם טז ג) וסכרתי את מצרים (ישעיהו יט ד) הכ"ף והגימ"ל בהם שוים וישתוו הקו"ף והכ"ף תמיד כמו קובע (שמואל א יז לח) וכובע (יחזקאל כז י) תקן משלים הרבה (קהלת יב ט) כמו מי תכן את רוח ה' (ישעיהו מ יג) ורבותינו יאמרו מלשון קישוט תכשיטים (שבת סג) ותקשיט (ירושלמי כתובות פ"ו ה"ג) וכן ויציקו את ארון האלהים ויעל אביתר עד תום כל העם לעבור מן העיר ( טו כד) אמר בו התרגום ואקימו ית ארונא עשאו כמו ויציגו וכענין שנאמר בו (שם ו יז) ויביאו את ארון ה' ויציגו אותו במקומו מלשון אציגה נא עמך (לעיל לג טו) והצגתיו לפניך (להלן מג ט)
@1244 **ויקבץ את כל אוכל** . יוסף הנזכר למעלה וגם אחרי כן ויצבור יוסף בר וכן כי חדל לספור יוסף הנזכר ואמר רבי אברהם כי אין פירושו "כל" כי ברעב היו מתים וכן וכל הארץ באו מצרימה רק טעמו שקבץ כל אשר יכול והנכון בעיני שקבץ את הכל אל תחת ידו והוא נתן להם ממנו בכל שנה כדי פרנסתם שלא יבזבזוהו והוא שאמר ויקבצו את כל אכל השנים הטובות ויצברו בר תחת יד פרעה אוכל בערים ושמרו ומפני שאמר ויקבצו את כל אכל ואמר ויצברו בר וכן ויקבוץ את כל אוכל ויצבור יוסף בר יורה שקבצו כל הנאכל לאדם בר ולחם ומזון אפילו תאנים וצמוקים וכיוצא בהן ויצברו מהם הבר אל תחת יד פרעה והוא התבואה שהובאה ברחת ובמזרה לזרות ולהבר ויתן בערים כדי אכלם מכל הפירות והיה כל האוכל למשמרת לצורך שני הרעב שיקחו ממנו כדי חיתם והנשאר בבר קיים באוצרות ויתכן שנתן להם דמים כשער הזול מגנזי המלך ולכן היה הבר לפרעה ומכרו להם בשני הרעב כמו שכתוב (להלן מז יד) וילקט יוסף את כל הכסף הנמצא בארץ מצרים או שלקחו המלך בחזקה כי אמר אני שמרתיו אבל אונקלוס תרגם אכל ובר בשוה
@1250 **ויהי רעב בכל הארצות** . אשר סביב ארץ מצרים כי מה יעשו הרחוקות אם היה בהן רעב כזה וכך אמרו בבראשית רבה (צ ו) בשלש ארצות בפינקיא ובערביא ובפלישטני
@1252 **וישבר למצרים ויחזק הרעב בארץ מצרים** . יאמר כי לא פתח יוסף אשר בהם עד שחזק הרעב בארץ לא כאשר צעקו אל פרעה מיד כי העם צועקים כשיש להם מחיה מעט והוא רצה שלא ישאר להם כלום זה טעם והרעב היה על כל פני הארץ כי טרם פתחו אוצרותיו היה הרעב על כל פני הארץ ועוד חזר לבאר שלא מכר להם עד שחזק עליהם מאד או שיפליג הכתוב לומר שהיה רעב של מהומה
@1254 **למה תתראו** . אל תראו עצמכם שבעים לפני בני עשו וישמעאל (תענית י) באותה שעה עדיין היתה להם תבואה ומפי אחרים שמעתי שהוא לשון כחישה למה תהיו כחושים ברעב ודומה לו ומרוה גם הוא יורה לשון רש"י ודברי אחרים אין בהם ממש ומה שאומר אל תראו עצמכם שבעים בפני בני ישמעאל ובני עשו לא הבינותי שאין בני ישמעאל ובני עשו עתה בארץ כנען ולמה לא יאמר שלא יראו את עצמן שבעים בפני בני ארץ כנען ואולי היו בני ישמעאל ובני עשו באים מארץ אחוזתם אל יוסף לשבור והיו באים דרך ארץ כנען עוברים עליו ואמר להם שלא יראו עצמן שבעים בפניהם כי יחשדוהו שיש ליעקב תבואה ויבואו אליו לאכול עמו לחם בביתו ואם כן מה שאמר ונחיה ולא נמות טעם אחר הוא הזהירם להיות נשמרים במעט אשר בידם ושילכו לקנות ממנו שלא ימותו כאשר יתום הלחם אשר בידם והנכון למה תתראו במקום הזה כי היה לכם ליסע מיד כאשר שמעתם שיש שבר במצרים כי כבר בסכנה היו אם לא ימהרו לדבר וזה טעם ונחיה ולא נמות
@1259 **הוא המשביר לכל עם הארץ** . איננו ראוי שיהיה השליט על הארץ משנה למלך מצרים מוכר לכל אחד סאה או תרקב מן התבואה ולכן נתעוררו בזה רבותינו ואמרו (ב"ר צא ו) שצוה לסתום כל האוצרות חוץ מאחד בעת ההיא ועל דרך הפשט יתכן שהיו באים לפניו מכל הארצות והוא שואל וחוקר עליהם ומצוה לפקידים תמכרו לאנשי עיר פלונית כך וכך תבואה ממין פלוני והוצרכו בני יעקב לבא לפניו בתוך הבאים מארץ כנען לצוות עליהם כמה ימכרו לארצם כי הם ראשונים לאשר באו מארץ כנען והם באו לפניו בעבור כולם
@1260 **וירא יוסף את אחיו ויכירם** . מיד שראה אותם הכירם ופחד אולי יכירוהו ויתנכר אליהם ששם המצנפת על מצחו וקצת הפנים ושנה עצמו כמו שנאמר באשת ירבעם (מלכים א יד ב) קומי נא והשתנית ולא ידעו כי את אשת ירבעם וכתיב (שם פסוק ה) ויהי כבואה והיא מתנכרה או יהיה ויתנכר בכאן שהתנכר להם בדבריו שדבר להם קשות ואמר להם בכעס כאילו לא יבא אדם לפניו לשבר מאין באתם לפני ויאמרו מארץ כנען לשבור אוכל וכאשר הזכירו לו זה אז נתברר לו שהם אחיו באמת וזה טעם ויכר יוסף פעם שנית כי נתוסף לו בהם היכר וידיעת אמת ורש"י כתב נעשה להם כנכרי בדברים לדבר אתם קשות ועל דעתו יהיה ויתנכר לומר שדבר כאיש נכרי ואיננו נכון
@1261 **והם לא הכירוהו** . כלל ולא הוצרך עוד להתנכר אליהם ואמרו רבותינו (יבמות פח) בטעם ההכרה לפי שהניחם חתומי זקן והם לא הכירוהו שיצא מאצלם בלא חתימת זקן ועכשיו מצאוהו בחתימת זקן והנה יששכר וזבולון אינם גדולים מיוסף רק מעט אבל כיון שהכיר את הגדולים הכיר את כולם ועוד היה מכירם מדעתו שיבאו שם והם לא הכירוהו שלא נתנו לבם שיהיה העבד אשר מכרו לישמעאלים הוא השליט על הארץ ואמר רבי אברהם ויכירם בתחלה הכיר שהם אחיו ואחרי כן הסתכל בכל אחד והכירו
@1262 **ויזכר יוסף את החלומות אשר חלם להם** . עליהם וידע שנתקיימו שהרי השתחוו לו לשון רש"י ולפי דעתי שהדבר בהפך כי יאמר הכתוב כי בראות יוסף את אחיו משתחוים לו זכר כל החלומות אשר חלם להם וידע שלא נתקיים אחד מהם בפעם הזאת כי יודע בפתרונם כי כל אחיו ישתחוו לו בתחילה מן החלום הראשון והנה אנחנו מאלמים אלומים כי "אנחנו" ירמוז לכל אחיו אחד עשר ופעם שנית ישתחוו לו השמש והירח ואחד עשר כוכבים מן החלום השני וכיון שלא ראה בנימן עמהם חשב זאת התחבולה שיעליל עליהם כדי שיביאו גם בנימין אחיו אליו לקיים החלום הראשון תחילה ועל כן לא רצה להגיד להם אני יוסף אחיכם ולאמר מהרו ועלו אל אבי וישלח העגלות כאשר עשה עמהם בפעם השניה כי היה אביו בא מיד בלא ספק ואחרי שנתקיים החלום הראשון הגיד להם לקיים החלום השני ולולי כן היה יוסף חוטא חטא גדול לצער את אביו ולהעמידו ימים רבים בשכול ואבל על שמעון ועליו ואף אם היה רצונו לצער את אחיו קצת איך לא יחמול על שיבת אביו אבל את הכל עשה יפה בעתו לקיים החלומות כי ידע שיתקיימו באמת גם הענין השני שעשה להם בגביע לא שתהיה כוונתו לצערם אבל חשד אולי יש להם שנאה בבנימין שיקנאו אותו באהבת אביהם כקנאתם בו או שמא הרגיש בנימין שהיה ידם ביוסף ונולדה ביניהם קטטה ושנאה ועל כן לא רצה שילך עמהם בנימן אולי ישלחו בו ידם עד בדקו אותם באהבתו ולזה נתכוונו בו רבותינו בבראשית רבה (צג ט) אמר רבי חייא בר' אבא כל הדברים שאתה קורא שדיבר יהודה בפני אחיו עד שאתה מגיע ולא יכול יוסף להתאפק היה בו פיוס ליוסף פיוס לאחיו פיוס לבנימין פיוס ליוסף ראה היאך נותן נפשו על בניה של רחל וכו' וכן אני אומר שכל הענינים האלה היו ביוסף מחכמתו בפתרון החלומות כי יש לתמוה אחר שעמד יוסף במצרים ימים רבים והיה פקיד ונגיד בבית שר גדול במצרים איך לא שלח כתב אחד לאביו להודיעו ולנחמו כי מצרים קרוב לחברון כששה ימים ואילו היה מהלך שנה היה ראוי להודיעו לכבוד אביו ויקר פדיון נפשו ויפדנו ברוב ממון אבל היה רואה כי השתחויית אחיו לו וגם אביו וכל זרעו אתו אי אפשר להיות בארצם והיה מקוה להיותו שם במצרים בראותו הצלחתו הגדולה שם וכל שכן אחרי ששמע חלום פרעה שנתברר לו כי יבאו כלם שמה ויתקיימו כל חלומותיו
@1262 "ויאמר אליהם מרגלים אתם" - העלילה הזאת יצטרך להיות בה טעם או אמתלא כי מה עשו להיות אומר להם ככה וכל הארץ באו אליו והם בתוך הבאים כמו שאמר לשבור בתוך הבאים כי היה הרעב בארץ כנען ואולי ראה אותם אנשי תואר ונכבדים לבושי מכלול כולם ואמר להם אין דרך אנשים נכבדים ככם לבא לשבור אוכל כי עבדים רבים לכם ויתכן שהיו בתחילת הבאים מארץ כנען והוא טעם ויבאו בני ישראל לשבור בתוך הבאים כי היה הרעב בארץ כנען כי עתה באו משם הראשונים ויאמר להם יוסף מרגלים אתם כי מארץ כנען לא בא אלי אדם לשבור אוכל וזה טעם מאין באתם שאמר להם בתחילה
@1264 **כלנו בני איש אחד נחנו** . יתכן לפרש הטענה הזאת כי אמרו מפני היותנו אחים בני איש אחד ולא נפרד זה מזה כי כן רצון אבינו באנו כלנו כאחד לשבר אוכל ולא שלחנו אחד ממנו עם עבדיו וכן היה הדבר כי למה ישלחם כולם אלא שאין רצונם להפרד זה מזה גם יתכן שעשו כן בעבור כובד הרעב שלא יגזלו מעבדיהם בדרך את השבר אשר יביאו ויתכן שאמרו לו כלנו בני איש אחד נחנו תוכל לחקור עליו כי הוא נודע בשערים בכבוד עשרו ורוב בניו ואם תשאל ותחקור תדע כי כנים אנחנו ואנשים צדיקים בני צדיק ולא מרגלים וטעם לא היו עבדיך מרגלים כי כנים אנחנו מנעורינו בכל דברינו לא היו עבדיך מרגלים מאז ועד עתה וכן (להלן פסוק לא) לא היינו מרגלים מעולם ורבותינו נתעוררו כמו שאמרנו ודרשו (ב"ר צא ו) שנכנסו בעשרה פתחים כדרך מרגלים ולכך העליל עליהם וטענה נכונה היא אבל לא הזכיר אותה הכתוב ועוד שאמרו לו בתחלה כלנו בני איש אחד נחנו והיא שמחייבת אותם ויתכן שמתחלה אמר להם נכנסתם בעשרה פתחים ועכשיו אתם נועדים במקום אחד ונקשרים יחדיו אין זה רק דרך מרגלים ואמרו לו בעבור היותנו אחים נאספנו יחד ואמר להם לא כי ערות הארץ באתם לראות כי אם אתם אחים היה לכם ליכנס בפתח אחד כאשר אתם עתה יחדיו אז אמרו כי האחד איננו והלכו לבקשו והכתוב לא יחוש להאריך בטעם הטענות
@1270 **ויאסף אותם אל משמר שלשת ימים** . עשה כן להפחידם ושיאמינו בו כי את האלהים הוא ירא ומפני מוראו מוציא אותם שלא ימותו אנשי ביתם ברעב וזה טעם ואתם לכו הביאו שבר רעבון בתיכם ועוד כי לא ישמעו להניח האחד רק להצלת כלם
@1274 **אשר ראינו צרת נפשו בהתחננו אלינו** . חשבו להם האכזריות לעונש גדול יותר מן המכירה כי היה אחיהם בשרם מתחנן ומתנפל לפניהם ולא ירחמו והכתוב לא סיפר זה שם או מפני שהדבר ידוע בטבע כי יתחנן אדם לאחיו בבואו לידם להרע לו וישביעם בחיי אביהם ויעשה כל אשר יוכל להציל נפשו ממות או שירצה הכתוב לקצר בסורחנם או מדרך הכתובים שמקצרים במקום אחד ומאריכים בו במקום אחר והנה ראובן ענה להם שכבר אמרתי אליכם בשעת מעשה שלא תחטאו בו כי ילד הוא ומפני נערותו חטא לכם וראוי לכם להעביר על חטאות נעוריו ועתה גם דמו עם האכזריות אשר אתם אומרים הנה נדרש או יהיה פירוש גם דמו אף על פי שלא הרגתם אותו ידרוש השם מכם דמו ונחשב לכם כאלו שפכתם דמו בהיותו נמכר לעבד עולם כי יתכן שמת בעבור היותו ילד שעשועים ולא נסה לעבוד ורבותינו דרשו (ב"ר צא ח) דמו ודם הזקן
@1278 **וטעם ולתת להם צדה לדרך** . כדי שלא יאכלו בדרך מה שקנו והנה הודיע להם זה כי בידם נתן הצדה דרך חסד כדי שיוכלו להביא את האח כי אמר אין דעתי להרע לכם אם יאמנו דבריכם
@1280 **ויפתח האחד את שקו** . אחד מהם פתח את שקו במלון לתת ממנו מספוא לחמורו והאחרים לא פתחו את שקיהם עד היותם עם אביהם כאשר אמר ויהי הם מריקים כי אולי היו האחרים לוקחים לחמוריהם תבן כי לא יאכלו כל משאם בדרך וזה האחד לא היה חמורו חזק והוצרך למספוא ומצא כספו בפי אמתחתו וכתב רש"י כי אמתחת הוא השק ואונקלוס תרגם טוענא והנראה מדעתו שהיו לכל אחד שק גדול ושקים קטנים להשוות משאם וכלל המשא יקרא אמתחת והנה אירע לאחד שמצא כספו בפי אותו השק שפתח ולא קרה לאחרים כן עד היותם מריקים את כולם והקרוב אלי כי אמתחת שק גדול יש לו שני צדדים הנקרא בלשון תלמוד (כתובות קי) מתראתא ובפי אחד מן הצדדין הושם הכסף לכולם ואירע לאחד שפתח הצד ההוא שהיה בו הכסף ולא לאחרים ונקרא אמתחת בעבור שימתח לצדדין
@1287 **ואת הארץ תסחרו** . שינו לו בדבר מפני השלום כדי שישמע אליהם לשלח אתם בנימין כי ברצונם מיד היו חוזרים לולי שאמר לא ילך בני עמכם וכן אמרו לו אחיכם האחד הניחו אתי ולא הגידו לו מאסרם ולא מאסר שמעון ויתכן שאמר להם יוסף ואת הארץ תסחרו ולא סיפרו הכתוב וטעמו שתביאו סחורה כרצונכם לקנות התבואה ולא אקח מכס סחורתכם כי איטיב לכם תחת בשתכם וכן שאול שאל האיש לנו ולמולדתינו (להלן מג ז) התנצלות לאביהם או כאשר אמרו לו כלנו בני איש אחד נחנו אמר להם לא כי באמת ערות הארץ באתם לראות והגידו לי אם אביכם חי ואם יש לכם עוד אח כי אחקור עליכם ואדע מה אתם ואז ענו שנים עשר אחים אנחנו בני איש אחד והוא בארץ כנען היום כי עודנו חי והקטן עמו והאחד איננו והוא מה שאמר יהודה (להלן מד יט) אדוני שאל את עבדיו לאמר היש לכם אב או אח וכן במקומות רבים יקצר במעשה או בסיפור כאשר הזכרתי (לעיל כד כב לא ז) ורש"י כתב תסחרו תסבבו וכל לשון סחורה וסוחרים על שם שמסבבים אחר פרקמטיא נראה שרצה הרב להזהר מזה שלא אמרו אלא שיהיו רשאים לסבוב הארץ ולשבור בר כרצונם תמיד ולא פירש כן (לעיל לד י) שבו וסחרוה ויסחרו אותה (שם פסוק כא)
@1290 **את שני בני תמית** . קיבל עליו באלה להביאו אל אביו כי אמר לו את שני בני תמית בהיות ענשך עלי אם לא אשיבנו אליך והוא כענין מה שאמר יהודה (להלן מג ט) וחטאתי לך כל הימים ואמר את שני בני והם היו ארבעה לאמר תחת האחד מבניך יהיה הכפל בבני והנה יעקב לא בטח בראובן כאשר בטח ביהודה כי יהודה גבר באחיו ועוד כי ראובן כבר פשע באביו ולא יבטח בו והכלל כי היתה עצת יהודה טובה להניחו לזקן עד שיכלה פת מן הבית (עיין תנחומא מקץ ח) כי אז ישמע והוא מה שאמר לו ונחיה ולא נמות גם אנחנו גם טפנו
@1305 **ושלח לכם את אחיכם אחר ואת בנימין** . נראה �ל דרך הפשט כי לא היה שמעון רצוי אביו בעבור דבר שכם ולכך לא אמר את שמעון בני ואת בנימין כי לא יזכרנו בשמו וכאשר עזבו במצרים ימים רבים אילו היה בביתו לחם לא שלח עדיין את בנימין וינחהו במצרים ורש"י כתב רוח הקדש נצנצה בו לרבות את יוסף ובבראשית רבה (צב ג) גם כן אמרו ושלח לכם את אחיכם זה יוסף אחר זה שמעון ונכון הוא כי נתן דעתו בעת התפלה להתפלל סתם גם על האחר אולי עודנו חי ולשון אחר דרשו שם בבראשית רבה אמרו רבי יהושע בן לוי פתר קריא בגליות ואל שדי יתן לכם רחמים לפני האיש זה הקדוש ברוך הוא שנאמר (שמות טו ג) ה' איש מלחמה וכתיב (תהלים קו מו) ויתן אותם לרחמים ושלח לכם את אחיכם אלו השבטים אחר ואת בנימין זה יהודה ובנימין ואני כאשר שכלתי בחורבן ראשון שכלתי בחורבן שני לא אשכל עוד זה לשונם ז"ל והכונה כי ירידת יעקב למצרים ירמוז לגלותינו ביד אדום כמו שאפרש (ריש פרשת ויחי) וראה הנביא הענין מתחלתו והתפלל סתם לשעה ולדורות והכתוב זה כפי מדרשם יש לו סוד גדול כי אמר ואל שדי במדת הדין יתן לכם רחמים שלפניו יעלה אתכם ממדת הדין למדת רחמים והמשכיל יבין
@1305 "ואני כאשר שכלתי שכלתי" - ואני עד שובכם אהיה שכול מספק כאשר שכלתי מיוסף ושמעון שכלתי מבנימין לשון רש"י והנכון שהוא אומר לא תוכלו להוסיף עלי שכול כי כבר שכלתי יתנחם מכל הבא עליו ביתרון כאבו על יוסף וכמוהו וכאשר אבדתי אבדתי (אסתר ד טז) כלומר כבר אני אבודה ואם ימיתני לא יוסיף עלי אבדון
@1309 **להתגולל עלינו** . מן ועמשא מתגולל בדם ( כ יב) ושמלה מגוללה בדמים (ישעיהו ט ד) כאדם שיהפוך מצד אל צד על חברו ולהתנפל עלינו כאדם שיתנפל ברצונו על חבירו מלוא קומתו ואונקלוס תרגם להתגולל לאתרברבא עלנא שינשא עלינו כשוא הים לגליו ולהתנפל לאיסתקפא לשים עלינו דברים שלא היו כי הדבר שאינו יקרא נופל כמו לא נפל דבר אחד (יהושע כג יד) ותרגום עלילות דברים (דברים כב יד) תסקופי מלין וכן תרגם יונתן תואנה (שופטים יד ד) תוסקפא וטעם ולקחת אותנו לעבדים ואת חמורינו כי ידאגו על חמוריהם לאמר הנה יקחו גם את חמורינו עם אמתחותיהם ולא נוכל לשלוח לביתנו בר וימותו כולם ברעב
@1311 **בי אדוני** . לשון בעיא ותחנונים הוא ובלשון ארמית בייא בייא לשון רש"י וזה דבר זר מאד לסמכו אל מלת לשון טורסי ואינה דומה אליה כי בייא כולה מלה לא תשתנה ולא יאמר ממנה בי ועוד שהמלה ההיא אינה לשון בעיא ותחנונים כמו שאמר הרב אבל היא לשון צעקה ותרעומת על שבר ועל עוות דבר כגון מלת אבוי בלשון קדש והיא ידועה בלשון ערב ירגילו אותה בקינותיהם כולן בפתחות הבי"ת ובלשון יון בייא הבי"ת רפא בשו"א יאמרו אותה על הדוחק והצער ובבראשית רבה סדר בראשית (יב ו) מהו סלו לרוכב בערבות ביה שמו (תהלים סח ה) אין לך כל מקום ומקום שאין לו ממונה על בייא שלו אגריקוס במדינה ממונה על בייא שלו אגרטוס במדינה ממונה על בייא שלו כך מי ממונה על בייא של עולמו הקב"ה רוצה לומר שבכל מקום יש איש ממונה על הצעקה ועל העוות והקב"ה ממונה על צעקת העשוקים בעולם הצועקים בייא ועוד לפנינו בפרשת ויגש אליו (ב"ר צג ו) אמר לו יהודה בייא אתה מעביר עלינו שכך אמרת לנו ואשימה עיני עליו זו היא השמת עין ובפרשת ויהי בשלח (כ י) שמא אני מעביר בייא על בריה ובפרשת וישמע יתרו (כז ט) נתמנה אדם ונטל טלית כל טורח ציבור עליו אם ראה אדם מעביר בייא על חברו או עובר עבירה ולא מיחה בו הוא נענש עליו ובפרשת אשה כי תזריע (עיין ערוך ערך ביאה) צווח אנא בייא עליכון וכן במקומות הרבה ואונקלוס שתרגם בי אדני בבעו רבוני לא שהוציא מלת בי מן בעו אבל רדף הענין שהוא בא בכל מקום בענין הבקשה ורבי אברהם אמר כי בי אדני דרך קצרה בלשון הקדש והוא כמו בי אני אדני העון והטעם עשה בי מה שתרצה ותשמעני ואם כן נכון הוא שיאמר אדם בי אחי או בי שמעני ולא מצאתי שתבא מלת בי רק עם אדני או עם השם הנכבד הנכתב באל"ף דלי"ת שגם הוא לשון אדון ולכן אני אומר שפירושו בי בעצמי אתה אדון ומושל ובאו שני כנויים לחזוק כמו ולי אני עבדך (מלכים א א כו) בי אני אדני (שמואל א כה כד) ודומה לזה כי בי בעזרך (הושע יג ט) בי עזרך בעזרך אני
@1314 **נתן לכם מטמון באמתחותיכם** . אמר רבי אברהם יתכן שהיה לאדם מטמון בביתו ושכחו ויצא בגורלכם כי כספכם בא אלי והנה הם דברי נחומים כי איך יצא לכל אחד כספו במשקלו אבל כל דבר מכוסה יקרא מטמון טמן עצל ידו בצלחת (משלי יט כד) יש לנו מטמונים בשדה (ירמיהו מא ח) והנה אמר להם כי דרך החמרים לוקחי התבואה לשום כל אחד כספו בשקו והנה המשביר לקח מן הבאים שקיהם ומלא עשרה שקים שבר והכסף טמון תחת התבואה ובא אדניו וצוה אליו לשפכם אל כלי בני יעקב כי רצה למהר לשלחם או מפני שלא בא הכסף אליו והנה לכל אחד בפי אמתחתו כספו במשקלו כי כל איש יביא בדמיו כסף שוה חמור לחם וזה יקרה תמיד בשוקים ובאוצרות הנמכרים ברוב מהומות העם
@1326 **כאשר יוכלון שאת** . יותר מן המגיע להם בכסף אשר הביאו לו
@1326 "ושים כסף איש בפי אמתחתו" - לדעתם כי אמר להם ידע אדני כי עשה לכם חמס ויבקש להטיב לכם שאם עשה זה כפעם הראשונה שלא לדעתם היה להם התנצלות בגביע שנעשה בו כאשר נעשה בכסף אבל היה לדעתם וידעו בכסף כאשר ידעו במשא כי הכירו כי נתן להם כאשר יוכלון שאת ואם היה שלא לדעתם אולי טען עליהם כי היה הכסף גם בפעם הזאת מטמון ולא יתכן כן בגביע ומי יוכל לדון עם שתקיף ממנו ודע כי בעבור היות השוברים רבים מאד מכל ארץ מצרים ומהומות רבות בתוכה היו הבאים נותנין שקיהם וכספיהם למשביר והוא מודד להם לפי הכסף הנמצא בהם והם לוקחים הניתן להם באשר דבר מלך שלטון ועוד כי באמונה הוא עושה ועל כן לקחו בפעם הראשונה שקיהם סגורים ולא ידעו מה בתוכם גם בשנית
@1330 **הלא זה אשר ישתה אדני בו** . לא הזכיר להם הגביע אבל דבר עמהם כאלו בידוע שהם לקחו הגביע ולכך אמר הלא זה שלקחתם הוא אשר ישתה אדני בו גם הם ענו כאילו אינם יודעים מה מבקש ואיך נגנב מבית אדוניך כסף או זהב ואמרו אשר ימצא אתו מעבדיך כסף או זהב גנוב ומת וטעם אשר ישתה אדני בו עלילה להגדיל עליהם האשם כי הגונב כוס המלך אשר ישתה בו בוזה המלכות ולא יועיל כי ירבה שחד ותשלומין והוא נחש ינחש בו כי איננו רוצה שיהיה הכוס שלו לאחרים וישאל למנחשים עליו וזהו שאמר איש אשר כמוני וכוונתו לומר כי על פי המנחשים ידע שהם גנבוהו ולכך רדף אחריהם יותר מכל הבאים בביתו וכל זה להתנכר בענין כאשר התנכר בחפשו שהחל בגדול ובקטן כילה
@1335 **גם עתה כדבריכם כן הוא** . אף זו מן הדין אמת כדבריכם כן הוא שכלכם חייבין בדבר עשרה שנמצאת גנבה ביד אחד מהן כלן נתפשין אבל אני אעשה לכם לפנים מן השורה אשר ימצא אתו בלבד יהיה לי עבד לשון רש"י ואין לשון "גם עתה" נופל יפה על הפירוש הזה ואולי יאמר גם עתה שכדבריכם כן הוא המשפט אשר ימצא אתו יהיה לי עבד בלבד אבל יוסף אמר חלילה לי מעשות זאת ויורה כי אין משפטם שיהיו כלם נתפשין בגנבה ולכן אמר חלילה לי כי שופט כל הארץ אני וחלילה לי מעשות לכם חמס כי אין חיוב בעשרה בהמצא גנבה ביד אחד מהם בלתי אם נועדו בה בהוסדם יחד ללכת לגנוב ולקח אחד מהם את הגנבה לדעת כולם אז יתחייבו והנכון כי מתחילה היה מאשים את כולם למה שלמתם רעה תחת טובה הרעותם אשר עשיתם והם פטרו עצמם באמרם אשר ימצא אתו ומת כי הוא הגנב וגם אנחנו הנקיים מן הגניבה נהיה לעבדים הנה דעתם לומר שהגנב אשר ימצא אתו הוא לבדו היודע בגנבה כי אם היו כולם בגנבה למה ימות זה ויחיו הם ראוי שימותו כולם או יהיו כולם עבדים כי הדין בהם שוה אבל הם טוענים שלא ידעו האחרים בגנבה רק קנסו את עצמם שיהיו גם הם לעבדים ולכן אמר להם גם עתה שאתם נועדים ונמצאים יחדיו כדבריכם כן הוא אשר ימצא אתו הוא הגנב והוא לבדו הראוי להענש ויהי לי עבד כי בתשלומיו אני חפץ יותר ממיתתו ואתם תהיו נקיים כי אולי לא ידעתם בגנבה כאשר אמרתם או טעם כן הוא כן יהיה גם עתה שאין כן המשפט כדבריכם כן יהיה וכמהו ותאמר כדבריכם כן הוא ותשלחם וילכו (יהושע ב כא) טעמו כן יהיה והוא הנכון בעיני והוא דברי רבותינו בבראשית רבה (צב ח) שאמרו עשרה בני אדם שנמצאו בגנבה אין כולם בסירה אני איני עושה כן וכו' נתכוונו למה שפירשתי לא כדברי רש"י ונוכל לתקן לדעת הרב שאמר יוסף חלילה לי מעשות זאת שאהיה לכם אני רע מאשר על ביתי שפטר אתכם מתחילה ואמר לכם ואתם תהיו נקיים כי אני אקים דבר עבדי ועצת מלאכי אשלים חסלת פרשת מקץ
@1343 **ידבר נא עבדך דבר** . לאמר כי דברים מועטים ידבר לא יהיו עליו לטורח והנכון בעיני כי "דבר" הוא התמורה אשר יחלה פניו להחליף בנימין אחיו בו כי לא יבקש ממנו דבר אחר ושאר דבריו פיוס ובקשה לזה
@1343 "ואל יחר אפך בעבדך" - יאמר אל יחר אפך בי על דברי לפניך
@1343 "כי כמוך כפרעה" - ובמורא גדול אני מדבר לפניך כאלו אני מדבר לפני פרעה
@1344 **אדני שאל את עבדיו** . לא ידעתי טעם לאריכות דברי יהודה בספור מה שהיה כבר ביניהם ומה שאמרו רז"ל (ב"ר צג ו) וכי זו היא שימת עין שאמרת לשום עינך עליו אינה טענה כי המושל שיצוה להביא אדם לפניו לא יעשה על מנת לפטור אותו מן הרעות שיעשה וכל שכן על הגנבה שיגנוב מבית המלך הגביע אשר ישתה בו ומתחלה כבר שם עינו עליו לטובה וקרא לו שלום בדבר אלהים יחנך בני (לעיל מג כט) ועשה לכולם לכבודו משתה לפניו בבית המלכות והרבה משאות להם ונתן להם בר כאשר יוכלון שאת יותר מן הכסף שהביאו לו כאשר פירשתי (לעיל מד א) ומה לעשות לו ואשר יראה לי על דרך הפשט שאינם רק תחנונים להעיר רחמיו כי חשב יהודה כי האלהים הוא ירא כאשר אמר לו וכאשר נהג עמהם חמלה כירא חטא לנחם אותם על הצער שעשה להם (לעיל מג כג) וזה ענין הסיפור אמר לו אנחנו באונס הגדנו באחינו זה מפני שאלת אדני ולא הודינו גם כן להורידו לפניך כמצותך הראשונה רק אמרנו כי לא יוכל הנער לעזוב את אביו אבל בנפשינו נביא אותו מפני זלעפות רעב כי אמרת לא תוסיפון לראות פני לא רצה אבינו לשמוע עד היותינו כולנו בסכנה לשוב לשבר מעט אכל ואז הודה בפחד ובדאגה ועתה כראותו כי אין הנער ימות בנפש מרה ולכן תפול נא תחנתי לפניך לרחם עלינו ועל הזקן וקח אותי תחת הנער לעבד עולם כי טוב אני ממנו ולך תהיה צדקה וזה טעם כל הפרשה ויתכן שיהיה והורידו עבדיך את שיבת עבדך אבינו כנוי לכבוד והורדת את שיבת עבדך אבינו וכן וחטאת עמך (שמות ה טז) ויש לומר עוד על דרך רבותינו שאמרו זו היא השמת עין יאמר כי כמוך כפרעה ראוי שתעמד בדבורך ובתיורך כי על פיך הבאנו אותו באונס גדול כאשר יזכיר ופחד לפרש לו יותר אבל יש בסתר דבריו שהיה מעשה הגביע תחבולה מאתו להעלילם כי למה יבקש לראותו על כרחם וכך אמרו בבראשית רבה (צג ח) אמר לו יהודה תדע לך שבעלילה באת עלינו כמה מדינות ירדו ליקח אוכל כלום שאלת אותם כמו ששאלת לנו שמא בתך אנו מבקשים או אחותנו אתה מבקש יאמרו כי זה היה נרמז בדבריו
@1346 **ואשימה עיני עליו** . אמר רבי אברהם הטעם שאראה אותו ולא מצאתי בכתוב שימת עין על הראיה בלבד ושמתי עיני עליהם לטובה (ירמיהו כד ו) קחנו ועינך שים עליו ואל תעש לו מאומה רע (שם לט יב) כי לא צוה אותו שיראנו אחר שיקחנו אלא שישמור אותו ויטיב לו אבל נדר להם יוסף לחמול עליו ולשמרו ואם לא נזכר בפירוש כאשר יקצר שם בכל הדברים האלה אשר ספר יהודה בפניו ולא הזכיר מאסר שמעון ועלילת מרגלים אתם דרך מוסר או אימת מלכות
@1347 **ועזב את אביו ומת** . פירש רבי אברהם ומת אביו ואם כן היה אומר לא יוכל אבינו לעזוב את בנו ועזב את בנו ומת או לא נוכל שיעזוב הנער את אביו כי לא יתלו החמלה על אביהם בנער כי הם יחזיקוהו כילד לא ידע בין טוב לרע אבל פירוש לא יוכל הנער לעזוב את אביו מפני נערותו והיותו ילד שעשועים בחיק אביו אשר אהבו ואם יעזבנו ויבא בדרך ימות הנער
@1349 **כי עלינו אל עבדך אבי ונגד לו את דברי אדני** . אמר כי בבואם אליו מיד הגידו לו שלא יוסיפו לראות פניו בלא אחיהם הקטן ולא אבה לשלחו והיה מניח לו שמעון במאסרו וזה טעם ויאמר אבינו שובו שברו לנו מעט אוכל כי לא רצה להודות לשלחו בכל אשר אמרנו עד שדחקו הרעב
@1352 **אתם ידעתם כי שנים ילדה לי אשתי** . אם יאמר שהוא יחיד לאמו מה טעם בזה שתרד שיבתו ברעה שאולה אחרי שיש לו כמה בנים רבים ובני בנים ואמו כבר מתה לא תבכה עליו בפניו אבל הטעם כי יעקב לא לקח אשה מדעתו רק רחל וזה טעם ילדה לי "אשתי" כי לא נולדו לי מאשה אשר היא אשתי ברצוני רק שנים ושמתי אהבתי בהם כאלו הם יחידים לי והשאר כבני פילגשים הם אלי ואחיו מת וזה לבדו בני יחידי אשר אהבתי ולכן יקדים הכתוב רחל ללאה כרחל וכלאה אשר בנו שתיהם את בית ישראל (רות ד יא) ויקרא לרחל וללאה השדה (לעיל לא ד) כי היא הקודמת במחשבתו ואמרו המפרשים כי לכך יאמר בסדר הזה (להלן מו יט) בני רחל אשת יעקב כי היא תקרא אשתו באמת בלא מרמה ולדעתי היה זה מפני שהזכירה שם בין השפחות וכבר הזכרתי כן (לעיל לא לג)
@1354 **וקרהו אסון והורדתם את שיבתי** . אם יקראהו אסון כאחיו תורידו את שיבתי ברעה שאולה או וקרהו אסון שיקרנו כן מפני היותו נער ורך ולא נסה ללכת בדרך וכמו שאמר למעלה (מב ד) פן יקראנו אסון כי פירוש אסון מות מקרית כמתים בידי אדם וחיה רעה או בשנוי האויר בדרך
@1357 **כי עבדך ערב את הנער** . יאמר כי ירד ביגון שאולה עליו כי גם בכל זה שאמרנו לו לא רצה הזקן לשלחו עד שנעשיתי לו ערב עליו ובטח בי ועל כן ישב נא עבדך תחתיו ואם יהיה פירוש "והורידו עבדיך" כפשוטו יאמר אנחנו הגורמים מיתת הזקן ברעה כי אני ערבתי בו
@1359 **ואמר כי איך אעלה אל אבי** . להודיעו כי יבחר להיות עבד עולם מעלותו אל אביו בלתי הנער שלא יוכל לראות ברעתו כי יבכה תמיד ויתאונן עליו כל היום והזכיר זה שלא יחשוד אותו שיעשה מרמה בעבור שהוא ידע לברוח יותר מן הנער
@1360 **ולא יכל יוסף להתאפק לכל הנצבים עליו** . לא יכול לסבול שיהיו המצריים נצבים עליו ושומעין שאחיו מתביישין בהודעו להם לשון רש"י ורבי אברהם אמר להתאפק לסבול לכל הנצבים עליו טעמו עד שיצאו כל הנצבים עליו והוצרך לקרא להוציאם אבל אונקלוס תרגם לאתחסנא להתחזק וכן ואתאפק ואעלה העולה (שמואל א יג יב) וכן כל לשון התאפקות בכל מקום חזוק והנכון בעיני שהיו שם מבית פרעה ומן המצרים אנשים רבים יחלו פניו למחול לבנימין כי נכמרו רחמיהם על תחנוני יהודה ולא יכול יוסף להתחזק לכלם ויקרא לעבדיו הוציאו כל איש נכרי מעלי כי אדבר עמהם ויצאו מעליו ובצאתם מעליו נתן את קולו בבכי וישמעו מצרים ואנשי בית פרעה המוצאים מעליו כי עודם בחצר החיצונה ויתכן כי פירוש "הנצבים עליו" משרתיו העומדים לפניו כמו הנער הנצב על הקוצרים (רות ב ו) שרי הנצבים (מלכים א ה ל) להתיצב על ה' (איוב א ו) וטעם "ויקרא" שהרים קולו בכעס ואמר למשרתיו הוציאו כל איש מעלי בלתי האנשים האלה וטעם בהוצאה שהוציאם משם כדי שלא ישמעו בהזכירו להם המכירה כי תהיה להם (לחרפה) וגם אליו למכשול שיאמרו עבדי פרעה ומצרים עליהם אלו אנשי בוגדות לא יגורו בארצנו ולא ידרכו בארמנותינו בגדו באחיהם גם באביהם בגדו מה יעשו במלך ובעמו וגם ביוסף לא יאמינו עוד
@1365 **כי זה שנתים הרעב בקרב הארץ** . הזכיר להם מה שעבר וידעו גם הם לומר כי הארץ אשר עברו עליה שתי שנים ברעב ואכלו כל מה שהיה בידם ונתיקר השער מאד ועוד יעברו עליהם חמש שנים לא תהיה לכם בה מחיה כלל אם לא שלחני השם לפניכם
@1369 **וישבת בארץ גשן** . היה יוסף יודע באביו שלא ירצה לעמוד בארץ מצרים אשר שם הבירה למלכות על כן שלח לו מעתה כי בארץ גושן יושיבנו וטעם אתה ובניך מחובר בפסוק העליון רדה אלי אתה ובניך ובני בניך וצאנך ובקרך וכל אשר לך
@1370 **ואמר פן תורש אתה וביתך** . דרך כבוד כי לאחיו אמר כי למחיה שלחני אלהים לפניכם ולשום לכם שארית שהיו מתים ולא ישאר להם שארית אבל לאביו לא רצה לאמר כן ואמר שאם תתעכב בארץ כנען תורש כי אני לא אוכל לשלוח לך לארץ כנען לחם רב מגנזי המלך כי יחשדו אותי שאני מוכרו שם לעשות לי שם אוצרות כסף ולשוב אל ארצי ואל מולדתי ובבואכם וידעו כי אתם אבי ואחי יתן לי המלך רשות
@1371 **כי פי המדבר אליכם** . בלשון הקדש (בלי מליץ זה) דעת המפרשים (רש"י הראב"ע והרד"ק) והוא תרגום אונקלוס ויתכן שאמר להם כך לאמתלא ולפיוס כי איננה ראיה שידבר אדם אחד במצרים בלשון הקדש כי על דעתי הוא שפת כנען כי אברהם לא הביאו מאור כשדים ומחרן כי ארמית היא והגל הזה עד ואיננו לשון לאיש אחד לבד אבל הוא לשון כנען ורבים במצרים יודעים אותו כי קרוב הוא ואף כי המושל שדרך המלכים והמושלים לדעת הלשונות וכמו שתראה בנבוכדנצר שאמר בלשון הקדש (דניאל ב ג) חלום חלמתי ותפעם רוחי לדעת את החלום בעבור שהיו שם חרטומים ואשפים ומכשפים וכשדים מלשונות רבים ומישראל וכולם יבינו אותו והם ענו לו בארמית וידברו הכשדים למלך ארמית כי הם היו הקרובים אליו היושבים ראשונה במלכות ולהם היה הרשות לדבר אל המלך ועוד כי כאשר בא יוסף משם למצרים יבאו רבים ויותר היה להם ראיה בהזכירו שמו וענין המכירה אני יוסף אחיכם אשר מכרתם אותי מצרימה והנכון בעיני כי יאמר והנה עיניכם רואות ועיני אחי בנימן כי אני המושל והאדון לכל מצרים המגיד לכם מפי כי אני אחיכם ומצוה להוריד אבי אלי לכלכלו אם כן תגידו לאבי את כל הכבוד ואת כל אשר ראיתם בעיניכם ותמהרו להורידו אלי כי הדברים אמת ויש בי כח להצילו ולהחיותו ברעב והוא כמו כי פי אני דברתי ובגמרא במסכת מגילה (טז) אמרו כפי כן לבי
@1375 **וטעם באו אחי יוסף** . כי היה יוסף מגיד לבית פרעה כי יש לו אחים נכבדים בארץ העברים כי גנב גונב משם ועתה שמעו כי באו אחי יוסף כאשר אמר
@1375 "וייטב בעיני פרעה ובעיני עבדיו" - כי היה הדבר להם לחרפה שימשול בהם איש נכרי עבד מבית האסורים יצא למלוך ועתה בבוא אליו אחים נכבדים ונודע כי הוא הגון להתיצב לפני מלכים שמחו כולם בדבר
@1378 **ואתה צויתה זאת עשו** . אמר הדבר בצואה לו מדעתו מוסר יוסף כי איננו שולח יד בהון המלך ולא ידע אתו מאומה על כן חשב פרעה אולי לא ירצה לשלוח לאביו דבר על כן אמר לו אני מצוה אותך שתעשה זאת על כל פנים
@1382 **ולאביו שלח כזאת** . כחשבון הזה ומהו החשבון עשרה חמורים וגו' לשון רש"י ואיננו נכון שירמוז על החשבון אבל יתכן שיאמר כזאת המנחה ויהי שעורו ולאביו שלח זאת המנחה עשרה חמורים וגו' והכ"ף כאילו יתירה רק דרך הלשון לדבר כן כמו ותדבר אליו כדברים האלה עשה לי עבדך (לעיל לט יט) או יאמר ולאביו שלח צידה כצידה הזאת אשר נתן לאחיו ולא להשוותן רק כאשר נתן להם צידה לדרך בלכתם כן שלח לאביו בר ולחם ומזון לדרך בבואו והוא הנכון והזכיר חמורים ואתונות כי המשא ונושא המשא הכל שלח לו והמנהג לשלוח זכרים ונקבות כאשר עשה אביו (לעיל לב טז)
@1383 **אל תרגזו בדרך** . רגז לשון רתת ותנועה ויאמר בבאו מן הפחד על הרוב לב רגז (דברים כח סה) ורגזו וחלו (שם ב כה) ותחתי ארגז (חבקוק ג טז) ומימיך ברגזה ובדאגה תשתה (יחזקאל יב יח) ולכן הנכון בעיני בפסוק הזה שאמר להם יוסף אל תפחדו בדרך והענין כי בעבור נשאם בר ולחם ומזון וטוב מצרים בימי הבצרות יפחדו אולי בדרך בלכתם יבואו עליהם לסטים וכל שכן בשובם עם כל רכושם ולא ימהרו לדבר ולכן אמר להם שילכו בזריזות וימהרו לבא כמו שנאמר (בפסוק ט) מהרו ועלו אל אבי ואל יפחדו כלל בדרך כי שמו עליהם שהוא המושל בכל ארץ מצרים וחיי כל הארצות ההם בידו וממוראו ייראו הכל וילכו ויבאו לשלום
@1385 **ויפג לבו** . נחלף לבו והלך מלהאמין לא היה לבו פונה אל הדברים לשון מפיגין טעמן לשון משנה (גמ' ביצה יד) וכמו מאין הפוגות (איכה ג מט) וריחו לא נמר (ירמיהו מח יא) מתורגם וריחיה לא פג לשון רש"י ואיננו נכון כי לשון פוגה שביתה וביטול כמו אל תתני פוגת לך (איכה ב יח) וכן עיני נגרה ולא תדמה מאין הפוגות (שם ג מט) שנגרה תמיד מאין שביתה והפסק וכן מפיגין טעמן שמפזרין אותו ומתבטל וכן על כן תפוג תורה (חבקוק א ד) תבטל ותפסק וגם זה ויפג לבו שנתבטל לבו ופסקה נשימתו כי פסקה תנועת הלב והיה כמת וזה הענין ידוע בבוא השמחה פתאום והוזכר בספרי הרפואות כי לא יסבלו זה הזקנים וחלושי הכח שיתעלפו רבים מהם בבוא להם שמחה בפתע פתאום כי יהיה הלב נרחב ונפתח פתאום והחום התולדי יוצא ומתפזר בחיצוני הגוף ויאפס הלב בהתקררו והנה נפל הזקן כמת ואמר כי לא האמין להם להגיד שעמד זמן גדול מן היום והוא שוכב דומם בעבור שלא האמין להם כי הידוע בעלוף הזה שיצעקו לו וירגילו אותו בשמחה ההיא עד שתקבע בו בנחת רוח וזה טעם וידברו אליו את כל דברי יוסף אשר דבר אליהם וירא את העגלות כי היו צועקים באזניו דברי יוסף ומביאים לפניו העגלות אז שבה רוחו אליו וחזרה נשימתו וחיה וזהו ותחי רוח יעקב אביהם ואונקלוס תרגם ושרת רוח נבואה בעבור שהדבר אמת הוסיף זה ודרש כן במלת רוח שלא אמר "ויחי יעקב אביהם" ועשאו מענין רוח ה' אלהים עלי (ישעיהו סא א) ועתה ה' אלהים שלחני ורוחו (שם מח טז) איש אשר רוח בו (במדבר כז יח)
@1386 **וידברו אליו את כל דברי יוסף** . יראה לי על דרך הפשט שלא הוגד ליעקב כל ימיו כי אחיו מכרו את יוסף אבל חשב כי היה תועה בשדה והמוצאים אותו לקחוהו ומכרו אותו אל מצרים כי אחיו לא רצו להגיד לו חטאתם אף כי יראו לנפשם פן יקצוף ויקללם כאשר עשה בראובן ושמעון ולוי (להלן מט ג-ז) ויוסף במוסרו הטוב לא רצה להגיד לו ולכך נאמר ויצוו אל יוסף לאמר אביך צוה לפני מותו לאמר וגו' ואלו ידע יעקב בענין הזה היה ראוי להם שיחלו פני אביהם במותו לצוות את יוסף מפיו כי ישא פניו ולא ימרה את דברו ולא היו בסכנה ולא יצטרכו לבדות מלבם דברים
@1388 **ויזבח זבחים לאלהי אביו יצחק** . חייב אדם בכבוד אביו יותר מכבוד זקנו לפיכך תלה ביצחק ולא באברהם לשון רש"י ואיננו מספיק שהראוי לומר לאלהי אבותיו בלי שייחד אדם כמו שאמר האלהים אשר התהלכו אבותי לפניו אברהם ויצחק (להלן מח טו) ובתפלתו אמר אלהי אבי אברהם ואלהי אבי יצחק (לעיל לב י) או יאמר ויזבח זבחים לה' כמו שאומר באברהם (לעיל יב ז) ויבן מזבח לה' ומה צורך לפרש בו יותר אבל הפסוק הזה יש בו סוד יגלו לנו אותו שם בבראשית רבה (צד ה) כי כאשר בא יעקב לרדת מצרים ראה כי הגלות יתחיל בו ובזרעו ופחד ממנו וזבח זבחים רבים לפחד אביו יצחק שלא תהא מדת הדין מתוחה כנגדו ועשה זה בבאר שבע שהוא בית תפלה לאבותיו ומשם נטל רשות בלכתו לחרן ואמר הכתוב זבחים להודיע שלא היו עולות כאבותיו כי אברהם עולות הקריב ורבותינו אמרו (זבחים קטז) לא הקריבו בני נח שלמים עולות הקריבו ובנח כתוב מפורש (לעיל ח כ) ויעל עולות במזבח אבל יעקב מפני פחד ה' הקריב שלמים להשלים אליו כל המדות כמו שדרשו (תורת כהנים ויקרא טז א) שלמים שמטילין שלום בעולם והנה היתה תחלת כונתו במדת הגבורה שהיא הקרובה אליו וזהו הטעם שהזכירו בבראשית רבה (צד ה) שחייב אדם בכבוד אביו יותר מכבוד זקנו והוא הטעם שאמרו שם בלשון אחר בתחילה שואלין בשלום התלמיד ואחר כך שואלין בכבוד הרב וראיתי במדרשו של רבי נחוניא בן הקנה (ספר הבהיר קלה) בלשון הזה וישבע יעקב בפחד אביו יצחק (לעיל לא נג) וכי יש אדם שנשבע כך באמונת פחד אביו אלא עדיין לא נתן ליעקב כח ונשבע בכח שנתן לאביו שנאמר וישבע יעקב בפחד אביו יצחק ומאי ניהו הוא דכתיב ביה (מלכים א יח לח) ותפול אש ה' ותאכל את העולה וכתיב (דברים ד כד) כי ה' אלהיך אש אוכלה הוא וגו' עד כאן במדרש ומדבריהם נלמוד שמפני כן לא אמר ויזבח זבחים לה' לפי שעתה כבר זכה יעקב בחלקו שנאמר (מיכה ז כ) תתן אמת ליעקב חסד לאברהם אשר נשבעת לאבותינו מימי קדם והוצרך לפרש עתה והנה בזכות הקרבנות נראה אליו אלהי יצחק אביו במראות הלילה במדת הדין רפה זהו שאמר אלהים במראות הלילה והוא מה שאמר אנכי האל אלהי אביך כי הוא האל בית אל אשר אמר לו בחרן אנכי האל בית אל אשר משחת שם מצבה (לעיל לא יג) והוא אלהי אביך הוא השם והיא המדה והבטיחו שלא יירא במצרים כי יזכה בדינו ויגאל אחר הענוי וזהו טעם ואנכי אעלך גם עלה וכתב הרב בפרק כז בחלק הראשון במורה הנבוכים כי תרגום אנכי ארד עמך מצרימה ואנכי אעלך גם עלה אנא איחות עמך ואנא אסקינך ונפלא הרב בזה על דעת אונקלוס ואמר כי אונקלוס שם כל מאודו להרחיק הגשמות בכל סיפור אשר בתורה וכל אשר ימצא מאלו השמות המורים על מין ממיני התנועה ישים ענין התנועה לכבוד נברא או לשמירה מהאל ומתרגם וירד ה' (שמות יט כ) ואיתגלי ה' ארדה נא ואראה (לעיל יח כא) איתגלי כען ואיחזי ואם כן למה תרגם כאן אנא איחות ופירש הרב כי בעבור שאמר בתחלת הענין ויאמר אלהים לישראל במראות הלילה לא היה קשה לאונקלוס לספר המאמר כאשר נאמר במראות הלילה כי הוא סיפור אמירה לא סיפור מעשה שהיה כי יש הפרש גדול בין מה שיאמר בחלום או במראה הלילה ובין מה שיאמר במחזה ובמראה ובין מה שיאמר בדבר מוחלט ויהי דבר ה' אלי לאמר או ויאמר ה' אלי לאמר אלו דבריו וכן אמר (הרמב"ם במו"נ א מז) שהרחיק אונקלוס השמיעה בכל מקום וישים פירושה הגעת הדבר ההוא לבורא או קבול תפלה ויתרגם שמיע קדם ה' (לעיל כט לג) וקבלא אקביל קבילתיה (שמות כב כב) ואם כן הדבר כדברי הרב למה יברח אונקלוס מן התנועה וירחיק השמיעה גם כן מיראתו שתורה על גשמות ולא יברח מן האמירה והדבור ולא מן הקריאה בשום מקום בין בחלום בין במראה בין במאמר מוחלט כי בכולם יתרגם ואמר ה' ומליל ה' וקרא ה' למשה והיא גם היא תורה על גשמות והיה לו לתרגם ויתאמר מן קדם ה' או ואמר יקרא דה' או ויתרעי ה' כפי הראוי בענין כמו שפירש הרב בדיבור ובאמירה (מו"נ א סד) ולמה ירחיק בשמיעה ולא ירחיק הראיה שתרגם אותה וחזא ה' ואשר אמר הרב (שם מז) כי יורה על ענין השגת שכל כאשר יורה על השגת העין כל שכן שהוא זה בשמיעה כי היא תאמר על ההשגה בשכל וברצון ברוב מקומות כגון וישמע אברם לקול שרי (לעיל טז ב) שמע קול תחנוני (תהלים כח ב) גם כי תרבו תפלה אינני שומע (ישעיהו א טו) הנה שמוע מזבח טוב (שמואל א טו כב) והיה אם שמוע תשמע בקול ה' אלהיך (דברים כח א) וכן לב שומע (מלכים א ג ט) וכן רובם והנה אונקלוס לא היה לו לירא מן השמיעה שלא תורה רק על קבלת הדבר והרצון בו ולא ברח מן הראיה בשום מקום אבל תרגם אותה כפשוטה בכל מקום שהדבר מושג בראיה בלבד אבל כאשר איננו מושג בראיה בלבד והוא צריך השגחה והתבוננות יתרגם כפי הראוי בו כאשר אמר (לעיל כט לב) כי ראה ה' בעניי ראה ראיתי את עני עמי (שמות ג ז) וירא אלהים את בני ישראל (שם ב כה) שאין הראיה בהם שיראה את גופם אבל שישגיח בענינם וידע אותו וזה דרכו בכל התורה לא כטעם שעלה בדעת הרב ונשתבש בידו והשני מקומות האחרים שתרגם אותם (לעיל ו יב כט לא) וחזא אליו ולא השלים אותו ובלשון העברה כנה אונקלוס ותרגם ויעבר ה' על פניו (שמות לד ו) ואעביר ה' שכינתיה על אפוהי שיהיה הדבר העובר נברא לדעתו ולא יזכיר לשון תנועה בבורא כפי מה שהזכיר הרב ואם כן איך תרגם ה' אלהיך הוא עובר לפניך (דברים לא ג) ה' אלהיך הוא עבר קדמך והנה זה מין תנועה בספור מעשה ולא ירא ממנו אונקלוס וכן בפסוק וירא ישראל את היד הגדולה (שמות יד לא) תרגם בו וחזא ישראל ית גבורתא ידא רבתא נופל בו הגבורה מפני לשון אשר עשה והשאיר בו ידא רבתא ולא היה ירא ומתפחד מן היד ולא יכנה אותה כלל וכן נהג בתרגום כתובים באצבע אלהים (שם לא יח) באצבעה דה' ומה שתירץ בו הרב (במו"נ א סה) כי ישים אונקלוס האצבע כלי נברא אשר פתח הלוחות בחפץ הבורא איננו אמת כי הנה מימינו אש דת למו (דברים לג ב) כתב ימיניה ולא פחד מן הימין הכותבת שתורה על גשמות וכן מן האצבע ועוד תרגם (שמות טו יב) ארימת ימינך ואמר (שם פסוק ו) ימינך ה' תברת שנאה ותרגם ידך החזקה (דברים ג כד) ית ידך תקיפא ואמר (שם ד לד) בידא תקיפא ובאדרעא מרממא וכן ותאחז במשפט ידי (שם לב מא) ותתקיף בדינא ידי וכן תרגם (שם יא יב) תדירא עיני ה' אלהיך בה מרישא דשתא והנה ביעקב כתוב בתחילת הענין ויחלום והנה סולם מוצב ארצה וגו' (לעיל כח יב) ופחד אונקלוס ממנו ותרגם והא יקרא דה' מעתד עלוהי ולא תרגם והא ה' בעבור שהוא בחלום ותרגם והנה אנכי עמך (שם טו) והא מימרי בסעדך ולא אמר והא אנא עמך כמו שתרגם אנא אחות עמך ואף על פי שהוא ספור דבר שנאמר בחלום כמוהו בשוה ותרגם ואנכי אהיה עם פיך (שמות ד יב) ואנא אהי עם פומך ואמר בויאמר כי אהיה עמך וזה לך האות (שם ג יב) ארי יהא מימרי עמך ועוד נזהר אונקלוס בחלומות ותרגם ויבא אלהים אל אבימלך בחלום הלילה (לעיל כ ג) ויבא אלהים אל לבן בחלום (לעיל לא כד) ואתא מימר מן קדם ה' ואם תאמר שחשש שלא תהא הביאה קודמת לחלום ויחשוב בה שהיא ממש הנה בשלמה כתוב (מלכים א ג ה) בגבעון נראה ה' אל שלמה בחלום הלילה ותרגם אותו יונתן אתגלי ה' לשלמה ואם הדבר נאמר בחלום יספרו אותו כאשר נאמר בחלום ההוא ואל יקשה עליהם אף על פי שהוא מאמר יורה על הגשמות כי היותו בחלום יתרץ להם שאינו ממש גם כן הדבר שיאמר כי הוא נראה בחלום ראוי שיספרו אותו באשר הוא כי מה שנאמר בו שהוא בחלום הלילה ילמד שאינו ממש אבל הוא חלום שנדמה לו ממנו כן ואל תחשוב שהיה זה ליונתן בן עוזיאל מפני שלא יאמר בארמית לשון ראיה בחלומות כי וארא בחלומי (לעיל מא כב) מתורגם וחזית ובנבוכדנצר חזה הוית (דניאל ב לא) וכן תרגם אונקלוס לא עלינו תלונותיכם כי על ה' (שמות טז ח) אלהין על מימרא דה' ואין כאן יראה ופחד מן הגשמות וכן וידבר העם באלהים ובמשה (במדבר כא ה) ואתרעם עמא על מימרא דה' וכן ביני וביניכם (לעיל ט יב) בין אלהים ובין כל נפש חיה (שם טז) בין מימרי ומימרא דה' וכיוצא בהן הרבה וכן תרגם יצף ה' (שם לא מט) יסך מימרא דה' אלהים עד (שם לא נ) מימרא דה' סהיד ואין לו בהן יראת הגשמות וגם אין למימרא ענין בכאן שיאמר בו שיצפה ויעיד וכן השבעה לי באלהים (שם כא כג) קיים לי במימרא דה' ואין הנשבעים מזכירין אני נשבע במאמר אלהים וכיוצא באלו רבים לאונקלוס וסודם ידוע למשכילים וכן בלשון עמידה אמר הרב (במו"נ א כז) ששם יונתן בן עוזיאל כוונתו לפרש בו קיום ולכך תרגם ועמדו רגליו (זכריה יד ד) ויתגלי בגבורתיה וכן תרגם כל דבר עסק ותנועה גבורתא והנה אונקלוס לא יתיירא מלשון עמידה ותרגם הנני עומד לפניך שם על הצור (שמות יז ו) הא אנא קאים קדמך תמן על טינרא ומה שאמר הרב (שם) כי אונקלוס ישים ענין התנועה גלוי השכינה והראות כבוד נברא הנה אונקלוס מן הכבוד יברח מלתת בו כלשונות האלה ויתרגם וירא כבוד ה' אל כל העדה (במדבר טז יט) ואתגלי יקרא דה' כמו שיאמר ואתגלי ה' (שמות יט כ) ולא יתרגם ואיתחזי יקרא דה' וכן יתרגם במלאכים (שם ג ב) ואתגלי ואם ידבר אונקלוס במלאכים ובכבוד נברא בעניני הגשמות כמו שאמר הרב (במו"נ א כו) היה ראוי שלא יתיירא מן הראיה שיראה האדם ויתרגם בהם ואתחזי כמו שעשה כי ראיתי אלהים פנים אל פנים (לעיל לב לא) ארי חזיתי מלאכא דה' וחס ושלום שיהיה הדבר הנקרא שכינה או כבוד נברא חוץ מהשם הנכבד יתברך כאשר חשב הרב כאן ובפרקים רבים מספרו והוא תרגם אם אין פניך הולכים (שמות לג טו) אם לית שכינתך מהלכא ביננא ומשה לא יחפוץ בלכת עמו כבוד נברא חוץ מהשם הנכבד יתברך שכבר אמר לו הקדוש ברוך הוא הנה מלאכי ילך לפניך (שם לב לד) ולא היה מתרצה בכך אבל היה מבקש שילך עמו האל בעצמו ובכבודו (שם לג יד) וכן אחר ששמע השם בקולו ואמר לו גם את הדבר הזה אשר דברת אעשה (שם יז) אמר משה ילך נא אדני בקרבנו (שם לד ט) תהך כען שכינתא דה' ביננא וכן תרגם לא תוכל לראות את פני (שם לג כ) לא תוכל למחזי אפי שכינתי ארי לא יחזינני אינשא ואמר יונתן בן עוזיאל (יחזקאל ג יב) בריך יקרא דה' מאתר בית שכינתיה ואם הכבוד הזה ירצה בו הכתוב עצם הבורא ואמתו ויהיה כמו הראני נא את כבודך (שמות לג יח) שפירש בו הרב כן (מו"נ א נג סג) הנה הזכיר בו אתר ובית שכינתיה ואם יאמר שהוא כבוד נברא כדעתו של הרב בפסוק וכבוד ה' מלא את המשכן (שמות מ לה) וזולתו איך יקבעו בו ברוך והמברך והמתפלל לכבוד נברא כעובד אלילים ובדברי רבותינו דברים רבים יורו על שם השכינה שהוא האל יתברך אבל הענינים האלה לאונקלוס ויונתן בן עוזיאל דברים ידועים בקבלה וסודם ליודעים חן ובמעמד הר סיני יתרגם אונקלוס כל מלת אלהים הנזכר בפרשה יקרא או מימרא דה' וכאשר תזכיר הפרשה השם המיוחד לא יאמר כן והכל בהשגחה ובחכמה ממנו ועוד אזכיר זה בעזרת השם יתברך (שמות כ יט) ומה שתרגם אונקלוס וידבר אלהים את כל הדברים האלה (שם כ א) ומליל ה' טעמו בזה משום שנאמר פנים בפנים דבר ה' אל כל קהלכם (דברים ה ד יט) והמשכיל יבין אבל מה שאמר כאן אנא אחות עמך רצה לרמוז בו מה שאמרו (מכילתא שירה ג) גלו למצרים שכינה עמהם שנאמר אנכי ארד עמך מצרימה גלו לעילם שכינה עמהם שנאמר (ירמיהו מט לח) ושמתי כסאי בעילם והנה האמירה והירידה שוים כמו שפירשתי למעלה ולא היה יכול לתרגם אלא כן בשום פנים כאשר רמזתי (ריש פסקא זו) אבל שם ביעקב לא יתכן לתרגם והא אנא עמך בעבור כי שם כתוב והנה ה' נצב עליו (לעיל כח יג) והמשכיל יבין ומפני שמצא אונקלוס שאינו כפשוטו ממש ברח ממנו ועשאו ענין עזר בלבד ואמר מימרי בסעדך ולא אמר מימרי עמך כמו שאמר במשה (שמות ג יב) והאל יראנו מתורתו נפלאות
@1389 **ויאמר יעקב יעקב** . אחר שאמר לו השם לא יקרא שמך עוד יעקב כי אם ישראל יהיה שמך היה ראוי שיקראנו בשם הנכבד ההוא וכן הוא נזכר בפרשה הזאת שלשה פעמים אבל קראו יעקב לרמוז כי עתה לא ישור עם אלהים ועם אנשים ויוכל אבל יהיה בבית עבדים עד שיעלנו גם עלה כי מעתה הגלות תתחיל בו וזה טעם ואלה שמות בני ישראל הבאים מצרימה יעקב ובניו (פסוק ח) כי בשם בני ישראל יבאו שמה כי יפרו הבנים וירבו ויגדל שמם וכבודם אבל יעקב הוא עתה ברדתו שם והזכיר הכתוב ער ואונן עם שמות בני ישראל הבאים מצרימה לסוד ידוע מדברינו שכתבנו כבר (לעיל לח ח) והמשכיל יבין זה וטעם כל הפסוק וכן הזכירם בפקודים (במדבר כו יט-כ) בני יהודה ער ואונן וימת ער ואונן בארץ כנען ויהיו בני יהודה למשפחותם ובדברי הימים (א ב ג-ד) מנאם במספר אמר בני יהודה ער ואונן ושלה שלושה נולד לו מבת שוע הכנענית ותמר כלתו ילדה לו את פרץ ואת זרח כל בני יהודה חמשה
@1394 **ובנות בניו** . שרח בת אשר ויוכבד בת לוי לשון רש"י ומה ירבה בבנותיו אבל דרך הכתוב כשידבר ביחוסי הרבים יאמר ביחיד לשון רבים ובני דן חושים (להלן פסוק כג) ובני פלוא אליאב (במדבר כו ח) וכן בנותיו דינה ובנות בניו סרח בת אשר אבל יוכבד לא יזכירנה הכתוב כמו שאמר כל נפש ששים ושש אבל ירמוז אליה כדעת רבותינו (ב"ב קכג)
@1402 **שלשים ושלש** . ובפרטן אי אתה מוצא אלא שלשים ושתים אלא זו יוכבד שנולדה בכניסתן לעיר שנאמר (במדבר כו נט) אשר ילדה אותה ללוי במצרים לידתה במצרים ואין הורתה במצרים זו היא שיטת רבותינו (סוטה יב) ורבי אברהם השיב ואמר כי זה תימה אם כן למה לא הזכיר הכתוב הפלא שנעשה עמה שהולידה משה והיא בת מאה ושלשים שנה ולמה הזכיר דבר שרה שהיתה בת תשעים ולא די לנו זה הצער עד שעשו הפייטנים פיוטים ביום שמחת תורה יוכבד אמי אחרי התנחמי והנה היא בת מאתים וחמשים שנה וכי אחיה השילוני חיה כך וכך שנים דרך הגדה או דברי יחיד אלו דבריו והנה פן יהיה חכם בעיניו בסתירת דברי רבותינו אני צריך לענות אליו ואומר כי על כל פנים יהיה בדבר יוכבד פלא גדול מן הנסים הנסתרים שהם יסוד התורה כי היא בת לוי עצמו לא מתיחסת אליו כמו שכתוב (במדבר כו נט) אשר ילדה אותה ללוי במצרים ועוד כתוב (שמות ו כ) את יוכבד דודתו והנה אם נאמר כי הוליד אותה בבחרותו כאשר הוליד כל בניו והיתה לידתה אחר רדתו למצרים מעט הנה היא בלדת משה זקנה מאד כמנין שאמרו רבותינו או קרוב לו ואם נאמר שנולדה לו אחר שבתו במצרים ימים רבים והנה נחשוב שהוליד אותה אחר רדתו למצרים חמשים ושבע שנה והוא יהיה בן מאה שנה כי ברדתו היה בן מ"ג שנים והנה יהיו בזה שני פלאים שיהיה הוא זקן כאברהם אשר הזכיר הכתוב (לעיל יז יז) הלבן מאה שנה יולד וכתיב (לעיל יח יב) ואדני זקן ותהיה היא זקנה בלדת משה בת ע"ג ואם נאחר עוד לידתה לסוף ימי לוי הנה יהיה פלא גדול משל אברהם אבל אומר לך דבר שהוא אמת וברור בתורה כי הנסים הנעשים על ידי נביא שיתנבא כן מתחילה או מלאך נגלה במלאכות השם יזכירם הכתוב והנעשים מאליהן לעזור צדיק או להכרית רשע לא יזכירו בתורה או בנביאים וזהו זהב רותח יוצק בפי החכם הזה ממה שהשיב על רבותינו בענין פינחס (במדבר כה יב) וזולתו במקומות הרבה ולמה יזכירם הכתוב כל יסודות התורה בנסים נסתרים הם ועם התורה אין בכל ענינו רק נסים לא טבע ומנהג שהרי יעודי התורה כולם אותות ומופתים כי לא יכרת וימות בטבע הבא על אחת מן העריות או האוכל חלב ולא יהיו השמים כברזל בטבעם מפני זרענו בשנה השביעית וכן כל יעודי התורה בטובות ההן וכל הצלחת הצדיקים בצדקתם וכל תפלות דוד מלכנו וכל תפלותינו נסים ונפלאות אלא שאין בהם שנוי מפורסם בטבעו של עולם כאשר הזכרתי זה כבר (לעיל יז א) ועוד אפרשנו בעזרת השם (שמות ו ב ויקרא כו יא) והנה אתן לך עד נאמן על מה שאמרתי ידענו כי מעת בוא ישראל לארץ עד לדת אדונינו דוד היה כשלש מאות ושבעים שנה והימים יתחלקו לארבעה דורות שלמון ובועז ועובד וישי ויגיע לכל אחד מהם צ"ג שנה והנה כלם זקנים קרוב לאברהם והיו מולידים כל אחד בשנת מותו שלא כדרך כל הארץ כי אין החיים בזמנם מאה שנה ואם הוליד אחד מהם בבחרותו כמנהג יהיו האחרים זקנים מאד יותר מאברהם ויהי בהם הפלא גדול יותר מאד כי ימי האדם בדור אברהם ארוכים ובשנות דוד חזרו למחציתם ואולי חיו יותר כי אפשר שהיו לשלמון ימים רבים בבואם לארץ ולכן נתנו אנשי הקבלה והם חכמי אמת לעובד ימים רבים והוא נס נסתר נעשה לאבי המלוכה בן הצדקת הבאה לחסות תחת כנפי השכינה וכן יזכירו באמו ארך ימים רבים וכבר פרשתי כי הפלא באברהם איננו כאשר יחשוב החכם הנזכר וזולתו מבעלי המקרא כי אברהם הוליד את יצחק טרם מותו שבעים וחמש שנה והנה לא עברו עליו שני חלקים בימיו והאנשים בכל דור אין הזקנה בהם עד עבור עליהם שלשת חלקי ימותם כאשר יחשבו הרופאים הילדות והבחרות והאישות והזקנה ובדורות האלה אשר הימים בהם כשבעים שנה לא יחשבו לו הרופאים זוקן עד אחר ששים ועוד כי אברהם הוליד בנים רבים אחרי ארבעים שנה מלדת יצחק ויהיה הפלא כפלי כפלים ואם נאמר שהחזירו האל לימי בחורותיו יקשה עליו כי לא הזכיר הכתוב הפלא הגדול הזה והוא נס גלוי ומפורסם בהפך מן הטבע ומן הידוע כי האנשים בדור הזה מהם שיולידו בזקנתם עד מלאת שבעים שנה או שמונים שנה ויותר כפי התקומם בהם הלחות לפי טבעם וגם הנשים אין להם זמן וכל עוד היות להן האורח תלדנה רק התימה באברהם ושרה כאשר פירשתי שם מפני שלא הולידו בנעוריהם ועתה הולידו זה מזה ועוד בשרה היה פלא כי חדל ממנה ארח כנשים ואחרי כן לא תלדנה והנה אם יהיו ימי יוכבד כימי אביה ותתקיים בה הלחות עד קרוב לזקנתה כמשפט הנשים איננו פלא אם תוליד בזמן אשר נתנו לה רבותינו מפני שרצה האלהים לגאול את ישראל על ידי האחים האלה ולא הגיע הקץ איחר לידתם ימים רבים עד כי זקנה אמם ולא יפלא מה' דבר
@1405 **אלה בני זלפה** . וגו' בני רחל אשת יעקב וגו' דרך הכתוב למנות בני הגבירות יחד בתחילה כמו שאמר בסדר וישלח יעקב (לעיל לה כג-כו) ובסדר ואלה שמות בני ישראל (שמות א ב-ד) או למנותם כתולדותם הבכור כבכורתו והצעיר כצעירתו כאשר עשה בברכתם בסדר ויחי יעקב אבל בכאן מפני שבא למנות מספרם כי בשבעים נפש ירדו מצרימה הקדים המרובה בנפשות ולכך הזכיר רחל בתוך הלחינות והוצרך להזכירה בכבוד ואמר אשת יעקב כאשר הזכרתי למעלה (לא לג מד כז)
@1406 ראו רמב"ן על בראשית מו יח
@1416 **וירא אליו** . יוסף נראה אל אביו ויבך על צואריו עוד לשון הרביית בכיה אבל יעקב לא נפל על צואר יוסף בנו ולא נשקו ואמרו רבותינו שהיה קורא קריאת שמע לשון רש"י ולא ידעתי טעם ב"וירא אליו" כי בידוע שנתראו כאשר נפל על צוארו ועוד כי איננו דרך כבוד שיפול יוסף על צוארי אביו אבל שישתחוה לו או שינשק ידיו ככתוב (להלן מח יב) ויוצא יוסף אותם מעם ברכיו וישתחו לאפיו והשעה הזו ראויה יותר להשתחות לו וכן כל "עוד" בכתוב תוספת על עיקר הוא איננו כמו הרבה לא על איש ישים עוד (איוב לד כג) שישים עליו כפי חטאיו ולא יותר והנכון בעיני כי כבר היו עיני ישראל כבדים קצת מזוקן וכשבא יוסף במרכבת המשנה ועל פניו המצנפת כדרך מלכי מצרים לא היה ניכר לאביו וגם אחיו לא הכירוהו לפיכך הזכיר הכתוב כי כאשר נתראה אל אביו שהביט בו והכירו נפל אביו על צוארו ובכה עליו עוד כאשר יבכה עליו תמיד עד היום הזה כשלא ראהו ואחר כך אמר אמותה הפעם אחרי ראותי את פניך ודבר ידוע הוא מי דמעתו מצויה אם האב הזקן המוצא את בנו חי לאחר היאוש והאבל או הבן הבכור המולך ואל תחוש בעבור אמרו ויאמר ישראל כי ממנו ידבר ויחזור ויזכיר שמו וכן (לעיל מא מח-נ) ויקבוץ את כל אוכל שבע שנים וגו' וליוסף יולד שני בנים וכן במקומות רבים תמיד בתורה ובמקרא
@1419 **והאנשים רעי צאן כי אנשי מקנה היו** . אמר להם שהם רועים אבל לא שירעו בהמות של אחרים כי גם בשל עצמם יש להם עבדים ובני בית ירעו אותם אלא שעשרם במקנה וזה טעם כי אנשי מקנה היו והיה להם עושר ועבודה רבה מאד במקנה רב אשר להם כי לא רצה להזכיר רק לכבוד
@1425 **לגור בארץ באנו כי אין מרעה לצאן אשר לעבדיך** . אני תמה בטעם הזה שאמרו לו כי גם במצרים אין מרעה כי כבד הרעב בארץ מצרים כמו בארץ כנען או יותר כי עליה היתה עיקר הגזירה ואולי אמרו כי בארץ כנען מפני כובד הרעב יאכלו האנשים עשב השדה ולא ישאירו מחיה לבהמה אבל בארץ מצרים יש בה שבר יחיו בה האנשים ותשאר בה מרעה מעט ויתכן שהיה בארץ מצרים מרעה מעט באחו מפני היאורים והאגמים
@1426 **אביך ואחיך באו אליך** . הכנסת דברים כאומר הנה שמעתי כי אביך ואחיך באו וארץ מצרים לפניך היא והנכון בעיני שיאמר אביך ואחיך אליך באו לשמע כבודך ועליך השליכו יהבם ראה שתעשה עמהם טובה כי עליך הדבר ויש לאל ידך
@1428 **ויברך יעקב את פרעה** . היא שאלת שלום כדרך כל הנראין לפני מלכים לפרקים לשון רש"י ואינו נראה כן שאין מדרך מוסר המלוכה שישאל אדם בשלום המלך וכמו שאמרו (שבת פט) כלום יש עבד שנותן שלום לרבו אבל היה ברכה ממש שדרך הזקנים והחסידים הבאים לפני המלכים לברך אותם בעושר ונכסים וכבוד והתנשא מלכותם וכענין שאמר הכתוב (מלכים א א לא) יחי אדוני המלך דוד לעולם ובצאתו מלפניו חזר וברך אותו ליטול רשות מלפניו ואמרו רבותינו (תנחומא נשא כו) שיעלה נילוס לרגלו
@1430 **מעט ורעים היו ימי שני חיי** . לא ידעתי טעם הזקן אבינו מה מוסר הוא שיתאונן אל המלך ומה טעם לאמר ולא השיגו את ימי שני חיי אבותי כי אולי עוד ישיגם ויחיה יותר מהם ונראה לי כי יעקב אבינו זרקה בו שיבה והיה נראה זקן מאד ופרעה תמה על זקנותו כי אין רוב אנשי זמנו מאריכים ימים כל כך שכבר קצרו שנותם ולכן שאל לו כמה ימי שני חייך כי לא ראיתי כמותך זקן בכל מלכותי אז ענה יעקב כי ימיו שלשים ומאת שנה ואל יתמה בהם כי מעט הם כנגד שנות אבותיו שחיו יותר אבל מפני היותם רעים בעמל ואנחה זרקה בו שיבה ונראה זקן מאד
@1432 **וטעם ויושב יוסף ויתן להם אחזה וגו'** . שהושיב אותם במיטב הארץ ובאחוזה שנתן להם כי לא רצה שיהיו כגרים בארץ וקנה להם בתים ונחלת שדה וכרם נתן להם וזה מרשות פרעה כי הם אמרו לגור בארץ באנו לא לדור וכשיעבור הרעב נשוב לארצנו ופרעה אמר ליוסף הושב את אביך שיושיבם כאנשי הארץ התושבים בארץ גשן
@1435 **וילקט יוסף את כל הכסף וגו'** . סיפר הכתוב זה וגמר הענין בכל הפרשה להודיע מעלות יוסף בחכמה בתבונה ובדעת וכי היה איש אמונים שהביא כל הכסף בית פרעה ולא עשה לעצמו אוצרות כסף ומטמוני מסתרים בארץ מצרים או לשלחו לארץ כנען אבל נתן למלך הבוטח בו כל הכסף וקנה לו את האדמה גם הגופות ומצא בזה חן גם כן בעיני העם כי השם הוא המצליח את יראיו
@1436 **ויתם הכסף מארץ מצרים ומארץ כנען ויבאו כל מצרים אל יוסף וגו'** . והזכיר כי תם הכסף מארץ כנען בעבור כי מצרים בבואם אל יוסף יזכירו לו זה כי אמרו אחרי שתם הכסף גם מארץ כנען ולא יבאו עוד אליך לשבור למה נמות נגדך כי אפס כסף ותמיתנו חנם ותשאר התבואה בידך ואין קונה
@1439 **ויבאו אליו בשנה השנית** . לשני הרעב ואף על פי שאמר יוסף ועוד חמש שנים אשר אין חריש וקציר (לעיל מה ו) מכיון שבא יעקב למצרים באתה ברכה לרגלו והתחילו לזרוע וכלה הרעב וכן שנינו בתוספתא דסוטה (י ג) לשון רש"י וכך הוזכר בבראשית רבה (פט יא) אמר רבי יוסי ברבי חנינא שתי שנים עשה רעב כיון שירד יעקב אבינו למצרים כלה הרעב ואימתי חזרו בימי יחזקאל וכו' ואם כן לא נתקיימו דברי יוסף כפתרונו ויבא הענין לחשוד אותו בחכמתו ואולי נאמר שהיה הרעב בארץ כנען כדבר יוסף אבל במצרים ירד יעקב אבינו אל היאור לעיני פרעה ולעיני כל מצרים וראו כל עמו שעלה נילוס לקראתו וידעו כי ברכת ה' היא לרגלי הנביא ואם כן יהיה ויכלכל יוסף את אביו ואת אחיו לחם לפי הטף בשאר שני השבע וכל ימי חיות אביו כי גם אחרי מות אביו אמר אנכי אכלכל אתכם ואת טפכם (להלן נ כא) ועם כל זה אני תמה שאם כן לא היה החלום אמת כי הראו לו את הגזרה ולא הענין הנהיה והנעשה בהם וראיתי שם בתוספתא דסוטה אמר רבי יוסי כיון שמת יעקב אבינו חזר הרעב לישנו וכו' ועוד שנינו בספרי (עקב לח) ויברך יעקב את פרעה במה ברכו שנמנע שני הרעב אף על פי כן שלמו אחר מיתתו שנאמר ועתה אל תיראו אנכי אכלכל אתכם מה כלכול האמור להלן (פרק מה יא) בשני רעבון הכתוב מדבר אף כלכול האמור כאן בשני רעבון הכתוב מדבר רבי שמעון אומר אין זה קידוש השם שדברי צדיקים קיימין בחייהם וניטלין לאחר מיתתן אמר רבי אלעזר ברבי שמעון רואה אני את דברי רבי יוסי מדברי אבא שזה קידוש השם שכל זמן שהצדיקים בעולם ברכה בעולם נסתלקו מן העולם נסתלקה ברכה מן העולם עד כאן והנה השלים הרעב חמש השנים הנותרות ודעת רבי אברהם שהיו אלו שתי השנים לאחר בוא יעקב למצרים וכך כתב מצינו בדרש כי נסתלק הרעב בזכות יעקב גם יתכן שהיה רעב שלש שנים ולא היה כמו ד' שעברו ואין דבריו נכונים כלל כי מספר החלום ושברו ישוה כל השבע שנים ואילו היה כן יזכיר הכתוב ענינם של השנים האלה אבל על דרך הפשט לקט יוסף את כל הכסף הנמצא בארץ מצרים ובארץ כנען בחמש שנים והביא אותו אל פרעה כי איך יתכן שיתום הכסף והמקנה בשנה אחת אבל הכסף הספיק להם כל חמש שנים כי כן הדבר במנהגו של עולם ובעבור שלא נתחדש ונשתנה דבר אחד בכל אלה השנים לא ספר בהם הכתוב רק וילקט יוסף את כל הכסף וגו' ואחרי שתם הכסף ספר שבאו אל יוסף והיה זה בשנה הששית ונתן להם במקניהם לחם רק נהלם בו שיאכלו לפי חיותם ולא לשבעה ותתם השנה ההיא אשר נדר להם לנהלם בלחם בכל מקניהם והיא השנה הששית ויבאו אליו בשנה השנית לה ואמרו לו שיקנה אותם ואת אדמתם בלחם שיאכילם בשנה הזאת השביעית ואחר שתהיה הארץ לפרעה יתן להם זרע שלא תשם האדמה כי ידעו כי כלו שבע שני הרעב ויהיה להם זרע וקציר וזה טעם ויכלכל יוסף לחם לפי הטף שנתן להם בשנות הרעב כדי צרכם לחם כי לפי הטף ירמוז כן
@1440 **קנה אתנו ואת אדמתנו** . הנה אמרו לו שגם גופם יקנה לעבדים לפרעה וכן אמר הן קניתי אתכם היום ואת אדמתכם אבל אמר ויקן יוסף את כל אדמת מצרים לפרעה כי מכרו מצרים איש שדהו ולא אמר שיקנה גופם רק האדמה והטעם כי הם אמרו לו שיקנה אותם לעבדים עושי מלאכת המלך כרצונו והוא לא רצה רק לקנות את האדמה והתנה עמהם שיעבדו אותה לעולם ויהיו בה אריסי בתי אבות לפרעה ואחרי כן אמר להם הן קניתי אתכם היום ואת אדמתכם לפרעה לא לעבדים כאשר אמרתם לי רק עם האדמה תהיו לו והנה ראוי שיטול המלך שהוא אדון הקרקע ארבע הידות ואתם החמישית אבל אני אתחסד עמכם שתטלו אתם חלק בעל הקרקע ופרעה יטול החלק הראוי לאריס אבל תהיו קנוים לו שלא תוכלו לעזוב את השדות וזה טעם מה שנדרו לו והאדמה לא תשם שלא תשם לעולם ולכך אמרו לו נמצא חן בעיני אדוני שהקלת עלינו ליטול ארבע הידות שנוכל לחיות בהם והיינו עבדים לפרעה כאשר נדרנו שנעבוד את האדמה לרצונו חסלת פרשת ויגש
@1449 **ויחי יעקב בארץ מצרים שבע עשרה שנה** . כבר הזכרתי (לעיל מג יד) כי רדת יעקב למצרים הוא גלותינו היום ביד החיה הרביעית (דניאל ז ז) רומי הרשעה כי בני יעקב הם עצמם סבבו רדתם שם במכירת יוסף אחיהם ויעקב ירד שם מפני הרעב וחשב להנצל עם בנו בבית אוהב לו כי פרעה אוהב את יוסף וכבן לו והיו סבורים לעלות משם ככלות הרעב מארץ כנען כמו שאמרו (לעיל מז ד) לגור בארץ באנו כי אין מרעה לצאן אשר לעבדיך כי כבד הרעב בארץ כנען והנה לא עלו אבל ארך עליהם הגלות ומת שם ועלו עצמותיו וזקני פרעה ושריו העלוהו ועשו עמו אבל כבד וכן אנחנו עם רומי ואדום אחינו הסיבונו ביאתינו בידם כי כרתו ברית עם הרומיים ואגריפס המלך האחרון לבית שני ברח אליהם לעזרה ומפני הרעב נלכדו אנשי ירושלים והגלות ארך עלינו מאד לא נודע קצו כשאר הגליות ואנחנו בו כמתים אומרים יבשו עצמותינו נגזרנו לנו ויעלו אותנו מכל העמים מנחה לה' ויהיה להם אבל כבד בראותם כבודנו ואנחנו נראה בנקמת ה' יקימנו ונחיה לפניו
@1450 **ויקרבו ימי ישראל למות** . פתרונו כאשר קרבו ימי ישראל למות קרא לבנו ליוסף והוא בשנה האחרונה לימיו וענינו כי הרגיש בעצמו אפיסת הכחות ויתרון החולשה ואיננו חולה אבל ידע כי לא יאריך ימים ולכן קרא לבנו ליוסף ואחרי שוב יוסף למצרים חלה והוגד ליוסף ובא לפניו עם שני בניו כדי שיברכם וכן ויקרבו ימי דוד למות (מלכים א ב א) ושם (שם פסוק ב) נאמר אנכי הולך בדרך כל הארץ כי ידע בנפשו כן
@1452 **השבעה לי וישבע לו** . לא היה יעקב חושד בבנו הצדיק האהוב לו שימרה על מצות אביו ועל הדבר אשר הבטיחו ואמר אנכי אעשה כדבריך אבל עשה כן לחזק הענין בעיני פרעה אולי לא יתן לו רשות להפרד ממנו ויאמר לו שלח את אחיך ואת עבדיך ויעלוהו שם או שיחפוץ פרעה שיקבר הנביא בארצו לכבוד להם ולזכות ולכן השביעו כי לא יהיה נכון להעבירו על שבועתו וגם יוסף יצטרך יותר להשתדל בענין מפני השבועה וכן היה הדבר כמו שאמר (להלן נ ו) עלה וקבור את אביך כאשר השביעך
@1458 **ומולדתך אשר הולדת אחריהם** . אם תוליד עוד בנים לא יהיו במנין בני אלא בתוך שבטי אפרים ומנשה יהיו נכללין ולא יהא להם שם כשאר השבטים לענין הנחלה ואף על פי שנתחלקה ארץ ישראל למנין גולגלותם כדכתיב לרב תרבה נחלתו וכל איש נטל בשוה חוץ מן הבכורות מכל מקום לא נקראו שבטים אלא אלו לשון רש"י וזה איננו נכון שאם כן אין הבכורה ליוסף אלא לענין הכבוד בלבד שיקראו בניו שבטים והכתוב אומר בנחלתם ובגמרא אמרו לנחלה הקשתים לראובן ושמעון ולא לדבר אחר וכו' כדאיתא בהוריות (ו) והזכירו רבותינו בכל מקום (ב"ב קכג) שהיה יוסף בכור לנחלה וירש פי שנים כאחד כמשפט כל בכור ולא היתה בכורתו להקרא שבטים בלבד כדברי הרב ומזה נלמוד עוד שלא חלקו הארץ לכל שבטי ישראל לגולגלותם שאם כן מה הבכורה הזאת בירושה ואם נאמר שנתנו לכל אחד ואחד מבני יוסף פי שנים כאחד מכל אישי שאר השבטים לא הוזכר זה בכתוב כלל ולא מצינו ביעקב שיתן בכורה ליוסף אלא שאמר בכאן כראובן ושמעון יהיו לי ומזה אמר הכתוב (דהי"א ה א) נתנה בכורתו לבני יוסף בן ישראל אם כן היו לגמרי כשני שבטים והיא בכורתו וכך הם דברי חכמים בכל מקום (ב"ב קכג) אבל הענין איננו כלל כמו שאמר הרב שארץ ישראל לשבטים נתחלקה שנים עשר חלקים שוים עשו ממנה ונטל שבט שמעון הממועט שבהם כשבט יהודה שמרובה באוכלוסין ונטלו אפרים ומנשה כראובן ושמעון בשוה וכך העלו בגמרא פרק יש נוחלין (שם) וכתוב (יחזקאל מז יג) תתנחלו בארץ לשנים עשר שבטי ישראל יוסף חבלים וכן אמר אונקלוס (להלן מט כב) תרין שבטין יפקון מבנוהי יקבלון חולקא ואחסנתא שיהיו שוים בקבלת הנחלה וטעם חולקא חלק בכור ואחסנתא ירושת הפשוט ומה מה שאמר הכתוב (במדבר כו נד) לרב תרבה נחלתו ולמעט תמעיט לענין בתי אבות הנזכרים בפרשה דבר הכתוב שהשבט מחלק חלקו לבתי אבות של יוצאי מצרים ובית אב מרובה נותנין לו חלק גדול ובית אב ממועט נותנין לו חלק קטן ומתים יורשים החיים כמפורש בספרי (פנחס קלב) ורש"י הזכירו בפרשת פנחס (במדבר כו נה) והכלל בענין יוסף שהיה בכור לנחלה ואם חלקו ישראל הארץ לשבטים כמוזכר בגמרא (ב"ב קכא) נתנו לו כראובן ושמעון בשוה ואם אולי נאמר שחלקוהו לגולגלותם כנגלה מן הכתוב נתנו להם כפלים במספרם חלק פשוט כדין שאר האנשים וחלק שני בכורה ויהיה טעם כראובן ושמעון כפלים במספרם אבל שיהיה יוסף כשאר השבטים בנחלה ותהיה הבכורה להקרא שני שבטים כמאמר הרב זה דבר שאי אפשר בשום פנים
@1459 **ואקברה שם** . כתוב בפירוש רש"י ולא הולכתיה אפילו לבית לחם להכניסה לארץ ולא ידעתי מהו וכי בחוצה לארץ נקברה חס ושלום שהרי בארץ מתה ושם נקברה כמו שנאמר כאן בפרשה מתה עלי רחל בארץ כנען ושם כתוב עוד מפורש (לעיל לה ו) ויבא יעקב לוזה אשר בארץ כנען היא בית אל וכתיב (שם פסוק טז) ויסעו מבית אל ויהי עוד כברת הארץ לבא אפרתה ומתה בדרך בין בית אל ובין בית לחם אפרתה בארץ ישראל
@1459 "ואקברה שם" - וידעתי שיש בלבבך עלי אבל דע לך שעל פי הדיבור קברתיה שם שתהא לעזרה לבניה כשיגלם נובזראדן והיו עוברים דרך שם יצתה על קברה ובקשה רחמים עליהם שנאמר (ירמיהו לא יד) קול ברמה נשמע רחל מבכה על בניה והקב"ה משיבה יש שכר לפעולתך וגו' ושבו בנים לגבולם לשון רש"י וצריך על כל פנים שיהיה רמז במקרא לטעם הזה שאמר באגדה זו ושמא זהו מה שאמר הכתוב
@1459 "מתה עלי רחל בדרך ואקברה שם בדרך" - כלומר בדרך אשר יעברו בה בניה מתה ושם קברתיה לטובתם כי היא לא מתה בדרך רק ברמה שהיא עיר בארץ בנימין ושם נקברה אבל בדרך של עתיד מתה והכתוב לא יפרש בעתידות רק ירמוז בהם ועל דרך הפשט גם כן אמר לו כן כמתנצל שלא יחר ליוסף בראות חפצו בקבורת המערה על שלא קבר אמו שם וכאשר קבר שם את לאה ולכך אמר לו כי מתה בארץ כנען ולא נקברה בחוצה לארץ כאשר תהיה קבורת מצרים ליעקב ומתה בדרך בפתע פתאום ולא יכול לקברה שם כי איך יעזוב את בניו ואת מקנהו בדרך וילך מהרה עמה למערת המכפלה ואיה הרופאים והרפואות לחנט אותה וזה טעם "עלי" ואף על פי שמערת המכפלה אינה רחוקה משם רק כחצי יום היה יעקב כבד מאד במקנה הגדול ובני בית ולא יגיעו שם רק בימים רבים וכן עשה בדרך ההוא ימים רבים עד בואו אל אביו ושנו חכמים (מו"ק כז) ולא של נשים לעולם מפני הכבוד ואני סבור שהיו אלו דברי התנצלות וגם יוסף יודע שמתה בדרך ונקברה בארץ וכבוד עשה לה במותה אבל הכוונה ליעקב שלא הוליך אותה למערה כדי שלא יקבור שם שתי אחיות כי יבוש מאבותיו ולאה היא הנשאת לו ראשונה בהיתר ורחל באהבתו אותה בנדר אשר נדר לה לקחה
@1461 **אשר נתן לי אלהים בזה** . לא היה יוסף צריך להודיע לאביו כי במצרים נולדו לו שהרי כשפירש ממנו לא היה לו אשה ובנים והוא אמר לו כבר שני בניך הנולדים לך בארץ מצרים ונראה לי כי פירוש "בזה" בענין הזה שאמרת שנתנם לי השם קודם בואך אלי מצרימה והם אשר אמרת עליהם שהם לך וכן ובזה הנערה באה אל המלך (אסתר ב יג) ואמר נתן לי אלהים שעשה לי השם נסים עד שנתן לי המלך האשה והיו לי הבנים האלה ממנה
@1467 **ויברך את יוסף ויאמר** . הטעם כי לברך את יוסף באהבתו אותו ברך את בניו ויגיד כי לא היה ליוסף זרע אחר והיתה כל ברכתו בברכת אלה הנערים או שיקראו שאר בניו על שם אחיהם ומברכתם יבורכו גם הם והוא הנכון בעיני כי הנביא אומר ומולדתך אשר הולדת אחריהם לך יהיו ודברו לא יהיה לריק אבל הוליד אחרי כן בנים כדעת אונקלוס שאמר ובנין דתוליד בתריהון ויהיה אשר הולדת עבר במקום עתיד כמו אשר לקחתי מיד האמורי ורבים מלבדו כי על דרך הפשט יראה שכבר היו לו בנים שהוליד אחרי בואו אליו מצרימה ממה שהוצרך להאריך ולא אמר "ועתה שני בניך הנולדים לך אפרים ומנשה כראובן ושמעון יהיו לי ומולדתך אשר תוליד לך יהיו" וזה טעם מה שאמר (לעיל מא נ) וליוסף יולד שני בנים בטרם תבא שנת הרעב כי אחרי הרעב נולדו לו עוד בנים אחרים והכתוב לא יזכיר אותם כי אין בהם צורך
@1467 "האלהים אשר התהלכו אבותי לפניו אברהם ויצחק" - יקרא הנביא אל אלהי אבותיו אשר לו הגדולה והגבורה ועשה עמהם את הגדולות ואת הנוראות ויקרא לאלהי האמת אשר הוא רועה אותו מעודו ויתכן שיהיה הרועה אותי מגזרת רעך ורע אביך אל תעזוב (משלי כז י) כי במדה ההיא שלום ורעות והמלאך הגואל הוא העונה אותו בעת צרתו ושאמר לו אנכי האל בית אל (לעיל לא יג) והוא שנאמר עליו (שמות כג כא) כי שמי בקרבו ולכך אמר בקרב הארץ והרי זה מבואר למשכיל ואל יקשה עליו מעודי עד היום הזה עם מה שכתבנו בפסוק ויזבח זבחים לאלהי אביו יצחק (לעיל מו א) כי מעודו ינחהו בדרך אמת אבל לא נתיחד לו המדה עד שובו לארץ אבותיו מפני היותו בחוצה לארץ גם בעבור שהוצרך להתנהג עם לבן בדרך פתלתול ואיננו דרך האמת
@1468 **וטעם ויקרא בהם שמי** . אמר רבי אברהם שנקראו ישראל על שם אפרים כאשר הם נקראים זרע אברהם יצחק ויעקב ואיננו נכון כי הכתוב אמר "בהם" והנה לא נקראו על שם מנשה ואולי בעבור שיקראו בית יוסף והנכון שיעמוד זרעם ושמם ויהיה שם אברהם יצחק ויעקב נזכר בהם לעולם
@1469 **וירע בעיניו** . אולי יוסף היה אוהב את מנשה יותר בעבור היותו בכור לכן חרה לו והנכון בעיני כי חשב שטעה אביו בהם ואם היתה ברכתו בבלי דעת לא תבא ברכתו עליהם כי איננה ברוח הקדש כראוי וכאשר אמר לו ידעתי בני ידעתי נתפייס
@1472 **ויברכם ביום ההוא** . טעם ביום ההוא בעבור שיוסף יפצר בו לשום מנשה ראשון הגיד כי לא רצה להסיר יד ימינו מראש אפרים על ראש מנשה ולא עוד אלא שחזר ואמר בפירוש במעמד ההוא בפני יוסף בברכו אותם "כאפרים וכמנשה"
@1472 "וישם את אפרים לפני מנשה" - בכל ברכותיו וטעם בך יברך ישראל אל יוסף ידבר כי בזרעך יברך עם ישראל ויאמר למתברך ישימך אלהים כאפרים וכמנשה
@1474 **ואני נתתי לך שכם אחד על אחיך** . אחרי שבירך את בני יוסף ועשאם שני שבטים חזר על יוסף ואמר לו הנה אנכי מת והיה אלהים עמכם בגלות להציל אתכם מכל צרה ותפרו ותרבו מאד וישיב אתכם אל ארץ אבותיכם לנחול אותה ואני כבר נתתי לך בארץ ההיא החלק האחד אשר בידי לתת והוא חלק הבכורה להיותך בו יתר על אחיך מיום שלקחתי אותו מיד האמורי בחרבי ובקשתי וזה כלו פיוס ליוסף ואהבתו אותו כי הודיעו שנתן לו הבכורה להיות בניו מעתה מתברכים להעשות שני שבטים גם בדגלי המדבר וחנוכת הנשיאים וגם החלק אשר לו בנחלה נתן לו שיזכה בו כאשר יכבשו הארץ בחרב ובקשת ובמלחמה והנה אמר לו עשיתי עמך כל הטובה שיכלתי לעשות לך לעת שהייתי יכול לעשותה כי אין ברשות יעקב בארץ רק שכם אחד שאין בידו לגזול מאחד מבניו את נחלתו רק הבכורה היתה לו לתת אותה לטוב בעיניו והנה נתן אותה אליו וטעם מיד האמורי כי ישראל לקחו הארץ תחילה מיד האמורי כי סיחון ועוג שני מלכי האמורי היו והמלחמה הראשונה והגדולה שהיתה להם בכבוש הארץ היתה לבניו של יוסף עם האמורי היא מלחמת יהושע עמם ובם נעשה הנס הגדול כדכתיב (יהושע י יב) אז ידבר יהושע לה' ביום תת ה' את האמורי לפני בני ישראל וגו' ומיד האמורי היה חלק ונחלה לבני יוסף כמו שכתוב (במדבר לב לט) וילכו בני מכיר בן מנשה גלעדה וילכדוה ויורש את האמורי אשר בה וגם בני אפרים נחלו בגבול האמורי כמו שכתוב (שופטים א לה) ויואל האמורי לשבת בהר חרס באילון ובשעלבים ותכבד יד בית יוסף ויהיו למס וטעם בחרבי ובקשתי כי הארץ לא תכבש להם רק בחרב ובקשת ירמוז למה שאמר הכתוב (יהושע יא יט כ) לא היתה עיר אשר השלימה אל בני ישראל בלתי החוי יושבי גבעון את הכל לקחו במלחמה כי מאת ה' היתה לחזק לבם לקראת המלחמה את ישראל למען החרימם וייחס החרב והקשת אליו כי זכותו היא העושה עמם מלחמה והיא הנלחם להם לא הם עצמם וכענין שאמר הכתוב (תהלים מד ד) כי לא בחרבם ירשו ארץ וזרועם לא הושיעה למו כי ימינך וזרועך ואור פניך כי רציתם וזהו בזכות האבות כי על דרך האמת ימינך לאברהם וזרועך ליצחק ואור פניך ליעקב וקרוב אלי עוד שעשה יעקב כדרך שיעשו הנביאים נטה ידו בחרב כנגד ארץ האמורי וזרק שם חצים להיותה נכבשת לבניו כענין שעשה אלישע וישם ידיו על ידי המלך ויאמר אלישע ירה ויור (מלכים ב יג טז) ואף על פי שלא סיפר הכתוב כן ירמזנו בפסוק הזה ויתכן שזה טעם אמרו לקחתי כי מאז לוקחה הארץ לבניו
@1475 **באחרית הימים** . הם ימות המשיח כי יעקב ירמוז אליו בדבריו כמו שאמר עד כי יבא שילה ולו יקהת עמים ורבותינו אמרו (פסחים נו) שבקש לגלות את הקץ ונסתלקה ממנו שכינה כי לדברי הכל אחרית הימים ימות המשיח הם
@1477 **ראובן בכורי אתה** . שיעור הפסוק הזה ראובן אתה בכורי וכחי וראשית אוני יתר שאתי ויתר עוזי וענינו אתה בכור כחי וראשית אוני בהיותי ביתרון שאת ומעלה כלשון הלא שאתו תבעת אתכם (איוב יג יא) משאתו יגורו אלים (שם מא יז) רוממות וגדולה ובהיותי יתרון עז למלחמה כמו ויתן עז למלכו (שמואל א ב י) ועזוז מלחמה (ישעיהו מב כה)
@1478 **פחז כמים אל תותר** . פחז שם דבר מן אנשים רקים ופוחזים (שופטים ט ד) ריקים ונמהרים קלי הדעת ורבותינו משתמשים בו תדיר (נדרים ט) נסתכלתי בבבואה שלי ופחז יצרי עלי כלומר קפץ יצרי עלי ואמרו עוד (סנהדרין נז) אפיחזיהו הוא דקא מגלי כלומר קלות דעתם עמא פחיזא דאקדמיה פומיה לאודניה עדין בפחזותיכו קימיתו (שבת פח) נמהרים קלי דעת ויתכן שהוא הפוך מן חפזון יאמר שטף הבא כמים אל תותר בו כי עלית משכבי אביך בפחזותיך וקלות דעתך אז חללת אותם כאשר יצועי עלה הפחז שלך שהוא כמים העולים ושוטפים וזה כלשון הכתוב במים הנה ה' מעלה עליהם את מי הנהר העצומים והרבים ועלה על כל אפיקיו והלך על כל גדותיו וחלף ביהודה ושטף ועבר (ישעיה ח ז ח) ורבותינו אמרו (עיין שבת נה) אז חללת יצועי עלה שכינה שדרכה לעלות על יצועי והכתוב אומר (דהי"א ה א) ובחללו יצועי אביו שהיצוע הוא המחולל ואולי יכנה אותו שם ואם בדרך כנוי יתכן שיהיה העולה יעקב עצמו כלשון אם אעלה על ערש יצועי (תהלים קלב ג) ויאמר אז חללת אותי רק דבר בנסתר דרך כבוד וכן ובחללו יצועי אביו כנוי בחללו העולה על יצועי אביו ומן הכתוב הזה כפי פשוטו נראה כמו שפירשתי בסדר וישלח (לעיל לה כב) כי ראובן נתכוון לפסול את בלהה מאביו כדי שלא תלד לו עוד בנים וימעיטו בכורתו על כן אמר לו שהוא פחיזות וקלות דעת שיחשוב להרויח ולא יבא לו ממנו יתרון רק הפסד
@1479 (בראשית מט ה): "שמעון ולוי אחים" - יאמר בעלי אחוה, כי יחם לבם על אחותם. ילמד עליהם זכות, כי בקנאתם על האחוה עשו מה שעשו, לומר שאין ראוים לעונש גדול, ולא החטא ראוי לימחל, כי הוא "חמס".
@1479 והנכון בעיני, שאמר כי "שמעון ולוי אחים" גמורים, דומים ומתאחים זה לזה בעצתם ומעשיהם.
@1479 וכבר פירשתי (בראשית לד יג), כי יעקב קצף על שמעון ולוי בהרגם אנשי העיר בעבור שעשו חמס, כי הם לא חטאו להם כלל ובאו בברית ונמולו, ואולי ישובו אל ה' ויהיו כולם בכלל אנשי בית אברהם, ומן הנפש אשר עשו בחרן. ועוד חרה לו, שלא יאמרו כי בעצתו נעשה הדבר, ויהיה חילול השם שיעשה הנביא חמס ושוד. וזה טעם (בראשית מט ו): "בסודם אל תבא נפשי" - התנצלות שלא היה בסודם בענותם במרמה, ובקהלם לא נתיחד כשבאו על העיר והרגום. ולכן יקלל (בראשית מט ז): "אפם ועברתם". וכן תרגם אונקלוס: "ברזיהון לא הות נפשי באיתכנשיהון למהך וכו'".
@1479 ופירוש "כלי חמס מכרותיהם" - על דעת אונקלוס וכל המפרשים (ראב"ע, רש"י, רד"ק) כלי חמס מגורותיהם, וכן (יחזקאל טז ג): "מכורותיך ומולדתיך", וכן (יחזקאל כט יד): "על ארץ מכורתם", אמרו כי פירושו שעשו חמס בארץ מגורותיהם. ואם כן, יהיה שיעור הכתוב: כלי חמס להם במגורותיהם. ויקרא אותה "ארץ מגורותיהם", שגרו בה אחרי כן.
@1479 אבל לפי דעתי יאמר "כלי חמס" הם מגורותיהם, חייהם, כלשון (בראשית מז ט): "ימי מגורי"; יאמר, כי כלי החמס עצמם הם מגוריהם, כי בם יחיו ויזונו. ודומה לזה (איוב כד ה): "ערבה לו לחם לנערים".
@1479 ובעבור זה (בראשית מט ז): "יחלקם ביעקב", שלא יוסדו; "ויפיצם בישראל", שלא יקהלו, ויהי להם כן, כי נחלת שמעון בתוך בני יהודה, כדכתיב (יהושע יט א): "ויהי נחלתם בתוך נחלת בני יהודה", והיו עריהם מחולקות זו מזו בכל שבט יהודה, ונחלת לוי, ערי מקלט, מנופצות בכל ישראל.
@1480 כבר פירשתי (בראשית לד יג), כי יעקב קצף על שמעון ולוי בהרגם אנשי העיר בעבור שעשו חמס, כי הם לא חטאו להם כלל ובאו בברית ונמולו, ואולי ישובו אל ה' ויהיו כולם בכלל אנשי בית אברהם, ומן הנפש אשר עשו בחרן. ועוד חרה לו, שלא יאמרו כי בעצתו נעשה הדבר, ויהיה חילול השם שיעשה הנביא חמס ושוד. וזה טעם (בראשית מט ו): "בסודם אל תבא נפשי" - התנצלות שלא היה בסודם בענותם במרמה, ובקהלם לא נתיחד כשבאו על העיר והרגום. ולכן יקלל (בראשית מט ז): "אפם ועברתם". וכן תרגם אונקלוס: "ברזיהון לא הות נפשי באיתכנשיהון למהך וכו'".
@1480 וטעם (בראשית מט ו): "כי באפם הרגו איש וברצונם עקרו שור" - שעשו החמס באפם שכעסו על שכם, וברצונם שהם חפצים בו, לא פשע המומתים ולא חטאתם.
@1480 ואמר אונקלוס, כי טעם שוֹר כמו שוּר בשורק, מן (בראשית מט כב): "בנות צעדה עלי שור", ותרגם בו עוד "סנאה", מן (תהלים צב יב): "ותבט עיני בשורי". והטעם, שעקרו עיר מוקפת חומה, את טפם ואת נשיהם, אחרי הרגם אנשיה. ויהיה "עקרו" מן (צפניה ב ד): "ועקרון תעקר".
@1480 ואחרים פירשו (רד"ק בשם ריב"א), כי שור גדול בבהמות, רמז לחמור ושכם בנו נשיא הארץ, כמו (דברים לג יז): "בכור שורו הדר לו", (עמוס ד א): "פרות הבשן אשר בהר שומרון". וכן יכנו הכתובים השרים הגדולים באילים ועתודים.
@1480 והנכון בעיני, שהכתוב כמשמעו, אמר כי "באפם הרגו" כל "איש" באפם, "וברצונם", אחרי ששככה חמתם בהריגת האנשים, "עקרו" כל "שור", רמז למקניהם וקנינם כל אשר בבית וכל אשר בשדה. והזכיר זה, לומר, כי בסודם לא באה נפשו בכל אלה, אפילו לעקור להם מקנה וקנין ולבוז שללם כלל. ו"עקרו" מן (יהושע יא ו): "ואת סוסיהם תעקר". אך הכל לשון אחד וענין אחד.
@1480 {ו} **וטעם כי באפם הרגו איש וברצונם עקרו שור** . שעשו החמס באפם שכעסו על שכם וברצונם שהם חפצים בו לא פשע המומתים ולא חטאתם ואמר אונקלוס כי טעם שור כמו שור בשורק מן בנות צעדה עלי שור (להלן פסוק כב) ותרגם בו עוד סנאה מן ותבט עיני בשורי (תהלים צב יב) והטעם שעקרו עיר מוקפת חומה את טפם ואת נשיהם אחרי הרגם אנשיה ויהיה "עקרו" מן ועקרון תעקר (צפניה ב ד) ואחרים פירשו (רד"ק בשם ריב"א) כי שור גדול בבהמות רמז לחמור ושכם בנו נשיא הארץ כמו בכור שורו הדר לו (דברים לג יז) פרות הבשן אשר בהר שומרון (עמוס ד א) וכן יכנו הכתובים השרים הגדולים באילים ועתודים והנכון בעיני שהכתוב כמשמעו אמר כי באפם הרגו כל איש באפם וברצונם אחרי ששככה חמתם בהריגת האנשים עקרו כל שור רמז למקניהם וקנינם כל אשר בבית וכל אשר בשדה והזכיר זה לומר כי בסודם לא באה נפשו בכל אלה אפילו לעקור להם מקנה וקנין ולבוז שללם כלל ו "עקרו" מן ואת סוסיהם תעקר (יהושע יא ו) אך הכל לשון אחד וענין אחד
@1481 ...ובעבור זה (בראשית מט ז): "יחלקם ביעקב", שלא יוסדו; "ויפיצם בישראל", שלא יקהלו, ויהי להם כן, כי נחלת שמעון בתוך בני יהודה, כדכתיב (יהושע יט א): "ויהי נחלתם בתוך נחלת בני יהודה", והיו עריהם מחולקות זו מזו בכל שבט יהודה, ונחלת לוי, ערי מקלט, מנופצות בכל ישראל.
@1484 אין ענינו שלא יסור לעולם, כי כתוב (דברים כח לו): "יולך ה' אותך ואת מלכך אשר תקים עליך אל גוי אשר לא ידעת אתה ואבותיך", והנה הם ומלכם בגולה, אין להם עוד מלך ושרים, וימים רבים אין מלך בישראל, והנביא לא יבטיח את ישראל שלא ילכו בשבי בשום ענין בעבור שימלוך עליהם יהודה.
@1484 אבל ענינו, שלא יסור שבט מיהודה אל אחד מאחיו, כי מלכות ישראל המושל עליהם ממנו יהיה, ולא ימשול אחד מאחיו עליו. וכן לא יסור "מחוקק מבין רגליו", שכל מחוקק בישראל אשר בידו טבעת המלך, ממנו יהיה, כי הוא ימשול ויצוה בכל ישראל, ולו חותם המלכות, "עד כי יבא שילה ולו יקהת כל העמים" לעשות בכולם כרצונו, וזהו המשיח, כי:
@1484 "השבט" ירמוז לדוד שהוא המלך הראשון אשר לו שבט מלכות,
@1484 ו"שילה" הוא בנו אשר לו יקהת העמים.
@1484 ולא יתכן מאמר רבי אברהם, שיהיה שילה דוד, כי לא היה ליהודה שבט קודם דוד, כי אף על פי ששבטו נכבד ונוסע בתחלה, אין שבט רק למלך ומושל, כדכתיב (תהלים מה ז): "שבט מישור שבט מלכותך", (ישעיהו יד ה): "שבט מושלים", (יחזקאל יט יד): "שבט למשול".
@1484 והכתוב הזה רמז, כי יעקב המליך שבט יהודה על אחיו, והוריש ליהודה הממשלה על ישראל, והוא מה שאמר דוד (דברי הימים א כח ד): "ויבחר ה' אלהי ישראל בי מכל בית אבי להיות למלך על ישראל לעולם כי ביהודה בחר לנגיד ובבית יהודה בית אבי ובבני אבי בי רצה להמליך על כל ישראל".
@1484 ואמר "לא יסור" לרמוז, כי ימלוך שבט אחר על ישראל, אבל מעת שיחל להיות ליהודה שבט מלכות, לא יסור ממנו אל שבט אחר, וזהו שנאמר (דברי הימים ב יג ה): "כי ה' אלהי ישראל נתן ממלכה לדוד על ישראל לעולם לו ולבניו".
@1484 וענין שאול היה, כי בעבור שדבר שאלת המלכות בעת ההיא נתעב אצל הקדוש ברוך הוא, לא רצה להמליך עליהם מן השבט אשר לו המלכות שלא יסור ממנו לעולמים, ונתן להם מלכות שעה, ולזה רמז הכתוב שאמר (הושע יג יא): "אתן לך מלך באפי ואקח בעברתי", שנתנו לו שלא ברצונו, ולכן לקחו בעברתו, שנהרג הוא ובניו ונפסקה ממנו המלכות. והיה כל זה מפני שהיה שמואל שופט ונביא ולוחם מלחמותיהם על פי ה' ומושיע אותם, ולא היה להם לשאול מלך בימיו, כמו שאמר להם (שמואל א יב יב): "וה' אלהיכם מלככם". והקב"ה אמר לו (שמואל א ח ז): "לא אותך מאסו כי אותי מאסו ממלוך עליהם", ולפיכך לא נתן להם מלכות של קיימא.
@1484 ומה שאמר הכתוב (שמואל א יג יג): "נסכלת לא שמרת את מצות ה' אלהיך אשר צוך כי עתה הכין ה' את ממלכתך אל ישראל עד עולם", שאם לא חטא, היה לזרעו מלכות בישראל, לא על כלם, וזה טעם "אל ישראל"; אולי היה מולך על שבטי אמו, על בנימן ואפרים ומנשה, כי יהודה ואפרים כשני עממים נחשבים בישראל; או היה מלך תחת יד מלך יהודה.
@1484 ולפי דעתי, היו המלכים המולכים על ישראל משאר השבטים אחרי דוד עוברים על דעת אביהם ומעבירים נחלה, והם היו סומכים על דבר אחיה השילוני הנביא שמשח לירבעם ואמר (מלכים א יא לט): "ואענה את זרע דוד למען זאת אך לא כל הימים", וכאשר האריכו ישראל להמליך עליהם משאר השבטים מלך אחר מלך, ולא היו חוזרים אל מלכות יהודה, עברו על צוואת הזקן ונענשו בהם, וכמו שאמר הושע (הושע ח ד): "הם המליכו ולא ממני".
@1484 וזה היה עונש החשמונאים, שמלכו בבית שני, כי היו חסידי עליון, ואלמלא הם נשתכחו התורה והמצות מישראל, ואף על פי כן נענשו עונש גדול, כי ארבעת בני חשמונאי הזקן החסידים המולכים זה אחר זה, עם כל גבורתם והצלחתם, נפלו ביד אויביהם בחרב, והגיע העונש בסוף למה שאמרו רז"ל (בבא בתרא ג א): "כל מאן דאמר מבית חשמונאי קאתינא עבדא הוא", שנכרתו כלם בעון הזה. ואף על פי שהיה בזרע שמעון עונש מן הצדוקים, אבל כל זרע מתתיה חשמונאי הצדיק לא עברו אלא בעבור זה שמלכו ולא היו מזרע יהודה ומבית דוד, והסירו השבט והמחוקק לגמרי, והיה עונשם מדה כנגד מדה, שהמשיל הקדוש ברוך הוא עליהם את עבדיהם והם הכריתום.
@1484 ואפשר גם כן שהיה עליהם חטא במלכותם מפני שהיו כהנים, ונצטוו (במדבר יח ז): "תשמרו את כהונתכם לכל דבר המזבח ולמבית לפרכת ועבדתם עבודת מתנה אתן את כהונתכם", ולא היה להם למלוך, רק לעבוד את עבודת ה'. וראיתי בירושלמי במסכת הוריות (ירושלמי הוריות פרק ג הלכה ב): "אין מושחין מלכים כהנים. אמר רבי יהודה ענתוריא על שם לא יסור שבט מיהודה. אמר רבי חייא בר' אבא למען יאריך ימים על ממלכתו הוא ובניו בקרב ישראל, מה כתיב בתריה לא יהיה לכהנים הלוים". הנה, שנו בכאן שאין מושחין מלכים מן הכהנים בני אהרן. ופירש תחלה שהוא לכבוד יהודה, שאין השררה סרה מן השבט ההוא. ולפיכך, אף על פי שישראל מקימים עליהם מלך משאר השבטים כפי צורך השעה, אין מושחים אותן שלא יהיה עליהם הוד מלכות אלא כמו שופטים ושוטרים יהיו. והזכירו הכהנים, שאף על פי שהן בעצמן ראויים למשיחה, אין מושחין אותן לשם מלכות, וכל שכן שאר השבטים, וכמו שאמרו בגמרא (הוריות יא) שאין מושחין אלא מלכי בית דוד. ורבי חייא בר אבא פירש, שהוא מנוע מן התורה שלא יהיה לכהנים הלוים כל שבט לוי חלק ונחלה במלכות, והוא דבר ראוי והגון.
@1484 "אסיפת העמים, שנאמר (ישעיהו יא י): "אליו גוים ידרשו". ודומה לו (משלי ל יז): "עין תלעג לאב ותבוז ליקהת אם", לקבוץ קמטים שבפניה מפני זקנתה. ובתלמוד (יבמות קי א): "דמקהו קהיאתא בשוקא דנהרדעא". ויכול לומר קהיית עמים", לשון רש"י.
@1484 ואינו נראה לפרש ב"יקהת אם" אסיפת אם.
@1484 ולשון "מקהו קהיאתא" אינו אלא לשון פירכות וקושיות שהיו מקשים ומפרכים בה קושיות הרבה, כי המתקשה בדבר יקרא "קוהה" בלשון חכמים, כמו שאמרו במדרש חזית (שיר השירים רבה ג ח) "כולם אחוזי חרב" - שהיו כולם שונים הלכה כחרב, שאם בא מעשה אל ידיהם לא תהא הלכה קוהה להם, וכן עוד שם רבים. וממנו אמרו בגמרא (נזיר סה ב): "ר' יהושע קיהה וטהר", שהקשה בו דברים רבים ושבר כל דברים המטמאים עד שטיהר בהכרח. וכן מצינו בנוסחאות ישנות בגמרא (בבא מציעא נב א): "מאן דקהי אזוזי מיקרי נפש רעה", שמדקדק בו ומתקשה לקבל אותו מחבירו.
@1484 ובעלי הדקדוק (הרד"ק ור' יונה בן ג'נאח) אומרים ב"יקהת" ששרשו יקה, ופירשו בו לשון משמעות וקבול המצוה, "יקהת עמים" - שישמעו אליו ויעשו כל אשר יצוה עליהם; "תבוז ליקהת אם" - לקבל מצותה.
@1484 והנכון בעיני, שהוא מלשון (ירמיהו לא כט): "האוכל הבוסר תקהינה שניו", ושרשו קהה, והיו"ד בו כיו"ד יצהר, וענין כלם החולשה והשבירה: יאמר שלא יסור שבט נוגש מיהודה, עד שיבא בנו אשר לו חולשת העמים ושבירתם, שיחליש את כלם לפי חרב. וכן (קהלת י י): "אם קהה הברזל", שנחלש ואינו יכול לכרות, כסכין שעמדה בלשון חכמים (ביצה כח), או שנשבר קצת ונעשו בו פגימות. וכן מצאתי עוד שם במדרש חזית (שיר השירים רבה א יב): "הופיע להם הקב"ה ריח טוב מבשמי גן עדן, והיתה נפשם קוהה לאכול, אמרו לו "רבינו משה תן לנו מה נאכל!" אמר להם "כך אמר לי הקב"ה כל בן נכר לא יאכל בו", עמדו והפרישו הנכרים מביניהם והיתה נפשם קוהה לאכול וכו'". והענין, שהיתה נפשם נחלשת ומשתברת בגופם מרוב תאותם לאכול מן הפסח, שנדבק בו הריח הטוב. וכן "לא תהא הלכה קוהה להם" - נחלשת ורופפת בידם. ו"מקהו קהיאתא" - מקשים קושיות מחלישות הנפש מרוב הצער והעיון, או הוא לשון שמשברין ומפרכין, כלשון (קידושין יג ב): "פריך רב אחא". וכך אמרו (מכילתא בא יח) "אף אתה הקהה את שניו" - שבר אותם או תחלישם בדבריך, כי הבוסר מחליש ואינו משבר, אלא שהחלישות והשבירה ענין שוה, והקהיה תכלול את שניהם.
@1486 **חכלילי עינים** . אמרו המפרשים (רש"י ראב"ע והרד"ק) שהוא ענין אדמימות שיתאדמו עיניו מרוב שתית יין וכמוהו למי חכלילות עינים (משלי כג כט) והנראה בעיני שהוא הפוך מן כחלת עיניך (יחזקאל כג מ) ונכפלה בו הלמ"ד כמנהג רבים והוא כענין מכחול העינים הידוע ומורגל בדברי רבותינו (כלים פי"ג מ"ב) וכן שמו בערבי "אל כחול" יאמר שהוא כחול העינים מן היין כי כאשר אחרים כוחלים אותם בפוך שהוא ה"אל כחול" כן יכחול אותם הוא ביין וכמו שהאחרים מלבנים שיניהם בתמרוקים כן ילבן אותם בחלב והמשל לרבוי היין והחלב בארצו כאשר הזכיר אונקלוס וכן למי חכלילות עינים (משלי כג כט) כמו כחלילות יאמר שעיניו כחולות ביין ולא יוכל להסתיר שכרותו או יאמר למי חכלילות עינים שיצטרך לכחול עיניו תמיד למאחרים על היין כי היין יחשיך את עיניהם ויורידו דמעה ותמקנה בחוריהן ויצטרך שיהיו עיניו במכחול תדיר יספר הכתוב בגנות היין ברעות הבאות לו מבחוץ במדנים ובפצעים ושישמע בביתו אוי ואבוי ויזכיר הנזק ההוא ההוה לו ממנו בגופו חשכת עיניו ותחלואיהם הרבים וזה פירוש וענין נכון
@1490 **דן ידין עמו** . כמו כי ידין ה' עמו (דברים לב לו) ארי ידין ה' דינא דעמיה כלשון שפטני ה' וריבה ריבי מגוי לא חסיד (תהלים מג א) ריב אלמנה (ישעיהו א יז) יאמר כי דן ינקום נקמת עמו כל שבטי ישראל כאחד והטעם כי פלשתים הרעו לכל ישראל כמה פעמים כי בימי שמגר בן ענת החלו (שופטים ג לא) ובימי יפתח כתוב (שם י ז) וימכרם ביד פלשתים וגם אחרי עבדון בן הילל (שם יב יג) ויתנם ה' ביד פלשתים ארבעים שנה (שם יג א) ולא היה בשופטים מי שהכניעם או שנצחם כלל ואף על פי שכתוב בשמגר (שם ג לא) ויך את פלשתים שש מאות איש במלמד הבקר איננה נקמה כי איננה מכה רבה על כן כתוב בשמשון (שם יג ה) והוא יחל להושיע את ישראל מיד פלשתים ולקח נקמת ישראל מהם כי הרג מהם עם רב וכל סרני פלשתים המית והזכיר ידין כי היה הנוקם הזה שופט לא מלך ואפשר שזה דעת אונקלוס שאמר ביומוהי יתפרק עמיה ויתכן שיהיה כאחד שבטי ישראל כמיוחד שבשבטים הוא יהודה שנאמר בו (לעיל פסוק ח) ידך בעורף אויביך כי גם זה יגבר על אויביו וינצחם
@1491 **שפיפון** . שם לנחש שישוף עקב ונכפלה בו העי"ן ואמרו בירושלמי במסכת תרומות (פ"ח מ"ג) מין קטן הוא ושפיפון שמו ודומה לשערה ונתנה רשות לארץ ליבקע מפניו ודמה שמשון לנחש בעבור שלא היה שמשון בא על אויביו במלחמה כאשר השופטים או המלכים רק הוא לבדו יוצא עליהם כמו צפעוני היוצא ממאורתו על הולכי דרך או המין הקטן שבנחשים שאינו ניכר כלל להולכי ארח וטעם הנושך עקבי סוס רמז לשני העמודים אשר הבית נכון עליהם (שופטים טז כט) ושלשת אלפים אשר על הגג (שם פסוק כז) הם הרוכב הנופל אחור כאשר ישוך הנחש בעקבי הסוס יגביה הסוס ראשו ורגליו הראשונים ויפול רוכבו אחור
@1492 **לישועתך קויתי ה'** . לא היה בכל שופטי ישראל מי שנפל ביד אויביו זולתי שמשון שהוא הנחש הזה כדכתיב (שופטים ב יח) והיה ה' עם השופט והושיעם מיד אויביהם כל ימי השופט והוא היה האחרון לשופטים כי שמואל נביא היה ולא נלחם להם ובימיו מלכו המלכים וכאשר ראה הנביא תשועת שמשון כי נפסקה אמר לישועתך קויתי ה' לא לישועת נחש ושפיפון כי בך אושע לא בשופט כי תשועתך תשועת עולמים
@1493 **גד גדוד יגודנו** . פירש רש"י על דרך אונקלוס יתנבא כי גדוד יגוד ממנו ואותו הגדוד יגוד עקב על עקבו שיחזור לדרך אשר בא לו לשלום אל ארצו והנכון שיהיה כמו לעלות לעם יגודנו (חבקוק ג טז) יאמר כי גדוד יגודנו תמיד שיהיו לו מלחמות רבות ופשט גדוד עליו בארצו והוא יגוד אותו על עקיבו שיתגבר עליו וירדוף אותו והם ישובו על עקב בשתם שבח אותם בגבורה ונצוח כל הבאים עליהם למלחמה וזה כענין ברכת משה רבינו בהם (דברים לג כ) ברוך מרחיב גד כלביא שכן בעבור שירש ארץ רחבת ידים וגדולה מאד והיא בעבר הירדן היו באים עליהם תמיד גדודי עמון ומואב שכניו הרעים התובעים בנחלה ופושטים עליהם והוא כלביא שכן על טרפו מקולם לא יירא ומהמונם לא ייחת וזה פירוש נאה למדתיו מן הירושלמי שאמרו במסכת סוטה (פ"ח ה"י) גד גדוד יגודנו גייסא אתי מגיסתא והוא מגייס לה לומר כי הגייס יבא לאסוף חיל ולגייס עליו והוא יגוד עליהם ויביא גדודיו בארצם ואולי ירמוז הנביא על מלחמת יפתח הגלעדי עם בני עמון כי בני גד ירשו כל ערי הגלעד וחצי ארץ בני עמון והיו בני עמון תמיד נלחמים באנשי גלעד והוא כמעט עבר עליהם והכה אותן ואת עריהן מכה גדולה מאד (שופטים יא לג) והיה הענין ההוא נס גדול הזכירו הנביא כאשר הזכיר דבר שמשון
@1495 **נפתלי אילה שלוחה** . מנהג במושלי ארץ לשלוח זה לזה האילים וכך הענין כי האילות שנולדו בארץ מלך הצפון יגדלו אותן בהיכלי מלך הנגב ויקשרו כתב הבשורה בקרניה והיא תרוץ מהר ותשוב למעונה ויתבשרו בהן וזה טעם אמרי שפר כלומר אילה שלוחה מבשר בשורות טובות והענין הזה ידוע והוא מוזכר בירושלמי במסכת שביעית (פ"ט ה"ב) אמרו אין אזלין לון חזרין ואי בעית למבדקיה אייתו טביין וישלחון לארע רחיקא בסוף אינון חזרין עבד כן ואייתי טביין וחפי קרניהון בכסף ושלחון לאפריקי ובסוף תלת עשרה שנין חזרון לאתריהון שהתירום לאחר י"ג שנה ומיד חזרו והמשל כי נפתלי שבע רצון ומלא כל טוב וממנו תבא בשורה לכל ישראל כי עשתה ארצו פירות לשבעה כמו שהזכירו רבותינו בפירות גנוסר (תנחומא ויחי יג)
@1496 **בן פורת יוסף** . בן חן והוא לשון ארמי (ב"מ קיט) אפריון נמטיה לרבי שמעון בן פורת עלי עין חנו נטוי על העין הרואה אותו לשון רש"י ורחוק הוא מאד לסמכו אל הלשון ההוא שלשונות כאלה בתלמוד יוני או פרסי ושאר לשונות אין להם חבר בלשון הקדש ועוד כי לפי הנמצא ממנו איננו רק לשון ברכה ושבח והנו"ן בו שרש וכן בבראשית רבה (ס יג) ויברכו את רבקה דוויין ושפופין ולא היו מפרנין אלא בפה ודומה לי שהוא ממה שאמרו (כתובות נד) פורנא ליתמי שפירושו השבח שהשביחו הוא ליתומים וקראו עוד הכתובה פורנא אשה גובה פורנא מהם (שם סז) הכתובה שהיא שבח בית אביה וכמו שאמרו (ב"ר פ ז) מהר פראנון אבל בן פורת או כדעת אונקלוס מלשון פוריה ועניפה או כדברי בעלי הדקדוק (עיין ספר השרשים שורש בנה) שעשו פורת מלשון ותארכנה פארותיו (יחזקאל לא ה) והם אמרו כי בן כמו נטע והביאו לו דומה (תהלים פ טז) וכנה אשר נטעה ימינך ועל בן אמצתה לך והענין כאלו אמר נטע שבו פארות רבות יוסף ועל דעתי בן כמשמעו יאמר כי יוסף הוא בן שהוא כמו פארות אילן שתול על המעין אשר לא יכזבו מימיו ועשתה בנות צעדה אותן על החומות הגבוהות בשמים וכנה הבדים אשר תצאנה מן פארה בבנות כי הן בנות לפארות הגדולות והוא דרך צחות לבן פורת ולא נסמך בן אל פורת אבל הוא כמו אשור ארז בלבנון (יחזקאל לא ג) נפתלי אילה שלוחה (לעיל פסוק כא) בנימין זאב (להלן פסוק כז) ולפיכך נקוד בצרי כי אילו היה פירושו נטע שיש לו פארות משפטו בסגול ואמר "בן" דרך חבוב כמו מטרף בני עלית ועל הכלל ראוי שנפרש בברכת יוסף שיהיה בה זכר לשני השבטים היוצאים ממנו והוא לשון פורת ובנות אבל מפני שהזכיר לוי ושבטי ישראל אינם אלא שנים עשר לא יעשה ממנו כן בברכתו שנים שבטים חלוקים אבל ירמוז להם וכן במשה רבינו בברכתו דמה אותו לשור ולראם (דברים לג יז) והזכיר בו הקרנים כי כל אחד מהם גוף אחד שממנו יתחלקו קרנים ובעבור ששם לא הזכיר שמעון אמר בפירוש והם רבבות אפרים והם אלפי מנשה (שם)
@1498 **מידי אביר יעקב** . זאת היתה לו מאת הקב"ה שהוא אביר יעקב ומשם זכה להיות רועה אבן ישראל עיקרן של ישראל לשון האבן הראשה לשון רש"י מאל אביך היתה זאת לך והוא יעזרך ועם הקב"ה היה לבך כשלא שמעת לדברי אדונתך והוא יברכך גם זה לשונו ורבי אברהם אמר כי מ"ם מאל אביך נמשך לואת שדי והוא יברכך ועל דרך האמת הברכה הזאת דומה לברכה אשר ברך למעלה את הנערים כי אביר יעקב הוא אלהי אמת ולא בא בכתוב אביר אברהם או יצחק וזולתם רק אביר יעקב או אביר ישראל (ישעיהו א כד) הוא יעקב והנה מידי אביר יעקב הגדולה והגבורה משם מידי אביר יעקב רועה אבן ישראל היא האבן הראשה שהיתה לראש פינה (תהלים קיח כב) מאת ה' ונקרא אבן ישראל כמו שאמרו חכמים כנסת ישראל היא האבן הראשה וטעם אבן שהוא בנין משלים הכל וענין רועה כי העוז בגבורה מתעלה בימינו של הקב"ה כדכתיב (חבקוק ג ד) קרנים מידו לו ושם חביון עזו כלומר ושם בימינו חביון העוז וחביון הוא הכח המתעלה הנחבא במקום אצילותו וזהו שנאמר (תהלים פ טז) וכנה אשר נטעה ימינך מאל אביך האלהים הרועה אותי מעודי ואת שדי ויברכך ודעת הברכה כי מידי אביר יעקב מחסד שרועה אבן ישראל ומאלהי אביו יפיק רצון ויבא עזרו ועם שדי תהיה ברכתו והנה הוא מבורך בשמים ובארץ וזה טעם ברכות אביך גברו על ברכת הורי כי הבנין שלם בו כך העליתי הענין הזה ממדרשו של רבי נחוניא בן הקנה (עיין ספר הבהיר קצג קמח) והמשכיל יבין
@1503 **קברו אותי אל אבותי** . עם אבותי לשון רש"י ולא פירש אל המערה ואיננו עם ויתכן שיהיה לשון המקרא הזה קצר קברו אותי ושאוני אל אבותי אל המערה כי כן אמר (לעיל מז ל) ונשאתני ממצרים וישאו אותו בניו (להלן נ יג) ויתכן שישמש "אל" בפנים רבים קברו אותי עם אבותי כמו ואשה אל אחותה לא תקח (ויקרא יח יח) עם אחותה אל המערה במערה כמו ואל הארון תתן את העדות (שמות כה כא) הנה הוא נחבא אל הכלים (שמואל א י כב) וכן (לעיל כג יט) ואחרי כן קבר אברהם וגו' אל מערת ואמר רבי אברהם כי טעם קברו אותי אל אבותי שילכו עם יוסף ולא היה יעקב צריך לכך אבל צוה לכולם עתה שיקברו אותו אל המערה כאשר השביע ליוסף כי פחד אולי לא יתן פרעה רשות ליוסף לצאת מן הארץ שלא יתעכב בארצו והלא תראה שהוצרך יוסף לחלות פני בית פרעה שיבקשו עליו מפרעה שילך והוא ענה כאשר השביעך כי בעבור השבועה יתרצה בזה
@1505 **וטעם שמה קברו את יצחק** . שלא אמר קברתי בעבור היות עשו עמו בקבורת אביהם ולא ירצה עתה להזכירו ועוד שלא יצטרך עתה להאריך לאמר שמה קברנו את יצחק ושמה קברו את רבקה אשתו כי לא היה הוא בקבורת אמו והזכיר להם בצואתו המערה והנקברים בה לגדל המקום כדי שיזדרזו לקברו שם ואמר אשר קנה אברהם את השדה לאחוזת קבר להודיע כי אברהם צוה שיהיה המקום ההוא בית הקברות להם לאחוזת עולם אבל למטה (נ יג) כשאמר ויקברו אותו במערת שדה המכפלה אשר קנה אברהם לאחזת קבר נתכוון הכתוב לרמוז כי ביעקב נשלמה כונת הצדיק כי לשלשתם קנאה ולא יקברו בה עוד איש ועל כן לא צוה יוסף שיקברו אותו במערה עם אבותיו וראיתי במכילתא לרבי שמעון בן יוחאי (בשלח יט) שאמר להם יוסף וכשאתם מעלין אותי קברו אותי בכל מקום שתרצו מקובל אני שאיני נכנס לקבורת אבותי שאין נכנס לקבר אבות אלא שלשה אבות ושלש אמהות שנאמר שמה קברו את אברהם וגו' ואומר (להלן נ ה) בקברי אשר כריתי לי בי הוא פוסק ויתכן שרמז להם באמרו ושמה קברתי את לאה שכבר החזיק הוא במערה ואמר זה כנגד עשו שלא יערער הוא ובניו בקבורתו לטעון שהמערה שלו כי הוא הבכור והוא הראוי להקבר עם אבותיו ואף על פי שהלך אל ארץ אחרת יהיו נושאים אותו משם כאשר ישאו בניו את יעקב כי ירצה להקבר עם אבותיו הקדושים וליחד אתם בקבורה ואם יקבר שם עשו לא יקבר שם יעקב כי אין לשתי משפחות בית קבורה אחד וזהו גם כן מה שאמר בקברי אשר כריתי לי שכבר כרה לו הקבר להחזיק בו וזה טעם ויעל עמו גם רכב גם פרשים (להלן נ ט) כי ידע זדון עשו ובניו וכן היה מעשה כי מצינו בספר דברי הימים ליוסף בן גוריון (הוא ספר יוסיפון) וזולתו מספרי הקדמוניות כי בא צפו בן אליפז בן עשו ועשה עמהם קטטה על זה עד שערכו מלחמה ותגבר יד יוסף ותפשו עם מבחר גדודיו והביאום למצרים ועמד שם בתפיסה כל ימי יוסף וברח משם במותו והלך לארץ כאנפנייא ומלך על כתים ברומא ובסוף הומלך על כל ארץ איטלייא והוא אשר מלך ראשון על רומה והוא אשר בנה ההיכל הראשון והגדול מאשר נבנו ברומה וגם רבותינו (סוטה יג) הזכירו מזה הענין מקטטת עשו במערה והכתוב שאמר בכאן (להלן נ יד) וישב יוסף מצרימה הוא ואחיו וכל העולים אתו לקבור את אביו אחרי קברו את אביו בא לרמוז שלא מת אחד מכלם במלחמה ולא בדרך שעמד להם זכות הנביא וזכות יוסף שעלו עמו ולא צוה יוסף כאשר צוה אביו לשאת אותו לקברו בארץ עתה כי לא יניחוהו בית פרעה כי לכבוד הוא להם ועוד שאם ילכו עמו אחיו ובית אביו יגזלו ויגנבו אנשי הארץ את כל אשר להם ואיננו דרך כבוד שיוליכוהו שם אחרים
@1505 "ויאמר יוסף אל אחיו אנכי מת" - (שם פסוק כד) כי אחיו חיים היו כי האריכו ימים יותר ממנו כאשר אתה רואה בלוי ואמר (שם פסוק כה) וישבע יוסף את בני ישראל כי בראותו שאחיו זקנים השביע כל בניהם וכל בית אביו שיצוו גם את בני בניהם לעת הגאולה כי כלם יודעים הגלות
@1507 **ויגוע ויאסף** . ומיתה לא נאמרה בו ואמרו רבותינו (תענית ה) יעקב אבינו לא מת לשון רש"י ולדעת רבותינו הרי יעקב הזכיר מיתה בעצמו (לעיל מח כא) הנה אנכי מת והיה אלהים עמכם ואולי לא ידע הוא בנפשו או שלא רצה לתת כבוד לשמו וכן (להלן נ טו) ויראו אחי יוסף כי מת אביהם כי להם מת הוא או שלא ידעו הם בזה כלל וענין המדרש הזה כי נפשות הצדיקים צרורות בצרור החיים וזו תחופף עליו כל היום לובשת לבושה השני שלא יפשטנה ערומה כיעקב או תתלבש לעתים מזומנות ויובן הענין הזה במסכת שבת (קנב) ובמסכת כתובות (קג.)
@1507 **ונשלם ספר בראשית בספור דברי האבותלהגיד ראשונות וחדשות בטרם תצמחנה בלבבותוליוצר כל ראשית רוכב ערבות תהלות רבות והודאות לרבבותולו נתכנו עלילות וסבות מגלה עמוקותודעות נשגבות ומוציא לאור המחשבותהמוליך אותי בדרך צדקה בתוך נתיבות הגומל לחייבים טובותתם ונשלם שבח לבורא עולם חסלת פרשת ויחי** אבן עזרא **ויאסף רגליו אל המטה** . כי בתחלה ישב על המטה ורגליו תלויות כמנהג ארץ אדום היום ולא כן מטות הישמעאלים:
